package com.shmayvan.slayerledger;

import lombok.Data;

/**
 * A Slayer assignment that ended without a saved session: skipped, blocked, reset, completed while no session was
 * tracked, or ended for a reason the plugin couldn't tell ({@link AssignmentOutcome}). Stored in the ledger file's
 * {@code assignments} list ({@link LedgerStore}), next to the records but never among them, and serialized with Gson
 * like {@link LedgerRecord}: {@code null} fields are left out when writing and missing fields read as {@code null}.
 *
 * <p><b>An entry is not a played task.</b> It has no kills, time, loot or supplies, and it never counts anywhere
 * played tasks do: the history list and its totals, the Monster filter, the saved-task count, the time-left estimate
 * ({@link TaskTimeEstimate}) and today's prices only ever see {@link LedgerRecord}s. Phase 3 (per-monster averages
 * and new-task estimates) must also use the records only and ignore these entries (owner decision).</p>
 *
 * <p>Added to schema 2 as an optional list (no schema bump), following the precedent of the optional
 * {@link LedgerRecord} fields: a file without it loads with no entries, and is written back without the field until
 * an entry is added. An older build would read such a file and drop the list on its next write.</p>
 */
@Data
public class AssignmentEntry
{
	/** Random id, so the entry can be deleted from the history. */
	private String id;
	/** Task name, or {@code null} when the lookup failed. */
	private String monster;
	/** Slayer task creature key ({@link SessionTracker#creatureKey}), or {@code null} when unknown. */
	private Integer creatureId;
	/** Assigned task size, or {@code null} when unknown. */
	private Integer originalAmount;
	/** SLAYER_MASTER value, as in {@link LedgerRecord#getSlayerMaster()}; {@code null} when unknown. */
	private Integer slayerMaster;
	/** SLAYER_AREA value (Konar), or {@code null}. */
	private Integer slayerArea;
	/** The area's name, or {@code null}. */
	private String taskLocation;
	/** When the assignment was first seen to have ended (epoch ms). */
	private long endedAt;
	/** How it ended; {@code null} reads as {@link AssignmentOutcome#UNKNOWN} (for example an outcome from a newer build, which this build also writes back as {@code null}, so a downgrade loses it). */
	private AssignmentOutcome outcome;
	/**
	 * Slayer points after the end minus points before it (negative when points were spent), or {@code null} when not
	 * observed (no reading before the end).
	 */
	private Integer pointsChange;

	/** The assignment's master and area as a {@link TaskContext} (no rewards). */
	TaskContext context()
	{
		return TaskContext.of(slayerMaster, slayerArea, taskLocation, null, null);
	}
}

package com.shmayvan.slayerledger;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

/**
 * Pure rules and formatting for the assignment entries ({@link AssignmentEntry}): the bound on how many are kept, the
 * check against saved records, the order and the "Skipped / blocked" section's text. No Swing, client or file access.
 *
 * <p>Entries are never mixed with {@link LedgerRecord}s: nothing here, or anywhere else, counts them as played tasks
 * (see {@link AssignmentEntry}).</p>
 */
final class AssignmentLog
{
	/** At most this many entries are kept; adding one more drops the oldest (by end time). */
	static final int MAX_ENTRIES = 500;
	/** Separator between the parts of a row, as in {@code Abyssal demons \u00b7 Skipped \u00b7 10/26/26}. */
	static final String SEPARATOR = " \u00b7 ";

	/** Newest first by end time; ties broken by id, for a stable order. */
	static final Comparator<AssignmentEntry> NEWEST_FIRST = Comparator
		.comparingLong(AssignmentEntry::getEndedAt).reversed()
		.thenComparing(e -> e.getId() == null ? "" : e.getId());

	private AssignmentLog()
	{
	}

	/**
	 * {@code entries} with {@code entry} added (unless one with the same id is already there), keeping only the newest
	 * {@link #MAX_ENTRIES}; the order on disk is oldest first.
	 */
	static List<AssignmentEntry> add(Collection<AssignmentEntry> entries, AssignmentEntry entry)
	{
		final List<AssignmentEntry> result = sortNewestFirst(entries);
		if (entry != null && (entry.getId() == null
			|| result.stream().noneMatch(e -> entry.getId().equals(e.getId()))))
		{
			result.add(entry);
			result.sort(NEWEST_FIRST);
		}
		while (result.size() > MAX_ENTRIES)
		{
			result.remove(result.size() - 1);
		}
		final List<AssignmentEntry> oldestFirst = new ArrayList<>(result.size());
		for (int i = result.size() - 1; i >= 0; i--)
		{
			oldestFirst.add(result.get(i));
		}
		return oldestFirst;
	}

	/** Copy without nulls, newest first. */
	static List<AssignmentEntry> sortNewestFirst(Collection<AssignmentEntry> entries)
	{
		final List<AssignmentEntry> sorted = new ArrayList<>();
		if (entries != null)
		{
			for (AssignmentEntry e : entries)
			{
				if (e != null)
				{
					sorted.add(e);
				}
			}
		}
		sorted.sort(NEWEST_FIRST);
		return sorted;
	}

	/**
	 * Whether the saved records suggest that an assignment the plugin didn't watch from its start
	 * ({@link AssignmentWatch.Ended#isCheckRecords()}) was played in an earlier run: the newest record is a partial
	 * (not completed) session of the same creature key with the same assigned size (when both are known). A partial
	 * session doesn't end its assignment, so the assignment it belonged to can still be the one that just ended. Errs
	 * towards "played": a missing entry is better than one for a task that was played.
	 */
	static boolean playedBefore(Collection<LedgerRecord> records, AssignmentEntry entry)
	{
		if (records == null || entry == null || entry.getCreatureId() == null)
		{
			return false;
		}
		final List<LedgerRecord> sorted = LedgerHistory.sortNewestFirst(records);
		if (sorted.isEmpty())
		{
			return false;
		}
		final LedgerRecord newest = sorted.get(0);
		return !newest.isCompleted() && Objects.equals(newest.getCreatureId(), entry.getCreatureId())
			&& (newest.getOriginalAmount() == null || entry.getOriginalAmount() == null
			|| newest.getOriginalAmount().equals(entry.getOriginalAmount()));
	}

	// ---- Display ----

	/** Date of a row, in the locale's short style. */
	static DateTimeFormatter shortDate(ZoneId zone)
	{
		return DateTimeFormatter.ofLocalizedDate(FormatStyle.SHORT).withZone(zone);
	}

	/** Task name, or {@link LedgerHistory#UNKNOWN_MONSTER}. */
	static String monster(AssignmentEntry entry)
	{
		final String monster = entry.getMonster();
		return monster == null || monster.isEmpty() ? LedgerHistory.UNKNOWN_MONSTER : monster;
	}

	/** {@code Skipped \u00b7 10/26/26}: the outcome and the end date (without a date when there is none). */
	static String status(AssignmentEntry entry, DateTimeFormatter date)
	{
		final String label = AssignmentOutcome.orUnknown(entry.getOutcome()).getLabel();
		return entry.getEndedAt() > 0 ? label + SEPARATOR + date.format(Instant.ofEpochMilli(entry.getEndedAt())) : label;
	}

	/** {@code Abyssal demons \u00b7 Skipped \u00b7 10/26/26}. */
	static String rowText(AssignmentEntry entry, DateTimeFormatter date)
	{
		return monster(entry) + SEPARATOR + status(entry, date);
	}

	/**
	 * The row's HTML tooltip: the task, the outcome, the end time, then the master, type, assigned amount and point
	 * change, each only when known.
	 */
	static String tooltip(AssignmentEntry entry, DateTimeFormatter dateTime)
	{
		final StringBuilder sb = new StringBuilder("<html>");
		sb.append(LedgerHistory.escapeHtml(monster(entry)));
		sb.append("<br>").append(AssignmentOutcome.orUnknown(entry.getOutcome()).getDescription());
		if (entry.getEndedAt() > 0)
		{
			sb.append("<br>Ended: ").append(dateTime.format(Instant.ofEpochMilli(entry.getEndedAt())));
		}
		if (SlayerMaster.isKnown(entry.getSlayerMaster()))
		{
			sb.append("<br>").append(LedgerHistory.escapeHtml(LedgerHistory.formatMaster(entry.getSlayerMaster())));
		}
		final TaskType type = TaskType.of(entry.getSlayerMaster(), entry.getCreatureId());
		if (type != null)
		{
			sb.append("<br>").append(LedgerHistory.escapeHtml(LedgerHistory.formatTaskType(type,
				entry.getTaskLocation())));
		}
		if (entry.getOriginalAmount() != null && entry.getOriginalAmount() > 0)
		{
			sb.append("<br>Assigned: ").append(entry.getOriginalAmount());
		}
		if (entry.getPointsChange() != null)
		{
			sb.append("<br>Points: ").append(formatPointsChange(entry.getPointsChange()));
		}
		return sb.append("</html>").toString();
	}

	/** A signed point change: {@code -30}, {@code +18}, {@code 0}. */
	static String formatPointsChange(int change)
	{
		return change > 0 ? "+" + change : Integer.toString(change);
	}

	/** Text of the delete confirmation dialog. */
	static String deleteConfirmation(AssignmentEntry entry)
	{
		return String.format("Delete this %s entry (%s)? This can't be undone.", monster(entry),
			AssignmentOutcome.orUnknown(entry.getOutcome()).getLabel().toLowerCase(Locale.ROOT));
	}
}

package com.shmayvan.slayerledger;

/**
 * How a Slayer assignment ended without a saved session (see {@link AssignmentEntry}), worked out from what changed
 * around its end. Pure; no RuneLite types.
 *
 * <p>The signals, compared between the last settled tick the assignment was active and the end of the decision
 * window ({@link AssignmentWatch}):</p>
 * <ul>
 *     <li>a task completion ({@link CompletionSignal}: one completion counter went up by exactly one);</li>
 *     <li>the change in Slayer points (the SLAYER_POINTS varbit);</li>
 *     <li>whether any of the blocked-task values changed (the SLAYER_REWARDS_BLOCKED* varps and the per-master
 *     SLAYER_BLOCKED_* varbits the plugin reads);</li>
 *     <li>whether a completion counter (task streak) went down.</li>
 * </ul>
 *
 * <p>Cancel and block costs vary by master (OSRS wiki "Slayer Rewards", read 2026-10-26: cancel 30-100, block
 * 40-120), so no amount is assumed: any drop in points counts as points spent, and the observed change is stored.
 * The blocked-task values are not decoded (which slot holds which task is not documented in the API); only "one of
 * them changed at the same moment" is used. When the signals don't fit one outcome cleanly, the outcome is
 * {@link #UNKNOWN}: never a guess.</p>
 */
enum AssignmentOutcome
{
	/** Cancelled for points: points went down, no block changed, no completion, no streak drop. */
	SKIPPED("Skipped", "Skipped (cancelled for points)"),
	/** Blocked: points went down and a blocked-task value changed, no completion, no streak drop. */
	BLOCKED("Blocked", "Blocked"),
	/** Replaced with the streak reset (a Turael or Spria reset): a streak went down and no points were spent. */
	RESET("Reset", "Reset (streak reset, no points spent)"),
	/** Completed without a session: a completion was signalled, and no streak went down. */
	COMPLETED("Completed (untracked)", "Completed without a tracked session"),
	/** The signals fit none of the above (or are missing). */
	UNKNOWN("Ended", "Ended (reason unknown)");

	private final String label;
	private final String description;

	AssignmentOutcome(String label, String description)
	{
		this.label = label;
		this.description = description;
	}

	/** Short label for the history row, e.g. "Skipped". */
	String getLabel()
	{
		return label;
	}

	/** Longer text for the row's tooltip, e.g. "Ended (reason unknown)". */
	String getDescription()
	{
		return description;
	}

	/** A saved outcome, or {@link #UNKNOWN} for {@code null} (for example a value written by a newer build). */
	static AssignmentOutcome orUnknown(AssignmentOutcome outcome)
	{
		return outcome == null ? UNKNOWN : outcome;
	}

	/**
	 * @param completed           whether a task completion was signalled around the end
	 * @param pointsChange        points after minus points before, or {@code null} when either reading is missing
	 * @param blockedValuesChanged whether any blocked-task value changed
	 * @param streakDropped       whether any completion counter went down
	 * @return the outcome; {@link #UNKNOWN} whenever the signals are ambiguous
	 */
	static AssignmentOutcome classify(boolean completed, Integer pointsChange, boolean blockedValuesChanged,
		boolean streakDropped)
	{
		if (completed)
		{
			// A completion with a streak reset (or a block) at the same moment doesn't fit one story.
			return streakDropped || blockedValuesChanged ? UNKNOWN : COMPLETED;
		}
		if (pointsChange == null || streakDropped && pointsChange != 0)
		{
			return UNKNOWN;
		}
		if (pointsChange < 0)
		{
			return blockedValuesChanged ? BLOCKED : SKIPPED;
		}
		if (pointsChange == 0 && streakDropped && !blockedValuesChanged)
		{
			return RESET;
		}
		// Points went up without a completion, a block with no points spent, or nothing changed at all.
		return UNKNOWN;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.List;

/**
 * Formats the chat preview of a newly assigned task from its completed-task history: the History estimate
 * ({@link TaskStatistics#estimate}) and What to bring's bank trips ({@link SupplyRecommendation#forTask}) for the kills
 * left, from the same statistics the panel shows. Pure; no RuneLite types.
 */
final class AssignmentPreviewMessage
{
	private AssignmentPreviewMessage()
	{
	}

	/**
	 * {@code Abyssal demons (172): ~1:40:00 · +1.2M (GE) · ~2 bank trips (from 3 tasks)}: the task, the kills left, then
	 * the estimated active time, profit (loot in {@code mode}, labelled with it, minus supplies; an approximate one as
	 * {@code ~+100} / {@code ~-500}, as the task-complete summary) and bank trips. A part the history doesn't have is
	 * left out. The sample count says where they are from when the statistics are limited to one location
	 * ({@code from 1 task at Smoke Dungeon}).
	 *
	 * @param task  the task's display name ({@link LedgerRecord#displayName})
	 * @param kills the kills left
	 * @param stats the task's statistics, as the panel's History estimate uses them
	 * @return the line, or {@code null} when there is no completed history (or no task, or no kills left)
	 */
	static String format(String task, int kills, TaskStatistics stats, LootPriceMode mode)
	{
		if (task == null || stats == null || kills <= 0)
		{
			return null;
		}
		final TaskStatistics.Estimate estimate = stats.estimate(kills);
		if (estimate == null)
		{
			return null;
		}

		final List<String> parts = new ArrayList<>();
		if (estimate.getActiveMillis() != null)
		{
			parts.add(LedgerHistory.APPROXIMATE + LedgerHistory.formatDuration(estimate.getActiveMillis()));
		}
		final Long loot = estimate.getLootValue();
		final Long supplies = estimate.getSuppliesValue();
		if (loot != null && supplies != null)
		{
			final long profit = saturatedSubtract(loot, supplies);
			final boolean approximate = estimate.isLootApproximate() || estimate.isSuppliesApproximate();
			parts.add((approximate ? LedgerHistory.APPROXIMATE : "") + (profit >= 0 ? "+" : "")
				+ LedgerHistory.formatAmount(profit, false) + " (" + LedgerHistory.priceLabel(mode) + ")");
		}
		final SupplyRecommendation.Estimate bring = SupplyRecommendation.forTask(stats, kills);
		final Long trips = bring == null ? null : bring.getBankTrips();
		if (trips != null)
		{
			// As What to bring's header.
			parts.add(trips == 0 ? "No bank trips" : LedgerHistory.APPROXIMATE + LedgerHistory.formatAmount(trips, false)
				+ (trips == 1 ? " bank trip" : " bank trips"));
		}

		final int samples = estimate.getSampleCount();
		final String from = "(from " + samples + (samples == 1 ? " task" : " tasks")
			+ (stats.getLocation() == null ? "" : " at " + stats.getLocation()) + ")";
		final String head = task + " (" + kills + "):";
		return parts.isEmpty() ? head + " " + from : head + " " + String.join(" · ", parts) + " " + from;
	}

	private static long saturatedSubtract(long left, long right)
	{
		try
		{
			return Math.subtractExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right < 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}
}

package com.shmayvan.slayerledger;

/** One "Skipped / blocked" row. */
final class AssignmentRow
{
	private final AssignmentEntry entry;
	private final String monster;
	private final String status;
	private final String tooltip;

	AssignmentRow(AssignmentEntry entry, String monster, String status, String tooltip)
	{
		this.entry = entry;
		this.monster = monster;
		this.status = status;
		this.tooltip = tooltip;
	}

	AssignmentEntry getEntry()
	{
		return entry;
	}

	String getMonster()
	{
		return monster;
	}

	String getStatus()
	{
		return status;
	}

	String getTooltip()
	{
		return tooltip;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.UUID;

/**
 * Watches Slayer assignments on the plugin's settled ticks and reports each one that ended without a session as an
 * {@link AssignmentEntry} (skipped, blocked, reset, completed while untracked, or ended for an unknown reason; see
 * {@link AssignmentOutcome}). Pure (no RuneLite types) and not thread-safe; the plugin uses it on the client thread
 * only, every settled tick, whether or not a session is running. It only reads; it never acts.
 *
 * <p><b>Played assignments.</b> An assignment that any session held (the creature keys from
 * {@link SessionTracker#takeSessionTaskKeys()}: started, adopted, restored, paused, or held for late loot) is played,
 * and never reported, whether that session was saved as completed, as partial, or discarded. Played-ness is only
 * known for what this plugin run saw: an assignment first seen at a login or plugin start ("not witnessed from its
 * start") may have had a session in an earlier run, so its entry is marked {@link Ended#isCheckRecords()} and the
 * plugin skips it when the newest saved record looks like the same assignment ({@link AssignmentLog#playedBefore}).</p>
 *
 * <p><b>Ending.</b> The assignment ends on the first settled tick it is no longer current: the task count reads 0, or
 * another task (another creature key, name or assigned size) is current. The outcome is decided
 * {@link #END_WINDOW_TICKS} ticks later, comparing the readings on the last tick it was active with the readings then,
 * so points or a streak that arrive a tick late still count. If the count reads 0 and the same task comes back first
 * (a transient zero, as {@link SessionTracker} also allows), nothing ended. An end by a 0 count whose outcome is
 * {@link AssignmentOutcome#UNKNOWN} waits until another task appears (and is dropped if the same task comes back with
 * no more kills left than before), as the tracker treats a long zero gap.</p>
 *
 * <p><b>Logins, hops and lost connections</b> ({@link #reset()}): any undecided end is dropped, and the first reading
 * afterwards only re-reads the baseline, as for {@link CompletionSignal} and {@link TaskRewards}, so a login resync
 * never produces an entry. The current assignment is remembered across it (an assignment still active at logout has
 * not ended): if the task after the login is the same one, it keeps its played flag; otherwise the old one ended while
 * the plugin wasn't watching and is forgotten without an entry. While the count still reads 0 after a login, the
 * baseline waits up to {@link #SYNC_MAX_TICKS} ticks for the task, like the restore check.</p>
 *
 * <p><b>New assignments</b> ({@link #takeStarted()}, for the new-task chat preview): an assignment counts as new only
 * when it is first seen outside a baseline, i.e. watched from its start. One read by a baseline (plugin start, login,
 * hop, account change) or that comes back after a transient or long zero is never new.</p>
 */
final class AssignmentWatch
{
	/** Ticks after the end at which the outcome is decided. One more than the tracker's transient-zero allowance. */
	static final int END_WINDOW_TICKS = SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS + 1;
	/** Ticks a post-login baseline waits for a non-zero task count before deciding there is no task. */
	static final int SYNC_MAX_TICKS = SessionTracker.RESTORE_SYNC_MAX_TICKS;

	/** One settled tick's reading of the task and the values the outcome is decided from; see {@link #builder()}. */
	static final class Reading
	{
		private final String monster;
		private final int creatureId;
		private final int remaining;
		private final int originalAmount;
		private final TaskContext context;
		private final Values values;
		private final boolean completionSignaled;

		private Reading(Builder b)
		{
			this.monster = b.monster;
			this.creatureId = b.creatureId;
			this.remaining = Math.max(0, b.remaining);
			this.originalAmount = b.originalAmount > 0 ? b.originalAmount : SessionTracker.UNKNOWN_AMOUNT;
			this.context = b.context == null ? TaskContext.NONE : b.context;
			this.values = new Values(b.points, b.counters, b.blockedValues);
			this.completionSignaled = b.completionSignaled;
		}

		/** A builder starting from no task: no creature, unknown size, no counters or blocked values. */
		static Builder builder()
		{
			return new Builder();
		}

		/** Builds a {@link Reading}. */
		static final class Builder
		{
			private String monster;
			private int creatureId = SessionTracker.NO_CREATURE;
			private int remaining;
			private int originalAmount = SessionTracker.UNKNOWN_AMOUNT;
			private TaskContext context;
			private int points;
			private int[] counters;
			private int[] blockedValues;
			private boolean completionSignaled;

			private Builder()
			{
			}

			/** Task name, or {@code null} when there is no task or the lookup failed. */
			Builder monster(String monster)
			{
				this.monster = monster;
				return this;
			}

			/** Creature key, or {@link SessionTracker#NO_CREATURE}. */
			Builder creatureId(int creatureId)
			{
				this.creatureId = creatureId;
				return this;
			}

			/** SLAYER_COUNT (0 when there is no task). */
			Builder remaining(int remaining)
			{
				this.remaining = remaining;
				return this;
			}

			/** Assigned size, or {@link SessionTracker#UNKNOWN_AMOUNT}. */
			Builder originalAmount(int originalAmount)
			{
				this.originalAmount = originalAmount;
				return this;
			}

			/** Master and area ({@link TaskContext#assignment}), or {@code null}. */
			Builder context(TaskContext context)
			{
				this.context = context;
				return this;
			}

			/** SLAYER_POINTS. */
			Builder points(int points)
			{
				this.points = points;
				return this;
			}

			/** The completion counters, as passed to {@link CompletionSignal#update}. */
			Builder counters(int[] counters)
			{
				this.counters = counters;
				return this;
			}

			/** Every blocked-task varp and varbit, in the same order every tick. */
			Builder blockedValues(int[] blockedValues)
			{
				this.blockedValues = blockedValues;
				return this;
			}

			/** {@link CompletionSignal#update}'s result for this tick. */
			Builder completionSignaled(boolean completionSignaled)
			{
				this.completionSignaled = completionSignaled;
				return this;
			}

			Reading build()
			{
				return new Reading(this);
			}
		}

		private boolean hasTask()
		{
			return remaining > 0;
		}
	}

	/** An ended assignment to store. */
	static final class Ended
	{
		private final AssignmentEntry entry;
		private final boolean checkRecords;

		private Ended(AssignmentEntry entry, boolean checkRecords)
		{
			this.entry = entry;
			this.checkRecords = checkRecords;
		}

		AssignmentEntry getEntry()
		{
			return entry;
		}

		/**
		 * Whether the assignment wasn't watched from its start, so a session in an earlier plugin run can't be ruled
		 * out: store it only if {@link AssignmentLog#playedBefore} says the saved records don't show one.
		 */
		boolean isCheckRecords()
		{
			return checkRecords;
		}
	}

	/** Points, completion counters and blocked-task values at one reading. */
	private static final class Values
	{
		private final int points;
		private final int[] counters;
		private final int[] blocked;

		private Values(int points, int[] counters, int[] blocked)
		{
			this.points = points;
			this.counters = counters == null ? new int[0] : counters.clone();
			this.blocked = blocked == null ? new int[0] : blocked.clone();
		}
	}

	/** An assignment as watched. */
	private static final class Assignment
	{
		private String monster;
		private final int creatureId;
		private int originalAmount;
		private TaskContext context;
		private int remaining;
		private final boolean witnessedStart;
		private boolean played;
		/** Readings on the last tick the assignment was current. */
		private Values lastActive;
		/** Whether a completion was signalled on that tick. */
		private boolean completionOnLastActive;

		private Assignment(Reading r, boolean witnessedStart)
		{
			this.monster = r.monster;
			this.creatureId = r.creatureId;
			this.originalAmount = r.originalAmount;
			this.context = r.context;
			this.remaining = r.remaining;
			this.witnessedStart = witnessedStart;
			this.lastActive = r.values;
			this.completionOnLastActive = r.completionSignaled;
		}

		/** Same task: creature key, name (when both known) and assigned size (when both known). */
		private boolean sameTask(Reading r)
		{
			return r.hasTask() && r.creatureId == creatureId
				&& (r.monster == null || monster == null || r.monster.equals(monster))
				&& (r.originalAmount == SessionTracker.UNKNOWN_AMOUNT || originalAmount == SessionTracker.UNKNOWN_AMOUNT
				|| r.originalAmount == originalAmount);
		}

		/** The same task after a gap (a login, or a long zero): also no more kills left than before. */
		private boolean sameTaskAfterGap(Reading r)
		{
			return sameTask(r) && r.remaining <= remaining;
		}

		/** Takes this tick's reading of the same task. */
		private void refresh(Reading r)
		{
			if (monster == null)
			{
				monster = r.monster;
			}
			if (originalAmount == SessionTracker.UNKNOWN_AMOUNT)
			{
				originalAmount = r.originalAmount;
			}
			context = context.fillAssignment(r.context);
			remaining = r.remaining;
			lastActive = r.values;
			completionOnLastActive = r.completionSignaled;
		}
	}

	/** An assignment that has ended, waiting for its outcome. */
	private static final class Pending
	{
		private final Assignment assignment;
		private final long endedAt;
		private final boolean endedByZero;
		private boolean completion;
		private int ticks;
		/** Readings at the end of the window, once an unknown outcome waits for the next task; else {@code null}. */
		private Values frozen;

		private Pending(Assignment assignment, long endedAt, boolean endedByZero, boolean completion)
		{
			this.assignment = assignment;
			this.endedAt = endedAt;
			this.endedByZero = endedByZero;
			this.completion = completion;
		}
	}

	/** The current assignment, or {@code null}; kept across {@link #reset()}. */
	private Assignment current;
	/** The ended assignment waiting for its outcome, or {@code null}. */
	private Pending pending;
	/** Whether the next readings only set the baseline (after construction, {@link #reset()} or {@link #forget()}). */
	private boolean syncing = true;
	/** Zero-count readings while syncing. */
	private int syncTicks;
	/** The current assignment watched from its start, until {@link #takeStarted()} takes it; else {@code null}. */
	private Assignment started;

	/** After a login, hop or lost connection: drops an undecided end, keeps the current assignment; see the class. */
	void reset()
	{
		pending = null;
		syncing = true;
		syncTicks = 0;
		started = null;
	}

	/** After an account change: forgets everything, including the current assignment. */
	void forget()
	{
		reset();
		current = null;
	}

	/**
	 * Takes one settled tick's reading.
	 *
	 * @param r               this tick's reading
	 * @param sessionTaskKeys {@link SessionTracker#takeSessionTaskKeys()} for this tick: creature keys of tasks a
	 *                        session held since the last tick
	 * @param now             the time (epoch ms), used as the end time of an assignment that ends on this tick
	 * @return the assignments to store (usually none)
	 */
	List<Ended> update(Reading r, Set<Integer> sessionTaskKeys, long now)
	{
		markPlayed(sessionTaskKeys);
		if (syncing)
		{
			sync(r);
			markPlayed(sessionTaskKeys);
			return Collections.emptyList();
		}

		final List<Ended> ended = new ArrayList<>(1);
		if (pending != null && current == null && pending.endedByZero && !pending.completion
			&& (pending.frozen == null ? pending.assignment.sameTask(r) : pending.assignment.sameTaskAfterGap(r)))
		{
			// A transient zero: the same task is back, so it never ended.
			current = pending.assignment;
			current.refresh(r);
			pending = null;
		}
		else if (current != null && current.sameTask(r))
		{
			current.refresh(r);
		}
		else if (current != null)
		{
			if (pending != null)
			{
				// Another end before the last one was decided: decide that one now, by the readings just before this
				// second change, so the second assignment's points or streak don't count for the first.
				add(ended, pending, current.lastActive);
			}
			pending = new Pending(current, now, !r.hasTask(), current.completionOnLastActive || r.completionSignaled);
			current = r.hasTask() ? new Assignment(r, true) : null;
			started = current;
			markPlayed(sessionTaskKeys);
			return ended;
		}
		else if (r.hasTask())
		{
			current = new Assignment(r, true);
			started = current;
			if (pending != null && pending.frozen != null)
			{
				// Another task after a long zero: the old one ended, reason unknown.
				add(ended, pending, pending.frozen);
				pending = null;
			}
		}

		if (pending != null && pending.frozen == null)
		{
			pending.ticks++;
			pending.completion |= r.completionSignaled;
			if (pending.ticks >= END_WINDOW_TICKS)
			{
				if (pending.endedByZero && current == null && outcome(pending, r.values) == AssignmentOutcome.UNKNOWN)
				{
					pending.frozen = r.values;
				}
				else
				{
					add(ended, pending, r.values);
					pending = null;
				}
			}
		}
		markPlayed(sessionTaskKeys);
		return ended;
	}

	private void sync(Reading r)
	{
		if (r.hasTask())
		{
			if (current != null && current.sameTaskAfterGap(r))
			{
				current.refresh(r);
			}
			else
			{
				// A new assignment, or the old one ended while the plugin wasn't watching: no entry either way.
				current = new Assignment(r, false);
			}
			syncing = false;
		}
		else if (++syncTicks >= SYNC_MAX_TICKS)
		{
			current = null;
			syncing = false;
		}
	}

	private void markPlayed(Set<Integer> keys)
	{
		if (keys == null || keys.isEmpty())
		{
			return;
		}
		if (current != null && keys.contains(current.creatureId))
		{
			current.played = true;
		}
		if (pending != null && keys.contains(pending.assignment.creatureId))
		{
			pending.assignment.played = true;
		}
	}

	private static AssignmentOutcome outcome(Pending p, Values now)
	{
		final Values before = p.assignment.lastActive;
		boolean streakDropped = false;
		final int n = Math.min(before.counters.length, now.counters.length);
		for (int i = 0; i < n; i++)
		{
			if (now.counters[i] < before.counters[i])
			{
				streakDropped = true;
				break;
			}
		}
		return AssignmentOutcome.classify(p.completion, now.points - before.points,
			!Arrays.equals(before.blocked, now.blocked), streakDropped);
	}

	/** Adds the pending assignment's entry, unless a session held it. */
	private static void add(List<Ended> ended, Pending p, Values now)
	{
		final Assignment a = p.assignment;
		if (a.played)
		{
			return;
		}
		final AssignmentEntry entry = new AssignmentEntry();
		entry.setId(UUID.randomUUID().toString());
		entry.setMonster(a.monster);
		entry.setCreatureId(a.creatureId == SessionTracker.NO_CREATURE ? null : a.creatureId);
		entry.setOriginalAmount(a.originalAmount == SessionTracker.UNKNOWN_AMOUNT ? null : a.originalAmount);
		entry.setSlayerMaster(a.context.getMaster());
		entry.setSlayerArea(a.context.getArea());
		entry.setTaskLocation(a.context.getLocation());
		entry.setEndedAt(p.endedAt);
		entry.setOutcome(outcome(p, now));
		entry.setPointsChange(now.points - a.lastActive.points);
		ended.add(new Ended(entry, !a.witnessedStart));
	}

	/**
	 * Whether the last {@link #update} saw a new assignment (one watched from its start; see the class), once: the
	 * flag is cleared by this call, by a later assignment replacing it, and by {@link #reset()}.
	 *
	 * @return {@code true} at most once per new assignment
	 */
	boolean takeStarted()
	{
		final boolean isNew = started != null && started == current;
		started = null;
		return isNew;
	}

	/** Test seam: whether an assignment is being watched now. */
	boolean hasCurrent()
	{
		return current != null;
	}

	/** Test seam: whether an ended assignment waits for its outcome. */
	boolean hasPending()
	{
		return pending != null;
	}

	@Override
	public String toString()
	{
		return "AssignmentWatch(current=" + (current == null ? null : current.creatureId) + ", pending="
			+ (pending == null ? null : pending.assignment.creatureId) + ", syncing=" + syncing + ")";
	}
}

package com.shmayvan.slayerledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.BiConsumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The collapsed "Skipped / blocked" section of {@link SlayerLedgerPanel}: assignments that ended without a saved
 * session, which never count as played tasks. Rows ({@link LedgerHistoryModel#assignmentRows}) are built only while the
 * section is open and its "Skipped / blocked" setting shows it. EDT only.
 *
 * <p>Each row's monster shows its task's icon ({@link TaskIcons}), or an empty slot of the same size for a name
 * that is no known task; asked for only as the rows are built.</p>
 */
final class AssignmentsSection
{
	private final LedgerHistoryModel model;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Parent of the delete confirmation. */
	private final Component dialogParent;
	/** Deletes the entry with the given id from the account's log, after the player confirmed it. */
	private final BiConsumer<Long, String> delete;
	/** Draws the rows' task icons. */
	private final ItemIcons icons;

	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	private final JLabel title = new JLabel();
	private final JLabel toggle = new JLabel();
	private final JPanel body = new JPanel();
	private final JPanel list = new JPanel();
	/** Whether the section is open; collapsed whenever the panel is created (owner decision). */
	private boolean expanded;
	/** How many times the rows were built. */
	private int builds;
	/** The "Skipped / blocked" setting; while off, no rows are built. The panel hides the components. */
	private boolean shown = true;

	/** @param icons draws the rows' task icons */
	AssignmentsSection(LedgerHistoryModel model, Runnable relayout, Component dialogParent,
		BiConsumer<Long, String> delete, ItemIcons icons)
	{
		this.model = model;
		this.relayout = relayout;
		this.dialogParent = dialogParent;
		this.delete = delete;
		this.icons = icons;
	}

	/** Adds the header and the body to {@code content}, collapsed. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		header.setName("assignments.header");
		title.setName("assignments.title");
		toggle.setName("assignments.toggle");
		body.setName("assignments.body");
		list.setName("assignments.list");
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		toggle.setFont(FontManager.getRunescapeSmallFont());
		toggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(title, BorderLayout.WEST);
		header.add(toggle, BorderLayout.EAST);
		header.setToolTipText("<html>Assignments that ended without a saved session: skipped, blocked,"
			+ " reset,<br>or completed while no session was tracked. They don't count as played tasks.</html>");
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggle();
			}
		});
		SlayerLedgerPanel.addRow(content, header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel hint = new JLabel("Not counted as played tasks. Right-click to delete.");
		hint.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(hint);
		body.add(Box.createVerticalStrut(4));
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(list);
		SlayerLedgerPanel.addRow(content, body);
		rebuild();
	}

	/** Opens or closes the section, as a click on its header does. */
	void toggle()
	{
		expanded = !expanded;
		rebuild();
	}

	/**
	 * Applies the "Skipped / blocked" setting: hidden, the section drops its rows and builds none; shown again, it
	 * is rebuilt at once if it was open.
	 */
	void setShown(boolean value)
	{
		if (shown != value)
		{
			shown = value;
			rebuild();
		}
	}

	/** Shows the section as it now is: the title with the count, and while open and shown, the rows. */
	void rebuild()
	{
		title.setText("Skipped / blocked (" + model.assignments().size() + ")");
		toggle.setText(expanded ? "Hide" : "Show");
		body.setVisible(expanded);
		list.removeAll();
		// No rows while collapsed or hidden.
		if (expanded && shown)
		{
			builds++;
			if (model.assignments().isEmpty())
			{
				JLabel empty = new JLabel("None yet.");
				empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				empty.setFont(FontManager.getRunescapeSmallFont());
				empty.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
				empty.setAlignmentX(Component.LEFT_ALIGNMENT);
				list.add(empty);
			}
			for (AssignmentRow entry : model.assignmentRows())
			{
				if (list.getComponentCount() > 0)
				{
					list.add(Box.createVerticalStrut(2));
				}
				JPanel row = row(model.account(), entry);
				row.setAlignmentX(Component.LEFT_ALIGNMENT);
				list.add(row);
			}
		}
		relayout.run();
	}

	private JPanel row(long account, AssignmentRow shownRow)
	{
		AssignmentEntry entry = shownRow.getEntry();
		JLabel name = SlayerLedgerPanel.historyLabel(shownRow.getMonster(), Color.WHITE);
		// A name for tests, which read the icon from it; no visible effect.
		name.setName("assignments.name");
		SmallItemIcon.applyTask(icons, name, entry.getMonster());
		JPanel row = SlayerLedgerPanel.historyLine(name,
			SlayerLedgerPanel.historyLabel(shownRow.getStatus(), ColorScheme.LIGHT_GRAY_COLOR));
		row.setOpaque(true);
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 8));
		row.setToolTipText(shownRow.getTooltip());

		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		JMenuItem deleteItem = new JMenuItem("Delete entry");
		// LedgerStore.deleteAssignment matches by id; an entry without one cannot be targeted safely.
		deleteItem.setEnabled(entry.getId() != null);
		deleteItem.addActionListener(e -> confirmDelete(account, entry));
		menu.add(deleteItem);
		row.setComponentPopupMenu(menu);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
		return row;
	}

	/** Asks before deleting an assignment entry; Cancel or closing the dialog does nothing. */
	private void confirmDelete(long account, AssignmentEntry entry)
	{
		String[] options = {"Delete", "Cancel"};
		int choice = JOptionPane.showOptionDialog(dialogParent, AssignmentLog.deleteConfirmation(entry),
			"Slayer Ledger", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);
		if (choice != 0 || entry.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		delete.accept(account, entry.getId());
	}

	/** How many times the rows were built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}
}

package com.shmayvan.slayerledger;

/**
 * The chat line posted after a logout or world hop paused a running session. Resuming stays manual (owner
 * decision), so the line says how to keep tracking.
 */
final class AutoPauseMessage
{
	/** What paused the session. */
	enum Reason
	{
		WORLD_HOP("world hop"),
		LOGOUT("logged out");

		private final String text;

		Reason(String text)
		{
			this.text = text;
		}
	}

	private AutoPauseMessage()
	{
	}

	/** The chat line for {@code reason}, for example {@code Slayer Ledger paused (world hop). Press Resume ...}. */
	static String format(Reason reason)
	{
		return "Slayer Ledger paused (" + reason.text + "). Press Resume to keep tracking.";
	}
}

package com.shmayvan.slayerledger;

import java.util.Objects;

/**
 * Decides which bank openings start a new bank trip. Pure: the plugin passes in the interface events and tick numbers
 * it sees on the client thread, and adds a trip to the session when {@link #bankOpened} says so. Not thread-safe.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>A bank interface ({@link #isBankInterface}: the bank, a deposit box or group storage, the same interfaces
 *     {@link SupplyExclusions} leaves out of supply counting) opening while the session is RUNNING is a trip.</li>
 *     <li>Opening one again within {@link #SAME_TRIP_TICKS} game ticks of the last time one was open (opened or closed)
 *     is the same trip, so going back for a forgotten item, or from a deposit box to the bank, counts once.</li>
 *     <li>Opening a bank while paused or with no session is never a trip, but still starts the window, so re-opening
 *     right after resuming does not count either.</li>
 *     <li>The window belongs to one session: the first opening in a new session always counts.</li>
 * </ul>
 * The trip count itself is kept by {@link SessionTracker} (RUNNING only, cleared when the session ends).
 */
final class BankTripCounter
{
	/** Re-opening a bank within this many game ticks (30 seconds) of it last being open is the same trip. */
	static final int SAME_TRIP_TICKS = 50;

	private static final int[] BANK_INTERFACES = SupplyExclusions.bankInterfaces();

	/** Last tick a bank interface was opened or closed, or {@code null} for none. */
	private Integer lastBankTick;
	/** Session (running or paused) active when a bank was last opened, or {@code null} for none. */
	private String lastSessionId;

	/** Whether {@code groupId} is the bank, a deposit box or group storage. */
	static boolean isBankInterface(int groupId)
	{
		for (int group : BANK_INTERFACES)
		{
			if (group == groupId)
			{
				return true;
			}
		}
		return false;
	}

	/** A copy of the bank interface group ids. */
	static int[] bankInterfaces()
	{
		return BANK_INTERFACES.clone();
	}

	/**
	 * A bank interface opened on {@code tick}.
	 *
	 * @param running   whether the session is RUNNING
	 * @param sessionId the running or paused session's id, or {@code null} when there is none
	 * @return whether this opening is a new trip to add to the running session
	 */
	boolean bankOpened(int tick, boolean running, String sessionId)
	{
		final boolean sameTrip = withinWindow(tick) && Objects.equals(sessionId, lastSessionId);
		lastBankTick = tick;
		lastSessionId = sessionId;
		return running && sessionId != null && !sameTrip;
	}

	/** A bank interface closed on {@code tick}; the same-trip window runs from here. */
	void bankClosed(int tick)
	{
		if (lastBankTick != null)
		{
			lastBankTick = tick;
		}
	}

	/** Forgets the last bank visit (plugin start). */
	void reset()
	{
		lastBankTick = null;
		lastSessionId = null;
	}

	/**
	 * Whether {@code tick} is within the window of the last visit. A tick before the last visit (the tick count
	 * restarted, for example after a login) is outside it.
	 */
	private boolean withinWindow(int tick)
	{
		return lastBankTick != null && tick >= lastBankTick && (long) tick - lastBankTick <= SAME_TRIP_TICKS;
	}
}

package com.shmayvan.slayerledger;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Text;

/**
 * Reads the toxic blowpipe's dart type from game messages. Pure (RuneLite's static {@link Text} only).
 *
 * <p>Checking the blowpipe (and, reportedly, adding darts or scales) sends
 * {@code Darts: <name> x <n>. Scales: <n> (<pct>%).} or {@code Darts: None. Scales: ...}, with the values coloured.
 * Tags are stripped before matching; numbers may contain commas. The messages below, from geheur/weapon-charges'
 * recorded game messages, mean the blowpipe has no darts:</p>
 * <ul>
 *     <li>{@code Your blowpipe has run out of darts.}</li>
 *     <li>{@code Your blowpipe has run out of scales and darts.}</li>
 *     <li>{@code Your blowpipe contains no darts.}</li>
 *     <li>{@code Your blowpipe needs to be charged with Zulrah's scales and loaded with darts.}</li>
 *     <li>{@code The blowpipe has no darts in it.} (unloading an empty blowpipe)</li>
 * </ul>
 */
final class BlowpipeMessage
{
	private static final Pattern CHECK = Pattern.compile(
		"^Darts: (?:None|(.+?) x ([\\d,]+))\\. Scales: ([\\d,]+) \\(([\\d.]+)%\\)\\.$");

	private static final String[] NO_DARTS = {
		"Your blowpipe has run out of darts.",
		"Your blowpipe has run out of scales and darts.",
		"Your blowpipe contains no darts.",
		"Your blowpipe needs to be charged with Zulrah's scales and loaded with darts.",
		"The blowpipe has no darts in it.",
	};

	/** Dart names as the check message shows them (lower case), to item ids. */
	private static final Map<String, Integer> DARTS = darts();

	private static Map<String, Integer> darts()
	{
		final Map<String, Integer> darts = new HashMap<>();
		darts.put("bronze dart", ItemID.BRONZE_DART);
		darts.put("iron dart", ItemID.IRON_DART);
		darts.put("steel dart", ItemID.STEEL_DART);
		darts.put("black dart", ItemID.BLACK_DART);
		darts.put("mithril dart", ItemID.MITHRIL_DART);
		darts.put("adamant dart", ItemID.ADAMANT_DART);
		darts.put("rune dart", ItemID.RUNE_DART);
		darts.put("amethyst dart", ItemID.AMETHYST_DART);
		darts.put("dragon dart", ItemID.DRAGON_DART);
		return Collections.unmodifiableMap(darts);
	}

	/** What a blowpipe message says about the darts inside. */
	@Value
	static class Darts
	{
		/** Whether the blowpipe holds darts. */
		boolean loaded;
		/**
		 * The dart item id, or {@link ChargedWeaponUsage#NO_ITEM} if the blowpipe holds no darts or holds a dart type
		 * this class doesn't know.
		 */
		int dartId;
		/** Darts inside, if the message says (a check message), else -1. */
		int dartCount;
		/** Zulrah's scales inside, if the message says (a check message), else -1. */
		int scales;
	}

	private BlowpipeMessage()
	{
	}

	/** The dart item id for a dart name as the check message shows it ("Rune dart"), or {@code NO_ITEM}. */
	static int dartId(String name)
	{
		return DARTS.getOrDefault(name.trim().toLowerCase(Locale.ROOT), ChargedWeaponUsage.NO_ITEM);
	}

	/**
	 * Parses a game message, possibly with tags.
	 *
	 * @return what it says about the blowpipe's darts, or {@code null} if it isn't a blowpipe dart message
	 */
	static Darts parse(String message)
	{
		if (message == null)
		{
			return null;
		}
		final String text = Text.removeTags(message).trim();
		final Matcher matcher = CHECK.matcher(text);
		if (matcher.matches())
		{
			final int scales = number(matcher.group(3));
			if (matcher.group(1) == null)
			{
				return new Darts(false, ChargedWeaponUsage.NO_ITEM, 0, scales);
			}
			return new Darts(true, dartId(matcher.group(1)), number(matcher.group(2)), scales);
		}
		for (String noDarts : NO_DARTS)
		{
			if (noDarts.equals(text))
			{
				return new Darts(false, ChargedWeaponUsage.NO_ITEM, 0, -1);
			}
		}
		return null;
	}

	private static int number(String digits)
	{
		try
		{
			return Integer.parseInt(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

