package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Rules for a task's boss kill counts ({@link BossKillCount}), from the game's kill count messages
 * ({@link KillCountMessage}). Pure (no RuneLite types).
 *
 * <ul>
 *     <li><b>Which messages count.</b> Only boss kill messages ({@link KillCountMessage.Result#isBossKill()}), and only
 *     while loot is being recorded (the session is running, or a completed task waits for its last loot; enforced by
 *     {@link SessionTracker#addBossKillCount}). On a boss task (SLAYER_TARGET
 *     {@value SessionTracker#BOSS_TASK_TARGET}) every boss's message counts, since one task can give counts under
 *     several names (Dagannoth Kings give Rex, Prime and Supreme; Barrows gives "Barrows chest"). On any other task a
 *     message counts only when its boss name {@linkplain #sameName matches} the task's name, for example a TzTok-Jad
 *     or TzKal-Zuk task.</li>
 *     <li><b>Name matching.</b> Colour tags are removed, runs of spaces (including non-breaking spaces) become one
 *     space, and the ends are trimmed; the two names must then be equal ignoring case. Nothing fuzzier: no plurals,
 *     prefixes or aliases.</li>
 *     <li><b>What is kept.</b> One entry per boss name (same matching), in the order first seen: the name as the
 *     first message gave it, the first and latest count, and the kills counted. A message counts a kill when its count
 *     is higher than the entry's latest (so a repeated message counts once); the first message of a boss counts one.
 *     Kills while paused have no message counted, so they are not in the kills, but the next count includes them.
 *     The count before the task is not stored: it can't be told reliably (kills before Play, or while paused).</li>
 *     <li>A task keeps at most {@link #MAX_PER_TASK} bosses; a further boss's messages are not counted.</li>
 * </ul>
 */
final class BossKillCounts
{
	/** Most bosses kept per task. */
	static final int MAX_PER_TASK = 8;

	private BossKillCounts()
	{
	}

	/** A name without colour tags, with runs of spaces made one and the ends trimmed ("" for {@code null}). */
	static String cleanName(String name)
	{
		if (name == null)
		{
			return "";
		}
		return name.replaceAll("<[^>]*>", "").replace('\u00A0', ' ').replaceAll("\\s+", " ").trim();
	}

	/** Whether two names are the same boss or task: equal after {@link #cleanName}, ignoring case. */
	static boolean sameName(String a, String b)
	{
		final String left = key(a);
		return !left.isEmpty() && left.equals(key(b));
	}

	private static String key(String name)
	{
		return cleanName(name).toLowerCase(Locale.ROOT);
	}

	/**
	 * Whether a boss's kill count message belongs to a task.
	 *
	 * @param taskName   the task's name, or {@code null} when unknown
	 * @param creatureId the task's creature key ({@link SessionTracker#creatureKey}); boss tasks are below
	 *                   {@link SessionTracker#NO_CREATURE}
	 * @param boss       the boss name the message gives
	 */
	static boolean appliesTo(String taskName, int creatureId, String boss)
	{
		if (cleanName(boss).isEmpty())
		{
			return false;
		}
		return creatureId < SessionTracker.NO_CREATURE || sameName(taskName, boss);
	}

	/**
	 * The task's kill counts with one more message counted (see the class rules). Returns a new list;
	 * {@code current} is not changed.
	 *
	 * @param current the task's kill counts so far, or {@code null}
	 * @param boss    the boss name the message gives
	 * @param kc      the count the message gives; below 1 is ignored
	 */
	static List<BossKillCount> add(List<BossKillCount> current, String boss, int kc)
	{
		final List<BossKillCount> result = sanitize(current);
		final String name = cleanName(boss);
		if (name.isEmpty() || kc < 1)
		{
			return result;
		}
		for (int i = 0; i < result.size(); i++)
		{
			final BossKillCount entry = result.get(i);
			if (sameName(entry.getBoss(), name))
			{
				if (kc > entry.getLastKc())
				{
					result.set(i, new BossKillCount(entry.getBoss(), entry.getFirstKc(), kc, entry.getKills() + 1));
				}
				return result;
			}
		}
		if (result.size() < MAX_PER_TASK)
		{
			result.add(new BossKillCount(name, kc, kc, 1));
		}
		return result;
	}

	/**
	 * The usable entries of a stored list (never {@code null}; a new list): an entry without a name, with a count
	 * below 1, a first count above the latest, or no kills is left out, and so is a later entry for a boss already
	 * listed and anything beyond {@link #MAX_PER_TASK}.
	 */
	static List<BossKillCount> sanitize(List<BossKillCount> counts)
	{
		final List<BossKillCount> result = new ArrayList<>();
		if (counts == null)
		{
			return result;
		}
		final Set<String> seen = new HashSet<>();
		for (BossKillCount entry : counts)
		{
			if (result.size() >= MAX_PER_TASK)
			{
				break;
			}
			if (entry == null || cleanName(entry.getBoss()).isEmpty() || entry.getFirstKc() < 1
				|| entry.getLastKc() < entry.getFirstKc() || entry.getKills() < 1 || !seen.add(key(entry.getBoss())))
			{
				continue;
			}
			result.add(entry);
		}
		return result;
	}

	/**
	 * One line per boss, for the panel and the history tooltip: {@code Boss KC: 152 (+12)} for the boss the task is
	 * named after, {@code Dagannoth Rex KC: 52 (+4)} for any other. The number is the latest count and {@code +n} the
	 * kills counted on the task. Empty when there are none.
	 *
	 * @param taskName the task's name, or {@code null}
	 */
	static List<String> lines(List<BossKillCount> counts, String taskName)
	{
		final List<BossKillCount> usable = sanitize(counts);
		if (usable.isEmpty())
		{
			return Collections.emptyList();
		}
		final List<String> lines = new ArrayList<>();
		for (BossKillCount entry : usable)
		{
			final String label = sameName(entry.getBoss(), taskName) ? "Boss" : cleanName(entry.getBoss());
			lines.add(label + " KC: " + String.format(Locale.ROOT, "%,d", entry.getLastKc())
				+ " (+" + String.format(Locale.ROOT, "%,d", entry.getKills()) + ")");
		}
		return lines;
	}
}

package com.shmayvan.slayerledger;

import java.util.Comparator;

/** One What to bring row. */
final class BringRow
{
	private final int itemId;
	private final String name;
	private final long quantity;
	private final ItemDetails.Unit unit;
	/** Value at a GE unit price, or {@code null} without one; for sorting only. */
	private final Long value;

	BringRow(int itemId, String name, long quantity, ItemDetails.Unit unit, Long value)
	{
		this.itemId = itemId;
		this.name = name;
		this.quantity = quantity;
		this.unit = unit;
		this.value = value;
	}

	/**
	 * What to bring's order: priced items first, by value (amount times a GE unit price, per dose for dose-counted ids),
	 * then unpriced items; ties by amount, then by name and id.
	 */
	static final Comparator<BringRow> ORDER = (a, b) ->
	{
		if ((a.value == null) != (b.value == null))
		{
			return a.value == null ? 1 : -1;
		}
		int order = a.value != null ? Long.compare(b.value, a.value) : 0;
		if (order == 0)
		{
			order = Long.compare(b.quantity, a.quantity);
		}
		if (order == 0)
		{
			order = String.CASE_INSENSITIVE_ORDER.compare(a.name, b.name);
		}
		return order != 0 ? order : Integer.compare(a.itemId, b.itemId);
	};

	String getName()
	{
		return name;
	}

	/** "x30", or "13 doses" / "1 dose" for a dose-counted id, as the item lists write it. */
	String quantityText()
	{
		String amount = LedgerHistory.formatAmount(quantity, false);
		return unit == ItemDetails.Unit.ITEMS ? "x" + amount : amount + " " + unitWord();
	}

	/** "30 x Cannonballs", or "13 doses of Prayer potion"; plain text, escaped by the caller. */
	String tooltipText()
	{
		String amount = LedgerHistory.formatAmount(quantity, false);
		return unit == ItemDetails.Unit.ITEMS ? amount + " x " + name : amount + " " + unitWord() + " of " + name;
	}

	private String unitWord()
	{
		return quantity == 1 ? unit.getOne() : unit.getMany();
	}
}

package com.shmayvan.slayerledger;

import java.util.Map;

/**
 * Cannon tasks (owner decision): a task counts as a <b>cannon task</b> when any cannonballs, regular or granite
 * ({@link SupplyTracker#CANNONBALL}, {@link SupplyTracker#GRANITE_CANNONBALL}), were fired during it, that is when the
 * session's supplies used hold any. Cannonballs that come back (picked up or unloaded) are taken off the supplies
 * ({@link SessionTracker#addSupplies}), so loading a cannon and picking it up again without firing is not a cannon
 * task. Nothing is stored for it: a saved record is classified from its {@link LedgerRecord#getSupplies supplies}, so
 * every record with supply data is classified the same way, and a record saved before supplies were tracked (no
 * supplies) is a task without a cannon. Pure (no RuneLite types).
 *
 * <p>A cannon task is its own group beside the task's other tasks, named with {@link #SUFFIX}, for example
 * "Dust devils (cannon)" or, done on a Catacombs variant, "Deviant spectres (cannon)" ({@link #name}).</p>
 */
final class CannonTasks
{
	/** What a cannon task's name ends with: {@code " (cannon)"}. */
	static final String SUFFIX = " (cannon)";

	private CannonTasks()
	{
	}

	/**
	 * Whether {@code supplies} (item id to quantity used, as a record stores them) hold any fired cannonballs, regular
	 * or granite; {@code false} for {@code null} (a record saved before supplies were tracked).
	 */
	static boolean fired(Map<Integer, Long> supplies)
	{
		if (supplies == null)
		{
			return false;
		}
		return positive(supplies.get(SupplyTracker.CANNONBALL))
			|| positive(supplies.get(SupplyTracker.GRANITE_CANNONBALL));
	}

	/** As {@link #fired(Map)}, for the live session's supplies used. */
	static boolean fired(ItemTally supplies)
	{
		return supplies != null && (supplies.get(SupplyTracker.CANNONBALL) > 0
			|| supplies.get(SupplyTracker.GRANITE_CANNONBALL) > 0);
	}

	/**
	 * The name a task is shown and grouped under: {@code name} with {@link #SUFFIX} for a cannon task, else
	 * {@code name} itself; {@code null} stays {@code null}.
	 */
	static String name(String name, boolean cannon)
	{
		return name == null || !cannon ? name : name + SUFFIX;
	}

	private static boolean positive(Long quantity)
	{
		return quantity != null && quantity > 0;
	}
}

package com.shmayvan.slayerledger;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.NpcID;

/**
 * The Catacombs of Kourend variants of Slayer task monsters, for example Deviant spectres on an Aberrant spectres
 * task, and the rule that decides from a session's kills ({@link NpcKillTally}) whether a task was done on its variant.
 * Pure (no RuneLite types; the ids are the RuneLite 1.13.4 gameval {@code NpcID} constants, plain ints).
 *
 * <p>The table is curated: one entry per task with a Catacombs-only variant, keyed by the NPC id the game uses in the
 * Catacombs ({@code NpcID.KOUREND_*}, ids 7272 to 7279). Each id and its NPC name were checked against the RuneLite
 * 1.13.4 gameval {@code NpcID} constants and their javadoc names; {@code CatacombsVariantsTest} checks the constants
 * again. Some variants also live outside the Catacombs under the same name with other ids (Greater Nechryael in the
 * Wilderness Slayer Cave, Mutated Bloodveld in Meiyerditch, Brutal dragons in Lithkren and Tapoyauik); those are not
 * Catacombs variants, so {@link #tallyName} leaves them out of the tally.</p>
 *
 * <p><b>Majority rule.</b> A task counts as its variant when the session's tallied kills of the variant are more than
 * half of the session's task kills (the kills the game's task counter counted, {@link SessionTracker#getKills}). Other
 * tallied kills (an Ankou on the way, Greater Nechryael death spawns, other monsters in a barrage) don't count either
 * way. A tie, no task kills, or a task without a variant is the standard monster.</p>
 */
final class CatacombsVariants
{
	/** One task's Catacombs variant. Immutable. */
	static final class Variant
	{
		private final String task;
		private final int npcId;
		private final String npcName;
		private final String name;

		private Variant(String task, int npcId, String npcName, String name)
		{
			this.task = task;
			this.npcId = npcId;
			this.npcName = npcName;
			this.name = name;
		}

		/** The Slayer task's name, as the game's task table gives it (for example "Aberrant spectres"). */
		String getTask()
		{
			return task;
		}

		/** The variant's NPC id in the Catacombs. */
		int getNpcId()
		{
			return npcId;
		}

		/** The variant's NPC name, as the game gives it (for example "Deviant spectre"). */
		String getNpcName()
		{
			return npcName;
		}

		/** The name a variant task is shown and grouped under, like a task name (for example "Deviant spectres"). */
		String getName()
		{
			return name;
		}
	}

	private static final List<Variant> VARIANTS = Collections.unmodifiableList(Arrays.asList(
		new Variant("Aberrant spectres", NpcID.KOUREND_SPECTRE, "Deviant spectre", "Deviant spectres"),
		new Variant("Nechryael", NpcID.KOUREND_NECHRYAEL, "Greater Nechryael", "Greater nechryael"),
		new Variant("Bloodveld", NpcID.KOUREND_BLOODVELD, "Mutated Bloodveld", "Mutated bloodveld"),
		new Variant("Jellies", NpcID.KOUREND_JELLY, "Warped Jelly", "Warped jellies"),
		new Variant("Banshees", NpcID.KOUREND_BANSHEE, "Twisted Banshee", "Twisted banshees"),
		new Variant("Black dragons", NpcID.KOUREND_BLACK_DRAGON, "Brutal black dragon", "Brutal black dragons"),
		new Variant("Blue dragons", NpcID.KOUREND_BLUE_DRAGON, "Brutal blue dragon", "Brutal blue dragons"),
		new Variant("Red dragons", NpcID.KOUREND_RED_DRAGON, "Brutal red dragon", "Brutal red dragons")
	));

	private CatacombsVariants()
	{
	}

	/** Every variant in the table, in a fixed order. */
	static List<Variant> all()
	{
		return VARIANTS;
	}

	/** The task's variant ({@code taskName} matched by {@link TaskStatistics#normalize}), or {@code null} for none. */
	static Variant forTask(String taskName)
	{
		String key = TaskStatistics.normalize(taskName);
		if (key == null)
		{
			return null;
		}
		for (Variant variant : VARIANTS)
		{
			if (key.equals(TaskStatistics.normalize(variant.task)))
			{
				return variant;
			}
		}
		return null;
	}

	/** Whether {@code npcName} (matched by {@link TaskStatistics#normalize}) is a Catacombs variant's NPC name. */
	static boolean isVariantNpcName(String npcName)
	{
		String key = TaskStatistics.normalize(npcName);
		if (key == null)
		{
			return false;
		}
		for (Variant variant : VARIANTS)
		{
			if (key.equals(TaskStatistics.normalize(variant.npcName)))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The name to tally a dead NPC's kill under: its trimmed name, or {@code null} (not tallied) for a blank name or an
	 * NPC outside the Catacombs that has a variant's name (so it never counts as the variant).
	 */
	static String tallyName(int npcId, String npcName)
	{
		String key = TaskStatistics.normalize(npcName);
		if (key == null)
		{
			return null;
		}
		for (Variant variant : VARIANTS)
		{
			if (key.equals(TaskStatistics.normalize(variant.npcName)) && npcId != variant.npcId)
			{
				return null;
			}
		}
		return npcName.trim();
	}

	/**
	 * The variant the session's kills say {@code taskName} was done on ({@link Variant#getName}), or {@code null} for
	 * the standard monster: a task without a variant, no task kills, or the variant's tallied kills not more than half
	 * of the task kills.
	 *
	 * @param tally     the session's kills per NPC name ({@link NpcKillTally}), or {@code null} for none
	 * @param taskKills the session's task kills, as the game's task counter counted them
	 */
	static String decide(String taskName, List<NpcKills> tally, int taskKills)
	{
		Variant variant = forTask(taskName);
		if (variant == null || taskKills <= 0)
		{
			return null;
		}
		long variantKills = NpcKillTally.killsOf(tally, variant.npcName);
		return variantKills * 2 > taskKills ? variant.name : null;
	}

	/**
	 * Which records the live task's statistics use: {@link TaskSelection#ANY} while the kills don't decide (a task
	 * without a variant, or no task kills yet), else the version {@link #decide} gives for the same numbers.
	 */
	static TaskSelection selection(String taskName, List<NpcKills> tally, int taskKills)
	{
		if (forTask(taskName) == null || taskKills <= 0)
		{
			return TaskSelection.ANY;
		}
		return TaskSelection.of(decide(taskName, tally, taskKills));
	}
}

package com.shmayvan.slayerledger;

import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Text;

/**
 * Keeps charging and emptying the blowpipe or a trident out of the supplies diff, so materials aren't counted twice
 * ({@link ChargedWeaponUsage} already counts them per attack). Pure (RuneLite's static {@link Text} only): the plugin
 * passes in menu clicks and messages with the tick it saw them on, and asks before each supplies diff. Not
 * thread-safe.
 *
 * <p>Without it, the inventory diff would count darts loaded into the blowpipe and runes, coins or scales used to
 * charge a trident as used, and darts or runes coming back out (unloading, uncharging, swapping the dart type) would
 * reduce what was counted.</p>
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>A window opens on the tick the player clicks "Use" with one of the {@link #WEAPONS} involved (a material
 *     used on a weapon, or a weapon on a material), or "Unload" or "Uncharge" on a weapon.</li>
 *     <li>Only the {@link #MATERIALS} (darts, Zulrah's scales, death, chaos and fire runes, coins) are excluded while
 *     it is open; other items count as usual.</li>
 *     <li>It closes {@link #CONFIRM_GRACE_TICKS} ticks after a confirming message or dialog text
 *     ({@link #isConfirmation}), so items that only move on the next tick are still excluded, or
 *     {@link #TIMEOUT_TICKS} ticks after it opened, whichever is first. The timeout is long because charging a trident
 *     opens a number input that can stay open while the player decides, and some actions (unloading darts,
 *     uncharging the blowpipe) print no message. A new click re-opens the window from its tick.</li>
 * </ul>
 */
final class ChargeExclusions
{
	/** Ticks (30 seconds) a window stays open without a confirming message. */
	static final int TIMEOUT_TICKS = 50;
	/** Ticks a window stays open after the confirming message. */
	static final int CONFIRM_GRACE_TICKS = 2;
	/** Far enough in the past that no window includes it, without overflowing tick arithmetic. */
	static final int NEVER_TICK = Integer.MIN_VALUE / 2;

	/** Blowpipes (empty and loaded) and tridents (charged and uncharged), with their ornament and (e) versions. */
	static final Set<Integer> WEAPONS = ids(
		ItemID.TOXIC_BLOWPIPE, ItemID.TOXIC_BLOWPIPE_LOADED, ItemID.TOXIC_BLOWPIPE_ORNAMENT,
		ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT,
		ItemID.TOTS, ItemID.TOTS_CHARGED, ItemID.TOTS_UNCHARGED, ItemID.TOTS_I_CHARGED, ItemID.TOTS_I_UNCHARGED,
		ItemID.TOTS_ORN, ItemID.TOTS_CHARGED_ORN, ItemID.TOTS_UNCHARGED_ORN, ItemID.TOTS_I_CHARGED_ORN,
		ItemID.TOTS_I_UNCHARGED_ORN,
		ItemID.TOXIC_TOTS_CHARGED, ItemID.TOXIC_TOTS_UNCHARGED, ItemID.TOXIC_TOTS_I_CHARGED,
		ItemID.TOXIC_TOTS_I_UNCHARGED, ItemID.TOXIC_TOTS_CHARGED_ORN, ItemID.TOXIC_TOTS_UNCHARGED_ORN,
		ItemID.TOXIC_TOTS_I_CHARGED_ORN, ItemID.TOXIC_TOTS_I_UNCHARGED_ORN);

	/** What the weapons are charged or loaded with. */
	static final Set<Integer> MATERIALS = ids(
		ItemID.BRONZE_DART, ItemID.IRON_DART, ItemID.STEEL_DART, ItemID.BLACK_DART, ItemID.MITHRIL_DART,
		ItemID.ADAMANT_DART, ItemID.RUNE_DART, ItemID.AMETHYST_DART, ItemID.DRAGON_DART,
		ItemID.SNAKEBOSS_SCALE, ItemID.DEATHRUNE, ItemID.CHAOSRUNE, ItemID.FIRERUNE, ItemID.COINS);

	/**
	 * Messages and dialog texts (tags removed) that end a charge, load, unload or uncharge, as recorded by
	 * geheur/weapon-charges: the blowpipe check message (shown after adding darts or scales), a full or empty
	 * blowpipe, and the trident's charge dialogs.
	 */
	private static final Pattern[] CONFIRMATIONS = {
		Pattern.compile("^Darts: .*\\. Scales: .*\\.$"),
		Pattern.compile("^The blowpipe can't hold any more (?:darts|scales)\\.$"),
		Pattern.compile("^The blowpipe has no darts in it\\.$"),
		Pattern.compile("^You add (?:a charge|[\\d,]+ charges) to the weapon\\..*$"),
		Pattern.compile("^Your weapon is already fully charged\\.$"),
		Pattern.compile("^You uncharge your weapon\\.$"),
	};

	/** Tick the window opened. */
	private int openTick = NEVER_TICK;
	/** Last tick the window covers. */
	private int endTick = NEVER_TICK;

	private static Set<Integer> ids(int... ids)
	{
		final Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return Collections.unmodifiableSet(set);
	}

	/**
	 * A menu option was clicked on {@code tick}.
	 *
	 * @param option  the option text, possibly with tags ("Use", "Unload", "Uncharge")
	 * @param itemIds the items involved: the clicked item and, for "Use", the item used on it
	 */
	void menuOptionClicked(String option, int[] itemIds, int tick)
	{
		if (option == null || itemIds == null || !involvesWeapon(itemIds))
		{
			return;
		}
		switch (Text.removeTags(option).trim().toLowerCase(Locale.ROOT))
		{
			case "use":
			case "unload":
			case "uncharge":
				openTick = tick;
				endTick = tick + TIMEOUT_TICKS;
				break;
			default:
				break;
		}
	}

	private static boolean involvesWeapon(int[] itemIds)
	{
		for (int itemId : itemIds)
		{
			if (WEAPONS.contains(itemId))
			{
				return true;
			}
		}
		return false;
	}

	/** Whether a message or dialog text (possibly with tags) confirms a charge, load, unload or uncharge. */
	static boolean isConfirmation(String text)
	{
		if (text == null)
		{
			return false;
		}
		final String plain = Text.removeTags(text).trim();
		for (Pattern confirmation : CONFIRMATIONS)
		{
			if (confirmation.matcher(plain).matches())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A game message or dialog text was seen on {@code tick}; a confirmation closes an open window after
	 * {@link #CONFIRM_GRACE_TICKS} more ticks.
	 */
	void messageSeen(String text, int tick)
	{
		if (isOpen(tick) && isConfirmation(text))
		{
			endTick = Math.min(endTick, tick + CONFIRM_GRACE_TICKS);
		}
	}

	private boolean isOpen(int tick)
	{
		return tick >= openTick && tick <= endTick;
	}

	/** Whether a change of {@code itemId} on {@code tick} is left out of the supplies diff. */
	boolean isExcluded(int itemId, int tick)
	{
		return MATERIALS.contains(itemId) && isOpen(tick);
	}

	/** The item ids left out of the supplies diff on {@code tick} (empty if no window is open). */
	Set<Integer> excludedItems(int tick)
	{
		return isOpen(tick) ? MATERIALS : Collections.emptySet();
	}

	/** Forgets the window (login, hop, plugin start): the tick count is re-sent and may restart. */
	void reset()
	{
		openTick = NEVER_TICK;
		endTick = NEVER_TICK;
	}
}

package com.shmayvan.slayerledger;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpotanimID;

/**
 * Counts what the toxic blowpipe and the tridents use up, from attacks seen once per game tick. The client exposes
 * no live dart, scale or trident charge count, so (like established Hub plugins) this counts attacks by animation
 * and multiplies by the known per-attack cost. Pure: the plugin reads the local player and worn items on each
 * GameTick into a {@link Tick} and merges the items returned by {@link #update} into the session's supplies. Not
 * thread-safe; the plugin uses it on the client thread only.
 *
 * <p>Rules (rates from the OSRS Wiki, ids from the RuneLite 1.13.4 gameval constants):</p>
 * <ul>
 *     <li>An attack is the local player's attack animation at frame 0 while the matching weapon is worn. At most one
 *     attack counts per tick: a second {@link #update} for the same tick (or an earlier one) returns nothing.</li>
 *     <li><b>Blowpipe</b> ({@link #BLOWPIPES}, animation {@link #BLOWPIPE_ANIMATIONS}): each shot uses 2/3 of a
 *     Zulrah's scale, carried over in thirds, so three shots use two scales. Each shot also uses a fraction of a dart
 *     that depends on the worn cape-slot device (see {@link #dartLossHundredths}): none 1.00, Ava's attractor 0.40,
 *     accumulator 0.28, assembler 0.20, ranging or max cape 0.28 (0.20 with the Vorkath's head upgrade), Dizana's
 *     quiver 0.20 unless the plugin passes a verified quiver setting. Dart fractions carry over in hundredths, so 100
 *     shots with an assembler use exactly 20 darts.</li>
 *     <li>If the dart type is unknown (no check message seen yet) a shot counts its scales only, no dart fraction is
 *     carried, and {@link #isDartCheckNeeded()} turns on until a tick arrives with a known dart type. When the dart
 *     type changes, the dart carry-over is dropped: it belonged to the old darts.</li>
 *     <li><b>Tridents</b> ({@link #SEAS_TRIDENTS}, {@link #SWAMP_TRIDENTS}, charged versions only): a cast is a
 *     wave-staff animation ({@link #TRIDENT_ANIMATIONS}) at frame 0 while the plugin also sees a trident cast graphic
 *     ({@link #TRIDENT_GRAPHICS}); the animation alone is shared with ordinary wave spells. A cast uses one charge,
 *     valued at what recharging it costs: seas 1 death, 1 chaos, 5 fire runes and 10 coins; swamp 1 death, 1 chaos, 5
 *     fire runes and 1 Zulrah's scale.</li>
 * </ul>
 */
final class ChargedWeaponUsage
{
	/** No item (no dart type known, nothing worn). */
	static final int NO_ITEM = -1;

	/** Loaded toxic blowpipe and its blazing (ornament) version. */
	static final Set<Integer> BLOWPIPES = ids(ItemID.TOXIC_BLOWPIPE_LOADED, ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT);
	/** Blowpipe attack animations (regular and ornament). */
	static final Set<Integer> BLOWPIPE_ANIMATIONS = ids(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK,
		AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK_ORNAMENT);

	/** Charged tridents of the seas: regular (full and part charged), (e), and their (o) versions. */
	static final Set<Integer> SEAS_TRIDENTS = ids(ItemID.TOTS, ItemID.TOTS_CHARGED, ItemID.TOTS_I_CHARGED,
		ItemID.TOTS_ORN, ItemID.TOTS_CHARGED_ORN, ItemID.TOTS_I_CHARGED_ORN);
	/** Charged tridents of the swamp: regular, (e), and their (o) versions. */
	static final Set<Integer> SWAMP_TRIDENTS = ids(ItemID.TOXIC_TOTS_CHARGED, ItemID.TOXIC_TOTS_I_CHARGED,
		ItemID.TOXIC_TOTS_CHARGED_ORN, ItemID.TOXIC_TOTS_I_CHARGED_ORN);
	/** The wave-spell staff animations a trident cast plays (also used by ordinary wave spells). */
	static final Set<Integer> TRIDENT_ANIMATIONS = ids(AnimationID.HUMAN_CASTWAVE_STAFF,
		AnimationID.HUMAN_CASTWAVE_STAFF_WALKMERGE);
	/** Trident cast graphics (spotanims): seas, swamp, and their ornament versions. */
	static final Set<Integer> TRIDENT_GRAPHICS = ids(SpotanimID.SLAYER_TOTS_CASTING, SpotanimID.TOXIC_TOTS_CASTING,
		SpotanimID.SLAYER_TOTS_CASTING_ORN_LEAGUES6, SpotanimID.TOXIC_TOTS_CASTING_ORN_LEAGUES6);

	/** Ava's attractor: 40% of darts lost. */
	static final Set<Integer> ATTRACTORS = ids(ItemID.ANMA_30_REWARD);
	/** Ava's accumulator and the accumulator max cape: 28% lost. */
	static final Set<Integer> ACCUMULATORS = ids(ItemID.ANMA_50_REWARD, ItemID.SKILLCAPE_MAX_ANMA);
	/** Ava's assembler, the Masori assembler and their max capes, with the (l) versions: 20% lost. */
	static final Set<Integer> ASSEMBLERS = ids(ItemID.AVAS_ASSEMBLER, ItemID.AVAS_ASSEMBLER_TROUVER,
		ItemID.AVAS_ASSEMBLER_MASORI, ItemID.AVAS_ASSEMBLER_MASORI_TROUVER, ItemID.SKILLCAPE_MAX_ASSEMBLER,
		ItemID.SKILLCAPE_MAX_ASSEMBLER_TROUVER, ItemID.SKILLCAPE_MAX_ASSEMBLER_MASORI,
		ItemID.SKILLCAPE_MAX_ASSEMBLER_MASORI_TROUVER);
	/** The ranging cape, ranging cape(t) and max cape: 28% lost, or 20% with the Vorkath's head upgrade. */
	static final Set<Integer> RANGING_CAPES = ids(ItemID.SKILLCAPE_RANGING, ItemID.SKILLCAPE_RANGING_TRIMMED,
		ItemID.SKILLCAPE_MAX, ItemID.SKILLCAPE_MAX_WORN);
	/** Dizana's quiver (charged, uncharged and blessed) and Dizana's max cape, with the (l) versions. */
	static final Set<Integer> QUIVERS = ids(ItemID.DIZANAS_QUIVER_CHARGED, ItemID.DIZANAS_QUIVER_CHARGED_TROUVER,
		ItemID.DIZANAS_QUIVER_UNCHARGED, ItemID.DIZANAS_QUIVER_UNCHARGED_TROUVER, ItemID.DIZANAS_QUIVER_INFINITE,
		ItemID.DIZANAS_QUIVER_INFINITE_TROUVER, ItemID.SKILLCAPE_MAX_DIZANAS, ItemID.SKILLCAPE_MAX_DIZANAS_TROUVER);

	/** Hundredths of a dart lost per shot with no device. */
	static final int NO_DEVICE_HUNDREDTHS = 100;
	static final int ATTRACTOR_HUNDREDTHS = 40;
	static final int ACCUMULATOR_HUNDREDTHS = 28;
	static final int ASSEMBLER_HUNDREDTHS = 20;

	/** Thirds of a Zulrah's scale used per blowpipe shot. */
	static final int SCALE_THIRDS_PER_SHOT = 2;

	static final int FIRE_RUNES_PER_CAST = 5;
	static final int COINS_PER_SEAS_CAST = 10;

	/** Last tick handled; a second update for it (or an earlier tick) counts nothing. */
	private int lastTick = Integer.MIN_VALUE;
	/** Dart hundredths used but not yet reported as a whole dart, for {@link #carryDartId}. */
	private int dartHundredths;
	/** The dart type {@link #dartHundredths} belongs to. */
	private int carryDartId = NO_ITEM;
	/** Scale thirds used but not yet reported as a whole scale. */
	private int scaleThirds;
	private boolean dartCheckNeeded;

	/**
	 * What the plugin reads on one game tick. Ids are {@link #NO_ITEM} (or any non-matching id) when nothing is worn.
	 */
	@Value
	@Builder
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static class Tick
	{
		/** The client's tick count. */
		int tick;
		/** Worn weapon item id. */
		@Builder.Default
		int weaponId = NO_ITEM;
		/** The local player's animation id (-1 for none). */
		@Builder.Default
		int animationId = -1;
		/** The local player's animation frame. */
		int animationFrame;
		/** Worn cape-slot item id (Ava's devices, ranging and max capes, Dizana's quiver). */
		@Builder.Default
		int capeId = NO_ITEM;
		/**
		 * Dizana's quiver ammo-saving setting, from varbit {@code DIZANAS_QUIVER_AMMO_SAVE} (9803), or {@code null} to
		 * ignore it and assume the quiver saves 80%. Its mapping is unverified (see {@link #quiverLossHundredths}), so
		 * the plugin should pass {@code null} until it has been checked in game.
		 */
		Integer quiverAmmoSave;
		/** Whether a trident cast graphic ({@link #TRIDENT_GRAPHICS}) is on the local player this tick. */
		boolean tridentGraphic;
		/** The "Ranging/max cape has Vorkath's head upgrade" setting. */
		boolean vorkathsHeadUpgrade;
		/** The blowpipe's dart item id from the last check message, or {@link #NO_ITEM} if unknown. */
		@Builder.Default
		int dartId = NO_ITEM;
	}

	private static Set<Integer> ids(int... ids)
	{
		final Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return Collections.unmodifiableSet(set);
	}

	/**
	 * Hundredths of a dart lost per blowpipe shot with {@code capeId} worn.
	 *
	 * @param quiverAmmoSave      Dizana's quiver setting, or {@code null} to assume 80% saved
	 * @param vorkathsHeadUpgrade whether a ranging or max cape has the Vorkath's head upgrade (80% instead of 72%)
	 */
	static int dartLossHundredths(int capeId, Integer quiverAmmoSave, boolean vorkathsHeadUpgrade)
	{
		if (ASSEMBLERS.contains(capeId))
		{
			return ASSEMBLER_HUNDREDTHS;
		}
		if (ACCUMULATORS.contains(capeId))
		{
			return ACCUMULATOR_HUNDREDTHS;
		}
		if (ATTRACTORS.contains(capeId))
		{
			return ATTRACTOR_HUNDREDTHS;
		}
		if (RANGING_CAPES.contains(capeId))
		{
			return vorkathsHeadUpgrade ? ASSEMBLER_HUNDREDTHS : ACCUMULATOR_HUNDREDTHS;
		}
		if (QUIVERS.contains(capeId))
		{
			return quiverLossHundredths(quiverAmmoSave);
		}
		return NO_DEVICE_HUNDREDTHS;
	}

	/**
	 * Hundredths of a dart lost per shot with Dizana's quiver. The quiver can be set to save 80%, 72% or 60%. UNVERIFIED
	 * mapping, taken from the order geheur/weapon-charges offers (0 = 80%, 1 = 72%, 2 = 60%); any other value, and
	 * {@code null}, is treated as 80%. Needs an in-game check of varbit 9803 before the plugin relies on it.
	 */
	static int quiverLossHundredths(Integer quiverAmmoSave)
	{
		if (quiverAmmoSave == null)
		{
			return ASSEMBLER_HUNDREDTHS;
		}
		switch (quiverAmmoSave)
		{
			case 1:
				return ACCUMULATOR_HUNDREDTHS;
			case 2:
				return ATTRACTOR_HUNDREDTHS;
			default:
				return ASSEMBLER_HUNDREDTHS;
		}
	}

	/**
	 * Handles one game tick and returns the items used by an attack on it (item id to quantity, only whole items; empty
	 * if none). Call once per tick, in tick order.
	 */
	Map<Integer, Integer> update(Tick tick)
	{
		if (tick.getTick() <= lastTick)
		{
			return Collections.emptyMap();
		}
		lastTick = tick.getTick();

		final int dartId = tick.getDartId();
		if (dartId != NO_ITEM)
		{
			dartCheckNeeded = false;
		}
		if (dartId != carryDartId)
		{
			dartHundredths = 0;
			carryDartId = dartId;
		}

		if (tick.getAnimationFrame() != 0)
		{
			return Collections.emptyMap();
		}
		final int weaponId = tick.getWeaponId();
		final int animationId = tick.getAnimationId();
		final Map<Integer, Integer> used = new HashMap<>();
		if (BLOWPIPES.contains(weaponId) && BLOWPIPE_ANIMATIONS.contains(animationId))
		{
			blowpipeShot(tick, used);
		}
		else if (tick.isTridentGraphic() && TRIDENT_ANIMATIONS.contains(animationId))
		{
			if (SEAS_TRIDENTS.contains(weaponId))
			{
				tridentCast(used);
				add(used, ItemID.COINS, COINS_PER_SEAS_CAST);
			}
			else if (SWAMP_TRIDENTS.contains(weaponId))
			{
				tridentCast(used);
				add(used, ItemID.SNAKEBOSS_SCALE, 1);
			}
		}
		return used;
	}

	private void blowpipeShot(Tick tick, Map<Integer, Integer> used)
	{
		scaleThirds += SCALE_THIRDS_PER_SHOT;
		add(used, ItemID.SNAKEBOSS_SCALE, scaleThirds / 3);
		scaleThirds %= 3;

		if (tick.getDartId() == NO_ITEM)
		{
			dartCheckNeeded = true;
			return;
		}
		dartHundredths += dartLossHundredths(tick.getCapeId(), tick.getQuiverAmmoSave(), tick.isVorkathsHeadUpgrade());
		add(used, tick.getDartId(), dartHundredths / 100);
		dartHundredths %= 100;
	}

	private static void tridentCast(Map<Integer, Integer> used)
	{
		add(used, ItemID.DEATHRUNE, 1);
		add(used, ItemID.CHAOSRUNE, 1);
		add(used, ItemID.FIRERUNE, FIRE_RUNES_PER_CAST);
	}

	private static void add(Map<Integer, Integer> used, int itemId, int quantity)
	{
		if (quantity > 0)
		{
			used.merge(itemId, quantity, Integer::sum);
		}
	}

	/**
	 * Whether a blowpipe shot was counted without a known dart type (scales only) and no dart type has been known since.
	 * The panel can show "Check your blowpipe".
	 */
	boolean isDartCheckNeeded()
	{
		return dartCheckNeeded;
	}

	/**
	 * Forgets the fractional carry-overs, the hint and the last tick (session start or end, login, hop, plugin start:
	 * the tick count may restart).
	 */
	void reset()
	{
		lastTick = Integer.MIN_VALUE;
		dartHundredths = 0;
		carryDartId = NO_ITEM;
		scaleThirds = 0;
		dartCheckNeeded = false;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * The plugin's client-thread lookup services: today's GE prices for the history ({@link PriceRetry} included),
 * item names for the panel's item lists, and the player's names for map regions, with their caches; plus the
 * {@code ItemManager} adapters the plugin prices and filters loot with.
 *
 * <p>Threading is the plugin's: the {@code request...} methods are called on the EDT (by the {@link LedgerHistoryModel}'s
 * callbacks) and only queue one client-thread task each; {@code ItemManager} and {@code ConfigManager} are only read on
 * the client thread; answers go to the history model on the EDT ({@link SwingUtilities#invokeLater}). Everything else is
 * client thread only. The caches live as long as the plugin instance and are cleared by {@link #reset()}, which the
 * plugin calls in its startUp client-thread block.
 *
 * <p>Injected by Guice into the plugin, as RuneLite plugins inject their overlays and helpers.
 */
@Slf4j
class ClientLookups
{
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final ConfigManager configManager;

	/** Added to a noted item's name in the panel's item names ({@link #requestItemNames}). */
	static final String NOTED_SUFFIX = " (noted)";

	/** The plugin's current history model (or {@code null} while stopped), read when an answer is ready. */
	private volatile Supplier<LedgerHistoryModel> historyModel = () -> null;

	/**
	 * Today's GE unit prices the history is valued at, by item id as tallied, looked up at most once per item
	 * while the plugin runs (unavailable prices are not kept, so they are tried again). Client thread only.
	 */
	private final Map<Integer, Long> currentGePrices = new HashMap<>();
	/** When to look up again the today's prices that were unavailable. Client thread only. */
	private final PriceRetry currentPriceRetry = new PriceRetry();
	/**
	 * Whether {@code ItemManager} has returned a positive GE price in this run of the plugin, so its price list is
	 * loaded (it loads all prices at once). Until then a tradeable item at 0 may only be waiting for the list, and the
	 * history waits for it to be looked up again; afterwards it is really unpriced. Coins and platinum tokens don't
	 * count: their values are fixed. Client thread only; cleared by {@link #reset()}.
	 */
	private boolean priceListSeen;
	/**
	 * Item names for the panel's item lists, by item id, looked up at most once per item while the plugin runs (a
	 * failed lookup is not kept). Client thread only.
	 */
	private final Map<Integer, String> itemNames = new HashMap<>();
	/**
	 * The player's region names read from (or saved to) the RSProfile config
	 * ({@link SlayerLedgerPlugin#LOCATION_NAME_KEY_PREFIX}), by region id; only named regions. Kept until another
	 * account logs in or another RuneScape profile is active, so a session saved while logging out (when the config has
	 * no profile) still gets its name. Client thread only.
	 */
	private final Map<Integer, String> locationNames = new HashMap<>();

	/**
	 * Client thread only. Prices items the way core LootTrackerPlugin does (1.13.3): GE via
	 * {@link ItemManager#getItemPrice} (which already un-notes, values coins at 1 and untradeables at 0) and high
	 * alchemy via {@code ItemComposition#getHaPrice()}. Ids are canonicalized first so noted items use the unnoted
	 * item's high-alchemy value too.
	 */
	private final ItemValuation.PriceLookup priceLookup = new ItemValuation.PriceLookup()
	{
		@Override
		public int canonicalize(int itemId)
		{
			return itemManager.canonicalize(itemId);
		}

		@Override
		public long gePrice(int canonicalId)
		{
			final long price = itemManager.getItemPrice(canonicalId);
			if (price > 0)
			{
				priceListSeen = true;
			}
			return price;
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return itemManager.getItemComposition(canonicalId).getHaPrice();
		}

		/**
		 * ItemManager (1.13.3) has no "prices loaded" flag: getItemPrice returns 0 both before its price list is
		 * fetched and for an item missing from it. A tradeable item at 0 is therefore an unavailable price, see
		 * {@link ItemValuation}.
		 */
		@Override
		public boolean isTradeable(int canonicalId)
		{
			return itemManager.getItemComposition(canonicalId).isTradeable();
		}
	};

	/** Client thread. Item facts for {@link LootFilter}, from the item compositions. */
	private final LootFilter.ItemNames lootItemNames = new LootFilter.ItemNames()
	{
		@Override
		public int unnoted(int itemId)
		{
			final ItemComposition comp = itemManager.getItemComposition(itemId);
			return comp.getNote() != -1 ? comp.getLinkedNoteId() : itemId;
		}

		@Override
		public String name(int itemId)
		{
			return itemManager.getItemComposition(itemId).getName();
		}
	};

	@Inject
	ClientLookups(ClientThread clientThread, ItemManager itemManager, ConfigManager configManager)
	{
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.configManager = configManager;
	}

	/** Where answers go: the plugin's current history model, or {@code null} while it has none. Any thread. */
	void setHistoryModelSource(Supplier<LedgerHistoryModel> source)
	{
		historyModel = source;
	}

	/** The {@code ItemManager} price lookup for saved records, live values and notable drops; client thread. */
	ItemValuation.PriceLookup priceLookup()
	{
		return priceLookup;
	}

	/** The {@code ItemManager} item facts for {@link LootFilter} and notable-drop names; client thread. */
	LootFilter.ItemNames lootItemNames()
	{
		return lootItemNames;
	}

	/**
	 * Client thread, in the plugin's startUp block. Today's prices are looked up afresh in each run of the plugin, and
	 * so are item and location names.
	 */
	void reset()
	{
		currentGePrices.clear();
		currentPriceRetry.clear();
		priceListSeen = false;
		itemNames.clear();
		locationNames.clear();
	}

	/**
	 * EDT. Looks up today's GE price of {@code ids} (item ids as tallied) to value the history at, in one
	 * client-thread task, and sends the available ones to the history model on the EDT. Items already priced this run
	 * are not looked up again.
	 */
	void requestCurrentPrices(Set<Integer> ids)
	{
		final Set<Integer> requested = new TreeSet<>(ids);
		clientThread.invoke(() -> lookUpCurrentPrices(requested));
	}

	/**
	 * Client thread. Prices the items of {@code requested} not cached yet through {@code ItemManager} (the same rules
	 * as saved records, see {@link ItemValuation}) and always answers the history model; a price that is unavailable
	 * (for example not loaded yet) is left out, so the history marks it with {@code ~}, and is tried again a few times
	 * on later ticks ({@link PriceRetry}, {@link #retryCurrentPrices}) and on a later request. Until RuneLite's price
	 * list is seen loaded ({@link #priceListSeen}), the model is told which ids are tried again, so a history waiting
	 * for its prices waits for those too (within its time limit); once it is loaded, a missing price is really
	 * unavailable and holds nothing back.
	 */
	private void lookUpCurrentPrices(Set<Integer> requested)
	{
		final Map<Integer, Long> prices = priceCurrent(requested);
		final Set<Integer> missing = new TreeSet<>(requested);
		missing.removeAll(prices.keySet());
		currentPriceRetry.found(prices.keySet());
		currentPriceRetry.missed(missing);
		final Set<Integer> retrying = priceListSeen ? Collections.emptySet() : missing;
		final LedgerHistoryModel m = historyModel.get();
		if (m != null)
		{
			SwingUtilities.invokeLater(() -> m.addCurrentPrices(requested, prices, retrying));
		}
	}

	/**
	 * Client thread, on each game tick. Looks up again the today's prices that came back unavailable, when
	 * {@link PriceRetry} says one is due, and sends the history model the ones found now (nothing when none was found,
	 * so the history is not redrawn for nothing). The model never asked for these, so it is not waiting for them.
	 */
	void retryCurrentPrices()
	{
		final Set<Integer> due = currentPriceRetry.tick();
		if (due.isEmpty())
		{
			return;
		}
		final Map<Integer, Long> prices = priceCurrent(due);
		currentPriceRetry.found(prices.keySet());
		final LedgerHistoryModel m = historyModel.get();
		if (m != null && !prices.isEmpty())
		{
			final Set<Integer> found = new TreeSet<>(prices.keySet());
			SwingUtilities.invokeLater(() -> m.addCurrentPrices(found, prices));
		}
	}

	/**
	 * Client thread. Today's GE prices of the ids of {@code ids} that have one, looking up those not cached yet and
	 * caching the available ones for the plugin's run.
	 */
	private Map<Integer, Long> priceCurrent(Set<Integer> ids)
	{
		final ItemValuation.UnitPrices looked = new ItemValuation.UnitPrices();
		for (int id : ids)
		{
			if (!currentGePrices.containsKey(id))
			{
				ItemValuation.capturePrice(id, priceLookup, looked);
			}
		}
		currentGePrices.putAll(looked.getGe());
		final Map<Integer, Long> prices = new TreeMap<>();
		for (int id : ids)
		{
			final Long price = currentGePrices.get(id);
			if (price != null)
			{
				prices.put(id, price);
			}
		}
		return prices;
	}

	/**
	 * EDT. Looks up the names of {@code ids} (item ids as tallied) for the panel's item lists, in one client-thread
	 * task, and sends them to the history model on the EDT. Names are never looked up on the EDT.
	 */
	void requestItemNames(Set<Integer> ids)
	{
		final Set<Integer> requested = new TreeSet<>(ids);
		clientThread.invoke(() -> lookUpItemNames(requested));
	}

	/**
	 * Client thread. Names the items of {@code requested} through {@code ItemManager}, caching them for the plugin's
	 * run; a noted item is named "&lt;name&gt; (noted)". An item whose lookup fails is left out (the panel shows its
	 * id).
	 */
	private void lookUpItemNames(Set<Integer> requested)
	{
		final Map<Integer, String> names = new TreeMap<>();
		for (int id : requested)
		{
			String name = itemNames.get(id);
			if (name == null)
			{
				name = lookUpItemName(id);
				if (name != null)
				{
					itemNames.put(id, name);
				}
			}
			if (name != null)
			{
				names.put(id, name);
			}
		}
		final LedgerHistoryModel m = historyModel.get();
		if (m != null)
		{
			// The alch hint subtracts the nature rune a cast uses; 0 means its price is unavailable.
			final long natureRunePrice = itemManager.getItemPrice(ItemID.NATURERUNE);
			final Long natureRune = natureRunePrice > 0 ? natureRunePrice : null;
			SwingUtilities.invokeLater(() -> m.addItemNames(requested, names, natureRune));
		}
	}

	/** Client thread. One item's name, or {@code null} when it has none or the lookup fails. */
	private String lookUpItemName(int itemId)
	{
		try
		{
			final ItemComposition comp = itemManager.getItemComposition(itemId);
			final String name = comp.getName();
			if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name.trim()))
			{
				return null;
			}
			return comp.getNote() != -1 ? name + NOTED_SUFFIX : name;
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to look up the name of item {}", itemId, e);
			return null;
		}
	}

	/**
	 * Client thread. The player's name for map region {@code region} in the active RuneScape profile, or {@code null}
	 * when it has none.
	 */
	String locationName(int region)
	{
		final String known = locationNames.get(region);
		if (known != null || !LocationTally.isRegion(region))
		{
			return known;
		}
		final String saved = TaskLocation.normalizeName(configManager.getRSProfileConfiguration(
			SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX + region));
		if (saved != null)
		{
			locationNames.put(region, saved);
		}
		return saved;
	}

	/**
	 * EDT. Looks up the player's names for {@code regions} in one client-thread task and sends them to the history
	 * model on the EDT; a region without a name is left out.
	 */
	void requestLocationNames(Set<Integer> regions)
	{
		final Set<Integer> requested = new TreeSet<>(regions);
		clientThread.invoke(() ->
		{
			final Map<Integer, String> names = new TreeMap<>();
			for (int region : requested)
			{
				final String name = locationName(region);
				if (name != null)
				{
					names.put(region, name);
				}
			}
			final LedgerHistoryModel m = historyModel.get();
			if (m != null)
			{
				SwingUtilities.invokeLater(() -> m.addLocationNames(requested, names));
			}
		});
	}

	/**
	 * Client thread. Saves {@code normalized} as the player's name for {@code region} in the RSProfile config and the
	 * cache. The config is written first: the write may create the profile, and the profile change it posts clears the
	 * cache.
	 */
	void saveLocationName(int region, String normalized)
	{
		configManager.setRSProfileConfiguration(SlayerLedgerConfig.GROUP,
			SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX + region, normalized);
		locationNames.put(region, normalized);
	}

	/**
	 * Client thread. Whether the player chose Skip for map region {@code region}'s name in the active RuneScape profile
	 *; {@code false} without a profile.
	 */
	boolean isLocationSkipped(int region)
	{
		return LocationTally.isRegion(region) && Boolean.parseBoolean(configManager.getRSProfileConfiguration(
			SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.LOCATION_SKIP_KEY_PREFIX + region));
	}

	/**
	 * Client thread. Keeps the player's Skip for {@code region} in the active RuneScape profile's config, so it is not
	 * asked about again after a restart. The write may create the profile, as for {@link #saveLocationName}.
	 */
	void saveLocationSkip(int region)
	{
		configManager.setRSProfileConfiguration(SlayerLedgerConfig.GROUP,
			SlayerLedgerPlugin.LOCATION_SKIP_KEY_PREFIX + region, true);
	}

	/**
	 * Client thread. Removes every skipped region from the active RuneScape profile's config.
	 *
	 * @return whether there was a profile to clear
	 */
	boolean clearLocationSkips()
	{
		final String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return false;
		}
		final List<String> keys = configManager.getRSProfileConfigurationKeys(SlayerLedgerConfig.GROUP, profile,
			SlayerLedgerPlugin.LOCATION_SKIP_KEY_PREFIX);
		if (keys != null)
		{
			for (String key : keys)
			{
				configManager.unsetRSProfileConfiguration(SlayerLedgerConfig.GROUP, key);
			}
		}
		return true;
	}

	/** Client thread. Another account or RuneScape profile is active: its region names are read afresh. */
	void forgetLocationNames()
	{
		locationNames.clear();
	}

	/**
	 * Client thread. Every name the player gave a region in the active RuneScape profile (the prompt suggests them, as
	 * a place can span several regions); empty without a profile.
	 */
	List<String> profileLocationNames()
	{
		final String prefix = SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX;
		final List<String> names = new ArrayList<>();
		final List<String> keys = configManager.getRSProfileConfigurationKeys(SlayerLedgerConfig.GROUP,
			configManager.getRSProfileKey(), prefix);
		if (keys == null)
		{
			return names;
		}
		for (String key : keys)
		{
			try
			{
				final String name = locationName(Integer.parseInt(key.substring(prefix.length())));
				if (name != null)
				{
					names.add(name);
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Ignoring a location name key that is not a region: {}", key);
			}
		}
		return names;
	}
}

package com.shmayvan.slayerledger;

import java.awt.Dimension;
import java.awt.Insets;
import java.awt.Point;
import javax.accessibility.Accessible;
import javax.swing.JComboBox;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import javax.swing.event.PopupMenuEvent;
import javax.swing.event.PopupMenuListener;
import javax.swing.plaf.basic.BasicComboPopup;

/**
 * Widens a drop-down's open list to fit its longest choice, up to a maximum, while the closed box keeps its own
 * (prototype) width, so a narrow box in the sidebar still shows long names in full when opened. The list is never
 * narrower than the box, and keeps its right edge on the box's (the sidebar is on the right of the client). EDT only.
 *
 * <p>The look and feel sizes the open list from the box's display size (its prototype) as it opens, so the list is
 * widened just after it is shown, and shown again at its new size.</p>
 */
final class ComboPopupWidener implements PopupMenuListener
{
	/** The widest the open list gets, in pixels: a 40-character location name and a scroll bar fit. */
	static final int MAX_WIDTH = 320;

	private final int maxWidth;

	private ComboPopupWidener(int maxWidth)
	{
		this.maxWidth = maxWidth;
	}

	/** Makes {@code box}'s open list fit its longest choice, at most {@code maxWidth} pixels wide. */
	static void install(JComboBox<?> box, int maxWidth)
	{
		box.addPopupMenuListener(new ComboPopupWidener(maxWidth));
	}

	/**
	 * The open list's width: its content's, at most {@code maxWidth}, and never narrower than {@code boxWidth} (the
	 * width the look and feel gives it).
	 */
	static int width(int boxWidth, int contentWidth, int maxWidth)
	{
		return Math.max(boxWidth, Math.min(contentWidth, maxWidth));
	}

	/** The scroll pane holding {@code box}'s open list, or {@code null} when its look and feel has no such list. */
	static JScrollPane listScroller(JComboBox<?> box)
	{
		BasicComboPopup popup = popup(box);
		return popup == null ? null
			: (JScrollPane) SwingUtilities.getAncestorOfClass(JScrollPane.class, popup.getList());
	}

	private static BasicComboPopup popup(JComboBox<?> box)
	{
		if (box.getUI() == null)
		{
			return null;
		}
		Accessible child = box.getUI().getAccessibleChild(box, 0);
		return child instanceof BasicComboPopup ? (BasicComboPopup) child : null;
	}

	@Override
	public void popupMenuWillBecomeVisible(PopupMenuEvent event)
	{
		JComboBox<?> box = (JComboBox<?>) event.getSource();
		// The look and feel sizes the list to the box as it opens: widen it once it is up.
		SwingUtilities.invokeLater(() -> widen(box));
	}

	@Override
	public void popupMenuWillBecomeInvisible(PopupMenuEvent event)
	{
	}

	@Override
	public void popupMenuCanceled(PopupMenuEvent event)
	{
	}

	/**
	 * Widens {@code box}'s open list to fit its choices ({@link #width}); while it is shown, shows it again at its new
	 * size, moved left so its right edge stays where it was.
	 */
	void widen(JComboBox<?> box)
	{
		BasicComboPopup popup = popup(box);
		JScrollPane scroller = listScroller(box);
		if (popup == null || scroller == null)
		{
			return;
		}
		Insets popupInsets = popup.getInsets();
		Insets scrollerInsets = scroller.getInsets();
		int boxWidth = Math.max(box.getWidth() - popupInsets.left - popupInsets.right, scroller.getWidth());
		int content = popup.getList().getPreferredSize().width + scrollerInsets.left + scrollerInsets.right;
		if (box.getItemCount() > box.getMaximumRowCount())
		{
			content += scroller.getVerticalScrollBar().getPreferredSize().width;
		}
		int wanted = width(boxWidth, content, maxWidth);
		Dimension size = scroller.getPreferredSize();
		if (wanted == size.width)
		{
			return;
		}
		Dimension wider = new Dimension(wanted, size.height);
		scroller.setPreferredSize(wider);
		scroller.setMaximumSize(wider);
		scroller.setMinimumSize(wider);
		if (popup.isShowing())
		{
			Point at = popup.getLocationOnScreen();
			int grown = wanted - scroller.getWidth();
			// Moving a shown list shows it again, at its new size; pack() covers the case it doesn't move.
			popup.setLocation(at.x - grown, at.y);
			popup.pack();
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.Arrays;

/**
 * Detects a Slayer task completion from the game's task-completion counters (regular, Wilderness and Mortimer
 * streaks). A completion increments one counter by exactly one. To avoid mistaking a login resync for a completion:
 * <ul>
 *     <li>the first reading after {@link #reset()} only sets the baseline;</li>
 *     <li>an increase of more than one in any counter is treated as a resync, not a completion;</li>
 *     <li>decreases (for example a streak reset) are never completions.</li>
 * </ul>
 * Not thread-safe; used on the client thread only.
 */
final class CompletionSignal
{
	/** No single counter went up by one in the last reading; see {@link #incrementedCounter()}. */
	static final int NO_COUNTER = -1;

	private int[] last;
	private int incremented = NO_COUNTER;

	/** Forget the baseline, e.g. after logout, world hop or connection loss. */
	void reset()
	{
		last = null;
		incremented = NO_COUNTER;
	}

	/**
	 * Index of the counter whose increase made the last {@link #update} a completion (the streak that completion
	 * raised), or {@link #NO_COUNTER} when the last update was not a completion or more than one counter went up.
	 */
	int incrementedCounter()
	{
		return incremented;
	}

	/**
	 * @param counters current counter values (the same order every call)
	 * @return whether this reading signals a task completion
	 */
	boolean update(int... counters)
	{
		int[] previous = last;
		last = Arrays.copyOf(counters, counters.length);
		incremented = NO_COUNTER;
		if (previous == null || previous.length != counters.length)
		{
			return false;
		}
		int raised = NO_COUNTER;
		int raisedCount = 0;
		for (int i = 0; i < counters.length; i++)
		{
			int delta = counters[i] - previous[i];
			if (delta > 1)
			{
				return false;
			}
			if (delta == 1)
			{
				raised = i;
				raisedCount++;
			}
		}
		if (raisedCount == 0)
		{
			return false;
		}
		incremented = raisedCount == 1 ? raised : NO_COUNTER;
		return true;
	}
}

package com.shmayvan.slayerledger;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * Leaves out of kill loot the items a bonecrusher or ash sanctifier destroys. The game's NPC loot (ServerNpcLoot)
 * still lists bones that a bonecrusher crushed (seen in game: 39 wyrm bones for 39 wyrm kills with a bonecrusher),
 * so the plugin filters them itself. Pure: the plugin reads the inventory and worn items at each loot drop, on the
 * client thread, and passes the item ids in; nothing here touches the client.
 *
 * <p>Detection is per loot drop, because the player may take the crusher off or put it in the bank mid-task. In
 * {@link BonecrusherMode#AUTO} a bonecrusher or bonecrusher necklace anywhere in the inventory or worn excludes the
 * {@link #BONES}, and an ash sanctifier excludes the {@link #DEMONIC_ASHES}. Charges are not checked: the charge
 * varbits are not read by any core plugin, so whether the client always has them is unknown, and a wrong reading would
 * count crushed bones. Auto therefore assumes the item is charged; {@link BonecrusherMode#NEVER_EXCLUDE} covers an
 * uncharged one.</p>
 *
 * <p>Item ids are the RuneLite 1.13.4 {@code net.runelite.api.gameval.ItemID} constants. Only unnoted ids are listed:
 * the crushers do not crush noted bones.</p>
 */
final class CrushedLootFilter
{
	/** The bonecrusher (inventory) and the bonecrusher necklace (inventory or worn). */
	static final Set<Integer> BONECRUSHERS = ids(ItemID.BONECRUSHER, ItemID.BONECRUSHER_NECKLACE);
	static final Set<Integer> ASH_SANCTIFIERS = ids(ItemID.ASH_SANCTIFIER);

	/**
	 * Buryable bones that monsters drop, which a bonecrusher crushes. Bones only obtained otherwise (blessed bones, quest
	 * and minigame bones) are not listed; they are not kill loot.
	 */
	static final Set<Integer> BONES = ids(
		ItemID.BONES, ItemID.BAT_BONES, ItemID.BIG_BONES, ItemID.BABYDRAGON_BONES, ItemID.DRAGON_BONES,
		ItemID.WOLF_BONES, ItemID.TBWT_BEAST_BONES, ItemID.TBWT_JOGRE_BONES,
		ItemID.MM_SMALL_NINJA_MONKEY_BONES, ItemID.MM_MEDIUM_NINJA_MONKEY_BONES, ItemID.MM_NORMAL_GORILLA_MONKEY_BONES,
		ItemID.MM_BEARDED_GORILLA_MONKEY_BONES, ItemID.MM_NORMAL_MONKEY_BONES, ItemID.MM_SMALL_ZOMBIE_MONKEY_BONES,
		ItemID.MM_LARGE_ZOMBIE_MONKEY_BONES,
		ItemID.ZOGRE_BONES, ItemID.ZOGRE_ANCESTRAL_BONES_FAYG, ItemID.ZOGRE_ANCESTRAL_BONES_RAURG,
		ItemID.ZOGRE_ANCESTRAL_BONES_OURG, ItemID.DAGANNOTH_KING_BONES, ItemID.WYVERN_BONES, ItemID.LAVA_DRAGON_BONES,
		ItemID.DRAGON_BONES_SUPERIOR, ItemID.WYRM_BONES, ItemID.DRAKE_BONES, ItemID.HYDRA_BONES,
		ItemID.BABYWYRM_BONES, ItemID.STRYKEWYRM_BONES, ItemID.FROST_DRAGON_BONES);

	/** Demonic ashes, which an ash sanctifier scatters. Plain ashes are not demonic and are always kept. */
	static final Set<Integer> DEMONIC_ASHES = ids(
		ItemID.FIENDISH_ASHES, ItemID.VILE_ASHES, ItemID.MALICIOUS_ASHES, ItemID.ABYSSAL_ASHES, ItemID.INFERNAL_ASHES);

	/** Keeps everything. */
	static final CrushedLootFilter KEEP_ALL = new CrushedLootFilter(false, false);

	private final boolean excludeBones;
	private final boolean excludeAshes;

	private CrushedLootFilter(boolean excludeBones, boolean excludeAshes)
	{
		this.excludeBones = excludeBones;
		this.excludeAshes = excludeAshes;
	}

	/**
	 * The filter for one loot drop.
	 *
	 * @param mode           the player's "Bonecrusher handling" setting ({@code null} is treated as AUTO)
	 * @param carriedItemIds ids of every item in the inventory and worn at the time of the drop; only used in AUTO
	 */
	static CrushedLootFilter forDrop(BonecrusherMode mode, Iterable<Integer> carriedItemIds)
	{
		if (mode == BonecrusherMode.NEVER_EXCLUDE)
		{
			return KEEP_ALL;
		}
		if (mode == BonecrusherMode.ALWAYS_EXCLUDE)
		{
			return new CrushedLootFilter(true, true);
		}
		boolean crusher = false;
		boolean sanctifier = false;
		if (carriedItemIds != null)
		{
			for (Integer id : carriedItemIds)
			{
				crusher |= id != null && BONECRUSHERS.contains(id);
				sanctifier |= id != null && ASH_SANCTIFIERS.contains(id);
			}
		}
		return crusher || sanctifier ? new CrushedLootFilter(crusher, sanctifier) : KEEP_ALL;
	}

	/** Whether the mode needs the carried items at all (only AUTO does). */
	static boolean needsCarriedItems(BonecrusherMode mode)
	{
		return mode != BonecrusherMode.NEVER_EXCLUDE && mode != BonecrusherMode.ALWAYS_EXCLUDE;
	}

	/** Whether {@code itemId} counts as loot under this filter. */
	boolean keeps(int itemId)
	{
		return !(excludeBones && BONES.contains(itemId)) && !(excludeAshes && DEMONIC_ASHES.contains(itemId));
	}

	boolean excludesBones()
	{
		return excludeBones;
	}

	boolean excludesAshes()
	{
		return excludeAshes;
	}

	/** A copy of {@code loot} without the items this filter leaves out. */
	ItemTally apply(ItemTally loot)
	{
		ItemTally kept = new ItemTally();
		if (loot != null)
		{
			for (int id : loot.itemIds())
			{
				if (keeps(id))
				{
					kept.add(id, loot.get(id));
				}
			}
		}
		return kept;
	}

	private static Set<Integer> ids(Integer... ids)
	{
		return Collections.unmodifiableSet(new HashSet<>(Arrays.asList(ids)));
	}
}

package com.shmayvan.slayerledger;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * The NPCs the player has damaged (a hitsplat of theirs, {@code Hitsplat.isMine()}) and that haven't died or despawned
 * yet, by world view id and NPC index. A death of one of them is the player's kill for {@link NpcKillTally}.
 * Bounded: at most {@link #MAX_NPCS} are kept, the one damaged longest ago is dropped first. Pure (no RuneLite types);
 * client thread only, not synchronized.
 *
 * <p>An NPC index is unique only among the NPCs of one world view (the top-level one, or a boat's), so an NPC is kept
 * by both. A despawned NPC's index can be reused, so the plugin forgets an NPC when it despawns ({@link #forget}) and
 * every NPC on every login, hop and plugin start ({@link #clear}).</p>
 */
final class DamagedNpcs
{
	/** Most NPCs kept; plenty for barraging a dense multi-combat spot. */
	static final int MAX_NPCS = 64;

	/** NPC key ({@link #key}) to {@code true}, in the order last damaged (access order), so the eldest is the oldest. */
	private final Map<Long, Boolean> damaged = new LinkedHashMap<Long, Boolean>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, Boolean> eldest)
		{
			return size() > MAX_NPCS;
		}
	};

	/** The player damaged the NPC at {@code index} in world view {@code worldViewId}. */
	void damaged(int worldViewId, int index)
	{
		damaged.put(key(worldViewId, index), Boolean.TRUE);
	}

	/**
	 * Whether the NPC at {@code index} in world view {@code worldViewId} was damaged by the player; it is forgotten
	 * either way (it died).
	 */
	boolean takeDied(int worldViewId, int index)
	{
		return damaged.remove(key(worldViewId, index)) != null;
	}

	/** Forgets the NPC at {@code index} in world view {@code worldViewId} (it despawned). */
	void forget(int worldViewId, int index)
	{
		damaged.remove(key(worldViewId, index));
	}

	/** Forgets every NPC. */
	void clear()
	{
		damaged.clear();
	}

	/** How many NPCs are kept. */
	int size()
	{
		return damaged.size();
	}

	/** One key per world view id and NPC index: the id in the high 32 bits, the index in the low 32. */
	private static long key(int worldViewId, int index)
	{
		return ((long) worldViewId << 32) | (index & 0xFFFFFFFFL);
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

/**
 * The core Ground Items plugin's hidden-items list, parsed, so Slayer Ledger hides the same items from its loot:
 * they are left out of the "Loot received" grids and out of the loot value. Pure: item names are passed in. Read only;
 * Slayer Ledger never writes Ground Items' settings.
 *
 * <p>Rules, as {@code GroundItemsPlugin} (RuneLite 1.13.4) applies its lists:</p>
 * <ul>
 *     <li>Each list is split on commas with RuneLite's {@link Text#fromCSV}: entries are trimmed and blank ones
 *     skipped.</li>
 *     <li>An entry with {@code *} is a wildcard, matched with RuneLite's {@link WildcardMatcher} ({@code *} matches
 *     any run of characters); any other entry must equal the item's name. Both ignore case.</li>
 *     <li>The highlighted list overrides the hidden one: an exact highlighted entry beats any hidden entry, and a
 *     wildcard highlighted entry beats a wildcard hidden entry, but an exact hidden entry beats a wildcard highlighted
 *     one ({@code GroundItemsPlugin.isHiddenOrHighlighted}).</li>
 *     <li>An entry with a quantity condition ("Coins &lt; 1000", "Bones &gt; 5") is ignored, in either list. Ground
 *     Items checks it against each stack on the ground; Slayer Ledger keeps only a task's totals, so it can't tell
 *     which drops the condition held for. "Name &gt; 0" has no condition (it holds for every stack).</li>
 *     <li>The name matched is the item's own name. A noted item's name is its unnoted item's name, so a note matches
 *     like the item.</li>
 *     <li>A list never edited reads as {@code null} from the config; Ground Items then uses its built-in default
 *     ({@link #DEFAULT_HIDDEN_ITEMS}), and so does Slayer Ledger.</li>
 * </ul>
 *
 * <p>Immutable, so a parsed list can be shared between threads; equal lists are {@link #equals equal}.</p>
 */
final class GroundItemsHidden
{
	/** Ground Items' config group ({@code GroundItemsConfig.GROUP}). */
	static final String GROUP = "grounditems";
	/** Ground Items' hidden-items key. */
	static final String HIDDEN_ITEMS_KEY = "hiddenItems";
	/** Ground Items' highlighted-items key. */
	static final String HIGHLIGHTED_ITEMS_KEY = "highlightedItems";
	/**
	 * Ground Items' built-in hidden list ({@code GroundItemsConfig.getHiddenItems()} in RuneLite 1.13.4), used while
	 * the setting was never edited. Recheck it when the RuneLite version is raised.
	 */
	static final String DEFAULT_HIDDEN_ITEMS = "Vial, Ashes, Coins, Bones, Bucket, Jug, Seaweed";
	/** The config group RuneLite keeps every plugin's on/off state in ({@code RuneLiteConfig.GROUP_NAME}). */
	static final String PLUGIN_ENABLED_GROUP = "runelite";
	/** Ground Items' on/off key: its class name in lower case ({@code PluginManager.isPluginEnabled}). */
	static final String PLUGIN_ENABLED_KEY = "grounditemsplugin";

	/** Hides nothing. */
	static final GroundItemsHidden NONE = new GroundItemsHidden(Collections.emptyList(), Collections.emptyList());

	/** No match, a wildcard match and an exact match, in Ground Items' order of strength. */
	private static final int NO_MATCH = 0;
	private static final int WILDCARD = 1;
	private static final int EXACT = 2;

	private final List<Entry> hidden;
	private final List<Entry> highlighted;

	private GroundItemsHidden(List<Entry> hidden, List<Entry> highlighted)
	{
		this.hidden = hidden;
		this.highlighted = highlighted;
	}

	/**
	 * What Slayer Ledger hides: nothing while its "Hide Ground Items' hidden items" setting is off or the Ground Items
	 * plugin is turned off, otherwise Ground Items' lists ({@link #parse}).
	 *
	 * @param settingOn          Slayer Ledger's setting
	 * @param groundItemsEnabled Ground Items' on/off value from the config ({@link #PLUGIN_ENABLED_KEY}); {@code null}
	 *                           (never changed) is on, as Ground Items is on by default
	 * @param hiddenSetting      Ground Items' hidden list, or {@code null} when never edited
	 * @param highlightedSetting Ground Items' highlighted list, or {@code null} when never edited
	 */
	static GroundItemsHidden effective(boolean settingOn, String groundItemsEnabled, String hiddenSetting,
		String highlightedSetting)
	{
		if (!settingOn || groundItemsEnabled != null && !Boolean.parseBoolean(groundItemsEnabled))
		{
			return NONE;
		}
		return parse(hiddenSetting, highlightedSetting);
	}

	/**
	 * Parses Ground Items' lists; see the class rules.
	 *
	 * @param hiddenSetting      the hidden list; {@code null} (never edited) is {@link #DEFAULT_HIDDEN_ITEMS}
	 * @param highlightedSetting the highlighted list; {@code null} (never edited) is empty, its default
	 */
	static GroundItemsHidden parse(String hiddenSetting, String highlightedSetting)
	{
		List<Entry> hidden = entries(hiddenSetting == null ? DEFAULT_HIDDEN_ITEMS : hiddenSetting);
		if (hidden.isEmpty())
		{
			return NONE;
		}
		return new GroundItemsHidden(hidden, entries(highlightedSetting == null ? "" : highlightedSetting));
	}

	/** Whether nothing is hidden, so no item names need to be looked up. */
	boolean isEmpty()
	{
		return hidden.isEmpty();
	}

	/**
	 * Whether Ground Items hides an item named {@code name} (its own name; a note's is the unnoted item's); {@code null}
	 * (unknown) never is.
	 */
	boolean hides(String name)
	{
		if (name == null || hidden.isEmpty())
		{
			return false;
		}
		int highlight = match(highlighted, name);
		if (highlight == EXACT)
		{
			return false;
		}
		int hide = match(hidden, name);
		return hide == EXACT || hide == WILDCARD && highlight != WILDCARD;
	}

	/** Ground Items' {@code ItemList.matches}: an exact entry first, then a wildcard one. */
	private static int match(List<Entry> entries, String name)
	{
		for (Entry e : entries)
		{
			if (!e.wildcard && e.name.equalsIgnoreCase(name))
			{
				return EXACT;
			}
		}
		for (Entry e : entries)
		{
			if (e.wildcard && WildcardMatcher.matches(e.name, name))
			{
				return WILDCARD;
			}
		}
		return NO_MATCH;
	}

	/** The list's entries without a quantity condition, in order. */
	private static List<Entry> entries(String setting)
	{
		List<Entry> result = new ArrayList<>();
		for (String raw : Text.fromCSV(setting))
		{
			Entry entry = Entry.parse(raw);
			if (entry != null && !result.contains(entry))
			{
				result.add(entry);
			}
		}
		return Collections.unmodifiableList(result);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof GroundItemsHidden))
		{
			return false;
		}
		GroundItemsHidden g = (GroundItemsHidden) o;
		return hidden.equals(g.hidden) && highlighted.equals(g.highlighted);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(hidden, highlighted);
	}

	@Override
	public String toString()
	{
		return "GroundItemsHidden{hidden=" + hidden + ", highlighted=" + highlighted + "}";
	}

	/** One entry of a list: a name or wildcard pattern. */
	private static final class Entry
	{
		private final String name;
		private final boolean wildcard;

		private Entry(String name, boolean wildcard)
		{
			this.name = name;
			this.wildcard = wildcard;
		}

		/**
		 * Parses an entry as {@code ItemThreshold.fromName} does: a trailing {@code < n} or {@code > n} is a quantity
		 * condition. Returns {@code null} for an empty entry or one with a condition (see the class rules).
		 */
		static Entry parse(String entry)
		{
			if (entry == null || entry.isEmpty())
			{
				return null;
			}
			boolean wildcard = entry.contains("*");
			String name = entry;
			for (int i = entry.length() - 1; i >= 0; i--)
			{
				char c = entry.charAt(i);
				if (c >= '0' && c <= '9' || Character.isWhitespace(c))
				{
					continue;
				}
				if ((c == '<' || c == '>') && i + 1 < entry.length())
				{
					int quantity;
					try
					{
						quantity = Integer.parseInt(entry.substring(i + 1).trim());
					}
					catch (NumberFormatException e)
					{
						// Ground Items then counts it as "> 0", which every stack meets.
						quantity = 0;
						c = '>';
					}
					if (c == '<' || quantity != 0)
					{
						return null;
					}
					name = entry.substring(0, i);
				}
				break;
			}
			name = name.trim();
			return name.isEmpty() ? null : new Entry(name, wildcard);
		}

		@Override
		public boolean equals(Object o)
		{
			return o instanceof Entry && ((Entry) o).wildcard == wildcard && ((Entry) o).name.equals(name);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(name, wildcard);
		}

		@Override
		public String toString()
		{
			return name;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/**
 * The loot item ids Ground Items' hidden list hides, as worked out from their names by
 * {@link HiddenLootResolver}. Every one is left out of the "Loot received" grids ({@link #visibleRows}); every one
 * but coins is also left out of the loot value (and so profit) wherever loot is valued ({@link #valued}). Coins always
 * count in the value (owner decision, 2026-10-28): only {@link ItemValuation#COINS} drops as loot, the other coin-like
 * ids in the item list (fake, Mage Training Arena) never do. Ids are as tallied, so a noted id is listed on its own.
 * Stored loot is never changed: this is applied when loot is valued or shown.
 *
 * <p>Immutable, so it can be handed to the views worked out off the EDT; equal sets are {@link #equals equal}.</p>
 */
final class HiddenLoot
{
	/** Hides nothing. */
	static final HiddenLoot NONE = new HiddenLoot(Collections.emptySet());

	/** Hidden from view. */
	private final Set<Integer> ids;
	/** Left out of the value: {@link #ids} without coins. */
	private final Set<Integer> valueIds;

	private HiddenLoot(Set<Integer> ids)
	{
		this.ids = ids;
		if (ids.contains(ItemValuation.COINS))
		{
			Set<Integer> withoutCoins = new TreeSet<>(ids);
			withoutCoins.remove(ItemValuation.COINS);
			valueIds = Collections.unmodifiableSet(withoutCoins);
		}
		else
		{
			valueIds = ids;
		}
	}

	/** The ids in {@code ids} ({@code null} ones skipped); {@link #NONE} when there are none. */
	static HiddenLoot of(Collection<Integer> ids)
	{
		Set<Integer> set = new TreeSet<>();
		if (ids != null)
		{
			for (Integer id : ids)
			{
				if (id != null)
				{
					set.add(id);
				}
			}
		}
		return set.isEmpty() ? NONE : new HiddenLoot(Collections.unmodifiableSet(set));
	}

	/** Whether nothing is hidden from view. */
	boolean isEmpty()
	{
		return ids.isEmpty();
	}

	/**
	 * {@code loot} as valued: without the hidden items except coins. A new tally, or {@code loot} itself when nothing
	 * in it is left out of the value. Never changes it.
	 */
	ItemTally valued(ItemTally loot)
	{
		if (loot == null || !leavesOutAny(loot.itemIds()))
		{
			return loot;
		}
		ItemTally kept = new ItemTally();
		for (int id : loot.itemIds())
		{
			if (!valueIds.contains(id))
			{
				kept.add(id, loot.get(id));
			}
		}
		return kept;
	}

	/** Whether any of {@code itemIds} is left out of the value (a hidden item other than coins). */
	boolean leavesOutAny(Collection<Integer> itemIds)
	{
		if (valueIds.isEmpty() || itemIds == null)
		{
			return false;
		}
		for (Integer id : itemIds)
		{
			if (id != null && valueIds.contains(id))
			{
				return true;
			}
		}
		return false;
	}

	/** The rows of items not hidden from view, in order; coins are hidden like any other item. */
	List<ItemDetails.Row> visibleRows(List<ItemDetails.Row> rows)
	{
		if (ids.isEmpty())
		{
			return rows;
		}
		List<ItemDetails.Row> kept = new ArrayList<>(rows.size());
		for (ItemDetails.Row row : rows)
		{
			if (!ids.contains(row.getItemId()))
			{
				kept.add(row);
			}
		}
		return kept;
	}

	@Override
	public boolean equals(Object o)
	{
		return this == o || o instanceof HiddenLoot && ids.equals(((HiddenLoot) o).ids);
	}

	@Override
	public int hashCode()
	{
		return ids.hashCode();
	}

	@Override
	public String toString()
	{
		return "HiddenLoot" + ids;
	}
}

package com.shmayvan.slayerledger;

import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.IntFunction;

/**
 * Works out which loot item ids Ground Items' hidden list ({@link GroundItemsHidden}) hides, from the items' names
 *. Each id is matched once per list: the answer is kept until the list changes ({@link #setList}), so the
 * wildcard matching does not run per tick or per row. An id whose name is unknown is not hidden, and is matched again
 * once its name is known.
 *
 * <p>Not thread-safe: each owner uses its own, on one thread (the plugin's on the client thread, the history model's
 * on the EDT).</p>
 */
final class HiddenLootResolver
{
	private GroundItemsHidden list = GroundItemsHidden.NONE;
	/** Whether each id matched so far hides, for {@link #list}. */
	private final Map<Integer, Boolean> matched = new HashMap<>();

	/** The list matched against. */
	GroundItemsHidden list()
	{
		return list;
	}

	/** Matches against {@code newList} from now on ({@code null} is none); returns whether it changed. */
	boolean setList(GroundItemsHidden newList)
	{
		GroundItemsHidden l = newList == null ? GroundItemsHidden.NONE : newList;
		if (l.equals(list))
		{
			return false;
		}
		list = l;
		matched.clear();
		return true;
	}

	/**
	 * The hidden ones of {@code itemIds}.
	 *
	 * @param names an item's own name (a note's is the unnoted item's), or {@code null} while unknown; a lookup that
	 *              throws counts as unknown. Only called for ids not matched yet.
	 */
	HiddenLoot resolve(Collection<Integer> itemIds, IntFunction<String> names)
	{
		if (list.isEmpty() || itemIds == null)
		{
			return HiddenLoot.NONE;
		}
		Set<Integer> hidden = new TreeSet<>();
		for (Integer id : itemIds)
		{
			if (id == null)
			{
				continue;
			}
			Boolean hides = matched.get(id);
			if (hides == null)
			{
				String name;
				try
				{
					name = names.apply(id);
				}
				catch (RuntimeException e)
				{
					name = null;
				}
				if (name == null)
				{
					continue;
				}
				hides = list.hides(name);
				matched.put(id, hides);
			}
			if (hides)
			{
				hidden.add(id);
			}
		}
		return HiddenLoot.of(hidden);
	}
}

package com.shmayvan.slayerledger;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Locale;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The History estimate of {@link SlayerLedgerPanel} with What to bring below it: historical estimates for
 * the kills left on the observed task, and the supplies and bank trips they suggest. The text and tooltips are rebuilt
 * only when the task's statistics, the kills left or the item names change, never every second by the panel's refresh
 * timer; while views wait for today's prices what is shown stays. Nothing of What to bring is worked out while
 * its "What to bring" setting hides it. EDT only.
 */
final class HistoryEstimateSection
{
	/**
	 * The estimate's note when the session has fired a cannonball but the history has no cannon tasks of the task, so
	 * tasks with and without a cannon still count.
	 */
	static final String NO_CANNON_TASKS_NOTE = "No cannon tasks yet, so tasks without a cannon count too.";

	private final LedgerHistoryModel model;
	private final SessionTracker tracker;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;

	/**
	 * Historical estimate for the observed task, two short lines like a history row: "History (N tasks)" and
	 * the kills and time, then the loot in the "Loot price" mode and the supplies. The tooltip has the averages. From
	 * the history at the current location (Part B), the title "History at <location> (N tasks)" has a line of its
	 * own ({@link #timeLine}).
	 */
	private final JPanel box = new JPanel(new GridLayout(0, 1, 0, 2));
	/** The estimate's first line: its title, then (unless it is on {@link #timeLine}) the time. */
	private final JPanel titleLine = new JPanel(new BorderLayout(6, 0));
	/**
	 * The kills and time on a line of their own, below a "History at <location>" title (Part B), which then has the
	 * whole width: beside the time, too little of a location name would show.
	 */
	private final JPanel timeLine = new JPanel(new BorderLayout(6, 0));
	private final JLabel titleLabel = new JLabel();
	/** " (N tasks)" right after {@link #titleLabel}, never cut: a long "History at <location>" truncates before it. */
	private final JLabel countLabel = new JLabel();
	private final JLabel timeLabel = new JLabel();
	private final JLabel lootLabel = new JLabel();
	private final JLabel suppliesLabel = new JLabel();
	/** How many times the estimate's text and tooltip were built. */
	private int builds;
	/**
	 * Cache key ({@link LedgerHistoryModel#taskStatisticsKey} and the kills left) of the shown estimate's text and
	 * tooltip, so the refresh timer doesn't rebuild them every second; {@code null} when they must be rebuilt.
	 */
	private String key;
	/** {@link #key} without the location, so the estimate can stay while only the location is pending. */
	private String anyLocationKey;

	/**
	 * What to bring for the kills left, styled like the History box below which it sits: a header with
	 * "What to bring (N tasks)", Show/Hide, the bank trips and the number of supplies, then (while open) one row per
	 * supply, name left and amount right. Rebuilt only with the estimate text ({@link #key}).
	 */
	private final JPanel bringSection = new JPanel();
	private final JPanel bringHeader = new JPanel(new GridLayout(2, 1, 0, 2));
	private final JLabel bringTitleLabel = new JLabel();
	private final JLabel bringToggleLabel = new JLabel();
	private final JLabel bringTripsLabel = new JLabel();
	private final JLabel bringCountLabel = new JLabel();
	private final JPanel bringRows = new JPanel();
	/** Whether What to bring is open; closed whenever the panel is created and kept for the session (owner). */
	private boolean bringExpanded;
	/** How many times What to bring was built. */
	private int bringBuilds;
	/** Whether the cached estimate ({@link #key}) has a What to bring section to show. */
	private boolean bringSectionBuilt;
	/** The "What to bring" setting; while off, nothing of the section is built. The panel hides its block. */
	private boolean bringShown = true;

	HistoryEstimateSection(LedgerHistoryModel model, SessionTracker tracker, Runnable relayout)
	{
		this.model = model;
		this.tracker = tracker;
		this.relayout = relayout;
	}

	/** Adds the History estimate box to {@code content}, hidden until there is an estimate. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		box.setName("estimate");
		titleLabel.setName("estimate.title");
		countLabel.setName("estimate.count");
		timeLabel.setName("estimate.time");
		timeLine.setName("estimate.timeLine");
		lootLabel.setName("estimate.loot");
		suppliesLabel.setName("estimate.supplies");
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		for (JLabel label : new JLabel[]{titleLabel, countLabel, timeLabel, lootLabel, suppliesLabel})
		{
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			label.setFont(FontManager.getRunescapeSmallFont());
		}
		JPanel title = new JPanel(new PrefixFitLayout());
		title.setOpaque(false);
		title.add(titleLabel);
		title.add(countLabel);
		titleLine.setOpaque(false);
		titleLine.add(title, BorderLayout.CENTER);
		titleLine.add(timeLabel, BorderLayout.EAST);
		timeLine.setOpaque(false);
		box.add(titleLine);
		box.add(SlayerLedgerPanel.historyLine(lootLabel, suppliesLabel));
		box.setVisible(false);
		SlayerLedgerPanel.addRow(content, box);
	}

	/** Adds What to bring to {@code block} (its optional block), closed and hidden until an estimate is shown. */
	void addBringTo(JPanel block)
	{
		// Names for tests, which find the parts by them; no visible effect.
		bringSection.setName("bring");
		bringHeader.setName("bring.header");
		bringTitleLabel.setName("bring.title");
		bringToggleLabel.setName("bring.toggle");
		bringTripsLabel.setName("bring.trips");
		bringCountLabel.setName("bring.count");
		bringRows.setName("bring.rows");
		bringSection.setLayout(new BoxLayout(bringSection, BoxLayout.Y_AXIS));
		bringSection.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bringSection.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		bringHeader.setOpaque(false);
		bringHeader.setAlignmentX(Component.LEFT_ALIGNMENT);
		bringHeader.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		for (JLabel label : new JLabel[]{bringTitleLabel, bringToggleLabel, bringTripsLabel, bringCountLabel})
		{
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			label.setFont(FontManager.getRunescapeSmallFont());
		}
		bringToggleLabel.setText("Show");
		bringHeader.add(SlayerLedgerPanel.historyLine(bringTitleLabel, bringToggleLabel));
		bringHeader.add(SlayerLedgerPanel.historyLine(bringTripsLabel, bringCountLabel));
		MouseAdapter toggle = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1)
				{
					toggleBring();
				}
			}
		};
		// Only the header listens: its labels have no listener or tooltip, so clicks and the tooltip reach it.
		bringHeader.addMouseListener(toggle);
		bringSection.add(bringHeader);

		bringRows.setLayout(new BoxLayout(bringRows, BoxLayout.Y_AXIS));
		bringRows.setOpaque(false);
		bringRows.setAlignmentX(Component.LEFT_ALIGNMENT);
		bringRows.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		bringRows.setVisible(false);
		bringSection.add(bringRows);
		bringSection.setVisible(false);
		SlayerLedgerPanel.addRow(block, bringSection);
	}

	/** Drops the cached estimate text, so the next {@link #refresh} rebuilds it. */
	void invalidate()
	{
		key = null;
	}

	/**
	 * Applies the "What to bring" setting: hidden, its rows are dropped and nothing of it is worked out; shown
	 * again, it is rebuilt with the estimate at once. The panel shows or hides the section's block.
	 */
	void setBringShown(boolean shown)
	{
		if (bringShown == shown)
		{
			return;
		}
		bringShown = shown;
		if (!shown)
		{
			bringRows.removeAll();
			bringSectionBuilt = false;
			setBringVisible(false);
		}
		// Built with the estimate text, so that is rebuilt too.
		key = null;
		refresh();
	}

	/**
	 * Shows historical estimates for the kills left on the observed task (the assigned size while it is new), also
	 * while it isn't being timed. The text and tooltip are rebuilt only when the statistics, the kills left or the
	 * item names change, not on every refresh.
	 */
	void refresh()
	{
		// The model decides whether the preview is posted; this is one of the points it is checked again at.
		model.checkAssignmentPreview();
		int remaining = tracker.getCurrentRemaining();
		if (!tracker.isTaskObserved() || remaining <= 0)
		{
			// Rebuilt when shown again, so the supply recommendation comes back with it.
			key = null;
			setVisible(false);
			setBringVisible(false);
			return;
		}
		if (model.isWaitingForCurrentPrices())
		{
			// Valued at today's prices: what is shown stays until the prices asked for arrive (PRICED_VIEWS).
			return;
		}

		int creatureId = tracker.getCurrentCreatureId();
		String monster = tracker.getCurrentMonster();
		String location = model.currentLocation();
		// Until the session's kills say which version of the task is done, both are pooled; until it fires a
		// cannonball, tasks with and without a cannon are, and after it too while there are no cannon tasks.
		TaskSelection selection = tracker.getCurrentTaskSelection();
		String newKey = model.taskStatisticsKey(creatureId, monster, selection, location) + "\u0000" + remaining;
		String newAnyLocationKey = model.taskStatisticsKey(creatureId, monster, selection, null) + "\u0000"
			+ remaining;
		if (newKey.equals(key) || (model.isCurrentLocationPending() && key != null
			&& newAnyLocationKey.equals(anyLocationKey)))
		{
			// While the name of the location is on its way, the shown estimate stays; it is rebuilt when it arrives.
			setVisible(true);
			setBringVisible(bringSectionBuilt);
			return;
		}
		TaskStatistics stats = model.taskStatistics(creatureId, monster, selection, location);
		TaskStatistics.Estimate estimate = stats.estimate(remaining);
		if (estimate == null)
		{
			key = null;
			setVisible(false);
			setBringVisible(false);
			return;
		}

		builds++;
		model.requestItemNames(stats.getSupplyTotals().keySet());
		// Nothing of What to bring is worked out while its setting hides it.
		WhatToBring bring = bringShown ? model.whatToBring(stats, remaining) : null;
		bringSectionBuilt = bring != null;
		refreshBring(bring, stats);
		// "History at Smoke Dungeon (3 tasks)": a long location truncates, the count stays (PrefixFitLayout).
		titleLabel.setText(stats.getLocation() == null ? "History" : "History at " + stats.getLocation());
		setTimeOnOwnLine(stats.getLocation() != null);
		countLabel.setText(" (" + estimate.getSampleCount() + " "
			+ (estimate.getSampleCount() == 1 ? "task" : "tasks") + ")");
		timeLabel.setText(remaining + (remaining == 1 ? " kill" : " kills")
			+ (estimate.getActiveMillis() == null ? "" : " ~" + LedgerHistory.formatDuration(estimate.getActiveMillis())));
		// Like a history row: the loot labelled with its price mode, no " gp", so both fit one sidebar line.
		lootLabel.setText(LedgerHistory.lootLabel(model.lootPriceMode())
			+ LedgerHistory.formatAmount(estimate.getLootValue(), estimate.isLootApproximate()));
		suppliesLabel.setText("Supplies: "
			+ LedgerHistory.formatAmount(estimate.getSuppliesValue(), estimate.isSuppliesApproximate()));
		box.setToolTipText(statisticsTooltip(stats, selectionNote(monster, selection,
			model.effectiveSelection(creatureId, monster, selection), stats)));
		key = newKey;
		anyLocationKey = newAnyLocationKey;
		setVisible(true);
	}

	/** Opens or closes What to bring, as a click on its header does. Nothing is rebuilt. */
	void toggleBring()
	{
		bringExpanded = !bringExpanded;
		bringToggleLabel.setText(bringExpanded ? "Hide" : "Show");
		bringRows.setVisible(bringExpanded);
		relayout.run();
	}

	/**
	 * Rebuilds What to bring for {@code bring}, or hides it for {@code null}. Called only when the estimate text is
	 * rebuilt (the statistics, the kills left or the item names changed), never by the refresh timer.
	 */
	private void refreshBring(WhatToBring bring, TaskStatistics stats)
	{
		if (bring == null)
		{
			setBringVisible(false);
			return;
		}
		SupplyRecommendation.Estimate estimate = bring.getEstimate();
		bringBuilds++;

		boolean suppliesKnown = estimate.getSupplySampleCount() > 0;
		int tasks = suppliesKnown ? estimate.getSupplySampleCount() : estimate.getBankTripSampleCount();
		bringTitleLabel.setText("What to bring (" + tasks + (tasks == 1 ? " task)" : " tasks)"));
		Long trips = estimate.getBankTrips();
		bringTripsLabel.setText(trips == null ? "" : trips == 0 ? "No bank trips"
			: "~" + LedgerHistory.formatAmount(trips, false) + (trips == 1 ? " bank trip" : " bank trips"));
		int count = estimate.getSupplies().size();
		bringCountLabel.setText(count == 0 ? "" : count + (count == 1 ? " supply" : " supplies"));
		bringHeader.setToolTipText(bringTooltip(estimate, stats.getLocation()));

		bringRows.removeAll();
		if (!suppliesKnown)
		{
			bringRows.add(bringMessage("No supply data in history"));
		}
		else if (estimate.getSupplies().isEmpty())
		{
			bringRows.add(bringMessage("No tracked supplies in history"));
		}
		else
		{
			for (BringRow row : bring.getRows())
			{
				JPanel line = SlayerLedgerPanel.historyLine(
					SlayerLedgerPanel.historyLabel(row.getName(), ColorScheme.LIGHT_GRAY_COLOR),
					SlayerLedgerPanel.historyLabel(row.quantityText(), ColorScheme.LIGHT_GRAY_COLOR));
				line.setAlignmentX(Component.LEFT_ALIGNMENT);
				line.setToolTipText("<html>" + LedgerHistory.escapeHtml(row.tooltipText()) + " for the "
					+ killsText(estimate.getKills()) + " left</html>");
				bringRows.add(line);
			}
		}
		bringRows.setVisible(bringExpanded);
		bringSection.setVisible(true);
		relayout.run();
	}

	private static JPanel bringMessage(String message)
	{
		JPanel line = SlayerLedgerPanel.historyLine(SlayerLedgerPanel.historyLabel(message,
			ColorScheme.MEDIUM_GRAY_COLOR), null);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		return line;
	}

	/**
	 * Lays out two components left to right with no gap, each at most its preferred width: the second ({@code " (3
	 * tasks)"}) always gets its full width while it fits, and the first (a JLabel, {@code "History at Smoke Dungeon"})
	 * gets what is left, so a long first text truncates with "..." and the second stays right after it.
	 */
	private static final class PrefixFitLayout implements LayoutManager
	{
		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			int width = 0;
			int height = 0;
			for (Component component : parent.getComponents())
			{
				Dimension size = component.getPreferredSize();
				width += size.width;
				height = Math.max(height, size.height);
			}
			Insets insets = parent.getInsets();
			return new Dimension(width + insets.left + insets.right, height + insets.top + insets.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			Dimension preferred = preferredLayoutSize(parent);
			Insets insets = parent.getInsets();
			// May shrink to nothing: the first component truncates, the line never widens the sidebar.
			return new Dimension(insets.left + insets.right, preferred.height);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets insets = parent.getInsets();
			int available = Math.max(0, parent.getWidth() - insets.left - insets.right);
			int height = Math.max(0, parent.getHeight() - insets.top - insets.bottom);
			Component[] components = parent.getComponents();
			if (components.length == 0)
			{
				return;
			}
			int secondWidth = components.length > 1
				? Math.min(components[1].getPreferredSize().width, available) : 0;
			int firstWidth = Math.max(0, Math.min(components[0].getPreferredSize().width, available - secondWidth));
			components[0].setBounds(insets.left, insets.top, firstWidth, height);
			for (int i = 1; i < components.length; i++)
			{
				components[i].setBounds(insets.left + firstWidth, insets.top, i == 1 ? secondWidth : 0, height);
			}
		}
	}

	/**
	 * The header tooltip: what the amounts are for and what they are based on (only the tasks at {@code location} when
	 * it is not {@code null}).
	 */
	private static String bringTooltip(SupplyRecommendation.Estimate estimate, String location)
	{
		StringBuilder tooltip = new StringBuilder("<html>Suggested for the ")
			.append(killsText(estimate.getKills())).append(" left.");
		if (location != null)
		{
			tooltip.append("<br>From your tasks at ").append(LedgerHistory.escapeHtml(location)).append(" only.");
		}
		tooltip.append("<br>Supplies: ");
		if (estimate.getSupplySampleCount() > 0)
		{
			tooltip.append("pooled use per kill over ").append(tasksText(estimate.getSupplySampleCount()))
				.append(" (").append(killsText(estimate.getSupplyKills())).append(") with supplies or values,")
				.append(" times the kills left, rounded up to whole tracked units.");
		}
		else
		{
			tooltip.append("no completed task recorded supplies or values.");
		}
		tooltip.append("<br>Bank trips: ");
		if (estimate.getBankTrips() != null)
		{
			tooltip.append("pooled trips per kill over ").append(tasksText(estimate.getBankTripSampleCount()))
				.append(" (").append(killsText(estimate.getBankTripKills())).append(") with a bank-trip count,")
				.append(" times the kills left, rounded up.");
		}
		else
		{
			tooltip.append("no completed task recorded them.");
		}
		return tooltip.append("<br>Click to show or hide the supplies.</html>").toString();
	}

	private static String killsText(long kills)
	{
		return LedgerHistory.formatAmount(kills, false) + (kills == 1 ? " kill" : " kills");
	}

	private static String tasksText(int tasks)
	{
		return tasks + (tasks == 1 ? " completed task" : " completed tasks");
	}

	/**
	 * Puts the estimate's kills and time on a line of their own below the title ({@code true}, for "History at
	 * <location>"), or beside the title as a two-line box ({@code false}).
	 */
	private void setTimeOnOwnLine(boolean ownLine)
	{
		if ((timeLabel.getParent() == timeLine) == ownLine)
		{
			return;
		}
		if (ownLine)
		{
			titleLine.remove(timeLabel);
			timeLine.add(timeLabel, BorderLayout.CENTER);
			box.add(timeLine, 1);
		}
		else
		{
			box.remove(timeLine);
			timeLine.remove(timeLabel);
			titleLine.add(timeLabel, BorderLayout.EAST);
		}
		relayout.run();
	}

	private void setVisible(boolean visible)
	{
		if (box.isVisible() != visible)
		{
			box.setVisible(visible);
			relayout.run();
		}
	}

	private void setBringVisible(boolean visible)
	{
		if (bringSection.isVisible() != visible)
		{
			bringSection.setVisible(visible);
			relayout.run();
		}
	}

	/**
	 * Which of the task's tasks the estimate counts, as plain text, or {@code null} when there is nothing to say: the
	 * {@link #variantNote} and the {@link #cannonNote}, in one line.
	 */
	static String selectionNote(String monster, TaskSelection selection, TaskSelection effective, TaskStatistics stats)
	{
		String variant = variantNote(monster, selection);
		String cannon = cannonNote(selection, effective, stats);
		if (variant == null || cannon == null)
		{
			return variant != null ? variant : cannon;
		}
		return variant + " " + cannon;
	}

	/**
	 * Which version of a task with a Catacombs variant the estimate counts, as plain text, or {@code null} for a
	 * task without one: both until the session's kills say which, then only that one.
	 */
	static String variantNote(String monster, TaskSelection selection)
	{
		CatacombsVariants.Variant catacombs = CatacombsVariants.forTask(monster);
		if (catacombs == null || selection == null)
		{
			return null;
		}
		if (selection.isAnyVariant())
		{
			return "Counts " + catacombs.getName() + " tasks too, until your kills show which you are doing.";
		}
		return selection.getVariant() != null
			? "Only your " + selection.getVariant() + " tasks count."
			: "Your " + catacombs.getName() + " tasks are left out.";
	}

	/**
	 * Whether the estimate counts the task's cannon tasks, as plain text, from the live {@code selection} and
	 * the one the statistics use ({@code effective}, {@link LedgerHistoryModel#effectiveSelection}): once the session
	 * has fired a cannonball, only them, or, with none in the history, all tasks; before that both, said only when
	 * {@code stats} have some; else {@code null}.
	 */
	static String cannonNote(TaskSelection selection, TaskSelection effective, TaskStatistics stats)
	{
		if (selection != null && Boolean.TRUE.equals(selection.getCannon()))
		{
			return effective != null && Boolean.TRUE.equals(effective.getCannon())
				? "Only your cannon tasks count."
				: NO_CANNON_TASKS_NOTE;
		}
		if (stats != null && stats.getCannonSampleCount() > 0)
		{
			return "Counts cannon tasks too, until you fire a cannonball.";
		}
		return null;
	}

	private String statisticsTooltip(TaskStatistics stats, String selectionNote)
	{
		StringBuilder tooltip = new StringBuilder("<html>Completed-task history");
		if (stats.getLocation() != null)
		{
			tooltip.append(" at ").append(LedgerHistory.escapeHtml(stats.getLocation()));
		}
		tooltip.append(" (")
			.append(stats.getSampleCount()).append(stats.getSampleCount() == 1 ? " sample" : " samples")
			.append("); outliers are retained.");
		if (stats.getLocation() != null)
		{
			tooltip.append("<br>Only tasks at this location count; without any there, all of them do.");
		}
		if (selectionNote != null)
		{
			tooltip.append("<br>").append(LedgerHistory.escapeHtml(selectionNote));
		}
		tooltip.append("<br>Average task duration: ")
			.append(LedgerHistory.formatDuration(stats.getAverageTaskDurationMillis()));
		Long msPerKill = stats.getMillisPerKill();
		tooltip.append("<br>Average time per kill: ")
			.append(msPerKill == null ? LedgerHistory.NO_VALUE : LedgerHistory.formatKillTime(msPerKill));
		tooltip.append("<br>Loot per kill: ")
			.append(formatHistoricalGp(stats.getLootPerKill(), stats.isLootApproximate()))
			.append("<br>Supplies per kill: ")
			.append(formatHistoricalGp(stats.getSuppliesValuePerKill(), stats.isSuppliesApproximate()))
			.append("<br>Profit per kill: ")
			.append(formatHistoricalGp(stats.getProfitPerKill(), stats.isProfitApproximate()));

		Map<Integer, Double> supplies = stats.getSuppliesPerKill();
		if (!supplies.isEmpty())
		{
			tooltip.append("<br>Supplies used per kill:");
			for (Map.Entry<Integer, Double> item : supplies.entrySet())
			{
				String known = model.itemName(item.getKey());
				String name = known == null ? "Item " + item.getKey() : known;
				// Dose-counted ids (potions, food eaten in bites, charged jewellery) in their own unit, as the item lists.
				Integer doses = stats.getSupplyDoses().get(item.getKey());
				String unit = doses == null ? "items"
					: ItemDetails.doseUnit(item.getKey()).name().toLowerCase(Locale.ROOT);
				tooltip.append("<br>").append(LedgerHistory.escapeHtml(name)).append(": ")
					.append(formatAverage(item.getValue())).append(' ').append(unit).append("/kill");
			}
		}

		Map<String, Double> xpPerKill = stats.getXpPerKill();
		if (!xpPerKill.isEmpty())
		{
			tooltip.append("<br>XP per kill:");
			for (Map.Entry<String, Double> skill : xpPerKill.entrySet())
			{
				tooltip.append("<br>").append(LedgerHistory.escapeHtml(SkillXp.skillName(skill.getKey())))
					.append(": ").append(formatAverage(skill.getValue()));
			}
		}
		Long xpPerHour = stats.getXpPerHour();
		if (xpPerHour != null)
		{
			tooltip.append("<br>XP per hour: ").append(LedgerHistory.formatAmount(xpPerHour, false));
		}
		tooltip.append("<br>GP averages use today's prices in ")
			.append(LedgerHistory.escapeHtml(model.lootPriceMode().toString()))
			.append(" mode; older unvalued tasks are excluded.")
			.append("<br>XP and supply-item averages use only records that captured those data.</html>");
		return tooltip.toString();
	}

	private static String formatHistoricalGp(Long value, boolean approximate)
	{
		return value == null ? LedgerHistory.NO_VALUE : LedgerHistory.formatAmount(value, approximate) + " gp";
	}

	private static String formatAverage(double value)
	{
		String formatted = String.format(Locale.ROOT, "%.2f", value);
		while (formatted.endsWith("0"))
		{
			formatted = formatted.substring(0, formatted.length() - 1);
		}
		return formatted.endsWith(".") ? formatted.substring(0, formatted.length() - 1) : formatted;
	}

	/**
	 * How many times the estimate's text and tooltip were built. Performance seam: tests assert this doesn't grow on the
	 * refresh timer.
	 */
	int getBuildCount()
	{
		return builds;
	}

	/** How many times What to bring was built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBringBuildCount()
	{
		return bringBuilds;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeSet;
import java.util.function.IntFunction;

/**
 * The Task history's filters: Monster, Location and Slayer master, each {@link LedgerHistory#ALL} or one value.
 * A record is shown when it matches every filter set (AND). Each filter's choices are the values in the records, so a
 * choice that matches nothing alone never appears; together the filters can still match nothing. Immutable and pure
 * (no Swing or RuneLite types).
 *
 * <ul>
 *   <li><b>Monster</b>: {@link LedgerHistory#monster} (the record's group name: Catacombs variant, cannon), exactly.</li>
 *   <li><b>Location</b>: the name the history shows ({@link TaskLocation#recordLocation}: the record's own name, else
 *   its assigned area, else its region's current name), compared as {@link TaskLocation#sameLocation} does (ignoring
 *   case and spacing); {@link #NO_LOCATION} for a record without one, shown as {@link #NO_LOCATION_LABEL}.</li>
 *   <li><b>Master</b>: {@link SlayerMaster#displayName} of the master who assigned the task; {@link #UNKNOWN_MASTER}
 *   for a record without one or with a value not in {@link SlayerMaster}'s table.</li>
 * </ul>
 */
final class HistoryFilter
{
	/**
	 * Location choice of the records without a location (older records, or a region nobody named), shown as
	 * {@link #NO_LOCATION_LABEL}. Empty, so it never equals a real name (names are never empty,
	 * {@link TaskLocation#normalizeName}): a place the player named "No location" stays a choice of its own.
	 */
	static final String NO_LOCATION = "";
	/** How the Location filter shows {@link #NO_LOCATION}. */
	static final String NO_LOCATION_LABEL = "No location";
	/**
	 * Master choice of the records whose master is not known. Shown as it is: masters' names come from
	 * {@link SlayerMaster}'s table, so none can be the same.
	 */
	static final String UNKNOWN_MASTER = "Unknown master";

	/** Alphabetical, ignoring case first, as the Monster filter sorts. */
	private static final Comparator<String> ALPHABETICAL = String.CASE_INSENSITIVE_ORDER
		.thenComparing(Comparator.naturalOrder());

	private final String monster;
	private final String location;
	private final String master;

	/**
	 * @param monster  a Monster choice, or {@code null} for "All"
	 * @param location a Location choice ({@link #NO_LOCATION} included), or {@code null} for "All"
	 * @param master   a Master choice ({@link #UNKNOWN_MASTER} included), or {@code null} for "All"
	 */
	HistoryFilter(String monster, String location, String master)
	{
		this.monster = monster;
		this.location = location;
		this.master = master;
	}

	/** How a filter shows {@code choice}: {@link #NO_LOCATION_LABEL} for {@link #NO_LOCATION}, others as they are. */
	static String label(String choice)
	{
		return NO_LOCATION.equals(choice) ? NO_LOCATION_LABEL : choice;
	}

	/** The location a history row shows, as the Location filter lists it: {@link #NO_LOCATION} when it has none. */
	static String location(LedgerRecord record, IntFunction<String> regionNames)
	{
		String name = TaskLocation.recordLocation(record, regionNames);
		return name == null ? NO_LOCATION : name;
	}

	/** The master who assigned the task, as the Master filter lists it: {@link #UNKNOWN_MASTER} when not known. */
	static String master(LedgerRecord record)
	{
		return SlayerMaster.hasName(record.getSlayerMaster()) ? SlayerMaster.displayName(record.getSlayerMaster())
			: UNKNOWN_MASTER;
	}

	/**
	 * Location choices: {@link LedgerHistory#ALL}, each location in the records alphabetically (names that are the
	 * same place, {@link TaskLocation#sameLocation}, once, as the newest record spells it; records are newest first),
	 * then {@link #NO_LOCATION} when a record has none.
	 */
	static List<String> locationOptions(Collection<LedgerRecord> records, IntFunction<String> regionNames)
	{
		Map<String, String> byKey = new LinkedHashMap<>();
		boolean none = false;
		for (LedgerRecord record : records)
		{
			if (record == null)
			{
				continue;
			}
			String name = location(record, regionNames);
			if (NO_LOCATION.equals(name))
			{
				none = true;
			}
			else
			{
				byKey.putIfAbsent(TaskLocation.matchKey(name), name);
			}
		}
		return options(byKey.values(), none, NO_LOCATION);
	}

	/**
	 * Master choices: {@link LedgerHistory#ALL}, each master in the records alphabetically, then
	 * {@link #UNKNOWN_MASTER} when a record's master is not known.
	 */
	static List<String> masterOptions(Collection<LedgerRecord> records)
	{
		List<String> names = new ArrayList<>();
		boolean unknown = false;
		for (LedgerRecord record : records)
		{
			if (record == null)
			{
				continue;
			}
			String name = master(record);
			if (UNKNOWN_MASTER.equals(name))
			{
				unknown = true;
			}
			else
			{
				names.add(name);
			}
		}
		return options(names, unknown, UNKNOWN_MASTER);
	}

	/** {@link LedgerHistory#ALL}, the distinct {@code names} alphabetically, then {@code last} when {@code addLast}. */
	private static List<String> options(Collection<String> names, boolean addLast, String last)
	{
		TreeSet<String> sorted = new TreeSet<>(ALPHABETICAL);
		sorted.addAll(names);
		List<String> options = new ArrayList<>(sorted.size() + 2);
		options.add(LedgerHistory.ALL);
		options.addAll(sorted);
		if (addLast)
		{
			options.add(last);
		}
		return options;
	}

	/**
	 * The Location choice to keep after the choices change ({@code options} start with "All"): the choice that is still
	 * the same place as {@code selection} (as it is spelled now), {@link #NO_LOCATION} while it is still a choice,
	 * otherwise {@code null} ("All").
	 */
	static String keepLocation(List<String> options, String selection)
	{
		if (selection == null)
		{
			return null;
		}
		if (NO_LOCATION.equals(selection))
		{
			return options.contains(NO_LOCATION) ? NO_LOCATION : null;
		}
		for (String option : options.subList(Math.min(1, options.size()), options.size()))
		{
			if (TaskLocation.sameLocation(option, selection))
			{
				return option;
			}
		}
		return null;
	}

	/**
	 * Whether two Location selections ({@code null} for "All") pick the same records: equal, or the same place
	 * spelled another way ({@link TaskLocation#sameLocation}).
	 */
	static boolean sameLocationChoice(String left, String right)
	{
		return Objects.equals(left, right) || TaskLocation.sameLocation(left, right);
	}

	/** Whether {@code record} matches every filter set. */
	boolean matches(LedgerRecord record, IntFunction<String> regionNames)
	{
		if (monster != null && !monster.equals(LedgerHistory.monster(record)))
		{
			return false;
		}
		if (master != null && !master.equals(master(record)))
		{
			return false;
		}
		if (location == null)
		{
			return true;
		}
		String name = location(record, regionNames);
		return NO_LOCATION.equals(location) ? NO_LOCATION.equals(name) : TaskLocation.sameLocation(location, name);
	}

	/** The records matching every filter set, in their order; nulls are left out. */
	List<LedgerRecord> apply(List<LedgerRecord> records, IntFunction<String> regionNames)
	{
		List<LedgerRecord> result = new ArrayList<>();
		for (LedgerRecord record : records)
		{
			if (record != null && matches(record, regionNames))
			{
				result.add(record);
			}
		}
		return result;
	}
}

