/**
 * The "Task history" section of {@link SlayerLedgerPanel}: the Monster, Location and Master filters, the error line
 * and one row per saved task, valued at today's prices, with its item details below it while open and a
 * right-click menu to edit or delete it. The rows are rebuilt from the history model's records only when they, their
 * pricing or the names they show change; while views wait for today's prices the rows shown stay. EDT only.
 *
 * <p>Filters ({@link HistoryFilter}): they combine, and each lists only the values in the account's records. Their
 * choices are rebuilt when the records change and when region names arrive or are forgotten (a record's location may
 * be its region's name), never on the refresh timer; a selected value that is gone goes back to "All".</p>
 *
 * <p>Paging: at most {@link #PAGE_SIZE} rows are built at first, with a "Show N more" button below them that
 * adds the next {@link #PAGE_SIZE} (ignored while the rows wait for today's prices). Choosing another value in a
 * filter (or a filter dropping the selected one) and another account's history go back to the first page; reloads of
 * the same account's records (a save, an edit, a delete, new prices or names) keep the rows the player has opened up.
 * A row's tooltip is built the first time it is asked for, not with the row.</p>
 *
 * <p>Each row's monster name shows its task's icon ({@link TaskIcons}, from the record's assigned name, so a
 * Catacombs variant or cannon task shows its task's), or an empty slot of the same size; asked for only as rows are
 * built, never on the refresh timer.</p>
 */
final class HistoryListSection
{
	/** Changes one value of a saved record: {@code (account, record id, new value)}. */
	@FunctionalInterface
	interface RecordEdit
	{
		void apply(long account, String recordId, String value);
	}

	private final LedgerHistoryModel model;
	/**
	 * Deletes a saved record, after the player confirmed it: {@code (account, record id)}. The panel also drops a
	 * notice about that record first.
	 */
	private final BiConsumer<Long, String> deleteRecord;
	/** Saves a record's new note ({@code null} removes it). */
	private final RecordEdit editNote;
	/** Saves a record's new location name ({@code null} removes it). */
	private final RecordEdit editLocation;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Parent of the dialogs. */
	private final Component dialogParent;
	/** Draws the item icons and the skill icons of a row's details. */
	private final SidebarIcons icons;

	private final FilterChoice monsterFilter = new FilterChoice("history.filter", "Show only tasks for this monster",
		Objects::equals);
	private final FilterChoice locationFilter = new FilterChoice("history.locationFilter",
		"Show only tasks at this location", HistoryFilter::sameLocationChoice);
	private final FilterChoice masterFilter = new FilterChoice("history.masterFilter",
		"Show only tasks from this Slayer master", Objects::equals);
	private final JPanel list = new JPanel();
	private final JLabel emptyLabel = new JLabel();
	private final JLabel errorLabel = new JLabel();
	/** Account whose history the section last showed, so another account's selection and open rows are forgotten. */
	private long shownAccount = SessionTracker.NO_ACCOUNT;
	/** Keys ({@link #recordKey}) of the history rows whose item details are open. */
	private final Set<String> expandedRecords = new HashSet<>();
	/** XP lists of open history rows showing all their skills ("+N more" clicked), by record key and list title. */
	private final Set<String> listsShowingAll = new HashSet<>();
	/** Shown instead of the rows when the filters together match none of the saved tasks. */
	static final String NO_MATCHES = "No saved tasks match these filters.";
	/** Rows shown at first, and added by each click on {@link #showMoreButton}. */
	static final int PAGE_SIZE = 25;
	/** Below the shown rows while more of the filtered records are left: adds {@link #PAGE_SIZE} rows. */
	private final JButton showMoreButton = new JButton();
	/** How many of the filtered records get a row: a multiple of {@link #PAGE_SIZE}. */
	private int shownLimit = PAGE_SIZE;
	/** How many times the history rows were built. */
	private int builds;

	HistoryListSection(LedgerHistoryModel model, BiConsumer<Long, String> deleteRecord, RecordEdit editNote,
		RecordEdit editLocation, Component dialogParent, Runnable relayout, SidebarIcons icons)
	{
		this.model = model;
		this.deleteRecord = deleteRecord;
		this.editNote = editNote;
		this.editLocation = editLocation;
		this.dialogParent = dialogParent;
		this.relayout = relayout;
		this.icons = icons;
	}

	/** Adds the title, the filter, the hints, the error line and the (empty) list to {@code content}. */
	void addTo(JPanel content)
	{
		JLabel title = new JLabel("Task history");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		SlayerLedgerPanel.addRow(content, title);

		// One labelled row per filter, the labels in one column.
		JPanel filters = new JPanel(new GridBagLayout());
		filters.setName("history.filters");
		filters.setBackground(ColorScheme.DARK_GRAY_COLOR);
		monsterFilter.addTo(filters, "Monster", 0);
		locationFilter.addTo(filters, "Location", 1);
		masterFilter.addTo(filters, "Master", 2);
		SlayerLedgerPanel.addRow(content, filters);

		JLabel itemsHint = new JLabel("Click a task to list its supplies and loot.");
		itemsHint.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		itemsHint.setFont(FontManager.getRunescapeSmallFont());
		SlayerLedgerPanel.addRow(content, itemsHint);
		// HTML so the hint wraps in the narrow sidebar.
		JLabel hint = new JLabel("<html>Right-click a task to edit its note or location, or delete it.</html>");
		hint.setName("history.editHint");
		hint.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(hint);

		errorLabel.setName("history.error");
		errorLabel.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		errorLabel.setFont(FontManager.getRunescapeSmallFont());
		errorLabel.setVisible(false);
		SlayerLedgerPanel.addRow(content, errorLabel);

		list.setName("history.list");
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		emptyLabel.setName("history.empty");
		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyLabel.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		emptyLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		showMoreButton.setName("history.showMore");
		showMoreButton.setFocusable(false);
		showMoreButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		showMoreButton.addActionListener(e ->
		{
			if (model.isWaitingForCurrentPrices())
			{
				// The rows stay until today's prices arrive; a click now would not show, so clicks don't pile up.
				return;
			}
			shownLimit += PAGE_SIZE;
			rebuild();
		});
		SlayerLedgerPanel.addRow(content, list);
	}

	/** Forgets the selection and open rows of another account's history. */
	void forgetOtherAccount()
	{
		if (model.account() != shownAccount)
		{
			shownAccount = model.account();
			monsterFilter.selection = null;
			locationFilter.selection = null;
			masterFilter.selection = null;
			shownLimit = PAGE_SIZE;
			expandedRecords.clear();
			listsShowingAll.clear();
		}
	}

	/**
	 * Shows a non-modal error above the history list (for example a failed delete) until the next successful refresh
	 * or the next delete. Ignored if {@code account}'s history is no longer shown.
	 */
	void showError(long account, String message)
	{
		if (account != model.account())
		{
			return;
		}
		errorLabel.setText("<html>" + LedgerHistory.escapeHtml(message) + "</html>");
		errorLabel.setVisible(true);
		relayout.run();
	}

	void clearError()
	{
		if (errorLabel.isVisible())
		{
			errorLabel.setVisible(false);
			relayout.run();
		}
	}

	/**
	 * Rebuilds the filters' choices from the records (and the region names known), keeping each selection while its
	 * value remains. Region names not known yet are asked for; their records' locations follow once they arrive
	 * ({@link #locationNamesChanged}).
	 */
	void rebuildFilter()
	{
		List<LedgerRecord> records = model.records();
		model.requestLocationNames(unnamedRegions(records));
		boolean changed = monsterFilter.setOptions(LedgerHistory.filterOptions(records), LedgerHistory::keepSelection);
		changed |= locationFilter.setOptions(HistoryFilter.locationOptions(records, model::locationName),
			HistoryFilter::keepLocation);
		changed |= masterFilter.setOptions(HistoryFilter.masterOptions(records), LedgerHistory::keepSelection);
		if (changed)
		{
			// A selected value is gone: "All", from its first page.
			shownLimit = PAGE_SIZE;
		}
		monsterFilter.box.setEnabled(!records.isEmpty());
		locationFilter.box.setEnabled(!records.isEmpty());
		masterFilter.box.setEnabled(!records.isEmpty());
	}

	/**
	 * Region names arrived (one changed) or were forgotten: records' locations may differ, so the Location filter's
	 * choices are rebuilt, then the rows.
	 */
	void locationNamesChanged()
	{
		rebuildFilter();
		if (!model.records().isEmpty())
		{
			rebuild();
		}
	}

	/** The regions of the records without a location name of their own: they show their region's name, if any. */
	private static Set<Integer> unnamedRegions(List<LedgerRecord> records)
	{
		Set<Integer> regions = new HashSet<>();
		for (LedgerRecord record : records)
		{
			if (record.getLocation() == null && record.getLocationRegion() != null)
			{
				regions.add(record.getLocationRegion());
			}
		}
		return regions;
	}

	/** The filters as selected now. */
	private HistoryFilter selectedFilter()
	{
		return new HistoryFilter(monsterFilter.selection, locationFilter.selection, masterFilter.selection);
	}

	/**
	 * Rebuilds the first {@link #shownLimit} rows of the filtered records and the "Show N more" button below them, or
	 * shows "No saved tasks yet." (or {@link #NO_MATCHES} when the filters together match no task); while prices are
	 * awaited the rows stay. Region names are asked for every record, as the Location filter needs them.
	 */
	void rebuild()
	{
		if (model.records().isEmpty())
		{
			showEmpty("No saved tasks yet.");
			return;
		}
		if (model.isWaitingForCurrentPrices())
		{
			// The rows shown stay until the prices asked for arrive; the model then has them rebuilt (PRICED_VIEWS).
			return;
		}
		builds++;
		clearRows();
		DateTimeFormatter formatter = LedgerHistory.shortDateTime(ZoneId.systemDefault());
		Map<Integer, Long> prices = model.shownPrices();
		Set<Integer> names = new HashSet<>();
		List<LedgerRecord> filtered = selectedFilter().apply(model.records(), model::locationName);
		model.requestLocationNames(unnamedRegions(model.records()));
		if (filtered.isEmpty())
		{
			showEmpty(NO_MATCHES);
			return;
		}
		int shown = Math.min(shownLimit, filtered.size());
		for (LedgerRecord record : filtered.subList(0, shown))
		{
			if (list.getComponentCount() > 0)
			{
				list.add(Box.createVerticalStrut(4));
			}
			JPanel row = row(model.account(), record,
				HistoryPricing.value(record, model.lootPriceMode(), prices, model.hiddenLoot()), formatter);
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			list.add(row);
			String key = recordKey(record);
			if (expandedRecords.contains(key))
			{
				JPanel details = details(record, prices, names);
				details.setAlignmentX(Component.LEFT_ALIGNMENT);
				list.add(details);
			}
		}
		int left = filtered.size() - shown;
		if (left > 0)
		{
			showMoreButton.setText("Show " + Math.min(PAGE_SIZE, left) + " more");
			showMoreButton.setToolTipText("Showing " + shown + " of " + filtered.size() + " tasks");
			list.add(Box.createVerticalStrut(4));
			list.add(showMoreButton);
		}
		model.requestItemNames(names);
		list.revalidate();
		list.repaint();
	}

	/** Rebuilds the rows once item names arrive, while any row's item details are open. */
	void itemNamesChanged()
	{
		if (!expandedRecords.isEmpty() && !model.records().isEmpty())
		{
			rebuild();
		}
	}

	/** Clears the rows and shows {@code message} instead. */
	void showEmpty(String message)
	{
		clearRows();
		emptyLabel.setText("<html>" + LedgerHistory.escapeHtml(message) + "</html>");
		list.add(emptyLabel);
		list.revalidate();
		list.repaint();
	}

	private void clearRows()
	{
		list.removeAll();
	}

	/** Identifies a record across reloads: its id, or its times for a record without one. */
	static String recordKey(LedgerRecord record)
	{
		return record.getId() != null ? "id:" + record.getId()
			: "t:" + record.getStartedAt() + ":" + record.getEndedAt();
	}

	/** Opens or closes the item details below a saved task, as a click on its row does. */
	private void toggleDetails(LedgerRecord record)
	{
		String key = recordKey(record);
		if (!expandedRecords.remove(key))
		{
			expandedRecords.add(key);
		}
		else
		{
			listsShowingAll.removeIf(k -> k.startsWith(key + "|"));
		}
		rebuild();
	}

	/**
	 * The item details below an open history row: the task's supplies and loot as item icons, at the prices its row
	 * shows (today's GE prices with the saved high-alchemy values, as {@link HistoryPricing} values the totals), or
	 * {@link ItemDetails#NO_ITEM_DETAILS} for a task saved before items were tracked. Ids whose names are needed are
	 * added to {@code names}.
	 */
	private JPanel details(LedgerRecord record, Map<Integer, Long> prices, Set<Integer> names)
	{
		JPanel details = new JPanel();
		details.setName("history.details");
		details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
		details.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		details.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(4, 8, 6, 8)));
		ItemDetails items = ItemDetails.of(record);
		if (items == null)
		{
			details.add(detailsLabel(ItemDetails.NO_ITEM_DETAILS, ColorScheme.LIGHT_GRAY_COLOR));
			addXp(details, record);
			return details;
		}
		items = items.withGePrices(prices);
		details.add(detailsLabel(SlayerLedgerPanel.ITEMS_AT_CURRENT_PRICES, ColorScheme.MEDIUM_GRAY_COLOR));
		ItemGridView supplies = new ItemGridView("Supplies used", false, ColorScheme.DARKER_GRAY_COLOR, icons.getItems());
		supplies.setRows(items.supplyRows(model::itemName));
		ItemGridView loot = new ItemGridView("Loot received", false, ColorScheme.DARKER_GRAY_COLOR, icons.getItems());
		// Without the items Ground Items hides, as the loot value leaves them out.
		loot.setRows(items.withNatureRunePrice(model.natureRunePrice()).lootRows(model.lootPriceMode(),
			model::itemName), model.hiddenLoot());
		addDetailsList(details, supplies);
		addDetailsList(details, loot);
		names.addAll(items.itemIds());
		addXp(details, record);
		return details;
	}

	/**
	 * Adds a saved task's XP, skill by skill with XP per hour of its active time, below its items; nothing for a task
	 * with no XP (or saved before XP was tracked; its row says "XP: -").
	 */
	private void addXp(JPanel details, LedgerRecord record)
	{
		List<SkillXp.Row> rows = SkillXp.rows(record.getXpGained(), record.getActiveMillis());
		if (rows.isEmpty())
		{
			return;
		}
		ItemListView xp = new ItemListView(SkillXp.LIST_TITLE, false, ColorScheme.DARKER_GRAY_COLOR, SkillXp.LIST_NOUN,
			icons.getSkills());
		xp.setRows(rows);
		// Keeps whether the list shows all its skills ("+N more") across rebuilds.
		String listKey = recordKey(record) + "|" + SkillXp.LIST_TITLE;
		xp.setShowAll(listsShowingAll.contains(listKey), shown ->
		{
			if (shown)
			{
				listsShowingAll.add(listKey);
			}
			else
			{
				listsShowingAll.remove(listKey);
			}
		});
		addDetailsList(details, xp);
	}

	/** Adds one list (item icons or XP) to a row's details. */
	private static void addDetailsList(JPanel details, TitledListView<?> itemList)
	{
		itemList.setOpaque(false);
		itemList.setAlignmentX(Component.LEFT_ALIGNMENT);
		itemList.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		details.add(itemList);
	}

	private static JLabel detailsLabel(String text, Color color)
	{
		JLabel label = SlayerLedgerPanel.historyLabel(text, color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private JPanel row(long account, LedgerRecord record, HistoryPricing.Values values, DateTimeFormatter formatter)
	{
		// Exact GE and high-alchemy values, which prices are shown, any that were unavailable, the location and the
		// counts, built when first asked for. The location is in the tooltip only: no row line has room for it
		// in the sidebar.
		JPanel row = new LazyTooltipPanel(new GridLayout(5, 1, 0, 2),
			() -> LedgerHistory.rowTooltip(record, values, recordLocation(record)));
		row.setName("history.row");
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

		JLabel name = SlayerLedgerPanel.historyLabel(LedgerHistory.monster(record), Color.WHITE);
		// A name for tests, which read the icon from it; no visible effect.
		name.setName("history.name");
		SmallItemIcon.applyTask(icons.getItems(), name, record.getMonster());
		row.add(SlayerLedgerPanel.historyLine(name,
			SlayerLedgerPanel.historyLabel(LedgerHistory.status(record),
				record.isCompleted() ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE)));
		row.add(SlayerLedgerPanel.historyLine(
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatEndedAt(record, formatter), ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatDuration(record.getActiveMillis()),
				ColorScheme.LIGHT_GRAY_COLOR)));
		row.add(SlayerLedgerPanel.historyLine(
			SlayerLedgerPanel.historyLabel("Kills: " + LedgerHistory.formatKills(record), ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatProfit(values),
				SlayerLedgerPanel.profitColor(values.getProfit()))));
		row.add(SlayerLedgerPanel.historyLine(
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatLoot(values), ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatSupplies(values), ColorScheme.LIGHT_GRAY_COLOR)));
		// "XP: -" for a task saved before XP was tracked.
		row.add(SlayerLedgerPanel.historyLine(
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatXp(record), ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatXpRate(record), ColorScheme.LIGHT_GRAY_COLOR)));

		// Right-click menu, as in core LootTrackerBox.
		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		JMenuItem editNote = new JMenuItem("Edit note");
		// LedgerStore.updateNote matches by id, like delete.
		editNote.setEnabled(record.getId() != null);
		editNote.addActionListener(e -> promptEditNote(account, record));
		menu.add(editNote);
		JMenuItem editLocation = new JMenuItem("Edit location");
		// LedgerStore.updateLocation matches by id, like the note.
		editLocation.setEnabled(record.getId() != null);
		editLocation.addActionListener(e -> promptEditLocation(account, record));
		menu.add(editLocation);
		JMenuItem delete = new JMenuItem("Delete task");
		// LedgerStore.delete matches by id; a record without one cannot be targeted safely.
		delete.setEnabled(record.getId() != null);
		delete.addActionListener(e -> confirmDelete(account, record));
		menu.add(delete);
		row.setComponentPopupMenu(menu);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				// A left click opens or closes the task's items (once per double click); a right click opens the menu.
				if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1)
				{
					toggleDetails(record);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
		return row;
	}

	/** Asks before deleting a saved record; Cancel or closing the dialog does nothing. */
	private void confirmDelete(long account, LedgerRecord record)
	{
		String[] options = {"Delete", "Cancel"};
		int choice = JOptionPane.showOptionDialog(dialogParent, LedgerHistory.deleteConfirmation(record),
			"Slayer Ledger", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);
		if (choice != 0 || record.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		clearError();
		deleteRecord.accept(account, record.getId());
	}

	/** Asks for a saved record's new note; Cancel or closing the dialog changes nothing, an empty note removes it. */
	private void promptEditNote(long account, LedgerRecord record)
	{
		Object input = JOptionPane.showInputDialog(dialogParent, LedgerHistory.editNotePrompt(record), "Slayer Ledger",
			JOptionPane.PLAIN_MESSAGE, null, null, record.getNote() == null ? "" : record.getNote());
		if (input == null || record.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		String note = TaskNote.normalize(input.toString());
		if (Objects.equals(note, record.getNote()))
		{
			return;
		}
		clearError();
		editNote.apply(account, record.getId(), note);
	}

	/**
	 * Asks for a saved record's location name, starting from the one shown; Cancel or closing the dialog changes
	 * nothing, an empty name removes the record's own name (it then shows its region's name, if any, or "Unknown").
	 */
	private void promptEditLocation(long account, LedgerRecord record)
	{
		String shown = recordLocation(record);
		Object input = JOptionPane.showInputDialog(dialogParent, TaskLocation.editPrompt(record), "Slayer Ledger",
			JOptionPane.PLAIN_MESSAGE, null, null, TaskLocation.UNKNOWN.equals(shown) ? "" : shown);
		if (input == null || record.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		String location = TaskLocation.normalizeName(input.toString());
		if (Objects.equals(location, record.getLocation()))
		{
			return;
		}
		clearError();
		editLocation.apply(account, record.getId(), location);
	}

	/** A saved record's location as the history shows it ({@link TaskLocation#displayName}). */
	private String recordLocation(LedgerRecord record)
	{
		return TaskLocation.displayName(record, model::locationName);
	}

	/**
	 * One filter's labelled drop-down and its selection. Sized from a short prototype, so a long name never
	 * widens the sidebar: it is cut short in the closed box, whose tooltip names the selected value in full, while the
	 * open list widens to fit it ({@link ComboPopupWidener}). Choices show as {@link HistoryFilter#label} names them.
	 */
	private final class FilterChoice
	{
		private final JComboBox<String> box = new JComboBox<>();
		/** What the filter does: the start of the box's tooltip. */
		private final String description;
		/** The choices shown, {@link LedgerHistory#ALL} first. */
		private List<String> options = Collections.singletonList(LedgerHistory.ALL);
		/** Selected value, or {@code null} for "All". */
		private String selection;
		/**
		 * Whether two selections ({@code null} for "All") pick the same records, so a choice spelled anew keeps the
		 * page.
		 */
		private final BiPredicate<String, String> sameChoice;
		/** True while the box's model is being rebuilt, so its change events are ignored. */
		private boolean updating;

		@SuppressWarnings("unchecked")
		private FilterChoice(String name, String description, BiPredicate<String, String> sameChoice)
		{
			this.description = description;
			this.sameChoice = sameChoice;
			box.setName(name);
			box.setFocusable(false);
			// The look and feel's renderer, given each choice's label ("No location" is not a real name).
			ListCellRenderer<Object> renderer = (ListCellRenderer<Object>) box.getRenderer();
			box.setRenderer((JList<? extends String> list, String value, int index, boolean selected, boolean focus) ->
				renderer.getListCellRendererComponent(list, HistoryFilter.label(value), index, selected, focus));
			// Sized from a short name, not the longest choice, so a long one never widens the sidebar.
			box.setPrototypeDisplayValue("Abyssal demons");
			ComboPopupWidener.install(box, ComboPopupWidener.MAX_WIDTH);
			box.setModel(new DefaultComboBoxModel<>(options.toArray(new String[0])));
			updateTooltip();
			box.addActionListener(e ->
			{
				if (updating)
				{
					return;
				}
				int index = box.getSelectedIndex();
				String chosen = index <= 0 ? null : box.getItemAt(index);
				if (!Objects.equals(chosen, selection))
				{
					// Another value: back to the first page.
					shownLimit = PAGE_SIZE;
				}
				selection = chosen;
				updateTooltip();
				rebuild();
			});
		}

		/** Adds the label and the box as row {@code row} of {@code filters} (a {@link GridBagLayout}). */
		private void addTo(JPanel filters, String label, int row)
		{
			JLabel text = new JLabel(label);
			text.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			text.setFont(FontManager.getRunescapeSmallFont());
			int top = row == 0 ? 0 : 4;
			GridBagConstraints c = new GridBagConstraints();
			c.gridx = 0;
			c.gridy = row;
			c.anchor = GridBagConstraints.WEST;
			c.insets = new Insets(top, 0, 0, 6);
			filters.add(text, c);
			c.gridx = 1;
			c.weightx = 1;
			c.fill = GridBagConstraints.HORIZONTAL;
			c.insets = new Insets(top, 0, 0, 0);
			filters.add(box, c);
		}

		/**
		 * Shows {@code newOptions}, keeping the selection as {@code keep} decides ({@code (options, selection)} to the
		 * value kept, {@code null} for "All"). The box's model is replaced only when the choices changed, so an open
		 * list is not disturbed.
		 *
		 * @return whether the selection was dropped or now picks other records (not when only its spelling changed)
		 */
		private boolean setOptions(List<String> newOptions, BiFunction<List<String>, String, String> keep)
		{
			String kept = keep.apply(newOptions, selection);
			boolean changed = !sameChoice.test(kept, selection);
			selection = kept;
			updating = true;
			try
			{
				if (!newOptions.equals(options))
				{
					options = newOptions;
					box.setModel(new DefaultComboBoxModel<>(newOptions.toArray(new String[0])));
				}
				box.setSelectedItem(selection == null ? LedgerHistory.ALL : selection);
			}
			finally
			{
				updating = false;
			}
			updateTooltip();
			return changed;
		}

		/** The description, and the selected value in full (the box may cut it short). */
		private void updateTooltip()
		{
			box.setToolTipText(selection == null ? description
				: "<html>" + LedgerHistory.escapeHtml(description) + ":<br>"
				+ LedgerHistory.escapeHtml(HistoryFilter.label(selection)) + "</html>");
		}
	}

	/**
	 * A history row whose tooltip is built the first time Swing (or a test) asks for it, then kept: the rows are rebuilt
	 * whenever what a tooltip shows changes (the records, their pricing, region names).
	 */
	private static final class LazyTooltipPanel extends JPanel
	{
		private final transient Supplier<String> tooltip;
		private String text;

		private LazyTooltipPanel(GridLayout layout, Supplier<String> tooltip)
		{
			super(layout);
			this.tooltip = tooltip;
			// What setToolTipText does, without building the text.
			ToolTipManager.sharedInstance().registerComponent(this);
		}

		@Override
		public String getToolTipText()
		{
			if (text == null)
			{
				text = tooltip.get();
			}
			return text;
		}

		@Override
		public String getToolTipText(MouseEvent event)
		{
			return getToolTipText();
		}
	}

	/** How many times the rows were built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}
}

package com.shmayvan.slayerledger;

import java.util.Collection;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;

/**
 * Pure valuation of a saved {@link LedgerRecord} for the task history, in a {@link LootPriceMode} and at today's GE
 * prices. No RuneLite dependencies; records are never changed.
 *
 * <p>Every saved task the sidebar shows is valued at today's prices (there is no "saved prices" view any more).
 * The prices saved with a task are still read in two places: its high-alchemy values (which never change), and a
 * {@code null} {@code currentGe}, which values a record at the prices saved with it. In the plugin only the
 * task-complete chat line does that, for the record it has just saved: those prices are today's.</p>
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>A record saved before values were tracked ({@link LedgerHistory#isValued}) has no values, whatever the
 *     mode or prices.</li>
 *     <li><b>Today's prices.</b> The loot and supplies GE totals are recomputed from the record's items at
 *     {@code currentGe} (unit GE prices keyed by the id as tallied); items missing from it are unpriced (the total is
 *     marked {@code ~}), and loot items at 0 count at their high-alchemy value ({@link LootPricing}). High-alchemy
 *     values never change, so the record's stored high-alchemy unit values and totals are used. Supplies stay per
 *     dose or bite. This holds for every record with loot or supply items, also one saved without per-item prices
 *     (neither {@code unitGePrices} nor {@code unitHaPrices}): its GE values are recomputed the same way, and its
 *     high-alchemy values are its saved totals (it has no high-alchemy unit values), as {@link ItemDetails} shows
 *     its items. In High alch mode the loot value of a record with loot items but no {@code unitHaPrices} is that
 *     saved total marked {@code ~}, every loot item counting as unpriced, as its item details show them.</li>
 *     <li><b>Tasks saved without items</b> (no loot or supply items, only totals) can't be revalued: at today's
 *     prices they keep their saved totals ({@link Values#isSavedTotals()}), and a non-zero GE total is marked
 *     {@code ~} because it is not at today's prices. Their high-alchemy total is exact, as high-alchemy values never
 *     change. A record without items whose saved GE totals are 0 has nothing to revalue: it is valued at today's
 *     prices (all 0).</li>
 *     <li><b>Saved prices</b> ({@code currentGe} {@code null}). Supplies and high-alchemy totals are the record's
 *     stored totals. A record with unit prices and items has its loot GE value recomputed per item from its
 *     {@code unitGePrices} and {@code unitHaPrices} ({@link LootPricing}), so an item saved with a GE price of 0
 *     counts at its high-alchemy value; the stored {@code lootGeValue} is left as saved. Any other record uses its
 *     stored loot GE total.</li>
 *     <li>Supplies are always valued at GE prices. Profit is the loot value in the mode minus the supplies.</li>
 *     <li><b>Hidden loot</b>. Loot items Ground Items hides ({@link HiddenLoot}), except coins, are left out of
 *     every loot value and of the unpriced counts, as if they had not dropped; the record itself is unchanged.
 *     They can only be left out where loot is valued per item: a record saved without items keeps its stored
 *     totals, and one saved without high-alchemy unit values its stored high-alchemy total, hidden items
 *     included.</li>
 * </ul>
 */
final class HistoryPricing
{
	/** A record's values as shown in the history. Immutable; build one with {@link #builder()}. */
	@Builder
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Values
	{
		private final LootPriceMode mode;
		private final boolean currentPrices;
		private final boolean savedTotals;
		private final Long lootValue;
		private final Long lootGe;
		private final Long lootHa;
		private final Long suppliesGe;
		private final Long suppliesHa;
		private final int lootUnpriced;
		private final int lootGeUnpriced;
		private final int suppliesUnpriced;

		/** Whether the record has values at all (it was saved after values were tracked). */
		boolean isValued()
		{
			return lootValue != null;
		}

		LootPriceMode getMode()
		{
			return mode;
		}

		/**
		 * Whether the GE values use today's prices: always, but for a {@code null} {@code currentGe} and a record
		 * that can't be revalued ({@link #isSavedTotals()}).
		 */
		boolean isCurrentPrices()
		{
			return currentPrices;
		}

		/**
		 * Whether today's prices were asked for but the record kept no loot or supply items to value, only a non-zero
		 * saved GE total, so its saved totals are used instead; a non-zero one is marked approximate ({@code ~}).
		 */
		boolean isSavedTotals()
		{
			return savedTotals;
		}

		/** Loot value in {@link #getMode()}, or {@code null} when not valued. */
		Long getLootValue()
		{
			return lootValue;
		}

		/** Loot value in {@link LootPriceMode#GE} ({@link LootPricing}), or {@code null} when not valued. */
		Long getLootGe()
		{
			return lootGe;
		}

		Long getLootHa()
		{
			return lootHa;
		}

		/** Supplies GE value: 0 for a valued record without supplies, {@code null} when not valued. */
		Long getSuppliesGe()
		{
			return suppliesGe;
		}

		Long getSuppliesHa()
		{
			return suppliesHa;
		}

		/** Distinct loot items whose price in {@link #getMode()} was unavailable. */
		int getLootUnpriced()
		{
			return lootUnpriced;
		}

		/** Distinct loot items whose GE price was unavailable, so {@link #getLootGe()} is approximate. */
		int getLootGeUnpriced()
		{
			return lootGeUnpriced;
		}

		/** Distinct supply items whose GE price was unavailable. */
		int getSuppliesUnpriced()
		{
			return suppliesUnpriced;
		}

		/**
		 * Whether {@link #getLootValue()} is approximate (shown with {@code ~}): some item had no price, or it is a
		 * non-zero saved GE total ({@link #isSavedTotals()}; high-alchemy values never change).
		 */
		boolean isLootApproximate()
		{
			return lootUnpriced > 0 || (savedTotals && mode != LootPriceMode.HIGH_ALCH && isNonZero(lootValue));
		}

		/** Whether {@link #getSuppliesGe()} is approximate: some item had no price, or a non-zero saved total. */
		boolean isSuppliesApproximate()
		{
			return suppliesUnpriced > 0 || (savedTotals && isNonZero(suppliesGe));
		}

		private static boolean isNonZero(Long value)
		{
			return value != null && value != 0;
		}

		/** Loot value minus supplies, or {@code null} when not valued. */
		Long getProfit()
		{
			return LedgerHistory.profit(lootValue, suppliesGe);
		}

		/** Whether {@link #getProfit()} is approximate. */
		boolean isProfitApproximate()
		{
			return isLootApproximate() || isSuppliesApproximate();
		}
	}

	private HistoryPricing()
	{
	}

	/**
	 * {@code record}'s values in {@code mode}; see the class rules.
	 *
	 * @param currentGe today's GE unit prices keyed by the id as tallied (an item without an entry has no price), or
	 *                  {@code null} to use the prices saved with the record
	 */
	static Values value(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe)
	{
		return value(record, mode, currentGe, HiddenLoot.NONE);
	}

	/**
	 * {@code record}'s values in {@code mode}, without the loot items {@code hidden} hides (coins always count); see
	 * the class rules.
	 *
	 * @param currentGe today's GE unit prices keyed by the id as tallied (an item without an entry has no price), or
	 *                  {@code null} to use the prices saved with the record
	 * @param hidden    loot items left out of the values; {@code null} is none
	 */
	static Values value(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		final LootPriceMode lootMode = mode == null ? LootPriceMode.GE : mode;
		if (!LedgerHistory.isValued(record))
		{
			return Values.builder().mode(lootMode).currentPrices(currentGe != null).build();
		}
		final ItemTally allLoot = ItemTally.fromMap(record.getLoot());
		final ItemTally loot = hidden == null ? allLoot : hidden.valued(allLoot);
		// Whether some loot is left out; only then are the saved totals and counts worked out again per item.
		final boolean hiding = loot != allLoot;
		final ItemTally supplies = record.getSupplies() == null ? null : ItemTally.fromMap(record.getSupplies());
		final Map<Integer, Long> ha = record.getUnitHaPrices();
		final boolean hasUnitPrices = record.getUnitGePrices() != null || ha != null;
		// Today's prices value the record's items; a record without any keeps its saved totals, when there are any.
		final boolean hasItems = !allLoot.isEmpty() || (supplies != null && !supplies.isEmpty());
		final boolean savedTotals = currentGe != null && !hasItems && hasSavedGeTotal(record);
		final boolean current = currentGe != null && !savedTotals;
		final long lootHa = hiding && ha != null ? ItemValuation.total(loot, ha)
			: record.getLootHaValue() != null ? record.getLootHaValue() : 0;
		final long suppliesHa = record.getSuppliesHaValue() != null ? record.getSuppliesHaValue() : 0;

		final long lootGe;
		final long suppliesGe;
		final int lootGeUnpriced;
		final int suppliesUnpriced;
		if (current)
		{
			lootGe = LootPricing.total(loot, LootPriceMode.GE, currentGe, ha, null);
			suppliesGe = ItemValuation.total(supplies, currentGe, record.getSupplyDoses());
			lootGeUnpriced = ItemValuation.countUnpriced(loot, currentGe);
			suppliesUnpriced = ItemValuation.countUnpriced(supplies, currentGe);
		}
		else
		{
			final Map<Integer, Long> ge = record.getUnitGePrices();
			final boolean perItem = hasUnitPrices && hasItems;
			lootGe = perItem ? LootPricing.total(loot, LootPriceMode.GE, ge, ha, null) : record.getLootGeValue();
			suppliesGe = LedgerHistory.suppliesGe(record);
			lootGeUnpriced = hiding && perItem ? ItemValuation.countUnpriced(loot, ge)
				: LedgerHistory.lootUnpriced(record);
			suppliesUnpriced = LedgerHistory.suppliesUnpriced(record);
		}

		long lootValue;
		int lootUnpriced;
		switch (lootMode)
		{
			case HIGH_ALCH:
				lootValue = lootHa;
				// Without high-alchemy unit values every loot item is unpriced, as its details show it, so the saved
				// high-alchemy total of a record with loot items is marked ~.
				lootUnpriced = ItemValuation.countUnpriced(loot, ha);
				break;
			default:
				lootValue = lootGe;
				lootUnpriced = lootGeUnpriced;
				break;
		}
		return Values.builder()
			.mode(lootMode)
			.currentPrices(current)
			.savedTotals(savedTotals)
			.lootValue(lootValue)
			.lootGe(lootGe)
			.lootHa(lootHa)
			.suppliesGe(suppliesGe)
			.suppliesHa(suppliesHa)
			.lootUnpriced(lootUnpriced)
			.lootGeUnpriced(lootGeUnpriced)
			.suppliesUnpriced(suppliesUnpriced)
			.build();
	}

	/** Whether {@code record} was saved with a non-zero loot or supplies GE total. */
	private static boolean hasSavedGeTotal(LedgerRecord record)
	{
		final Long lootGe = record.getLootGeValue();
		final Long suppliesGe = record.getSuppliesGeValue();
		return (lootGe != null && lootGe != 0) || (suppliesGe != null && suppliesGe != 0);
	}

	/** Every distinct item id in the loot and supplies of {@code records}, for one batched price lookup. */
	static Set<Integer> itemIds(Collection<LedgerRecord> records)
	{
		Set<Integer> ids = new TreeSet<>();
		for (LedgerRecord r : records)
		{
			if (r == null)
			{
				continue;
			}
			addKeys(ids, r.getLoot());
			addKeys(ids, r.getSupplies());
		}
		return ids;
	}

	private static void addKeys(Set<Integer> into, Map<Integer, Long> map)
	{
		if (map == null)
		{
			return;
		}
		for (Integer id : map.keySet())
		{
			if (id != null)
			{
				into.add(id);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * How the shown history is valued (split from {@link LedgerHistoryModel}): the "Loot price" mode, today's GE
 * prices received and asked for, the wait for them and its expiry, and {@link #valuationVersion}, bumped whenever
 * any of these changes what the history is worth. Saved tasks are always valued at today's prices (the rules
 * are {@link HistoryPricing}'s).
 *
 * <p>Threading: EDT only, like the model that owns it; the exception is {@link #isWaitingForCurrentPrices}, which reads
 * one volatile field. It only keeps the state: the model decides what a change means (dropping the statistics,
 * re-checking the chat preview) and tells its listener. Callers write through the model.</p>
 */
final class HistoryValuation
{
	/**
	 * How long the views valued at today's prices wait for the prices asked for before they are redrawn with the
	 * prices there are.
	 */
	static final long CURRENT_PRICES_WAIT_MILLIS = 3_000;

	/** Asks the plugin for today's GE prices of item ids (EDT). */
	private final Consumer<Set<Integer>> currentPriceRequests;
	/** How loot is valued (the "Loot price" setting). */
	private LootPriceMode lootPriceMode;
	/**
	 * Today's GE unit prices received from the plugin this session, by item id as tallied; items whose price was
	 * unavailable have no entry (and are asked for again when the records change).
	 */
	private final Map<Integer, Long> currentPrices = new HashMap<>();
	/** {@link #currentPrices}, read-only, as handed to the views. */
	private final Map<Integer, Long> shownPrices = Collections.unmodifiableMap(currentPrices);
	/** Ids asked for whose answer has not arrived yet, so they are not asked for twice. */
	private final Set<Integer> currentPricesPending = new HashSet<>();
	/**
	 * While the views wait for today's prices: ids whose answer came back without a price and that the plugin is
	 * looking up again ({@link PriceRetry}), for example because RuneLite's price list had not loaded yet at client
	 * start. The wait goes on until they arrive too, or the wait runs out; emptied whenever the wait ends.
	 */
	private final Set<Integer> currentPricesRetrying = new HashSet<>();
	/**
	 * Whether the views valued at today's prices keep what they show until the prices asked for arrive, instead of
	 * briefly showing {@code ~} and lower totals for the items not priced yet. Never longer than
	 * {@link #CURRENT_PRICES_WAIT_MILLIS}. Written on the EDT only; volatile so the plugin may check it on the client
	 * thread ({@link #isWaitingForCurrentPrices}).
	 */
	private volatile boolean waitingForCurrentPrices;
	/** When {@link #waitingForCurrentPrices} began ({@link System#nanoTime}). */
	private long waitingForCurrentPricesSince;
	/**
	 * Loot items left out of the loot value, worked out by the model from Ground Items' hidden list and the
	 * item names.
	 */
	private HiddenLoot hiddenLoot = HiddenLoot.NONE;
	/** Bumped whenever how the history is valued changes: the mode, today's prices or the hidden loot. */
	private long valuationVersion;

	/**
	 * @param lootPriceMode        the "Loot price" mode; {@code null} is GE
	 * @param currentPriceRequests asks the plugin for today's GE prices of item ids (EDT)
	 */
	HistoryValuation(LootPriceMode lootPriceMode, Consumer<Set<Integer>> currentPriceRequests)
	{
		this.lootPriceMode = lootPriceMode == null ? LootPriceMode.GE : lootPriceMode;
		this.currentPriceRequests = currentPriceRequests;
	}

	LootPriceMode lootPriceMode()
	{
		return lootPriceMode;
	}

	/** Sets the "Loot price" mode ({@code null} is GE); returns whether it changed, which bumps the version. */
	boolean setLootPriceMode(LootPriceMode mode)
	{
		LootPriceMode newMode = mode == null ? LootPriceMode.GE : mode;
		if (newMode == lootPriceMode)
		{
			return false;
		}
		lootPriceMode = newMode;
		valuationVersion++;
		return true;
	}

	/** Loot items left out of the loot value; never {@code null}. */
	HiddenLoot hiddenLoot()
	{
		return hiddenLoot;
	}

	/**
	 * Sets the loot items left out of the loot value ({@code null} is none); returns whether they changed, which bumps
	 * the version.
	 */
	boolean setHiddenLoot(HiddenLoot hidden)
	{
		HiddenLoot h = hidden == null ? HiddenLoot.NONE : hidden;
		if (h.equals(hiddenLoot))
		{
			return false;
		}
		hiddenLoot = h;
		valuationVersion++;
		return true;
	}

	/**
	 * Today's GE prices to value the history at: read-only, never {@code null}, and changing as prices arrive (copy it
	 * to keep it). An item without an entry has no price yet, so it is left out and its total marked {@code ~}.
	 */
	Map<Integer, Long> shownPrices()
	{
		return shownPrices;
	}

	/**
	 * Asks the plugin (once, in one batch) for today's GE price of every item in {@code records} that has none yet and
	 * is not already asked for.
	 */
	void requestCurrentPrices(List<LedgerRecord> records)
	{
		Set<Integer> ids = HistoryPricing.itemIds(records);
		ids.removeAll(currentPrices.keySet());
		ids.removeAll(currentPricesPending);
		if (!ids.isEmpty())
		{
			currentPricesPending.addAll(ids);
			currentPriceRequests.accept(ids);
		}
	}

	/**
	 * Adds today's GE prices the plugin looked up ({@code prices}, for those of {@code requested} that it found);
	 * {@code requested} is no longer pending. While the views wait for prices, the ids of {@code retrying} (those the
	 * plugin looks up again, {@link PriceRetry}) keep the wait going until they arrive ({@link #isWaitOver}). Bumps
	 * the version, so the cached views are worked out again, only when some price is new or changed; returns whether
	 * it did.
	 *
	 * @param retrying ids of {@code requested} that came back without a price and are looked up again; may be empty
	 */
	boolean addCurrentPrices(Set<Integer> requested, Map<Integer, Long> prices, Set<Integer> retrying)
	{
		currentPricesPending.removeAll(requested);
		currentPricesRetrying.removeAll(prices.keySet());
		if (waitingForCurrentPrices)
		{
			for (Integer id : retrying)
			{
				if (!prices.containsKey(id))
				{
					currentPricesRetrying.add(id);
				}
			}
		}
		boolean changed = false;
		for (Map.Entry<Integer, Long> e : prices.entrySet())
		{
			Long old = currentPrices.put(e.getKey(), e.getValue());
			changed |= !Objects.equals(e.getValue(), old);
		}
		if (changed)
		{
			valuationVersion++;
		}
		return changed;
	}

	/** Whether some prices asked for have not arrived yet. */
	boolean isCurrentPricesPending()
	{
		return !currentPricesPending.isEmpty();
	}

	/**
	 * Whether a wait for today's prices may end: every price asked for has been answered, and none that came back
	 * unavailable is still being looked up again.
	 */
	boolean isWaitOver()
	{
		return currentPricesPending.isEmpty() && currentPricesRetrying.isEmpty();
	}

	/**
	 * After {@link #requestCurrentPrices}: whether the views valued at today's prices should keep what they show until
	 * the prices asked for arrive (some asked for are on their way, or, in a wait that already began, are being looked
	 * up again). Starts the wait, or keeps one that already began; ends it otherwise.
	 */
	boolean waitForCurrentPrices()
	{
		if (isWaitOver())
		{
			stopWaiting();
			return false;
		}
		if (!waitingForCurrentPrices)
		{
			waitingForCurrentPrices = true;
			waitingForCurrentPricesSince = System.nanoTime();
		}
		return true;
	}

	/**
	 * Whether the views valued at today's prices keep what they show until the prices asked for arrive. Any
	 * thread (one volatile read).
	 */
	boolean isWaitingForCurrentPrices()
	{
		return waitingForCurrentPrices;
	}

	/** Ends any wait for today's prices; the prices being looked up again no longer hold anything back. */
	void stopWaiting()
	{
		waitingForCurrentPrices = false;
		currentPricesRetrying.clear();
	}

	/**
	 * Whether a wait for today's prices has lasted {@link #CURRENT_PRICES_WAIT_MILLIS} (an answer never came, or a
	 * price looked up again was still unavailable); if so, the pending ids are forgotten so the missing prices may be
	 * asked for again, and the caller ends the wait.
	 */
	boolean currentPricesWaitExpired()
	{
		if (waitingForCurrentPrices && System.nanoTime() - waitingForCurrentPricesSince
			>= TimeUnit.MILLISECONDS.toNanos(CURRENT_PRICES_WAIT_MILLIS))
		{
			currentPricesPending.clear();
			currentPricesRetrying.clear();
			return true;
		}
		return false;
	}

	/** Test seam: lets a wait for today's prices run out at once, as if no answer came in time. */
	void expireCurrentPricesWait()
	{
		waitingForCurrentPricesSince -= TimeUnit.MILLISECONDS.toNanos(CURRENT_PRICES_WAIT_MILLIS);
	}

	/** Bumped whenever how the history is valued changes: the mode, today's prices or the hidden loot. */
	long valuationVersion()
	{
		return valuationVersion;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.runelite.client.util.WildcardMatcher;

/**
 * The player's "Ignored loot" setting, parsed: items left out of kill loot when it is captured. Pure: names are passed
 * in by the plugin, which reads them from item compositions on the client thread.
 *
 * <p>The setting is a comma-separated list. An entry of only digits is an item id; any other entry is an item name,
 * matched case-insensitively, in which {@code *} matches any run of characters (RuneLite's {@link WildcardMatcher}, as
 * used by the core Ground Items plugin). Blank entries are skipped. A noted item matches through its unnoted item: its
 * unnoted id and name.</p>
 *
 * <p>Immutable, so a parsed list can be shared between threads.</p>
 */
final class IgnoredLoot
{
	/** Ignores nothing. */
	static final IgnoredLoot NONE = new IgnoredLoot(Collections.emptySet(), Collections.emptyList());

	private final Set<Integer> ids;
	/** Name patterns, lower-cased and trimmed. */
	private final List<String> names;

	private IgnoredLoot(Set<Integer> ids, List<String> names)
	{
		this.ids = ids;
		this.names = names;
	}

	/**
	 * Parses the setting.
	 *
	 * @param setting the comma-separated list, or {@code null}
	 */
	static IgnoredLoot parse(String setting)
	{
		if (setting == null || setting.trim().isEmpty())
		{
			return NONE;
		}
		final Set<Integer> ids = new HashSet<>();
		final List<String> names = new ArrayList<>();
		for (String raw : setting.split(","))
		{
			final String entry = raw.trim();
			if (entry.isEmpty())
			{
				continue;
			}
			if (entry.chars().allMatch(c -> c >= '0' && c <= '9'))
			{
				try
				{
					ids.add(Integer.parseInt(entry));
					continue;
				}
				catch (NumberFormatException e)
				{
					// Too large to be an item id; then it can only match a name.
				}
			}
			final String name = entry.toLowerCase(Locale.ROOT);
			if (!names.contains(name))
			{
				names.add(name);
			}
		}
		if (ids.isEmpty() && names.isEmpty())
		{
			return NONE;
		}
		return new IgnoredLoot(Collections.unmodifiableSet(ids), Collections.unmodifiableList(names));
	}

	/** Whether nothing is ignored (so no item names need to be looked up). */
	boolean isEmpty()
	{
		return ids.isEmpty() && names.isEmpty();
	}

	/** Whether any entry is a name (so item names need to be looked up). */
	boolean hasNames()
	{
		return !names.isEmpty();
	}

	/**
	 * Whether a dropped item is ignored.
	 *
	 * @param itemId         the item id as dropped (possibly noted)
	 * @param unnotedId      the unnoted item's id ({@code itemId} itself when not noted)
	 * @param unnotedName    the unnoted item's name, or {@code null} when unknown (then only ids can match)
	 */
	boolean ignores(int itemId, int unnotedId, String unnotedName)
	{
		if (ids.contains(itemId) || ids.contains(unnotedId))
		{
			return true;
		}
		if (unnotedName == null)
		{
			return false;
		}
		final String name = unnotedName.trim();
		for (String pattern : names)
		{
			if (WildcardMatcher.matches(pattern, name))
			{
				return true;
			}
		}
		return false;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Value;

/**
 * Pure: a task's supplies and loot item by item, for the panel's item grids. No RuneLite dependencies; item
 * names come from an injected {@link ItemNames} (the plugin resolves them through {@code ItemManager} on the client
 * thread, and the panel passes what it has received).
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>One row per item id as tallied (a noted drop is its own row). Quantities in doses, bites or charges (ids in
 *     the supply doses, see {@link LedgerRecord#getSupplyDoses()}) show as "N doses", "N bites" or "N charges"; the
 *     word comes from {@link SupplyTracker#MULTI_BITE_FOOD} and {@link SupplyTracker#CHARGED_ITEMS}, any other is a
 *     potion. Their names drop the "(4)" dose or charge suffix of the item they are keyed by.</li>
 *     <li>Supplies are valued at GE prices, per dose, bite or charge ({@link ItemValuation#total(ItemTally, Map, Map)});
 *     loot in the {@link LootPriceMode}, with a GE price of 0 at high alch ({@link LootPricing}). The values are the
 *     same per-item amounts the totals add up. An item without the price shows as unavailable in its tooltip.</li>
 *     <li>Rows are sorted by value, highest first; unpriced rows come last; ties by name (ignoring case), then id.</li>
 *     <li>A loot row gets the alch hint ({@link #ALCH_MARKER}) when its high alch unit value, less the nature rune
 *     the cast uses, is above its GE unit price ({@link #alchBeatsGe}). Untradeables (GE 0), items without either
 *     price, and every item while the nature rune price is unknown never get it.</li>
 *     <li>The panel shows every row as an item icon ({@link ItemGridView}). A text list (the XP lists) shows at most
 *     {@link #MAX_ROWS} rows until the player asks for all ({@link #visible}).</li>
 * </ul>
 *
 * <p>Immutable.</p>
 */
final class ItemDetails
{
	/** Rows a text list ({@link ItemListView}, the XP lists) shows before "+N more". */
	static final int MAX_ROWS = 10;
	/** Value of an item whose price is unavailable. */
	static final String UNPRICED = "?";
	/** Shown for a saved task that has no item data (saved before loot and supplies were tracked). */
	static final String NO_ITEM_DETAILS = "No item details";
	/**
	 * Names the alch hint in the tooltip of a loot item whose high alch value beats its GE price (its icon has an
	 * orange border). Not "(HA)", which the panel uses for the "Loot price" setting.
	 */
	static final String ALCH_MARKER = "(alch)";
	/** Details without any items. */
	static final ItemDetails EMPTY = new ItemDetails(null, null, null, null, null, null);

	/** Item names, as far as they are known. */
	interface ItemNames
	{
		/** The item's name, or {@code null} while it is unknown. */
		String name(int itemId);
	}

	/** How a row's quantity is counted. */
	enum Unit
	{
		ITEMS(null, null),
		DOSES("dose", "doses"),
		BITES("bite", "bites"),
		CHARGES("charge", "charges");

		private final String one;
		private final String many;

		Unit(String one, String many)
		{
			this.one = one;
			this.many = many;
		}

		/** The word for one ("dose"), or {@code null} for {@link #ITEMS}. */
		String getOne()
		{
			return one;
		}

		/** The word for several ("doses"), or {@code null} for {@link #ITEMS}. */
		String getMany()
		{
			return many;
		}
	}

	/** One line of an item list. */
	@Value
	@Builder(toBuilder = true)
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static class Row
	{
		int itemId;
		/** Name to show (never {@code null}). */
		String name;
		long quantity;
		Unit unit;
		/** Value of the whole quantity, or {@code null} when the price is unavailable. */
		Long value;
		/** What {@link #value} is: "GE" or "high alch". */
		String priceName;
		/** GE unit price (per item, not per dose) as saved or looked up, or {@code null} when unavailable. */
		Long unitGe;
		/** High alch unit value, or {@code null} when unavailable. */
		Long unitHa;
		/** Doses (bites, charges) in one item for {@link #unitGe}, or {@code null}. */
		Integer dosesPerItem;
		/**
		 * Whether to show the alch hint (the icon's orange border, and {@link #ALCH_MARKER} in the tooltip): loot whose
		 * high alch value beats its GE price.
		 */
		boolean alchHint;
		/**
		 * Whether {@link #value} leaves out part of the quantity, whose price was unavailable: only in rows summed over
		 * several tasks ({@link ItemSums}), when some of them had the price and others not.
		 */
		boolean approximate;

		/** "x14", or "22 doses" for an item counted in doses, bites or charges. */
		String quantityText()
		{
			if (unit == Unit.ITEMS)
			{
				return "x" + LedgerHistory.formatAmount(quantity, false);
			}
			return LedgerHistory.formatAmount(quantity, false) + " " + (quantity == 1 ? unit.one : unit.many);
		}

		/** The value without " gp" (as in history rows), or {@link #UNPRICED}. */
		String valueText()
		{
			return value == null ? UNPRICED : LedgerHistory.formatAmount(value, approximate);
		}

		/**
		 * HTML tooltip of the item's icon: the full name, the exact quantity and value, the unit prices and, if shown,
		 * the alch hint.
		 */
		String tooltip()
		{
			StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(name));
			sb.append("<br>Quantity: ").append(String.format("%,d", quantity));
			if (unit != Unit.ITEMS)
			{
				sb.append(' ').append(quantity == 1 ? unit.one : unit.many);
			}
			sb.append("<br>Value (").append(priceName).append("): ")
				.append(value == null ? "unavailable"
					: (approximate ? LedgerHistory.APPROXIMATE : "") + LedgerHistory.formatGpExact(value));
			sb.append("<br>GE: ").append(geText());
			sb.append("<br>High alch: ").append(unitHa == null ? "unavailable" : LedgerHistory.formatGpExact(unitHa)
				+ " each");
			if (alchHint)
			{
				sb.append("<br>").append(ALCH_MARKER).append(" High alch, less a nature rune, is worth more than")
					.append("<br>the GE price. GE tax not included.");
			}
			return sb.append("</html>").toString();
		}

		private String geText()
		{
			if (unitGe == null)
			{
				return "unavailable";
			}
			if (unitGe == 0)
			{
				return "untradeable";
			}
			String each = LedgerHistory.formatGpExact(unitGe) + " each";
			if (dosesPerItem != null && unit != Unit.ITEMS)
			{
				return each + " (" + dosesPerItem + " " + (dosesPerItem == 1 ? unit.one : unit.many) + ")";
			}
			return each;
		}
	}

	/** Highest value first; unpriced last; then by name ignoring case, then id. */
	static final Comparator<Row> BY_VALUE = Comparator
		.comparing((Row r) -> r.getValue() == null)
		.thenComparing(r -> r.getValue() == null ? 0L : r.getValue(), Comparator.reverseOrder())
		.thenComparing(Row::getName, String.CASE_INSENSITIVE_ORDER)
		.thenComparingInt(Row::getItemId);

	private final Map<Integer, Long> loot;
	private final Map<Integer, Long> supplies;
	private final Map<Integer, Integer> doses;
	private final Map<Integer, Long> ge;
	private final Map<Integer, Long> ha;
	/** The GE price of the nature rune a high alch uses, or {@code null} while unknown (then no alch hint). */
	private final Long natureRunePrice;

	private ItemDetails(Map<Integer, Long> loot, Map<Integer, Long> supplies, Map<Integer, Integer> doses,
		Map<Integer, Long> ge, Map<Integer, Long> ha, Long natureRunePrice)
	{
		this.loot = copy(loot);
		this.supplies = copy(supplies);
		this.doses = copy(doses);
		this.ge = copy(ge);
		this.ha = copy(ha);
		this.natureRunePrice = natureRunePrice;
	}

	/**
	 * A live session's items: its tallies and the unit prices it is valued at (keyed by the id as tallied, as in
	 * {@link ItemValuation.UnitPrices}). Everything is copied.
	 */
	static ItemDetails of(ItemTally loot, ItemTally supplies, Map<Integer, Integer> doses, Map<Integer, Long> ge,
		Map<Integer, Long> ha)
	{
		return new ItemDetails(loot == null ? null : loot.toMap(), supplies == null ? null : supplies.toMap(), doses,
			ge, ha, null);
	}

	/**
	 * A saved task's items at the prices saved with it, or {@code null} when it has no item data: saved before loot
	 * and supplies were tracked (not valued, and neither loot nor supplies stored).
	 */
	static ItemDetails of(LedgerRecord record)
	{
		if (record == null || !LedgerHistory.isValued(record) && record.getLoot() == null
			&& record.getSupplies() == null)
		{
			return null;
		}
		return new ItemDetails(record.getLoot(), record.getSupplies(), record.getSupplyDoses(),
			record.getUnitGePrices(), record.getUnitHaPrices(), null);
	}

	/**
	 * These items at other GE unit prices ({@code currentGe}, keyed by the id as tallied; an id without an entry has no
	 * price), as the history values them at today's prices ({@link HistoryPricing}); the high alch values stay.
	 */
	ItemDetails withGePrices(Map<Integer, Long> currentGe)
	{
		return new ItemDetails(loot, supplies, doses, currentGe, ha, natureRunePrice);
	}

	/** These items with the nature rune's GE price for the alch hint ({@code null} or not positive: unknown). */
	ItemDetails withNatureRunePrice(Long price)
	{
		return new ItemDetails(loot, supplies, doses, ge, ha, price != null && price > 0 ? price : null);
	}

	/** Every item id in the loot and supplies, for one name lookup. */
	Set<Integer> itemIds()
	{
		Set<Integer> ids = new TreeSet<>(loot.keySet());
		ids.addAll(supplies.keySet());
		return ids;
	}

	boolean hasLoot()
	{
		return !loot.isEmpty();
	}

	boolean hasSupplies()
	{
		return !supplies.isEmpty();
	}

	/** The supplies, valued at GE prices per dose, bite or charge, sorted by {@link #BY_VALUE}. */
	List<Row> supplyRows(ItemNames names)
	{
		List<Row> rows = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : supplies.entrySet())
		{
			int id = e.getKey();
			Integer perItem = doses.get(id);
			Unit unit = perItem == null ? Unit.ITEMS : doseUnit(id);
			Long unitGe = ge.get(id);
			rows.add(Row.builder()
				.itemId(id)
				.name(displayName(id, names, unit != Unit.ITEMS))
				.quantity(e.getValue())
				.unit(unit)
				.value(value(id, e.getValue(), unitGe, doses))
				.priceName("GE")
				.unitGe(unitGe)
				.unitHa(ha.get(id))
				.dosesPerItem(perItem)
				.alchHint(false)
				.build());
		}
		rows.sort(BY_VALUE);
		return rows;
	}

	/** The loot, valued in {@code mode} ({@link LootPricing}), sorted by {@link #BY_VALUE}, with the alch hint. */
	List<Row> lootRows(LootPriceMode mode, ItemNames names)
	{
		LootPriceMode lootMode = mode == null ? LootPriceMode.GE : mode;
		Map<Integer, Long> prices = LootPricing.unitPrices(lootMode, ge, ha);
		String priceName = lootMode == LootPriceMode.HIGH_ALCH ? "high alch" : "GE";
		List<Row> rows = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : loot.entrySet())
		{
			int id = e.getKey();
			Long unitGe = ge.get(id);
			Long unitHa = ha.get(id);
			rows.add(Row.builder()
				.itemId(id)
				.name(displayName(id, names, false))
				.quantity(e.getValue())
				.unit(Unit.ITEMS)
				.value(value(id, e.getValue(), prices.get(id), null))
				.priceName(priceName)
				.unitGe(unitGe)
				.unitHa(unitHa)
				.dosesPerItem(null)
				.alchHint(alchBeatsGe(unitGe, unitHa, natureRunePrice))
				.build());
		}
		rows.sort(BY_VALUE);
		return rows;
	}

	/**
	 * Whether alching beats selling: the high alch unit value, less the nature rune the cast uses, is above a known,
	 * non-zero GE unit price. An untradeable item (GE 0, already valued at high alch), an item missing either price,
	 * and any item while the nature rune price is unknown never qualify. The GE tax is not counted.
	 */
	static boolean alchBeatsGe(Long unitGe, Long unitHa, Long natureRunePrice)
	{
		return unitGe != null && unitHa != null && natureRunePrice != null && unitGe > 0
			&& unitHa - natureRunePrice > unitGe;
	}

	/**
	 * Rows worked out without names ({@link ItemSums#rows()}, Overall totals), as {@link #supplyRows} or
	 * {@link #lootRows} would show them: named through {@code names} and, for {@code loot}, given the alch hint at
	 * {@code natureRunePrice} ({@code null} or not positive: unknown, no hint). Sorted by {@link #BY_VALUE}.
	 */
	static List<Row> named(List<Row> rows, ItemNames names, Long natureRunePrice, boolean loot)
	{
		Long nature = natureRunePrice != null && natureRunePrice > 0 ? natureRunePrice : null;
		List<Row> result = new ArrayList<>(rows.size());
		for (Row row : rows)
		{
			result.add(row.toBuilder()
				.name(displayName(row.getItemId(), names, row.getUnit() != Unit.ITEMS))
				.alchHint(loot && alchBeatsGe(row.getUnitGe(), row.getUnitHa(), nature))
				.build());
		}
		result.sort(BY_VALUE);
		return result;
	}

	/** The rows to show: all of them when {@code showAll}, otherwise the first {@link #MAX_ROWS}. */
	static <T> List<T> visible(List<T> rows, boolean showAll)
	{
		if (showAll || rows.size() <= MAX_ROWS)
		{
			return rows;
		}
		return rows.subList(0, MAX_ROWS);
	}

	/** Rows left out by {@link #visible} when not showing all (0 when they all fit). */
	static int hiddenCount(int rows)
	{
		return Math.max(0, rows - MAX_ROWS);
	}

	/** The quantity word of a dose-counted supply id: bites, charges, or doses (potions). */
	static Unit doseUnit(int itemId)
	{
		if (SupplyTracker.MULTI_BITE_FOOD.containsKey(itemId))
		{
			return Unit.BITES;
		}
		if (SupplyTracker.CHARGED_ITEMS.containsKey(itemId))
		{
			return Unit.CHARGES;
		}
		return Unit.DOSES;
	}

	/**
	 * The name to show: the looked-up name, without a trailing "(4)" for an item counted in doses, bites or charges
	 * (its row counts doses, not that item); "Item &lt;id&gt;" while the name is unknown.
	 */
	static String displayName(int itemId, ItemNames names, boolean perDose)
	{
		String name = names == null ? null : names.name(itemId);
		if (name == null || name.trim().isEmpty())
		{
			return "Item " + itemId;
		}
		if (perDose)
		{
			String stripped = name.replaceFirst("(\\s*\\([a-z]?\\d+\\)|\\s+\\d+)$", "");
			return stripped.isEmpty() ? name : stripped;
		}
		return name;
	}

	/** One item's value as the totals count it, or {@code null} without a unit price. */
	private static Long value(int id, long quantity, Long unitPrice, Map<Integer, Integer> doses)
	{
		if (unitPrice == null)
		{
			return null;
		}
		ItemTally one = new ItemTally();
		one.add(id, quantity);
		return ItemValuation.total(one, Collections.singletonMap(id, unitPrice), doses);
	}

	private static <V> Map<Integer, V> copy(Map<Integer, V> map)
	{
		Map<Integer, V> result = new TreeMap<>();
		if (map != null)
		{
			for (Map.Entry<Integer, V> e : map.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null)
				{
					result.put(e.getKey(), e.getValue());
				}
			}
		}
		return Collections.unmodifiableMap(result);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof ItemDetails))
		{
			return false;
		}
		ItemDetails d = (ItemDetails) o;
		return loot.equals(d.loot) && supplies.equals(d.supplies) && doses.equals(d.doses) && ge.equals(d.ge)
			&& ha.equals(d.ha);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(loot, supplies, doses, ge, ha);
	}

	@Override
	public String toString()
	{
		return "ItemDetails{loot=" + loot + ", supplies=" + supplies + ", doses=" + doses + "}";
	}
}

package com.shmayvan.slayerledger;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;

/**
 * Supplies or loot as a grid of item icons, {@value #COLUMNS} to a row like RuneLite's Loot Tracker, in the
 * rows' order ({@link ItemDetails#BY_VALUE}). Each icon has its quantity drawn on it (a dose, bite or charge count for
 * items counted that way; the tooltip says which), and the row's tooltip ({@link ItemDetails.Row#tooltip()}: the full
 * name, exact quantity, value, unit prices and why the alch hint is shown). Loot whose high alch beats its GE price
 * (the alch hint, {@link ItemDetails#ALCH_MARKER}) gets a thin orange border. Every item is shown: five to a row keep
 * long lists short, so there is no "+N more". The title, "None" and opening and closing are
 * {@link TitledListView}'s. Loot grids leave out the items Ground Items hides, coins included
 * ({@link #setRows(List, HiddenLoot)}). EDT only.
 */
final class ItemGridView extends TitledListView<ItemDetails.Row>
{
	/** Icons per row, as in Loot Tracker. */
	static final int COLUMNS = 5;
	/** Height of a cell: an item sprite (32 px) and the 1 px border above and below it. */
	static final int CELL_HEIGHT = 34;
	/** The alch hint's border. */
	static final Color ALCH_BORDER_COLOR = ColorScheme.BRAND_ORANGE;
	/** Background of a cell, lighter than the list's so the slots stand out. */
	private static final Color CELL_BACKGROUND = ColorScheme.DARK_GRAY_COLOR;

	private final ItemIcons icons;

	ItemGridView(String title, boolean collapsible, Color background, ItemIcons icons)
	{
		super(title, collapsible, background, "items");
		this.icons = icons;
		rebuild();
	}

	/**
	 * Shows the rows {@code hidden} does not hide ({@code null}: all of them), and how many it hides in the title and
	 * the header's tooltip.
	 */
	void setRows(List<ItemDetails.Row> rows, HiddenLoot hidden)
	{
		List<ItemDetails.Row> shown = hidden == null ? rows : hidden.visibleRows(rows);
		setRows(shown, rows.size() - shown.size());
	}

	@Override
	String hiddenNote(int hidden)
	{
		return (hidden == 1 ? "1 item is" : hidden + " items are") + " hidden by your Ground Items<br>hidden list;"
			+ " hidden items<br>are left out of loot value, except coins.";
	}

	@Override
	void fillBody(JPanel body, List<ItemDetails.Row> shown)
	{
		JPanel grid = new JPanel(new GridLayout(0, COLUMNS, 1, 1));
		// Names for tests, which find the cells from the list itself; no visible effect.
		grid.setName("itemGrid.grid");
		grid.setOpaque(false);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (ItemDetails.Row row : shown)
		{
			grid.add(cell(row));
		}
		// Empty slots fill the last row, as in Loot Tracker.
		for (int i = shown.size(); i % COLUMNS != 0; i++)
		{
			grid.add(slot(new JLabel(), BorderFactory.createEmptyBorder(1, 1, 1, 1)));
		}
		body.add(grid);
	}

	private JLabel cell(ItemDetails.Row row)
	{
		JLabel cell = slot(new JLabel(), row.isAlchHint()
			? BorderFactory.createLineBorder(ALCH_BORDER_COLOR, 1)
			: BorderFactory.createEmptyBorder(1, 1, 1, 1));
		cell.setName("itemGrid.cell");
		cell.setToolTipText(row.tooltip());
		icons.apply(cell, row.getItemId(), iconQuantity(row.getQuantity()));
		return cell;
	}

	/**
	 * A slot of the grid. Its preferred width is minimal, so the grid never widens the sidebar: the grid takes the
	 * list's width and its five columns share it (about 38 px each in the sidebar, room for a 36 px sprite).
	 */
	private static JLabel slot(JLabel label, Border border)
	{
		label.setOpaque(true);
		label.setBackground(CELL_BACKGROUND);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setVerticalAlignment(SwingConstants.CENTER);
		label.setBorder(border);
		label.setPreferredSize(new Dimension(1, CELL_HEIGHT));
		return label;
	}

	/** The quantity to draw on an icon: the row's, capped to an {@code int} (the game shortens it, "10M"). */
	static int iconQuantity(long quantity)
	{
		return (int) Math.max(0, Math.min(Integer.MAX_VALUE, quantity));
	}
}

package com.shmayvan.slayerledger;

import javax.swing.JLabel;

/**
 * Where the sidebar's item icons ({@link ItemGridView}) come from. The plugin backs it with RuneLite's
 * {@code ItemManager} ({@link SlayerLedgerPlugin#applyItemIcon}); tests pass a fake. Called on the EDT.
 */
@FunctionalInterface
interface ItemIcons
{
	/**
	 * Puts the icon of {@code itemId} (a noted id shows as a note) on {@code label}, with {@code quantity} drawn on it
	 * when it is above 1. The icon may be drawn later; the label is repainted when it is.
	 */
	void apply(JLabel label, int itemId, int quantity);
}

package com.shmayvan.slayerledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A text list of the sidebar ({@link TitledListView}): one line per {@link ItemListView.Line}, a small skill icon
 * ({@link SkillIcons}, as RuneLite's XP tracker shows), the name (cut short, with the full name in the tooltip) and the
 * amount on the right. Every line keeps an icon-sized slot before its name, empty for a line with no skill, so the
 * names stay aligned and the lines keep one height. A line can show a small item sprite in the slot instead
 * ({@link Line#getIconItemId}, {@link SmallItemIcon}; Overall totals' monsters assigned). At most
 * {@link ItemDetails#MAX_ROWS} lines show until "+N more" is clicked. The per-skill XP lists use it, with
 * {@link SkillXp.Row} lines; supplies and loot are item icons ({@link ItemGridView}). EDT only.
 */
class ItemListView extends TitledListView<ItemListView.Line>
{
	/** One line of a list: a name on the left, an amount on the right and a tooltip. */
	interface Line
	{
		/** Name to show (never {@code null}); cut short when too long. */
		String getName();

		/**
		 * Key of the skill whose small icon shows before the name (the name of RuneLite's {@code Skill} constant), or
		 * {@code null} for none.
		 */
		String getSkill();

		/**
		 * Item whose sprite shows small in the icon slot when the line has no skill, or {@code null} for none
		 * (the slot stays empty).
		 */
		default Integer getIconItemId()
		{
			return null;
		}

		/** Right-aligned amount text. */
		String amountText();

		/** HTML tooltip of the line. */
		String tooltip();
	}

	/**
	 * Width of the icon slot before a name: the small skill icons are 16 px wide (Ranged 18 px; checked against
	 * RuneLite 1.13.4's {@code skill_icons_small}).
	 */
	static final int ICON_WIDTH = 18;
	/** Height of the icon slot, as in the XP tracker's compact rows; Ranged's 18 px icon loses a pixel at each edge. */
	static final int ICON_HEIGHT = 16;

	/** What the lines are ("skills"), for the tooltips. */
	private final String noun;
	private final SkillIcons icons;
	/** Draws the item sprites of lines with {@link Line#getIconItemId}. */
	private final ItemIcons itemIcons;
	private final JLabel moreLabel = new JLabel();
	/** Whether every line is shown, past {@link ItemDetails#MAX_ROWS}. */
	private boolean showAll;
	/** Told when the player clicks "+N more" or "Show less", or {@code null}. */
	private Consumer<Boolean> showAllListener;

	/**
	 * @param noun what the lines are, for the tooltips ("skills")
	 * @param icons draws the small skill icons before the names
	 */
	ItemListView(String title, boolean collapsible, Color background, String noun, SkillIcons icons)
	{
		this(title, collapsible, background, noun, icons, (label, itemId, quantity) ->
		{
		});
	}

	/**
	 * @param noun what the lines are, for the tooltips ("monsters")
	 * @param icons draws the small skill icons before the names
	 * @param itemIcons draws the item sprites of lines with {@link Line#getIconItemId}, scaled to the slot
	 */
	ItemListView(String title, boolean collapsible, Color background, String noun, SkillIcons icons,
		ItemIcons itemIcons)
	{
		super(title, collapsible, background, noun);
		this.noun = noun;
		this.icons = icons;
		this.itemIcons = itemIcons;
		// Name for tests, which find it from the list itself; no visible effect.
		moreLabel.setName("itemList.more");
		moreLabel.setFont(FontManager.getRunescapeSmallFont());
		moreLabel.setForeground(ColorScheme.BRAND_ORANGE);
		moreLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		moreLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		moreLabel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1)
				{
					toggleShowAll();
				}
			}
		});
		rebuild();
	}

	/** Shows every line, or only the first {@link ItemDetails#MAX_ROWS} again, as a click on "+N more" does. */
	void toggleShowAll()
	{
		showAll = !showAll;
		rebuild();
		if (showAllListener != null)
		{
			showAllListener.accept(showAll);
		}
	}

	/**
	 * Starts with every line shown (or not), and tells {@code listener} when the player changes it, so a list that is
	 * built again (a history row's XP) keeps the choice.
	 */
	void setShowAll(boolean shown, Consumer<Boolean> listener)
	{
		showAllListener = listener;
		if (shown != showAll)
		{
			showAll = shown;
			rebuild();
		}
	}

	@Override
	void fillBody(JPanel body, List<Line> shown)
	{
		for (Line row : ItemDetails.visible(shown, showAll))
		{
			body.add(rowLine(row));
		}
		int hidden = ItemDetails.hiddenCount(shown.size());
		if (hidden > 0)
		{
			moreLabel.setText(showAll ? "Show less" : "+" + hidden + " more");
			moreLabel.setToolTipText(showAll ? "Show only the top " + ItemDetails.MAX_ROWS
				: "Click to show all " + shown.size() + " " + noun);
			body.add(moreLabel);
		}
	}

	/** The skill icon's slot, then the name filling the line (cut short if too long); the amount is right-aligned. */
	private JPanel rowLine(Line row)
	{
		JPanel line = new JPanel(new BorderLayout(4, 0));
		line.setOpaque(false);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		line.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		line.add(iconSlot(row), BorderLayout.WEST);
		JLabel name = label(row.getName(), Color.WHITE);
		// The name asks for no width of its own, so a long one is cut short in the space left rather than widening
		// the sidebar (long monster names in "Monsters assigned").
		name.setPreferredSize(new Dimension(0, name.getPreferredSize().height));
		line.add(name, BorderLayout.CENTER);
		JPanel right = new JPanel(new BorderLayout(4, 0));
		right.setOpaque(false);
		right.add(label(row.amountText(), ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.EAST);
		line.add(right, BorderLayout.EAST);
		// The tooltip has the full name and the exact amounts.
		line.setToolTipText(row.tooltip());
		return line;
	}

	/**
	 * A fixed-size slot with the skill's small icon, else the line's item sprite at the same size, or empty for a line
	 * with neither, so the names line up.
	 */
	private JLabel iconSlot(Line row)
	{
		String skill = row.getSkill();
		Integer itemId = row.getIconItemId();
		JLabel slot = new JLabel();
		// Name for tests, which read the icon from it; no visible effect.
		slot.setName("itemList.icon");
		Dimension size = new Dimension(ICON_WIDTH, ICON_HEIGHT);
		slot.setPreferredSize(size);
		slot.setMinimumSize(size);
		slot.setHorizontalAlignment(SwingConstants.CENTER);
		slot.setVerticalAlignment(SwingConstants.CENTER);
		if (skill != null)
		{
			icons.apply(slot, skill);
		}
		else if (itemId != null)
		{
			SmallItemIcon.apply(itemIcons, slot, itemId);
		}
		return slot;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Pure: the supplies or the loot of several saved tasks added up item by item, for the item grids of Overall totals
 *. Each task's rows come from {@link ItemDetails} exactly as its history details show them (at the prices it is
 * shown at), so a summed row is valued as the group's profit line counts it. No RuneLite dependencies.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>One row per item id and {@link ItemDetails.Unit}, as tallied: a noted item stays its own row, and the doses,
 *     bites or charges of an item counted that way add up as doses, bites or charges.</li>
 *     <li>Quantities and values are the sums of the tasks' rows. A task whose item had no price adds its quantity but
 *     no value: the row's value is the sum of the priced tasks' values, marked approximate
 *     ({@link ItemDetails.Row#isApproximate()}); with no priced task it is unavailable ({@code null}).</li>
 *     <li>The unit prices and doses per item shown in the tooltip are those of the first task added that has them;
 *     Overall totals adds tasks newest first. At today's prices every task has the same GE price.</li>
 *     <li>The rows are not named and have no alch hint: names and the nature rune price are known on the EDT only, so
 *     the panel adds them with {@link ItemDetails#named}.</li>
 * </ul>
 *
 * <p>Not thread-safe: one is filled and read by one thread (the background thread working out the totals). The rows it
 * returns are immutable.</p>
 */
final class ItemSums
{
	/** The sums by item id and unit, in the order first added. */
	private final Map<List<Object>, Sum> sums = new LinkedHashMap<>();

	/** Adds one task's supply or loot rows ({@link ItemDetails#supplyRows} or {@link ItemDetails#lootRows}). */
	void add(List<ItemDetails.Row> rows)
	{
		for (ItemDetails.Row row : rows)
		{
			sums.computeIfAbsent(Arrays.asList(row.getItemId(), row.getUnit()), key -> new Sum(row)).add(row);
		}
	}

	/** The summed rows, unnamed ("Item &lt;id&gt;") and without the alch hint, unmodifiable. */
	List<ItemDetails.Row> rows()
	{
		List<ItemDetails.Row> rows = new ArrayList<>(sums.size());
		for (Sum sum : sums.values())
		{
			rows.add(sum.toRow());
		}
		return Collections.unmodifiableList(rows);
	}

	/** One item's running sum. */
	private static final class Sum
	{
		private final ItemDetails.Row first;
		private long quantity;
		private long value;
		private int priced;
		private int unpriced;
		private Long unitGe;
		private Long unitHa;
		private Integer dosesPerItem;

		private Sum(ItemDetails.Row first)
		{
			this.first = first;
		}

		private void add(ItemDetails.Row row)
		{
			quantity = saturatedAdd(quantity, row.getQuantity());
			if (row.getValue() == null)
			{
				unpriced++;
			}
			else
			{
				value = saturatedAdd(value, row.getValue());
				priced++;
			}
			unitGe = unitGe != null ? unitGe : row.getUnitGe();
			unitHa = unitHa != null ? unitHa : row.getUnitHa();
			dosesPerItem = dosesPerItem != null ? dosesPerItem : row.getDosesPerItem();
		}

		private ItemDetails.Row toRow()
		{
			return first.toBuilder()
				.quantity(quantity)
				.value(priced == 0 ? null : value)
				.unitGe(unitGe)
				.unitHa(unitHa)
				.dosesPerItem(dosesPerItem)
				.alchHint(false)
				.approximate(priced > 0 && unpriced > 0)
				.build();
		}
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Per-item quantities (item id to quantity), used for loot and supplies. Pure: no RuneLite dependencies.
 *
 * <p>Ids are stored exactly as received (a noted drop keeps its noted id); pricing resolves the unnoted id, see
 * {@link ItemValuation}. Quantities are {@code long} so large coin stacks over a long task cannot overflow. Only
 * positive quantities are kept. Not thread-safe; {@link SessionTracker} guards its instance with its own lock.</p>
 *
 * <p>The JSON form is a plain {@code Map<Integer, Long>} (an object such as {@code {"995": 1200}}), see
 * {@link #toMap()} and {@link #fromMap(Map)}.</p>
 */
public final class ItemTally
{
	private final TreeMap<Integer, Long> quantities = new TreeMap<>();

	public ItemTally()
	{
	}

	/** A copy of another tally. */
	public ItemTally(ItemTally other)
	{
		if (other != null)
		{
			quantities.putAll(other.quantities);
		}
	}

	/**
	 * Builds a tally from its JSON form. {@code null} gives an empty tally; null keys and non-positive quantities
	 * are skipped.
	 */
	public static ItemTally fromMap(Map<Integer, Long> map)
	{
		ItemTally tally = new ItemTally();
		if (map != null)
		{
			for (Map.Entry<Integer, Long> e : map.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null)
				{
					tally.add(e.getKey(), e.getValue());
				}
			}
		}
		return tally;
	}

	/**
	 * Adds a quantity of an item. Non-positive quantities are ignored. Saturates at {@link Long#MAX_VALUE}.
	 */
	public void add(int itemId, long quantity)
	{
		if (quantity <= 0)
		{
			return;
		}
		quantities.merge(itemId, quantity, ItemTally::saturatedAdd);
	}

	/**
	 * Removes up to a quantity of an item, never going below zero (an item reaching zero is removed). Non-positive
	 * quantities are ignored.
	 *
	 * @return the quantity actually removed
	 */
	public long subtract(int itemId, long quantity)
	{
		if (quantity <= 0)
		{
			return 0;
		}
		final long current = get(itemId);
		final long removed = Math.min(current, quantity);
		if (removed == current)
		{
			quantities.remove(itemId);
		}
		else
		{
			quantities.put(itemId, current - removed);
		}
		return removed;
	}

	/** Adds every item of another tally to this one. */
	public void merge(ItemTally other)
	{
		if (other == null)
		{
			return;
		}
		// Merging a tally into itself iterates over a copy.
		Map<Integer, Long> source = other == this ? new TreeMap<>(quantities) : other.quantities;
		for (Map.Entry<Integer, Long> e : source.entrySet())
		{
			add(e.getKey(), e.getValue());
		}
	}

	/** Quantity of an item, or 0. */
	public long get(int itemId)
	{
		Long q = quantities.get(itemId);
		return q == null ? 0 : q;
	}

	public boolean isEmpty()
	{
		return quantities.isEmpty();
	}

	/** Number of distinct items. */
	public int size()
	{
		return quantities.size();
	}

	/** Item ids in ascending order (read-only view). */
	public Set<Integer> itemIds()
	{
		return Collections.unmodifiableSet(quantities.keySet());
	}

	public void clear()
	{
		quantities.clear();
	}

	/**
	 * The JSON form: a new, sorted, mutable map, or {@code null} when the tally is empty (so records and snapshots
	 * without items omit the field).
	 */
	public Map<Integer, Long> toMap()
	{
		return quantities.isEmpty() ? null : new TreeMap<>(quantities);
	}

	private static long saturatedAdd(long a, long b)
	{
		long sum = a + b;
		return sum < 0 ? Long.MAX_VALUE : sum;
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof ItemTally && quantities.equals(((ItemTally) o).quantities);
	}

	@Override
	public int hashCode()
	{
		return quantities.hashCode();
	}

	@Override
	public String toString()
	{
		return "ItemTally" + quantities;
	}
}

package com.shmayvan.slayerledger;

import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * Pure item valuation: captures per-item unit prices through a {@link PriceLookup} and totals a tally against them.
 * No RuneLite dependencies; the plugin supplies a lookup backed by {@code ItemManager} on the client thread.
 *
 * <p>Rules (matching how core RuneLite values loot in 1.13.3):</p>
 * <ul>
 *     <li>Coins are valued at face value (1 gp each) for both GE and high alchemy, and platinum tokens at 1,000 gp.
 *     {@code ItemManager#getItemPrice} already does this for GE; it is applied here for high alchemy too, because the
 *     coin item's own high-alchemy value is not its face value.</li>
 *     <li>Prices are looked up by the canonical id ({@link PriceLookup#canonicalize}, which un-notes noted items), so
 *     a noted drop is valued like the unnoted item. Unit prices are keyed by the id as tallied.</li>
 *     <li>A GE price is <em>unavailable</em> when the lookup throws, or when a tradeable item's GE price is 0 or
 *     less. {@code ItemManager} (1.13.3) has no "prices loaded" flag: until its price list has been fetched, and for
 *     an item missing from it, {@code getItemPrice} simply returns 0, the same as for an untradeable item. So a
 *     tradeable item at 0 is treated as unavailable rather than worthless. An unavailable GE price is left out of
 *     {@link UnitPrices#getGe()} (and recorded in {@link UnitPrices#getGeMissing()}), so it can be told apart from a
 *     real 0. An untradeable item with no GE price is a known 0.</li>
 *     <li>A high-alchemy value of 0 or less is a known 0; it is unavailable only when the lookup throws.</li>
 *     <li>Totals sum the known prices; {@link #countUnpriced} tells how many items of a tally were left out.</li>
 * </ul>
 */
final class ItemValuation
{
	/** {@code net.runelite.api.gameval.ItemID.COINS} (1.13.3). */
	static final int COINS = 995;
	/** {@code net.runelite.api.gameval.ItemID.PLATINUM} (1.13.3). */
	static final int PLATINUM = 13204;
	static final long PLATINUM_VALUE = 1000L;

	/**
	 * Price source. Implementations may only be valid on a particular thread (the plugin's runs on the client thread).
	 */
	interface PriceLookup
	{
		/** The id to price: the unnoted id for a noted item, otherwise the id itself. */
		int canonicalize(int itemId);

		/** Grand Exchange unit price of a canonical id, or 0 / negative when unknown. */
		long gePrice(int canonicalId);

		/**
		 * Whether a canonical id can be traded on the Grand Exchange; a tradeable item without a GE price has an
		 * unavailable price rather than a value of 0.
		 */
		boolean isTradeable(int canonicalId);

		/** High-alchemy unit value of a canonical id, or 0 / negative when unknown. */
		long haPrice(int canonicalId);
	}

	/** Unit prices for a set of items, keyed by the id as tallied. */
	static final class UnitPrices
	{
		private final Map<Integer, Long> ge = new TreeMap<>();
		private final Map<Integer, Long> ha = new TreeMap<>();
		private final Set<Integer> geMissing = new TreeSet<>();

		/** GE unit prices of the ids whose price was available. */
		Map<Integer, Long> getGe()
		{
			return ge;
		}

		/** High-alchemy unit values of the ids whose value was available. */
		Map<Integer, Long> getHa()
		{
			return ha;
		}

		/** Ids looked up whose GE price was unavailable (absent from {@link #getGe()}). */
		Set<Integer> getGeMissing()
		{
			return geMissing;
		}
	}

	private ItemValuation()
	{
	}

	/**
	 * Adds the GE and high-alchemy unit price of every item in the tally to {@code into}. Items already present are
	 * looked up again; an item whose GE price is unavailable (see the class rules) is removed from the GE prices and
	 * added to {@link UnitPrices#getGeMissing()}, and likewise for a high-alchemy lookup that throws.
	 */
	static void capturePrices(ItemTally tally, PriceLookup lookup, UnitPrices into)
	{
		if (tally == null)
		{
			return;
		}
		for (int id : tally.itemIds())
		{
			capturePrice(id, lookup, into);
		}
	}

	/** Looks up one id's prices into {@code into}, as {@link #capturePrices(ItemTally, PriceLookup, UnitPrices)}. */
	static void capturePrice(int id, PriceLookup lookup, UnitPrices into)
	{
		Long ge = null;
		Long ha = null;
		try
		{
			int canonical = lookup.canonicalize(id);
			if (canonical == COINS)
			{
				ge = 1L;
				ha = 1L;
			}
			else if (canonical == PLATINUM)
			{
				ge = PLATINUM_VALUE;
				ha = PLATINUM_VALUE;
			}
			else
			{
				ge = gePrice(canonical, lookup);
				ha = haPrice(canonical, lookup);
			}
		}
		catch (RuntimeException e)
		{
			// Unknown item definition; both prices are unavailable.
		}
		if (ge != null)
		{
			into.getGe().put(id, ge);
			into.getGeMissing().remove(id);
		}
		else
		{
			into.getGe().remove(id);
			into.getGeMissing().add(id);
		}
		if (ha != null)
		{
			into.getHa().put(id, ha);
		}
		else
		{
			into.getHa().remove(id);
		}
	}

	/** The GE price, 0 for an untradeable item without one, or {@code null} when unavailable. */
	private static Long gePrice(int canonical, PriceLookup lookup)
	{
		try
		{
			long price = lookup.gePrice(canonical);
			if (price > 0)
			{
				return price;
			}
			return lookup.isTradeable(canonical) ? null : 0L;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** The high-alchemy value (at least 0), or {@code null} when the lookup fails. */
	private static Long haPrice(int canonical, PriceLookup lookup)
	{
		try
		{
			return Math.max(0, lookup.haPrice(canonical));
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Number of distinct items in {@code tally} without an entry in {@code unitPrices} (their price was unavailable),
	 * or 0 when the tally is empty. Every item counts as unpriced when {@code unitPrices} is {@code null}.
	 */
	static int countUnpriced(ItemTally tally, Map<Integer, Long> unitPrices)
	{
		if (tally == null)
		{
			return 0;
		}
		int count = 0;
		for (int id : tally.itemIds())
		{
			if (unitPrices == null || !unitPrices.containsKey(id))
			{
				count++;
			}
		}
		return count;
	}

	/** Captures unit prices for one tally. */
	static UnitPrices capturePrices(ItemTally tally, PriceLookup lookup)
	{
		UnitPrices prices = new UnitPrices();
		capturePrices(tally, lookup, prices);
		return prices;
	}

	/**
	 * Total value of a tally at the given unit prices. Items without a price are left out (count as 0); the total
	 * saturates at {@link Long#MAX_VALUE}.
	 */
	static long total(ItemTally tally, Map<Integer, Long> unitPrices)
	{
		return total(tally, unitPrices, null);
	}

	/**
	 * Total value of a tally whose quantities are in doses for some items: for an id with an entry {@code n} in
	 * {@code dosesPerItem}, the quantity counts doses and each is worth {@code unitPrice / n} (the id's price is for one
	 * {@code n}-dose item). The per-item product is rounded to the nearest gp. Other items are valued as in
	 * {@link #total(ItemTally, Map)}.
	 */
	static long total(ItemTally tally, Map<Integer, Long> unitPrices, Map<Integer, Integer> dosesPerItem)
	{
		if (tally == null || unitPrices == null)
		{
			return 0;
		}
		long total = 0;
		for (int id : tally.itemIds())
		{
			Long price = unitPrices.get(id);
			if (price == null || price <= 0)
			{
				continue;
			}
			Integer doses = dosesPerItem == null ? null : dosesPerItem.get(id);
			try
			{
				long value = Math.multiplyExact(price, tally.get(id));
				if (doses != null && doses > 1)
				{
					value = value / doses + (value % doses * 2 >= doses ? 1 : 0);
				}
				total = Math.addExact(total, value);
			}
			catch (ArithmeticException e)
			{
				return Long.MAX_VALUE;
			}
		}
		return total;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The Slayer keys and clue scrolls among a task's loot: brimstone keys (Konar), Larran's keys (Krystilia's Wilderness
 * tasks) and clue scrolls by tier. Derived from the loot tally ({@link LedgerRecord#getLoot()}, or the session's
 * loot), so it follows the loot's rules (only loot received while the session was running, after the bonecrusher and
 * "Ignored loot" filters) and older records with loot get counts too. Nothing extra is stored. Immutable; pure (no
 * RuneLite types).
 *
 * <p>Ids are those of {@code net.runelite.api.gameval.ItemID} in RuneLite API 1.13.4 ({@code KeysAndCluesTest} checks
 * them against it). Besides each key's own id, the ids the game lists under the same name (its stack-size display
 * variants) are counted too, in case loot ever reports one. Clue scroll ids are in {@link ClueScrollIds}.</p>
 */
final class KeysAndClues
{
	/** Clue scroll tiers, in display order. */
	enum ClueTier
	{
		BEGINNER("beginner", ClueScrollIds.BEGINNER),
		EASY("easy", ClueScrollIds.EASY),
		MEDIUM("medium", ClueScrollIds.MEDIUM),
		HARD("hard", ClueScrollIds.HARD),
		ELITE("elite", ClueScrollIds.ELITE),
		MASTER("master", ClueScrollIds.MASTER);

		private final String displayName;
		private final int[] itemIds;

		ClueTier(String displayName, int[] itemIds)
		{
			this.displayName = displayName;
			this.itemIds = itemIds;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Brimstone key: {@code ItemID.KONAR_KEY} (23083) and its {@code KONAR_KEY_COUNTVIEW1}..{@code 6} variants
	 * (23085-23090).
	 */
	static final int[] BRIMSTONE_KEY_IDS = {23083, 23085, 23086, 23087, 23088, 23089, 23090};
	/**
	 * Larran's key: {@code ItemID.SLAYER_WILDERNESS_KEY} (23490) and its {@code SLAYER_WILDERNESS_KEY_2}, {@code _4}
	 * and {@code _5} variants (23492-23494).
	 */
	static final int[] LARRANS_KEY_IDS = {23490, 23492, 23493, 23494};

	static final KeysAndClues NONE = new KeysAndClues(0, 0, new long[ClueTier.values().length]);

	/** What each counted id is: a {@link ClueTier}, or {@link #BRIMSTONE} / {@link #LARRAN} for keys. */
	private static final Map<Integer, Object> KINDS = new HashMap<>();
	private static final Object BRIMSTONE = new Object();
	private static final Object LARRAN = new Object();

	static
	{
		for (int id : BRIMSTONE_KEY_IDS)
		{
			KINDS.put(id, BRIMSTONE);
		}
		for (int id : LARRANS_KEY_IDS)
		{
			KINDS.put(id, LARRAN);
		}
		for (ClueTier tier : ClueTier.values())
		{
			for (int id : tier.itemIds)
			{
				KINDS.put(id, tier);
			}
		}
	}

	private final long brimstoneKeys;
	private final long larransKeys;
	/** Clue scrolls by {@link ClueTier#ordinal()}. */
	private final long[] clues;

	private KeysAndClues(long brimstoneKeys, long larransKeys, long[] clues)
	{
		this.brimstoneKeys = brimstoneKeys;
		this.larransKeys = larransKeys;
		this.clues = clues;
	}

	/** The keys and clue scrolls in {@code loot} (item id to quantity); {@link #NONE} for {@code null}. */
	static KeysAndClues of(Map<Integer, Long> loot)
	{
		if (loot == null || loot.isEmpty())
		{
			return NONE;
		}
		long brimstone = 0;
		long larran = 0;
		long[] clues = new long[ClueTier.values().length];
		for (Map.Entry<Integer, Long> e : loot.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null || e.getValue() <= 0)
			{
				continue;
			}
			Object kind = KINDS.get(e.getKey());
			if (kind == BRIMSTONE)
			{
				brimstone = saturatedAdd(brimstone, e.getValue());
			}
			else if (kind == LARRAN)
			{
				larran = saturatedAdd(larran, e.getValue());
			}
			else if (kind instanceof ClueTier)
			{
				int i = ((ClueTier) kind).ordinal();
				clues[i] = saturatedAdd(clues[i], e.getValue());
			}
		}
		return new KeysAndClues(brimstone, larran, clues);
	}

	/** The keys and clue scrolls in {@code loot}; {@link #NONE} for {@code null}. */
	static KeysAndClues of(ItemTally loot)
	{
		return loot == null ? NONE : of(loot.toMap());
	}

	long getBrimstoneKeys()
	{
		return brimstoneKeys;
	}

	long getLarransKeys()
	{
		return larransKeys;
	}

	long getClues(ClueTier tier)
	{
		return clues[tier.ordinal()];
	}

	boolean hasKeys()
	{
		return brimstoneKeys > 0 || larransKeys > 0;
	}

	boolean hasClues()
	{
		return Arrays.stream(clues).anyMatch(n -> n > 0);
	}

	/** {@code Keys: 2 brimstone, 1 Larran's}, leaving out a kind with none; {@code null} when there are no keys. */
	String keysText()
	{
		List<String> parts = new ArrayList<>();
		if (brimstoneKeys > 0)
		{
			parts.add(brimstoneKeys + " brimstone");
		}
		if (larransKeys > 0)
		{
			parts.add(larransKeys + " Larran's");
		}
		return parts.isEmpty() ? null : "Keys: " + String.join(", ", parts);
	}

	/** {@code Clues: 1 hard, 2 elite}, lowest tier first, leaving out tiers with none; {@code null} when none. */
	String cluesText()
	{
		List<String> parts = new ArrayList<>();
		for (ClueTier tier : ClueTier.values())
		{
			long n = clues[tier.ordinal()];
			if (n > 0)
			{
				parts.add(n + " " + tier);
			}
		}
		return parts.isEmpty() ? null : "Clues: " + String.join(", ", parts);
	}

	private static long saturatedAdd(long a, long b)
	{
		long r = a + b;
		return ((a ^ r) & (b ^ r)) < 0 ? Long.MAX_VALUE : r;
	}
}

package com.shmayvan.slayerledger;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/**
 * Recognises the game's kill count chat messages, such as {@code Your Vorkath kill count is: <col=ff0000>152</col>.}
 * Pure (no RuneLite types).
 *
 * <p>The pattern is core ChatCommandsPlugin's {@code KILLCOUNT_PATTERN} (RuneLite 1.13.4), matched the same way (on the
 * message with its colour tags, anywhere in it) for the same chat types (game, spam, trade and friends chat
 * notification messages). As in core, the count must be coloured ({@code <col=...>} or {@code @...@}, closed by
 * {@code </col>}), and a message with neither a prefix nor a count word ({@code Your X is: ...}) is not a kill count.
 * The boss name may be coloured too; its tags are removed.</p>
 *
 * <p>Core's pattern also matches counts that are not boss kills: raids and other completions ({@code completed},
 * {@code completion count for}, {@code completion count}), {@code subdued} (Wintertodt), {@code harvest} (Herbiboar),
 * {@code lap} (agility courses), {@code success} and {@code Total Ticket} counts. Those parse with
 * {@link Result#isBossKill()} {@code false}. Only {@code <boss> kill count is:} and the bare {@code <boss> count is:}
 * (for example {@code Your Barrows chest count is:}) are boss kills.</p>
 */
final class KillCountMessage
{
	/** Core ChatCommandsPlugin's KILLCOUNT_PATTERN (RuneLite 1.13.4), unchanged. */
	static final Pattern KILLCOUNT_PATTERN = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?"
		+ "(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?"
		+ "(?:count )?)is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");

	private static final String KILL_COUNT = "kill count ";
	private static final String COUNT = "count ";

	private KillCountMessage()
	{
	}

	/** A recognised kill count message. */
	@Getter
	@EqualsAndHashCode
	@ToString
	static final class Result
	{
		/** The name the message gives, without colour tags, for example {@code Vorkath} or {@code Barrows chest}. */
		private final String boss;
		/** The count the message gives (at least 0). */
		private final int kc;
		/** Whether it counts a boss kill ({@code kill count} or bare {@code count}), rather than a lap, raid and so on. */
		private final boolean bossKill;

		Result(String boss, int kc, boolean bossKill)
		{
			this.boss = boss;
			this.kc = kc;
			this.bossKill = bossKill;
		}
	}

	/**
	 * What a chat message says about a kill count, or {@code null} when it is not a kill count message.
	 *
	 * @param kcMessageType whether the message type is one core checks: GAMEMESSAGE, SPAM, TRADE or
	 *                      FRIENDSCHATNOTIFICATION
	 * @param message       the message text, with its tags
	 */
	static Result parse(boolean kcMessageType, String message)
	{
		if (!kcMessageType || message == null)
		{
			return null;
		}
		final Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return null;
		}
		final String pre = matcher.group("pre");
		final String post = matcher.group("post");
		final boolean hasPre = pre != null && !pre.isEmpty();
		final boolean hasPost = post != null && !post.isEmpty();
		if (!hasPre && !hasPost)
		{
			// Core ignores these too ("Your X is: n").
			return null;
		}
		final String boss = BossKillCounts.cleanName(matcher.group("boss"));
		final Integer kc = parseCount(matcher.group("kc"));
		if (boss.isEmpty() || kc == null)
		{
			return null;
		}
		final boolean bossKill = !hasPre && (KILL_COUNT.equals(post) || COUNT.equals(post));
		return new Result(boss, kc, bossKill);
	}

	/** A count such as {@code 1,130}, or {@code null} when it has no digits or is too large. */
	private static Integer parseCount(String text)
	{
		final String digits = text.replace(",", "");
		if (digits.isEmpty() || digits.length() > 10)
		{
			return null;
		}
		final long value = Long.parseLong(digits);
		return value > Integer.MAX_VALUE ? null : (int) value;
	}
}

package com.shmayvan.slayerledger;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.OptionalLong;
import java.util.TreeSet;
import net.runelite.client.util.QuantityFormatter;

/**
 * Pure sorting, filtering and formatting for the task-history view and the live session values. No Swing, client
 * or file access (only RuneLite's static {@link QuantityFormatter}), so it can be unit-tested and called from any
 * thread.
 */
final class LedgerHistory
{
	/** Label of the filter entry that shows every monster. */
	static final String ALL = "All";
	static final String UNKNOWN_MONSTER = "Unknown task";
	/** Shown instead of a value that was never recorded (tasks saved before values were tracked). */
	static final String NO_VALUE = "-";
	/** Prefix of a total that leaves out items whose GE price was unavailable. */
	static final String APPROXIMATE = "~";
	/** Time left until a session has enough kills and active time for an estimate ({@link #formatTimeLeft}). */
	static final String TIME_LEFT_ESTIMATING = "estimating...";
	/** Tooltip text for a task saved before loot and supply values were tracked. */
	static final String NOT_VALUED = "Not valued: this task was saved before loot and supply values were tracked.";
	/** Tooltip line of a history row valued at today's GE prices. */
	static final String CURRENT_PRICES = "Prices: today's GE prices (high alch values don't change)";
	/** Tooltip line of a history row saved without per-item prices, which keeps its saved totals. */
	static final String SAVED_TOTALS = "Prices: saved totals (no items kept), so GE values are marked ~";

	/** Newest first by end time; ties broken by start time (newest first), then id, for a stable order. */
	static final Comparator<LedgerRecord> NEWEST_FIRST = Comparator
		.comparingLong(LedgerRecord::getEndedAt).reversed()
		.thenComparing(Comparator.comparingLong(LedgerRecord::getStartedAt).reversed())
		.thenComparing(r -> r.getId() == null ? "" : r.getId());

	private LedgerHistory()
	{
	}

	/**
	 * Name shown for a record, and what the Monster filter matches: its {@link LedgerRecord#groupName} (the Catacombs
	 * variant for a task done on one); records without a name (very old or hand-edited files) show a fallback.
	 */
	static String monster(LedgerRecord record)
	{
		String monster = record.groupName();
		return monster == null || monster.isEmpty() ? UNKNOWN_MONSTER : monster;
	}

	/** Copy of {@code records} without nulls, newest first. */
	static List<LedgerRecord> sortNewestFirst(Collection<LedgerRecord> records)
	{
		List<LedgerRecord> sorted = new ArrayList<>(records.size());
		for (LedgerRecord r : records)
		{
			if (r != null)
			{
				sorted.add(r);
			}
		}
		sorted.sort(NEWEST_FIRST);
		return sorted;
	}

	/** Filter choices: {@link #ALL} followed by each distinct monster in the records, alphabetically (ignoring case). */
	static List<String> filterOptions(Collection<LedgerRecord> records)
	{
		TreeSet<String> names = new TreeSet<>(Comparator.comparing((String s) -> s.toLowerCase(Locale.ROOT)).thenComparing(s -> s));
		for (LedgerRecord r : records)
		{
			if (r != null)
			{
				names.add(monster(r));
			}
		}
		List<String> options = new ArrayList<>(names.size() + 1);
		options.add(ALL);
		options.addAll(names);
		return options;
	}

	/**
	 * The filter selection to keep after the options change: {@code selection} while it is still one of the monster
	 * options, otherwise {@code null} ("All").
	 */
	static String keepSelection(List<String> options, String selection)
	{
		return selection != null && !ALL.equals(selection) && options.contains(selection) ? selection : null;
	}

	/** "kills / originalAmount" when the assigned amount is known, otherwise just the kills. */
	static String formatKills(LedgerRecord record)
	{
		Integer original = record.getOriginalAmount();
		if (original != null && original > 0)
		{
			return record.getKills() + " / " + original;
		}
		return Integer.toString(record.getKills());
	}

	/** Active time as H:MM:SS. */
	static String formatDuration(long millis)
	{
		long totalSeconds = Math.max(0, millis) / 1000;
		return String.format("%d:%02d:%02d", totalSeconds / 3600, (totalSeconds / 60) % 60, totalSeconds % 60);
	}

	/**
	 * A time per kill in short form, rounded to whole seconds (half up): {@code 18s} under a minute,
	 * {@code 4m 05s} under an hour and {@code 1h 02m} from an hour on (minutes rounded half up). A negative time counts
	 * as none ({@code 0s}). Task lengths and elapsed time keep {@link #formatDuration}.
	 */
	static String formatKillTime(long millis)
	{
		long clamped = Math.max(0, millis);
		long seconds = clamped / 1000 + (clamped % 1000 >= 500 ? 1 : 0);
		if (seconds < 60)
		{
			return seconds + "s";
		}
		if (seconds < 3600)
		{
			return String.format("%dm %02ds", seconds / 60, seconds % 60);
		}
		// Minutes from the exact time, not the rounded seconds, so a time is rounded only once.
		long minutes = clamped / 60_000 + (clamped % 60_000 >= 30_000 ? 1 : 0);
		return String.format("%dh %02dm", minutes / 60, minutes % 60);
	}

	/**
	 * Estimated time left, rounded to the nearest whole minute (half up), without seconds: {@code ~44m} under an hour,
	 * {@code ~1h 05m} from an hour on, and {@code ~<1m} when it rounds to no minutes. A negative time counts as none;
	 * the saturated {@link Long#MAX_VALUE} of {@link #historicalTimeLeftMillis} formats without overflowing.
	 */
	static String formatTimeLeftMinutes(long millis)
	{
		long clamped = Math.max(0, millis);
		long minutes = clamped / 60_000 + (clamped % 60_000 >= 30_000 ? 1 : 0);
		if (minutes == 0)
		{
			return "~<1m";
		}
		if (minutes < 60)
		{
			return "~" + minutes + "m";
		}
		return String.format("~%dh %02dm", minutes / 60, minutes % 60);
	}

	/**
	 * Estimated time left on the task from the session's pace alone: {@link #formatTimeLeft(long, int, int, Long)}
	 * with no history.
	 */
	static String formatTimeLeft(long activeMillis, int kills, int remaining)
	{
		return formatTimeLeft(activeMillis, kills, remaining, null);
	}

	/**
	 * Estimated time left on the task, in whole minutes ({@link #formatTimeLeftMinutes}): at the session's pace so far
	 * (see {@link TaskTimeEstimate}); until there are enough kills and active time for that, at the historical time per
	 * kill when there is one ({@link #historicalTimeLeftMillis}), else {@link #TIME_LEFT_ESTIMATING}; or
	 * {@link #NO_VALUE} when no kills are left on the task (no task, the task is done, or the kills left are unknown).
	 * The sidebar and the overlay both show it, so they can't disagree.
	 *
	 * @param historicalMillisPerKill the task's average active time per kill in its completed history
	 *                                ({@link TaskStatistics#getMillisPerKill}), or {@code null} when it has none
	 */
	static String formatTimeLeft(long activeMillis, int kills, int remaining, Long historicalMillisPerKill)
	{
		if (remaining <= 0)
		{
			return NO_VALUE;
		}
		OptionalLong estimate = TaskTimeEstimate.remainingMillis(activeMillis, kills, remaining);
		if (estimate.isPresent())
		{
			return formatTimeLeftMinutes(estimate.getAsLong());
		}
		return historicalMillisPerKill == null ? TIME_LEFT_ESTIMATING
			: formatTimeLeftMinutes(historicalTimeLeftMillis(historicalMillisPerKill, remaining));
	}

	/**
	 * Whether {@link #formatTimeLeft(long, int, int, Long)} shows the historical estimate for these values (rather than
	 * the live pace, {@link #TIME_LEFT_ESTIMATING} or {@link #NO_VALUE}).
	 */
	static boolean isHistoricalTimeLeft(long activeMillis, int kills, int remaining, Long historicalMillisPerKill)
	{
		return remaining > 0 && historicalMillisPerKill != null
			&& !TaskTimeEstimate.remainingMillis(activeMillis, kills, remaining).isPresent();
	}

	/**
	 * The historical time left: {@code millisPerKill * remaining}, saturated at {@link Long#MAX_VALUE} as
	 * {@link TaskStatistics#estimate} does.
	 */
	static long historicalTimeLeftMillis(long millisPerKill, int remaining)
	{
		try
		{
			return Math.multiplyExact(millisPerKill, (long) remaining);
		}
		catch (ArithmeticException e)
		{
			return millisPerKill >= 0 == remaining >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	static String status(LedgerRecord record)
	{
		return record.isCompleted() ? "Completed" : "Partial";
	}

	/** Short, locale-style date/time formatter in the given zone (the system zone in the panel). */
	static DateTimeFormatter shortDateTime(ZoneId zone)
	{
		return DateTimeFormatter.ofLocalizedDateTime(FormatStyle.SHORT).withZone(zone);
	}

	/** End time formatted with {@code formatter}, or "-" when the record has no end time. */
	static String formatEndedAt(LedgerRecord record, DateTimeFormatter formatter)
	{
		long endedAt = record.getEndedAt();
		if (endedAt <= 0)
		{
			return "-";
		}
		return formatter.format(Instant.ofEpochMilli(endedAt));
	}

	/** Text of the delete confirmation dialog. */
	static String deleteConfirmation(LedgerRecord record)
	{
		return String.format("Delete this %s task (%d kills)? This can't be undone.", monster(record), record.getKills());
	}

	// ---- Values ----

	/** Compact gp amount as in core Loot Tracker ({@code QuantityFormatter}, e.g. "9,450 gp", "350K gp", "1.23M gp"). */
	static String formatGp(long value)
	{
		return QuantityFormatter.quantityToStackSize(value) + " gp";
	}

	/**
	 * Compact gp amount, {@link #NO_VALUE} when {@code value} is {@code null} (never "0"), prefixed with
	 * {@link #APPROXIMATE} when {@code approximate}.
	 */
	static String formatGp(Long value, boolean approximate)
	{
		if (value == null)
		{
			return NO_VALUE;
		}
		return (approximate ? APPROXIMATE : "") + formatGp(value.longValue());
	}

	/**
	 * Like {@link #formatGp(Long, boolean)} without the " gp" suffix, for history rows: with the price label the loot
	 * and supplies don't fit one sidebar line otherwise.
	 */
	static String formatAmount(Long value, boolean approximate)
	{
		if (value == null)
		{
			return NO_VALUE;
		}
		return (approximate ? APPROXIMATE : "") + QuantityFormatter.quantityToStackSize(value);
	}

	/** Full gp amount with thousands separators, for tooltips. */
	static String formatGpExact(long value)
	{
		return QuantityFormatter.formatNumber(value) + " gp";
	}

	/**
	 * Loot value minus supplies value, saturating at the {@code long} range; {@code null} when the loot was not valued.
	 * A {@code null} supplies value counts as 0 (no supplies recorded).
	 */
	static Long profit(Long loot, Long supplies)
	{
		if (loot == null)
		{
			return null;
		}
		if (supplies == null)
		{
			return loot;
		}
		try
		{
			return Math.subtractExact(loot, supplies);
		}
		catch (ArithmeticException e)
		{
			return supplies < 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** Whether a record was valued when saved; records saved before values were tracked were not. */
	static boolean isValued(LedgerRecord record)
	{
		return record.getLootGeValue() != null;
	}

	/**
	 * The record's stored loot GE value, or {@code null} when it was not valued. This is the raw saved total (an
	 * untradeable item at 0); what the history shows comes from {@link HistoryPricing}, which values a GE price of 0
	 * at high alch.
	 */
	static Long lootGe(LedgerRecord record)
	{
		return record.getLootGeValue();
	}

	/**
	 * The record's supplies GE value: the saved total, 0 for a valued record without supplies (none were used), or
	 * {@code null} when the record was not valued.
	 */
	static Long suppliesGe(LedgerRecord record)
	{
		if (record.getSuppliesGeValue() != null)
		{
			return record.getSuppliesGeValue();
		}
		return isValued(record) ? 0L : null;
	}

	/**
	 * Stored loot GE minus supplies GE, or {@code null} when the record was not valued; see {@link #lootGe} (use
	 * {@link HistoryPricing} for the shown profit).
	 */
	static Long profitGe(LedgerRecord record)
	{
		return profit(lootGe(record), suppliesGe(record));
	}

	/** Distinct loot items whose GE price was unavailable when the record was saved. */
	static int lootUnpriced(LedgerRecord record)
	{
		Integer n = record.getLootUnpricedItems();
		return n == null ? 0 : Math.max(0, n);
	}

	/** Distinct supply items whose GE price was unavailable when the record was saved. */
	static int suppliesUnpriced(LedgerRecord record)
	{
		Integer n = record.getSuppliesUnpricedItems();
		return n == null ? 0 : Math.max(0, n);
	}

	/** Short name of a loot price mode for the panel's value labels: "GE", or "HA" for high alchemy. */
	static String priceLabel(LootPriceMode mode)
	{
		return mode == LootPriceMode.HIGH_ALCH ? "HA" : "GE";
	}

	/** "Loot (GE): " or "Loot (HA): ", the label of a loot value in {@code mode} ({@code null} counts as GE). */
	static String lootLabel(LootPriceMode mode)
	{
		return "Loot (" + priceLabel(mode) + "): ";
	}

	/** "Profit (GE): " or "Profit (HA): ", the label of a profit with the loot in {@code mode}. */
	static String profitLabel(LootPriceMode mode)
	{
		return profitName(mode) + ": ";
	}

	/** "Profit (GE)" or "Profit (HA)", the name of a profit with the loot in {@code mode} (the overlay's row label). */
	static String profitName(LootPriceMode mode)
	{
		return "Profit (" + priceLabel(mode) + ")";
	}

	/**
	 * The live session's profit amount ({@code 1.2M gp}): loot in its price mode minus supplies, approximate when
	 * either has an unavailable price. The sidebar's live profit line and the overlay both show it.
	 */
	static String formatLiveProfit(SessionValuation.Values values)
	{
		int unpriced = values.getLootValueUnpriced() + values.getSuppliesUnpriced();
		return formatGp(values.getProfit(), unpriced > 0);
	}

	/** "Loot (GE): ..." or "Loot (HA): ..." text of a history row: the loot value in the values' price mode. */
	static String formatLoot(HistoryPricing.Values values)
	{
		return lootLabel(values.getMode()) + formatAmount(values.getLootValue(), values.isLootApproximate());
	}

	/** "Supplies: ..." text of a history row (always at GE prices). */
	static String formatSupplies(HistoryPricing.Values values)
	{
		return "Supplies: " + formatAmount(values.getSuppliesGe(), values.isSuppliesApproximate());
	}

	/**
	 * "Profit (GE): ..." or "Profit (HA): ..." text of a history row: loot in the values' price mode minus supplies;
	 * approximate when either is.
	 */
	static String formatProfit(HistoryPricing.Values values)
	{
		return profitLabel(values.getMode()) + formatAmount(values.getProfit(), values.isProfitApproximate());
	}

	/**
	 * HTML tooltip of a history row: the exact values ({@code values}, which also say which prices and price mode are
	 * shown), followed by the superior spawns, bank trips and deaths ({@link #NO_VALUE} when the task was saved before
	 * they were counted), the task context, the boss kill counts, keys, clue scrolls and notable drops (when there are
	 * any) and the note, if any.
	 */
	static String rowTooltip(LedgerRecord record, HistoryPricing.Values values)
	{
		return rowTooltip(record, values, null);
	}

	/**
	 * HTML tooltip of a history row ({@link #rowTooltip(LedgerRecord, HistoryPricing.Values)}) with its location line
	 * ({@link TaskLocation#format}) after the values.
	 *
	 * @param location the location to show ({@link TaskLocation#displayName}), or {@code null} for no location line
	 */
	static String rowTooltip(LedgerRecord record, HistoryPricing.Values values, String location)
	{
		String valuesText = values.isValued() ? valuesTooltipBody(values) : NOT_VALUED;
		String note = record.getNote() == null ? "" : "<br>" + formatNote(record.getNote());
		String locationText = location == null ? "" : "<br>" + escapeHtml(TaskLocation.format(location));
		String variantText = variantTooltip(record);
		return "<html>" + valuesText + variantText + locationText + "<br>"
			+ formatSuperiors(record.getSuperiorsSpawned()) + "<br>"
			+ formatBankTrips(record.getBankTrips()) + "<br>" + formatDeaths(record.getDeaths())
			+ taskContextTooltip(record) + bossKillCountTooltip(record.getBossKillCounts(), record.getMonster())
			+ taskLootTooltip(record, values.getMode()) + note + "</html>";
	}

	/**
	 * The tooltip line of a task done on its Catacombs variant, {@code <br>Catacombs variant of Aberrant
	 * spectres}, or "" for the standard monster.
	 */
	static String variantTooltip(LedgerRecord record)
	{
		String variant = record.getVariant();
		if (variant == null || variant.trim().isEmpty() || record.getMonster() == null)
		{
			return "";
		}
		return "<br>" + escapeHtml("Catacombs variant of " + record.getMonster());
	}

	/**
	 * The boss kill count lines ({@link BossKillCounts#lines}) of a tooltip, each starting with {@code <br>}; "" when
	 * there are none (for example a record saved before they were recorded).
	 *
	 * @param taskName the task's name, or {@code null}
	 */
	static String bossKillCountTooltip(List<BossKillCount> counts, String taskName)
	{
		StringBuilder sb = new StringBuilder();
		for (String line : BossKillCounts.lines(counts, taskName))
		{
			sb.append("<br>").append(escapeHtml(line));
		}
		return sb.toString();
	}

	/**
	 * The keys, clue scrolls and notable drops lines of a history row's tooltip, each starting with {@code <br>}. Keys
	 * and clues come from the record's loot ({@link KeysAndClues}); a kind with none, and a record without loot or
	 * notable drops (for example one saved before they were recorded), has no line at all.
	 *
	 * @param mode the price mode the notable drops' values are shown in ({@code null} is GE)
	 */
	static String taskLootTooltip(LedgerRecord record, LootPriceMode mode)
	{
		StringBuilder sb = new StringBuilder();
		KeysAndClues keysAndClues = KeysAndClues.of(record.getLoot());
		if (keysAndClues.hasKeys())
		{
			sb.append("<br>").append(escapeHtml(keysAndClues.keysText()));
		}
		if (keysAndClues.hasClues())
		{
			sb.append("<br>").append(escapeHtml(keysAndClues.cluesText()));
		}
		sb.append(notableDropsTooltip(record.getNotableDrops(), mode));
		return sb.toString();
	}

	/** Most notable drops listed in the live panel; the rest are in its tooltip. */
	static final int LIVE_NOTABLE_DROP_LINES = 3;

	/**
	 * The live panel's keys, clue scrolls and notable drops lines: {@code Keys: 2 brimstone} and
	 * {@code Clues: 1 hard, 2 elite} when there are any, then {@code Notable drops:} with the newest
	 * {@link #LIVE_NOTABLE_DROP_LINES} drops (short values in {@code mode}) and {@code +N more} for the rest. Empty when
	 * there is nothing to show.
	 */
	static List<String> liveTaskLootLines(KeysAndClues keysAndClues, List<NotableDrop> drops, LootPriceMode mode)
	{
		List<String> lines = new ArrayList<>();
		if (keysAndClues != null && keysAndClues.hasKeys())
		{
			lines.add(keysAndClues.keysText());
		}
		if (keysAndClues != null && keysAndClues.hasClues())
		{
			lines.add(keysAndClues.cluesText());
		}
		List<NotableDrop> sorted = NotableDrops.newestFirst(drops);
		if (!sorted.isEmpty())
		{
			lines.add("Notable drops:");
			for (int i = 0; i < Math.min(LIVE_NOTABLE_DROP_LINES, sorted.size()); i++)
			{
				lines.add("  " + formatNotableDrop(sorted.get(i), mode, false));
			}
			if (sorted.size() > LIVE_NOTABLE_DROP_LINES)
			{
				lines.add("  +" + (sorted.size() - LIVE_NOTABLE_DROP_LINES) + " more");
			}
		}
		return lines;
	}

	/**
	 * {@code <br>Notable drops:} followed by one indented line per drop, newest first, with exact values in
	 * {@code mode}; "" when there are none.
	 */
	static String notableDropsTooltip(List<NotableDrop> drops, LootPriceMode mode)
	{
		List<NotableDrop> sorted = NotableDrops.newestFirst(drops);
		if (sorted.isEmpty())
		{
			return "";
		}
		StringBuilder sb = new StringBuilder("<br>Notable drops:");
		for (NotableDrop drop : sorted)
		{
			sb.append("<br>&nbsp;&nbsp;").append(escapeHtml(formatNotableDrop(drop, mode, true)));
		}
		return sb.toString();
	}

	/**
	 * One notable drop: {@code Abyssal whip: 1.5M}, {@code Rune bar x 25: 300K}, {@code Pet} or
	 * {@code Pet (already owned)}. The value is in {@code mode} ({@code null} is GE) as it was when the drop arrived,
	 * {@link #NO_VALUE} when unknown; {@code exact} gives the full amount in gp, for tooltips.
	 */
	static String formatNotableDrop(NotableDrop drop, LootPriceMode mode, boolean exact)
	{
		if (drop.isPet())
		{
			return drop.getPet() == NotableDrop.Pet.DUPLICATE ? "Pet (already owned)" : "Pet";
		}
		String name = drop.getName() != null ? drop.getName()
			: drop.getItemId() != null ? "Item " + drop.getItemId() : "Unknown drop";
		String quantity = drop.getQuantity() > 1 ? " x " + QuantityFormatter.formatNumber(drop.getQuantity()) : "";
		Long value = drop.value(mode);
		String valueText = value == null ? NO_VALUE
			: exact ? formatGpExact(value) : QuantityFormatter.quantityToStackSize(value);
		return name + quantity + ": " + valueText;
	}

	/**
	 * The task context lines of a history row's tooltip, each starting with {@code <br>}: the master, the type, the
	 * points earned and the streak. A part that is unknown (for example in a record saved before it was recorded) has
	 * no line at all.
	 */
	static String taskContextTooltip(LedgerRecord record)
	{
		StringBuilder sb = new StringBuilder();
		if (SlayerMaster.isKnown(record.getSlayerMaster()))
		{
			sb.append("<br>").append(escapeHtml(formatMaster(record.getSlayerMaster())));
		}
		TaskType type = TaskType.of(record.getSlayerMaster(), record.getCreatureId());
		if (type != null)
		{
			sb.append("<br>").append(escapeHtml(formatTaskType(type, record.getTaskLocation())));
		}
		if (record.getPointsEarned() != null)
		{
			sb.append("<br>").append(formatPointsEarned(record.getPointsEarned()));
		}
		if (record.getTaskStreak() != null)
		{
			sb.append("<br>").append(formatTaskStreak(record.getTaskStreak()));
		}
		return sb.toString();
	}

	/**
	 * {@code Master: Konar}; {@code Unknown master (n)} for a value not in {@link SlayerMaster}'s table; or
	 * {@code Master: -} when no master is known.
	 */
	static String formatMaster(Integer master)
	{
		if (!SlayerMaster.isKnown(master))
		{
			return "Master: " + NO_VALUE;
		}
		String name = SlayerMaster.displayName(master);
		return SlayerMaster.hasName(master) ? "Master: " + name : name;
	}

	/**
	 * {@code Type: Konar (Kraken Cove)}, {@code Type: Boss} and so on, or {@code Type: -} when the type is unknown.
	 *
	 * @param location the task's assigned area name (Konar's tasks), or {@code null}
	 */
	static String formatTaskType(TaskType type, String location)
	{
		if (type == null)
		{
			return "Type: " + NO_VALUE;
		}
		return "Type: " + type + (location == null ? "" : " (" + location + ")");
	}

	/** {@code Points earned: N}, or {@code Points earned: -} when unknown. */
	static String formatPointsEarned(Integer pointsEarned)
	{
		return "Points earned: " + formatCount(pointsEarned);
	}

	/** {@code Task streak: N}, or {@code Task streak: -} when unknown. */
	static String formatTaskStreak(Integer taskStreak)
	{
		return "Task streak: " + formatCount(taskStreak);
	}

	/** {@code Note: ...} for an HTML tooltip, with the note's HTML special characters escaped. */
	static String formatNote(String note)
	{
		return "Note: " + escapeHtml(note);
	}

	/** Escapes {@code &}, {@code <} and {@code >} for Swing HTML text; {@code null} becomes "". */
	static String escapeHtml(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Text of the history "Edit note" dialog. */
	static String editNotePrompt(LedgerRecord record)
	{
		return String.format("Note for this %s task (up to %d characters; leave empty to remove it):", monster(record),
			TaskNote.MAX_LENGTH);
	}

	/** {@code Superiors: N}, or {@code Superiors: -} when not counted. */
	static String formatSuperiors(Integer superiorsSpawned)
	{
		return "Superiors: " + formatCount(superiorsSpawned);
	}

	/** {@code Bank trips: N}, or {@code Bank trips: -} when not counted. */
	static String formatBankTrips(Integer bankTrips)
	{
		return "Bank trips: " + formatCount(bankTrips);
	}

	/** {@code Deaths: N}, or {@code Deaths: -} when not counted. */
	static String formatDeaths(Integer deaths)
	{
		return "Deaths: " + formatCount(deaths);
	}

	/**
	 * A history row's XP: {@code XP: 12,345}, or {@code XP: -} for a task saved before XP was tracked (see
	 * {@link SkillXp#totalText}).
	 */
	static String formatXp(LedgerRecord record)
	{
		return SkillXp.totalText(record.getXpGained(), 0);
	}

	/**
	 * A history row's XP per hour of active time, labelled so it doesn't read as gp: {@code XP/h: 40.1K}; ""
	 * when the XP was not recorded or the task had too little active time for a rate.
	 */
	static String formatXpRate(LedgerRecord record)
	{
		if (record.getXpGained() == null)
		{
			return "";
		}
		Long rate = SkillXp.perHour(SkillXp.total(record.getXpGained()), record.getActiveMillis());
		return rate == null ? "" : "XP/h: " + formatAmount(rate, false);
	}

	/** A count, or {@link #NO_VALUE} when it is unknown ({@code null}). Never shows an unknown count as 0. */
	static String formatCount(Integer count)
	{
		return count == null ? NO_VALUE : Integer.toString(count);
	}

	/** Tooltip body of a valued history row: the values, the prices used and any approximations. */
	private static String valuesTooltipBody(HistoryPricing.Values v)
	{
		long lootGe = v.getLootGe() != null ? v.getLootGe() : 0;
		long lootHa = v.getLootHa() != null ? v.getLootHa() : 0;
		long suppliesGe = v.getSuppliesGe() != null ? v.getSuppliesGe() : 0;
		long suppliesHa = v.getSuppliesHa() != null ? v.getSuppliesHa() : 0;
		return valuesTooltipBody(v.getMode(), v.getLootValue(), lootGe, lootHa, suppliesGe, suppliesHa,
			v.getLootUnpriced(), v.getLootGeUnpriced(), v.getSuppliesUnpriced())
			+ (v.isCurrentPrices() ? "<br>" + CURRENT_PRICES : v.isSavedTotals() ? "<br>" + SAVED_TOTALS : "");
	}

	/** HTML tooltip of the live session values. */
	static String valuesTooltip(SessionValuation.Values v)
	{
		return "<html>" + valuesTooltipBody(v.getLootPriceMode(), v.getLootValue(), v.getLootGe(), v.getLootHa(),
			v.getSuppliesGe(), v.getSuppliesHa(), v.getLootValueUnpriced(), v.getLootUnpriced(), v.getSuppliesUnpriced())
			+ "</html>";
	}

	/**
	 * HTML tooltip for GE and high-alchemy loot and supply values with the loot at GE prices, noting the loot and
	 * supply items whose GE price was unavailable.
	 */
	static String valuesTooltip(long lootGe, long lootHa, long suppliesGe, long suppliesHa, int lootUnpriced,
		int suppliesUnpriced)
	{
		return "<html>" + valuesTooltipBody(LootPriceMode.GE, lootGe, lootGe, lootHa, suppliesGe, suppliesHa,
			lootUnpriced, lootUnpriced, suppliesUnpriced) + "</html>";
	}

	/**
	 * Exact GE and high-alchemy loot and supply values, a GE figure marked {@link #APPROXIMATE} when some of its GE
	 * prices were unavailable; the loot value in {@code mode} when that is not GE; the profit (loot in {@code mode}
	 * minus supplies at GE); and a note when some loot (priced in {@code mode}, and at GE when that is not the mode) or
	 * supply items had no price. So in High alch mode a missing GE price is still flagged.
	 *
	 * @param lootUnpriced   distinct loot items without a price in {@code mode}
	 * @param lootGeUnpriced distinct loot items without a GE price
	 */
	private static String valuesTooltipBody(LootPriceMode mode, long lootValue, long lootGe, long lootHa,
		long suppliesGe, long suppliesHa, int lootUnpriced, int lootGeUnpriced, int suppliesUnpriced)
	{
		boolean geMode = mode == null || mode == LootPriceMode.GE;
		StringBuilder sb = new StringBuilder();
		sb.append("Loot: ").append(formatGpExact(lootGe, lootGeUnpriced > 0)).append(" GE, ")
			.append(formatGpExact(lootHa)).append(" high alch");
		if (!geMode)
		{
			sb.append("<br>Loot value (").append(mode).append("): ").append(formatGpExact(lootValue));
		}
		sb.append("<br>Supplies: ").append(formatGpExact(suppliesGe, suppliesUnpriced > 0)).append(" GE, ")
			.append(formatGpExact(suppliesHa)).append(" high alch");
		sb.append("<br>Profit: ").append(formatGpExact(profit(lootValue, suppliesGe)));
		if (mode == null || mode == LootPriceMode.GE)
		{
			sb.append(" GE");
		}
		else
		{
			sb.append(" (loot at ").append(mode.toString().toLowerCase(Locale.ROOT)).append(", supplies at GE)");
		}
		if (!geMode && lootGeUnpriced > 0)
		{
			sb.append("<br>").append(unpricedNote(mode, lootUnpriced, lootGeUnpriced, suppliesUnpriced));
		}
		else if (lootUnpriced > 0 || suppliesUnpriced > 0)
		{
			sb.append("<br>").append(unpricedNote(lootUnpriced, suppliesUnpriced));
		}
		return sb.toString();
	}

	/** {@link #formatGpExact(long)}, prefixed with {@link #APPROXIMATE} when {@code approximate}. */
	private static String formatGpExact(long value, boolean approximate)
	{
		return (approximate ? APPROXIMATE : "") + formatGpExact(value);
	}

	/**
	 * Explains a {@link #APPROXIMATE} total. Loot and supplies are counted separately (not added up), because one item
	 * can be both loot and a supply and would otherwise be counted twice.
	 */
	static String unpricedNote(int lootUnpriced, int suppliesUnpriced)
	{
		return String.format("~ Some prices were unavailable (loot: %d, supplies: %d), so totals may be too low.",
			lootUnpriced, suppliesUnpriced);
	}

	/**
	 * {@link #unpricedNote(int, int)} in a loot price mode other than GE when some loot GE prices were unavailable:
	 * the loot is counted both in {@code mode} and at GE, for example
	 * {@code (loot at high alch: 0, loot at GE: 1, supplies: 0)}.
	 */
	static String unpricedNote(LootPriceMode mode, int lootUnpriced, int lootGeUnpriced, int suppliesUnpriced)
	{
		return String.format("~ Some prices were unavailable (loot at %s: %d, loot at GE: %d, supplies: %d), so the"
			+ " figures marked ~ may be too low.", mode.toString().toLowerCase(Locale.ROOT), lootUnpriced, lootGeUnpriced,
			suppliesUnpriced);
	}
}

package com.shmayvan.slayerledger;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * The shown account's saved history and everything worked out from it: its records and "Skipped /
 * blocked" entries, the new-task chat preview and the overlay's historical time per kill. Since the off-EDT views the
 * rest is kept by three collaborators it owns: how loot is valued ({@link HistoryValuation}: the "Loot price" mode,
 * today's GE prices and the wait for them), the player's region names and item names ({@link NameBook}) and the sidebar's
 * derived views ({@link LedgerViews}: the per-task statistics, the task advisor, Trends, Overall totals, the luck
 * meter, the "Skipped / blocked" rows and What to bring). The model is still the one entry point: callers read and
 * write through it, and it decides what each change means and tells its listener ({@link Change}). The plugin creates
 * and owns it and writes to it; the panel observes it ({@link #setListener}) and only renders the immutable results it
 * returns.
 *
 * <p>Threading: EDT only. Every method, including the getters, must be called on the Swing event dispatch thread, as
 * the panel's were; the exceptions are the static {@link #liveInputs} and the instance method
 * {@link #isWaitingForCurrentPrices}, which reads one volatile field (in {@link HistoryValuation}). Nothing here is
 * synchronized. The advice, Trends and Overall totals are worked out on a background executor from an immutable
 * snapshot and handed back on the EDT ({@link LedgerViews}): they return {@code null} until ready, then the
 * listener is told {@link Change#VIEWS}.
 * The tracker it reads is synchronized, so the EDT may read it. The plugin's callbacks it calls
 * ({@code requestLocationNames}, {@code requestCurrentPrices} and {@code requestItemNames}, which the plugin's
 * {@link ClientLookups} serves, {@code postAssignmentPreview} and {@code publishHistoricalPace}) are the plugin's EDT
 * entry points: they queue client-thread work or write one volatile field. The panel's listener
 * ({@link #setListener}) is told of every change, on the EDT and after the change is complete, and redraws what it
 * shows. The lists and views it returns are unmodifiable and replaced, never changed, when what they come from
 * changes.</p>
 *
 * <p>Derived views are worked out on demand and cached until what they come from changes: the records
 * ({@link #version}), how they are valued ({@link #valuationVersion}), item names where they are shown, and the view's
 * own inputs (a metric, a grouping, a task). Asking again with nothing changed returns the same object, so the panel's
 * refresh timer never works them out again. The per-task statistics stay on the EDT: the chat preview and the
 * overlay's time per kill decide from them at once.</p>
 *
 * <p>No Swing or AWT: whether a chat line is posted, what the overlay is told and when a wait for today's prices runs
 * out are decided here, not by a refresh timer. The plugin re-checks them ({@link #refreshLive}) whenever the live task
 * or session changes ({@link #liveInputs}), and ends an expired wait for today's prices ({@link
 * #endExpiredCurrentPricesWait}) on the settled ticks while one runs; the panel's own refresh also ends an expired wait
 * and re-checks the preview. The preview is also re-checked whenever what it waits for arrives ({@link #setRecords},
 * {@link #addLocationNames}, {@link #endCurrentPricesWait}).</p>
 */
final class LedgerHistoryModel
{
	/** See {@link HistoryValuation#CURRENT_PRICES_WAIT_MILLIS}. */
	static final long CURRENT_PRICES_WAIT_MILLIS = HistoryValuation.CURRENT_PRICES_WAIT_MILLIS;

	private final SessionTracker tracker;
	private final Consumer<String> previewPoster;
	private final Consumer<OverlayRows.HistoricalPace> pacePublisher;
	/** How the history is valued. */
	private final HistoryValuation valuation;
	/** Region and item names. */
	private final NameBook names;
	/** The cached derived views. */
	private final LedgerViews views;
	/**
	 * Which of the records' loot ids Ground Items' hidden list hides, from the item names; the result is kept
	 * by {@link #valuation}.
	 */
	private final HiddenLootResolver hiddenLoot = new HiddenLootResolver();
	/**
	 * Whether a loot item's name that {@link #updateHiddenLoot} asked for has not arrived yet while the list hides
	 * something, so the hidden loot may still change; the chat preview waits for it.
	 */
	private boolean hiddenLootNamesPending;
	/** Told of every change (EDT); the panel's, none until set. */
	private Consumer<Change> listener = change -> { };
	/** Set by {@link #shutDown}: nothing is asked for, posted or published any more. */
	private boolean closed;

	// History
	/** Account whose records are held, or {@link SessionTracker#NO_ACCOUNT} when none are. */
	private long account = SessionTracker.NO_ACCOUNT;
	/** All records of {@link #account}, newest first; unmodifiable. */
	private List<LedgerRecord> records = Collections.emptyList();
	/** Whether {@link #records} are {@link #account}'s loaded records, not a message's empty list. */
	private boolean loaded;
	/** "Skipped / blocked" entries of {@link #account}, newest first; unmodifiable. */
	private List<AssignmentEntry> assignments = Collections.emptyList();
	/** Why the history is empty ({@link #clearRecords}), or {@code null} while records are held. */
	private String historyMessage;
	/** Bumped whenever {@link #records}, {@link #assignments} or {@link #account} change. */
	private long version;

	// Live
	/**
	 * Whether the latest {@link #currentLocation} may change once a region name asked of the plugin arrives.
	 */
	private boolean currentLocationPending;
	/** A new assignment whose chat preview waits for what it needs ({@link #checkAssignmentPreview}), or null. */
	private AssignmentPreview pendingPreview;

	/** What changed, as told to the listener ({@link #setListener}). */
	enum Change
	{
		/** New records; the views valued at today's prices are redrawn now. */
		RECORDS,
		/** New records, but the views valued at today's prices keep what they show until the prices arrive. */
		RECORDS_WAITING_FOR_PRICES,
		/** The records were dropped, with a message to show instead ({@link #historyMessage}). */
		HISTORY_CLEARED,
		/** New "Skipped / blocked" entries. */
		ASSIGNMENTS,
		/** Another "Loot price" mode. */
		LOOT_PRICE_MODE,
		/**
		 * Other loot items are hidden: Ground Items' hidden list or the setting changed, or names arrived that
		 * match it. Every view valued from the loot is redrawn.
		 */
		HIDDEN_LOOT,
		/** Today's prices arrived while nothing waited for them: the views valued at them are redrawn. */
		CURRENT_PRICES,
		/** A wait for today's prices ended: every view valued at them is redrawn. */
		PRICED_VIEWS,
		/** Region names arrived and one changed: records' and the current task's locations may differ. */
		LOCATION_NAMES,
		/** Region names arrived and none changed. */
		LOCATION_NAMES_UNCHANGED,
		/** Every region name was forgotten (another RuneScape profile). */
		LOCATION_NAMES_CLEARED,
		/** Item names (or the nature rune's price) arrived. */
		ITEM_NAMES,
		/** The task advisor settings changed. */
		TASK_ADVISOR,
		/**
		 * A view worked out in the background (the advice, Trends or Overall totals) is ready: what shows it is redrawn.
		 */
		VIEWS
	}

	/**
	 * @param locationNameRequests asks the plugin for the names of regions (EDT)
	 * @param currentPriceRequests asks the plugin for today's GE prices of item ids (EDT)
	 * @param itemNameRequests     asks the plugin for the names of item ids, and the nature rune's price (EDT)
	 * @param previewPoster        posts a new assignment's chat preview line (EDT)
	 * @param pacePublisher        publishes the overlay's historical time per kill, or {@code null} to clear it (EDT)
	 * @param viewExecutor         works out the advice, Trends and Overall totals off the EDT (the plugin's executor)
	 * @param edt                  runs their results on the EDT ({@code SwingUtilities::invokeLater})
	 */
	LedgerHistoryModel(SessionTracker tracker, LootPriceMode lootPriceMode,
		Consumer<Set<Integer>> locationNameRequests, Consumer<Set<Integer>> currentPriceRequests,
		Consumer<Set<Integer>> itemNameRequests, Consumer<String> previewPoster,
		Consumer<OverlayRows.HistoricalPace> pacePublisher, Executor viewExecutor, Executor edt)
	{
		this.tracker = tracker;
		this.previewPoster = previewPoster;
		this.pacePublisher = pacePublisher;
		valuation = new HistoryValuation(lootPriceMode, currentPriceRequests);
		names = new NameBook(locationNameRequests, itemNameRequests);
		// The views get the records from setHistory, not from the model.
		views = new LedgerViews(tracker, valuation, names, viewExecutor, edt);
		views.setOnReady(() -> fire(Change.VIEWS));
	}

	/**
	 * Sets what is told of every change (the panel, which redraws); EDT. It is called on the EDT, after the change is
	 * complete, and may read the model.
	 */
	void setListener(Consumer<Change> listener)
	{
		this.listener = listener == null ? change -> { } : listener;
	}

	/** Sets what reads the bundled luck-meter snapshot; it is read once, the first time the luck meter is shown. */
	void setLuckMeterSource(Supplier<LuckMeter> source)
	{
		views.setLuckMeterSource(source);
	}

	private void fire(Change change)
	{
		listener.accept(change);
	}

	/** The plugin stopped: the waiting preview is dropped and nothing is asked for, posted or published again. */
	void shutDown()
	{
		closed = true;
		names.close();
		views.close();
		pendingPreview = null;
	}

	// ---- History ----

	/** Account whose history is held, or {@link SessionTracker#NO_ACCOUNT} when none is. */
	long account()
	{
		return account;
	}

	/** The account's records, newest first; unmodifiable, and empty while none are loaded. */
	List<LedgerRecord> records()
	{
		return records;
	}

	/** Whether {@link #records} are the account's loaded records (not the empty list of a message). */
	boolean isLoaded()
	{
		return loaded;
	}

	/** The account's "Skipped / blocked" entries, newest first; unmodifiable. */
	List<AssignmentEntry> assignments()
	{
		return assignments;
	}

	/** Bumped on every change of the account, its records or its entries; never goes back. */
	long version()
	{
		return version;
	}

	/**
	 * Holds an account's saved records (in any order; copied) and drops the statistics. Asks for today's prices of the
	 * items not priced yet; returns whether the views valued at today's prices should be redrawn now ({@code false}
	 * while they keep what they show until the prices arrive, which is never longer than
	 * {@link #CURRENT_PRICES_WAIT_MILLIS}; another account's records and an emptied history are always redrawn at
	 * once, and again when the prices arrive). The plugin clears the history before it loads another account's
	 * records ({@link #clearRecords}), so a first load waits too. The caller must have checked that {@code account} is
	 * still the account whose history should be shown. Tells the listener {@link Change#RECORDS} or
	 * {@link Change#RECORDS_WAITING_FOR_PRICES}.
	 */
	boolean setRecords(long account, List<LedgerRecord> records)
	{
		final boolean sameAccount = account == this.account;
		this.account = account;
		this.records = Collections.unmodifiableList(LedgerHistory.sortNewestFirst(records));
		loaded = true;
		historyMessage = null;
		version++;
		updateHiddenLoot();
		views.setHistory(this.account, version, this.records, assignments);
		clearTaskStatistics();
		requestCurrentPrices();
		final boolean redraw = !sameAccount || this.records.isEmpty() || !waitForCurrentPrices();
		if (redraw)
		{
			valuation.stopWaiting();
		}
		refreshHistoricalPace();
		// A preview waiting for the records is posted now, not on a panel redraw.
		checkAssignmentPreview();
		fire(redraw ? Change.RECORDS : Change.RECORDS_WAITING_FOR_PRICES);
		return redraw;
	}

	/**
	 * Drops the records and entries (logged out, loading, or a load failure), keeping {@code account} as the one shown;
	 * nothing waits for today's prices any more. {@code message} says why ({@link #historyMessage}). Tells the listener
	 * {@link Change#HISTORY_CLEARED}.
	 */
	void clearRecords(long account, String message)
	{
		valuation.stopWaiting();
		this.account = account;
		records = Collections.emptyList();
		loaded = false;
		assignments = Collections.emptyList();
		historyMessage = message;
		version++;
		updateHiddenLoot();
		views.setHistory(this.account, version, records, assignments);
		clearTaskStatistics();
		refreshHistoricalPace();
		fire(Change.HISTORY_CLEARED);
	}

	/** Why the history is empty (the message of the last {@link #clearRecords}), or {@code null}. */
	String historyMessage()
	{
		return historyMessage;
	}

	/**
	 * Holds an account's "Skipped / blocked" entries (in any order; copied). Ignored, returning {@code false}, unless
	 * {@code account}'s history is the one held; otherwise tells the listener {@link Change#ASSIGNMENTS}.
	 */
	boolean setAssignments(long account, List<AssignmentEntry> entries)
	{
		if (account != this.account)
		{
			return false;
		}
		assignments = Collections.unmodifiableList(AssignmentLog.sortNewestFirst(entries));
		version++;
		views.setHistory(this.account, version, records, assignments);
		fire(Change.ASSIGNMENTS);
		return true;
	}

	// ---- Valuation (kept by HistoryValuation) ----

	LootPriceMode lootPriceMode()
	{
		return valuation.lootPriceMode();
	}

	/**
	 * Sets the "Loot price" mode ({@code null} is GE); returns whether it changed, which drops the statistics and tells
	 * the listener {@link Change#LOOT_PRICE_MODE}.
	 */
	boolean setLootPriceMode(LootPriceMode mode)
	{
		if (!valuation.setLootPriceMode(mode))
		{
			return false;
		}
		clearTaskStatistics();
		fire(Change.LOOT_PRICE_MODE);
		return true;
	}

	/** See {@link HistoryValuation#shownPrices}: today's GE prices the history is valued at; never {@code null}. */
	Map<Integer, Long> shownPrices()
	{
		return valuation.shownPrices();
	}

	/**
	 * Asks the plugin (once, in one batch) for today's GE price of every item in the records that has none yet and is
	 * not already asked for.
	 */
	void requestCurrentPrices()
	{
		if (!closed)
		{
			valuation.requestCurrentPrices(records);
		}
	}

	/**
	 * Adds today's GE prices the plugin looked up again after they were unavailable ({@code prices}, for those of
	 * {@code requested} that it found; {@code requested} was not pending); see
	 * {@link #addCurrentPrices(Set, Map, Set)}.
	 */
	void addCurrentPrices(Set<Integer> requested, Map<Integer, Long> prices)
	{
		addCurrentPrices(requested, prices, Collections.emptySet());
	}

	/**
	 * Adds today's GE prices the plugin looked up ({@code prices}, for those of {@code requested} that it found). The
	 * plugin also sends the prices it found when it looked up again the ones that were unavailable ({@code requested}
	 * is then not pending). While the views wait for prices ({@link #waitForCurrentPrices}), the wait ends once the
	 * last batch asked for has arrived and none of {@code retrying} is still being looked up again (for example while
	 * RuneLite's price list loads at client start), or once it runs out ({@link #endExpiredCurrentPricesWait});
	 * otherwise, when some price is new or changed, the statistics are dropped and the listener is told
	 * {@link Change#CURRENT_PRICES}. An answer that adds no new price redraws nothing.
	 *
	 * @param retrying ids of {@code requested} that came back without a price and that the plugin looks up again
	 *                 ({@link PriceRetry}); may be empty
	 */
	void addCurrentPrices(Set<Integer> requested, Map<Integer, Long> prices, Set<Integer> retrying)
	{
		final boolean changed = valuation.addCurrentPrices(requested, prices, retrying);
		if (valuation.isWaitingForCurrentPrices())
		{
			if (valuation.isWaitOver())
			{
				endCurrentPricesWait();
			}
			return;
		}
		if (!changed)
		{
			return;
		}
		clearTaskStatistics();
		fire(Change.CURRENT_PRICES);
	}

	/** Whether some prices asked for have not arrived yet. */
	boolean isCurrentPricesPending()
	{
		return valuation.isCurrentPricesPending();
	}

	/** See {@link HistoryValuation#waitForCurrentPrices}. */
	boolean waitForCurrentPrices()
	{
		return valuation.waitForCurrentPrices();
	}

	/**
	 * Whether the views valued at today's prices keep what they show until the prices asked for arrive. Any
	 * thread (one volatile read): the plugin checks it on the client thread to ask for
	 * {@link #endExpiredCurrentPricesWait} on the EDT.
	 */
	boolean isWaitingForCurrentPrices()
	{
		return valuation.isWaitingForCurrentPrices();
	}

	/** See {@link HistoryValuation#currentPricesWaitExpired}; the caller ends the wait ({@link #endCurrentPricesWait}). */
	boolean currentPricesWaitExpired()
	{
		return valuation.currentPricesWaitExpired();
	}

	/** Test seam: lets a wait for today's prices run out at once, as if no answer came in time. */
	void expireCurrentPricesWait()
	{
		valuation.expireCurrentPricesWait();
	}

	/**
	 * Ends any wait for today's prices and drops the statistics, checks the waiting chat preview again and tells the
	 * listener {@link Change#PRICED_VIEWS}, so every view valued at them is redrawn.
	 */
	void endCurrentPricesWait()
	{
		valuation.stopWaiting();
		clearTaskStatistics();
		checkAssignmentPreview();
		fire(Change.PRICED_VIEWS);
	}

	/**
	 * Ends a wait for today's prices that has lasted {@link #CURRENT_PRICES_WAIT_MILLIS} (an answer never came;
	 * {@link #currentPricesWaitExpired}): the waiting chat preview is checked again ({@link #endCurrentPricesWait}) and
	 * the panel redraws its views valued at today's prices with the prices there are ({@link Change#PRICED_VIEWS}).
	 * Returns whether it did; does nothing while no wait has run out, so it may be called as often as wanted.
	 */
	boolean endExpiredCurrentPricesWait()
	{
		if (closed || !currentPricesWaitExpired())
		{
			return false;
		}
		endCurrentPricesWait();
		return true;
	}

	/** Bumped whenever how the history is valued changes: the mode, today's prices or the hidden loot. */
	long valuationVersion()
	{
		return valuation.valuationVersion();
	}

	// ---- Hidden loot ----

	/**
	 * Hides what {@code list} hides from now on (Ground Items' hidden list, or {@link GroundItemsHidden#NONE} while
	 * the setting or Ground Items is off; {@code null} is none). When that changes which loot is hidden, the statistics
	 * are dropped and the listener is told {@link Change#HIDDEN_LOOT}. Item names not known yet are asked for; the
	 * items are matched again when they arrive ({@link #addItemNames}).
	 */
	void setGroundItemsHidden(GroundItemsHidden list)
	{
		if (hiddenLoot.setList(list) && updateHiddenLoot())
		{
			hiddenLootChanged();
		}
	}

	/** The records' loot items left out of the loot value and the "Loot received" grids; never {@code null}. */
	HiddenLoot hiddenLoot()
	{
		return valuation.hiddenLoot();
	}

	/**
	 * Works out which of the records' loot ids are hidden, from the names known, and asks for the missing names while
	 * something can be hidden. Returns whether that changed (which bumps the valuation version); the caller tells the
	 * listener.
	 */
	private boolean updateHiddenLoot()
	{
		Set<Integer> ids = new HashSet<>();
		if (!hiddenLoot.list().isEmpty())
		{
			for (LedgerRecord record : records)
			{
				if (record.getLoot() != null)
				{
					ids.addAll(record.getLoot().keySet());
				}
			}
			ids.remove(null);
			names.requestItemNames(ids);
		}
		hiddenLootNamesPending = false;
		for (Integer id : ids)
		{
			if (names.isItemNamePending(id))
			{
				hiddenLootNamesPending = true;
				break;
			}
		}
		return valuation.setHiddenLoot(hiddenLoot.resolve(ids, names::itemBaseName));
	}

	/** Other loot is hidden: drops the statistics, re-checks the waiting chat preview and tells the listener. */
	private void hiddenLootChanged()
	{
		clearTaskStatistics();
		checkAssignmentPreview();
		fire(Change.HIDDEN_LOOT);
	}

	// ---- Region names (kept by NameBook) ----

	/** The player's name for {@code region}, or {@code null} when it has none or it is not known yet. */
	String locationName(Integer region)
	{
		return names.locationName(region);
	}

	/** Asks the plugin (once, in one batch) for the names of {@code regions} not known, asked for or missing yet. */
	void requestLocationNames(Set<Integer> regions)
	{
		names.requestLocationNames(regions);
	}

	/**
	 * Adds region names from the plugin ({@code names}, for the regions in {@code requested} that have one; also sent
	 * when the player names one). Requested regions without a name are not asked for again. Returns whether a name
	 * changed: the statistics are then dropped (a record's or the current task's location may have changed) and the
	 * overlay's time per kill is worked out again.
	 */
	boolean addLocationNames(Set<Integer> requested, Map<Integer, String> names)
	{
		boolean changed = this.names.addLocationNames(requested, names);
		if (changed)
		{
			clearTaskStatistics();
		}
		refreshHistoricalPace();
		// A preview waiting for a location name is posted now, not on a panel redraw.
		checkAssignmentPreview();
		fire(changed ? Change.LOCATION_NAMES : Change.LOCATION_NAMES_UNCHANGED);
		return changed;
	}

	/**
	 * Forgets every region name (another RuneScape profile is active): they are asked for again as needed. Tells the
	 * listener {@link Change#LOCATION_NAMES_CLEARED}.
	 */
	void clearLocationNames()
	{
		names.clearLocationNames();
		clearTaskStatistics();
		refreshHistoricalPace();
		fire(Change.LOCATION_NAMES_CLEARED);
	}

	/** Whether some region names asked for have not arrived yet. */
	boolean isLocationNamePending()
	{
		return names.isLocationNamePending();
	}

	/**
	 * The current task's location for the same-location estimates ({@link TaskLocation#currentName}): its assigned
	 * area, else the name of the running or paused session's region with the most kills, else the name of the region
	 * the player is in. Names not known yet are asked of the plugin (once each); {@code null} while unknown.
	 */
	String currentLocation()
	{
		SessionTracker.State state = tracker.getState();
		boolean active = state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED;
		String area = active ? tracker.getSessionTaskLocation() : null;
		if (area == null)
		{
			area = tracker.getCurrentContext().getLocation();
		}
		Integer sessionRegion = active ? tracker.getDominantRegion() : null;
		int currentRegion = tracker.getCurrentRegion();
		currentLocationPending = false;
		if (TaskLocation.normalizeName(area) == null)
		{
			// Where the player stands matters only while the session's own region has no name.
			Set<Integer> regions = new HashSet<>();
			if (sessionRegion != null)
			{
				regions.add(sessionRegion);
			}
			if (sessionRegion == null || !names.hasLocationName(sessionRegion))
			{
				regions.add(currentRegion);
			}
			names.requestLocationNames(regions);
			for (Integer region : regions)
			{
				currentLocationPending |= names.isLocationNamePending(region);
			}
		}
		return TaskLocation.currentName(area, sessionRegion, currentRegion, names::locationName);
	}

	/**
	 * Whether the latest {@link #currentLocation} may change once a region name asked of the plugin arrives
	 * ({@link #addLocationNames}).
	 */
	boolean isCurrentLocationPending()
	{
		return currentLocationPending;
	}

	// ---- Item names (kept by NameBook) ----

	/** The name of item {@code id} (as tallied), or {@code null} when it is not known (yet). */
	String itemName(Integer id)
	{
		return names.itemName(id);
	}

	/** The nature rune's GE price for the alch hint, or {@code null} while unknown. */
	Long natureRunePrice()
	{
		return names.natureRunePrice();
	}

	/** Whether the name of {@code id} was asked for and has not arrived yet. */
	boolean isItemNamePending(Integer id)
	{
		return names.isItemNamePending(id);
	}

	/** Whether the plugin could not name {@code id}. */
	boolean isItemNameFailed(Integer id)
	{
		return names.isItemNameFailed(id);
	}

	/** See {@link NameBook#requestItemNames}; the answer comes through {@link #addItemNames}. */
	void requestItemNames(Set<Integer> ids)
	{
		names.requestItemNames(ids);
	}

	/**
	 * Adds item names looked up by the plugin ({@code names}, for the ids in {@code requested} that have one) and the
	 * nature rune's GE price ({@code null} when unavailable); ids without a name are not asked for again. Tells the
	 * listener {@link Change#ITEM_NAMES}.
	 */
	void addItemNames(Set<Integer> requested, Map<Integer, String> names, Long natureRune)
	{
		this.names.addItemNames(requested, names, natureRune);
		fire(Change.ITEM_NAMES);
		// A name that arrived may be one Ground Items hides.
		if (!hiddenLoot.list().isEmpty() && updateHiddenLoot())
		{
			hiddenLootChanged();
		}
		// A preview waiting for those names is posted now that the hidden loot is worked out.
		checkAssignmentPreview();
	}

	// ---- Live: the chat preview and the overlay's time per kill ----

	/**
	 * What {@link #refreshLive} depends on that the tracker holds: the session's state and id, the task and its kills
	 * left, which version of it the session's kills say is done and whether it fired a cannonball
	 * ({@link SessionTracker#getCurrentTaskSelection}), and every input of {@link #currentLocation}. Any
	 * thread (the tracker is synchronized); the plugin reads it on the client thread each settled tick and asks for
	 * {@link #refreshLive} on the EDT only when it changed.
	 */
	static List<Object> liveInputs(SessionTracker tracker)
	{
		SessionTracker.State state = tracker.getState();
		return Arrays.asList(state, tracker.getSessionId(), tracker.isTaskObserved(), tracker.getCurrentCreatureId(),
			tracker.getCurrentMonster(), tracker.getCurrentRemaining(), tracker.getSessionTaskLocation(),
			tracker.getCurrentContext().getLocation(), tracker.getDominantRegion(), tracker.getCurrentRegion(),
			tracker.getCurrentTaskSelection());
	}

	/**
	 * Ends a wait for today's prices that ran out ({@link #endExpiredCurrentPricesWait}), re-checks the waiting chat
	 * preview and publishes the overlay's time per kill again.
	 */
	void refreshLive()
	{
		endExpiredCurrentPricesWait();
		checkAssignmentPreview();
		refreshHistoricalPace();
	}

	/**
	 * The plugin saw a new assignment of {@code account}: its chat preview is posted once the history and what
	 * the estimate needs are here ({@link #checkAssignmentPreview}), at most once. A later one replaces it.
	 */
	void requestAssignmentPreview(long account, int creatureId, String monster)
	{
		if (closed)
		{
			return;
		}
		pendingPreview = new AssignmentPreview(account, creatureId, monster);
		checkAssignmentPreview();
	}

	/** Whether an assignment preview waits to be posted. */
	boolean isAssignmentPreviewPending()
	{
		return pendingPreview != null;
	}

	/**
	 * Posts the waiting assignment preview through the plugin, built like the History estimate for the kills left
	 * (the same statistics, location first), or drops it. It waits while the account's records are loading, today's
	 * prices are on their way, a location name is, or a loot item name that decides the hidden loot is; it is
	 * dropped once that task is no longer the current one or another account's history is held. Without completed
	 * history nothing is posted.
	 */
	void checkAssignmentPreview()
	{
		AssignmentPreview preview = pendingPreview;
		if (preview == null || closed)
		{
			return;
		}
		int remaining = tracker.getCurrentRemaining();
		if (preview.account != account || !tracker.isTaskObserved() || remaining <= 0
			|| tracker.getCurrentCreatureId() != preview.creatureId
			|| !Objects.equals(TaskStatistics.normalize(tracker.getCurrentMonster()),
			TaskStatistics.normalize(preview.monster)))
		{
			pendingPreview = null;
			return;
		}
		if (!loaded || valuation.isWaitingForCurrentPrices() || hiddenLootNamesPending)
		{
			// addItemNames re-checks once the names that decide the hidden loot are here.
			return;
		}
		String location = currentLocation();
		TaskStatistics stats = taskStatistics(preview.creatureId, preview.monster, location);
		if (currentLocationPending || names.isLocationNamePending())
		{
			// addLocationNames drops the statistics; the next check builds them again.
			return;
		}
		pendingPreview = null;
		String line = AssignmentPreviewMessage.format(LedgerRecord.displayName(preview.monster, preview.creatureId),
			remaining, stats, valuation.lootPriceMode());
		if (line != null)
		{
			previewPoster.accept(line);
		}
	}

	/**
	 * The historical time per kill the sidebar's "Time left" uses for the running or paused session's task (at its
	 * location first, and of the version and cannon use its session shows), or {@code null} with no such
	 * session or no history for its task.
	 */
	OverlayRows.HistoricalPace historicalPace()
	{
		SessionTracker.State state = tracker.getState();
		if (state != SessionTracker.State.RUNNING && state != SessionTracker.State.PAUSED)
		{
			return null;
		}
		TaskStatistics stats = taskStatistics(tracker.getCurrentCreatureId(), tracker.getCurrentMonster(),
			tracker.getCurrentTaskSelection(), currentLocation());
		Long perKill = stats.getSampleCount() == 0 ? null : stats.getMillisPerKill();
		String sessionId = tracker.getSessionId();
		return perKill == null || sessionId == null ? null : new OverlayRows.HistoricalPace(sessionId, perKill);
	}

	/**
	 * Publishes {@link #historicalPace} to the plugin for the overlay: run when the records, a region name, the
	 * task, its location or the session change.
	 */
	void refreshHistoricalPace()
	{
		if (closed)
		{
			return;
		}
		pacePublisher.accept(historicalPace());
	}

