	/** Adds the progress, note, values, item lists, task loot and dart hint rows to {@code content}. */
	void addTo(JPanel content)
	{
		countsLine.setOpaque(false);
		for (JLabel label : new JLabel[]{superiorsLabel, deathsLabel, bankTripsLabel})
		{
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			label.setFont(FontManager.getRunescapeSmallFont());
		}
		deathsLabel.setHorizontalAlignment(JLabel.CENTER);
		countsLine.add(superiorsLabel, BorderLayout.WEST);
		countsLine.add(deathsLabel, BorderLayout.CENTER);
		countsLine.add(bankTripsLabel, BorderLayout.EAST);
		// Added back while a session is running or paused; a hidden label would still take a GridLayout row.
		progressSection.remove(timeLeftLabel);
		xpLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		xpLabel.setFont(FontManager.getRunescapeSmallFont());
		((GridLayout) progressSection.getLayout()).setRows(progressSection.getComponentCount());
		SlayerLedgerPanel.addRow(content, progressSection);
		SlayerLedgerPanel.addRow(content, noteSection);
		valuesSection.setVisible(false);
		SlayerLedgerPanel.addRow(content, valuesSection);
		for (TitledListView<?> list : new TitledListView<?>[]{liveSupplies, liveLoot, liveXp})
		{
			list.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
			list.setVisible(false);
			SlayerLedgerPanel.addRow(content, list);
		}
		taskLootSection.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		taskLootSection.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		taskLootSection.setVisible(false);
		SlayerLedgerPanel.addRow(content, taskLootSection);
		dartHintLabel.setForeground(ColorScheme.BRAND_ORANGE);
		dartHintLabel.setFont(FontManager.getRunescapeSmallFont());
		dartHintLabel.setToolTipText("<html>Blowpipe darts are counted once the plugin knows the dart type.<br>"
			+ "Use Check on the blowpipe; until then only Zulrah's scales are counted.</html>");
		dartHintLabel.setVisible(false);
		SlayerLedgerPanel.addRow(content, dartHintLabel);
	}

	/** Keeps the live values to show ({@link SlayerLedgerPanel#setSessionValues}); the next refresh shows them. */
	void setSessionValues(SessionValuation.Values values)
	{
		sessionValues = values;
	}

	/** Asks for (or withdraws) the "Check your blowpipe" hint; the next refresh shows or hides it. */
	void setDartHint(boolean requested)
	{
		dartHintRequested = requested;
	}

	/** Updates every row from the tracker for {@code state}, with {@code remaining} kills left on the task. */
	void refresh(SessionTracker.State state, int remaining)
	{
		stateLabel.setText("State: " + stateText(state));
		final long activeMillis = tracker.getActiveMillis();
		final int kills = tracker.getKills();
		killsLabel.setText("Kills: " + kills);
		elapsedLabel.setText("Elapsed: " + LedgerHistory.formatDuration(activeMillis));
		refreshActiveRows(state, activeMillis, kills, remaining);
		refreshNote(state);
	}

	/** Updates the values, item lists, task loot and dart hint for {@code state}. */
	void refreshValuesAndLoot(SessionTracker.State state)
	{
		refreshValues(state);
		refreshTaskLoot(state);
		boolean hint = dartHintRequested && state == SessionTracker.State.RUNNING;
		if (dartHintLabel.isVisible() != hint)
		{
			dartHintLabel.setVisible(hint);
			relayout.run();
		}
	}

	/** Redraws the task loot in the new "Loot price" mode; the values follow it through the plugin's values. */
	void lootPriceModeChanged()
	{
		refreshTaskLoot(tracker.getState());
	}

	/** Redraws the item lists once item names arrive. */
	void itemNamesChanged()
	{
		refreshItemLists(shownValues(sessionValues, tracker.getState(), tracker.getSessionId()));
	}

	// ---- Session note ----

	private JPanel buildNoteSection()
	{
		JPanel section = new JPanel(new BorderLayout(6, 0));
		section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		section.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		JLabel label = new JLabel("Note");
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		section.add(label, BorderLayout.WEST);

		noteBox.setEditable(true);
		// Sized from a short label, not the longest note, so a long note never widens the sidebar.
		noteBox.setPrototypeDisplayValue("Strength gear");
		noteBox.setToolTipText("<html>How you're doing this task, e.g. Barrage. Saved with the task.<br>"
			+ "Type a note and press Enter, or pick a recent one.</html>");
		noteBox.addActionListener(e ->
		{
			Object picked = noteBox.getSelectedItem();
			if (!updatingNote && "comboBoxChanged".equals(e.getActionCommand()) && picked != null)
			{
				// A pick from the list: make sure the editor shows it before it is read.
				setNoteEditorText(picked.toString());
			}
			commitNote();
		});
		noteBox.getEditor().getEditorComponent().addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				commitNote();
			}
		});
		setRecentNotes(TaskNote.DEFAULTS);
		section.add(noteBox, BorderLayout.CENTER);
		section.setVisible(false);
		return section;
	}

	/** Text in the note box's editor (what the player has typed so far). */
	private String noteEditorText()
	{
		Object item = noteBox.getEditor().getItem();
		return item == null ? "" : item.toString();
	}

	/** Puts {@code text} in the note box without it counting as the player's edit. */
	private void setNoteEditorText(String text)
	{
		String shown = text == null ? "" : text;
		updatingNote = true;
		try
		{
			noteBox.setSelectedItem(shown);
			noteBox.getEditor().setItem(shown);
		}
		finally
		{
			updatingNote = false;
		}
	}

	/**
	 * Sends the typed note to the session the note box belongs to (Enter, a pick from the list, leaving the box, or
	 * Stop), and shows it as it was saved (trimmed and shortened).
	 */
	void commitNote()
	{
		if (updatingNote || noteSessionId == null)
		{
			return;
		}
		String note = TaskNote.normalize(noteEditorText());
		if (!Objects.equals(note, committedNote))
		{
			committedNote = note;
			saveNote.save(noteAccount, noteSessionId, note);
		}
		if (!noteEditorText().equals(note == null ? "" : note))
		{
			setNoteEditorText(note);
		}
	}

	/** Replaces the note box's list, keeping what is in its editor. */
	void setRecentNotes(List<String> notes)
	{
		if (notes.equals(recentNotes))
		{
			return;
		}
		recentNotes = notes;
		String text = noteEditorText();
		updatingNote = true;
		try
		{
			noteBox.setModel(new DefaultComboBoxModel<>(notes.toArray(new String[0])));
		}
		finally
		{
			updatingNote = false;
		}
		setNoteEditorText(text);
	}

	/**
	 * Shows the note box while a session is running or paused, filled with that session's note. While the player is
	 * typing (the box has focus) or picking (its list is open) the text is left alone; when the session ends, text
	 * still being typed is sent first, to the session it was typed for.
	 */
	private void refreshNote(SessionTracker.State state)
	{
		boolean active = state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED;
		String sessionId = active ? tracker.getSessionId() : null;
		if (noteSessionId != null && !noteSessionId.equals(sessionId))
		{
			commitNote();
			noteSessionId = null;
			noteAccount = SessionTracker.NO_ACCOUNT;
			committedNote = null;
			setNoteEditorText(null);
		}
		if (sessionId != null)
		{
			String note = tracker.getNote();
			if (noteSessionId == null)
			{
				noteSessionId = sessionId;
				noteAccount = tracker.getSessionAccountHash();
				committedNote = note;
				setNoteEditorText(note);
			}
			else if (!isNoteBeingEdited() && !Objects.equals(note, committedNote))
			{
				committedNote = note;
				setNoteEditorText(note);
			}
		}
		if (noteSection.isVisible() != active)
		{
			noteSection.setVisible(active);
			relayout.run();
		}
	}

	/** Whether the player is typing in, or picking from, the note box. */
	private boolean isNoteBeingEdited()
	{
		return noteBox.getEditor().getEditorComponent().isFocusOwner() || noteBox.isPopupVisible();
	}

	// ---- Progress ----

	/**
	 * Shows the estimated time left (it stands still while paused, as active time does), the session's XP (the total
	 * line and the per-skill list) and its superior spawns, deaths and bank trips while a session is running or
	 * paused; hides them otherwise.
	 */
	private void refreshActiveRows(SessionTracker.State state, long activeMillis, int kills, int remaining)
	{
		boolean active = state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED;
		if (active)
		{
			// The same statistics as the overlay's time per kill (LedgerHistoryModel#historicalPace), which the model
			// publishes itself when they or the session change.
			TaskStatistics stats = model.taskStatistics(tracker.getCurrentCreatureId(), tracker.getCurrentMonster(),
				tracker.getCurrentTaskSelection(), model.currentLocation());
			Long historicalPerKill = stats.getSampleCount() == 0 ? null : stats.getMillisPerKill();
			timeLeftLabel.setText(timeLeftText(activeMillis, kills, remaining, historicalPerKill));
			if (!LedgerHistory.isHistoricalTimeLeft(activeMillis, kills, remaining, historicalPerKill))
			{
				timeLeftLabel.setToolTipText(timeLeftTooltip(activeMillis, kills));
			}
			else
			{
				timeLeftLabel.setToolTipText(String.format("<html>Historical estimate from %d completed %s%s; assumes "
					+ "the same average time per kill.<br>The live pace takes over after %d kills and %d minute of "
					+ "active time.</html>", stats.getSampleCount(), stats.getSampleCount() == 1 ? "task" : "tasks",
					stats.getLocation() == null ? "" : " at " + LedgerHistory.escapeHtml(stats.getLocation()),
					TaskTimeEstimate.MIN_KILLS, TaskTimeEstimate.MIN_ACTIVE_MILLIS / 60_000));
			}
			superiorsLabel.setText(LedgerHistory.formatSuperiors(tracker.getSuperiorsSpawned()));
			bankTripsLabel.setText(LedgerHistory.formatBankTrips(tracker.getBankTrips()));
			deathsLabel.setText(LedgerHistory.formatDeaths(tracker.getDeaths()));
			Map<String, Long> xp = tracker.getXpGained();
			xpLabel.setText(SkillXp.totalText(xp, activeMillis));
			xpLabel.setToolTipText(SkillXp.tooltip(xp, activeMillis));
			// Without rates, so the rows (and an open tooltip) don't change every second; the total line has the rate.
			liveXp.setRows(SkillXp.rows(xp, 0));
		}
		if (liveXp.isVisible() != active)
		{
			liveXp.setVisible(active);
			relayout.run();
		}
		boolean shown = timeLeftLabel.getParent() == progressSection;
		if (shown != active)
		{
			if (active)
			{
				progressSection.add(timeLeftLabel);
				progressSection.add(xpLabel);
				progressSection.add(countsLine);
			}
			else
			{
				progressSection.remove(timeLeftLabel);
				progressSection.remove(xpLabel);
				progressSection.remove(countsLine);
			}
			((GridLayout) progressSection.getLayout()).setRows(progressSection.getComponentCount());
			relayout.run();
		}
	}

	/**
	 * Text of the time-left line: whole minutes ({@link LedgerHistory#formatTimeLeftMinutes}) at the session's pace
	 * so far (see {@link TaskTimeEstimate}), "estimating" until there are enough kills and active time, or {@code -}
	 * when no kills are left on the task (no task, or the task is done).
	 */
	static String timeLeftText(long activeMillis, int kills, int remaining)
	{
		return timeLeftText(activeMillis, kills, remaining, null);
	}

	/**
	 * Text of the time-left line with the task's historical time per kill (or {@code null}): the historical estimate
	 * until the live pace takes over ({@link LedgerHistory#formatTimeLeft(long, int, int, Long)}, as the overlay).
	 */
	static String timeLeftText(long activeMillis, int kills, int remaining, Long historicalMillisPerKill)
	{
		return "Time left: " + LedgerHistory.formatTimeLeft(activeMillis, kills, remaining, historicalMillisPerKill);
	}

	/** Tooltip of the time-left line: the pace behind the estimate, or when an estimate will appear. */
	static String timeLeftTooltip(long activeMillis, int kills)
	{
		OptionalDouble perHour = TaskTimeEstimate.killsPerHour(activeMillis, kills);
		OptionalLong perKill = TaskTimeEstimate.averageKillMillis(activeMillis, kills);
		if (!perHour.isPresent() || !perKill.isPresent())
		{
			return String.format("Estimated after %d kills and %d minute of active time.", TaskTimeEstimate.MIN_KILLS,
				TaskTimeEstimate.MIN_ACTIVE_MILLIS / 60_000);
		}
		return String.format("<html>Kills per hour: %d<br>Average kill: %s<br>Assumes the same pace as so far.</html>",
			Math.round(perHour.getAsDouble()), LedgerHistory.formatKillTime(perKill.getAsLong()));
	}

	private static String stateText(SessionTracker.State state)
	{
		switch (state)
		{
			case RUNNING:
				return "Running";
			case PAUSED:
				return "Paused";
			case STOPPED:
				return "Stopped";
			default:
				return "Idle";
		}
	}

	// ---- Values, item lists and task loot ----

	/** Live session values to show: those of the tracker's current session while it is running or paused. */
	static SessionValuation.Values shownValues(SessionValuation.Values values, SessionTracker.State state,
		String currentSessionId)
	{
		boolean active = state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED;
		if (!active || values == null || !Objects.equals(values.getSessionId(), currentSessionId))
		{
			return null;
		}
		return values;
	}

	/** Shows the live session values while a session is running or paused; clears them otherwise. */
	private void refreshValues(SessionTracker.State state)
	{
		boolean active = state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED;
		if (!active)
		{
			sessionValues = null;
		}
		SessionValuation.Values values = shownValues(sessionValues, state, tracker.getSessionId());
		if (values != null)
		{
			long profit = values.getProfit();
			lootValueLabel.setText(liveLootText(values));
			suppliesValueLabel.setText("Supplies: "
				+ LedgerHistory.formatGp(values.getSuppliesGe(), values.getSuppliesUnpriced() > 0));
			profitValueLabel.setText(liveProfitText(values));
			profitValueLabel.setForeground(SlayerLedgerPanel.profitColor(profit));
			valuesSection.setToolTipText(LedgerHistory.valuesTooltip(values));
		}
		boolean show = values != null;
		if (valuesSection.isVisible() != show)
		{
			valuesSection.setVisible(show);
			relayout.run();
		}
		refreshItemLists(values);
	}

	/**
	 * Shows the live session's supplies and loot as item icons, with {@link #valuesSection} (from the same values, so
	 * at the same prices and "Loot price" setting), and asks for the names not known yet. The icons are only rebuilt
	 * when the rows change.
	 */
	private void refreshItemLists(SessionValuation.Values values)
	{
		boolean show = values != null;
		if (show)
		{
			ItemDetails items = values.getItems();
			liveSupplies.setRows(items.supplyRows(model::itemName));
			// Without the items Ground Items hides, as the loot value leaves them out.
			liveLoot.setRows(items.withNatureRunePrice(model.natureRunePrice())
				.lootRows(values.getLootPriceMode(), model::itemName), values.getHiddenLoot());
			// Asks the plugin, through the model, for the names not known, asked for or failed yet.
			model.requestItemNames(items.itemIds());
		}
		if (liveSupplies.isVisible() != show)
		{
			liveSupplies.setVisible(show);
			liveLoot.setVisible(show);
			relayout.run();
		}
	}

	/**
	 * Shows the session's boss kill counts, keys, clue scrolls and notable drops while a session is running or paused
	 * and there are any; hides them otherwise. The notable drops' values follow the "Loot price" setting; the tooltip
	 * lists the boss kill counts and every drop.
	 */
	private void refreshTaskLoot(SessionTracker.State state)
	{
		boolean active = state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED;
		List<NotableDrop> drops = active ? tracker.getNotableDrops() : Collections.emptyList();
		List<BossKillCount> killCounts = active ? tracker.getBossKillCounts() : Collections.emptyList();
		String taskName = active ? tracker.getSessionMonster() : null;
		LootPriceMode mode = model.lootPriceMode();
		List<String> lines = new ArrayList<>(BossKillCounts.lines(killCounts, taskName));
		if (active)
		{
			lines.addAll(LedgerHistory.liveTaskLootLines(KeysAndClues.of(tracker.getLoot()), drops, mode));
		}
		if (!lines.equals(taskLootLines))
		{
			taskLootLines = lines;
			taskLootSection.removeAll();
			taskLootSection.setLayout(new GridLayout(Math.max(1, lines.size()), 1, 0, 2));
			for (String line : lines)
			{
				JLabel label = new JLabel(line);
				label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				label.setFont(FontManager.getRunescapeSmallFont());
				taskLootSection.add(label);
			}
			relayout.run();
		}
		String tooltip = LedgerHistory.bossKillCountTooltip(killCounts, taskName)
			+ LedgerHistory.notableDropsTooltip(drops, mode);
		// The tooltip lists the kill counts and every notable drop with its exact value; the sidebar may cut a long
		// name short.
		taskLootSection.setToolTipText(tooltip.isEmpty() ? null : "<html>" + tooltip.substring("<br>".length())
			+ "</html>");
		boolean show = !lines.isEmpty();
		if (taskLootSection.isVisible() != show)
		{
			taskLootSection.setVisible(show);
			relayout.run();
		}
	}

	/**
	 * The live loot line: the loot in its price mode, labelled with the mode ("Loot (GE): ..." or "Loot (HA): ...").
	 * The other figure is in the tooltip.
	 */
	static String liveLootText(SessionValuation.Values values)
	{
		return LedgerHistory.lootLabel(values.getLootPriceMode())
			+ LedgerHistory.formatGp(values.getLootValue(), values.getLootValueUnpriced() > 0);
	}

	/**
	 * The live profit line: loot in its price mode minus supplies, labelled with the mode; approximate when either has
	 * an unavailable price.
	 */
	static String liveProfitText(SessionValuation.Values values)
	{
		return LedgerHistory.profitLabel(values.getLootPriceMode()) + LedgerHistory.formatLiveProfit(values);
	}
}

package com.shmayvan.slayerledger;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/**
 * Kills a session counted in one map region. Serialized with Gson in {@link SessionSnapshot}; effectively
 * immutable (no setters). Pure (no RuneLite types). The rules are in {@link LocationTally}.
 */
@Getter
@EqualsAndHashCode
@ToString
final class LocationKills
{
	/** Map region id of the local player's tile when the kills were counted (instances as their template region). */
	private int region;
	/** Kills counted in {@link #region}; at least 1. */
	private int kills;

	/** For Gson. */
	private LocationKills()
	{
	}

	LocationKills(int region, int kills)
	{
		this.region = region;
		this.kills = kills;
	}
}

package com.shmayvan.slayerledger;

import java.util.HashSet;
import java.util.Set;

/**
 * Which map region the panel's "Name this location" prompt asks about. A counted kill in a region without a
 * name offers it; one region is asked about at a time, and the prompt stays until the player saves a name or skips
 * it. A skipped region is not asked about again: the plugin keeps the skip in the RuneScape profile's config and
 * says so in {@link #offer}; this class also remembers it until {@link #forgetSkips} or {@link #reset}, so a skip that
 * could not be kept (no profile yet) still holds for the account. Pure (no RuneLite types); client thread only.
 */
final class LocationPrompt
{
	private final Set<Integer> skipped = new HashSet<>();
	private int shown = LocationTally.NO_REGION;

	/**
	 * Offers the region of a counted kill.
	 *
	 * @param named        whether the region already has a name
	 * @param skippedSaved whether the active profile's config has the region as skipped
	 * @return whether the prompt should now be shown for {@code region}
	 */
	boolean offer(int region, boolean named, boolean skippedSaved)
	{
		if (!LocationTally.isRegion(region) || named || skippedSaved || LocationTally.isRegion(shown)
			|| skipped.contains(region))
		{
			return false;
		}
		shown = region;
		return true;
	}

	/** The player skipped naming {@code region}: it is not asked about again until {@link #forgetSkips}. */
	void skip(int region)
	{
		skipped.add(region);
		if (shown == region)
		{
			shown = LocationTally.NO_REGION;
		}
	}

	/** {@code region} got a name; its prompt (if shown) is done. */
	void named(int region)
	{
		if (shown == region)
		{
			shown = LocationTally.NO_REGION;
		}
	}

	/** Hides the prompt (logout, another profile) without skipping its region: a later kill there asks again. */
	void hide()
	{
		shown = LocationTally.NO_REGION;
	}

	/**
	 * Forgets the skipped regions (another profile is active, or the player asked about them again), without hiding a
	 * shown prompt.
	 */
	void forgetSkips()
	{
		skipped.clear();
	}

	/** Forgets everything, for a new plugin run. */
	void reset()
	{
		skipped.clear();
		shown = LocationTally.NO_REGION;
	}

	/** The region the prompt is shown for, or {@link LocationTally#NO_REGION}. */
	int getShown()
	{
		return shown;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.Collections;
import java.util.List;
import java.util.function.BiPredicate;
import java.util.function.IntConsumer;
import javax.swing.BorderFactory;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.text.JTextComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The inline, non-modal "Name this location" prompt below the task box of {@link SlayerLedgerPanel}, shown when a
 * kill was counted in a region without a name: an editable name with suggestions, Save and Skip. EDT only.
 */
final class LocationPromptView
{
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** The client's injected Gson, used to read the bundled Wiki locations. */
	private final Gson gson;
	/** Saves the name for the region; {@code true} when it was saved, so the prompt is hidden. */
	private final BiPredicate<Integer, String> save;
	/** Skips the prompt for the region on this account, until "Ask again about skipped places". */
	private final IntConsumer skip;

	private final JPanel panel = new JPanel(new BorderLayout(0, 4));
	private final JLabel label = new JLabel(SlayerLedgerPanel.LOCATION_PROMPT_TITLE);
	/**
	 * The prompt's name: typed, or picked from the suggestions (Part B: the task's bundled Wiki locations, then the
	 * player's names for other regions). Editable; its editor is limited to {@link TaskLocation#MAX_NAME_LENGTH}.
	 */
	private final JComboBox<String> box = new JComboBox<>();
	/** The text field of {@link #box}'s editor. */
	private JTextComponent field;
	/** While the view itself changes {@link #box}, so its events are not the player's. */
	private boolean updating;
	/** The bundled task location list (Part B), read once when the prompt is first shown; {@code null} if it failed. */
	private TaskLocations taskLocations;
	private boolean taskLocationsLoaded;
	/** Resource of {@link #taskLocations}; tests point it at a missing or broken file. */
	private String taskLocationsResource = TaskLocations.SNAPSHOT_RESOURCE;
	private final JButton saveButton = new JButton("Save");
	private final JButton skipButton = new JButton("Skip");
	/** Region the prompt asks about, or {@link LocationTally#NO_REGION} while it is hidden. */
	private int region = LocationTally.NO_REGION;

	LocationPromptView(Gson gson, Runnable relayout, BiPredicate<Integer, String> save, IntConsumer skip)
	{
		this.gson = gson;
		this.relayout = relayout;
		this.save = save;
		this.skip = skip;
	}

	/** Adds the prompt to {@code content}, hidden. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		panel.setName("locationPrompt");
		box.setName("locationPrompt.box");
		saveButton.setName("locationPrompt.save");
		skipButton.setName("locationPrompt.skip");
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, ColorScheme.BRAND_ORANGE),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setToolTipText("<html>Kills here are in a map region you haven't named yet.<br>The name is "
			+ "kept for this account and used for every task here.<br>Skip stops asking about this place on this"
			+ " account;<br>the Ask again about skipped places setting undoes it.</html>");
		box.setEditable(true);
		// Sized from a short name, not the longest suggestion, so a long one never widens the sidebar.
		box.setPrototypeDisplayValue("Smoke Dungeon");
		box.setToolTipText("<html>Type a name of up to " + TaskLocation.MAX_NAME_LENGTH
			+ " characters,<br>or pick one: the Wiki's locations for this task, then your other names.</html>");
		field = (JTextComponent) box.getEditor().getEditorComponent();
		LengthLimitFilter.apply(field, TaskLocation.MAX_NAME_LENGTH);
		JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
		buttons.setOpaque(false);
		for (JButton button : new JButton[]{saveButton, skipButton})
		{
			button.setMargin(new Insets(2, 4, 2, 4));
			buttons.add(button);
		}
		panel.add(label, BorderLayout.NORTH);
		panel.add(box, BorderLayout.CENTER);
		panel.add(buttons, BorderLayout.SOUTH);
		panel.setVisible(false);
		saveButton.addActionListener(e -> saveTyped());
		// Enter in the field saves too. Not the combo box's own "comboBoxEdited": Swing also fires it when the field
		// loses focus (clicking Skip or the game), which would save a half-typed name. A list pick only fills the field.
		if (field instanceof JTextField)
		{
			((JTextField) field).addActionListener(e ->
			{
				if (!updating)
				{
					saveTyped();
				}
			});
		}
		skipButton.addActionListener(e ->
		{
			int skipped = region;
			hide();
			if (LocationTally.isRegion(skipped))
			{
				skip.accept(skipped);
			}
		});
		SlayerLedgerPanel.addRow(content, panel);
	}

	/** The prompt's Save: an empty name (after {@link TaskLocation#normalizeName}) is not saved and the prompt stays. */
	private void saveTyped()
	{
		int saved = region;
		if (!LocationTally.isRegion(saved) || TaskLocation.normalizeName(field.getText()) == null)
		{
			return;
		}
		if (save.test(saved, field.getText()))
		{
			hide();
		}
	}

	/**
	 * Shows the prompt for map region {@code newRegion}, with an empty field and the names it suggests
	 * ({@link TaskLocation#suggestions}): the bundled Wiki locations of {@code monster}'s task, then {@code ownNames},
	 * the player's names for other regions. Without the bundled list (it failed to load) only the player's names are
	 * suggested. Nothing changes when it is already shown for that region.
	 */
	void show(int newRegion, String monster, List<String> ownNames)
	{
		if (!LocationTally.isRegion(newRegion) || newRegion == region)
		{
			return;
		}
		region = newRegion;
		TaskLocations bundled = taskLocations();
		List<String> suggestions = TaskLocation.suggestions(
			bundled == null ? Collections.emptyList() : bundled.locationsFor(monster), ownNames);
		updating = true;
		try
		{
			box.setModel(new DefaultComboBoxModel<>(suggestions.toArray(new String[0])));
			box.setSelectedItem(null);
		}
		finally
		{
			updating = false;
		}
		field.setText("");
		panel.setVisible(true);
		relayout.run();
	}

	/** The bundled task location list, read once; {@code null} when it could not be read (logged by its load). */
	private TaskLocations taskLocations()
	{
		if (!taskLocationsLoaded)
		{
			taskLocationsLoaded = true;
			taskLocations = gson == null ? null : TaskLocations.load(gson, taskLocationsResource);
		}
		return taskLocations;
	}

	/** Hides the prompt. */
	void hide()
	{
		region = LocationTally.NO_REGION;
		if (box.isPopupVisible())
		{
			box.setPopupVisible(false);
		}
		if (panel.isVisible())
		{
			panel.setVisible(false);
			relayout.run();
		}
	}

	/** The region the prompt asks about, or {@link LocationTally#NO_REGION} while hidden. */
	int getRegion()
	{
		// Test seam (through the panel): the region is not shown in the prompt.
		return panel.isVisible() ? region : LocationTally.NO_REGION;
	}

	/** Reads the bundled task location list from {@code resource} instead, before the prompt is first shown. */
	void setTaskLocationsResource(String resource)
	{
		// Test seam (through the panel): lets a test point the prompt at a missing or broken list.
		taskLocationsResource = resource;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.List;

/**
 * Rules for a session's kills per map region: each counted kill is added to the region the local player stood in
 * when the task count went down, in the order regions are first seen. The task's location is the region with the most
 * kills; ties go to the region seen first. Pure (no RuneLite types); the lists passed in are never changed.
 */
final class LocationTally
{
	/** Value used for "no region known" (no local player or scene yet). Valid region ids are never negative. */
	static final int NO_REGION = -1;
	/** Most regions tallied per session; kills in further regions are still counted, only not tallied. */
	static final int MAX_REGIONS = 64;

	private LocationTally()
	{
	}

	/** Whether {@code region} is a region id (not {@link #NO_REGION} or another negative value). */
	static boolean isRegion(int region)
	{
		return region >= 0;
	}

	/**
	 * A copy of {@code tally} with {@code kills} more kills in {@code region} (saturating). Nothing is added for an
	 * unknown region, no kills, or a new region once {@link #MAX_REGIONS} are tallied.
	 *
	 * @param tally the tally so far, or {@code null} for none
	 */
	static List<LocationKills> add(List<LocationKills> tally, int region, int kills)
	{
		final List<LocationKills> result = sanitize(tally);
		if (!isRegion(region) || kills <= 0)
		{
			return result;
		}
		for (int i = 0; i < result.size(); i++)
		{
			final LocationKills entry = result.get(i);
			if (entry.getRegion() == region)
			{
				result.set(i, new LocationKills(region, saturatedAdd(entry.getKills(), kills)));
				return result;
			}
		}
		if (result.size() < MAX_REGIONS)
		{
			result.add(new LocationKills(region, kills));
		}
		return result;
	}

	/**
	 * A clean copy of a tally (for example one read from a file): entries without a region or kills are dropped, a
	 * repeated region is merged into its first entry, and at most {@link #MAX_REGIONS} regions are kept. Never
	 * {@code null}.
	 */
	static List<LocationKills> sanitize(List<LocationKills> tally)
	{
		final List<LocationKills> result = new ArrayList<>();
		if (tally == null)
		{
			return result;
		}
		for (LocationKills entry : tally)
		{
			if (entry == null || !isRegion(entry.getRegion()) || entry.getKills() <= 0)
			{
				continue;
			}
			boolean merged = false;
			for (int i = 0; i < result.size(); i++)
			{
				if (result.get(i).getRegion() == entry.getRegion())
				{
					result.set(i, new LocationKills(entry.getRegion(),
						saturatedAdd(result.get(i).getKills(), entry.getKills())));
					merged = true;
					break;
				}
			}
			if (!merged && result.size() < MAX_REGIONS)
			{
				result.add(new LocationKills(entry.getRegion(), entry.getKills()));
			}
		}
		return result;
	}

	/** Whether {@code tally} has kills in {@code region}. */
	static boolean contains(List<LocationKills> tally, int region)
	{
		if (tally == null || !isRegion(region))
		{
			return false;
		}
		for (LocationKills entry : tally)
		{
			if (entry != null && entry.getRegion() == region && entry.getKills() > 0)
			{
				return true;
			}
		}
		return false;
	}

	/** The region with the most kills, the earliest seen among equals, or {@code null} when nothing is tallied. */
	static Integer dominantRegion(List<LocationKills> tally)
	{
		if (tally == null)
		{
			return null;
		}
		LocationKills best = null;
		for (LocationKills entry : tally)
		{
			if (entry == null || !isRegion(entry.getRegion()) || entry.getKills() <= 0)
			{
				continue;
			}
			// Strictly more, so the earliest seen region wins a tie.
			if (best == null || entry.getKills() > best.getKills())
			{
				best = entry;
			}
		}
		return best == null ? null : best.getRegion();
	}

	private static int saturatedAdd(int a, int b)
	{
		final long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}
}

package com.shmayvan.slayerledger;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/**
 * Decides which items of one kill-loot drop are counted, when the loot is captured: the items a bonecrusher or ash
 * sanctifier destroyed ({@link CrushedLootFilter}) and the player's ignored items ({@link IgnoredLoot}) are left out.
 * Saved records and loot already counted are never changed. Pure: item facts come from an {@link ItemNames} the plugin
 * backs with item compositions on the client thread.
 */
final class LootFilter
{
	/** Item facts for the ignored-items check. Implementations may only be valid on the client thread. */
	interface ItemNames
	{
		/** The unnoted item's id for a noted item, otherwise {@code itemId}. */
		int unnoted(int itemId);

		/** The item's name, or {@code null} when unknown. */
		String name(int itemId);
	}

	private final CrushedLootFilter crushed;
	private final IgnoredLoot ignored;

	LootFilter(CrushedLootFilter crushed, IgnoredLoot ignored)
	{
		this.crushed = Objects.requireNonNull(crushed);
		this.ignored = Objects.requireNonNull(ignored);
	}

	/**
	 * The loot that counts. Item facts are only looked up when items are ignored, at most once per distinct id; a
	 * failed lookup leaves that item to be matched by its id alone.
	 *
	 * @param loot  the drop, by item id as received
	 * @param names item facts; not used when nothing is ignored
	 */
	ItemTally apply(ItemTally loot, ItemNames names)
	{
		final ItemTally kept = new ItemTally();
		if (loot == null)
		{
			return kept;
		}
		final Map<Integer, Boolean> ignoredIds = new HashMap<>();
		for (int id : loot.itemIds())
		{
			if (crushed.keeps(id) && !ignoredIds.computeIfAbsent(id, k -> isIgnored(k, names)))
			{
				kept.add(id, loot.get(id));
			}
		}
		return kept;
	}

	private boolean isIgnored(int itemId, ItemNames names)
	{
		if (ignored.isEmpty())
		{
			return false;
		}
		int unnoted = itemId;
		String name = null;
		try
		{
			unnoted = names.unnoted(itemId);
			if (ignored.hasNames())
			{
				name = names.name(unnoted);
			}
		}
		catch (RuntimeException e)
		{
			// Item data unavailable: only an id entry can match.
		}
		return ignored.ignores(itemId, unnoted, name);
	}
}

package com.shmayvan.slayerledger;

/**
 * Which price values kill loot; see {@link LootPricing}. Supplies are always valued at GE prices, because they are
 * bought.
 *
 * <p>A "Higher of the two" option was removed (owner decision, 2026-10-25). A config value saved for it no longer
 * matches a constant; RuneLite's config proxy then returns the item's default, GE.</p>
 */
public enum LootPriceMode
{
	/** The Grand Exchange price. */
	GE("GE"),
	/** The high-alchemy value. */
	HIGH_ALCH("High alch");

	private final String displayName;

	LootPriceMode(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.shmayvan.slayerledger;

import java.util.Map;
import java.util.TreeMap;

/**
 * Pure loot valuation in a {@link LootPriceMode}, from per-item GE and high-alchemy unit prices (keyed by the id as
 * tallied, as in {@link ItemValuation.UnitPrices}). No RuneLite dependencies.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>An item whose GE unit price is exactly 0 (untradeable, see {@link ItemValuation}) is valued at its
 *     high-alchemy unit value in every mode (owner decision, 2026-10-25). It has a known price, so it is not
 *     unpriced. An item <em>without</em> a GE price (unavailable) is not affected by this rule.</li>
 *     <li>{@link LootPriceMode#GE GE}: the GE unit price; an item without one is unpriced (left out, counted).</li>
 *     <li>{@link LootPriceMode#HIGH_ALCH High alch}: the high-alchemy unit value; an item without one is unpriced.</li>
 *     <li>Quantities in doses or bites are valued per dose ({@link ItemValuation#total(ItemTally, Map, Map)}).</li>
 * </ul>
 */
final class LootPricing
{
	private LootPricing()
	{
	}

	/**
	 * The unit price of every id in {@code ge} or {@code ha} in {@code mode}, leaving out ids without one. Either map
	 * may be {@code null} (no prices of that kind).
	 */
	static Map<Integer, Long> unitPrices(LootPriceMode mode, Map<Integer, Long> ge, Map<Integer, Long> ha)
	{
		Map<Integer, Long> result = new TreeMap<>();
		switch (mode == null ? LootPriceMode.GE : mode)
		{
			case HIGH_ALCH:
				putAll(result, ha);
				break;
			default:
				result.putAll(geUnitPrices(ge, ha));
				break;
		}
		return result;
	}

	/**
	 * The GE unit price of every id in {@code ge}, with a price of exactly 0 replaced by the id's high-alchemy value
	 * from {@code ha} when it has one (see the class rules). Ids without a GE price are left out. Either map may be
	 * {@code null}.
	 */
	static Map<Integer, Long> geUnitPrices(Map<Integer, Long> ge, Map<Integer, Long> ha)
	{
		Map<Integer, Long> result = new TreeMap<>();
		putAll(result, ge);
		if (ha != null)
		{
			for (Map.Entry<Integer, Long> e : result.entrySet())
			{
				Long alch = ha.get(e.getKey());
				if (e.getValue() == 0 && alch != null && alch > 0)
				{
					e.setValue(alch);
				}
			}
		}
		return result;
	}

	private static void putAll(Map<Integer, Long> into, Map<Integer, Long> from)
	{
		if (from == null)
		{
			return;
		}
		for (Map.Entry<Integer, Long> e : from.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null)
			{
				into.put(e.getKey(), e.getValue());
			}
		}
	}

	/** Total value of {@code tally} in {@code mode}; see the class rules. Saturates at {@link Long#MAX_VALUE}. */
	static long total(ItemTally tally, LootPriceMode mode, Map<Integer, Long> ge, Map<Integer, Long> ha,
		Map<Integer, Integer> dosesPerItem)
	{
		return ItemValuation.total(tally, unitPrices(mode, ge, ha), dosesPerItem);
	}

	/**
	 * Distinct items of {@code tally} whose value in {@code mode} is unknown: without the mode's price. An item with a
	 * GE price of 0 has a known price in GE mode, so it is not counted.
	 */
	static int countUnpriced(ItemTally tally, LootPriceMode mode, Map<Integer, Long> ge, Map<Integer, Long> ha)
	{
		return ItemValuation.countUnpriced(tally, mode == LootPriceMode.HIGH_ALCH ? ha : ge);
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * Expected counts for the selected, bundled Slayer drop-table entries. An instance holds one validated snapshot
 * ({@link #load}); the comparison logic is pure (no RuneLite types).
 */
@Slf4j
final class LuckMeter
{
	/** The bundled snapshot, relative to this class. */
	static final String SNAPSHOT_RESOURCE = "slayer-drop-snapshot.json";
	/** The only snapshot schema version this build reads. */
	static final int SNAPSHOT_VERSION = 1;
	/** Suffix the plugin adds to a noted item's name. */
	private static final String NOTED_SUFFIX = " (noted)";

	private final Snapshot snapshot;

	private LuckMeter(Snapshot snapshot)
	{
		this.snapshot = snapshot;
	}

	/**
	 * Reads and validates the snapshot {@code resource} (relative to this class) with {@code gson}, the client's
	 * injected instance. Returns {@code null}, logged at debug level, when the resource is missing, unreadable,
	 * malformed or invalid, so a bad snapshot never breaks the panel.
	 */
	static LuckMeter load(Gson gson, String resource)
	{
		try (InputStream stream = LuckMeter.class.getResourceAsStream(resource))
		{
			if (stream == null)
			{
				log.debug("Slayer drop snapshot {} is missing", resource);
				return null;
			}
			return parse(gson, new InputStreamReader(stream, StandardCharsets.UTF_8));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Unable to load the Slayer drop snapshot {}", resource, e);
			return null;
		}
	}

	/** Parses and validates a snapshot. Throws a {@link RuntimeException} when it is malformed or invalid. */
	static LuckMeter parse(Gson gson, Reader reader)
	{
		Snapshot snapshot = gson.fromJson(reader, Snapshot.class);
		validate(snapshot);
		return new LuckMeter(snapshot);
	}

	/**
	 * Whether a record is a sample: a completed, non-partial played task with kills whose loot was tracked. Records
	 * saved before loot tracking (schema 1) have neither {@code loot} nor values; a tracked task with no loot has no
	 * {@code loot} map (an empty tally is stored as {@code null}) but is valued.
	 */
	static boolean isSample(LedgerRecord record)
	{
		return record != null && record.isCompleted() && !record.isPartial() && record.getKills() > 0
			&& (record.getLoot() != null || LedgerHistory.isValued(record));
	}

	/** Supported task names (as in the snapshot) that have at least one sample, in snapshot order. */
	List<String> supportedTasks(Collection<LedgerRecord> records)
	{
		if (records == null || records.isEmpty())
		{
			return Collections.emptyList();
		}
		Set<String> recordedTasks = new HashSet<>();
		for (LedgerRecord record : records)
		{
			if (isSample(record))
			{
				recordedTasks.add(TaskStatistics.normalize(record.getMonster()));
			}
		}
		List<String> tasks = new ArrayList<>();
		for (Table table : snapshot.tables)
		{
			if (recordedTasks.contains(TaskStatistics.normalize(table.task)))
			{
				tasks.add(table.task);
			}
		}
		return Collections.unmodifiableList(tasks);
	}

	/**
	 * The samples for {@code task}, matched by the {@link TaskStatistics#normalize}d name (trimmed, lower case). The
	 * snapshot has no creature ids, so a record matches by name whether or not it has a {@code creatureId}.
	 */
	List<LedgerRecord> samples(Collection<LedgerRecord> records, String task)
	{
		Table table = table(task);
		if (table == null || records == null)
		{
			return Collections.emptyList();
		}
		String key = TaskStatistics.normalize(table.task);
		List<LedgerRecord> matching = new ArrayList<>();
		for (LedgerRecord record : records)
		{
			if (isSample(record) && key.equals(TaskStatistics.normalize(record.getMonster())))
			{
				matching.add(record);
			}
		}
		return matching;
	}

	/**
	 * Aggregates the samples for one task. Actual items are matched to snapshot names using the supplied item-name
	 * lookup (a noted name counts as its item); unknown names are not guessed.
	 */
	Summary summarize(Collection<LedgerRecord> records, String task, Map<Integer, String> itemNames)
	{
		Table table = table(task);
		List<LedgerRecord> samples = samples(records, task);
		if (table == null || samples.isEmpty())
		{
			return Summary.empty(table == null ? task : table.task);
		}

		Map<String, Long> actualByItem = new HashMap<>();
		long kills = 0;
		for (LedgerRecord record : samples)
		{
			kills = saturatedAdd(kills, record.getKills());
			Map<Integer, Long> loot = record.getLoot();
			if (loot == null || itemNames == null)
			{
				continue;
			}
			for (Map.Entry<Integer, Long> drop : loot.entrySet())
			{
				String key = itemKey(itemNames.get(drop.getKey()));
				Long quantity = drop.getValue();
				if (key == null || quantity == null || quantity <= 0)
				{
					continue;
				}
				actualByItem.merge(key, quantity, LuckMeter::saturatedAdd);
			}
		}

		List<DropEntry> drops = new ArrayList<>();
		for (Drop drop : table.drops)
		{
			long actual = actualByItem.getOrDefault(itemKey(drop.item), 0L);
			double expected = (double) kills * drop.numerator / drop.denominator;
			drops.add(new DropEntry(drop.item, drop.numerator, drop.denominator, actual, expected));
		}
		return new Summary(table.task, samples.size(), kills, drops);
	}

	/**
	 * The chance of at least {@code observed} drops when the count is Poisson with mean {@code expected}: 1 for
	 * {@code observed <= 0}. Summed in log space, so large means and counts neither overflow nor underflow early.
	 */
	static double chanceOfAtLeast(long observed, double expected)
	{
		if (observed <= 0)
		{
			return 1;
		}
		if (!(expected > 0) || Double.isInfinite(expected))
		{
			return Double.isInfinite(expected) ? 1 : 0;
		}
		double logMean = Math.log(expected);
		if (observed > expected)
		{
			// Upper tail directly: sum the terms from observed up until they no longer change the total.
			double logTerm = -expected + observed * logMean - logFactorial(observed);
			double sum = 0;
			for (long i = observed; ; i++)
			{
				double term = Math.exp(logTerm);
				sum += term;
				if (term <= sum * 1e-17 || i - observed > 1_000_000)
				{
					break;
				}
				logTerm += logMean - Math.log(i + 1);
			}
			return clamp(sum);
		}
		// 1 - P(X < observed): the lower tail has at most observed (<= expected) terms.
		double logTerm = -expected;
		double below = 0;
		for (long i = 0; i < observed; i++)
		{
			below += Math.exp(logTerm);
			logTerm += logMean - Math.log(i + 1);
		}
		return clamp(1 - below);
	}

	private static double logFactorial(long n)
	{
		double sum = 0;
		for (long i = 2; i <= n; i++)
		{
			sum += Math.log(i);
		}
		return sum;
	}

	private static double clamp(double value)
	{
		return Math.max(0, Math.min(1, value));
	}

	/** Snapshot metadata, for the attribution tooltip. */
	String getSnapshotDate()
	{
		return snapshot.snapshotDate;
	}

	String getSource()
	{
		return snapshot.source;
	}

	String getLicense()
	{
		return snapshot.license;
	}

	/**
	 * The item name as matched: normalized, with the plugin's " (noted)" suffix dropped. {@code null} for a blank
	 * name, which matches no drop.
	 */
	private static String itemKey(String name)
	{
		String key = TaskStatistics.normalize(name);
		return key == null ? null : key.endsWith(NOTED_SUFFIX) ? key.substring(0, key.length() - NOTED_SUFFIX.length()).trim() : key;
	}

	private Table table(String task)
	{
		String key = TaskStatistics.normalize(task);
		for (Table table : snapshot.tables)
		{
			if (TaskStatistics.normalize(table.task).equals(key))
			{
				return table;
			}
		}
		return null;
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	private static void validate(Snapshot snapshot)
	{
		if (snapshot == null || snapshot.version != SNAPSHOT_VERSION || snapshot.tables == null
			|| snapshot.tables.isEmpty() || isBlank(snapshot.snapshotDate) || isBlank(snapshot.license)
			|| isBlank(snapshot.licenseUrl) || isBlank(snapshot.source) || isBlank(snapshot.contributors)
			|| isBlank(snapshot.attribution) || isBlank(snapshot.scope))
		{
			throw new IllegalStateException("Slayer drop snapshot metadata is missing or unsupported.");
		}
		Set<String> tasks = new HashSet<>();
		for (Table table : snapshot.tables)
		{
			if (table == null || isBlank(table.task) || isBlank(table.article) || isBlank(table.page)
				|| table.revision <= 0 || table.drops == null || table.drops.isEmpty()
				|| !tasks.add(TaskStatistics.normalize(table.task)))
			{
				throw new IllegalStateException("Slayer drop snapshot has an invalid or duplicate task table.");
			}
			Set<String> items = new HashSet<>();
			for (Drop drop : table.drops)
			{
				if (drop == null || isBlank(drop.item) || drop.numerator <= 0 || drop.denominator <= 0
					|| drop.numerator > drop.denominator || !items.add(itemKey(drop.item)))
				{
					throw new IllegalStateException("Slayer drop snapshot has an invalid or duplicate drop.");
				}
			}
		}
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	static final class Summary
	{
		private final String task;
		private final int taskCount;
		private final long kills;
		private final List<DropEntry> drops;

		private Summary(String task, int taskCount, long kills, List<DropEntry> drops)
		{
			this.task = task;
			this.taskCount = taskCount;
			this.kills = kills;
			this.drops = Collections.unmodifiableList(new ArrayList<>(drops));
		}

		private static Summary empty(String task)
		{
			return new Summary(task, 0, 0, Collections.emptyList());
		}

		String getTask()
		{
			return task;
		}

		/** Samples: completed tasks with loot data. */
		int getTaskCount()
		{
			return taskCount;
		}

		/** Kills of the samples only. */
		long getKills()
		{
			return kills;
		}

		List<DropEntry> getDrops()
		{
			return drops;
		}
	}

	static final class DropEntry
	{
		/** Below this expected count the ratio is hidden (owner decision). */
		static final double MIN_EXPECTED_FOR_RATIO = 1;

		private final String item;
		private final int numerator;
		private final int denominator;
		private final long actual;
		private final double expected;

		private DropEntry(String item, int numerator, int denominator, long actual, double expected)
		{
			this.item = item;
			this.numerator = numerator;
			this.denominator = denominator;
			this.actual = actual;
			this.expected = expected;
		}

		String getItem()
		{
			return item;
		}

		int getNumerator()
		{
			return numerator;
		}

		int getDenominator()
		{
			return denominator;
		}

		long getActual()
		{
			return actual;
		}

		double getExpected()
		{
			return expected;
		}

		/** Whether enough drops are expected to show the observed / expected ratio. */
		boolean hasRatio()
		{
			return expected >= MIN_EXPECTED_FOR_RATIO;
		}

		/** Observed / expected, or {@code NaN} when {@link #hasRatio()} is false. */
		double getRatio()
		{
			return hasRatio() ? actual / expected : Double.NaN;
		}

		/** The Poisson chance of at least the observed count, see {@link LuckMeter#chanceOfAtLeast}. */
		double getChanceOfAtLeastObserved()
		{
			return chanceOfAtLeast(actual, expected);
		}
	}

	private static final class Snapshot
	{
		private int version;
		private String snapshotDate;
		private String license;
		private String licenseUrl;
		private String source;
		private String contributors;
		private String attribution;
		private String scope;
		private List<Table> tables;
	}

	private static final class Table
	{
		private String task;
		private String article;
		private String page;
		private long revision;
		private List<Drop> drops;
	}

	private static final class Drop
	{
		private String item;
		private int numerator;
		private int denominator;
	}
}

package com.shmayvan.slayerledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The collapsed "Luck meter" section of {@link SlayerLedgerPanel}: selected drops in completed tasks against
 * their expected count ({@link LuckMeter}, worked out by the history model). Nothing is compared or named while the
 * section is collapsed or its "Luck meter" setting hides it, and never by the panel's refresh timer. EDT only.
 *
 * <p>The Task choices show each task's icon ({@link TaskIcons}) before its name, asked for when the choices are
 * built (open and shown) and drawn by a wrapper around the look and feel's renderer ({@link TaskIconCache}). The box is
 * sized from a short name, so a long one is cut short in the closed box rather than widening the sidebar, and its open
 * list widens to fit ({@link ComboPopupWidener}).</p>
 */
final class LuckMeterSection
{
	private final LedgerHistoryModel model;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;

	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	private final JLabel title = new JLabel("Luck meter");
	private final JLabel toggle = new JLabel();
	private final JPanel body = new JPanel();
	private final JComboBox<String> task = new JComboBox<>();
	/** The Task choices' icons. */
	private final TaskIconCache taskIcons;
	private final JLabel summary = new JLabel();
	private final JPanel list = new JPanel();
	private boolean expanded;
	private boolean updatingTasks;
	/** The "Luck meter" setting; while off, nothing is built, open or not. The panel hides the components. */
	private boolean shown = true;
	/** How many times the rows were built. */
	private int builds;

	/** @param icons draws the Task choices' icons */
	LuckMeterSection(LedgerHistoryModel model, Runnable relayout, ItemIcons icons)
	{
		this.model = model;
		this.relayout = relayout;
		this.taskIcons = new TaskIconCache(icons, task);
	}

	/** Adds the header and the body to {@code content}, collapsed. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		header.setName("luck.header");
		title.setName("luck.title");
		toggle.setName("luck.toggle");
		body.setName("luck.body");
		task.setName("luck.task");
		summary.setName("luck.summary");
		list.setName("luck.list");
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		toggle.setFont(FontManager.getRunescapeSmallFont());
		toggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(title, BorderLayout.WEST);
		header.add(toggle, BorderLayout.EAST);
		header.setToolTipText("<html>Compare selected drops in completed tasks with their expected count."
			+ "<br>Every kill of the task counts toward expected at the standard monster's rate: variants,"
			+ "<br>superiors, task bosses (Abyssal Sire, Grotesque Guardians), Greater nechryael in the"
			+ "<br>Catacombs and any location are pooled, so the comparison is approximate."
			+ "<br>Only tasks with loot data count. Rare drops vary a lot over small samples."
			+ "<br>Drop rates: Old School RuneScape Wiki contributors, CC BY-NC-SA 3.0.</html>");
		MouseAdapter toggleListener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggle();
			}
		};
		header.addMouseListener(toggleListener);
		title.addMouseListener(toggleListener);
		toggle.addMouseListener(toggleListener);
		SlayerLedgerPanel.addRow(content, header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel taskRow = SlayerLedgerPanel.selectorRow("Task", task);
		task.setFocusable(false);
		taskIcons.install(task, choice -> choice);
		// Sized from a short name, not the longest choice, so neither a long name nor the icon widens the sidebar.
		task.setPrototypeDisplayValue("Abyssal demons");
		ComboPopupWidener.install(task, ComboPopupWidener.MAX_WIDTH);
		task.setToolTipText("Choose a supported task; totals pool its completed tasks with loot data.");
		task.addActionListener(e ->
		{
			if (!updatingTasks && expanded && shown)
			{
				buildRows();
			}
		});
		SlayerLedgerPanel.addRow(body, taskRow);

		summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		summary.setFont(FontManager.getRunescapeSmallFont());
		summary.setBorder(BorderFactory.createEmptyBorder(4, 8, 2, 4));
		summary.setAlignmentX(Component.LEFT_ALIGNMENT);
		SlayerLedgerPanel.addRow(body, summary);
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);
		SlayerLedgerPanel.addRow(body, list);
		body.setVisible(false);
		SlayerLedgerPanel.addRow(content, body);
		rebuild();
	}

	/** Opens or closes the section. */
	void toggle()
	{
		expanded = !expanded;
		rebuild();
	}

	/**
	 * Applies the "Luck meter" setting: hidden, the section drops its rows and compares nothing; shown again, it
	 * is rebuilt from the current records at once if it was open.
	 */
	void setShown(boolean value)
	{
		if (shown != value)
		{
			shown = value;
			rebuild();
		}
	}

	/** Rebuilds the section when it is open and shown, as item names arrive; does nothing otherwise. */
	void itemNamesChanged()
	{
		if (expanded && shown)
		{
			rebuild();
		}
	}

	/**
	 * Shows the section as it now is: when open and shown, refreshes the task choices and compares the current records;
	 * otherwise drops the rows.
	 */
	void rebuild()
	{
		toggle.setText(expanded ? "Hide" : "Show");
		body.setVisible(expanded);
		if (!expanded || !shown)
		{
			// Nothing is compared (or named) while collapsed or hidden; opening or showing the section compares the
			// current records.
			list.removeAll();
			relayout.run();
			return;
		}
		List<String> tasks = model.luckTasks();
		if (tasks == null)
		{
			tasks = Collections.emptyList();
		}
		String previous = (String) task.getSelectedItem();
		updatingTasks = true;
		try
		{
			DefaultComboBoxModel<String> choices = new DefaultComboBoxModel<>();
			for (String choice : tasks)
			{
				choices.addElement(choice);
				// Each task's icon once; open and shown only, never on the refresh timer.
				taskIcons.request(choice);
			}
			task.setModel(choices);
			if (previous != null && tasks.contains(previous))
			{
				task.setSelectedItem(previous);
			}
			task.setEnabled(!tasks.isEmpty());
		}
		finally
		{
			updatingTasks = false;
		}
		buildRows();
	}

	private void buildRows()
	{
		builds++;
		list.removeAll();
		summary.setToolTipText(null);
		LuckView view = model.luck((String) task.getSelectedItem());
		switch (view.getState())
		{
			case UNAVAILABLE:
				summary.setText("");
				addMessage("Luck meter data unavailable");
				break;
			case NO_SAMPLES:
				summary.setText("");
				addMessage("No completed tasks with loot data.");
				break;
			case NAMES_LOADING:
				summary.setText("");
				addMessage("Loading saved loot item names...");
				break;
			default:
				LuckMeter.Summary result = view.getSummary();
				summary.setText(SlayerLedgerPanel.sampleTasks(result.getTaskCount()) + " / " + result.getKills()
					+ " kills with loot data");
				for (int i = 0; i < result.getDrops().size(); i++)
				{
					list.add(row(result, result.getDrops().get(i), view.isNamesFailed()));
					if (i + 1 < result.getDrops().size())
					{
						list.add(Box.createVerticalStrut(2));
					}
				}
				if (view.isNamesFailed())
				{
					addMessage("Some item names unavailable.");
				}
				break;
		}
		relayout.run();
	}

	/**
	 * One drop in two short two-column lines that fit the sidebar, like a history row: the item name (truncates) and
	 * the ratio, or {@code too few kills} below 1 expected drop (owner decision), then observed / expected.
	 */
	private static JPanel row(LuckMeter.Summary summary, LuckMeter.DropEntry drop, boolean namesFailed)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(3, 8, 3, 4));

		JLabel name = SlayerLedgerPanel.historyLabel(drop.getItem(), Color.WHITE);
		String ratio = drop.hasRatio() ? String.format(Locale.ROOT, "%.1fx", drop.getRatio()) : "too few kills";
		row.add(SlayerLedgerPanel.historyLine(name, SlayerLedgerPanel.historyLabel(ratio, ColorScheme.LIGHT_GRAY_COLOR)));
		row.add(SlayerLedgerPanel.historyLine(
			SlayerLedgerPanel.historyLabel("Observed / expected:", ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(drop.getActual() + " / " + String.format(Locale.ROOT, "%.2f",
				drop.getExpected()), ColorScheme.LIGHT_GRAY_COLOR)));
		for (Component line : row.getComponents())
		{
			((JComponent) line).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		row.setToolTipText(tooltip(summary, drop, namesFailed));
		return row;
	}

	/** The drop row's tooltip (HTML-escaped): exact numbers, the Poisson chance and the caveats. */
	static String tooltip(LuckMeter.Summary summary, LuckMeter.DropEntry drop, boolean namesFailed)
	{
		StringBuilder text = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(drop.getItem()))
			.append("<br>Observed: ").append(drop.getActual())
			.append("<br>Expected: ").append(String.format(Locale.ROOT, "%.4f", drop.getExpected()))
			.append(" (").append(summary.getKills()).append(" kills x ")
			.append(drop.getNumerator()).append('/').append(drop.getDenominator()).append(')');
		if (drop.hasRatio())
		{
			text.append("<br>Observed / expected: ").append(String.format(Locale.ROOT, "%.2fx", drop.getRatio()));
		}
		else
		{
			text.append("<br>Too few kills for a ratio (under 1 expected drop).");
		}
		text.append("<br>Chance of at least ").append(drop.getActual()).append(": ")
			.append(formatChance(drop.getChanceOfAtLeastObserved())).append(" (Poisson model)")
			.append("<br>Rare drops vary a lot; small samples say little about luck.")
			.append("<br>n = ").append(summary.getTaskCount()).append(" tasks with loot data.")
			.append("<br>All task kills count at the standard monster's rate, so this is approximate.");
		if (namesFailed)
		{
			text.append("<br>Some item names were unavailable; observed counts may be incomplete.");
		}
		return text.append("</html>").toString();
	}

	/** A probability as a percentage, never rounding an uncertain value to 0% or 100%. */
	static String formatChance(double chance)
	{
		if (chance >= 1)
		{
			return "100%";
		}
		if (chance <= 0)
		{
			return "0%";
		}
		if (chance < 0.001)
		{
			return "<0.1%";
		}
		if (chance > 0.999)
		{
			return ">99.9%";
		}
		return String.format(Locale.ROOT, "%.1f%%", chance * 100);
	}

	private void addMessage(String text)
	{
		JLabel message = new JLabel(text);
		message.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		message.setFont(FontManager.getRunescapeSmallFont());
		message.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 4));
		message.setAlignmentX(Component.LEFT_ALIGNMENT);
		list.add(message);
	}

	/** How many times the rows were built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}
}

package com.shmayvan.slayerledger;

/** The luck meter for one task: what to show, and the comparison once it can be shown. */
final class LuckView
{
	enum State
	{
		/** The bundled data could not be read. */
		UNAVAILABLE,
		/** No completed task of it has loot data. */
		NO_SAMPLES,
		/** The loot's item names are on their way. */
		NAMES_LOADING,
		/** The comparison ({@link #getSummary}). */
		SUMMARY
	}

	static final LuckView UNAVAILABLE = new LuckView(State.UNAVAILABLE, null, false);

	private final State state;
	private final LuckMeter.Summary summary;
	private final boolean namesFailed;

	LuckView(State state, LuckMeter.Summary summary, boolean namesFailed)
	{
		this.state = state;
		this.summary = summary;
		this.namesFailed = namesFailed;
	}

	State getState()
	{
		return state;
	}

	/** The comparison while {@link State#SUMMARY}, else {@code null}. */
	LuckMeter.Summary getSummary()
	{
		return summary;
	}

	/** Whether some of the loot's item names could not be looked up. */
	boolean isNamesFailed()
	{
		return namesFailed;
	}
}

package com.shmayvan.slayerledger;

import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.Icon;
import lombok.extern.slf4j.Slf4j;

/**
 * The Slayer masters' face icons of Overall totals' By master headers: each master's chathead image from the
 * Old School RuneScape Wiki, bundled as a class resource under {@link #DIRECTORY} (Jagex's art, credited in the README).
 *
 * <p>Every image is optional: a missing or unreadable file gives {@link SmallItemIcon#EMPTY}, the same 18 by 16 slot,
 * and nothing throws, so deleting the {@code masters/} folder removes the faces with no code change.
 * Images are read with {@code getResourceAsStream}, as the bundled JSON is (no
 * {@code java.io} file APIs), the first time a master's icon is asked for, then kept (a missing one is remembered too).
 * A name two masters share ({@link SlayerMaster#displayName}, for example {@code Duradel/Kuradal}) shows the first
 * master's face; an unknown master shows the empty slot. EDT only.</p>
 *
 * <p>Images are scaled at load to twice the slot (keeping their aspect ratio, in halving steps so the downscale stays
 * smooth) and drawn into the slot at paint time with bicubic interpolation, centred, keeping the aspect ratio
 * ({@link MasterIcon}).</p>
 */
@Slf4j
final class MasterIcons
{
	/** Where the images are, relative to this class's package. */
	static final String DIRECTORY = "masters/";

	/**
	 * The image file of each master name {@link SlayerMaster#displayName} gives. A shared name uses the first master's
	 * face: Turael for Turael/Aya, Duradel for Duradel/Kuradal, Nieve for Nieve/Steve.
	 */
	private static final Map<String, String> FILES;

	static
	{
		Map<String, String> files = new HashMap<>();
		files.put("Turael/Aya", "turael_chathead.png");
		files.put("Mazchna", "mazchna_chathead.png");
		files.put("Vannaka", "vannaka_chathead.png");
		files.put("Chaeldar", "chaeldar_chathead.png");
		files.put("Duradel/Kuradal", "duradel_chathead.png");
		files.put("Nieve/Steve", "nieve_chathead.png");
		files.put("Krystilia", "krystilia_chathead.png");
		files.put("Konar", "konar_quo_maten_chathead.png");
		files.put("Spria", "spria_chathead.png");
		files.put("Mortimer", "mortimer_chathead.png");
		FILES = Collections.unmodifiableMap(files);
	}

	/** Where this loader reads the images from. */
	private final String directory;
	/** The icon of each file asked for; a file that could not be read maps to {@link SmallItemIcon#EMPTY}. */
	private final Map<String, Icon> icons = new HashMap<>();

	MasterIcons()
	{
		this(DIRECTORY);
	}

	/** Test seam: reads the images from {@code directory} (relative to this class's package) instead. */
	MasterIcons(String directory)
	{
		this.directory = directory;
	}

	/** The image file of the master named {@code master} ({@link SlayerMaster#displayName}), or {@code null}. */
	static String fileName(String master)
	{
		return master == null ? null : FILES.get(master);
	}

	/**
	 * The face of the master named {@code master} ({@link SlayerMaster#displayName}) at the small slot size, or
	 * {@link SmallItemIcon#EMPTY} for an unknown master or a missing or unreadable image. Read once, then kept.
	 */
	Icon icon(String master)
	{
		String file = fileName(master);
		if (file == null)
		{
			return SmallItemIcon.EMPTY;
		}
		return icons.computeIfAbsent(file, this::load);
	}

	private Icon load(String file)
	{
		String resource = directory + file;
		try (InputStream stream = MasterIcons.class.getResourceAsStream(resource))
		{
			if (stream == null)
			{
				log.debug("Slayer master image {} is missing", resource);
				return SmallItemIcon.EMPTY;
			}
			BufferedImage image;
			// As RuneLite's ImageUtil: ImageIO is not safe to use from several threads at once.
			synchronized (ImageIO.class)
			{
				image = ImageIO.read(stream);
			}
			if (image == null || image.getWidth() <= 0 || image.getHeight() <= 0)
			{
				log.debug("Slayer master image {} is unreadable", resource);
				return SmallItemIcon.EMPTY;
			}
			return new MasterIcon(file, scaled(image, 2 * ItemListView.ICON_WIDTH, 2 * ItemListView.ICON_HEIGHT));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Unable to load the Slayer master image {}", resource, e);
			return SmallItemIcon.EMPTY;
		}
	}

	/**
	 * {@code image} fitted into {@code maxWidth} by {@code maxHeight}, keeping its aspect ratio, halving the size in
	 * bilinear steps first so the result stays smooth; an image already that small is kept.
	 */
	static BufferedImage scaled(BufferedImage image, int maxWidth, int maxHeight)
	{
		double scale = Math.min(1, Math.min(maxWidth / (double) image.getWidth(), maxHeight / (double) image.getHeight()));
		int targetWidth = Math.max(1, (int) Math.round(image.getWidth() * scale));
		int targetHeight = Math.max(1, (int) Math.round(image.getHeight() * scale));
		BufferedImage current = image;
		while (current.getWidth() != targetWidth || current.getHeight() != targetHeight)
		{
			int width = Math.max(targetWidth, current.getWidth() / 2);
			int height = Math.max(targetHeight, current.getHeight() / 2);
			BufferedImage next = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = next.createGraphics();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
				g.drawImage(current, 0, 0, width, height, null);
			}
			finally
			{
				g.dispose();
			}
			current = next;
		}
		return current;
	}

	/**
	 * A master's face in the small slot ({@link ItemListView#ICON_WIDTH} by {@link ItemListView#ICON_HEIGHT}), scaled
	 * as it is painted with bicubic interpolation, keeping its aspect ratio, centred.
	 */
	static final class MasterIcon implements Icon
	{
		/** The image's file name, for tests. */
		private final String file;
		private final BufferedImage image;

		private MasterIcon(String file, BufferedImage image)
		{
			this.file = file;
			this.image = image;
		}

		/** The image's file name (under {@link #DIRECTORY}). */
		String getFile()
		{
			return file;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			double scale = Math.min(getIconWidth() / (double) image.getWidth(),
				getIconHeight() / (double) image.getHeight());
			int width = Math.max(1, (int) Math.round(image.getWidth() * scale));
			int height = Math.max(1, (int) Math.round(image.getHeight() * scale));
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
				g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
				g2.drawImage(image, x + (getIconWidth() - width) / 2, y + (getIconHeight() - height) / 2, width,
					height, null);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override
		public int getIconWidth()
		{
			return ItemListView.ICON_WIDTH;
		}

		@Override
		public int getIconHeight()
		{
			return ItemListView.ICON_HEIGHT;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;

/**
 * The names the shown history needs from the plugin (split from {@link LedgerHistoryModel}): the player's region
 * names and item names, which are asked for and which could not be found, and the nature rune's GE price for the alch
 * hint (it comes with the item names).
 *
 * <p>Threading: EDT only, like the model that owns it. It only keeps the names and asks for missing ones, each once;
 * the model decides what an arrival means (dropping the statistics, re-checking the chat preview) and tells its
 * listener. Callers write through the model.</p>
 */
final class NameBook
{
	/** Asks the plugin for the names of regions (EDT). */
	private final Consumer<Set<Integer>> locationNameRequests;
	/** Asks the plugin for the names of item ids, and the nature rune's price (EDT). */
	private final Consumer<Set<Integer>> itemNameRequests;
	/** Set by {@link #close}: nothing is asked for any more. */
	private boolean closed;

	// Region names
	/**
	 * The player's region names received from the plugin (the active RuneScape profile's), by region id; kept until the
	 * plugin says the profile changed ({@link #clearLocationNames}).
	 */
	private final Map<Integer, String> locationNames = new HashMap<>();
	/** Regions whose names were asked for and have not arrived yet, so they are not asked for twice. */
	private final Set<Integer> locationNamesPending = new HashSet<>();
	/** Regions without a name when last asked; asked again only after the profile changes or one is named. */
	private final Set<Integer> locationNamesMissing = new HashSet<>();

	// Item names
	/** Item names from the plugin, by item id as tallied. */
	private final Map<Integer, String> itemNames = new HashMap<>();
	/** Read-only view of {@link #itemNames}. */
	private final Map<Integer, String> itemNamesView = Collections.unmodifiableMap(itemNames);
	/** Ids asked for whose answer has not arrived yet, so they are not asked for twice. */
	private final Set<Integer> itemNamesPending = new HashSet<>();
	/** Ids the plugin could not name; never asked for again. */
	private final Set<Integer> itemNamesFailed = new HashSet<>();
	/** The nature rune's GE price for the alch hint, or {@code null} while unknown. */
	private Long natureRunePrice;
	/** Whether the nature rune's price was asked for (with the first batch of names). */
	private boolean natureRunePriceAsked;
	/** Bumped whenever item names arrive, so views that show them are worked out again. */
	private long itemNamesVersion;

	/**
	 * @param locationNameRequests asks the plugin for the names of regions (EDT)
	 * @param itemNameRequests     asks the plugin for the names of item ids, and the nature rune's price (EDT)
	 */
	NameBook(Consumer<Set<Integer>> locationNameRequests, Consumer<Set<Integer>> itemNameRequests)
	{
		this.locationNameRequests = locationNameRequests;
		this.itemNameRequests = itemNameRequests;
	}

	/** The plugin stopped: nothing is asked for again. */
	void close()
	{
		closed = true;
	}

	// ---- Region names ----

	/** The player's name for {@code region}, or {@code null} when it has none or it is not known yet. */
	String locationName(Integer region)
	{
		return locationNames.get(region);
	}

	/** Whether the name of {@code region} is known. */
	boolean hasLocationName(Integer region)
	{
		return locationNames.containsKey(region);
	}

	/** Asks the plugin (once, in one batch) for the names of {@code regions} not known, asked for or missing yet. */
	void requestLocationNames(Set<Integer> regions)
	{
		if (closed)
		{
			return;
		}
		Set<Integer> missing = new HashSet<>();
		for (Integer region : regions)
		{
			if (region != null && LocationTally.isRegion(region) && !locationNames.containsKey(region)
				&& !locationNamesPending.contains(region) && !locationNamesMissing.contains(region))
			{
				missing.add(region);
			}
		}
		if (!missing.isEmpty())
		{
			locationNamesPending.addAll(missing);
			locationNameRequests.accept(missing);
		}
	}

	/**
	 * Adds region names from the plugin ({@code names}, for the regions in {@code requested} that have one; also sent
	 * when the player names one). Requested regions without a name are not asked for again. Returns whether a name
	 * changed.
	 */
	boolean addLocationNames(Set<Integer> requested, Map<Integer, String> names)
	{
		locationNamesPending.removeAll(requested);
		boolean changed = false;
		for (Integer region : requested)
		{
			String name = names.get(region);
			if (name == null)
			{
				locationNamesMissing.add(region);
			}
			else
			{
				locationNamesMissing.remove(region);
				changed |= !name.equals(locationNames.put(region, name));
			}
		}
		return changed;
	}

	/** Forgets every region name (another RuneScape profile is active): they are asked for again as needed. */
	void clearLocationNames()
	{
		locationNames.clear();
		locationNamesPending.clear();
		locationNamesMissing.clear();
	}

	/** Whether some region names asked for have not arrived yet. */
	boolean isLocationNamePending()
	{
		return !locationNamesPending.isEmpty();
	}

	/** Whether the name of {@code region} was asked for and has not arrived yet. */
	boolean isLocationNamePending(Integer region)
	{
		return locationNamesPending.contains(region);
	}

	// ---- Item names ----

	/** The name of item {@code id} (as tallied), or {@code null} when it is not known (yet). */
	String itemName(Integer id)
	{
		return itemNames.get(id);
	}

	/**
	 * The item's own name, as Ground Items matches it: {@link #itemName} without the
	 * {@link ClientLookups#NOTED_SUFFIX} a note is shown with (a note's own name is its unnoted item's); {@code null}
	 * when not known (yet).
	 */
	String itemBaseName(Integer id)
	{
		String name = itemNames.get(id);
		return name != null && name.endsWith(ClientLookups.NOTED_SUFFIX)
			? name.substring(0, name.length() - ClientLookups.NOTED_SUFFIX.length()) : name;
	}

	/** Every known item name, by item id; a read-only view. */
	Map<Integer, String> itemNames()
	{
		return itemNamesView;
	}

	/** The nature rune's GE price for the alch hint, or {@code null} while unknown. */
	Long natureRunePrice()
	{
		return natureRunePrice;
	}

	/** Whether the name of {@code id} was asked for and has not arrived yet. */
	boolean isItemNamePending(Integer id)
	{
		return itemNamesPending.contains(id);
	}

	/** Whether the plugin could not name {@code id}. */
	boolean isItemNameFailed(Integer id)
	{
		return itemNamesFailed.contains(id);
	}

	/**
	 * Asks the plugin (once, in one batch) for the names of {@code ids} not known, asked for or failed yet; it looks
	 * them up on the client thread and answers through {@link LedgerHistoryModel#addItemNames}. The nature rune price for the alch hint
	 * comes with the first batch, and is asked for again with later batches while it is unknown.
	 */
	void requestItemNames(Set<Integer> ids)
	{
		if (closed)
		{
			return;
		}
		Set<Integer> missing = new HashSet<>(ids);
		missing.removeAll(itemNames.keySet());
		missing.removeAll(itemNamesPending);
		missing.removeAll(itemNamesFailed);
		if (!missing.isEmpty() || !natureRunePriceAsked)
		{
			natureRunePriceAsked = true;
			itemNamesPending.addAll(missing);
			itemNameRequests.accept(missing);
		}
	}

	/**
	 * Adds item names looked up by the plugin ({@code names}, for the ids in {@code requested} that have one) and the
	 * nature rune's GE price ({@code null} when unavailable); ids without a name are not asked for again. Bumps
	 * {@link #itemNamesVersion}.
	 */
	void addItemNames(Set<Integer> requested, Map<Integer, String> names, Long natureRune)
	{
		if (natureRune != null)
		{
			natureRunePrice = natureRune;
		}
		itemNamesPending.removeAll(requested);
		itemNames.putAll(names);
		for (Integer id : requested)
		{
			if (!names.containsKey(id))
			{
				itemNamesFailed.add(id);
			}
		}
		itemNamesVersion++;
	}

	/** Bumped whenever item names arrive; never goes back. */
	long itemNamesVersion()
	{
		return itemNamesVersion;
	}
}

package com.shmayvan.slayerledger;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/**
 * One notable drop of a task: a loot item stack worth at least the "Notable drop value" setting, or a pet. Its values
 * are kept as they were when it dropped, so the history doesn't depend on later prices. Serialized with Gson in
 * {@link LedgerRecord} and {@link SessionSnapshot}; effectively immutable (no setters). Pure (no RuneLite types). The
 * rules are in {@link NotableDrops}.
 */
@Getter
@EqualsAndHashCode
@ToString
final class NotableDrop
{
	/** What a pet message said. */
	enum Pet
	{
		/** A pet dropped (it follows you, or went to your inventory). */
		RECEIVED,
		/** A pet dropped that you already have, so you didn't receive it. */
		DUPLICATE
	}

	/** Item id as received (possibly noted), or {@code null} for a pet. */
	private Integer itemId;
	/** The item's name when it dropped, or {@code null} for a pet (or when the lookup failed). */
	private String name;
	/** Quantity of the stack; 1 for a pet. */
	private long quantity;
	/**
	 * Value of the stack at the GE price (an untradeable item at its high-alchemy value, as {@link LootPricing} does),
	 * or {@code null} when unknown (and for a pet).
	 */
	private Long geValue;
	/** Value of the stack at its high-alchemy value, or {@code null} when unknown (and for a pet). */
	private Long haValue;
	/** When it dropped (epoch milliseconds). */
	private long time;
	/** For a pet, what its message said; {@code null} for an item. */
	private Pet pet;

	/** For Gson. */
	private NotableDrop()
	{
	}

	private NotableDrop(Integer itemId, String name, long quantity, Long geValue, Long haValue, long time, Pet pet)
	{
		this.itemId = itemId;
		this.name = name;
		this.quantity = quantity;
		this.geValue = geValue;
		this.haValue = haValue;
		this.time = time;
		this.pet = pet;
	}

	/** An item stack worth {@code geValue} / {@code haValue} in all (each {@code null} when unknown). */
	static NotableDrop item(int itemId, String name, long quantity, Long geValue, Long haValue, long time)
	{
		return new NotableDrop(itemId, name, quantity, geValue, haValue, time, null);
	}

	/** A pet message seen at {@code time}. */
	static NotableDrop pet(Pet pet, long time)
	{
		return new NotableDrop(null, null, 1, null, null, time, pet == null ? Pet.RECEIVED : pet);
	}

	/** Whether this is a pet rather than an item stack. */
	boolean isPet()
	{
		return pet != null;
	}

	/** The stack's value in {@code mode} ({@code null} counts as GE), or {@code null} when unknown or a pet. */
	Long value(LootPriceMode mode)
	{
		return mode == LootPriceMode.HIGH_ALCH ? haValue : geValue;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;

/**
 * Rules for a task's notable drops ({@link NotableDrop}). Pure (no RuneLite types).
 *
 * <ul>
 *     <li>A loot item stack is notable when its value, in the "Loot price" setting's mode, is at least the "Notable
 *     drop value" setting ({@link #DEFAULT_THRESHOLD} by default). The value is the unit price times the quantity,
 *     with the same unit prices as the live loot value ({@link LootPricing}): in GE mode an untradeable item counts at
 *     its high-alchemy value. An item whose price in that mode is unavailable is never notable. One stack is one item
 *     id in one kill's loot (stacks of the same id in one kill are added up), after the bonecrusher and "Ignored loot"
 *     filters.</li>
 *     <li>A pet message ({@link PetMessage}) is always notable.</li>
 *     <li>A task keeps at most {@link #MAX_PER_TASK} notable drops, so the ledger file can't grow without limit. When
 *     another arrives, the lowest-ranked one is left out: items rank by value (the higher of the GE and high-alchemy
 *     values; unknown counts as 0), pets above every item, and among equals the oldest goes first.</li>
 * </ul>
 */
final class NotableDrops
{
	/** Default "Notable drop value" setting, in gp (owner decision, 2026-10-26). */
	static final int DEFAULT_THRESHOLD = 100_000;
	/** Most notable drops kept per task. */
	static final int MAX_PER_TASK = 20;

	/** Newest first by time; equal times keep the later-added one first when the list is reversed beforehand. */
	private static final Comparator<NotableDrop> NEWEST_FIRST =
		Comparator.comparingLong(NotableDrop::getTime).reversed();

	private NotableDrops()
	{
	}

	/** The threshold to use for a setting value: at least 1 gp. */
	static long threshold(long setting)
	{
		return Math.max(1, setting);
	}

	/**
	 * The notable stacks of one kill's loot.
	 *
	 * @param drop      the kill's loot (after filtering), by item id as received
	 * @param prices    unit prices of the loot's items ({@link ItemValuation#capturePrices})
	 * @param mode      the "Loot price" setting ({@code null} is GE)
	 * @param threshold the "Notable drop value" setting, in gp (see {@link #threshold(long)})
	 * @param names     the item name for an id, or {@code null}; only asked for notable items
	 * @param time      when the loot arrived (epoch milliseconds)
	 * @return the notable stacks, in item id order (empty when none)
	 */
	static List<NotableDrop> find(ItemTally drop, ItemValuation.UnitPrices prices, LootPriceMode mode,
		long threshold, IntFunction<String> names, long time)
	{
		if (drop == null || drop.isEmpty() || prices == null)
		{
			return Collections.emptyList();
		}
		final long minimum = threshold(threshold);
		final Map<Integer, Long> ge = LootPricing.geUnitPrices(prices.getGe(), prices.getHa());
		final Map<Integer, Long> ha = prices.getHa();
		List<NotableDrop> result = new ArrayList<>();
		for (int id : drop.itemIds())
		{
			final long quantity = drop.get(id);
			final Long geValue = stackValue(ge.get(id), quantity);
			final Long haValue = stackValue(ha.get(id), quantity);
			final Long value = mode == LootPriceMode.HIGH_ALCH ? haValue : geValue;
			if (value != null && value >= minimum)
			{
				result.add(NotableDrop.item(id, names == null ? null : names.apply(id), quantity, geValue, haValue,
					time));
			}
		}
		return result;
	}

	/** {@code unit * quantity}, saturating; {@code null} when the unit price is unknown or the quantity isn't positive. */
	static Long stackValue(Long unit, long quantity)
	{
		if (unit == null || quantity <= 0)
		{
			return null;
		}
		if (unit <= 0)
		{
			return 0L;
		}
		return unit > Long.MAX_VALUE / quantity ? Long.MAX_VALUE : unit * quantity;
	}

	/**
	 * {@code current} with {@code added} appended, keeping at most {@link #MAX_PER_TASK} (see the class rules).
	 * {@code null} entries are dropped. Neither list is changed; the result is in the order the drops were added.
	 */
	static List<NotableDrop> add(Collection<NotableDrop> current, Collection<NotableDrop> added)
	{
		List<NotableDrop> result = new ArrayList<>();
		addNonNull(result, current);
		addNonNull(result, added);
		while (result.size() > MAX_PER_TASK)
		{
			int lowest = 0;
			for (int i = 1; i < result.size(); i++)
			{
				// Strictly lower, so among equals the oldest (first) is removed.
				if (rank(result.get(i)) < rank(result.get(lowest)))
				{
					lowest = i;
				}
			}
			result.remove(lowest);
		}
		return result;
	}

	/** A stored list cleaned up for use: no {@code null} entries, at most {@link #MAX_PER_TASK}. */
	static List<NotableDrop> sanitize(Collection<NotableDrop> stored)
	{
		return add(stored, null);
	}

	/** {@code drops} newest first (by time; among equal times the later-added first). */
	static List<NotableDrop> newestFirst(Collection<NotableDrop> drops)
	{
		List<NotableDrop> result = sanitize(drops);
		Collections.reverse(result);
		result.sort(NEWEST_FIRST);
		return result;
	}

	/** Rank for {@link #add}: pets above every item, items by their higher known value. */
	static long rank(NotableDrop drop)
	{
		if (drop.isPet())
		{
			return Long.MAX_VALUE;
		}
		long ge = drop.getGeValue() == null ? 0 : drop.getGeValue();
		long ha = drop.getHaValue() == null ? 0 : drop.getHaValue();
		// Below every pet, even for an item at Long.MAX_VALUE.
		return Math.min(Long.MAX_VALUE - 1, Math.max(ge, ha));
	}

	private static void addNonNull(List<NotableDrop> into, Collection<NotableDrop> from)
	{
		if (from == null)
		{
			return;
		}
		for (NotableDrop d : from)
		{
			if (d != null)
			{
				into.add(d);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.List;

/**
 * Rules for a session's kills per NPC name: each death of an NPC the player damaged while the session ran is
 * added to its name, in the order names are first seen. Names are matched by {@link TaskStatistics#normalize}; the
 * first spelling seen is kept. Pure (no RuneLite types); the lists passed in are never changed.
 */
final class NpcKillTally
{
	/**
	 * Most names tallied per session; kills of further names are not tallied (the task count is unaffected), except a
	 * Catacombs variant's name ({@link CatacombsVariants#isVariantNpcName}), which is always tallied, so a session
	 * that met many other NPCs first still decides its variant. At most {@code MAX_NAMES} plus the variants' names.
	 */
	static final int MAX_NAMES = 32;

	private NpcKillTally()
	{
	}

	/**
	 * A copy of {@code tally} with one more kill of {@code name} (saturating). Nothing is added for a blank name, or a
	 * new name other than a Catacombs variant's once {@link #MAX_NAMES} are tallied.
	 *
	 * @param tally the tally so far, or {@code null} for none
	 */
	static List<NpcKills> add(List<NpcKills> tally, String name)
	{
		final List<NpcKills> result = sanitize(tally);
		merge(result, name, 1);
		return result;
	}

	/**
	 * A clean copy of a tally (for example one read from a file): entries without a name or kills are dropped, a
	 * repeated name is merged into its first entry, and at most {@link #MAX_NAMES} names are kept, plus any Catacombs
	 * variant's names. Never {@code null}.
	 */
	static List<NpcKills> sanitize(List<NpcKills> tally)
	{
		final List<NpcKills> result = new ArrayList<>();
		if (tally == null)
		{
			return result;
		}
		for (NpcKills entry : tally)
		{
			if (entry != null)
			{
				merge(result, entry.getName(), entry.getKills());
			}
		}
		return result;
	}

	/** The kills tallied for {@code name} (matched by {@link TaskStatistics#normalize}); 0 for none. */
	static int killsOf(List<NpcKills> tally, String name)
	{
		final String key = TaskStatistics.normalize(name);
		if (tally == null || key == null)
		{
			return 0;
		}
		int kills = 0;
		for (NpcKills entry : tally)
		{
			if (entry != null && entry.getKills() > 0 && key.equals(TaskStatistics.normalize(entry.getName())))
			{
				kills = saturatedAdd(kills, entry.getKills());
			}
		}
		return kills;
	}

	/** Every kill in the tally; 0 for none. */
	static int total(List<NpcKills> tally)
	{
		if (tally == null)
		{
			return 0;
		}
		int kills = 0;
		for (NpcKills entry : tally)
		{
			if (entry != null && TaskStatistics.normalize(entry.getName()) != null && entry.getKills() > 0)
			{
				kills = saturatedAdd(kills, entry.getKills());
			}
		}
		return kills;
	}

	private static void merge(List<NpcKills> result, String name, int kills)
	{
		final String key = TaskStatistics.normalize(name);
		if (key == null || kills <= 0)
		{
			return;
		}
		for (int i = 0; i < result.size(); i++)
		{
			final NpcKills entry = result.get(i);
			if (key.equals(TaskStatistics.normalize(entry.getName())))
			{
				result.set(i, new NpcKills(entry.getName(), saturatedAdd(entry.getKills(), kills)));
				return;
			}
		}
		if (result.size() < MAX_NAMES || CatacombsVariants.isVariantNpcName(name))
		{
			result.add(new NpcKills(name.trim(), kills));
		}
	}

	private static int saturatedAdd(int a, int b)
	{
		final long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}
}

package com.shmayvan.slayerledger;

import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/**
 * The player's kills of one NPC name in a session. Serialized with Gson in {@link SessionSnapshot}; effectively
 * immutable (no setters). Pure (no RuneLite types). The rules are in {@link NpcKillTally}.
 */
@Getter
@EqualsAndHashCode
@ToString
final class NpcKills
{
	/** The NPC's name as the game gives it, trimmed (for example "Deviant spectre"). */
	private String name;
	/** Deaths of NPCs with this name that the player had damaged; at least 1. */
	private int kills;

	/** For Gson. */
	private NpcKills()
	{
	}

	NpcKills(String name, int kills)
	{
		this.name = name;
		this.kills = kills;
	}
}

package com.shmayvan.slayerledger;

import java.time.Instant;
import java.time.YearMonth;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Value;

/**
 * Overall and grouped totals from completed played-task records. XP is the total of every skill in a record's
 * {@code xpGained} ({@link SkillXp#total}; owner decision), not only Slayer XP. Each group also sums its tasks'
 * supplies and loot item by item ({@link ItemSums}), from the rows their history details show
 * ({@link ItemDetails}) at the same prices as the profit; a task saved without item data adds none.
 *
 * <p>Each group also has the figures the By monster and By master groupings show: kills, averages per
 * task, profit per kill and per hour, Slayer XP and Slayer points. The rates follow the Trends rules
 * ({@link TaskRanking}): pooled over the group's task samples ({@link TaskRanking#isTaskSample}) that recorded the
 * figure, an hourly rate only from {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of their active time, and Slayer XP only
 * (the {@link SkillXp#SLAYER} entry). A task that didn't record a figure is left out of it rather than counted as 0.
 * By master groups also count the master's assignments per monster ({@link Assignment}): its completed played tasks
 * plus the assignment log's entries ({@link AssignmentEntry}: skipped, blocked, reset, untracked and other ended
 * assignments).</p>
 */
final class OverallTotals
{
	enum Grouping
	{
		ALL("Overall"),
		MASTER("By master"),
		MONTH("By month"),
		/** One group per monster as the history names it ({@link LedgerRecord#groupName}). */
		MONSTER("By monster");

		private final String label;

		Grouping(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	static final String UNKNOWN_MASTER = "Unknown master";
	static final String UNKNOWN_DATE = "Unknown date";

	/** Sort rank of a group: named groups first, then masters with an unnamed id, then no master or date. */
	private static final int NAMED = 0;
	private static final int UNNAMED_ID = 1;
	private static final int UNKNOWN = 2;

	/** Most assigned first, then by name ignoring case, then by name. */
	private static final Comparator<Assignment> ASSIGNMENT_ORDER = Comparator
		.comparingInt(Assignment::getCount).reversed()
		.thenComparing(Assignment::getName, String.CASE_INSENSITIVE_ORDER)
		.thenComparing(Assignment::getName);

	private OverallTotals()
	{
	}

	/**
	 * Aggregates completed records, leaving profit and XP unknown unless the record captured them. Monthly groups use
	 * each task's local completion month; records without an end time are kept in an unknown-date group. Items are
	 * summed in the order of {@code records} (the history's: newest first), which picks the unit prices a summed row's
	 * tooltip shows ({@link ItemSums}).
	 *
	 * @param currentGe today's GE unit prices the records are valued at ({@link HistoryPricing}); never {@code null}
	 */
	static List<Entry> summarize(Collection<LedgerRecord> records, Grouping grouping, LootPriceMode mode,
		Map<Integer, Long> currentGe, ZoneId zone)
	{
		return summarize(records, Collections.emptyList(), grouping, mode, currentGe, HiddenLoot.NONE, zone);
	}

	/**
	 * As {@link #summarize(Collection, Grouping, LootPriceMode, Map, ZoneId)}, with the loot items {@code hidden} hides
	 * left out of the profit ({@link HistoryPricing}). The summed loot items still list them; the panel leaves them out
	 * of its grid.
	 */
	static List<Entry> summarize(Collection<LedgerRecord> records, Grouping grouping, LootPriceMode mode,
		Map<Integer, Long> currentGe, HiddenLoot hidden, ZoneId zone)
	{
		return summarize(records, Collections.emptyList(), grouping, mode, currentGe, hidden, zone);
	}

	/**
	 * As {@link #summarize(Collection, Grouping, LootPriceMode, Map, HiddenLoot, ZoneId)}; By master groups also count
	 * their assignments per monster ({@link Entry#getAssignments}) from the completed records and {@code assignments},
	 * the assignment log's entries. Only masters with a group (a completed played task) are counted.
	 */
	static List<Entry> summarize(Collection<LedgerRecord> records, Collection<AssignmentEntry> assignments,
		Grouping grouping, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden, ZoneId zone)
	{
		Objects.requireNonNull(currentGe, "currentGe");
		if (records == null || records.isEmpty() || grouping == null)
		{
			return Collections.emptyList();
		}
		ZoneId localZone = zone == null ? ZoneId.systemDefault() : zone;
		Map<String, Aggregate> groups = new HashMap<>();
		for (LedgerRecord record : records)
		{
			if (!isCompletedTask(record))
			{
				continue;
			}
			String key = groupKey(record, grouping, localZone);
			int rank = groupRank(record, grouping);
			// By monster: keyed by the normalized name, labelled as the first (newest) record names it, and its icon is
			// that record's assigned task's, so a Catacombs variant or cannon task shows its task's icon.
			String label = grouping == Grouping.MONSTER ? monsterLabel(record) : key;
			String task = grouping == Grouping.MONSTER ? record.getMonster() : null;
			Aggregate aggregate = groups.computeIfAbsent(key, k -> new Aggregate(label, rank, task));
			aggregate.add(record, mode, currentGe, hidden);
		}
		if (grouping == Grouping.MASTER)
		{
			countAssignments(records, assignments, groups);
		}

		List<Entry> entries = new ArrayList<>();
		for (Map.Entry<String, Aggregate> group : groups.entrySet())
		{
			entries.add(group.getValue().toEntry());
		}
		entries.sort(comparator(grouping));
		return Collections.unmodifiableList(entries);
	}

	private static boolean isCompletedTask(LedgerRecord record)
	{
		return record != null && record.isCompleted() && !record.isPartial() && record.getKills() > 0;
	}

	private static String groupKey(LedgerRecord record, Grouping grouping, ZoneId zone)
	{
		switch (grouping)
		{
			case MASTER:
				return masterKey(record.getSlayerMaster());
			case MONTH:
				return record.getEndedAt() <= 0 ? UNKNOWN_DATE
					: YearMonth.from(Instant.ofEpochMilli(record.getEndedAt()).atZone(zone)).toString();
			case MONSTER:
				return TaskStatistics.normalize(monsterLabel(record));
			default:
				return "Overall";
		}
	}

	/**
	 * The By monster name of a record: the name the history shows and groups it under
	 * ({@link LedgerRecord#groupName}, with its Catacombs variant and cannon use), trimmed;
	 * {@link LedgerHistory#UNKNOWN_MONSTER} when blank.
	 */
	private static String monsterLabel(LedgerRecord record)
	{
		String name = LedgerHistory.monster(record).trim();
		return name.isEmpty() ? LedgerHistory.UNKNOWN_MONSTER : name;
	}

	/** The By master group of a SLAYER_MASTER value: its name, "Unknown master (N)" or {@link #UNKNOWN_MASTER}. */
	private static String masterKey(Integer master)
	{
		String masterName = SlayerMaster.displayName(master);
		return masterName == null ? UNKNOWN_MASTER : masterName;
	}

	private static int groupRank(LedgerRecord record, Grouping grouping)
	{
		switch (grouping)
		{
			case MASTER:
				if (SlayerMaster.hasName(record.getSlayerMaster()))
				{
					return NAMED;
				}
				return SlayerMaster.displayName(record.getSlayerMaster()) == null ? UNKNOWN : UNNAMED_ID;
			case MONTH:
				return record.getEndedAt() <= 0 ? UNKNOWN : NAMED;
			default:
				return NAMED;
		}
	}

	/**
	 * Months newest first and masters by name ignoring case; in both, unknown groups come last ("Unknown master (N)"
	 * groups, then "Unknown master"; "Unknown date"). Monsters by task count, most first, then by name ignoring case.
	 */
	private static Comparator<Entry> comparator(Grouping grouping)
	{
		Comparator<Entry> byRank = Comparator.comparingInt(entry -> entry.rank);
		if (grouping == Grouping.MONTH)
		{
			// "yyyy-MM" labels sort by date as text.
			return byRank.thenComparing(Entry::getLabel, Comparator.reverseOrder());
		}
		if (grouping == Grouping.MONSTER)
		{
			return Comparator.comparingInt(Entry::getTaskCount).reversed()
				.thenComparing(Entry::getLabel, String.CASE_INSENSITIVE_ORDER)
				.thenComparing(Entry::getLabel);
		}
		return byRank.thenComparing(Entry::getLabel, String.CASE_INSENSITIVE_ORDER)
			.thenComparing(Entry::getLabel);
	}

	/**
	 * Counts each By master group's assignments per monster: every completed task the groups count
	 * ({@link #isCompletedTask}, so a completed record without kills is not one) and every assignment log entry,
	 * under its master. A task is counted under its assigned name ({@link LedgerRecord#getMonster}), so a Catacombs
	 * variant or cannon task counts as its task. Entries and records of a master without a group are left out.
	 */
	private static void countAssignments(Collection<LedgerRecord> records, Collection<AssignmentEntry> assignments,
		Map<String, Aggregate> groups)
	{
		for (LedgerRecord record : records)
		{
			if (isCompletedTask(record))
			{
				Aggregate group = groups.get(masterKey(record.getSlayerMaster()));
				if (group != null)
				{
					group.assignments.add(record.getMonster(), null);
				}
			}
		}
		if (assignments == null)
		{
			return;
		}
		for (AssignmentEntry entry : assignments)
		{
			if (entry != null)
			{
				Aggregate group = groups.get(masterKey(entry.getSlayerMaster()));
				if (group != null)
				{
					group.assignments.add(entry.getMonster(), AssignmentOutcome.orUnknown(entry.getOutcome()));
				}
			}
		}
	}

	/**
	 * {@code 12 / 80 (15%)}: a monster's assignments out of the master's. The share is rounded to a whole percent
	 * (half up); a share that rounds to 0 shows as {@code <1%}.
	 */
	static String shareText(int count, int total)
	{
		return count + " / " + total + " (" + percentText(count, total) + ")";
	}

	private static String percentText(int count, int total)
	{
		if (total <= 0)
		{
			return LedgerHistory.NO_VALUE;
		}
		long percent = Math.round(count * 100d / total);
		return percent == 0 && count > 0 ? "<1%" : percent + "%";
	}

	/** {@code total / n} rounded, or {@code null} without samples. */
	private static Long average(long total, long n)
	{
		return n <= 0 ? null : Math.round(total / (double) n);
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/**
	 * One monster in a By master group's assignments: how often the master assigned it, of how many, and how
	 * they ended. Immutable; equal when every field is.
	 */
	@Value
	static class Assignment
	{
		/** The task's name as the newest of them names it. */
		String name;
		int count;
		/** All the master's assignments counted. */
		int total;
		/** Assignments played to completion with a saved task the groups count (with kills). */
		int completed;
		/** Assignment log entries by outcome; unmodifiable, without zero counts. */
		Map<AssignmentOutcome, Integer> outcomes;

		/** {@code 12 / 80 (15%)} ({@link #shareText}). */
		String text()
		{
			return shareText(count, total);
		}

		/**
		 * HTML tooltip: the name, the count of the master's assignments with the exact share, then how they ended
		 * ({@code Completed: 8}, then each outcome of the log's entries, as their rows label them).
		 */
		String tooltip(String master)
		{
			StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(name))
				.append("<br>").append(count).append(" of ").append(total)
				.append(total == 1 ? " assignment" : " assignments").append(" from ")
				.append(LedgerHistory.escapeHtml(master));
			if (total > 0)
			{
				sb.append(String.format(Locale.ROOT, " (%.1f%%)", count * 100d / total));
			}
			if (completed > 0)
			{
				sb.append("<br>Completed: ").append(completed);
			}
			for (Map.Entry<AssignmentOutcome, Integer> outcome : outcomes.entrySet())
			{
				sb.append("<br>").append(outcome.getKey().getLabel()).append(": ").append(outcome.getValue());
			}
			return sb.append("</html>").toString();
		}
	}

	@Builder
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Entry
	{
		private final String label;
		/**
		 * By monster: the assigned task name ({@link LedgerRecord#getMonster}) of the group's newest task, whose icon
		 * ({@link TaskIcons}) the group shows; {@code null} in other groupings.
		 */
		private final String task;
		private final int rank;
		private final int taskCount;
		private final long activeMillis;
		private final Long profit;
		private final int profitSampleCount;
		private final boolean profitApproximate;
		private final Long xp;
		private final int xpSampleCount;
		/** Summed supplies, unnamed and unsorted ({@link ItemSums#rows()}); empty without item data. */
		private final List<ItemDetails.Row> supplies;
		/** Summed loot, unnamed, unsorted and without the alch hint ({@link ItemSums#rows()}). */
		private final List<ItemDetails.Row> loot;
		private final long kills;
		private final Long millisPerKill;
		private final Long profitPerKill;
		private final Long profitPerHour;
		private final boolean profitRateApproximate;
		private final Long slayerXp;
		private final int slayerXpSampleCount;
		private final Long slayerXpPerHour;
		private final Long points;
		private final int pointsSampleCount;
		/** Points of the tasks with recorded points that are not bonus (milestone) tasks, for the average. */
		private final long regularPoints;
		private final int regularPointsSampleCount;
		/** By master: the master's assignments per monster, most first; empty otherwise. */
		private final List<Assignment> assignments;
		private final int assignmentTotal;

		String getLabel()
		{
			return label;
		}

		/**
		 * By monster: the assigned task name of the group's newest task, without its Catacombs variant or cannon use
		 *, for its icon ({@link TaskIcons}); {@code null} in other groupings or when the task had no name.
		 */
		String getTask()
		{
			return task;
		}

		int getTaskCount()
		{
			return taskCount;
		}

		long getActiveMillis()
		{
			return activeMillis;
		}

		/** Average active time per task. */
		long getAverageActiveMillis()
		{
			return taskCount <= 0 ? 0 : activeMillis / taskCount;
		}

		Long getProfit()
		{
			return profit;
		}

		int getProfitSampleCount()
		{
			return profitSampleCount;
		}

		boolean isProfitApproximate()
		{
			return profitApproximate;
		}

		/** Average profit per task over the {@link #getProfitSampleCount} tasks that have one, or {@code null}. */
		Long getAverageProfit()
		{
			return profit == null ? null : average(profit, profitSampleCount);
		}

		/** XP of every skill ({@link SkillXp#total}) over the records with {@code xpGained}, or {@code null}. */
		Long getXp()
		{
			return xp;
		}

		int getXpSampleCount()
		{
			return xpSampleCount;
		}

		/**
		 * The group's supplies summed item by item, valued at GE prices as the profit counts them; not named, so name
		 * them on the EDT ({@link ItemDetails#named}). Empty when none of its tasks used any or has item data.
		 */
		List<ItemDetails.Row> getSupplies()
		{
			return supplies == null ? Collections.emptyList() : supplies;
		}

		/**
		 * The group's loot summed item by item, in the Loot price mode as the profit counts it; not named and without
		 * the alch hint ({@link ItemDetails#named}). Empty when none of its tasks has any.
		 */
		List<ItemDetails.Row> getLoot()
		{
			return loot == null ? Collections.emptyList() : loot;
		}

		/** Task kills of all the group's tasks. */
		long getKills()
		{
			return kills;
		}

		/** Active time per kill over the group's task samples, or {@code null} without any. */
		Long getMillisPerKill()
		{
			return millisPerKill;
		}

		/**
		 * Profit per kill as Trends pools it: the profit of the task samples that have one over their kills, or
		 * {@code null} without any.
		 */
		Long getProfitPerKill()
		{
			return profitPerKill;
		}

		/**
		 * Profit per hour as Trends pools it: the profit of the task samples that have one over their active time, or
		 * {@code null} under {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of it.
		 */
		Long getProfitPerHour()
		{
			return profitPerHour;
		}

		/** Whether {@link #getProfitPerKill} and {@link #getProfitPerHour} are approximate. */
		boolean isProfitRateApproximate()
		{
			return profitRateApproximate;
		}

		/** Slayer XP only, over the tasks with recorded XP, or {@code null} when none has any. */
		Long getSlayerXp()
		{
			return slayerXp;
		}

		int getSlayerXpSampleCount()
		{
			return slayerXpSampleCount;
		}

		/** Average Slayer XP per task over {@link #getSlayerXpSampleCount} tasks, or {@code null}. */
		Long getAverageSlayerXp()
		{
			return slayerXp == null ? null : average(slayerXp, slayerXpSampleCount);
		}

		/**
		 * Slayer XP per hour as Trends pools it (the task samples with XP over their active time), or {@code null}
		 * under {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of it.
		 */
		Long getSlayerXpPerHour()
		{
			return slayerXpPerHour;
		}

		/** Slayer points of the tasks that recorded them (bonus tasks included), or {@code null} when none did. */
		Long getPoints()
		{
			return points;
		}

		int getPointsSampleCount()
		{
			return pointsSampleCount;
		}

		/**
		 * Average points per task over the {@link #getAveragePointsSampleCount} tasks with recorded points that are not
		 * bonus tasks ({@link StreakMilestone#isMilestone}, as Points/h leaves them out), or {@code null} without any.
		 * {@link #getPoints} still counts the bonus tasks.
		 */
		Long getAveragePoints()
		{
			return average(regularPoints, regularPointsSampleCount);
		}

		/** The tasks {@link #getAveragePoints} averages over. */
		int getAveragePointsSampleCount()
		{
			return regularPointsSampleCount;
		}

		/** By master: each monster's assignments, most first ({@link Assignment}); empty in other groupings. */
		List<Assignment> getAssignments()
		{
			return assignments == null ? Collections.emptyList() : assignments;
		}

		/** By master: all the master's assignments counted; 0 in other groupings. */
		int getAssignmentTotal()
		{
			return assignmentTotal;
		}
	}

	/** A pooled rate's totals, as {@link TaskRanking} pools a metric: its total, active time and kills. */
	private static final class Pool
	{
		private long total;
		private long activeMillis;
		private long kills;
		private boolean approximate;

		private void add(long value, LedgerRecord record, boolean isApproximate)
		{
			total = saturatedAdd(total, value);
			activeMillis = saturatedAdd(activeMillis, record.getActiveMillis());
			kills = saturatedAdd(kills, record.getKills());
			approximate |= isApproximate;
		}

		private Long perHour()
		{
			return activeMillis <= 0 ? null : TaskRanking.perHour(total, activeMillis);
		}
	}

	/** A By master group's assignments per monster, by normalized name. */
	private static final class AssignmentTally
	{
		private final Map<String, Counts> monsters = new LinkedHashMap<>();
		private int total;

		/** Counts one assignment of {@code monster}: a completed task ({@code outcome} {@code null}) or a log entry. */
		private void add(String monster, AssignmentOutcome outcome)
		{
			String name = monster == null || TaskStatistics.normalize(monster) == null
				? LedgerHistory.UNKNOWN_MONSTER : monster.trim();
			Counts counts = monsters.computeIfAbsent(TaskStatistics.normalize(name), k -> new Counts(name));
			counts.count++;
			if (outcome == null)
			{
				counts.completed++;
			}
			else
			{
				counts.outcomes.merge(outcome, 1, Integer::sum);
			}
			total++;
		}

		private List<Assignment> rows()
		{
			List<Assignment> rows = new ArrayList<>();
			for (Counts counts : monsters.values())
			{
				rows.add(new Assignment(counts.name, counts.count, total, counts.completed,
					Collections.unmodifiableMap(new EnumMap<>(counts.outcomes))));
			}
			rows.sort(ASSIGNMENT_ORDER);
			return Collections.unmodifiableList(rows);
		}

		private static final class Counts
		{
			private final String name;
			private int count;
			private int completed;
			private final Map<AssignmentOutcome, Integer> outcomes = new EnumMap<>(AssignmentOutcome.class);

			private Counts(String name)
			{
				this.name = name;
			}
		}
	}

	private static final class Aggregate
	{
		private final String label;
		private final int rank;
		/** By monster: the newest task's assigned name ({@link Entry#getTask}); {@code null} otherwise. */
		private final String task;
		private int taskCount;
		private long activeMillis;
		private long profit;
		private int profitSampleCount;
		private boolean profitApproximate;
		private long xp;
		private int xpSampleCount;
		private final ItemSums supplies = new ItemSums();
		private final ItemSums loot = new ItemSums();
		private long kills;
		/** The task samples' time and kills, for the time per kill. */
		private final Pool time = new Pool();
		private final Pool profitRate = new Pool();
		private long slayerXp;
		private int slayerXpSampleCount;
		private final Pool slayerXpRate = new Pool();
		private long points;
		private int pointsSampleCount;
		private long regularPoints;
		private int regularPointsSampleCount;
		private final AssignmentTally assignments = new AssignmentTally();

		private Aggregate(String label, int rank, String task)
		{
			this.label = label;
			this.rank = rank;
			this.task = task;
		}

		private void add(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
		{
			taskCount++;
			activeMillis = saturatedAdd(activeMillis, Math.max(0, record.getActiveMillis()));
			kills = saturatedAdd(kills, record.getKills());
			// The rates pool only the task samples, as Trends does (a task with no active time adds none).
			boolean sample = TaskRanking.isTaskSample(record);
			if (sample)
			{
				time.add(0, record, false);
			}

			if (LedgerHistory.isValued(record))
			{
				HistoryPricing.Values values = HistoryPricing.value(record, mode, currentGe, hidden);
				if (values.getProfit() != null)
				{
					profit = saturatedAdd(profit, values.getProfit());
					profitSampleCount++;
					profitApproximate |= values.isProfitApproximate();
					if (sample)
					{
						profitRate.add(values.getProfit(), record, values.isProfitApproximate());
					}
				}
			}

			Map<String, Long> recordXp = record.getXpGained();
			if (recordXp != null)
			{
				xp = saturatedAdd(xp, SkillXp.total(recordXp));
				xpSampleCount++;
				// As Trends: XP recorded without a Slayer entry means no Slayer XP was gained.
				Long slayer = recordXp.get(SkillXp.SLAYER);
				long slayerValue = slayer == null ? 0 : Math.max(0, slayer);
				slayerXp = saturatedAdd(slayerXp, slayerValue);
				slayerXpSampleCount++;
				if (sample)
				{
					slayerXpRate.add(slayerValue, record, false);
				}
			}

			Integer earned = record.getPointsEarned();
			if (earned != null && earned >= 0)
			{
				points = saturatedAdd(points, earned);
				pointsSampleCount++;
				// The average leaves out bonus tasks, whose points would swamp it.
				if (!StreakMilestone.isMilestone(record.getTaskStreak()))
				{
					regularPoints = saturatedAdd(regularPoints, earned);
					regularPointsSampleCount++;
				}
			}

			addItems(record, mode, currentGe);
		}

		/**
		 * Adds the record's supplies and loot as its history details show them (at the same prices: today's GE prices,
		 * as {@link HistoryPricing} values the profit); nothing without item data.
		 */
		private void addItems(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe)
		{
			ItemDetails items = ItemDetails.of(record);
			if (items == null)
			{
				return;
			}
			items = items.withGePrices(currentGe);
			supplies.add(items.supplyRows(null));
			loot.add(items.lootRows(mode, null));
		}

		private Entry toEntry()
		{
			return Entry.builder()
				.label(label)
				.task(task)
				.rank(rank)
				.taskCount(taskCount)
				.activeMillis(activeMillis)
				.profit(profitSampleCount == 0 ? null : profit)
				.profitSampleCount(profitSampleCount)
				.profitApproximate(profitApproximate)
				.xp(xpSampleCount == 0 ? null : xp)
				.xpSampleCount(xpSampleCount)
				.supplies(supplies.rows())
				.loot(loot.rows())
				.kills(kills)
				.millisPerKill(TaskRanking.perKill(time.activeMillis, time.kills))
				.profitPerKill(TaskRanking.perKill(profitRate.total, profitRate.kills))
				.profitPerHour(profitRate.perHour())
				.profitRateApproximate(profitRate.approximate)
				.slayerXp(slayerXpSampleCount == 0 ? null : slayerXp)
				.slayerXpSampleCount(slayerXpSampleCount)
				.slayerXpPerHour(slayerXpRate.perHour())
				.points(pointsSampleCount == 0 ? null : points)
				.pointsSampleCount(pointsSampleCount)
				.regularPoints(regularPoints)
				.regularPointsSampleCount(regularPointsSampleCount)
				.assignments(assignments.rows())
				.assignmentTotal(assignments.total)
				.build();
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeSet;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The collapsed "Overall totals" section of {@link SlayerLedgerPanel}: completed-task totals, overall or grouped
 * by Slayer master, month or monster ({@link OverallTotals}, worked out by the history model). The rows are built only
 * while the section is open and its "Overall totals" setting shows it, and never by the panel's refresh timer.
 * Overall and By month show the task count, active time, profit and XP of all skills; By monster and By master
 * show averages and rates instead, and By master its monsters assigned ({@link OverallTotals.Assignment}) in a
 * text list with "+N more" ({@link ItemListView}).
 *
 * <p>By monster's group names and By master's monsters assigned show the task's icon before the name (* {@link TaskIcons}), the item sprite at the XP lists' small icon size ({@link SmallItemIcon}), asked for on the EDT
 * only when the rows are built (open and shown, never by the refresh timer); a task without a known icon keeps an
 * empty slot of the same size.</p>
 *
 * <p>By master's group names show the master's face ({@link MasterIcons}), the bundled chathead image drawn in
 * the same slot, read the first time it is shown; a missing image or an unknown master keeps the empty slot.</p>
 *
 * <p>Each group has two item grids, "Supplies used" and "Loot received", closed until clicked. Its items are
 * summed off the EDT with the totals ({@link OverallTotals.Entry#getSupplies()}); here they are only named
 * ({@link ItemDetails#named}, with the names the model's {@link NameBook} has, asked for here) and shown. A grid stays
 * open or closed while the section rebuilds the same group in the same grouping; closing the section or changing the
 * grouping closes them again. EDT only.</p>
 */
final class OverallTotalsSection
{
	/** XP is every skill's (owner decision), unlike Trends' Slayer XP/h. */
	private static final String XP_LABEL = "XP (all skills)";
	private static final String SUPPLIES_TITLE = "Supplies used";
	private static final String LOOT_TITLE = "Loot received";
	private static final String ASSIGNMENTS_TITLE = "Monsters assigned";
	/** The assignment lines have no skill icons; their task icons are item sprites ({@link #icons}). */
	private static final SkillIcons NO_ICONS = (label, skill) ->
	{
	};

	private final LedgerHistoryModel model;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Draws the item grids' icons and the task icons. */
	private final ItemIcons icons;
	/** The masters' faces of By master. */
	private final MasterIcons masterIcons;

	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	private final JLabel title = new JLabel("Overall totals");
	private final JLabel toggle = new JLabel();
	private final JPanel body = new JPanel();
	private final JComboBox<OverallTotals.Grouping> grouping = new JComboBox<>(OverallTotals.Grouping.values());
	private final JPanel list = new JPanel();
	private boolean expanded;
	/** The "Overall totals" setting; while off, nothing is summed, open or not. The panel hides the components. */
	private boolean shown = true;
	/** How many times the rows were built. */
	private int builds;
	/** The model's totals the rows shown were built from; {@code null} when none are. */
	private List<OverallTotals.Entry> shownEntries;
	/**
	 * The item grids shown, by grouping, group and list, with the unnamed rows they show; kept while the same groups
	 * are rebuilt, so an open grid stays open.
	 */
	private Map<String, Grid> grids = new HashMap<>();
	/** The By master assignment lists shown, by grouping and group; kept like {@link #grids}, so "+N more" stays. */
	private Map<String, ItemListView> assignmentLists = new HashMap<>();

	/** @param masterIcons the masters' faces before By master's group names */
	OverallTotalsSection(LedgerHistoryModel model, Runnable relayout, ItemIcons icons, MasterIcons masterIcons)
	{
		this.model = model;
		this.relayout = relayout;
		this.icons = icons;
		this.masterIcons = masterIcons;
	}

	/** Adds the header and the body to {@code content}, collapsed. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		header.setName("totals.header");
		title.setName("totals.title");
		toggle.setName("totals.toggle");
		body.setName("totals.body");
		grouping.setName("totals.grouping");
		list.setName("totals.list");
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		toggle.setFont(FontManager.getRunescapeSmallFont());
		toggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(title, BorderLayout.WEST);
		header.add(toggle, BorderLayout.EAST);
		header.setToolTipText("Completed-task totals, overall or grouped by Slayer master, month or monster.");
		MouseAdapter toggleListener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggle();
			}
		};
		header.addMouseListener(toggleListener);
		title.addMouseListener(toggleListener);
		toggle.addMouseListener(toggleListener);
		SlayerLedgerPanel.addRow(content, header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel groupingRow = new JPanel(new BorderLayout(6, 0));
		groupingRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel groupingLabel = new JLabel("Group");
		groupingLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		groupingLabel.setFont(FontManager.getRunescapeSmallFont());
		grouping.setFocusable(false);
		grouping.addActionListener(e ->
		{
			if (expanded && shown)
			{
				buildRows();
			}
		});
		groupingRow.add(groupingLabel, BorderLayout.WEST);
		groupingRow.add(grouping, BorderLayout.CENTER);
		SlayerLedgerPanel.addRow(body, groupingRow);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);
		SlayerLedgerPanel.addRow(body, list);
		body.setVisible(false);
		SlayerLedgerPanel.addRow(content, body);
		rebuild();
	}

	/** Opens or closes the section. */
	void toggle()
	{
		expanded = !expanded;
		rebuild();
	}

	/**
	 * Applies the "Overall totals" setting: hidden, the section drops its rows and sums nothing; shown again, it
	 * is rebuilt from the current records at once if it was open.
	 */
	void setShown(boolean value)
	{
		if (shown != value)
		{
			shown = value;
			rebuild();
		}
	}

	/** Shows the section as it now is: when open and shown, sums the current records; otherwise drops the rows. */
	void rebuild()
	{
		toggle.setText(expanded ? "Hide" : "Show");
		body.setVisible(expanded);
		if (expanded && shown)
		{
			buildRows();
		}
		else
		{
			// Nothing is summed while collapsed or hidden; opening or showing the section sums the current records.
			list.removeAll();
			shownEntries = null;
			grids = new HashMap<>();
			assignmentLists = new HashMap<>();
		}
		relayout.run();
	}

	/**
	 * Item names or the nature rune price (the alch hint) arrived: while open and shown, the grids are named again.
	 * Only grids whose rows changed are redrawn, and the totals are not rebuilt.
	 */
	void itemNamesChanged()
	{
		if (expanded && shown && shownEntries != null)
		{
			for (Grid grid : grids.values())
			{
				grid.show();
			}
			relayout.run();
		}
	}

	/**
	 * The totals worked out off the EDT are ready (the model's {@link LedgerHistoryModel.Change#VIEWS}): while open and
	 * shown, builds the rows again if the model now has totals it does not show.
	 */
	void viewsReady()
	{
		// While views wait for today's prices what is shown stays; the end of the wait rebuilds it.
		if (expanded && shown && !model.isWaitingForCurrentPrices())
		{
			List<OverallTotals.Entry> entries = model.overallTotals(
				(OverallTotals.Grouping) grouping.getSelectedItem());
			if (entries != null && entries != shownEntries)
			{
				buildRows();
			}
		}
	}

	private void buildRows()
	{
		OverallTotals.Grouping selected = (OverallTotals.Grouping) grouping.getSelectedItem();
		List<OverallTotals.Entry> entries = model.overallTotals(selected);
		if (entries == null)
		{
			// Worked out off the EDT: the rows shown stay until it is ready (viewsReady).
			return;
		}
		builds++;
		shownEntries = entries;
		list.removeAll();
		Map<String, Grid> kept = new HashMap<>();
		Map<String, ItemListView> keptLists = new HashMap<>();
		Set<Integer> ids = new TreeSet<>();
		if (entries.isEmpty())
		{
			JLabel empty = new JLabel("No completed tasks yet.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
			empty.setAlignmentX(Component.LEFT_ALIGNMENT);
			list.add(empty);
		}
		else
		{
			for (int i = 0; i < entries.size(); i++)
			{
				OverallTotals.Entry entry = entries.get(i);
				String key = selected + "|" + entry.getLabel();
				JPanel row = row(entry, selected);
				JPanel items = items(entry, key, kept, ids);
				if (selected == OverallTotals.Grouping.MASTER)
				{
					// The monsters assigned come first, above the item grids.
					items.add(assignmentList(entry, key, keptLists), 0);
					JComponent gap = (JComponent) Box.createVerticalStrut(2);
					gap.setAlignmentX(Component.LEFT_ALIGNMENT);
					items.add(gap, 1);
				}
				row.add(items);
				list.add(row);
				if (i + 1 < entries.size())
				{
					list.add(Box.createVerticalStrut(2));
				}
			}
		}
		grids = kept;
		assignmentLists = keptLists;
		if (!ids.isEmpty())
		{
			model.requestItemNames(ids);
		}
		relayout.run();
	}

	/**
	 * A group's two item grids, below its lines: the grids already shown for {@code key} if any, so an open one stays
	 * open, else new closed ones. They go into {@code kept}, and their item ids into {@code ids}.
	 */
	private JPanel items(OverallTotals.Entry entry, String key, Map<String, Grid> kept, Set<Integer> ids)
	{
		JPanel items = new JPanel();
		// A name for tests, which read the lines above it apart from it; no visible effect.
		items.setName("totals.items");
		items.setLayout(new BoxLayout(items, BoxLayout.Y_AXIS));
		items.setOpaque(false);
		items.setAlignmentX(Component.LEFT_ALIGNMENT);
		items.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
		items.add(grid(key + "|supplies", "totals.supplies", SUPPLIES_TITLE, entry.getSupplies(), false, kept));
		items.add(Box.createVerticalStrut(2));
		items.add(grid(key + "|loot", "totals.loot", LOOT_TITLE, entry.getLoot(), true, kept));
		for (Component c : items.getComponents())
		{
			((JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		for (ItemDetails.Row row : entry.getSupplies())
		{
			ids.add(row.getItemId());
		}
		for (ItemDetails.Row row : entry.getLoot())
		{
			ids.add(row.getItemId());
		}
		return items;
	}

	/**
	 * A By master group's monsters assigned: {@code Dust devils | 12 / 80 (15%)}, most first, the top
	 * {@link ItemDetails#MAX_ROWS} until "+N more" is clicked. The list shown for {@code key} is kept, so its "+N more"
	 * choice stays while the same group rebuilds; it goes into {@code kept}.
	 */
	private ItemListView assignmentList(OverallTotals.Entry entry, String key, Map<String, ItemListView> kept)
	{
		ItemListView view = assignmentLists.get(key);
		if (view == null)
		{
			view = new ItemListView(ASSIGNMENTS_TITLE, false, ColorScheme.DARKER_GRAY_COLOR, "monsters", NO_ICONS,
				icons);
			// A name for tests, which find the list by it; no visible effect.
			view.setName("totals.assignments");
			view.hideCount();
			view.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
			view.setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		List<AssignmentLine> lines = new ArrayList<>();
		for (OverallTotals.Assignment assignment : entry.getAssignments())
		{
			lines.add(new AssignmentLine(assignment, entry.getLabel()));
		}
		view.setRows(lines);
		kept.put(key, view);
		return view;
	}

	/** The grid for {@code key}, kept from the last build or new and closed, showing {@code rows}. */
	private ItemGridView grid(String key, String name, String title, List<ItemDetails.Row> rows, boolean loot,
		Map<String, Grid> kept)
	{
		Grid grid = grids.get(key);
		if (grid == null)
		{
			ItemGridView view = new ItemGridView(title, true, ColorScheme.DARKER_GRAY_COLOR, icons);
			// A name for tests, which find the grids by it; no visible effect.
			view.setName(name);
			view.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
			grid = new Grid(view, loot);
		}
		grid.rows = rows;
		grid.show();
		kept.put(key, grid);
		return grid.view;
	}

	/**
	 * One totals entry in short two-column lines that fit the sidebar, like a history row: the bold group name and
	 * task count, then the grouping's lines ({@link #addTotalLines}, {@link #addMonsterLines},
	 * {@link #addMasterLines}).
	 */
	private JPanel row(OverallTotals.Entry entry, OverallTotals.Grouping grouping)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(3, 8, 3, 4));

		JLabel name = SlayerLedgerPanel.historyLabel(entry.getLabel(), Color.WHITE);
		name.setFont(FontManager.getRunescapeBoldFont());
		if (grouping == OverallTotals.Grouping.MONSTER)
		{
			taskIcon(name, entry.getTask());
		}
		else if (grouping == OverallTotals.Grouping.MASTER)
		{
			masterIcon(name, entry.getLabel());
		}
		JLabel count = SlayerLedgerPanel.historyLabel(SlayerLedgerPanel.sampleTasks(entry.getTaskCount()),
			ColorScheme.LIGHT_GRAY_COLOR);
		// Completed tasks, not By master's assignments.
		count.setToolTipText(completedTasks(entry.getTaskCount()));
		row.add(SlayerLedgerPanel.historyLine(name, count));
		if (grouping == OverallTotals.Grouping.MONSTER)
		{
			addMonsterLines(row, entry);
			row.setToolTipText(monsterTooltip(entry));
		}
		else if (grouping == OverallTotals.Grouping.MASTER)
		{
			addMasterLines(row, entry);
			row.setToolTipText(masterTooltip(entry));
		}
		else
		{
			addTotalLines(row, entry);
			row.setToolTipText(tooltip(entry));
		}
		for (Component line : row.getComponents())
		{
			((JComponent) line).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		return row;
	}

	/**
	 * By monster's group name: the icon of the group's task ({@link OverallTotals.Entry#getTask}, so a Catacombs
	 * variant or cannon group shows its task's), or an empty slot of the same size, before the name. The name asks for
	 * no width of its own, so the icon can't widen the sidebar: a long name is cut short (the row's tooltip has it).
	 */
	private void taskIcon(JLabel name, String task)
	{
		// A name for tests, which read the icon from it; no visible effect.
		name.setName("totals.name");
		SmallItemIcon.applyTask(icons, name, task);
	}

	/**
	 * By master's group name: the master's face ({@link MasterIcons}), or an empty slot of the same size for an
	 * unknown master or a missing image, before the name, which asks for no width of its own, as {@link #taskIcon}.
	 */
	private void masterIcon(JLabel name, String master)
	{
		// A name for tests, which read the icon from it; no visible effect.
		name.setName("totals.name");
		name.setIconTextGap(4);
		name.setIcon(masterIcons.icon(master));
		name.setPreferredSize(new Dimension(0, name.getPreferredSize().height));
	}

	/** Overall and By month: active time, profit and XP of all skills, each value with its own sample count. */
	private void addTotalLines(JPanel row, OverallTotals.Entry entry)
	{
		row.add(SlayerLedgerPanel.historyLine(SlayerLedgerPanel.historyLabel("Active:", ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatDuration(entry.getActiveMillis()),
				ColorScheme.LIGHT_GRAY_COLOR)));
		// "Profit (GE):" / "Profit (HA):" with the Loot price mode; amounts without " gp", as history rows.
		String profit = LedgerHistory.formatAmount(entry.getProfit(), entry.isProfitApproximate())
			+ " (n=" + entry.getProfitSampleCount() + ")";
		row.add(SlayerLedgerPanel.historyLine(SlayerLedgerPanel.historyLabel(
			LedgerHistory.profitLabel(model.lootPriceMode()).trim(), ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(profit, SlayerLedgerPanel.profitColor(entry.getProfit()))));
		row.add(SlayerLedgerPanel.historyLine(SlayerLedgerPanel.historyLabel(XP_LABEL + ":",
			ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(LedgerHistory.formatAmount(entry.getXp(), false) + " (n="
				+ entry.getXpSampleCount() + ")", ColorScheme.LIGHT_GRAY_COLOR)));
	}

	/**
	 * By monster: tasks done, kills, average task length, average task profit, profit per kill, time per kill,
	 * profit per hour, then Slayer XP and Slayer XP per hour. The totals show their sample count as {@code (n=...)};
	 * the averages use those tasks and the rates those of them with active time, so they don't repeat it.
	 */
	private void addMonsterLines(JPanel row, OverallTotals.Entry entry)
	{
		String profit = LedgerHistory.profitName(model.lootPriceMode());
		addLine(row, "Tasks done:", LedgerHistory.formatAmount((long) entry.getTaskCount(), false),
			ColorScheme.LIGHT_GRAY_COLOR);
		addLine(row, "Killed:", LedgerHistory.formatAmount(entry.getKills(), false), ColorScheme.LIGHT_GRAY_COLOR);
		addLine(row, "Avg task:", LedgerHistory.formatDuration(entry.getAverageActiveMillis()),
			ColorScheme.LIGHT_GRAY_COLOR);
		addProfitLine(row, "Avg " + lowerFirst(profit) + ":", entry.getAverageProfit(), entry.isProfitApproximate(),
			entry.getProfitSampleCount());
		addProfitLine(row, profit + "/kill:", entry.getProfitPerKill(), entry.isProfitRateApproximate(), null);
		addLine(row, "Time/kill:", entry.getMillisPerKill() == null ? LedgerHistory.NO_VALUE
			: LedgerHistory.formatKillTime(entry.getMillisPerKill()), ColorScheme.LIGHT_GRAY_COLOR);
		addProfitLine(row, profit + "/h:", entry.getProfitPerHour(), entry.isProfitRateApproximate(), null);
		addCountLine(row, "Slayer XP:", entry.getSlayerXp(), entry.getSlayerXpSampleCount());
		addLine(row, "Slayer XP/h:", LedgerHistory.formatAmount(entry.getSlayerXpPerHour(), false),
			ColorScheme.LIGHT_GRAY_COLOR);
	}

	/**
	 * By master: total tasks, average task length, average task profit, total profit, profit per hour, Slayer
	 * points (total and per task, the average without bonus tasks) and Slayer XP (total and per task). The monsters
	 * assigned are a list below them ({@link #assignmentList}).
	 */
	private void addMasterLines(JPanel row, OverallTotals.Entry entry)
	{
		String profit = LedgerHistory.profitName(model.lootPriceMode());
		addLine(row, "Total tasks:", LedgerHistory.formatAmount((long) entry.getTaskCount(), false),
			ColorScheme.LIGHT_GRAY_COLOR);
		addLine(row, "Avg task:", LedgerHistory.formatDuration(entry.getAverageActiveMillis()),
			ColorScheme.LIGHT_GRAY_COLOR);
		addProfitLine(row, "Avg " + lowerFirst(profit) + ":", entry.getAverageProfit(), entry.isProfitApproximate(),
			null);
		addProfitLine(row, profit + ":", entry.getProfit(), entry.isProfitApproximate(), entry.getProfitSampleCount());
		addProfitLine(row, profit + "/h:", entry.getProfitPerHour(), entry.isProfitRateApproximate(), null);
		addCountLine(row, "Points:", entry.getPoints(), entry.getPointsSampleCount());
		addLine(row, "Avg points:", LedgerHistory.formatAmount(entry.getAveragePoints(), false),
			ColorScheme.LIGHT_GRAY_COLOR);
		addCountLine(row, "Slayer XP:", entry.getSlayerXp(), entry.getSlayerXpSampleCount());
		addLine(row, "Avg Slayer XP:", LedgerHistory.formatAmount(entry.getAverageSlayerXp(), false),
			ColorScheme.LIGHT_GRAY_COLOR);
	}

	/** "Profit (GE)" as "profit (GE)", after "Avg". */
	private static String lowerFirst(String text)
	{
		return text.isEmpty() ? text : Character.toLowerCase(text.charAt(0)) + text.substring(1);
	}

	/** A two-column line: {@code left} in grey, {@code right} in {@code color}. */
	private static void addLine(JPanel row, String left, String right, Color color)
	{
		row.add(SlayerLedgerPanel.historyLine(SlayerLedgerPanel.historyLabel(left, ColorScheme.LIGHT_GRAY_COLOR),
			SlayerLedgerPanel.historyLabel(right, color)));
	}

	/**
	 * A profit amount without " gp", with {@code ~} when approximate, coloured as a profit, and {@code (n=...)} when
	 * {@code samples} is given.
	 */
	private static void addProfitLine(JPanel row, String left, Long value, boolean approximate, Integer samples)
	{
		addLine(row, left, LedgerHistory.formatAmount(value, approximate)
			+ (samples == null ? "" : " (n=" + samples + ")"), SlayerLedgerPanel.profitColor(value));
	}

	/** A total with its sample count: {@code 12.3K (n=12)}, or {@code - (n=0)}. */
	private static void addCountLine(JPanel row, String left, Long value, int samples)
	{
		addLine(row, left, LedgerHistory.formatAmount(value, false) + " (n=" + samples + ")",
			ColorScheme.LIGHT_GRAY_COLOR);
	}

	/** Exact totals, the price source and what each sample count means. */
	private String tooltip(OverallTotals.Entry entry)
	{
		LootPriceMode mode = model.lootPriceMode();
		StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(entry.getLabel()));
		int tasks = entry.getTaskCount();
		sb.append("<br>").append(tasks).append(tasks == 1 ? " completed task" : " completed tasks")
			.append(", active ").append(LedgerHistory.formatDuration(entry.getActiveMillis()));

		Long profit = entry.getProfit();
		sb.append("<br>").append(LedgerHistory.escapeHtml(LedgerHistory.profitLabel(mode)))
			.append(profit == null ? "unknown" : (entry.isProfitApproximate() ? LedgerHistory.APPROXIMATE : "")
				+ LedgerHistory.escapeHtml(LedgerHistory.formatGpExact(profit)));
		String source = "Loot at " + mode + " prices minus GE-valued supplies"
			+ (mode == LootPriceMode.HIGH_ALCH
			? " (today's available GE prices for GE-priced items)"
			: " (today's available GE prices)");
		sb.append("<br>").append(LedgerHistory.escapeHtml(source));
		sb.append("<br>n = ").append(SlayerLedgerPanel.sampleTasks(entry.getProfitSampleCount()))
			.append(" with loot and supply values");

		Long xp = entry.getXp();
		sb.append("<br>").append(XP_LABEL).append(": ")
			.append(xp == null ? "unknown" : String.format("%,d", xp));
		sb.append("<br>n = ").append(SlayerLedgerPanel.sampleTasks(entry.getXpSampleCount())).append(" with recorded XP");
		if (entry.isProfitApproximate())
		{
			sb.append("<br>~ means some item prices were unavailable, or an older task kept its saved totals.");
		}
		return sb.append("</html>").toString();
	}

	/** By monster's tooltip: the exact figures, the price source and how the rates are worked out. */
	private String monsterTooltip(OverallTotals.Entry entry)
	{
		LootPriceMode mode = model.lootPriceMode();
		String profit = LedgerHistory.profitName(mode);
		StringBuilder sb = groupTooltipStart(entry);
		sb.append("<br>Killed: ").append(String.format("%,d", entry.getKills()));
		sb.append("<br>Average task: ").append(LedgerHistory.formatDuration(entry.getAverageActiveMillis()));
		sb.append("<br>Average ").append(lowerFirst(profit)).append(": ")
			.append(exactGp(entry.getAverageProfit(), entry.isProfitApproximate()));
		sb.append("<br>").append(profit).append(" per kill: ")
			.append(exactGp(entry.getProfitPerKill(), entry.isProfitRateApproximate()));
		sb.append("<br>Time per kill: ").append(entry.getMillisPerKill() == null ? LedgerHistory.NO_VALUE
			: LedgerHistory.formatKillTime(entry.getMillisPerKill()));
		sb.append("<br>").append(profit).append(" per hour: ")
			.append(exactGp(entry.getProfitPerHour(), entry.isProfitRateApproximate()));
		sb.append("<br>Slayer XP: ").append(exact(entry.getSlayerXp()))
			.append(", per hour: ").append(exact(entry.getSlayerXpPerHour()));
		appendNotes(sb, entry, mode);
		return sb.append("</html>").toString();
	}

	/** By master's tooltip: the exact figures, the price source and what the sample counts mean. */
	private String masterTooltip(OverallTotals.Entry entry)
	{
		LootPriceMode mode = model.lootPriceMode();
		String profit = LedgerHistory.profitName(mode);
		StringBuilder sb = groupTooltipStart(entry);
		sb.append("<br>Average task: ").append(LedgerHistory.formatDuration(entry.getAverageActiveMillis()));
		sb.append("<br>Average ").append(lowerFirst(profit)).append(": ")
			.append(exactGp(entry.getAverageProfit(), entry.isProfitApproximate()));
		sb.append("<br>").append(profit).append(": ").append(exactGp(entry.getProfit(), entry.isProfitApproximate()));
		sb.append("<br>").append(profit).append(" per hour: ")
			.append(exactGp(entry.getProfitPerHour(), entry.isProfitRateApproximate()));
		sb.append("<br>Slayer points: ").append(exact(entry.getPoints())).append(", per task: ")
			.append(exact(entry.getAveragePoints()));
		sb.append("<br>n = ").append(SlayerLedgerPanel.sampleTasks(entry.getPointsSampleCount()))
			.append(" with recorded points (bonus tasks included)");
		sb.append("<br>Per task leaves out bonus tasks (every 10th in a streak): ")
			.append(SlayerLedgerPanel.sampleTasks(entry.getAveragePointsSampleCount()));
		sb.append("<br>Slayer XP: ").append(exact(entry.getSlayerXp())).append(", per task: ")
			.append(exact(entry.getAverageSlayerXp()));
		appendNotes(sb, entry, mode);
		int assigned = entry.getAssignmentTotal();
		sb.append("<br>Monsters assigned: ").append(assigned).append(assigned == 1 ? " assignment" : " assignments")
			.append(" (completed tasks and Skipped / blocked entries)");
		return sb.append("</html>").toString();
	}

	/** The group's name and task count, with the active time. */
	private static StringBuilder groupTooltipStart(OverallTotals.Entry entry)
	{
		StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(entry.getLabel()));
		return sb.append("<br>").append(completedTasks(entry.getTaskCount())).append(", active ")
			.append(LedgerHistory.formatDuration(entry.getActiveMillis()));
	}

	/** {@code 12 completed tasks}. */
	private static String completedTasks(int tasks)
	{
		return tasks + (tasks == 1 ? " completed task" : " completed tasks");
	}

	/** The price source, the sample counts, the rate rules and the {@code ~} note. */
	private static void appendNotes(StringBuilder sb, OverallTotals.Entry entry, LootPriceMode mode)
	{
		sb.append("<br>").append(LedgerHistory.escapeHtml("Loot at " + mode + " prices minus GE-valued supplies"
			+ (mode == LootPriceMode.HIGH_ALCH
			? " (today's available GE prices for GE-priced items)"
			: " (today's available GE prices)")));
		sb.append("<br>n = ").append(SlayerLedgerPanel.sampleTasks(entry.getProfitSampleCount()))
			.append(" with loot and supply values, ").append(entry.getSlayerXpSampleCount())
			.append(" with recorded XP");
		sb.append("<br>Averages use those tasks; rates pool those of them with active time, as Trends does,")
			.append(" and hourly rates need 1 minute of it.");
		if (entry.isProfitApproximate())
		{
			sb.append("<br>~ means some item prices were unavailable, or an older task kept its saved totals.");
		}
	}

	/** An exact gp amount for a tooltip, {@code ~} when approximate, or "-". */
	private static String exactGp(Long value, boolean approximate)
	{
		return value == null ? LedgerHistory.NO_VALUE : (approximate ? LedgerHistory.APPROXIMATE : "")
			+ LedgerHistory.escapeHtml(LedgerHistory.formatGpExact(value));
	}

	/** An exact count for a tooltip, or "-". */
	private static String exact(Long value)
	{
		return value == null ? LedgerHistory.NO_VALUE : String.format("%,d", value);
	}

	/** How many times the rows were built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}

	/**
	 * One line of a By master group's monsters assigned ({@link OverallTotals.Assignment}); equal when its assignment
	 * and master are, so an unchanged list is not redrawn.
	 */
	private static final class AssignmentLine implements ItemListView.Line
	{
		private final OverallTotals.Assignment assignment;
		private final String master;

		private AssignmentLine(OverallTotals.Assignment assignment, String master)
		{
			this.assignment = assignment;
			this.master = master;
		}

		@Override
		public String getName()
		{
			return assignment.getName();
		}

		@Override
		public String getSkill()
		{
			return null;
		}

		/** The task's icon, or {@code null} for a name that is no known task (an empty slot). */
		@Override
		public Integer getIconItemId()
		{
			return TaskIcons.itemId(assignment.getName());
		}

		@Override
		public String amountText()
		{
			return assignment.text();
		}

		@Override
		public String tooltip()
		{
			return assignment.tooltip(master);
		}

		@Override
		public boolean equals(Object other)
		{
			if (!(other instanceof AssignmentLine))
			{
				return false;
			}
			AssignmentLine that = (AssignmentLine) other;
			return assignment.equals(that.assignment) && master.equals(that.master);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(assignment, master);
		}
	}

	/** One item grid and the unnamed rows it shows. */
	private final class Grid
	{
		private final ItemGridView view;
		/** Whether the rows are loot, which can have the alch hint. */
		private final boolean loot;
		/** Unnamed rows ({@link OverallTotals.Entry#getSupplies()} or {@link OverallTotals.Entry#getLoot()}). */
		private List<ItemDetails.Row> rows;

		private Grid(ItemGridView view, boolean loot)
		{
			this.view = view;
			this.loot = loot;
		}

		/**
		 * Names the rows with what the model knows and shows them, loot without the items Ground Items hides;
		 * nothing is redrawn when they are unchanged.
		 */
		private void show()
		{
			view.setRows(ItemDetails.named(rows, model::itemName, model.natureRunePrice(), loot),
				loot ? model.hiddenLoot() : HiddenLoot.NONE);
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * The task overlay's rows ({@link SlayerLedgerOverlay}): a paused or not-tracking indicator, the task name, its kills
 * left (a row of its own, so the narrow overlay doesn't wrap), session kills, time left and profit.
 * Pure: the overlay passes the row settings in. Time left and profit use the sidebar's own formatting
 * ({@link LedgerHistory#formatTimeLeft(long, int, int, Long)}, {@link LedgerHistory#formatLiveProfit}), so both show
 * the same text; for time left that includes the historical estimate the history model publishes
 * ({@link HistoricalPace}).
 */
final class OverlayRows
{
	/** Shown instead of the kills left while they are not known (see {@link SessionTracker#liveTask()}). */
	static final String UNKNOWN_REMAINING = "?";
	/** Label of the indicator row shown first while the session is paused (manually or by a logout or world hop). */
	static final String PAUSED_LABEL = "Paused";
	/** Value of the paused indicator row: resuming is manual, from the sidebar. */
	static final String PAUSED_VALUE = "Resume in sidebar";
	/** Label of the warning row shown after a task kill while no session is running ({@link TrackingNudge}). */
	static final String NOT_TRACKING_LABEL = "Not tracking";
	/** Value of the not-tracking row: starting a session is manual, from the sidebar. */
	static final String NOT_TRACKING_VALUE = "Play in sidebar";

	private OverlayRows()
	{
	}

	/**
	 * What the overlay shows: the active session's task and its live values, if any are known yet; or, with no active
	 * session, only the not-tracking nudge ({@link #notTracking()}).
	 */
	static final class Data
	{
		private static final Data NOT_TRACKING = new Data(null, null);

		private final SessionTracker.LiveTask task;
		private final SessionValuation.Values values;
		private final Long historicalMillisPerKill;
		private final TaskSelection selection;

		/**
		 * @param task   the active session's task (not {@code null})
		 * @param values the same session's live values, or {@code null} when none are known yet
		 */
		Data(SessionTracker.LiveTask task, SessionValuation.Values values)
		{
			this(task, values, null);
		}

		/**
		 * @param task                    the active session's task (not {@code null})
		 * @param values                  the same session's live values, or {@code null} when none are known yet
		 * @param historicalMillisPerKill the same session's task's historical time per kill, as the sidebar uses it
		 *                                ({@link HistoricalPace}), or {@code null} when it has no history
		 */
		Data(SessionTracker.LiveTask task, SessionValuation.Values values, Long historicalMillisPerKill)
		{
			this(task, values, historicalMillisPerKill, null);
		}

		/**
		 * @param task                    the active session's task (not {@code null})
		 * @param values                  the same session's live values, or {@code null} when none are known yet
		 * @param historicalMillisPerKill the same session's task's historical time per kill, as the sidebar uses it
		 *                                ({@link HistoricalPace}), or {@code null} when it has no history
		 * @param selection               the same session's task's version and cannon use, as the sidebar's task box
		 *                                shows them ({@link SessionTracker#getCurrentTaskSelection}), or
		 *                                {@code null} for the task itself
		 */
		Data(SessionTracker.LiveTask task, SessionValuation.Values values, Long historicalMillisPerKill,
			TaskSelection selection)
		{
			this.task = task;
			this.values = values;
			this.historicalMillisPerKill = historicalMillisPerKill;
			this.selection = selection;
		}

		/** The not-tracking nudge alone: a task kill was seen while no session is running ({@link TrackingNudge}). */
		static Data notTracking()
		{
			return NOT_TRACKING;
		}

		/** The active session's task, or {@code null} for {@link #notTracking()}. */
		SessionTracker.LiveTask getTask()
		{
			return task;
		}

		/** The session's live values, or {@code null}. */
		SessionValuation.Values getValues()
		{
			return values;
		}

		/** The historical time per kill for the time-left row, or {@code null} when there is none. */
		Long getHistoricalMillisPerKill()
		{
			return historicalMillisPerKill;
		}

		/**
		 * The task's display name ({@link LedgerRecord#displayName}), or its Catacombs variant's name once the session's
		 * kills say so, with {@code (cannon)} once it fired a cannonball, as the sidebar's task box shows
		 * it ({@link TaskSelection#displayName}).
		 */
		String getTaskName()
		{
			String name = LedgerRecord.displayName(task.getMonster(), task.getCreatureId());
			return selection == null ? name : selection.displayName(name);
		}
	}

	/**
	 * The historical time per kill the sidebar uses for a session's task (and location) until the live pace takes over
	 * ({@link LedgerHistory#formatTimeLeft(long, int, int, Long)}). {@link LedgerHistoryModel} computes it from the
	 * history on the EDT and publishes it; the overlay reads it on the client thread and uses it only for the same
	 * session. Immutable.
	 */
	static final class HistoricalPace
	{
		private final String sessionId;
		private final long millisPerKill;

		HistoricalPace(String sessionId, long millisPerKill)
		{
			this.sessionId = sessionId;
			this.millisPerKill = millisPerKill;
		}

		/** The time per kill when this pace belongs to {@code task}'s session, else {@code null}. */
		Long millisPerKillFor(SessionTracker.LiveTask task)
		{
			return task != null && sessionId != null && sessionId.equals(task.getSessionId()) ? millisPerKill : null;
		}

		String getSessionId()
		{
			return sessionId;
		}

		long getMillisPerKill()
		{
			return millisPerKill;
		}

		@Override
		public boolean equals(Object other)
		{
			if (!(other instanceof HistoricalPace))
			{
				return false;
			}
			HistoricalPace that = (HistoricalPace) other;
			return millisPerKill == that.millisPerKill && Objects.equals(sessionId, that.sessionId);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(sessionId, millisPerKill);
		}
	}

	/** One overlay line: a label on the left, its value on the right, optionally drawn as a warning. */
	static final class Row
	{
		private final String label;
		private final String value;
		private final boolean warning;

		Row(String label, String value)
		{
			this(label, value, false);
		}

		Row(String label, String value, boolean warning)
		{
			this.label = label;
			this.value = value;
			this.warning = warning;
		}

		/** Whether the overlay draws this row in its warning colour. */
		boolean isWarning()
		{
			return warning;
		}

		String getLabel()
		{
			return label;
		}

		String getValue()
		{
			return value;
		}
	}

	/**
	 * The rows to show, in order, for the enabled settings; empty when {@code data} is {@code null}. While the session
	 * is paused, a warning row ({@link #PAUSED_LABEL}) comes first whatever the settings, so a paused session never
	 * looks like it is still tracking. With no active session, {@link Data#notTracking()} gives the one warning row
	 * {@link #NOT_TRACKING_LABEL}, also whatever the settings. {@code showTask} controls both the task name row and the
	 * kills-left row under it. The profit row is left out until the session has live values.
	 */
	static List<Row> rows(Data data, boolean showTask, boolean showKills, boolean showTimeLeft, boolean showProfit)
	{
		if (data == null)
		{
			return Collections.emptyList();
		}

		SessionTracker.LiveTask task = data.getTask();
		if (task == null)
		{
			return Collections.singletonList(new Row(NOT_TRACKING_LABEL, NOT_TRACKING_VALUE, true));
		}
		int remaining = task.getRemaining();
		List<Row> rows = new ArrayList<>(6);
		if (task.getState() == SessionTracker.State.PAUSED)
		{
			rows.add(new Row(PAUSED_LABEL, PAUSED_VALUE, true));
		}
		if (showTask)
		{
			rows.add(new Row("Task", data.getTaskName()));
			rows.add(new Row("Left", remaining > 0 ? Integer.toString(remaining) : UNKNOWN_REMAINING));
		}
		if (showKills)
		{
			rows.add(new Row("Kills", Integer.toString(task.getKills())));
		}
		if (showTimeLeft)
		{
			rows.add(new Row("Time left",
				LedgerHistory.formatTimeLeft(task.getActiveMillis(), task.getKills(), remaining,
					data.getHistoricalMillisPerKill())));
		}
		SessionValuation.Values values = data.getValues();
		if (showProfit && values != null)
		{
			rows.add(new Row(LedgerHistory.profitName(values.getLootPriceMode()), LedgerHistory.formatLiveProfit(values)));
		}
		return rows;
	}
}

package com.shmayvan.slayerledger;

import net.runelite.client.util.Text;

/**
 * Recognises the game messages sent when a pet drops. Pure (RuneLite's static {@link Text} only).
 *
 * <p>The texts are the three core ScreenshotPlugin (RuneLite 1.13.4, {@code PET_MESSAGES}) takes a pet screenshot on,
 * for the same chat types (game, spam, trade and friends chat notification messages). Core uses {@code contains};
 * this strips the colour tags and checks the start of the message instead, so a message only quoting the text is not
 * counted. Each text starts with "You", so another player's pet broadcast never matches.</p>
 */
final class PetMessage
{
	/** The pet follows you. */
	static final String FOLLOWED = "You have a funny feeling like you're being followed";
	/** The pet went to your inventory, because another follower was out. */
	static final String BACKPACK = "You feel something weird sneaking into your backpack";
	/** You already have this pet, so it was not given to you. */
	static final String DUPLICATE = "You have a funny feeling like you would have been followed";

	private PetMessage()
	{
	}

	/**
	 * What a chat message says about a pet drop, or {@code null} when it is not a pet message.
	 *
	 * @param petMessageType whether the message type is one core checks: GAMEMESSAGE, SPAM, TRADE or
	 *                       FRIENDSCHATNOTIFICATION
	 * @param message        the message text, possibly with tags
	 */
	static NotableDrop.Pet parse(boolean petMessageType, String message)
	{
		if (!petMessageType || message == null)
		{
			return null;
		}
		final String text = Text.removeTags(message).trim();
		if (text.startsWith(FOLLOWED) || text.startsWith(BACKPACK))
		{
			return NotableDrop.Pet.RECEIVED;
		}
		if (text.startsWith(DUPLICATE))
		{
			return NotableDrop.Pet.DUPLICATE;
		}
		return null;
	}
}

package com.shmayvan.slayerledger;

import java.util.Collection;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * Decides when to look up again the items whose GE price was unavailable when the history asked for today's prices
 *. Pure: the plugin tells it which ids came back without a price and which were found, and asks it on every
 * game tick which ids to look up again. Not thread-safe (the plugin uses it on the client thread only).
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>RuneLite's {@code ItemManager} has no "prices loaded" flag, so an item asked for before its price list was
 *     fetched comes back unavailable (see {@link ItemValuation}). Each such id is tried again every
 *     {@link #INTERVAL_TICKS} game ticks, at most {@link #MAX_ATTEMPTS} times, then dropped: it is only asked for
 *     again when the history next asks for it (the records change).</li>
 *     <li>An id that comes back unavailable from a new request (not a retry) gets {@link #MAX_ATTEMPTS} tries again,
 *     so a later request can never be cut short by an earlier one, while retries alone can never loop.</li>
 *     <li>An id whose price is found is never tried again.</li>
 * </ul>
 */
final class PriceRetry
{
	/** Game ticks (3 seconds) between tries of the unavailable prices. */
	static final int INTERVAL_TICKS = 5;
	/** Tries per unavailable price after the request that missed it (30 seconds in all). */
	static final int MAX_ATTEMPTS = 10;

	/** Tries left per id still unavailable. */
	private final Map<Integer, Integer> attemptsLeft = new TreeMap<>();
	/** Game ticks until the next try, while there are ids to try. */
	private int ticksLeft;

	/**
	 * Ids a request (not a retry) found unavailable: each is tried again {@link #MAX_ATTEMPTS} times, the first time
	 * {@link #INTERVAL_TICKS} ticks from now (or with the next try already counting down).
	 */
	void missed(Collection<Integer> ids)
	{
		for (Integer id : ids)
		{
			if (id != null)
			{
				attemptsLeft.put(id, MAX_ATTEMPTS);
			}
		}
		if (!attemptsLeft.isEmpty() && ticksLeft <= 0)
		{
			ticksLeft = INTERVAL_TICKS;
		}
	}

	/** Ids whose price is now known: they are not tried again. */
	void found(Collection<Integer> ids)
	{
		attemptsLeft.keySet().removeAll(ids);
		if (attemptsLeft.isEmpty())
		{
			ticksLeft = 0;
		}
	}

	/**
	 * One game tick: the ids to look up again now, or an empty set. Each id returned has used up one try; an id
	 * without tries left is dropped. The caller reports the ones it found through {@link #found}.
	 */
	Set<Integer> tick()
	{
		if (attemptsLeft.isEmpty() || --ticksLeft > 0)
		{
			return Collections.emptySet();
		}
		final Set<Integer> due = new TreeSet<>(attemptsLeft.keySet());
		attemptsLeft.replaceAll((id, left) -> left - 1);
		attemptsLeft.values().removeIf(left -> left <= 0);
		ticksLeft = attemptsLeft.isEmpty() ? 0 : INTERVAL_TICKS;
		return due;
	}

	/** Whether any id is waiting for another try. */
	boolean isEmpty()
	{
		return attemptsLeft.isEmpty();
	}

	/** Forgets every id (a new run of the plugin). */
	void clear()
	{
		attemptsLeft.clear();
		ticksLeft = 0;
	}
}

package com.shmayvan.slayerledger;

/**
 * Pure decision of what to do with a session when it ends or must leave memory.
 */
final class SaveDecision
{
	/** Why the session is ending (or being taken out of memory). */
	enum EndReason
	{
		/** The player pressed Stop. */
		PLAYER_STOP,
		/** The plugin ended it while logged in (task completed, changed, or cleared). */
		SYSTEM,
		/** The player logged out. The in-memory session is kept; a copy is persisted. */
		LOGOUT,
		/** The plugin was turned off or the client is closing. */
		SHUTDOWN,
		/** Another account logged in while this account's session was active. */
		ACCOUNT_SWITCH,
		/** A persisted active session could not be restored because the task no longer matches. */
		RESTORE_MISMATCH,
		/** A Keep/Discard dialog was still open when the client or plugin shut down. */
		PROMPT_UNRESOLVED
	}

	enum Action
	{
		/** Save as a completed record. */
		SAVE_COMPLETED,
		/** Ask the player whether to keep (as partial) or discard. */
		PROMPT,
		/** Save as partial silently. */
		SAVE_PARTIAL,
		/** Save as partial and show a non-modal notice offering Discard. */
		SAVE_PARTIAL_WITH_NOTICE,
		/** Do not create a record; persist the session as the account's active session to restore later. */
		PERSIST_ACTIVE,
		/** Do not save. */
		DISCARD
	}

	private SaveDecision()
	{
	}

	static Action decide(SessionTracker.Summary summary, EndReason reason, boolean confirmIncomplete)
	{
		return decide(summary.hasTask(), summary.getAccountHash(), summary.isCompleted(), reason, confirmIncomplete);
	}

	static Action decide(boolean hasTask, long accountHash, boolean completed, EndReason reason,
		boolean confirmIncomplete)
	{
		if (!hasTask || accountHash == SessionTracker.NO_ACCOUNT)
		{
			return Action.DISCARD;
		}
		if (completed)
		{
			return Action.SAVE_COMPLETED;
		}
		switch (reason)
		{
			case LOGOUT:
			case SHUTDOWN:
			case ACCOUNT_SWITCH:
				return Action.PERSIST_ACTIVE;
			case SYSTEM:
			case RESTORE_MISMATCH:
				return Action.SAVE_PARTIAL_WITH_NOTICE;
			case PROMPT_UNRESOLVED:
				return Action.SAVE_PARTIAL;
			case PLAYER_STOP:
			default:
				return confirmIncomplete ? Action.PROMPT : Action.SAVE_PARTIAL;
		}
	}
}

package com.shmayvan.slayerledger;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Value;

/**
 * The plain counters of one session (superior spawns, bank trips, deaths), shared by {@link SessionTracker} (which
 * counts them), {@link SessionTracker.Summary}, {@link SessionSnapshot} and {@link LedgerRecord}. Immutable; build one
 * with {@link #builder()} or {@link #toBuilder()}. No RuneLite dependencies.
 *
 * <p>Each counter is {@code null} when unknown: a snapshot or record from before it was counted. A builder starts every
 * counter at 0. The persisted classes keep these as flat fields of their own (their JSON must not change), so this
 * class copies them in and out ({@link #copyTo(SessionSnapshot)}, {@link #copyTo(LedgerRecord)},
 * {@link #from(SessionSnapshot)}).</p>
 *
 * <p>Adding a counter: add the field here (and to {@link #copyTo(SessionSnapshot)}, {@link #copyTo(LedgerRecord)},
 * {@link #from(SessionSnapshot)} and {@link #withUnknownAsZero()}), the same-named field to {@link SessionSnapshot} and
 * {@link LedgerRecord}, and count it in {@link SessionTracker} with {@code toBuilder()}.</p>
 */
@Value
@Builder(toBuilder = true)
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class SessionCounters
{
	/** Every counter at 0: a new session. */
	static final SessionCounters ZERO = builder().build();

	/** Superior Slayer monster spawns seen while RUNNING, or {@code null} when unknown. */
	@Builder.Default
	Integer superiorsSpawned = 0;
	/** Bank trips made while RUNNING (see {@link BankTripCounter}), or {@code null} when unknown. */
	@Builder.Default
	Integer bankTrips = 0;
	/** Deaths of the local player while RUNNING, or {@code null} when unknown. */
	@Builder.Default
	Integer deaths = 0;

	/** The counters with every unknown or negative count as 0, as a restored session counts on from them. */
	SessionCounters withUnknownAsZero()
	{
		return builder()
			.superiorsSpawned(nonNegative(superiorsSpawned))
			.bankTrips(nonNegative(bankTrips))
			.deaths(nonNegative(deaths))
			.build();
	}

	/** The snapshot's counters as stored ({@code null} where the file has none). */
	static SessionCounters from(SessionSnapshot snapshot)
	{
		return builder()
			.superiorsSpawned(snapshot.getSuperiorsSpawned())
			.bankTrips(snapshot.getBankTrips())
			.deaths(snapshot.getDeaths())
			.build();
	}

	/** Sets the snapshot's counter fields. */
	void copyTo(SessionSnapshot snapshot)
	{
		snapshot.setSuperiorsSpawned(superiorsSpawned);
		snapshot.setBankTrips(bankTrips);
		snapshot.setDeaths(deaths);
	}

	/** Sets the record's counter fields. */
	void copyTo(LedgerRecord record)
	{
		record.setSuperiorsSpawned(superiorsSpawned);
		record.setBankTrips(bankTrips);
		record.setDeaths(deaths);
	}

	private static int nonNegative(Integer n)
	{
		return n == null ? 0 : Math.max(0, n);
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import lombok.Builder;

/**
 * What a session received and used: its loot, supplies (with their doses), notable drops and boss kill counts. Shared by
 * {@link SessionTracker.Summary}, {@link SessionSnapshot} and {@link LedgerRecord}: the persisted classes keep these as
 * flat fields of their own (their JSON must not change), and this class converts to and from them in one place.
 * Immutable; build one with {@link #builder()} or {@link #toBuilder()}. No RuneLite dependencies.
 */
public final class SessionLoot
{
	/** Nothing received or used. */
	static final SessionLoot EMPTY = builder().build();

	private final ItemTally loot;
	private final ItemTally supplies;
	private final Map<Integer, Integer> supplyDoses;
	private final List<NotableDrop> notableDrops;
	private final List<BossKillCount> bossKillCounts;

	/**
	 * Copies everything it is given, so later changes to the arguments don't reach it.
	 *
	 * @param loot           NPC loot, or {@code null} for none
	 * @param supplies       supplies used, potions in doses, or {@code null} for none
	 * @param supplyDoses    doses per item for potion ids in {@code supplies} (only positive entries are kept), or
	 *                       {@code null} for none
	 * @param notableDrops   notable drops in the order they arrived, or {@code null} for none
	 * @param bossKillCounts boss kill counts in the order first seen, or {@code null} for none
	 */
	@Builder(toBuilder = true)
	private SessionLoot(ItemTally loot, ItemTally supplies, Map<Integer, Integer> supplyDoses,
		List<NotableDrop> notableDrops, List<BossKillCount> bossKillCounts)
	{
		this.loot = loot == null ? new ItemTally() : new ItemTally(loot);
		this.supplies = supplies == null ? new ItemTally() : new ItemTally(supplies);
		final Map<Integer, Integer> doses = new TreeMap<>();
		SessionTracker.putDoses(doses, supplyDoses);
		this.supplyDoses = Collections.unmodifiableMap(doses);
		this.notableDrops = Collections.unmodifiableList(NotableDrops.sanitize(notableDrops));
		this.bossKillCounts = Collections.unmodifiableList(BossKillCounts.sanitize(bossKillCounts));
	}

	/** A copy of the loot (never {@code null}). */
	public ItemTally getLoot()
	{
		return new ItemTally(loot);
	}

	/** A copy of the supplies used, potions in doses (never {@code null}). */
	public ItemTally getSupplies()
	{
		return new ItemTally(supplies);
	}

	/** A copy of the doses per item for potion ids in {@link #getSupplies()} (never {@code null}). */
	public Map<Integer, Integer> getSupplyDoses()
	{
		return new TreeMap<>(supplyDoses);
	}

	/** Notable drops in the order they arrived (never {@code null}; unmodifiable). */
	public List<NotableDrop> getNotableDrops()
	{
		return notableDrops;
	}

	/** Boss kill counts in the order first seen (never {@code null}; unmodifiable). */
	public List<BossKillCount> getBossKillCounts()
	{
		return bossKillCounts;
	}

	/** A copy with extra loot (may be {@code null}) merged in and extra notable drops (likewise) added. */
	SessionLoot withAddedLoot(ItemTally extra, List<NotableDrop> extraNotableDrops)
	{
		final ItemTally merged = new ItemTally(loot);
		if (extra != null)
		{
			merged.merge(extra);
		}
		return toBuilder().loot(merged).notableDrops(NotableDrops.add(notableDrops, extraNotableDrops)).build();
	}

	/** A copy with one more boss kill count message counted ({@link BossKillCounts#add}). */
	SessionLoot withBossKillCount(String boss, int kc)
	{
		return toBuilder().bossKillCounts(BossKillCounts.add(bossKillCounts, boss, kc)).build();
	}

	/** The snapshot's loot as stored. */
	static SessionLoot from(SessionSnapshot snapshot)
	{
		return builder()
			.loot(ItemTally.fromMap(snapshot.getLoot()))
			.supplies(ItemTally.fromMap(snapshot.getSupplies()))
			.supplyDoses(snapshot.getSupplyDoses())
			.notableDrops(snapshot.getNotableDrops())
			.bossKillCounts(snapshot.getBossKillCounts())
			.build();
	}

	/** Sets the snapshot's loot, supplies, doses, notable drop and boss kill count fields. */
	void copyTo(SessionSnapshot snapshot)
	{
		snapshot.setLoot(loot.toMap());
		snapshot.setSupplies(supplies.toMap());
		snapshot.setSupplyDoses(dosesFor(snapshot.getSupplies(), supplyDoses));
		snapshot.setNotableDrops(notableDropsOrNull());
		snapshot.setBossKillCounts(bossKillCountsOrNull());
	}

	/** Sets the record's loot, supplies, doses, notable drop and boss kill count fields. */
	void copyTo(LedgerRecord record)
	{
		record.setLoot(loot.toMap());
		record.setSupplies(supplies.toMap());
		record.setSupplyDoses(dosesFor(record.getSupplies(), supplyDoses));
		record.setNotableDrops(notableDropsOrNull());
		record.setBossKillCounts(bossKillCountsOrNull());
	}

	/** The notable drops as stored, or {@code null} when there are none. */
	private List<NotableDrop> notableDropsOrNull()
	{
		return notableDrops.isEmpty() ? null : new ArrayList<>(notableDrops);
	}

	/** The boss kill counts as stored, or {@code null} when there are none. */
	private List<BossKillCount> bossKillCountsOrNull()
	{
		return bossKillCounts.isEmpty() ? null : new ArrayList<>(bossKillCounts);
	}

	/** The dose entries for ids present in {@code supplies}, or {@code null} when there are none. */
	static Map<Integer, Integer> dosesFor(Map<Integer, Long> supplies, Map<Integer, Integer> doses)
	{
		if (supplies == null || doses == null)
		{
			return null;
		}
		Map<Integer, Integer> result = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : doses.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null && e.getValue() > 0 && supplies.containsKey(e.getKey()))
			{
				result.put(e.getKey(), e.getValue());
			}
		}
		return result.isEmpty() ? null : result;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import lombok.Data;

/**
 * A persisted in-progress session (the account's "active session" file). Written on logout, client exit, plugin
 * shutdown and account switch, and restored as PAUSED on the next login if the task still matches. Serialized with
 * Gson; no RuneLite dependencies.
 */
@Data
public class SessionSnapshot
{
	/**
	 * Version 2 adds {@link #loot}. Raised from 1 so an older build, which would drop the loot when it rewrites the
	 * file, refuses to overwrite or restore it instead. {@link #supplies} and {@link #supplyDoses} were added to
	 * version 2 later as optional fields, before any build wrote supplies. {@link #superiorsSpawned} and
	 * {@link #bankTrips} were added the same way; a file without them restores with both counts at 0. {@link #note} was
	 * added the same way; a file without it has no note. {@link #deaths} was added the same way; a file without it
	 * restores with 0 deaths. {@link #slayerMaster}, {@link #slayerArea} and {@link #taskLocation} were added the same
	 * way; a file without them restores with the assignment read from the game, since the task must match. Points and
	 * streak are not kept: a snapshot is never of a completed task. {@link #notableDrops} was added the same way; a file
	 * without it restores with none. {@link #bossKillCounts} was added the same way; a file without it restores with
	 * none. {@link #xpGained} was added the same way; a file without it restores with no XP, and XP counts from the
	 * restore. {@link #locationKills} was added the same way; a file without it restores with none, and kills are
	 * tallied per region from the restore. {@link #npcKills} was added the same way; a file without it restores
	 * with none, and kills are tallied per NPC name from the restore.
	 */
	public static final int CURRENT_SCHEMA_VERSION = 2;

	private int schemaVersion = CURRENT_SCHEMA_VERSION;
	/** Session id; becomes the ledger record id so a session can never become two records. */
	private String sessionId;
	private long accountHash;
	private String monster;
	/** Creature key, see {@link SessionTracker#creatureKey(int, int)}. */
	private int creatureId = SessionTracker.NO_CREATURE;
	private int initialAmount;
	/** Assigned task size, or {@code null} when unknown. */
	private Integer originalAmount;
	private int kills;
	private long activeMillis;
	private long startedAt;
	/** When the snapshot was taken; used as the end time if it later becomes a partial record. */
	private long savedAt;
	/** Remaining task count when the snapshot was taken. */
	private int remaining;
	/** Task-completion counters when the snapshot was taken, or {@code null} if unknown. */
	private int[] completionCounters;
	/** Loot tally so far (item id to quantity), or {@code null} when none (and in version 1 files). */
	private Map<Integer, Long> loot;
	/** Supplies used so far (item id to quantity, potions in doses), or {@code null} when none. */
	private Map<Integer, Long> supplies;
	/** Doses per item for potion ids in {@link #supplies}, or {@code null} when none. */
	private Map<Integer, Integer> supplyDoses;
	/** Superior spawns counted so far, or {@code null} in files from before they were counted. */
	private Integer superiorsSpawned;
	/** Bank trips counted so far, or {@code null} in files from before they were counted. */
	private Integer bankTrips;
	/** Deaths of the local player counted so far, or {@code null} in files from before they were counted. */
	private Integer deaths;
	/** The player's note on the session, or {@code null} when none (and in files from before notes existed). */
	private String note;
	/** SLAYER_MASTER value of the session task, or {@code null} when unknown (and in older files). */
	private Integer slayerMaster;
	/** SLAYER_AREA value of the session task, or {@code null} when none or unknown. */
	private Integer slayerArea;
	/** Name of {@link #slayerArea}, or {@code null}. */
	private String taskLocation;
	/** Notable drops so far, in the order they arrived, or {@code null} when none (and in older files). */
	private List<NotableDrop> notableDrops;
	/** Boss kill counts so far, in the order first seen, or {@code null} when none (and in older files). */
	private List<BossKillCount> bossKillCounts;
	/**
	 * XP gained so far per skill (keyed as {@link SkillXp} keys them, e.g. {@code "SLAYER"}), or {@code null} in files
	 * from before XP was tracked. Empty when the session has gained none yet.
	 */
	private Map<String, Long> xpGained;
	/**
	 * Counted kills per map region so far, in the order first seen ({@link LocationTally}), or {@code null} when none
	 * (and in older files).
	 */
	private List<LocationKills> locationKills;
	/**
	 * Kills per NPC name so far, in the order first seen ({@link NpcKillTally}), or {@code null} when none (and in
	 * older files).
	 */
	private List<NpcKills> npcKills;

	static SessionSnapshot fromSummary(SessionTracker.Summary summary, int[] completionCounters, long savedAt)
	{
		SessionSnapshot s = new SessionSnapshot();
		s.setSessionId(summary.getSessionId());
		s.setAccountHash(summary.getAccountHash());
		s.setMonster(summary.getMonster());
		s.setCreatureId(summary.getCreatureId());
		s.setInitialAmount(summary.getInitialAmount());
		s.setOriginalAmount(summary.getOriginalAmount() == SessionTracker.UNKNOWN_AMOUNT ? null : summary.getOriginalAmount());
		s.setKills(summary.getKills());
		s.setActiveMillis(summary.getActiveMillis());
		s.setStartedAt(summary.getStartedAt());
		s.setSavedAt(savedAt);
		s.setRemaining(summary.getResumeRemaining());
		s.setCompletionCounters(completionCounters == null ? null : Arrays.copyOf(completionCounters, completionCounters.length));
		summary.getSessionLoot().copyTo(s);
		summary.getCounters().copyTo(s);
		s.setNote(summary.getNote());
		final TaskContext context = summary.getContext();
		s.setSlayerMaster(context.getMaster());
		s.setSlayerArea(context.getArea());
		s.setTaskLocation(context.getLocation());
		s.setXpGained(LedgerRecord.xpGainedFor(summary));
		s.setLocationKills(summary.getLocationKills().isEmpty() ? null : new ArrayList<>(summary.getLocationKills()));
		s.setNpcKills(summary.getNpcKills().isEmpty() ? null : new ArrayList<>(summary.getNpcKills()));
		return s;
	}

	/**
	 * The snapshot as an ended, incomplete session summary (used when it cannot be restored).
	 */
	SessionTracker.Summary toSummary()
	{
		return SessionTracker.Summary.builder()
			.sessionId(sessionId)
			.accountHash(accountHash)
			.monster(monster)
			.creatureId(creatureId)
			.hasTask(true)
			.initialAmount(initialAmount)
			.originalAmount(originalAmount == null ? SessionTracker.UNKNOWN_AMOUNT : originalAmount)
			.kills(kills)
			.activeMillis(activeMillis)
			.startedAt(startedAt)
			.endedAt(savedAt)
			.completed(false)
			.resumeRemaining(remaining)
			.sessionLoot(SessionLoot.from(this))
			.counters(SessionCounters.from(this))
			.note(TaskNote.normalize(note))
			.context(TaskContext.of(slayerMaster, slayerArea, taskLocation, null, null))
			.xpGained(xpGained)
			.locationKills(locationKills)
			.npcKills(npcKills)
			.build();
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.UUID;
import java.util.function.LongSupplier;

/**
 * Tracks a single Slayer task session. This class has no RuneLite dependencies so it can be unit tested with a
 * controllable clock. All public methods are synchronized because the plugin calls it from both the client thread
 * (task observations, auto-pause, account changes) and the Swing event dispatch thread (Play / Pause / Stop).
 *
 * <p>States: {@code IDLE -> RUNNING <-> PAUSED}, {@code RUNNING|PAUSED -> STOPPED}, and {@link #restore} takes
 * {@code IDLE} to {@code PAUSED}. Invalid transitions are no-ops and return {@code false}. The plugin ends sessions
 * through {@link #stopAndReset}, so it never leaves the tracker {@code STOPPED}.
 * {@link #reset()} returns a stopped tracker to {@code IDLE} so a new session can begin.</p>
 *
 * <p>A running session that completes can be held back from saving for {@link #COMPLETION_LOOT_GRACE_TICKS} game
 * ticks (see {@link #holdCompletion()}) so the final kill's loot, which may arrive after the task count update, is
 * still recorded. The held session is already stopped (its kills and active time are final) and the tracker is back to
 * {@code IDLE}; it is outside the state machine, so it is never reported as active.</p>
 */
public class SessionTracker
{
	public enum State
	{
		IDLE,
		RUNNING,
		PAUSED,
		STOPPED
	}

	/**
	 * Outcome of {@link #restore}.
	 */
	public enum RestoreResult
	{
		/** The snapshot was restored as a PAUSED session. */
		RESTORED,
		/** The current task does not match the snapshot; it should be saved as partial instead. */
		MISMATCH,
		/** Restore is not possible right now (a session is active or no task has been observed yet). */
		REFUSED
	}

	/**
	 * Outcome of {@link #observe}, telling the caller whether the session needs attention.
	 */
	public enum ObserveResult
	{
		/** Nothing the caller needs to act on. */
		NONE,
		/** The session's task was completed (the session should be stopped and saved). */
		COMPLETED,
		/** The remaining count dropped to zero without a completion signal (for example, a cancelled task). */
		TASK_CLEARED,
		/** A different task was observed while a session was active (the session should be stopped). */
		TASK_CHANGED
	}

	/** Value used for "no creature id known". */
	public static final int NO_CREATURE = -1;
	/** Value used for "no amount known". */
	public static final int UNKNOWN_AMOUNT = -1;
	/**
	 * A drop to zero followed by the same task within this many zero observations (ticks) is treated as a transient
	 * glitch and the session resumes. Longer gaps are treated as a cancelled-and-reassigned task, unless the assigned
	 * size is unchanged and the remaining count did not go up.
	 */
	public static final int MAX_TRANSIENT_ZERO_OBSERVATIONS = 3;

	/** Maximum ticks a post-login restore check waits for a non-zero task count before running anyway. */
	public static final int RESTORE_SYNC_MAX_TICKS = 10;

	/** SLAYER_TARGET value for boss tasks, from [proc,helper_slayer_current_assignment] (as used by core SlayerPlugin). */
	public static final int BOSS_TASK_TARGET = 98;

	/**
	 * Creature key identifying a task: the SLAYER_TARGET value, or for boss tasks {@code -2 - bossId} so that each
	 * boss is a distinct task even when name lookups fail. Boss keys are always negative and never equal
	 * {@link #NO_CREATURE}.
	 */
	public static int creatureKey(int slayerTarget, int bossId)
	{
		return slayerTarget == BOSS_TASK_TARGET ? -2 - Math.max(0, bossId) : slayerTarget;
	}

	/** Value used for "no account". Matches {@code Client#getAccountHash()} when logged out. */
	public static final long NO_ACCOUNT = -1L;

	/**
	 * Game ticks a completed running session waits for late loot before it is saved (see {@link #holdCompletion()}).
	 * The final kill's loot can arrive on the completion tick after the task count update, or a tick or two later; the
	 * plugin counts the window from the tick after completion, so loot through completion tick + 2 is kept.
	 */
	public static final int COMPLETION_LOOT_GRACE_TICKS = 2;

	/** Read under the tracker's lock; only {@link #setClock} replaces it. */
	private LongSupplier clock;

	private State state = State.IDLE;

	// Latest observed task, kept regardless of session state.
	private boolean taskObserved;
	private String currentMonster;
	private int currentCreatureId = NO_CREATURE;
	private int currentRemaining;
	private int currentOriginalAmount = UNKNOWN_AMOUNT;
	/** Who assigned the latest observed task (master and area), or {@link TaskContext#NONE}. */
	private TaskContext currentContext = TaskContext.NONE;

	// Session task.
	private String sessionId;
	private boolean restoredPending;
	private long sessionAccountHash = NO_ACCOUNT;
	private String sessionMonster;
	private int sessionCreatureId = NO_CREATURE;
	private boolean hasSessionTask;
	private int initialAmount;
	private int originalAmount = UNKNOWN_AMOUNT;
	private int baseline;
	private int kills;
	// Kills from a final drop to zero that is awaiting a completion signal.
	private int pendingFinalKills;
	private boolean awaitingCompletion;
	// Remaining count just before the drop to zero, and how many zero observations have been seen since.
	private int preZeroBaseline;
	private int zeroObservations;
	private boolean completed;
	/** NPC loot received while RUNNING. */
	private final ItemTally loot = new ItemTally();
	/** Supplies used while RUNNING; potions in doses (see {@link #supplyDoses}). */
	private final ItemTally supplies = new ItemTally();
	/** Doses per item for potion ids in {@link #supplies}. */
	private final Map<Integer, Integer> supplyDoses = new TreeMap<>();
	/** Superior spawns, bank trips and deaths counted while RUNNING; never {@code null} and never unknown here. */
	private SessionCounters counters = SessionCounters.ZERO;
	/** Notable drops while RUNNING, in the order they arrived; bounded by {@link NotableDrops#add}. */
	private List<NotableDrop> notableDrops = new ArrayList<>();
	/** Boss kill counts while RUNNING, in the order first seen; bounded by {@link BossKillCounts#add}. */
	private List<BossKillCount> bossKillCounts = new ArrayList<>();
	/** Counted kills per map region, in the order first seen (see {@link LocationTally}); counted like {@link #kills}. */
	private List<LocationKills> locationKills = new ArrayList<>();
	/**
	 * Deaths of NPCs the player damaged while RUNNING, per NPC name in the order first seen ({@link NpcKillTally}); they decide whether the task was done on its Catacombs variant ({@link CatacombsVariants}).
	 */
	private List<NpcKills> npcKills = new ArrayList<>();
	/** Region the player was in when {@link #pendingFinalKills} dropped, so they are tallied there when confirmed. */
	private int pendingFinalRegion = LocationTally.NO_REGION;
	/**
	 * Region of the latest counted kill whose task has no assigned area name, until {@link #takeRegionToName()} takes
	 * it; {@link LocationTally#NO_REGION} when none. Not session data: it outlives the session that counted the kill.
	 */
	private int regionToName = LocationTally.NO_REGION;
	/**
	 * Region the player was in at the latest {@link #observe}, or {@link LocationTally#NO_REGION} when unknown or the
	 * task was cleared. Not session data: the panel uses it for the current task's location (Part B).
	 */
	private int currentRegion = LocationTally.NO_REGION;
	/** The player's note on the session ({@link TaskNote#normalize normalized}), or {@code null}. */
	private String note;
	/** XP gained per skill while RUNNING (see {@link #observeXp}), keyed as {@link SkillXp} keys them. */
	private final Map<String, Long> xpGained = new TreeMap<>();
	/**
	 * The latest XP reading of every skill ({@link #observeXp}), or {@code null} after {@link #resetXpBaseline()} or an
	 * unsynced reading. Kept whatever the state, so it is always the baseline for the next reading: XP gained while
	 * idle, paused, before Play or in a held completion's grace window moves it and is never counted later.
	 */
	private Map<String, Integer> xpReading;
	/**
	 * The session task's assignment, and once the task is completed the points earned and streak (see
	 * {@link #setCompletionRewards}), or {@link TaskContext#NONE}.
	 */
	private TaskContext sessionContext = TaskContext.NONE;

	private long accumulatedMillis;
	private long runningSince;
	private long startedAt;
	private long endedAt;

	/** Completed session held back from saving for late loot, or {@code null}. Independent of {@link #state}. */
	private Summary pendingCompletion;
	/** Game ticks left before {@link #pendingCompletion} is released by {@link #tickCompletion()}. */
	private int pendingCompletionTicks;
	/**
	 * Creature keys of tasks a session took (adopted or restored) since the last {@link #takeSessionTaskKeys()}, so a
	 * session started and ended between two calls is still reported.
	 */
	private final Set<Integer> takenTaskKeys = new HashSet<>();

	public SessionTracker(LongSupplier clock)
	{
		this.clock = Objects.requireNonNull(clock);
	}

	/** Test seam: reads the time from {@code clock} from now on (a harness-run plugin's tracker reads the system clock). */
	synchronized void setClock(LongSupplier clock)
	{
		this.clock = Objects.requireNonNull(clock);
	}

	/**
	 * Whether {@link #play(long)} would succeed for the given account.
	 */
	public synchronized boolean canPlay(long accountHash)
	{
		if (accountHash == NO_ACCOUNT || !taskObserved)
		{
			return false;
		}
		return state == State.IDLE || (state == State.PAUSED && accountHash == sessionAccountHash);
	}

	/**
	 * Starts a session (from IDLE) or resumes it (from PAUSED) for the given account. Refused until the task has
	 * been observed for the current login (see {@link #clearCurrentTask()}), and resuming requires the same account
	 * that started the session.
	 */
	public synchronized boolean play(long accountHash)
	{
		if (!canPlay(accountHash))
		{
			return false;
		}
		long now = clock.getAsLong();
		restoredPending = false;
		if (state == State.IDLE)
		{
			sessionId = UUID.randomUUID().toString();
			sessionAccountHash = accountHash;
			startedAt = now;
			runningSince = now;
			state = State.RUNNING;
			if (currentRemaining > 0)
			{
				adoptCurrentTask();
			}
			return true;
		}
		runningSince = now;
		state = State.RUNNING;
		return true;
	}

	/**
	 * Pauses a running session.
	 */
	public synchronized boolean pause()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		accumulate(clock.getAsLong());
		state = State.PAUSED;
		return true;
	}

	/**
	 * Pauses because of logout or world hop. Resuming is always manual.
	 */
	public synchronized boolean autoPause()
	{
		return pause();
	}

	/**
	 * Forgets the latest observed task (for example on logout or account change) so stale data is not shown or
	 * adopted. Play is refused until the next {@link #observe}. The active session, if any, is unaffected.
	 */
	public synchronized void clearCurrentTask()
	{
		taskObserved = false;
		currentMonster = null;
		currentCreatureId = NO_CREATURE;
		currentRemaining = 0;
		currentOriginalAmount = UNKNOWN_AMOUNT;
		currentContext = TaskContext.NONE;
		currentRegion = LocationTally.NO_REGION;
	}

	/**
	 * Stops a running or paused session. Use {@link #summary()} to read the result, then {@link #reset()}.
	 */
	public synchronized boolean stop()
	{
		if (state != State.RUNNING && state != State.PAUSED)
		{
			return false;
		}
		long now = clock.getAsLong();
		if (state == State.RUNNING)
		{
			accumulate(now);
		}
		endedAt = now;
		state = State.STOPPED;
		return true;
	}

	/**
	 * Returns a stopped tracker to IDLE. The latest observed task is kept so it can be shown and adopted by the
	 * next session.
	 */
	public synchronized boolean reset()
	{
		if (state != State.STOPPED)
		{
			return false;
		}
		state = State.IDLE;
		clearSession();
		return true;
	}

	/**
	 * Atomically stops an active session, captures its summary and returns to IDLE.
	 *
	 * @return the stopped session's summary, or {@code null} if no session was running or paused
	 */
	public synchronized Summary stopAndReset()
	{
		if (!stop())
		{
			return null;
		}
		Summary summary = summary();
		reset();
		return summary;
	}

	/**
	 * Atomically stops and resets the active session only if it belongs to an account other than the given one.
	 *
	 * @return the stopped session's summary, or {@code null} if nothing was stopped
	 */
	public synchronized Summary stopAndResetIfOtherAccount(long accountHash)
	{
		if ((state != State.RUNNING && state != State.PAUSED) || sessionAccountHash == accountHash)
		{
			return null;
		}
		return stopAndReset();
	}

	/**
	 * Whether a snapshot matches the latest observed task closely enough to be restored: same creature key, a task
	 * is active, the remaining count has not gone up, the assigned size has not changed (when both are known), and
	 * no task-completion counter has changed since the snapshot (when both are known). See
	 * {@link #counterChanged(int, int)}.
	 */
	public synchronized boolean matchesCurrentTask(SessionSnapshot snapshot, int[] currentCompletionCounters)
	{
		if (!taskObserved || currentRemaining <= 0 || currentCreatureId != snapshot.getCreatureId()
			|| currentRemaining > snapshot.getRemaining())
		{
			return false;
		}
		Integer savedOriginal = snapshot.getOriginalAmount();
		if (savedOriginal != null && currentOriginalAmount != UNKNOWN_AMOUNT && savedOriginal != currentOriginalAmount)
		{
			return false;
		}
		int[] saved = snapshot.getCompletionCounters();
		if (saved != null && currentCompletionCounters != null && saved.length == currentCompletionCounters.length)
		{
			for (int i = 0; i < saved.length; i++)
			{
				if (counterChanged(saved[i], currentCompletionCounters[i]))
				{
					return false;
				}
			}
		}
		return true;
	}

	/**
	 * For a session kept in memory across a logout: whether it still matches the task observed after the next login,
	 * using the same checks as {@link #restore}. Returns {@code true} (nothing to do) if no session is active or the
	 * active session is not the one in the snapshot.
	 */
	public synchronized boolean activeSessionStillMatches(SessionSnapshot logoutSnapshot, int[] currentCompletionCounters)
	{
		if ((state != State.RUNNING && state != State.PAUSED) || logoutSnapshot == null
			|| !Objects.equals(sessionId, logoutSnapshot.getSessionId()))
		{
			return true;
		}
		return matchesCurrentTask(logoutSnapshot, currentCompletionCounters);
	}

	/**
	 * Whether one task-completion counter shows a change since a snapshot. An increase means a task was completed;
	 * a decrease to a non-zero value means the streak changed (for example a Turael reset or cancellation). A counter
	 * that reads zero now but was non-zero in the snapshot is treated as not yet synced (unknown), not a decrease.
	 */
	static boolean counterChanged(int saved, int current)
	{
		if (current == 0 && saved != 0)
		{
			return false;
		}
		return current != saved;
	}

	/**
	 * Whether a post-login restore / re-login check should wait another tick: the task count may not be synced yet
	 * while it reads zero, so the check is deferred until it is positive, for at most
	 * {@link #RESTORE_SYNC_MAX_TICKS} ticks (after which it runs anyway and a zero count is a mismatch).
	 *
	 * @param remaining    the task count read this tick
	 * @param ticksWaited  how many ticks the check has already been deferred
	 */
	public static boolean shouldDeferRestoreCheck(int remaining, int ticksWaited)
	{
		return remaining <= 0 && ticksWaited < RESTORE_SYNC_MAX_TICKS;
	}

	/**
	 * Restores a persisted session as PAUSED if it matches the latest observed task. Kills and active time are kept;
	 * the kill baseline is the current remaining count, so kills made while untracked are not counted.
	 */
	public synchronized RestoreResult restore(SessionSnapshot snapshot, int[] currentCompletionCounters)
	{
		if (state != State.IDLE || !taskObserved)
		{
			return RestoreResult.REFUSED;
		}
		if (snapshot.getAccountHash() == NO_ACCOUNT || !matchesCurrentTask(snapshot, currentCompletionCounters))
		{
			return RestoreResult.MISMATCH;
		}
		clearSession();
		state = State.PAUSED;
		restoredPending = true;
		sessionId = snapshot.getSessionId() != null ? snapshot.getSessionId() : UUID.randomUUID().toString();
		sessionAccountHash = snapshot.getAccountHash();
		sessionMonster = snapshot.getMonster() != null ? snapshot.getMonster() : currentMonster;
		sessionCreatureId = snapshot.getCreatureId();
		hasSessionTask = true;
		takenTaskKeys.add(sessionCreatureId);
		initialAmount = snapshot.getInitialAmount();
		originalAmount = snapshot.getOriginalAmount() != null ? snapshot.getOriginalAmount() : currentOriginalAmount;
		baseline = currentRemaining;
		kills = Math.max(0, snapshot.getKills());
		loot.merge(ItemTally.fromMap(snapshot.getLoot()));
		supplies.merge(ItemTally.fromMap(snapshot.getSupplies()));
		putDoses(supplyDoses, snapshot.getSupplyDoses());
		// A snapshot from before these were counted has none; counting starts from the restore.
		counters = SessionCounters.from(snapshot).withUnknownAsZero();
		// A snapshot from before notable drops were kept has none.
		notableDrops = NotableDrops.sanitize(snapshot.getNotableDrops());
		// Likewise for boss kill counts.
		bossKillCounts = BossKillCounts.sanitize(snapshot.getBossKillCounts());
		// Likewise for the kills per region; a snapshot without them tallies from the restore.
		locationKills = LocationTally.sanitize(snapshot.getLocationKills());
		// Likewise for the kills per NPC name; a snapshot without them tallies from the restore.
		npcKills = NpcKillTally.sanitize(snapshot.getNpcKills());
		note = TaskNote.normalize(snapshot.getNote());
		// A snapshot from before XP was tracked has none; counting starts from the restore.
		SkillXp.add(xpGained, snapshot.getXpGained());
		// The snapshot matched the current task, so the current reading fills what an older snapshot lacks.
		sessionContext = TaskContext.of(snapshot.getSlayerMaster(), snapshot.getSlayerArea(),
			snapshot.getTaskLocation(), null, null).fillAssignment(currentContext);
		accumulatedMillis = Math.max(0, snapshot.getActiveMillis());
		startedAt = snapshot.getStartedAt();
		return RestoreResult.RESTORED;
	}

	/**
	 * Stops a RUNNING session whose task was just completed and holds it back from saving for
	 * {@link #COMPLETION_LOOT_GRACE_TICKS} game ticks, so late loot from the final kill is still recorded. The kills,
	 * active time and end time are frozen now and the tracker returns to {@code IDLE} at once.
	 *
	 * <p>Refused (returns {@code false}, nothing changes) unless the session is RUNNING and completed, or if another
	 * completed session is already held. A completion while PAUSED is not held: no loot is counted while paused, so the
	 * caller saves it immediately as before.</p>
	 *
	 * @return whether the session is now held; if {@code false} the caller should end and save it as usual
	 */
	public synchronized boolean holdCompletion()
	{
		if (state != State.RUNNING || !completed || pendingCompletion != null)
		{
			return false;
		}
		pendingCompletion = stopAndReset();
		pendingCompletionTicks = COMPLETION_LOOT_GRACE_TICKS;
		return true;
	}

	/**
	 * Counts down the held completed session by one game tick. Call once per game tick.
	 *
	 * @return the held session's final summary once its grace window has ended (it is no longer held), otherwise
	 *         {@code null}
	 */
	public synchronized Summary tickCompletion()
	{
		if (pendingCompletion == null)
		{
			return null;
		}
		pendingCompletionTicks--;
		return pendingCompletionTicks > 0 ? null : takePendingCompletion();
	}

	/**
	 * Releases the held completed session at once (for example on logout, account change, Stop or shutdown). Each
	 * held session is returned exactly once, by this method or {@link #tickCompletion()}.
	 *
	 * @return the held session's summary (including loot received so far), or {@code null} if none is held
	 */
	public synchronized Summary takePendingCompletion()
	{
		final Summary summary = pendingCompletion;
		pendingCompletion = null;
		pendingCompletionTicks = 0;
		return summary;
	}

	/** Whether a completed session is being held for late loot. */
	public synchronized boolean hasPendingCompletion()
	{
		return pendingCompletion != null;
	}

	/**
	 * Creature keys of the tasks a session held since the previous call: the active (or just stopped) session's task,
	 * a completed session held for late loot, and any task a session took since then, even if that session has ended
	 * already. {@link AssignmentWatch} uses them, once per settled tick, to tell played assignments from ones that
	 * ended without a session. Decided in one call, so a Play click can't fall between two reads.
	 */
	public synchronized Set<Integer> takeSessionTaskKeys()
	{
		final Set<Integer> keys = new HashSet<>(takenTaskKeys);
		takenTaskKeys.clear();
		if (state != State.IDLE && hasSessionTask)
		{
			keys.add(sessionCreatureId);
		}
		if (pendingCompletion != null && pendingCompletion.hasTask())
		{
			keys.add(pendingCompletion.getCreatureId());
		}
		return keys;
	}

	/**
	 * Adds NPC loot to the session, only while it is RUNNING. Loot received while IDLE, PAUSED or STOPPED is not
	 * attributed to any session. While a completed session is held for late loot (see {@link #holdCompletion()}), all
	 * loot goes to that session instead, even if a new session has been started meanwhile.
	 *
	 * <p>Loot is deliberately not filtered by the task monster: any NPC loot received while the session runs counts,
	 * because drop sources do not map reliably to Slayer task categories (superiors, variants, bosses and wildcards
	 * share or rename NPCs) and the player controls the session with Play / Pause.</p>
	 *
	 * @return whether the loot was recorded
	 */
	public synchronized boolean addLoot(ItemTally items)
	{
		return addLoot(items, null);
	}

	/**
	 * Adds NPC loot and its notable stacks (see {@link NotableDrops}) to the session, by the rules of
	 * {@link #addLoot(ItemTally)}: both go to the same session, or neither is recorded.
	 *
	 * @param items        the loot
	 * @param notableDrops the loot's notable stacks, or {@code null} when none
	 * @return whether the loot was recorded
	 */
	public synchronized boolean addLoot(ItemTally items, List<NotableDrop> notableDrops)
	{
		if (items == null || items.isEmpty())
		{
			return false;
		}
		if (pendingCompletion != null)
		{
			pendingCompletion = pendingCompletion.withAddedLoot(items, notableDrops);
			return true;
		}
		if (state != State.RUNNING)
		{
			return false;
		}
		loot.merge(items);
		this.notableDrops = NotableDrops.add(this.notableDrops, notableDrops);
		return true;
	}

	/**
	 * Whether loot would be recorded now ({@link #addLoot(ItemTally)}): the session is RUNNING, or a completed session
	 * is held for late loot. Lets the caller skip pricing loot that would not be recorded.
	 */
	public synchronized boolean isRecordingLoot()
	{
		return pendingCompletion != null || state == State.RUNNING;
	}

	/**
	 * Adds a pet drop ({@link PetMessage}) to the session's notable drops, by the same rules as loot
	 * ({@link #addLoot(ItemTally)}): while RUNNING, or to a completed session held for late loot, since the pet may
	 * come from the final kill.
	 *
	 * @return whether it was recorded
	 */
	public synchronized boolean addPet(NotableDrop pet)
	{
		if (pet == null)
		{
			return false;
		}
		final List<NotableDrop> added = Collections.singletonList(pet);
		if (pendingCompletion != null)
		{
			pendingCompletion = pendingCompletion.withAddedLoot(null, added);
			return true;
		}
		if (state != State.RUNNING)
		{
			return false;
		}
		notableDrops = NotableDrops.add(notableDrops, added);
		return true;
	}

	/**
	 * Counts a boss kill count message ({@link KillCountMessage}) for the session, by the same rules as loot
	 * ({@link #addLoot(ItemTally)}): while RUNNING, or for a completed session held for late loot, since the message
	 * may come with the final kill. Whether the boss belongs to the task, and the counts, follow
	 * {@link BossKillCounts}; all of it is decided here in one step.
	 *
	 * @param boss the boss name the message gives
	 * @param kc   the count the message gives
	 * @return whether it was counted for a session (its count may still have been a repeat)
	 */
	public synchronized boolean addBossKillCount(String boss, int kc)
	{
		if (pendingCompletion != null)
		{
			if (!BossKillCounts.appliesTo(pendingCompletion.getMonster(), pendingCompletion.getCreatureId(), boss))
			{
				return false;
			}
			pendingCompletion = pendingCompletion.withBossKillCount(boss, kc);
			return true;
		}
		if (state != State.RUNNING || !BossKillCounts.appliesTo(sessionMonster, sessionCreatureId, boss))
		{
			return false;
		}
		bossKillCounts = BossKillCounts.add(bossKillCounts, boss, kc);
		return true;
	}

	/**
	 * Adds supplies used to the session, only while it is RUNNING. Unlike loot, supplies are never added to a completed
	 * session held for late loot (see {@link #holdCompletion()}): it stopped running when the task completed.
	 *
	 * @param used     items used; potions in doses
	 * @param returned ammo or cannonballs that came back (picked up, or unloaded from the cannon); each reduces that
	 *                 item's used quantity, never below zero
	 * @param doses    doses per item for the potion ids in {@code used}, or {@code null}
	 * @return whether the session changed
	 */
	public synchronized boolean addSupplies(ItemTally used, ItemTally returned, Map<Integer, Integer> doses)
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		boolean changed = false;
		if (used != null && !used.isEmpty())
		{
			supplies.merge(used);
			putDoses(supplyDoses, doses);
			changed = true;
		}
		if (returned != null)
		{
			for (int id : returned.itemIds())
			{
				changed |= supplies.subtract(id, returned.get(id)) > 0;
			}
		}
		return changed;
	}

	/**
	 * Counts a superior Slayer monster spawn, only while the session is RUNNING. Unlike loot, a spawn is never added to
	 * a completed session held for late loot (see {@link #holdCompletion()}): it stopped running when the task
	 * completed, and a superior that appears after that belongs to no task.
	 *
	 * @return whether it was counted
	 */
	public synchronized boolean addSuperiorSpawn()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		counters = counters.toBuilder().superiorsSpawned(saturatedIncrement(counters.getSuperiorsSpawned())).build();
		return true;
	}

	/**
	 * Counts a bank trip, only while the session is RUNNING (never for a held completed session). Which bank openings
	 * are trips is decided by {@link BankTripCounter}.
	 *
	 * @return whether it was counted
	 */
	public synchronized boolean addBankTrip()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		counters = counters.toBuilder().bankTrips(saturatedIncrement(counters.getBankTrips())).build();
		return true;
	}

	/**
	 * Counts a death of the local player, only while the session is RUNNING (never for a held completed session, like
	 * {@link #addSuperiorSpawn()}). Deaths are only counted; what a death costs is not tracked.
	 *
	 * @return whether it was counted
	 */
	public synchronized boolean addDeath()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		counters = counters.toBuilder().deaths(saturatedIncrement(counters.getDeaths())).build();
		return true;
	}

	/**
	 * Counts the death of an NPC the player damaged under its name ({@link CatacombsVariants#tallyName}), only while
	 * the session is RUNNING (never for a held completed session, like {@link #addDeath()}). The kill count itself
	 * still comes from the task count; this tally only tells a Catacombs variant apart.
	 *
	 * @param name the name to tally, or {@code null} for none
	 * @return whether it was tallied
	 */
	public synchronized boolean addNpcKill(String name)
	{
		if (state != State.RUNNING || TaskStatistics.normalize(name) == null)
		{
			return false;
		}
		final List<NpcKills> updated = NpcKillTally.add(npcKills, name);
		final boolean tallied = NpcKillTally.total(updated) != NpcKillTally.total(npcKills);
		npcKills = updated;
		return tallied;
	}

	/** A copy of the session's kills per NPC name so far, in the order first seen. */
	public synchronized List<NpcKills> getNpcKills()
	{
		return new ArrayList<>(npcKills);
	}

	/**
	 * Which records the observed task's statistics use, while the active session is on the observed task (else
	 * {@link TaskSelection#ANY}):
	 * <ul>
	 * <li>the version the session's kills decide ({@link CatacombsVariants#selection} of its kills per NPC name
	 * and its task kills, the same numbers the saved record's variant is decided from);</li>
	 * <li>cannon tasks only once the session has fired a cannonball ({@link CannonTasks#fired} of its supplies,
	 * as the saved record is classified), else tasks with and without a cannon pooled. It never narrows to tasks
	 * without a cannon (owner decision): a cannon can still be set up later in the task.</li>
	 * </ul>
	 */
	public synchronized TaskSelection getCurrentTaskSelection()
	{
		if (!isSessionOnCurrentTask())
		{
			return TaskSelection.ANY;
		}
		return CatacombsVariants.selection(sessionMonster, npcKills, kills)
			.withCannon(CannonTasks.fired(supplies) ? Boolean.TRUE : null);
	}

	private boolean isSessionOnCurrentTask()
	{
		return (state == State.RUNNING || state == State.PAUSED) && hasSessionTask && taskObserved
			&& currentCreatureId == sessionCreatureId
			&& (currentMonster == null || sessionMonster == null || currentMonster.equals(sessionMonster));
	}

	/**
	 * Records this tick's XP reading of every skill and, only while the session is RUNNING, adds the XP gained since
	 * the previous reading to it. Decided in one synchronized call, so a Play or Pause click can't fall between the
	 * reading and the decision. The previous reading is the baseline whatever the state, so after Play or Resume the
	 * first counted XP is what arrived after the click (the same way kills count from the task count read before
	 * Play). Nothing is counted when:
	 * <ul>
	 *     <li>the session is not RUNNING: idle, paused, stopped, or a completion held for late loot (it stopped on its
	 *     completion tick, so XP after that tick never reaches it);</li>
	 *     <li>there is no previous reading: the first reading after {@link #resetXpBaseline()} (login, world hop, lost
	 *     connection, account switch) or after an unsynced one only sets the baseline, so the stats a login sends are
	 *     never counted;</li>
	 *     <li>{@code reading} is {@code null} (the caller's sign that the stats are not synced); the baseline is
	 *     dropped;</li>
	 *     <li>any skill went down since the previous reading ({@link SkillXp#gains}): the readings can't be compared,
	 *     and this one becomes the baseline.</li>
	 * </ul>
	 *
	 * @param reading every skill's XP, keyed as {@link SkillXp} keys them, or {@code null} when not synced
	 * @return whether XP was added to the session
	 */
	public synchronized boolean observeXp(Map<String, Integer> reading)
	{
		final Map<String, Integer> previous = xpReading;
		xpReading = reading == null ? null : new TreeMap<>(reading);
		if (reading == null || previous == null || state != State.RUNNING)
		{
			return false;
		}
		final Map<String, Long> gains = SkillXp.gains(previous, reading);
		if (gains == null || gains.isEmpty())
		{
			return false;
		}
		SkillXp.add(xpGained, gains);
		return true;
	}

	/**
	 * Forgets the XP baseline (on login, world hop, lost connection or account switch), so the next reading of
	 * {@link #observeXp} only sets it. The session's XP so far is kept.
	 */
	public synchronized void resetXpBaseline()
	{
		xpReading = null;
	}

	/** A copy of the XP gained per skill in the started (running, paused or just stopped) session. */
	public synchronized Map<String, Long> getXpGained()
	{
		return new TreeMap<>(xpGained);
	}

	/**
	 * Sets (or, with an empty or {@code null} note, clears) the note of the given session: the running or paused
	 * session, or a completed session still held for late loot (see {@link #holdCompletion()}), so a note committed
	 * just as the task completes still reaches the saved record. The note is {@link TaskNote#normalize normalized}.
	 *
	 * @param sessionId the session the note was typed for; another session's note is never changed
	 * @return whether a session took the note; {@code false} when it is no longer active or held
	 */
	public synchronized boolean setNote(String sessionId, String note)
	{
		if (sessionId == null)
		{
			return false;
		}
		final String normalized = TaskNote.normalize(note);
		if ((state == State.RUNNING || state == State.PAUSED) && sessionId.equals(this.sessionId))
		{
			this.note = normalized;
			return true;
		}
		if (pendingCompletion != null && sessionId.equals(pendingCompletion.getSessionId()))
		{
			pendingCompletion = pendingCompletion.withNote(normalized);
			return true;
		}
		return false;
	}

	/**
	 * Sets the Slayer points earned and the streak of a completed session: the running or paused session once
	 * {@link #observe} reported it {@link ObserveResult#COMPLETED}, or the completed session held for late loot (see
	 * {@link #holdCompletion()}), so the points can still be corrected while it is held. Recorded whether the session
	 * was running or paused when the task completed: they belong to the task, not to the time tracked.
	 *
	 * @param sessionId    the completed session; another session is never changed
	 * @param pointsEarned points the completion gave, or {@code null} when not trusted
	 * @param taskStreak   streak after the completion, or {@code null} when unknown
	 * @return whether a completed session took them; {@code false} when it is no longer active or held
	 */
	public synchronized boolean setCompletionRewards(String sessionId, Integer pointsEarned, Integer taskStreak)
	{
		if (sessionId == null)
		{
			return false;
		}
		if ((state == State.RUNNING || state == State.PAUSED) && completed && sessionId.equals(this.sessionId))
		{
			sessionContext = sessionContext.withRewards(pointsEarned, taskStreak);
			return true;
		}
		if (pendingCompletion != null && sessionId.equals(pendingCompletion.getSessionId()))
		{
			pendingCompletion = pendingCompletion.withContext(
				pendingCompletion.getContext().withRewards(pointsEarned, taskStreak));
			return true;
		}
		return false;
	}

