	private volatile LootPriceMode lootPriceMode = LootPriceMode.GE;
	/**
	 * The "Notable drop value" setting, in gp. Read in startUp and again when it changes (on any thread, so it is
	 * volatile); used on the client thread when loot arrives.
	 */
	private volatile long notableDropThreshold = NotableDrops.DEFAULT_THRESHOLD;
	/**
	 * What Ground Items' hidden list hides from the loot, or {@link GroundItemsHidden#NONE} while the "Hide
	 * Ground Items' hidden items" setting or Ground Items is off. Read from the config in startUp and again when one of
	 * them changes (on any thread, so it is volatile); used on the client thread for the live values and the
	 * task-complete line, and sent to the history model on the EDT. Immutable.
	 */
	private volatile GroundItemsHidden groundItemsHidden = GroundItemsHidden.NONE;
	/** Which live and just-saved loot ids {@link #groundItemsHidden} hides, from the item names; client thread only. */
	private final HiddenLootResolver hiddenLoot = new HiddenLootResolver();
	/**
	 * Values last sent to the panel, or {@code null} when none are shown. They carry their session's id, so a new
	 * session is always sent, even with equal amounts.
	 */
	private volatile SessionValuation.Values publishedValues;
	/**
	 * The historical time per kill the sidebar shows for the active session's task (and location) until the live pace
	 * takes over, or {@code null} when it has no history or no session is active. Written by the history model on the
	 * EDT ({@link #publishHistoricalPace}), read by the overlay on the client thread ({@link #overlayData()});
	 * immutable.
	 */
	private volatile OverlayRows.HistoricalPace historicalPace;
	/** Tick the live session values were last computed (or tried, if that failed). */
	private int sessionValueTick = SupplyExclusions.NEVER_TICK;
	/** "Loot price" setting the live session values were last computed (or tried) in; client thread only. */
	private LootPriceMode sessionValueMode;
	/** Ground Items' hidden list the live session values were last computed (or tried) with; client thread only. */
	private GroundItemsHidden sessionValueHidden;
	/**
	 * Id of the paused session whose values were worked out while paused with every price known, or {@code null}. A
	 * paused session's loot and supplies can't change, so it is not valued again until it is resumed or the "Loot
	 * price" setting changes. Client thread only.
	 */
	private String pausedValuesSession;
	/** This settled tick's XP of every skill, by {@link #SKILLS} index; reused every tick. Client thread only. */
	private final int[] xpReading = new int[SKILLS.length];
	/** The XP reading last passed to the tracker, by {@link #SKILLS} index; valid while {@link #xpSent}. */
	private final int[] xpLastSent = new int[SKILLS.length];
	/** Whether the tracker's XP baseline is {@link #xpLastSent} (see {@link #observeSkillXp}). Client thread only. */
	private boolean xpSent;
	/**
	 * Idle ticks left to read the inventory and note its potions ({@link SupplyTracker#noteVariants}) while no supplies
	 * diff runs, or 0 once noted: {@link #INVENTORY_NOTE_TRIES} when the inventory changes and on (re)login or a hop.
	 * Client thread only.
	 */
	private int inventoryNoteTries;

	// Shared between client thread and EDT
	/**
	 * False from the start of startUp until its client-thread block has reset the client-thread state. startUp runs on
	 * the EDT and only queues that block, so the plugin's client-thread handlers (registered right after startUp) may
	 * run before it; while this is false they return at once instead of using the previous run's state. The block
	 * reads the game state and account from the client itself, so nothing a skipped event carried is lost.
	 */
	private volatile boolean clientStateReady;
	private volatile boolean loggedIn;
	private volatile long accountHash = SessionTracker.NO_ACCOUNT;
	/**
	 * Account whose saved records the panel may show: the logged-in account, or {@link SessionTracker#NO_ACCOUNT}
	 * at the login screen. Written on the client thread; ledger results are applied on the EDT only while it still
	 * matches, so a stale load can never show another account's records.
	 */
	private volatile long historyAccount = SessionTracker.NO_ACCOUNT;
	/** Latest task-completion counters read on the client thread (regular, Wilderness, Mortimer). */
	private volatile int[] lastCompletionCounters;
	/**
	 * The task streak the panel's "Next bonus" line is for: the {@link #streakCounter} counter as last read on a
	 * settled tick, or {@code null} when unknown. Written on the client thread, read by the panel on the EDT.
	 */
	private volatile Integer currentTaskStreak;
	/** True while an active-session file is being loaded; Play is disabled so it cannot race the restore. */
	private volatile boolean restorePending;
	/** Session awaiting the Keep/Discard dialog; saved as partial on shutdown if still unresolved. */
	private final AtomicReference<SessionTracker.Summary> pendingPrompt = new AtomicReference<>();

	@Override
	protected void startUp()
	{
		// Until the client-thread block below has run; see clientStateReady.
		clientStateReady = false;
		tracker = new SessionTracker(System::currentTimeMillis);
		// The store resolves its directory on its first operation; all of them run on the executor.
		store = new LedgerStore(ledgerDirectorySource != null ? ledgerDirectorySource : this::getPluginDirectory, gson);
		// getPluginDirectory does file IO and may move the legacy directory, so resolve it now, off the EDT, rather
		// than on the first save (possibly while the client exits). A failure is retried by the next operation.
		final LedgerStore startStore = store;
		executor.execute(() ->
		{
			try
			{
				startStore.directory();
			}
			catch (IOException e)
			{
				log.warn("Unable to open the Slayer Ledger directory; records cannot be loaded or saved", e);
			}
		});
		lootPriceMode = readLootPriceMode();
		groundItemsHidden = readGroundItemsHidden();
		// The lookups answer whichever history model is current when an answer is ready.
		lookups.setHistoryModelSource(this::historyModel);
		historyModel = new LedgerHistoryModel(tracker, lootPriceMode, lookups::requestLocationNames,
			lookups::requestCurrentPrices, lookups::requestItemNames, this::postAssignmentPreview,
			this::publishHistoricalPace, executor, SwingUtilities::invokeLater);
		final Gson luckGson = gson;
		final String luckResource = luckSnapshotResource;
		historyModel.setLuckMeterSource(() -> luckGson == null ? null : LuckMeter.load(luckGson, luckResource));
		historyModel.setGroundItemsHidden(groundItemsHidden);
		panel = new SlayerLedgerPanel(this, tracker, historyModel, gson);
		// startUp runs on the EDT, so the panel's sections can be set here.
		for (SlayerLedgerPanel.OptionalSection section : SlayerLedgerPanel.OptionalSection.values())
		{
			panel.setSectionShown(section, isSectionShown(section));
		}
		historyModel.setTaskAdvisor(config.taskAdvisor(), taskAdvisorMetric());
		taskOverlay = new SlayerLedgerOverlay(this, config);
		overlayManager.add(taskOverlay);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Slayer Ledger")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		restorePending = false;
		publishedValues = null;
		historicalPace = null;
		ignoredLoot = IgnoredLoot.parse(config.ignoredLoot());
		notableDropThreshold = NotableDrops.threshold(config.notableDropThreshold());
		// Queued (startUp runs on the EDT). Client-thread state is reset here, not on the EDT, so it is only ever touched
		// on the client thread; the handlers wait for it (clientStateReady).
		clientThread.invoke(() ->
		{
			try
			{
				restoreCheckNeeded = true;
				pendingAutoPause = null;
				supplyTracker = new SupplyTracker(supplyReader::classifyItem);
				supplyReader.reset();
				bankTripCounter.reset();
				sessionValuation.reset();
				// Item names are looked up afresh in each run of the plugin.
				hiddenLoot.setList(GroundItemsHidden.NONE);
				streakCounter = StreakMilestone.NO_COUNTER;
				// A not-tracking row from before the plugin was turned off must not show; the nudged assignment is
				// kept. Not in resetClientState, so a hop keeps the row. The overlay shows nothing until this has run.
				trackingNudge.hideRow();
				resetClientState();
				// Today's prices are looked up afresh in each run of the plugin, and so are item and location names.
				lookups.reset();
				locationPrompt.reset();
				lastLiveInputs = null;
				// Assignments are watched afresh too; one first seen now is checked against the saved records.
				assignmentWatch.forget();
				// From the client, not from GameStateChanged: one posted before this block ran was skipped.
				loggedIn = client.getGameState() == GameState.LOGGED_IN;
				if (loggedIn)
				{
					checkAccount();
					loadBlowpipeDartId();
				}
				// "Ask again about skipped places" ticked while the plugin was off.
				applyLocationSkipReset();
			}
			finally
			{
				// Last: the handlers may now use the client-thread state. Even after a failure here, as before this
				// guard, so one bad lookup can't leave the plugin deaf for the rest of the run.
				clientStateReady = true;
			}
		});
		// Last, so the ticker only runs once everything it uses exists. If startUp fails, RuneLite calls shutDown, which
		// unregisters it; the unregister first makes a repeated registration impossible.
		eventBus.unregister(completionGraceTicker);
		eventBus.register(completionGraceTicker);
	}

	@Override
	protected void shutDown()
	{
		// An unresolved Keep/Discard dialog is saved as partial; a completed session still held for late loot is saved
		// as completed (by endSession); an in-progress session is persisted as the account's active session (not a
		// ledger record) and restored on the next login if the task matches. A held completion is saved by endSession,
		// so the grace ticker is stopped first. RuneLite also calls this after a failed startUp, so anything may be
		// missing; the UI is always removed.
		eventBus.unregister(completionGraceTicker);
		try
		{
			if (tracker != null && store != null)
			{
				savePendingPrompt();
				endSession(SaveDecision.EndReason.SHUTDOWN);
			}
		}
		finally
		{
			if (taskOverlay != null)
			{
				overlayManager.remove(taskOverlay);
				taskOverlay = null;
			}
			if (navButton != null)
			{
				clientToolbar.removeNavigation(navButton);
			}
			if (panel != null)
			{
				panel.shutDown();
			}
			panel = null;
			if (historyModel != null)
			{
				historyModel.shutDown();
			}
			historyModel = null;
			navButton = null;
		}
		loggedIn = false;
		accountHash = SessionTracker.NO_ACCOUNT;
		historyAccount = SessionTracker.NO_ACCOUNT;
	}

	/** Test seam: keeps the ledger files in {@code directory} instead of the plugin directory. Call before startUp. */
	void setLedgerDirectory(Filepath directory)
	{
		setLedgerDirectorySource(() -> directory);
	}

	/** Test seam: answers the Keep/Discard dialog with {@code dialog} (on the EDT) instead. Call before startUp. */
	void setKeepIncompleteDialog(BiPredicate<SlayerLedgerPanel, SessionTracker.Summary> dialog)
	{
		keepIncompleteDialog = dialog;
	}

	/** Test seam: resolves the ledger directory from {@code source} instead. Call before startUp. */
	void setLedgerDirectorySource(LedgerStore.DirectorySource source)
	{
		ledgerDirectorySource = source;
	}

	/** Test seam: reads the luck meter's drop snapshot from {@code resource} instead. Call before startUp. */
	void setLuckSnapshotResource(String resource)
	{
		luckSnapshotResource = resource;
	}

	/**
	 * Binds the plugin's own helpers here, so Guice keeps them in the plugin's injector. Left to just-in-time
	 * binding they would land in RuneLite's main injector and keep this plugin's classes loaded after a Plugin Hub
	 * update or uninstall.
	 */
	@Override
	public void configure(Binder binder)
	{
		binder.bind(ClientLookups.class);
		binder.bind(SupplyReader.class);
		binder.bind(SlayerDbLookups.class);
	}

	@Provides
	SlayerLedgerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerLedgerConfig.class);
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		Future<?> pending = savePendingPrompt();
		if (pending != null)
		{
			event.waitFor(pending);
		}
		Future<?> completion = flushPendingCompletion();
		if (completion != null)
		{
			event.waitFor(completion);
		}
		Future<?> save = endSession(SaveDecision.EndReason.SHUTDOWN);
		if (save != null)
		{
			event.waitFor(save);
		}
	}

	/**
	 * Any thread. Re-parses the "Ignored loot" setting when it changes (loot already counted is not changed), reads a
	 * new "Notable drop value" (notable drops already listed are kept), and applies a new "Loot price" setting: the
	 * live values follow on the next game tick and the history is redrawn on the EDT. A change of "Hide Ground Items'
	 * hidden items", of Ground Items' hidden or highlighted list, or Ground Items turned on or off, is applied the same
	 * way. A "Panel sections" setting shows or hides its sidebar section on the EDT. "Ask again about skipped
	 * places" is applied on the client thread.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (isGroundItemsHiddenKey(event.getGroup(), event.getKey()))
		{
			applyGroundItemsHidden();
			return;
		}
		if (!SlayerLedgerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (SlayerLedgerConfig.HIDE_GROUND_ITEMS_HIDDEN.equals(event.getKey()))
		{
			applyGroundItemsHidden();
		}
		else if (SlayerLedgerConfig.IGNORED_LOOT.equals(event.getKey()))
		{
			ignoredLoot = IgnoredLoot.parse(config.ignoredLoot());
		}
		else if (SlayerLedgerConfig.NOTABLE_DROP_THRESHOLD.equals(event.getKey()))
		{
			notableDropThreshold = NotableDrops.threshold(config.notableDropThreshold());
		}
		else if (SlayerLedgerConfig.LOOT_PRICE_MODE.equals(event.getKey()))
		{
			final LootPriceMode mode = readLootPriceMode();
			lootPriceMode = mode;
			final LedgerHistoryModel m = historyModel;
			if (m != null)
			{
				SwingUtilities.invokeLater(() -> m.setLootPriceMode(mode));
			}
		}
		else if (SlayerLedgerConfig.RESET_LOCATION_SKIPS.equals(event.getKey()))
		{
			clientThread.invoke(this::applyLocationSkipReset);
		}
		else if (SlayerLedgerConfig.TASK_ADVISOR.equals(event.getKey())
			|| SlayerLedgerConfig.TASK_ADVISOR_GOAL.equals(event.getKey()))
		{
			final boolean enabled = config.taskAdvisor();
			final TaskRanking.Metric metric = taskAdvisorMetric();
			final LedgerHistoryModel m = historyModel;
			if (m != null)
			{
				SwingUtilities.invokeLater(() -> m.setTaskAdvisor(enabled, metric));
			}
		}
		else
		{
			final SlayerLedgerPanel.OptionalSection section = optionalSection(event.getKey());
			final SlayerLedgerPanel p = panel;
			if (section != null && p != null)
			{
				final boolean shown = isSectionShown(section);
				SwingUtilities.invokeLater(() -> p.setSectionShown(section, shown));
			}
		}
	}

	/** The optional sidebar section a "Panel sections" setting's key shows, or {@code null} for any other key. */
	private static SlayerLedgerPanel.OptionalSection optionalSection(String key)
	{
		if (key == null)
		{
			return null;
		}
		switch (key)
		{
			case SlayerLedgerConfig.SHOW_WHAT_TO_BRING:
				return SlayerLedgerPanel.OptionalSection.WHAT_TO_BRING;
			case SlayerLedgerConfig.SHOW_TRENDS:
				return SlayerLedgerPanel.OptionalSection.TRENDS;
			case SlayerLedgerConfig.SHOW_OVERALL_TOTALS:
				return SlayerLedgerPanel.OptionalSection.OVERALL_TOTALS;
			case SlayerLedgerConfig.SHOW_LUCK_METER:
				return SlayerLedgerPanel.OptionalSection.LUCK_METER;
			case SlayerLedgerConfig.SHOW_SKIPPED_BLOCKED:
				return SlayerLedgerPanel.OptionalSection.SKIPPED_BLOCKED;
			default:
				return null;
		}
	}

	/** Whether the "Panel sections" settings show {@code section} in the sidebar. */
	private boolean isSectionShown(SlayerLedgerPanel.OptionalSection section)
	{
		switch (section)
		{
			case WHAT_TO_BRING:
				return config.showWhatToBring();
			case TRENDS:
				return config.showTrends();
			case OVERALL_TOTALS:
				return config.showOverallTotals();
			case LUCK_METER:
				return config.showLuckMeter();
			default:
				return config.showSkippedBlocked();
		}
	}

	/** The "Task advisor goal" setting's metric, Profit/h when unset. */
	private TaskRanking.Metric taskAdvisorMetric()
	{
		final TaskAdvisorGoal goal = config.taskAdvisorGoal();
		return (goal == null ? TaskAdvisorGoal.PROFIT : goal).metric();
	}

	/**
	 * The "Loot price" setting, GE when unset. A saved value that is no longer a {@link LootPriceMode} (the removed
	 * "Higher of the two") also reads as GE: RuneLite's config proxy returns the item's default when it cannot parse
	 * the value.
	 */
	private LootPriceMode readLootPriceMode()
	{
		final LootPriceMode mode = config.lootPriceMode();
		return mode == null ? LootPriceMode.GE : mode;
	}

	/** Whether a config change of {@code group} and {@code key} can change what {@link #groundItemsHidden} hides. */
	private static boolean isGroundItemsHiddenKey(String group, String key)
	{
		if (GroundItemsHidden.GROUP.equals(group))
		{
			return GroundItemsHidden.HIDDEN_ITEMS_KEY.equals(key) || GroundItemsHidden.HIGHLIGHTED_ITEMS_KEY.equals(key);
		}
		return GroundItemsHidden.PLUGIN_ENABLED_GROUP.equals(group) && GroundItemsHidden.PLUGIN_ENABLED_KEY.equals(key);
	}

	/**
	 * Any thread. What Ground Items' lists hide from the loot now, read from the config (Ground Items' own
	 * settings are only read, never written; ConfigManager reads are safe on any thread).
	 */
	private GroundItemsHidden readGroundItemsHidden()
	{
		return GroundItemsHidden.effective(config.hideGroundItemsHidden(),
			configManager.getConfiguration(GroundItemsHidden.PLUGIN_ENABLED_GROUP, GroundItemsHidden.PLUGIN_ENABLED_KEY),
			configManager.getConfiguration(GroundItemsHidden.GROUP, GroundItemsHidden.HIDDEN_ITEMS_KEY),
			configManager.getConfiguration(GroundItemsHidden.GROUP, GroundItemsHidden.HIGHLIGHTED_ITEMS_KEY));
	}

	/**
	 * Any thread. Reads {@link #groundItemsHidden} again; when it changed, the live values follow on the next game tick
	 * and the history model works out the hidden loot again on the EDT. Synchronized so that concurrent
	 * {@code ConfigChanged} events read, store and hand over their lists one at a time, in order: the last list read
	 * is the one kept and the last one the model gets.
	 */
	private synchronized void applyGroundItemsHidden()
	{
		final GroundItemsHidden list = readGroundItemsHidden();
		if (list.equals(groundItemsHidden))
		{
			return;
		}
		groundItemsHidden = list;
		final LedgerHistoryModel m = historyModel;
		if (m != null)
		{
			SwingUtilities.invokeLater(() -> m.setGroundItemsHidden(list));
		}
	}

	/**
	 * Client thread. Which of {@code itemIds} {@link #groundItemsHidden} hides, from their item compositions' names (a
	 * note's is its unnoted item's, as Ground Items matches it).
	 */
	private HiddenLoot hiddenLoot(Collection<Integer> itemIds)
	{
		hiddenLoot.setList(groundItemsHidden);
		return hiddenLoot.resolve(itemIds, lookups.lootItemNames()::name);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (!clientStateReady)
		{
			return;
		}
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
				// A completed session held for late loot is saved now; it is never persisted as the active session.
				flushPendingCompletion();
				noteAutoPause(tracker.autoPause(), AutoPauseMessage.Reason.LOGOUT);
				cancelPendingRestore();
				// Keep the session in memory (a re-login resumes it) but persist it in case the client is closed.
				persistOnLogout();
				restoreCheckNeeded = true;
				// The next login may be a different account; never show or adopt the old task.
				tracker.clearCurrentTask();
				trackingNudge.hideRow();
				streakCounter = StreakMilestone.NO_COUNTER;
				loggedIn = false;
				resetClientState();
				blowpipeDartId = ChargedWeaponUsage.NO_ITEM;
				// The next login may be another profile; a later kill in the region asks again.
				hideLocationPrompt();
				// Hide the history while logged out; it is reloaded on the next login (any account).
				setHistoryAccount(SessionTracker.NO_ACCOUNT);
				break;
			case HOPPING:
				noteAutoPause(tracker.autoPause(), AutoPauseMessage.Reason.WORLD_HOP);
				// fall through
			case LOGGING_IN:
			case CONNECTION_LOST:
				// No game ticks count the grace window down while not logged in; save a held completion now.
				flushPendingCompletion();
				loggedIn = false;
				resetClientState();
				break;
			case LOGGED_IN:
				loggedIn = true;
				checkAccount();
				loadBlowpipeDartId();
				break;
			default:
				break;
		}
	}

	/**
	 * Client thread. Remembers why a logout or world hop paused the session, if it did ({@code paused}); a session
	 * that was already paused or idle keeps any earlier reason, so the first cause is the one told.
	 */
	private void noteAutoPause(boolean paused, AutoPauseMessage.Reason reason)
	{
		if (paused)
		{
			pendingAutoPause = reason;
		}
	}

	/**
	 * Client thread, on the first settled tick after the login, once any relogin restore check has run. Posts one chat
	 * line telling the player that a logout or world hop paused the session, then forgets the reason. Nothing is posted when the session is no longer paused
	 * (resumed, stopped, or another account's session was put away) or when it belongs to another account.
	 */
	private void announceAutoPause()
	{
		final AutoPauseMessage.Reason reason = pendingAutoPause;
		pendingAutoPause = null;
		if (reason == null || tracker.getState() != SessionTracker.State.PAUSED
			|| tracker.getSessionAccountHash() != client.getAccountHash())
		{
			return;
		}
		postChatLine(AutoPauseMessage.format(reason));
	}

	/**
	 * Any thread (ConfigManager posts it from wherever the profile changed). Another RuneScape profile is active, for
	 * example a different account or world type: its blowpipe dart type is read.
	 */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadBlowpipeDartId();
		// Logging out leaves no profile; the names are kept until another profile is active.
		if (event.getNewProfile() != null)
		{
			clientThread.invoke(this::forgetLocationNames);
		}
	}

	/**
	 * Client thread. Another account or RuneScape profile is active: its region names and skipped regions are read
	 * afresh, and the history model forgets the names it has (the panel then hides the prompt). A pending "Ask again
	 * about skipped places" applies to it.
	 */
	private void forgetLocationNames()
	{
		lookups.forgetLocationNames();
		locationPrompt.hide();
		locationPrompt.forgetSkips();
		applyLocationSkipReset();
		final LedgerHistoryModel m = historyModel;
		if (m != null)
		{
			// The panel hides its prompt when the model forgets the names.
			SwingUtilities.invokeLater(m::clearLocationNames);
		}
	}

	/** Client thread. Hides the "Name this location" prompt without skipping its region. */
	private void hideLocationPrompt()
	{
		locationPrompt.hide();
		final SlayerLedgerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::hideLocationPrompt);
		}
	}

	/**
	 * EDT. Saves the player's name for map region {@code region} (the prompt's Save): kept in the RSProfile config, so
	 * it names the running session, every later task there and, for display, saved tasks there without a name.
	 *
	 * @return whether the name was taken; {@code false} when nothing is left after {@link TaskLocation#normalizeName}
	 */
	boolean saveLocationName(int region, String name)
	{
		final String normalized = TaskLocation.normalizeName(name);
		if (normalized == null || !LocationTally.isRegion(region))
		{
			return false;
		}
		clientThread.invoke(() ->
		{
			lookups.saveLocationName(region, normalized);
			locationPrompt.named(region);
			final LedgerHistoryModel m = historyModel;
			if (m != null)
			{
				SwingUtilities.invokeLater(() -> m.addLocationNames(Collections.singleton(region),
					Collections.singletonMap(region, normalized)));
			}
		});
		return true;
	}

	/**
	 * EDT. The prompt's Skip: {@code region} is not asked about again on this RuneScape profile, also after a restart
	 * (kept in its RSProfile config), until the "Ask again about skipped places" setting clears it.
	 */
	void skipLocationPrompt(int region)
	{
		clientThread.invoke(() ->
		{
			// Written first: the write may create the profile, and the profile change it posts forgets the skips held.
			lookups.saveLocationSkip(region);
			locationPrompt.skip(region);
		});
	}

	/**
	 * Client thread. While "Ask again about skipped places" is ticked and a RuneScape profile is active: forgets that
	 * profile's skipped regions (in its config and here) and unticks the setting. Without a profile it stays ticked
	 * until one is active ({@link #forgetLocationNames}).
	 */
	private void applyLocationSkipReset()
	{
		if (!config.resetLocationSkips() || !lookups.clearLocationSkips())
		{
			return;
		}
		locationPrompt.forgetSkips();
		configManager.unsetConfiguration(SlayerLedgerConfig.GROUP, SlayerLedgerConfig.RESET_LOCATION_SKIPS);
	}

	/**
	 * Client thread, after the task is observed. Asks the player to name the region of a kill just counted when it has
	 * no name and the task has no assigned area (see {@link SessionTracker#takeRegionToName()}).
	 */
	private void offerLocationPrompt(int region)
	{
		if (!LocationTally.isRegion(region) || !locationPrompt.offer(region, lookups.locationName(region) != null,
			lookups.isLocationSkipped(region)))
		{
			return;
		}
		final SlayerLedgerPanel p = panel;
		if (p != null)
		{
			// The task's Wiki locations are added by the panel, which reads the bundled list.
			final String monster = tracker.getSessionMonster() != null
				? tracker.getSessionMonster() : tracker.getCurrentMonster();
			final List<String> ownNames = lookups.profileLocationNames();
			SwingUtilities.invokeLater(() -> p.showLocationPrompt(region, monster, ownNames));
		}
	}

	/**
	 * Client thread. The map region of the local player's tile ({@link WorldPoint#fromLocalInstance}, so an instance is
	 * its template's region), or {@link LocationTally#NO_REGION} while there is no player or scene, or while the player
	 * is on a Sailing boat (the tile is in the boat's own world view, whose template region is not where the boat is).
	 * Never throws, so the task is always observed.
	 */
	private int readRegion()
	{
		try
		{
			final Player player = client.getLocalPlayer();
			final LocalPoint local = player == null ? null : player.getLocalLocation();
			final WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
			if (view == null || !view.isTopLevel())
			{
				return LocationTally.NO_REGION;
			}
			return WorldPoint.fromLocalInstance(client, local).getRegionID();
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to read the local player's region", e);
			return LocationTally.NO_REGION;
		}
	}

	/** Any thread. Reads the active RuneScape profile's blowpipe dart type from the RSProfile config. */
	private void loadBlowpipeDartId()
	{
		final String saved = configManager.getRSProfileConfiguration(SlayerLedgerConfig.GROUP, BLOWPIPE_DART_KEY);
		int dartId = ChargedWeaponUsage.NO_ITEM;
		if (saved != null)
		{
			try
			{
				dartId = Integer.parseInt(saved.trim());
			}
			catch (NumberFormatException e)
			{
				log.debug("Ignoring a saved blowpipe dart type that is not an item id: {}", saved);
			}
		}
		blowpipeDartId = dartId;
	}

	/**
	 * Client thread. Remembers the blowpipe's dart type for this RuneScape profile (or forgets it, with
	 * {@link ChargedWeaponUsage#NO_ITEM}).
	 */
	private void setBlowpipeDartId(int dartId)
	{
		if (dartId == blowpipeDartId)
		{
			return;
		}
		blowpipeDartId = dartId;
		if (dartId == ChargedWeaponUsage.NO_ITEM)
		{
			configManager.unsetRSProfileConfiguration(SlayerLedgerConfig.GROUP, BLOWPIPE_DART_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(SlayerLedgerConfig.GROUP, BLOWPIPE_DART_KEY, dartId);
		}
	}

	/**
	 * Counts down the grace window of a completed session held for late loot, and saves it when the window ends. A
	 * separate subscriber because the event bus requires handlers to be named after their event and a class can have
	 * only one {@code onGameTick(GameTick)}. Registered at a lower priority than the default-priority tick handlers, so
	 * LootManager has already posted this tick's ServerNpcLoot; the completion tick itself is not counted. Loot from the
	 * completion tick through {@link SessionTracker#COMPLETION_LOOT_GRACE_TICKS} ticks later is therefore included.
	 */
	private final class CompletionGraceTicker
	{
		/** Client thread. */
		@Subscribe(priority = -1)
		public void onGameTick(GameTick tick)
		{
			if (!clientStateReady || client.getGameState() != GameState.LOGGED_IN || client.getTickCount() == completionHeldTick)
			{
				return;
			}
			handleEndedSession(tracker.tickCompletion(), SaveDecision.EndReason.SYSTEM);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!clientStateReady)
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		checkAccount();
		lookups.retryCurrentPrices();
		// Before observing the task, so supplies used on the tick the task completes still count.
		trackSupplies();
		// The menu clicks and messages that open a charging window arrive before this tick's GameTick, so trackSupplies
		// has already left the charged materials out of this tick's diff. Weapon use comes from the attack itself, not
		// the diff, so it is counted next and valued with the rest of this tick's supplies.
		trackChargedWeapons();
		updateSessionValues();

		if (settleTicks > 0)
		{
			settleTicks--;
			return;
		}

		// Before observing the task, so XP gained on the tick the task completes still counts; a completion held for
		// late loot is no longer running, so it gets no XP after its completion tick.
		observeSkillXp();

		final int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int[] counters = {
			client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED),
			client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED),
			client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED)
		};
		lastCompletionCounters = counters;
		final boolean completionSignaled = completionSignal.update(counters);
		final int points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		taskRewards.update(points);
		// A completed session held for late loot takes points that arrive after its completion tick.
		if (taskRewards.isFollowing() && !tracker.setCompletionRewards(taskRewards.getSessionId(), taskRewards.earned(),
			taskRewards.streak()))
		{
			// Saved (or no longer held): nothing left to update.
			taskRewards.stopFollowing();
		}

		String name = null;
		int creatureId = SessionTracker.NO_CREATURE;
		int originalAmount = SessionTracker.UNKNOWN_AMOUNT;
		TaskContext assignment = TaskContext.NONE;
		if (remaining > 0)
		{
			final int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			final int bossId = taskId == SessionTracker.BOSS_TASK_TARGET
				? client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID) : 0;
			creatureId = SessionTracker.creatureKey(taskId, bossId);
			name = dbLookups.lookupTaskName(taskId, bossId, creatureId);
			originalAmount = readOriginalAmount();
			assignment = readAssignment();
		}

		// Decide before observing so Play stays disabled from the first settled observation until the restore ran.
		if (restoreCheckNeeded)
		{
			restoreCheckNeeded = false;
			pendingFileRestore = accountHash != SessionTracker.NO_ACCOUNT
				&& tracker.getState() == SessionTracker.State.IDLE;
			// A session kept in memory across logout must pass the same checks as one restored from disk.
			pendingReloginSnapshot = pendingFileRestore ? null : logoutSnapshot;
			logoutSnapshot = null;
			restoreWaitTicks = 0;
			if (pendingFileRestore || pendingReloginSnapshot != null)
			{
				restorePending = true;
			}
		}

		// Read with the task, so the kills this observation counts are tallied where the player is.
		final int region = readRegion();
		switch (tracker.observe(name, creatureId, remaining, originalAmount, assignment, region, completionSignaled))
		{
			case COMPLETED:
				log.debug("Slayer task completed");
				// The completion was signalled on this tick, so the incremented counter is this completion's streak.
				taskRewards.startCompletion(tracker.getSessionId(), counters, completionSignal.incrementedCounter());
				tracker.setCompletionRewards(taskRewards.getSessionId(), taskRewards.earned(), taskRewards.streak());
				// A running session waits COMPLETION_LOOT_GRACE_TICKS ticks for the final kill's loot before it is
				// saved (see CompletionGraceTicker); a paused one is saved now.
				if (tracker.holdCompletion())
				{
					completionHeldTick = client.getTickCount();
				}
				else
				{
					taskRewards.stopFollowing();
					endSession(SaveDecision.EndReason.SYSTEM);
				}
				break;
			case TASK_CHANGED:
				log.debug("Slayer task changed during a session");
				// The tracker already holds the new task as "current", ready for the next session.
				endSession(SaveDecision.EndReason.SYSTEM);
				break;
			default:
				break;
		}
		// After the session's decision, so the final kill of a task held for late loot is offered too.
		offerLocationPrompt(tracker.takeRegionToName());
		// After the session's decision, so the master the tracker filled in for this task is used.
		updateTaskStreak(remaining, counters);
		// After the session's decision, so a session that took this task on this tick marks it as played.
		watchAssignments(AssignmentWatch.Reading.builder()
			.monster(name)
			.creatureId(creatureId)
			.remaining(remaining)
			.originalAmount(originalAmount)
			.context(assignment)
			.points(points)
			.counters(counters)
			.blockedValues(readBlockedTaskValues())
			.completionSignaled(completionSignaled)
			.build());
		// After the session's decision, so a kill a running session counted, or the kill that completed it, never nudges.
		nudgeIfNotTracking(name, creatureId, remaining, originalAmount);

		if (pendingFileRestore || pendingReloginSnapshot != null)
		{
			runPendingRestoreCheck(remaining, counters);
		}
		// After the restore check and this tick's task decision, so a session that one of them ended gets no line.
		if (pendingAutoPause != null && !pendingFileRestore && pendingReloginSnapshot == null)
		{
			announceAutoPause();
		}
		// Last, so a session this tick started, restored or ended is seen.
		refreshHistoryModelIfLiveChanged();
	}

	/**
	 * Client thread, every settled tick. When the task, its kills left, its location or the session changed
	 * ({@link LedgerHistoryModel#liveInputs}), asks the history model on the EDT to check the waiting chat preview
	 * again and publish the overlay's historical time per kill; otherwise, while the model waits for today's prices,
	 * asks it to end that wait once it has run out. So none of these waits for the panel's refresh timer.
	 */
	private void refreshHistoryModelIfLiveChanged()
	{
		final List<Object> inputs = LedgerHistoryModel.liveInputs(tracker);
		final LedgerHistoryModel m = historyModel;
		if (!inputs.equals(lastLiveInputs))
		{
			lastLiveInputs = inputs;
			if (m != null)
			{
				SwingUtilities.invokeLater(m::refreshLive);
			}
		}
		else if (m != null && m.isWaitingForCurrentPrices())
		{
			SwingUtilities.invokeLater(m::endExpiredCurrentPricesWait);
		}
	}

	/** Test seam: the history model, or {@code null} while the plugin is stopped. Use it on the EDT. */
	LedgerHistoryModel historyModel()
	{
		return historyModel;
	}

	/**
	 * Test seam: replaces (or, with {@code null}, unsets) the history model, so a test can lose the answers the client
	 * thread would send it.
	 */
	void setHistoryModel(LedgerHistoryModel model)
	{
		historyModel = model;
	}

	/** Test seam: the session tracker, or {@code null} before the plugin first starts. */
	SessionTracker tracker()
	{
		return tracker;
	}

	/** Test seam: the sidebar panel, or {@code null} while the plugin is stopped. Use it on the EDT. */
	SlayerLedgerPanel panel()
	{
		return panel;
	}

	/** Test seam: stands {@code valuation} in for the live session valuation. Call on the client thread. */
	void setSessionValuation(SessionValuation valuation)
	{
		sessionValuation = valuation;
	}

	/** Test seam: the game-tick subscriber the plugin registers on the event bus next to itself. */
	Object completionGraceTicker()
	{
		return completionGraceTicker;
	}

	/** EDT, after a panel action changed the session: the history model's live checks run at once. */
	private void refreshHistoryModel()
	{
		final LedgerHistoryModel m = historyModel;
		if (m != null)
		{
			m.refreshLive();
		}
	}

	/**
	 * Client thread, every settled tick. Tells the player, once per assignment, that a task kill was not tracked because
	 * no session is running or the session is paused ({@link TrackingNudge}); the overlay row comes from
	 * {@link #overlayData()}. Only informs: it never starts or resumes a session. Quiet while a restore check is pending
	 * (the session may yet be restored) and for another account's session.
	 */
	private void nudgeIfNotTracking(String name, int creatureId, int remaining, int originalAmount)
	{
		SessionTracker.State state = tracker.getState();
		final boolean suppressed = restorePending || pendingFileRestore || pendingReloginSnapshot != null
			|| accountHash == SessionTracker.NO_ACCOUNT
			|| (state == SessionTracker.State.PAUSED && tracker.getSessionAccountHash() != accountHash);
		final TrackingNudge.Line line = trackingNudge.update(accountHash, name, creatureId, remaining, originalAmount,
			state, suppressed);
		if (line == TrackingNudge.Line.NONE)
		{
			return;
		}
		postChatLine(TrackingNudge.message(line));
	}

	/**
	 * Client thread, every settled tick, whether or not a session is running (only varps and varbits are read). Saves
	 * each assignment that ended without a session, and asks the history model for a new one's chat preview; see
	 * {@link AssignmentWatch}.
	 */
	private void watchAssignments(AssignmentWatch.Reading reading)
	{
		final List<AssignmentWatch.Ended> ended = assignmentWatch.update(reading, tracker.takeSessionTaskKeys(),
			System.currentTimeMillis());
		// Taken every tick, so a new assignment is previewed on the tick it is seen or never.
		final boolean started = assignmentWatch.takeStarted();
		final long account = accountHash;
		if (account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		if (started && config.assignmentPreview())
		{
			// The tracker took this tick's task before the watch did. The history is on the EDT; the history model
			// posts the line through postAssignmentPreview once it has what it needs.
			final int creatureId = tracker.getCurrentCreatureId();
			final String monster = tracker.getCurrentMonster();
			final LedgerHistoryModel m = historyModel;
			if (m != null)
			{
				SwingUtilities.invokeLater(() -> m.requestAssignmentPreview(account, creatureId, monster));
			}
		}
		for (AssignmentWatch.Ended e : ended)
		{
			log.debug("Slayer assignment ended without a session: {}", e.getEntry().getOutcome());
			executor.execute(() ->
			{
				try
				{
					publishAssignments(account, store.appendAssignment(account, e.getEntry(), e.isCheckRecords()));
				}
				catch (IOException | RuntimeException ex)
				{
					log.warn("Unable to save a Slayer Ledger assignment entry", ex);
				}
			});
		}
	}

	/**
	 * Client thread, every settled tick. Publishes the streak for the panel's "Next bonus" line: the counter of
	 * the current task's master while there is a task; right after a completion the counter it raised, so the line
	 * shows the new streak until the next task. Unknown (hidden) while the master is unknown or not in the table.
	 */
	private void updateTaskStreak(int remaining, int[] counters)
	{
		if (remaining > 0)
		{
			streakCounter = StreakMilestone.counterFor(tracker.getCurrentContext().getMaster());
		}
		else if (completionSignal.incrementedCounter() != CompletionSignal.NO_COUNTER)
		{
			streakCounter = completionSignal.incrementedCounter();
		}
		currentTaskStreak = streakCounter >= 0 && streakCounter < counters.length ? counters[streakCounter] : null;
	}

	/**
	 * The current task streak for the panel's "Next bonus" line, or {@code null} when unknown (not logged in, no
	 * settled reading yet, no task or completion seen since logging in, or the master is unknown). Any thread.
	 */
	Integer currentTaskStreak()
	{
		return currentTaskStreak;
	}

	/** Client thread. The blocked-task varps then varbits, in a fixed order. */
	private int[] readBlockedTaskValues()
	{
		final int[] values = new int[BLOCKED_TASK_VARPS.length + BLOCKED_TASK_VARBITS.length];
		int i = 0;
		for (int varp : BLOCKED_TASK_VARPS)
		{
			values[i++] = client.getVarpValue(varp);
		}
		for (int varbit : BLOCKED_TASK_VARBITS)
		{
			values[i++] = client.getVarbitValue(varbit);
		}
		return values;
	}

	/**
	 * Client thread. NPC kill loot from the game's own loot tracker, the event core LootTrackerPlugin (1.13.3) uses for
	 * NPC loot. Counted only while the session is RUNNING, or for a just-completed session during its late-loot grace
	 * window (enforced by {@link SessionTracker#addLoot}). Loot from any NPC counts, not only the task monster; see
	 * {@link SessionTracker#addLoot}. Bones and demonic ashes a bonecrusher or ash sanctifier destroyed are left out
	 * ({@link CrushedLootFilter}), judged by what is carried at the time of this drop, and so are the player's ignored
	 * items ({@link IgnoredLoot}); see {@link LootFilter}. The kept loot's notable stacks ({@link NotableDrops}) go
	 * with it; they are only priced while loot is recorded ({@link SessionTracker#isRecordingLoot}), so no price
	 * lookups run for loot outside a session.
	 */
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (!clientStateReady)
		{
			return;
		}
		if (pickpocketTick == client.getTickCount())
		{
			// The server sends NPC loot for pickpockets too; like core LootTracker, ignore it.
			return;
		}
		final ItemTally items = new ItemTally();
		for (ItemStack stack : event.getItems())
		{
			items.add(stack.getId(), stack.getQuantity());
		}
		final ItemTally kept = new LootFilter(crushedLootFilter(), ignoredLoot).apply(items, lookups.lootItemNames());
		// Priced only while recording. A Play click between the check and addLoot records this kill's loot without its
		// notable stacks (at most one drop's entries); addLoot still decides loot and drops in one step.
		final boolean priced = !kept.isEmpty() && tracker.isRecordingLoot();
		tracker.addLoot(kept, priced ? findNotableDrops(kept) : null);
	}

	/**
	 * Client thread. The notable stacks of one kill's kept loot, valued now at the "Loot price" setting through
	 * {@code ItemManager} (see {@link NotableDrops}); none when the lookup fails.
	 */
	private List<NotableDrop> findNotableDrops(ItemTally loot)
	{
		if (loot == null || loot.isEmpty())
		{
			return null;
		}
		try
		{
			final ItemValuation.UnitPrices prices = new ItemValuation.UnitPrices();
			ItemValuation.capturePrices(loot, lookups.priceLookup(), prices);
			return NotableDrops.find(loot, prices, lootPriceMode, notableDropThreshold, this::lootItemName,
				System.currentTimeMillis());
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to value loot for notable drops", e);
			return null;
		}
	}

	/** Client thread. An item's name for a notable drop, or {@code null} when the lookup fails. */
	private String lootItemName(int itemId)
	{
		try
		{
			return lookups.lootItemNames().name(itemId);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Client thread. The bonecrusher filter for a loot drop now: in Auto mode, from the items in the inventory and worn
	 * right now (the player may switch the crusher on and off mid-task).
	 */
	private CrushedLootFilter crushedLootFilter()
	{
		final BonecrusherMode mode = config.bonecrusherHandling();
		if (!CrushedLootFilter.needsCarriedItems(mode))
		{
			return CrushedLootFilter.forDrop(mode, null);
		}
		final List<Integer> carried = new ArrayList<>();
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			final ItemContainer container = client.getItemContainer(containerId);
			if (container != null)
			{
				for (Item item : container.getItems())
				{
					carried.add(item.getId());
				}
			}
		}
		return CrushedLootFilter.forDrop(mode, carried);
	}

	/**
	 * Client thread. Remembers the tick of a pickpocket so its server NPC loot is not counted as kill loot, counts
	 * superior spawns ({@link SuperiorSpawnMessage}; RUNNING only, see {@link SessionTracker#addSuperiorSpawn}), learns
	 * the blowpipe's dart type from its check message ({@link BlowpipeMessage}), lets a charging message close a
	 * {@link ChargeExclusions} window, adds a pet drop ({@link PetMessage}) to the notable drops (by the loot rules,
	 * see {@link SessionTracker#addPet}), and counts a boss kill count message ({@link KillCountMessage}; by the loot
	 * rules and {@link BossKillCounts}, see {@link SessionTracker#addBossKillCount}).
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final ChatMessageType type = event.getType();
		// The chat types core ScreenshotPlugin (pets) and ChatCommandsPlugin (kill counts) check.
		final boolean notificationType = type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM
			|| type == ChatMessageType.TRADE || type == ChatMessageType.FRIENDSCHATNOTIFICATION;
		final NotableDrop.Pet pet = PetMessage.parse(notificationType, event.getMessage());
		if (pet != null)
		{
			tracker.addPet(NotableDrop.pet(pet, System.currentTimeMillis()));
		}
		final KillCountMessage.Result killCount = KillCountMessage.parse(notificationType, event.getMessage());
		if (killCount != null && killCount.isBossKill())
		{
			tracker.addBossKillCount(killCount.getBoss(), killCount.getKc());
		}
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM && type != ChatMessageType.MESBOX)
		{
			return;
		}
		if (PICKPOCKET_REGEX.matcher(event.getMessage()).matches())
		{
			pickpocketTick = client.getTickCount();
		}
		if (SuperiorSpawnMessage.matches(type != ChatMessageType.MESBOX, event.getMessage()))
		{
			tracker.addSuperiorSpawn();
		}
		final BlowpipeMessage.Darts darts = BlowpipeMessage.parse(event.getMessage());
		if (darts != null)
		{
			// A check message naming a dart type this plugin doesn't know also forgets the type: darts aren't counted.
			setBlowpipeDartId(darts.isLoaded() ? darts.getDartId() : ChargedWeaponUsage.NO_ITEM);
		}
		chargeExclusions.messageSeen(event.getMessage(), client.getTickCount());
	}

	/**
	 * Client thread. Remembers "Drop" clicks so the dropped item's decrease is not counted as a supply, and loading,
	 * charging, unloading or uncharging the blowpipe or a trident ({@link ChargeExclusions}). Only reads the click;
	 * the menu is never changed.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}
		final String plain = Text.removeTags(option).trim();
		final int itemId = event.getItemId();
		final int tick = client.getTickCount();
		if ("Drop".equalsIgnoreCase(plain))
		{
			if (itemId >= 0)
			{
				// Dropping a rune pouch counts nothing on these ticks: the runes inside leave with the pouch.
				supplyExclusions.dropClicked(itemId, SupplyReader.isRunePouch(itemId), tick);
			}
			return;
		}
		if ("Use".equalsIgnoreCase(plain))
		{
			// Only the click that uses the selected item on another one; selecting an item is also "Use".
			if (event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_WIDGET)
			{
				chargeExclusions.menuOptionClicked(option, useItemIds(event), tick);
			}
			return;
		}
		if ("Unload".equalsIgnoreCase(plain) || "Uncharge".equalsIgnoreCase(plain))
		{
			chargeExclusions.menuOptionClicked(option, new int[]{itemId}, tick);
			if (ChargedWeaponUsage.BLOWPIPES.contains(itemId))
			{
				// The darts come out; the type is learned again from the next check message.
				setBlowpipeDartId(ChargedWeaponUsage.NO_ITEM);
			}
		}
	}

	/**
	 * Client thread. The items of an item-on-item "Use": the target (the clicked entry's item and its widget's item)
	 * and the selected item ({@code client.getSelectedWidget()}, as core CompostTracker reads it, 1.13.4).
	 */
	private int[] useItemIds(MenuOptionClicked event)
	{
		final Widget target = event.getWidget();
		final Widget selected = client.getSelectedWidget();
		return new int[]{
			event.getItemId(),
			target != null ? target.getItemId() : -1,
			selected != null ? selected.getItemId() : -1
		};
	}

	/**
	 * Client thread. An excluded interface opening; also covers one opened and closed between two ticks. A bank opening
	 * may be a bank trip ({@link BankTripCounter}; RUNNING only).
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final int tick = client.getTickCount();
		supplyExclusions.interfaceChanged(event.getGroupId(), tick);
		if (event.getGroupId() == InterfaceID.OBJECTBOX)
		{
			// The trident's "You add N charges to the weapon." is an item dialog. Its text may be set after the
			// interface loads, so it is read later on the client thread, as core ItemChargePlugin reads the dialog's
			// item (1.13.4).
			clientThread.invokeLater(this::readObjectboxText);
		}
		if (BankTripCounter.isBankInterface(event.getGroupId()))
		{
			final SessionTracker.State state = tracker.getState();
			final boolean active = state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED;
			if (bankTripCounter.bankOpened(tick, state == SessionTracker.State.RUNNING,
				active ? tracker.getSessionId() : null))
			{
				tracker.addBankTrip();
			}
		}
	}

	/** Client thread. Lets the item dialog's text close a {@link ChargeExclusions} window. */
	private void readObjectboxText()
	{
		final Widget text = client.getWidget(InterfaceID.Objectbox.TEXT);
		if (text != null)
		{
			chargeExclusions.messageSeen(text.getText(), client.getTickCount());
		}
	}

	/**
	 * Client thread. An excluded interface closing; items it moved may only arrive on the next tick. A bank closing
	 * starts the same-trip window.
	 */
	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final int tick = client.getTickCount();
		supplyExclusions.interfaceChanged(event.getGroupId(), tick);
		if (BankTripCounter.isBankInterface(event.getGroupId()))
		{
			bankTripCounter.bankClosed(tick);
		}
	}

	/**
	 * Client thread. A death of the local player: counted while RUNNING ({@link SessionTracker#addDeath}), and the
	 * items that leave the inventory after it are not supplies used. A death of an NPC the player damaged
	 * ({@link #onHitsplatApplied}) is tallied under its name ({@link SessionTracker#addNpcKill}).
	 */
	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!clientStateReady)
		{
			return;
		}
		if (event.getActor() != null && event.getActor() == client.getLocalPlayer())
		{
			supplyExclusions.playerDied(client.getTickCount());
			tracker.addDeath();
		}
		else if (event.getActor() instanceof NPC)
		{
			final NPC npc = (NPC) event.getActor();
			if (damagedNpcs.takeDied(worldViewId(npc), npc.getIndex()))
			{
				// Tallied only while RUNNING (the tracker decides); an NPC outside the Catacombs that has a variant's
				// name is not tallied at all (CatacombsVariants#tallyName).
				tracker.addNpcKill(CatacombsVariants.tallyName(npc.getId(), npc.getName()));
			}
		}
	}

	/**
	 * Client thread. Remembers an NPC the player hit while a session is running, so its death counts as the
	 * player's kill in the session's kills per NPC name ({@link SessionTracker#addNpcKill}). Only the player's own
	 * hitsplats count ({@code Hitsplat.isMine()}); {@link DamagedNpcs} keeps a bounded number of NPCs.
	 */
	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!clientStateReady || !(event.getActor() instanceof NPC) || event.getHitsplat() == null
			|| !event.getHitsplat().isMine() || tracker.getState() != SessionTracker.State.RUNNING)
		{
			return;
		}
		final NPC npc = (NPC) event.getActor();
		damagedNpcs.damaged(worldViewId(npc), npc.getIndex());
	}

	/** Client thread. Forgets a despawned NPC the player damaged: its index can be reused. */
	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (!clientStateReady || event.getNpc() == null)
		{
			return;
		}
		damagedNpcs.forget(worldViewId(event.getNpc()), event.getNpc().getIndex());
	}

	/**
	 * Client thread. The id of the world view {@code npc} is in: NPC indexes are unique only within one world
	 * view (the top-level one, or a boat's), so {@link DamagedNpcs} keeps both. An NPC without a world view is taken
	 * as top-level ({@link WorldView#TOPLEVEL}), the same way on its hit, death and despawn.
	 */
	private static int worldViewId(NPC npc)
	{
		final WorldView worldView = npc.getWorldView();
		return worldView == null ? WorldView.TOPLEVEL : worldView.getId();
	}

	/**
	 * Client thread. Reads this tick's tracked containers and adds what was used to the session (RUNNING only; the
	 * diff and its rules are in {@link SupplyTracker}). The baseline always moves to this tick, so changes made inside
	 * an excluded interface are never counted later. While no session is running (idle, paused or a completion held
	 * for late loot) the containers are not read and the baseline is dropped: nothing would be counted, and Play
	 * (start or resume) takes a fresh baseline ({@link #takeSupplyBaseline}); only the inventory is read, once after it
	 * changes, to note its potions ({@link #notePotionVariants}). Two exceptions keep the old behaviour:
	 * the excluded interfaces are still checked every tick, so one closed just before Play still shields the first
	 * ticks after it; and while a cannon is set up or loaded ({@link #cannonInUse}) the containers are still diffed
	 * (without counting), so cannonballs loaded before Play are still told apart by type
	 * ({@link SupplyTracker}'s cannonball type is inferred from what leaves the inventory on a load).
	 */
	private void trackSupplies()
	{
		final int tick = client.getTickCount();
		boolean excludedOpen = false;
		for (int group : SUPPLY_EXCLUDED_INTERFACES)
		{
			// An interface is open while its root widget is loaded (as core plugins check).
			if (client.getWidget(group, 0) != null)
			{
				excludedOpen = true;
				break;
			}
		}
		supplyExclusions.beginTick(tick, excludedOpen);

		final boolean running = tracker.getState() == SessionTracker.State.RUNNING;
		if (!running && !cannonInUse())
		{
			supplyTracker.reset();
			notePotionVariants();
			return;
		}
		final SupplyTracker.Observation observation = supplyReader.readSupplyObservation();
		if (observation == null)
		{
			supplyTracker.reset();
			return;
		}
		final boolean excluded = supplyExclusions.isTickExcluded(tick);
		// Charged materials are skipped both ways: loading darts is not a use, and unloading them is not a return.
		final SupplyTracker.Usage usage = supplyTracker.update(observation, running, excluded,
			supplyExclusions.droppedItems(), chargeExclusions.excludedItems(tick));
		if (!usage.isEmpty())
		{
			tracker.addSupplies(usage.getUsed(), usage.getReturned(), usage.getDoses());
		}
	}

	/**
	 * Client thread, while no supplies diff runs. The diff used to see the inventory every tick, and each potion's use
	 * is recorded under the highest-dose variant the tracker has seen ({@link SupplyTracker}); so, after the inventory
	 * changed, its items alone are read once and their potions noted. A potion drunk from 4 to 3 doses before
	 * Play is still recorded as the 4-dose item.
	 *
	 * <p>Each read notes every item whose data is loaded. An item whose data is not loaded yet is retried on the next
	 * idle ticks, at most {@link #INVENTORY_NOTE_TRIES} reads per change: apart from a lookup that threw, only a
	 * wieldable item waiting for its item stats can be in that state ({@link SupplyReader#classifyItem}), and that is
	 * never a potion, so stopping loses no potion. Counting is unchanged: the diff classifies every item it sees while
	 * a session runs.</p>
	 */
	private void notePotionVariants()
	{
		if (inventoryNoteTries <= 0)
		{
			return;
		}
		final SupplyTracker.Observation inventory = supplyReader.readInventoryObservation();
		if (inventory == null || supplyTracker.noteVariants(inventory))
		{
			// Not loaded: the client posts ItemContainerChanged when it is. Noted: nothing left to read.
			inventoryNoteTries = 0;
		}
		else
		{
			// Item data not loaded yet: noted again next tick, a few times at most.
			inventoryNoteTries--;
		}
	}

	/** Client thread. The inventory changed: its potions are noted on the next tick no diff runs. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (clientStateReady && event.getContainerId() == InventoryID.INV)
		{
			inventoryNoteTries = INVENTORY_NOTE_TRIES;
		}
	}

	/**
	 * Client thread. Whether the player's cannon is being set up or is set up ({@code DROPCANNON} not 0; core
	 * CannonPlugin treats 4 as placed, 1.13.4) or holds cannonballs ({@code ROCKTHROWER}). A cannon can only be loaded
	 * once it is set up, which takes several ticks, so the supplies diff has a baseline before any load.
	 */
	private boolean cannonInUse()
	{
		return client.getVarpValue(VarPlayerID.DROPCANNON) != 0 || client.getVarpValue(VarPlayerID.ROCKTHROWER) > 0;
	}

	/**
	 * Client thread. Counts this tick's blowpipe shot or trident cast ({@link ChargedWeaponUsage}) from the worn weapon
	 * and cape, the local player's animation and frame, and the trident cast graphic ({@code Actor#hasSpotAnim},
	 * 1.13.4), and adds what it used to the session's supplies. Only while RUNNING: otherwise the carry-overs and the
	 * dart hint are reset, so a stopped or paused session never counts a shot later. Also shows or hides the panel's
	 * "Check your blowpipe" hint.
	 */
	private void trackChargedWeapons()
	{
		final Player player = tracker.getState() == SessionTracker.State.RUNNING ? client.getLocalPlayer() : null;
		if (player == null)
		{
			chargedWeaponUsage.reset();
			publishDartHint(false);
			return;
		}
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		final int weaponId = SupplyReader.wornItemId(worn, EquipmentInventorySlot.WEAPON);
		final int animationId = player.getAnimation();
		boolean tridentGraphic = false;
		if (ChargedWeaponUsage.TRIDENT_ANIMATIONS.contains(animationId))
		{
			for (int graphic : ChargedWeaponUsage.TRIDENT_GRAPHICS)
			{
				tridentGraphic |= player.hasSpotAnim(graphic);
			}
		}
		final Map<Integer, Integer> used = chargedWeaponUsage.update(ChargedWeaponUsage.Tick.builder()
			.tick(client.getTickCount())
			.weaponId(weaponId)
			.animationId(animationId)
			.animationFrame(player.getAnimationFrame())
			.capeId(SupplyReader.wornItemId(worn, EquipmentInventorySlot.CAPE))
			// Dizana's quiver setting (varbit 9803) is not verified in game yet: assume it saves 80%.
			.quiverAmmoSave(null)
			.tridentGraphic(tridentGraphic)
			.vorkathsHeadUpgrade(config.vorkathsHeadUpgrade())
			.dartId(blowpipeDartId)
			.build());
		if (!used.isEmpty())
		{
			final ItemTally items = new ItemTally();
			used.forEach(items::add);
			tracker.addSupplies(items, null, null);
		}
		publishDartHint(chargedWeaponUsage.isDartCheckNeeded() && ChargedWeaponUsage.BLOWPIPES.contains(weaponId));
	}

	/** Client thread. Shows or hides the panel's "Check your blowpipe" hint (on the EDT) when it changes. */
	private void publishDartHint(boolean shown)
	{
		if (shown == dartHintShown)
		{
			return;
		}
		dartHintShown = shown;
		final SlayerLedgerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.setDartHint(shown));
		}
	}

	/**
	 * Client thread. Values the running or paused session's loot and supplies for the panel, at most once every
	 * {@link #SESSION_VALUE_TICKS} ticks. ItemManager is only called here, on the client thread; {@link SessionValuation}
	 * caches unit prices for the session and skips the lookups when nothing changed. Results reach the panel on the
	 * EDT, and only when they differ from what it shows. When no session is active the values are cleared.
	 *
	 * <p>A paused session's loot and supplies can't change, so once it has been valued while paused with every GE price
	 * known, it is not valued again (no copy of its tallies is taken) until it is resumed or the "Loot price" setting
	 * changes. While a price is unavailable it keeps being valued, so the retry can still fill it in.</p>
	 */
	private void updateSessionValues()
	{
		final SessionTracker.State state = tracker.getState();
		if (state != SessionTracker.State.RUNNING && state != SessionTracker.State.PAUSED)
		{
			if (publishedValues != null)
			{
				sessionValuation.reset();
				publishSessionValues(null);
			}
			// The next session is valued on its first tick.
			sessionValueTick = SupplyExclusions.NEVER_TICK;
			pausedValuesSession = null;
			return;
		}
		final LootPriceMode mode = lootPriceMode;
		final GroundItemsHidden hiddenList = groundItemsHidden;
		// A new "Loot price" setting or hidden list is valued at once (once: a failing valuation is still throttled).
		final boolean modeChanged = mode != sessionValueMode || !hiddenList.equals(sessionValueHidden);
		if (state != SessionTracker.State.PAUSED)
		{
			pausedValuesSession = null;
		}
		else if (!modeChanged && pausedValuesSession != null && pausedValuesSession.equals(tracker.getSessionId()))
		{
			// Valued while paused already, in this mode and with every price known: nothing can have changed.
			return;
		}
		final int tick = client.getTickCount();
		// Throttled whether or not the last valuation succeeded, so a failing price lookup is not retried every tick.
		if (!modeChanged && tick >= sessionValueTick && tick - sessionValueTick < SESSION_VALUE_TICKS)
		{
			return;
		}
		sessionValueTick = tick;
		sessionValueMode = mode;
		sessionValueHidden = hiddenList;
		final SessionTracker.Summary active = tracker.activeSummary();
		if (active == null)
		{
			return;
		}
		final SessionValuation.Values values;
		try
		{
			final HiddenLoot hidden = hiddenLoot(active.getLoot() == null ? null : active.getLoot().itemIds());
			values = sessionValuation.update(active.getSessionId(), active.getLoot(), active.getSupplies(),
				active.getSupplyDoses(), mode, hidden, lookups.priceLookup(), tick);
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to value the Slayer Ledger session", e);
			return;
		}
		// The state read above: a session resumed meanwhile is RUNNING on the next tick, which clears this again.
		pausedValuesSession = state == SessionTracker.State.PAUSED && values.getLootUnpriced() == 0
			&& values.getSuppliesUnpriced() == 0 ? active.getSessionId() : null;
		if (!values.equals(publishedValues))
		{
			publishSessionValues(values);
		}
	}

	/** Client thread. Sends the live session values (or {@code null} to clear them) to the panel on the EDT. */
	private void publishSessionValues(SessionValuation.Values values)
	{
		publishedValues = values;
		final SlayerLedgerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.setSessionValues(values));
		}
	}

	/**
	 * Client thread. Takes a fresh supplies baseline now, so nothing from before a Play (start or resume) is counted.
	 */
	private void takeSupplyBaseline()
	{
		if (supplyTracker == null)
		{
			return;
		}
		supplyTracker.reset();
		// Fractional darts and scales from before are not carried into the started or resumed session.
		chargedWeaponUsage.reset();
		final SupplyTracker.Observation observation = supplyReader.readSupplyObservation();
		if (observation != null)
		{
			supplyTracker.update(observation, false, true, Collections.emptySet());
		}
	}

	/**
	 * Client thread. Runs the pending file-restore or re-login check, deferring while the task count still reads
	 * zero (possibly not yet synced) for up to {@link SessionTracker#RESTORE_SYNC_MAX_TICKS} ticks.
	 */
	private void runPendingRestoreCheck(int remaining, int[] counters)
	{
		if (SessionTracker.shouldDeferRestoreCheck(remaining, restoreWaitTicks))
		{
			restoreWaitTicks++;
			return;
		}
		final boolean fileRestore = pendingFileRestore;
		final SessionSnapshot reloginSnapshot = pendingReloginSnapshot;
		pendingFileRestore = false;
		pendingReloginSnapshot = null;

		if (fileRestore)
		{
			// restorePending is cleared when the load is applied.
			loadActiveSession(accountHash);
		}
		if (reloginSnapshot != null)
		{
			try
			{
				if (!tracker.activeSessionStillMatches(reloginSnapshot, counters))
				{
					log.debug("Session {} no longer matches the task after re-login", reloginSnapshot.getSessionId());
					endSession(SaveDecision.EndReason.RESTORE_MISMATCH);
				}
			}
			finally
			{
				restorePending = false;
			}
		}
	}

	/** Client thread. Drops any pending restore check and invalidates in-flight loads (logout, account change). */
	private void cancelPendingRestore()
	{
		pendingFileRestore = false;
		pendingReloginSnapshot = null;
		restoreWaitTicks = 0;
		loadGeneration++;
		restorePending = false;
	}


	// ---- Panel actions (EDT) ----

	boolean play()
	{
		if (!loggedIn || restorePending || !tracker.play(accountHash))
		{
			return false;
		}
		// Supplies count from now: anything used before Play (while idle or paused) is never counted.
		clientThread.invoke(this::takeSupplyBaseline);
		refreshHistoryModel();
		return true;
	}

	void pause()
	{
		tracker.pause();
		refreshHistoryModel();
	}

	void stop()
	{
		endSession(SaveDecision.EndReason.PLAYER_STOP);
		refreshHistoryModel();
	}

	boolean canPlay()
	{
		return loggedIn && !restorePending && tracker.canPlay(accountHash);
	}

	/**
	 * What the task overlay shows, or {@code null} when no running or paused session has a task (idle, a no-task
	 * session, or a completed one held for late loot) and no not-tracking nudge is shown. The task comes from one
	 * {@link SessionTracker#liveTask()} call; the live values and the historical time per kill
	 * ({@link #publishHistoricalPace}) are those last published, used only when they belong to the same session. The
	 * Task row shows the name the task box shows: the Catacombs variant and {@code (cannon)}
	 * ({@link SessionTracker#getCurrentTaskSelection}). While IDLE after a task kill
	 * ({@link TrackingNudge}), only the nudge is shown; it goes as soon as the session is no longer IDLE. Called by the
	 * overlay on the client thread every frame, so it stays cheap.
	 */
	OverlayRows.Data overlayData()
	{
		if (tracker == null || !clientStateReady)
		{
			return null;
		}
		SessionTracker.LiveTask task = tracker.liveTask();
		if (task == null)
		{
			return trackingNudge.isRowShown() && tracker.getState() == SessionTracker.State.IDLE
				? OverlayRows.Data.notTracking() : null;
		}

		SessionValuation.Values values = publishedValues;
		if (values != null && !Objects.equals(task.getSessionId(), values.getSessionId()))
		{
			values = null;
		}
		final OverlayRows.HistoricalPace pace = historicalPace;
		// The variant and cannon use the task box shows. The variant is used only when it is this task's,
		// as a separate call could see a new session; a new session can't have fired a cannonball in between.
		final TaskSelection selection = tracker.getCurrentTaskSelection().forTask(task.getMonster());
		return new OverlayRows.Data(task, values, pace == null ? null : pace.millisPerKillFor(task), selection);
	}

	/**
	 * EDT, from the history model ({@link LedgerHistoryModel#refreshHistoricalPace}) whenever the records, a region
	 * name, the task, its location or the session change; never from a timer. Publishes the historical time per kill
	 * the sidebar's "Time left" uses for the active session, or {@code null} to clear it (no session, or no history for
	 * its task), so the overlay shows the same estimate. Only a volatile write: no other work.
	 */
	void publishHistoricalPace(OverlayRows.HistoricalPace pace)
	{
		historicalPace = pace;
	}

	/**
	 * Puts an item's icon on a sidebar label ({@link ItemIcons}), with the quantity drawn when it is above 1, as
	 * Loot Tracker does. Called on the EDT, as Loot Tracker calls it: unlike the rest of {@code ItemManager},
	 * {@code getImage} may be called from any thread. It returns a cached image at once (blank until drawn) and queues
	 * the sprite drawing to the client thread; {@code addTo} repaints the label once the sprite is drawn.
	 */
	void applyItemIcon(JLabel label, int itemId, int quantity)
	{
		AsyncBufferedImage image = itemManager.getImage(itemId, quantity, quantity > 1);
		if (image != null)
		{
			image.addTo(label);
		}
	}

	/**
	 * Puts a skill's small icon on a sidebar label ({@link SkillIcons}), as the XP tracker shows before a skill's
	 * name; a key that is no {@link Skill} constant (a skill this client does not know) leaves the label without an
	 * icon.
	 *
	 * <p>Checked against RuneLite 1.13.4: {@code SkillIconManager.getSkillImage(Skill skill, boolean small)} returns a
	 * {@code BufferedImage} loaded from the client's {@code skill_icons_small} resources (16 by 16 px, Ranged 18) and
	 * caches it per skill. It reads nothing from the client, so it needs no client thread, but its cache is an
	 * unsynchronized array: it is called only on the EDT, as the XP tracker and Skill Calculator panels call it.</p>
	 */
	void applySkillIcon(JLabel label, String skill)
	{
		if (skill == null)
		{
			return;
		}
		Skill constant;
		try
		{
			constant = Skill.valueOf(skill);
		}
		catch (IllegalArgumentException e)
		{
			return;
		}
		BufferedImage image = skillIconManager.getSkillImage(constant, true);
		if (image != null)
		{
			label.setIcon(new ImageIcon(image));
		}
	}

	/**
	 * Deletes a saved ledger record (history Delete or the partial notice's Discard) on the executor, then reloads
	 * the account's ledger and refreshes the panel. Never touches the active (in-progress) session or its file.
	 */
	void deleteRecord(long account, String id)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.delete(account, id);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to delete Slayer Ledger record", e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.DELETE_FAILED_MESSAGE);
			}
		});
	}

	/**
	 * Deletes an assignment entry (the "Skipped / blocked" section's Delete) on the executor, then shows the account's
	 * entries again. Never touches the records or the active session.
	 */
	void deleteAssignment(long account, String id)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		executor.execute(() ->
		{
			try
			{
				publishAssignments(account, store.deleteAssignment(account, id));
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to delete Slayer Ledger assignment entry", e);
				// Reload so the panel reflects what is actually on disk, then post the error after that update.
				reloadLedger(account);
				publishHistoryError(account, SlayerLedgerPanel.DELETE_ENTRY_FAILED_MESSAGE);
			}
		});
	}

	/**
	 * Sets the note of the session the panel's note box belongs to (see {@link SessionTracker#setNote}). If that
	 * session has ended and was handed off for saving meanwhile (for example the task completed while the player was
	 * typing), the note is written to its saved record instead: via the client thread, so the record's save, which is
	 * queued on the executor from the client thread, is queued first and the note lands after it.
	 */
	void setSessionNote(long account, String sessionId, String note)
	{
		if (sessionId == null || tracker.setNote(sessionId, note))
		{
			return;
		}
		clientThread.invokeLater(() -> editRecordNote(account, sessionId, note));
	}

	/**
	 * Sets (or, with an empty note, clears) the note of a saved ledger record on the executor, then reloads the
	 * account's ledger and refreshes the panel, like {@link #deleteRecord}. A record that no longer exists is left
	 * alone. Never touches the active (in-progress) session or its file.
	 */
	void editRecordNote(long account, String id, String note)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		final String normalized = TaskNote.normalize(note);
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.updateNote(account, id, normalized);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to update the note of Slayer Ledger record", e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.EDIT_NOTE_FAILED_MESSAGE);
			}
		});
	}

	/**
	 * Sets (or, with an empty name, clears) the location name of a saved ledger record on the executor, then reloads
	 * the account's ledger and refreshes the panel, like {@link #editRecordNote}. Only that record's name changes: its
	 * region, the region's name and other records are kept. Never touches the active session.
	 */
	void editRecordLocation(long account, String id, String location)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		final String normalized = TaskLocation.normalizeName(location);
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.updateLocation(account, id, normalized);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to update the location of Slayer Ledger record", e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.EDIT_LOCATION_FAILED_MESSAGE);
			}
		});
	}

	/** Any thread. Shows a non-modal error above the history list, guarded like {@link #publishRecords}. */
	private void publishHistoryError(long account, String message)
	{
		final SlayerLedgerPanel p = panel;
		if (p == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				p.showHistoryError(account, message);
			}
		});
	}

	// ---- Internals ----

	/**
	 * Stops the active session (if any) and handles it according to {@link SaveDecision}. May be called from the
	 * client thread or the EDT; the prompt and notice are always shown on the EDT and file IO runs on the executor.
	 *
	 * @return the pending file write, or {@code null} if nothing is being written yet
	 */
	private Future<?> endSession(SaveDecision.EndReason reason)
	{
		// Any completed session still held for late loot is saved first, as completed. Its write is not returned;
		// ClientShutdown waits for it separately via flushPendingCompletion.
		flushPendingCompletion();
		return handleEndedSession(tracker.stopAndReset(), reason);
	}

	/**
	 * Saves, as completed, a completed session still held for late loot (see {@link SessionTracker#holdCompletion()}),
	 * without waiting for the rest of its grace window. The tracker hands each held session out exactly once.
	 *
	 * @return the pending save, or {@code null} if no session was held
	 */
	private Future<?> flushPendingCompletion()
	{
		return handleEndedSession(tracker.takePendingCompletion(), SaveDecision.EndReason.SYSTEM);
	}

	private Future<?> handleEndedSession(SessionTracker.Summary summary, SaveDecision.EndReason reason)
	{
		if (summary == null)
		{
			return null;
		}
		final long account = summary.getAccountHash();
		final String sessionId = summary.getSessionId();
		switch (SaveDecision.decide(summary, reason, config.confirmIncomplete()))
		{
			case SAVE_COMPLETED:
			{
				final LedgerRecord record = LedgerRecord.fromSummary(summary, false);
				final LootPriceMode mode = lootPriceMode;
				return saveRecord(account, record, () -> announceCompletedTask(record, mode));
			}
			case SAVE_PARTIAL:
				return saveRecord(account, LedgerRecord.fromSummary(summary, true), null);
			case SAVE_PARTIAL_WITH_NOTICE:
			{
				final LedgerRecord record = LedgerRecord.fromSummary(summary, true);
				final SlayerLedgerPanel noticePanel = panel;
				// The notice is posted only after the append succeeds, so a failed save never claims "saved".
				return saveRecord(account, record, noticePanel == null ? null
					: () -> SwingUtilities.invokeLater(() -> noticePanel.showPartialNotice(account, record)));
			}
			case PERSIST_ACTIVE:
				return persistActive(summary);
			case PROMPT:
			{
				final SlayerLedgerPanel promptPanel = panel;
				final BiPredicate<SlayerLedgerPanel, SessionTracker.Summary> dialog = keepIncompleteDialog;
				pendingPrompt.set(summary);
				SwingUtilities.invokeLater(() ->
				{
					boolean keep = promptPanel == null || dialog.test(promptPanel, summary);
					// If shutdown already saved the pending session, compareAndSet fails and nothing is saved twice.
					if (pendingPrompt.compareAndSet(summary, null))
					{
						if (keep)
						{
							saveRecord(account, LedgerRecord.fromSummary(summary, true), null);
						}
						else
						{
							deleteActive(account, sessionId);
						}
					}
				});
				return null;
			}
			case DISCARD:
			default:
				log.debug("Discarding session without a task or account");
				return deleteActive(account, sessionId);
		}
	}

	/**
	 * Any thread. Queues a completed-task summary after its ledger record has been appended successfully; it is worked
	 * out on the client thread, where the loot Ground Items hides is known.
	 */
	private void announceCompletedTask(LedgerRecord record, LootPriceMode mode)
	{
		clientThread.invoke(() ->
		{
			final String message = TaskCompleteMessage.format(record, mode,
				hiddenLoot(record.getLoot() == null ? null : record.getLoot().keySet()));
			if (message == null)
			{
				return;
			}
			postChatLine(message);
			if (config.taskCompleteNotification())
			{
				notifier.notify(message);
			}
		});
	}

	/**
	 * EDT. Queues a new assignment's chat preview ({@link AssignmentPreviewMessage}) like the task-complete
	 * summary, unless the "New-task chat preview" setting was turned off meanwhile.
	 */
	void postAssignmentPreview(String message)
	{
		clientThread.invoke(() ->
		{
			if (config.assignmentPreview())
			{
				postChatLine(message);
			}
		});
	}

	/**
	 * Client thread. Posts one of the plugin's chat lines (task complete, assignment preview, auto-pause, not
	 * tracking) as a console message named "Slayer Ledger". The plain text is always escaped with
	 * {@link Text#escapeJagex}, so any player-typed part (a location name, a note) shows as typed and can't add tags.
	 * The lines are plain text with no markup of their own, so nothing is escaped twice.
	 */
	private void postChatLine(String text)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.name("Slayer Ledger")
			.runeLiteFormattedMessage(Text.escapeJagex(text))
			.build());
	}

	/**
	 * Saves, as partial, a session whose Keep/Discard dialog is still open (client exit or plugin shutdown).
	 *
	 * @return the pending save, or {@code null} if no dialog was pending
	 */
	private Future<?> savePendingPrompt()
	{
		return handleEndedSession(pendingPrompt.getAndSet(null), SaveDecision.EndReason.PROMPT_UNRESOLVED);
	}

	/**
	 * Writes the session as the account's active session file (on the executor). The session is not turned into a
	 * ledger record.
	 */
	private Future<?> persistActive(SessionTracker.Summary summary)
	{
		return persistActive(SessionSnapshot.fromSummary(summary, lastCompletionCounters, System.currentTimeMillis()));
	}

	private Future<?> persistActive(SessionSnapshot snapshot)
	{
		final long account = snapshot.getAccountHash();
		return executor.submit(() ->
		{
			try
			{
				store.writeActive(account, snapshot);
				log.debug("Persisted active Slayer Ledger session {}", snapshot.getSessionId());
			}
			catch (IOException e)
			{
				log.warn("Unable to persist the active Slayer Ledger session", e);
			}
		});
	}

	/**
	 * Client thread. On logout the in-memory session is kept (and auto-paused) but a copy is persisted in case the
	 * client is closed before the next login.
	 */
	private void persistOnLogout()
	{
		final SessionTracker.Summary summary = tracker.activeSummary();
		if (summary != null
			&& SaveDecision.decide(summary, SaveDecision.EndReason.LOGOUT, config.confirmIncomplete())
			== SaveDecision.Action.PERSIST_ACTIVE)
		{
			logoutSnapshot = SessionSnapshot.fromSummary(summary, lastCompletionCounters, System.currentTimeMillis());
			persistActive(logoutSnapshot);
		}
		else
		{
			logoutSnapshot = null;
		}
	}

	/**
	 * Captures the record's item prices on the client thread (prices are recorded as of the save), and its location
	 * name when the task had no assigned area (the player's name for its dominant region, as of the save), then appends
	 * it on the executor and removes the account's active session file if it holds the same session. {@code onSaved},
	 * if given, runs on the executor after a successful append. If pricing fails the record is saved without values.
	 *
	 * @return completes when the write has finished (or failed)
	 */
	private Future<?> saveRecord(long account, LedgerRecord record, Runnable onSaved)
	{
		final CompletableFuture<Void> done = new CompletableFuture<>();
		// Runs immediately when already on the client thread. The client thread keeps running while ClientShutdown
		// consumers are awaited, so this also completes on client exit.
		clientThread.invoke(() ->
		{
			try
			{
				if (record.getLocation() == null && record.getLocationRegion() != null)
				{
					record.setLocation(TaskLocation.recordName(null, lookups.locationName(record.getLocationRegion())));
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Unable to name the location of Slayer Ledger record {}", record.getId(), e);
			}
			try
			{
				record.captureValues(lookups.priceLookup());
			}
			catch (RuntimeException e)
			{
				log.warn("Unable to price Slayer Ledger record {}", record.getId(), e);
			}
			finally
			{
				try
				{
					executor.execute(() ->
					{
						try
						{
							writeRecord(account, record, onSaved);
						}
						finally
						{
							done.complete(null);
						}
					});
				}
				catch (RejectedExecutionException e)
				{
					log.warn("Unable to save Slayer Ledger record {}", record.getId(), e);
					done.completeExceptionally(e);
				}
			}
		});
		return done;
	}

	/**
	 * Executor. Appends the record and removes the matching active session file, then saves any records kept by
	 * earlier failed saves. If the append fails, the record is kept in a side file for the next save or ledger load
	 * ({@link LedgerStore#writeUnsaved}) and the panel shows {@link SlayerLedgerPanel#SAVE_FAILED_MESSAGE}.
	 */
	private void writeRecord(long account, LedgerRecord record, Runnable onSaved)
	{
		List<LedgerRecord> updatedRecords;
		try
		{
			updatedRecords = store.append(account, record);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to save Slayer Ledger record {}; keeping it to save later", record.getId(), e);
			boolean keptRecord = false;
			try
			{
				store.writeUnsaved(account, record);
				keptRecord = true;
			}
			catch (IOException | RuntimeException keepFailure)
			{
				log.warn("Unable to keep unsaved Slayer Ledger record {}", record.getId(), keepFailure);
			}
			if (keptRecord)
			{
				// A stale active file of this session (from a logout mid-task) must not become a second, partial
				// record of it; readActive also ignores a session that is kept.
				try
				{
					store.deleteActive(account, record.getId());
				}
				catch (IOException | RuntimeException deleteFailure)
				{
					log.warn("Unable to remove the active session of kept Slayer Ledger record {}",
						record.getId(), deleteFailure);
				}
			}
			publishHistoryError(account, SlayerLedgerPanel.SAVE_FAILED_MESSAGE);
			return;
		}

		final KeptRecords kept = saveKeptRecords(account);
		if (kept.records != null)
		{
			updatedRecords = kept.records;
		}

		try
		{
			publishRecords(account, updatedRecords);
		}
		catch (RuntimeException e)
		{
			log.warn("Unable to publish saved Slayer Ledger records for account {}", account, e);
		}
		if (kept.failed)
		{
			// Posted after the records' update, so the refresh does not immediately clear it.
			publishHistoryError(account, SlayerLedgerPanel.SAVE_FAILED_MESSAGE);
		}
		// After the append: a crash in between leaves an active file whose id is already in the ledger,
		// which readActive detects and removes instead of restoring it.
		try
		{
			store.deleteActive(account, record.getId());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to remove saved Slayer Ledger active session {}", record.getId(), e);
		}
		if (onSaved != null)
		{
			try
			{
				onSaved.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Unable to run post-save action for Slayer Ledger record {}", record.getId(), e);
			}
		}
	}

	/**
	 * Executor. Appends the records kept by earlier failed saves ({@link LedgerStore#appendUnsaved}). Their post-save
	 * actions (the task-complete chat line) are not run: the task ended earlier.
	 */
	private KeptRecords saveKeptRecords(long account)
	{
		try
		{
			return new KeptRecords(store.appendUnsaved(account), false);
		}
		catch (LedgerStore.UnsavedRecordsException e)
		{
			log.warn("Unable to save kept Slayer Ledger records; keeping them for the next try", e);
			// Any kept records saved before the failure are in the ledger; show them.
			return new KeptRecords(e.getRecords(), true);
		}
		catch (IOException | RuntimeException e)
		{
			// The side files could not be listed (for example no ledger directory), so none are known to be waiting.
			log.warn("Unable to check for kept Slayer Ledger records", e);
			return new KeptRecords(null, false);
		}
	}

	/** The result of {@link #saveKeptRecords}. */
	private static final class KeptRecords
	{
		/** The updated record list, or {@code null} if no kept record was saved. */
		final List<LedgerRecord> records;
		/** Whether a kept record could not be saved and is still waiting. */
		final boolean failed;

		KeptRecords(List<LedgerRecord> records, boolean failed)
		{
			this.records = records;
			this.failed = failed;
		}
	}

	private Future<?> deleteActive(long account, String sessionId)
	{
		if (account == SessionTracker.NO_ACCOUNT || sessionId == null)
		{
			return null;
		}
		return executor.submit(() ->
		{
			try
			{
				store.deleteActive(account, sessionId);
			}
			catch (IOException e)
			{
				log.warn("Unable to delete the active Slayer Ledger session", e);
			}
		});
	}

	/**
	 * Client thread. Loads the account's active session file on the executor, then applies it on the client thread.
	 */
	private void loadActiveSession(long account)
	{
		final int generation = ++loadGeneration;
		executor.execute(() ->
		{
			SessionSnapshot snapshot = null;
			try
			{
				snapshot = store.readActive(account);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to read the active Slayer Ledger session", e);
			}
			finally
			{
				// Always hand back to the client thread so restorePending is cleared.
				final SessionSnapshot loaded = snapshot;
				clientThread.invokeLater(() -> applyActiveSession(account, loaded, generation));
			}
		});
	}

	/**
	 * Client thread. Restores a loaded active session as PAUSED if the task still matches, otherwise saves it as a
	 * partial record with the Discard notice.
	 */
	private void applyActiveSession(long account, SessionSnapshot snapshot, int generation)
	{
		if (generation != loadGeneration)
		{
			// Superseded by a newer load (or cancelled by logout); that one owns restorePending.
			return;
		}
		try
		{
			if (snapshot == null || account != accountHash)
			{
				// Nothing to restore, or another account logged in meanwhile (the file stays for later).
				return;
			}
			if (!tracker.isTaskObserved())
			{
				// Logged out (or switched) before this ran; try again after the next settled observation.
				restoreCheckNeeded = true;
				return;
			}
			final SessionTracker.Summary active = tracker.activeSummary();
			if (active != null && snapshot.getSessionId() != null && snapshot.getSessionId().equals(active.getSessionId()))
			{
				// Already in memory (e.g. a stale load after a quick plugin restart); never turn it into a record too.
				return;
			}
			// The file is per account; it is authoritative for which account the session belongs to.
			snapshot.setAccountHash(account);
			switch (tracker.restore(snapshot, lastCompletionCounters))
			{
				case RESTORED:
					log.debug("Restored Slayer Ledger session {}", snapshot.getSessionId());
					break;
				case REFUSED:
					// A session is active in memory; keep the file and check again after the next login.
					restoreCheckNeeded = true;
					return;
				case MISMATCH:
				default:
					log.debug("Active Slayer Ledger session {} does not match the current task", snapshot.getSessionId());
					handleEndedSession(snapshot.toSummary(), SaveDecision.EndReason.RESTORE_MISMATCH);
					break;
			}
		}
		finally
		{
			restorePending = false;
		}
	}

	/** Loads the account's ledger on the executor and shows it in the panel. */
	private void loadLedger(long account)
	{
		executor.execute(() -> reloadLedger(account));
	}

	/**
	 * Executor. Saves the records kept by earlier failed saves, then reads the account's ledger and shows it in the
	 * panel, or a load-failure message; while a kept record still cannot be saved, the save-failed message too.
	 */
	private void reloadLedger(long account)
	{
		final boolean keptRecordsFailed = saveKeptRecords(account).failed;
		try
		{
			final LedgerStore.Contents contents = store.loadContents(account);
			publishRecords(account, contents.getRecords());
			publishAssignments(account, contents.getAssignments());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to load Slayer Ledger records", e);
			publishHistoryMessage(account, SlayerLedgerPanel.LOAD_FAILED_MESSAGE);
		}
		if (keptRecordsFailed)
		{
			// Posted after the history's update, so the refresh does not immediately clear it.
			publishHistoryError(account, SlayerLedgerPanel.SAVE_FAILED_MESSAGE);
		}
	}

	/**
	 * Any thread. Gives the history model (which the panel shows) an account's records on the EDT, but only if that
	 * account's history is still the one to show when the update runs; results for a previous account or a
	 * logged-out client are dropped.
	 */
	private void publishRecords(long account, List<LedgerRecord> records)
	{
		final LedgerHistoryModel m = historyModel;
		if (m == null)
		{
			return;
		}
		final List<LedgerRecord> copy = new ArrayList<>(records);
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				m.setRecords(account, copy);
			}
		});
	}

	/**
	 * Any thread. Gives the history model an account's entries for the panel's "Skipped / blocked" section, guarded
	 * like {@link #publishRecords}. Entries never go to the played-task history.
	 */
	private void publishAssignments(long account, List<AssignmentEntry> entries)
	{
		final LedgerHistoryModel m = historyModel;
		if (m == null)
		{
			return;
		}
		final List<AssignmentEntry> copy = new ArrayList<>(entries);
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				m.setAssignments(account, copy);
			}
		});
	}

	/** Any thread. Like {@link #publishRecords} but replaces the history with a message. */
	private void publishHistoryMessage(long account, String message)
	{
		final LedgerHistoryModel m = historyModel;
		if (m == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				m.clearRecords(account, message);
			}
		});
	}

	/**
	 * Client thread. Changes whose history the panel shows, clearing it at once (so another account's rows are never
	 * left on screen), and loads the new account's ledger.
	 */
	private void setHistoryAccount(long account)
	{
		if (account == historyAccount)
		{
			return;
		}
		historyAccount = account;
		if (account == SessionTracker.NO_ACCOUNT)
		{
			publishHistoryMessage(account, SlayerLedgerPanel.LOGGED_OUT_MESSAGE);
		}
		else
		{
			publishHistoryMessage(account, SlayerLedgerPanel.LOADING_MESSAGE);
			loadLedger(account);
		}
	}

	/**
	 * Client thread. Detects account changes, persists sessions that belong to another account and loads the
	 * ledger.
	 */
	private void checkAccount()
	{
		final long hash = client.getAccountHash();
		// Also covers re-login to the same account, whose history was hidden at the login screen.
		setHistoryAccount(hash);
		if (hash == accountHash)
		{
			return;
		}
		accountHash = hash;
		tracker.clearCurrentTask();
		// The XP read so far was the previous account's.
		resetXpBaseline();
		// The watched assignment belonged to the previous account.
		assignmentWatch.forget();
		cancelPendingRestore();
		restoreCheckNeeded = true;
		// A completed session held for late loot is saved under its own account, as completed.
		flushPendingCompletion();
		// Another account's session is persisted as that account's active session, not saved as partial.
		handleEndedSession(tracker.stopAndResetIfOtherAccount(hash), SaveDecision.EndReason.ACCOUNT_SWITCH);
		// The region names were the previous account's: an account with no RuneScape profile yet posts no profile
		// change. Forgotten after the saves above (named on this thread, as they ran), so those still get their names.
		forgetLocationNames();
	}

	/**
	 * Client thread, every settled tick. Reads every skill's XP ({@code Client#getSkillExperience}, as core
	 * XpTrackerPlugin reads it) into a reused array and gives it to the tracker ({@link SessionTracker#observeXp}),
	 * keyed by the {@link Skill} constant's name for {@link SkillXp}; {@code null} while the stats are not synced
	 * (Hitpoints XP reads 0, which no synced account has: Hitpoints starts at level 10). A reading equal to the last one
	 * the tracker got is not passed again: the tracker would find no gain and keep an equal baseline, so only
	 * ticks with an XP change build a map. {@link #resetXpBaseline} keeps this in step with the tracker's baseline.
	 */
	private void observeSkillXp()
	{
		if (client.getSkillExperience(Skill.HITPOINTS) <= 0)
		{
			xpSent = false;
			tracker.observeXp(null);
			return;
		}
		for (int i = 0; i < SKILLS.length; i++)
		{
			xpReading[i] = client.getSkillExperience(SKILLS[i]);
		}
		if (xpSent && Arrays.equals(xpReading, xpLastSent))
		{
			return;
		}
		final Map<String, Integer> xp = new HashMap<>();
		for (int i = 0; i < SKILLS.length; i++)
		{
			xp.put(SKILLS[i].name(), xpReading[i]);
		}
		tracker.observeXp(xp);
		System.arraycopy(xpReading, 0, xpLastSent, 0, SKILLS.length);
		xpSent = true;
	}

	/**
	 * Client thread. Drops the tracker's XP baseline ({@link SessionTracker#resetXpBaseline}), so the next settled
	 * reading is only a baseline, and makes {@link #observeSkillXp} pass that reading even if it equals the last one.
	 */
	private void resetXpBaseline()
	{
		tracker.resetXpBaseline();
		xpSent = false;
	}

	private void resetClientState()
	{
		completionSignal.reset();
		// Shown again from the next settled reading; the counter it is for is kept across a hop.
		currentTaskStreak = null;
		// The stats are re-sent after (re)login or a hop: the next settled reading is only a baseline.
		resetXpBaseline();
		taskRewards.reset();
		// Drops an undecided end; the next reading is a baseline. The current assignment is kept (not ended by logout).
		assignmentWatch.reset();
		// The next reading is a baseline too; the nudged assignment is kept, so a relogin onto it is not nudged again.
		trackingNudge.reset();
		settleTicks = LOGIN_SETTLE_TICKS;
		// Containers and the tick count are re-sent after (re)login or a hop; start supplies from a fresh baseline.
		if (supplyTracker != null)
		{
			supplyTracker.reset();
		}
		// Includes the plugin starting while logged in, when no ItemContainerChanged comes for the current inventory.
		inventoryNoteTries = INVENTORY_NOTE_TRIES;
		supplyExclusions.reset();
		chargedWeaponUsage.reset();
		chargeExclusions.reset();
		// NPC indexes are re-sent after (re)login or a hop.
		damagedNpcs.clear();
		// Hidden after a login or hop, and in step with a new panel (startUp), which starts with it hidden.
		publishDartHint(false);
		sessionValueTick = SupplyExclusions.NEVER_TICK;
		// A paused session is valued once more after a login or hop, as on its first tick.
		pausedValuesSession = null;
	}

	/**
	 * Client thread. Assigned task size as computed by core SlayerPlugin (1.13.3): SLAYER_COUNT_ORIGINAL adjusted by
	 * an amount modifier when SLAYER_MODIFIER_ID is 2.
	 */
	private int readOriginalAmount()
	{
		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		if (client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID) == AMOUNT_MODIFIER_ID)
		{
			boolean negative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1;
			int value = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
			amount += negative ? -value : value;
		}
		return amount > 0 ? amount : SessionTracker.UNKNOWN_AMOUNT;
	}

	/**
	 * Client thread. Who assigned the current task: the SLAYER_MASTER varbit and the SLAYER_AREA varp (Konar's
	 * location), with the area named from the SlayerArea DB table as core SlayerPlugin does (1.13.4).
	 */
	private TaskContext readAssignment()
	{
		final int master = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		final int area = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		return TaskContext.assignment(master, area, area > 0 ? dbLookups.lookupAreaName(area) : null);
	}
}

package com.shmayvan.slayerledger;

/**
 * Names of the Slayer masters by the game's SLAYER_MASTER varbit value (4067), which says which master assigned the
 * current task. Pure; no RuneLite types.
 *
 * <p>The values come from the OSRS wiki's page for varbit 4067 ("RuneScape:Varbit/4067", read 2026-10-26). Core
 * RuneLite SlayerPlugin (1.13.4) uses the same values for Krystilia (7) and Mortimer (10) to pick the task streak.
 * Some values are shared by two masters that assign the same tasks (Turael and Aya, for example), so the name shows
 * both. A value not in the table shows as "Unknown master (n)", never as a guessed name.</p>
 */
final class SlayerMaster
{
	/** SLAYER_MASTER value when no task has been assigned (and the value before it has synced). */
	static final int NONE = 0;
	static final int KRYSTILIA = 7;
	static final int KONAR = 8;
	static final int MORTIMER = 10;

	/** Names by SLAYER_MASTER value; index 0 (no task) has none. */
	private static final String[] NAMES = {
		null,
		"Turael/Aya",
		"Mazchna",
		"Vannaka",
		"Chaeldar",
		"Duradel/Kuradal",
		"Nieve/Steve",
		"Krystilia",
		"Konar",
		"Spria",
		"Mortimer",
	};

	private SlayerMaster()
	{
	}

	/** Whether {@code master} names a master: a known (non-{@code null}) value other than {@link #NONE}. */
	static boolean isKnown(Integer master)
	{
		return master != null && master != NONE;
	}

	/**
	 * The master's name, "Unknown master (n)" for a value not in the table, or {@code null} when no master is known
	 * ({@code null} or {@link #NONE}).
	 */
	static String displayName(Integer master)
	{
		if (!isKnown(master))
		{
			return null;
		}
		if (master > 0 && master < NAMES.length)
		{
			return NAMES[master];
		}
		return "Unknown master (" + master + ")";
	}

	/** Whether the value is in the name table (so {@link #displayName} is a real name). */
	static boolean hasName(Integer master)
	{
		return isKnown(master) && master > 0 && master < NAMES.length;
	}
}

package com.shmayvan.slayerledger;

import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JLabel;

/**
 * An item sprite drawn at the size of the sidebar's small icon slot ({@link ItemListView#ICON_WIDTH} by
 * {@link ItemListView#ICON_HEIGHT}, half the 36 by 32 item sprite), for the task icons of Overall totals, so a
 * line with one is no taller or wider than an XP list's skill line. The sprite comes through the item grids' path
 * ({@link ItemIcons}, RuneLite's {@code ItemManager.getImage}, on the EDT) and is scaled as it is painted, so a sprite
 * that arrives later is drawn when the label repaints, as {@link ItemIcons#apply} promises. {@link #getImage()} is the
 * full sprite. The task icons also show in Task history, Skipped / blocked and Trends ({@link #applyTask}),
 * and in the Luck meter's and Trends' choices ({@link TaskIconCache}). EDT only.
 */
final class SmallItemIcon extends ImageIcon
{
	/** An empty slot of the same size, for a task without a known icon, so the names stay aligned. */
	static final Icon EMPTY = new Icon()
	{
		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
		}

		@Override
		public int getIconWidth()
		{
			return ItemListView.ICON_WIDTH;
		}

		@Override
		public int getIconHeight()
		{
			return ItemListView.ICON_HEIGHT;
		}
	};

	private SmallItemIcon(Image image)
	{
		super(image);
	}

	/**
	 * Puts {@code itemId}'s sprite on {@code label} at the small slot size, through {@code icons}; {@link #EMPTY} when
	 * {@code icons} puts no image on it.
	 */
	static void apply(ItemIcons icons, JLabel label, int itemId)
	{
		label.setIcon(null);
		icons.apply(label, itemId, 1);
		Icon full = label.getIcon();
		label.setIcon(full instanceof ImageIcon ? new SmallItemIcon(((ImageIcon) full).getImage()) : EMPTY);
	}

	/**
	 * Puts the icon of the Slayer task {@code task} ({@link TaskIcons}; pass the assigned name, so a Catacombs variant
	 * or cannon task shows its task's) before {@code label}'s text at the small slot size, or {@link #EMPTY} for a name
	 * that is no known task, so the names line up. The label then asks for no width of its own, so the
	 * icon can't widen the sidebar: a long name is cut short in the space its line gives it.
	 */
	static void applyTask(ItemIcons icons, JLabel label, String task)
	{
		label.setIconTextGap(4);
		Integer itemId = TaskIcons.itemId(task);
		if (itemId == null)
		{
			label.setIcon(EMPTY);
		}
		else
		{
			apply(icons, label, itemId);
		}
		label.setPreferredSize(new Dimension(0, label.getPreferredSize().height));
	}

	@Override
	public int getIconWidth()
	{
		return ItemListView.ICON_WIDTH;
	}

	@Override
	public int getIconHeight()
	{
		return ItemListView.ICON_HEIGHT;
	}

	@Override
	public synchronized void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g2.drawImage(getImage(), x, y, getIconWidth(), getIconHeight(), c);
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.shmayvan.slayerledger;

/**
 * The next bonus-points task of a Slayer task streak. Pure; no RuneLite types.
 *
 * <p>Per the OSRS Wiki "Slayer reward point" (revision 15372070, 2026-10-13,
 * https://oldschool.runescape.wiki/w/Slayer_reward_point?oldid=15372070), bonus points are awarded after every 10th,
 * 50th, 100th, 250th and 1,000th completed task in a row, and Krystilia (Wilderness) has a streak of her own. Every one
 * of those is a multiple of 10, so the next bonus task is always the next multiple of 10 (the larger tiers only change
 * how many points it gives, which this does not show). Turael, Aya and Spria give no points, even on a bonus task.</p>
 *
 * <p>The streak counters are those {@link CompletionSignal} reads, in its order: regular ({@link #REGULAR}),
 * Wilderness ({@link #WILDERNESS}) and Mortimer ({@link #MORTIMER}).</p>
 */
final class StreakMilestone
{
	/** No streak counter applies: the master is unknown. */
	static final int NO_COUNTER = CompletionSignal.NO_COUNTER;
	static final int REGULAR = 0;
	static final int WILDERNESS = 1;
	static final int MORTIMER = 2;

	/** Bonus points come every this many tasks in a row. */
	static final int INTERVAL = 10;

	private StreakMilestone()
	{
	}

	/**
	 * The streak counter for a task from {@code master} (a SLAYER_MASTER value): Wilderness for Krystilia, Mortimer's
	 * for Mortimer, regular for the other masters in {@link SlayerMaster}'s table, and {@link #NO_COUNTER} for no
	 * master or one not in the table.
	 */
	static int counterFor(Integer master)
	{
		if (!SlayerMaster.hasName(master))
		{
			return NO_COUNTER;
		}
		switch (master)
		{
			case SlayerMaster.KRYSTILIA:
				return WILDERNESS;
			case SlayerMaster.MORTIMER:
				return MORTIMER;
			default:
				return REGULAR;
		}
	}

	/**
	 * The next bonus task after {@code streak} completed tasks in a row: the smallest multiple of {@link #INTERVAL}
	 * above it, or {@code null} when the streak is unknown ({@code null}, negative) or the next one would overflow.
	 */
	static Integer nextMilestone(Integer streak)
	{
		if (streak == null || streak < 0 || streak > Integer.MAX_VALUE - INTERVAL)
		{
			return null;
		}
		return (streak / INTERVAL + 1) * INTERVAL;
	}

	/**
	 * Whether {@code streak}, a record's streak after its completion ({@link LedgerRecord#getTaskStreak()}), makes that
	 * task a bonus-points task: a positive multiple of {@link #INTERVAL}. {@code false} when the streak is unknown
	 * ({@code null}), 0 or negative. Points/h leaves these tasks out (owner decision): which monster lands on a
	 * bonus task is streak luck, not the monster.
	 */
	static boolean isMilestone(Integer streak)
	{
		return streak != null && streak > 0 && streak % INTERVAL == 0;
	}

	/**
	 * {@code Next bonus: task 50 (in 3)}: the next bonus task and how many tasks are left to it (the current task, when
	 * one is assigned, is the first of them), or {@code null} when the streak is unknown.
	 */
	static String format(Integer streak)
	{
		final Integer next = nextMilestone(streak);
		if (next == null)
		{
			return null;
		}
		return "Next bonus: task " + next + " (in " + (next - streak) + ")";
	}

	/**
	 * {@code bonus in 3}: the short form of {@link #format} for the task box's second line, or {@code null} when the
	 * streak is unknown.
	 */
	static String formatShort(Integer streak)
	{
		final Integer next = nextMilestone(streak);
		if (next == null)
		{
			return null;
		}
		return "bonus in " + (next - streak);
	}
}

package com.shmayvan.slayerledger;

import net.runelite.client.util.Text;

/**
 * Recognises the game message sent when a superior Slayer monster spawns. Pure (RuneLite's static {@link Text} only).
 *
 * <p>The text is the one core SlayerPlugin (RuneLite 1.13.4, {@code CHAT_SUPERIOR_MESSAGE}) notifies on, received as a
 * game or spam message. The game colours it, so colour and other tags are stripped before an exact comparison; core
 * uses {@code contains}, which this deliberately tightens so that, for example, a player's own message quoting the
 * text in another chat type or with extra words is never counted.</p>
 */
final class SuperiorSpawnMessage
{
	static final String TEXT = "A superior foe has appeared...";

	private SuperiorSpawnMessage()
	{
	}

	/**
	 * Whether a chat message announces a superior spawn.
	 *
	 * @param gameOrSpamMessage whether the message type is GAMEMESSAGE or SPAM (as core SlayerPlugin checks)
	 * @param message           the message text, possibly with tags
	 */
	static boolean matches(boolean gameOrSpamMessage, String message)
	{
		return gameOrSpamMessage && message != null && TEXT.equals(Text.removeTags(message).trim());
	}
}

package com.shmayvan.slayerledger;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.InterfaceID;

/**
 * Decides which game ticks, and which items, are left out of supply counting. Pure: the plugin passes in the tick
 * numbers and events it sees (on the client thread) and asks before each supplies diff. Not thread-safe.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>While an excluded interface (see {@link #isExcludedInterface}) is open, and for {@link #INTERFACE_TICKS}
 *     ticks after it was last seen open, opened or closed, the whole tick is excluded.</li>
 *     <li>Dropping a rune pouch excludes the whole tick the same way, because the runes inside leave with it.</li>
 *     <li>For {@link #DEATH_TICKS} ticks after the local player dies the whole tick is excluded (items move to the
 *     gravestone on respawn).</li>
 *     <li>An item on which "Drop" was clicked {@link #DROP_WINDOW_TICKS} ticks ago or less is not a supply.</li>
 * </ul>
 */
final class SupplyExclusions
{
	/** Ticks after an excluded interface was last seen open (or opened or closed) during which nothing is counted. */
	static final int INTERFACE_TICKS = 2;
	/** A decrease of an item is not a supply if "Drop" was clicked on that item this many ticks ago or less. */
	static final int DROP_WINDOW_TICKS = 2;
	/** Ticks after the local player dies during which nothing is counted. */
	static final int DEATH_TICKS = 10;
	/** Far enough in the past that no tick window above includes it, without overflowing tick arithmetic. */
	static final int NEVER_TICK = Integer.MIN_VALUE / 2;

	/** The bank, deposit box and group storage; also counted as bank trips (see {@link BankTripCounter}). */
	private static final int[] BANK_INTERFACES = {
		InterfaceID.BANKMAIN, InterfaceID.BANK_DEPOSITBOX, InterfaceID.SHARED_BANK
	};

	/**
	 * Interfaces that move items without using them (bank, deposit box, group storage, seed vault, Grand Exchange,
	 * shops, trade, Death's office and coffer).
	 */
	private static final int[] EXCLUDED_INTERFACES = {
		InterfaceID.BANKMAIN, InterfaceID.BANK_DEPOSITBOX, InterfaceID.SHARED_BANK, InterfaceID.SEED_VAULT,
		InterfaceID.GE_OFFERS, InterfaceID.GE_COLLECT, InterfaceID.SHOPMAIN, InterfaceID.TRADEMAIN,
		InterfaceID.TRADECONFIRM, InterfaceID.DEATH_OFFICE, InterfaceID.DEATH_COFFER
	};

	/** Tick on which "Drop" was last clicked, per item id; pruned by {@link #beginTick}. */
	private final Map<Integer, Integer> dropTicks = new HashMap<>();
	/** Last tick an excluded interface was open, opened or closed (or a rune pouch was dropped). */
	private int exclusionTick = NEVER_TICK;
	/** Tick the local player last died. */
	private int deathTick = NEVER_TICK;

	/** A copy of the bank interface group ids (the bank, deposit box and group storage), all of them excluded. */
	static int[] bankInterfaces()
	{
		return BANK_INTERFACES.clone();
	}

	/** A copy of the excluded interface group ids. */
	static int[] excludedInterfaces()
	{
		return EXCLUDED_INTERFACES.clone();
	}

	static boolean isExcludedInterface(int groupId)
	{
		for (int group : EXCLUDED_INTERFACES)
		{
			if (group == groupId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * An interface opened (WidgetLoaded) or closed (WidgetClosed) on {@code tick}; excludes the tick if it is an
	 * excluded interface. Covers an interface opened and closed between two ticks, and items it moved that only
	 * arrive on the next tick.
	 */
	void interfaceChanged(int groupId, int tick)
	{
		if (isExcludedInterface(groupId))
		{
			exclusionTick = tick;
		}
	}

	/** "Drop" was clicked on {@code itemId} on {@code tick}; dropping a rune pouch excludes the whole tick. */
	void dropClicked(int itemId, boolean runePouch, int tick)
	{
		dropTicks.put(itemId, tick);
		if (runePouch)
		{
			exclusionTick = tick;
		}
	}

	/** The local player died on {@code tick}. */
	void playerDied(int tick)
	{
		deathTick = tick;
	}

	/**
	 * Start of a supplies diff on {@code tick}: records whether an excluded interface is open now and forgets drop
	 * clicks outside the {@link #DROP_WINDOW_TICKS} window (or from a later tick).
	 */
	void beginTick(int tick, boolean excludedInterfaceOpen)
	{
		if (excludedInterfaceOpen)
		{
			exclusionTick = tick;
		}
		dropTicks.values().removeIf(t -> t > tick || tick - t > DROP_WINDOW_TICKS);
	}

	/** Whether nothing may be counted on {@code tick} (an excluded interface or a rune pouch drop, or a death). */
	boolean isTickExcluded(int tick)
	{
		return tick - exclusionTick <= INTERFACE_TICKS || tick - deathTick <= DEATH_TICKS;
	}

	/** A copy of the item ids dropped within the window, as of the last {@link #beginTick}. */
	Set<Integer> droppedItems()
	{
		return new HashSet<>(dropTicks.keySet());
	}

	/** Forgets everything (login, hop, plugin start): the tick count is re-sent and may restart. */
	void reset()
	{
		dropTicks.clear();
		exclusionTick = NEVER_TICK;
		deathTick = NEVER_TICK;
	}
}

package com.shmayvan.slayerledger;

import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Reads what the player carries for supply counting: the {@link SupplyTracker.Observation} of the tracked
 * containers, and each item's supplies category ({@link #classifyItem}) from its definition. The diff and the counting
 * rules stay in {@link SupplyTracker}; this class only reads the client. Client thread only; the rune pouch's rune ids
 * are cached until {@link #reset()}, which the plugin calls in its startUp client-thread block.
 *
 * <p>Injected by Guice into the plugin, as RuneLite plugins inject their overlays and helpers.
 */
class SupplyReader
{
	/** Rune pouch slots as read by core RunepouchOverlay (1.13.3); the divine rune pouch uses the same varbits. */
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};
	/** Worn slots read for supplies: ammo and thrown weapons, and teleport jewellery used from the equipment tab. */
	private static final EquipmentInventorySlot[] SUPPLY_WORN_SLOTS = {
		EquipmentInventorySlot.AMMO, EquipmentInventorySlot.WEAPON, EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.RING, EquipmentInventorySlot.GLOVES
	};

	private final Client client;
	private final ItemManager itemManager;
	/** Item ids the rune pouch can hold (EnumID.RUNEPOUCH_RUNE values), loaded on first use. */
	private Set<Integer> runePouchRuneIds;

	@Inject
	SupplyReader(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/** Client thread, in the plugin's startUp block: the rune pouch's rune ids are loaded afresh. */
	void reset()
	{
		runePouchRuneIds = null;
	}

	/**
	 * Client thread. The tracked containers: the inventory; the worn ammo and weapon slots (classification keeps only
	 * ammo and stackable thrown weapons) and amulet, ring and gloves slots (classification keeps only charged teleport
	 * jewellery, see {@link SupplyTracker#CHARGED_ITEMS}); Dizana's quiver (the DIZANAS_QUIVER_TEMP_AMMO / _AMOUNT varps,
	 * as core AmmoPlugin reads them); the rune pouch while one is in the inventory (varbits RUNE_POUCH_TYPE_1-6 and
	 * RUNE_POUCH_QUANTITY_1-6 mapped through EnumID.RUNEPOUCH_RUNE, as core RunepouchOverlay does); and the cannon's
	 * loaded ammo (the ROCKTHROWER varp core CannonPlugin reads).
	 *
	 * @return the observation, or {@code null} while the inventory is not loaded
	 */
	SupplyTracker.Observation readSupplyObservation()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return null;
		}
		final SupplyTracker.Observation observation = new SupplyTracker.Observation();
		boolean hasRunePouch = false;
		for (Item item : inventory.getItems())
		{
			observation.add(item.getId(), item.getQuantity());
			hasRunePouch |= isRunePouch(item.getId());
		}

		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			for (EquipmentInventorySlot slot : SUPPLY_WORN_SLOTS)
			{
				final Item item = worn.getItem(slot.getSlotIdx());
				if (item != null)
				{
					observation.add(item.getId(), item.getQuantity());
				}
			}
		}

		final int quiverAmmo = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		final int quiverAmount = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		if (quiverAmmo >= 0 && quiverAmount > 0)
		{
			observation.add(quiverAmmo, quiverAmount);
		}

		if (hasRunePouch)
		{
			final EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			for (int i = 0; runeEnum != null && i < RUNE_POUCH_TYPE_VARBITS.length; i++)
			{
				final int type = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
				final int amount = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[i]);
				if (type != 0 && amount > 0)
				{
					observation.add(runeEnum.getIntValue(type), amount);
				}
			}
		}

		observation.setCannonBalls(client.getVarpValue(VarPlayerID.ROCKTHROWER));
		return observation;
	}

	/**
	 * Client thread. The inventory's items alone (the only place potions are kept), for
	 * {@link SupplyTracker#noteVariants} while no session is running; {@code null} while the inventory is not loaded.
	 */
	SupplyTracker.Observation readInventoryObservation()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return null;
		}
		final SupplyTracker.Observation observation = new SupplyTracker.Observation();
		for (Item item : inventory.getItems())
		{
			observation.add(item.getId(), item.getQuantity());
		}
		return observation;
	}

	/**
	 * Client thread. Supplies category from the item definition: cannonballs by id, runes by the rune pouch enum (or a
	 * name ending in " rune"), ammo by equipment slot (ammo, or a stackable weapon such as darts, knives or
	 * chinchompas), multi-bite food (pies, pizzas and cakes), charged teleport jewellery, the fungicide spray and Slayer
	 * consumables by id, and teleport tablets, potions and food by name and inventory actions (see
	 * {@link SupplyTracker#classify}). Noted items and placeholders are never supplies.
	 *
	 * @return the category, or {@code null} while a wieldable item's stats are not loaded yet (retried later)
	 */
	SupplyTracker.ItemInfo classifyItem(int itemId)
	{
		final ItemComposition comp = itemManager.getItemComposition(itemId);
		if (comp.getNote() != -1 || comp.getPlaceholderTemplateId() != -1)
		{
			return SupplyTracker.ItemInfo.OTHER;
		}
		final String name = comp.getName();
		if (SupplyTracker.classifiesById(itemId))
		{
			// Decided by id alone: no need to wait for the item stats of wearable jewellery.
			return SupplyTracker.classify(itemId, name, comp.getInventoryActions(), false, false, false);
		}
		final boolean cannonball = itemId == SupplyTracker.CANNONBALL || itemId == SupplyTracker.GRANITE_CANNONBALL;
		final boolean rune = runePouchRuneIds().contains(itemId) || (name != null && name.endsWith(" rune"));
		final ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null && !cannonball && !rune && isEquipable(comp.getInventoryActions()))
		{
			// Item stats are loaded asynchronously and may not be available yet; don't let an unloaded wieldable item
			// (possibly ammo) be cached as untracked. SupplyTracker retries a null classification later.
			return null;
		}
		final int slot = stats != null && stats.getEquipment() != null ? stats.getEquipment().getSlot() : -1;
		final boolean ammo = slot == EquipmentInventorySlot.AMMO.getSlotIdx()
			|| (slot == EquipmentInventorySlot.WEAPON.getSlotIdx() && comp.isStackable());
		return SupplyTracker.classify(itemId, name, comp.getInventoryActions(), rune, ammo, cannonball);
	}

	/** Whether inventory actions {@code actions} include "Wield" or "Wear". Pure. */
	static boolean isEquipable(String[] actions)
	{
		if (actions != null)
		{
			for (String action : actions)
			{
				if ("Wield".equals(action) || "Wear".equals(action))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Client thread. Item ids the rune pouch can hold; empty (and retried later) while the enum is unavailable. */
	private Set<Integer> runePouchRuneIds()
	{
		if (runePouchRuneIds != null)
		{
			return runePouchRuneIds;
		}
		final Set<Integer> ids = new HashSet<>();
		final EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runeEnum != null)
		{
			for (int id : runeEnum.getIntVals())
			{
				if (id > 0)
				{
					ids.add(id);
				}
			}
		}
		if (!ids.isEmpty())
		{
			runePouchRuneIds = ids;
		}
		return ids;
	}

	/** Whether {@code itemId} is a rune pouch (regular or divine, either version) whose runes are read. Pure. */
	static boolean isRunePouch(int itemId)
	{
		return itemId == ItemID.BH_RUNE_POUCH || itemId == ItemID.BH_RUNE_POUCH_TROUVER
			|| itemId == ItemID.DIVINE_RUNE_POUCH || itemId == ItemID.DIVINE_RUNE_POUCH_TROUVER;
	}

	/** The item worn in {@code slot} of {@code worn}, or {@link ChargedWeaponUsage#NO_ITEM}. Pure. */
	static int wornItemId(ItemContainer worn, EquipmentInventorySlot slot)
	{
		final Item item = worn != null ? worn.getItem(slot.getSlotIdx()) : null;
		return item != null ? item.getId() : ChargedWeaponUsage.NO_ITEM;
	}
}

package com.shmayvan.slayerledger;

import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;

/**
 * Suggested supplies and bank trips for the kills left on a task, from the completed-task history of
 * {@link TaskStatistics}. Each amount is a pooled total per kill scaled to the kills and rounded up to a whole tracked
 * unit (item, dose, bite or charge), in whole numbers so no floating-point error adds a unit.
 */
final class SupplyRecommendation
{
	private SupplyRecommendation()
	{
	}

	/**
	 * Scales the pooled supply totals to {@code kills}: {@code ceil(total * kills / supplyKills)} per item, over the
	 * records with supplies or values. Bank trips are pooled the same way, over the kills of the records with a known
	 * count. Returns {@code null} when neither has a sample; a metric without samples stays unknown.
	 */
	static Estimate forTask(TaskStatistics stats, int kills)
	{
		if (stats == null || kills <= 0)
		{
			return null;
		}

		Map<Integer, Long> supplies = new TreeMap<>();
		long supplyKills = stats.getSupplyKills();
		boolean suppliesKnown = stats.getSupplySampleCount() > 0 && supplyKills > 0;
		if (suppliesKnown)
		{
			for (Map.Entry<Integer, Long> item : stats.getSupplyTotals().entrySet())
			{
				supplies.put(item.getKey(), scaleUp(item.getValue(), kills, supplyKills));
			}
		}

		long bankTripKills = stats.getBankTripKills();
		Long bankTrips = stats.getBankTripSampleCount() > 0 && bankTripKills > 0
			? scaleUp(stats.getBankTripTotal(), kills, bankTripKills) : null;
		if (!suppliesKnown && bankTrips == null)
		{
			return null;
		}
		return new Estimate(kills, supplies, suppliesKnown ? stats.getSupplySampleCount() : 0, supplyKills,
			bankTrips, stats.getBankTripSampleCount(), bankTripKills);
	}

	/**
	 * {@code ceil(total * kills / sampleKills)} in exact integer arithmetic, saturating at {@link Long#MAX_VALUE}
	 * when the product overflows; 0 for a non-positive total.
	 */
	static long scaleUp(long total, long kills, long sampleKills)
	{
		if (total <= 0 || kills <= 0 || sampleKills <= 0)
		{
			return 0;
		}
		long product;
		try
		{
			product = Math.multiplyExact(total, kills);
		}
		catch (ArithmeticException e)
		{
			return Long.MAX_VALUE;
		}
		long quotient = product / sampleKills;
		return product % sampleKills == 0 ? quotient : quotient + 1;
	}

	static final class Estimate
	{
		private final int kills;
		private final Map<Integer, Long> supplies;
		private final int supplySampleCount;
		private final long supplyKills;
		private final Long bankTrips;
		private final int bankTripSampleCount;
		private final long bankTripKills;

		private Estimate(int kills, Map<Integer, Long> supplies, int supplySampleCount, long supplyKills,
			Long bankTrips, int bankTripSampleCount, long bankTripKills)
		{
			this.kills = kills;
			this.supplies = Collections.unmodifiableMap(new TreeMap<>(supplies));
			this.supplySampleCount = supplySampleCount;
			this.supplyKills = supplyKills;
			this.bankTrips = bankTrips;
			this.bankTripSampleCount = bankTripSampleCount;
			this.bankTripKills = bankTripKills;
		}

		/** The kills the amounts are for (the kills left). */
		int getKills()
		{
			return kills;
		}

		/** Suggested amount by item id, in the id's tracked unit; empty when the history used no tracked supplies. */
		Map<Integer, Long> getSupplies()
		{
			return supplies;
		}

		/** Records behind the supply amounts; 0 when none has supplies or values (the amounts are unknown). */
		int getSupplySampleCount()
		{
			return supplySampleCount;
		}

		/** Kills of the records behind the supply amounts. */
		long getSupplyKills()
		{
			return supplyKills;
		}

		/** Suggested bank trips, or {@code null} when no record has a known count. */
		Long getBankTrips()
		{
			return bankTrips;
		}

		int getBankTripSampleCount()
		{
			return bankTripSampleCount;
		}

		/** Kills of the records behind the bank-trip suggestion. */
		long getBankTripKills()
		{
			return bankTripKills;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * Pure per-tick supplies diff. The plugin reads the player's item containers once per game tick into an
 * {@link Observation} (inventory, worn ammo, weapon, amulet, ring and gloves slots, Dizana's quiver, rune pouch, and the
 * cannon's loaded ammo); this class compares it with the previous tick and reports what was used. No RuneLite dependencies; item
 * facts come from a {@link Classifier} the plugin backs with {@code ItemComposition} on the client thread.
 *
 * <p>All tracked containers are summed into one virtual container before diffing, so moving items between them nets
 * to zero: filling or emptying the rune pouch, equipping ammo from the inventory, loading the quiver, and loading or
 * picking up the cannon. Only these categories are tracked; every other item is ignored:</p>
 * <ul>
 *     <li>{@link Category#FOOD}: items with an "Eat" or "Drink" inventory action that are not potions. Food eaten in
 *     parts (pies, pizzas and cakes, see {@link #MULTI_BITE_FOOD}) is tracked in bites per food, like potion doses:
 *     eating a whole pizza (2 to 1 bite, then 1 to 0) uses two bites, which are worth one pizza.</li>
 *     <li>{@link Category#POTION}: items named {@code Name(n)} with a "Drink" action. Tracked in doses per family
 *     ({@code Name}), so a drink (4 to 3) uses one dose and decanting, which keeps the family's total doses, nets to
 *     zero.</li>
 *     <li>{@link Category#RUNE}, {@link Category#AMMO} and {@link Category#CANNONBALL}, as decided by the plugin.</li>
 *     <li>{@link Category#SLAYER_CONSUMABLE}: bags of salt and ice coolers ({@link #SLAYER_CONSUMABLES}), one per item
 *     used.</li>
 *     <li>{@link Category#TELEPORT_TABLET}: items with a "Break" inventory action whose name contains "teleport" (for
 *     example "Varrock teleport", "Teleport to house" or "Salve graveyard teleport"), one per tablet broken.</li>
 *     <li>{@link Category#CHARGES}: teleport jewellery and the fungicide spray ({@link #CHARGED_ITEMS}), tracked in
 *     charges per item type like potion doses and recorded under the item's highest-charge variant. Using a charge (8
 *     to 7) uses one charge, and so does the last one, whether the item then crumbles (ring of dueling, games
 *     necklace) or becomes an uncharged variant, which is not a supply (amulet of glory, "Fungicide spray 0").
 *     Recharging (the Fountain of Heroes, refilling the spray) is an increase, so it is ignored. The refill item
 *     ("Fungicide") is not a supply, so a spray's cost is counted once, per charge sprayed.</li>
 * </ul>
 *
 * <p>A net decrease is a use, except for items dropped on this tick (see {@link #update}). A net increase is ignored
 * (it is loot or a withdrawal), except that an increase of ammo or cannonballs is reported as
 * {@link Usage#getReturned() returned}: picked-up ammo, or cannonballs back from the cannon, offset what was counted as
 * used before (the session never lets that go below zero).</p>
 *
 * <p>The cannon's loaded ammo is counted as the cannonball type that left the inventory when it was loaded. When
 * tracking starts with the cannon already loaded, the type is unknown and regular cannonballs are assumed until a load
 * or pickup shows it. If the cannon's pickup or unload (or a further load) shows the other type, the assumption is
 * corrected: its load moves to that type, so picking up a cannon that has not fired counts nothing, and cannonballs
 * fired since the last {@link #reset()} under the assumed type move to that type too. A pickup or unload shows
 * the type only when more than half of the cannon's last seen load comes back as it, so shots fired on the pickup tick
 * are allowed for, while fewer cannonballs looted as the cannon empties are not taken for its type.</p>
 *
 * <p>Not thread-safe; the plugin uses it on the client thread only.</p>
 */
final class SupplyTracker
{
	/** {@code net.runelite.api.gameval.ItemID.MCANNONBALL} (1.13.3), the default for the cannon's loaded ammo. */
	static final int CANNONBALL = 2;
	/** {@code net.runelite.api.gameval.ItemID.GRANITE_CANNONBALL} (1.13.3). */
	static final int GRANITE_CANNONBALL = 21728;

	/** Potion names end in the dose count, for example "Prayer potion(4)". */
	private static final Pattern DOSE_NAME = Pattern.compile("^(.+)\\((\\d)\\)$");

	/**
	 * Food eaten in parts, by the id of each stage: {full item id, bites left in this stage, bites in a full item}. The
	 * ids are the RuneLite 1.13.4 {@code net.runelite.api.gameval.ItemID} constants (unnoted; noted items are never
	 * supplies). What is left after the last bite of a pie (the pie dish) has no "Eat" action, so it is not a supply.
	 */
	static final Map<Integer, int[]> MULTI_BITE_FOOD = multiBiteFood();

	private static Map<Integer, int[]> multiBiteFood()
	{
		final Map<Integer, int[]> food = new HashMap<>();
		// Pizzas: full, then 1/2.
		addStages(food, ItemID.PLAIN_PIZZA, ItemID.HALF_PLAIN_PIZZA);
		addStages(food, ItemID.MEAT_PIZZA, ItemID.HALF_MEAT_PIZZA);
		addStages(food, ItemID.ANCHOVIE_PIZZA, ItemID.HALF_ANCHOVIE_PIZZA);
		addStages(food, ItemID.PINEAPPLE_PIZZA, ItemID.HALF_PINEAPPLE_PIZZA);
		// Pies: full, then half (then the pie dish, which is not food).
		addStages(food, ItemID.REDBERRY_PIE, ItemID.HALF_A_REDBERRY_PIE);
		addStages(food, ItemID.MEAT_PIE, ItemID.HALF_A_MEAT_PIE);
		addStages(food, ItemID.APPLE_PIE, ItemID.HALF_AN_APPLE_PIE);
		addStages(food, ItemID.GARDEN_PIE, ItemID.HALF_GARDEN_PIE);
		addStages(food, ItemID.FISH_PIE, ItemID.HALF_FISH_PIE);
		addStages(food, ItemID.BOTANICAL_PIE, ItemID.HALF_BOTANICAL_PIE);
		addStages(food, ItemID.MUSHROOM_PIE, ItemID.HALF_MUSHROOM_PIE);
		addStages(food, ItemID.ADMIRAL_PIE, ItemID.HALF_ADMIRAL_PIE);
		addStages(food, ItemID.DRAGONFRUIT_PIE, ItemID.HALF_DRAGONFRUIT_PIE);
		addStages(food, ItemID.WILD_PIE, ItemID.HALF_WILD_PIE);
		addStages(food, ItemID.SUMMER_PIE, ItemID.HALF_SUMMER_PIE);
		// Cakes: full, then 2/3, then a slice.
		addStages(food, ItemID.CAKE, ItemID.PARTIAL_CAKE, ItemID.CAKE_SLICE);
		addStages(food, ItemID.CHOCOLATE_CAKE, ItemID.PARTIAL_CHOCOLATE_CAKE, ItemID.CHOCOLATE_SLICE);
		return Collections.unmodifiableMap(food);
	}

	/**
	 * Items used per charge, by the id of each charged variant: {highest-charge item id, charges left, charges in the
	 * highest-charge item}. One family per item type; the trimmed glory and the imbued ring of wealth are families of
	 * their own. Uncharged variants ("Amulet of glory", "Skills necklace", "Fungicide spray 0" and so on) are not
	 * listed, so they are not supplies, and neither are items that never run out (amulet of eternal glory, slayer ring
	 * (eternal)). The ids are the RuneLite 1.13.4 {@code net.runelite.api.gameval.ItemID} constants, with the charges
	 * core {@code ItemWithCharge} gives them (its TELEPORT and FUNGICIDE_SPRAY types).
	 */
	static final Map<Integer, int[]> CHARGED_ITEMS = chargedItems();

	private static Map<Integer, int[]> chargedItems()
	{
		final Map<Integer, int[]> items = new HashMap<>();
		addStages(items, ItemID.RING_OF_DUELING_8, ItemID.RING_OF_DUELING_7, ItemID.RING_OF_DUELING_6,
			ItemID.RING_OF_DUELING_5, ItemID.RING_OF_DUELING_4, ItemID.RING_OF_DUELING_3, ItemID.RING_OF_DUELING_2,
			ItemID.RING_OF_DUELING_1);
		// Games necklace.
		addStages(items, ItemID.NECKLACE_OF_MINIGAMES_8, ItemID.NECKLACE_OF_MINIGAMES_7,
			ItemID.NECKLACE_OF_MINIGAMES_6, ItemID.NECKLACE_OF_MINIGAMES_5, ItemID.NECKLACE_OF_MINIGAMES_4,
			ItemID.NECKLACE_OF_MINIGAMES_3, ItemID.NECKLACE_OF_MINIGAMES_2, ItemID.NECKLACE_OF_MINIGAMES_1);
		addStages(items, ItemID.AMULET_OF_GLORY_6, ItemID.AMULET_OF_GLORY_5, ItemID.AMULET_OF_GLORY_4,
			ItemID.AMULET_OF_GLORY_3, ItemID.AMULET_OF_GLORY_2, ItemID.AMULET_OF_GLORY_1);
		// Amulet of glory (t).
		addStages(items, ItemID.TRAIL_AMULET_OF_GLORY_6, ItemID.TRAIL_AMULET_OF_GLORY_5,
			ItemID.TRAIL_AMULET_OF_GLORY_4, ItemID.TRAIL_AMULET_OF_GLORY_3, ItemID.TRAIL_AMULET_OF_GLORY_2,
			ItemID.TRAIL_AMULET_OF_GLORY_1);
		// Skills necklace.
		addStages(items, ItemID.JEWL_NECKLACE_OF_SKILLS_6, ItemID.JEWL_NECKLACE_OF_SKILLS_5,
			ItemID.JEWL_NECKLACE_OF_SKILLS_4, ItemID.JEWL_NECKLACE_OF_SKILLS_3, ItemID.JEWL_NECKLACE_OF_SKILLS_2,
			ItemID.JEWL_NECKLACE_OF_SKILLS_1);
		// Combat bracelet.
		addStages(items, ItemID.JEWL_BRACELET_OF_COMBAT_6, ItemID.JEWL_BRACELET_OF_COMBAT_5,
			ItemID.JEWL_BRACELET_OF_COMBAT_4, ItemID.JEWL_BRACELET_OF_COMBAT_3, ItemID.JEWL_BRACELET_OF_COMBAT_2,
			ItemID.JEWL_BRACELET_OF_COMBAT_1);
		addStages(items, ItemID.RING_OF_WEALTH_5, ItemID.RING_OF_WEALTH_4, ItemID.RING_OF_WEALTH_3,
			ItemID.RING_OF_WEALTH_2, ItemID.RING_OF_WEALTH_1);
		// Ring of wealth (i).
		addStages(items, ItemID.RING_OF_WEALTH_I5, ItemID.RING_OF_WEALTH_I4, ItemID.RING_OF_WEALTH_I3,
			ItemID.RING_OF_WEALTH_I2, ItemID.RING_OF_WEALTH_I1);
		addStages(items, ItemID.NECKLACE_OF_PASSAGE_5, ItemID.NECKLACE_OF_PASSAGE_4, ItemID.NECKLACE_OF_PASSAGE_3,
			ItemID.NECKLACE_OF_PASSAGE_2, ItemID.NECKLACE_OF_PASSAGE_1);
		// Digsite pendant.
		addStages(items, ItemID.NECKLACE_OF_DIGSITE_5, ItemID.NECKLACE_OF_DIGSITE_4, ItemID.NECKLACE_OF_DIGSITE_3,
			ItemID.NECKLACE_OF_DIGSITE_2, ItemID.NECKLACE_OF_DIGSITE_1);
		addStages(items, ItemID.BURNING_AMULET_5, ItemID.BURNING_AMULET_4, ItemID.BURNING_AMULET_3,
			ItemID.BURNING_AMULET_2, ItemID.BURNING_AMULET_1);
		addStages(items, ItemID.SLAYER_RING_8, ItemID.SLAYER_RING_7, ItemID.SLAYER_RING_6, ItemID.SLAYER_RING_5,
			ItemID.SLAYER_RING_4, ItemID.SLAYER_RING_3, ItemID.SLAYER_RING_2, ItemID.SLAYER_RING_1);
		addStages(items, ItemID.RING_OF_RETURNING_5, ItemID.RING_OF_RETURNING_4, ItemID.RING_OF_RETURNING_3,
			ItemID.RING_OF_RETURNING_2, ItemID.RING_OF_RETURNING_1);
		// Fungicide spray 10 down to 1 ("Fungicide spray 0" is empty).
		addStages(items, ItemID.SLAYER_SPRAY_PUMP_10, ItemID.SLAYER_SPRAY_PUMP_9, ItemID.SLAYER_SPRAY_PUMP_8,
			ItemID.SLAYER_SPRAY_PUMP_7, ItemID.SLAYER_SPRAY_PUMP_6, ItemID.SLAYER_SPRAY_PUMP_5,
			ItemID.SLAYER_SPRAY_PUMP_4, ItemID.SLAYER_SPRAY_PUMP_3, ItemID.SLAYER_SPRAY_PUMP_2,
			ItemID.SLAYER_SPRAY_PUMP_1);
		return Collections.unmodifiableMap(items);
	}

	/**
	 * Slayer items used up one per use: the bag of salt ({@code SLAYER_BAG_OF_SALT}) and the ice cooler
	 * ({@code SLAYER_ICY_WATER}), RuneLite 1.13.4 {@code net.runelite.api.gameval.ItemID} constants. Tools that are not
	 * used up, such as the rock hammer, are not supplies.
	 */
	static final Set<Integer> SLAYER_CONSUMABLES = Collections.unmodifiableSet(
		new HashSet<>(Arrays.asList(ItemID.SLAYER_BAG_OF_SALT, ItemID.SLAYER_ICY_WATER)));

	/** Adds an item's stages, from the full item down to the last bite (or charge). */
	private static void addStages(Map<Integer, int[]> food, int... stages)
	{
		for (int i = 0; i < stages.length; i++)
		{
			food.put(stages[i], new int[]{stages[0], stages.length - i, stages.length});
		}
	}

	/** How an item is tracked. */
	enum Category
	{
		FOOD,
		POTION,
		RUNE,
		AMMO,
		CANNONBALL,
		/** Bags of salt and ice coolers; see {@link #SLAYER_CONSUMABLES}. */
		SLAYER_CONSUMABLE,
		/** Teleport tablets: a "Break" action and "teleport" in the name. */
		TELEPORT_TABLET,
		/** Teleport jewellery and the fungicide spray, in charges; see {@link #CHARGED_ITEMS}. */
		CHARGES,
		/** Not a supply; ignored. */
		OTHER
	}

	/** What the tracker needs to know about one item id. */
	static final class ItemInfo
	{
		static final ItemInfo OTHER = new ItemInfo(Category.OTHER, null, 0);

		private final Category category;
		private final String family;
		private final int doses;
		/**
		 * Item a multi-bite food's bites (or a charged item's charges) are recorded under, or -1 (potions use their
		 * highest-dose variant seen).
		 */
		private final int fullItemId;
		/** Bites (or charges) in one {@link #fullItemId} item, or 0. */
		private final int dosesPerItem;

		ItemInfo(Category category, String family, int doses)
		{
			this(category, family, doses, -1, 0);
		}

		private ItemInfo(Category category, String family, int doses, int fullItemId, int dosesPerItem)
		{
			this.category = Objects.requireNonNull(category);
			this.family = family;
			this.doses = doses;
			this.fullItemId = fullItemId;
			this.dosesPerItem = dosesPerItem;
		}

		static ItemInfo of(Category category)
		{
			return new ItemInfo(category, null, 0);
		}

		static ItemInfo potion(String family, int doses)
		{
			return new ItemInfo(Category.POTION, family, doses);
		}

		/**
		 * One stage of a food eaten in parts: food tracked in bites, in one family per full item, and recorded under the
		 * full item with {@code bitesPerItem} bites per item.
		 */
		static ItemInfo multiBiteFood(int fullItemId, int bitesLeft, int bitesPerItem)
		{
			return new ItemInfo(Category.FOOD, "bites:" + fullItemId, bitesLeft, fullItemId, bitesPerItem);
		}

		/**
		 * One variant of a charged item: tracked in charges, in one family per item type, and recorded under the
		 * highest-charge item {@code fullItemId} with {@code chargesPerItem} charges per item.
		 */
		static ItemInfo charged(int fullItemId, int chargesLeft, int chargesPerItem)
		{
			return new ItemInfo(Category.CHARGES, "charges:" + fullItemId, chargesLeft, fullItemId, chargesPerItem);
		}

		Category getCategory()
		{
			return category;
		}

		/**
		 * Family tracked in doses (or bites), or {@code null}: a potion's name without the dose suffix, or one key per
		 * full item for food eaten in parts.
		 */
		String getFamily()
		{
			return family;
		}

		/** Doses in one potion item, or bites left in one stage of a multi-bite food; 0 otherwise. */
		int getDoses()
		{
			return doses;
		}

		/** Full item a multi-bite food's bites are recorded under, or -1. */
		int getFullItemId()
		{
			return fullItemId;
		}

		/** Bites in one {@link #getFullItemId() full item}, or 0. */
		int getDosesPerItem()
		{
			return dosesPerItem;
		}
	}

	/** Item facts source. Implementations may only be valid on a particular thread (the plugin's: the client thread). */
	interface Classifier
	{
		ItemInfo classify(int itemId);
	}

	/**
	 * Classifies an item from its definition. Rune, ammo and cannonball are decided by the caller (they need lookups
	 * this class cannot do) and take precedence. A teleport tablet has a "Break" action and "teleport" in its name; a
	 * potion is a {@code Name(n)} item with a "Drink" action; food is any other item with an "Eat" or "Drink" action.
	 * Noted items have no inventory actions, so they are never supplies.
	 *
	 * @param name             item name, or {@code null}
	 * @param inventoryActions inventory actions, entries may be {@code null}
	 */
	static ItemInfo classify(String name, String[] inventoryActions, boolean rune, boolean ammo, boolean cannonball)
	{
		return classify(-1, name, inventoryActions, rune, ammo, cannonball);
	}

	/**
	 * Like {@link #classify(String, String[], boolean, boolean, boolean)}, except that some items are classified by
	 * their id first (see {@link #classifiesById}): a stage of a food eaten in parts ({@link #MULTI_BITE_FOOD}) as
	 * {@link ItemInfo#multiBiteFood multi-bite food}, a charged item ({@link #CHARGED_ITEMS}) as
	 * {@link ItemInfo#charged charges}, and a {@link #SLAYER_CONSUMABLES Slayer consumable}.
	 */
	static ItemInfo classify(int itemId, String name, String[] inventoryActions, boolean rune, boolean ammo,
		boolean cannonball)
	{
		final int[] stage = MULTI_BITE_FOOD.get(itemId);
		if (stage != null)
		{
			return ItemInfo.multiBiteFood(stage[0], stage[1], stage[2]);
		}
		final int[] charges = CHARGED_ITEMS.get(itemId);
		if (charges != null)
		{
			return ItemInfo.charged(charges[0], charges[1], charges[2]);
		}
		if (SLAYER_CONSUMABLES.contains(itemId))
		{
			return ItemInfo.of(Category.SLAYER_CONSUMABLE);
		}
		if (cannonball)
		{
			return ItemInfo.of(Category.CANNONBALL);
		}
		if (rune)
		{
			return ItemInfo.of(Category.RUNE);
		}
		if (ammo)
		{
			return ItemInfo.of(Category.AMMO);
		}
		if (hasAction(inventoryActions, "Break") && name != null && name.toLowerCase(Locale.ROOT).contains("teleport"))
		{
			return ItemInfo.of(Category.TELEPORT_TABLET);
		}
		final boolean eat = hasAction(inventoryActions, "Eat");
		final boolean drink = hasAction(inventoryActions, "Drink");
		if (drink && name != null)
		{
			final Matcher m = DOSE_NAME.matcher(name.trim());
			if (m.matches())
			{
				final int doses = Integer.parseInt(m.group(2));
				if (doses > 0)
				{
					return ItemInfo.potion(m.group(1).trim(), doses);
				}
			}
		}
		return eat || drink ? ItemInfo.of(Category.FOOD) : ItemInfo.OTHER;
	}

	/**
	 * Whether {@link #classify(int, String, String[], boolean, boolean, boolean)} decides this id from its tables alone
	 * (multi-bite food, charged items and Slayer consumables), so the caller needs no other lookups for it.
	 */
	static boolean classifiesById(int itemId)
	{
		return MULTI_BITE_FOOD.containsKey(itemId) || CHARGED_ITEMS.containsKey(itemId)
			|| SLAYER_CONSUMABLES.contains(itemId);
	}

	private static boolean hasAction(String[] actions, String action)
	{
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (a != null && a.equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	/** One tick's view of the tracked containers. Quantities of the same id are summed. */
	static final class Observation
	{
		private final Map<Integer, Long> items = new TreeMap<>();
		private int cannonBalls;

		/** Adds an item stack. Negative ids (empty slots) and non-positive quantities are ignored. */
		Observation add(int itemId, long quantity)
		{
			if (itemId >= 0 && quantity > 0)
			{
				items.merge(itemId, quantity, Long::sum);
			}
			return this;
		}

		/** Cannonballs loaded in the player's cannon (the ROCKTHROWER varp); 0 when none or no cannon. */
		Observation setCannonBalls(int cannonBalls)
		{
			this.cannonBalls = Math.max(0, cannonBalls);
			return this;
		}

		Map<Integer, Long> getItems()
		{
			return Collections.unmodifiableMap(items);
		}

		int getCannonBalls()
		{
			return cannonBalls;
		}
	}

	/** Supplies used on one tick. */
	static final class Usage
	{
		static final Usage NONE = new Usage(new ItemTally(), new ItemTally(), Collections.emptyMap());

		private final ItemTally used;
		private final ItemTally returned;
		private final Map<Integer, Integer> doses;

		Usage(ItemTally used, ItemTally returned, Map<Integer, Integer> doses)
		{
			this.used = used;
			this.returned = returned;
			this.doses = doses;
		}

		/**
		 * Items used, by item id. Potions are in doses, keyed by the highest-dose variant seen of their family,
		 * multi-bite food is in bites, keyed by the full item, and charged items are in charges, keyed by the
		 * highest-charge item; see {@link #getDoses()}.
		 */
		ItemTally getUsed()
		{
			return new ItemTally(used);
		}

		/** Ammo and cannonballs that came back (picked up or unloaded), by item id. */
		ItemTally getReturned()
		{
			return new ItemTally(returned);
		}

		/** Doses (bites, charges) per item for every potion, multi-bite food and charged item id in {@link #getUsed()}. */
		Map<Integer, Integer> getDoses()
		{
			return new TreeMap<>(doses);
		}

		boolean isEmpty()
		{
			return used.isEmpty() && returned.isEmpty();
		}
	}

	/** Identifies one tracked quantity: an item id, or a potion or multi-bite food family (in doses or bites). */
	private static final class Key
	{
		private final int itemId;
		private final String family;

		private Key(int itemId, String family)
		{
			this.itemId = itemId;
			this.family = family;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Key))
			{
				return false;
			}
			Key k = (Key) o;
			return family != null ? family.equals(k.family) : k.family == null && itemId == k.itemId;
		}

		@Override
		public int hashCode()
		{
			return family != null ? family.hashCode() : Integer.hashCode(itemId);
		}
	}

	private final Classifier classifier;
	/** Classifications by item id; item definitions do not change while the client runs. */
	private final Map<Integer, ItemInfo> infoCache = new HashMap<>();
	/** Category of every key seen. */
	private final Map<Key, Category> keyCategories = new HashMap<>();
	/**
	 * Item each family's use is recorded under, with its doses per item: {doses, item id}. For a potion, the
	 * highest-dose variant seen; for multi-bite food and charged items, the full (highest-charge) item.
	 */
	private final Map<String, int[]> potionVariants = new HashMap<>();

	/** Tracked quantities at the previous update, or {@code null} when a fresh baseline is needed. */
	private Map<Key, Long> baseline;
	private int baselineCannonBalls;
	/** The cannon's ammo at the update before the baseline's, so a pickup split over two ticks can resolve a guess. */
	private int priorCannonBalls;
	/** Cannonball type the cannon's loaded ammo is attributed to; inferred from what the player loads or picks up. */
	private int cannonBallId = CANNONBALL;
	/**
	 * Whether {@link #cannonBallId} comes from a load or pickup this tracker saw. Until then it is only a guess (regular
	 * cannonballs), for example when tracking starts with a cannon already loaded.
	 */
	private boolean cannonBallIdKnown;
	/** Cannonballs counted as used under the guessed type since the last reset; moved to the real type once it shows. */
	private long guessedFired;

	SupplyTracker(Classifier classifier)
	{
		this.classifier = Objects.requireNonNull(classifier);
	}

	/** Forgets the baseline; the next {@link #update} takes a fresh one and counts nothing. */
	void reset()
	{
		baseline = null;
		baselineCannonBalls = 0;
		priorCannonBalls = 0;
		// A correction after a reset could move cannonballs into a session that never counted them.
		guessedFired = 0;
	}

	/** Whether a baseline is held. */
	boolean hasBaseline()
	{
		return baseline != null;
	}

	/** Item id the cannon's loaded ammo is currently attributed to. */
	int getCannonBallId()
	{
		return cannonBallId;
	}

	/**
	 * Compares this tick's containers with the previous tick's and returns what was used. The observation always
	 * becomes the new baseline. Nothing is counted when there was no baseline (first tick, or after {@link #reset()}),
	 * when {@code counting} is false (the session is not running), or when {@code excluded} is true (a bank, shop,
	 * trade or similar interface was open, or the player died).
	 *
	 * @param dropped item ids the player chose "Drop" on recently; decreases of these (and, for a potion, of its whole
	 *                family) are not counted this tick
	 */
	Usage update(Observation observation, boolean counting, boolean excluded, Set<Integer> dropped)
	{
		return update(observation, counting, excluded, dropped, Collections.emptySet());
	}

	/**
	 * Like {@link #update(Observation, boolean, boolean, Set)}, and changes of the {@code ignored} item ids count
	 * neither way this tick: no decrease is used and no increase is returned. Used for the materials of a blowpipe or
	 * trident being loaded, charged or emptied ({@link ChargeExclusions}), which leave or enter the inventory without
	 * being used up.
	 */
	Usage update(Observation observation, boolean counting, boolean excluded, Set<Integer> dropped,
		Set<Integer> ignored)
	{
		final Map<Key, Long> after = new HashMap<>();
		for (Map.Entry<Integer, Long> e : observation.getItems().entrySet())
		{
			final int id = e.getKey();
			final ItemInfo info = info(id);
			if (info.getCategory() == Category.OTHER)
			{
				continue;
			}
			final Key key = key(id, info);
			long quantity = e.getValue();
			if (info.getFamily() != null)
			{
				quantity = saturatedMultiply(quantity, info.getDoses());
			}
			after.merge(key, quantity, SupplyTracker::saturatedAdd);
		}

		final int cannon = observation.getCannonBalls();
		final int previousCannon = baselineCannonBalls;
		// Cannonballs counted under a wrong guess of the loaded type, moved to the type that showed.
		int guessedId = -1;
		long correction = 0;
		if (baseline != null)
		{
			// The cannon's previous load is the type that showed only when this load adds to it or this is its pickup.
			boolean sameLoad = baselineCannonBalls > 0;
			int shown = -1;
			if (cannon > baselineCannonBalls)
			{
				// Loading: attribute the cannon's ammo to the cannonball type that left the inventory.
				shown = largestInventoryChange(after, false);
			}
			else if (!cannonBallIdKnown && cannon == 0 && (baselineCannonBalls > 0 || priorCannonBalls > 0))
			{
				// Picked up or unloaded with the type a guess (on this tick, or the varp a tick before the
				// inventory): the type that came back is the one the cannon held.
				final int returnedId = largestInventoryChange(after, true);
				// Only when more than half of the cannon's last load came back: the cannon may fire between the
				// last load seen and the pickup, so fewer than it held can come back, but a few cannonballs looted
				// on the tick the cannon emptied by firing must not pass for its type.
				final int lastLoad = baselineCannonBalls > 0 ? baselineCannonBalls : priorCannonBalls;
				if (returnedId >= 0 && inventoryChange(after, new Key(returnedId, null)) * 2 > lastLoad)
				{
					shown = returnedId;
					sameLoad = true;
				}
			}
			if (shown >= 0)
			{
				if (!cannonBallIdKnown && shown != cannonBallId && sameLoad)
				{
					// The guess was wrong: the baseline's load, and what it fired, were the shown type all along.
					moveCannonLoad(shown);
					guessedId = cannonBallId;
					correction = guessedFired;
				}
				cannonBallId = shown;
				cannonBallIdKnown = true;
				guessedFired = 0;
			}
			else if (!cannonBallIdKnown && cannon == 0 && baselineCannonBalls == 0 && priorCannonBalls == 0)
			{
				// Empty for three updates without its type showing: what it fired stays under the guess.
				guessedFired = 0;
			}
		}
		if (cannon > 0)
		{
			final Key cannonKey = new Key(cannonBallId, null);
			keyCategories.put(cannonKey, Category.CANNONBALL);
			after.merge(cannonKey, (long) cannon, SupplyTracker::saturatedAdd);
		}

		final Map<Key, Long> before = baseline;
		baseline = after;
		priorCannonBalls = previousCannon;
		baselineCannonBalls = cannon;
		if (before == null || !counting || excluded)
		{
			return Usage.NONE;
		}

		final Set<Key> droppedKeys = new HashSet<>();
		if (dropped != null)
		{
			for (Integer id : dropped)
			{
				if (id != null && id >= 0)
				{
					droppedKeys.add(key(id, info(id)));
				}
			}
		}
		final Set<Key> ignoredKeys = new HashSet<>();
		if (ignored != null)
		{
			for (Integer id : ignored)
			{
				if (id != null && id >= 0)
				{
					ignoredKeys.add(key(id, info(id)));
				}
			}
		}

		final ItemTally used = new ItemTally();
		final ItemTally returned = new ItemTally();
		final Map<Integer, Integer> doses = new TreeMap<>();
		final Set<Key> keys = new HashSet<>(before.keySet());
		keys.addAll(after.keySet());
		keys.removeAll(ignoredKeys);
		for (Key key : keys)
		{
			final long delta = after.getOrDefault(key, 0L) - before.getOrDefault(key, 0L);
			final Category category = keyCategories.getOrDefault(key, Category.OTHER);
			if (delta < 0)
			{
				if (droppedKeys.contains(key))
				{
					continue;
				}
				if (key.family != null)
				{
					final int[] variant = potionVariants.get(key.family);
					used.add(variant[1], -delta);
					doses.put(variant[1], variant[0]);
				}
				else
				{
					used.add(key.itemId, -delta);
					if (!cannonBallIdKnown && key.itemId == cannonBallId)
					{
						// Fired from a cannon whose type is a guess: corrected if its pickup shows another type.
						guessedFired = saturatedAdd(guessedFired, Math.min(-delta, Math.max(0, previousCannon - cannon)));
					}
				}
			}
			else if (delta > 0 && (category == Category.AMMO || category == Category.CANNONBALL))
			{
				returned.add(key.itemId, delta);
			}
		}
		if (correction > 0)
		{
			used.add(cannonBallId, correction);
			returned.add(guessedId, correction);
		}
		return used.isEmpty() && returned.isEmpty() ? Usage.NONE : new Usage(used, returned, doses);
	}

	/**
	 * Classifies the observation's items and notes each potion family's highest-dose variant seen, as {@link #update}
	 * does for every item it sees, without touching the baseline or counting anything. Lets the plugin keep noting the
	 * potions the player holds while no diff runs (no session running), so a potion's use is recorded under the same
	 * item as when every tick was diffed.
	 *
	 * @return {@code false} when an item's data was not loaded yet, so it should be noted again later
	 */
	boolean noteVariants(Observation observation)
	{
		boolean complete = true;
		for (Integer id : observation.getItems().keySet())
		{
			final ItemInfo info = info(id);
			if (info.getCategory() == Category.OTHER)
			{
				// Not cached: the classifier had no answer yet (see info), and asks again next time.
				complete &= infoCache.containsKey(id);
				continue;
			}
			key(id, info);
		}
		return complete;
	}

	/**
	 * The cannonball type whose amount outside the cannon changed most since the baseline, or -1 when none did: the
	 * largest decrease (what was loaded) or, with {@code increase}, the largest increase (what came back from a pickup
	 * or unload).
	 */
	private int largestInventoryChange(Map<Key, Long> after, boolean increase)
	{
		long largest = 0;
		int itemId = -1;
		// Only a key in the baseline can decrease, and only one in after can increase.
		for (Key key : (increase ? after : baseline).keySet())
		{
			if (key.family != null || keyCategories.get(key) != Category.CANNONBALL)
			{
				continue;
			}
			final long change = inventoryChange(after, key);
			final long size = increase ? change : -change;
			if (size > largest)
			{
				largest = size;
				itemId = key.itemId;
			}
		}
		return itemId;
	}

	/**
	 * How much the amount of {@code key} outside the cannon changed since the baseline: positive when it went up. The
	 * baseline's cannon load, held under the current {@link #cannonBallId}, is left out.
	 */
	private long inventoryChange(Map<Key, Long> after, Key key)
	{
		long beforeInventory = baseline.getOrDefault(key, 0L);
		if (key.itemId == cannonBallId)
		{
			// The baseline includes the cannon's previous load under the current type.
			beforeInventory -= baselineCannonBalls;
		}
		return after.getOrDefault(key, 0L) - beforeInventory;
	}

	/** Moves the baseline's cannon load from the guessed {@link #cannonBallId} to {@code itemId}. */
	private void moveCannonLoad(int itemId)
	{
		if (baselineCannonBalls <= 0)
		{
			return;
		}
		baseline.merge(new Key(cannonBallId, null), (long) -baselineCannonBalls, Long::sum);
		baseline.merge(new Key(itemId, null), (long) baselineCannonBalls, Long::sum);
	}

	private ItemInfo info(int itemId)
	{
		ItemInfo info = infoCache.get(itemId);
		if (info == null)
		{
			try
			{
				info = classifier.classify(itemId);
			}
			catch (RuntimeException e)
			{
				info = null;
			}
			if (info == null)
			{
				// Item data not available yet (or the lookup failed): treat as untracked now, classify again later.
				return ItemInfo.OTHER;
			}
			if ((info.getCategory() == Category.POTION || info.getFamily() != null)
				&& (info.getFamily() == null || info.getDoses() <= 0))
			{
				info = ItemInfo.OTHER;
			}
			infoCache.put(itemId, info);
		}
		return info;
	}

	private Key key(int itemId, ItemInfo info)
	{
		final Key key;
		if (info.getFamily() != null)
		{
			key = new Key(-1, info.getFamily());
			if (info.getFullItemId() >= 0)
			{
				potionVariants.putIfAbsent(info.getFamily(), new int[]{info.getDosesPerItem(), info.getFullItemId()});
			}
			else
			{
				final int[] best = potionVariants.get(info.getFamily());
				if (best == null || info.getDoses() > best[0])
				{
					potionVariants.put(info.getFamily(), new int[]{info.getDoses(), itemId});
				}
			}
		}
		else
		{
			key = new Key(itemId, null);
		}
		keyCategories.putIfAbsent(key, info.getCategory());
		return key;
	}

	private static long saturatedAdd(long a, long b)
	{
		long sum = a + b;
		return sum < 0 ? Long.MAX_VALUE : sum;
	}

	private static long saturatedMultiply(long a, long b)
	{
		try
		{
			return Math.multiplyExact(a, b);
		}
		catch (ArithmeticException e)
		{
			return Long.MAX_VALUE;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.Collection;
import java.util.List;
import java.util.Map;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;

/**
 * The task box's advice for the current task: Do, Consider skip or Consider block, from how the monster's rate
 * on the goal metric compares with the player's other monsters'. Advice only. Pure: no RuneLite types.
 *
 * <p>The rates are {@link TaskRanking}'s, exactly as the Trends list shows them (records only, completed and not
 * partial, a rate from 1 minute of active time, Points/h only from tasks tracked from the start of the assignment and
 * not bonus tasks). Whole-monster history, not the current location's, as the rankings. How often a task is assigned
 * is not used (owner decision).</p>
 *
 * <p><b>Qualifying monsters</b> (owner decision): a monster takes part only with a rate on the metric from
 * at least {@link #MIN_TASKS} tasks with that metric and at least {@link #MIN_ACTIVE_MILLIS} of their pooled active
 * time. One that falls short gets no advice and does not count in the ranking.</p>
 *
 * <p><b>Pools</b>: boss tasks ({@link TaskType#BOSS}, creature keys below {@link SessionTracker#NO_CREATURE})
 * are ranked only against boss tasks, and every other monster (Jad and Zuk included, which are Regular tasks, and
 * older records grouped by name) only against the others.</p>
 *
 * <p><b>Position from the bottom:</b> among the {@code m} qualifying monsters of the current monster's pool, its
 * position {@code p} is the number of them whose rate is <em>at or below</em> its own (itself included), so tied
 * monsters share the highest position of their tie and a tie is never pushed down. It is in the bottom 10% when
 * {@code p <= m * 10%} and in the bottom 25% when {@code p <= m * 25%}: bottom 10% is "Consider block", otherwise
 * bottom 25% is "Consider skip", otherwise "Do". So under 10 monsters in the pool none is "Consider block" (from 10
 * the lowest is), and with 6 or 7 only the lowest can be "Consider skip" (from 8 the two lowest). "Consider block"
 * also needs at least {@link #MIN_BLOCK_TASKS} of the monster's own tasks; with fewer it is "Consider skip".</p>
 *
 * <p><b>Minimum data</b> (owner decision): the current monster qualifies and at least {@link #MIN_MONSTERS} monsters
 * of its pool, itself included, qualify; otherwise no advice.</p>
 *
 * <p><b>Catacombs variants</b> (owner decision): the advice above pools a task's standard and Catacombs variant
 * records, as before. Beside it, for a task with a variant ({@link CatacombsVariants}), {@link #adviseVariant} says
 * which version has the better rate on the goal metric, when both versions qualify on their own records (at least
 * {@link #MIN_TASKS} tasks and {@link #MIN_ACTIVE_MILLIS} of active time each, as above), whatever the other monsters.
 * Equal rates, or either version short of data, give no variant advice.</p>
 *
 * <p><b>Cannon</b> (owner decision): likewise the advice above pools a task's tasks with and without a cannon
 * ({@link CannonTasks}), and {@link #adviseCannon} says which has the better rate on the goal metric, when both qualify
 * on their own records, whatever the other monsters. The variant advice pools cannon use and the cannon advice pools
 * the versions, so each compares one thing; they are worked out independently and the task box shows them together
 * ({@link #betterText}).</p>
 */
final class TaskAdvisor
{
	/** The cannon advice's label when cannon tasks are better. */
	static final String WITH_CANNON = "with cannon";
	/** The cannon advice's label when tasks without a cannon are better. */
	static final String WITHOUT_CANNON = "without cannon";
	/** Qualifying monsters in the current monster's pool, itself included, needed for any advice. */
	static final int MIN_MONSTERS = 6;
	/** Tasks with the metric a monster needs to qualify. */
	static final int MIN_TASKS = 3;
	/** Pooled active time on the metric a monster needs to qualify: 30 minutes. */
	static final long MIN_ACTIVE_MILLIS = 30 * 60_000L;
	/** The monster's own tasks needed for "Consider block"; with fewer it is "Consider skip". */
	static final int MIN_BLOCK_TASKS = 5;

	enum Advice
	{
		DO("Do"),
		CONSIDER_SKIP("Consider skip"),
		CONSIDER_BLOCK("Consider block");

		private final String displayName;

		Advice(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	private TaskAdvisor()
	{
	}

	/**
	 * The advice for the current task ({@code creatureId}, {@code monster}) from {@code records} on {@code metric},
	 * valued as {@link TaskRanking#rank} values it; {@code null} without enough data.
	 */
	static Result advise(Collection<LedgerRecord> records, int creatureId, String monster, TaskRanking.Metric metric,
		LootPriceMode mode, Map<Integer, Long> currentGe)
	{
		return advise(records, creatureId, monster, metric, mode, currentGe, HiddenLoot.NONE);
	}

	/**
	 * As {@link #advise(Collection, int, String, TaskRanking.Metric, LootPriceMode, Map)}, with the loot items
	 * {@code hidden} hides left out of the profit.
	 */
	static Result advise(Collection<LedgerRecord> records, int creatureId, String monster, TaskRanking.Metric metric,
		LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		if (records == null || records.isEmpty() || metric == null)
		{
			return null;
		}
		TaskRanking.TaskKey current = TaskRanking.currentTaskKey(records, creatureId, monster);
		// The task's Catacombs variant and cannon records are pooled with its others here, as before.
		return current == null ? null
			: advise(TaskRanking.rank(records, metric, mode, currentGe, hidden, TaskRanking.Split.NONE), current,
				metric);
	}

	/**
	 * The advice ({@link #advise(Collection, int, String, TaskRanking.Metric, LootPriceMode, Map, HiddenLoot)}), the
	 * variant advice ({@link #adviseVariant}) and the cannon advice ({@link #adviseCannon}) for the current task, worked
	 * out together (the task box shows them all), each with the loot items {@code hidden} hides left out of the profit.
	 */
	static Outcome adviseAll(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskRanking.Metric metric, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		return new Outcome(advise(records, creatureId, monster, metric, mode, currentGe, hidden),
			adviseVariant(records, creatureId, monster, metric, mode, currentGe, hidden),
			adviseCannon(records, creatureId, monster, metric, mode, currentGe, hidden));
	}

	/**
	 * Which version of the current task, standard or Catacombs variant, has the better rate on {@code metric},
	 * from {@code records} split by version with cannon use pooled ({@link TaskRanking.Split#VARIANT}); {@code null} for
	 * a task without a variant, when either version doesn't {@link #qualifies qualify}, or when their rates are equal.
	 * Its label is the better version's name, for example "Deviant spectres". The loot items {@code hidden} hides are
	 * left out of the profit.
	 */
	static VersionAdvice adviseVariant(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskRanking.Metric metric, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		CatacombsVariants.Variant variant = CatacombsVariants.forTask(monster);
		if (variant == null || records == null || records.isEmpty() || metric == null)
		{
			return null;
		}
		TaskRanking.TaskKey standardKey = TaskRanking.currentTaskKey(records, creatureId, monster, null, false);
		TaskRanking.TaskKey variantKey = TaskRanking.currentTaskKey(records, creatureId, monster, variant.getName(),
			false);
		return compare(TaskRanking.rank(records, metric, mode, currentGe, hidden, TaskRanking.Split.VARIANT), metric,
			variantKey, null, standardKey, null);
	}

	/**
	 * Whether the current task's tasks with a cannon or without one have the better rate on {@code metric}, from
	 * {@code records} split by cannon use with the versions pooled ({@link TaskRanking.Split#CANNON}); {@code null}
	 * when either doesn't {@link #qualifies qualify}, or when their rates are equal. Its label is
	 * {@link #WITH_CANNON} or {@link #WITHOUT_CANNON}; for a task with a Catacombs variant its reason names both groups
	 * as pooled across versions. The loot items {@code hidden} hides are left out of the profit.
	 */
	static VersionAdvice adviseCannon(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskRanking.Metric metric, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		if (records == null || records.isEmpty() || metric == null)
		{
			return null;
		}
		TaskRanking.TaskKey withoutKey = TaskRanking.currentTaskKey(records, creatureId, monster, null, false);
		TaskRanking.TaskKey withKey = TaskRanking.currentTaskKey(records, creatureId, monster, null, true);
		VersionAdvice advice = compare(
			TaskRanking.rank(records, metric, mode, currentGe, hidden, TaskRanking.Split.CANNON), metric, withKey,
			WITH_CANNON, withoutKey, WITHOUT_CANNON);
		if (advice == null || CatacombsVariants.forTask(monster) == null)
		{
			return advice;
		}
		// Both groups hold the Catacombs variant's tasks too, so the reason says so rather than naming them after the
		// standard monster: "Aberrant spectres, any version, with cannon".
		String task = (WITH_CANNON.equals(advice.getLabel()) ? advice.other : advice.better).getMonster();
		String better = task + ", any version, " + advice.getLabel();
		String other = task + ", any version, " + (WITH_CANNON.equals(advice.getLabel()) ? WITHOUT_CANNON
			: WITH_CANNON);
		return new VersionAdvice(metric, advice.better, advice.other, advice.getLabel(), better, other);
	}

	/**
	 * The better of the groups {@code firstKey} and {@code secondKey} in {@code ranking}, labelled
	 * {@code firstLabel} or {@code secondLabel} ({@code null}: the group's name); {@code null} when either is missing
	 * or doesn't {@link #qualifies qualify}, or their rates are equal.
	 */
	private static VersionAdvice compare(List<TaskRanking.Entry> ranking, TaskRanking.Metric metric,
		TaskRanking.TaskKey firstKey, String firstLabel, TaskRanking.TaskKey secondKey, String secondLabel)
	{
		if (firstKey == null || secondKey == null)
		{
			return null;
		}
		TaskRanking.Entry first = null;
		TaskRanking.Entry second = null;
		for (TaskRanking.Entry entry : ranking)
		{
			if (entry.getKey().equals(firstKey))
			{
				first = entry;
			}
			else if (entry.getKey().equals(secondKey))
			{
				second = entry;
			}
		}
		if (first == null || second == null || !qualifies(first) || !qualifies(second))
		{
			return null;
		}
		int compare = Long.compare(first.getRatePerHour(), second.getRatePerHour());
		if (compare == 0)
		{
			return null;
		}
		return compare > 0
			? new VersionAdvice(metric, first, second, firstLabel != null ? firstLabel : first.getMonster())
			: new VersionAdvice(metric, second, first, secondLabel != null ? secondLabel : second.getMonster());
	}

	/**
	 * The task box's line for the variant and cannon advice, plain text: {@code Better: Deviant spectres},
	 * {@code Better: with cannon}, or both in one line, {@code Better: Deviant spectres, without cannon}; {@code null}
	 * when both are {@code null}. The two are separate comparisons (each pools the other dimension).
	 */
	static String betterText(VersionAdvice variant, VersionAdvice cannon)
	{
		if (variant == null && cannon == null)
		{
			return null;
		}
		if (variant == null || cannon == null)
		{
			return "Better: " + (variant != null ? variant : cannon).getLabel();
		}
		return "Better: " + variant.getLabel() + ", " + cannon.getLabel();
	}

	/** The advice for the monster {@code current} in a {@link TaskRanking#rank} ranking; {@code null} without data. */
	static Result advise(List<TaskRanking.Entry> ranking, TaskRanking.TaskKey current, TaskRanking.Metric metric)
	{
		boolean boss = isBoss(current);
		TaskRanking.Entry own = null;
		int monsters = 0;
		for (TaskRanking.Entry entry : ranking)
		{
			if (!qualifies(entry) || isBoss(entry.getKey()) != boss)
			{
				continue;
			}
			monsters++;
			if (entry.getKey().equals(current))
			{
				own = entry;
			}
		}
		if (own == null || monsters < MIN_MONSTERS)
		{
			return null;
		}
		long rate = own.getRatePerHour();
		int position = 0;
		for (TaskRanking.Entry entry : ranking)
		{
			if (qualifies(entry) && isBoss(entry.getKey()) == boss && entry.getRatePerHour() <= rate)
			{
				position++;
			}
		}
		Advice advice = classify(position, monsters);
		boolean blockNeedsTasks = advice == Advice.CONSIDER_BLOCK && own.getSampleCount() < MIN_BLOCK_TASKS;
		if (blockNeedsTasks)
		{
			advice = Advice.CONSIDER_SKIP;
		}
		return Result.builder()
			.advice(advice)
			.metric(metric)
			.ratePerHour(rate)
			.approximate(own.isApproximate())
			.position(position)
			.monsters(monsters)
			.tasks(own.getSampleCount())
			.boss(boss)
			.blockNeedsTasks(blockNeedsTasks)
			.build();
	}

	/**
	 * Whether {@code entry} takes part in the advice: a rate from at least {@link #MIN_TASKS} tasks with the
	 * metric and {@link #MIN_ACTIVE_MILLIS} of their pooled active time.
	 */
	static boolean qualifies(TaskRanking.Entry entry)
	{
		return entry.getRatePerHour() != null && entry.getSampleCount() >= MIN_TASKS
			&& entry.getActiveMillis() >= MIN_ACTIVE_MILLIS;
	}

	/** Whether the group is a boss task's ({@link TaskType#BOSS}); a name group (no creature key) is not. */
	static boolean isBoss(TaskRanking.TaskKey key)
	{
		return key.getCreatureId() != null && TaskType.of(null, key.getCreatureId()) == TaskType.BOSS;
	}

	/**
	 * The advice for position {@code position} from the bottom (1 is the lowest) of {@code monsters}: bottom 10%
	 * ({@code position <= monsters / 10}, not rounded) is "Consider block", bottom 25% "Consider skip", else "Do".
	 */
	static Advice classify(int position, int monsters)
	{
		if (position * 10L <= monsters)
		{
			return Advice.CONSIDER_BLOCK;
		}
		if (position * 4L <= monsters)
		{
			return Advice.CONSIDER_SKIP;
		}
		return Advice.DO;
	}

	/** "1st", "2nd", "3rd", "4th", "11th", "21st". */
	static String ordinal(int n)
	{
		int lastTwo = n % 100;
		if (lastTwo >= 11 && lastTwo <= 13)
		{
			return n + "th";
		}
		switch (n % 10)
		{
			case 1:
				return n + "st";
			case 2:
				return n + "nd";
			case 3:
				return n + "rd";
			default:
				return n + "th";
		}
	}

	/** The task box's two pieces of advice for the current task; either may be {@code null}. Immutable. */
	static final class Outcome
	{
		private final Result advice;
		private final VersionAdvice variant;
		private final VersionAdvice cannon;

		Outcome(Result advice, VersionAdvice variant, VersionAdvice cannon)
		{
			this.advice = advice;
			this.variant = variant;
			this.cannon = cannon;
		}

		/** The advice on the task ({@link #advise}), or {@code null} without enough data. */
		Result getAdvice()
		{
			return advice;
		}

		/** Which version of the task is better ({@link #adviseVariant}), or {@code null}. */
		VersionAdvice getVariant()
		{
			return variant;
		}

		/** Whether the task is better with or without a cannon ({@link #adviseCannon}), or {@code null}. */
		VersionAdvice getCannon()
		{
			return cannon;
		}
	}

	/**
	 * Which of two groups of a task's records has the better rate on the goal metric: its standard monster or its
	 * Catacombs variant ({@link #adviseVariant}), or its tasks with or without a cannon (* {@link #adviseCannon}). The two groups' entries in a split {@link TaskRanking#rank}, the better first, and the
	 * better one's label. Immutable.
	 */
	static final class VersionAdvice
	{
		private final TaskRanking.Metric metric;
		private final TaskRanking.Entry better;
		private final TaskRanking.Entry other;
		private final String label;
		/** What the reason calls the better group: its name in the ranking unless given. */
		private final String betterName;
		/** What the reason calls the other group: its name in the ranking unless given. */
		private final String otherName;

		VersionAdvice(TaskRanking.Metric metric, TaskRanking.Entry better, TaskRanking.Entry other, String label)
		{
			this(metric, better, other, label, better.getMonster(), other.getMonster());
		}

		VersionAdvice(TaskRanking.Metric metric, TaskRanking.Entry better, TaskRanking.Entry other, String label,
			String betterName, String otherName)
		{
			this.metric = metric;
			this.better = better;
			this.other = other;
			this.label = label;
			this.betterName = betterName;
			this.otherName = otherName;
		}

		/** What the task box says is better: "Deviant spectres", {@link #WITH_CANNON} or {@link #WITHOUT_CANNON}. */
		String getLabel()
		{
			return label;
		}

		/**
		 * Why, plain text: {@code Profit (GE)/h: Deviant spectres 450K (n=4), Aberrant spectres 300K (n=5)}, each rate
		 * as Trends shows it, with {@code ~} when some prices were unavailable. The cannon advice on a task with a
		 * Catacombs variant names its groups as pooled across versions: {@code Aberrant spectres, any version, with
		 * cannon}.
		 */
		String reason(LootPriceMode mode)
		{
			return metric.label(mode) + ": " + part(betterName, better) + ", " + part(otherName, other);
		}

		private static String part(String name, TaskRanking.Entry entry)
		{
			return name + " " + LedgerHistory.formatAmount(entry.getRatePerHour(), entry.isApproximate())
				+ " (n=" + entry.getSampleCount() + ")";
		}
	}

	@Builder
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Result
	{
		private final Advice advice;
		private final TaskRanking.Metric metric;
		private final long ratePerHour;
		private final boolean approximate;
		private final int position;
		private final int monsters;
		private final int tasks;
		private final boolean boss;
		private final boolean blockNeedsTasks;

		Advice getAdvice()
		{
			return advice;
		}

		long getRatePerHour()
		{
			return ratePerHour;
		}

		/** The position from the bottom: how many monsters' rates are at or below this one's (itself included). */
		int getPosition()
		{
			return position;
		}

		/** Qualifying monsters in this one's pool (boss or not), this one included. */
		int getMonsters()
		{
			return monsters;
		}

		/** The monster's tasks with the metric: the sample size {@code n}. */
		int getTasks()
		{
			return tasks;
		}

		/** Whether this is a boss task, ranked only against boss tasks. */
		boolean isBoss()
		{
			return boss;
		}

		/** {@code Advice: Consider skip (n=3)}, or {@code Advice: Do} (no sample size, to keep it short). */
		String text()
		{
			return "Advice: " + advice + (advice == Advice.DO ? "" : " (n=" + tasks + ")");
		}

		/**
		 * Why: {@code Profit (GE)/h 210K: 5th lowest of your 24 monsters (bottom 25%)}, the metric named as in Trends
		 * ({@link TaskRanking.Metric#label}), the rate compact with {@code ~} when some prices were unavailable. In the
		 * upper half ({@code position * 2 > monsters}) it counts from the top instead: 20th of 24 is
		 * {@code 5th highest of your 24 monsters}. A boss task says {@code bosses}; a bottom-10% monster with too few
		 * tasks to block says {@code (bottom 10%, block from 5 tasks)}.
		 */
		String reason(LootPriceMode mode)
		{
			String bottom;
			switch (advice)
			{
				case CONSIDER_BLOCK:
					bottom = " (bottom 10%)";
					break;
				case CONSIDER_SKIP:
					bottom = blockNeedsTasks
						? " (bottom 10%, block from " + MIN_BLOCK_TASKS + " tasks)"
						: " (bottom 25%)";
					break;
				default:
					bottom = "";
					break;
			}
			String place = position * 2 > monsters
				? ordinal(monsters - position + 1) + " highest"
				: ordinal(position) + " lowest";
			return metric.label(mode) + " " + LedgerHistory.formatAmount(ratePerHour, approximate) + ": " + place
				+ " of your " + monsters + (boss ? " bosses" : " monsters") + bottom;
		}
	}
}

package com.shmayvan.slayerledger;

/** The "Task advisor goal" setting: which rate the task advisor ({@link TaskAdvisor}) compares. */
public enum TaskAdvisorGoal
{
	/** Loot in the "Loot price" mode minus supplies at GE, per hour. */
	PROFIT("Profit/h", TaskRanking.Metric.PROFIT),
	/** Slayer XP per hour. */
	SLAYER_XP("Slayer XP/h", TaskRanking.Metric.XP),
	/** Slayer points per hour, from tasks tracked from the start of the assignment, leaving out bonus (milestone) tasks. */
	POINTS("Points/h", TaskRanking.Metric.POINTS);

	private final String displayName;
	private final TaskRanking.Metric metric;

	TaskAdvisorGoal(String displayName, TaskRanking.Metric metric)
	{
		this.displayName = displayName;
		this.metric = metric;
	}

	/** The Trends metric with the same rules. */
	TaskRanking.Metric metric()
	{
		return metric;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.shmayvan.slayerledger;

import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Supplier;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The task box at the top of {@link SlayerLedgerPanel}, at most three lines:
 * <ol>
 * <li>the task and the kills left: {@code Abyssal demons · 172 left}; a task done on its Catacombs variant, once the
 * session's kills say so, shows the variant instead: {@code Deviant spectres · 120 left}; once the session has
 * fired a cannonball the name ends with {@code (cannon)}: {@code Dust devils (cannon) · 80 left};</li>
 * <li>(while any part is known) the master, the type when it isn't Regular or Konar (the master already says
 * Konar), the location (the running or paused session's, else the task's assigned area) and the next bonus
 *: {@code Konar · Kraken Cove · bonus in 3}; its tooltip has each of them in full;</li>
 * <li>(while the task advisor has advice other than Do) the advice, with its reason as the tooltip. Do adds
 * nothing to the box; its reason is in the first line's tooltip. When the advisor can say which version of the task
 * is better, standard or Catacombs variant ({@link TaskAdvisor#adviseVariant}), or with or without a cannon
 * ({@link TaskAdvisor#adviseCannon}): with advice other than Do it is in the advice's tooltip, otherwise this
 * line shows it, both in one line when there are both ({@link TaskAdvisor#betterText}):
 * {@code Better: Deviant spectres, without cannon}.</li>
 * </ol>
 * The optional lines are added or removed only when they appear or go. EDT only.
 */
final class TaskBoxView
{
	/** Between the parts of the first and second lines. */
	static final String SEPARATOR = " · ";

	private final LedgerHistoryModel model;
	private final SessionTracker tracker;
	/** The plugin's current task streak, or {@code null} while unknown. */
	private final Supplier<Integer> taskStreak;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;

	/** "Abyssal demons · 172 left", "Task: None" or "Task: waiting for game data". */
	private final JLabel taskLabel = new JLabel();
	/** "Konar · Kraken Cove · bonus in 3"; in {@link #box}, after the task, only while some part is known. */
	private final JLabel detailsLabel = new JLabel();
	/**
	 * "Advice: Consider skip (n=3)" ({@link TaskAdvisor}); last in {@link #box}, only while there is a task, the
	 * "Task advisor" setting is on, there is enough history and the advice isn't Do.
	 */
	private final JLabel adviceLabel = new JLabel();
	/** The task box: the task, then (while known) the details and the advice. */
	private final JPanel box;
	/** The advice shown (the model's result), so the row is redrawn only when the model works out a new one. */
	private TaskAdvisor.Result shownAdvice;
	/** The variant advice shown, likewise. */
	private TaskAdvisor.VersionAdvice shownVariant;
	/** The cannon advice shown, likewise. */
	private TaskAdvisor.VersionAdvice shownCannon;

	/** The first line's tooltip without the advice: the task and the kills left in full, or {@code null}. */
	private String taskTooltip;
	/** The details of the current task, as of the last {@link #refreshTask}: whether there is a task, its master etc. */
	private boolean hasTask;
	private Integer master;
	private TaskType type;
	/** The task's assigned area (Konar, Wilderness), or {@code null}. */
	private String area;
	/** The running or paused session's location name, as of the last {@link #refreshLocation}, or {@code null}. */
	private String liveLocation;

	TaskBoxView(LedgerHistoryModel model, SessionTracker tracker, Supplier<Integer> taskStreak, Runnable relayout)
	{
		this.model = model;
		this.tracker = tracker;
		this.taskStreak = taskStreak;
		this.relayout = relayout;
		box = SlayerLedgerPanel.section(taskLabel);
		// Names for tests, which find the rows by them; no visible effect.
		box.setName("taskBox");
		taskLabel.setName("taskBox.task");
		detailsLabel.setName("taskBox.details");
		adviceLabel.setName("taskBox.advice");
	}

	/** Adds the task box to {@code content}. */
	void addTo(JPanel content)
	{
		detailsLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		detailsLabel.setFont(FontManager.getRunescapeSmallFont());
		adviceLabel.setFont(FontManager.getRunescapeSmallFont());
		SlayerLedgerPanel.addRow(content, box);
	}

	/** Shows the task and the kills left, then who assigned it, its type, the next bonus and the advice. */
	void refreshTask(int remaining, String monster)
	{
		hasTask = remaining > 0;
		if (!tracker.isTaskObserved())
		{
			taskLabel.setText("Task: waiting for game data");
			taskTooltip = null;
		}
		else if (hasTask)
		{
			// The Catacombs variant the running or paused session's kills say is being done, and whether it
			// fired a cannonball: the name its task is saved under.
			TaskSelection selection = tracker.getCurrentTaskSelection();
			String variant = selection.getVariant();
			boolean cannon = Boolean.TRUE.equals(selection.getCannon());
			taskLabel.setText(selection.displayName(monster) + SEPARATOR + remaining + " left");
			// A long monster name may not fit the sidebar; the tooltip has it in full.
			taskTooltip = "Task: " + LedgerHistory.escapeHtml(monster)
				+ (variant == null ? "" : "<br>Doing: " + LedgerHistory.escapeHtml(variant) + " (from your kills)")
				+ (cannon ? "<br>Cannon: cannonballs fired this session" : "")
				+ "<br>Remaining: " + remaining;
		}
		else
		{
			taskLabel.setText("Task: None");
			taskTooltip = null;
		}
		TaskContext context = hasTask ? tracker.getCurrentContext() : TaskContext.NONE;
		master = context.getMaster();
		type = hasTask ? context.type(tracker.getCurrentCreatureId()) : null;
		area = type == null ? null : TaskLocation.normalizeName(context.getLocation());
		refreshDetails();
		refreshAdvice();
	}

	/**
	 * Takes the running or paused session's location while it is known: its assigned area, else the player's name for
	 * its region with the most kills (asked of the plugin when not known yet).
	 */
	void refreshLocation(SessionTracker.State state)
	{
		String name = null;
		if (state == SessionTracker.State.RUNNING || state == SessionTracker.State.PAUSED)
		{
			Integer region = tracker.getDominantRegion();
			if (region != null)
			{
				model.requestLocationNames(Collections.singleton(region));
			}
			name = TaskLocation.liveName(tracker.getSessionTaskLocation(), region, model::locationName);
		}
		liveLocation = name;
		refreshDetails();
	}

	/**
	 * Shows the second line: the known parts of master, type (unless Regular or Konar), location and next bonus, with
	 * each in full in the tooltip; the line is in the box only while some part is known.
	 */
	private void refreshDetails()
	{
		List<String> parts = new ArrayList<>();
		List<String> tooltip = new ArrayList<>();
		if (hasTask)
		{
			String masterName = SlayerMaster.displayName(master);
			if (masterName != null)
			{
				parts.add(masterName);
			}
			if (type != null && type != TaskType.REGULAR && type != TaskType.KONAR)
			{
				parts.add(type.toString());
			}
			tooltip.add("Master: " + LedgerHistory.escapeHtml(masterName == null ? LedgerHistory.NO_VALUE : masterName));
			tooltip.add(LedgerHistory.escapeHtml(LedgerHistory.formatTaskType(type, area)));
		}
		String location = liveLocation != null ? liveLocation : area;
		if (location != null)
		{
			parts.add(location);
		}
		if (liveLocation != null)
		{
			tooltip.add(LedgerHistory.escapeHtml(TaskLocation.format(liveLocation)));
		}
		Integer streak = taskStreak.get();
		String bonus = StreakMilestone.formatShort(streak);
		if (bonus != null)
		{
			parts.add(bonus);
			tooltip.add(StreakMilestone.format(streak));
		}

		boolean show = !parts.isEmpty();
		if (show)
		{
			String text = String.join(SEPARATOR, parts);
			// A player-typed location first in the line must not turn it into HTML.
			detailsLabel.setText(text.regionMatches(true, 0, "<html", 0, 5) ? " " + text : text);
			// A long location may not fit the sidebar; the tooltip has every part in full.
			detailsLabel.setToolTipText("<html>" + String.join("<br>", tooltip) + "</html>");
		}
		boolean shown = detailsLabel.getParent() == box;
		if (shown != show)
		{
			if (show)
			{
				box.add(detailsLabel, 1);
			}
			else
			{
				box.remove(detailsLabel);
			}
			relayoutBox();
		}
	}

	/**
	 * Shows the task advisor's row for the current task, last in the box. The model works it out
	 * ({@link LedgerHistoryModel#advice}) only when the task, the records, the Loot price mode, today's prices or the
	 * settings change, and the row is redrawn only then; while views wait for today's prices the shown row stays
	 * until they arrive.
	 */
	void refreshAdvice()
	{
		if (!model.isAdviceShown())
		{
			shownAdvice = null;
			shownVariant = null;
			shownCannon = null;
			showAdvice(null, null, null);
			return;
		}
		if (model.isWaitingForCurrentPrices())
		{
			// The first line's tooltip may have changed (a new task); the advice in it stays until the prices arrive.
			showTaskTooltip(shownAdvice, shownVariant, shownCannon);
			return;
		}
		TaskAdvisor.Result result = model.advice();
		TaskAdvisor.VersionAdvice variant = model.variantAdvice();
		TaskAdvisor.VersionAdvice cannon = model.cannonAdvice();
		boolean rowShown = adviceLabel.getParent() == box;
		if (result != shownAdvice || variant != shownVariant || cannon != shownCannon
			|| hasRow(result, variant, cannon) != rowShown)
		{
			shownAdvice = result;
			shownVariant = variant;
			shownCannon = cannon;
			showAdvice(result, variant, cannon);
		}
		else
		{
			showTaskTooltip(result, variant, cannon);
		}
	}

	/** Whether the advice row is in the box: advice other than Do, or variant or cannon advice. */
	private static boolean hasRow(TaskAdvisor.Result result, TaskAdvisor.VersionAdvice variant,
		TaskAdvisor.VersionAdvice cannon)
	{
		return isWarning(result) || variant != null || cannon != null;
	}

	/** Whether {@code result} is advice other than Do (shown in orange). */
	private static boolean isWarning(TaskAdvisor.Result result)
	{
		return result != null && result.getAdvice() != TaskAdvisor.Advice.DO;
	}

	/**
	 * Shows {@code result}: as the last row of the task box when it isn't Do, in the first line's tooltip when it is,
	 * or nowhere for {@code null}. The variant and cannon advice are in that row's tooltip, or the row
	 * itself, in one line, when there is no other advice to show there: the box keeps to three lines.
	 */
	private void showAdvice(TaskAdvisor.Result result, TaskAdvisor.VersionAdvice variant,
		TaskAdvisor.VersionAdvice cannon)
	{
		boolean row = hasRow(result, variant, cannon);
		String versions = versionReasons(variant, cannon);
		if (isWarning(result))
		{
			adviceLabel.setText(result.text());
			// The panel's hint colour (as the blowpipe hint) for skip and block.
			adviceLabel.setForeground(ColorScheme.BRAND_ORANGE);
			adviceLabel.setToolTipText("<html>" + adviceReason(result)
				+ (versions == null ? "" : "<br>" + versions) + "</html>");
		}
		else if (versions != null)
		{
			String better = TaskAdvisor.betterText(variant, cannon);
			adviceLabel.setText(better);
			adviceLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			// The line in full first, as the sidebar may cut it off.
			adviceLabel.setToolTipText("<html>" + LedgerHistory.escapeHtml(better) + "<br>" + versions + "</html>");
		}
		showTaskTooltip(result, variant, cannon);
		boolean shown = adviceLabel.getParent() == box;
		if (shown != row)
		{
			if (row)
			{
				box.add(adviceLabel);
			}
			else
			{
				box.remove(adviceLabel);
			}
			relayoutBox();
		}
	}

	/**
	 * Sets the first line's tooltip: the task in full and, when {@code advice} is Do, that advice and its reason, and
	 * then the variant and cannon advice, if any.
	 */
	private void showTaskTooltip(TaskAdvisor.Result advice, TaskAdvisor.VersionAdvice variant,
		TaskAdvisor.VersionAdvice cannon)
	{
		String tooltip = taskTooltip;
		if (tooltip != null && advice != null && advice.getAdvice() == TaskAdvisor.Advice.DO)
		{
			tooltip += "<br>" + advice.text() + "<br>" + adviceReason(advice);
		}
		String versions = versionReasons(variant, cannon);
		if (tooltip != null && versions != null)
		{
			tooltip += "<br>" + LedgerHistory.escapeHtml(TaskAdvisor.betterText(variant, cannon)) + "<br>" + versions;
		}
		taskLabel.setToolTipText(tooltip == null ? null : "<html>" + tooltip + "</html>");
	}

	/**
	 * The variant and cannon advice's reasons and what they count, as HTML without the {@code <html>}
	 * tags, or {@code null} when there is neither.
	 */
	private String versionReasons(TaskAdvisor.VersionAdvice variant, TaskAdvisor.VersionAdvice cannon)
	{
		if (variant == null && cannon == null)
		{
			return null;
		}
		StringBuilder reasons = new StringBuilder();
		if (variant != null)
		{
			reasons.append(LedgerHistory.escapeHtml(variant.reason(model.lootPriceMode())))
				.append("<br>Standard and Catacombs variant tasks compared, with and without a cannon.");
		}
		if (cannon != null)
		{
			reasons.append(reasons.length() == 0 ? "" : "<br>")
				.append(LedgerHistory.escapeHtml(cannon.reason(model.lootPriceMode())))
				.append("<br>Tasks with a cannon (cannonballs fired) and without one compared, both versions.");
		}
		return reasons.append("<br>Each with ").append(TaskAdvisor.MIN_TASKS).append("+ tasks and ")
			.append(TaskAdvisor.MIN_ACTIVE_MILLIS / 60_000L).append("+ min, rates as in the Trends list. Advice only.")
			.toString();
	}

	/**
	 * The advice's reason and what it counts, as HTML without the {@code <html>} tags. The main advice pools each
	 * task's Catacombs variant and cannon tasks with its others, while the Trends list splits them, so it
	 * says so.
	 */
	private String adviceReason(TaskAdvisor.Result result)
	{
		return LedgerHistory.escapeHtml(result.reason(model.lootPriceMode()))
			+ "<br>From " + result.getTasks() + " completed tasks of this monster (n), with rates as in the Trends"
			+ " list, Catacombs variant and cannon tasks pooled with their task. Advice only."
			+ "<br>Counts monsters with " + TaskAdvisor.MIN_TASKS + "+ tasks and "
			+ TaskAdvisor.MIN_ACTIVE_MILLIS / 60_000L + "+ min; Consider block needs n of "
			+ TaskAdvisor.MIN_BLOCK_TASKS + "+. " + (result.isBoss() ? "Bosses rank only against bosses."
			: "Boss tasks are ranked separately.");
	}

	private void relayoutBox()
	{
		((GridLayout) box.getLayout()).setRows(box.getComponentCount());
		relayout.run();
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Per-completed-task metric points for a selected monster. Pure: no RuneLite types.
 *
 * <p>Samples, grouping, names and metrics follow {@link TaskRanking}: records only that are completed, not partial,
 * with kills, grouped by creature key, with Profit/h and Profit/kill in the Loot price mode, Slayer XP/h, and Points/h
 * only for records that tracked the whole assignment and are not bonus tasks ({@link TaskRanking#countsForPointsRate}).
 * Each point is one task, so a task also needs a completion date ({@code endedAt > 0}) and, for an hourly metric, at
 * least {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of active time; a per-kill point is that task's value over its
 * kills, with no minimum time.</p>
 */
final class TaskChart
{
	private static final Comparator<Point> POINT_ORDER = Comparator.comparingLong(Point::getEndedAt)
		.thenComparing(point -> point.getRecordId() == null ? "" : point.getRecordId());

	private TaskChart()
	{
	}

	/** Monsters with at least one plotted task for {@code metric}, by label ignoring case. */
	static List<Monster> monsters(Collection<LedgerRecord> records, TaskRanking.Metric metric, LootPriceMode mode,
		Map<Integer, Long> currentGe)
	{
		return monsters(records, metric, mode, currentGe, HiddenLoot.NONE);
	}

	/** As {@link #monsters(Collection, TaskRanking.Metric, LootPriceMode, Map)}, with {@code hidden}'s loot left out. */
	static List<Monster> monsters(Collection<LedgerRecord> records, TaskRanking.Metric metric, LootPriceMode mode,
		Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		Map<TaskRanking.TaskKey, Group> groups = groups(records, metric, mode, currentGe, hidden);
		List<Group> plotted = new ArrayList<>();
		for (Group group : groups.values())
		{
			if (!group.points.isEmpty())
			{
				plotted.add(group);
			}
		}
		List<Monster> result = new ArrayList<>();
		for (Group group : plotted)
		{
			result.add(new Monster(group.key, label(group, plotted), group.name.getTask()));
		}
		result.sort(Comparator.comparing(Monster::getLabel, String.CASE_INSENSITIVE_ORDER)
			.thenComparing(Monster::getLabel)
			.thenComparing(Monster::getKey));
		return Collections.unmodifiableList(result);
	}

	/** One dated metric point per plotted task of {@code monster}, oldest first. */
	static List<Point> points(Collection<LedgerRecord> records, Monster monster, TaskRanking.Metric metric,
		LootPriceMode mode, Map<Integer, Long> currentGe)
	{
		return points(records, monster, metric, mode, currentGe, HiddenLoot.NONE);
	}

	/**
	 * As {@link #points(Collection, Monster, TaskRanking.Metric, LootPriceMode, Map)}, with {@code hidden}'s loot left
	 * out.
	 */
	static List<Point> points(Collection<LedgerRecord> records, Monster monster, TaskRanking.Metric metric,
		LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		if (monster == null)
		{
			return Collections.emptyList();
		}
		Group group = groups(records, metric, mode, currentGe, hidden).get(monster.key);
		if (group == null)
		{
			return Collections.emptyList();
		}
		List<Point> result = new ArrayList<>(group.points);
		result.sort(POINT_ORDER);
		return Collections.unmodifiableList(result);
	}

	/** Every group of task samples (named from all of them), with the points for {@code metric}. */
	private static Map<TaskRanking.TaskKey, Group> groups(Collection<LedgerRecord> records,
		TaskRanking.Metric metric, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		if (records == null || records.isEmpty() || metric == null)
		{
			return Collections.emptyMap();
		}
		Map<String, Set<Integer>> idsByName = TaskRanking.creatureIdsByName(records);
		Map<TaskRanking.TaskKey, Group> groups = new LinkedHashMap<>();
		for (LedgerRecord record : records)
		{
			if (!TaskRanking.isTaskSample(record))
			{
				continue;
			}
			TaskRanking.TaskKey key = TaskRanking.taskKey(record, idsByName);
			if (key == null)
			{
				continue;
			}
			Group group = groups.computeIfAbsent(key, Group::new);
			group.name.offer(record, key);
			if (record.getEndedAt() <= 0
				|| !metric.isPerKill() && record.getActiveMillis() < TaskTimeEstimate.MIN_ACTIVE_MILLIS)
			{
				continue;
			}
			MetricValue value = metricValue(record, metric, mode, currentGe, hidden);
			if (value != null)
			{
				// A task sample has kills, so a per-kill value is never null.
				long rate = metric.isPerKill()
					? TaskRanking.perKill(value.value, record.getKills())
					: Math.round(value.value * 3_600_000d / record.getActiveMillis());
				group.points.add(new Point(record.getEndedAt(), rate, value.approximate, record.getNote(),
					record.getId()));
			}
		}
		return groups;
	}

	/**
	 * The group's name, with a suffix when another plotted group has the same name: {@code (boss)}, {@code (older
	 * records)} for a name group of records without a creature key, or {@code (task)}; the id only as a last resort,
	 * when that still leaves two the same.
	 */
	private static String label(Group group, List<Group> plotted)
	{
		String name = group.name.get();
		Map<String, Integer> kinds = new HashMap<>();
		boolean shared = false;
		for (Group other : plotted)
		{
			if (other.name.get().equalsIgnoreCase(name))
			{
				shared |= other != group;
				kinds.merge(kind(other.key), 1, Integer::sum);
			}
		}
		if (!shared)
		{
			return name;
		}
		String kind = kind(group.key);
		Integer creatureId = group.key.getCreatureId();
		if (kinds.get(kind) > 1 && creatureId != null)
		{
			return name + " (" + kind + " " + (creatureId < SessionTracker.NO_CREATURE ? -2 - creatureId : creatureId)
				+ ")";
		}
		return name + " (" + kind + ")";
	}

	private static String kind(TaskRanking.TaskKey key)
	{
		Integer creatureId = key.getCreatureId();
		if (creatureId == null)
		{
			return "older records";
		}
		return creatureId < SessionTracker.NO_CREATURE ? "boss" : "task";
	}

	/** The task's metric total as {@link TaskRanking} counts it, or {@code null} when the task has no such data. */
	private static MetricValue metricValue(LedgerRecord record, TaskRanking.Metric metric, LootPriceMode mode,
		Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		switch (metric)
		{
			case PROFIT:
			case PROFIT_PER_KILL:
				if (!LedgerHistory.isValued(record))
				{
					return null;
				}
				HistoryPricing.Values values = HistoryPricing.value(record, mode, currentGe, hidden);
				// As TaskRanking: a valued record counts only with both a loot and a supplies value.
				if (values.getLootValue() == null || values.getSuppliesGe() == null || values.getProfit() == null)
				{
					return null;
				}
				return new MetricValue(values.getProfit(), values.isProfitApproximate());
			case XP:
				Map<String, Long> xp = record.getXpGained();
				if (xp == null)
				{
					return null;
				}
				// XP recorded without a Slayer entry means no Slayer XP was gained.
				Long slayer = xp.get(SkillXp.SLAYER);
				return new MetricValue(slayer == null ? 0 : Math.max(0, slayer), false);
			case POINTS:
				return TaskRanking.countsForPointsRate(record)
					? new MetricValue(record.getPointsEarned(), false) : null;
			default:
				return null;
		}
	}

	private static final class Group
	{
		private final TaskRanking.TaskKey key;
		private final TaskRanking.GroupName name = new TaskRanking.GroupName();
		private final List<Point> points = new ArrayList<>();

		private Group(TaskRanking.TaskKey key)
		{
			this.key = key;
		}
	}

	static final class Monster
	{
		private final TaskRanking.TaskKey key;
		private final String label;
		/** The assigned task name of the record that names the group, for its icon; not part of equality. */
		private final String task;

		private Monster(TaskRanking.TaskKey key, String label, String task)
		{
			this.key = key;
			this.label = label;
			this.task = task;
		}

		/**
		 * A choice that only sizes the Monster box ({@code JComboBox#setPrototypeDisplayValue}): never in its list,
		 * never compared or hashed (it has no key).
		 */
		static Monster prototype(String label)
		{
			return new Monster(null, label, null);
		}

		String getLabel()
		{
			return label;
		}

		/**
		 * The assigned task name ({@link TaskRanking.GroupName#getTask}): a Catacombs variant or cannon group's task,
		 * whose icon the Monster choice shows; {@code null} when it had none.
		 */
		String getTask()
		{
			return task;
		}

		TaskRanking.TaskKey getKey()
		{
			return key;
		}

		@Override
		public String toString()
		{
			return label;
		}

		@Override
		public boolean equals(Object other)
		{
			return other instanceof Monster && Objects.equals(key, ((Monster) other).key);
		}

		@Override
		public int hashCode()
		{
			return Objects.hashCode(key);
		}
	}

	static final class Point
	{
		private final long endedAt;
		private final long ratePerHour;
		private final boolean approximate;
		private final String note;
		private final String recordId;

		private Point(long endedAt, long ratePerHour, boolean approximate, String note, String recordId)
		{
			this.endedAt = endedAt;
			this.ratePerHour = ratePerHour;
			this.approximate = approximate;
			this.note = note;
			this.recordId = recordId;
		}

		long getEndedAt()
		{
			return endedAt;
		}

		/** The task's rate per hour, or its value per kill for a per-kill metric. */
		long getRatePerHour()
		{
			return ratePerHour;
		}

		boolean isApproximate()
		{
			return approximate;
		}

		String getNote()
		{
			return note;
		}

		String getRecordId()
		{
			return recordId;
		}
	}

	private static final class MetricValue
	{
		private final long value;
		private final boolean approximate;

		private MetricValue(long value, boolean approximate)
		{
			this.value = value;
			this.approximate = approximate;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.List;

/** Formats the chat summary for a successfully saved completed task. */
final class TaskCompleteMessage
{
	private static final String PREFIX = "Slayer task complete: ";

	private TaskCompleteMessage()
	{
	}

	/**
	 * Formats a completed record in the selected loot price mode. Values not present in the record are omitted, as is a
	 * superior count of 0, and an approximate profit puts the sign after the {@code ~} ({@code ~+100}, {@code ~-500}).
	 */
	static String format(LedgerRecord record, LootPriceMode mode)
	{
		return format(record, mode, HiddenLoot.NONE);
	}

	/**
	 * As {@link #format(LedgerRecord, LootPriceMode)}, with the loot items {@code hidden} hides left out of the profit
	 *.
	 */
	static String format(LedgerRecord record, LootPriceMode mode, HiddenLoot hidden)
	{
		if (record == null || !record.isCompleted())
		{
			return null;
		}

		List<String> parts = new ArrayList<>();
		parts.add(record.getKills() + " " + LedgerHistory.monster(record));
		parts.add(LedgerHistory.formatDuration(record.getActiveMillis()));

		// The record was just saved, so the prices saved with it are today's.
		HistoryPricing.Values values = HistoryPricing.value(record, mode, null, hidden);
		Long profit = values.getProfit();
		if (profit != null)
		{
			String amount = LedgerHistory.formatAmount(profit, false);
			parts.add((values.isProfitApproximate() ? LedgerHistory.APPROXIMATE : "") + (profit >= 0 ? "+" : "") + amount);
		}

		Integer superiors = record.getSuperiorsSpawned();
		// Most tasks have none; "0 superiors" would only make the line longer.
		if (superiors != null && superiors > 0)
		{
			parts.add(superiors + (superiors == 1 ? " superior" : " superiors"));
		}

		return PREFIX + String.join(" · ", parts);
	}
}

package com.shmayvan.slayerledger;

import java.util.Objects;

/**
 * Who assigned a task and what completing it gave: the raw SLAYER_MASTER and SLAYER_AREA values, the area's name, and
 * (for a completed task) the Slayer points earned and the streak afterwards. Every part is {@code null} when unknown.
 * Immutable; pure (no RuneLite types). The task's {@link TaskType} is derived from it, see {@link #type(Integer)}.
 */
final class TaskContext
{
	static final TaskContext NONE = new TaskContext(null, null, null, null, null);

	private final Integer master;
	private final Integer area;
	private final String location;
	private final Integer pointsEarned;
	private final Integer taskStreak;

	private TaskContext(Integer master, Integer area, String location, Integer pointsEarned, Integer taskStreak)
	{
		this.master = master;
		this.area = area;
		this.location = location;
		this.pointsEarned = pointsEarned;
		this.taskStreak = taskStreak;
	}

	/**
	 * The assignment as read from the game.
	 *
	 * @param master   SLAYER_MASTER value; {@link SlayerMaster#NONE} or less is unknown
	 * @param area     SLAYER_AREA value (Konar's location); 0 or less is none
	 * @param location the area's name, or {@code null} when there is none or the lookup failed
	 */
	static TaskContext assignment(int master, int area, String location)
	{
		final boolean hasArea = area > 0;
		return of(master > SlayerMaster.NONE ? master : null, hasArea ? area : null,
			hasArea && location != null && !location.isEmpty() ? location : null, null, null);
	}

	/** A context from stored values ({@code null} for each unknown part); {@link #NONE} when all are unknown. */
	static TaskContext of(Integer master, Integer area, String location, Integer pointsEarned, Integer taskStreak)
	{
		if (master == null && area == null && location == null && pointsEarned == null && taskStreak == null)
		{
			return NONE;
		}
		return new TaskContext(master, area, location, pointsEarned, taskStreak);
	}

	/** This context with the completion's points earned and streak (each {@code null} when not trusted). */
	TaskContext withRewards(Integer newPointsEarned, Integer newTaskStreak)
	{
		return of(master, area, location, newPointsEarned, newTaskStreak);
	}

	/**
	 * This context with the assignment parts it doesn't know yet taken from {@code later}, a later reading of the same
	 * task's assignment: the master once its varbit has synced, the area, or the area's name once its lookup worked.
	 * Known parts are kept.
	 */
	TaskContext fillAssignment(TaskContext later)
	{
		if (later == null)
		{
			return this;
		}
		final Integer newMaster = master != null ? master : later.master;
		Integer newArea = area;
		String newLocation = location;
		if (area == null && later.area != null)
		{
			newArea = later.area;
			newLocation = later.location;
		}
		else if (area != null && location == null && area.equals(later.area))
		{
			newLocation = later.location;
		}
		return of(newMaster, newArea, newLocation, pointsEarned, taskStreak);
	}

	/** SLAYER_MASTER value, or {@code null} when unknown. */
	Integer getMaster()
	{
		return master;
	}

	/** SLAYER_AREA value, or {@code null} when the task has no area (or it is unknown). */
	Integer getArea()
	{
		return area;
	}

	/** The area's name, or {@code null}. */
	String getLocation()
	{
		return location;
	}

	/** Slayer points the completion gave, or {@code null} when unknown or not trusted. */
	Integer getPointsEarned()
	{
		return pointsEarned;
	}

	/** The streak the completion raised, as it stood afterwards, or {@code null} when unknown. */
	Integer getTaskStreak()
	{
		return taskStreak;
	}

	/** The task's type for the given creature key; see {@link TaskType#of}. */
	TaskType type(Integer creatureId)
	{
		return TaskType.of(master, creatureId);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof TaskContext))
		{
			return false;
		}
		TaskContext other = (TaskContext) o;
		return Objects.equals(master, other.master) && Objects.equals(area, other.area)
			&& Objects.equals(location, other.location) && Objects.equals(pointsEarned, other.pointsEarned)
			&& Objects.equals(taskStreak, other.taskStreak);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(master, area, location, pointsEarned, taskStreak);
	}

	@Override
	public String toString()
	{
		return "TaskContext(master=" + master + ", area=" + area + ", location=" + location + ", pointsEarned="
			+ pointsEarned + ", taskStreak=" + taskStreak + ")";
	}
}

package com.shmayvan.slayerledger;

import java.awt.Component;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;
import javax.swing.Icon;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.ListCellRenderer;

/**
 * The task icons of a drop-down's choices (the Luck meter's Task, Trends' Monster), at the small slot size
 * ({@link SmallItemIcon}). A renderer runs whenever Swing paints or measures the box, so it must not ask for sprites:
 * the section asks for its choices' icons with {@link #request} when it builds them (open and shown, never on the
 * refresh timer), each item once for the panel's life, and the renderer ({@link #install}) only reads what was asked
 * for; a choice not asked for, or no known task, shows {@link SmallItemIcon#EMPTY}. A sprite that arrives later
 * repaints the box. EDT only.
 */
final class TaskIconCache
{
	private final ItemIcons icons;
	/** Repainted when a sprite arrives. */
	private final Component target;
	/** The small icon of each item asked for. */
	private final Map<Integer, Icon> byItem = new HashMap<>();

	/**
	 * @param icons  where the sprites come from
	 * @param target repainted when a sprite arrives (the drop-down)
	 */
	TaskIconCache(ItemIcons icons, Component target)
	{
		this.icons = icons;
		this.target = target;
	}

	/** Asks for the icon of the task {@code task} ({@link TaskIcons}) unless it was asked for already. */
	void request(String task)
	{
		Integer itemId = TaskIcons.itemId(task);
		if (itemId == null || byItem.containsKey(itemId))
		{
			return;
		}
		// A label only to receive the sprite; when it arrives later, its repaint repaints the drop-down instead.
		JLabel holder = new JLabel()
		{
			@Override
			public void repaint(long tm, int x, int y, int width, int height)
			{
				if (target != null)
				{
					target.repaint();
				}
			}
		};
		SmallItemIcon.apply(icons, holder, itemId);
		byItem.put(itemId, holder.getIcon());
	}

	/** The icon asked for {@code task}, or {@link SmallItemIcon#EMPTY}; never asks for one. */
	Icon get(String task)
	{
		Integer itemId = TaskIcons.itemId(task);
		Icon icon = itemId == null ? null : byItem.get(itemId);
		return icon == null ? SmallItemIcon.EMPTY : icon;
	}

	/**
	 * Wraps {@code box}'s renderer (the look and feel's, as the History filters keep it) so each choice shows the icon of
	 * its task ({@code task} of the choice) before its text; no icon for an empty box.
	 */
	<T> void install(JComboBox<T> box, Function<T, String> task)
	{
		ListCellRenderer<? super T> renderer = box.getRenderer();
		box.setRenderer((JList<? extends T> list, T value, int index, boolean selected, boolean focus) ->
		{
			Component shown = renderer.getListCellRendererComponent(list, value, index, selected, focus);
			if (shown instanceof JLabel)
			{
				JLabel label = (JLabel) shown;
				label.setIconTextGap(4);
				label.setIcon(value == null ? null : get(task.apply(value)));
			}
			return shown;
		});
	}
}

