package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.IntFunction;

/**
 * Rules for a task's location name: how a typed name is cleaned up, which name a record is saved with, and which
 * name the panel shows. A region's name is the player's own (named once, kept per RuneScape profile); a Konar or
 * Wilderness task's assigned area ({@code taskLocation}) is its location without naming. Pure (no RuneLite types).
 */
final class TaskLocation
{
	/** Longest location name kept, in characters; longer names are cut. */
	static final int MAX_NAME_LENGTH = 40;
	/** Shown for a record without a location (older records, or a region nobody named). */
	static final String UNKNOWN = "Unknown";

	private TaskLocation()
	{
	}

	/**
	 * A location name as stored: cleaned up like a note ({@link TaskNote#normalize(String, int)}: whitespace runs become
	 * one space, the ends are trimmed) and cut to {@link #MAX_NAME_LENGTH} characters.
	 *
	 * @return the name, or {@code null} when nothing is left (an empty name is never stored)
	 */
	static String normalizeName(String raw)
	{
		return TaskNote.normalize(raw, MAX_NAME_LENGTH);
	}

	/**
	 * The location name a record is saved with: the task's assigned area when it has one (Konar, Wilderness), otherwise
	 * the dominant region's name.
	 *
	 * @param taskLocation the task's assigned area name, or {@code null}
	 * @param regionName   the dominant region's name, or {@code null} when unnamed or there is no region
	 * @return the name, or {@code null} when neither is known
	 */
	static String recordName(String taskLocation, String regionName)
	{
		final String area = normalizeName(taskLocation);
		return area != null ? area : normalizeName(regionName);
	}

	/**
	 * The location a history row shows: the record's own name, else its assigned area (an older Konar or Wilderness
	 * record), else the current name of its region (named after the record was saved; display only, the file is not
	 * changed), else {@link #UNKNOWN}.
	 *
	 * @param regionNames region id to its name, {@code null} when unnamed or not known yet
	 */
	static String displayName(LedgerRecord record, IntFunction<String> regionNames)
	{
		final String name = recordLocation(record, regionNames);
		return name != null ? name : UNKNOWN;
	}

	/**
	 * A saved record's location, as {@link #displayName} finds it: its own name, else its assigned area, else its
	 * region's current name (a record saved before its region was named).
	 *
	 * @return the name, or {@code null} when none is known (never {@link #UNKNOWN})
	 */
	static String recordLocation(LedgerRecord record, IntFunction<String> regionNames)
	{
		final String own = normalizeName(record.getLocation());
		if (own != null)
		{
			return own;
		}
		return liveName(record.getTaskLocation(), record.getLocationRegion(), regionNames);
	}

	/**
	 * The current task's location, for same-location estimates (Part B): its assigned area (Konar, Wilderness),
	 * else the name of the running or paused session's region with the most kills, else the name of the region the
	 * player is in now.
	 *
	 * @param sessionRegion the running or paused session's dominant region, or {@code null}
	 * @param currentRegion the region the player is in now, or {@link LocationTally#NO_REGION}
	 * @return the name, or {@code null} while unknown
	 */
	static String currentName(String taskLocation, Integer sessionRegion, int currentRegion,
		IntFunction<String> regionNames)
	{
		final String name = liveName(taskLocation, sessionRegion, regionNames);
		if (name != null || !LocationTally.isRegion(currentRegion) || regionNames == null)
		{
			return name;
		}
		return normalizeName(regionNames.apply(currentRegion));
	}

	/**
	 * A location name as names are compared: {@link #normalizeName}d and lower case, so names that differ only in
	 * case or spacing are the same place.
	 *
	 * @return the key, or {@code null} for no name
	 */
	static String matchKey(String name)
	{
		final String normalized = normalizeName(name);
		return normalized == null ? null : normalized.toLowerCase(Locale.ROOT);
	}

	/** Whether two location names are the same place ({@link #matchKey}); no name never matches. */
	static boolean sameLocation(String left, String right)
	{
		final String key = matchKey(left);
		return key != null && key.equals(matchKey(right));
	}

	/**
	 * The names the "Name this location" prompt suggests: the Wiki's locations of the task, in the Wiki's order, then
	 * the player's own names (for other regions), sorted ignoring case. Each is {@link #normalizeName}d; blank names and
	 * repeats ({@link #sameLocation}, the first spelling kept) are left out.
	 */
	static List<String> suggestions(Collection<String> bundled, Collection<String> own)
	{
		final List<String> suggestions = new ArrayList<>();
		final Set<String> seen = new HashSet<>();
		addSuggestions(suggestions, seen, bundled);
		if (own != null)
		{
			final List<String> sorted = new ArrayList<>();
			for (String name : own)
			{
				if (name != null)
				{
					sorted.add(name);
				}
			}
			sorted.sort(String.CASE_INSENSITIVE_ORDER.thenComparing(Comparator.naturalOrder()));
			addSuggestions(suggestions, seen, sorted);
		}
		return Collections.unmodifiableList(suggestions);
	}

	private static void addSuggestions(List<String> suggestions, Set<String> seen, Collection<String> names)
	{
		if (names == null)
		{
			return;
		}
		for (String raw : names)
		{
			final String name = normalizeName(raw);
			if (name != null && seen.add(matchKey(name)))
			{
				suggestions.add(name);
			}
		}
	}

	/**
	 * The live session's location: its assigned area, else the name of its dominant region.
	 *
	 * @param region the session's dominant region, or {@code null} when no kill was tallied yet
	 * @return the name, or {@code null} while unknown
	 */
	static String liveName(String taskLocation, Integer region, IntFunction<String> regionNames)
	{
		final String area = normalizeName(taskLocation);
		if (area != null)
		{
			return area;
		}
		if (region == null || !LocationTally.isRegion(region) || regionNames == null)
		{
			return null;
		}
		return normalizeName(regionNames.apply(region));
	}

	/** The location line of the live task box and the history tooltip: {@code Location: Smoke Dungeon}. */
	static String format(String name)
	{
		return "Location: " + (name == null ? UNKNOWN : name);
	}

	/** The question of the history's "Edit location" dialog. */
	static String editPrompt(LedgerRecord record)
	{
		final int creatureId = record.getCreatureId() == null ? SessionTracker.NO_CREATURE : record.getCreatureId();
		return "Location of this " + LedgerRecord.displayName(record.getMonster(), creatureId)
			+ " task (empty to remove its own name):";
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * The bundled list of each Slayer task's locations, from the Old School RuneScape Wiki. An instance holds one
 * validated snapshot ({@link #load}); the lookup is pure (no RuneLite types).
 */
@Slf4j
final class TaskLocations
{
	/** The bundled snapshot, relative to this class. */
	static final String SNAPSHOT_RESOURCE = "slayer-task-locations.json";
	/** The only snapshot schema version this build reads. */
	static final int SNAPSHOT_VERSION = 1;

	private final Snapshot snapshot;
	/** Unmodifiable location lists by {@link TaskStatistics#normalize}d task name. */
	private final Map<String, List<String>> locationsByTask;

	private TaskLocations(Snapshot snapshot)
	{
		this.snapshot = snapshot;
		Map<String, List<String>> byTask = new HashMap<>();
		for (Entry entry : snapshot.tasks)
		{
			byTask.put(TaskStatistics.normalize(entry.task),
				Collections.unmodifiableList(new ArrayList<>(entry.locations)));
		}
		this.locationsByTask = byTask;
	}

	/**
	 * Reads and validates the snapshot {@code resource} (relative to this class) with {@code gson}, the client's
	 * injected instance. Returns {@code null}, logged at debug level, when the resource is missing, unreadable,
	 * malformed or invalid, so bad data never breaks the plugin.
	 */
	static TaskLocations load(Gson gson, String resource)
	{
		try (InputStream stream = TaskLocations.class.getResourceAsStream(resource))
		{
			if (stream == null)
			{
				log.debug("Slayer task locations {} are missing", resource);
				return null;
			}
			return parse(gson, new InputStreamReader(stream, StandardCharsets.UTF_8));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Unable to load the Slayer task locations {}", resource, e);
			return null;
		}
	}

	/** Parses and validates a snapshot. Throws a {@link RuntimeException} when it is malformed or invalid. */
	static TaskLocations parse(Gson gson, Reader reader)
	{
		Snapshot snapshot = gson.fromJson(reader, Snapshot.class);
		validate(snapshot);
		return new TaskLocations(snapshot);
	}

	/**
	 * The Wiki's locations for {@code taskName}, matched by the {@link TaskStatistics#normalize}d name (trimmed, lower
	 * case), in the Wiki's order. Unmodifiable; empty when the task is unknown or the name is {@code null}.
	 */
	List<String> locationsFor(String taskName)
	{
		List<String> locations = locationsByTask.get(TaskStatistics.normalize(taskName));
		return locations == null ? Collections.emptyList() : locations;
	}

	/** The task names in the snapshot, in snapshot order. Unmodifiable. */
	List<String> tasks()
	{
		List<String> tasks = new ArrayList<>(snapshot.tasks.size());
		for (Entry entry : snapshot.tasks)
		{
			tasks.add(entry.task);
		}
		return Collections.unmodifiableList(tasks);
	}

	/** Snapshot metadata, for attribution. */
	String getRetrieved()
	{
		return snapshot.retrieved;
	}

	String getSource()
	{
		return snapshot.source;
	}

	String getLicense()
	{
		return snapshot.license;
	}

	String getAttribution()
	{
		return snapshot.attribution;
	}

	private static void validate(Snapshot snapshot)
	{
		if (snapshot == null || snapshot.version != SNAPSHOT_VERSION || snapshot.tasks == null
			|| snapshot.tasks.isEmpty() || isBlank(snapshot.source) || isBlank(snapshot.license)
			|| isBlank(snapshot.licenseUrl) || isBlank(snapshot.contributors) || isBlank(snapshot.retrieved)
			|| isBlank(snapshot.attribution))
		{
			throw new IllegalStateException("Slayer task locations metadata is missing or unsupported.");
		}
		Set<String> tasks = new HashSet<>();
		for (Entry entry : snapshot.tasks)
		{
			if (entry == null || isBlank(entry.task) || isBlank(entry.article) || isBlank(entry.page)
				|| entry.revision <= 0 || entry.locations == null || entry.locations.isEmpty()
				|| !tasks.add(TaskStatistics.normalize(entry.task)))
			{
				throw new IllegalStateException("Slayer task locations have an invalid or duplicate task.");
			}
			Set<String> locations = new HashSet<>();
			for (String location : entry.locations)
			{
				if (isBlank(location) || !locations.add(TaskStatistics.normalize(location)))
				{
					throw new IllegalStateException("Slayer task locations have a blank or duplicate location.");
				}
			}
		}
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static final class Snapshot
	{
		private int version;
		private String source;
		private String license;
		private String licenseUrl;
		private String contributors;
		private String retrieved;
		private String attribution;
		private List<Entry> tasks;
	}

	private static final class Entry
	{
		private String task;
		private String article;
		private String page;
		private long revision;
		private List<String> locations;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Rules for the free-text note on a task (for example "Barrage" or "Prayer gear"): how a typed note is cleaned up and
 * which notes the panel offers for reuse. Pure; no RuneLite, Swing or file access.
 */
final class TaskNote
{
	/** Longest note kept, in characters; longer notes are cut. */
	static final int MAX_LENGTH = 60;
	/** Most notes offered in the recent-notes list. */
	static final int MAX_RECENT = 8;
	/** Notes offered before (and after) the player's own, so common labels are spelled the same way every time. */
	static final List<String> DEFAULTS = Collections.unmodifiableList(Arrays.asList(
		"Prayer gear", "Strength gear", "Barrage", "Range pray", "Cannon"));

	private TaskNote()
	{
	}

	/**
	 * The note as stored: control characters become spaces, runs of whitespace become one space, the ends are trimmed
	 * and it is cut to {@link #MAX_LENGTH} characters (never in the middle of a surrogate pair).
	 *
	 * @return the note, or {@code null} when nothing is left (or {@code raw} is {@code null})
	 */
	static String normalize(String raw)
	{
		return normalize(raw, MAX_LENGTH);
	}

	/**
	 * {@link #normalize(String)} with another length limit, for other short player-typed labels (for example
	 * {@link TaskLocation#normalizeName location names}).
	 *
	 * @param maxLength longest result kept, in characters
	 */
	static String normalize(String raw, int maxLength)
	{
		if (raw == null)
		{
			return null;
		}
		StringBuilder sb = new StringBuilder(Math.min(raw.length(), maxLength + 1));
		boolean pendingSpace = false;
		for (int i = 0; i < raw.length(); )
		{
			int cp = raw.codePointAt(i);
			i += Character.charCount(cp);
			if (Character.isISOControl(cp) || Character.isWhitespace(cp) || Character.isSpaceChar(cp)
				|| Character.getType(cp) == Character.FORMAT)
			{
				// Separators become one space between words; format characters (e.g. zero-width) are dropped too.
				pendingSpace |= Character.getType(cp) != Character.FORMAT;
				continue;
			}
			int extra = (pendingSpace && sb.length() > 0 ? 1 : 0) + Character.charCount(cp);
			if (sb.length() + extra > maxLength)
			{
				break;
			}
			if (pendingSpace && sb.length() > 0)
			{
				sb.append(' ');
			}
			pendingSpace = false;
			sb.appendCodePoint(cp);
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	/**
	 * Notes to offer for reuse: the distinct notes of the given records, newest first, then the {@link #DEFAULTS}, at
	 * most {@link #MAX_RECENT}. Notes differing only in case count once, with the newest record's spelling.
	 */
	static List<String> recentNotes(Collection<LedgerRecord> records)
	{
		List<String> notes = new ArrayList<>();
		for (LedgerRecord r : LedgerHistory.sortNewestFirst(records))
		{
			notes.add(r.getNote());
		}
		return recentNotes(notes);
	}

	/**
	 * Like {@link #recentNotes(Collection)}, from notes already ordered newest first. Each is normalized; empty and
	 * {@code null} ones are skipped.
	 */
	static List<String> recentNotes(List<String> newestFirst)
	{
		List<String> result = new ArrayList<>(MAX_RECENT);
		Set<String> seen = new HashSet<>();
		addDistinct(newestFirst, result, seen);
		addDistinct(DEFAULTS, result, seen);
		return result;
	}

	private static void addDistinct(List<String> notes, List<String> result, Set<String> seen)
	{
		for (String raw : notes)
		{
			if (result.size() >= MAX_RECENT)
			{
				return;
			}
			String note = normalize(raw);
			if (note != null && seen.add(note.toLowerCase(Locale.ROOT)))
			{
				result.add(note);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;

/**
 * Ranks monsters by productivity metrics from completed task history. Pure: no RuneLite types.
 *
 * <p>Samples are records only (never assignment entries) that are completed, not partial, with kills and active time.
 * Each hourly metric pools its totals and active time over the samples that have that metric; a monster gets no rate
 * for it until that pooled time reaches {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} (it is still listed, last).
 * {@link Metric#PROFIT_PER_KILL} pools profit and kills instead, with no minimum time.</p>
 *
 * <p><b>Catacombs variants and cannon tasks</b>: a record done on its task's Catacombs variant
 * ({@link LedgerRecord#getVariant}) or with a cannon ({@link LedgerRecord#cannonTask}) is its own group, named as
 * {@link LedgerRecord#groupName} names it (for example "Deviant spectres" or "Dust devils (cannon)"), apart from the
 * task's other records ({@link Split#ALL}, the Trends list and chart). The task advisor's ranking pools them again
 * ({@link Split#NONE}), as it did before; its version advice splits one dimension at a time.</p>
 */
final class TaskRanking
{
	/** Which of a task's records are groups of their own. */
	enum Split
	{
		/** One group per task, every version and cannon use pooled: the task advisor's ranking. */
		NONE(false, false),
		/** The Catacombs variant apart, cannon use pooled: the advisor's variant advice. */
		VARIANT(true, false),
		/** Cannon tasks apart, versions pooled: the advisor's cannon advice. */
		CANNON(false, true),
		/** Both apart: the Trends list and chart. */
		ALL(true, true);

		private final boolean byVariant;
		private final boolean byCannon;

		Split(boolean byVariant, boolean byCannon)
		{
			this.byVariant = byVariant;
			this.byCannon = byCannon;
		}
	}

	enum Metric
	{
		/** Loot in the "Loot price" mode minus supplies at GE, per hour. */
		PROFIT,
		/**
		 * The same profit as {@link #PROFIT}, per kill: the profit of the tasks that have one over their kills.
		 * Not a task advisor goal ({@link TaskAdvisorGoal}).
		 */
		PROFIT_PER_KILL,
		/** Slayer XP only (the {@link SkillXp#SLAYER} entry of a record's XP), per hour. */
		XP,
		/** Slayer points per hour, over records that tracked the whole assignment and are not bonus tasks only. */
		POINTS;

		/**
		 * The metric's name as shown: "Profit (GE)/h" or "Profit (HA)/h", "Profit (GE)/kill" or "Profit (HA)/kill",
		 * "Slayer XP/h", "Points/h".
		 */
		String label(LootPriceMode mode)
		{
			switch (this)
			{
				case XP:
					return "Slayer XP/h";
				case POINTS:
					return "Points/h";
				case PROFIT_PER_KILL:
					return LedgerHistory.profitName(mode == null ? LootPriceMode.GE : mode) + "/kill";
				default:
					return LedgerHistory.profitName(mode == null ? LootPriceMode.GE : mode) + "/h";
			}
		}

		/** Whether the metric is per kill rather than per active hour, so it needs no minimum active time. */
		boolean isPerKill()
		{
			return this == PROFIT_PER_KILL;
		}

		@Override
		public String toString()
		{
			return label(LootPriceMode.GE);
		}
	}

	/** Rate first (highest first, no rate last), then name ignoring case, then name. */
	private static final Comparator<Entry> ORDER = Comparator
		.comparing(Entry::getRatePerHour, Comparator.nullsLast(Comparator.<Long>reverseOrder()))
		.thenComparing(Entry::getMonster, String.CASE_INSENSITIVE_ORDER)
		.thenComparing(Entry::getMonster);

	private TaskRanking()
	{
	}

	/**
	 * Builds a pooled hourly rate for each monster: metric totals divided by the active time of records that contain
	 * that metric. Every metric reports its own sample count. Outliers are not trimmed. A monster whose pooled active
	 * time for the metric is under {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} has a {@code null} rate and sorts last.
	 * A {@linkplain Metric#isPerKill per-kill} metric divides by the kills of the same records instead, with no
	 * minimum time.
	 */
	static List<Entry> rank(Collection<LedgerRecord> records, Metric metric, LootPriceMode mode,
		Map<Integer, Long> currentGe)
	{
		return rank(records, metric, mode, currentGe, HiddenLoot.NONE, Split.ALL);
	}

	/** As {@link #rank(Collection, Metric, LootPriceMode, Map)}, with {@code hidden}'s loot left out of the profit. */
	static List<Entry> rank(Collection<LedgerRecord> records, Metric metric, LootPriceMode mode,
		Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		return rank(records, metric, mode, currentGe, hidden, Split.ALL);
	}

	/**
	 * As {@link #rank(Collection, Metric, LootPriceMode, Map, HiddenLoot)}, with a task's records grouped as
	 * {@code split} says: {@link Split#ALL} as the Trends list, {@link Split#NONE} pooled as the task
	 * advisor ranks them.
	 */
	static List<Entry> rank(Collection<LedgerRecord> records, Metric metric, LootPriceMode mode,
		Map<Integer, Long> currentGe, HiddenLoot hidden, Split split)
	{
		if (records == null || records.isEmpty() || metric == null)
		{
			return Collections.emptyList();
		}

		Map<String, Set<Integer>> creatureIdsByName = creatureIdsByName(records);
		Map<TaskKey, Aggregate> aggregates = new TreeMap<>();
		for (LedgerRecord record : records)
		{
			if (!isTaskSample(record))
			{
				continue;
			}
			TaskKey key = taskKey(record, creatureIdsByName, split);
			if (key == null)
			{
				continue;
			}
			Aggregate aggregate = aggregates.computeIfAbsent(key, k -> new Aggregate());
			aggregate.name.offer(record, key);
			aggregate.add(record, metric, mode, currentGe, hidden);
		}

		List<Entry> entries = new ArrayList<>();
		for (Map.Entry<TaskKey, Aggregate> aggregate : aggregates.entrySet())
		{
			Entry entry = aggregate.getValue().entry(aggregate.getKey(), metric);
			if (entry != null)
			{
				entries.add(entry);
			}
		}
		entries.sort(ORDER);
		return Collections.unmodifiableList(entries);
	}

	/** A completed, not partial record with kills and active time: the samples rankings and charts use. */
	static boolean isTaskSample(LedgerRecord record)
	{
		return record != null && record.isCompleted() && !record.isPartial() && record.getKills() > 0
			&& record.getActiveMillis() > 0;
	}

	/** The creature ids seen for each normalized name among the task samples, to place records without an id. */
	static Map<String, Set<Integer>> creatureIdsByName(Collection<LedgerRecord> records)
	{
		Map<String, Set<Integer>> creatureIdsByName = new HashMap<>();
		for (LedgerRecord record : records)
		{
			if (isTaskSample(record) && record.getCreatureId() != null)
			{
				String name = TaskStatistics.normalize(record.getMonster());
				if (name != null)
				{
					creatureIdsByName.computeIfAbsent(name, n -> new HashSet<>()).add(record.getCreatureId());
				}
			}
		}
		return creatureIdsByName;
	}

	/**
	 * Whether the record's session tracked the whole assignment (it started at the assigned size), so its points
	 * belong to all of the task's active time. Owner decision: a task whose session started part-way through
	 * is left out of Points/h only.
	 */
	static boolean coversWholeTask(LedgerRecord record)
	{
		Integer original = record.getOriginalAmount();
		return original != null && record.getInitialAmount() >= original;
	}

	/**
	 * Whether a record's points count for Points/h (the Trends list and chart, and the task advisor): known,
	 * non-negative points, a task tracked from the full assigned amount ({@link #coversWholeTask}), and not a
	 * bonus-points task ({@link StreakMilestone#isMilestone}). A record without a stored streak still counts.
	 * A record's own points (History tooltip) are unaffected.
	 */
	static boolean countsForPointsRate(LedgerRecord record)
	{
		Integer points = record.getPointsEarned();
		return points != null && points >= 0 && coversWholeTask(record)
			&& !StreakMilestone.isMilestone(record.getTaskStreak());
	}

	/**
	 * The group the task advisor's ranking ({@link #rank} with {@link Split#NONE}) puts the current task's records in
	 *, whichever version and cannon use: its creature key, or with none
	 * ({@link SessionTracker#NO_CREATURE}) the group its name gets among {@code records}, as {@link #taskKey} places a
	 * record without one. When no task sample is in the creature key's group (the monster's history is only older
	 * records without an id), its name key instead, so it matches what the History estimate counts. {@code null} for
	 * no creature key and a blank name.
	 */
	static TaskKey currentTaskKey(Collection<LedgerRecord> records, int creatureId, String monster)
	{
		Map<String, Set<Integer>> creatureIdsByName = records == null
			? Collections.emptyMap()
			: creatureIdsByName(records);
		if (creatureId != SessionTracker.NO_CREATURE)
		{
			TaskKey creature = TaskKey.forCreature(creatureId);
			String name = TaskStatistics.normalize(monster);
			if (name == null || records == null)
			{
				return creature;
			}
			for (LedgerRecord record : records)
			{
				if (isTaskSample(record) && creature.equals(taskKey(record, creatureIdsByName, Split.NONE)))
				{
					return creature;
				}
			}
			return TaskKey.forName(name);
		}
		LedgerRecord current = new LedgerRecord();
		current.setMonster(monster);
		return taskKey(current, creatureIdsByName, Split.NONE);
	}

	/**
	 * The group of one version of the current task in a {@link #rank} ranking split by version or cannon:
	 * {@link #currentTaskKey} with {@code variant} ({@link CatacombsVariants.Variant#getName}, or {@code null} for the
	 * standard monster or versions pooled) and {@code cannon} (cannon tasks, or without a cannon or cannon use pooled).
	 * {@code null} as {@link #currentTaskKey}.
	 */
	static TaskKey currentTaskKey(Collection<LedgerRecord> records, int creatureId, String monster, String variant,
		boolean cannon)
	{
		TaskKey task = currentTaskKey(records, creatureId, monster);
		return task == null ? null : task.withVersion(TaskStatistics.normalize(variant), cannon);
	}

	/**
	 * {@link #taskKey(LedgerRecord, Map, Split)} split by both, as the Trends list and chart: a Catacombs
	 * variant record and a cannon task are groups of their own.
	 */
	static TaskKey taskKey(LedgerRecord record, Map<String, Set<Integer>> creatureIdsByName)
	{
		return taskKey(record, creatureIdsByName, Split.ALL);
	}

	/**
	 * The record's group: its creature key, or for a record without one, the single creature key its name has among
	 * {@code creatureIdsByName}, else its normalized name. As {@code split} says, a record done on a Catacombs variant
	 * or with a cannon is in that key's group for its version instead ({@link TaskKey#withVersion}).
	 * {@code null} for a blank name without a creature key.
	 */
	static TaskKey taskKey(LedgerRecord record, Map<String, Set<Integer>> creatureIdsByName, Split split)
	{
		TaskKey task = taskKeyOfTask(record, creatureIdsByName);
		if (task == null)
		{
			return null;
		}
		return task.withVersion(split.byVariant ? TaskStatistics.normalize(record.getVariant()) : null,
			split.byCannon && record.cannonTask());
	}

	private static TaskKey taskKeyOfTask(LedgerRecord record, Map<String, Set<Integer>> creatureIdsByName)
	{
		Integer creatureId = record.getCreatureId();
		String name = TaskStatistics.normalize(record.getMonster());
		if (creatureId != null)
		{
			return TaskKey.forCreature(creatureId);
		}
		if (name == null)
		{
			return null;
		}
		Set<Integer> ids = creatureIdsByName.get(name);
		return ids != null && ids.size() == 1
			? TaskKey.forCreature(ids.iterator().next())
			: TaskKey.forName(name);
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** As {@link SkillXp#perHour}: no rate until there is {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of time. */
	static Long perHour(long total, long activeMillis)
	{
		if (activeMillis < TaskTimeEstimate.MIN_ACTIVE_MILLIS)
		{
			return null;
		}
		return Math.round(total * 3_600_000d / activeMillis);
	}

	/** {@code total} per kill, or {@code null} without kills; no minimum time. */
	static Long perKill(long total, long kills)
	{
		return kills <= 0 ? null : Math.round(total / (double) kills);
	}

	static final class Entry
	{
		private final TaskKey key;
		private final String monster;
		private final Long ratePerHour;
		private final int sampleCount;
		private final long activeMillis;
		private final boolean approximate;
		/** The assigned task name of the record that names the entry ({@link GroupName#getTask}), for its icon. */
		private final String task;

		private Entry(TaskKey key, String monster, Long ratePerHour, int sampleCount, long activeMillis,
			boolean approximate, String task)
		{
			this.key = key;
			this.monster = monster;
			this.task = task;
			this.ratePerHour = ratePerHour;
			this.sampleCount = sampleCount;
			this.activeMillis = activeMillis;
			this.approximate = approximate;
		}

		/** The group the entry's records are in ({@link #taskKey}). */
		TaskKey getKey()
		{
			return key;
		}

		String getMonster()
		{
			return monster;
		}

		/**
		 * The assigned task name ({@link LedgerRecord#getMonster}) of the record that names the entry, without its
		 * Catacombs variant or cannon use, for its icon ({@link TaskIcons}); {@code null} when it had none.
		 */
		String getTask()
		{
			return task;
		}

		/**
		 * The pooled rate per hour, or {@code null} while the metric has under a minute of active time; for a
		 * {@linkplain Metric#isPerKill per-kill} metric, the pooled value per kill instead.
		 */
		Long getRatePerHour()
		{
			return ratePerHour;
		}

		int getSampleCount()
		{
			return sampleCount;
		}

		/** The pooled active time of the samples with the metric (the rate's denominator), in milliseconds. */
		long getActiveMillis()
		{
			return activeMillis;
		}

		boolean isApproximate()
		{
			return approximate;
		}
	}

	/**
	 * A group's display name: the trimmed name of a record with a creature id when there is one, as
	 * {@link LedgerRecord#groupName} names it for the group's version: the variant's name for a Catacombs variant group
	 *, with {@link CannonTasks#SUFFIX} for a cannon group.
	 */
	static final class GroupName
	{
		private String monster;
		/** The assigned task name of the record {@link #monster} came from ({@link #getTask}). */
		private String task;
		/** Whether {@link #monster} came from a record with a creature id (preferred over a name-only one). */
		private boolean monsterFromCreatureId;

		/** Takes the record's trimmed name, until there is one from a record with a creature id. */
		void offer(LedgerRecord record, TaskKey key)
		{
			boolean fromCreatureId = record.getCreatureId() != null;
			if (monster != null && (monsterFromCreatureId || !fromCreatureId))
			{
				return;
			}
			String groupName = key.variant != null ? record.versionName() : record.getMonster();
			String trimmed = groupName == null ? null : groupName.trim();
			int creatureId = key.creatureId == null ? SessionTracker.NO_CREATURE : key.creatureId;
			monster = CannonTasks.name(
				LedgerRecord.displayName(trimmed == null || trimmed.isEmpty() ? null : trimmed, creatureId), key.cannon);
			task = record.getMonster();
			monsterFromCreatureId = fromCreatureId;
		}

		String get()
		{
			return monster;
		}

		/**
		 * The assigned task name ({@link LedgerRecord#getMonster}) of the record that named the group: a Catacombs
		 * variant or cannon group's task, whose icon it shows; {@code null} when it had none.
		 */
		String getTask()
		{
			return task;
		}
	}

	private static final class Aggregate
	{
		private final GroupName name = new GroupName();
		private long activeMillis;
		private long kills;
		private long total;
		private int samples;
		private boolean approximate;

		private void add(LedgerRecord record, Metric metric, LootPriceMode mode, Map<Integer, Long> currentGe,
			HiddenLoot hidden)
		{
			long value;
			boolean isApproximate = false;
			switch (metric)
			{
				case PROFIT:
				case PROFIT_PER_KILL:
					if (!LedgerHistory.isValued(record))
					{
						return;
					}
					HistoryPricing.Values prices = HistoryPricing.value(record, mode, currentGe, hidden);
					// As TaskStatistics: a valued record counts only with both a loot and a supplies value.
					if (prices.getLootValue() == null || prices.getSuppliesGe() == null || prices.getProfit() == null)
					{
						return;
					}
					value = prices.getProfit();
					isApproximate = prices.isProfitApproximate();
					break;
				case XP:
					Map<String, Long> xp = record.getXpGained();
					if (xp == null)
					{
						return;
					}
					// XP recorded without a Slayer entry means no Slayer XP was gained.
					Long slayer = xp.get(SkillXp.SLAYER);
					value = slayer == null ? 0 : Math.max(0, slayer);
					break;
				case POINTS:
					if (!countsForPointsRate(record))
					{
						return;
					}
					value = record.getPointsEarned().longValue();
					break;
				default:
					return;
			}
			total = saturatedAdd(total, value);
			activeMillis = saturatedAdd(activeMillis, record.getActiveMillis());
			kills = saturatedAdd(kills, record.getKills());
			samples++;
			approximate |= isApproximate;
		}

		private Entry entry(TaskKey key, Metric metric)
		{
			if (samples == 0 || activeMillis <= 0)
			{
				return null;
			}
			Long rate = metric.isPerKill() ? perKill(total, kills) : perHour(total, activeMillis);
			return new Entry(key, name.get(), rate, samples, activeMillis, approximate, name.getTask());
		}
	}

	/**
	 * A ranking or chart group: a creature key, or a normalized name for records without one; the normalized name of
	 * the task's Catacombs variant, or {@code null} for the standard monster (or both pooled); and whether it is
	 * the task's cannon tasks ({@code false} for tasks without a cannon, or both pooled).
	 */
	static final class TaskKey implements Comparable<TaskKey>
	{
		private final Integer creatureId;
		private final String name;
		private final String variant;
		private final boolean cannon;

		private TaskKey(Integer creatureId, String name, String variant, boolean cannon)
		{
			this.creatureId = creatureId;
			this.name = name;
			this.variant = variant;
			this.cannon = cannon;
		}

		private static TaskKey forCreature(int creatureId)
		{
			return new TaskKey(creatureId, null, null, false);
		}

		private static TaskKey forName(String name)
		{
			return new TaskKey(null, name, null, false);
		}

		/**
		 * This task's group for its version {@code variant} (normalized; {@code null} for the standard monster) and
		 * {@code cannon} use.
		 */
		TaskKey withVersion(String variant, boolean cannon)
		{
			return Objects.equals(variant, this.variant) && cannon == this.cannon
				? this : new TaskKey(creatureId, name, variant, cannon);
		}

		/** The normalized name of the group's Catacombs variant, or {@code null} for the standard monster. */
		String getVariant()
		{
			return variant;
		}

		/** The creature key ({@code < -1} for a boss task), or {@code null} for a name group. */
		Integer getCreatureId()
		{
			return creatureId;
		}

		@Override
		public int compareTo(TaskKey other)
		{
			if (creatureId != null && other.creatureId == null)
			{
				return -1;
			}
			if (creatureId == null && other.creatureId != null)
			{
				return 1;
			}
			int task = creatureId != null ? creatureId.compareTo(other.creatureId) : name.compareTo(other.name);
			if (task != 0)
			{
				return task;
			}
			// The standard monster first, then its variant; each without a cannon first, then with one.
			int version = Comparator.nullsFirst(Comparator.<String>naturalOrder()).compare(variant, other.variant);
			return version != 0 ? version : Boolean.compare(cannon, other.cannon);
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof TaskKey))
			{
				return false;
			}
			TaskKey that = (TaskKey) other;
			return Objects.equals(creatureId, that.creatureId) && Objects.equals(name, that.name)
				&& Objects.equals(variant, that.variant) && cannon == that.cannon;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(creatureId, name, variant, cannon);
		}
	}
}

package com.shmayvan.slayerledger;

/**
 * Works out what a task completion gave: the Slayer points earned (the SLAYER_POINTS varbit, 4068) and the streak the
 * completion raised. Read on the same settled ticks as {@link CompletionSignal}. Pure (no RuneLite types) and not
 * thread-safe; the plugin uses it on the client thread only.
 *
 * <p>Points earned are the change from the reading just before the completion tick to the latest reading. Points
 * spent earlier in the task don't matter, since the baseline is the last reading before the completion. The change
 * is followed after the completion tick ({@link #startCompletion}, {@link #earned}) while the completed session is
 * held for late loot, in case the points arrive a tick after the streak counter. It is {@code null}, never negative,
 * when it can't be trusted:</p>
 * <ul>
 *     <li>there is no reading before the completion: the first reading after {@link #reset()} (after login, a world
 *     hop or a lost connection) only sets the baseline, as it does for {@link CompletionSignal}, so a login resync is
 *     never counted;</li>
 *     <li>the points went down (spent on the completion tick or just after).</li>
 * </ul>
 */
final class TaskRewards
{
	/** Reading before the latest, or {@code null}. */
	private Integer previous;
	/** Latest reading, or {@code null} after {@link #reset()}. */
	private Integer latest;
	/** Session whose completion is being followed, or {@code null} when none is. */
	private String sessionId;
	/** Points before the followed completion, or {@code null} when unknown. */
	private Integer completionBaseline;
	/** Streak after the followed completion, or {@code null} when unknown. */
	private Integer completionStreak;

	/** Forgets every reading and stops following. */
	void reset()
	{
		previous = null;
		latest = null;
		stopFollowing();
	}

	/** Records this settled tick's SLAYER_POINTS reading. Call once per settled tick, before {@link #startCompletion}. */
	void update(int points)
	{
		previous = latest;
		latest = points;
	}

	/**
	 * Starts following a completion signalled on this tick.
	 *
	 * @param completedSessionId the completed session
	 * @param counters           this tick's completion counters (as passed to {@link CompletionSignal#update})
	 * @param incrementedCounter {@link CompletionSignal#incrementedCounter()} for this tick
	 */
	void startCompletion(String completedSessionId, int[] counters, int incrementedCounter)
	{
		sessionId = completedSessionId;
		completionBaseline = previous;
		completionStreak = streakAfter(counters, incrementedCounter);
	}

	/** Whether a completion is being followed. */
	boolean isFollowing()
	{
		return sessionId != null;
	}

	/** The session whose completion is being followed, or {@code null}. */
	String getSessionId()
	{
		return sessionId;
	}

	/** Points earned by the followed completion as of the latest reading, or {@code null}; see the class comment. */
	Integer earned()
	{
		return isFollowing() ? pointsEarned(completionBaseline, latest) : null;
	}

	/** Streak after the followed completion, or {@code null}. */
	Integer streak()
	{
		return isFollowing() ? completionStreak : null;
	}

	/** Stops following the completion (it has been saved, or can no longer be updated). */
	void stopFollowing()
	{
		sessionId = null;
		completionBaseline = null;
		completionStreak = null;
	}

	/** {@code after - before}, or {@code null} when either is unknown or the points went down. */
	static Integer pointsEarned(Integer before, Integer after)
	{
		if (before == null || after == null || after < before)
		{
			return null;
		}
		return after - before;
	}

	/**
	 * The streak a completion raised: the counter that went up, as it stands now, or {@code null} when it is not
	 * known which counter that was.
	 */
	static Integer streakAfter(int[] counters, int incrementedCounter)
	{
		if (counters == null || incrementedCounter < 0 || incrementedCounter >= counters.length)
		{
			return null;
		}
		return counters[incrementedCounter];
	}
}

package com.shmayvan.slayerledger;

import java.util.Objects;

/**
 * Which of a task's records the current task's statistics use, on two independent dimensions:
 * <ul>
 * <li>the version: any (the standard monster and its Catacombs variant pooled, as before variants were told
 * apart), only the standard monster's, or only one variant's;</li>
 * <li>the cannon: any (tasks with and without a cannon pooled), only cannon tasks, or only tasks without one
 * ({@link CannonTasks}).</li>
 * </ul>
 * Immutable; compares by value so it can be part of a cache key. Pure (no RuneLite types).
 */
final class TaskSelection
{
	/** Every record of the task, whichever version and with or without a cannon. */
	static final TaskSelection ANY = new TaskSelection(true, null, null);
	/** Only records of the standard monster (no {@link LedgerRecord#getVariant variant}), with or without a cannon. */
	static final TaskSelection STANDARD = new TaskSelection(false, null, null);

	private final boolean anyVariant;
	/** The variant's name ({@link CatacombsVariants.Variant#getName}), or {@code null} for any and standard. */
	private final String variant;
	/** {@code true} for cannon tasks only, {@code false} for tasks without a cannon only, {@code null} for both. */
	private final Boolean cannon;

	private TaskSelection(boolean anyVariant, String variant, Boolean cannon)
	{
		this.anyVariant = anyVariant;
		this.variant = variant;
		this.cannon = cannon;
	}

	/** Only the records of the variant {@code name} (with or without a cannon); {@link #STANDARD} for a blank name. */
	static TaskSelection of(String name)
	{
		return TaskStatistics.normalize(name) == null ? STANDARD : new TaskSelection(false, name.trim(), null);
	}

	/**
	 * This selection, limited to cannon tasks ({@code true}), tasks without a cannon ({@code false}) or both
	 * ({@code null}). Without a cannon limit, {@link #ANY} and {@link #STANDARD} stay the same instances.
	 */
	TaskSelection withCannon(Boolean cannon)
	{
		if (Objects.equals(cannon, this.cannon))
		{
			return this;
		}
		if (cannon == null && variant == null)
		{
			return anyVariant ? ANY : STANDARD;
		}
		return new TaskSelection(anyVariant, variant, cannon);
	}

	/** This selection with the version pooled ({@link #ANY}'s), keeping its cannon limit. */
	TaskSelection withAnyVariant()
	{
		return anyVariant ? this : ANY.withCannon(cannon);
	}

	/**
	 * This selection for the task {@code taskName}: kept when its variant is that task's Catacombs variant (or it has
	 * none), else with the version pooled ({@link #withAnyVariant}). Guards a selection read in a separate call from the
	 * task it is shown with, which could see another session (the overlay's Task row).
	 */
	TaskSelection forTask(String taskName)
	{
		if (variant == null)
		{
			return this;
		}
		final CatacombsVariants.Variant taskVariant = CatacombsVariants.forTask(taskName);
		return taskVariant != null && variant.equals(taskVariant.getName()) ? this : withAnyVariant();
	}

	/** The variant's name, or {@code null} when the version is any or standard. */
	String getVariant()
	{
		return variant;
	}

	/** Whether the version is pooled (standard and variant alike). */
	boolean isAnyVariant()
	{
		return anyVariant;
	}

	/** {@code true} for cannon tasks only, {@code false} for tasks without a cannon only, {@code null} for both. */
	Boolean getCannon()
	{
		return cannon;
	}

	/** Whether {@code record}'s version and cannon use are ones this selects (its task is matched elsewhere). */
	boolean matches(LedgerRecord record)
	{
		if (cannon != null && cannon != record.cannonTask())
		{
			return false;
		}
		if (anyVariant)
		{
			return true;
		}
		return Objects.equals(TaskStatistics.normalize(variant), TaskStatistics.normalize(record.getVariant()));
	}

	/**
	 * The name the live task is shown under with this selection, the same way {@link LedgerRecord#groupName} names a
	 * saved one: the variant's name when there is one, else {@code task}, with {@link CannonTasks#SUFFIX} for cannon
	 * tasks only. A pooled cannon dimension adds nothing.
	 */
	String displayName(String task)
	{
		return CannonTasks.name(variant != null ? variant : task, Boolean.TRUE.equals(cannon));
	}

	/**
	 * A short key for caches: the version ({@code *} for any, empty for standard, else the normalized name), then
	 * {@code /} and the cannon ({@code *} for both, {@code c} with, {@code n} without).
	 */
	String key()
	{
		String version;
		if (anyVariant)
		{
			version = "*";
		}
		else
		{
			String normalized = TaskStatistics.normalize(variant);
			version = normalized == null ? "" : normalized;
		}
		return version + "/" + (cannon == null ? "*" : cannon ? "c" : "n");
	}

	@Override
	public boolean equals(Object other)
	{
		return other instanceof TaskSelection && key().equals(((TaskSelection) other).key());
	}

	@Override
	public int hashCode()
	{
		return key().hashCode();
	}

	@Override
	public String toString()
	{
		String version = anyVariant ? "ANY" : variant == null ? "STANDARD" : variant;
		return cannon == null ? version : version + (cannon ? " (cannon)" : " (no cannon)");
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.function.Function;

/** Per-task historical averages, calculated from saved completed records only. */
final class TaskStatistics
{
	private final int sampleCount;
	private final long totalKills;
	private final long activeMillis;
	private final long valuedKills;
	private final long lootValue;
	private final long suppliesValue;
	private final boolean lootApproximate;
	private final boolean suppliesApproximate;
	private final long supplyKills;
	private final int supplySampleCount;
	private final Map<Integer, Long> supplies;
	private final Map<Integer, Integer> supplyDoses;
	private final Map<Integer, Long> supplyUnitGe;
	private final long bankTrips;
	private final long bankTripKills;
	private final int bankTripSampleCount;
	private final long xpKills;
	private final long xpActiveMillis;
	private final Map<String, Long> xp;
	/** The location the samples were limited to (Part B), or {@code null} when every location counts. */
	private final String location;
	/** How many of the samples are cannon tasks ({@link LedgerRecord#cannonTask}). */
	private final int cannonSampleCount;

	private TaskStatistics(Totals t)
	{
		this.location = t.location;
		this.sampleCount = t.sampleCount;
		this.cannonSampleCount = t.cannonSampleCount;
		this.totalKills = t.totalKills;
		this.activeMillis = t.activeMillis;
		this.valuedKills = t.valuedKills;
		this.lootValue = t.lootValue;
		this.suppliesValue = t.suppliesValue;
		this.lootApproximate = t.lootApproximate;
		this.suppliesApproximate = t.suppliesApproximate;
		this.supplyKills = t.supplyKills;
		this.supplySampleCount = t.supplySampleCount;
		this.supplies = Collections.unmodifiableMap(new TreeMap<>(t.supplies));
		this.supplyDoses = Collections.unmodifiableMap(new TreeMap<>(t.supplyDoses));
		this.supplyUnitGe = Collections.unmodifiableMap(new TreeMap<>(t.supplyUnitGe));
		this.bankTrips = t.bankTrips;
		this.bankTripKills = t.bankTripKills;
		this.bankTripSampleCount = t.bankTripSampleCount;
		this.xpKills = t.xpKills;
		this.xpActiveMillis = t.xpActiveMillis;
		this.xp = Collections.unmodifiableMap(new TreeMap<>(t.xp));
	}

	/** The running totals {@link #aggregate} adds the samples into; a new one is the empty statistics. */
	private static final class Totals
	{
		private int sampleCount;
		private int cannonSampleCount;
		private long totalKills;
		private long activeMillis;
		private long valuedKills;
		private long lootValue;
		private long suppliesValue;
		private boolean lootApproximate;
		private boolean suppliesApproximate;
		private long supplyKills;
		private int supplySampleCount;
		private final Map<Integer, Long> supplies = new TreeMap<>();
		private final Map<Integer, Integer> supplyDoses = new TreeMap<>();
		private final Map<Integer, Long> supplyUnitGe = new TreeMap<>();
		private long bankTrips;
		private long bankTripKills;
		private int bankTripSampleCount;
		private long xpKills;
		private long xpActiveMillis;
		private final Map<String, Long> xp = new TreeMap<>();
		private String location;
	}

	/**
	 * Aggregates records matching the current task. Per-kill values are pooled across their available kills; task
	 * duration is the arithmetic mean of task samples. Outliers are not removed.
	 *
	 * @param currentGe today's GE unit prices the records are valued at ({@link HistoryPricing}); never {@code null}
	 */
	static TaskStatistics forTask(Collection<LedgerRecord> records, int creatureId, String monster,
		LootPriceMode mode, Map<Integer, Long> currentGe)
	{
		return aggregate(records, creatureId, monster, TaskSelection.ANY, mode, currentGe, HiddenLoot.NONE, null);
	}

	/**
	 * Same location first (Part B): when {@code location} is known and at least one sample ({@link #isSample}) is
	 * at that location ({@link TaskLocation#sameLocation} with {@code recordLocation}'s name for it), only those samples
	 * count and {@link #getLocation} is the location; otherwise every sample counts, as
	 * {@link #forTask(Collection, int, String, LootPriceMode, Map)}.
	 *
	 * @param location       the current task's location, or {@code null} while unknown
	 * @param recordLocation a saved record's location ({@link TaskLocation#recordLocation}), {@code null} when unknown
	 */
	static TaskStatistics forTask(Collection<LedgerRecord> records, int creatureId, String monster, String location,
		Function<LedgerRecord, String> recordLocation, LootPriceMode mode, Map<Integer, Long> currentGe)
	{
		return forTask(records, creatureId, monster, TaskSelection.ANY, location, recordLocation, mode, currentGe,
			HiddenLoot.NONE);
	}

	/**
	 * As {@link #forTask(Collection, int, String, String, Function, LootPriceMode, Map)}, with the loot items
	 * {@code hidden} hides left out of the loot values ({@link HistoryPricing}).
	 */
	static TaskStatistics forTask(Collection<LedgerRecord> records, int creatureId, String monster, String location,
		Function<LedgerRecord, String> recordLocation, LootPriceMode mode, Map<Integer, Long> currentGe,
		HiddenLoot hidden)
	{
		return forTask(records, creatureId, monster, TaskSelection.ANY, location, recordLocation, mode, currentGe,
			hidden);
	}

	/**
	 * As {@link #forTask(Collection, int, String, String, Function, LootPriceMode, Map, HiddenLoot)}, counting only the
	 * records of the task {@code selection} selects: its version and whether a cannon was used.
	 * {@link TaskSelection#ANY} pools the standard monster and its Catacombs variant, with and without a cannon, as
	 * before they were told apart.
	 */
	static TaskStatistics forTask(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskSelection selection, String location, Function<LedgerRecord, String> recordLocation, LootPriceMode mode,
		Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		final String here = TaskLocation.normalizeName(location);
		if (here != null && records != null && recordLocation != null)
		{
			List<LedgerRecord> atLocation = new ArrayList<>();
			for (LedgerRecord record : records)
			{
				if (isSample(record, creatureId, monster, selection)
					&& TaskLocation.sameLocation(here, recordLocation.apply(record)))
				{
					atLocation.add(record);
				}
			}
			if (!atLocation.isEmpty())
			{
				return aggregate(atLocation, creatureId, monster, selection, mode, currentGe, hidden, here);
			}
		}
		return aggregate(records, creatureId, monster, selection, mode, currentGe, hidden, null);
	}

	/**
	 * Whether {@code record} is a sample of the task: completed, not partial, with kills, and the same creature (either
	 * version, standard or Catacombs variant, with or without a cannon).
	 */
	static boolean isSample(LedgerRecord record, int creatureId, String monster)
	{
		return isSample(record, creatureId, monster, TaskSelection.ANY);
	}

	/**
	 * As {@link #isSample(LedgerRecord, int, String)}, and of the version and cannon use {@code selection} selects
	 *.
	 */
	static boolean isSample(LedgerRecord record, int creatureId, String monster, TaskSelection selection)
	{
		return record != null && record.isCompleted() && !record.isPartial() && record.getKills() > 0
			&& matches(record, creatureId, monster) && (selection == null || selection.matches(record));
	}

	/**
	 * The selection the live task's statistics use for {@code selection} (owner decision 2026-10-28): when it
	 * asks for cannon tasks only but {@code records} hold no {@link #isSample sample} of the task that is a cannon task
	 * of its version (at any location), tasks with and without a cannon pooled ({@code selection} without its cannon
	 * limit), as before the cannonball; otherwise {@code selection} itself. A {@code null} selection is
	 * {@link TaskSelection#ANY}.
	 */
	static TaskSelection effectiveSelection(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskSelection selection)
	{
		TaskSelection requested = selection == null ? TaskSelection.ANY : selection;
		if (!Boolean.TRUE.equals(requested.getCannon()))
		{
			return requested;
		}
		if (records != null)
		{
			for (LedgerRecord record : records)
			{
				if (isSample(record, creatureId, monster, requested))
				{
					return requested;
				}
			}
		}
		return requested.withCannon(null);
	}

	private static TaskStatistics aggregate(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskSelection selection, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden, String location)
	{
		Objects.requireNonNull(currentGe, "currentGe");
		if (records == null)
		{
			return empty();
		}

		final Totals t = new Totals();
		t.location = location;

		for (LedgerRecord record : records)
		{
			if (!isSample(record, creatureId, monster, selection))
			{
				continue;
			}

			long recordKills = record.getKills();
			t.sampleCount++;
			if (record.cannonTask())
			{
				t.cannonSampleCount++;
			}
			t.totalKills = saturatedAdd(t.totalKills, recordKills);
			t.activeMillis = saturatedAdd(t.activeMillis, Math.max(0, record.getActiveMillis()));

			if (LedgerHistory.isValued(record))
			{
				HistoryPricing.Values values = HistoryPricing.value(record, mode, currentGe, hidden);
				if (values.getLootValue() != null && values.getSuppliesGe() != null)
				{
					t.valuedKills = saturatedAdd(t.valuedKills, recordKills);
					t.lootValue = saturatedAdd(t.lootValue, values.getLootValue());
					t.suppliesValue = saturatedAdd(t.suppliesValue, values.getSuppliesGe());
					t.lootApproximate |= values.isLootApproximate();
					t.suppliesApproximate |= values.isSuppliesApproximate();
				}
			}

			Map<Integer, Long> recordSupplies = record.getSupplies();
			if (recordSupplies != null || LedgerHistory.isValued(record))
			{
				t.supplyKills = saturatedAdd(t.supplyKills, recordKills);
				t.supplySampleCount++;
				if (recordSupplies != null)
				{
					for (Map.Entry<Integer, Long> item : recordSupplies.entrySet())
					{
						if (item.getKey() != null && item.getValue() != null && item.getValue() > 0)
						{
							t.supplies.merge(item.getKey(), item.getValue(), TaskStatistics::saturatedAdd);
							Integer doses = record.getSupplyDoses() == null
								? null : record.getSupplyDoses().get(item.getKey());
							if (doses != null && doses > 0)
							{
								t.supplyDoses.put(item.getKey(), doses);
							}
						}
					}
				}
			}

			if (record.getBankTrips() != null && record.getBankTrips() >= 0)
			{
				t.bankTrips = saturatedAdd(t.bankTrips, record.getBankTrips());
				t.bankTripKills = saturatedAdd(t.bankTripKills, recordKills);
				t.bankTripSampleCount++;
			}

			Map<String, Long> recordXp = record.getXpGained();
			if (recordXp != null)
			{
				t.xpKills = saturatedAdd(t.xpKills, recordKills);
				t.xpActiveMillis = saturatedAdd(t.xpActiveMillis, Math.max(0, record.getActiveMillis()));
				for (Map.Entry<String, Long> skill : recordXp.entrySet())
				{
					if (skill.getKey() != null && skill.getValue() != null && skill.getValue() > 0)
					{
						t.xp.merge(skill.getKey(), skill.getValue(), TaskStatistics::saturatedAdd);
					}
				}
			}
		}

		// Today's prices; an item without one has no price, as in the history.
		for (Integer id : t.supplies.keySet())
		{
			Long price = currentGe.get(id);
			if (price != null && price > 0)
			{
				t.supplyUnitGe.put(id, price);
			}
		}

		return new TaskStatistics(t);
	}

	private static boolean matches(LedgerRecord record, int creatureId, String monster)
	{
		Integer recordCreatureId = record.getCreatureId();
		if (creatureId != SessionTracker.NO_CREATURE && recordCreatureId != null)
		{
			return recordCreatureId == creatureId;
		}
		String recordMonster = normalize(record.getMonster());
		return recordMonster != null && recordMonster.equals(normalize(monster));
	}

	/**
	 * The one monster-name key every feature groups and matches by (task statistics, Trends ranking and chart, luck
	 * meter, Wiki task locations): trimmed and lower case in {@link Locale#ROOT}, so the key never depends on the
	 * client's default locale. {@code null} for a {@code null} or blank name, which matches nothing.
	 */
	static String normalize(String value)
	{
		if (value == null)
		{
			return null;
		}
		String name = value.trim();
		return name.isEmpty() ? null : name.toLowerCase(Locale.ROOT);
	}

	private static TaskStatistics empty()
	{
		return new TaskStatistics(new Totals());
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	int getSampleCount()
	{
		return sampleCount;
	}

	/** How many of the {@link #getSampleCount samples} are cannon tasks. */
	int getCannonSampleCount()
	{
		return cannonSampleCount;
	}

	/**
	 * The location the samples are limited to ({@link TaskLocation#normalizeName}d, as the current task's location was
	 * given), or {@code null} when they are from every location.
	 */
	String getLocation()
	{
		return location;
	}

	long getAverageTaskDurationMillis()
	{
		return sampleCount == 0 ? 0 : Math.round(activeMillis / (double) sampleCount);
	}

	Long getMillisPerKill()
	{
		return totalKills == 0 ? null : Math.round(activeMillis / (double) totalKills);
	}

	Long getLootPerKill()
	{
		return valuedKills == 0 ? null : Math.round(lootValue / (double) valuedKills);
	}

	Long getSuppliesValuePerKill()
	{
		return valuedKills == 0 ? null : Math.round(suppliesValue / (double) valuedKills);
	}

	/**
	 * Profit per kill: {@link #getLootPerKill} minus {@link #getSuppliesValuePerKill}, so the three tooltip
	 * lines add up; loot in the Loot price mode, supplies at GE. {@code null} when either part is unknown.
	 */
	Long getProfitPerKill()
	{
		Long loot = getLootPerKill();
		Long supplies = getSuppliesValuePerKill();
		return loot == null || supplies == null ? null : LedgerHistory.profit(loot, supplies);
	}

	boolean isLootApproximate()
	{
		return lootApproximate;
	}

	boolean isSuppliesApproximate()
	{
		return suppliesApproximate;
	}

	/** Whether {@link #getProfitPerKill} is approximate: either part left out an item without a price. */
	boolean isProfitApproximate()
	{
		return lootApproximate || suppliesApproximate;
	}

	Map<Integer, Double> getSuppliesPerKill()
	{
		Map<Integer, Double> result = new TreeMap<>();
		if (supplyKills > 0)
		{
			supplies.forEach((id, quantity) -> result.put(id, quantity / (double) supplyKills));
		}
		return Collections.unmodifiableMap(result);
	}

	Map<Integer, Integer> getSupplyDoses()
	{
		return supplyDoses;
	}

	/**
	 * Pooled supply totals by item id (doses, bites or charges for the {@link #getSupplyDoses} ids), over the
	 * {@link #getSupplyKills} of the records with supplies or values; the exact sums behind {@link #getSuppliesPerKill}.
	 */
	Map<Integer, Long> getSupplyTotals()
	{
		return supplies;
	}

	/** Kills of the records that count for the supply averages (with supplies or values). */
	long getSupplyKills()
	{
		return supplyKills;
	}

	/** How many records count for the supply averages (with supplies or values). */
	int getSupplySampleCount()
	{
		return supplySampleCount;
	}

	/**
	 * Today's GE unit price (per item, not per dose) of each pooled supply id that has one. For sorting only.
	 */
	Map<Integer, Long> getSupplyUnitGePrices()
	{
		return supplyUnitGe;
	}

	/** Bank trips summed over the records with a known (non-negative) count. */
	long getBankTripTotal()
	{
		return bankTrips;
	}

	/** Kills of the records with a known bank-trip count, the denominator of trips per kill. */
	long getBankTripKills()
	{
		return bankTripKills;
	}

	/** How many records have a known bank-trip count. */
	int getBankTripSampleCount()
	{
		return bankTripSampleCount;
	}

	Map<String, Double> getXpPerKill()
	{
		Map<String, Double> result = new TreeMap<>();
		if (xpKills > 0)
		{
			xp.forEach((skill, value) -> result.put(skill, value / (double) xpKills));
		}
		return Collections.unmodifiableMap(result);
	}

	Long getXpPerHour()
	{
		long totalXp = SkillXp.total(xp);
		return SkillXp.perHour(totalXp, xpActiveMillis);
	}

	/**
	 * Estimated session values for {@code taskSize}, with unavailable historical GP data kept unknown.
	 */
	Estimate estimate(int taskSize)
	{
		if (taskSize <= 0 || sampleCount == 0)
		{
			return null;
		}
		Long msPerKill = getMillisPerKill();
		Long lootPerKill = getLootPerKill();
		Long suppliesPerKill = getSuppliesValuePerKill();
		Long estimatedMillis = msPerKill == null ? null : multiply(msPerKill, taskSize);
		Long estimatedLoot = lootPerKill == null ? null : multiply(lootPerKill, taskSize);
		Long estimatedSupplies = suppliesPerKill == null ? null : multiply(suppliesPerKill, taskSize);
		return new Estimate(sampleCount, estimatedMillis, estimatedLoot, estimatedSupplies,
			lootApproximate, suppliesApproximate);
	}

	private static long multiply(long value, int multiplier)
	{
		try
		{
			return Math.multiplyExact(value, (long) multiplier);
		}
		catch (ArithmeticException e)
		{
			return value >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	static final class Estimate
	{
		private final int sampleCount;
		private final Long activeMillis;
		private final Long lootValue;
		private final Long suppliesValue;
		private final boolean lootApproximate;
		private final boolean suppliesApproximate;

		Estimate(int sampleCount, Long activeMillis, Long lootValue, Long suppliesValue, boolean lootApproximate,
			boolean suppliesApproximate)
		{
			this.sampleCount = sampleCount;
			this.activeMillis = activeMillis;
			this.lootValue = lootValue;
			this.suppliesValue = suppliesValue;
			this.lootApproximate = lootApproximate;
			this.suppliesApproximate = suppliesApproximate;
		}

		int getSampleCount()
		{
			return sampleCount;
		}

		Long getActiveMillis()
		{
			return activeMillis;
		}

		Long getLootValue()
		{
			return lootValue;
		}

		Long getSuppliesValue()
		{
			return suppliesValue;
		}

		boolean isLootApproximate()
		{
			return lootApproximate;
		}

		boolean isSuppliesApproximate()
		{
			return suppliesApproximate;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.OptionalDouble;
import java.util.OptionalLong;

/**
 * Estimates how long the rest of a Slayer task will take from the session's pace so far: the average active time per
 * kill times the kills left. Pure; no RuneLite types.
 *
 * <p>No estimate is given until the session has at least {@link #MIN_KILLS} kills and {@link #MIN_ACTIVE_MILLIS} of
 * active time, so the first kills (or a quick first kill) do not produce a wild figure.</p>
 */
final class TaskTimeEstimate
{
	/** Kills needed before an estimate is given. */
	static final int MIN_KILLS = 3;
	/** Active time needed before an estimate is given. */
	static final long MIN_ACTIVE_MILLIS = 60_000;

	private static final double MILLIS_PER_HOUR = 3_600_000d;

	private TaskTimeEstimate()
	{
	}

	/**
	 * Estimated active time left on the task.
	 *
	 * @param activeMillis the session's active (running) time so far
	 * @param kills        kills in the session so far
	 * @param remaining    kills left on the task
	 * @return {@code round(activeMillis / kills * remaining)}, saturated at {@link Long#MAX_VALUE}; empty when there
	 * is too little data ({@link #isEstimable}) or nothing is left ({@code remaining <= 0})
	 */
	static OptionalLong remainingMillis(long activeMillis, int kills, int remaining)
	{
		if (!isEstimable(activeMillis, kills) || remaining <= 0)
		{
			return OptionalLong.empty();
		}
		// Math.round saturates at Long.MAX_VALUE, and the double cannot overflow for int and long inputs.
		return OptionalLong.of(Math.round(activeMillis / (double) kills * remaining));
	}

	/** Kills per hour of active time, or empty when there is too little data ({@link #isEstimable}). */
	static OptionalDouble killsPerHour(long activeMillis, int kills)
	{
		if (!isEstimable(activeMillis, kills))
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(kills * MILLIS_PER_HOUR / activeMillis);
	}

	/** Average active time per kill, or empty when there is too little data ({@link #isEstimable}). */
	static OptionalLong averageKillMillis(long activeMillis, int kills)
	{
		if (!isEstimable(activeMillis, kills))
		{
			return OptionalLong.empty();
		}
		return OptionalLong.of(Math.round(activeMillis / (double) kills));
	}

	/** Whether the session has enough kills and active time for an estimate. */
	static boolean isEstimable(long activeMillis, int kills)
	{
		return kills >= MIN_KILLS && activeMillis >= MIN_ACTIVE_MILLIS;
	}
}

package com.shmayvan.slayerledger;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/** Small Swing chart of one metric across completed tasks. */
final class TaskTrendChartView extends JPanel
{
	private static final int LEFT = 54;
	private static final int RIGHT = 8;
	private static final int TOP = 12;
	private static final int BOTTOM = 28;
	private static final int HEIGHT = 150;
	private static final int POINT_RADIUS = 3;
	/** Aimed-for number of y-axis steps; nice-number steps give 3 to 6. */
	private static final int TARGET_STEPS = 4;
	private static final Stroke LINE = new BasicStroke(1.5f);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofLocalizedDate(FormatStyle.SHORT);
	private static final DateTimeFormatter DATE_TIME = DateTimeFormatter.ofLocalizedDateTime(FormatStyle.SHORT);

	private List<TaskChart.Point> points = Collections.emptyList();
	private String metricLabel = "";
	private int[] pointXs = new int[0];
	private int[] pointYs = new int[0];
	private DateTimeFormatter dateFormat = DATE.withZone(ZoneId.systemDefault());
	private DateTimeFormatter dateTimeFormat = DATE_TIME.withZone(ZoneId.systemDefault());

	TaskTrendChartView()
	{
		setOpaque(true);
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setToolTipText("");
		// No preferred width, so it never widens the sidebar; the box layout stretches it across.
		setPreferredSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
	}

	/** Plots {@code points}, labelled {@code metricLabel} (as the metric choice shows it) in the tooltips. */
	void setData(List<TaskChart.Point> points, String metricLabel, ZoneId zone)
	{
		this.points = points == null ? Collections.emptyList() : new ArrayList<>(points);
		this.metricLabel = metricLabel == null ? "" : metricLabel;
		ZoneId shownZone = zone == null ? ZoneId.systemDefault() : zone;
		dateFormat = DATE.withZone(shownZone);
		dateTimeFormat = DATE_TIME.withZone(shownZone);
		pointXs = new int[0];
		pointYs = new int[0];
		repaint();
	}

	/** Test seam: the number of points drawn, which the chart doesn't show as text. */
	int getPointCount()
	{
		return points.size();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		super.paintComponent(graphics);
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setFont(getFont());
			FontMetrics font = g.getFontMetrics();
			if (points.isEmpty())
			{
				g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				g.drawString("No completed task data.", 8, TOP + font.getAscent());
				pointXs = new int[0];
				pointYs = new int[0];
				return;
			}

			int width = Math.max(1, getWidth() - LEFT - RIGHT);
			int height = Math.max(1, getHeight() - TOP - BOTTOM);
			int x0 = LEFT;
			int y0 = TOP + height;
			long minimum = Long.MAX_VALUE;
			long maximum = Long.MIN_VALUE;
			for (TaskChart.Point point : points)
			{
				minimum = Math.min(minimum, point.getRatePerHour());
				maximum = Math.max(maximum, point.getRatePerHour());
			}
			long[] ticks = ticks(minimum, maximum);
			double low = ticks[0];
			double span = Math.max(1d, (double) ticks[ticks.length - 1] - low);
			pointXs = new int[points.size()];
			pointYs = new int[points.size()];

			String lastLabel = null;
			for (long tick : ticks)
			{
				int y = y0 - (int) Math.round(height * ((tick - low) / span));
				g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
				g.drawLine(x0, y, x0 + width, y);
				// Short amounts can round two ticks to the same text; label only the first.
				String label = LedgerHistory.formatAmount(tick, false);
				if (!label.equals(lastLabel))
				{
					g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
					g.drawString(label, Math.max(0, LEFT - font.stringWidth(label) - 5), y + font.getAscent() / 2);
					lastLabel = label;
				}
			}

			long firstTime = points.get(0).getEndedAt();
			long lastTime = points.get(points.size() - 1).getEndedAt();
			for (int i = 0; i < points.size(); i++)
			{
				TaskChart.Point point = points.get(i);
				double xRatio = lastTime == firstTime
					? (points.size() == 1 ? 0.5d : i / (double) (points.size() - 1))
					: (point.getEndedAt() - firstTime) / (double) (lastTime - firstTime);
				double yRatio = (point.getRatePerHour() - low) / span;
				pointXs[i] = x0 + (int) Math.round(width * xRatio);
				pointYs[i] = y0 - (int) Math.round(height * yRatio);
			}

			g.setColor(ColorScheme.BRAND_ORANGE);
			g.setStroke(LINE);
			for (int i = 1; i < points.size(); i++)
			{
				g.drawLine(pointXs[i - 1], pointYs[i - 1], pointXs[i], pointYs[i]);
			}
			for (int i = 0; i < points.size(); i++)
			{
				g.fillOval(pointXs[i] - POINT_RADIUS, pointYs[i] - POINT_RADIUS, POINT_RADIUS * 2 + 1,
					POINT_RADIUS * 2 + 1);
			}
			g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			int dateY = y0 + font.getAscent() + 5;
			String firstDate = dateFormat.format(Instant.ofEpochMilli(firstTime));
			if (points.size() == 1)
			{
				// A single point sits in the middle; its date goes under it.
				int x = pointXs[0] - font.stringWidth(firstDate) / 2;
				g.drawString(firstDate, Math.max(0, Math.min(x, getWidth() - font.stringWidth(firstDate))), dateY);
				return;
			}
			String lastDate = dateFormat.format(Instant.ofEpochMilli(lastTime));
			g.drawString(firstDate, x0, dateY);
			int lastLabelX = x0 + width - font.stringWidth(lastDate);
			if (!firstDate.equals(lastDate))
			{
				g.drawString(lastDate, Math.max(x0, lastLabelX), dateY);
			}
		}
		finally
		{
			g.dispose();
		}
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		int nearest = -1;
		double nearestDistance = 9d;
		for (int i = 0; i < pointXs.length; i++)
		{
			double distance = Math.hypot(event.getX() - pointXs[i], event.getY() - pointYs[i]);
			if (distance < nearestDistance)
			{
				nearest = i;
				nearestDistance = distance;
			}
		}
		if (nearest < 0)
		{
			return null;
		}
		TaskChart.Point point = points.get(nearest);
		StringBuilder tooltip = new StringBuilder("<html>")
			.append(LedgerHistory.escapeHtml(dateTimeFormat.format(Instant.ofEpochMilli(point.getEndedAt()))))
			.append("<br>").append(LedgerHistory.escapeHtml(metricLabel)).append(": ")
			.append(LedgerHistory.formatAmount(point.getRatePerHour(), point.isApproximate()));
		if (point.getNote() != null && !point.getNote().trim().isEmpty())
		{
			tooltip.append("<br>Note: ").append(LedgerHistory.escapeHtml(point.getNote()));
		}
		if (point.isApproximate())
		{
			tooltip.append("<br>~ means some item prices were unavailable, or an older task kept its saved totals.");
		}
		return tooltip.append("</html>").toString();
	}

	/**
	 * Y-axis ticks covering {@code minimum..maximum}: multiples of a 1, 2 or 5 times a power of ten step, about
	 * {@link #TARGET_STEPS} of them, the first at or below the minimum and the last at or above the maximum.
	 */
	static long[] ticks(long minimum, long maximum)
	{
		long low = minimum;
		long high = maximum;
		if (low == high)
		{
			long padding = Math.max(1, Math.abs(low) / 10);
			low -= padding;
			high += padding;
		}
		long step = niceStep((high - (double) low) / TARGET_STEPS);
		long first = Math.floorDiv(low, step) * step;
		long last = -Math.floorDiv(-high, step) * step;
		int count = (int) Math.min(TARGET_STEPS * 3L, (last - first) / step) + 1;
		long[] ticks = new long[count];
		for (int i = 0; i < count; i++)
		{
			ticks[i] = first + i * step;
		}
		return ticks;
	}

	private static long niceStep(double raw)
	{
		if (raw <= 1)
		{
			return 1;
		}
		double magnitude = Math.pow(10, Math.floor(Math.log10(raw)));
		double fraction = raw / magnitude;
		double nice = fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 5 ? 5 : 10;
		return Math.max(1, (long) (nice * magnitude));
	}
}

package com.shmayvan.slayerledger;

/**
 * Kind of Slayer task, derived from the assigning master and the task (never stored, so it can't disagree with the
 * raw values it comes from). Pure; no RuneLite types.
 *
 * <p>A boss task (SLAYER_TARGET {@value SessionTracker#BOSS_TASK_TARGET}) is {@link #BOSS} whoever assigned it.
 * Otherwise Krystilia's tasks are {@link #WILDERNESS}, Konar's are {@link #KONAR} and every other known master's are
 * {@link #REGULAR}. Without a known master (or with one missing from {@link SlayerMaster}'s table) a non-boss task
 * has no type. Whether a task was extended is not part of the
 * type: the plugin has no reliable way to tell (see docs/COUNTING_RULES.md).</p>
 */
enum TaskType
{
	REGULAR("Regular"),
	WILDERNESS("Wilderness"),
	KONAR("Konar"),
	BOSS("Boss");

	private final String label;

	TaskType(String label)
	{
		this.label = label;
	}

	/**
	 * @param master     SLAYER_MASTER value, or {@code null} when unknown
	 * @param creatureId creature key ({@link SessionTracker#creatureKey}), or {@code null} or
	 *                   {@link SessionTracker#NO_CREATURE} when unknown
	 * @return the task's type, or {@code null} when it can't be told
	 */
	static TaskType of(Integer master, Integer creatureId)
	{
		if (creatureId != null && creatureId < SessionTracker.NO_CREATURE)
		{
			// Boss keys are -2 - bossId, always below NO_CREATURE.
			return BOSS;
		}
		if (!SlayerMaster.isKnown(master))
		{
			return null;
		}
		switch (master)
		{
			case SlayerMaster.KRYSTILIA:
				return WILDERNESS;
			case SlayerMaster.KONAR:
				return KONAR;
			default:
				// A master missing from the name table could be any kind (a new Wilderness master, say).
				return SlayerMaster.hasName(master) ? REGULAR : null;
		}
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.shmayvan.slayerledger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A titled list of the sidebar, the part {@link ItemListView} (text lines) and {@link ItemGridView} (item icons)
 * share: a title with its row count, then "None" while the list is empty, or the body a subclass fills from the rows.
 * A collapsible list (the live ones) opens and closes from its title ("Show" or "Hide") and starts closed. Rows the
 * caller left out (the loot Ground Items hides) are counted in the title, "Loot received (12,
 * 3 hidden)", explained in the header's tooltip ({@link #hiddenNote}), and an empty list then says they are all
 * hidden instead of "None". Subclasses call {@link #rebuild} at the end of their constructor. EDT only.
 *
 * @param <T> what one row is
 */
abstract class TitledListView<T> extends JPanel
{
	private final String title;
	private final boolean collapsible;
	private final JLabel titleLabel = new JLabel();
	private final JLabel toggleLabel = new JLabel();
	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	/** What the header's tooltip says without hidden rows ({@code null}: no tooltip). */
	private final String headerTip;
	private final JPanel body = new JPanel();
	/** Rows shown; empty before the first {@link #setRows}. */
	private List<T> rows;
	/** Whether a collapsible list is open; always true otherwise. */
	private boolean expanded;
	/** Rows the caller left out of {@link #rows}, counted in the title; 0 for none. */
	private int hiddenCount;
	/** Whether the title shows the row count ({@link #hideCount}). */
	private boolean countShown = true;

	/** @param noun what the rows are, for the tooltips ("items", "skills") */
	TitledListView(String title, boolean collapsible, Color background, String noun)
	{
		this.title = title;
		this.collapsible = collapsible;
		this.expanded = !collapsible;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(background);

		// Names for tests, which find the parts by them (searching from the list itself); no visible effect.
		header.setName("itemList.header");
		titleLabel.setName("itemList.title");
		toggleLabel.setName("itemList.toggle");
		body.setName("itemList.body");
		header.setOpaque(false);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		titleLabel.setFont(FontManager.getRunescapeSmallFont());
		titleLabel.setForeground(collapsible ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		header.add(titleLabel, BorderLayout.CENTER);
		if (collapsible)
		{
			toggleLabel.setFont(FontManager.getRunescapeSmallFont());
			toggleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			header.add(toggleLabel, BorderLayout.EAST);
			header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			headerTip = "Click to show or hide the " + noun;
			header.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1)
					{
						toggle();
					}
				}
			});
		}
		else
		{
			headerTip = null;
		}
		header.setToolTipText(headerTip);
		add(header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(body);
		rows = Collections.emptyList();
	}

	/** Shows {@code newRows} (already sorted); nothing is rebuilt when they are the rows already shown. */
	void setRows(List<? extends T> newRows)
	{
		setRows(newRows, 0);
	}

	/**
	 * Shows {@code newRows} (already sorted), with {@code hidden} more left out by the caller; nothing is
	 * rebuilt when both are what is shown already.
	 */
	void setRows(List<? extends T> newRows, int hidden)
	{
		int newHidden = Math.max(0, hidden);
		if (newRows.equals(rows) && newHidden == hiddenCount)
		{
			return;
		}
		rows = new ArrayList<>(newRows);
		hiddenCount = newHidden;
		rebuild();
	}

	/**
	 * The header tooltip's lines on {@code hidden} rows left out (HTML, lines joined by {@code <br>}, no player or game
	 * text), or {@code null} to say nothing.
	 */
	String hiddenNote(int hidden)
	{
		return null;
	}

	/** Opens or closes a collapsible list, as a click on its title does. */
	void toggle()
	{
		if (collapsible)
		{
			expanded = !expanded;
			rebuild();
		}
	}

	boolean isExpanded()
	{
		return expanded;
	}

	/** The title as shown, with " | Show" or " | Hide" for a collapsible list. */
	String getHeaderText()
	{
		return collapsible ? titleLabel.getText() + " | " + toggleLabel.getText() : titleLabel.getText();
	}

	/** Draws the title and, while the list is open, "None" or the rows ({@link #fillBody}). */
	final void rebuild()
	{
		titleLabel.setText(titleText());
		toggleLabel.setText(expanded ? "Hide" : "Show");
		String note = hiddenCount > 0 ? hiddenNote(hiddenCount) : null;
		header.setToolTipText(note == null ? headerTip
			: "<html>" + (headerTip == null ? "" : headerTip + ".<br>") + note + "</html>");
		body.removeAll();
		body.setVisible(expanded);
		if (expanded)
		{
			if (rows.isEmpty())
			{
				JPanel none = new JPanel(new BorderLayout());
				none.setOpaque(false);
				none.setAlignmentX(Component.LEFT_ALIGNMENT);
				none.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
				none.add(label(hiddenCount > 0 ? "All hidden" : "None", ColorScheme.MEDIUM_GRAY_COLOR),
					BorderLayout.CENTER);
				body.add(none);
			}
			else
			{
				fillBody(body, rows);
			}
		}
		revalidate();
		repaint();
	}

	/**
	 * "Title (12)", the rows shown, or "Title (12, 3 hidden)" when rows are left out; the same for collapsible and
	 * fixed lists.
	 */
	private String titleText()
	{
		if (!countShown)
		{
			return title;
		}
		return title + " (" + rows.size() + (hiddenCount > 0 ? ", " + hiddenCount + " hidden" : "") + ")";
	}

	/**
	 * Shows the plain title without the row count, for a list whose lines count something else (Monsters assigned:
	 * its lines are assignment shares, so a count of monsters in the title would read like a count of assignments).
	 */
	void hideCount()
	{
		countShown = false;
		titleLabel.setText(titleText());
	}

	/**
	 * Adds the components that show {@code shown} (never empty) to {@code body}, a vertical box; their alignment must
	 * be {@link Component#LEFT_ALIGNMENT}.
	 */
	abstract void fillBody(JPanel body, List<T> shown);

	/** A label in the sidebar's small font. */
	static JLabel label(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeSmallFont());
		return label;
	}
}

package com.shmayvan.slayerledger;

import java.util.Objects;

/**
 * The "not tracking" nudge: a task kill while no session is running (IDLE) or while the session is paused. Starting
 * and resuming stay manual (owner decision), so the plugin only tells the player: one chat line per assignment, and an
 * overlay row ({@link OverlayRows#NOT_TRACKING_LABEL}) while IDLE. Pure (no RuneLite types) and not thread-safe; the
 * plugin uses it on the client thread only, every settled tick, after the tracker's decision for that tick.
 *
 * <p><b>Kills.</b> A kill is the Slayer count going down on the same assignment while it stays above zero. The kill that
 * completes a task (the count drops to 0) never nudges: the task is over and its completion is being handled. A count
 * change from a new assignment or a reset (another creature key, name or assigned size, or a count that went up) only
 * sets the baseline. So does the first reading after a login, hop or lost connection ({@link #reset()}), and readings
 * while the plugin is still checking for a session to restore.</p>
 *
 * <p><b>Once per assignment.</b> The chat line is posted on the first kill of an assignment seen while IDLE or PAUSED,
 * whichever comes first, and never again for that assignment. Only the last assignment read is remembered (one account
 * at a time), across logins, hops and plugin restarts in the same client run, so a relogin onto the same assignment
 * doesn't repeat the line. A new assignment, or a reading from another account, replaces it and can nudge again.</p>
 *
 * <p><b>Overlay row.</b> Shown from a kill seen while IDLE until a session starts (any state but IDLE), the count reads 0
 * (the task ended, or a transient zero), another assignment is read, or the player logs out or the plugin starts ({@link #hideRow()}). A
 * later kill while IDLE on the same assignment shows it again, without another chat line. While PAUSED the overlay's
 * Paused row already says it isn't tracking, so no second warning row is shown.</p>
 */
final class TrackingNudge
{
	/** Which chat line to post, if any. */
	enum Line
	{
		NONE,
		/** A kill while no session is running. */
		IDLE,
		/** A kill while the session is paused. */
		PAUSED
	}

	/** The account of the remembered assignment. */
	private long account;
	/** Whether an assignment is remembered (a reading with a task was taken). */
	private boolean hasAssignment;
	private String monster;
	private int creatureId;
	private int originalAmount;
	/** The count at the last reading of the remembered assignment. */
	private int remaining;
	/** Whether the remembered assignment's chat line was posted. */
	private boolean lineSent;
	/** Whether the next reading with a task only sets the baseline. */
	private boolean baseline = true;
	/** Whether the overlay row is shown (still only while IDLE; see {@link #isRowShown}). */
	private boolean rowShown;

	/** After a login, hop or lost connection: the next reading with a task is a baseline. The assignment is kept. */
	void reset()
	{
		baseline = true;
	}

	/** At the login screen and at plugin start: hides the overlay row (the next login may be another account). */
	void hideRow()
	{
		rowShown = false;
	}

	/**
	 * Takes one settled tick's reading, after the tracker's decision for the tick.
	 *
	 * @param accountHash    the logged-in account
	 * @param monster        the task name, or {@code null} when unknown
	 * @param creatureId     the task's creature key
	 * @param remaining      SLAYER_COUNT (0 when there is no task)
	 * @param originalAmount the assigned size, or {@link SessionTracker#UNKNOWN_AMOUNT}
	 * @param state          the session state after this tick's decision
	 * @param suppressed     whether kills must not nudge now (a restore check is pending); the baseline still moves
	 * @return the chat line to post for this tick (at most one per assignment)
	 */
	Line update(long accountHash, String monster, int creatureId, int remaining, int originalAmount,
		SessionTracker.State state, boolean suppressed)
	{
		if (state != SessionTracker.State.IDLE)
		{
			rowShown = false;
		}
		if (remaining <= 0)
		{
			// The task ended (or a transient zero). The assignment is kept: if the same one comes back with no more kills
			// left, it is still the same assignment.
			rowShown = false;
			return Line.NONE;
		}

		final int amount = originalAmount > 0 ? originalAmount : SessionTracker.UNKNOWN_AMOUNT;
		final boolean same = hasAssignment && accountHash == account && creatureId == this.creatureId
			&& (monster == null || this.monster == null || Objects.equals(monster, this.monster))
			&& (amount == SessionTracker.UNKNOWN_AMOUNT || this.originalAmount == SessionTracker.UNKNOWN_AMOUNT
			|| amount == this.originalAmount)
			&& remaining <= this.remaining;
		final boolean kill = same && !baseline && remaining < this.remaining;
		if (same)
		{
			if (this.monster == null)
			{
				this.monster = monster;
			}
			if (this.originalAmount == SessionTracker.UNKNOWN_AMOUNT)
			{
				this.originalAmount = amount;
			}
		}
		else
		{
			hasAssignment = true;
			account = accountHash;
			this.monster = monster;
			this.creatureId = creatureId;
			this.originalAmount = amount;
			lineSent = false;
			rowShown = false;
		}
		this.remaining = remaining;
		baseline = false;

		if (!kill || suppressed
			|| (state != SessionTracker.State.IDLE && state != SessionTracker.State.PAUSED))
		{
			return Line.NONE;
		}
		if (state == SessionTracker.State.IDLE)
		{
			rowShown = true;
		}
		if (lineSent)
		{
			return Line.NONE;
		}
		lineSent = true;
		return state == SessionTracker.State.IDLE ? Line.IDLE : Line.PAUSED;
	}

	/**
	 * Whether the overlay shows the not-tracking row. The caller also checks that the session is still IDLE, so the row
	 * goes as soon as Play is pressed, before the next tick.
	 */
	boolean isRowShown()
	{
		return rowShown;
	}

	/** The chat line for {@code line}, or {@code null} for {@link Line#NONE}. */
	static String message(Line line)
	{
		switch (line)
		{
			case IDLE:
				return "Kill not counted: Slayer Ledger isn't tracking. Press Play in the sidebar.";
			case PAUSED:
				return "Kill not counted: Slayer Ledger is paused. Press Resume in the sidebar.";
			default:
				return null;
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.ZoneId;
import java.util.Collections;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ButtonGroup;
import javax.swing.DefaultComboBoxModel;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The collapsed "Trends" section of {@link SlayerLedgerPanel}: one Metric choice and a List / Chart toggle over
 * the completed-task records. List ranks monsters ({@link TaskRanking}); Chart plots one point per task for a chosen
 * monster ({@link TaskChart}). Only the visible view is built, only while the section is open, and never by the
 * panel's refresh timer. The view, metric and monster choices last for the panel's life; they are not saved.
 * The list and the chart are worked out off the EDT: until the model has them, what is shown stays, and the
 * panel calls {@link #viewsReady} when they are ready. EDT only.
 *
 * <p>Task icons ({@link TaskIcons}): each List row shows its task's icon before its rank and name, and each
 * Monster choice before its name, through a wrapper around the look and feel's renderer ({@link TaskIconCache}). A
 * Catacombs variant or cannon group shows its task's icon ({@link TaskRanking.Entry#getTask},
 * {@link TaskChart.Monster#getTask}); a name that is no known task an empty slot of the same size. They are asked for
 * only when the shown view is built. The Monster box is sized from a short name, its open list widened to fit
 * ({@link ComboPopupWidener}), so a long name never widens the sidebar.</p>
 */
final class TrendsSection
{
	enum View
	{
		LIST,
		CHART
	}

	/** Works the list and the chart out, once per change of the records or their pricing. */
	private final LedgerHistoryModel model;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Draws the List rows' task icons. */
	private final ItemIcons icons;

	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	private final JLabel title = new JLabel("Trends");
	private final JLabel toggle = new JLabel();
	private final JPanel body = new JPanel();
	private final JToggleButton listButton = new JToggleButton("List");
	private final JToggleButton chartButton = new JToggleButton("Chart");
	private final JComboBox<TaskRanking.Metric> metric = new JComboBox<>(TaskRanking.Metric.values());
	private final JComboBox<TaskChart.Monster> monster = new JComboBox<>();
	/** The Monster choices' icons. */
	private final TaskIconCache monsterIcons;
	private JPanel monsterRow;
	/** The Monster row with the gap below it, hidden as one in List view so no empty gap is left. */
	private final JPanel monsterBlock = new JPanel(new BorderLayout());
	private final JPanel list = new JPanel();
	private final TaskTrendChartView chart = new TaskTrendChartView();
	private boolean expanded;
	/** The "Trends" setting; while off, nothing is built, open or not. The panel hides the components. */
	private boolean shown = true;
	private View view = View.LIST;
	private boolean updatingChoices;
	/** How many times the shown view (the list rows or the chart points) was built. */
	private int builds;
	/** The model's results the shown list, Monster choices and chart were built from; {@code null} when none. */
	private List<TaskRanking.Entry> shownRanking;
	private List<TaskChart.Monster> shownMonsters;
	private List<TaskChart.Point> shownPoints;

	/** @param icons draws the task icons of the List rows and the Monster choices */
	TrendsSection(LedgerHistoryModel model, Runnable relayout, ItemIcons icons)
	{
		this.model = model;
		this.relayout = relayout;
		this.icons = icons;
		this.monsterIcons = new TaskIconCache(icons, monster);
	}

	/** Adds the header and the body to {@code content}, collapsed. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		header.setName("trends.header");
		title.setName("trends.title");
		toggle.setName("trends.toggle");
		body.setName("trends.body");
		listButton.setName("trends.listButton");
		chartButton.setName("trends.chartButton");
		metric.setName("trends.metric");
		monster.setName("trends.monster");
		list.setName("trends.list");
		chart.setName("trends.chart");
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		toggle.setFont(FontManager.getRunescapeSmallFont());
		toggle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(title, BorderLayout.WEST);
		header.add(toggle, BorderLayout.EAST);
		header.setToolTipText("<html>Compare completed tasks by profit, Slayer XP or Slayer points per active hour,"
			+ " or by profit per kill."
			+ "<br>List ranks monsters; Chart plots one point per task over time (hover a point for its task note)."
			+ "<br>An hourly rate needs " + TaskTimeEstimate.MIN_ACTIVE_MILLIS / 60_000 + " minute of active time."
			+ "<br>Points/h counts only tasks tracked from the full assigned amount.</html>");
		MouseAdapter toggleListener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggle();
			}
		};
		header.addMouseListener(toggleListener);
		title.addMouseListener(toggleListener);
		toggle.addMouseListener(toggleListener);
		SlayerLedgerPanel.addRow(content, header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel viewButtons = new JPanel(new GridLayout(1, 2, 4, 0));
		viewButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		ButtonGroup viewGroup = new ButtonGroup();
		for (JToggleButton button : new JToggleButton[]{listButton, chartButton})
		{
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setFocusable(false);
			button.setMargin(new Insets(1, 4, 1, 4));
			viewGroup.add(button);
			viewButtons.add(button);
		}
		listButton.setToolTipText("Rank monsters by the metric");
		chartButton.setToolTipText("Chart one monster's tasks over time");
		listButton.setSelected(true);
		listButton.addActionListener(e -> setView(View.LIST));
		chartButton.addActionListener(e -> setView(View.CHART));
		SlayerLedgerPanel.addRow(body, SlayerLedgerPanel.selectorRow("View", viewButtons));

		metric.setFocusable(false);
		metric.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected,
				boolean focused)
			{
				String text = metricLabel((TaskRanking.Metric) value);
				return super.getListCellRendererComponent(list, text, index, selected, focused);
			}
		});
		metric.addActionListener(e ->
		{
			if (isOpen() && !updatingChoices)
			{
				buildView();
			}
		});
		SlayerLedgerPanel.addRow(body, SlayerLedgerPanel.selectorRow("Metric", metric));

		monster.setFocusable(false);
		monsterIcons.install(monster, TaskChart.Monster::getTask);
		// Sized from a short name, not the longest choice, so neither a long name nor the icon widens the sidebar.
		monster.setPrototypeDisplayValue(TaskChart.Monster.prototype("Abyssal demons"));
		ComboPopupWidener.install(monster, ComboPopupWidener.MAX_WIDTH);
		monster.addActionListener(e ->
		{
			if (isOpen() && view == View.CHART && !updatingChoices)
			{
				buildChartPoints();
			}
		});
		monsterRow = SlayerLedgerPanel.selectorRow("Monster", monster);
		monsterRow.setName("trends.monsterRow");
		monsterBlock.setOpaque(false);
		monsterBlock.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		monsterBlock.add(monsterRow, BorderLayout.CENTER);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		// One row for the views: only the shown one takes space, so hidden ones leave no gaps.
		JPanel views = new JPanel();
		views.setLayout(new BoxLayout(views, BoxLayout.Y_AXIS));
		views.setOpaque(false);
		for (JPanel part : new JPanel[]{monsterBlock, list})
		{
			part.setAlignmentX(Component.LEFT_ALIGNMENT);
			views.add(part);
		}
		chart.setAlignmentX(Component.LEFT_ALIGNMENT);
		views.add(chart);
		SlayerLedgerPanel.addRow(body, views);
		body.setVisible(false);
		SlayerLedgerPanel.addRow(content, body);
		rebuild();
	}

	/**
	 * Shows the section as it now is: when open, builds the shown view from the current records, Loot price mode and
	 * prices; when collapsed, drops what was built. The panel calls this on record changes, a Loot price mode change
	 * and today's prices; never on its refresh timer.
	 */
	void rebuild()
	{
		toggle.setText(expanded ? "Hide" : "Show");
		body.setVisible(expanded);
		// The profit choice is labelled with the Loot price mode.
		metric.repaint();
		showViewComponents();
		if (isOpen())
		{
			buildView();
		}
		else
		{
			// Nothing is built while collapsed or hidden; opening or showing the section builds the shown view.
			clearList();
			clearChart();
		}
		relayout.run();
	}

	/**
	 * Applies the "Trends" setting: hidden, the section drops what was built and builds nothing; shown again, it
	 * is rebuilt from the current records at once if it was open.
	 */
	void setShown(boolean value)
	{
		if (shown != value)
		{
			shown = value;
			rebuild();
		}
	}

	/**
	 * A view worked out off the EDT is ready (the model's {@link LedgerHistoryModel.Change#VIEWS}): while open, builds
	 * the shown view again if the model now has a result it does not show.
	 */
	void viewsReady()
	{
		// While views wait for today's prices what is shown stays; the end of the wait rebuilds it.
		if (!isOpen() || model.isWaitingForCurrentPrices())
		{
			return;
		}
		TaskRanking.Metric selected = (TaskRanking.Metric) metric.getSelectedItem();
		if (view == View.LIST)
		{
			List<TaskRanking.Entry> entries = model.ranking(selected);
			if (entries != null && entries != shownRanking)
			{
				buildList();
			}
			return;
		}
		List<TaskChart.Monster> monsters = model.chartMonsters(selected);
		if (monsters == null)
		{
			return;
		}
		if (monsters != shownMonsters)
		{
			buildChart();
			return;
		}
		List<TaskChart.Point> points = model.chartPoints((TaskChart.Monster) monster.getSelectedItem(), selected);
		if (points != null && points != shownPoints)
		{
			buildChartPoints();
		}
	}

	/** Whether the section is open and its setting shows it, so the shown view is built. */
	private boolean isOpen()
	{
		return expanded && shown;
	}

	/** Opens or closes the section. */
	void toggle()
	{
		expanded = !expanded;
		rebuild();
	}

	/** Shows the list or the chart; when open, builds the newly shown one once and drops the other. */
	void setView(View newView)
	{
		if (newView == null || newView == view)
		{
			// Keep the buttons in step (a click on the selected button changes nothing).
			(view == View.LIST ? listButton : chartButton).setSelected(true);
			return;
		}
		view = newView;
		(view == View.LIST ? listButton : chartButton).setSelected(true);
		showViewComponents();
		if (view == View.LIST)
		{
			clearChart();
		}
		else
		{
			clearList();
		}
		if (isOpen())
		{
			buildView();
		}
		relayout.run();
	}

	private void showViewComponents()
	{
		boolean chartShown = view == View.CHART;
		monsterRow.setVisible(chartShown);
		monsterBlock.setVisible(chartShown);
		chart.setVisible(chartShown);
		list.setVisible(!chartShown);
	}

	private void buildView()
	{
		if (view == View.LIST)
		{
			buildList();
		}
		else
		{
			buildChart();
		}
	}

	/** A metric's name in the Metric choice; the profit one follows the Loot price mode. */
	private String metricLabel(TaskRanking.Metric value)
	{
		return value == null ? "" : value.label(model.lootPriceMode());
	}

	private void clearList()
	{
		list.removeAll();
		shownRanking = null;
	}

	private void clearChart()
	{
		chart.setData(Collections.emptyList(), null, null);
		shownMonsters = null;
		shownPoints = null;
	}

	private void buildList()
	{
		TaskRanking.Metric selected = (TaskRanking.Metric) metric.getSelectedItem();
		List<TaskRanking.Entry> entries = model.ranking(selected);
		if (entries == null)
		{
			// Worked out off the EDT: the rows shown stay until it is ready (viewsReady).
			return;
		}
		builds++;
		shownRanking = entries;
		list.removeAll();
		LootPriceMode mode = model.lootPriceMode();
		if (entries.isEmpty())
		{
			JLabel empty = new JLabel("No completed records with this data.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
			empty.setAlignmentX(Component.LEFT_ALIGNMENT);
			list.add(empty);
		}
		else
		{
			for (int i = 0; i < entries.size(); i++)
			{
				TaskRanking.Entry entry = entries.get(i);
				// Name left (truncates in a narrow sidebar), rate and count right-aligned, like a history line.
				JLabel name = SlayerLedgerPanel.historyLabel((i + 1) + ". " + entry.getMonster(),
					ColorScheme.LIGHT_GRAY_COLOR);
				// A name for tests, which read the icon from it; no visible effect.
				name.setName("trends.name");
				// The task's icon: a variant or cannon group shows its task's.
				SmallItemIcon.applyTask(icons, name, entry.getTask());
				JPanel row = SlayerLedgerPanel.historyLine(name,
					SlayerLedgerPanel.historyLabel(rateText(entry, selected), ColorScheme.LIGHT_GRAY_COLOR));
				row.setAlignmentX(Component.LEFT_ALIGNMENT);
				row.setBorder(BorderFactory.createEmptyBorder(3, 8, 3, 4));
				row.setToolTipText(rankingTooltip(entry, selected, mode));
				list.add(row);
				if (i + 1 < entries.size())
				{
					list.add(Box.createVerticalStrut(2));
				}
			}
		}
		relayout.run();
	}

	/** Refreshes the Monster choices for the metric (keeping the selection while it remains), then the points. */
	private void buildChart()
	{
		TaskRanking.Metric selected = (TaskRanking.Metric) metric.getSelectedItem();
		List<TaskChart.Monster> monsters = model.chartMonsters(selected);
		if (monsters == null)
		{
			// Worked out off the EDT: the chart shown stays until it is ready (viewsReady).
			return;
		}
		shownMonsters = monsters;
		TaskChart.Monster previous = (TaskChart.Monster) monster.getSelectedItem();
		updatingChoices = true;
		try
		{
			DefaultComboBoxModel<TaskChart.Monster> model = new DefaultComboBoxModel<>();
			for (TaskChart.Monster choice : monsters)
			{
				model.addElement(choice);
				// Each task's icon once, as the chart is built.
				monsterIcons.request(choice.getTask());
			}
			monster.setModel(model);
			int kept = previous == null ? -1 : monsters.indexOf(previous);
			if (kept >= 0)
			{
				// The new choice, so a changed label shows.
				monster.setSelectedIndex(kept);
			}
			monster.setEnabled(!monsters.isEmpty());
		}
		finally
		{
			updatingChoices = false;
		}
		buildChartPoints();
	}

	private void buildChartPoints()
	{
		TaskChart.Monster selectedMonster = (TaskChart.Monster) monster.getSelectedItem();
		TaskRanking.Metric selected = (TaskRanking.Metric) metric.getSelectedItem();
		List<TaskChart.Point> points = model.chartPoints(selectedMonster, selected);
		if (points == null)
		{
			// Worked out off the EDT: the points shown stay until they are ready (viewsReady).
			return;
		}
		builds++;
		shownPoints = points;
		chart.setData(points, metricLabel(selected), ZoneId.systemDefault());
		relayout.run();
	}

	/**
	 * The rate and sample count; {@code - (n=N)} while an hourly metric has under a minute of active time. Profit per
	 * kill shows as {@code 12.3K gp/kill (n=N)}.
	 */
	private static String rateText(TaskRanking.Entry entry, TaskRanking.Metric metric)
	{
		String sampleCount = " (n=" + entry.getSampleCount() + ")";
		if (entry.getRatePerHour() == null)
		{
			return LedgerHistory.NO_VALUE + sampleCount;
		}
		switch (metric)
		{
			case XP:
				return LedgerHistory.formatAmount(entry.getRatePerHour(), false) + " XP/h" + sampleCount;
			case POINTS:
				return LedgerHistory.formatAmount(entry.getRatePerHour(), false) + " points/h" + sampleCount;
			case PROFIT_PER_KILL:
				return LedgerHistory.formatGp(entry.getRatePerHour(), entry.isApproximate()) + "/kill" + sampleCount;
			default:
				return LedgerHistory.formatGp(entry.getRatePerHour(), entry.isApproximate()) + "/h" + sampleCount;
		}
	}

	private String rankingTooltip(TaskRanking.Entry entry, TaskRanking.Metric metric, LootPriceMode mode)
	{
		String source;
		switch (metric)
		{
			case XP:
				source = "Recorded Slayer XP divided by recorded active time";
				break;
			case POINTS:
				source = "Recorded Slayer points divided by recorded active time.<br>Only tasks tracked from the full"
					+ " assigned amount count; a task started part-way through is left out.<br>Bonus tasks (every"
					+ " 10th in a streak) are left out too";
				break;
			default:
				source = "Loot at " + mode + " prices minus GE-valued supplies"
					+ (mode == LootPriceMode.HIGH_ALCH
					? " (today's available GE prices for GE-priced items)"
					: " (today's available GE prices)");
				source += metric.isPerKill() ? ", divided by recorded kills" : ", divided by recorded active time";
				break;
		}
		Long rate = entry.getRatePerHour();
		String rateLine = metric.label(mode) + ": " + (rate == null
			? "no rate until " + TaskTimeEstimate.MIN_ACTIVE_MILLIS / 60_000 + " minute of active time"
			: (entry.isApproximate() ? LedgerHistory.APPROXIMATE : "") + String.format("%,d", rate));
		return "<html>" + LedgerHistory.escapeHtml(entry.getMonster()) + "<br>" + LedgerHistory.escapeHtml(rateLine)
			+ "<br>" + source + "<br>" + entry.getSampleCount() + (entry.getSampleCount() == 1
				? " completed task included" : " completed tasks included")
			+ (entry.isApproximate()
			? "<br>Some item prices were unavailable, or an older task kept its saved totals." : "") + "</html>";
	}

	/** How many times the shown view was built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}
}

