package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import org.junit.Test;

/** {@link AssignmentLog}: the bound, the check against saved records, the order and the row text. */
public class AssignmentLogTest
{
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("M/d/yy", Locale.US)
		.withZone(ZoneOffset.UTC);
	private static final DateTimeFormatter DATE_TIME = DateTimeFormatter.ofPattern("M/d/yy, h:mm a", Locale.US)
		.withZone(ZoneOffset.UTC);
	/** 2026-10-26 12:00 UTC. */
	private static final long OCT_26 = 1_793_016_000_000L;

	static AssignmentEntry entry(String id, long endedAt)
	{
		AssignmentEntry e = new AssignmentEntry();
		e.setId(id);
		e.setMonster("Abyssal demons");
		e.setCreatureId(42);
		e.setOriginalAmount(120);
		e.setEndedAt(endedAt);
		e.setOutcome(AssignmentOutcome.SKIPPED);
		e.setPointsChange(-30);
		return e;
	}

	private static LedgerRecord record(int creatureId, Integer amount, boolean completed, long endedAt)
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("r" + endedAt);
		r.setCreatureId(creatureId);
		r.setOriginalAmount(amount);
		r.setCompleted(completed);
		r.setPartial(!completed);
		r.setEndedAt(endedAt);
		return r;
	}

	@Test
	public void addKeepsTheNewestEntriesOldestFirst()
	{
		List<AssignmentEntry> entries = new ArrayList<>();
		for (int i = 0; i < AssignmentLog.MAX_ENTRIES; i++)
		{
			entries = AssignmentLog.add(entries, entry("e" + i, 1_000L + i));
		}
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		entries = AssignmentLog.add(entries, entry("newest", 5_000L));
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		assertEquals("the oldest went", "e1", entries.get(0).getId());
		assertEquals("newest", entries.get(entries.size() - 1).getId());
	}

	@Test
	public void anOlderEntryBeyondTheBoundIsNotKept()
	{
		List<AssignmentEntry> entries = new ArrayList<>();
		for (int i = 0; i < AssignmentLog.MAX_ENTRIES; i++)
		{
			entries.add(entry("e" + i, 1_000L + i));
		}
		entries = AssignmentLog.add(entries, entry("ancient", 1L));
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		assertTrue(entries.stream().noneMatch(e -> "ancient".equals(e.getId())));
	}

	@Test
	public void addIgnoresAnIdAlreadyThereAndNulls()
	{
		List<AssignmentEntry> entries = AssignmentLog.add(Arrays.asList(entry("a", 1L), null), entry("a", 2L));
		assertEquals(1, entries.size());
		assertEquals(1L, entries.get(0).getEndedAt());
		assertEquals(1, AssignmentLog.add(entries, null).size());
	}

	@Test
	public void sortNewestFirst()
	{
		List<AssignmentEntry> sorted = AssignmentLog.sortNewestFirst(Arrays.asList(entry("a", 1L), entry("b", 3L),
			null, entry("c", 2L)));
		assertEquals(Arrays.asList("b", "c", "a"), Arrays.asList(sorted.get(0).getId(), sorted.get(1).getId(),
			sorted.get(2).getId()));
		assertTrue(AssignmentLog.sortNewestFirst(null).isEmpty());
	}

	@Test
	public void playedBeforeWhenTheNewestRecordIsAPartialOfTheSameTask()
	{
		AssignmentEntry e = entry("a", 9_000L);
		assertTrue(AssignmentLog.playedBefore(Arrays.asList(record(46, 150, true, 1_000L), record(42, 120, false, 2_000L)),
			e));
		assertTrue("size unknown in the record", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, null, false, 2_000L)), e));
	}

	@Test
	public void notPlayedBeforeOtherwise()
	{
		AssignmentEntry e = entry("a", 9_000L);
		assertFalse("no records", AssignmentLog.playedBefore(Collections.emptyList(), e));
		assertFalse("completed: that assignment ended", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, 120, true, 2_000L)), e));
		assertFalse("another task", AssignmentLog.playedBefore(
			Collections.singletonList(record(46, 120, false, 2_000L)), e));
		assertFalse("another size", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, 200, false, 2_000L)), e));
		assertFalse("only the newest counts", AssignmentLog.playedBefore(
			Arrays.asList(record(42, 120, false, 1_000L), record(46, 150, true, 2_000L)), e));
		e.setCreatureId(null);
		assertFalse("unknown task", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, 120, false, 2_000L)), e));
	}

	@Test
	public void rowText()
	{
		assertEquals("Abyssal demons \u00b7 Skipped \u00b7 10/26/26", AssignmentLog.rowText(entry("a", OCT_26), DATE));
		AssignmentEntry e = entry("a", OCT_26);
		e.setOutcome(null);
		e.setMonster(null);
		assertEquals("Unknown task \u00b7 Ended \u00b7 10/26/26", AssignmentLog.rowText(e, DATE));
		e.setEndedAt(0);
		assertEquals("Ended", AssignmentLog.status(e, DATE));
	}

	@Test
	public void tooltipShowsKnownPartsOnly()
	{
		AssignmentEntry e = entry("a", OCT_26);
		e.setSlayerMaster(5);
		assertEquals("<html>Abyssal demons<br>Skipped (cancelled for points)<br>Ended: 10/26/26, 12:00 PM"
			+ "<br>Master: Duradel/Kuradal<br>Type: Regular<br>Assigned: 120<br>Points: -30</html>",
			AssignmentLog.tooltip(e, DATE_TIME));

		AssignmentEntry bare = new AssignmentEntry();
		bare.setOutcome(AssignmentOutcome.COMPLETED);
		bare.setMonster("<b>x</b>");
		assertEquals("<html>&lt;b&gt;x&lt;/b&gt;<br>Completed without a tracked session</html>",
			AssignmentLog.tooltip(bare, DATE_TIME));

		AssignmentEntry konar = entry("k", OCT_26);
		konar.setSlayerMaster(SlayerMaster.KONAR);
		konar.setTaskLocation("Kraken Cove");
		konar.setSlayerArea(12);
		konar.setPointsChange(18);
		konar.setOutcome(AssignmentOutcome.COMPLETED);
		String tip = AssignmentLog.tooltip(konar, DATE_TIME);
		assertTrue(tip, tip.contains("<br>Type: Konar (Kraken Cove)<br>"));
		assertTrue(tip, tip.endsWith("<br>Points: +18</html>"));
	}

	@Test
	public void deleteConfirmation()
	{
		assertEquals("Delete this Abyssal demons entry (skipped)? This can't be undone.",
			AssignmentLog.deleteConfirmation(entry("a", 1L)));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/** {@link AssignmentOutcome#classify}: every outcome, and the ambiguous cases that must stay unknown. */
public class AssignmentOutcomeTest
{
	private static AssignmentOutcome classify(boolean completed, Integer points, boolean blocked, boolean streakDropped)
	{
		return AssignmentOutcome.classify(completed, points, blocked, streakDropped);
	}

	@Test
	public void pointsSpentWithoutABlockIsASkip()
	{
		assertEquals(AssignmentOutcome.SKIPPED, classify(false, -30, false, false));
		// Costs vary by master; any amount counts.
		assertEquals(AssignmentOutcome.SKIPPED, classify(false, -100, false, false));
		assertEquals(AssignmentOutcome.SKIPPED, classify(false, -1, false, false));
	}

	@Test
	public void pointsSpentWithABlockChangeIsABlock()
	{
		assertEquals(AssignmentOutcome.BLOCKED, classify(false, -100, true, false));
		assertEquals(AssignmentOutcome.BLOCKED, classify(false, -40, true, false));
	}

	@Test
	public void aStreakDropWithNoPointsSpentIsAReset()
	{
		assertEquals(AssignmentOutcome.RESET, classify(false, 0, false, true));
	}

	@Test
	public void aCompletionIsCompleted()
	{
		assertEquals(AssignmentOutcome.COMPLETED, classify(true, 15, false, false));
		assertEquals("no points (an early task)", AssignmentOutcome.COMPLETED, classify(true, 0, false, false));
		assertEquals("points not read", AssignmentOutcome.COMPLETED, classify(true, null, false, false));
	}

	@Test
	public void nothingChangedIsUnknown()
	{
		assertEquals(AssignmentOutcome.UNKNOWN, classify(false, 0, false, false));
	}

	@Test
	public void ambiguousSignalsAreUnknown()
	{
		assertEquals("completion and streak reset", AssignmentOutcome.UNKNOWN, classify(true, 15, false, true));
		assertEquals("completion and block", AssignmentOutcome.UNKNOWN, classify(true, -85, true, false));
		assertEquals("points spent and streak reset", AssignmentOutcome.UNKNOWN, classify(false, -30, false, true));
		assertEquals("points spent, block and streak reset", AssignmentOutcome.UNKNOWN,
			classify(false, -100, true, true));
		assertEquals("points up without a completion", AssignmentOutcome.UNKNOWN, classify(false, 20, false, false));
		assertEquals("a block without points spent", AssignmentOutcome.UNKNOWN, classify(false, 0, true, false));
		assertEquals("reset with a block change", AssignmentOutcome.UNKNOWN, classify(false, 0, true, true));
		assertEquals("points unknown", AssignmentOutcome.UNKNOWN, classify(false, null, false, false));
		assertEquals("points unknown with a block", AssignmentOutcome.UNKNOWN, classify(false, null, true, false));
		assertEquals("points unknown with a streak drop", AssignmentOutcome.UNKNOWN, classify(false, null, false, true));
	}

	@Test
	public void aMissingOutcomeReadsAsUnknown()
	{
		assertEquals(AssignmentOutcome.UNKNOWN, AssignmentOutcome.orUnknown(null));
		assertEquals(AssignmentOutcome.BLOCKED, AssignmentOutcome.orUnknown(AssignmentOutcome.BLOCKED));
		assertEquals("Ended (reason unknown)", AssignmentOutcome.UNKNOWN.getDescription());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** {@link AssignmentPreviewMessage}: the new-assignment chat line from the History estimate's statistics. */
public class AssignmentPreviewMessageTest
{
	private static final long MINUTE = 60_000L;
	private static final int DEMONS = 42;

	/**
	 * A completed Abyssal demons task: 10 kills in 10 minutes, loot 100K GE / 200K HA, supplies 10K, 1 bank trip; with
	 * its items ({@link SavedItems}).
	 */
	private static LedgerRecord task(String location)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(DEMONS);
		record.setMonster("Abyssal demons");
		record.setKills(10);
		record.setActiveMillis(10 * MINUTE);
		record.setCompleted(true);
		record.setLootGeValue(100_000L);
		record.setLootHaValue(200_000L);
		record.setSuppliesGeValue(10_000L);
		record.setBankTrips(1);
		record.setLocation(location);
		return SavedItems.withItems(record);
	}

	private static TaskStatistics stats(List<LedgerRecord> records, LootPriceMode mode)
	{
		return TaskStatistics.forTask(records, DEMONS, "Abyssal demons", mode, SavedItems.todaysPrices());
	}

	private static String format(int kills, List<LedgerRecord> records, LootPriceMode mode)
	{
		return AssignmentPreviewMessage.format("Abyssal demons", kills, stats(records, mode), mode);
	}

	@Test
	public void theFullLineHasTimeProfitAndBankTripsForTheKillsLeft()
	{
		List<LedgerRecord> records = Arrays.asList(task(null), task(null), task(null));
		assertEquals("Abyssal demons (172): ~2:52:00 · +1.54M (GE) · ~18 bank trips (from 3 tasks)",
			format(172, records, LootPriceMode.GE));
	}

	@Test
	public void theProfitIsInTheLootPriceModeAndSaysWhich()
	{
		List<LedgerRecord> records = Collections.singletonList(task(null));
		assertEquals("Abyssal demons (20): ~0:20:00 · +180K (GE) · ~2 bank trips (from 1 task)",
			format(20, records, LootPriceMode.GE));
		assertEquals("Abyssal demons (20): ~0:20:00 · +380K (HA) · ~2 bank trips (from 1 task)",
			format(20, records, LootPriceMode.HIGH_ALCH));
	}

	@Test
	public void unknownPartsAreLeftOut()
	{
		// Saved before values and bank trips were tracked: only the time is known.
		LedgerRecord old = task(null);
		old.setLootGeValue(null);
		old.setLootHaValue(null);
		old.setSuppliesGeValue(null);
		old.setBankTrips(null);
		assertEquals("Abyssal demons (20): ~0:20:00 (from 1 task)",
			format(20, Collections.singletonList(old), LootPriceMode.GE));

		// No bank trips on any of them: "No bank trips", as What to bring.
		LedgerRecord noTrips = task(null);
		noTrips.setBankTrips(0);
		assertEquals("Abyssal demons (20): ~0:20:00 · +180K (GE) · No bank trips (from 1 task)",
			format(20, Collections.singletonList(noTrips), LootPriceMode.GE));
	}

	@Test
	public void anApproximateOrLosingProfitPutsTheSignAfterTheMark()
	{
		LedgerRecord loss = task(null);
		loss.setLootGeValue(1_000L);
		loss.setSuppliesGeValue(6_000L);
		SavedItems.withItems(loss);
		// Item 7 has no price today.
		Map<Integer, Long> loot = new HashMap<>(loss.getLoot());
		loot.put(7, 1L);
		loss.setLoot(loot);
		loss.setBankTrips(null);
		assertEquals("Abyssal demons (10): ~0:10:00 · ~-5,000 (GE) (from 1 task)",
			format(10, Collections.singletonList(loss), LootPriceMode.GE));
	}

	@Test
	public void historyLimitedToALocationSaysWhere()
	{
		List<LedgerRecord> records = Arrays.asList(task("Catacombs of Kourend"), task("Abyss"));
		TaskStatistics stats = TaskStatistics.forTask(records, DEMONS, "Abyssal demons", "Catacombs of Kourend",
			LedgerRecord::getLocation, LootPriceMode.GE, SavedItems.todaysPrices());
		assertEquals("Abyssal demons (10): ~0:10:00 · +90K (GE) · ~1 bank trip (from 1 task at Catacombs of Kourend)",
			AssignmentPreviewMessage.format("Abyssal demons", 10, stats, LootPriceMode.GE));
	}

	@Test
	public void nothingWithoutCompletedHistory()
	{
		LedgerRecord partial = task(null);
		partial.setPartial(true);
		assertNull(format(20, Collections.singletonList(partial), LootPriceMode.GE));
		assertNull(format(20, Collections.emptyList(), LootPriceMode.GE));
		assertNull("no kills left", format(0, Collections.singletonList(task(null)), LootPriceMode.GE));
		assertNull(AssignmentPreviewMessage.format("Abyssal demons", 20, null, LootPriceMode.GE));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link AssignmentWatch}: which assignment ends produce an entry, with which outcome, and the guards (played tasks,
 * transient zeros, logins). The readings come from a small fake of the game's values, with a real
 * {@link CompletionSignal} as in the plugin.
 */
public class AssignmentWatchTest
{
	private static final int DEMONS = 42;
	private static final int GARGOYLES = 46;

	private final AssignmentWatch watch = new AssignmentWatch();
	private final CompletionSignal completionSignal = new CompletionSignal();
	private final List<AssignmentWatch.Ended> ended = new ArrayList<>();
	private long now = 1_000_000L;

	// The fake game's values.
	private String monster;
	private int creatureId = SessionTracker.NO_CREATURE;
	private int remaining;
	private int amount;
	private int master = SlayerMaster.NONE;
	private int points = 500;
	private int[] counters = {10, 0, 0};
	private int[] blocked = {0, 0, 0};
	/** Keys a session held this tick. */
	private Set<Integer> sessionKeys = Collections.emptySet();

	@Before
	public void setUp()
	{
		// The first readings after a start only sync; with no task, the sync ends after SYNC_MAX_TICKS.
		clearTask();
		ticks(AssignmentWatch.SYNC_MAX_TICKS);
		// Then the task is assigned while watched.
		assign("Abyssal demons", DEMONS, 120, 5);
		tick();
		assertTrue(watch.hasCurrent());
		assertTrue(ended.isEmpty());
	}

	private void assign(String name, int key, int count, int byMaster)
	{
		monster = name;
		creatureId = key;
		remaining = count;
		amount = count;
		master = byMaster;
	}

	private void clearTask()
	{
		monster = null;
		creatureId = SessionTracker.NO_CREATURE;
		remaining = 0;
		amount = 0;
		master = SlayerMaster.NONE;
	}

	private void tick()
	{
		final boolean completion = completionSignal.update(counters);
		final TaskContext context = remaining > 0 ? TaskContext.assignment(master, 0, null) : TaskContext.NONE;
		ended.addAll(watch.update(AssignmentWatch.Reading.builder().monster(monster).creatureId(creatureId)
			.remaining(remaining).originalAmount(amount).context(context).points(points).counters(counters.clone())
			.blockedValues(blocked.clone()).completionSignaled(completion).build(), sessionKeys, now));
		now += 600;
	}

	private void ticks(int n)
	{
		for (int i = 0; i < n; i++)
		{
			tick();
		}
	}

	/** Ticks out the decision window. */
	private void settle()
	{
		ticks(AssignmentWatch.END_WINDOW_TICKS + 1);
	}

	private void login()
	{
		watch.reset();
		completionSignal.reset();
	}

	private AssignmentEntry only()
	{
		assertEquals(ended.toString(), 1, ended.size());
		return ended.get(0).getEntry();
	}

	@Test
	public void aTaskAssignedWhileWatchedIsStartedOnce()
	{
		assertTrue(watch.takeStarted());
		assertFalse(watch.takeStarted());
		tick();
		assertFalse(watch.takeStarted());
	}

	@Test
	public void theSameTaskBackAfterAZeroIsNotStartedAgain()
	{
		watch.takeStarted();
		remaining = 80;
		tick();
		clearTask();
		ticks(2);
		assign("Abyssal demons", DEMONS, 120, 5);
		remaining = 80;
		tick();
		assertFalse("transient zero", watch.takeStarted());
		clearTask();
		ticks(20);
		assign("Abyssal demons", DEMONS, 120, 5);
		remaining = 79;
		tick();
		assertFalse("long zero", watch.takeStarted());
	}

	@Test
	public void aDirectChangeToAnotherTaskIsStarted()
	{
		watch.takeStarted();
		assign("Gargoyles", GARGOYLES, 150, 5);
		tick();
		assertTrue(watch.takeStarted());
		assertFalse(watch.takeStarted());
	}

	@Test
	public void aTaskSeenAfterAForgetOrLoginIsNotStarted()
	{
		watch.takeStarted();
		watch.forget();
		tick();
		assertFalse("account change", watch.takeStarted());
		login();
		ticks(AssignmentWatch.SYNC_MAX_TICKS);
		assertFalse("login", watch.takeStarted());
	}

	@Test
	public void aSkipIsRecordedWithThePointsSpent()
	{
		remaining = 80;
		tick();
		final long endTime = now;
		clearTask();
		points -= 30;
		settle();

		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.SKIPPED, e.getOutcome());
		assertEquals(Integer.valueOf(-30), e.getPointsChange());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals(Integer.valueOf(DEMONS), e.getCreatureId());
		assertEquals(Integer.valueOf(120), e.getOriginalAmount());
		assertEquals(Integer.valueOf(5), e.getSlayerMaster());
		assertEquals("the first tick it was gone", endTime, e.getEndedAt());
		assertNotNull(e.getId());
		assertFalse("watched from its start", ended.get(0).isCheckRecords());
	}

	@Test
	public void theOutcomeIsDecidedAfterTheWindow()
	{
		clearTask();
		points -= 30;
		ticks(AssignmentWatch.END_WINDOW_TICKS);
		assertTrue("not yet", ended.isEmpty());
		tick();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
	}

	@Test
	public void pointsArrivingLateInTheWindowStillCount()
	{
		clearTask();
		tick();
		points -= 30;
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
		assertEquals(Integer.valueOf(-30), only().getPointsChange());
	}

	@Test
	public void aSkipFollowedQuicklyByANewTaskIsStillASkip()
	{
		clearTask();
		points -= 30;
		tick();
		assign("Gargoyles", GARGOYLES, 150, 5);
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
		assertEquals("Abyssal demons", only().getMonster());
		assertTrue("the new task is watched", watch.hasCurrent());
	}

	@Test
	public void aBlockIsRecorded()
	{
		clearTask();
		points -= 100;
		blocked[1] = DEMONS;
		settle();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.BLOCKED, e.getOutcome());
		assertEquals(Integer.valueOf(-100), e.getPointsChange());
	}

	@Test
	public void aTuraelResetIsRecorded()
	{
		// Turael gives a new task straight away and the streak drops to 0; no points are spent.
		assign("Cows", 6, 20, 1);
		counters[0] = 0;
		settle();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.RESET, e.getOutcome());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals(Integer.valueOf(0), e.getPointsChange());
	}

	@Test
	public void aCompletionWithoutASessionIsRecorded()
	{
		remaining = 1;
		tick();
		clearTask();
		counters[0]++;
		points += 15;
		settle();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.COMPLETED, e.getOutcome());
		assertEquals(Integer.valueOf(15), e.getPointsChange());
	}

	@Test
	public void aStreakArrivingAfterTheCountStillCountsAsACompletion()
	{
		clearTask();
		tick();
		counters[0]++;
		points += 15;
		settle();
		assertEquals(AssignmentOutcome.COMPLETED, only().getOutcome());
	}

	@Test
	public void anEndThatFitsNothingIsUnknownOnceTheNextTaskAppears()
	{
		// Count to 0 with nothing else changing (for example the task was stored).
		clearTask();
		settle();
		assertTrue("an unknown end by a 0 count waits", ended.isEmpty());
		ticks(20);
		assertTrue(ended.isEmpty());
		assign("Gargoyles", GARGOYLES, 150, 5);
		tick();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.UNKNOWN, e.getOutcome());
		assertEquals(Integer.valueOf(0), e.getPointsChange());
	}

	@Test
	public void aDirectChangeThatFitsNothingIsUnknown()
	{
		assign("Gargoyles", GARGOYLES, 150, 5);
		settle();
		assertEquals(AssignmentOutcome.UNKNOWN, only().getOutcome());
	}

	@Test
	public void theUnknownOutcomeUsesTheWindowsReadings()
	{
		clearTask();
		settle();
		// Points spent long after the end (a reward bought) don't turn it into a skip.
		points -= 30;
		ticks(5);
		assign("Gargoyles", GARGOYLES, 150, 5);
		tick();
		assertEquals(AssignmentOutcome.UNKNOWN, only().getOutcome());
		assertEquals(Integer.valueOf(0), only().getPointsChange());
	}

	@Test
	public void aTransientZeroIsNotAnEnd()
	{
		remaining = 80;
		tick();
		clearTask();
		ticks(2);
		assign("Abyssal demons", DEMONS, 120, 5);
		remaining = 80;
		settle();
		assertTrue(ended.isEmpty());
		assertFalse(watch.hasPending());
	}

	@Test
	public void theSameTaskAfterALongZeroIsNotAnEnd()
	{
		remaining = 80;
		tick();
		clearTask();
		ticks(20);
		assign("Abyssal demons", DEMONS, 120, 5);
		remaining = 79;
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void theSameCreatureWithMoreLeftAfterALongZeroIsANewAssignment()
	{
		remaining = 80;
		tick();
		clearTask();
		ticks(20);
		assign("Abyssal demons", DEMONS, 120, 5);
		tick();
		assertEquals(AssignmentOutcome.UNKNOWN, only().getOutcome());
	}

	@Test
	public void killsOnTheTaskAreNotAnEnd()
	{
		for (int i = 0; i < 10; i++)
		{
			remaining--;
			tick();
		}
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void aPlayedTaskIsNeverRecorded()
	{
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		clearTask();
		points -= 30;
		settle();
		assertTrue("skipped after a session", ended.isEmpty());
	}

	@Test
	public void aCompletedPlayedTaskIsNeverRecorded()
	{
		sessionKeys = Collections.singleton(DEMONS);
		clearTask();
		counters[0]++;
		tick();
		sessionKeys = Collections.emptySet();
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void aSessionTakingTheTaskOnTheEndTickStillCounts()
	{
		clearTask();
		points -= 30;
		// Reported on the tick the count dropped (for example Play pressed and Stopped within one tick).
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void aSessionOnAnotherTaskDoesNotMarkThisOne()
	{
		sessionKeys = new HashSet<>(Collections.singletonList(GARGOYLES));
		tick();
		sessionKeys = Collections.emptySet();
		clearTask();
		points -= 30;
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
	}

	@Test
	public void theFirstReadingAfterALoginProducesNothing()
	{
		login();
		// The task was skipped while logged out (on another client): the login resync shows a new task.
		points -= 30;
		assign("Gargoyles", GARGOYLES, 150, 5);
		tick();
		settle();
		assertTrue(ended.isEmpty());
		assertTrue(watch.hasCurrent());
	}

	@Test
	public void aZeroCountWhileTheLoginSyncsProducesNothing()
	{
		login();
		clearTask();
		points = 0;
		ticks(3);
		assign("Abyssal demons", DEMONS, 120, 5);
		points = 500;
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void anAssignmentActiveAtLogoutKeepsItsPlayedFlag()
	{
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		login();
		tick();
		clearTask();
		points -= 30;
		settle();
		assertTrue("played before the logout", ended.isEmpty());
	}

	@Test
	public void anUndecidedEndIsDroppedByALogin()
	{
		clearTask();
		points -= 30;
		tick();
		login();
		settle();
		assertTrue(ended.isEmpty());
		assertFalse(watch.hasPending());
	}

	@Test
	public void anAssignmentFirstSeenAtAStartIsCheckedAgainstTheRecords()
	{
		watch.forget();
		completionSignal.reset();
		tick();
		clearTask();
		points -= 30;
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
		assertTrue(ended.get(0).isCheckRecords());
	}

	@Test
	public void forgettingDropsThePlayedFlag()
	{
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		// Another account logged in.
		watch.forget();
		tick();
		clearTask();
		points -= 30;
		settle();
		assertEquals(1, ended.size());
	}

	@Test
	public void aSecondEndInsideTheWindowDecidesTheFirstAtOnce()
	{
		// Turael reset to cows, then the cows task is skipped straight away.
		assign("Cows", 6, 20, 1);
		counters[0] = 0;
		tick();
		clearTask();
		points -= 30;
		tick();
		assertEquals(1, ended.size());
		assertEquals("Abyssal demons", ended.get(0).getEntry().getMonster());
		assertEquals("judged before the skip", AssignmentOutcome.RESET, ended.get(0).getEntry().getOutcome());
		settle();
		assertEquals(2, ended.size());
		assertEquals("Cows", ended.get(1).getEntry().getMonster());
		assertEquals(AssignmentOutcome.SKIPPED, ended.get(1).getEntry().getOutcome());
	}

	@Test
	public void noTaskAtAllProducesNothing()
	{
		clearTask();
		login();
		ticks(AssignmentWatch.SYNC_MAX_TICKS + 5);
		assertTrue(ended.isEmpty());
		assertFalse(watch.hasCurrent());
	}

	@Test
	public void unknownPartsAreStoredAsNull()
	{
		watch.forget();
		completionSignal.reset();
		monster = null;
		amount = 0;
		master = SlayerMaster.NONE;
		tick();
		clearTask();
		points -= 30;
		settle();
		AssignmentEntry e = only();
		assertNull(e.getMonster());
		assertNull(e.getOriginalAmount());
		assertNull(e.getSlayerMaster());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

/**
 * Which bank openings are new bank trips; {@link SessionTrackerCountersTest} covers the count on the session.
 */
public class BankTripCounterTest
{
	private static final String SESSION = "session-1";
	private static final int WINDOW = BankTripCounter.SAME_TRIP_TICKS;

	private final BankTripCounter counter = new BankTripCounter();

	@Test
	public void bankInterfacesAreTheBankDepositBoxAndGroupStorage()
	{
		assertTrue(BankTripCounter.isBankInterface(InterfaceID.BANKMAIN));
		assertTrue(BankTripCounter.isBankInterface(InterfaceID.BANK_DEPOSITBOX));
		assertTrue(BankTripCounter.isBankInterface(InterfaceID.SHARED_BANK));
		assertFalse(BankTripCounter.isBankInterface(InterfaceID.SEED_VAULT));
		assertFalse(BankTripCounter.isBankInterface(InterfaceID.GE_OFFERS));
		assertFalse(BankTripCounter.isBankInterface(149));
		assertEquals(3, BankTripCounter.bankInterfaces().length);
		// The same interfaces supply counting already leaves out.
		for (int group : BankTripCounter.bankInterfaces())
		{
			assertTrue(SupplyExclusions.isExcludedInterface(group));
		}
	}

	@Test
	public void windowIsThirtySeconds()
	{
		// 50 game ticks of 0.6 s.
		assertEquals(30_000, BankTripCounter.SAME_TRIP_TICKS * 600);
	}

	@Test
	public void firstOpeningWhileRunningIsATrip()
	{
		assertTrue(counter.bankOpened(100, true, SESSION));
	}

	@Test
	public void reopeningWithinTheWindowOfClosingIsTheSameTrip()
	{
		assertTrue(counter.bankOpened(100, true, SESSION));
		// A long bank visit: the window runs from closing, not opening.
		counter.bankClosed(400);
		assertFalse(counter.bankOpened(400 + WINDOW, true, SESSION));
		counter.bankClosed(410 + WINDOW);
		assertFalse("deposit box after the bank", counter.bankOpened(410 + 2 * WINDOW, true, SESSION));
	}

	@Test
	public void openingAfterTheWindowIsANewTrip()
	{
		assertTrue(counter.bankOpened(100, true, SESSION));
		counter.bankClosed(110);
		assertTrue(counter.bankOpened(110 + WINDOW + 1, true, SESSION));
		counter.bankClosed(200 + WINDOW);
		assertTrue(counter.bankOpened(201 + 2 * WINDOW, true, SESSION));
	}

	@Test
	public void openingWithoutCloseUsesTheOpeningTick()
	{
		assertTrue(counter.bankOpened(100, true, SESSION));
		assertFalse(counter.bankOpened(100 + WINDOW, true, SESSION));
		assertTrue(counter.bankOpened(101 + 2 * WINDOW, true, SESSION));
	}

	@Test
	public void bankingWhilePausedOrIdleIsNeverATrip()
	{
		assertFalse("paused", counter.bankOpened(100, false, SESSION));
		assertFalse("no session", counter.bankOpened(1_000, false, null));
		assertFalse("running without a session id", counter.bankOpened(2_000, true, null));
	}

	@Test
	public void reopeningRightAfterResumingIsTheSameTripAsThePausedVisit()
	{
		assertFalse(counter.bankOpened(100, false, SESSION));
		counter.bankClosed(105);
		assertFalse(counter.bankOpened(110, true, SESSION));
		counter.bankClosed(115);
		assertTrue(counter.bankOpened(116 + WINDOW, true, SESSION));
	}

	@Test
	public void aNewSessionsFirstOpeningAlwaysCounts()
	{
		assertFalse("idle", counter.bankOpened(100, false, null));
		counter.bankClosed(101);
		assertTrue(counter.bankOpened(102, true, SESSION));
		counter.bankClosed(103);
		assertTrue("the next session", counter.bankOpened(104, true, "session-2"));
	}

	@Test
	public void closingWithoutAnOpeningDoesNotStartAWindow()
	{
		counter.bankClosed(100);
		assertTrue(counter.bankOpened(101, true, SESSION));
	}

	@Test
	public void aTickCountThatWentBackIsANewTrip()
	{
		assertTrue(counter.bankOpened(5_000, true, SESSION));
		assertTrue(counter.bankOpened(10, true, SESSION));
	}

	@Test
	public void resetForgetsTheLastVisit()
	{
		assertTrue(counter.bankOpened(100, true, SESSION));
		counter.reset();
		assertTrue(counter.bankOpened(101, true, SESSION));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * The blowpipe's dart type read from its check and out-of-darts messages.
 */
public class BlowpipeMessageTest
{
	@Test
	public void checkMessageWithDarts()
	{
		final BlowpipeMessage.Darts darts = BlowpipeMessage.parse(
			"Darts: <col=007f00>Adamant dart x 16,383</col>. Scales: <col=007f00>16,383 (100.0%)</col>.");
		assertTrue(darts.isLoaded());
		assertEquals(ItemID.ADAMANT_DART, darts.getDartId());
		assertEquals(16_383, darts.getDartCount());
		assertEquals(16_383, darts.getScales());
	}

	@Test
	public void checkMessageWithoutTags()
	{
		final BlowpipeMessage.Darts darts = BlowpipeMessage.parse("Darts: Dragon dart x 5. Scales: 0 (0.0%).");
		assertEquals(ItemID.DRAGON_DART, darts.getDartId());
		assertEquals(5, darts.getDartCount());
		assertEquals(0, darts.getScales());
	}

	@Test
	public void checkMessageWithNoDarts()
	{
		final BlowpipeMessage.Darts darts = BlowpipeMessage.parse(
			"Darts: <col=007f00>None</col>. Scales: <col=007f00>99 (0.6%)</col>.");
		assertFalse(darts.isLoaded());
		assertEquals(ChargedWeaponUsage.NO_ITEM, darts.getDartId());
		assertEquals(0, darts.getDartCount());
		assertEquals(99, darts.getScales());
	}

	@Test
	public void everyDartName()
	{
		assertDart("Bronze dart", ItemID.BRONZE_DART);
		assertDart("Iron dart", ItemID.IRON_DART);
		assertDart("Steel dart", ItemID.STEEL_DART);
		assertDart("Black dart", ItemID.BLACK_DART);
		assertDart("Mithril dart", ItemID.MITHRIL_DART);
		assertDart("Adamant dart", ItemID.ADAMANT_DART);
		assertDart("Rune dart", ItemID.RUNE_DART);
		assertDart("Amethyst dart", ItemID.AMETHYST_DART);
		assertDart("Dragon dart", ItemID.DRAGON_DART);
	}

	private static void assertDart(String name, int itemId)
	{
		assertEquals(name, itemId, BlowpipeMessage.parse("Darts: " + name + " x 1,000. Scales: 2 (0.0%).").getDartId());
		assertEquals(name, itemId, BlowpipeMessage.dartId(name.toUpperCase()));
	}

	@Test
	public void unknownDartNameIsLoadedButUnknown()
	{
		final BlowpipeMessage.Darts darts = BlowpipeMessage.parse("Darts: Atlatl dart x 12. Scales: 3 (0.1%).");
		assertTrue(darts.isLoaded());
		assertEquals(ChargedWeaponUsage.NO_ITEM, darts.getDartId());
		assertEquals(12, darts.getDartCount());
	}

	@Test
	public void outOfDartsMessages()
	{
		for (String message : new String[]{
			"Your blowpipe has run out of darts.",
			"Your blowpipe has run out of scales and darts.",
			"Your blowpipe contains no darts.",
			"Your blowpipe needs to be charged with Zulrah's scales and loaded with darts.",
			"<col=ef1020>The blowpipe has no darts in it.</col>"})
		{
			final BlowpipeMessage.Darts darts = BlowpipeMessage.parse(message);
			assertFalse(message, darts.isLoaded());
			assertEquals(ChargedWeaponUsage.NO_ITEM, darts.getDartId());
			assertEquals(-1, darts.getScales());
		}
	}

	@Test
	public void otherMessagesAreIgnored()
	{
		assertNull(BlowpipeMessage.parse(null));
		assertNull(BlowpipeMessage.parse(""));
		assertNull(BlowpipeMessage.parse("Your blowpipe needs to be charged with Zulrah's scales."));
		assertNull(BlowpipeMessage.parse("The blowpipe can't hold any more darts."));
		assertNull(BlowpipeMessage.parse("Scales: 11,000 (100.0%)"));
		assertNull(BlowpipeMessage.parse("Player: Darts: Rune dart x 5. Scales: 3 (0.1%). lol"));
		assertNull(BlowpipeMessage.parse("Darts: Rune dart x 5. Scales: 3."));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/** {@link BossKillCounts}: which messages belong to a task, name matching, the per-task counts and their lines. */
public class BossKillCountsTest
{
	private static final int BOSS_TASK = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 20);
	private static final int REGULAR_TASK = 42;

	@Test
	public void nameMatchingIgnoresCaseTagsAndSpacing()
	{
		assertTrue(BossKillCounts.sameName("TzTok-Jad", "tztok-jad"));
		assertTrue(BossKillCounts.sameName("<col=ff0000>TzTok-Jad</col>", " TzTok-Jad "));
		assertTrue("double and non-breaking spaces",
			BossKillCounts.sameName("Kalphite  Queen", "Kalphite\u00A0queen"));
		assertFalse("no fuzzy matching", BossKillCounts.sameName("Dagannoth Kings", "Dagannoth Rex"));
		assertFalse(BossKillCounts.sameName("Black demons", "Black demon"));
		assertFalse(BossKillCounts.sameName(null, null));
		assertFalse(BossKillCounts.sameName("", ""));
		assertEquals("Vorkath", BossKillCounts.cleanName("<col=ff0000>Vorkath</col>"));
	}

	@Test
	public void bossTasksTakeEveryBossRegularTasksOnlyTheirOwn()
	{
		assertTrue(BossKillCounts.appliesTo("Dagannoth Kings", BOSS_TASK, "Dagannoth Rex"));
		assertTrue("the name lookup failed", BossKillCounts.appliesTo(null, BOSS_TASK, "Vorkath"));
		assertTrue(BossKillCounts.appliesTo("TzTok-Jad", REGULAR_TASK, "TzTok-Jad"));
		assertTrue(BossKillCounts.appliesTo("Tztok-jad", REGULAR_TASK, "<col=ff0000>TzTok-Jad</col>"));
		assertFalse(BossKillCounts.appliesTo("Abyssal demons", REGULAR_TASK, "Vorkath"));
		assertFalse(BossKillCounts.appliesTo(null, REGULAR_TASK, "Vorkath"));
		assertFalse(BossKillCounts.appliesTo("TzTok-Jad", SessionTracker.NO_CREATURE, "Vorkath"));
		assertFalse(BossKillCounts.appliesTo("Vorkath", BOSS_TASK, " "));
	}

	@Test
	public void countsKillsFromTheFirstMessage()
	{
		List<BossKillCount> counts = BossKillCounts.add(null, "Vorkath", 141);
		assertEquals(Collections.singletonList(new BossKillCount("Vorkath", 141, 141, 1)), counts);
		counts = BossKillCounts.add(counts, "vorkath", 142);
		counts = BossKillCounts.add(counts, "Vorkath", 152);
		assertEquals("one kill per message; the first spelling stays",
			Collections.singletonList(new BossKillCount("Vorkath", 141, 152, 3)), counts);
	}

	@Test
	public void repeatedOrLowerCountsAndBadCountsAreIgnored()
	{
		List<BossKillCount> counts = BossKillCounts.add(null, "Vorkath", 10);
		counts = BossKillCounts.add(counts, "Vorkath", 10);
		counts = BossKillCounts.add(counts, "Vorkath", 9);
		counts = BossKillCounts.add(counts, "Vorkath", 0);
		counts = BossKillCounts.add(counts, "", 11);
		assertEquals(Collections.singletonList(new BossKillCount("Vorkath", 10, 10, 1)), counts);
	}

	@Test
	public void addDoesNotChangeTheGivenList()
	{
		List<BossKillCount> before = BossKillCounts.add(null, "Vorkath", 10);
		List<BossKillCount> copy = new ArrayList<>(before);
		BossKillCounts.add(before, "Vorkath", 11);
		BossKillCounts.add(before, "Zulrah", 1);
		assertEquals(copy, before);
	}

	@Test
	public void severalBossesInOrderFirstSeenAndBounded()
	{
		List<BossKillCount> counts = BossKillCounts.add(null, "Dagannoth Rex", 50);
		counts = BossKillCounts.add(counts, "Dagannoth Prime", 20);
		counts = BossKillCounts.add(counts, "Dagannoth Rex", 51);
		assertEquals(Arrays.asList(new BossKillCount("Dagannoth Rex", 50, 51, 2),
			new BossKillCount("Dagannoth Prime", 20, 20, 1)), counts);

		for (int i = 0; i < BossKillCounts.MAX_PER_TASK + 2; i++)
		{
			counts = BossKillCounts.add(counts, "Boss " + i, 1);
		}
		assertEquals(BossKillCounts.MAX_PER_TASK, counts.size());
		counts = BossKillCounts.add(counts, "Dagannoth Rex", 52);
		assertEquals("a listed boss still counts once full", 52, counts.get(0).getLastKc());
	}

	@Test
	public void sanitizeDropsBrokenEntries()
	{
		List<BossKillCount> stored = Arrays.asList(null, new BossKillCount(null, 1, 1, 1),
			new BossKillCount("Vorkath", 0, 5, 1), new BossKillCount("Vorkath", 6, 5, 1),
			new BossKillCount("Vorkath", 5, 6, 0), new BossKillCount("Vorkath", 5, 6, 2),
			new BossKillCount("VORKATH", 1, 9, 9));
		assertEquals(Collections.singletonList(new BossKillCount("Vorkath", 5, 6, 2)),
			BossKillCounts.sanitize(stored));
		assertTrue(BossKillCounts.sanitize(null).isEmpty());
	}

	@Test
	public void linesNameOnlyTheOtherBosses()
	{
		List<BossKillCount> counts = Arrays.asList(new BossKillCount("Vorkath", 141, 1152, 12));
		assertEquals(Collections.singletonList("Boss KC: 1,152 (+12)"), BossKillCounts.lines(counts, "vorkath"));
		assertEquals(Collections.singletonList("Vorkath KC: 1,152 (+12)"), BossKillCounts.lines(counts, null));
		assertEquals(Arrays.asList("Dagannoth Rex KC: 51 (+2)", "Dagannoth Prime KC: 20 (+1)"),
			BossKillCounts.lines(Arrays.asList(new BossKillCount("Dagannoth Rex", 50, 51, 2),
				new BossKillCount("Dagannoth Prime", 20, 20, 1)), "Dagannoth Kings"));
		assertTrue(BossKillCounts.lines(null, "Vorkath").isEmpty());
	}

	@Test
	public void tooltipIsEmptyWithoutCounts()
	{
		assertEquals("", LedgerHistory.bossKillCountTooltip(null, "Vorkath"));
	}

	@Test
	public void tooltipListsTheCountsEscaped()
	{
		assertEquals("<br>Kree'arra KC: 4 (+1)", LedgerHistory.bossKillCountTooltip(
			Collections.singletonList(new BossKillCount("Kree'arra", 4, 4, 1)), "General Graardor"));
		assertEquals("<br>A &amp; B KC: 1 (+1)", LedgerHistory.bossKillCountTooltip(
			Collections.singletonList(new BossKillCount("A & B", 1, 1, 1)), null));
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Cannon tasks: detection from the supplies used ({@link CannonTasks}), in the session and the saved record
 * (also records saved before supplies were tracked), the grouping name with and without a Catacombs variant, the
 * History estimate's selection, the Trends list and chart split and pooled, and the task advisor's cannon advice alone
 * and with the variant advice. {@link HarnessCannonTaskTest} covers the wiring.
 */
public class CannonTaskGroupingTest
{
	private static final long ACCOUNT = 555L;
	private static final int DUST_DEVILS = 49;
	private static final String DEVILS = "Dust devils";
	private static final int SPECTRES = 7;
	private static final String SPECTRE_TASK = "Aberrant spectres";
	private static final String DEVIANT = "Deviant spectres";
	private static final long HOUR = 60 * 60_000L;
	private static final long MINUTE = 60_000L;

	private long now = 1_000_000L;

	// ---- Detection ----

	@Test
	public void anyFiredCannonballRegularOrGraniteMakesACannonTask()
	{
		assertTrue(CannonTasks.fired(supplies(SupplyTracker.CANNONBALL, 1L)));
		assertTrue(CannonTasks.fired(supplies(SupplyTracker.GRANITE_CANNONBALL, 30L)));
		assertFalse("other supplies only", CannonTasks.fired(supplies(385, 12L)));
		assertFalse("none", CannonTasks.fired(Collections.<Integer, Long>emptyMap()));
		assertFalse("not tracked", CannonTasks.fired((Map<Integer, Long>) null));
		assertFalse("a zero left by a hand-edited file", CannonTasks.fired(supplies(SupplyTracker.CANNONBALL, 0L)));

		ItemTally live = new ItemTally();
		assertFalse(CannonTasks.fired(live));
		live.add(SupplyTracker.GRANITE_CANNONBALL, 2);
		assertTrue(CannonTasks.fired(live));
		assertFalse(CannonTasks.fired((ItemTally) null));
	}

	@Test
	public void recordsAreClassifiedFromTheirSuppliesAndOldOnesHaveNoCannon()
	{
		Gson gson = new Gson();
		LedgerRecord old = gson.fromJson("{\"schemaVersion\":2,\"id\":\"a\",\"monster\":\"Dust devils\","
			+ "\"creatureId\":49,\"kills\":10,\"activeMillis\":60000,\"completed\":true}", LedgerRecord.class);
		assertNull(old.getSupplies());
		assertFalse("saved before supplies were tracked", old.cannonTask());
		assertEquals(DEVILS, old.groupName());

		LedgerRecord withSupplies = gson.fromJson("{\"schemaVersion\":2,\"id\":\"b\",\"monster\":\"Dust devils\","
			+ "\"creatureId\":49,\"kills\":10,\"activeMillis\":60000,\"completed\":true,"
			+ "\"supplies\":{\"2\":120,\"385\":3}}", LedgerRecord.class);
		assertTrue(withSupplies.cannonTask());
		assertEquals("Dust devils (cannon)", withSupplies.groupName());
		// Nothing is stored for it.
		assertFalse(gson.toJson(withSupplies).contains("cannon"));
	}

	@Test
	public void theSessionNarrowsToCannonTasksOnceACannonballIsFired()
	{
		SessionTracker tracker = playing(DEVILS, DUST_DEVILS);
		assertSame("pooled before any cannonball", TaskSelection.ANY, tracker.getCurrentTaskSelection());

		// Loaded, then picked up again: they came back, so nothing was fired.
		assertTrue(tracker.addSupplies(tally(SupplyTracker.CANNONBALL, 30), null, null));
		assertTrue(tracker.addSupplies(null, tally(SupplyTracker.CANNONBALL, 30), null));
		assertSame(TaskSelection.ANY, tracker.getCurrentTaskSelection());

		assertTrue(tracker.addSupplies(tally(SupplyTracker.CANNONBALL, 2), null, null));
		assertEquals(TaskSelection.ANY.withCannon(true), tracker.getCurrentTaskSelection());
		assertEquals("Dust devils (cannon)", tracker.getCurrentTaskSelection().displayName(DEVILS));

		// Still a cannon task once paused; the saved record is named the same way.
		tracker.pause();
		assertEquals(TaskSelection.ANY.withCannon(true), tracker.getCurrentTaskSelection());
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertTrue(record.cannonTask());
		assertEquals("Dust devils (cannon)", record.groupName());
		assertSame("no session any more", TaskSelection.ANY, tracker.getCurrentTaskSelection());
	}

	@Test
	public void cannonAndCatacombsVariantCombine()
	{
		SessionTracker tracker = playing(SPECTRE_TASK, SPECTRES);
		assertTrue(tracker.addSupplies(tally(SupplyTracker.GRANITE_CANNONBALL, 5), null, null));
		assertEquals("no task kills yet: any version, cannon only", TaskSelection.ANY.withCannon(true),
			tracker.getCurrentTaskSelection());
		assertEquals("Aberrant spectres (cannon)", tracker.getCurrentTaskSelection().displayName(SPECTRE_TASK));

		assertTrue(tracker.addNpcKill("Deviant spectre"));
		now += MINUTE;
		tracker.observe(SPECTRE_TASK, SPECTRES, 49, 50, false);
		TaskSelection selection = tracker.getCurrentTaskSelection();
		assertEquals(TaskSelection.of(DEVIANT).withCannon(true), selection);
		assertEquals("Deviant spectres (cannon)", selection.displayName(SPECTRE_TASK));
		assertEquals(DEVIANT, tracker.getCurrentTaskSelection().getVariant());

		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(DEVIANT, record.getVariant());
		assertEquals("Deviant spectres (cannon)", record.groupName());
		assertEquals(DEVIANT, record.versionName());
	}

	// ---- Grouping ----

	@Test
	public void historyFilterTitlesAndTheChatLineUseTheCannonName()
	{
		LedgerRecord plain = record(DUST_DEVILS, DEVILS, null, false, 10, HOUR);
		LedgerRecord cannon = record(DUST_DEVILS, DEVILS, null, true, 10, HOUR);
		LedgerRecord both = record(SPECTRES, SPECTRE_TASK, DEVIANT, true, 10, HOUR);
		List<LedgerRecord> records = Arrays.asList(plain, cannon, both);

		assertEquals(Arrays.asList(LedgerHistory.ALL, DEVIANT + " (cannon)", DEVILS, DEVILS + " (cannon)"),
			LedgerHistory.filterOptions(records));
		assertEquals(Collections.singletonList(cannon), new HistoryFilter(DEVILS + " (cannon)", null, null).apply(records, r -> null));
		assertEquals(Collections.singletonList(plain), new HistoryFilter(DEVILS, null, null).apply(records, r -> null));
		assertEquals(DEVILS + " (cannon)", LedgerHistory.monster(cannon));

		String chat = TaskCompleteMessage.format(cannon, LootPriceMode.GE);
		assertTrue(chat, chat.startsWith("Slayer task complete: 10 Dust devils (cannon) · "));
		assertTrue(TaskCompleteMessage.format(plain, LootPriceMode.GE)
			.startsWith("Slayer task complete: 10 Dust devils · "));
	}

	@Test
	public void statisticsCountTheSelectedCannonUse()
	{
		List<LedgerRecord> records = Arrays.asList(
			record(DUST_DEVILS, DEVILS, null, false, 10, 10 * MINUTE),
			record(DUST_DEVILS, DEVILS, null, false, 10, 10 * MINUTE),
			record(DUST_DEVILS, DEVILS, null, true, 10, 5 * MINUTE));
		TaskStatistics pooled = devilStats(records, TaskSelection.ANY);
		assertEquals(3, pooled.getSampleCount());
		assertEquals(1, pooled.getCannonSampleCount());
		TaskStatistics cannon = devilStats(records, TaskSelection.ANY.withCannon(true));
		assertEquals(1, cannon.getSampleCount());
		assertEquals(Long.valueOf(30_000L), cannon.getMillisPerKill());
		assertEquals(2, devilStats(records, TaskSelection.ANY.withCannon(false)).getSampleCount());
		// The pooled overloads are unchanged.
		assertEquals(3, TaskStatistics.forTask(records, DUST_DEVILS, DEVILS, LootPriceMode.GE, Collections.emptyMap())
			.getSampleCount());
	}

	@Test
	public void statisticsSelectVariantAndCannonTogether()
	{
		List<LedgerRecord> records = Arrays.asList(
			record(SPECTRES, SPECTRE_TASK, null, false, 10, HOUR),
			record(SPECTRES, SPECTRE_TASK, null, true, 10, HOUR),
			record(SPECTRES, SPECTRE_TASK, DEVIANT, false, 10, HOUR),
			record(SPECTRES, SPECTRE_TASK, DEVIANT, true, 10, HOUR),
			record(SPECTRES, SPECTRE_TASK, DEVIANT, true, 10, HOUR));
		assertEquals(5, spectreStats(records, TaskSelection.ANY).getSampleCount());
		assertEquals(3, spectreStats(records, TaskSelection.ANY.withCannon(true)).getSampleCount());
		assertEquals(3, spectreStats(records, TaskSelection.of(DEVIANT)).getSampleCount());
		assertEquals(2, spectreStats(records, TaskSelection.of(DEVIANT).withCannon(true)).getSampleCount());
		assertEquals(1, spectreStats(records, TaskSelection.STANDARD.withCannon(true)).getSampleCount());
		assertEquals(1, spectreStats(records, TaskSelection.STANDARD.withCannon(false)).getSampleCount());
	}

	@Test
	public void aSelectionKeepsItsVariantOnlyForThatVariantsTask()
	{
		// The overlay reads the task and the selection in separate calls; a selection from another session's task
		// shows the task without that variant, keeping its cannon limit.
		TaskSelection deviant = TaskSelection.of(DEVIANT).withCannon(true);
		assertSame(deviant, deviant.forTask(SPECTRE_TASK));
		assertEquals(TaskSelection.ANY.withCannon(true), deviant.forTask(DEVILS));
		assertEquals(TaskSelection.ANY, TaskSelection.of("Mutated bloodveld").forTask(SPECTRE_TASK));
		assertEquals(TaskSelection.ANY, TaskSelection.of(DEVIANT).forTask(null));
		assertEquals(DEVILS + CannonTasks.SUFFIX, deviant.forTask(DEVILS).displayName(DEVILS));

		// Without a variant there is nothing to guard.
		assertSame(TaskSelection.STANDARD, TaskSelection.STANDARD.forTask(DEVILS));
		assertSame(TaskSelection.ANY, TaskSelection.ANY.forTask(SPECTRE_TASK));
		TaskSelection cannon = TaskSelection.ANY.withCannon(true);
		assertSame(cannon, cannon.forTask(null));
	}

	@Test
	public void selectionsCompareByValueAndKeyTheCannon()
	{
		assertSame(TaskSelection.ANY, TaskSelection.ANY.withCannon(null));
		assertSame(TaskSelection.ANY, TaskSelection.ANY.withCannon(true).withCannon(null));
		assertSame(TaskSelection.STANDARD, TaskSelection.STANDARD.withCannon(false).withCannon(null));
		assertNotEquals(TaskSelection.ANY, TaskSelection.ANY.withCannon(true));
		assertNotEquals(TaskSelection.ANY.withCannon(true), TaskSelection.ANY.withCannon(false));
		assertNotEquals(TaskSelection.ANY.withCannon(true).key(), TaskSelection.STANDARD.withCannon(true).key());
		assertEquals(TaskSelection.of("Deviant spectres").withCannon(true),
			TaskSelection.of("deviant SPECTRES").withCannon(true));
		assertEquals(TaskSelection.ANY.withCannon(true), TaskSelection.of(DEVIANT).withCannon(true).withAnyVariant());
		assertTrue(TaskSelection.ANY.withCannon(true).isAnyVariant());
		assertNull(TaskSelection.ANY.withCannon(true).getVariant());

		assertEquals(DEVILS, TaskSelection.ANY.displayName(DEVILS));
		assertEquals("without a cannon limit nothing is added", DEVILS,
			TaskSelection.ANY.withCannon(false).displayName(DEVILS));
		assertEquals(DEVIANT, TaskSelection.of(DEVIANT).displayName(SPECTRE_TASK));
	}

	@Test
	public void trendsSplitCannonTasksAndTheAdvisorRankingPoolsThem()
	{
		List<LedgerRecord> records = new ArrayList<>();
		records.add(profit(DUST_DEVILS, DEVILS, null, false, 100_000L));
		records.add(profit(DUST_DEVILS, DEVILS, null, true, 300_000L));
		records.add(profit(DUST_DEVILS, DEVILS, null, true, 300_000L));
		records.add(profit(SPECTRES, SPECTRE_TASK, DEVIANT, true, 200_000L));

		List<TaskRanking.Entry> split = TaskRanking.rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE, null);
		assertEquals(Arrays.asList(DEVILS + " (cannon)", DEVIANT + " (cannon)", DEVILS), names(split));
		assertEquals(2, split.get(0).getSampleCount());

		List<TaskRanking.Entry> pooled = TaskRanking.rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE, null,
			HiddenLoot.NONE, TaskRanking.Split.NONE);
		assertEquals(Arrays.asList(DEVILS, SPECTRE_TASK), names(pooled));
		assertEquals(3, pooled.get(0).getSampleCount());

		List<TaskRanking.Entry> byCannon = TaskRanking.rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			null, HiddenLoot.NONE, TaskRanking.Split.CANNON);
		assertEquals(Arrays.asList(DEVILS + " (cannon)", SPECTRE_TASK + " (cannon)", DEVILS), names(byCannon));

		List<TaskChart.Monster> monsters = TaskChart.monsters(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			null);
		List<String> labels = new ArrayList<>();
		for (TaskChart.Monster monster : monsters)
		{
			labels.add(monster.getLabel());
		}
		assertTrue(labels.toString(), labels.contains(DEVILS + " (cannon)"));
		assertTrue(labels.toString(), labels.contains(DEVILS));
		assertTrue(labels.toString(), labels.contains(DEVIANT + " (cannon)"));
		TaskChart.Monster cannonDevils = monsters.get(labels.indexOf(DEVILS + " (cannon)"));
		assertEquals(2, TaskChart.points(records, cannonDevils, TaskRanking.Metric.PROFIT, LootPriceMode.GE, null)
			.size());
	}

	// ---- Task advisor ----

	@Test
	public void theAdvisorSaysWhetherTheCannonWasWorthItWithEnoughHistoryOfBoth()
	{
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			records.add(profit(DUST_DEVILS, DEVILS, null, false, 300_000L));
			records.add(profit(DUST_DEVILS, DEVILS, null, true, 450_000L));
		}
		TaskAdvisor.VersionAdvice advice = adviseCannon(records);
		assertNotNull(advice);
		assertEquals(TaskAdvisor.WITH_CANNON, advice.getLabel());
		assertEquals("Better: with cannon", TaskAdvisor.betterText(null, advice));
		assertEquals("Profit (GE)/h: Dust devils (cannon) 450K (n=3), Dust devils 300K (n=3)",
			advice.reason(LootPriceMode.GE));

		// The other way round.
		for (LedgerRecord record : records)
		{
			record.setLootGeValue(record.cannonTask() ? 100_000L : 500_000L);
		}
		assertEquals(TaskAdvisor.WITHOUT_CANNON, adviseCannon(records).getLabel());

		// Equal rates: no cannon advice.
		for (LedgerRecord record : records)
		{
			record.setLootGeValue(300_000L);
		}
		assertNull(adviseCannon(records));
	}

	@Test
	public void theAdvisorGivesNoCannonAdviceWithoutEnoughHistoryOfEither()
	{
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			records.add(profit(DUST_DEVILS, DEVILS, null, false, 300_000L));
		}
		records.add(profit(DUST_DEVILS, DEVILS, null, true, 450_000L));
		records.add(profit(DUST_DEVILS, DEVILS, null, true, 450_000L));
		assertNull("2 cannon tasks", adviseCannon(records));

		// Three cannon tasks, but under 30 minutes of them.
		List<LedgerRecord> quick = new ArrayList<>(records.subList(0, TaskAdvisor.MIN_TASKS));
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			LedgerRecord record = profit(DUST_DEVILS, DEVILS, null, true, 450_000L);
			record.setActiveMillis(5 * MINUTE);
			quick.add(record);
		}
		assertNull("15 minutes of cannon tasks", adviseCannon(quick));

		// No cannon history at all, or none for this task.
		assertNull(adviseCannon(records.subList(0, TaskAdvisor.MIN_TASKS)));
		assertNull(TaskAdvisor.adviseCannon(records, 42, "Abyssal demons", TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HiddenLoot.NONE));
		assertNull(TaskAdvisor.betterText(null, null));
	}

	@Test
	public void cannonAndVariantAdviceAreComparedApartAndShownInOneLine()
	{
		// Deviant spectres beat Aberrant spectres either way; the cannon loses for both versions.
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			records.add(profit(SPECTRES, SPECTRE_TASK, null, false, 300_000L));
			records.add(profit(SPECTRES, SPECTRE_TASK, null, true, 200_000L));
			records.add(profit(SPECTRES, SPECTRE_TASK, DEVIANT, false, 500_000L));
			records.add(profit(SPECTRES, SPECTRE_TASK, DEVIANT, true, 400_000L));
		}
		TaskAdvisor.Outcome outcome = TaskAdvisor.adviseAll(records, SPECTRES, SPECTRE_TASK,
			TaskRanking.Metric.PROFIT, LootPriceMode.GE, null, HiddenLoot.NONE);
		assertNull("one monster only: no main advice", outcome.getAdvice());

		TaskAdvisor.VersionAdvice variant = outcome.getVariant();
		assertNotNull(variant);
		// The variant advice pools cannon use: 3 + 3 tasks of each version.
		assertEquals("Profit (GE)/h: Deviant spectres 450K (n=6), Aberrant spectres 250K (n=6)",
			variant.reason(LootPriceMode.GE));
		TaskAdvisor.VersionAdvice cannon = outcome.getCannon();
		assertNotNull(cannon);
		// The cannon advice pools the versions, and says so.
		assertEquals("Profit (GE)/h: Aberrant spectres, any version, without cannon 400K (n=6), Aberrant spectres,"
			+ " any version, with cannon 300K (n=6)", cannon.reason(LootPriceMode.GE));
		assertEquals("Better: Deviant spectres, without cannon", TaskAdvisor.betterText(variant, cannon));
		assertEquals("Better: Deviant spectres", TaskAdvisor.betterText(variant, null));
		assertEquals("Better: without cannon", TaskAdvisor.betterText(null, cannon));
	}

	@Test
	public void theMainAdvicePoolsCannonTasks()
	{
		// Six monsters of 3 tasks each; the dust devils' tasks are split 2 + 1 by cannon use.
		List<LedgerRecord> records = new ArrayList<>();
		for (int creature = 1; creature <= 5; creature++)
		{
			for (int task = 0; task < TaskAdvisor.MIN_TASKS; task++)
			{
				records.add(profit(100 + creature, "Monster " + creature, null, false, (creature + 1) * 100_000L));
			}
		}
		records.add(profit(DUST_DEVILS, DEVILS, null, false, 50_000L));
		records.add(profit(DUST_DEVILS, DEVILS, null, false, 50_000L));
		records.add(profit(DUST_DEVILS, DEVILS, null, true, 50_000L));
		TaskAdvisor.Outcome outcome = TaskAdvisor.adviseAll(records, DUST_DEVILS, DEVILS, TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HiddenLoot.NONE);
		assertNotNull("pooled, the dust devils have 3 tasks and qualify", outcome.getAdvice());
		assertEquals(3, outcome.getAdvice().getTasks());
		assertEquals(TaskAdvisor.Advice.CONSIDER_SKIP, outcome.getAdvice().getAdvice());
		assertNull("too few of each", outcome.getCannon());
		assertNull("no Catacombs variant", outcome.getVariant());
	}

	// ---- History estimate and overlay text ----

	@Test
	public void afterACannonballTheEstimateUsesCannonTasksOnlyWhenThereAreSome()
	{
		TaskSelection cannon = TaskSelection.ANY.withCannon(true);
		List<LedgerRecord> plain = Arrays.asList(record(DUST_DEVILS, DEVILS, null, false, 10, HOUR),
			record(DUST_DEVILS, DEVILS, null, false, 20, HOUR));
		assertSame("no cannon tasks: pooled, as before the cannonball", TaskSelection.ANY,
			TaskStatistics.effectiveSelection(plain, DUST_DEVILS, DEVILS, cannon));
		assertEquals(2, devilStats(plain, TaskStatistics.effectiveSelection(plain, DUST_DEVILS, DEVILS, cannon))
			.getSampleCount());

		List<LedgerRecord> mixed = new ArrayList<>(plain);
		mixed.add(record(DUST_DEVILS, DEVILS, null, true, 10, HOUR));
		assertEquals("one cannon task: cannon tasks only", cannon,
			TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, cannon));
		assertEquals(1, devilStats(mixed, TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, cannon))
			.getSampleCount());

		// Another task's cannon tasks, or an unfinished one, don't count.
		List<LedgerRecord> others = new ArrayList<>(plain);
		others.add(record(SPECTRES, SPECTRE_TASK, null, true, 10, HOUR));
		LedgerRecord partial = record(DUST_DEVILS, DEVILS, null, true, 10, HOUR);
		partial.setCompleted(false);
		others.add(partial);
		assertSame(TaskSelection.ANY, TaskStatistics.effectiveSelection(others, DUST_DEVILS, DEVILS, cannon));

		// Without a cannonball the selection stays, whatever the history.
		assertSame(TaskSelection.ANY, TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, TaskSelection.ANY));
		assertSame(TaskSelection.ANY, TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, null));

		// The version stays: a Deviant spectres cannon task needs a Deviant spectres one in the history.
		TaskSelection deviantCannon = TaskSelection.of(DEVIANT).withCannon(true);
		List<LedgerRecord> spectres = Arrays.asList(record(SPECTRES, SPECTRE_TASK, null, true, 10, HOUR),
			record(SPECTRES, SPECTRE_TASK, DEVIANT, false, 10, HOUR));
		assertEquals(TaskSelection.of(DEVIANT),
			TaskStatistics.effectiveSelection(spectres, SPECTRES, SPECTRE_TASK, deviantCannon));
		assertEquals(TaskSelection.ANY.withCannon(true), TaskStatistics.effectiveSelection(spectres, SPECTRES,
			SPECTRE_TASK, TaskSelection.ANY.withCannon(true)));
	}

	@Test
	public void theEstimateSaysWhichCannonUseItCounts()
	{
		List<LedgerRecord> records = Arrays.asList(record(DUST_DEVILS, DEVILS, null, false, 10, HOUR),
			record(DUST_DEVILS, DEVILS, null, true, 10, HOUR));
		TaskSelection cannon = TaskSelection.ANY.withCannon(true);
		TaskStatistics pooled = devilStats(records, TaskSelection.ANY);
		assertEquals("Counts cannon tasks too, until you fire a cannonball.",
			HistoryEstimateSection.selectionNote(DEVILS, TaskSelection.ANY, TaskSelection.ANY, pooled));
		assertEquals("Only your cannon tasks count.", HistoryEstimateSection.selectionNote(DEVILS, cannon, cannon,
			devilStats(records, cannon)));
		assertNull("no cannon history: nothing to say", HistoryEstimateSection.selectionNote(DEVILS,
			TaskSelection.ANY, TaskSelection.ANY, devilStats(records.subList(0, 1), TaskSelection.ANY)));
		assertEquals("a cannonball fired, but no cannon tasks yet", HistoryEstimateSection.NO_CANNON_TASKS_NOTE,
			HistoryEstimateSection.selectionNote(DEVILS, cannon, TaskSelection.ANY,
				devilStats(records.subList(0, 1), TaskSelection.ANY)));
		assertEquals("No cannon tasks yet, so tasks without a cannon count too.",
			HistoryEstimateSection.NO_CANNON_TASKS_NOTE);
		TaskSelection deviantCannon = TaskSelection.of(DEVIANT).withCannon(true);
		assertEquals("Only your Deviant spectres tasks count. Only your cannon tasks count.",
			HistoryEstimateSection.selectionNote(SPECTRE_TASK, deviantCannon, deviantCannon, null));
		assertEquals("Only your Deviant spectres tasks count. " + HistoryEstimateSection.NO_CANNON_TASKS_NOTE,
			HistoryEstimateSection.selectionNote(SPECTRE_TASK, deviantCannon, TaskSelection.of(DEVIANT), null));
		assertEquals("Counts Deviant spectres tasks too, until your kills show which you are doing. Only your cannon"
				+ " tasks count.",
			HistoryEstimateSection.selectionNote(SPECTRE_TASK, cannon, cannon, null));
	}

	@Test
	public void theOverlayNamesTheTaskAsTheTaskBoxDoes()
	{
		SessionTracker.LiveTask task = new SessionTracker.LiveTask(SessionTracker.State.RUNNING, "session", DEVILS,
			DUST_DEVILS, 3, 60_000L, 20);
		assertEquals(DEVILS, new OverlayRows.Data(task, null, null, null).getTaskName());
		assertEquals(DEVILS, new OverlayRows.Data(task, null, null, TaskSelection.ANY).getTaskName());
		assertEquals(DEVILS + " (cannon)",
			new OverlayRows.Data(task, null, null, TaskSelection.ANY.withCannon(true)).getTaskName());
