	// ---- Helpers ----

	/** A running task of 50 just started, without task kills. */
	private SessionTracker playing(String monster, int creatureId)
	{
		SessionTracker tracker = new SessionTracker(() -> now);
		tracker.observe(monster, creatureId, 50, 50, false);
		assertTrue(tracker.play(ACCOUNT));
		return tracker;
	}

	private static ItemTally tally(int id, long quantity)
	{
		ItemTally tally = new ItemTally();
		tally.add(id, quantity);
		return tally;
	}

	private static Map<Integer, Long> supplies(int id, long quantity)
	{
		Map<Integer, Long> supplies = new HashMap<>();
		supplies.put(id, quantity);
		return supplies;
	}

	private static List<String> names(List<TaskRanking.Entry> ranking)
	{
		List<String> names = new ArrayList<>();
		for (TaskRanking.Entry entry : ranking)
		{
			names.add(entry.getMonster());
		}
		return names;
	}

	private static TaskAdvisor.VersionAdvice adviseCannon(List<LedgerRecord> records)
	{
		return TaskAdvisor.adviseCannon(records, DUST_DEVILS, DEVILS, TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			null, HiddenLoot.NONE);
	}

	private static TaskStatistics devilStats(List<LedgerRecord> records, TaskSelection selection)
	{
		return TaskStatistics.forTask(records, DUST_DEVILS, DEVILS, selection, null, null, LootPriceMode.GE,
			Collections.emptyMap(), HiddenLoot.NONE);
	}

	private static TaskStatistics spectreStats(List<LedgerRecord> records, TaskSelection selection)
	{
		return TaskStatistics.forTask(records, SPECTRES, SPECTRE_TASK, selection, null, null, LootPriceMode.GE,
			Collections.emptyMap(), HiddenLoot.NONE);
	}

	/** An hour-long completed task making {@code profit} (loot at GE, supplies valued at 0). */
	private static LedgerRecord profit(int creatureId, String monster, String variant, boolean cannon, long profit)
	{
		LedgerRecord record = record(creatureId, monster, variant, cannon, 10, HOUR);
		record.setLootGeValue(profit);
		record.setSuppliesGeValue(0L);
		return record;
	}

	/** A completed task; a cannon task fired 50 cannonballs. */
	private static LedgerRecord record(int creatureId, String monster, String variant, boolean cannon, int kills,
		long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(java.util.UUID.randomUUID().toString());
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setVariant(variant);
		record.setSupplies(cannon ? supplies(SupplyTracker.CANNONBALL, 50L) : null);
		record.setKills(kills);
		record.setInitialAmount(kills);
		record.setOriginalAmount(kills);
		record.setActiveMillis(activeMillis);
		record.setEndedAt(500_000L);
		record.setCompleted(true);
		return record;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Catacombs variant tasks in the session, the saved record and every per-monster grouping: the History estimate
 * statistics, the Trends list and chart, the history list and its Monster filter, the task advisor (pooled) and its
 * variant advice. Records saved before variants were tracked have no variant and stay standard.
 */
public class CatacombsVariantGroupingTest
{
	private static final long ACCOUNT = 555L;
	private static final int SPECTRES = 7;
	private static final String TASK = "Aberrant spectres";
	private static final String DEVIANT = "Deviant spectres";
	private static final long HOUR = 60 * 60_000L;
	private static final long MINUTE = 60_000L;

	private long now = 1_000_000L;

	// ---- Session and saved record ----

	@Test
	public void killsWhileRunningDecideTheSavedRecordsVariant()
	{
		// 10 task kills: 6 Deviant spectres, 4 Aberrant spectres, and Ankous on the way that don't count.
		SessionTracker tracker = runningSpectreTask();
		for (int i = 0; i < 6; i++)
		{
			assertTrue(tracker.addNpcKill("Deviant spectre"));
		}
		for (int i = 0; i < 4; i++)
		{
			assertTrue(tracker.addNpcKill("Aberrant spectre"));
		}
		for (int i = 0; i < 8; i++)
		{
			assertTrue(tracker.addNpcKill("Ankou"));
		}
		assertFalse(tracker.addNpcKill(null));
		assertEquals(DEVIANT, tracker.getCurrentTaskSelection().getVariant());
		assertEquals(TaskSelection.of(DEVIANT), tracker.getCurrentTaskSelection());

		// Paused: not tallied, but the decision stands.
		assertTrue(tracker.pause());
		assertFalse(tracker.addNpcKill("Aberrant spectre"));
		assertFalse(tracker.addNpcKill("Aberrant spectre"));
		assertEquals(DEVIANT, tracker.getCurrentTaskSelection().getVariant());

		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(DEVIANT, record.getVariant());
		assertEquals(TASK, record.getMonster());
		assertEquals(DEVIANT, record.groupName());
		assertEquals(DEVIANT, LedgerHistory.monster(record));
		assertNull("no session any more", tracker.getCurrentTaskSelection().getVariant());
		assertSame(TaskSelection.ANY, tracker.getCurrentTaskSelection());
	}

	@Test
	public void theLiveSelectionWaitsForTheFirstTaskKillAndATieIsStandard()
	{
		SessionTracker tracker = playingSpectreTask();
		assertNull(tracker.getCurrentTaskSelection().getVariant());
		assertSame("no task kills yet: both versions pooled", TaskSelection.ANY, tracker.getCurrentTaskSelection());
		assertNull(LedgerRecord.fromSummary(tracker.activeSummary(), true).getVariant());

		// An unrelated kill first (for example an Ankou on the way) changes nothing.
		tracker.addNpcKill("Ankou");
		assertSame(TaskSelection.ANY, tracker.getCurrentTaskSelection());
		// A variant kill counts once the task counter has counted it.
		tracker.addNpcKill("Deviant spectre");
		assertSame(TaskSelection.ANY, tracker.getCurrentTaskSelection());
		killTask(tracker);
		assertEquals(DEVIANT, tracker.getCurrentTaskSelection().getVariant());
		assertEquals(TaskSelection.of(DEVIANT), tracker.getCurrentTaskSelection());
		assertEquals(DEVIANT, LedgerRecord.fromSummary(tracker.activeSummary(), true).getVariant());

		tracker.addNpcKill("Aberrant spectre");
		killTask(tracker);
		assertNull("a tie is standard", tracker.getCurrentTaskSelection().getVariant());
		assertSame(TaskSelection.STANDARD, tracker.getCurrentTaskSelection());
		assertNull(LedgerRecord.fromSummary(tracker.stopAndReset(), true).getVariant());
	}

	@Test
	public void deathSpawnsAndOtherBarragedNpcsDontMakeItStandard()
	{
		// A Greater nechryael task: each Greater Nechryael kill also kills its death spawns, which count for nothing.
		SessionTracker tracker = new SessionTracker(() -> now);
		tracker.observe("Nechryael", 52, 20, 20, false);
		assertTrue(tracker.play(ACCOUNT));
		for (int i = 1; i <= 5; i++)
		{
			tracker.addNpcKill("Greater Nechryael");
			tracker.addNpcKill("Death spawn");
			tracker.addNpcKill("Death spawn");
			tracker.addNpcKill("Death spawn");
			now += MINUTE;
			tracker.observe("Nechryael", 52, 20 - i, 20, false);
			assertEquals("Greater nechryael", tracker.getCurrentTaskSelection().getVariant());
		}
		assertEquals("Greater nechryael", LedgerRecord.fromSummary(tracker.stopAndReset(), true).getVariant());
	}

	@Test
	public void theTallySurvivesTheActiveSessionFile()
	{
		Gson gson = new Gson();
		SessionTracker tracker = runningSpectreTask();
		for (int i = 0; i < 6; i++)
		{
			tracker.addNpcKill("Deviant spectre");
		}
		tracker.autoPause();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), null, now);
		String json = gson.toJson(snapshot);
		String tally = ",\"npcKills\":[{\"name\":\"Deviant spectre\",\"kills\":6}]";
		assertTrue(json, json.contains(tally));

		// Restored, the same 6 variant kills of 10 task kills decide it, live and on save.
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe(TASK, SPECTRES, 40, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED,
			restored.restore(gson.fromJson(json, SessionSnapshot.class), null));
		assertEquals(10, restored.getKills());
		assertEquals(DEVIANT, restored.getCurrentTaskSelection().getVariant());
		assertEquals(TaskSelection.of(DEVIANT), restored.getCurrentTaskSelection());
		assertEquals(DEVIANT, LedgerRecord.fromSummary(restored.activeSummary(), true).getVariant());
		// A snapshot that can't be restored becomes a partial record with its variant.
		assertEquals(DEVIANT, LedgerRecord.fromSummary(gson.fromJson(json, SessionSnapshot.class).toSummary(), true)
			.getVariant());

		// Fewer variant kills than half of the restored task kills: standard, live and on save.
		SessionTracker half = new SessionTracker(() -> now);
		half.observe(TASK, SPECTRES, 40, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED,
			half.restore(gson.fromJson(json.replace("\"kills\":6}", "\"kills\":5}"), SessionSnapshot.class), null));
		assertNull(half.getCurrentTaskSelection().getVariant());
		assertSame(TaskSelection.STANDARD, half.getCurrentTaskSelection());
		assertNull(LedgerRecord.fromSummary(half.activeSummary(), true).getVariant());

		// An older file has no tally and restores without one.
		SessionSnapshot old = gson.fromJson(json.replace(tally, ""), SessionSnapshot.class);
		assertNull(old.getNpcKills());
		SessionTracker fromOld = new SessionTracker(() -> now);
		fromOld.observe(TASK, SPECTRES, 40, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, fromOld.restore(old, null));
		assertTrue(fromOld.getNpcKills().isEmpty());
		assertNull(fromOld.getCurrentTaskSelection().getVariant());
	}

	@Test
	public void recordsWithoutTheFieldLoadAsStandard()
	{
		Gson gson = new Gson();
		LedgerRecord old = gson.fromJson("{\"schemaVersion\":2,\"id\":\"a\",\"monster\":\"Aberrant spectres\","
			+ "\"creatureId\":7,\"kills\":10,\"activeMillis\":60000,\"completed\":true}", LedgerRecord.class);
		assertNull(old.getVariant());
		assertEquals(TASK, old.groupName());
		assertTrue(TaskSelection.STANDARD.matches(old));
		// Written back without the field, and a variant record with it.
		assertFalse(gson.toJson(old).contains("variant"));
		old.setVariant(DEVIANT);
		assertTrue(gson.toJson(old).contains("\"variant\":\"Deviant spectres\""));
	}

	// ---- Grouping ----

	@Test
	public void statisticsCountTheSelectedVersion()
	{
		List<LedgerRecord> records = Arrays.asList(record(null, 10, 10 * MINUTE), record(null, 10, 10 * MINUTE),
			record(DEVIANT, 10, 20 * MINUTE));
		assertEquals(3, stats(records, TaskSelection.ANY).getSampleCount());
		assertEquals(2, stats(records, TaskSelection.STANDARD).getSampleCount());
		TaskStatistics deviant = stats(records, TaskSelection.of(DEVIANT));
		assertEquals(1, deviant.getSampleCount());
		assertEquals(Long.valueOf(2 * MINUTE), deviant.getMillisPerKill());
		// The pooled overloads are unchanged.
		assertEquals(3, TaskStatistics.forTask(records, SPECTRES, TASK, LootPriceMode.GE, Collections.emptyMap())
			.getSampleCount());
	}

	@Test
	public void trendsListAndChartShowAVariantAsItsOwnMonster()
	{
		List<LedgerRecord> records = new ArrayList<>();
		records.add(profit(null, 100_000L));
		records.add(profit(DEVIANT, 400_000L));
		records.add(profit(DEVIANT, 400_000L));

		List<TaskRanking.Entry> ranking = TaskRanking.rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE, null);
		assertEquals(2, ranking.size());
		assertEquals(DEVIANT, ranking.get(0).getMonster());
		assertEquals(2, ranking.get(0).getSampleCount());
		assertEquals(Long.valueOf(400_000L), ranking.get(0).getRatePerHour());
		assertEquals(TASK, ranking.get(1).getMonster());
		assertEquals(1, ranking.get(1).getSampleCount());

		// The advisor's ranking pools the two, as before.
		List<TaskRanking.Entry> pooled = TaskRanking.rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE, null,
			HiddenLoot.NONE, TaskRanking.Split.NONE);
		assertEquals(1, pooled.size());
		assertEquals(TASK, pooled.get(0).getMonster());
		assertEquals(3, pooled.get(0).getSampleCount());

		List<TaskChart.Monster> monsters = TaskChart.monsters(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			null);
		assertEquals(Arrays.asList(TASK, DEVIANT), Arrays.asList(monsters.get(0).getLabel(),
			monsters.get(1).getLabel()));
		assertEquals(2, TaskChart.points(records, monsters.get(1), TaskRanking.Metric.PROFIT, LootPriceMode.GE, null)
			.size());
	}

	@Test
	public void theHistoryFilterListsTheVariantSeparately()
	{
		List<LedgerRecord> records = Arrays.asList(record(null, 10, HOUR), record(DEVIANT, 10, HOUR));
		assertEquals(Arrays.asList(LedgerHistory.ALL, TASK, DEVIANT), LedgerHistory.filterOptions(records));
		assertEquals(1, new HistoryFilter(DEVIANT, null, null).apply(records, r -> null).size());
		assertEquals(1, new HistoryFilter(TASK, null, null).apply(records, r -> null).size());
		assertTrue(LedgerHistory.rowTooltip(records.get(1), HistoryPricing.value(records.get(1), LootPriceMode.GE,
			Collections.emptyMap()), null).contains("Catacombs variant of Aberrant spectres"));
		assertFalse(LedgerHistory.rowTooltip(records.get(0), HistoryPricing.value(records.get(0), LootPriceMode.GE,
			Collections.emptyMap()), null).contains("Catacombs variant"));
	}

	// ---- Task advisor ----

	@Test
	public void theAdvisorSaysWhichVersionIsBetterWithEnoughHistoryOfBoth()
	{
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			records.add(profit(null, 300_000L));
			records.add(profit(DEVIANT, 450_000L));
		}
		TaskAdvisor.VersionAdvice advice = adviseVariant(records);
		assertNotNull(advice);
		assertEquals(DEVIANT, advice.getLabel());
		assertEquals("Better: Deviant spectres", TaskAdvisor.betterText(advice, null));
		assertEquals("Profit (GE)/h: Deviant spectres 450K (n=3), Aberrant spectres 300K (n=3)",
			advice.reason(LootPriceMode.GE));

		// The other way round.
		for (LedgerRecord record : records)
		{
			record.setLootGeValue(record.getVariant() == null ? 500_000L : 200_000L);
		}
		assertEquals(TASK, adviseVariant(records).getLabel());

		// Equal rates: no variant advice.
		for (LedgerRecord record : records)
		{
			record.setLootGeValue(300_000L);
		}
		assertNull(adviseVariant(records));
	}

	@Test
	public void theAdvisorGivesNoVariantAdviceWithoutEnoughHistoryOfEither()
	{
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			records.add(profit(null, 300_000L));
		}
		records.add(profit(DEVIANT, 450_000L));
		records.add(profit(DEVIANT, 450_000L));
		assertNull("2 variant tasks", adviseVariant(records));

		// Three variant tasks, but under 30 minutes of them.
		List<LedgerRecord> short3 = new ArrayList<>(records.subList(0, TaskAdvisor.MIN_TASKS));
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			LedgerRecord quick = profit(DEVIANT, 450_000L);
			quick.setActiveMillis(5 * MINUTE);
			short3.add(quick);
		}
		assertNull("15 minutes of variant tasks", adviseVariant(short3));

		// No variant for the task, or no variant history at all.
		assertNull(adviseVariant(records.subList(0, TaskAdvisor.MIN_TASKS)));
		assertNull(TaskAdvisor.adviseVariant(records, 42, "Abyssal demons", TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HiddenLoot.NONE));
	}

	@Test
	public void theMainAdvicePoolsBothVersions()
	{
		// Six monsters of 3 tasks each; the spectres' tasks are split 2 + 1 between the versions.
		List<LedgerRecord> records = new ArrayList<>();
		for (int creature = 1; creature <= 5; creature++)
		{
			for (int task = 0; task < TaskAdvisor.MIN_TASKS; task++)
			{
				LedgerRecord other = profit(null, (creature + 1) * 100_000L);
				other.setCreatureId(100 + creature);
				other.setMonster("Monster " + creature);
				records.add(other);
			}
		}
		records.add(profit(null, 50_000L));
		records.add(profit(null, 50_000L));
		records.add(profit(DEVIANT, 50_000L));
		TaskAdvisor.Outcome outcome = TaskAdvisor.adviseAll(records, SPECTRES, TASK, TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HiddenLoot.NONE);
		assertNotNull("pooled, the spectres have 3 tasks and qualify", outcome.getAdvice());
		assertEquals(3, outcome.getAdvice().getTasks());
		assertEquals(TaskAdvisor.Advice.CONSIDER_SKIP, outcome.getAdvice().getAdvice());
		assertNull("too few of each version", outcome.getVariant());
	}

	// ---- Helpers ----

	/** A running spectres task of 50 with 10 task kills so far. */
	private SessionTracker runningSpectreTask()
	{
		SessionTracker tracker = playingSpectreTask();
		now += 60_000;
		tracker.observe(TASK, SPECTRES, 40, 50, false);
		return tracker;
	}

	/** A spectres task of 50 just started, without task kills. */
	private SessionTracker playingSpectreTask()
	{
		SessionTracker tracker = new SessionTracker(() -> now);
		tracker.observe(TASK, SPECTRES, 50, 50, false);
		assertTrue(tracker.play(ACCOUNT));
		return tracker;
	}

	/** The task counter counts one more kill of the running spectres task. */
	private void killTask(SessionTracker tracker)
	{
		now += MINUTE;
		tracker.observe(TASK, SPECTRES, tracker.getCurrentRemaining() - 1, 50, false);
	}

	private static TaskAdvisor.VersionAdvice adviseVariant(List<LedgerRecord> records)
	{
		return TaskAdvisor.adviseVariant(records, SPECTRES, TASK, TaskRanking.Metric.PROFIT, LootPriceMode.GE, null,
			HiddenLoot.NONE);
	}

	private static TaskStatistics stats(List<LedgerRecord> records, TaskSelection variant)
	{
		return TaskStatistics.forTask(records, SPECTRES, TASK, variant, null, null, LootPriceMode.GE,
			Collections.emptyMap(), HiddenLoot.NONE);
	}

	/** An hour-long completed spectres task making {@code profit} (loot at GE, no supplies). */
	private static LedgerRecord profit(String variant, long profit)
	{
		LedgerRecord record = record(variant, 10, HOUR);
		record.setLootGeValue(profit);
		record.setSuppliesGeValue(0L);
		return record;
	}

	private static LedgerRecord record(String variant, int kills, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(java.util.UUID.randomUUID().toString());
		record.setCreatureId(SPECTRES);
		record.setMonster(TASK);
		record.setVariant(variant);
		record.setKills(kills);
		record.setInitialAmount(kills);
		record.setOriginalAmount(kills);
		record.setActiveMillis(activeMillis);
		record.setEndedAt(1_700_000_000_000L + activeMillis);
		record.setCompleted(true);
		return record;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.NpcID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The Catacombs variant table, the kills per NPC name and the majority rule: {@link CatacombsVariants},
 * {@link NpcKillTally}, {@link DamagedNpcs} and {@link TaskSelection}.
 */
public class CatacombsVariantsTest
{
	@Test
	public void theTableHasTheCatacombsNpcIdsAndNames()
	{
		// The ids and names of the RuneLite 1.13.4 gameval NpcID constants (their javadoc gives the NPC's name).
		assertVariant("Aberrant spectres", NpcID.KOUREND_SPECTRE, 7279, "Deviant spectre", "Deviant spectres");
		assertVariant("Nechryael", NpcID.KOUREND_NECHRYAEL, 7278, "Greater Nechryael", "Greater nechryael");
		assertVariant("Bloodveld", NpcID.KOUREND_BLOODVELD, 7276, "Mutated Bloodveld", "Mutated bloodveld");
		assertVariant("Jellies", NpcID.KOUREND_JELLY, 7277, "Warped Jelly", "Warped jellies");
		assertVariant("Banshees", NpcID.KOUREND_BANSHEE, 7272, "Twisted Banshee", "Twisted banshees");
		assertVariant("Black dragons", NpcID.KOUREND_BLACK_DRAGON, 7275, "Brutal black dragon", "Brutal black dragons");
		assertVariant("Blue dragons", NpcID.KOUREND_BLUE_DRAGON, 7273, "Brutal blue dragon", "Brutal blue dragons");
		assertVariant("Red dragons", NpcID.KOUREND_RED_DRAGON, 7274, "Brutal red dragon", "Brutal red dragons");
		assertEquals(8, CatacombsVariants.all().size());
	}

	@Test
	public void tasksMatchByTheOneNameKeyAndOthersHaveNoVariant()
	{
		assertEquals("Deviant spectres", CatacombsVariants.forTask("  ABERRANT spectres ").getName());
		assertNull(CatacombsVariants.forTask("Abyssal demons"));
		assertNull(CatacombsVariants.forTask("Green dragons"));
		assertNull(CatacombsVariants.forTask(null));
		assertNull(CatacombsVariants.forTask(" "));
	}

	@Test
	public void onlyTheCatacombsNpcCountsAsTheVariant()
	{
		assertEquals("Deviant spectre", CatacombsVariants.tallyName(NpcID.KOUREND_SPECTRE, " Deviant spectre "));
		assertEquals("Aberrant spectre", CatacombsVariants.tallyName(NpcID.SLAYER_ABBERANT_SPECTRE_1, "Aberrant spectre"));
		// The same names outside the Catacombs are not the variant, so they are not tallied.
		assertNull(CatacombsVariants.tallyName(NpcID.WILD_CAVE_NECHRYAEL, "Greater Nechryael"));
		assertNull(CatacombsVariants.tallyName(NpcID.MYQ5_BLOODVELD, "Mutated Bloodveld"));
		assertNull(CatacombsVariants.tallyName(NpcID.DS2_BRUT_BLACK_DRAGON, "Brutal black dragon"));
		assertNull(CatacombsVariants.tallyName(NpcID.BRUTAL_BLUE_DRAGON_TAPOYAUIK, "Brutal blue dragon"));
		assertNull(CatacombsVariants.tallyName(1, null));
		assertNull(CatacombsVariants.tallyName(1, "  "));
	}

	@Test
	public void theVariantMustBeMoreThanHalfOfTheTaskKills()
	{
		// All standard.
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Aberrant spectre", 50), 50));
		// All variant.
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 50),
			50));
		// Mixed: more than half of the task kills variant, or not.
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres",
			tally("Deviant spectre", 31, "Aberrant spectre", 30), 61));
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 30, "Aberrant spectre", 31),
			61));
		// A tie is the standard monster.
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 20, "Aberrant spectre", 20),
			40));
		// No tallied kills, or no task kills.
		assertNull(CatacombsVariants.decide("Aberrant spectres", Collections.emptyList(), 10));
		assertNull(CatacombsVariants.decide("Aberrant spectres", null, 10));
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 5), 0));
		// Names match ignoring case and spaces; a task without a variant never has one.
		assertEquals("Greater nechryael", CatacombsVariants.decide("nechryael", tally(" greater NECHRYAEL", 3), 3));
		assertNull(CatacombsVariants.decide("Abyssal demons", tally("Deviant spectre", 50), 50));
		assertNull(CatacombsVariants.decide(null, tally("Deviant spectre", 50), 50));
	}

	@Test
	public void unrelatedKillsDontCount()
	{
		// An Ankou on the way and other barraged NPCs are left out: 10 of 14 task kills were the variant.
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 10,
			"Ankou", 6, "Aberrant spectre", 4, "Ghost", 12), 14));
		// Greater Nechryael death spawns (and other names) don't count against the variant.
		assertEquals("Greater nechryael", CatacombsVariants.decide("Nechryael", tally("Greater Nechryael", 20,
			"Death spawn", 45), 20));
		// Nor for it: the variant against the task kills only.
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 3, "Ankou", 40), 6));
		assertSame(TaskSelection.STANDARD,
			CatacombsVariants.selection("Aberrant spectres", tally("Deviant spectre", 3, "Ankou", 40), 6));
	}

	@Test
	public void theLiveSelectionPoolsUntilTheFirstTaskKill()
	{
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Aberrant spectres", Collections.emptyList(), 0));
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Abyssal demons", tally("Abyssal demon", 5), 5));
		// An unrelated kill before the first task kill changes nothing.
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Aberrant spectres", tally("Ankou", 1), 0));
		// A variant kill tallied before the task counter moved: still pooled.
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Aberrant spectres", tally("Deviant spectre", 1), 0));
		assertSame(TaskSelection.STANDARD, CatacombsVariants.selection("Aberrant spectres", tally("Aberrant spectre", 1),
			1));
		// One unrelated kill doesn't make it standard.
		assertEquals(TaskSelection.of("Deviant spectres"),
			CatacombsVariants.selection("Aberrant spectres", tally("Ankou", 1, "Deviant spectre", 1), 1));
		// A tie is standard.
		assertSame(TaskSelection.STANDARD,
			CatacombsVariants.selection("Aberrant spectres", tally("Deviant spectre", 1, "Aberrant spectre", 1), 2));
	}

	@Test
	public void taskVariantsSelectRecordsByTheirVersion()
	{
		LedgerRecord standard = new LedgerRecord();
		standard.setMonster("Aberrant spectres");
		LedgerRecord deviant = new LedgerRecord();
		deviant.setMonster("Aberrant spectres");
		deviant.setVariant("Deviant spectres");

		assertTrue(TaskSelection.ANY.matches(standard));
		assertTrue(TaskSelection.ANY.matches(deviant));
		assertTrue(TaskSelection.STANDARD.matches(standard));
		assertFalse(TaskSelection.STANDARD.matches(deviant));
		assertFalse(TaskSelection.of("deviant SPECTRES ").matches(standard));
		assertTrue(TaskSelection.of("deviant SPECTRES ").matches(deviant));
		assertSame(TaskSelection.STANDARD, TaskSelection.of(" "));
		assertNotEquals(TaskSelection.ANY, TaskSelection.STANDARD);
		assertEquals(TaskSelection.of("Deviant spectres").hashCode(), TaskSelection.of("deviant spectres").hashCode());

		// The group name is the variant's for a variant record, else the monster.
		assertEquals("Aberrant spectres", standard.groupName());
		assertEquals("Deviant spectres", deviant.groupName());
		deviant.setVariant(" ");
		assertEquals("Aberrant spectres", deviant.groupName());
	}

	@Test
	public void theTallyMergesNamesAndIsBounded()
	{
		List<NpcKills> tally = NpcKillTally.add(null, "Deviant spectre");
		tally = NpcKillTally.add(tally, " deviant SPECTRE ");
		tally = NpcKillTally.add(tally, "Ankou");
		tally = NpcKillTally.add(tally, null);
		tally = NpcKillTally.add(tally, " ");
		assertEquals(Arrays.asList(new NpcKills("Deviant spectre", 2), new NpcKills("Ankou", 1)), tally);
		assertEquals(2, NpcKillTally.killsOf(tally, "DEVIANT spectre"));
		assertEquals(0, NpcKillTally.killsOf(tally, "Aberrant spectre"));
		assertEquals(3, NpcKillTally.total(tally));

		List<NpcKills> many = new ArrayList<>();
		for (int i = 0; i < NpcKillTally.MAX_NAMES + 5; i++)
		{
			many = NpcKillTally.add(many, "Npc " + i);
		}
		assertEquals(NpcKillTally.MAX_NAMES, many.size());
		// A name already tallied still counts once the tally is full.
		many = NpcKillTally.add(many, "Npc 0");
		assertEquals(2, NpcKillTally.killsOf(many, "Npc 0"));
		// A Catacombs variant's name is always tallied, so the full tally can still decide the variant.
		many = NpcKillTally.add(many, "Deviant spectre");
		many = NpcKillTally.add(many, "deviant spectre");
		assertEquals(NpcKillTally.MAX_NAMES + 1, many.size());
		assertEquals(2, NpcKillTally.killsOf(many, "Deviant spectre"));
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres", many, 3));
		// Other new names still aren't, and a file's full tally keeps the variant's name.
		many = NpcKillTally.add(many, "Npc 99");
		assertEquals(0, NpcKillTally.killsOf(many, "Npc 99"));
		assertEquals(2, NpcKillTally.killsOf(NpcKillTally.sanitize(many), "Deviant spectre"));
		assertTrue(CatacombsVariants.isVariantNpcName(" GREATER nechryael"));
		assertFalse(CatacombsVariants.isVariantNpcName("Aberrant spectre"));
		assertFalse(CatacombsVariants.isVariantNpcName(null));

		// A file's tally is cleaned: no names, no kills and repeats.
		List<NpcKills> read = Arrays.asList(null, new NpcKills(null, 3), new NpcKills("Ankou", 0),
			new NpcKills("Ankou", 2), new NpcKills("ankou", 1));
		assertEquals(Collections.singletonList(new NpcKills("Ankou", 3)), NpcKillTally.sanitize(read));
		assertTrue(NpcKillTally.sanitize(null).isEmpty());
	}

	@Test
	public void damagedNpcsAreTakenOnceAndBounded()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 5);
		assertTrue(npcs.takeDied(0, 5));
		assertFalse("taken once", npcs.takeDied(0, 5));
		assertFalse("never damaged", npcs.takeDied(0, 6));

		npcs.damaged(0, 7);
		npcs.forget(0, 7);
		assertFalse("despawned", npcs.takeDied(0, 7));

		for (int i = 0; i < DamagedNpcs.MAX_NPCS + 10; i++)
		{
			npcs.damaged(0, i);
		}
		assertEquals(DamagedNpcs.MAX_NPCS, npcs.size());
		// The ones damaged longest ago went first.
		assertFalse(npcs.takeDied(0, 0));
		assertTrue(npcs.takeDied(0, DamagedNpcs.MAX_NPCS + 9));
		npcs.clear();
		assertEquals(0, npcs.size());
	}

	@Test
	public void damagedNpcsAreKeptPerWorldView()
	{
		// The same index in another world view (a boat's) is another NPC.
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 5);
		assertFalse(npcs.takeDied(3, 5));
		npcs.forget(3, 5);
		assertTrue(npcs.takeDied(0, 5));

		npcs.damaged(-1, 5);
		npcs.damaged(3, 5);
		assertEquals(2, npcs.size());
		assertTrue(npcs.takeDied(3, 5));
		assertFalse(npcs.takeDied(0, 5));
		assertTrue(npcs.takeDied(-1, 5));
		// Indexes and ids with the high bit set don't collide.
		npcs.damaged(0, -1);
		assertFalse(npcs.takeDied(-1, -1));
		assertTrue(npcs.takeDied(0, -1));
	}

	private static void assertVariant(String task, int constant, int id, String npcName, String name)
	{
		assertEquals(id, constant);
		CatacombsVariants.Variant variant = CatacombsVariants.forTask(task);
		assertEquals(task, variant.getTask());
		assertEquals(id, variant.getNpcId());
		assertEquals(npcName, variant.getNpcName());
		assertEquals(name, variant.getName());
	}

	/** A tally of name and kills pairs, in order. */
	static List<NpcKills> tally(Object... nameAndKills)
	{
		List<NpcKills> tally = new ArrayList<>();
		for (int i = 0; i < nameAndKills.length; i += 2)
		{
			tally.add(new NpcKills((String) nameAndKills[i], (Integer) nameAndKills[i + 1]));
		}
		return tally;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Charging, loading, unloading and uncharging the blowpipe or a trident is left out of the supplies diff.
 */
public class ChargeExclusionsTest
{
	private static final int SHARK = 385;
	private static final int BLOWPIPE = ItemID.TOXIC_BLOWPIPE_LOADED;
	private static final int TRIDENT = ItemID.TOXIC_TOTS_CHARGED;

	private final ChargeExclusions exclusions = new ChargeExclusions();

	@Test
	public void nothingIsExcludedByDefault()
	{
		assertFalse(exclusions.isExcluded(ItemID.RUNE_DART, 0));
		assertTrue(exclusions.excludedItems(0).isEmpty());
	}

	@Test
	public void usingDartsOnTheBlowpipeExcludesMaterialsOnly()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		assertTrue(exclusions.isExcluded(ItemID.RUNE_DART, 100));
		assertTrue(exclusions.isExcluded(ItemID.SNAKEBOSS_SCALE, 100));
		assertTrue(exclusions.isExcluded(ItemID.DEATHRUNE, 101));
		assertTrue(exclusions.isExcluded(ItemID.CHAOSRUNE, 101));
		assertTrue(exclusions.isExcluded(ItemID.FIRERUNE, 101));
		assertTrue(exclusions.isExcluded(ItemID.COINS, 101));
		assertFalse(exclusions.isExcluded(SHARK, 100));
		assertFalse(exclusions.isExcluded(BLOWPIPE, 100));
		assertFalse(exclusions.isExcluded(ItemID.NATURERUNE, 100));
		assertEquals(ChargeExclusions.MATERIALS, exclusions.excludedItems(100));
	}

	@Test
	public void eitherOrderOfUseCounts()
	{
		exclusions.menuOptionClicked("Use", new int[]{TRIDENT, ItemID.FIRERUNE}, 10);
		assertTrue(exclusions.isExcluded(ItemID.FIRERUNE, 10));
	}

	@Test
	public void unloadAndUnchargeOpenTheWindow()
	{
		exclusions.menuOptionClicked("Unload", new int[]{BLOWPIPE}, 10);
		assertTrue(exclusions.isExcluded(ItemID.RUNE_DART, 11));
		exclusions.reset();
		exclusions.menuOptionClicked("<col=ff9040>Uncharge</col>", new int[]{ItemID.TOTS_CHARGED_ORN}, 20);
		assertTrue(exclusions.isExcluded(ItemID.COINS, 21));
		exclusions.reset();
		exclusions.menuOptionClicked("UNCHARGE", new int[]{ItemID.TOXIC_BLOWPIPE_ORNAMENT}, 30);
		assertTrue(exclusions.isExcluded(ItemID.SNAKEBOSS_SCALE, 30));
	}

	@Test
	public void otherOptionsAndItemsDontOpenIt()
	{
		exclusions.menuOptionClicked("Check", new int[]{BLOWPIPE}, 10);
		exclusions.menuOptionClicked("Wield", new int[]{TRIDENT}, 10);
		exclusions.menuOptionClicked("Drop", new int[]{BLOWPIPE}, 10);
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, SHARK}, 10);
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART}, 10);
		exclusions.menuOptionClicked(null, new int[]{BLOWPIPE}, 10);
		exclusions.menuOptionClicked("Use", null, 10);
		assertFalse(exclusions.isExcluded(ItemID.RUNE_DART, 10));
		assertFalse(exclusions.isExcluded(ItemID.RUNE_DART, 11));
	}

	@Test
	public void timesOut()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.CHAOSRUNE, TRIDENT}, 100);
		assertFalse("before", exclusions.isExcluded(ItemID.CHAOSRUNE, 99));
		assertTrue(exclusions.isExcluded(ItemID.CHAOSRUNE, 100 + ChargeExclusions.TIMEOUT_TICKS));
		assertFalse(exclusions.isExcluded(ItemID.CHAOSRUNE, 101 + ChargeExclusions.TIMEOUT_TICKS));
	}

	@Test
	public void confirmationClosesAfterTheGrace()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.DEATHRUNE, TRIDENT}, 100);
		exclusions.messageSeen("You add 123 charges to the weapon.<br>New total: 246", 110);
		assertTrue(exclusions.isExcluded(ItemID.DEATHRUNE, 110));
		assertTrue(exclusions.isExcluded(ItemID.DEATHRUNE, 112));
		assertFalse(exclusions.isExcluded(ItemID.DEATHRUNE, 113));
		assertTrue(exclusions.excludedItems(113).isEmpty());
	}

	@Test
	public void otherMessagesDontClose()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		exclusions.messageSeen("You eat the shark.", 101);
		exclusions.messageSeen(null, 101);
		assertTrue(exclusions.isExcluded(ItemID.RUNE_DART, 120));
	}

	@Test
	public void confirmationWithoutAWindowDoesNothing()
	{
		exclusions.messageSeen("You uncharge your weapon.", 5);
		assertFalse(exclusions.isExcluded(ItemID.COINS, 5));
		exclusions.menuOptionClicked("Uncharge", new int[]{TRIDENT}, 10);
		// The earlier confirmation didn't shorten the new window.
		assertTrue(exclusions.isExcluded(ItemID.COINS, 20));
	}

	@Test
	public void aNewClickReopensTheWindow()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		exclusions.messageSeen("Darts: Rune dart x 50. Scales: 0 (0.0%).", 100);
		exclusions.menuOptionClicked("Use", new int[]{ItemID.SNAKEBOSS_SCALE, BLOWPIPE}, 140);
		assertTrue(exclusions.isExcluded(ItemID.SNAKEBOSS_SCALE, 140 + ChargeExclusions.TIMEOUT_TICKS));
	}

	@Test
	public void confirmations()
	{
		assertTrue(ChargeExclusions.isConfirmation(
			"Darts: <col=007f00>Rune dart x 1,000</col>. Scales: <col=007f00>16,383 (100.0%)</col>."));
		assertTrue(ChargeExclusions.isConfirmation("Darts: None. Scales: 99 (0.6%)."));
		assertTrue(ChargeExclusions.isConfirmation("The blowpipe can't hold any more darts."));
		assertTrue(ChargeExclusions.isConfirmation("The blowpipe can't hold any more scales."));
		assertTrue(ChargeExclusions.isConfirmation("The blowpipe has no darts in it."));
		assertTrue(ChargeExclusions.isConfirmation("You add a charge to the weapon.<br>New total: 2016"));
		assertTrue(ChargeExclusions.isConfirmation("You add 1,200 charges to the weapon.<br>New total: 2,500"));
		assertTrue(ChargeExclusions.isConfirmation("Your weapon is already fully charged."));
		assertTrue(ChargeExclusions.isConfirmation("You uncharge your weapon."));
		assertFalse(ChargeExclusions.isConfirmation("Your blowpipe has run out of darts."));
		assertFalse(ChargeExclusions.isConfirmation(null));
	}

	@Test
	public void resetForgetsTheWindow()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		exclusions.reset();
		assertFalse(exclusions.isExcluded(ItemID.RUNE_DART, 100));
	}

	@Test
	public void everyWeaponVariantIsAWeapon()
	{
		for (int id : ChargedWeaponUsage.BLOWPIPES)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		for (int id : ChargedWeaponUsage.SEAS_TRIDENTS)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		for (int id : ChargedWeaponUsage.SWAMP_TRIDENTS)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		assertEquals(22, ChargeExclusions.WEAPONS.size());
		assertEquals(14, ChargeExclusions.MATERIALS.size());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Blowpipe darts and scales and trident casts counted from attack animations.
 */
public class ChargedWeaponUsageTest
{
	private static final int BLOWPIPE = ItemID.TOXIC_BLOWPIPE_LOADED;
	private static final int SHOT = AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK;
	private static final int CAST = AnimationID.HUMAN_CASTWAVE_STAFF;
	private static final int DART = ItemID.ADAMANT_DART;
	private static final int SCALE = ItemID.SNAKEBOSS_SCALE;

	private final ChargedWeaponUsage usage = new ChargedWeaponUsage();
	private int tick;

	private static ChargedWeaponUsage.Tick.TickBuilder blowpipeShot()
	{
		return ChargedWeaponUsage.Tick.builder().weaponId(BLOWPIPE).animationId(SHOT).dartId(DART);
	}

	private static ChargedWeaponUsage.Tick.TickBuilder tridentCast(int weaponId)
	{
		return ChargedWeaponUsage.Tick.builder().weaponId(weaponId).animationId(CAST).tridentGraphic(true);
	}

	/** Feeds {@code shots} ticks built by {@code tick} and sums what was used. */
	private Map<Integer, Integer> run(ChargedWeaponUsage.Tick.TickBuilder builder, int shots)
	{
		final Map<Integer, Integer> total = new HashMap<>();
		for (int i = 0; i < shots; i++)
		{
			usage.update(builder.tick(++tick).build()).forEach((id, qty) -> total.merge(id, qty, Integer::sum));
		}
		return total;
	}

	private static int qty(Map<Integer, Integer> used, int itemId)
	{
		return used.getOrDefault(itemId, 0);
	}

	@Test
	public void noDeviceUsesOneDartPerShot()
	{
		final Map<Integer, Integer> used = run(blowpipeShot(), 3);
		assertEquals(3, qty(used, DART));
		assertEquals(2, qty(used, SCALE));
	}

	@Test
	public void scalesCarryOverInThirds()
	{
		assertEquals(0, qty(run(blowpipeShot(), 1), SCALE));
		assertEquals(1, qty(run(blowpipeShot(), 1), SCALE));
		assertEquals(1, qty(run(blowpipeShot(), 1), SCALE));
		assertEquals(0, qty(run(blowpipeShot(), 1), SCALE));
	}

	@Test
	public void hundredShotsWithEachDevice()
	{
		assertDarts(ItemID.ANMA_30_REWARD, false, 40);
		assertDarts(ItemID.ANMA_50_REWARD, false, 28);
		assertDarts(ItemID.SKILLCAPE_MAX_ANMA, false, 28);
		assertDarts(ItemID.AVAS_ASSEMBLER, false, 20);
		assertDarts(ItemID.AVAS_ASSEMBLER_MASORI, false, 20);
		assertDarts(ItemID.SKILLCAPE_MAX_ASSEMBLER_MASORI_TROUVER, false, 20);
		assertDarts(ItemID.SKILLCAPE_RANGING, false, 28);
		assertDarts(ItemID.SKILLCAPE_RANGING, true, 20);
		assertDarts(ItemID.SKILLCAPE_RANGING_TRIMMED, true, 20);
		assertDarts(ItemID.SKILLCAPE_MAX, false, 28);
		assertDarts(ItemID.SKILLCAPE_MAX, true, 20);
		assertDarts(ItemID.DIZANAS_QUIVER_CHARGED, false, 20);
		assertDarts(ItemID.SKILLCAPE_MAX_DIZANAS, false, 20);
		// The upgrade setting only affects ranging and max capes.
		assertDarts(ItemID.ANMA_50_REWARD, true, 28);
		assertDarts(ChargedWeaponUsage.NO_ITEM, true, 100);
		// A broken assembler saves nothing.
		assertDarts(ItemID.AVAS_ASSEMBLER_BROKEN, false, 100);
	}

	private void assertDarts(int capeId, boolean upgrade, int expectedDarts)
	{
		usage.reset();
		final Map<Integer, Integer> used = run(blowpipeShot().capeId(capeId).vorkathsHeadUpgrade(upgrade), 100);
		assertEquals("darts with " + capeId, expectedDarts, qty(used, DART));
		assertEquals("scales with " + capeId, 66, qty(used, SCALE));
	}

	@Test
	public void assemblerCarriesDartsOverInHundredths()
	{
		final ChargedWeaponUsage.Tick.TickBuilder shot = blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER);
		assertEquals(0, qty(run(shot, 4), DART));
		assertEquals(1, qty(run(shot, 1), DART));
		assertEquals(0, qty(run(shot, 4), DART));
		assertEquals(1, qty(run(shot, 1), DART));
	}

	@Test
	public void quiverSettingWhenPassed()
	{
		assertEquals(20, ChargedWeaponUsage.quiverLossHundredths(null));
		assertEquals(20, ChargedWeaponUsage.quiverLossHundredths(0));
		assertEquals(28, ChargedWeaponUsage.quiverLossHundredths(1));
		assertEquals(40, ChargedWeaponUsage.quiverLossHundredths(2));
		assertEquals(20, ChargedWeaponUsage.quiverLossHundredths(7));
		assertEquals(40, ChargedWeaponUsage.dartLossHundredths(ItemID.DIZANAS_QUIVER_INFINITE, 2, false));
		// The quiver setting doesn't apply to other capes.
		assertEquals(20, ChargedWeaponUsage.dartLossHundredths(ItemID.AVAS_ASSEMBLER, 2, false));
	}

	@Test
	public void unknownDartTypeCountsScalesOnlyAndAsksForACheck()
	{
		assertFalse(usage.isDartCheckNeeded());
		final Map<Integer, Integer> used = run(blowpipeShot().dartId(ChargedWeaponUsage.NO_ITEM), 3);
		assertEquals(1, used.size());
		assertEquals(2, qty(used, SCALE));
		assertTrue(usage.isDartCheckNeeded());

		// No dart fraction was carried while unknown: the first known shot uses one dart from scratch.
		final Map<Integer, Integer> known = run(blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER), 4);
		assertFalse(usage.isDartCheckNeeded());
		assertEquals(0, qty(known, DART));
	}

	@Test
	public void knownDartTypeOnAnyTickClearsTheHint()
	{
		run(blowpipeShot().dartId(ChargedWeaponUsage.NO_ITEM), 1);
		assertTrue(usage.isDartCheckNeeded());
		run(ChargedWeaponUsage.Tick.builder().dartId(DART), 1);
		assertFalse(usage.isDartCheckNeeded());
	}

	@Test
	public void changingDartTypeDropsTheCarryOver()
	{
		final ChargedWeaponUsage.Tick.TickBuilder shot = blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER);
		run(shot, 4);
		final Map<Integer, Integer> used = run(shot.dartId(ItemID.RUNE_DART), 1);
		assertEquals(0, qty(used, ItemID.RUNE_DART));
		assertEquals(0, qty(used, DART));
		assertEquals(1, qty(run(shot, 4), ItemID.RUNE_DART));
	}

	@Test
	public void ornamentBlowpipeAndAnimationCount()
	{
		final Map<Integer, Integer> used = run(blowpipeShot().weaponId(ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT)
			.animationId(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK_ORNAMENT), 1);
		assertEquals(1, qty(used, DART));
	}

	@Test
	public void nothingWithoutTheBlowpipeWorn()
	{
		assertTrue(run(blowpipeShot().weaponId(ChargedWeaponUsage.NO_ITEM), 10).isEmpty());
		assertTrue(run(blowpipeShot().weaponId(ItemID.TOXIC_BLOWPIPE), 10).isEmpty());
	}

	@Test
	public void nothingForOtherAnimations()
	{
		assertTrue(run(blowpipeShot().animationId(-1), 10).isEmpty());
		assertTrue(run(blowpipeShot().animationId(CAST), 10).isEmpty());
	}

	@Test
	public void nothingAfterFrameZero()
	{
		assertTrue(run(blowpipeShot().animationFrame(1), 10).isEmpty());
		assertTrue(run(tridentCast(ItemID.TOTS_CHARGED).animationFrame(3), 10).isEmpty());
	}

	@Test
	public void atMostOneAttackPerTick()
	{
		final ChargedWeaponUsage.Tick shot = blowpipeShot().tick(5).build();
		assertEquals(1, qty(usage.update(shot), DART));
		assertTrue(usage.update(shot).isEmpty());
		assertTrue(usage.update(blowpipeShot().tick(4).build()).isEmpty());
		assertEquals(1, qty(usage.update(blowpipeShot().tick(6).build()), DART));
	}

	@Test
	public void tridentOfTheSeasCast()
	{
		for (int trident : new int[]{ItemID.TOTS, ItemID.TOTS_CHARGED, ItemID.TOTS_I_CHARGED, ItemID.TOTS_ORN,
			ItemID.TOTS_CHARGED_ORN, ItemID.TOTS_I_CHARGED_ORN})
		{
			final Map<Integer, Integer> used = run(tridentCast(trident), 1);
			assertEquals("" + trident, 4, used.size());
			assertEquals(1, qty(used, ItemID.DEATHRUNE));
			assertEquals(1, qty(used, ItemID.CHAOSRUNE));
			assertEquals(5, qty(used, ItemID.FIRERUNE));
			assertEquals(10, qty(used, ItemID.COINS));
		}
	}

	@Test
	public void tridentOfTheSwampCast()
	{
		for (int trident : new int[]{ItemID.TOXIC_TOTS_CHARGED, ItemID.TOXIC_TOTS_I_CHARGED,
			ItemID.TOXIC_TOTS_CHARGED_ORN, ItemID.TOXIC_TOTS_I_CHARGED_ORN})
		{
			final Map<Integer, Integer> used = run(tridentCast(trident)
				.animationId(AnimationID.HUMAN_CASTWAVE_STAFF_WALKMERGE), 1);
			assertEquals("" + trident, 4, used.size());
			assertEquals(1, qty(used, ItemID.DEATHRUNE));
			assertEquals(1, qty(used, ItemID.CHAOSRUNE));
			assertEquals(5, qty(used, ItemID.FIRERUNE));
			assertEquals(1, qty(used, SCALE));
		}
	}

	@Test
	public void tridentCastsAddUp()
	{
		final Map<Integer, Integer> used = run(tridentCast(ItemID.TOXIC_TOTS_CHARGED), 10);
		assertEquals(10, qty(used, ItemID.DEATHRUNE));
		assertEquals(50, qty(used, ItemID.FIRERUNE));
		assertEquals(10, qty(used, SCALE));
	}

	@Test
	public void unchargedTridentsCastNothing()
	{
		for (int trident : new int[]{ItemID.TOTS_UNCHARGED, ItemID.TOTS_I_UNCHARGED, ItemID.TOTS_UNCHARGED_ORN,
			ItemID.TOTS_I_UNCHARGED_ORN, ItemID.TOXIC_TOTS_UNCHARGED, ItemID.TOXIC_TOTS_I_UNCHARGED,
			ItemID.TOXIC_TOTS_UNCHARGED_ORN, ItemID.TOXIC_TOTS_I_UNCHARGED_ORN})
		{
			assertTrue("" + trident, run(tridentCast(trident), 1).isEmpty());
		}
	}

	@Test
	public void tridentNeedsTheCastGraphic()
	{
		assertTrue(run(tridentCast(ItemID.TOTS_CHARGED).tridentGraphic(false), 5).isEmpty());
		// A wave spell from another staff shows no trident graphic, and the graphic alone isn't a cast.
		assertTrue(run(tridentCast(ItemID.TOTS_CHARGED).animationId(-1), 5).isEmpty());
	}

	@Test
	public void resetForgetsCarryOversAndTheLastTick()
	{
		run(blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER), 4);
		run(blowpipeShot().dartId(ChargedWeaponUsage.NO_ITEM), 2);
		assertTrue(usage.isDartCheckNeeded());
		usage.reset();
		assertFalse(usage.isDartCheckNeeded());
		tick = 0;
		final Map<Integer, Integer> used = run(blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER), 1);
		assertEquals(0, qty(used, DART));
		assertEquals(0, qty(used, SCALE));
	}

	@Test
	public void trackedIdSetsDontOverlap()
	{
		for (int id : ChargedWeaponUsage.BLOWPIPES)
		{
			assertFalse(ChargedWeaponUsage.SEAS_TRIDENTS.contains(id) || ChargedWeaponUsage.SWAMP_TRIDENTS.contains(id));
		}
		for (int id : ChargedWeaponUsage.SEAS_TRIDENTS)
		{
			assertFalse(ChargedWeaponUsage.SWAMP_TRIDENTS.contains(id));
		}
		for (int id : ChargedWeaponUsage.ASSEMBLERS)
		{
			assertFalse(ChargedWeaponUsage.ACCUMULATORS.contains(id) || ChargedWeaponUsage.RANGING_CAPES.contains(id)
				|| ChargedWeaponUsage.QUIVERS.contains(id) || ChargedWeaponUsage.ATTRACTORS.contains(id));
		}
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import javax.swing.JComboBox;
import javax.swing.JScrollPane;
import javax.swing.event.PopupMenuListener;
import org.junit.Test;

/**
 * A drop-down's open list widening to fit its longest choice. Headless, the list is never shown, so these check
 * the size it is given; the move to keep its right edge in place needs a screen (checked in game).
 */
public class ComboPopupWidenerTest
{
	private static final String LONG = "Catacombs of Kourend, the far north end";

	private static JComboBox<String> box(String... items)
	{
		JComboBox<String> box = new JComboBox<>(items);
		box.setPrototypeDisplayValue("Abyssal demons");
		box.setSize(box.getPreferredSize());
		return box;
	}

	private static ComboPopupWidener widener(JComboBox<String> box)
	{
		for (PopupMenuListener listener : box.getPopupMenuListeners())
		{
			if (listener instanceof ComboPopupWidener)
			{
				return (ComboPopupWidener) listener;
			}
		}
		throw new AssertionError("no widener");
	}

	@Test
	public void theWidthIsTheContentsAtLeastTheBoxAndAtMostTheMaximum()
	{
		assertEquals(250, ComboPopupWidener.width(120, 250, 320));
		assertEquals("never narrower than the box", 120, ComboPopupWidener.width(120, 80, 320));
		assertEquals("capped", 320, ComboPopupWidener.width(120, 500, 320));
		assertEquals("a box wider than the cap stays as it is", 400, ComboPopupWidener.width(400, 500, 320));
	}

	@Test
	public void theListWidensToItsLongestChoiceAndTheBoxKeepsItsWidth()
	{
		JComboBox<String> box = box("All", LONG);
		int closed = box.getPreferredSize().width;
		ComboPopupWidener.install(box, 1_000);
		widener(box).widen(box);
		JScrollPane scroller = ComboPopupWidener.listScroller(box);
		assertNotNull(scroller);
		int list = scroller.getPreferredSize().width;
		assertTrue("wider than the box: " + list + " > " + closed, list > closed);
		assertEquals("the closed box keeps its width", closed, box.getPreferredSize().width);
	}

	@Test
	public void aLongChoiceIsCappedAndShortOnesKeepTheBoxWidth()
	{
		JComboBox<String> capped = box("All", LONG);
		int cap = capped.getWidth() + 20;
		ComboPopupWidener.install(capped, cap);
		widener(capped).widen(capped);
		assertEquals(cap, ComboPopupWidener.listScroller(capped).getPreferredSize().width);

		JComboBox<String> narrow = box("All", "Abyss");
		ComboPopupWidener.install(narrow, 1_000);
		widener(narrow).widen(narrow);
		int list = ComboPopupWidener.listScroller(narrow).getPreferredSize().width;
		assertTrue("the box's width, less the list's border: " + list + " of " + narrow.getWidth(),
			list <= narrow.getWidth() && list >= narrow.getWidth() - 10);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * The late-loot grace window for a running session whose task completes ({@link SessionTracker#holdCompletion()}).
 * The plugin calls {@code tickCompletion()} once per game tick before observing, holds on a running completion, and
 * releases any held session with {@code takePendingCompletion()} on every other end path.
 */
public class CompletionGraceTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final int BONES = 526;
	private static final int ASHES = 592;

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	private static ItemTally tally(int id, int qty)
	{
		ItemTally t = new ItemTally();
		t.add(id, qty);
		return t;
	}

	/** Starts a 3-kill demon task, kills all three over 60 seconds and completes it on the last observation. */
	private void runAndCompleteTask()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 3, 3, false);
		assertTrue(tracker.play(ACCOUNT));
		tracker.addLoot(tally(BONES, 1));
		now += 30_000;
		tracker.observe("Abyssal demons", DEMON_ID, 1, 3, false);
		now += 30_000;
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
	}

	/** Mirrors the plugin's endSession: a held completion is released first, then the active session is stopped. */
	private SessionTracker.Summary[] endSession()
	{
		return new SessionTracker.Summary[]{tracker.takePendingCompletion(), tracker.stopAndReset()};
	}

	@Test
	public void lootDuringGraceWindowIsIncluded()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.hasPendingCompletion());
		// Same tick as the completion, after the task count update.
		assertTrue(tracker.addLoot(tally(BONES, 1)));

		assertNull("tick 1 of 2", tracker.tickCompletion());
		assertTrue(tracker.addLoot(tally(ASHES, 2)));

		SessionTracker.Summary summary = tracker.tickCompletion();
		assertNotNull("released after " + SessionTracker.COMPLETION_LOOT_GRACE_TICKS + " ticks", summary);
		assertFalse(tracker.hasPendingCompletion());
		assertTrue(summary.isCompleted());
		assertEquals(2, summary.getLoot().get(BONES));
		assertEquals(2, summary.getLoot().get(ASHES));
		assertEquals(SaveDecision.Action.SAVE_COMPLETED,
			SaveDecision.decide(summary, SaveDecision.EndReason.SYSTEM, true));
		assertNull("released once", tracker.tickCompletion());
		assertNull(tracker.takePendingCompletion());
	}

	@Test
	public void lootAfterGraceWindowIsNotIncluded()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.tickCompletion();
		SessionTracker.Summary summary = tracker.tickCompletion();
		assertNotNull(summary);
		assertFalse("idle, no session", tracker.addLoot(tally(ASHES, 1)));
		assertEquals(1, summary.getLoot().get(BONES));
		assertEquals(0, summary.getLoot().get(ASHES));
	}

	@Test
	public void durationAndKillsAreFrozenAtCompletion()
	{
		runAndCompleteTask();
		final long completedAt = now;
		assertTrue(tracker.holdCompletion());
		assertEquals("the panel shows the session as ended", SessionTracker.State.IDLE, tracker.getState());
		assertNull(tracker.activeSummary());

		now += 600;
		tracker.tickCompletion();
		// A stray count change during the window does not touch the held session.
		tracker.observe("Abyssal demons", DEMON_ID, 5, 5, false);
		now += 600;
		SessionTracker.Summary summary = tracker.tickCompletion();
		assertNotNull(summary);
		assertEquals(3, summary.getKills());
		assertEquals(60_000, summary.getActiveMillis());
		assertEquals(completedAt, summary.getEndedAt());
	}

	@Test
	public void holdIsRefusedUnlessRunningAndCompleted()
	{
		assertFalse("idle", tracker.holdCompletion());
		tracker.observe("Abyssal demons", DEMON_ID, 3, 3, false);
		assertTrue(tracker.play(ACCOUNT));
		assertFalse("running, not completed", tracker.holdCompletion());
		assertEquals(SessionTracker.State.RUNNING, tracker.getState());
		assertNull(tracker.tickCompletion());
	}

	@Test
	public void pausedCompletionIsNotHeldAndSavesAsBefore()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 3, 3, false);
		assertTrue(tracker.play(ACCOUNT));
		now += 10_000;
		tracker.observe("Abyssal demons", DEMON_ID, 2, 3, false);
		tracker.pause();
		now += 10_000;
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));

		assertFalse(tracker.holdCompletion());
		assertFalse(tracker.hasPendingCompletion());
		assertEquals(SessionTracker.State.PAUSED, tracker.getState());
		assertFalse("paused", tracker.addLoot(tally(BONES, 1)));

		SessionTracker.Summary[] ended = endSession();
		assertNull(ended[0]);
		assertNotNull(ended[1]);
		assertTrue(ended[1].isCompleted());
		assertEquals(1, ended[1].getKills());
		assertEquals(10_000, ended[1].getActiveMillis());
		assertEquals(SaveDecision.Action.SAVE_COMPLETED,
			SaveDecision.decide(ended[1], SaveDecision.EndReason.SYSTEM, true));
	}

	@Test
	public void completionAfterAwaitedZeroIsHeldToo()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 2, 2, false);
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(SessionTracker.ObserveResult.TASK_CLEARED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.holdCompletion());
		tracker.addLoot(tally(BONES, 1));
		tracker.tickCompletion();
		SessionTracker.Summary summary = tracker.tickCompletion();
		assertEquals(2, summary.getKills());
		assertEquals(1, summary.getLoot().get(BONES));
	}

	@Test
	public void endPathsDuringWindowSaveOnceAsCompleted()
	{
		for (SaveDecision.EndReason reason : new SaveDecision.EndReason[]{SaveDecision.EndReason.LOGOUT,
			SaveDecision.EndReason.PLAYER_STOP, SaveDecision.EndReason.SHUTDOWN, SaveDecision.EndReason.ACCOUNT_SWITCH,
			SaveDecision.EndReason.SYSTEM})
		{
			setUp();
			runAndCompleteTask();
			assertTrue(tracker.holdCompletion());
			tracker.addLoot(tally(ASHES, 1));
			tracker.autoPause();
			// Logout persists only an active session; a held completion is never one.
			assertNull(reason.name(), tracker.activeSummary());

			SessionTracker.Summary[] ended = endSession();
			assertNotNull(reason.name(), ended[0]);
			assertNull(reason.name() + ": no active session", ended[1]);
			assertTrue(ended[0].isCompleted());
			assertEquals(1, ended[0].getLoot().get(ASHES));
			// The plugin saves a released completion with SYSTEM, but any reason saves a completed summary.
			assertEquals(reason.name(), SaveDecision.Action.SAVE_COMPLETED,
				SaveDecision.decide(ended[0], reason, true));

			// Nothing left to save twice: not by a later tick, end path or shutdown.
			assertNull(tracker.tickCompletion());
			assertNull(tracker.tickCompletion());
			SessionTracker.Summary[] again = endSession();
			assertNull(again[0]);
			assertNull(again[1]);
		}
	}

	@Test
	public void newSessionDuringWindowDoesNotStealLoot()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.observe("Black dragons", DRAGON_ID, 10, 10, false);
		assertTrue("Play is allowed during the window", tracker.play(ACCOUNT));
		assertTrue(tracker.addLoot(tally(ASHES, 1)));
		assertTrue("the new session gets none of it", tracker.getLoot().isEmpty());

		SessionTracker.Summary[] ended = endSession();
		assertEquals(1, ended[0].getLoot().get(ASHES));
		assertEquals(DEMON_ID, ended[0].getCreatureId());
		assertEquals(DRAGON_ID, ended[1].getCreatureId());
		assertTrue(ended[1].getLoot().isEmpty());
	}

	@Test
	public void newSessionGetsLootAfterWindow()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.observe("Black dragons", DRAGON_ID, 10, 10, false);
		assertTrue(tracker.play(ACCOUNT));
		tracker.tickCompletion();
		assertNotNull(tracker.tickCompletion());
		assertTrue(tracker.addLoot(tally(ASHES, 1)));
		assertEquals(1, tracker.getLoot().get(ASHES));
	}

	@Test
	public void secondCompletionIsNotHeldWhileOneIsPending()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.observe("Black dragons", DRAGON_ID, 1, 1, false);
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertFalse(tracker.holdCompletion());
		// The plugin then ends the session normally, which releases the held one first.
		SessionTracker.Summary[] ended = endSession();
		assertEquals(DEMON_ID, ended[0].getCreatureId());
		assertEquals(DRAGON_ID, ended[1].getCreatureId());
		assertTrue(ended[0].isCompleted());
		assertTrue(ended[1].isCompleted());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CompletionSignalTest
{
	@Test
	public void firstReadingIsBaselineOnly()
	{
		CompletionSignal signal = new CompletionSignal();
		assertFalse(signal.update(10, 0, 0));
		assertTrue(signal.update(11, 0, 0));
		assertFalse(signal.update(11, 0, 0));
	}

	@Test
	public void resetRestoresBaselineBehaviour()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(10, 0, 0);
		signal.reset();
		assertFalse(signal.update(11, 0, 0));
	}

	@Test
	public void lateLoginSyncIsNotACompletion()
	{
		CompletionSignal signal = new CompletionSignal();
		// counters read as zero before the server resynced them
		assertFalse(signal.update(0, 0, 0));
		assertFalse(signal.update(57, 0, 0));
		assertFalse(signal.update(57, 3, 0));
		assertTrue(signal.update(58, 3, 0));
	}

	@Test
	public void resyncAlongsideAnotherCounterIsNotACompletion()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(0, 0, 0);
		assertFalse(signal.update(1, 40, 0));
	}

	@Test
	public void decreasesAreNotCompletions()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(25, 0, 0);
		assertFalse(signal.update(0, 0, 0)); // streak reset
		assertTrue(signal.update(0, 0, 1)); // another counter increments by one
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Which kill loot a bonecrusher or ash sanctifier leaves out, for each "Bonecrusher handling" mode.
 */
public class CrushedLootFilterTest
{
	private static final List<Integer> NOTHING = Collections.emptyList();
	private static final List<Integer> CRUSHER = Arrays.asList(ItemID.SHARK, ItemID.BONECRUSHER);
	private static final List<Integer> NECKLACE = Collections.singletonList(ItemID.BONECRUSHER_NECKLACE);
	private static final List<Integer> SANCTIFIER = Collections.singletonList(ItemID.ASH_SANCTIFIER);
	private static final List<Integer> BOTH = Arrays.asList(ItemID.BONECRUSHER_NECKLACE, ItemID.ASH_SANCTIFIER);

	/** Wyrm loot as in the owner's task: wyrm bones, demonic ashes, plain ashes, noted bones, coins. */
	private static ItemTally wyrmLoot()
	{
		ItemTally loot = new ItemTally();
		loot.add(ItemID.WYRM_BONES, 1);
		loot.add(ItemID.ABYSSAL_ASHES, 1);
		loot.add(ItemID.ASHES, 1);
		loot.add(ItemID.Cert.DRAGON_BONES, 5);
		loot.add(ItemID.COINS, 300);
		return loot;
	}

	@Test
	public void itemIdsMatchTheGameValues()
	{
		// Checked against net.runelite.api.gameval.ItemID in RuneLite 1.13.4, and the owner's wyrm data (22780).
		assertEquals(13116, ItemID.BONECRUSHER);
		assertEquals(22986, ItemID.BONECRUSHER_NECKLACE);
		assertEquals(25781, ItemID.ASH_SANCTIFIER);
		assertEquals(22780, ItemID.WYRM_BONES);
		assertTrue(CrushedLootFilter.BONES.contains(22780));
		assertTrue(CrushedLootFilter.DEMONIC_ASHES.containsAll(Arrays.asList(25766, 25769, 25772, 25775, 25778)));
		assertEquals(5, CrushedLootFilter.DEMONIC_ASHES.size());
	}

	@Test
	public void boneAndAshSetsDoNotOverlapAndHoldNoNotedOrPlainItems()
	{
		for (int id : CrushedLootFilter.BONES)
		{
			assertFalse(CrushedLootFilter.DEMONIC_ASHES.contains(id));
		}
		assertFalse(CrushedLootFilter.BONES.contains(ItemID.Cert.BONES));
		assertFalse(CrushedLootFilter.BONES.contains(ItemID.Cert.WYRM_BONES));
		assertFalse(CrushedLootFilter.DEMONIC_ASHES.contains(ItemID.ASHES));
		assertFalse(CrushedLootFilter.DEMONIC_ASHES.contains(ItemID.Cert.ABYSSAL_ASHES));
		assertTrue(CrushedLootFilter.BONES.containsAll(Arrays.asList(ItemID.BONES, ItemID.BIG_BONES,
			ItemID.DRAGON_BONES, ItemID.DAGANNOTH_KING_BONES, ItemID.DRAKE_BONES, ItemID.HYDRA_BONES)));
	}

	@Test
	public void autoWithoutACrusherKeepsEverything()
	{
		CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, NOTHING);
		assertSame(CrushedLootFilter.KEEP_ALL, filter);
		assertEquals(wyrmLoot(), filter.apply(wyrmLoot()));
		assertSame(CrushedLootFilter.KEEP_ALL, CrushedLootFilter.forDrop(BonecrusherMode.AUTO, null));
		assertSame(CrushedLootFilter.KEEP_ALL, CrushedLootFilter.forDrop(BonecrusherMode.AUTO,
			Arrays.asList(null, ItemID.SHARK)));
	}

	@Test
	public void autoWithABonecrusherDropsBonesOnly()
	{
		for (List<Integer> carried : Arrays.asList(CRUSHER, NECKLACE))
		{
			CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, carried);
			assertTrue(filter.excludesBones());
			assertFalse(filter.excludesAshes());
			ItemTally kept = filter.apply(wyrmLoot());
			assertEquals(0, kept.get(ItemID.WYRM_BONES));
			assertEquals(1, kept.get(ItemID.ABYSSAL_ASHES));
			assertEquals(1, kept.get(ItemID.ASHES));
			assertEquals("noted bones are not crushed", 5, kept.get(ItemID.Cert.DRAGON_BONES));
			assertEquals(300, kept.get(ItemID.COINS));
			assertEquals(4, kept.size());
		}
	}

	@Test
	public void autoWithAnAshSanctifierDropsDemonicAshesOnly()
	{
		CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, SANCTIFIER);
		assertFalse(filter.excludesBones());
		assertTrue(filter.excludesAshes());
		ItemTally kept = filter.apply(wyrmLoot());
		assertEquals(1, kept.get(ItemID.WYRM_BONES));
		assertEquals(0, kept.get(ItemID.ABYSSAL_ASHES));
		assertEquals("plain ashes are not demonic", 1, kept.get(ItemID.ASHES));
	}

	@Test
	public void autoWithBothDropsBonesAndAshes()
	{
		ItemTally kept = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, BOTH).apply(wyrmLoot());
		assertEquals(0, kept.get(ItemID.WYRM_BONES));
		assertEquals(0, kept.get(ItemID.ABYSSAL_ASHES));
		assertEquals(3, kept.size());
	}

	@Test
	public void alwaysExcludeIgnoresWhatIsCarried()
	{
		for (List<Integer> carried : Arrays.asList(NOTHING, CRUSHER, null))
		{
			CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.ALWAYS_EXCLUDE, carried);
			assertTrue(filter.excludesBones());
			assertTrue(filter.excludesAshes());
			assertFalse(filter.keeps(ItemID.WYRM_BONES));
			assertFalse(filter.keeps(ItemID.INFERNAL_ASHES));
			assertTrue(filter.keeps(ItemID.COINS));
		}
		assertFalse(CrushedLootFilter.needsCarriedItems(BonecrusherMode.ALWAYS_EXCLUDE));
	}

	@Test
	public void neverExcludeKeepsEverythingEvenWithACrusher()
	{
		CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.NEVER_EXCLUDE, BOTH);
		assertSame(CrushedLootFilter.KEEP_ALL, filter);
		assertEquals(wyrmLoot(), filter.apply(wyrmLoot()));
		assertFalse(CrushedLootFilter.needsCarriedItems(BonecrusherMode.NEVER_EXCLUDE));
	}

	@Test
	public void nullModeIsAuto()
	{
		assertTrue(CrushedLootFilter.needsCarriedItems(BonecrusherMode.AUTO));
		assertTrue(CrushedLootFilter.needsCarriedItems(null));
		assertTrue(CrushedLootFilter.forDrop(null, CRUSHER).excludesBones());
	}

	@Test
	public void applyLeavesTheInputAloneAndHandlesNull()
	{
		ItemTally loot = wyrmLoot();
		CrushedLootFilter.forDrop(BonecrusherMode.ALWAYS_EXCLUDE, null).apply(loot);
		assertEquals(wyrmLoot(), loot);
		assertTrue(CrushedLootFilter.KEEP_ALL.apply(null).isEmpty());
	}

	@Test
	public void modesShowReadableNames()
	{
		assertEquals("Auto", BonecrusherMode.AUTO.toString());
		assertEquals("Always exclude", BonecrusherMode.ALWAYS_EXCLUDE.toString());
		assertEquals("Never exclude", BonecrusherMode.NEVER_EXCLUDE.toString());
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.Callable;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * Test stand-in for RuneLite's shared {@link ScheduledExecutorService}. Tasks are queued and run only when the test
 * (or {@link PluginHarness}) calls {@link #runPending}, in submission order, on the calling thread. This keeps file
 * IO deterministic while still being asynchronous from the plugin's point of view: work handed to the executor has
 * not happened until it is drained, as in the real client.
 *
 * <p>{@link #submit} returns a {@link java.util.concurrent.FutureTask}, which completes when the task runs, so
 * {@code ClientShutdown.waitFor} sees real completion. Delayed scheduling is not used by the plugin and throws
 * {@link UnsupportedOperationException} so a future use is noticed. After {@link #shutdown()} new tasks are rejected
 * with {@link RejectedExecutionException}, as a stopped executor would.</p>
 */
final class DeterministicExecutor extends AbstractExecutorService implements ScheduledExecutorService
{
	private final Queue<Runnable> tasks = new ArrayDeque<>();
	private boolean shutdown;
	private boolean running;

	@Override
	public synchronized void execute(Runnable command)
	{
		if (shutdown)
		{
			throw new RejectedExecutionException("executor is shut down");
		}
		tasks.add(command);
	}

	/** Number of queued tasks not yet run. */
	synchronized int pendingCount()
	{
		return tasks.size();
	}

	/** Whether a task is running right now (on the draining thread). */
	synchronized boolean isRunningTask()
	{
		return running;
	}

	/**
	 * Runs queued tasks, including ones they queue, until none are left. A task that throws is reported to
	 * {@code onError} and the rest still run.
	 *
	 * @return the number of tasks run
	 */
	int runPending(Consumer<Throwable> onError)
	{
		int ran = 0;
		for (;;)
		{
			final Runnable task;
			synchronized (this)
			{
				task = tasks.poll();
				if (task == null)
				{
					return ran;
				}
				running = true;
			}
			try
			{
				task.run();
			}
			catch (RuntimeException | Error e)
			{
				onError.accept(e);
			}
			finally
			{
				synchronized (this)
				{
					running = false;
				}
			}
			ran++;
		}
	}

	@Override
	public synchronized void shutdown()
	{
		shutdown = true;
	}

	@Override
	public synchronized List<Runnable> shutdownNow()
	{
		shutdown = true;
		final List<Runnable> remaining = new ArrayList<>(tasks);
		tasks.clear();
		return remaining;
	}

	@Override
	public synchronized boolean isShutdown()
	{
		return shutdown;
	}

	@Override
	public synchronized boolean isTerminated()
	{
		return shutdown && tasks.isEmpty() && !running;
	}

	@Override
	public boolean awaitTermination(long timeout, TimeUnit unit)
	{
		return isTerminated();
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
	{
		throw new UnsupportedOperationException("delayed tasks are not supported by the test executor");
	}

	@Override
	public <V> ScheduledFuture<V> schedule(Callable<V> callable, long delay, TimeUnit unit)
	{
		throw new UnsupportedOperationException("delayed tasks are not supported by the test executor");
	}

	@Override
	public ScheduledFuture<?> scheduleAtFixedRate(Runnable command, long initialDelay, long period, TimeUnit unit)
	{
		throw new UnsupportedOperationException("periodic tasks are not supported by the test executor");
	}

	@Override
	public ScheduledFuture<?> scheduleWithFixedDelay(Runnable command, long initialDelay, long delay, TimeUnit unit)
	{
		throw new UnsupportedOperationException("periodic tasks are not supported by the test executor");
	}
}

