package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Ground Items' hidden list as Slayer Ledger reads it: {@link GroundItemsHidden} matches names as
 * {@code GroundItemsPlugin} (RuneLite 1.13.4) does, and {@link HiddenLootResolver} turns names into hidden item ids
 * once per list.
 */
public class GroundItemsHiddenTest
{
	private static GroundItemsHidden hidden(String list)
	{
		return GroundItemsHidden.parse(list, "");
	}

	@Test
	public void exactNamesIgnoreCase()
	{
		GroundItemsHidden list = hidden("Bones, Rune platebody");
		assertTrue(list.hides("Bones"));
		assertTrue(list.hides("bones"));
		assertTrue(list.hides("RUNE PLATEBODY"));
		assertFalse("exact means the whole name", list.hides("Big bones"));
		assertFalse(list.hides("Bone"));
		assertFalse("an unknown name is never hidden", list.hides(null));
	}

	@Test
	public void wildcardsUseRuneLitesMatcher()
	{
		GroundItemsHidden list = hidden("*seed, Clue scroll*, *rune*");
		assertTrue(list.hides("Ranarr seed"));
		assertTrue(list.hides("RANARR SEED"));
		assertTrue(list.hides("Clue scroll (hard)"));
		assertTrue(list.hides("Nature rune"));
		assertTrue(list.hides("Rune platebody"));
		assertFalse(list.hides("Seed pod"));
		assertFalse(list.hides("Bones"));
		// Other regex characters are taken literally.
		assertTrue(hidden("Clue scroll (*)").hides("Clue scroll (elite)"));
		assertFalse(hidden("Coins.*").hides("Coinsxx"));
		assertTrue(hidden("Coins.*").hides("Coins.xx"));
	}

	@Test
	public void entriesAreSplitOnCommasAndTrimmed()
	{
		GroundItemsHidden list = hidden("  Vial ,Ashes,, ,  Jug  ,");
		assertTrue(list.hides("Vial"));
		assertTrue(list.hides("Ashes"));
		assertTrue(list.hides("Jug"));
		assertFalse("blank entries match nothing", list.hides(""));
		assertFalse(list.hides(" "));
		assertEquals("the same list however it is spaced", hidden("Vial, Ashes, Jug"), list);
	}

	@Test
	public void anEmptyListHidesNothing()
	{
		assertSame(GroundItemsHidden.NONE, hidden(""));
		assertSame(GroundItemsHidden.NONE, hidden(" , ,"));
		assertTrue(hidden("").isEmpty());
		assertFalse(hidden("").hides("Bones"));
	}

	@Test
	public void aListNeverEditedIsGroundItemsDefault()
	{
		GroundItemsHidden list = GroundItemsHidden.parse(null, null);
		assertEquals(hidden(GroundItemsHidden.DEFAULT_HIDDEN_ITEMS), list);
		for (String name : Arrays.asList("Vial", "Ashes", "Coins", "Bones", "Bucket", "Jug", "Seaweed"))
		{
			assertTrue(name, list.hides(name));
		}
		assertFalse(list.hides("Big bones"));
	}

	@Test
	public void entriesWithAQuantityConditionAreIgnored()
	{
		GroundItemsHidden list = hidden("Coins < 1000, Bones > 5, Ashes > 0, Vial > 1 2");
		assertFalse("only a stack on the ground can be checked against it", list.hides("Coins"));
		assertFalse(list.hides("Bones"));
		assertTrue("> 0 holds for every stack", list.hides("Ashes"));
		// Ground Items reads an unparsable quantity as "> 0".
		assertTrue(list.hides("Vial"));
		// Text after the < or > that is not a number: no condition, it is all name.
		assertTrue(hidden("Vial>abc").hides("vial>ABC"));
		// A trailing number without < or > is part of the name.
		assertTrue(hidden("Rune 2h sword").hides("Rune 2h sword"));
		assertTrue(hidden("Coins <").hides("Coins <"));
		assertSame(GroundItemsHidden.NONE, hidden("Coins < 1000"));
	}

	@Test
	public void theHighlightedListWinsAsInGroundItems()
	{
		// An exact highlight beats any hide.
		assertFalse(GroundItemsHidden.parse("*", "Dragon bones").hides("Dragon bones"));
		assertTrue(GroundItemsHidden.parse("*", "Dragon bones").hides("Bones"));
		assertFalse(GroundItemsHidden.parse("Bones", "bones").hides("Bones"));
		// A wildcard highlight beats a wildcard hide, but not an exact one.
		assertFalse(GroundItemsHidden.parse("*bones", "Dragon*").hides("Dragon bones"));
		assertTrue(GroundItemsHidden.parse("Dragon bones", "Dragon*").hides("Dragon bones"));
		// A highlight with a quantity condition is ignored too.
		assertTrue(GroundItemsHidden.parse("Coins", "Coins > 10000").hides("Coins"));
	}

	@Test
	public void theSettingAndGroundItemsMustBothBeOn()
	{
		assertSame("setting off", GroundItemsHidden.NONE, GroundItemsHidden.effective(false, null, "Bones", ""));
		assertSame("Ground Items off", GroundItemsHidden.NONE,
			GroundItemsHidden.effective(true, "false", "Bones", ""));
		assertTrue("Ground Items on", GroundItemsHidden.effective(true, "true", "Bones", "").hides("Bones"));
		assertTrue("never turned off: on by default", GroundItemsHidden.effective(true, null, "Bones", "")
			.hides("Bones"));
		assertTrue("never edited: the default list", GroundItemsHidden.effective(true, null, null, null)
			.hides("Coins"));
	}

	@Test
	public void equalListsAreEqual()
	{
		assertEquals(hidden("Bones, *seed"), GroundItemsHidden.parse("Bones,*seed", null));
		assertEquals(hidden("Bones, *seed").hashCode(), hidden("Bones,*seed").hashCode());
		assertNotEquals(hidden("Bones"), hidden("Bones, Ashes"));
		assertNotEquals(GroundItemsHidden.parse("Bones", "Ashes"), hidden("Bones"));
	}

	// ---- HiddenLootResolver and HiddenLoot ----

	@Test
	public void theResolverMatchesEachIdOncePerList()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(526, "Bones");
		names.put(1127, "Rune platebody");
		// A noted item's own name is its unnoted item's.
		names.put(527, "Bones");
		List<Integer> asked = new ArrayList<>();
		HiddenLootResolver resolver = new HiddenLootResolver();
		assertSame("nothing to hide: no names asked", HiddenLoot.NONE,
			resolver.resolve(Arrays.asList(526, 1127), id ->
			{
				asked.add(id);
				return names.get(id);
			}));
		assertTrue(asked.isEmpty());

		assertTrue(resolver.setList(hidden("Bones")));
		assertFalse("the same list again", resolver.setList(hidden("Bones")));
		HiddenLoot result = resolver.resolve(Arrays.asList(526, 527, 1127), id ->
		{
			asked.add(id);
			return names.get(id);
		});
		assertEquals("the note too, not the platebody", HiddenLoot.of(Arrays.asList(526, 527)), result);
		assertEquals(Arrays.asList(526, 527, 1127), asked);

		// Matched once: asked again, no name is looked up.
		resolver.resolve(Arrays.asList(526, 527, 1127), id ->
		{
			asked.add(id);
			return names.get(id);
		});
		assertEquals(3, asked.size());

		// Another list matches afresh.
		assertTrue(resolver.setList(hidden("Rune*")));
		assertEquals(HiddenLoot.of(Collections.singleton(1127)), resolver.resolve(Arrays.asList(526, 1127),
			names::get));
	}

	@Test
	public void anUnknownNameIsNotHiddenUntilItIsKnown()
	{
		Map<Integer, String> names = new HashMap<>();
		HiddenLootResolver resolver = new HiddenLootResolver();
		resolver.setList(hidden("Bones"));
		assertSame(HiddenLoot.NONE, resolver.resolve(Collections.singleton(526), names::get));
		assertSame("a failed lookup is unknown", HiddenLoot.NONE, resolver.resolve(Collections.singleton(526), id ->
		{
			throw new IllegalStateException("no item data");
		}));
		names.put(526, "Bones");
		assertEquals(HiddenLoot.of(Collections.singleton(526)), resolver.resolve(Collections.singleton(526),
			names::get));
	}

	@Test
	public void hiddenLootLeavesItemsOutWithoutChangingTheTally()
	{
		ItemTally loot = new ItemTally();
		loot.add(526, 3);
		loot.add(1127, 1);
		HiddenLoot hidden = HiddenLoot.of(Arrays.asList(526, null));
		ItemTally valued = hidden.valued(loot);
		assertEquals(0, valued.get(526));
		assertEquals(1, valued.get(1127));
		assertEquals("the tally itself is unchanged", 3, loot.get(526));
		assertSame("nothing hidden: the same tally", loot, HiddenLoot.of(Collections.singleton(4151)).valued(loot));
		assertSame(HiddenLoot.NONE, HiddenLoot.of(Collections.emptyList()));
		assertTrue(hidden.leavesOutAny(Arrays.asList(1, 526)));
		assertFalse(hidden.leavesOutAny(Collections.singleton(1)));
	}

	@Test
	public void hiddenCoinsLeaveTheGridButKeepTheirValue()
	{
		ItemTally loot = new ItemTally();
		loot.add(ItemValuation.COINS, 5_000);
		loot.add(526, 3);
		loot.add(1127, 1);
		HiddenLoot coinsAndBones = HiddenLoot.of(Arrays.asList(ItemValuation.COINS, 526));

		ItemTally valued = coinsAndBones.valued(loot);
		assertEquals("coins always count in the value", 5_000, valued.get(ItemValuation.COINS));
		assertEquals("bones are left out", 0, valued.get(526));
		assertEquals(1, valued.get(1127));
		assertFalse(coinsAndBones.isEmpty());

		HiddenLoot coinsOnly = HiddenLoot.of(Collections.singleton(ItemValuation.COINS));
		assertFalse(coinsOnly.isEmpty());
		assertFalse(coinsOnly.leavesOutAny(loot.itemIds()));
		assertSame("hidden coins alone leave nothing out of the value", loot, coinsOnly.valued(loot));

		List<ItemDetails.Row> rows = Arrays.asList(
			ItemDetails.Row.builder().itemId(1127).name("Rune platebody").quantity(1).build(),
			ItemDetails.Row.builder().itemId(526).name("Bones").quantity(3).build(),
			ItemDetails.Row.builder().itemId(ItemValuation.COINS).name("Coins").quantity(5_000).build());
		List<ItemDetails.Row> shown = coinsAndBones.visibleRows(rows);
		assertEquals("coins are hidden from the grid like any item", 1, shown.size());
		assertEquals(1127, shown.get(0).getItemId());
		assertEquals(2, coinsOnly.visibleRows(rows).size());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.events.ConfigChanged;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Ignored loot, multi-bite food and deaths as wired in the plugin ({@link PluginHarness}): the ignored-items setting is
 * read at startUp and on ConfigChanged and applied when loot arrives, with item names read on the client thread;
 * pizzas are counted in bites from the inventory each tick; and local-player deaths count while RUNNING and survive
 * logout and a restart. {@link IgnoredLootTest}, {@link LootFilterTest}, {@link MultiBiteFoodTest} and
 * {@link SessionTrackerCountersTest} cover the rules.
 */
public class HarnessAccuracyTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String EAT = "Eat";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1, "Bury");
		harness.defineItem(ItemID.COINS, "Coins", 1, 1);
		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 40_000, 20);
		harness.defineItem(ItemID.DRAGON_BONES, "Dragon bones", 2_000, 1, "Bury");
		harness.defineNotedItem(ItemID.Cert.DRAGON_BONES, ItemID.DRAGON_BONES);
		harness.defineItem(ItemID.PLAIN_PIZZA, "Plain pizza", 300, 10, EAT);
		harness.defineItem(ItemID.HALF_PLAIN_PIZZA, "1/2 plain pizza", 200, 5, EAT);
		harness.defineItem(ItemID.MEAT_PIE, "Meat pie", 100, 6, EAT);
		harness.defineItem(ItemID.HALF_A_MEAT_PIE, "Half a meat pie", 60, 3, EAT);
		harness.defineItem(ItemID.PIEDISH, "Pie dish", 10, 1);
	}

	private void startRunning(String ignoredLoot)
	{
		harness.config.ignoredLoot = ignoredLoot;
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
	}

	private void killDrops()
	{
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.lootOnNextTick(ItemID.COINS, 100);
		harness.lootOnNextTick(ItemID.RANARR_SEED, 1);
		harness.lootOnNextTick(ItemID.Cert.DRAGON_BONES, 3);
		harness.tick();
	}

	private ItemTally loot()
	{
		return harness.tracker().getLoot();
	}

	// ---- Ignored loot ----

	@Test
	public void theSettingAtStartUpIsApplied()
	{
		startRunning("bones, *SEED");
		killDrops();
		assertEquals(0, loot().get(ItemID.BONES));
		assertEquals(0, loot().get(ItemID.RANARR_SEED));
		assertEquals(100, loot().get(ItemID.COINS));
		assertEquals("Dragon bones is not matched by 'bones'", 3, loot().get(ItemID.Cert.DRAGON_BONES));
	}

	@Test
	public void aChangedSettingAppliesToNewLootOnly()
	{
		startRunning("");
		killDrops();
		assertEquals(1, loot().get(ItemID.BONES));

		harness.setIgnoredLoot("Bones, Dragon bones, " + ItemID.COINS);
		assertEquals("loot already counted is kept", 1, loot().get(ItemID.BONES));
		killDrops();
		assertEquals(1, loot().get(ItemID.BONES));
		assertEquals(100, loot().get(ItemID.COINS));
		assertEquals("a noted drop matches its unnoted name", 3, loot().get(ItemID.Cert.DRAGON_BONES));
		assertEquals(2, loot().get(ItemID.RANARR_SEED));

		harness.setIgnoredLoot("");
		killDrops();
		assertEquals(2, loot().get(ItemID.BONES));

		harness.stop();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(2), record.getLoot().get(ItemID.BONES));
		assertEquals(Long.valueOf(6), record.getLoot().get(ItemID.Cert.DRAGON_BONES));
	}

	@Test
	public void otherSettingsChangesDoNotReparse()
	{
		startRunning("coins");
		// The value changes without a ConfigChanged for its key: the cached list is still used.
		harness.config.ignoredLoot = "";
		harness.post(configChanged(SlayerLedgerConfig.GROUP, "bonecrusherHandling"));
		harness.post(configChanged("lootTracker", SlayerLedgerConfig.IGNORED_LOOT));
		killDrops();
		assertEquals(0, loot().get(ItemID.COINS));
	}

	@Test
	public void ignoredLootByIdMatchesTheNotedDrop()
	{
		startRunning(Integer.toString(ItemID.DRAGON_BONES));
		killDrops();
		assertEquals(0, loot().get(ItemID.Cert.DRAGON_BONES));
		assertEquals(1, loot().get(ItemID.BONES));
	}

	private static ConfigChanged configChanged(String group, String key)
	{
		ConfigChanged event = new ConfigChanged();
		event.setGroup(group);
		event.setKey(key);
		return event;
	}

	// ---- Multi-bite food ----

	@Test
	public void eatingAWholePizzaCostsOnePizza()
	{
		startRunning("");
		harness.setInventory(PluginHarness.item(ItemID.PLAIN_PIZZA, 1));
		harness.tick();
		harness.setInventory(PluginHarness.item(ItemID.HALF_PLAIN_PIZZA, 1));
		harness.tick();
		harness.setInventory();
		harness.tick();

		ItemTally used = harness.tracker().getSupplies();
		assertEquals(2, used.get(ItemID.PLAIN_PIZZA));
		assertEquals(0, used.get(ItemID.HALF_PLAIN_PIZZA));
		harness.stop();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(2), record.getSupplies().get(ItemID.PLAIN_PIZZA));
		assertEquals(Integer.valueOf(2), record.getSupplyDoses().get(ItemID.PLAIN_PIZZA));
		assertEquals("exactly one pizza", Long.valueOf(300), record.getSuppliesGeValue());
	}

	@Test
	public void aHalfPieInTheInventoryAtPlayCostsHalf()
	{
		harness.config.ignoredLoot = "";
		harness.startUp();
		harness.setInventory(PluginHarness.item(ItemID.HALF_A_MEAT_PIE, 1));
		harness.setTask(TASK, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.setInventory(PluginHarness.item(ItemID.PIEDISH, 1));
		harness.tick();

		harness.stop();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(1), record.getSupplies().get(ItemID.MEAT_PIE));
		assertNull("the dish is not a supply", record.getSupplies().get(ItemID.PIEDISH));
		assertEquals("half of the 100 gp pie", Long.valueOf(50), record.getSuppliesGeValue());
	}

	// ---- Deaths ----

	@Test
	public void localPlayerDeathsCountOnlyWhileRunning()
	{
		startRunning("");
		harness.localPlayerDies();
		harness.otherActorDies();
		assertEquals(1, harness.tracker().getDeaths());
		harness.pause();
		harness.localPlayerDies();
		assertEquals("not while paused", 1, harness.tracker().getDeaths());
		assertTrue(harness.play());
		harness.localPlayerDies();
		assertEquals("Superiors: 0 | Deaths: 2 | Bank trips: 0", countsText());
		harness.stop();
		assertEquals(Integer.valueOf(2), harness.onlyRecord(ACCOUNT).getDeaths());
	}

	@Test
	public void deathsSurviveLogoutAndARestart()
	{
		startRunning("");
		harness.localPlayerDies();
		harness.logout();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertNotNull(snapshot);
		assertEquals(Integer.valueOf(1), snapshot.getDeaths());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals(1, harness.tracker().getDeaths());
		assertTrue(harness.play());
		harness.localPlayerDies();
		harness.stop();
		assertEquals(Integer.valueOf(2), harness.onlyRecord(ACCOUNT).getDeaths());
	}

	@Test
	public void deathDuringTheCompletionGraceWindowIsNotAdded()
	{
		startRunning("");
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.localPlayerDies();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(Integer.valueOf(0), harness.onlyRecord(ACCOUNT).getDeaths());
	}

	private String countsText()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getCountsText();
		});
		return text[0];
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The skip and block log as wired in the plugin ({@link PluginHarness}): assignments that end without a session are
 * saved beside the records with their outcome, never for a played task, never from a login resync or a hop, bounded,
 * deletable, shown only in the collapsed "Skipped / blocked" section and never counted as played tasks.
 * {@link AssignmentWatchTest}, {@link AssignmentOutcomeTest} and {@link AssignmentLogTest} cover the rules.
 */
public class HarnessAssignmentLogTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int DEMONS = 42;
	private static final int CAVE_HORRORS = 80;
	private static final int DURADEL = 5;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(DEMONS, "Abyssal demons", 120, 120);
		harness.setAssignment(DURADEL, 0, null);
		harness.setSlayerPoints(500);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Ticks out the decision window after an end. */
	private void settle()
	{
		harness.ticks(AssignmentWatch.END_WINDOW_TICKS + 1);
	}

	private void skip(int cost)
	{
		harness.setRemaining(0);
		harness.setSlayerPoints(500 - cost);
	}

	private AssignmentEntry onlyEntry()
	{
		final List<AssignmentEntry> entries = harness.assignments(ACCOUNT);
		assertEquals(entries.toString(), 1, entries.size());
		return entries.get(0);
	}

	private <T> T onEdt(java.util.function.Supplier<T> read)
	{
		final List<T> result = new ArrayList<>(1);
		harness.onEdt(() -> result.add(read.get()));
		return result.get(0);
	}

	private List<String> assignmentRows()
	{
		return onEdt(() -> harness.ui().getAssignments().getRows());
	}

	@Test
	public void aSkipIsSavedAndShownCollapsed()
	{
		skip(30);
		settle();
		AssignmentEntry e = onlyEntry();
		assertEquals(AssignmentOutcome.SKIPPED, e.getOutcome());
		assertEquals(Integer.valueOf(-30), e.getPointsChange());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals(Integer.valueOf(DEMONS), e.getCreatureId());
		assertEquals(Integer.valueOf(120), e.getOriginalAmount());
		assertEquals(Integer.valueOf(DURADEL), e.getSlayerMaster());
		assertTrue(e.getEndedAt() > 0);
		assertTrue("not a played task", harness.records(ACCOUNT).isEmpty());

		assertEquals("collapsed by default", "Skipped / blocked (1) | Show",
			onEdt(() -> harness.ui().getAssignments().getHeaderText()));
		assertFalse(onEdt(() -> harness.ui().getAssignments().isExpanded()));
		assertTrue(assignmentRows().isEmpty());

		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		assertTrue(onEdt(() -> harness.ui().getAssignments().isExpanded()));
		List<String> rows = assignmentRows();
		assertEquals(1, rows.size());
		assertTrue(rows.get(0), rows.get(0).startsWith("Abyssal demons | Skipped \u00b7 "));
		assertTrue(rows.get(0), rows.get(0).contains("<br>Master: Duradel/Kuradal<br>Type: Regular<br>Assigned: 120"
			+ "<br>Points: -30</html>"));
		assertEquals("Saved tasks: 0", onEdt(() -> harness.ui().getSavedTasksText()));
		assertEquals(Arrays.asList(LedgerHistory.ALL), onEdt(() -> harness.ui().getHistory().getFilterOptions()));
		assertTrue(onEdt(() -> harness.ui().getHistory().getValuesText()).isEmpty());
	}

	@Test
	public void aBlockIsSaved()
	{
		skip(100);
		harness.setVarbit(VarbitID.SLAYER_BLOCKED_DURADEL_1, DEMONS);
		settle();
		assertEquals(AssignmentOutcome.BLOCKED, onlyEntry().getOutcome());
		assertEquals(Integer.valueOf(-100), onlyEntry().getPointsChange());
	}

	@Test
	public void aBlockSeenInAnOldBlockedVarpIsSaved()
	{
		skip(100);
		harness.setVarp(VarPlayerID.SLAYER_REWARDS_BLOCKED_2, DEMONS);
		settle();
		assertEquals(AssignmentOutcome.BLOCKED, onlyEntry().getOutcome());
	}

	@Test
	public void aTuraelResetIsSaved()
	{
		harness.setTask(6, "Cows", 20, 20);
		harness.setAssignment(1, 0, null);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 0);
		settle();
		AssignmentEntry e = onlyEntry();
		assertEquals(AssignmentOutcome.RESET, e.getOutcome());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals("the old task's master", Integer.valueOf(DURADEL), e.getSlayerMaster());
		assertEquals(Integer.valueOf(0), e.getPointsChange());
	}

	@Test
	public void aCompletionWithoutASessionIsSaved()
	{
		harness.completeTask(15);
		settle();
		AssignmentEntry e = onlyEntry();
		assertEquals(AssignmentOutcome.COMPLETED, e.getOutcome());
		assertEquals(Integer.valueOf(15), e.getPointsChange());
		assertTrue(harness.records(ACCOUNT).isEmpty());
	}

	@Test
	public void anUnexplainedEndIsSavedAsUnknownWhenTheNextTaskAppears()
	{
		harness.setRemaining(0);
		settle();
		harness.ticks(10);
		assertTrue("waits for the next task", harness.assignments(ACCOUNT).isEmpty());
		harness.setTask(CAVE_HORRORS, "Cave horrors", 150, 150);
		harness.tick();
		assertEquals(AssignmentOutcome.UNKNOWN, onlyEntry().getOutcome());
	}

	@Test
	public void aCompletedPlayedTaskGetsNoEntry()
	{
		assertTrue(harness.play());
		harness.setRemaining(119);
		harness.tick();
		harness.completeTask(15);
		settle();
		assertTrue(harness.onlyRecord(ACCOUNT).isCompleted());
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aPartialPlayedTaskGetsNoEntryWhenSkippedLater()
	{
		assertTrue(harness.play());
		harness.setRemaining(100);
		harness.tick();
		harness.stop();
		assertTrue(harness.onlyRecord(ACCOUNT).isPartial());
		harness.ticks(5);
		skip(30);
		settle();
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aRunningSessionsTaskSkippedGetsNoEntry()
	{
		assertTrue(harness.play());
		harness.tick();
		skip(30);
		settle();
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aTaskChangedDuringASessionGetsNoEntry()
	{
		assertTrue(harness.play());
		harness.tick();
		harness.setTask(6, "Cows", 20, 20);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 0);
		settle();
		assertTrue("the session was saved as partial", harness.onlyRecord(ACCOUNT).isPartial());
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aTaskPlayedInAnEarlierRunGetsNoEntry()
	{
		assertTrue(harness.play());
		harness.setRemaining(100);
		harness.tick();
		harness.stop();
		// The client is restarted: the plugin forgets what it watched.
		harness.shutDown();
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		skip(30);
		settle();
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void anUnplayedTaskFirstSeenAtAStartIsStillSaved()
	{
		harness.shutDown();
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		skip(30);
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, onlyEntry().getOutcome());
	}

	@Test
	public void aLoginResyncMakesNoEntry()
	{
		harness.logout();
		// Skipped and reassigned on another client while logged out here.
		harness.setTask(CAVE_HORRORS, "Cave horrors", 150, 150);
		harness.setSlayerPoints(470);
		harness.loginAndSettle(ACCOUNT);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void varpsSyncingAfterALoginMakeNoEntry()
	{
		harness.logout();
		harness.setRemaining(0);
		harness.setSlayerPoints(0);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(3);
		harness.setRemaining(120);
		harness.setSlayerPoints(500);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aHopMakesNoEntry()
	{
		harness.hop();
		harness.setRemaining(0);
		harness.setSlayerPoints(0);
		harness.ticks(PluginHarness.SETTLE_TICKS + 2);
		harness.setRemaining(120);
		harness.setSlayerPoints(500);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aSkipJustBeforeALogoutIsDropped()
	{
		skip(30);
		harness.tick();
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		settle();
		harness.ticks(10);
		assertTrue("an undecided end is dropped, not guessed", harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void theNewestEntriesAreKept() throws IOException
	{
		harness.logout();
		final StringBuilder json = new StringBuilder("{\"schemaVersion\":2,\"records\":[],\"assignments\":[");
		for (int i = 0; i < AssignmentLog.MAX_ENTRIES; i++)
		{
			json.append(i == 0 ? "" : ",").append("{\"id\":\"old").append(i).append("\",\"monster\":\"Cows\","
				+ "\"endedAt\":").append(1_000 + i).append(",\"outcome\":\"SKIPPED\"}");
		}
		json.append("]}");
		writeLedger(json.toString());
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Skipped / blocked (500) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));

		skip(30);
		settle();
		final List<AssignmentEntry> entries = harness.assignments(ACCOUNT);
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		assertEquals("the oldest went", "old1", entries.get(0).getId());
		assertEquals("Abyssal demons", entries.get(entries.size() - 1).getMonster());
		assertEquals("Skipped / blocked (500) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));
	}

	@Test
	public void anEntryCanBeDeleted()
	{
		skip(30);
		settle();
		final String id = onlyEntry().getId();
		harness.deleteAssignment(ACCOUNT, id);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
		assertEquals("Skipped / blocked (0) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));
		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		assertTrue(assignmentRows().isEmpty());
	}

	@Test
	public void deletingAnEntryKeepsTheRecords()
	{
		assertTrue(harness.play());
		harness.setRemaining(100);
		harness.tick();
		harness.stop();
		harness.setTask(CAVE_HORRORS, "Cave horrors", 150, 150);
		harness.ticks(2);
		skip(30);
		settle();
		harness.deleteAssignment(ACCOUNT, onlyEntry().getId());
		assertEquals(1, harness.records(ACCOUNT).size());
		assertEquals("Saved tasks: 1", onEdt(() -> harness.ui().getSavedTasksText()));
	}

	@Test
	public void anOldLedgerFileLoadsUnchanged() throws IOException
	{
		harness.logout();
		final String old = "{\"schemaVersion\":2,\"records\":[{\"id\":\"r1\",\"monster\":\"Kraken\",\"creatureId\":"
			+ DEMONS + ",\"initialAmount\":3,\"kills\":3,\"activeMillis\":60000,\"startedAt\":1000,\"endedAt\":61000,"
			+ "\"completed\":true,\"partial\":false}]}";
		writeLedger(old);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Saved tasks: 1", onEdt(() -> harness.ui().getSavedTasksText()));
		assertEquals("Skipped / blocked (0) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));
		assertEquals("loading never rewrites the file", old, readLedger());

		skip(30);
		settle();
		assertEquals(1, harness.records(ACCOUNT).size());
		assertEquals("Kraken", harness.onlyRecord(ACCOUNT).getMonster());
		assertEquals(1, harness.assignments(ACCOUNT).size());
	}

	@Test
	public void anotherAccountsTaskIsNotCarriedOver()
	{
		harness.logout();
		harness.setSlayerPoints(470);
		harness.setRemaining(0);
		harness.loginAndSettle(PluginHarness.OTHER_ACCOUNT);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
		assertTrue(harness.assignments(PluginHarness.OTHER_ACCOUNT).isEmpty());
	}

	private Path ledgerPath()
	{
		return harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json");
	}

	private void writeLedger(String json) throws IOException
	{
		Files.write(ledgerPath(), json.getBytes(StandardCharsets.UTF_8));
	}

	private String readLedger() throws IOException
	{
		return new String(Files.readAllBytes(ledgerPath()), StandardCharsets.UTF_8);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * The new-assignment chat preview as wired in the plugin ({@link PluginHarness}): one line for a task assigned
 * while the plugin watches, from the same statistics as the History estimate; none for a task already there at a
 * login, hop or restore, none without history, none with the setting off. {@link AssignmentPreviewMessageTest} covers
 * the line.
 */
public class HarnessAssignmentPreviewTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final long MINUTE = 60_000L;
	private static final int DEMONS = 42;
	private static final int GARGOYLES = 46;
	private static final int CATACOMBS = 6_557;
	private static final int UNNAMED = 13_623;
	/** The line for 20 Abyssal demons from the three saved tasks anywhere. */
	private static final String LINE = "Abyssal demons (20): ~0:20:00 · +180K (GE) · ~2 bank trips (from 3 tasks)";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp() throws IOException
	{
		save(task(null), task(null), task(null));
		SavedItems.define(harness);
		harness.startUp();
		harness.setInventory();
		harness.setPlayerRegion(UNNAMED);
	}

	/**
	 * A completed Abyssal demons task: 10 kills in 10 minutes, loot 100K GE, supplies 10K, 1 bank trip; with its items
	 * ({@link SavedItems}).
	 */
	private static LedgerRecord task(String location)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId("task-" + System.nanoTime());
		record.setCreatureId(DEMONS);
		record.setMonster("Abyssal demons");
		record.setKills(10);
		record.setActiveMillis(10 * MINUTE);
		record.setCompleted(true);
		record.setLootGeValue(100_000L);
		record.setLootHaValue(200_000L);
		record.setSuppliesGeValue(10_000L);
		record.setBankTrips(1);
		record.setLocation(location);
		return SavedItems.withItems(record);
	}

	/** Saves the records to the account's ledger file, read when the account logs in. */
	private void save(LedgerRecord... records) throws IOException
	{
		LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(harness.ledgerDirectory().toPath()),
			harness.gson);
		for (LedgerRecord record : records)
		{
			store.append(ACCOUNT, record);
		}
	}

	/** Logs in with no task, and lets the plugin's post-login reading see that there is none. */
	private void loginWithoutTask()
	{
		harness.setRemaining(0);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(AssignmentWatch.SYNC_MAX_TICKS);
	}

	/** A master assigns a task, seen on the next tick. */
	private void assign(int taskId, String name, int amount)
	{
		harness.setTask(taskId, name, amount, amount);
		harness.tick();
	}

	private List<String> lines()
	{
		ArgumentCaptor<QueuedMessage> messages = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, atLeast(0)).queue(messages.capture());
		for (QueuedMessage message : messages.getAllValues())
		{
			assertEquals(ChatMessageType.CONSOLE, message.getType());
			assertEquals("Slayer Ledger", message.getName());
		}
		return messages.getAllValues().stream().map(QueuedMessage::getRuneLiteFormattedMessage)
			.collect(Collectors.toList());
	}

	private void assertNoLine()
	{
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
	}

	@Test
	public void aNewAssignmentWithHistoryPostsOneLine()
	{
		loginWithoutTask();
		assign(DEMONS, "Abyssal demons", 20);

		assertEquals(Collections.singletonList(LINE), lines());
		// Seen again on every tick, and through a kill: still once. The idle kill also posts the not-tracking line.
		harness.ticks(5);
		harness.setRemaining(19);
		harness.ticks(2);
		assertEquals(Arrays.asList(LINE, "Kill not counted: Slayer Ledger isn't tracking. Press Play in the sidebar."),
			lines());
	}

	@Test
	public void aTaskAfterACompletedOneIsNewToo()
	{
		harness.setTask(GARGOYLES, "Gargoyles", 5, 5);
		harness.loginAndSettle(ACCOUNT);
		harness.completeTask();
		harness.ticks(AssignmentWatch.END_WINDOW_TICKS + 1);
		assign(DEMONS, "Abyssal demons", 20);

		assertEquals(Collections.singletonList(LINE), lines());
	}

	@Test
	public void noHistoryPostsNothing()
	{
		loginWithoutTask();
		assign(GARGOYLES, "Gargoyles", 20);
		harness.ticks(3);

		assertNoLine();
		final AtomicBoolean pending = new AtomicBoolean(true);
		harness.onEdt(() -> pending.set(harness.historyModel().isAssignmentPreviewPending()));
		assertFalse("dropped, not waiting", pending.get());
	}

	@Test
	public void aTaskAlreadyAssignedAtLoginPostsNothing()
	{
		harness.setTask(DEMONS, "Abyssal demons", 20, 20);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(5);

		assertNoLine();
	}

	@Test
	public void aRelogOrHopWithTheTaskStillAssignedPostsNothingMore()
	{
		loginWithoutTask();
		assign(DEMONS, "Abyssal demons", 20);
		verify(harness.chatMessageManager, times(1)).queue(any(QueuedMessage.class));

		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS + 3);
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(3);

		verify(harness.chatMessageManager, times(1)).queue(any(QueuedMessage.class));
	}

	@Test
	public void aRestoredSessionPostsNothing()
	{
		harness.setTask(DEMONS, "Abyssal demons", 20, 20);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.setRemaining(19);
		harness.tick();
		harness.logout();
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(5);

		assertEquals("restored", SessionTracker.State.PAUSED, harness.sessionState());
		assertNoLine();
	}

	@Test
	public void aPluginStartWhileLoggedInPostsNothing()
	{
		harness.shutDown();
		harness.setTask(DEMONS, "Abyssal demons", 20, 20);
		harness.setAccountHash(ACCOUNT);
		harness.setGameStateSilently(GameState.LOGGED_IN);
		harness.startUp();
		harness.ticks(5);

		assertNoLine();
	}

	@Test
	public void theSettingOffPostsNothing()
	{
		harness.config.assignmentPreview = false;
		loginWithoutTask();
		assign(DEMONS, "Abyssal demons", 20);
		harness.ticks(3);

		assertNoLine();
	}

	@Test
	public void aNewAssignmentBeforeTheHistoryLoadedIsPostedOnceItHas()
	{
		loginWithoutTask();
		// As while the ledger is still being read.
		harness.onEdt(() -> harness.historyModel().clearRecords(ACCOUNT, SlayerLedgerPanel.LOADING_MESSAGE));
		assign(DEMONS, "Abyssal demons", 20);
		harness.ticks(2);
		assertNoLine();
		final AtomicBoolean pending = new AtomicBoolean();
		harness.onEdt(() -> pending.set(harness.historyModel().isAssignmentPreviewPending()));
		assertTrue("waits for the records", pending.get());

		final List<LedgerRecord> records = harness.records(ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, records));
		harness.drain();
		// And still once when the records are shown again.
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, records));
		harness.ticks(2);
		assertEquals(Collections.singletonList(LINE), lines());
	}

	@Test
	public void theHistoryWhereThePlayerIsComesFirst() throws IOException
	{
		save(task("Catacombs of Kourend"));
		harness.setRsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX + CATACOMBS,
			"Catacombs of Kourend");
		harness.setPlayerRegion(CATACOMBS);
		loginWithoutTask();
		assign(DEMONS, "Abyssal demons", 20);

		assertEquals(Collections.singletonList(
			"Abyssal demons (20): ~0:20:00 · +180K (GE) · ~2 bank trips (from 1 task at Catacombs of Kourend)"), lines());
	}

	@Test
	public void aTypedLocationNameIsNotReadAsTags() throws IOException
	{
		save(task("<col=ff0000>Cave"));
		harness.setRsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX + CATACOMBS,
			"<col=ff0000>Cave");
		harness.setPlayerRegion(CATACOMBS);
		loginWithoutTask();
		assign(DEMONS, "Abyssal demons", 20);

		assertEquals(Collections.singletonList(
			"Abyssal demons (20): ~0:20:00 · +180K (GE) · ~2 bank trips (from 1 task at <lt>col=ff0000<gt>Cave)"),
			lines());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.clearInvocations;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * A logout or world hop pauses the running session: the overlay shows the paused indicator, and one chat line
 * on the next login says why. Resuming stays manual. {@link OverlayRowsTest} covers the indicator row itself.
 */
public class HarnessAutoPauseTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 12, 12);
		harness.loginAndSettle(ACCOUNT);
	}

	/** The overlay's rows now, with every row setting on. */
	private List<OverlayRows.Row> rows()
	{
		return OverlayRows.rows(harness.overlayData(), true, true, true, true);
	}

	private boolean showsPaused()
	{
		List<OverlayRows.Row> rows = rows();
		return !rows.isEmpty() && OverlayRows.PAUSED_LABEL.equals(rows.get(0).getLabel()) && rows.get(0).isWarning();
	}

	/** The one chat line queued so far (fails unless exactly one was). */
	private QueuedMessage onlyChatLine()
	{
		ArgumentCaptor<QueuedMessage> message = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, times(1)).queue(message.capture());
		return message.getValue();
	}

	@Test
	public void hopShowsPausedAndPostsOneChatLineAfterLogin()
	{
		assertTrue(harness.play());
		assertFalse("running shows no indicator", showsPaused());

		harness.setGameState(GameState.HOPPING);
		assertEquals(SessionTracker.State.PAUSED, harness.tracker().getState());
		assertTrue("indicator shown as soon as the hop pauses", showsPaused());
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));

		harness.setGameState(GameState.LOADING);
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
		harness.setGameState(GameState.LOGGED_IN);
		harness.ticks(PluginHarness.SETTLE_TICKS);

		assertTrue(showsPaused());
		QueuedMessage message = onlyChatLine();
		assertEquals(ChatMessageType.CONSOLE, message.getType());
		assertEquals("Slayer Ledger", message.getName());
		assertEquals("Slayer Ledger paused (world hop). Press Resume to keep tracking.",
			message.getRuneLiteFormattedMessage());
		assertEquals("resume stays manual", SessionTracker.State.PAUSED, harness.tracker().getState());

		// Another hop or login without a new pause (the session is already paused) posts nothing more.
		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		onlyChatLine();
		assertTrue(showsPaused());

		assertTrue("Resume still works", harness.play());
		assertFalse("indicator gone once resumed", showsPaused());
		onlyChatLine();
	}

	@Test
	public void logoutPostsOneChatLineOnTheNextLogin()
	{
		assertTrue(harness.play());
		harness.logout();
		assertEquals(SessionTracker.State.PAUSED, harness.tracker().getState());
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));

		harness.loginAndSettle(ACCOUNT);
		assertEquals("Slayer Ledger paused (logged out). Press Resume to keep tracking.",
			onlyChatLine().getRuneLiteFormattedMessage());
		assertTrue(showsPaused());

		clearInvocations(harness.chatMessageManager);
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
	}

	@Test
	public void manualPauseShowsTheIndicatorButPostsNoChatLine()
	{
		assertTrue(harness.play());
		harness.pause();
		assertTrue(showsPaused());

		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertTrue(showsPaused());
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
	}

	@Test
	public void idleSessionPostsNothingOnAHop()
	{
		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals(SessionTracker.State.IDLE, harness.tracker().getState());
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
	}

	@Test
	public void taskChangedWhileLoggedOutPostsNoPausedLine()
	{
		assertTrue(harness.play());
		harness.logout();
		// The task changed elsewhere (another client) before this login: the restore check ends the session.
		harness.setTask(43, "Black demons", 30, 30);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(PluginHarness.SETTLE_TICKS);

		assertFalse("the restore check ended the session", harness.tracker().getState() == SessionTracker.State.PAUSED);
		ArgumentCaptor<QueuedMessage> messages = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, atLeast(0)).queue(messages.capture());
		for (QueuedMessage message : messages.getAllValues())
		{
			assertFalse(message.getRuneLiteFormattedMessage(),
				String.valueOf(message.getRuneLiteFormattedMessage()).contains("paused"));
		}
	}

	@Test
	public void stoppedBeforeTheLoginPostsNothing()
	{
		assertTrue(harness.play());
		harness.setGameState(GameState.HOPPING);
		// Stopped from the sidebar before the next login: nothing is left to tell.
		harness.stop();
		harness.setGameState(GameState.LOADING);
		harness.setGameState(GameState.LOGGED_IN);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Boss kill counts as wired in the plugin ({@link PluginHarness}): kill count messages counted while the session runs
 * (or a completed task waits for its last loot), for a boss task or a regular task named after the boss, the boss
 * task's name, the live panel, the saved record and its history tooltip, and the active session file.
 * {@link KillCountMessageTest} and {@link BossKillCountsTest} cover the rules.
 */
public class HarnessBossKillCountTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int VORKATH_BOSS_ID = 31;
	private static final int DKS_BOSS_ID = 5;
	private static final int JAD_TASK = 93;
	private static final int REGULAR_TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 10);
	}

	private static String kc(String boss, String count)
	{
		return "Your " + boss + " kill count is: <col=ff0000>" + count + "</col>.";
	}

	private void chat(String message)
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, message);
	}

	private List<String> liveLines()
	{
		final List<?>[] lines = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			lines[0] = harness.ui().getTaskLootLines();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) lines[0];
		return result;
	}

	private String liveTooltip()
	{
		final String[] text = new String[1];
		harness.onEdt(() -> text[0] = harness.ui().getTaskLootTooltip());
		return text[0];
	}

	private List<String> historyText()
	{
		final List<?>[] rows = new List<?>[1];
		harness.onEdt(() -> rows[0] = harness.ui().getHistory().getValuesText());
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) rows[0];
		return result;
	}

	@Test
	public void bossTaskCountsItsBossWhileRunning()
	{
		harness.setBossTask(VORKATH_BOSS_ID, "Vorkath", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		chat(kc("Vorkath", "140"));
		assertTrue(harness.play());
		assertNull("nothing to show yet; idle messages don't count", liveLines());

		chat(kc("Vorkath", "141"));
		chat("Your <col=ff0000>Vorkath</col> kill count is: <col=ff0000>1,142</col>.");
		chat("Your Prifddinas Agility Course lap count is: @mes_hl_red@2</col>.");
		harness.chat(ChatMessageType.PUBLICCHAT, kc("Vorkath", "2000"));
		assertEquals(Collections.singletonList("Boss KC: 1,142 (+2)"), liveLines());
		assertEquals("<html>Boss KC: 1,142 (+2)</html>", liveTooltip());

		harness.stop();
		assertNull("hidden once the session ends", liveLines());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals("the boss task is named after its boss", "Vorkath", record.getMonster());
		assertEquals(Collections.singletonList(new BossKillCount("Vorkath", 141, 1142, 2)), record.getBossKillCounts());
		String row = historyText().get(0);
		assertTrue(row, row.contains("<br>Type: Boss<br>Boss KC: 1,142 (+2)"));
	}

	@Test
	public void bossTaskWithSeveralBossNamesListsEach()
	{
		harness.setBossTask(DKS_BOSS_ID, "Dagannoth Kings", 5, 5);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		chat(kc("Dagannoth Rex", "50"));
		chat(kc("Dagannoth Prime", "20"));
		chat(kc("Dagannoth Rex", "51"));
		assertEquals(Arrays.asList("Dagannoth Rex KC: 51 (+2)", "Dagannoth Prime KC: 20 (+1)"), liveLines());

		harness.stop();
		assertEquals(2, harness.onlyRecord(ACCOUNT).getBossKillCounts().size());
		String row = historyText().get(0);
		assertTrue(row, row.contains("<br>Dagannoth Rex KC: 51 (+2)<br>Dagannoth Prime KC: 20 (+1)"));
	}

	@Test
	public void regularTaskCountsOnlyTheBossItIsNamedAfter()
	{
		harness.setTask(JAD_TASK, "TzTok-Jad", 1, 1);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		chat(kc("Vorkath", "141"));
		assertNull("another boss: ignored on a regular task", liveLines());
		chat(kc("TzTok-Jad", "2"));
		assertEquals(Collections.singletonList("Boss KC: 2 (+1)"), liveLines());

		harness.stop();
		assertEquals(Collections.singletonList(new BossKillCount("TzTok-Jad", 2, 2, 1)),
			harness.onlyRecord(ACCOUNT).getBossKillCounts());
	}

	@Test
	public void regularTaskWithoutABossNameIgnoresKillCounts()
	{
		harness.setTask(REGULAR_TASK, "Abyssal demons", 50, 50);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		chat(kc("Abyssal Sire", "12"));
		assertNull(liveLines());
		harness.stop();
		assertNull(harness.onlyRecord(ACCOUNT).getBossKillCounts());
		assertFalse(historyText().get(0).contains("KC"));
	}

	@Test
	public void messagesWhilePausedDoNotCount()
	{
		harness.setBossTask(VORKATH_BOSS_ID, "Vorkath", 5, 5);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		chat(kc("Vorkath", "141"));
		harness.pause();
		chat(kc("Vorkath", "142"));
		chat(kc("Vorkath", "143"));
		assertEquals("paused: nothing counted", Collections.singletonList("Boss KC: 141 (+1)"), liveLines());

		assertTrue(harness.play());
		chat(kc("Vorkath", "144"));
		assertEquals("the latest count includes the paused kills; the gain doesn't",
			Collections.singletonList("Boss KC: 144 (+2)"), liveLines());
	}

	@Test
	public void finalKillCountDuringTheGraceWindowGoesToTheCompletedTask()
	{
		harness.setTask(JAD_TASK, "TzTok-Jad", 1, 1);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		// The player gets a new task and presses Play before the final KC message arrives.
		harness.setTask(JAD_TASK, "TzTok-Jad", 1, 1);
		assertTrue("a new session started", harness.play());
		chat(kc("TzTok-Jad", "3"));
		chat(kc("Vorkath", "141"));
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Collections.singletonList(new BossKillCount("TzTok-Jad", 3, 3, 1)), record.getBossKillCounts());
	}

	@Test
	public void activeSessionKeepsItsKillCountsAcrossARestart()
	{
		harness.setBossTask(VORKATH_BOSS_ID, "Vorkath", 5, 5);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		chat(kc("Vorkath", "141"));
		harness.logout();
		harness.shutDown();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertEquals(Collections.singletonList(new BossKillCount("Vorkath", 141, 141, 1)),
			snapshot.getBossKillCounts());

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals(Collections.singletonList("Boss KC: 141 (+1)"), liveLines());

		assertTrue(harness.play());
		chat(kc("Vorkath", "142"));
		harness.stop();
		assertEquals(Collections.singletonList(new BossKillCount("Vorkath", 141, 142, 2)),
			harness.onlyRecord(ACCOUNT).getBossKillCounts());
	}

	@Test
	public void olderRecordsStillLoadWithoutKillCounts() throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		String json = "{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\",\"monster\":\"Vorkath\","
			+ "\"creatureId\":-33,\"initialAmount\":3,\"kills\":3,\"activeMillis\":60000,\"startedAt\":1000,"
			+ "\"endedAt\":61000,\"completed\":true,\"partial\":false}]}";
		Files.write(harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json"), json.getBytes(StandardCharsets.UTF_8));

		harness.loginAndSettle(ACCOUNT);
		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(1, records.size());
		assertNull(records.get(0).getBossKillCounts());
		String row = historyText().get(0);
		assertFalse(row, row.contains("KC"));
		assertTrue("unchanged: " + row, row.endsWith("<br>Deaths: -<br>Type: Boss</html>"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Rule;
import org.junit.Test;

/**
 * The plugin started with neither bundled Wiki resource (the drop snapshot and the task location list), as it would
 * ship if the CC BY-NC-SA data had to be left out: the luck meter says its data is unavailable, the "Name this
 * location" prompt suggests nothing, and nothing fails ({@link PluginHarness} fails the test on any swallowed error).
 */
public class HarnessBundledDataMissingTest
{
	private static final int TASK = 42;
	private static final int SMOKE = 12_946;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void thePluginWorksWithoutEitherBundledResource()
	{
		harness.plugin.setLuckSnapshotResource("missing-drop-snapshot.json");
		harness.startUp();
		harness.onEdt(() -> harness.ui().getLocationPrompt().setTaskLocationsResource("missing-task-locations.json"));
		harness.setInventory();
		harness.setTask(TASK, "Dust devils", 20, 20);
		harness.setPlayerRegion(SMOKE);
		harness.loginAndSettle(PluginHarness.ACCOUNT);

		// The location prompt still appears for a new place, with no suggestions, and still saves a typed name.
		assertTrue(harness.play());
		harness.setRemaining(harness.tracker().getCurrentRemaining() - 1);
		harness.tick();
		final int[] region = new int[1];
		harness.onEdt(() -> region[0] = harness.ui().getLocationPrompt().getRegion());
		assertEquals(SMOKE, region[0]);
		final AtomicReference<List<String>> suggestions = new AtomicReference<>();
		harness.onEdt(() -> suggestions.set(harness.ui().getLocationPrompt().getSuggestions()));
		assertEquals(Collections.emptyList(), suggestions.get());
		harness.onEdt(() -> harness.ui().getLocationPrompt().save("Smoke Dungeon"));
		harness.drain();
		assertEquals("Smoke Dungeon", harness.rsProfileConfig(SlayerLedgerConfig.GROUP,
			SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX + SMOKE));

		// The luck meter shows only that its data is unavailable, even with loot history to compare.
		LedgerRecord record = new LedgerRecord();
		record.setMonster("Abyssal demons");
		record.setKills(512);
		record.setCompleted(true);
		record.setPartial(false);
		record.setLoot(Collections.singletonMap(1001, 1L));
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT,
			Collections.singletonList(record)));
		harness.onEdt(() -> harness.ui().getLuckMeter().clickTitle());
		harness.drain();
		final AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() -> rows.set(harness.ui().getLuckMeter().getRows()));
		assertEquals(Collections.singletonList("Luck meter data unavailable"), rows.get());

		harness.shutDown();
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Cannon tasks as wired in the plugin ({@link PluginHarness}): once the running session fires a cannonball (the
 * cannon's loaded ammo goes down, as the supplies diff counts it), the task box and the overlay's Task row add
 * "(cannon)", the History estimate and the historical time left (sidebar and overlay alike) narrow from every task
 * to cannon tasks when the history has some, and the saved task is shown as its own monster in the History list and
 * Trends. Picking the cannon up returns the cannonballs not fired, also when tracking started with the cannon already
 * loaded with granite cannonballs. {@link CannonTaskGroupingTest} covers the rules.
 */
public class HarnessCannonTaskTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 49;
	private static final String DEVILS = "Dust devils";
	private static final String CANNON = DEVILS + " (cannon)";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private final AtomicLong now = new AtomicLong(1_000_000L);
	/** Cannonballs loaded in the cannon. */
	private int loaded;

	@Before
	public void setUp()
	{
		harness.defineItem(SupplyTracker.CANNONBALL, "Cannonball", 200, 1);
		harness.defineItem(SupplyTracker.GRANITE_CANNONBALL, "Granite cannonball", 400, 1);
		harness.startUp();
		harness.setInventory(PluginHarness.item(SupplyTracker.CANNONBALL, 100));
		harness.setTrackerClock(now::get);
		harness.setTask(TASK, DEVILS, 5, 5);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Sets up the cannon and loads 30 cannonballs from the inventory: moved, not used. */
	private void setUpCannon()
	{
		harness.setVarp(VarPlayerID.DROPCANNON, 4);
		harness.tick();
		harness.setInventory(PluginHarness.item(SupplyTracker.CANNONBALL, 70));
		loaded = 30;
		harness.setVarp(VarPlayerID.ROCKTHROWER, loaded);
		harness.tick();
	}

	/** Picks the cannon up: its loaded cannonballs go back to the inventory on the same tick. */
	private void pickUpCannon()
	{
		harness.setInventory(PluginHarness.item(SupplyTracker.CANNONBALL, 70 + loaded));
		loaded = 0;
		harness.setVarp(VarPlayerID.ROCKTHROWER, 0);
		harness.setVarp(VarPlayerID.DROPCANNON, 0);
		harness.tick();
	}

	/**
	 * sets up the cannon and loads 30 granite cannonballs, then restarts the plugin, so tracking starts with the
	 * cannon already loaded and the new supplies tracker never saw which type went in.
	 */
	private void restartWithLoadedGraniteCannon()
	{
		harness.setInventory(PluginHarness.item(SupplyTracker.GRANITE_CANNONBALL, 100));
		harness.tick();
		harness.setVarp(VarPlayerID.DROPCANNON, 4);
		harness.tick();
		harness.setInventory(PluginHarness.item(SupplyTracker.GRANITE_CANNONBALL, 70));
		loaded = 30;
		harness.setVarp(VarPlayerID.ROCKTHROWER, loaded);
		harness.tick();

		harness.shutDown();
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
	}

	/** Picks up the granite-loaded cannon: its loaded cannonballs go back to the inventory on the same tick. */
	private void pickUpGraniteCannon()
	{
		harness.setInventory(PluginHarness.item(SupplyTracker.GRANITE_CANNONBALL, 70 + loaded));
		loaded = 0;
		harness.setVarp(VarPlayerID.ROCKTHROWER, 0);
		harness.setVarp(VarPlayerID.DROPCANNON, 0);
		harness.tick();
	}

	/** The cannon fires {@code count} of its loaded cannonballs. */
	private void fire(int count)
	{
		loaded -= count;
		harness.setVarp(VarPlayerID.ROCKTHROWER, loaded);
		harness.tick();
	}

	/** The task count goes down on the next tick (2 minutes later). */
	private void kill()
	{
		now.addAndGet(2 * 60_000L);
		harness.setRemaining(harness.tracker().getCurrentRemaining() - 1);
		harness.tick();
	}

	/** Completes the task and lets its grace window pass, so it is saved. */
	private void complete()
	{
		now.addAndGet(60_000L);
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);
	}

	private List<String> taskBoxRows()
	{
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			rows.set(harness.ui().getTaskBox().getRows());
		});
		return rows.get();
	}

	/** The overlay's Task row value, or {@code null} when it has none. */
	private String overlayTask()
	{
		return overlayValue("Task");
	}

	/** Asserts the overlay's Task row shows {@code task} and its Left row {@code left}. */
	private void assertOverlayTask(String task, String left)
	{
		assertOverlayTask(null, task, left);
	}

	/** As {@link #assertOverlayTask(String, String)}, with {@code message} on failure. */
	private void assertOverlayTask(String message, String task, String left)
	{
		assertEquals(message, task, overlayTask());
		assertEquals(message, left, overlayValue("Left"));
	}

	/** The overlay's {@code label} row value, or {@code null} when it has none. */
	private String overlayValue(String label)
	{
		for (OverlayRows.Row row : OverlayRows.rows(harness.overlayData(), true, true, true, true))
		{
			if (label.equals(row.getLabel()))
			{
				return row.getValue();
			}
		}
		return null;
	}

	/** The sidebar's time-left line, after a refresh. */
	private String sidebarTimeLeft()
	{
		AtomicReference<String> text = new AtomicReference<>();
		harness.drain();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text.set(harness.ui().getTimeLeftText());
		});
		return text.get();
	}

	/** Asserts the sidebar and the overlay show {@code expected} as the time left. */
	private void assertTimeLeft(String message, String expected)
	{
		assertEquals(message, "Time left: " + expected, sidebarTimeLeft());
		assertEquals(message, expected, overlayValue("Time left"));
	}

	/** The History estimate's text and tooltip, after a refresh. */
	private String[] estimate()
	{
		String[] result = new String[2];
		harness.drain();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			result[0] = harness.ui().getHistoryEstimate().getText();
			result[1] = harness.ui().getHistoryEstimate().getTooltip();
		});
		return result;
	}

	@Test
	public void aFiredCannonballShowsInTheTaskBoxAndOverlayAndNamesTheSavedTask()
	{
		assertTrue(harness.play());
		setUpCannon();
		kill();
		assertEquals("loading the cannon fires nothing", DEVILS + " · 4 left", taskBoxRows().get(0));
		assertOverlayTask(DEVILS, "4");

		fire(2);
		assertEquals(Long.valueOf(2), harness.tracker().getSupplies().toMap().get(SupplyTracker.CANNONBALL));
		assertEquals(CANNON + " · 4 left", taskBoxRows().get(0));
		assertOverlayTask(CANNON, "4");
		AtomicReference<String> tooltip = new AtomicReference<>();
		harness.onEdt(() -> tooltip.set(harness.ui().getTaskBox().getTaskTooltip()));
		assertTrue(tooltip.get(), tooltip.get().contains("Task: Dust devils<br>Cannon: cannonballs fired"));

		// Paused, it stays a cannon task.
		harness.pause();
		assertOverlayTask(CANNON, "4");
		assertTrue(harness.play());
		for (int i = 0; i < 3; i++)
		{
			kill();
		}
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(DEVILS, record.getMonster());
		assertTrue(record.cannonTask());
		assertEquals(CANNON, record.groupName());
	}

	@Test
	public void historyAndTrendsShowCannonTasksAsTheirOwnMonster()
	{
		// A task without a cannon, then one with.
		assertTrue(harness.play());
		for (int i = 0; i < 5; i++)
		{
			kill();
		}
		complete();

		harness.setTask(TASK, DEVILS, 5, 5);
		harness.tick();
		assertTrue(harness.play());
		setUpCannon();
		fire(3);
		for (int i = 0; i < 5; i++)
		{
			kill();
		}
		complete();

		assertEquals(2, harness.records(ACCOUNT).size());
		harness.drain();
		AtomicReference<List<String>> filter = new AtomicReference<>();
		AtomicReference<List<String>> titles = new AtomicReference<>();
		harness.onEdt(() ->
		{
			filter.set(harness.ui().getHistory().getFilterOptions());
			titles.set(harness.ui().getHistory().getTitleTexts());
		});
		assertEquals(Arrays.asList(LedgerHistory.ALL, DEVILS, CANNON), filter.get());
		assertEquals("newest first", Arrays.asList(CANNON + " | Completed", DEVILS + " | Completed"), titles.get());

		harness.onEdt(() -> harness.ui().getTrends().clickTitle());
		harness.drain();
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() -> rows.set(harness.ui().getTrends().getRows()));
		assertEquals(rows.get().toString(), 2, rows.get().size());
		assertTrue(rows.get().toString(), rows.get().stream().anyMatch(row -> row.contains(". " + CANNON + " |")));
		assertTrue(rows.get().toString(), rows.get().stream().anyMatch(row -> row.contains(". " + DEVILS + " |")));
	}

	@Test
	public void theEstimatePoolsUntilACannonballIsFiredThenCountsCannonTasksOnly()
	{
		// 6 minutes a kill without a cannon, 3 with: 4.5 pooled.
		List<LedgerRecord> history = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			history.add(saved(false));
			history.add(saved(true));
		}
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, history));
		harness.drain();

		assertTrue(estimate()[0], estimate()[0].startsWith("History (6 tasks)"));
		assertTrue(estimate()[1], estimate()[1].contains("Counts cannon tasks too, until you fire a cannonball."));

		assertTrue(harness.play());
		setUpCannon();
		kill();
		assertTrue("still pooled without a cannonball fired", estimate()[0].startsWith("History (6 tasks)"));
		assertTimeLeft("4 kills at 4.5 minutes", "~18m");

		fire(1);
		assertEquals(TaskSelection.ANY.withCannon(true), harness.tracker().getCurrentTaskSelection());
		assertTrue(estimate()[0], estimate()[0].startsWith("History (3 tasks)"));
		assertTrue(estimate()[1], estimate()[1].contains("Only your cannon tasks count."));
		assertTimeLeft("4 kills at 3 minutes", "~12m");
	}

	@Test
	public void withoutCannonTasksInTheHistoryTheEstimateKeepsPoolingAfterACannonball()
	{
		List<LedgerRecord> history = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			history.add(saved(false));
		}
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, history));
		harness.drain();

		assertTrue(harness.play());
		setUpCannon();
		fire(1);
		kill();
		assertEquals(TaskSelection.ANY.withCannon(true), harness.tracker().getCurrentTaskSelection());
		assertEquals("the task box still shows the cannon", CANNON + " · 4 left", taskBoxRows().get(0));
		String[] estimate = estimate();
		assertTrue(estimate[0], estimate[0].startsWith("History (3 tasks)"));
		assertTrue(estimate[1], estimate[1].contains(HistoryEstimateSection.NO_CANNON_TASKS_NOTE));
		assertFalse(estimate[1], estimate[1].contains("Only your cannon tasks count."));
		assertTimeLeft("4 kills at 6 minutes", "~24m");

		// A first cannon task in the history: from then on only it counts.
		List<LedgerRecord> withCannon = new ArrayList<>(history);
		withCannon.add(saved(true));
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, withCannon));
		harness.drain();
		estimate = estimate();
		assertTrue(estimate[0], estimate[0].startsWith("History (1 task)"));
		assertTrue(estimate[1], estimate[1].contains("Only your cannon tasks count."));
		assertTimeLeft("4 kills at 3 minutes", "~12m");
	}

	@Test
	public void aCannonLoadedAndPickedUpWithoutFiringIsNoCannonTask()
	{
		assertTrue(harness.play());
		setUpCannon();
		kill();
		pickUpCannon();
		assertEquals(0L, harness.tracker().getSupplies().get(SupplyTracker.CANNONBALL));
		assertEquals(TaskSelection.ANY, harness.tracker().getCurrentTaskSelection());
		assertEquals(DEVILS + " · 4 left", taskBoxRows().get(0));
		for (int i = 0; i < 4; i++)
		{
			kill();
		}
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertFalse(record.cannonTask());
		assertFalse(String.valueOf(record.getSupplies()), CannonTasks.fired(record.getSupplies()));
		assertEquals(DEVILS, record.groupName());
	}

	@Test
	public void aCannonPickedUpAfterFiringCountsOnlyTheFiredCannonballs()
	{
		assertTrue(harness.play());
		setUpCannon();
		fire(4);
		kill();
		pickUpCannon();
		assertEquals(4L, harness.tracker().getSupplies().get(SupplyTracker.CANNONBALL));
		assertEquals(TaskSelection.ANY.withCannon(true), harness.tracker().getCurrentTaskSelection());
		assertEquals(CANNON + " · 4 left", taskBoxRows().get(0));
		for (int i = 0; i < 4; i++)
		{
			kill();
		}
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.cannonTask());
		assertEquals(Long.valueOf(4), record.getSupplies().get(SupplyTracker.CANNONBALL));
		assertEquals(CANNON, record.groupName());
	}

	@Test
	public void aGraniteCannonLoadedBeforeTrackingStartsAndPickedUpWithoutFiringIsNoCannonTask()
	{
		restartWithLoadedGraniteCannon();
		assertTrue(harness.play());
		kill();
		pickUpGraniteCannon();
		assertEquals(0L, harness.tracker().getSupplies().get(SupplyTracker.CANNONBALL));
		assertEquals(0L, harness.tracker().getSupplies().get(SupplyTracker.GRANITE_CANNONBALL));
		assertEquals(TaskSelection.ANY, harness.tracker().getCurrentTaskSelection());
		assertEquals(DEVILS + " · 4 left", taskBoxRows().get(0));
		for (int i = 0; i < 4; i++)
		{
			kill();
		}
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertFalse(record.cannonTask());
		assertFalse(String.valueOf(record.getSupplies()), CannonTasks.fired(record.getSupplies()));
		assertEquals(DEVILS, record.groupName());
	}

	@Test
	public void aGraniteCannonPickupSplitOverTwoTicksNetsTheFiredGraniteCannonballs()
	{
		restartWithLoadedGraniteCannon();
		assertTrue(harness.play());
		fire(4);
		// The varps go to 0 a tick before the cannonballs reach the inventory: counted under the guess for now.
		final int returning = loaded;
		loaded = 0;
		harness.setVarp(VarPlayerID.ROCKTHROWER, 0);
		harness.setVarp(VarPlayerID.DROPCANNON, 0);
		harness.tick();
		assertEquals(30L, harness.tracker().getSupplies().get(SupplyTracker.CANNONBALL));
		harness.setInventory(PluginHarness.item(SupplyTracker.GRANITE_CANNONBALL, 70 + returning));
		harness.tick();

		assertEquals(0L, harness.tracker().getSupplies().get(SupplyTracker.CANNONBALL));
		assertEquals(4L, harness.tracker().getSupplies().get(SupplyTracker.GRANITE_CANNONBALL));
	}

	@Test
	public void aGraniteCannonFiringOnItsPickupTickNetsTheFiredGraniteCannonballs()
	{
		restartWithLoadedGraniteCannon();
		assertTrue(harness.play());
		fire(4);
		// One more shot on the pickup tick: 25 of the 26 the cannon held come back.
		loaded -= 1;
		pickUpGraniteCannon();

		assertEquals(0L, harness.tracker().getSupplies().get(SupplyTracker.CANNONBALL));
		assertEquals(5L, harness.tracker().getSupplies().get(SupplyTracker.GRANITE_CANNONBALL));
	}

	@Test
	public void aGraniteCannonLoadedBeforeTrackingStartsCountsOnlyTheFiredGraniteCannonballs()
	{
		restartWithLoadedGraniteCannon();
		assertTrue(harness.play());
		fire(4);
		// The loaded type is not known yet, but the count is: the task box shows the cannon at once.
		assertEquals(CANNON + " · 5 left", taskBoxRows().get(0));
		kill();
		pickUpGraniteCannon();
		assertEquals("moved to the type the pickup returned", 0L,
			harness.tracker().getSupplies().get(SupplyTracker.CANNONBALL));
		assertEquals(4L, harness.tracker().getSupplies().get(SupplyTracker.GRANITE_CANNONBALL));
		assertEquals(TaskSelection.ANY.withCannon(true), harness.tracker().getCurrentTaskSelection());
		assertEquals(CANNON + " · 4 left", taskBoxRows().get(0));
		for (int i = 0; i < 4; i++)
		{
			kill();
		}
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.cannonTask());
		assertEquals(Long.valueOf(4), record.getSupplies().get(SupplyTracker.GRANITE_CANNONBALL));
		assertEquals(0L, record.getSupplies().getOrDefault(SupplyTracker.CANNONBALL, 0L).longValue());
		assertEquals(CANNON, record.groupName());
	}

	/**
	 * A completed dust devils task of 10 kills, saved earlier: an hour long, or half an hour as a cannon task, which
	 * fired 50 cannonballs.
	 */
	private static LedgerRecord saved(boolean cannon)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(java.util.UUID.randomUUID().toString());
		record.setCreatureId(TASK);
		record.setMonster(DEVILS);
		record.setKills(10);
		record.setInitialAmount(10);
		record.setOriginalAmount(10);
		record.setActiveMillis((cannon ? 30 : 60) * 60_000L);
		record.setEndedAt(500_000L);
		record.setCompleted(true);
		record.setSupplies(cannon ? Collections.singletonMap(SupplyTracker.CANNONBALL, 50L) : null);
		record.setLootGeValue(cannon ? 400_000L : 100_000L);
		record.setSuppliesGeValue(0L);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.NPC;
import net.runelite.api.gameval.NpcID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Catacombs variants as wired in the plugin ({@link PluginHarness}): the player's hits ({@code HitsplatApplied})
 * and NPC deaths ({@code ActorDeath}) while a session runs are tallied per NPC name (by world view and index), the task
 * box and the overlay's Task row show the variant once the kills say so, and the saved record keeps it, so the History
 * list and Trends show it as its own monster. {@link CatacombsVariantsTest} and {@link CatacombsVariantGroupingTest}
 * cover the rules.
 */
public class HarnessCatacombsVariantTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 7;
	private static final String SPECTRES = "Aberrant spectres";
	private static final String DEVIANT = "Deviant spectres";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private final AtomicLong now = new AtomicLong(1_000_000L);
	/** The next NPC scene index, so every NPC is a new one. */
	private int nextIndex = 1;

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setInventory();
		harness.setTrackerClock(now::get);
		harness.setTask(TASK, SPECTRES, 5, 5);
		harness.loginAndSettle(ACCOUNT);
	}

	/** The player hits a new NPC and it dies; the task count goes down on the next tick (2 minutes later). */
	private void kill(int id, String name)
	{
		NPC npc = harness.npc(nextIndex++, id, name);
		harness.hitsplat(npc, true);
		harness.npcDies(npc);
		now.addAndGet(2 * 60_000L);
		harness.setRemaining(harness.tracker().getCurrentRemaining() - 1);
		harness.tick();
	}

	private void killDeviant()
	{
		kill(NpcID.KOUREND_SPECTRE, "Deviant spectre");
	}

	private void killAberrant()
	{
		kill(NpcID.SLAYER_ABBERANT_SPECTRE_1, "Aberrant spectre");
	}

	/** Completes the task and lets its grace window pass, so it is saved. */
	private void complete()
	{
		now.addAndGet(60_000L);
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);
	}

	private List<String> taskBoxRows()
	{
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			rows.set(harness.ui().getTaskBox().getRows());
		});
		return rows.get();
	}

	@Test
	public void variantKillsShowInTheTaskBoxAndAreSavedWithTheTask()
	{
		assertTrue(harness.play());
		assertEquals(SPECTRES + " · 5 left", taskBoxRows().get(0));

		killDeviant();
		assertEquals(Arrays.asList(new NpcKills("Deviant spectre", 1)), harness.tracker().getNpcKills());
		assertEquals(DEVIANT + " · 4 left", taskBoxRows().get(0));
		AtomicReference<String> tooltip = new AtomicReference<>();
		harness.onEdt(() -> tooltip.set(harness.ui().getTaskBox().getTaskTooltip()));
		assertTrue(tooltip.get(), tooltip.get().contains("Task: Aberrant spectres<br>Doing: Deviant spectres"));

		killAberrant();
		assertEquals("a tie is the standard monster", SPECTRES + " · 3 left", taskBoxRows().get(0));
		killDeviant();
		killDeviant();
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(SPECTRES, record.getMonster());
		assertEquals(DEVIANT, record.getVariant());
	}

	/** The overlay's Task row value, or {@code null} when it has none. */
	private String overlayTask()
	{
		return overlayValue("Task");
	}

	/** The overlay's {@code label} row value, or {@code null} when it has none. */
	private String overlayValue(String label)
	{
		for (OverlayRows.Row row : OverlayRows.rows(harness.overlayData(), true, true, true, true))
		{
			if (label.equals(row.getLabel()))
			{
				return row.getValue();
			}
		}
		return null;
	}

	/** Asserts the overlay's Task row shows {@code task} and its Left row {@code left}. */
	private void assertOverlayTask(String task, String left)
	{
		assertOverlayTask(null, task, left);
	}

	/** As {@link #assertOverlayTask(String, String)}, with {@code message} on failure. */
	private void assertOverlayTask(String message, String task, String left)
	{
		assertEquals(message, task, overlayTask());
		assertEquals(message, left, overlayValue("Left"));
	}

	@Test
	public void theOverlayTaskRowShowsTheVariantLikeTheTaskBox()
	{
		assertTrue(harness.play());
		assertOverlayTask("the task before any kill", SPECTRES, "5");

		killDeviant();
		assertOverlayTask(DEVIANT, "4");
		assertEquals(DEVIANT + " · 4 left", taskBoxRows().get(0));

		killAberrant();
		assertOverlayTask("a tie is the standard monster", SPECTRES, "3");
		killDeviant();
		assertOverlayTask(DEVIANT, "2");

		// Paused, the decision stands.
		harness.pause();
		assertOverlayTask(DEVIANT, "2");
	}

	@Test
	public void anUnrelatedKillDoesNotDecideTheTask()
	{
		assertTrue(harness.play());
		// An Ankou on the way: tallied, but not a task kill.
		NPC ankou = harness.npc(nextIndex++, NpcID.KOUREND_ANKOU, "Ankou");
		harness.hitsplat(ankou, true);
		harness.npcDies(ankou);
		harness.tick();
		assertEquals(Arrays.asList(new NpcKills("Ankou", 1)), harness.tracker().getNpcKills());
		assertEquals(TaskSelection.ANY, harness.tracker().getCurrentTaskSelection());
		assertEquals(SPECTRES + " · 5 left", taskBoxRows().get(0));

		killDeviant();
		assertEquals(TaskSelection.of(DEVIANT), harness.tracker().getCurrentTaskSelection());
		assertEquals(DEVIANT + " · 4 left", taskBoxRows().get(0));
	}

	@Test
	public void npcsAreToldApartByWorldView()
	{
		assertTrue(harness.play());
		// The same index on a boat is another NPC: its death isn't the one the player hit.
		NPC hit = harness.npc(nextIndex, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		NPC onBoat = harness.npcOnBoat(nextIndex, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		nextIndex++;
		harness.hitsplat(hit, true);
		harness.npcDies(onBoat);
		harness.npcDespawns(onBoat);
		assertTrue(harness.tracker().getNpcKills().isEmpty());
		harness.npcDies(hit);
		assertEquals(Arrays.asList(new NpcKills("Deviant spectre", 1)), harness.tracker().getNpcKills());

		// An NPC without a world view is kept as top-level.
		NPC noView = harness.npcWithoutWorldView(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(noView, true);
		harness.npcDies(noView);
		assertEquals(Arrays.asList(new NpcKills("Deviant spectre", 2)), harness.tracker().getNpcKills());
	}

	@Test
	public void onlyNpcsThePlayerHitWhileRunningAreTallied()
	{
		// Before Play: not remembered, so its death is not tallied.
		NPC early = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(early, true);
		assertTrue(harness.play());
		harness.npcDies(early);
		// Someone else's hits only.
		NPC others = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(others, false);
		harness.npcDies(others);
		// Hit, then despawned before dying (for example out of view).
		NPC gone = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(gone, true);
		harness.npcDespawns(gone);
		harness.npcDies(gone);
		// A Greater Nechryael outside the Catacombs is not a variant kill.
		NPC wilderness = harness.npc(nextIndex++, NpcID.WILD_CAVE_NECHRYAEL, "Greater Nechryael");
		harness.hitsplat(wilderness, true);
		harness.npcDies(wilderness);
		assertTrue(harness.tracker().getNpcKills().isEmpty());

		// Paused: hits are not remembered.
		harness.pause();
		NPC paused = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(paused, true);
		assertTrue(harness.play());
		harness.npcDies(paused);
		assertTrue(harness.tracker().getNpcKills().isEmpty());

		// A logout forgets the NPCs hit before it.
		NPC beforeHop = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(beforeHop, true);
		harness.hop();
		harness.ticks(5);
		assertTrue(harness.play());
		harness.npcDies(beforeHop);
		assertTrue(harness.tracker().getNpcKills().isEmpty());
		assertNull(harness.tracker().getCurrentTaskSelection().getVariant());
	}

	@Test
	public void theEstimatePoolsUntilKillsDecideAndTheAdvisorComparesTheVersions()
	{
		List<LedgerRecord> history = new java.util.ArrayList<>();
		for (int i = 0; i < TaskAdvisor.MIN_TASKS; i++)
		{
			history.add(saved(null, 100_000L));
			history.add(saved(DEVIANT, 400_000L));
		}
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, history));
		harness.drain();

		// Before any kill both versions count.
		assertTrue(estimate()[0], estimate()[0].startsWith("History (6 tasks)"));
		assertTrue(estimate()[1], estimate()[1].contains("Counts Deviant spectres tasks too"));
		// One monster only: no main advice, but the versions are compared.
		assertEquals(Arrays.asList(SPECTRES + " · 5 left", "Better: Deviant spectres"), taskBoxRows());
		AtomicReference<String> tooltip = new AtomicReference<>();
		harness.onEdt(() -> tooltip.set(harness.ui().getTaskBox().getAdviceTooltip()));
		assertTrue("the line in full first, as the sidebar may cut it off: " + tooltip.get(),
			tooltip.get().startsWith("<html>Better: Deviant spectres<br>"));
		assertTrue(tooltip.get(), tooltip.get().contains(
			"Profit (GE)/h: Deviant spectres ~400K (n=3), Aberrant spectres ~100K (n=3)"));

		assertTrue(harness.play());
		killDeviant();
		assertTrue(estimate()[0], estimate()[0].startsWith("History (3 tasks)"));
		assertTrue(estimate()[1], estimate()[1].contains("Only your Deviant spectres tasks count."));
		killAberrant();
		assertTrue("a tie is standard", estimate()[0].startsWith("History (3 tasks)"));
		assertTrue(estimate()[1], estimate()[1].contains("Your Deviant spectres tasks are left out."));
	}

	/** The History estimate's text and tooltip, after a refresh. */
	private String[] estimate()
	{
		String[] result = new String[2];
		harness.drain();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			result[0] = harness.ui().getHistoryEstimate().getText();
			result[1] = harness.ui().getHistoryEstimate().getTooltip();
		});
		return result;
	}

	/** An hour-long completed spectres task of 10 kills making {@code profit}, saved earlier with totals only (~). */
	private static LedgerRecord saved(String variant, long profit)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(java.util.UUID.randomUUID().toString());
		record.setCreatureId(TASK);
		record.setMonster(SPECTRES);
		record.setVariant(variant);
		record.setKills(10);
		record.setInitialAmount(10);
		record.setOriginalAmount(10);
		record.setActiveMillis(60 * 60_000L);
		record.setEndedAt(500_000L);
		record.setCompleted(true);
		record.setLootGeValue(profit);
		record.setSuppliesGeValue(0L);
		return record;
	}

	@Test
	public void historyAndTrendsShowTheVariantAsItsOwnMonster()
	{
		assertTrue(harness.play());
		for (int i = 0; i < 4; i++)
		{
			killAberrant();
		}
		complete();

		harness.setTask(TASK, SPECTRES, 5, 5);
		harness.tick();
		assertTrue(harness.play());
		for (int i = 0; i < 4; i++)
		{
			killDeviant();
		}
		complete();

		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		harness.drain();
		AtomicReference<List<String>> filter = new AtomicReference<>();
		AtomicReference<List<String>> titles = new AtomicReference<>();
		harness.onEdt(() ->
		{
			filter.set(harness.ui().getHistory().getFilterOptions());
			titles.set(harness.ui().getHistory().getTitleTexts());
		});
		assertEquals(Arrays.asList(LedgerHistory.ALL, SPECTRES, DEVIANT), filter.get());
		assertEquals("newest first", Arrays.asList(DEVIANT + " | Completed", SPECTRES + " | Completed"), titles.get());

		harness.onEdt(() -> harness.ui().getTrends().clickTitle());
		harness.drain();
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() -> rows.set(harness.ui().getTrends().getRows()));
		assertEquals(rows.get().toString(), 2, rows.get().size());
		assertTrue(rows.get().toString(), rows.get().stream().anyMatch(row -> row.contains(". " + DEVIANT + " |")));
		assertTrue(rows.get().toString(), rows.get().stream().anyMatch(row -> row.contains(". " + SPECTRES + " |")));
		assertFalse(rows.get().toString(), rows.get().stream().anyMatch(row -> row.contains("(n=2)")));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.PluginHarness.item;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Teleport jewellery, teleport tablets and Slayer consumables as wired in the plugin ({@link PluginHarness}): the worn
 * amulet, ring and gloves slots are read with the inventory, charged items are classified by id even though their item
 * stats are not loaded (the harness never loads them), and charges are saved and valued per charge.
 * {@link SupplyChargesTest} covers the rules themselves.
 */
public class HarnessChargedSuppliesTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final String[] WEAR = {null, "Wear", "Rub", null, "Drop"};

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.AMULET_OF_GLORY_6, "Amulet of glory(6)", 12_000, 0, WEAR);
		harness.defineItem(ItemID.AMULET_OF_GLORY_4, "Amulet of glory(4)", 11_000, 0, WEAR);
		harness.defineItem(ItemID.AMULET_OF_GLORY_3, "Amulet of glory(3)", 10_000, 0, WEAR);
		harness.defineItem(ItemID.RING_OF_DUELING_8, "Ring of dueling(8)", 800, 0, WEAR);
		harness.defineItem(ItemID.RING_OF_DUELING_1, "Ring of dueling(1)", 100, 0, WEAR);
		harness.defineItem(ItemID.JEWL_BRACELET_OF_COMBAT_6, "Combat bracelet(6)", 6_000, 0, WEAR);
		harness.defineItem(ItemID.JEWL_BRACELET_OF_COMBAT_5, "Combat bracelet(5)", 5_000, 0, WEAR);
		harness.defineItem(ItemID.POH_TABLET_VARROCKTELEPORT, "Varrock teleport", 500, 0,
			"Break", null, null, null, "Drop");
		harness.defineItem(ItemID.SLAYER_BAG_OF_SALT, "Bag of salt", 10, 0, null, null, null, null, "Drop");
		harness.setInventory(item(ItemID.POH_TABLET_VARROCKTELEPORT, 5), item(ItemID.SLAYER_BAG_OF_SALT, 50));
		harness.setWorn(EquipmentInventorySlot.AMULET, ItemID.AMULET_OF_GLORY_4, 1);
		harness.setWorn(EquipmentInventorySlot.RING, ItemID.RING_OF_DUELING_1, 1);
		harness.setWorn(EquipmentInventorySlot.GLOVES, ItemID.JEWL_BRACELET_OF_COMBAT_6, 1);
		harness.startUp();
		harness.setTask(42, "Rockslugs", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	private static long used(Map<Integer, Long> supplies, int itemId)
	{
		return supplies == null ? 0 : supplies.getOrDefault(itemId, 0L);
	}

	@Test
	public void wornJewelleryTabletsAndSaltAreCountedAndValued()
	{
		assertTrue(harness.play());
		// Teleports from the equipment tab: a glory charge, the dueling ring's last charge (it crumbles) and a combat
		// bracelet charge.
		harness.setWorn(EquipmentInventorySlot.AMULET, ItemID.AMULET_OF_GLORY_3, 1);
		harness.setWorn(EquipmentInventorySlot.RING, -1, 0);
		harness.setWorn(EquipmentInventorySlot.GLOVES, ItemID.JEWL_BRACELET_OF_COMBAT_5, 1);
		// A tablet broken and two bags of salt used.
		harness.setInventory(item(ItemID.POH_TABLET_VARROCKTELEPORT, 4), item(ItemID.SLAYER_BAG_OF_SALT, 48));
		harness.tick();

		harness.stop();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		Map<Integer, Long> supplies = record.getSupplies();
		assertEquals(1L, used(supplies, ItemID.AMULET_OF_GLORY_6));
		assertEquals(1L, used(supplies, ItemID.RING_OF_DUELING_8));
		assertEquals(1L, used(supplies, ItemID.JEWL_BRACELET_OF_COMBAT_6));
		assertEquals(1L, used(supplies, ItemID.POH_TABLET_VARROCKTELEPORT));
		assertEquals(2L, used(supplies, ItemID.SLAYER_BAG_OF_SALT));
		assertEquals(5, supplies.size());
		Map<Integer, Integer> doses = record.getSupplyDoses();
		assertEquals(Integer.valueOf(6), doses.get(ItemID.AMULET_OF_GLORY_6));
		assertEquals(Integer.valueOf(8), doses.get(ItemID.RING_OF_DUELING_8));
		assertEquals(Integer.valueOf(6), doses.get(ItemID.JEWL_BRACELET_OF_COMBAT_6));
		assertNull(doses.get(ItemID.POH_TABLET_VARROCKTELEPORT));
		// 12,000 / 6 + 800 / 8 + 6,000 / 6 + 500 + 2 * 10.
		assertEquals(Long.valueOf(2_000 + 100 + 1_000 + 500 + 20), record.getSuppliesGeValue());
	}

	@Test
	public void unequippingAndPausingAreNotCounted()
	{
		assertTrue(harness.play());
		// Taking the amulet off into the inventory moves it between tracked containers.
		harness.setWorn(EquipmentInventorySlot.AMULET, -1, 0);
		harness.setInventory(item(ItemID.POH_TABLET_VARROCKTELEPORT, 5), item(ItemID.SLAYER_BAG_OF_SALT, 50),
			item(ItemID.AMULET_OF_GLORY_4, 1));
		harness.tick();
		harness.pause();
		harness.setInventory(item(ItemID.POH_TABLET_VARROCKTELEPORT, 5), item(ItemID.SLAYER_BAG_OF_SALT, 50),
			item(ItemID.AMULET_OF_GLORY_3, 1));
		harness.tick();

		harness.stop();
		Map<Integer, Long> supplies = harness.onlyRecord(ACCOUNT).getSupplies();
		assertEquals(Collections.emptyMap(), supplies == null ? Collections.emptyMap() : supplies);
	}

	@Test
	public void jewelleryBankedFromTheEquipmentIsNotCounted()
	{
		assertTrue(harness.play());
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.setWorn(EquipmentInventorySlot.AMULET, -1, 0);
		harness.setWorn(EquipmentInventorySlot.GLOVES, -1, 0);
		harness.tick();
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.ticks(SupplyExclusions.INTERFACE_TICKS + 1);

		harness.stop();
		Map<Integer, Long> supplies = harness.onlyRecord(ACCOUNT).getSupplies();
		assertEquals(0L, used(supplies, ItemID.AMULET_OF_GLORY_6));
		assertEquals(0L, used(supplies, ItemID.JEWL_BRACELET_OF_COMBAT_6));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.PluginHarness.item;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpotanimID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Blowpipe and trident use as wired in the plugin ({@link PluginHarness}): shots and casts read from the local
 * player's animation, frame and spotanims with the worn weapon and cape on GameTick and counted only while RUNNING;
 * the dart type learned from the check message and kept in the RSProfile config; loading, charging and unloading
 * kept out of the supplies diff; and the panel's "Check your blowpipe" hint. {@link ChargedWeaponUsageTest},
 * {@link BlowpipeMessageTest} and {@link ChargeExclusionsTest} cover the rules themselves.
 */
public class HarnessChargedWeaponsTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final String RUNE_DART_CHECK =
		"Darts: <col=007f00>Rune dart x 1,000</col>. Scales: <col=007f00>5,000 (33.3%)</col>.";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineStackableWeapon(ItemID.RUNE_DART, "Rune dart", 100);
		harness.defineItem(ItemID.SNAKEBOSS_SCALE, "Zulrah's scales", 150, 0, null, null, null, null, "Drop");
		harness.defineItem(ItemID.DEATHRUNE, "Death rune", 200, 0, null, null, null, null, "Drop");
		harness.defineItem(ItemID.CHAOSRUNE, "Chaos rune", 80, 0, null, null, null, null, "Drop");
		harness.defineItem(ItemID.FIRERUNE, "Fire rune", 5, 0, null, null, null, null, "Drop");
		harness.setInventory();
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Stops the session and returns the saved record's supplies. */
	private Map<Integer, Long> stopAndGetSupplies()
	{
		harness.stop();
		Map<Integer, Long> supplies = harness.onlyRecord(ACCOUNT).getSupplies();
		return supplies == null ? Collections.emptyMap() : supplies;
	}

	private static long used(Map<Integer, Long> supplies, int itemId)
	{
		return supplies.getOrDefault(itemId, 0L);
	}

	/** One tick on which a blowpipe shot starts (attack animation at frame 0), then the animation ends. */
	private void blowpipeShot()
	{
		harness.setAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, 0);
		harness.tick();
		harness.setAnimation(-1, 0);
	}

	private void blowpipeShots(int n)
	{
		for (int i = 0; i < n; i++)
		{
			blowpipeShot();
		}
	}

	private boolean dartHintShown()
	{
		final boolean[] shown = new boolean[1];
		harness.onEdt(() -> shown[0] = harness.ui().isDartHintShown());
		return shown[0];
	}

	@Test
	public void blowpipeShotsCountDartsAndScalesOnlyWhileRunning()
	{
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.TOXIC_BLOWPIPE_LOADED, 1);
		harness.chat(ChatMessageType.GAMEMESSAGE, RUNE_DART_CHECK);
		// Before Play: not counted.
		blowpipeShots(3);

		assertTrue(harness.play());
		// No cape-slot device: a dart per shot; 2/3 of a scale per shot.
		blowpipeShots(3);
		// A frame other than 0 is the same shot still playing.
		harness.setAnimation(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK, 5);
		harness.tick();
		harness.setAnimation(-1, 0);
		harness.pause();
		blowpipeShots(3);

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(3L, used(supplies, ItemID.RUNE_DART));
		assertEquals(2L, used(supplies, ItemID.SNAKEBOSS_SCALE));
		assertEquals(2, supplies.size());
	}

	@Test
	public void vorkathsHeadSettingAppliesToTheMaxCape()
	{
		harness.config.vorkathsHeadUpgrade = true;
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.TOXIC_BLOWPIPE_LOADED, 1);
		harness.setWorn(EquipmentInventorySlot.CAPE, ItemID.SKILLCAPE_MAX, 1);
		harness.chat(ChatMessageType.GAMEMESSAGE, RUNE_DART_CHECK);
		assertTrue(harness.play());
		// 80% saved: 0.2 darts per shot.
		blowpipeShots(10);

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(2L, used(supplies, ItemID.RUNE_DART));
		// 10 shots: 20 thirds, 6 whole scales.
		assertEquals(6L, used(supplies, ItemID.SNAKEBOSS_SCALE));
	}

	@Test
	public void tridentCastsCountTheirChargeMaterials()
	{
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.TOTS_CHARGED, 1);
		assertTrue(harness.play());
		harness.setAnimation(AnimationID.HUMAN_CASTWAVE_STAFF, 0);
		harness.setSpotAnims(SpotanimID.SLAYER_TOTS_CASTING);
		harness.tick();
		// The wave-staff animation without the trident's graphic is another spell.
		harness.setSpotAnims();
		harness.tick();
		harness.setAnimation(-1, 0);
		harness.tick();

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(1L, used(supplies, ItemID.DEATHRUNE));
		assertEquals(1L, used(supplies, ItemID.CHAOSRUNE));
		assertEquals(5L, used(supplies, ItemID.FIRERUNE));
		assertEquals(10L, used(supplies, ItemID.COINS));
		assertEquals(4, supplies.size());
	}

	@Test
	public void loadingAndUnloadingDartsIsNotCountedTwice()
	{
		harness.setInventory(item(ItemID.RUNE_DART, 100), item(ItemID.TOXIC_BLOWPIPE_LOADED, 1));
		harness.tick();
		assertTrue(harness.play());
		// Loading the inventory's darts into the blowpipe.
		harness.clickUseOn(ItemID.RUNE_DART, ItemID.TOXIC_BLOWPIPE_LOADED);
