			harness.rsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.BLOWPIPE_DART_KEY));

		// Two shots with the blowpipe wielded.
		harness.setInventory();
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.TOXIC_BLOWPIPE_LOADED, 1);
		harness.tick();
		blowpipeShots(2);

		// Unloading the darts back into the inventory is not a return of ammo used.
		harness.clickMenu("Unload", ItemID.TOXIC_BLOWPIPE_LOADED);
		harness.setInventory(item(ItemID.RUNE_DART, 98));
		harness.tick();
		assertNull("unloading forgets the dart type",
			harness.rsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.BLOWPIPE_DART_KEY));

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(2L, used(supplies, ItemID.RUNE_DART));
		assertEquals(1L, used(supplies, ItemID.SNAKEBOSS_SCALE));
	}

	@Test
	public void chargingATridentIsNotCountedAndTheDialogEndsTheWindow()
	{
		harness.setInventory(item(ItemID.TOTS_UNCHARGED, 1), item(ItemID.DEATHRUNE, 100),
			item(ItemID.CHAOSRUNE, 100), item(ItemID.FIRERUNE, 500));
		harness.tick();
		assertTrue(harness.play());
		harness.clickUseOn(ItemID.FIRERUNE, ItemID.TOTS_UNCHARGED);
		// The number input is answered; 100 charges use all the runes.
		harness.tick();
		harness.setInventory(item(ItemID.TOTS_CHARGED, 1));
		harness.tick();
		harness.showObjectbox("You add 100 charges to the weapon.<br>New total: 100");
		harness.ticks(ChargeExclusions.CONFIRM_GRACE_TICKS + 1);
		harness.showObjectbox(null);

		// After the window, runes used from the inventory count again.
		harness.setInventory(item(ItemID.TOTS_CHARGED, 1), item(ItemID.FIRERUNE, 10));
		harness.tick();
		harness.setInventory(item(ItemID.TOTS_CHARGED, 1), item(ItemID.FIRERUNE, 4));
		harness.tick();

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(0L, used(supplies, ItemID.DEATHRUNE));
		assertEquals(0L, used(supplies, ItemID.CHAOSRUNE));
		assertEquals(6L, used(supplies, ItemID.FIRERUNE));
	}

	@Test
	public void theDartTypeIsKeptForTheNextRunAndForgottenWhenEmpty()
	{
		// Saved in an earlier run of the plugin, for this RuneScape profile.
		harness.shutDown();
		harness.setRsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.BLOWPIPE_DART_KEY,
			String.valueOf(ItemID.RUNE_DART));
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.TOXIC_BLOWPIPE_LOADED, 1);
		assertTrue(harness.play());
		blowpipeShots(1);

		// Out of darts: shots count scales only until the type is known again.
		harness.chat(ChatMessageType.GAMEMESSAGE, "Your blowpipe has run out of darts.");
		assertNull(harness.rsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.BLOWPIPE_DART_KEY));
		blowpipeShots(2);

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(1L, used(supplies, ItemID.RUNE_DART));
		assertEquals(2L, used(supplies, ItemID.SNAKEBOSS_SCALE));
	}

	@Test
	public void theCheckHintSaysWhatToDo()
	{
		assertEquals("Check your blowpipe to count darts.", LiveSessionSection.DART_HINT_TEXT);
	}

	@Test
	public void theCheckHintShowsWhileDartsCannotBeCounted()
	{
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.TOXIC_BLOWPIPE_LOADED, 1);
		assertTrue(harness.play());
		harness.tick();
		assertFalse("no shot yet", dartHintShown());
		blowpipeShot();
		assertTrue(dartHintShown());

		harness.pause();
		harness.tick();
		assertFalse("hidden while paused", dartHintShown());
		assertTrue(harness.play());
		blowpipeShot();
		assertTrue(dartHintShown());

		// Checking the blowpipe names the darts: the hint goes on the next tick.
		harness.chat(ChatMessageType.GAMEMESSAGE, RUNE_DART_CHECK);
		harness.tick();
		assertFalse(dartHintShown());

		// Unknown again, but the blowpipe is no longer wielded.
		harness.chat(ChatMessageType.GAMEMESSAGE, "Your blowpipe contains no darts.");
		blowpipeShot();
		assertTrue(dartHintShown());
		harness.setWorn(EquipmentInventorySlot.WEAPON, -1, 0);
		harness.tick();
		assertFalse(dartHintShown());

		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.TOXIC_BLOWPIPE_LOADED, 1);
		blowpipeShot();
		assertTrue(dartHintShown());
		harness.stop();
		harness.tick();
		assertFalse("hidden once stopped", dartHintShown());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.Future;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * The late-loot grace window as wired in the plugin ({@link PluginHarness}): the priority -1 grace ticker runs after
 * the default-priority handlers and LootManager's loot, a completed session is saved exactly once as completed when
 * the window ends, and every other way out (logout, hop, plugin stop, client exit) saves it at once.
 * {@link CompletionGraceTest} covers the tracker's side of the window.
 */
public class HarnessCompletionGraceTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.defineItem(ItemID.COINS, "Coins", 1, 1);
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.setRemaining(1);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
	}

	/** Kills the last monster: the completion is read on this tick and the session is held for late loot. */
	private void completeOnNextTick()
	{
		harness.completeTask();
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		assertTrue("not saved during the grace window", harness.records(ACCOUNT).isEmpty());
	}

	@Test
	public void lootPostedOnTheCompletionTickIsCounted()
	{
		harness.completeTask();
		// LootManager posts this during the completion tick. It counts whichever side of the hold it lands on, so this
		// does not test ordering; lootWithinTheGraceWindowCountsAndLaterLootDoesNot does.
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertFalse(record.isPartial());
		assertEquals(3, record.getKills());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.BONES));
		// Priced on the client thread when saved (the harness fails the test on an off-thread ItemManager call).
		assertEquals(Long.valueOf(1_500_100), record.getLootGeValue());
	}

	@Test
	public void successfulCompletionPostsOneChatSummaryAndNoNotificationByDefault()
	{
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		ArgumentCaptor<QueuedMessage> message = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, times(1)).queue(message.capture());
		assertEquals(ChatMessageType.CONSOLE, message.getValue().getType());
		assertEquals("Slayer Ledger", message.getValue().getName());
		assertTrue(message.getValue().getRuneLiteFormattedMessage().startsWith("Slayer task complete: 3 Abyssal demons · "));
		assertTrue(message.getValue().getRuneLiteFormattedMessage().endsWith(" · +1.5M"));
		verifyNoInteractions(harness.notifier);
	}

	@Test
	public void notificationCanBeEnabledForSuccessfulCompletion()
	{
		harness.config.taskCompleteNotification = true;
		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		ArgumentCaptor<String> message = ArgumentCaptor.forClass(String.class);
		verify(harness.notifier, times(1)).notify(message.capture());
		assertTrue(message.getValue().startsWith("Slayer task complete: 3 Abyssal demons · "));
	}

	@Test
	public void completionSummaryIsPostedOnlyOnce()
	{
		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		harness.ticks(5);
		harness.logout();

		verify(harness.chatMessageManager, times(1)).queue(any(QueuedMessage.class));
	}

	@Test
	public void failedSaveDoesNotPostCompletionSummary() throws IOException
	{
		harness.config.taskCompleteNotification = true;
		// A ledger from a newer plugin version is never overwritten, so the completed record's append fails.
		String json = "{\"schemaVersion\":" + (LedgerStore.FILE_SCHEMA_VERSION + 1) + ",\"records\":[]}";
		Path ledger = harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json");
		Files.write(ledger, json.getBytes(StandardCharsets.UTF_8));

		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		assertFalse("the save was attempted", harness.tracker().hasPendingCompletion());
		assertEquals("the newer ledger is left alone", json, new String(Files.readAllBytes(ledger), StandardCharsets.UTF_8));
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
		verifyNoInteractions(harness.notifier);
	}

	@Test
	public void partialSaveDoesNotPostCompletionSummary()
	{
		harness.config.taskCompleteNotification = true;
		harness.stop();

		assertTrue(harness.onlyRecord(ACCOUNT).isPartial());
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
		verifyNoInteractions(harness.notifier);
	}

	@Test
	public void lootWithinTheGraceWindowCountsAndLaterLootDoesNot()
	{
		completeOnNextTick();
		harness.lootOnNextTick(ItemID.BONES, 2);
		harness.tick();
		assertTrue("one grace tick left", harness.tracker().hasPendingCompletion());
		assertTrue(harness.records(ACCOUNT).isEmpty());

		// The last grace tick: LootManager's loot arrives before the ticker releases the session.
		harness.lootOnNextTick(ItemID.COINS, 500);
		harness.tick();
		assertFalse(harness.tracker().hasPendingCompletion());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Long.valueOf(3), record.getLoot().get(ItemID.BONES));
		assertEquals(Long.valueOf(500), record.getLoot().get(ItemID.COINS));

		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.ticks(3);
		record = harness.onlyRecord(ACCOUNT);
		assertNull("loot after the window is not added", record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void lootPostedBetweenTicksDuringTheWindowCounts()
	{
		completeOnNextTick();
		harness.postLoot(ItemID.ABYSSAL_WHIP, 1);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(Long.valueOf(1), harness.onlyRecord(ACCOUNT).getLoot().get(ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void logoutDuringTheWindowSavesTheCompletedSessionOnce()
	{
		completeOnNextTick();
		harness.logout();
		assertFalse(harness.tracker().hasPendingCompletion());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertNull("a completed session is never persisted as active", harness.activeSession(ACCOUNT));

		harness.setTask(TASK + 1, "Greater demons", 20, 20);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(5);
		harness.shutDown();
		assertEquals(1, harness.records(ACCOUNT).size());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void worldHopDuringTheWindowSavesTheCompletedSession()
	{
		completeOnNextTick();
		harness.hop();
		assertFalse(harness.tracker().hasPendingCompletion());
		assertTrue(harness.onlyRecord(ACCOUNT).isCompleted());
		harness.ticks(PluginHarness.SETTLE_TICKS + SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(1, harness.records(ACCOUNT).size());
	}

	@Test
	public void pluginStopDuringTheWindowSavesTheCompletedSession()
	{
		completeOnNextTick();
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		harness.shutDown();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertFalse(record.isPartial());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void clientExitDuringTheWindowSavesTheCompletedSessionAndWaitsForIt()
	{
		completeOnNextTick();
		List<Future<?>> waitedFor = harness.clientShutdown();

		assertEquals("the held completion's save", 1, waitedFor.size());
		for (Future<?> future : waitedFor)
		{
			assertTrue(future.isDone());
			assertFalse(future.isCancelled());
		}
		assertTrue(harness.onlyRecord(ACCOUNT).isCompleted());
		assertFalse(harness.tracker().hasPendingCompletion());
	}

	@Test
	public void stopDuringTheWindowKeepsTheCompletedRecordAndNewSessionApart()
	{
		completeOnNextTick();
		// A new task, and a new session, while the old one is still held.
		harness.setTask(TASK + 1, "Greater demons", 20, 20);
		harness.tick();
		assertTrue(harness.play());
		harness.stop();

		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		LedgerRecord completed = records.stream().filter(LedgerRecord::isCompleted).findFirst().orElse(null);
		LedgerRecord partial = records.stream().filter(LedgerRecord::isPartial).findFirst().orElse(null);
		assertEquals("Abyssal demons", completed.getMonster());
		assertEquals("Greater demons", partial.getMonster());
		assertFalse(harness.tracker().hasPendingCompletion());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * Ground Items' hidden list as wired in the plugin: the items it hides are left out of every "Loot received"
 * grid (live, a saved task's details, Overall totals) and out of the loot value and profit everywhere (live values,
 * history rows, Overall totals, Trends, the task-complete line), read only from Ground Items' config. A change of the
 * list, of Ground Items' on/off state or of the "Hide Ground Items' hidden items" setting applies at once, and the
 * records are never changed, so the values come back. {@link GroundItemsHiddenTest} covers the matching and
 * {@link HiddenLootValuationTest} the values.
 */
public class HarnessGroundItemsHiddenTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.RUNE_PLATEBODY, "Rune platebody", 38_000, 39_000);
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.defineNotedItem(ItemID.Cert.BONES, ItemID.BONES);
		harness.defineItem(ItemID.NATURERUNE, "Nature rune", 90, 108);
	}

	private <T> T onEdt(Supplier<T> read)
	{
		AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}

	private String liveLootLine()
	{
		return onEdt(() ->
		{
			harness.panel().refresh();
			return harness.ui().getValuesText();
		}).split(" \\| ")[0];
	}

	private static String lootLine(long value)
	{
		return LedgerHistory.lootLabel(LootPriceMode.GE) + LedgerHistory.formatGp(value);
	}

	/** Starts a session with a platebody, 3 bones and 2 noted bones looted, and opens the live loot grid. */
	private void startLooting()
	{
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.postLoot(ItemID.RUNE_PLATEBODY, 1);
		harness.postLoot(ItemID.BONES, 3);
		harness.postLoot(ItemID.Cert.BONES, 2);
		harness.ticks(2);
		harness.onEdt(() -> harness.ui().getLiveLoot().toggle());
	}

	@Test
	public void liveLootLeavesHiddenItemsOutOfTheGridAndTheValue()
	{
		harness.setGroundItemsHidden("bones");
		startLooting();

		assertEquals("noted bones match as bones", lootLine(38_000), liveLootLine());
		assertEquals("Loot received (1, 2 hidden) | Hide", onEdt(() -> harness.ui().getLiveLoot().getHeaderText()));
		assertEquals(Collections.singletonList("Rune platebody | " + ItemID.RUNE_PLATEBODY + " | (alch)"),
			onEdt(() -> harness.ui().getLiveLoot().getCellTexts()));
		String tip = onEdt(() -> harness.ui().getLiveLoot().getHeaderTooltip());
		assertTrue(tip, tip.contains("2 items are hidden by your Ground Items<br>hidden list"));
		assertTrue(tip, tip.contains("hidden items<br>are left out of loot value, except coins."));

		// The setting turned off: everything counts again, at once (on the next tick).
		harness.setHideGroundItemsHidden(false);
		harness.tick();
		assertEquals(lootLine(38_500), liveLootLine());
		assertEquals("Loot received (3) | Hide", onEdt(() -> harness.ui().getLiveLoot().getHeaderText()));

		// On again, and the list edited in Ground Items: applied without a restart.
		harness.setHideGroundItemsHidden(true);
		harness.setGroundItemsHidden("Rune*");
		harness.tick();
		assertEquals(lootLine(500), liveLootLine());
		assertEquals("Loot received (2, 1 hidden) | Hide", onEdt(() -> harness.ui().getLiveLoot().getHeaderText()));

		// Ground Items turned off: its list no longer applies.
		harness.setGroundItemsConfig(GroundItemsHidden.PLUGIN_ENABLED_GROUP, GroundItemsHidden.PLUGIN_ENABLED_KEY,
			"false");
		harness.tick();
		assertEquals(lootLine(38_500), liveLootLine());
		harness.setGroundItemsConfig(GroundItemsHidden.PLUGIN_ENABLED_GROUP, GroundItemsHidden.PLUGIN_ENABLED_KEY,
			"true");
		harness.tick();
		assertEquals(lootLine(500), liveLootLine());

		// Never edited: Ground Items' built-in list, which hides Bones.
		harness.setGroundItemsHidden(null);
		harness.tick();
		assertEquals(lootLine(38_000), liveLootLine());
	}

	@Test
	public void onlyGroundItemsOwnSettingsAreRead()
	{
		startLooting();
		// Another Ground Items setting, or another plugin's, changes nothing.
		harness.setGroundItemsConfig(GroundItemsHidden.GROUP, "showHighlightedOnly", "true");
		harness.setGroundItemsConfig("lootTracker", GroundItemsHidden.HIDDEN_ITEMS_KEY, "Bones");
		harness.tick();
		assertEquals(lootLine(38_500), liveLootLine());
	}

	@Test
	public void theTaskCompleteLineLeavesHiddenLootOut()
	{
		harness.setGroundItemsHidden("Bones");
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.setRemaining(1);
		harness.lootOnNextTick(ItemID.RUNE_PLATEBODY, 1);
		harness.tick();
		harness.lootOnNextTick(ItemID.BONES, 10);
		harness.tick();
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		ArgumentCaptor<QueuedMessage> message = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, times(1)).queue(message.capture());
		String line = message.getValue().getRuneLiteFormattedMessage();
		assertTrue(line, line.endsWith(" · +" + LedgerHistory.formatAmount(38_000L, false)));
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals("the saved loot keeps the bones", Long.valueOf(10), record.getLoot().get(ItemID.BONES));
		assertEquals("and its saved value", Long.valueOf(39_000), record.getLootGeValue());
	}

	private static String profitLine(long profit)
	{
		return "Profit (GE): | " + LedgerHistory.formatAmount(profit, false) + " (n=1)";
	}

	/** A completed hour-long task: a platebody (30,000 saved) and 10 bones (50 saved), 600 gp of supplies. */
	private static LedgerRecord record()
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("a");
		r.setMonster("Abyssal demons");
