	@Test
	public void olderTasksHaveNoItemDetails() throws IOException
	{
		writeLedger();
		harness.loginAndSettle(ACCOUNT);
		harness.onEdt(() -> harness.ui().getHistory().clickRow(1));
		harness.drain();
