	@Test
	public void aSavedSkillThisClientDoesNotKnowGetsAnEmptyIconSlot() throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		// A key that is no Skill constant, as a file from a newer client could hold.
		String json = "{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"future\",\"monster\":\"Cows\","
			+ "\"initialAmount\":5,\"kills\":5,\"activeMillis\":3600000,\"startedAt\":1000,\"endedAt\":2000,"
			+ "\"completed\":true,\"partial\":false,\"xpGained\":{\"SLAYER\":200,\"FUTURE_SKILL\":100}}]}";
		Files.write(harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json"),
			json.getBytes(StandardCharsets.UTF_8));
		harness.loginAndSettle(ACCOUNT);
		harness.onEdt(() -> harness.ui().getHistory().clickRow(0));
		harness.drain();

		List<String> lines = details(0);
		assertEquals(Arrays.asList("Slayer | 200", "Future skill | 100"), lines.subList(lines.size() - 2, lines.size()));
		// No icon, but a slot of the same size, so both names line up.
		assertEquals(Arrays.asList("skill SLAYER 18x16", "- 18x16"),
			onEdt(() -> harness.ui().getHistory().getDetailsXpIcons(0)));
	}

	/**
	 * Writes a ledger with a task saved with items and prices (newest) and one saved before items were tracked.
	 */
	private void writeLedger() throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		int potion = ItemID._4DOSEPRAYERRESTORE;
		int shark = ItemID.SHARK;
		int platebody = ItemID.RUNE_PLATEBODY;
		String json = "{\"schemaVersion\":2,\"records\":["
			+ "{\"schemaVersion\":2,\"id\":\"new\",\"monster\":\"Abyssal demons\",\"initialAmount\":10,\"kills\":10,"
			+ "\"activeMillis\":60000,\"startedAt\":3000,\"endedAt\":63000,\"completed\":true,\"partial\":false,"
			+ "\"loot\":{\"" + platebody + "\":1},"
			+ "\"supplies\":{\"" + shark + "\":3,\"" + potion + "\":6},"
			+ "\"supplyDoses\":{\"" + potion + "\":4},"
			+ "\"unitGePrices\":{\"" + platebody + "\":30000,\"" + shark + "\":500,\"" + potion + "\":6000},"
			+ "\"unitHaPrices\":{\"" + platebody + "\":39000,\"" + shark + "\":50,\"" + potion + "\":100},"
			+ "\"lootGeValue\":30000,\"lootHaValue\":39000,\"suppliesGeValue\":10500,\"suppliesHaValue\":300},"
			+ "{\"schemaVersion\":1,\"id\":\"old\",\"monster\":\"Cows\",\"initialAmount\":5,\"kills\":5,"
			+ "\"activeMillis\":60000,\"startedAt\":1000,\"endedAt\":2000,\"completed\":true,\"partial\":false}"
			+ "]}";
		Files.write(harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json"),
			json.getBytes(StandardCharsets.UTF_8));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.concurrent.Future;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The Keep/Discard dialog that Stop shows for an unfinished task while "Confirm before saving incomplete tasks" is on
 * (the default), through the plugin's wiring ({@link PluginHarness}, with the dialog's answer scripted): Keep saves one
 * partial record, Discard saves none, and a dialog still open when the plugin is turned off or the client exits is
 * saved as partial exactly once, with the late answer saving nothing more (checked by the work it queues, as the ledger
 * also skips a record id it already holds). Each test also checks the account's
 * active-session file, which the logout before Stop has written. {@link SaveDecisionTest} covers the decision itself.
 */
public class HarnessKeepDiscardPromptTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The id of the session Stop ends; its active-session file was written at the logout. */
	private String sessionId;

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);

		// Two kills, then a logout and login, so the session has an active-session file when Stop is pressed.
		assertTrue(harness.play());
		harness.setRemaining(8);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.tick();

		final SessionSnapshot active = harness.activeSession(ACCOUNT);
		assertNotNull(active);
		sessionId = active.getSessionId();
		assertTrue(harness.records(ACCOUNT).isEmpty());
	}

	/** The account's one record: the partial session Stop ended. */
	private void assertOnePartialRecord()
	{
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isPartial());
		assertFalse(record.isCompleted());
		assertEquals(sessionId, record.getId());
		assertEquals(TASK_NAME, record.getMonster());
		assertEquals(2, record.getKills());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.BONES));
	}

	@Test
	public void keepSavesOnePartialRecord()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.KEEP);
		harness.stop();

		assertEquals(1, harness.promptsShown());
		assertOnePartialRecord();
		assertNull("the active file goes once the record is saved", harness.activeSession(ACCOUNT));
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());

		harness.clientShutdown();
		harness.shutDown();
		assertOnePartialRecord();
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void discardSavesNothingAndRemovesTheActiveFile()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.DISCARD);
		harness.stop();

		assertEquals(1, harness.promptsShown());
		assertTrue(harness.records(ACCOUNT).isEmpty());
		assertNull("a discarded session is not restored later", harness.activeSession(ACCOUNT));
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());

		harness.clientShutdown();
		harness.shutDown();
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("nothing restored", SessionTracker.State.IDLE, harness.sessionState());
		assertTrue(harness.records(ACCOUNT).isEmpty());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void keepAnsweredAfterTheDialogWasOpenSavesOnce()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.stop();
		assertTrue(harness.isPromptOpen());
		assertTrue("nothing saved while the dialog is open", harness.records(ACCOUNT).isEmpty());
		assertNotNull(harness.activeSession(ACCOUNT));

		assertTrue("Keep queues the save", harness.answerOpenPrompt(true) > 0);
		assertFalse(harness.isPromptOpen());
		assertOnePartialRecord();
		assertNull(harness.activeSession(ACCOUNT));

		harness.clientShutdown();
		harness.shutDown();
		assertOnePartialRecord();
		assertEquals(1, harness.promptsShown());
	}

	@Test
	public void pluginShutDownWhileTheDialogIsOpenSavesThePartialOnce()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.stop();
		assertTrue(harness.isPromptOpen());

		harness.shutDown();
		assertOnePartialRecord();
		assertNull(harness.activeSession(ACCOUNT));

		// The dialog outlives the plugin; its late answer saves nothing more.
		assertTrue(harness.isPromptOpen());
		assertEquals("the late Keep queues no second save", 0, harness.answerOpenPrompt(true));
		assertOnePartialRecord();
		assertNull(harness.activeSession(ACCOUNT));
		assertEquals(1, harness.promptsShown());
	}

	@Test
	public void pluginShutDownWhileTheDialogIsOpenKeepsThePartialWhenDiscardIsAnsweredLate()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.stop();

		harness.shutDown();
		assertEquals("the late Discard queues no delete", 0, harness.answerOpenPrompt(false));
		assertOnePartialRecord();
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void clientExitWhileTheDialogIsOpenSavesThePartialOnceAndWaitsForIt()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.stop();
		assertTrue(harness.isPromptOpen());

		final List<Future<?>> waitedFor = harness.clientShutdown();
		assertEquals("the client waits for the partial's save", 1, waitedFor.size());
		assertTrue(waitedFor.get(0).isDone());
		assertOnePartialRecord();
		assertNull(harness.activeSession(ACCOUNT));

		// The plugin is stopped as the client closes, then the dialog's late answer comes; neither saves again.
		harness.shutDown();
		assertEquals("the late Keep queues no second save", 0, harness.answerOpenPrompt(true));
		assertOnePartialRecord();
		assertNull(harness.activeSession(ACCOUNT));
		assertEquals(1, harness.promptsShown());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Where the ledger files live and when that is decided: the descriptor names the plugin directory and the legacy
 * directory RuneLite migrates, the directory is resolved once on the executor (never the client thread or the EDT),
 * and a directory that cannot be resolved leaves the plugin running without saving, through startUp, saves and
 * shutDown. The migration itself is RuneLite's ({@code Plugin#getPluginDirectory}) and is not exercised here: tests
 * never call it, so they never touch {@code ~/.runelite}.
 */
public class HarnessLedgerDirectoryTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** Thread descriptions of every directory resolution: "executor", "client thread", "EDT" or "other". */
	private final List<String> resolvedOn = new CopyOnWriteArrayList<>();
	private final AtomicInteger failuresLeft = new AtomicInteger();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		final Filepath directory = Filepath.Unchecked.getRooted(harness.ledgerDirectory().toPath());
		harness.plugin.setLedgerDirectorySource(() ->
		{
			resolvedOn.add(currentThread());
			if (failuresLeft.getAndUpdate(n -> Math.max(0, n - 1)) > 0)
			{
				throw new IOException("plugin directory unavailable");
			}
			return directory;
		});
	}

	private String currentThread()
	{
		if (harness.executor.isRunningTask())
		{
			return "executor";
		}
		if (SwingUtilities.isEventDispatchThread())
		{
			return "EDT";
		}
		return harness.isClientThread() ? "client thread" : "other";
	}

	/** Logs in on the task, plays and kills two of the ten. */
	private void loginPlayAndKillTwo()
	{
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.setRemaining(8);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
	}

	private String[] savedFiles()
	{
		return harness.ledgerDirectory().list();
	}

	@Test
	public void descriptorNamesThePluginDirectoryAndTheLegacyDirectory()
	{
		final PluginDescriptor descriptor = SlayerLedgerPlugin.class.getAnnotation(PluginDescriptor.class);
		assertNotNull(descriptor);
		assertEquals("slayer-ledger", descriptor.internalName());
		assertEquals("slayer-ledger", descriptor.legacyDataDirectory());

		// getPluginDirectory joins these as single segments (the legacy one must not be a RuneLite directory); both
		// throw for an unusable name. Only paths are built here, nothing is read or written.
		final Path fakeRuneLiteDir = harness.ledgerDirectory().toPath();
		assertEquals("slayer-ledger", Filepath.Unchecked.getRooted(fakeRuneLiteDir.resolve("plugin-data"))
			.joinSegment(descriptor.internalName()).getFileName());
		assertEquals("slayer-ledger", Filepath.Unchecked.getLegacyPluginDirectory(fakeRuneLiteDir,
			descriptor.legacyDataDirectory()).getFileName());
	}

	@Test
	public void directoryIsResolvedOnceOnTheExecutorAtStartUp()
	{
		harness.startUp();
		assertEquals("resolved by startUp's executor task", 1, resolvedOn.size());
		assertEquals("executor", resolvedOn.get(0));

		loginPlayAndKillTwo();
		harness.stop();
		harness.onlyRecord(ACCOUNT);
		harness.shutDown();
		assertEquals("kept for the plugin's lifetime", 1, resolvedOn.size());
	}

	@Test
	public void failedResolutionKeepsThePluginRunningWithoutSaving()
	{
		failuresLeft.set(Integer.MAX_VALUE);
		harness.startUp();
		loginPlayAndKillTwo();
		assertEquals("tracking still works", 2, harness.tracker().getKills());

		harness.stop();
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());
		assertTrue(harness.play());
		harness.setRemaining(7);
		harness.tick();
		// Shutdown with a running session tries to persist it and fails quietly (logged), like any IO failure.
		harness.shutDown();

		assertEquals("nothing written", 0, savedFiles().length);
		assertTrue("each operation tried again", resolvedOn.size() > 2);
		assertTrue(resolvedOn.stream().allMatch("executor"::equals));
	}

	@Test
	public void resolutionThatFailedAtStartUpIsRetriedByTheNextOperation()
	{
		failuresLeft.set(1);
		harness.startUp();
		assertEquals(1, resolvedOn.size());
		loginPlayAndKillTwo();
		harness.stop();

		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(2, record.getKills());
		assertNull(harness.activeSession(ACCOUNT));
		assertEquals("resolved by the history load after login, then kept", 2, resolvedOn.size());
		assertFalse(resolvedOn.contains("client thread"));
		assertFalse(resolvedOn.contains("EDT"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.NavigationButton;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * Plugin start and stop through the client's wiring ({@link PluginHarness}): registration with a real event bus, the
 * sidebar button, the completion grace ticker's registration, and recovery from a failed start.
 */
public class HarnessLifecycleTest
{
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void startedPluginReceivesEventsFromTheEventBus()
	{
		harness.startUp();
		assertFalse("logged out", harness.canPlay());

		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.login(PluginHarness.ACCOUNT);
		harness.ticks(PluginHarness.SETTLE_TICKS - 1);
		assertFalse("task not read while the login settles", harness.canPlay());
		harness.tick();

		// Only true if onGameStateChanged and onGameTick both ran.
		assertTrue(harness.canPlay());
		assertEquals(TASK_NAME, harness.tracker().getCurrentMonster());
		assertEquals(10, harness.tracker().getCurrentRemaining());
	}

	@Test
	public void navigationButtonIsAddedOnStartAndRemovedOnStop()
	{
		harness.startUp();
		ArgumentCaptor<NavigationButton> added = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar).addNavigation(added.capture());
		assertEquals("Slayer Ledger", added.getValue().getTooltip());
		assertNotNull(added.getValue().getPanel());
		verify(harness.clientToolbar, never()).removeNavigation(any());

		harness.shutDown();
		verify(harness.clientToolbar).removeNavigation(added.getValue());
	}

	@Test
	public void stoppedPluginIgnoresEvents()
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		harness.shutDown();

		// Neither the plugin nor its grace ticker is left subscribed, so no handler of the plugin reads the client.
		final int callsWhenStopped = harness.pluginCallCount();
		assertTrue("the running plugin read the client, so the count works", callsWhenStopped > 0);
		harness.setRemaining(9);
		harness.ticks(3);
		harness.lootOnNextTick(526, 1);
		harness.tick();
		harness.postLoot(526, 1);
		harness.chat(ChatMessageType.GAMEMESSAGE, "You pick the man's pocket.");
		harness.clickMenu("Drop", 526);
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.localPlayerDies();
		harness.hop();
		harness.logout();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertEquals("client calls by a stopped plugin", callsWhenStopped, harness.pluginCallCount());

		assertFalse(harness.canPlay());
		assertTrue(harness.records(PluginHarness.ACCOUNT).isEmpty());
		assertNull(harness.activeSession(PluginHarness.ACCOUNT));
	}

	/**
	 * startUp (EDT) only queues the reset of the client-thread state, and the handlers are registered right after it, so
	 * a client frame may post events before that block runs. Until it has, the handlers do nothing: no client reads, and
	 * nothing from the previous run (here a settled login, which would read the task at once).
	 */
	@Test
	public void handlersWaitForTheStartUpResetOfClientThreadState()
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		harness.shutDown();

		harness.startUpWithoutDrain();
		final int callsBeforeReset = harness.pluginCallCount();
		harness.postWithoutDrain(new GameTick());
		final GameStateChanged loggedIn = new GameStateChanged();
		loggedIn.setGameState(GameState.LOGGED_IN);
		harness.postWithoutDrain(loggedIn);
		harness.postWithoutDrain(new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", "You pick the man's pocket.",
			null, 0));
		assertEquals("no handler read the client before the reset", callsBeforeReset, harness.pluginCallCount());
		assertFalse("the task was not read with the previous run's state", harness.tracker().isTaskObserved());
		assertFalse(harness.canPlay());

		// The block reads the game state and account itself, so the skipped GameStateChanged loses nothing; the login
		// settles afresh before the task is read.
		harness.drain();
		harness.ticks(PluginHarness.SETTLE_TICKS - 1);
		assertFalse("task not read while the login settles", harness.tracker().isTaskObserved());
		harness.tick();
		assertTrue(harness.canPlay());
		assertEquals(10, harness.tracker().getCurrentRemaining());
	}

	@Test
	public void startingWhileLoggedInPicksUpTheAccountAndTask()
	{
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.setAccountHash(PluginHarness.ACCOUNT);
		harness.setGameStateSilently(GameState.LOGGED_IN);

		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);

		assertTrue(harness.canPlay());
		assertTrue(harness.play());
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(PluginHarness.ACCOUNT, harness.tracker().getSessionAccountHash());
	}

	@Test
	public void failedStartUpIsCleanedUpByShutDown()
	{
		doThrow(new IllegalStateException("toolbar unavailable")).when(harness.clientToolbar).addNavigation(any());
		try
		{
			harness.startUp();
			fail("startUp should have failed");
		}
		catch (IllegalStateException e)
		{
			assertEquals("toolbar unavailable", e.getMessage());
			assertEquals("shutDown after the failed startUp threw", 0, e.getSuppressed().length);
		}
		assertFalse(harness.isRunning());
		ArgumentCaptor<NavigationButton> button = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar).addNavigation(button.capture());
		verify(harness.clientToolbar).removeNavigation(button.getValue());

		// Nothing is left subscribed: game events after the failed start reach nothing and throw nothing.
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertFalse(harness.canPlay());
	}

	@Test
	public void pluginStartsNormallyAfterAFailedStart()
	{
		doThrow(new IllegalStateException("toolbar unavailable")).doNothing()
			.when(harness.clientToolbar).addNavigation(any());
		try
		{
			harness.startUp();
			fail("startUp should have failed");
		}
		catch (IllegalStateException expected)
		{
			// Retried below.
		}

		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 3, 3);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertTrue(harness.play());
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.tick();
		assertTrue("the ticker counts each tick once", harness.tracker().hasPendingCompletion());
		harness.tick();
		assertTrue(harness.onlyRecord(PluginHarness.ACCOUNT).isCompleted());
	}

	@Test
	public void shutDownWithoutStartUpDoesNotThrow()
	{
		harness.onEdt(harness.plugin::shutDown);
		verify(harness.clientToolbar, never()).removeNavigation(any());
	}

	@Test
	public void restartDoesNotRegisterTheGraceTickerTwice()
	{
		harness.startUp();
		harness.shutDown();
		harness.startUp();
		verify(harness.clientToolbar, times(2)).addNavigation(any());

		harness.setTask(TASK, TASK_NAME, 3, 3);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertTrue(harness.play());
		harness.setRemaining(1);
		harness.tick();
		harness.completeTask();
		harness.tick();

		// Held on the completion tick, then two more ticks. A second ticker registration would halve the window.
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		assertTrue(harness.records(PluginHarness.ACCOUNT).isEmpty());
		harness.tick();
		assertFalse(harness.tracker().hasPendingCompletion());
		LedgerRecord record = harness.onlyRecord(PluginHarness.ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(3, record.getKills());
	}

	@Test
	public void restartKeepsTheSameNavigationLifecycle()
	{
		harness.startUp();
		harness.shutDown();
		harness.startUp();
		harness.shutDown();
		ArgumentCaptor<NavigationButton> added = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar, times(2)).addNavigation(added.capture());
		ArgumentCaptor<NavigationButton> removed = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar, times(2)).removeNavigation(removed.capture());
		assertSame(added.getAllValues().get(0), removed.getAllValues().get(0));
		assertSame(added.getAllValues().get(1), removed.getAllValues().get(1));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The panel's live session lines as wired in the plugin ({@link PluginHarness}): the time-left line, live values
 * that belong to another session, and the valuation throttle when pricing fails. {@link TaskTimeEstimateTest} and
 * {@link SessionValuationTest} cover the calculations.
 */
public class HarnessLiveValuesTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** A valuation that throws (an unexpected failure) until {@link #fail} is cleared, counting its calls. */
	private static final class FailingValuation extends SessionValuation
	{
		volatile boolean fail = true;
		int attempts;

		@Override
		Values update(String sessionId, ItemTally loot, ItemTally supplies, Map<Integer, Integer> doses,
			LootPriceMode mode, HiddenLoot hidden, ItemValuation.PriceLookup lookup, int tick)
		{
			attempts++;
			if (fail)
			{
				throw new IllegalStateException("valuation failure (set by the test)");
			}
			return super.update(sessionId, loot, supplies, doses, mode, hidden, lookup, tick);
		}
	}

	/** Stands {@code valuation} in for the plugin's live session valuation. */
	private void replaceSessionValuation(SessionValuation valuation)
	{
		harness.plugin.setSessionValuation(valuation);
	}

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Refreshes the panel from the tracker (as its timer does) and returns whether the time-left line is shown. */
	private boolean timeLeftShown()
	{
		final boolean[] shown = new boolean[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			shown[0] = harness.ui().isTimeLeftShown();
		});
		return shown[0];
	}

	private String timeLeftText()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getTimeLeftText();
		});
		return text[0];
	}

	private boolean valuesShown()
	{
		final boolean[] shown = new boolean[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			shown[0] = harness.ui().isValuesShown();
		});
		return shown[0];
	}

	@Test
	public void timeLeftIsShownOnlyWhileRunningOrPaused()
	{
		assertFalse("idle", timeLeftShown());

		assertTrue(harness.play());
		assertTrue("running", timeLeftShown());
		assertEquals("no kills yet", LiveSessionSection.TIME_LEFT_ESTIMATING, timeLeftText());

		harness.pause();
		assertTrue("paused", timeLeftShown());

		harness.stop();
		assertFalse("stopped", timeLeftShown());
	}

	@Test
	public void valuesOfAnotherSessionAreIgnored()
	{
		assertTrue(harness.play());
		harness.ticks(2);
		assertTrue("the plugin's own values are shown", valuesShown());

		final String current = harness.tracker().getSessionId();
		assertNotNull(current);
		harness.onEdt(() -> harness.panel().setSessionValues(
			new SessionValuation.Values("an-ended-session", 1_000, 0, 0, 0, 0, 0)));
		assertFalse("values of another session are not shown", valuesShown());

		harness.onEdt(() -> harness.panel().setSessionValues(new SessionValuation.Values(current, 1_000, 0, 0, 0, 0, 0)));
		assertTrue(valuesShown());
	}

	@Test
	public void newSessionWithEqualAmountsIsStillShown()
	{
		assertTrue(harness.play());
		harness.ticks(2);
		assertTrue(valuesShown());
		final String first = harness.tracker().getSessionId();

		// Stop and start again between ticks: the new session's values have the same (zero) amounts as the old one's.
		harness.stop();
		assertTrue(harness.play());
		assertNotEquals(first, harness.tracker().getSessionId());
		harness.ticks(2);
		assertTrue("the new session's values are published although the amounts are equal", valuesShown());
	}

	@Test
	public void shownValuesFilter()
	{
		SessionValuation.Values values = new SessionValuation.Values("s1", 0, 0, 0, 0, 0, 0);
		assertSame(values, LiveSessionSection.shownValues(values, SessionTracker.State.RUNNING, "s1"));
		assertSame(values, LiveSessionSection.shownValues(values, SessionTracker.State.PAUSED, "s1"));
		assertNull(LiveSessionSection.shownValues(values, SessionTracker.State.RUNNING, "s2"));
		assertNull(LiveSessionSection.shownValues(values, SessionTracker.State.RUNNING, null));
		assertNull(LiveSessionSection.shownValues(values, SessionTracker.State.STOPPED, "s1"));
		assertNull(LiveSessionSection.shownValues(null, SessionTracker.State.RUNNING, "s1"));
	}

	@Test
	public void aLootPriceChangeIsValuedAtOnceButAFailingValuationStaysThrottled()
	{
		final FailingValuation valuation = new FailingValuation();
		replaceSessionValuation(valuation);
		assertTrue(harness.play());
		harness.ticks(1);
		assertEquals(1, valuation.attempts);

		// The next tick would be throttled; a new setting is valued on it anyway, but only once.
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.ticks(1);
		assertEquals(2, valuation.attempts);
		harness.ticks(1);
		assertEquals(2, valuation.attempts);
		harness.ticks(1);
		assertEquals(3, valuation.attempts);
	}

	@Test
	public void failingValuationIsStillThrottled()
	{
		final FailingValuation valuation = new FailingValuation();
		replaceSessionValuation(valuation);
		assertTrue(harness.play());
		harness.postLoot(ItemID.BONES, 1);

		// A new session is valued on its first tick.
		harness.ticks(1);
		assertEquals(1, valuation.attempts);

		// The first valuation fails, so no values have ever been shown.
		harness.ticks(9);
		// One attempt every 2 ticks, not one every tick.
		assertEquals(5, valuation.attempts);
		assertFalse(valuesShown());

		// Once valuing works again the values come back.
		valuation.fail = false;
		harness.ticks(2);
		assertTrue(valuesShown());
		harness.stop();
		assertEquals(Long.valueOf(100), harness.onlyRecord(ACCOUNT).getLootGeValue());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Rule;
import org.junit.Test;

public class HarnessLuckMeterTest
{
	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void meterStartsCollapsedAndRefreshesAfterItemNamesAreLookedUp()
	{
		harness.defineItem(1001, "Abyssal whip", 1_500_000, 0);
		harness.defineItem(1002, "Abyssal dagger", 20_000_000, 0);
		harness.defineItem(1003, "Granite maul", 200_000, 0);
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);

		Map<Integer, Long> loot = new HashMap<>();
		loot.put(1001, 2L);
		loot.put(1002, 1L);
		LedgerRecord demons = record("Abyssal demons", 512, loot);
		LedgerRecord gargoyles = record("Gargoyles", 256, Collections.singletonMap(1003, 1L));
		// Saved before loot tracking: its kills must not count.
		LedgerRecord old = record("Abyssal demons", 5_000, null);
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT,
			Arrays.asList(demons, gargoyles, old)));

		boolean[] expanded = new boolean[1];
		harness.onEdt(() -> expanded[0] = harness.ui().getLuckMeter().isExpanded());
		assertFalse(expanded[0]);

		harness.onEdt(() -> harness.ui().getLuckMeter().clickTitle());
		harness.drain();
		List<String> rows = rows();
		assertEquals(Arrays.asList(
			"Abyssal whip | 2.0x\nObserved / expected: | 2 / 1.00",
			"Abyssal dagger | too few kills\nObserved / expected: | 1 / 0.02"), rows);
		assertEquals("1 task / 512 kills with loot data", summary());
		List<String> tooltips = tooltips();
		assertTrue(tooltips.get(1), tooltips.get(1).contains("Chance of at least 1: 1.6% (Poisson model)"));
		assertTrue(tooltips.get(1), tooltips.get(1).contains("Too few kills for a ratio"));
		assertTrue(tooltips.get(0), tooltips.get(0).contains("Observed / expected: 2.00x"));

		harness.onEdt(() -> harness.ui().getLuckMeter().setTask("Gargoyles"));
		harness.drain();
		rows = rows();
		assertEquals(2, rows.size());
		assertEquals("Granite maul | 1.0x\nObserved / expected: | 1 / 1.00", rows.get(0));
	}

	@Test
	public void namesAreNotEscapedAndFailedNamesAreNoted()
	{
		harness.defineItem(1001, "Abyssal whip", 1_500_000, 0);
		// A "null" name is a failed lookup, as in the game.
		harness.defineItem(1009, "null", 0, 0);
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		Map<Integer, Long> loot = new HashMap<>();
		loot.put(1001, 1L);
		loot.put(1009, 1L);
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT,
			Collections.singletonList(record("Abyssal demons", 1_024, loot))));
		harness.onEdt(() -> harness.ui().getLuckMeter().clickTitle());
		harness.drain();
		List<String> rows = rows();
		assertEquals(3, rows.size());
		assertEquals("Abyssal whip | 0.5x\nObserved / expected: | 1 / 2.00", rows.get(0));
		assertEquals("Some item names unavailable.", rows.get(2));
		assertTrue(tooltips().get(0).contains("observed counts may be incomplete"));
	}

	@Test
	public void nothingIsBuiltWhileCollapsedOrByTheRefreshTimerOrPrices()
	{
		harness.defineItem(1001, "Abyssal whip", 1_500_000, 0);
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		LedgerRecord record = record("Abyssal demons", 512, Collections.singletonMap(1001, 1L));
		int[] builds = new int[2];
		harness.onEdt(() ->
		{
			SlayerLedgerPanel panel = harness.panel();
			PanelProbe ui = harness.ui();
			builds[0] = ui.getLuckMeter().getBuildCount();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(record));
			panel.refresh();
			builds[1] = ui.getLuckMeter().getBuildCount();
		});
		assertEquals("collapsed: nothing built", builds[0], builds[1]);
		assertTrue(rows().isEmpty());

		harness.onEdt(() -> harness.ui().getLuckMeter().clickTitle());
		harness.drain();
		assertEquals(2, rows().size());
		harness.onEdt(() ->
		{
			SlayerLedgerPanel panel = harness.panel();
			PanelProbe ui = harness.ui();
			builds[0] = ui.getLuckMeter().getBuildCount();
			panel.refresh();
			panel.refresh();
			builds[1] = ui.getLuckMeter().getBuildCount();
		});
		assertEquals("the refresh timer never rebuilds", builds[0], builds[1]);

		// The meter uses no prices: the Loot price mode and today's prices arriving don't rebuild it.
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.onEdt(() -> harness.historyModel().addCurrentPrices(Collections.singleton(ItemValuation.COINS),
			Collections.singletonMap(ItemValuation.COINS, 1L)));
		harness.drain();
		harness.onEdt(() -> builds[1] = harness.ui().getLuckMeter().getBuildCount());
		assertEquals("prices never rebuild", builds[0], builds[1]);

		// Collapsing drops the rows; record changes while collapsed build nothing.
		harness.onEdt(() ->
		{
			PanelProbe ui = harness.ui();
			ui.getLuckMeter().clickTitle();
			builds[0] = ui.getLuckMeter().getBuildCount();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(record));
			builds[1] = ui.getLuckMeter().getBuildCount();
		});
		assertEquals(builds[0], builds[1]);
		assertTrue(rows().isEmpty());
	}

	private List<String> rows()
	{
		Object[] rows = new Object[1];
		harness.onEdt(() -> rows[0] = harness.ui().getLuckMeter().getRows());
		@SuppressWarnings("unchecked")
		List<String> result = (List<String>) rows[0];
		return result;
	}

	private List<String> tooltips()
	{
		Object[] tooltips = new Object[1];
		harness.onEdt(() -> tooltips[0] = harness.ui().getLuckMeter().getTooltips());
		@SuppressWarnings("unchecked")
		List<String> result = (List<String>) tooltips[0];
		return result;
	}

	private String summary()
	{
		String[] summary = new String[1];
		harness.onEdt(() -> summary[0] = harness.ui().getLuckMeter().getSummary());
		return summary[0];
	}

	private static LedgerRecord record(String monster, int kills, Map<Integer, Long> loot)
	{
		LedgerRecord record = new LedgerRecord();
		record.setMonster(monster);
		record.setKills(kills);
		record.setCompleted(true);
		record.setPartial(false);
		record.setLoot(loot);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
