		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);
	}

	/** A completed Konar task of {@code name}, without values. */
	private static LedgerRecord monster(String name, int kills, long activeMillis)
	{
		LedgerRecord record = record(SlayerMaster.KONAR, 1, activeMillis);
		record.setMonster(name);
		record.setKills(kills);
		return record;
	}

	/** A Konar "Skipped / blocked" entry. */
	private static AssignmentEntry entry(String name, AssignmentOutcome outcome)
	{
		AssignmentEntry entry = new AssignmentEntry();
		entry.setId(UUID.randomUUID().toString());
		entry.setMonster(name);
		entry.setSlayerMaster(SlayerMaster.KONAR);
		entry.setOutcome(outcome);
		entry.setEndedAt(1);
		return entry;
	}

	/** Reads {@code read} on the EDT. */
	private <T> T onEdt(Supplier<T> read)
	{
		AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}

	/** Asserts that each tooltip contains its expected text, in order. */
	private static void assertTooltips(List<String> tooltips, String... expected)
	{
		assertEquals(tooltips.toString(), expected.length, tooltips.size());
		for (int i = 0; i < expected.length; i++)
		{
			assertTrue(tooltips.get(i), tooltips.get(i).contains(expected[i]));
		}
	}

	/**
	 * A Konar task with {@code supplies} and one rune platebody of loot per {@code platebodies}, at saved prices (shark
	 * 1,000, prayer potion 8,000, platebody GE 38,000 and high alch 39,000), valued as the plugin saves it.
	 */
	private static LedgerRecord itemized(Map<Integer, Long> supplies, long platebodies)
	{
		LedgerRecord record = record(SlayerMaster.KONAR, 1, 60_000L);
		record.setSupplies(supplies);
		record.setLoot(Collections.singletonMap(ItemID.RUNE_PLATEBODY, platebodies));
		record.setUnitGePrices(map(ItemID.SHARK, 1_000, ItemID._4DOSEPRAYERRESTORE, 8_000, ItemID.RUNE_PLATEBODY,
			38_000));
		record.setUnitHaPrices(map(ItemID.SHARK, 50, ItemID._4DOSEPRAYERRESTORE, 100, ItemID.RUNE_PLATEBODY, 39_000));
		record.setLootGeValue(38_000L * platebodies);
		record.setLootHaValue(39_000L * platebodies);
		long supplyValue = 0;
		for (Map.Entry<Integer, Long> e : supplies.entrySet())
		{
			supplyValue += e.getKey() == ItemID.SHARK ? 1_000 * e.getValue() : 2_000 * e.getValue();
		}
		record.setSuppliesGeValue(supplyValue);
		return record;
	}

	private static Map<Integer, Long> map(long... idValue)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < idValue.length; i += 2)
		{
			m.put((int) idValue[i], idValue[i + 1]);
		}
		return m;
	}

	/** The profit line of the first entry. */
	private String profitLine()
	{
		return rows().get(0).split("\n")[2];
	}

	private List<String> rows()
	{
		@SuppressWarnings("unchecked")
		List<String>[] rows = new List[1];
		// The totals are worked out off the EDT.
		harness.drain();
		harness.onEdt(() -> rows[0] = harness.ui().getOverallTotals().getRows());
		return rows[0];
	}

	private List<String> tooltips()
	{
		@SuppressWarnings("unchecked")
		List<String>[] tooltips = new List[1];
		harness.drain();
		harness.onEdt(() -> tooltips[0] = harness.ui().getOverallTotals().getTooltips());
		return tooltips[0];
	}

	private static LedgerRecord record(Integer master, long endedAt, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setSlayerMaster(master);
		record.setEndedAt(endedAt);
		record.setKills(10);
		record.setActiveMillis(activeMillis);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.overlay.Overlay;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * The task overlay as wired in the plugin ({@link PluginHarness}): registration, what it shows as the session
 * changes, live values matched by session, the settings, the completion grace window and a re-login. {@link
 * OverlayRowsTest} covers the row text.
 */
public class HarnessOverlayTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final long MINUTE = 60_000;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The tracker's clock, so active time (and the time-left estimate) is under the test's control. */
	private final AtomicLong now = new AtomicLong(1_000_000_000L);

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.startUp();
		useTestClock();
		harness.setTask(42, "Abyssal demons", 12, 12);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Points the plugin's session tracker at {@link #now} (it reads the system clock otherwise). */
	private void useTestClock()
	{
		harness.setTrackerClock(now::get);
	}

	/** The overlay the plugin registered. */
	private SlayerLedgerOverlay overlay()
	{
		ArgumentCaptor<Overlay> overlay = ArgumentCaptor.forClass(Overlay.class);
		verify(harness.overlayManager, times(1)).add(overlay.capture());
		return (SlayerLedgerOverlay) overlay.getValue();
	}

	/** Renders the overlay as the client does (on the client thread); {@code null} when it draws nothing. */
	private java.awt.Dimension render()
	{
		BufferedImage image = new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			return overlay().render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}

	/** The rows the overlay shows now, with every row on. */
	private List<OverlayRows.Row> rows()
	{
		return OverlayRows.rows(harness.overlayData(), true, true, true, true);
	}

	private String value(String label)
	{
		for (OverlayRows.Row row : rows())
		{
			if (row.getLabel().equals(label))
			{
				return row.getValue();
			}
		}
		return null;
	}

	@Test
	public void registersOverlayAndShowsOnlyRunningOrPausedTaskSessions()
	{
		assertNull("idle sessions have no task overlay", harness.overlayData());
		assertNull(render());

		assertTrue(harness.play());
		OverlayRows.Data running = harness.overlayData();
		assertNotNull(running);
		assertEquals("Abyssal demons", running.getTaskName());
		assertEquals(12, running.getTask().getRemaining());
		assertNotNull("drawn while running", render());

		harness.pause();
		OverlayRows.Data paused = harness.overlayData();
		assertNotNull(paused);
		assertEquals(SessionTracker.State.PAUSED, paused.getTask().getState());
		assertEquals(12, paused.getTask().getRemaining());
		assertNotNull("drawn while paused", render());

		harness.stop();
		assertNull("stopped sessions have no task overlay", harness.overlayData());
		assertNull(render());

		harness.shutDown();
		verify(harness.overlayManager, times(1)).remove(any(Overlay.class));
	}

	@Test
	public void killsAndTimeLeftUpdateAfterAKill()
	{
		assertTrue(harness.play());
		assertEquals("Abyssal demons", value("Task"));
		assertEquals("12", value("Left"));
		assertEquals("0", value("Kills"));
		assertEquals(LedgerHistory.TIME_LEFT_ESTIMATING, value("Time left"));

		now.addAndGet(4 * MINUTE);
		harness.setRemaining(8);
		harness.tick();

		assertEquals("Abyssal demons", value("Task"));
		assertEquals("8", value("Left"));
		assertEquals("4", value("Kills"));
		// One kill a minute so far, 8 left.
		assertEquals("~8m", value("Time left"));
	}

	@Test
	public void profitComesFromThisSessionsPublishedValuesOnly()
	{
		assertTrue(harness.play());
		assertNull("not valued yet", value("Profit (GE)"));
		harness.postLoot(ItemID.BONES, 1);
		harness.tick();
		assertEquals("100 gp", value("Profit (GE)"));

		// A new session between ticks: the published values still belong to the old one.
		harness.stop();
		assertTrue(harness.play());
		assertNull("the previous session's values are ignored", value("Profit (GE)"));
		assertNull(harness.overlayData().getValues());

		// Valued once the 2-tick throttle from the old session's valuation has passed.
		harness.ticks(2);
		assertEquals("the new session's own values", "0 gp", value("Profit (GE)"));
	}

	@Test
	public void settingsHideTheOverlay()
	{
		assertTrue(harness.play());
		assertNotNull(render());

		harness.config.showTaskOverlay = false;
		assertNull("the master toggle hides it", render());

		harness.config.showTaskOverlay = true;
		harness.config.overlayTask = false;
		harness.config.overlayKills = false;
		harness.config.overlayTimeLeft = false;
		harness.config.overlayProfit = false;
		assertNull("nothing to draw with every row off", render());

		harness.config.overlayKills = true;
		assertNotNull(render());
	}

	@Test
	public void hiddenDuringTheCompletionGraceWindowAndAfterTheSave()
	{
		assertTrue(harness.play());
		harness.setRemaining(1);
		harness.tick();
		assertEquals("Abyssal demons", value("Task"));
		assertEquals("1", value("Left"));

		harness.completeTask();
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		assertNull("hidden once the final kill completes the task", harness.overlayData());
		assertNull(render());

		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertTrue(harness.onlyRecord(ACCOUNT).isCompleted());
		assertNull("hidden after the save", harness.overlayData());
		assertNull(render());
	}

	@Test
	public void aPausedSessionAfterReLoginIsNeverShownAsComplete()
	{
		assertTrue(harness.play());
		harness.setRemaining(10);
		harness.tick();
		harness.pause();
		harness.logout();

		harness.login(ACCOUNT);
		for (int i = 0; i < PluginHarness.SETTLE_TICKS; i++)
		{
			// Until the task is read again the kills left are unknown, never 0.
			assertEquals("tick " + i, SessionTracker.LiveTask.UNKNOWN_REMAINING,
				harness.overlayData().getTask().getRemaining());
			assertEquals("tick " + i, "Abyssal demons", value("Task"));
			assertEquals("tick " + i, "?", value("Left"));
			assertEquals("tick " + i, LedgerHistory.NO_VALUE, value("Time left"));
			assertEquals("tick " + i, "2", value("Kills"));
			harness.tick();
		}
		assertEquals("Abyssal demons", value("Task"));
		assertEquals("10", value("Left"));
	}

	@Test
	public void aClearedTaskWaitingForItsCompletionShowsUnknownKillsLeft()
	{
		assertTrue(harness.play());
		// The count reads 0 without a completion: possibly transient, so the session waits.
		harness.setRemaining(0);
		harness.tick();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());

		assertEquals(SessionTracker.LiveTask.UNKNOWN_REMAINING, harness.overlayData().getTask().getRemaining());
		assertEquals("Abyssal demons", value("Task"));
		assertEquals("?", value("Left"));
		assertEquals(LedgerHistory.NO_VALUE, value("Time left"));
	}

	/** A completed Abyssal demons task: 10 kills in 10 minutes, so one minute a kill. */
	private static LedgerRecord priorTask()
	{
		LedgerRecord prior = new LedgerRecord();
		prior.setCreatureId(42);
		prior.setMonster("Abyssal demons");
		prior.setKills(10);
		prior.setActiveMillis(10 * MINUTE);
		prior.setCompleted(true);
		return prior;
	}

	/** The sidebar's time-left line after a refresh (on the EDT, as the panel's timer runs it). */
	private String sidebarTimeLeft()
	{
		String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getTimeLeftText();
		});
		return text[0];
	}

	@Test
	public void earlyInATaskTheOverlayShowsTheSidebarsHistoricalEstimate()
	{
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, Collections.singletonList(priorTask())));
		assertTrue(harness.play());

		String sidebar = sidebarTimeLeft();
		assertEquals("12 kills at the history's minute a kill", "Time left: ~12m", sidebar);
		assertEquals(sidebar, "Time left: " + value("Time left"));

		// 1 kill in 30 seconds: too little for the live pace, so still the history, for the 11 left.
		now.addAndGet(MINUTE / 2);
		harness.setRemaining(11);
		harness.tick();
		sidebar = sidebarTimeLeft();
		assertEquals("Time left: ~11m", sidebar);
		assertEquals(sidebar, "Time left: " + value("Time left"));

		// 3 kills in 90 seconds: the live pace (30 seconds a kill, 9 left) takes over in both.
		now.addAndGet(MINUTE);
		harness.setRemaining(9);
		harness.tick();
		sidebar = sidebarTimeLeft();
		assertEquals("4m 30s rounds half up", "Time left: ~5m", sidebar);
		assertEquals(sidebar, "Time left: " + value("Time left"));
	}

	@Test
	public void theHistoricalEstimateIsClearedWithItsSession()
	{
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, Collections.singletonList(priorTask())));
		assertTrue(harness.play());
		assertEquals("Time left: ~12m", sidebarTimeLeft());
		assertEquals("~12m", value("Time left"));

		// A new session before the panel's next refresh: the old session's estimate is still the published one.
		harness.stop();
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, Collections.emptyList()));
		assertTrue(harness.play());
		assertEquals("the previous session's estimate is not reused before the panel refreshes",
			LedgerHistory.TIME_LEFT_ESTIMATING, value("Time left"));
		assertEquals(LiveSessionSection.TIME_LEFT_ESTIMATING, sidebarTimeLeft());
		assertEquals(LedgerHistory.TIME_LEFT_ESTIMATING, value("Time left"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.function.Supplier;
import org.junit.Rule;
import org.junit.Test;

/**
 * The "Panel sections" settings as wired in the plugin ({@link PluginHarness}): a hidden section takes no space,
 * builds nothing and asks for no item names; turned back on, it is rebuilt from the current data at once.
 */
public class HarnessPanelSectionsTest
{
	@Rule
	public final PluginHarness harness = new PluginHarness();

	private static final int WHIP = 1001;

	private <T> T onEdt(Supplier<T> read)
	{
		List<T> result = new ArrayList<>(1);
		harness.onEdt(() -> result.add(read.get()));
		return result.get(0);
	}

	private boolean shown(SlayerLedgerPanel.OptionalSection section)
	{
		return onEdt(() -> harness.ui().isSectionShown(section));
	}

	private int panelHeight()
	{
		return onEdt(() -> harness.panel().getPreferredSize().height);
	}

	@Test
	public void everySectionIsShownByDefaultAndAHiddenOneLeavesNoGap()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		Map<SlayerLedgerPanel.OptionalSection, String> keys = new HashMap<>();
		keys.put(SlayerLedgerPanel.OptionalSection.WHAT_TO_BRING, SlayerLedgerConfig.SHOW_WHAT_TO_BRING);
		keys.put(SlayerLedgerPanel.OptionalSection.TRENDS, SlayerLedgerConfig.SHOW_TRENDS);
		keys.put(SlayerLedgerPanel.OptionalSection.OVERALL_TOTALS, SlayerLedgerConfig.SHOW_OVERALL_TOTALS);
		keys.put(SlayerLedgerPanel.OptionalSection.LUCK_METER, SlayerLedgerConfig.SHOW_LUCK_METER);
		keys.put(SlayerLedgerPanel.OptionalSection.SKIPPED_BLOCKED, SlayerLedgerConfig.SHOW_SKIPPED_BLOCKED);
		for (SlayerLedgerPanel.OptionalSection section : SlayerLedgerPanel.OptionalSection.values())
		{
			assertTrue(section.name(), shown(section));
			int before = panelHeight();
			int header = onEdt(() -> harness.ui().getSectionHeaderHeight(section));
			harness.setPanelSection(keys.get(section), false);
			assertFalse(section.name(), shown(section));
			// A collapsed section is its header with a 6 px gap above it and above its hidden body; What to bring is
			// hidden here (no task), so only its gap is left. Hiding either takes all of it away.
			int expected = section == SlayerLedgerPanel.OptionalSection.WHAT_TO_BRING ? 6 : header + 12;
			assertEquals(section.name(), before - expected, panelHeight());
			harness.setPanelSection(keys.get(section), true);
			assertTrue(section.name(), shown(section));
			assertEquals(section.name(), before, panelHeight());
		}
	}

	@Test
	public void hiddenTrendsTotalsAndSkippedBlockedBuildNothingAndAreRebuiltWhenShown()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		LedgerRecord demons = completed("Abyssal demons", 42, 100, 10 * 60_000L);
		demons.setLootGeValue(100_000L);
		demons.setSuppliesGeValue(10_000L);
		AssignmentEntry skip = new AssignmentEntry();
		skip.setId("a1");
		skip.setMonster("Kurasks");
		skip.setEndedAt(1_000L);
		skip.setOutcome(AssignmentOutcome.SKIPPED);
		harness.onEdt(() ->
		{
			PanelProbe ui = harness.ui();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(demons));
			harness.historyModel().setAssignments(PluginHarness.ACCOUNT, Collections.singletonList(skip));
			ui.getTrends().toggle();
			ui.getOverallTotals().toggle();
			ui.getAssignments().toggle();
		});
		// Trends and the totals are worked out off the EDT.
		harness.drain();
		List<String> trendRows = onEdt(() -> harness.ui().getTrends().getRows());
		List<String> totalsRows = onEdt(() -> harness.ui().getOverallTotals().getRows());
		List<String> assignmentRows = onEdt(() -> harness.ui().getAssignments().getRows());
		assertEquals(1, trendRows.size());
		assertEquals(1, totalsRows.size());
		assertEquals(1, assignmentRows.size());

		Function<PanelProbe, int[]> builds = ui -> new int[]{ui.getTrends().getBuildCount(),
			ui.getOverallTotals().getBuildCount(), ui.getAssignments().getBuildCount()};
		harness.setPanelSection(SlayerLedgerConfig.SHOW_TRENDS, false);
		harness.setPanelSection(SlayerLedgerConfig.SHOW_OVERALL_TOTALS, false);
		harness.setPanelSection(SlayerLedgerConfig.SHOW_SKIPPED_BLOCKED, false);
		int[] hidden = onEdt(() -> builds.apply(harness.ui()));
		assertTrue(onEdt(() -> harness.ui().getTrends().getRows()).isEmpty());
		assertTrue(onEdt(() -> harness.ui().getOverallTotals().getRows()).isEmpty());
		assertTrue(onEdt(() -> harness.ui().getAssignments().getRows()).isEmpty());

		// New records and assignments, the Loot price mode, today's prices and the refresh timer build nothing while
		// hidden.
		LedgerRecord dagannoth = completed("Dagannoth", 120, 150, 20 * 60_000L);
		dagannoth.setLootGeValue(50_000L);
		dagannoth.setSuppliesGeValue(5_000L);
		AssignmentEntry block = new AssignmentEntry();
		block.setId("a2");
		block.setMonster("Gargoyles");
		block.setEndedAt(2_000L);
		block.setOutcome(AssignmentOutcome.BLOCKED);
		harness.onEdt(() ->
		{
			SlayerLedgerPanel panel = harness.panel();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Arrays.asList(dagannoth, demons));
			harness.historyModel().setAssignments(PluginHarness.ACCOUNT, Arrays.asList(block, skip));
			panel.refresh();
		});
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.setLootPriceMode(LootPriceMode.GE);
		harness.onEdt(() -> harness.historyModel().addCurrentPrices(Collections.singleton(ItemValuation.COINS),
			Collections.singletonMap(ItemValuation.COINS, 1L)));
		harness.drain();
		assertTrue(Arrays.equals(hidden, onEdt(() -> builds.apply(harness.ui()))));
		assertTrue(onEdt(() -> harness.ui().getTrends().getRows()).isEmpty());
		assertTrue(onEdt(() -> harness.ui().getOverallTotals().getRows()).isEmpty());
		assertTrue(onEdt(() -> harness.ui().getAssignments().getRows()).isEmpty());

		// Shown again: open as before and rebuilt once, at once, from the current data.
		harness.setPanelSection(SlayerLedgerConfig.SHOW_TRENDS, true);
		harness.setPanelSection(SlayerLedgerConfig.SHOW_OVERALL_TOTALS, true);
		harness.setPanelSection(SlayerLedgerConfig.SHOW_SKIPPED_BLOCKED, true);
		int[] reshown = onEdt(() -> builds.apply(harness.ui()));
		for (int i = 0; i < hidden.length; i++)
		{
			assertEquals("section " + i, hidden[i] + 1, reshown[i]);
		}
		// The rows come from the data set while hidden, not from before the hide.
		assertEquals(2, onEdt(() -> harness.ui().getTrends().getRows()).size());
		assertFalse(totalsRows.equals(onEdt(() -> harness.ui().getOverallTotals().getRows())));
		List<String> reshownAssignments = onEdt(() -> harness.ui().getAssignments().getRows());
		assertEquals(2, reshownAssignments.size());
		assertTrue(reshownAssignments.containsAll(assignmentRows));
		assertTrue(onEdt(() -> harness.ui().getTrends().isExpanded()));
		assertTrue(onEdt(() -> harness.ui().getOverallTotals().isExpanded()));
		assertTrue(onEdt(() -> harness.ui().getAssignments().isExpanded()));
	}

	@Test
	public void aLuckMeterHiddenAtStartUpAsksForNoItemNamesUntilShown()
	{
		harness.defineItem(WHIP, "Abyssal whip", 1_500_000, 0);
		harness.config.showLuckMeter = false;
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertFalse("hidden from the start", shown(SlayerLedgerPanel.OptionalSection.LUCK_METER));
		// Opened earlier (the header itself is hidden): still nothing is compared or named.
		harness.onEdt(() -> harness.ui().getLuckMeter().toggle());
		LedgerRecord demons = completed("Abyssal demons", 42, 512, 60 * 60_000L);
		demons.setLoot(Collections.singletonMap(WHIP, 2L));
		int[] builds = new int[1];
		harness.onEdt(() ->
		{
			SlayerLedgerPanel panel = harness.panel();
			PanelProbe ui = harness.ui();
			builds[0] = ui.getLuckMeter().getBuildCount();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(demons));
			panel.refresh();
		});
		harness.drain();
		assertEquals(builds[0], (int) onEdt(() -> harness.ui().getLuckMeter().getBuildCount()));
		assertTrue(onEdt(() -> harness.ui().getLuckMeter().getRows()).isEmpty());
		// The whip's composition is read for its price (the history is valued at today's prices), but its name
		// is not asked for.
		assertNull("no item name asked for", onEdt(() -> harness.historyModel().itemName(WHIP)));

		harness.setPanelSection(SlayerLedgerConfig.SHOW_LUCK_METER, true);
		assertTrue(shown(SlayerLedgerPanel.OptionalSection.LUCK_METER));
		assertTrue(onEdt(() -> harness.ui().getLuckMeter().isExpanded()));
		assertEquals("Abyssal whip", onEdt(() -> harness.historyModel().itemName(WHIP)));
		assertEquals("Abyssal whip | 2.0x\nObserved / expected: | 2 / 1.00",
			onEdt(() -> harness.ui().getLuckMeter().getRows()).get(0));

		// Hidden again: the rows go, and later records and item names build nothing.
		harness.setPanelSection(SlayerLedgerConfig.SHOW_LUCK_METER, false);
		assertTrue(onEdt(() -> harness.ui().getLuckMeter().getRows()).isEmpty());
		harness.onEdt(() ->
		{
			PanelProbe ui = harness.ui();
			builds[0] = ui.getLuckMeter().getBuildCount();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(demons));
			harness.historyModel().addItemNames(Collections.singleton(WHIP),
				Collections.singletonMap(WHIP, "Abyssal whip"), null);
		});
		assertEquals(builds[0], (int) onEdt(() -> harness.ui().getLuckMeter().getBuildCount()));
		assertTrue(onEdt(() -> harness.ui().getLuckMeter().getRows()).isEmpty());
	}

	@Test
	public void hiddenWhatToBringIsNotWorkedOutAndComesBackWithTheEstimate()
	{
		harness.defineItem(101, "Cannonballs", 200, 0);
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 10, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		LedgerRecord demons = completed("Abyssal demons", 42, 10, 10_000L);
		demons.setSupplies(Collections.singletonMap(101, 30L));
		demons.setBankTrips(1);
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(demons));
			harness.ui().getHistoryEstimate().toggleBring();
		});
		harness.drain();
		String header = onEdt(() ->
		{
			harness.panel().refresh();
			return harness.ui().getHistoryEstimate().getBringText();
		});
		List<String> lines = onEdt(() -> harness.ui().getHistoryEstimate().getBringLines());
		assertNotNull(header);
		assertEquals(Collections.singletonList("Cannonballs | x30"), lines);

		harness.setPanelSection(SlayerLedgerConfig.SHOW_WHAT_TO_BRING, false);
		assertFalse(shown(SlayerLedgerPanel.OptionalSection.WHAT_TO_BRING));
		assertNull(onEdt(() -> harness.ui().getHistoryEstimate().getBringText()));
		assertNotNull("the History estimate stays", onEdt(() -> harness.ui().getHistoryEstimate().getText()));
		int builds = onEdt(() -> harness.ui().getHistoryEstimate().getBringBuildCount());
		// Records, the Loot price mode and the refresh timer work nothing of it out while hidden.
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(demons));
			harness.panel().refresh();
		});
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.drain();
		assertEquals(builds, (int) onEdt(() -> harness.ui().getHistoryEstimate().getBringBuildCount()));
		assertNull(onEdt(() -> harness.ui().getHistoryEstimate().getBringText()));
		assertTrue(onEdt(() -> harness.ui().getHistoryEstimate().getBringLines()).isEmpty());

		harness.setPanelSection(SlayerLedgerConfig.SHOW_WHAT_TO_BRING, true);
		assertTrue(shown(SlayerLedgerPanel.OptionalSection.WHAT_TO_BRING));
		assertEquals(builds + 1, (int) onEdt(() -> harness.ui().getHistoryEstimate().getBringBuildCount()));
		assertEquals(header, onEdt(() -> harness.ui().getHistoryEstimate().getBringText()));
		assertEquals("still open", lines, onEdt(() -> harness.ui().getHistoryEstimate().getBringLines()));
	}

	private static LedgerRecord completed(String monster, int creatureId, int kills, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(monster + kills);
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setKills(kills);
		record.setActiveMillis(activeMillis);
		record.setEndedAt(1_700_000_000_000L);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The "Loot price" setting and the history at today's prices as wired in the plugin
 * ({@link PluginHarness}): a setting change reaches the live values and the history without a restart, and saved tasks
 * are valued at today's prices, looked up on the client thread, once per item, and shown on the EDT.
 * {@link LootPricingTest}, {@link HistoryPricingTest} and {@link SessionValuationTest} cover the calculations.
 */
public class HarnessPricingTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		// High alch above GE, so the modes differ.
		harness.defineItem(ItemID.DRAGON_BONES, "Dragon bones", 2_000, 5_000);
		harness.startUp();
		harness.setInventory();
		harness.setTask(42, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Plays a session that loots bones and dragon bones (GE 2,100, high alch 5,001). */
	private void loot()
	{
		assertTrue(harness.play());
		harness.postLoot(ItemID.BONES, 1);
		harness.postLoot(ItemID.DRAGON_BONES, 1);
		harness.ticks(2);
	}

	private String liveValues()
	{
		AtomicReference<String> text = new AtomicReference<>();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text.set(harness.ui().getValuesText());
		});
		return text.get();
	}

	/** The only history row: "Loot | Supplies | Profit | tooltip". */
	private String historyRow()
	{
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() -> rows.set(harness.ui().getHistory().getValuesText()));
		assertEquals(1, rows.get().size());
		return rows.get().get(0);
	}

	@Test
	public void lootPriceSettingChangesLiveValuesAndHistoryWithoutRestart()
	{
		loot();
		assertEquals("Loot (GE): 2,100 gp | Supplies: 0 gp | Profit (GE): 2,100 gp", liveValues());

		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.tick();
		assertEquals("Loot (HA): 5,001 gp | Supplies: 0 gp | Profit (HA): 5,001 gp", liveValues());

		harness.stop();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals("the record keeps both GE and high alch", Long.valueOf(2_100), record.getLootGeValue());
		assertEquals(Long.valueOf(5_001), record.getLootHaValue());
		assertTrue(historyRow(), historyRow().startsWith("Loot (HA): 5,001 | Supplies: 0 | Profit (HA): 5,001 | "));
		assertTrue(historyRow(), historyRow().contains("Loot value (High alch): 5,001 gp"));

		harness.setLootPriceMode(LootPriceMode.GE);
		assertTrue(historyRow(), historyRow().startsWith("Loot (GE): 2,100 | Supplies: 0 | Profit (GE): 2,100 | "));
		assertFalse(historyRow(), historyRow().contains("Loot value ("));
	}

	@Test
	public void aSavedTaskIsRevaluedAtTodaysPricesInTheHistoryTrendsAndTotals()
	{
		// Saved at 40,000 gp for the seed and 500 gp a shark; 50,000 gp and 900 gp today.
		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 50_000, 20);
		harness.defineItem(ItemID.SHARK, "Shark", 900, 10);
		LedgerRecord record = ranarrRecord();
		record.setCompleted(true);
		record.setActiveMillis(60 * 60_000L);
		record.setSupplies(Collections.singletonMap(ItemID.SHARK, 10L));
		Map<Integer, Long> ge = new HashMap<>(record.getUnitGePrices());
		ge.put(ItemID.SHARK, 500L);
		record.setUnitGePrices(ge);
		record.setSuppliesGeValue(5_000L);
		int calls = harness.pluginCallCount();
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(ACCOUNT, Collections.singletonList(record));
			harness.ui().getOverallTotals().clickTitle();
			harness.ui().getTrends().clickTitle();
		});
		// The lookup is queued for the client thread, and its answer for the EDT.
		harness.drain();
		assertTrue("prices are looked up through ItemManager", harness.pluginCallCount() > calls);

		String row = historyRow();
		assertTrue(row, row.startsWith("Loot (GE): 50K | Supplies: 9,000 | Profit (GE): 41K | "));
		assertTrue(row, row.contains(LedgerHistory.CURRENT_PRICES));
		assertTrue("high alch unchanged", row.contains("Loot: 50,000 gp GE, 20 gp high alch"));
		assertFalse("no saved prices are shown", row.contains("40,000") || row.contains("35,000"));
		assertEquals(Collections.singletonList("1. Abyssal demons | 41K gp/h (n=1)"), trendsRows());
		assertTrue(totalsRows().toString(), totalsRows().get(0).contains("Profit (GE): | 41K (n=1)"));

		// High alch: the loot at its saved high alch value, the supplies still at today's GE price.
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		assertTrue(historyRow(), historyRow().startsWith("Loot (HA): 20 | Supplies: 9,000 | Profit (HA): -8,980 | "));
		assertEquals(Collections.singletonList("1. Abyssal demons | -8,980 gp/h (n=1)"), trendsRows());
		assertTrue(totalsRows().toString(), totalsRows().get(0).contains("Profit (HA): | -8,980 (n=1)"));

		// Looked up once: the same tasks again ask for nothing, even after today's price changes.
		harness.setGePrice(ItemID.RANARR_SEED, 60_000);
		calls = harness.pluginCallCount();
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, Collections.singletonList(record)));
		harness.drain();
		assertEquals(calls, harness.pluginCallCount());
		assertTrue(historyRow(), historyRow().contains("Loot: 50,000 gp GE"));
	}

	private List<String> trendsRows()
	{
		AtomicReference<List<String>> rows = new AtomicReference<>();
		// Worked out off the EDT.
		harness.drain();
		harness.onEdt(() -> rows.set(harness.ui().getTrends().getRows()));
		return rows.get();
	}

	private List<String> totalsRows()
	{
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.drain();
		harness.onEdt(() -> rows.set(harness.ui().getOverallTotals().getRows()));
		return rows.get();
	}

	@Test
	public void todaysPricesCoverNewlySavedTasks()
	{
		loot();
		harness.stop();

		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 40_000, 20);
		assertTrue(harness.play());
		harness.postLoot(ItemID.RANARR_SEED, 1);
		harness.tick();
		int builds = historyListBuilds();
		harness.stop();
		// The save reloads the records; the rows wait for the seed's price and are drawn once.
		assertEquals(builds + 1, historyListBuilds());
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() -> rows.set(harness.ui().getHistory().getValuesText()));
		assertEquals(2, rows.get().size());
		for (String row : rows.get())
		{
			assertTrue(row, row.contains(LedgerHistory.CURRENT_PRICES));
			assertFalse("every item was priced", row.contains("~"));
		}
		assertTrue(rows.get().toString(), rows.get().stream().anyMatch(r -> r.startsWith("Loot (GE): 40K | ")));
	}

	private int historyListBuilds()
	{
		AtomicReference<Integer> builds = new AtomicReference<>();
		harness.onEdt(() -> builds.set(harness.ui().getHistory().getBuildCount()));
		return builds.get();
	}

	private List<String> historyValues()
	{
		AtomicReference<List<String>> rows = new AtomicReference<>();
		harness.onEdt(() -> rows.set(harness.ui().getHistory().getValuesText()));
		return rows.get();
	}

	/** A record that looted one Ranarr seed (saved at GE 40,000), newer than the played session. */
	private static LedgerRecord ranarrRecord()
	{
		LedgerRecord record = new LedgerRecord();
		record.setId("ranarr");
		record.setMonster("Abyssal demons");
		record.setCreatureId(42);
		record.setStartedAt(System.currentTimeMillis() + 60_000);
		record.setEndedAt(System.currentTimeMillis() + 120_000);
		record.setKills(1);
		record.setActiveMillis(60_000);
		record.setLoot(Collections.singletonMap(ItemID.RANARR_SEED, 1L));
		record.setUnitGePrices(Collections.singletonMap(ItemID.RANARR_SEED, 40_000L));
		record.setUnitHaPrices(Collections.singletonMap(ItemID.RANARR_SEED, 20L));
		record.setLootGeValue(40_000L);
		record.setLootHaValue(20L);
		record.setSuppliesGeValue(0L);
		record.setSuppliesHaValue(0L);
		return record;
	}

	/** Whether the history waits for today's prices. */
	private boolean waiting()
	{
		AtomicReference<Boolean> waiting = new AtomicReference<>();
		harness.onEdt(() -> waiting.set(harness.historyModel().isWaitingForCurrentPrices()));
		return waiting.get();
	}

	/** Lets a wait for today's prices run out, as after {@link HistoryValuation#CURRENT_PRICES_WAIT_MILLIS}. */
	private void runOutTheWait()
	{
		harness.onEdt(() ->
		{
			harness.historyModel().expireCurrentPricesWait();
			assertTrue(harness.historyModel().endExpiredCurrentPricesWait());
		});
	}

	@Test
	public void atClientStartTheHistoryWaitsForPricesLookedUpAgainAndIsDrawnOnce()
	{
		// Played, saved and shown before RuneLite has loaded its price list: every tradeable item reads 0.
		harness.setGePrice(ItemID.BONES, 0);
		harness.setGePrice(ItemID.DRAGON_BONES, 0);
		loot();
		int builds = historyListBuilds();
		harness.stop();
		assertTrue("the answer came without the price: wait for it to be looked up again", waiting());
		assertEquals("nothing drawn unpriced", builds, historyListBuilds());

		// The price list loads; the next try finds the prices and the wait ends with one redraw.
		harness.setGePrice(ItemID.BONES, 100);
		harness.setGePrice(ItemID.DRAGON_BONES, 3_000);
		harness.ticks(PriceRetry.INTERVAL_TICKS);
		assertFalse(waiting());
		String row = historyRow();
		assertTrue(row, row.startsWith("Loot (GE): 3,100 | Supplies: 0 | Profit (GE): 3,100 | "));
		assertEquals("drawn once, priced", builds + 1, historyListBuilds());
	}

	@Test
	public void aWaitForAPriceLookedUpAgainStillRunsOutAndEndsWhenTheHistoryIsCleared()
	{
		// RuneLite's price list never loads in this run.
		harness.setGePrice(ItemID.BONES, 0);
		harness.setGePrice(ItemID.DRAGON_BONES, 0);
		loot();
		harness.stop();
		assertTrue(waiting());
		runOutTheWait();
		assertFalse(waiting());
		assertTrue(historyRow(), historyRow().startsWith("Loot (GE): ~0 | "));

		// Waiting again for the same price, until the history is cleared (logging out).
		List<LedgerRecord> records = harness.records(ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, records));
		harness.drain();
		assertTrue(waiting());
		harness.onEdt(() -> harness.historyModel().clearRecords(ACCOUNT, SlayerLedgerPanel.LOADING_MESSAGE));
		assertFalse(waiting());
	}

	@Test
	public void onceAPriceIsSeenAnItemWithoutAPriceHoldsNothingBack()
	{
		// RuneLite's price list is loaded (the bones are priced) but has no price for the dragon bones.
		loot();
		harness.setGePrice(ItemID.DRAGON_BONES, 0);
		int builds = historyListBuilds();
		harness.stop();
		assertFalse("a missing price is not waited for", waiting());
		assertTrue(historyRow(), historyRow().startsWith("Loot (GE): ~100 | Supplies: 0 | Profit (GE): ~100 | "));
		assertEquals("drawn at once", builds + 1, historyListBuilds());

		// Loaded again, the history still doesn't wait for it.
		List<LedgerRecord> records = harness.records(ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, records));
		harness.drain();
		assertFalse(waiting());
		assertTrue(historyRow(), historyRow().startsWith("Loot (GE): ~100 | "));
	}

	@Test
	public void unavailablePricesAreMarkedAndLookedUpAgain()
	{
		loot();
		// No price for the dragon bones yet; the bones are priced, so the history is drawn without waiting.
		harness.setGePrice(ItemID.DRAGON_BONES, 0);
		harness.stop();
		String unpriced = historyRow();
		assertTrue(unpriced, unpriced.startsWith("Loot (GE): ~100 | Supplies: 0 | Profit (GE): ~100 | "));
		assertTrue(unpriced, unpriced.contains("Some prices were unavailable (loot: 1, supplies: 0)"));

		harness.setGePrice(ItemID.DRAGON_BONES, 3_000);
		int builds = historyListBuilds();
		harness.ticks(PriceRetry.INTERVAL_TICKS - 1);
		assertTrue("not due yet", historyRow().startsWith("Loot (GE): ~100 | "));
		assertEquals(builds, historyListBuilds());
		harness.tick();
		String row = historyRow();
		assertTrue(row, row.startsWith("Loot (GE): 3,100 | Supplies: 0 | Profit (GE): 3,100 | "));
		assertFalse(row, row.contains("Some prices were unavailable"));
		assertTrue(row, row.contains(LedgerHistory.CURRENT_PRICES));
		assertEquals("redrawn once", builds + 1, historyListBuilds());

		// Found: not looked up or redrawn again.
		harness.setGePrice(ItemID.DRAGON_BONES, 4_000);
		harness.ticks(PriceRetry.INTERVAL_TICKS * 3);
		assertTrue(historyRow(), historyRow().startsWith("Loot (GE): 3,100 | "));
		assertEquals(builds + 1, historyListBuilds());
	}

	@Test
	public void unavailablePricesAreRetriedAtMostMaxAttemptsTimes()
	{
		loot();
		harness.setGePrice(ItemID.DRAGON_BONES, 0);
		harness.stop();
		int builds = historyListBuilds();
		harness.ticks(PriceRetry.INTERVAL_TICKS * PriceRetry.MAX_ATTEMPTS);
		assertEquals("a retry that finds nothing redraws nothing", builds, historyListBuilds());

		// The cap is reached: a price that turns up later is not looked up by the retry.
		harness.setGePrice(ItemID.DRAGON_BONES, 3_000);
		harness.ticks(PriceRetry.INTERVAL_TICKS * 3);
		assertTrue(historyRow(), historyRow().startsWith("Loot (GE): ~100 | "));

		// A change of the saved tasks (here, the same ones loaded again) still asks for it.
		List<LedgerRecord> records = harness.records(ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, records));
		harness.drain();
		assertTrue(historyRow(), historyRow().startsWith("Loot (GE): 3,100 | "));
	}

	@Test
	public void newRecordsKeepThePreviousRowsUntilTheirPricesArriveThenRedrawOnce()
	{
		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 50_000, 20);
		loot();
		harness.stop();
		LedgerRecord saved = harness.onlyRecord(ACCOUNT);
		harness.onEdt(() -> harness.ui().getOverallTotals().clickTitle());
		harness.onEdt(() -> harness.ui().getTrends().clickTitle());
		int[] before = new int[3];
		harness.onEdt(() ->
		{
			SlayerLedgerPanel panel = harness.panel();
			PanelProbe ui = harness.ui();
			before[0] = ui.getHistory().getBuildCount();
			before[1] = ui.getOverallTotals().getBuildCount();
			before[2] = ui.getTrends().getBuildCount();
			List<String> rows = ui.getHistory().getValuesText();
			// The lookup is queued for the client thread, so it cannot answer inside this EDT task.
			harness.historyModel().setRecords(ACCOUNT, Arrays.asList(saved, ranarrRecord()));
			panel.refresh();
			assertTrue(harness.historyModel().isWaitingForCurrentPrices());
			assertEquals("the previous rows stay", rows, ui.getHistory().getValuesText());
			assertEquals(before[0], ui.getHistory().getBuildCount());
			assertEquals(before[1], ui.getOverallTotals().getBuildCount());
			assertEquals(before[2], ui.getTrends().getBuildCount());
			assertEquals("the count does not wait", "Saved tasks: 2", ui.getSavedTasksText());
		});

		harness.drain();
		harness.onEdt(() ->
		{
			PanelProbe ui = harness.ui();
			assertFalse(harness.historyModel().isWaitingForCurrentPrices());
			assertEquals("redrawn once", before[0] + 1, ui.getHistory().getBuildCount());
			assertEquals(before[1] + 1, ui.getOverallTotals().getBuildCount());
			assertEquals(before[2] + 1, ui.getTrends().getBuildCount());
			List<String> rows = ui.getHistory().getValuesText();
			assertEquals(2, rows.size());
			assertTrue(rows.toString(), rows.get(0).startsWith("Loot (GE): 50K | "));
			for (String row : rows)
			{
				assertFalse(row, row.contains("~"));
			}
		});
	}

	@Test
	public void aWaitForPricesThatNeverArriveEnds()
	{
		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 50_000, 20);
		loot();
		harness.stop();
		LedgerRecord saved = harness.onlyRecord(ACCOUNT);
		harness.onEdt(() ->
		{
			SlayerLedgerPanel panel = harness.panel();
			PanelProbe ui = harness.ui();
			harness.historyModel().setRecords(ACCOUNT, Arrays.asList(saved, ranarrRecord()));
			assertTrue(harness.historyModel().isWaitingForCurrentPrices());
			harness.historyModel().expireCurrentPricesWait();
			panel.refresh();
			assertFalse(harness.historyModel().isWaitingForCurrentPrices());
			List<String> rows = ui.getHistory().getValuesText();
			assertEquals("shown without the missing price", 2, rows.size());
			assertTrue(rows.toString(), rows.get(0).startsWith("Loot (GE): ~0 | "));
		});

		// A late answer is still shown.
		harness.drain();
		assertTrue(historyValues().get(0), historyValues().get(0).startsWith("Loot (GE): 50K | "));
	}

	@Test
	public void deletingTheLastTaskWhileWaitingClearsTheHistory()
	{
		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 50_000, 20);
		loot();
		harness.stop();
		LedgerRecord saved = harness.onlyRecord(ACCOUNT);
		harness.onEdt(() ->
		{
			PanelProbe ui = harness.ui();
			harness.historyModel().setRecords(ACCOUNT, Arrays.asList(saved, ranarrRecord()));
			assertTrue(harness.historyModel().isWaitingForCurrentPrices());
			// The account's last tasks are deleted while their prices are still being looked up.
			harness.historyModel().setRecords(ACCOUNT, Collections.emptyList());
			assertTrue("the deleted rows are gone at once", ui.getHistory().getValuesText().isEmpty());
		});
		harness.drain();
		assertTrue(historyValues().toString(), historyValues().isEmpty());
	}

	@Test
	public void highAlchTooltipsFlagMissingGePrices()
	{
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.setGePrice(ItemID.DRAGON_BONES, 0);
		loot();
		assertEquals("high alch values are all known", "Loot (HA): 5,001 gp | Supplies: 0 gp | Profit (HA): 5,001 gp",
			liveValues());
		AtomicReference<String> tooltip = new AtomicReference<>();
		harness.onEdt(() -> tooltip.set(harness.ui().getValuesTooltip()));
		assertTrue(tooltip.get(), tooltip.get().contains("Loot: ~100 gp GE, 5,001 gp high alch"));
		assertTrue(tooltip.get(), tooltip.get().contains("(loot at high alch: 0, loot at GE: 1, supplies: 0)"));

		// The history at today's prices says the same when today's GE price is missing.
		harness.stop();
		String row = historyRow();
		assertTrue(row, row.startsWith("Loot (HA): 5,001 | Supplies: 0 | Profit (HA): 5,001 | "));
		assertTrue(row, row.contains("Loot: ~100 gp GE, 5,001 gp high alch"));
		assertTrue(row, row.contains("(loot at high alch: 0, loot at GE: 1, supplies: 0)"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.attribute.PosixFilePermission;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * A task whose save fails: the panel says so, the record is kept in a side file
 * ({@code <hash>.unsaved-<id>.json}), and it is appended exactly once by the next successful save or ledger load,
 * which also clears the message.
 */
public class HarnessSaveFailedTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";
	private static final String NEWER_LEDGER = "{\"schemaVersion\":99,\"records\":[{\"id\":\"future\","
		+ "\"monster\":\"Hydras\",\"kills\":9,\"completed\":true}]}";
	private static final String SAME_LEDGER_AT_THIS_VERSION = "{\"schemaVersion\":2,\"records\":[{\"id\":\"future\","
		+ "\"monster\":\"Hydras\",\"kills\":9,\"completed\":true}]}";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private final boolean posix = FileSystems.getDefault().supportedFileAttributeViews().contains("posix");

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
	}

	private <T> T onEdt(Supplier<T> read)
	{
		final List<T> result = new ArrayList<>(1);
		harness.onEdt(() -> result.add(read.get()));
		return result.get(0);
	}

	private String historyError()
	{
		return onEdt(() -> harness.ui().getHistory().getErrorText());
	}

	private String savedTasks()
	{
		return onEdt(() -> harness.ui().getSavedTasksText());
	}

	private File ledgerFile()
	{
		return new File(harness.ledgerDirectory(), ACCOUNT + ".json");
	}

	private String[] keptFiles()
	{
		final String[] names = harness.ledgerDirectory().list();
		return names == null ? new String[0]
			: Arrays.stream(names).filter(n -> n.startsWith(ACCOUNT + ".unsaved-")).toArray(String[]::new);
	}

	private static String expectedError()
	{
		return "<html>" + SlayerLedgerPanel.SAVE_FAILED_MESSAGE + "</html>";
	}

	/**
	 * Makes the ledger file unreadable, so any save fails without it being a parse error (which would move it aside):
	 * write-only where permissions are POSIX, a directory in its place on Windows (where a directory cannot be opened
	 * as a reader), as in {@code LedgerStoreTest.nonParseIoFailureDoesNotRenameFile}.
	 */
	private void blockLedger() throws IOException
	{
		final File file = ledgerFile();
		if (posix)
		{
			Files.write(file.toPath(), "ledger".getBytes(StandardCharsets.UTF_8));
			Files.setPosixFilePermissions(file.toPath(), Collections.singleton(PosixFilePermission.OWNER_WRITE));
		}
		else
		{
			assertTrue(file.mkdirs());
		}
	}

	/** Undoes {@link #blockLedger}: the ledger is missing again, so the next write creates it. */
	private void unblockLedger() throws IOException
	{
		final File file = ledgerFile();
		if (posix)
		{
			Files.setPosixFilePermissions(file.toPath(),
				EnumSet.of(PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE));
		}
		Files.delete(file.toPath());
	}

	private void writeLedger(String json) throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		Files.write(ledgerFile().toPath(), json.getBytes(StandardCharsets.UTF_8));
	}

	private String readLedger() throws IOException
	{
		return new String(Files.readAllBytes(ledgerFile().toPath()), StandardCharsets.UTF_8);
	}

	/** Plays the task from ten left, kills them all and lets the completion save after its grace ticks. */
	private void playAndComplete()
	{
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertTrue(harness.play());
		harness.setRemaining(8);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());
	}

	private void relogin()
	{
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
	}

	@Test
	public void unwritableLedgerShowsTheMessageAndTheNextLoadSavesTheKeptTaskOnce() throws IOException
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertNull(historyError());
		blockLedger();

		playAndComplete();
		assertEquals(expectedError(), historyError());
		assertEquals("the task is kept beside the ledger", 1, keptFiles().length);
		assertNull("no active session file holds it", harness.activeSession(ACCOUNT));

		unblockLedger();
		relogin();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(10, record.getKills());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.BONES));
		assertEquals(0, keptFiles().length);
		assertNull("cleared once the task is saved", historyError());
		assertEquals("Saved tasks: 1", savedTasks());

		relogin();
		assertEquals("saved exactly once", 1, harness.records(ACCOUNT).size());
	}

	@Test
	public void nextSaveAlsoSavesTheKeptTaskOnce() throws IOException
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		blockLedger();
		playAndComplete();
		assertEquals(expectedError(), historyError());
		final String[] kept = keptFiles();
		assertEquals(1, kept.length);
		final String keptName = kept[0];
		unblockLedger();

		// The next task's Stop saves it as partial, and the kept task with it.
		harness.setTask(TASK, TASK_NAME, 20, 20);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertTrue(harness.play());
		harness.setRemaining(19);
		harness.tick();
		harness.stop();

		final List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		assertEquals(1, records.stream().filter(LedgerRecord::isCompleted).count());
		assertEquals(1, records.stream().filter(LedgerRecord::isPartial).count());
		assertEquals(0, keptFiles().length);
		assertNull(historyError());
		assertEquals("Saved tasks: 2", savedTasks());
		final LedgerRecord completed = records.stream().filter(LedgerRecord::isCompleted).findFirst().get();
		assertEquals("the kept task is the completed one", ACCOUNT + ".unsaved-" + completed.getId() + ".json",
			keptName);
	}

	@Test
	public void newerSchemaLedgerKeepsTheTaskWithoutRetryingForeverAndNeverChangesTheFile() throws IOException
	{
		writeLedger(NEWER_LEDGER);
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("read on a best-effort basis", "Saved tasks: 1", savedTasks());

		playAndComplete();
		assertEquals(expectedError(), historyError());
		assertEquals(1, keptFiles().length);
		final String[] kept = keptFiles();

		// Every load tries once more and fails the same way; drain() would fail if it kept retrying.
		relogin();
		assertEquals(expectedError(), historyError());
		assertArrayEquals(kept, keptFiles());
		assertEquals(NEWER_LEDGER, readLedger());
		harness.shutDown();
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(expectedError(), historyError());
		assertArrayEquals(kept, keptFiles());
		assertEquals(NEWER_LEDGER, readLedger());

		// A build that can write it again (here: the file back at this version) saves the task once.
		writeLedger(SAME_LEDGER_AT_THIS_VERSION);
		relogin();
		assertEquals(2, harness.records(ACCOUNT).size());
		assertEquals(0, keptFiles().length);
		assertNull(historyError());
		assertEquals("Saved tasks: 2", savedTasks());
	}

	@Test
	public void messageIsShownEvenWhenTheTaskCannotBeKept()
	{
		// No ledger directory at all: neither the ledger nor the side file can be written.
		harness.plugin.setLedgerDirectorySource(() ->
		{
			throw new IOException("plugin directory unavailable");
		});
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertNull("a failed load alone is not a failed save", historyError());

		playAndComplete();
		assertEquals(expectedError(), historyError());
		final String[] files = harness.ledgerDirectory().list();
		assertEquals("nothing written", 0, files == null ? 0 : files.length);
		assertFalse(Arrays.asList(files == null ? new String[0] : files).contains(ACCOUNT + ".json"));
	}

	@Test
	public void keptFileUsesTheStoresLayout() throws IOException
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		blockLedger();
		playAndComplete();

		final String[] kept = keptFiles();
		assertEquals(1, kept.length);
		// Read back with a fresh store over the same directory, as after a client restart.
		unblockLedger();
		final LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(harness.ledgerDirectory().toPath()),
			new com.google.gson.Gson());
		final List<LedgerRecord> saved = store.appendUnsaved(ACCOUNT);
		assertEquals(1, saved.size());
		assertEquals(TASK_NAME, saved.get(0).getMonster());
		assertEquals(ACCOUNT + ".unsaved-" + saved.get(0).getId() + ".json", kept[0]);
	}

	@Test
	public void staleActiveFileOfTheKeptTaskNeverReplacesIt() throws IOException
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.setRemaining(8);
		harness.tick();
		// Logging out mid-task writes the active file; it stays after the next login.
		relogin();
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertNotNull("the logout's active file is still there", harness.activeSession(ACCOUNT));

		blockLedger();
		assertTrue(harness.play());
		harness.setRemaining(5);
		harness.tick();
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());
		assertEquals(expectedError(), historyError());
		final String[] kept = keptFiles();
		assertEquals(1, kept.length);
		assertNull("the stale active file goes with the kept task", harness.activeSession(ACCOUNT));

		// Still blocked: nothing turns the old snapshot into a partial copy that replaces the completed task.
		relogin();
		assertArrayEquals(kept, keptFiles());
		assertEquals(expectedError(), historyError());

		unblockLedger();
		relogin();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(10, record.getKills());
		assertEquals(0, keptFiles().length);
		assertNull(historyError());
		assertEquals("Saved tasks: 1", savedTasks());
	}

	@Test
	public void keptTasksSavedBeforeALaterOneFailsAreShown() throws IOException
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		// Two kept tasks: one that saves, then one the ledger can never take (a lone surrogate the encoder refuses).
		final LedgerRecord good = new LedgerRecord();
		good.setId("a");
		good.setMonster("Gargoyles");
		good.setKills(5);
		good.setCompleted(true);
		final LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(harness.ledgerDirectory().toPath()),
			new com.google.gson.Gson());
		store.writeUnsaved(ACCOUNT, good);
		Files.write(new File(harness.ledgerDirectory(), ACCOUNT + ".unsaved-b.json").toPath(),
			("{\"schemaVersion\":2,\"record\":{\"id\":\"b\",\"monster\":\"Bad \\ud800\",\"kills\":1,"
				+ "\"completed\":true}}").getBytes(StandardCharsets.UTF_8));

		playAndComplete();
		assertEquals(2, harness.records(ACCOUNT).size());
		assertEquals("the panel shows both saved tasks", "Saved tasks: 2", savedTasks());
		assertEquals("the bad one is still waiting", expectedError(), historyError());
		assertEquals(Collections.singletonList(ACCOUNT + ".unsaved-b.json"), Arrays.asList(keptFiles()));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.concurrent.Future;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * How a running session leaves memory, through the plugin's wiring ({@link PluginHarness}): logout keeps it and
 * persists a copy, plugin stop and client exit persist it as the active session, the next login restores it (or saves
 * it as partial when the task no longer matches), Stop saves it as partial, and each path saves exactly once. Also
 * checks that loot counts only while the session is RUNNING. {@link SessionRestoreTest} and
 * {@link LootTrackingTest} cover the tracker's side.
 */
public class HarnessSessionEndTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Plays and kills two of the ten (two kills, one bones). */
	private void playAndKillTwo()
	{
		assertTrue(harness.play());
		harness.setRemaining(8);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
	}

	@Test
	public void logoutPersistsTheSessionAndReloginResumesItInMemory()
	{
		playAndKillTwo();
		harness.logout();

		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		SessionSnapshot active = harness.activeSession(ACCOUNT);
		assertNotNull("persisted in case the client is closed", active);
		assertEquals(2, active.getKills());
		assertEquals(8, active.getRemaining());
		assertEquals(Long.valueOf(1), active.getLoot().get(ItemID.BONES));
		assertTrue("no record on logout", harness.records(ACCOUNT).isEmpty());

		harness.loginAndSettle(ACCOUNT);
		assertEquals("kept in memory, paused", SessionTracker.State.PAUSED, harness.sessionState());
		assertTrue(harness.canPlay());
		assertTrue(harness.play());
		harness.setRemaining(7);
		harness.tick();
		harness.stop();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isPartial());
		assertEquals(3, record.getKills());
		assertEquals(active.getSessionId(), record.getId());
		assertNull("the active file goes once the record is saved", harness.activeSession(ACCOUNT));
	}

	@Test
	public void sessionPersistedAtLogoutIsRestoredFromFileAfterARestart()
	{
		playAndKillTwo();
		harness.logout();
		final String sessionId = harness.activeSession(ACCOUNT).getSessionId();
		harness.shutDown();
		assertNotNull(harness.activeSession(ACCOUNT));
		assertTrue(harness.records(ACCOUNT).isEmpty());

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as paused", SessionTracker.State.PAUSED, harness.sessionState());
		assertTrue(harness.tracker().isRestoredPending());
		assertTrue(harness.play());
		harness.setRemaining(7);
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		harness.stop();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(sessionId, record.getId());
		assertEquals(3, record.getKills());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.BONES));
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void pluginStopWhileRunningPersistsTheActiveSessionWithoutARecord()
	{
		playAndKillTwo();
		harness.shutDown();

		SessionSnapshot active = harness.activeSession(ACCOUNT);
		assertNotNull(active);
		assertEquals(2, active.getKills());
		assertTrue(harness.records(ACCOUNT).isEmpty());

		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("restored after the plugin is turned back on", SessionTracker.State.PAUSED,
			harness.sessionState());
		assertEquals(2, harness.tracker().getKills());
		assertTrue(harness.records(ACCOUNT).isEmpty());
	}

	@Test
	public void clientExitWhileRunningPersistsTheActiveSessionAndWaitsForTheWrite()
	{
		playAndKillTwo();
		List<Future<?>> waitedFor = harness.clientShutdown();

		assertEquals(1, waitedFor.size());
		assertTrue(waitedFor.get(0).isDone());
		SessionSnapshot active = harness.activeSession(ACCOUNT);
		assertNotNull(active);
		assertEquals(2, active.getKills());
		assertTrue(harness.records(ACCOUNT).isEmpty());
	}

	@Test
	public void reloginWithADifferentTaskSavesThePartialSessionOnce()
	{
		playAndKillTwo();
		harness.logout();
		harness.setTask(TASK + 1, "Greater demons", 20, 20);
		harness.loginAndSettle(ACCOUNT);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isPartial());
		assertFalse(record.isCompleted());
		assertEquals(TASK_NAME, record.getMonster());
		assertEquals(2, record.getKills());
		assertNull(harness.activeSession(ACCOUNT));
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());

		harness.ticks(5);
		harness.logout();
		harness.shutDown();
		assertEquals(1, harness.records(ACCOUNT).size());
	}

	@Test
	public void restoredFileWithADifferentTaskIsSavedAsPartial()
	{
		playAndKillTwo();
		harness.shutDown();
		harness.logout();
		harness.setTask(TASK + 1, "Greater demons", 20, 20);
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isPartial());
		assertEquals(TASK_NAME, record.getMonster());
		assertNull(harness.activeSession(ACCOUNT));
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());
	}

	@Test
	public void worldHopPausesTheSessionWithoutSavingIt()
	{
		playAndKillTwo();
		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);

		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertTrue(harness.records(ACCOUNT).isEmpty());
		assertTrue(harness.play());
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
	}

	@Test
	public void stopSavesAPartialRecordOnce()
	{
		playAndKillTwo();
		harness.stop();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isPartial());
		assertEquals(2, record.getKills());
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());

		harness.ticks(3);
		harness.logout();
		harness.clientShutdown();
		harness.shutDown();
		assertEquals(1, harness.records(ACCOUNT).size());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void accountSwitchPersistsTheOtherAccountsSession()
	{
		playAndKillTwo();
		harness.logout();
		harness.loginAndSettle(PluginHarness.OTHER_ACCOUNT);

		assertEquals(SessionTracker.State.IDLE, harness.sessionState());
		SessionSnapshot active = harness.activeSession(ACCOUNT);
		assertNotNull(active);
		assertEquals(2, active.getKills());
		assertTrue(harness.records(ACCOUNT).isEmpty());
		assertTrue(harness.records(PluginHarness.OTHER_ACCOUNT).isEmpty());
		assertNull(harness.activeSession(PluginHarness.OTHER_ACCOUNT));
	}

	@Test
	public void lootCountsOnlyWhileRunning()
	{
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		assertTrue(harness.play());
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		harness.pause();
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 2);
		harness.tick();
		harness.postLoot(ItemID.ABYSSAL_WHIP, 3);
		assertTrue(harness.play());
		harness.postLoot(ItemID.BONES, 2);
		harness.stop();
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 4);
		harness.tick();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(3), record.getLoot().get(ItemID.BONES));
		assertNull("idle, paused and stopped loot is not counted", record.getLoot().get(ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void pickpocketLootIsNotCounted()
	{
		assertTrue(harness.play());
		harness.chat(ChatMessageType.SPAM, "You pick the H.A.M. Member's pocket.");
		// The server sends the pickpocket's NPC loot on that tick.
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		harness.stop();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertNull(record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.BONES));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The task box's next bonus, short on its second line and in full in that line's tooltip, as wired in the
 * plugin ({@link PluginHarness}): the streak of the current task's master, read on settled ticks, the new streak right
 * after a completion, and hidden while it is unknown.
 * {@link StreakMilestoneTest} covers the rules.
 */
public class HarnessStreakHintTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(42, "Kraken", 3, 3);
		harness.setAssignment(SlayerMaster.KONAR, 0, null);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 47);
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 9);
		harness.setVarp(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED, 120);
	}

	private String hint()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getTaskBox().getStreakHintText();
		});
		return text[0];
	}

	private List<String> taskBoxRows()
	{
		final List<?>[] rows = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			rows[0] = harness.ui().getTaskBox().getRows();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) rows[0];
		return result;
	}

	@Test
	public void hiddenUntilLoggedInAndSettled()
	{
		assertNull("not logged in", hint());
		harness.login(ACCOUNT);
		assertNull("no settled reading yet", hint());
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void shownShortOnTheSecondLineAndInFullInItsTooltip()
	{
		harness.loginAndSettle(ACCOUNT);
		assertEquals(Arrays.asList("Kraken · 3 left", "Konar · bonus in 3"), taskBoxRows());
		assertEquals("Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void hiddenWhileTheMasterIsUnknown()
	{
		harness.setAssignment(SlayerMaster.NONE, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertNull(hint());
		// The master's varbit syncs later.
		harness.setAssignment(6, 0, null);
		harness.tick();
		assertEquals("Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void hiddenForAMasterNotInTheTable()
	{
		harness.setAssignment(14, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertNull(hint());
	}

	@Test
	public void hiddenWithNoTaskAndNoCompletionSeen()
	{
		harness.setRemaining(0);
		harness.loginAndSettle(ACCOUNT);
		assertNull(hint());
	}

	@Test
	public void justCompletedTaskShowsTheNewStreak()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.completeTask(18);
		harness.tick();
		assertEquals("streak 48, no task yet", "Next bonus: task 50 (in 2)", hint());
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals("kept until the next task", "Next bonus: task 50 (in 2)", hint());

		// The next task, from the same master type.
		harness.setTask(43, "Hydras", 100, 100);
		harness.tick();
		assertEquals("Next bonus: task 50 (in 2)", hint());
	}

	@Test
	public void completingTheTenthTaskMovesToTheNext()
	{
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 49);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Next bonus: task 50 (in 1)", hint());
		// Completed without a session: the hint still follows the counter.
		harness.completeTask();
		harness.tick();
		assertEquals("Next bonus: task 60 (in 10)", hint());
	}

	@Test
	public void wildernessAndMortimerUseTheirOwnStreaks()
	{
		harness.setAssignment(SlayerMaster.KRYSTILIA, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Wilderness streak 9", "Next bonus: task 10 (in 1)", hint());
		harness.setRemaining(0);
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 10);
		harness.tick();
		assertEquals("the Wilderness streak went up", "Next bonus: task 20 (in 10)", hint());

		harness.setTask(43, "Hydras", 100, 100);
		harness.setAssignment(SlayerMaster.MORTIMER, 0, null);
		harness.tick();
		assertEquals("Mortimer streak 120", "Next bonus: task 130 (in 10)", hint());

		harness.setAssignment(SlayerMaster.KONAR, 0, null);
		harness.tick();
		assertEquals("regular streak 47", "Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void aStreakRisingATickAfterTheTaskEndsKeepsItsMaster()
	{
		harness.setAssignment(SlayerMaster.KRYSTILIA, 0, null);
		harness.loginAndSettle(ACCOUNT);
		harness.setRemaining(0);
		harness.tick();
		assertEquals("still the Wilderness streak", "Next bonus: task 10 (in 1)", hint());
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 10);
		harness.tick();
		assertEquals("the Wilderness streak went up", "Next bonus: task 20 (in 10)", hint());
	}

	@Test
	public void logoutHidesItAndAHopKeepsIt()
	{
		harness.loginAndSettle(ACCOUNT);
		harness.completeTask();
		harness.tick();
		assertEquals("Next bonus: task 50 (in 2)", hint());

		harness.hop();
		assertNull("no settled reading after the hop yet", hint());
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("the completed task's streak is kept across a hop", "Next bonus: task 50 (in 2)", hint());

		harness.logout();
		assertNull(hint());
		harness.loginAndSettle(ACCOUNT);
		assertNull("no task and no completion seen since the login screen", hint());
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.PluginHarness.item;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.Map;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Supplies counting as wired in the plugin ({@link PluginHarness}): only while RUNNING, and not while a bank-like
 * interface is open (tracked through WidgetLoaded / WidgetClosed and the root widget), after a "Drop" click on the
 * item, or around the local player's death. {@link SupplyExclusionsTest}, {@link SupplyTrackerTest} and
 * {@link SuppliesSessionTest} cover the rules themselves.
 */
public class HarnessSupplyExclusionsTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.SHARK, "Shark", 800, 0, "Eat", null, null, null, "Drop");
		harness.defineItem(ItemID.LOBSTER, "Lobster", 150, 0, "Eat", null, null, null, "Drop");
		harness.setInventory(item(ItemID.SHARK, 10), item(ItemID.LOBSTER, 5));
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	private void inventory(int sharks, int lobsters)
	{
		harness.setInventory(item(ItemID.SHARK, sharks), item(ItemID.LOBSTER, lobsters));
	}

	/** Stops the session and returns the saved record's supplies. */
	private Map<Integer, Long> stopAndGetSupplies()
	{
		harness.stop();
		Map<Integer, Long> supplies = harness.onlyRecord(ACCOUNT).getSupplies();
		return supplies == null ? Collections.emptyMap() : supplies;
	}

	private static long used(Map<Integer, Long> supplies, int itemId)
	{
		return supplies.getOrDefault(itemId, 0L);
	}

	@Test
	public void foodEatenWhileRunningIsCountedAndPriced()
	{
		assertTrue(harness.play());
		inventory(8, 5);
		harness.tick();
		inventory(8, 4);
		harness.tick();

		harness.stop();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(2L, used(record.getSupplies(), ItemID.SHARK));
		assertEquals(1L, used(record.getSupplies(), ItemID.LOBSTER));
		assertEquals(Long.valueOf(2 * 800 + 150), record.getSuppliesGeValue());
	}

	@Test
	public void suppliesCountOnlyWhileRunning()
	{
		inventory(9, 5);
		harness.tick();
		assertTrue(harness.play());
		inventory(8, 5);
		harness.tick();
		harness.pause();
		inventory(7, 5);
		harness.tick();
		// Eaten between the last tick and Play: Play takes a fresh baseline, so this is not counted either.
		inventory(6, 5);
		assertTrue(harness.play());
		inventory(5, 5);
		harness.tick();

		assertEquals(2L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void nothingIsCountedWhileTheBankIsOpenOrJustAfter()
	{
		assertTrue(harness.play());
		harness.openInterface(InterfaceID.BANKMAIN);
		inventory(3, 0);
		harness.tick();
		inventory(20, 0);
		harness.tick();
		harness.closeInterface(InterfaceID.BANKMAIN);
		// Items the bank moved can still arrive for a couple of ticks after it closes.
		inventory(18, 0);
		harness.ticks(SupplyExclusions.INTERFACE_TICKS + 1);

		inventory(17, 0);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void bankOpenedAndClosedBetweenTicksStillExcludesTheTick()
	{
		assertTrue(harness.play());
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		inventory(4, 5);
		harness.tick();

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(0L, used(supplies, ItemID.SHARK));
	}

	@Test
	public void otherInterfacesDoNotExclude()
	{
		assertTrue(harness.play());
		harness.openInterface(InterfaceID.INVENTORY);
		inventory(9, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void droppedItemIsNotASupplyButOthersOnTheSameTickAre()
	{
		assertTrue(harness.play());
		harness.clickMenu("Drop", ItemID.SHARK);
		inventory(9, 4);
		harness.tick();
		harness.ticks(SupplyExclusions.DROP_WINDOW_TICKS);
		// Outside the drop window, eating a shark counts again.
		inventory(8, 4);
		harness.tick();

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(1L, used(supplies, ItemID.SHARK));
		assertEquals(1L, used(supplies, ItemID.LOBSTER));
	}

	@Test
	public void otherMenuOptionsDoNotExclude()
	{
		assertTrue(harness.play());
		harness.clickMenu("Eat", ItemID.SHARK);
		inventory(9, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void nothingIsCountedAroundTheLocalPlayersDeath()
	{
		assertTrue(harness.play());
		harness.localPlayerDies();
		inventory(0, 0);
		harness.ticks(SupplyExclusions.DEATH_TICKS + 1);
		assertEquals(0L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void suppliesCountAgainAfterTheDeathWindow()
	{
		assertTrue(harness.play());
		harness.localPlayerDies();
		inventory(0, 0);
		harness.ticks(SupplyExclusions.DEATH_TICKS + 1);
		inventory(5, 5);
		harness.tick();
		inventory(4, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void anotherActorsDeathDoesNotExclude()
	{
		assertTrue(harness.play());
		harness.otherActorDies();
		inventory(9, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Rule;
import org.junit.Test;

/**
 * What to bring as wired in the panel ({@link PluginHarness}): the collapsible section below History, its rows
 * and their order, and its rebuilds with the estimate cache. {@link SupplyRecommendationTest} covers the amounts.
 */
public class HarnessSupplyRecommendationTest
{
	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** Two completed tasks, 30 kills: 52 prayer doses (12,000 gp a 4-dose potion), 90 cannonballs (200 gp), 3 trips. */
	private static List<LedgerRecord> twoTasks()
	{
		LedgerRecord first = record(10, map(100, 12, 101, 30), 1);
		first.setSupplyDoses(Collections.singletonMap(100, 4));
		first.setUnitGePrices(map(100, 12_000, 101, 200));
		LedgerRecord second = record(20, map(100, 40, 101, 60), 2);
		second.setSupplyDoses(Collections.singletonMap(100, 4));
		second.setUnitGePrices(map(100, 12_000, 101, 200));
		return Arrays.asList(first, second);
	}

	private void start(int remaining, List<LedgerRecord> records)
	{
		start(remaining, records, 12_000, 200);
	}

	/** Starts with today's GE prices of the potion and the cannonballs (0: unavailable). */
	private void start(int remaining, List<LedgerRecord> records, long potionGe, long cannonballGe)
	{
		harness.defineItem(100, "Prayer potion(4)", potionGe, 200);
		harness.defineItem(101, "Cannonballs", cannonballGe, 0);
		harness.startUp();
		harness.setTask(42, "Abyssal demons", remaining, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		setRecords(records);
	}

	private void setRecords(List<LedgerRecord> records)
	{
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT, records));
		// The item names are looked up on the client thread and answered on the EDT.
		harness.drain();
	}

	private String header()
	{
		String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getHistoryEstimate().getBringText();
		});
		return text[0];
	}

	private List<String> lines()
	{
		@SuppressWarnings("unchecked")
		List<String>[] lines = new List[1];
		harness.onEdt(() -> lines[0] = harness.ui().getHistoryEstimate().getBringLines());
		return lines[0];
	}

	private String tooltip()
	{
		String[] text = new String[1];
		harness.onEdt(() -> text[0] = harness.ui().getHistoryEstimate().getBringTooltip());
		return text[0];
	}

	private String rowTooltip(int index)
	{
		String[] text = new String[1];
		harness.onEdt(() -> text[0] = harness.ui().getHistoryEstimate().getBringRowTooltip(index));
		return text[0];
	}

	private int builds()
	{
		int[] builds = new int[1];
		harness.onEdt(() -> builds[0] = harness.ui().getHistoryEstimate().getBringBuildCount());
		return builds[0];
	}

	private void open()
	{
		harness.onEdt(() -> harness.ui().getHistoryEstimate().clickBringTitle());
	}

	@Test
	public void collapsedByDefaultAndOpensToRowsSortedByValue()
	{
		start(7, twoTasks());

		// 3 trips over 30 kills, times 7 kills left: 0.7, rounded up.
		assertEquals("What to bring (2 tasks) | Show | ~1 bank trip | 2 supplies", header());
		assertTrue(lines().isEmpty());
		String tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("Suggested for the 7 kills left."));
		assertTrue(tooltip, tooltip.contains("over 2 completed tasks (30 kills) with supplies or values"));
		assertTrue(tooltip, tooltip.contains("rounded up to whole tracked units"));
		assertTrue(tooltip, tooltip.contains("pooled trips per kill over 2 completed tasks (30 kills)"));

		open();
		assertEquals("What to bring (2 tasks) | Hide | ~1 bank trip | 2 supplies", header());
		// 52 doses / 30 * 7 = 12.1 -> 13 (39,000 gp); 90 / 30 * 7 = 21 (4,200 gp): the potion first despite fewer.
		assertEquals(Arrays.asList("Prayer potion | 13 doses", "Cannonballs | x21"), lines());
		assertEquals("<html>13 doses of Prayer potion for the 7 kills left</html>", rowTooltip(0));
		assertEquals("<html>21 x Cannonballs for the 7 kills left</html>", rowTooltip(1));

		open();
		assertEquals("What to bring (2 tasks) | Show | ~1 bank trip | 2 supplies", header());
		assertTrue(lines().isEmpty());
	}

	@Test
	public void unpricedRowsSortByAmountThenName()
	{
		LedgerRecord record = record(10, map(100, 4, 101, 10, 102, 10), 0);
		// No GE price today for any of them: the views wait for them until the wait runs out.
		start(10, Collections.singletonList(record), 0, 0);
		harness.onEdt(() ->
		{
			harness.historyModel().expireCurrentPricesWait();
			harness.historyModel().endExpiredCurrentPricesWait();
		});
		// The item names are looked up on the client thread and answered on the EDT.
		harness.drain();
		harness.onEdt(() -> harness.historyModel().addItemNames(Collections.singleton(102),
			Collections.singletonMap(102, "Arrows"), null));
		header();
		open();

		assertEquals(Arrays.asList("Arrows | x10", "Cannonballs | x10", "Prayer potion(4) | x4"), lines());
		assertEquals("What to bring (1 task) | Hide | No bank trips | 3 supplies", header());
	}

	@Test
	public void rebuildsOnlyWhenTheKillsLeftChangeNotOnTheTimer()
	{
		start(7, twoTasks());
		open();
		header();
		int builds = builds();
		header();
		header();
		assertEquals("the refresh timer rebuilds nothing", builds, builds());

		harness.setRemaining(1);
		harness.tick();
		assertEquals("What to bring (2 tasks) | Hide | ~1 bank trip | 2 supplies", header());
		assertEquals(builds + 1, builds());
		// 52 / 30 = 1.7 -> 2 doses; 90 / 30 = 3.
		assertEquals(Arrays.asList("Prayer potion | 2 doses", "Cannonballs | x3"), lines());
		assertTrue(tooltip(), tooltip().contains("Suggested for the 1 kill left."));
		assertEquals("<html>3 x Cannonballs for the 1 kill left</html>", rowTooltip(1));
	}

	@Test
	public void hiddenWithoutATaskAndBackWhenItReturnsStillOpen()
	{
		start(7, twoTasks());
		open();
		assertEquals("What to bring (2 tasks) | Hide | ~1 bank trip | 2 supplies", header());

		harness.setRemaining(0);
		harness.tick();
		assertNull(header());

		harness.setRemaining(7);
		harness.tick();
		assertEquals("open state kept for the session", "What to bring (2 tasks) | Hide | ~1 bank trip | 2 supplies",
			header());
		assertEquals(Arrays.asList("Prayer potion | 13 doses", "Cannonballs | x21"), lines());
	}

	@Test
	public void hiddenWithoutHistoryAndUpdatedWhenRecordsChange()
	{
		start(7, Collections.emptyList());
		assertNull(header());

		setRecords(twoTasks());
		assertEquals("What to bring (2 tasks) | Show | ~1 bank trip | 2 supplies", header());

		setRecords(Collections.singletonList(record(10, map(101, 20), 5)));
		open();
		// 5 trips over 10 kills, times 7: 3.5 -> 4; 20 / 10 * 7 = 14.
		assertEquals("What to bring (1 task) | Hide | ~4 bank trips | 1 supply", header());
		assertEquals(Collections.singletonList("Cannonballs | x14"), lines());
	}

	@Test
	public void itemNamesArrivingLaterReplaceItemIds()
	{
		start(10, Collections.singletonList(record(10, map(300, 5), 0)));
		open();
		assertEquals(Collections.singletonList("Item 300 | x5"), lines());

		harness.onEdt(() -> harness.historyModel().addItemNames(Collections.singleton(300),
			Collections.singletonMap(300, "<b>Bolts</b>"), null));
		header();
		assertEquals("the name is shown as text", Collections.singletonList("<b>Bolts</b> | x5"), lines());
		assertEquals("<html>5 x &lt;b&gt;Bolts&lt;/b&gt; for the 10 kills left</html>", rowTooltip(0));
	}

	@Test
	public void singularAndDoseUnits()
	{
		harness.defineItem(ItemID.ANCHOVIE_PIZZA, "Anchovy pizza", 100, 0);
		harness.defineItem(ItemID.AMULET_OF_GLORY_6, "Amulet of glory(6)", 10_000, 0);
		LedgerRecord record = record(10, map(100, 1, ItemID.ANCHOVIE_PIZZA, 20, ItemID.AMULET_OF_GLORY_6, 1), 1);
		Map<Integer, Integer> doses = new java.util.HashMap<>();
		doses.put(100, 4);
		doses.put(ItemID.ANCHOVIE_PIZZA, 2);
		doses.put(ItemID.AMULET_OF_GLORY_6, 6);
		record.setSupplyDoses(doses);
		start(1, Collections.singletonList(record));
		open();

		assertEquals("What to bring (1 task) | Hide | ~1 bank trip | 3 supplies", header());
		// At today's prices: a dose 3,000 gp, a charge 1,667 gp, 2 bites 100 gp.
		assertEquals(Arrays.asList("Prayer potion | 1 dose", "Amulet of glory | 1 charge", "Anchovy pizza | 2 bites"),
			lines());
		assertEquals("<html>1 dose of Prayer potion for the 1 kill left</html>", rowTooltip(0));
	}

	@Test
	public void bankOnlyAndNoTrackedSuppliesMessages()
	{
		LedgerRecord bankOnly = record(10, null, 2);
		start(10, Collections.singletonList(bankOnly));
		open();
		assertEquals("What to bring (1 task) | Hide | ~2 bank trips | ", header());
		assertEquals(Collections.singletonList("No supply data in history"), lines());
		assertTrue(tooltip(), tooltip().contains("Supplies: no completed task recorded supplies or values."));

		LedgerRecord none = record(10, Collections.emptyMap(), 0);
		none.setLootGeValue(0L);
		setRecords(Collections.singletonList(none));
		assertEquals("What to bring (1 task) | Hide | No bank trips | ", header());
		assertEquals(Collections.singletonList("No tracked supplies in history"), lines());

		LedgerRecord unknownTrips = record(10, Collections.emptyMap(), 0);
		unknownTrips.setBankTrips(null);
		setRecords(Collections.singletonList(unknownTrips));
		assertEquals("What to bring (1 task) | Hide |  | ", header());
		assertTrue(tooltip(), tooltip().contains("Bank trips: no completed task recorded them."));
	}

	private static LedgerRecord record(int kills, Map<Integer, Long> supplies, int bankTrips)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(42);
		record.setMonster("Abyssal demons");
		record.setKills(kills);
		record.setActiveMillis(kills * 1_000L);
		record.setCompleted(true);
		record.setSupplies(supplies);
		record.setBankTrips(bankTrips);
		return record;
	}

	private static Map<Integer, Long> map(int... values)
	{
		Map<Integer, Long> result = new java.util.HashMap<>();
		for (int i = 0; i < values.length; i += 2)
		{
			result.put(values[i], (long) values[i + 1]);
		}
		return result;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Rule;
import org.junit.Test;

/**
 * The task box's advice row as wired in the plugin ({@link PluginHarness}): shown for the current task with
 * enough history, hidden otherwise, following the "Task advisor" settings live and never worked out on the refresh
 * timer. {@link TaskAdvisorTest} covers the rules.
 */
public class HarnessTaskAdvisorTest
{
	private static final long HOUR = 60 * 60_000L;
	/** The current task's creature key; the records' monsters are this and the next ones. */
	private static final int TASK = 42;
	/** Tasks per monster in {@link #history}: the fewest the advisor counts. */
	private static final int TASKS = 3;
	private static final Gson GSON = new Gson();

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void shownAsTheThirdLineOnAnAssignmentWithEnoughHistory()
	{
		harness.setAssignment(SlayerMaster.KONAR, 0, null);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 47);
