		String json = "{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\",\"monster\":\"Kraken\","
			+ "\"creatureId\":42,\"initialAmount\":3,\"kills\":3,\"activeMillis\":60000,\"startedAt\":1000,"
			+ "\"endedAt\":61000,\"completed\":true,\"partial\":false}]}";
		Files.write(harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json"), json.getBytes(StandardCharsets.UTF_8));

		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.completeTask(18);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		LedgerRecord old = records.stream().filter(r -> "old".equals(r.getId())).findFirst().orElseThrow(AssertionError::new);
		assertNull(old.getSlayerMaster());
		assertNull(old.getPointsEarned());
		assertNull(old.getTaskStreak());
		List<String> rows = historyText();
		assertEquals(2, rows.size());
		String oldRow = rows.get(1);
		assertTrue(oldRow, oldRow.endsWith("<br>Deaths: -</html>"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.ChatMessageType;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Bonecrusher handling, superior spawns and bank trips as wired in the plugin ({@link PluginHarness}): the crusher is
 * read from the inventory and worn items at each loot drop on the client thread, the spawn message and bank interfaces
 * count only while RUNNING, and the counts survive logout and a restart. {@link CrushedLootFilterTest},
 * {@link SuperiorSpawnMessageTest}, {@link BankTripCounterTest} and {@link SessionTrackerCountersTest} cover the rules.
 */
public class HarnessTaskDetailsTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String SUPERIOR = "<col=ef1020>A superior foe has appeared...</col>";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.WYRM_BONES, "Wyrm bones", 600, 1, "Bury");
		harness.defineItem(ItemID.ABYSSAL_ASHES, "Abyssal ashes", 300, 1, "Scatter");
		harness.defineItem(ItemID.COINS, "Coins", 1, 1);
		harness.defineItem(ItemID.BONECRUSHER, "Bonecrusher", 0, 1);
		harness.defineItem(ItemID.BONECRUSHER_NECKLACE, "Bonecrusher necklace", 0, 1, "Wear");
		harness.defineItem(ItemID.ASH_SANCTIFIER, "Ash sanctifier", 0, 1);
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Wyrms", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
	}

	/** Loot from one kill, arriving through LootManager on the next tick. */
	private void killDrops()
	{
		harness.lootOnNextTick(ItemID.WYRM_BONES, 1);
		harness.lootOnNextTick(ItemID.ABYSSAL_ASHES, 1);
		harness.lootOnNextTick(ItemID.COINS, 100);
		harness.tick();
	}

	private ItemTally loot()
	{
		return harness.tracker().getLoot();
	}

	// ---- Bonecrusher ----

	@Test
	public void lootWithoutACrusherKeepsBonesAndAshes()
	{
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));
		assertEquals(1, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(100, loot().get(ItemID.COINS));
	}

	@Test
	public void crusherIsCheckedAtEachLootDrop()
	{
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1));
		killDrops();
		assertEquals("crushed", 0, loot().get(ItemID.WYRM_BONES));
		assertEquals(1, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(100, loot().get(ItemID.COINS));

		// Banked mid-task: the next kill's bones count again.
		harness.setInventory();
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));

		// A worn bonecrusher necklace and an ash sanctifier.
		harness.setWorn(EquipmentInventorySlot.AMULET, ItemID.BONECRUSHER_NECKLACE, 1);
		harness.setInventory(PluginHarness.item(ItemID.ASH_SANCTIFIER, 1));
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));
		assertEquals(2, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(300, loot().get(ItemID.COINS));

		harness.stop();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.WYRM_BONES));
		assertEquals(Long.valueOf(2), record.getLoot().get(ItemID.ABYSSAL_ASHES));
	}

	@Test
	public void lootPostedBetweenTicksIsFilteredToo()
	{
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1));
		harness.postLoot(ItemID.WYRM_BONES, 1);
		assertEquals(0, loot().get(ItemID.WYRM_BONES));
	}

	@Test
	public void overridesIgnoreWhatIsCarried()
	{
		harness.config.bonecrusherHandling = BonecrusherMode.ALWAYS_EXCLUDE;
		killDrops();
		assertEquals(0, loot().get(ItemID.WYRM_BONES));
		assertEquals(0, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(100, loot().get(ItemID.COINS));

		harness.config.bonecrusherHandling = BonecrusherMode.NEVER_EXCLUDE;
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1), PluginHarness.item(ItemID.ASH_SANCTIFIER, 1));
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));
		assertEquals(1, loot().get(ItemID.ABYSSAL_ASHES));
	}

	@Test
	public void lootOfOnlyCrushedBonesAddsNothing()
	{
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1));
		harness.lootOnNextTick(ItemID.WYRM_BONES, 1);
		harness.tick();
		assertTrue(loot().isEmpty());
	}

	// ---- Superior spawns ----

	@Test
	public void superiorSpawnCountsOnlyWhileRunning()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.chat(ChatMessageType.SPAM, SUPERIOR);
		harness.chat(ChatMessageType.PUBLICCHAT, SUPERIOR);
		harness.chat(ChatMessageType.GAMEMESSAGE, "A superior foe has appeared");
		assertEquals(2, harness.tracker().getSuperiorsSpawned());

		harness.pause();
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		assertEquals("not while paused", 2, harness.tracker().getSuperiorsSpawned());

		assertTrue(harness.play());
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.stop();
		assertEquals(Integer.valueOf(3), harness.onlyRecord(ACCOUNT).getSuperiorsSpawned());
	}

	@Test
	public void superiorSpawnDuringTheCompletionGraceWindowIsNotAdded()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.completeTask();
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertFalse(harness.tracker().hasPendingCompletion());

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Integer.valueOf(1), record.getSuperiorsSpawned());
	}

	// ---- Bank trips ----

	@Test
	public void bankOpensAndReopensCountAsTrips()
	{
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.ticks(5);
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.ticks(10);
		// A forgotten item: the same trip.
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		assertEquals(1, harness.tracker().getBankTrips());

		harness.ticks(BankTripCounter.SAME_TRIP_TICKS + 1);
		harness.openInterface(InterfaceID.BANK_DEPOSITBOX);
		harness.closeInterface(InterfaceID.BANK_DEPOSITBOX);
		assertEquals(2, harness.tracker().getBankTrips());

		// Other interfaces are not banks.
		harness.ticks(BankTripCounter.SAME_TRIP_TICKS + 1);
		harness.openInterface(InterfaceID.SEED_VAULT);
		harness.closeInterface(InterfaceID.SEED_VAULT);
		assertEquals(2, harness.tracker().getBankTrips());

		harness.openInterface(InterfaceID.SHARED_BANK);
		assertEquals(3, harness.tracker().getBankTrips());
		harness.closeInterface(InterfaceID.SHARED_BANK);

		harness.stop();
		assertEquals(Integer.valueOf(3), harness.onlyRecord(ACCOUNT).getBankTrips());
	}

	@Test
	public void bankingWhilePausedIsNotATripAndANewSessionStartsAtZero()
	{
		harness.pause();
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		assertEquals(0, harness.tracker().getBankTrips());
		harness.ticks(BankTripCounter.SAME_TRIP_TICKS + 1);
		assertTrue(harness.play());
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		assertEquals(1, harness.tracker().getBankTrips());
		harness.stop();
		assertEquals(Integer.valueOf(1), harness.onlyRecord(ACCOUNT).getBankTrips());

		// The next session's first bank visit counts even within the window, and its count starts at 0.
		assertTrue(harness.play());
		assertEquals(0, harness.tracker().getBankTrips());
		harness.openInterface(InterfaceID.BANKMAIN);
		assertEquals(1, harness.tracker().getBankTrips());
	}

	// ---- Persistence and panel ----

	@Test
	public void countsSurviveLogoutAndARestart()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.logout();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertNotNull(snapshot);
		assertEquals(Integer.valueOf(1), snapshot.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), snapshot.getBankTrips());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as paused", SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals(1, harness.tracker().getSuperiorsSpawned());
		assertEquals(1, harness.tracker().getBankTrips());
		assertTrue(harness.play());
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.stop();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Integer.valueOf(2), record.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), record.getBankTrips());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void panelShowsTheCountsOnlyWhileASessionIsActive()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.openInterface(InterfaceID.BANKMAIN);
		assertEquals("Superiors: 1 | Deaths: 0 | Bank trips: 1", countsText());
		harness.pause();
		assertEquals("Superiors: 1 | Deaths: 0 | Bank trips: 1", countsText());
		harness.stop();
		assertNull("hidden once the session ended", countsText());
	}

	private String countsText()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getCountsText();
		});
		return text[0];
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.PluginPanel;
import org.junit.Rule;
import org.junit.Test;

/**
 * The task icons of Overall totals as wired in the plugin: By monster's group names and By master's monsters
 * assigned show the task's item sprite at the small slot size, through the {@code ItemManager.getImage} fake, on the
 * EDT; an unknown task keeps an empty slot of the same size; nothing is asked for while the section is closed or by
 * the refresh timer.
 */
public class HarnessTaskIconsTest
{
	/** A name that is no task, long enough to test the sidebar's width. */
	private static final String UNKNOWN = "Lava strykewyrms in the Wilderness Slayer Cave";
	private static final String SLOT = " " + ItemListView.ICON_WIDTH + "x" + ItemListView.ICON_HEIGHT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void byMonsterNamesShowTheirTasksIcon()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			records.add(monster("Dust devils"));
		}
		for (int i = 0; i < 2; i++)
		{
			LedgerRecord deviant = monster("Aberrant spectres");
			deviant.setVariant("Deviant spectres");
			records.add(deviant);
		}
		LedgerRecord cannon = monster("Dust devils");
		cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 200L));
		records.add(cannon);
		records.add(monster(UNKNOWN));
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, records);
			harness.ui().getOverallTotals().clickTitle();
			harness.ui().getOverallTotals().setGrouping(OverallTotals.Grouping.MONSTER);
		});

		List<String> rows = rows();
		assertEquals(4, rows.size());
		// The names read as before: the icon is on the name's label, not in its text.
		assertTrue(rows.get(0), rows.get(0).startsWith("Dust devils | 3 tasks\n"));
		assertTrue(rows.get(1), rows.get(1).startsWith("Deviant spectres | 2 tasks\n"));
		assertTrue(rows.get(2), rows.get(2).startsWith("Dust devils (cannon) | 1 task\n"));
		assertTrue(rows.get(3), rows.get(3).startsWith(UNKNOWN + " | 1 task\n"));
		// A Catacombs variant and a cannon task show their task's icon; an unknown task an empty slot of the same size.
		assertEquals(Arrays.asList(ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT, ItemID.SLAYERGUIDE_ABERRANTSPECTER + SLOT,
			ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT, "-" + SLOT),
			onEdt(() -> harness.ui().getOverallTotals().getNameIcons()));

		int width = onEdt(() -> harness.ui().getOverallTotals().getListPreferredWidth());
		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);

		// Overall and By month have no icons; By master shows the master's face (HarnessMoreIconsTest).
		for (OverallTotals.Grouping grouping : Arrays.asList(OverallTotals.Grouping.ALL,
			OverallTotals.Grouping.MONTH))
		{
			harness.onEdt(() -> harness.ui().getOverallTotals().setGrouping(grouping));
			harness.drain();
			assertEquals(grouping.toString(), Collections.singletonList("none"),
				onEdt(() -> harness.ui().getOverallTotals().getNameIcons()));
		}
	}

	@Test
	public void monstersAssignedLinesShowTheirTasksIcon()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		LedgerRecord deviant = monster("Aberrant spectres");
		deviant.setVariant("Deviant spectres");
		LedgerRecord cannon = monster("Dust devils");
		cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 200L));
		List<LedgerRecord> records = Arrays.asList(monster("Dust devils"), monster("Dust devils"), cannon, deviant);
		List<AssignmentEntry> entries = Arrays.asList(entry("Abyssal demons"), entry(UNKNOWN));
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, records);
			harness.historyModel().setAssignments(PluginHarness.ACCOUNT, entries);
			harness.ui().getOverallTotals().clickTitle();
			harness.ui().getOverallTotals().setGrouping(OverallTotals.Grouping.MASTER);
		});
		rows();

		// Variants and cannon tasks count as their task, with its icon; the unknown name keeps an empty slot.
		assertEquals(Arrays.asList("Dust devils | 3 / 6 (50%)", "Aberrant spectres | 1 / 6 (17%)",
			"Abyssal demons | 1 / 6 (17%)", UNKNOWN + " | 1 / 6 (17%)"),
			onEdt(() -> harness.ui().getOverallTotals().getAssignments(0).getLineTexts()));
		assertEquals(Arrays.asList(ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT, ItemID.SLAYERGUIDE_ABERRANTSPECTER + SLOT,
			ItemID.SLAYERGUIDE_ABYSSALDEMON + SLOT, "-" + SLOT),
			onEdt(() -> harness.ui().getOverallTotals().getAssignments(0).getLineIcons()));
		// The master's name shows the master's face, or an empty slot when the image is not bundled.
		String konar = MasterIcons.fileName("Konar");
		assertEquals(Collections.singletonList(MasterIcons.class.getResource(MasterIcons.DIRECTORY + konar) != null
			? "master:" + konar + SLOT : "-" + SLOT), onEdt(() -> harness.ui().getOverallTotals().getNameIcons()));

		int width = onEdt(() -> harness.ui().getOverallTotals().getListPreferredWidth());
		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);

		// Equal lines are not drawn again: the same entries again rebuild the totals but ask for no icon.
		int before = harness.itemImageRequests();
		int builds = onEdt(() -> harness.ui().getOverallTotals().getBuildCount());
		harness.onEdt(() -> harness.historyModel().setAssignments(PluginHarness.ACCOUNT, new ArrayList<>(entries)));
		harness.drain();
		assertTrue("the totals were built again",
			onEdt(() -> harness.ui().getOverallTotals().getBuildCount()) > builds);
		assertEquals(before, harness.itemImageRequests());
	}

	@Test
	public void noIconIsAskedForWhileClosedOrByTheRefreshTimer()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		List<LedgerRecord> records = Arrays.asList(monster("Dust devils"), monster("Kurask"));
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT, records));
		harness.drain();
		// The Task history rows have asked for theirs; the closed totals ask for none.
		int before = harness.itemImageRequests();
		harness.onEdt(() ->
		{
			harness.ui().getOverallTotals().setGrouping(OverallTotals.Grouping.MONSTER);
			harness.panel().refresh();
		});
		harness.drain();
		assertEquals("closed: no icons", before, harness.itemImageRequests());

		// Opening asks for the two icons once, on the EDT (the fake fails a call from any other thread).
		harness.onEdt(() -> harness.ui().getOverallTotals().clickTitle());
		rows();
		assertEquals(before + 2, harness.itemImageRequests());
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			harness.panel().refresh();
		});
		harness.drain();
		assertEquals("the refresh timer asks for none", before + 2, harness.itemImageRequests());

		// Closed again, new records ask for none in the totals: only the one Task history row asks for its icon.
		harness.onEdt(() ->
		{
			harness.ui().getOverallTotals().clickTitle();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(monster("Nechryael")));
		});
		harness.drain();
		assertEquals(before + 3, harness.itemImageRequests());
	}

	/** A completed Konar task of {@code name}, without values. */
	private static LedgerRecord monster(String name)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(UUID.randomUUID().toString());
		record.setMonster(name);
		record.setSlayerMaster(SlayerMaster.KONAR);
		record.setEndedAt(1);
		record.setKills(10);
		record.setActiveMillis(30 * 60_000L);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}

	/** A Konar "Skipped / blocked" entry. */
	private static AssignmentEntry entry(String name)
	{
		AssignmentEntry entry = new AssignmentEntry();
		entry.setId(UUID.randomUUID().toString());
		entry.setMonster(name);
		entry.setSlayerMaster(SlayerMaster.KONAR);
		entry.setOutcome(AssignmentOutcome.SKIPPED);
		entry.setEndedAt(1);
		return entry;
	}

	/** Reads {@code read} on the EDT. */
	private <T> T onEdt(Supplier<T> read)
	{
		AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}

	/** The Overall totals rows, after the totals worked out off the EDT arrive. */
	private List<String> rows()
	{
		harness.drain();
		return onEdt(() -> harness.ui().getOverallTotals().getRows());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Task locations (Part B) as wired in the panel ({@link PluginHarness}): the History estimate and What to bring
 * use only the history at the current task's location when there is some (the assigned area, else the session's
 * region with the most kills, else where the player is), and say so; otherwise all of it. The "Name this location"
 * prompt suggests the task's bundled Wiki locations and the player's other names. {@link TaskStatisticsTest} and
 * {@link TaskLocationTest} cover the rules.
 */
public class HarnessTaskLocationEstimateTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final long MINUTE = 60_000L;
	private static final int TASK = 42;
	private static final int SMOKE = 12_946;
	private static final int CATACOMBS = 6_557;
	private static final int UNNAMED = 13_623;
	private static final int KONAR_AREA = 7;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Dust devils", 20, 20);
		harness.setPlayerRegion(SMOKE);
	}

	/**
	 * A completed Dust devils task of 10 kills in {@code minutes} minutes, 1,000 gp loot a minute (in coins), at
	 * {@code location}.
	 */
	private static LedgerRecord task(int minutes, String location)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId("task-" + minutes);
		record.setCreatureId(TASK);
		record.setMonster("Dust devils");
		record.setKills(10);
		record.setActiveMillis(minutes * MINUTE);
		record.setCompleted(true);
		record.setLootGeValue(minutes * 1_000L);
		record.setLootHaValue(minutes * 1_000L);
		record.setSuppliesGeValue(0L);
		record.setSupplies(Collections.singletonMap(100, (long) minutes));
		record.setBankTrips(0);
		record.setLocation(location);
		return SavedItems.withItems(record);
	}

	private void name(int region, String name)
	{
		harness.setRsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX + region, name);
	}

	private void showRecords(LedgerRecord... records)
	{
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, Arrays.asList(records)));
		harness.drain();
	}

