		assertFalse(harness.isResetLocationSkipsTicked());
		assertNull(skipKey(SMOKE));
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertTrue(harness.play());
		kill(1, SMOKE);
		assertEquals(SMOKE, promptRegion());
	}

