package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Keys, clue scrolls and notable drops as wired in the plugin ({@link PluginHarness}): counted from loot received while
 * the session runs, notable stacks valued at the "Notable drop value" and "Loot price" settings, pet messages, the live
 * panel, the saved record and its history tooltip, and the active session file. {@link KeysAndCluesTest},
 * {@link NotableDropsTest} and {@link PetMessageTest} cover the rules.
 */
public class HarnessTaskLootTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final int HARD_CLUE = ClueScrollIds.HARD[0];
	private static final int ELITE_CLUE = ClueScrollIds.ELITE[0];
	private static final String PET_TEXT = "<col=ef1020>You have a funny feeling like you're being followed.</col>";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 50, 50);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 10);
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.defineItem(ItemID.RUNE_PLATEBODY, "Rune platebody", 100_000, 39_000);
		harness.defineItem(ItemID.RUNE_FULL_HELM, "Rune full helm", 99_999, 21_120);
		harness.defineItem(ItemID.KONAR_KEY, "Brimstone key", 0, 0);
	}

	private void loot(int... idQuantityPairs)
	{
		for (int i = 0; i < idQuantityPairs.length; i += 2)
		{
			harness.lootOnNextTick(idQuantityPairs[i], idQuantityPairs[i + 1]);
		}
		harness.tick();
	}

	private List<String> liveLines()
	{
		final List<?>[] lines = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			lines[0] = harness.ui().getTaskLootLines();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) lines[0];
		return result;
	}

	private String liveTooltip()
	{
		final String[] text = new String[1];
		harness.onEdt(() -> text[0] = harness.ui().getTaskLootTooltip());
		return text[0];
	}

	/**
	 * The history rows. The brimstone key has no GE price, so the history waits for it until the wait runs out
	 *; the wait is run out first.
	 */
	private List<String> historyText()
	{
		final List<?>[] rows = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.historyModel().expireCurrentPricesWait();
			harness.historyModel().endExpiredCurrentPricesWait();
			rows[0] = harness.ui().getHistory().getValuesText();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) rows[0];
		return result;
	}

	private List<NotableDrop> sessionDrops()
	{
		return harness.tracker().getNotableDrops();
	}

	@Test
	public void lootWhileRunningCountsAndLootWhilePausedDoesNot()
	{
		harness.loginAndSettle(ACCOUNT);
		assertNull("nothing to show yet", liveLines());
		assertTrue(harness.play());
		assertNull(liveLines());

		loot(ItemID.ABYSSAL_WHIP, 1, ItemID.KONAR_KEY, 2, HARD_CLUE, 1);
		assertEquals(Arrays.asList("Keys: 2 brimstone", "Clues: 1 hard", "Notable drops:", "  Abyssal whip: 1.5M"),
			liveLines());
		assertEquals("<html>Notable drops:<br>&nbsp;&nbsp;Abyssal whip: 1,500,000 gp</html>", liveTooltip());

		harness.pause();
		loot(ItemID.ABYSSAL_WHIP, 1, ItemID.KONAR_KEY, 1, ELITE_CLUE, 1);
		assertEquals("paused: nothing counted", Arrays.asList("Keys: 2 brimstone", "Clues: 1 hard",
			"Notable drops:", "  Abyssal whip: 1.5M"), liveLines());
		assertEquals(1, sessionDrops().size());

		harness.stop();
		assertNull("hidden once the session ends", liveLines());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(2), record.getLoot().get(ItemID.KONAR_KEY));
		assertEquals(1, record.getNotableDrops().size());
		NotableDrop whip = record.getNotableDrops().get(0);
		assertEquals(Integer.valueOf(ItemID.ABYSSAL_WHIP), whip.getItemId());
		assertEquals("Abyssal whip", whip.getName());
		assertEquals(1, whip.getQuantity());
		assertEquals(Long.valueOf(1_500_000), whip.getGeValue());
		assertEquals(Long.valueOf(72_000), whip.getHaValue());
		assertFalse(whip.isPet());

		String row = historyText().get(0);
		assertTrue(row, row.contains("<br>Keys: 2 brimstone<br>Clues: 1 hard<br>Notable drops:"
			+ "<br>&nbsp;&nbsp;Abyssal whip: 1,500,000 gp"));
	}

	/**
	 * Notable drops are priced through ItemManager only while loot is recorded: never for loot while idle, but still
	 * while running and for the final kill's loot in the held-completion grace window.
	 */
	@Test
	public void notableDropsArePricedOnlyWhileLootIsRecorded()
	{
		harness.setTask(TASK, "Abyssal demons", 2, 50);
		harness.loginAndSettle(ACCOUNT);
		final int idleLookups = harness.itemPriceLookups(ItemID.ABYSSAL_WHIP);
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertEquals("no price lookup for loot while idle", idleLookups,
			harness.itemPriceLookups(ItemID.ABYSSAL_WHIP));

		assertTrue(harness.play());
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertTrue("priced while running", harness.itemPriceLookups(ItemID.ABYSSAL_WHIP) > idleLookups);
		assertEquals(1, sessionDrops().size());

		harness.setRemaining(1);
		harness.tick();
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		final int heldLookups = harness.itemPriceLookups(ItemID.ABYSSAL_WHIP);
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertTrue("priced in the grace window", harness.itemPriceLookups(ItemID.ABYSSAL_WHIP) > heldLookups);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals("the running kill's and the final kill's whips", 2, record.getNotableDrops().size());
	}

	@Test
	public void thresholdBoundaryAndChangingTheSetting()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());

		loot(ItemID.RUNE_PLATEBODY, 1, ItemID.RUNE_FULL_HELM, 1);
		assertEquals("exactly the threshold is notable; 1 gp below is not", 1, sessionDrops().size());
		assertEquals(Integer.valueOf(ItemID.RUNE_PLATEBODY), sessionDrops().get(0).getItemId());

		harness.setNotableDropThreshold(200_000);
		loot(ItemID.RUNE_PLATEBODY, 1);
		assertEquals("below the new threshold", 1, sessionDrops().size());
		loot(ItemID.RUNE_PLATEBODY, 2);
		assertEquals("one stack of two is worth the threshold", 2, sessionDrops().size());
		assertEquals(Long.valueOf(200_000), sessionDrops().get(1).getGeValue());
		assertEquals("  Rune platebody x 2: 200K", liveLines().get(1));

		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.setNotableDropThreshold(100_000);
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertEquals("the whip alchs for 72K: not notable in high alch mode", 2, sessionDrops().size());
		loot(ItemID.RUNE_PLATEBODY, 3);
		assertEquals(3, sessionDrops().size());
		assertEquals("values follow the setting", Arrays.asList("Notable drops:", "  Rune platebody x 3: 117K",
			"  Rune platebody x 2: 78K", "  Rune platebody: 39K"), liveLines());
	}

	@Test
	public void petMessageWhileRunningIsANotableDrop()
	{
		harness.loginAndSettle(ACCOUNT);
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		assertTrue(harness.play());
		harness.pause();
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		assertTrue("not counted while paused or idle", sessionDrops().isEmpty());

		assertTrue(harness.play());
		harness.chat(ChatMessageType.PUBLICCHAT, PET_TEXT);
		assertTrue("not a game message", sessionDrops().isEmpty());
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		harness.chat(ChatMessageType.GAMEMESSAGE,
			"You have a funny feeling like you would have been followed...");
		assertEquals(Arrays.asList("Notable drops:", "  Pet (already owned)", "  Pet"), liveLines());

		harness.stop();
		List<NotableDrop> drops = harness.onlyRecord(ACCOUNT).getNotableDrops();
		assertEquals(2, drops.size());
		assertEquals(NotableDrop.Pet.RECEIVED, drops.get(0).getPet());
		assertEquals(NotableDrop.Pet.DUPLICATE, drops.get(1).getPet());
	}

	@Test
	public void finalKillDropsDuringTheGraceWindowGoToTheCompletedTask()
	{
		harness.setTask(TASK, "Abyssal demons", 1, 50);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		loot(ItemID.ABYSSAL_WHIP, 1, ItemID.KONAR_KEY, 1);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(2, record.getNotableDrops().size());
		assertTrue(record.getNotableDrops().get(0).isPet());
		assertEquals(Integer.valueOf(ItemID.ABYSSAL_WHIP), record.getNotableDrops().get(1).getItemId());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.KONAR_KEY));
	}

	@Test
	public void activeSessionKeepsItsNotableDropsAcrossARestart()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.play());
		loot(ItemID.ABYSSAL_WHIP, 1, HARD_CLUE, 1);
		harness.logout();
		harness.shutDown();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertEquals(1, snapshot.getNotableDrops().size());
		assertEquals(Long.valueOf(1_500_000), snapshot.getNotableDrops().get(0).getGeValue());

		// Today's price has dropped; the drop keeps the value it had.
		harness.setGePrice(ItemID.ABYSSAL_WHIP, 1_000_000);
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals(Arrays.asList("Clues: 1 hard", "Notable drops:", "  Abyssal whip: 1.5M"), liveLines());

		assertTrue(harness.play());
		loot(ItemID.ABYSSAL_WHIP, 1);
		harness.stop();
		List<NotableDrop> drops = harness.onlyRecord(ACCOUNT).getNotableDrops();
		assertEquals(2, drops.size());
		assertEquals(Long.valueOf(1_500_000), drops.get(0).getGeValue());
		assertEquals(Long.valueOf(1_000_000), drops.get(1).getGeValue());
	}

	@Test
	public void olderRecordsStillLoadAndRecordsWithLootGainKeyCounts() throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		String json = "{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\",\"monster\":\"Kraken\","
			+ "\"creatureId\":42,\"initialAmount\":3,\"kills\":3,\"activeMillis\":60000,\"startedAt\":1000,"
			+ "\"endedAt\":61000,\"completed\":true,\"partial\":false},"
			+ "{\"schemaVersion\":2,\"id\":\"withLoot\",\"monster\":\"Kraken\",\"creatureId\":42,\"initialAmount\":3,"
			+ "\"kills\":3,\"activeMillis\":60000,\"startedAt\":2000,\"endedAt\":62000,\"completed\":true,"
			+ "\"partial\":false,\"loot\":{\"" + ItemID.KONAR_KEY + "\":1,\"995\":500}}]}";
		Files.write(harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json"), json.getBytes(StandardCharsets.UTF_8));

		harness.loginAndSettle(ACCOUNT);
		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		for (LedgerRecord r : records)
		{
			assertNull(r.getNotableDrops());
		}
		List<String> rows = historyText();
		assertEquals(2, rows.size());
		assertTrue("derived from the saved loot", rows.get(0).endsWith("<br>Deaths: -<br>Keys: 1 brimstone</html>"));
		assertTrue("unchanged", rows.get(1).endsWith("<br>Deaths: -</html>"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Task notes as wired in the plugin ({@link PluginHarness}): the panel's note box sets the live session's note on
 * the EDT, the note is saved on the record, kept across logout and a restart, and a saved record's note is rewritten
 * on the executor. {@link TaskNoteTest} and {@link SessionTrackerNoteTest} cover the rules.
 */
public class HarnessTaskNoteTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Wyrms", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Types a note in the panel's note box and commits it (Enter), on the EDT. */
	private void typeNote(String text)
	{
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			harness.ui().typeNote(text);
		});
		harness.drain();
	}

	/** The note box's text after a refresh, or {@code null} while it is hidden. */
	private String noteBox()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().isNoteShown() ? harness.ui().getNoteText() : null;
		});
		return text[0];
	}

	/** The panel's list of recent notes. */
	private List<String> recentNotes()
	{
		final AtomicReference<List<String>> recent = new AtomicReference<>();
		harness.onEdt(() -> recent.set(harness.ui().getRecentNotes()));
		return recent.get();
	}

	@Test
	public void noteSetWhileRunningIsSavedOnTheRecord()
	{
		assertNull("hidden without a session", noteBox());
		assertTrue(harness.play());
		assertEquals("", noteBox());
		typeNote("  Barrage   and  burst ");
		assertEquals("Barrage and burst", harness.tracker().getNote());
		assertEquals("shown as saved", "Barrage and burst", noteBox());

		harness.pause();
		typeNote("Prayer gear");
		assertEquals("Prayer gear", noteBox());
		harness.stop();
		assertNull("hidden once the session ended", noteBox());

		assertEquals("Prayer gear", harness.onlyRecord(ACCOUNT).getNote());
		assertEquals("offered first next time", "Prayer gear", recentNotes().get(0));

		assertTrue(harness.play());
		assertEquals("a new session starts without a note", "", noteBox());
	}

	@Test
	public void clearingTheNoteSavesNone()
	{
		assertTrue(harness.play());
		typeNote("Cannon");
		typeNote("   ");
		assertNull(harness.tracker().getNote());
		harness.stop();
		assertNull(harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void noteSurvivesLogoutAndARestart()
	{
		assertTrue(harness.play());
		typeNote("Range pray");
		harness.logout();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertNotNull(snapshot);
		assertEquals("Range pray", snapshot.getNote());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as paused", SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals("Range pray", harness.tracker().getNote());
		assertEquals("Range pray", noteBox());
		assertTrue(harness.play());
		harness.stop();
		assertEquals("Range pray", harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void noteKeptInMemoryAcrossARelogin()
	{
		assertTrue(harness.play());
		typeNote("Strength gear");
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals("Strength gear", noteBox());
	}

	@Test
	public void noteSetDuringTheCompletionGraceWindowIsSaved()
	{
		assertTrue(harness.play());
		final String sessionId = harness.tracker().getSessionId();
		harness.completeTask();
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		harness.onEdt(() -> harness.plugin.setSessionNote(ACCOUNT, sessionId, "Barrage"));
		harness.drain();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertFalse(harness.tracker().hasPendingCompletion());

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals("Barrage", record.getNote());
	}

	@Test
	public void noteSentAfterTheSessionWasSavedGoesToItsRecord()
	{
		assertTrue(harness.play());
		final String sessionId = harness.tracker().getSessionId();
		harness.completeTask();
		harness.ticks(1 + SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(sessionId, harness.onlyRecord(ACCOUNT).getId());

		harness.onEdt(() -> harness.plugin.setSessionNote(ACCOUNT, sessionId, " Cannon "));
		harness.drain();
		assertEquals("Cannon", harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void noteSentJustAsStopIsPressedReachesTheRecord()
	{
		assertTrue(harness.play());
		final String sessionId = harness.tracker().getSessionId();
		// Stop queues the record's save on the client thread; a note sent before that runs must still land on it.
		harness.onEdt(() ->
		{
			harness.plugin.stop();
			harness.plugin.setSessionNote(ACCOUNT, sessionId, "Barrage");
		});
		harness.drain();
		assertEquals("Barrage", harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void editingASavedRecordsNoteRewritesItAndClearingRemovesIt()
	{
		assertTrue(harness.play());
		typeNote("Cannon");
		harness.stop();
		final LedgerRecord saved = harness.onlyRecord(ACCOUNT);
		assertEquals("Cannon", saved.getNote());

		harness.onEdt(() -> harness.plugin.editRecordNote(ACCOUNT, saved.getId(), "  Burst\n"));
		harness.drain();
		LedgerRecord edited = harness.onlyRecord(ACCOUNT);
		assertEquals("Burst", edited.getNote());
		saved.setNote("Burst");
		assertEquals("only the note changes", saved, edited);
		assertEquals("the panel was refreshed", "Burst", recentNotes().get(0));

		harness.onEdt(() -> harness.plugin.editRecordNote(ACCOUNT, saved.getId(), ""));
		harness.drain();
		assertNull(harness.onlyRecord(ACCOUNT).getNote());
		assertEquals(TaskNote.DEFAULTS, recentNotes());
	}

	@Test
	public void editingANoteNeverTouchesTheActiveSession()
	{
		assertTrue(harness.play());
		typeNote("Cannon");
		harness.stop();
		final String savedId = harness.onlyRecord(ACCOUNT).getId();
		assertTrue(harness.play());
		typeNote("Barrage");

		harness.onEdt(() -> harness.plugin.editRecordNote(ACCOUNT, savedId, "Burst"));
		harness.drain();
		assertEquals("Burst", harness.onlyRecord(ACCOUNT).getNote());
		assertEquals("Barrage", harness.tracker().getNote());
		assertEquals("Barrage", noteBox());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.gameval.ItemID;
import org.junit.Rule;
import org.junit.Test;

/**
 * The current task's historical estimate as wired in the panel ({@link PluginHarness}): the History lines for
 * the kills left, the cache cleared by the "Loot price" mode and today's prices, and the time-left fallback until
 * the live pace is reliable. {@link TaskStatisticsTest} covers the averages.
 */
public class HarnessTaskStatisticsTest
{
	private static final long MINUTE = 60_000L;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The tracker's clock, so active time (and the live time-left estimate) is under the test's control. */
	private final AtomicLong now = new AtomicLong(1_000_000_000L);

	/**
	 * A completed task: 10 kills in 10 minutes, loot 100K GE / 200K high alch, supplies 10K; with its items
	 * ({@link SavedItems}).
	 */
	private static LedgerRecord prior()
	{
		LedgerRecord prior = new LedgerRecord();
		prior.setCreatureId(42);
		prior.setMonster("Abyssal demons");
		prior.setKills(10);
		prior.setActiveMillis(10 * MINUTE);
		prior.setCompleted(true);
		prior.setLootGeValue(100_000L);
		prior.setLootHaValue(200_000L);
		prior.setSuppliesGeValue(10_000L);
		return SavedItems.withItems(prior);
	}

	/** Starts the plugin on a task with {@code remaining} of {@code assigned} kills left and shows {@code prior}. */
	private void start(int remaining, int assigned, LedgerRecord prior)
	{
		SavedItems.define(harness);
		harness.startUp();
		useTestClock();
		harness.setTask(42, "Abyssal demons", remaining, assigned);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(prior)));
		// Today's prices of its items are looked up on the client thread and answered on the EDT.
		harness.drain();
	}

	/** Points the plugin's session tracker at {@link #now} (it reads the system clock otherwise). */
	private void useTestClock()
	{
		harness.setTrackerClock(now::get);
	}

	private String estimateText()
	{
		String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getHistoryEstimate().getText();
		});
		return text[0];
	}

	/** The History estimate's tooltip after a refresh. */
	private String estimateTooltip()
	{
		String[] tooltip = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			tooltip[0] = harness.ui().getHistoryEstimate().getTooltip();
		});
		return tooltip[0];
	}

	private String[] timeLeft()
	{
		String[] time = new String[2];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			time[0] = harness.ui().getTimeLeftText();
			time[1] = harness.ui().getTimeLeftTooltip();
		});
		return time;
	}

	@Test
	public void showsIdleAssignmentEstimateAndUsesHistoryForLiveTimeFallback()
	{
		start(10, 10, prior());

		String estimate = estimateText();
		assertNotNull(estimate);
		assertEquals("History (1 task) | 10 kills ~0:10:00 | Loot (GE): 100K | Supplies: 10K", estimate);
		String[] tooltip = new String[1];
		harness.onEdt(() -> tooltip[0] = harness.ui().getHistoryEstimate().getTooltip());
		assertTrue(tooltip[0], tooltip[0].contains("Average task duration"));

		assertTrue(harness.play());
		String[] time = timeLeft();
		assertEquals("Time left: ~10m", time[0]);
		assertTrue(time[1], time[1].contains("Historical estimate"));
		assertTrue(time[1], time[1].contains("after 3 kills and 1 minute"));
		assertEquals("still shown while running (owner decision)", "History (1 task) | 10 kills ~0:10:00 | "
			+ "Loot (GE): 100K | Supplies: 10K", estimateText());
	}

	@Test
	public void idleEstimateUsesTheKillsLeftNotTheAssignedSize()
	{
		// For example after a partial save at 3 of 10, or kills made before Play.
		start(7, 10, prior());

		assertEquals("History (1 task) | 7 kills ~0:07:00 | Loot (GE): 70K | Supplies: 7,000", estimateText());
	}

	@Test
	public void theEstimateIsAtTodaysPricesInTheLootPriceMode()
	{
		// Saved at 2,000 gp a bone; 3,000 gp today.
		harness.defineItem(ItemID.DRAGON_BONES, "Dragon bones", 3_000, 5_000);
		LedgerRecord prior = prior();
		prior.setLoot(Collections.singletonMap(ItemID.DRAGON_BONES, 10L));
		prior.setUnitGePrices(Collections.singletonMap(ItemID.DRAGON_BONES, 2_000L));
		prior.setUnitHaPrices(Collections.singletonMap(ItemID.DRAGON_BONES, 5_000L));
		prior.setLootGeValue(20_000L);
		prior.setLootHaValue(50_000L);
		// No supplies used: supplies are revalued from the (empty) tally, as in the history.
		prior.setSupplies(null);
		prior.setSuppliesGeValue(0L);
		start(10, 10, prior);
		// The lookup is queued for the client thread, and its answer for the EDT.
		harness.drain();
		assertEquals("History (1 task) | 10 kills ~0:10:00 | Loot (GE): 30K | Supplies: 0", estimateText());
		String[] tooltip = new String[1];
		harness.onEdt(() -> tooltip[0] = harness.ui().getHistoryEstimate().getTooltip());
		assertTrue(tooltip[0], tooltip[0].contains("GP averages use today's prices in GE mode"));
		assertFalse(tooltip[0], tooltip[0].contains("saved prices"));

		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		assertEquals("History (1 task) | 10 kills ~0:10:00 | Loot (HA): 50K | Supplies: 0", estimateText());
	}

	@Test
	public void theTooltipShowsProfitPerKillUnderLootAndSupplies()
	{
		start(10, 10, prior());
		assertTrue(estimateTooltip(), estimateTooltip().contains("<br>Loot per kill: 10K gp"
			+ "<br>Supplies per kill: 1,000 gp<br>Profit per kill: 9,000 gp<br>"));

		// Loot at the Loot price setting, supplies at GE.
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		assertTrue(estimateTooltip(), estimateTooltip().contains("<br>Profit per kill: 19K gp<br>"));
	}

	@Test
	public void profitPerKillIsApproximateALossOrUnknownLikeItsParts()
	{
		// Saved with its totals only, with a supply price unavailable: no loot, supplies marked ~.
		LedgerRecord prior = prior();
		prior.setLoot(null);
		prior.setSupplies(null);
		prior.setUnitGePrices(null);
		prior.setUnitHaPrices(null);
		prior.setLootGeValue(0L);
		prior.setSuppliesUnpricedItems(1);
		start(10, 10, prior);
		assertTrue(estimateTooltip(), estimateTooltip().contains("<br>Loot per kill: 0 gp"
			+ "<br>Supplies per kill: ~1,000 gp<br>Profit per kill: ~-1,000 gp<br>"));

		// A task saved before values were tracked: no GP averages at all.
		LedgerRecord legacy = prior();
		legacy.setLootGeValue(null);
		legacy.setLootHaValue(null);
		legacy.setSuppliesGeValue(null);
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT,
			Collections.singletonList(legacy)));
		harness.drain();
		assertTrue(estimateTooltip(), estimateTooltip().contains("<br>Loot per kill: -<br>Supplies per kill: -"
			+ "<br>Profit per kill: -<br>"));
	}

	@Test
	public void livePaceTakesOverAfterThreeKillsAndOneMinute()
	{
		start(10, 10, prior());
		assertTrue(harness.play());
		assertEquals("Time left: ~10m", timeLeft()[0]);

		// 3 kills in 30 seconds: not yet a minute of active time, so still the history (1 minute a kill, 7 left).
		now.addAndGet(MINUTE / 2);
		harness.setRemaining(7);
		harness.tick();
		String[] time = timeLeft();
		assertEquals("Time left: ~7m", time[0]);
		assertTrue(time[1], time[1].contains("Historical estimate"));
		assertEquals("History (1 task) | 7 kills ~0:07:00 | Loot (GE): 70K | Supplies: 7,000", estimateText());

		// 3 kills in 90 seconds: 30 seconds a kill, 7 left.
		now.addAndGet(MINUTE);
		harness.tick();
		time = timeLeft();
		assertEquals("3m 30s rounds half up", "Time left: ~4m", time[0]);
		assertTrue(time[1], time[1].contains("Kills per hour"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.ui.overlay.Overlay;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * The "not tracking" nudge: a task kill while idle or paused shows an overlay row (idle only) and posts one chat
 * line per assignment. {@link TrackingNudgeTest} covers the rules, {@link OverlayRowsTest} the row.
 */
public class HarnessTrackingNudgeTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final String IDLE_LINE =
		"Kill not counted: Slayer Ledger isn't tracking. Press Play in the sidebar.";
	private static final String PAUSED_LINE =
		"Kill not counted: Slayer Ledger is paused. Press Resume in the sidebar.";
	/** The line after a hop paused a running session. */
	private static final String AUTO_PAUSE_LINE = "Slayer Ledger paused (world hop). Press Resume to keep tracking.";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 12, 12);
		harness.loginAndSettle(ACCOUNT);
	}

	/** The nudge lines queued so far (other chat lines, such as a new-task preview, are left out). */
	private List<QueuedMessage> nudgeLines()
	{
		ArgumentCaptor<QueuedMessage> messages = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, atLeast(0)).queue(messages.capture());
		List<QueuedMessage> lines = new ArrayList<>();
		for (QueuedMessage message : messages.getAllValues())
		{
			String text = message.getRuneLiteFormattedMessage();
			if (IDLE_LINE.equals(text) || PAUSED_LINE.equals(text))
			{
				lines.add(message);
			}
		}
		return lines;
	}

	/** Every chat line queued so far, in order. */
	private List<String> allLines()
	{
		ArgumentCaptor<QueuedMessage> messages = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, atLeast(0)).queue(messages.capture());
		List<String> lines = new ArrayList<>();
		for (QueuedMessage message : messages.getAllValues())
		{
			lines.add(message.getRuneLiteFormattedMessage());
		}
		return lines;
	}

	/** The overlay's rows now, with every row setting on. */
	private List<OverlayRows.Row> rows()
	{
		return OverlayRows.rows(harness.overlayData(), true, true, true, true);
	}

	private boolean showsNotTracking()
	{
		for (OverlayRows.Row row : rows())
		{
			if (OverlayRows.NOT_TRACKING_LABEL.equals(row.getLabel()))
			{
				assertTrue(row.isWarning());
				return true;
			}
		}
		return false;
	}

	private int warningRows()
	{
		int n = 0;
		for (OverlayRows.Row row : rows())
		{
			n += row.isWarning() ? 1 : 0;
		}
		return n;
	}

	private void kill(int remaining)
	{
		harness.setRemaining(remaining);
		harness.tick();
	}

	@Test
	public void idleKillShowsTheRowAndOneChatLine()
	{
		assertFalse("nothing before a kill", showsNotTracking());
		assertNull("the overlay is hidden while idle without a nudge", harness.overlayData());

		kill(11);
		assertTrue(showsNotTracking());
		assertEquals(1, rows().size());
		List<QueuedMessage> lines = nudgeLines();
		assertEquals(1, lines.size());
		assertEquals(IDLE_LINE, lines.get(0).getRuneLiteFormattedMessage());
		assertEquals(ChatMessageType.CONSOLE, lines.get(0).getType());
		assertEquals("Slayer Ledger", lines.get(0).getName());

		kill(10);
		kill(9);
		harness.ticks(3);
		assertEquals("one line per task, not per kill", 1, nudgeLines().size());
		assertTrue(showsNotTracking());
		assertEquals("only informs", SessionTracker.State.IDLE, harness.sessionState());
	}

	@Test
	public void playClearsTheRow()
	{
		kill(11);
		assertTrue(showsNotTracking());

		assertTrue(harness.play());
		assertFalse("gone as soon as Play is pressed", showsNotTracking());
		kill(10);
		assertFalse(showsNotTracking());
		assertEquals(1, nudgeLines().size());

		// Stopped again: another untracked kill shows the row again, still without a second line.
		harness.stop();
		assertFalse(showsNotTracking());
		kill(9);
		assertTrue(showsNotTracking());
		assertEquals(1, nudgeLines().size());
	}

	@Test
	public void pausedKillPostsOnePausedLineAndNoSecondWarningRow()
	{
		assertTrue(harness.play());
		kill(11);
		harness.pause();

		kill(10);
		List<QueuedMessage> lines = nudgeLines();
		assertEquals(1, lines.size());
		assertEquals(PAUSED_LINE, lines.get(0).getRuneLiteFormattedMessage());
		assertEquals("only the Paused row warns", 1, warningRows());
		assertEquals(OverlayRows.PAUSED_LABEL, rows().get(0).getLabel());
		assertFalse(showsNotTracking());

		kill(9);
		assertEquals(1, nudgeLines().size());
		assertEquals("resume stays manual", SessionTracker.State.PAUSED, harness.sessionState());
	}

	@Test
	public void runningSessionNeverNudges()
	{
		assertTrue(harness.play());
		kill(11);
		kill(10);
		assertFalse(showsNotTracking());
		assertEquals(0, nudgeLines().size());
	}

	@Test
	public void completingKillNeverNudges()
	{
		kill(1);
		assertEquals(1, nudgeLines().size());
		harness.setTask(43, "Black demons", 1, 30);
		harness.tick();
		assertFalse("a new assignment clears the row", showsNotTracking());

		// The final kill of the new task, while idle: the completion, not a nudge.
		harness.completeTask();
		harness.ticks(3);
		assertEquals(1, nudgeLines().size());
		assertFalse(showsNotTracking());
	}

	@Test
	public void completingKillOfARunningSessionNeverNudges()
	{
		assertTrue(harness.play());
		kill(1);
		harness.completeTask();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 2);
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());
		assertEquals(0, nudgeLines().size());
		assertFalse(showsNotTracking());
	}

	@Test
	public void newAssignmentCanNudgeAgain()
	{
		kill(11);
		assertEquals(1, nudgeLines().size());

		harness.completeTask();
		harness.ticks(3);
		harness.setTask(43, "Black demons", 30, 30);
		harness.tick();
		assertEquals("a new assignment is not a kill", 1, nudgeLines().size());
		assertFalse(showsNotTracking());

		kill(29);
		assertEquals(2, nudgeLines().size());
		assertTrue(showsNotTracking());
	}

	@Test
	public void sameAssignmentIsNotNudgedAgainAfterAHopOrRelogin()
	{
		kill(11);
		assertEquals(1, nudgeLines().size());

		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		kill(10);
		assertEquals(1, nudgeLines().size());
		assertTrue(showsNotTracking());

		harness.logout();
		assertNull("hidden at the login screen", harness.overlayData());
		harness.loginAndSettle(ACCOUNT);
		assertFalse(showsNotTracking());
		kill(9);
		assertEquals(1, nudgeLines().size());
		assertTrue("the row comes back on the next untracked kill", showsNotTracking());
	}

	@Test
	public void hopAutoPauseThenAKillPostsTheAutoPauseLineAndOnePausedLine()
	{
		assertTrue(harness.play());
		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals(Collections.singletonList(AUTO_PAUSE_LINE), allLines());

		kill(11);
		kill(10);
		harness.ticks(3);
		assertEquals(Arrays.asList(AUTO_PAUSE_LINE, PAUSED_LINE), allLines());
		assertEquals("only the Paused row warns", 1, warningRows());
		assertEquals("resume stays manual", SessionTracker.State.PAUSED, harness.sessionState());
	}

	@Test
	public void aKillOnTheFirstSettledTickAfterReloginWithARestoreCheckPendingPostsNothing()
	{
		harness.logout();
		harness.login(ACCOUNT);
		harness.ticks(PluginHarness.SETTLE_TICKS - 1);
		// The first settled tick: the restore check for this account starts on it, and the count went down since login.
		harness.setRemaining(11);
		harness.tick();
		assertEquals(Collections.emptyList(), allLines());
		assertFalse(showsNotTracking());
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());

		// The check is done (no session to restore): the next kill nudges.
		kill(10);
		assertEquals(Collections.singletonList(IDLE_LINE), allLines());
		assertTrue(showsNotTracking());
	}

	@Test
	public void aPluginRestartHidesTheRowButKeepsTheAssignment()
	{
		kill(11);
		assertTrue(showsNotTracking());

		harness.shutDown();
		harness.startUpWithoutDrain();
		assertNull("no row before the start's client-thread block has run", harness.overlayData());
		harness.drain();
		assertNull("no row from before the restart", harness.overlayData());
		harness.ticks(PluginHarness.SETTLE_TICKS + 2);
		assertNull(harness.overlayData());

		kill(10);
		assertTrue("the next untracked kill shows it again", showsNotTracking());
		assertEquals("the assignment was already nudged", 1, nudgeLines().size());
	}

	@Test
	public void overlaySettingOffHidesTheRowButNotTheLine()
	{
		harness.config.showTaskOverlay = false;
		kill(11);
		assertEquals(1, nudgeLines().size());
		assertNull("the overlay draws nothing", render());
		harness.config.showTaskOverlay = true;
		assertNotNull(render());
	}

	private java.awt.Dimension render()
	{
		ArgumentCaptor<Overlay> overlay = ArgumentCaptor.forClass(Overlay.class);
		verify(harness.overlayManager, times(1)).add(overlay.capture());
		BufferedImage image = new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			return overlay.getValue().render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}
}

