			state[1] = trends().isMonsterChoiceShown();
			view[0] = trends().getView();
		});
		assertFalse(state[0]);
		assertFalse("the Monster choice is the chart's", state[1]);
		assertEquals(TrendsSection.View.LIST, view[0]);

		String[][] rows = new String[3][];
