		// The list is worked out off the EDT: each read waits for it (rows() drains).
		harness.onEdt(() -> trends().clickTitle());
		rows[0] = rows().toArray(new String[0]);
		labels[0] = metricText();
		harness.onEdt(() -> trends().setMetric(TaskRanking.Metric.XP));
