		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 50_000, 20);
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		LedgerRecord first = chartRecord(42, "Abyssal demons", Instant.parse("2025-01-15T12:00:00Z").toEpochMilli());
		first.setId("first");
		first.setLoot(Collections.singletonMap(ItemID.DRAGON_BONES, 10L));
		first.setLootGeValue(20_000L);
		first.setLootHaValue(50_000L);
		first.setSuppliesGeValue(0L);
		LedgerRecord second = chartRecord(42, "Abyssal demons", Instant.parse("2025-01-16T12:00:00Z").toEpochMilli());
		second.setId("second");
		second.setLoot(Collections.singletonMap(ItemID.RANARR_SEED, 1L));
		second.setLootGeValue(40_000L);
		second.setLootHaValue(20L);
		second.setSuppliesGeValue(0L);
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(first)));
		harness.drain();
		harness.onEdt(() ->
		{
			trends().clickTitle();
			trends().clickView(TrendsSection.View.CHART);
		});
		assertEquals(1, pointCount());

		int[] before = new int[1];
		harness.onEdt(() ->
		{
			SlayerLedgerPanel panel = harness.panel();
			before[0] = trends().getBuildCount();
			// The lookup is queued for the client thread, so it cannot answer inside this EDT task.
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Arrays.asList(first, second));
			panel.refresh();
			assertTrue(harness.historyModel().isWaitingForCurrentPrices());
			assertEquals("the previous chart stays", before[0], trends().getBuildCount());
			assertEquals(1, trends().getPointCount());
		});

		harness.drain();
		harness.onEdt(() ->
		{
			assertFalse(harness.historyModel().isWaitingForCurrentPrices());
			assertEquals("redrawn once", before[0] + 1, trends().getBuildCount());
			assertEquals(2, trends().getPointCount());
		});
	}

	private PanelProbe.TrendsProbe trends()
	{
		return harness.ui().getTrends();
	}

	// The reads below drain first: the list and the chart are worked out off the EDT.

	private List<String> rows()
	{
		@SuppressWarnings("unchecked")
		List<String>[] rows = new List[1];
		harness.drain();
		harness.onEdt(() -> rows[0] = trends().getRows());
		return rows[0];
	}

	private List<String> tooltips()
	{
		@SuppressWarnings("unchecked")
		List<String>[] tooltips = new List[1];
		harness.drain();
		harness.onEdt(() -> tooltips[0] = trends().getTooltips());
		return tooltips[0];
	}

	private String metricText()
	{
		String[] text = new String[1];
		harness.drain();
		harness.onEdt(() -> text[0] = trends().getMetricText());
		return text[0];
	}

	private int pointCount()
	{
		int[] count = new int[1];
		harness.drain();
		harness.onEdt(() -> count[0] = trends().getPointCount());
		return count[0];
	}

	/** Paints the chart at a fixed size and returns the tooltip of its single point, in the middle. */
	private String tooltip()
	{
		String[] tooltip = new String[1];
		harness.drain();
		harness.onEdt(() ->
		{
			TaskTrendChartView chart = trends().getChart();
			chart.setSize(240, 150);
			BufferedImage image = new BufferedImage(240, 150, BufferedImage.TYPE_INT_ARGB);
			Graphics2D graphics = image.createGraphics();
			chart.paint(graphics);
			graphics.dispose();
			tooltip[0] = chart.getToolTipText(new MouseEvent(chart, MouseEvent.MOUSE_MOVED,
				System.currentTimeMillis(), 0, 143, 67, 0, false));
		});
		return tooltip[0];
	}

	/** A completed task that tracked the whole assignment, without a completion date. */
	private static LedgerRecord rankingRecord(int creatureId, String monster, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setKills(10);
		record.setInitialAmount(10);
		record.setOriginalAmount(10);
		record.setActiveMillis(activeMillis);
		record.setCompleted(true);
		return record;
	}

	/** A completed hour-long task that ended at {@code endedAt}. */
	private static LedgerRecord chartRecord(int creatureId, String monster, long endedAt)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setEndedAt(endedAt);
		record.setKills(10);
		record.setActiveMillis(60 * 60 * 1000L);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * XP gained per task as wired in the plugin ({@link PluginHarness}): read once per settled tick before the task
 * is observed, counted only while RUNNING, never from a login's stats, and kept through logout and a restart.
 * {@link SessionTrackerXpTest} covers the tracker's rules.
 */
public class HarnessXpTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.setSkillXp(Skill.SLAYER, 1_000_000);
		harness.setSkillXp(Skill.HITPOINTS, 2_000_000);
		harness.setSkillXp(Skill.MAGIC, 3_000_000);
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 100, 100);
		harness.loginAndSettle(ACCOUNT);
	}

	private static Map<String, Long> xp(Object... skillAndXp)
	{
		Map<String, Long> map = new TreeMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], ((Number) skillAndXp[i + 1]).longValue());
		}
		return map;
	}

	@Test
	public void xpIsCountedOnlyWhileRunning()
	{
		harness.gainXp(Skill.SLAYER, 500);
		harness.tick();
		assertTrue(harness.play());
		harness.gainXp(Skill.SLAYER, 120);
		harness.gainXp(Skill.MAGIC, 300);
		harness.tick();
		harness.pause();
		harness.gainXp(Skill.SLAYER, 9_999);
		harness.ticks(2);
		assertTrue("resume", harness.play());
		harness.gainXp(Skill.HITPOINTS, 40);
		harness.tick();
		harness.stop();

		assertEquals(xp("SLAYER", 120, "MAGIC", 300, "HITPOINTS", 40), harness.onlyRecord(ACCOUNT).getXpGained());
	}

	@Test
	public void aReconnectsStatBurstIsNotCounted()
	{
		assertTrue(harness.play());
		harness.gainXp(Skill.SLAYER, 100);
		harness.tick();
		// A lost connection doesn't pause the session. The stats read 0 until the login re-sends them, then jump.
		harness.setGameState(GameState.CONNECTION_LOST);
		harness.clearSkillXp();
		harness.setGameState(GameState.LOGGED_IN);
		harness.tick();
		harness.setSkillXp(Skill.SLAYER, 1_000_200);
		harness.setSkillXp(Skill.HITPOINTS, 2_000_000);
		harness.setSkillXp(Skill.MAGIC, 3_000_000);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		harness.gainXp(Skill.SLAYER, 7);
		harness.tick();
		harness.stop();

		assertEquals(xp("SLAYER", 107), harness.onlyRecord(ACCOUNT).getXpGained());
	}

	@Test
	public void aHopIsNeverAGain()
	{
		assertTrue(harness.play());
		harness.gainXp(Skill.SLAYER, 10);
		harness.tick();
		harness.hop();
		harness.gainXp(Skill.SLAYER, 50_000);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertTrue("resume after the hop", harness.play());
		harness.gainXp(Skill.SLAYER, 5);
		harness.tick();
		harness.stop();

		assertEquals(xp("SLAYER", 15), harness.onlyRecord(ACCOUNT).getXpGained());
	}

	@Test
	public void anotherAccountsStatsAreNotCounted()
	{
		assertTrue(harness.play());
		harness.gainXp(Skill.SLAYER, 10);
		harness.tick();
		harness.logout();
		// The other account has more XP in every skill: a naive diff would count all of it.
		harness.setSkillXp(Skill.SLAYER, 5_000_000);
		harness.setSkillXp(Skill.HITPOINTS, 9_000_000);
		harness.setSkillXp(Skill.MAGIC, 9_000_000);
		harness.loginAndSettle(ACCOUNT + 1);
		assertTrue(harness.play());
		harness.gainXp(Skill.MAGIC, 3);
		harness.tick();
		harness.stop();

		assertEquals(xp("MAGIC", 3), harness.onlyRecord(ACCOUNT + 1).getXpGained());
		SessionSnapshot first = harness.activeSession(ACCOUNT);
		assertNotNull("the first account's session is persisted", first);
		assertEquals(xp("SLAYER", 10), first.getXpGained());
	}

	@Test
	public void theCompletionTickCountsAndTheGraceWindowDoesNot()
	{
		harness.setRemaining(1);
		harness.tick();
		assertTrue(harness.play());
		harness.tick();
		harness.completeTask();
		harness.gainXp(Skill.SLAYER, 300);
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		harness.gainXp(Skill.SLAYER, 999);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(xp("SLAYER", 300), record.getXpGained());
	}

	@Test
	public void xpSurvivesLogoutAndARestart()
	{
		assertTrue(harness.play());
		harness.gainXp(Skill.SLAYER, 400);
		harness.tick();
		harness.logout();
		assertEquals(xp("SLAYER", 400), harness.activeSession(ACCOUNT).getXpGained());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as paused", SessionTracker.State.PAUSED, harness.sessionState());
		assertEquals(xp("SLAYER", 400), harness.tracker().getXpGained());
		assertTrue(harness.play());
		harness.gainXp(Skill.SLAYER, 100);
		harness.tick();
		harness.stop();

		assertEquals(xp("SLAYER", 500), harness.onlyRecord(ACCOUNT).getXpGained());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void panelShowsTheLiveXpAndTheSavedTasksXp()
	{
		assertTrue(harness.play());
		harness.gainXp(Skill.SLAYER, 1_500);
		harness.gainXp(Skill.HITPOINTS, 500);
		harness.tick();
		final String[] live = new String[3];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			live[0] = harness.ui().getXpText();
			harness.ui().getLiveXp().toggle();
			live[1] = String.join(" / ", harness.ui().getLiveXp().getLineTexts());
			live[2] = String.join(" / ", harness.ui().getLiveXp().getLineIcons());
		});
		assertEquals("XP: 2,000", live[0]);
		assertEquals("Slayer | 1,500 / Hitpoints | 500", live[1]);
		// Each line has its skill's small icon from SkillIconManager, asked for on the EDT.
		assertEquals("skill SLAYER 18x16 / skill HITPOINTS 18x16", live[2]);

		harness.stop();
		final Object[] saved = new Object[2];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			saved[0] = harness.ui().getXpText();
			saved[1] = harness.ui().getHistory().getXpText();
			harness.ui().getHistory().clickRow(0);
		});
		harness.drain();
		final Object[] details = new Object[2];
		harness.onEdt(() ->
		{
			details[0] = harness.ui().getHistory().getDetailsText(0);
			details[1] = harness.ui().getHistory().getDetailsXpIcons(0);
		});
		assertNull("hidden once the session ended", saved[0]);
		assertEquals(Arrays.asList("XP: 2,000 | "), saved[1]);
		String text = details[0].toString();
		assertTrue(text, text.contains("XP gained (2), Slayer | 1,500, Hitpoints | 500"));
		assertEquals(Arrays.asList("skill SLAYER 18x16", "skill HITPOINTS 18x16"), details[1]);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Loot Ground Items hides is left out of the loot value: saved tasks ({@link HistoryPricing}) and everything
 * built on them (Trends, Overall totals, the chart, the statistics, the chat line), and the live session
 * ({@link SessionValuation}). The records themselves are never changed, so with nothing hidden the values come back.
 */
public class HiddenLootValuationTest
{
	private static final int RUNE = 1;
	private static final int BONES = 2;
	private static final int UNPRICED = 3;
	private static final int POTION = 4;
	private static final HiddenLoot HIDE_BONES = HiddenLoot.of(Collections.singleton(BONES));

	private static Map<Integer, Long> map(long... idValue)
	{
		Map<Integer, Long> map = new HashMap<>();
		for (int i = 0; i < idValue.length; i += 2)
		{
			map.put((int) idValue[i], idValue[i + 1]);
		}
		return map;
	}

	/**
	 * A completed hour-long task: loot 2 runes (GE 100, HA 60), 10 bones (GE 50, HA 5) and an item without a GE price
	 * (HA 300); supplies 600 gp. Totals as {@link LedgerRecord#captureValues} saves them.
	 */
	private static LedgerRecord record()
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("a");
		r.setMonster("Kurask");
		r.setCreatureId(410);
		r.setKills(10);
		r.setActiveMillis(3_600_000L);
		r.setStartedAt(1_000L);
		r.setEndedAt(3_601_000L);
		r.setCompleted(true);
		r.setPartial(false);
		r.setLoot(map(RUNE, 2, BONES, 10, UNPRICED, 1));
		r.setSupplies(map(POTION, 3));
		r.setSupplyDoses(Collections.singletonMap(POTION, 4));
		r.setUnitGePrices(map(RUNE, 100, BONES, 50, POTION, 800));
		r.setUnitHaPrices(map(RUNE, 60, BONES, 5, UNPRICED, 300, POTION, 100));
		r.setLootGeValue(700L);
		r.setLootHaValue(470L);
		r.setSuppliesGeValue(600L);
		r.setSuppliesHaValue(75L);
		r.setLootUnpricedItems(1);
		return r;
	}

	@Test
	public void savedPricesLeaveHiddenItemsOutOfLootAndProfit()
	{
		HistoryPricing.Values all = HistoryPricing.value(record(), LootPriceMode.GE, null, HiddenLoot.NONE);
		HistoryPricing.Values hidden = HistoryPricing.value(record(), LootPriceMode.GE, null, HIDE_BONES);
		assertEquals(Long.valueOf(700), all.getLootValue());
		assertEquals("10 bones at 50 gp left out", Long.valueOf(200), hidden.getLootValue());
		assertEquals(Long.valueOf(200), hidden.getLootGe());
		assertEquals("high alch too", Long.valueOf(420), hidden.getLootHa());
		assertEquals("supplies unchanged", all.getSuppliesGe(), hidden.getSuppliesGe());
		assertEquals(Long.valueOf(-400), hidden.getProfit());
		assertTrue("the unpriced item still counts", hidden.isLootApproximate());

		HistoryPricing.Values ha = HistoryPricing.value(record(), LootPriceMode.HIGH_ALCH, null, HIDE_BONES);
		assertEquals(Long.valueOf(420), ha.getLootValue());
		assertEquals(Long.valueOf(-180), ha.getProfit());
	}

	@Test
	public void aHiddenUnpricedItemNoLongerMakesTheValueApproximate()
	{
		HistoryPricing.Values v = HistoryPricing.value(record(), LootPriceMode.GE, null,
			HiddenLoot.of(Collections.singleton(UNPRICED)));
		assertEquals(Long.valueOf(700), v.getLootValue());
		assertFalse(v.isLootApproximate());
		assertEquals(Long.valueOf(470 - 300), v.getLootHa());
	}

	@Test
	public void todaysPricesLeaveHiddenItemsOutToo()
	{
		Map<Integer, Long> today = map(RUNE, 150, BONES, 80, POTION, 800);
		assertEquals(Long.valueOf(300 + 800), HistoryPricing.value(record(), LootPriceMode.GE, today,
			HiddenLoot.NONE).getLootValue());
		assertEquals(Long.valueOf(300), HistoryPricing.value(record(), LootPriceMode.GE, today, HIDE_BONES)
			.getLootValue());
	}

	@Test
	public void todaysPricesInHighAlchLeaveHiddenItemsOutOfTheLootNotTheSupplies()
	{
		Map<Integer, Long> today = map(RUNE, 150, BONES, 80, POTION, 1_600);
		HistoryPricing.Values ha = HistoryPricing.value(record(), LootPriceMode.HIGH_ALCH, today, HIDE_BONES);
		assertEquals("2 runes at 60 and the 300 item; the bones (5 each) left out", Long.valueOf(420),
			ha.getLootValue());
		assertEquals("3 doses of a 1,600 gp 4-dose potion, today", Long.valueOf(1_200), ha.getSuppliesGe());
		assertEquals(Long.valueOf(420 - 1_200), ha.getProfit());
		assertEquals(Long.valueOf(470), HistoryPricing.value(record(), LootPriceMode.HIGH_ALCH, today,
			HiddenLoot.NONE).getLootValue());
	}

	@Test
	public void aRecordWithoutUnitPricesLeavesHiddenItemsOutOnlyAtGe()
	{
		LedgerRecord old = record();
		old.setUnitGePrices(null);
		old.setUnitHaPrices(null);
		HistoryPricing.Values v = HistoryPricing.value(old, LootPriceMode.GE, null, HIDE_BONES);
		assertEquals("at saved prices, nothing per item to leave out", Long.valueOf(700), v.getLootValue());
		assertEquals(Long.valueOf(470), v.getLootHa());

		// At today's prices its items are valued, so the bones are left out of the GE value; its high alch
		// value is its saved total, hidden items included.
		HistoryPricing.Values today = HistoryPricing.value(old, LootPriceMode.GE, map(RUNE, 150, BONES, 80),
			HIDE_BONES);
		assertEquals("2 runes at 150; the unpriced item left out and marked", Long.valueOf(300), today.getLootValue());
		assertFalse(today.isSavedTotals());
		assertTrue(today.isLootApproximate());
		assertEquals(Long.valueOf(470), today.getLootHa());

		// Saved without items: its saved totals, hidden items included, marked ~.
		old.setLoot(null);
		old.setSupplies(null);
		HistoryPricing.Values totals = HistoryPricing.value(old, LootPriceMode.GE, map(RUNE, 150, BONES, 80),
			HIDE_BONES);
		assertEquals(Long.valueOf(700), totals.getLootValue());
		assertTrue(totals.isSavedTotals());
		assertTrue(totals.isLootApproximate());
	}

	@Test
	public void nothingHiddenIsTheValueAsBefore()
	{
		for (LootPriceMode mode : LootPriceMode.values())
		{
			HistoryPricing.Values before = HistoryPricing.value(record(), mode, null);
			HistoryPricing.Values none = HistoryPricing.value(record(), mode, null, HiddenLoot.NONE);
			HistoryPricing.Values other = HistoryPricing.value(record(), mode, null,
				HiddenLoot.of(Collections.singleton(995)));
			for (HistoryPricing.Values v : new HistoryPricing.Values[]{none, other})
			{
				assertEquals(before.getLootValue(), v.getLootValue());
				assertEquals(before.getLootHa(), v.getLootHa());
				assertEquals(before.getLootUnpriced(), v.getLootUnpriced());
				assertEquals(before.getLootGeUnpriced(), v.getLootGeUnpriced());
			}
		}
		LedgerRecord record = record();
		HistoryPricing.value(record, LootPriceMode.GE, null, HIDE_BONES);
		assertEquals("the record is not changed", Long.valueOf(10), record.getLoot().get(BONES));
	}

	@Test
	public void trendsTotalsChartAndStatisticsDropByTheHiddenValue()
	{
		List<LedgerRecord> records = Collections.singletonList(record());
		// Today's prices are the ones the task was saved with.
		Map<Integer, Long> saved = map(RUNE, 100, BONES, 50, POTION, 800);

		List<TaskRanking.Entry> ranking = TaskRanking.rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE, saved,
			HIDE_BONES);
		assertEquals("profit/h: 200 - 600 over an hour", Long.valueOf(-400), ranking.get(0).getRatePerHour());
		assertEquals(Long.valueOf(100), TaskRanking.rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE, saved)
			.get(0).getRatePerHour());

		List<OverallTotals.Entry> totals = OverallTotals.summarize(records, OverallTotals.Grouping.ALL,
			LootPriceMode.GE, saved, HIDE_BONES, ZoneOffset.UTC);
		assertEquals(Long.valueOf(-400), totals.get(0).getProfit());
		assertEquals("the summed loot items still list the bones (the grid leaves them out)", 3,
			totals.get(0).getLoot().size());
		assertEquals(Long.valueOf(100), OverallTotals.summarize(records, OverallTotals.Grouping.ALL,
			LootPriceMode.GE, saved, HiddenLoot.NONE, ZoneOffset.UTC).get(0).getProfit());

		List<TaskChart.Monster> monsters = TaskChart.monsters(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			saved, HIDE_BONES);
		assertEquals(-400, TaskChart.points(records, monsters.get(0), TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			saved, HIDE_BONES).get(0).getRatePerHour());

		TaskStatistics stats = TaskStatistics.forTask(records, 410, "Kurask", null, r -> null, LootPriceMode.GE,
			saved, HIDE_BONES);
		assertEquals("loot per kill", Long.valueOf(20), stats.getLootPerKill());
		assertEquals(Long.valueOf(70), TaskStatistics.forTask(records, 410, "Kurask", LootPriceMode.GE, saved)
			.getLootPerKill());

		TaskAdvisor.Result advice = TaskAdvisor.advise(records, 410, "Kurask", TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, saved, HIDE_BONES);
		assertEquals("one monster is not enough to advise on", null, advice);
	}

	// ---- Coins always count in the value (owner decision, 2026-10-28) ----

	private static final int COINS = ItemValuation.COINS;
	/** Coins and bones hidden, as Ground Items' built-in list hides them. */
	private static final HiddenLoot HIDE_COINS_AND_BONES = HiddenLoot.of(Arrays.asList(COINS, BONES));

	/** {@link #record()} with 500 coins more in the loot, priced at face value as {@link ItemValuation} saves them. */
	private static LedgerRecord recordWithCoins()
	{
		LedgerRecord r = record();
		r.setLoot(map(RUNE, 2, BONES, 10, UNPRICED, 1, COINS, 500));
		r.setUnitGePrices(map(RUNE, 100, BONES, 50, POTION, 800, COINS, 1));
		r.setUnitHaPrices(map(RUNE, 60, BONES, 5, UNPRICED, 300, POTION, 100, COINS, 1));
		r.setLootGeValue(1_200L);
		r.setLootHaValue(970L);
		return r;
	}

	@Test
	public void hiddenCoinsStillCountInSavedTasksValues()
	{
		HistoryPricing.Values ge = HistoryPricing.value(recordWithCoins(), LootPriceMode.GE, null,
			HIDE_COINS_AND_BONES);
		assertEquals("only the 10 bones at 50 gp are left out", Long.valueOf(1_200 - 500), ge.getLootValue());
		assertEquals(Long.valueOf(970 - 50), ge.getLootHa());
		assertEquals(Long.valueOf(700 - 600), ge.getProfit());

		HistoryPricing.Values ha = HistoryPricing.value(recordWithCoins(), LootPriceMode.HIGH_ALCH, null,
			HIDE_COINS_AND_BONES);
		assertEquals(Long.valueOf(920), ha.getLootValue());

		HistoryPricing.Values coinsOnly = HistoryPricing.value(recordWithCoins(), LootPriceMode.GE, null,
			HiddenLoot.of(Collections.singleton(COINS)));
		assertEquals("hidden coins alone change no value", Long.valueOf(1_200), coinsOnly.getLootValue());
		assertEquals(Long.valueOf(970), coinsOnly.getLootHa());

		Map<Integer, Long> today = map(RUNE, 150, BONES, 80, POTION, 800, COINS, 1);
		assertEquals("today's prices: coins at face value, bones left out", Long.valueOf(300 + 500),
			HistoryPricing.value(recordWithCoins(), LootPriceMode.GE, today, HIDE_COINS_AND_BONES).getLootValue());

		String line = TaskCompleteMessage.format(recordWithCoins(), LootPriceMode.GE, HIDE_COINS_AND_BONES);
		assertTrue(line, line.endsWith(" · ~+100"));
	}

	@Test
	public void hiddenCoinsStillCountInTrendsAndTotals()
	{
		List<LedgerRecord> records = Collections.singletonList(recordWithCoins());
		// Today's prices are the ones the task was saved with.
		Map<Integer, Long> today = map(RUNE, 100, BONES, 50, POTION, 800, COINS, 1);
		assertEquals("profit/h: 700 - 600 over an hour", Long.valueOf(100), TaskRanking.rank(records,
			TaskRanking.Metric.PROFIT, LootPriceMode.GE, today, HIDE_COINS_AND_BONES).get(0).getRatePerHour());
		List<TaskChart.Monster> monsters = TaskChart.monsters(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			today, HIDE_COINS_AND_BONES);
		assertEquals(100, TaskChart.points(records, monsters.get(0), TaskRanking.Metric.PROFIT, LootPriceMode.GE,
			today, HIDE_COINS_AND_BONES).get(0).getRatePerHour());

		OverallTotals.Entry totals = OverallTotals.summarize(records, OverallTotals.Grouping.ALL, LootPriceMode.GE,
			today, HIDE_COINS_AND_BONES, ZoneOffset.UTC).get(0);
		assertEquals(Long.valueOf(100), totals.getProfit());
		assertEquals("the summed loot items still list coins and bones (the grid hides them)", 4,
			totals.getLoot().size());

		TaskStatistics stats = TaskStatistics.forTask(records, 410, "Kurask", null, r -> null, LootPriceMode.GE,
			today, HIDE_COINS_AND_BONES);
		assertEquals("loot per kill: 700 over 10 kills", Long.valueOf(70), stats.getLootPerKill());
	}

	@Test
	public void hiddenCoinsStillCountInTheLiveValues()
	{
		SessionValuation valuation = new SessionValuation();
		ItemTally loot = new ItemTally();
		loot.add(BONES, 10);
		loot.add(RUNE, 1);
		loot.add(COINS, 2_500);
		SessionValuation.Values v = valuation.update("s1", loot, null, null, LootPriceMode.GE,
			HIDE_COINS_AND_BONES, new Lookup(), 0);
		assertEquals("the rune and the coins; the bones are left out", 1_000 + 2_500, v.getLootValue());
		assertEquals(600 + 2_500, v.getLootHa());
		assertEquals(3_500, v.getProfit());
		assertEquals("the grid still gets coins to hide", HIDE_COINS_AND_BONES, v.getHiddenLoot());
		assertEquals(1, HIDE_COINS_AND_BONES.visibleRows(v.getItems().lootRows(LootPriceMode.GE, null)).size());
	}

	// ---- The advisor ----

	/** A completed hour-long task of {@code monster} with {@code bones} bones at 1,000 gp and 1,000 gp of runes. */
	private static LedgerRecord advisorTask(String id, int creatureId, String monster, long bones)
	{
		LedgerRecord r = new LedgerRecord();
		r.setId(id);
		r.setMonster(monster);
		r.setCreatureId(creatureId);
		r.setKills(10);
		r.setActiveMillis(3_600_000L);
		r.setStartedAt(1_000L);
		r.setEndedAt(3_601_000L);
		r.setCompleted(true);
		r.setPartial(false);
		r.setLoot(bones > 0 ? map(RUNE, 10, BONES, bones) : map(RUNE, 10));
		r.setUnitGePrices(map(RUNE, 100, BONES, 1_000));
		r.setUnitHaPrices(map(RUNE, 60, BONES, 5));
		r.setLootGeValue(1_000L + bones * 1_000L);
		r.setLootHaValue(600L + bones * 5L);
		r.setSuppliesGeValue(0L);
		return r;
	}

	@Test
	public void theAdvisorRanksWithHiddenLootLeftOut()
	{
		List<LedgerRecord> records = new ArrayList<>();
		// Kurask earns its profit from bones; five other monsters earn 2,000 to 6,000 gp/h without any.
		for (int t = 0; t < 3; t++)
		{
			records.add(advisorTask("k" + t, 410, "Kurask", 100));
			for (int m = 1; m <= 5; m++)
			{
				LedgerRecord other = advisorTask("m" + m + t, 410 + m, "Monster " + m, 0);
				other.setLoot(map(RUNE, 10 + 10 * m));
				other.setLootGeValue(1_000L + 1_000L * m);
				records.add(other);
			}
		}

		TaskAdvisor.Result all = TaskAdvisor.advise(records, 410, "Kurask", TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HiddenLoot.NONE);
		assertEquals(TaskAdvisor.Advice.DO, all.getAdvice());
		assertEquals(101_000L, all.getRatePerHour());
		assertEquals("the highest of six", 6, all.getPosition());

		TaskAdvisor.Result hidden = TaskAdvisor.advise(records, 410, "Kurask", TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HIDE_BONES);
		assertEquals("only the runes count", 1_000L, hidden.getRatePerHour());
		assertEquals("now the lowest of six", 1, hidden.getPosition());
		assertEquals(6, hidden.getMonsters());
		assertEquals(TaskAdvisor.Advice.CONSIDER_SKIP, hidden.getAdvice());
	}

	/**
	 * {@link TaskAdvisor#MIN_TASKS} hour-long tasks of each of two groups of one monster: {@code first} earns 11,000
	 * gp/h, mostly from 10 bones, and {@code second} 4,000 gp/h from runes alone.
	 */
	private static List<LedgerRecord> twoGroups(int creatureId, String monster, String firstVariant,
		String secondVariant, boolean secondCannon)
	{
		List<LedgerRecord> records = new ArrayList<>();
		for (int t = 0; t < TaskAdvisor.MIN_TASKS; t++)
		{
			LedgerRecord first = advisorTask("a" + t, creatureId, monster, 10);
			first.setVariant(firstVariant);
			records.add(first);
			LedgerRecord second = advisorTask("b" + t, creatureId, monster, 0);
			second.setVariant(secondVariant);
			second.setLoot(map(RUNE, 40));
			second.setLootGeValue(4_000L);
			if (secondCannon)
			{
				second.setSupplies(map(SupplyTracker.CANNONBALL, 50));
				second.setUnitGePrices(map(RUNE, 100, BONES, 1_000, SupplyTracker.CANNONBALL, 0));
			}
			records.add(second);
		}
		return records;
	}

	@Test
	public void theVariantAdviceFlipsWhenTheStandardVersionsLootIsHidden()
	{
		List<LedgerRecord> records = twoGroups(7, "Aberrant spectres", null, "Deviant spectres", false);

		TaskAdvisor.VersionAdvice all = TaskAdvisor.adviseVariant(records, 7, "Aberrant spectres",
			TaskRanking.Metric.PROFIT, LootPriceMode.GE, null, HiddenLoot.NONE);
		assertEquals("Aberrant spectres", all.getLabel());
		assertEquals("Profit (GE)/h: Aberrant spectres 11K (n=3), Deviant spectres 4,000 (n=3)",
			all.reason(LootPriceMode.GE));

		TaskAdvisor.VersionAdvice hidden = TaskAdvisor.adviseVariant(records, 7, "Aberrant spectres",
			TaskRanking.Metric.PROFIT, LootPriceMode.GE, null, HIDE_BONES);
		assertEquals("only the runes count", "Deviant spectres", hidden.getLabel());
		assertEquals("Profit (GE)/h: Deviant spectres 4,000 (n=3), Aberrant spectres 1,000 (n=3)",
			hidden.reason(LootPriceMode.GE));
	}

	@Test
	public void theCannonAdviceFlipsWhenTheLootWithoutACannonIsHidden()
	{
		List<LedgerRecord> records = twoGroups(49, "Dust devils", null, null, true);

		TaskAdvisor.Outcome all = TaskAdvisor.adviseAll(records, 49, "Dust devils", TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HiddenLoot.NONE);
		assertEquals(TaskAdvisor.WITHOUT_CANNON, all.getCannon().getLabel());

		TaskAdvisor.Outcome hidden = TaskAdvisor.adviseAll(records, 49, "Dust devils", TaskRanking.Metric.PROFIT,
			LootPriceMode.GE, null, HIDE_BONES);
		assertEquals("only the runes count", TaskAdvisor.WITH_CANNON, hidden.getCannon().getLabel());
		assertEquals("Profit (GE)/h: Dust devils (cannon) 4,000 (n=3), Dust devils 1,000 (n=3)",
			hidden.getCannon().reason(LootPriceMode.GE));
	}

	@Test
	public void theTaskCompleteLineLeavesHiddenLootOut()
	{
		String all = TaskCompleteMessage.format(record(), LootPriceMode.GE);
		String hidden = TaskCompleteMessage.format(record(), LootPriceMode.GE, HIDE_BONES);
		assertTrue(all, all.endsWith(" · ~+100"));
		assertTrue(hidden, hidden.endsWith(" · ~-400"));
	}

	// ---- The live session ----

	/** GE 100 a bone, 1,000 a shark; high alch 5 a bone. */
	private static final class Lookup implements ItemValuation.PriceLookup
	{
		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int canonicalId)
		{
			return canonicalId == BONES ? 100 : canonicalId == RUNE ? 1_000 : 0;
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return canonicalId == BONES ? 5 : 600;
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}
	}

	@Test
	public void liveValuesLeaveHiddenLootOutAndFollowTheList()
	{
		SessionValuation valuation = new SessionValuation();
		Lookup lookup = new Lookup();
		ItemTally loot = new ItemTally();
		loot.add(BONES, 10);
		loot.add(RUNE, 1);
		SessionValuation.Values all = valuation.update("s1", loot, null, null, LootPriceMode.GE, HiddenLoot.NONE,
			lookup, 0);
		assertEquals(2_000, all.getLootValue());
		assertEquals(HiddenLoot.NONE, all.getHiddenLoot());

		SessionValuation.Values hidden = valuation.update("s1", loot, null, null, LootPriceMode.GE, HIDE_BONES,
			lookup, 1);
		assertNotEquals("another hidden list is valued again", all, hidden);
		assertEquals(1_000, hidden.getLootValue());
		assertEquals(1_000, hidden.getLootGe());
		assertEquals(600, hidden.getLootHa());
		assertEquals(1_000, hidden.getProfit());
		assertEquals(HIDE_BONES, hidden.getHiddenLoot());
		assertEquals("the item details still list the bones", 2,
			hidden.getItems().lootRows(LootPriceMode.GE, null).size());
		assertEquals("the tally is not changed", 10, loot.get(BONES));

		SessionValuation.Values ha = valuation.update("s1", loot, null, null, LootPriceMode.HIGH_ALCH, HIDE_BONES,
			lookup, 2);
		assertEquals(600, ha.getLootValue());

		SessionValuation.Values back = valuation.update("s1", loot, null, null, LootPriceMode.GE, HiddenLoot.NONE,
			lookup, 3);
		assertEquals(all, back);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import org.junit.Test;

/** The Task history's Location and Master filters, combined with the Monster filter. */
public class HistoryFilterTest
{
	private static final int SMOKE = 12_946;
	private static final int UNNAMED = 6_557;
	private static final Map<Integer, String> REGION_NAMES = Collections.singletonMap(SMOKE, "Smoke Dungeon");
	private static final IntFunction<String> NAMES = REGION_NAMES::get;
	private static final IntFunction<String> NO_NAMES = region -> null;

	private static LedgerRecord record(String id, String monster, String location, Integer master)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(id);
		record.setMonster(monster);
		record.setLocation(location);
		record.setSlayerMaster(master);
		return record;
	}

	private static List<String> ids(List<LedgerRecord> records)
	{
		List<String> ids = new ArrayList<>();
		for (LedgerRecord record : records)
		{
			ids.add(record.getId());
		}
		return ids;
	}

	/** Newest first, as the model holds them. */
	private static List<LedgerRecord> history()
	{
		LedgerRecord regionOnly = record("r", "Dust devils", null, 5);
		regionOnly.setLocationRegion(SMOKE);
		LedgerRecord unnamedRegion = record("u", "Dust devils", null, null);
		unnamedRegion.setLocationRegion(UNNAMED);
		LedgerRecord konar = record("k", "Hydras", null, SlayerMaster.KONAR);
		konar.setTaskLocation("Karuulm Slayer Dungeon");
		return Arrays.asList(
			record("a", "Abyssal demons", "Catacombs", 5),
			record("b", "Dust devils", "Smoke Dungeon", 6),
			regionOnly,
			unnamedRegion,
			konar,
			record("c", "Abyssal demons", "abyss", 99),
			record("d", "Abyssal demons", null, SlayerMaster.NONE));
	}

	@Test
	public void aRecordsLocationIsTheOneHistoryShowsOrNoLocation()
	{
		List<LedgerRecord> records = history();
		assertEquals("Catacombs", HistoryFilter.location(records.get(0), NAMES));
		assertEquals("its region's name", "Smoke Dungeon", HistoryFilter.location(records.get(2), NAMES));
		assertEquals("not named yet", HistoryFilter.NO_LOCATION, HistoryFilter.location(records.get(2), NO_NAMES));
		assertEquals(HistoryFilter.NO_LOCATION, HistoryFilter.location(records.get(3), NAMES));
		assertEquals("its assigned area", "Karuulm Slayer Dungeon", HistoryFilter.location(records.get(4), NAMES));
		assertEquals(HistoryFilter.NO_LOCATION, HistoryFilter.location(records.get(6), NAMES));
	}

	@Test
	public void aRecordsMasterIsItsNameOrUnknownMaster()
	{
		List<LedgerRecord> records = history();
		assertEquals("Duradel/Kuradal", HistoryFilter.master(records.get(0)));
		assertEquals("Konar", HistoryFilter.master(records.get(4)));
		assertEquals("no master saved", HistoryFilter.UNKNOWN_MASTER, HistoryFilter.master(records.get(3)));
		assertEquals("a value not in the table", HistoryFilter.UNKNOWN_MASTER, HistoryFilter.master(records.get(5)));
		assertEquals("no task", HistoryFilter.UNKNOWN_MASTER, HistoryFilter.master(records.get(6)));
	}

	@Test
	public void locationChoicesAreAllThenEachLocationAlphabeticallyThenNoLocation()
	{
		assertEquals(Arrays.asList(LedgerHistory.ALL, "abyss", "Catacombs", "Karuulm Slayer Dungeon", "Smoke Dungeon",
			HistoryFilter.NO_LOCATION), HistoryFilter.locationOptions(history(), NAMES));
	}

	@Test
	public void locationsThatAreTheSamePlaceAreOneChoiceAsTheNewestRecordSpellsIt()
	{
		List<LedgerRecord> records = Arrays.asList(record("new", "Kurask", "Fremennik  slayer dungeon", 5),
			record("old", "Kurask", "Fremennik Slayer Dungeon", 5));
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Fremennik slayer dungeon"),
			HistoryFilter.locationOptions(records, NAMES));
		assertEquals(Arrays.asList("new", "old"),
			ids(new HistoryFilter(null, "Fremennik slayer dungeon", null).apply(records, NAMES)));
	}

	@Test
	public void masterChoicesAreAllThenEachMasterAlphabeticallyThenUnknownMaster()
	{
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Duradel/Kuradal", "Konar", "Nieve/Steve",
			HistoryFilter.UNKNOWN_MASTER), HistoryFilter.masterOptions(history()));
	}

	@Test
	public void choicesLeaveOutSentinelsNobodyHasAndAreJustAllWithoutRecords()
	{
		List<LedgerRecord> records = Collections.singletonList(record("a", "Kurask", "Iorwerth Dungeon", 6));
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Iorwerth Dungeon"), HistoryFilter.locationOptions(records, NAMES));
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Nieve/Steve"), HistoryFilter.masterOptions(records));
		assertEquals(Collections.singletonList(LedgerHistory.ALL),
			HistoryFilter.locationOptions(Collections.emptyList(), NAMES));
		assertEquals(Collections.singletonList(LedgerHistory.ALL), HistoryFilter.masterOptions(Collections.emptyList()));
	}

	@Test
	public void eachFilterAloneKeepsTheRecordOrder()
	{
		List<LedgerRecord> records = history();
		assertEquals(Arrays.asList("a", "b", "r", "u", "k", "c", "d"), ids(new HistoryFilter(null, null, null).apply(records, NAMES)));
		assertEquals(Arrays.asList("a", "c", "d"),
			ids(new HistoryFilter("Abyssal demons", null, null).apply(records, NAMES)));
		assertEquals("its own name or its region's", Arrays.asList("b", "r"),
			ids(new HistoryFilter(null, "Smoke Dungeon", null).apply(records, NAMES)));
		assertEquals("ignoring case", Arrays.asList("b", "r"),
			ids(new HistoryFilter(null, "smoke dungeon", null).apply(records, NAMES)));
		assertEquals(Arrays.asList("u", "d"),
			ids(new HistoryFilter(null, HistoryFilter.NO_LOCATION, null).apply(records, NAMES)));
		assertEquals(Arrays.asList("a", "r"),
			ids(new HistoryFilter(null, null, "Duradel/Kuradal").apply(records, NAMES)));
		assertEquals(Arrays.asList("u", "c", "d"),
			ids(new HistoryFilter(null, null, HistoryFilter.UNKNOWN_MASTER).apply(records, NAMES)));
	}

	@Test
	public void filtersCombine()
	{
		List<LedgerRecord> records = history();
		assertEquals(Collections.singletonList("r"),
			ids(new HistoryFilter("Dust devils", "Smoke Dungeon", "Duradel/Kuradal").apply(records, NAMES)));
		assertEquals(Collections.singletonList("d"),
			ids(new HistoryFilter("Abyssal demons", HistoryFilter.NO_LOCATION, HistoryFilter.UNKNOWN_MASTER)
				.apply(records, NAMES)));
		assertEquals("each matches alone, not together", Collections.emptyList(),
			ids(new HistoryFilter("Hydras", "Catacombs", null).apply(records, NAMES)));
	}

	@Test
	public void aLocationSelectionIsKeptWhileTheSamePlaceIsAChoice()
	{
		List<String> options = Arrays.asList(LedgerHistory.ALL, "Catacombs", "Smoke Dungeon", HistoryFilter.NO_LOCATION);
		assertEquals("Smoke Dungeon", HistoryFilter.keepLocation(options, "Smoke Dungeon"));
		assertEquals("as it is spelled now", "Smoke Dungeon", HistoryFilter.keepLocation(options, "smoke  dungeon"));
		assertEquals(HistoryFilter.NO_LOCATION, HistoryFilter.keepLocation(options, HistoryFilter.NO_LOCATION));
		assertNull(HistoryFilter.keepLocation(options, "Abyss"));
		assertNull(HistoryFilter.keepLocation(options, null));
		assertNull(HistoryFilter.keepLocation(options, LedgerHistory.ALL));
		assertNull("no record without a location any more",
			HistoryFilter.keepLocation(Arrays.asList(LedgerHistory.ALL, "Catacombs"), HistoryFilter.NO_LOCATION));
	}

	@Test
	public void aPlaceNamedNoLocationIsAChoiceOfItsOwn()
	{
		List<LedgerRecord> records = Arrays.asList(record("named", "Kurask", "No location", 6),
			record("respelled", "Kurask", "no  LOCATION", 6), record("none", "Kurask", null, 6));
		List<String> options = HistoryFilter.locationOptions(records, NAMES);
		assertEquals(Arrays.asList(LedgerHistory.ALL, "No location", HistoryFilter.NO_LOCATION), options);
		assertEquals("both show the same", Arrays.asList(LedgerHistory.ALL, "No location", "No location"),
			Arrays.asList(HistoryFilter.label(options.get(0)), HistoryFilter.label(options.get(1)),
				HistoryFilter.label(options.get(2))));
		assertEquals(Arrays.asList("named", "respelled"),
			ids(new HistoryFilter(null, "No location", null).apply(records, NAMES)));
		assertEquals(Collections.singletonList("none"),
			ids(new HistoryFilter(null, HistoryFilter.NO_LOCATION, null).apply(records, NAMES)));
		assertEquals("No location", HistoryFilter.keepLocation(options, "no location"));
		assertEquals(HistoryFilter.NO_LOCATION, HistoryFilter.keepLocation(options, HistoryFilter.NO_LOCATION));
		assertFalse(HistoryFilter.sameLocationChoice("No location", HistoryFilter.NO_LOCATION));
	}

	@Test
	public void aLocationSpelledAnewIsTheSameChoice()
	{
		assertTrue(HistoryFilter.sameLocationChoice(null, null));
		assertTrue(HistoryFilter.sameLocationChoice("Smoke Dungeon", "smoke  dungeon"));
		assertTrue(HistoryFilter.sameLocationChoice(HistoryFilter.NO_LOCATION, HistoryFilter.NO_LOCATION));
		assertFalse(HistoryFilter.sameLocationChoice("Smoke Dungeon", null));
		assertFalse(HistoryFilter.sameLocationChoice(null, "Smoke Dungeon"));
		assertFalse(HistoryFilter.sameLocationChoice("Smoke Dungeon", "Catacombs"));
	}

	@Test
	public void aRegionNamedLaterMovesItsRecordsOutOfNoLocation()
	{
		Map<Integer, String> names = new HashMap<>();
		List<LedgerRecord> records = history();
		assertEquals(Arrays.asList("r", "u", "d"),
			ids(new HistoryFilter(null, HistoryFilter.NO_LOCATION, null).apply(records, names::get)));
		names.put(UNNAMED, "Catacombs");
		assertEquals(Arrays.asList("a", "u"), ids(new HistoryFilter(null, "Catacombs", null).apply(records, names::get)));
		assertEquals(Arrays.asList("r", "d"),
			ids(new HistoryFilter(null, HistoryFilter.NO_LOCATION, null).apply(records, names::get)));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Saved tasks valued for the history: the price mode at saved prices, and re-pricing at today's GE prices,
 * which is what the sidebar always shows.
 */
public class HistoryPricingTest
{
	private static final int RUNE = 1;
	private static final int NO_GE = 3;
	private static final int POTION = 4;
	private static final int KEY = 23083;

	private static Map<Integer, Long> prices(long... idPrice)
	{
		Map<Integer, Long> map = new HashMap<>();
		for (int i = 0; i < idPrice.length; i += 2)
		{
			map.put((int) idPrice[i], idPrice[i + 1]);
		}
		return map;
	}

	/**
	 * Loot: 2 runes (GE 100, HA 60) and an item without a GE price (HA 300). Supplies: 3 doses of a 4-dose potion
	 * (GE 800, HA 100). Totals as {@link LedgerRecord#captureValues} saves them.
	 */
	private static LedgerRecord record()
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("a");
		r.setMonster("Kurask");
		r.setLoot(prices(RUNE, 2, NO_GE, 1));
		r.setSupplies(prices(POTION, 3));
		r.setSupplyDoses(Collections.singletonMap(POTION, 4));
		r.setUnitGePrices(prices(RUNE, 100, POTION, 800));
		r.setUnitHaPrices(prices(RUNE, 60, NO_GE, 300, POTION, 100));
		r.setLootGeValue(200L);
		r.setLootHaValue(420L);
		r.setSuppliesGeValue(600L);
		r.setSuppliesHaValue(75L);
