import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class ItemDetailsTest
{
	private static final int SHARK = ItemID.SHARK;
	private static final int PRAYER_POTION_4 = ItemID._4DOSEPRAYERRESTORE;
	private static final int WHIP = ItemID.ABYSSAL_WHIP;
	private static final int RUNE_PLATEBODY = ItemID.RUNE_PLATEBODY;
	private static final int COINS = ItemID.COINS;
	/** An untradeable drop: GE 0, valued at high alch. */
	private static final int KEY = ItemID.KONAR_KEY;
	private static final int UNPRICED = 99_999;

	private static final Map<Integer, String> NAMES = new HashMap<>();

	static
	{
		NAMES.put(SHARK, "Shark");
		NAMES.put(PRAYER_POTION_4, "Prayer potion(4)");
		NAMES.put(WHIP, "Abyssal whip");
		NAMES.put(RUNE_PLATEBODY, "Rune platebody");
		NAMES.put(COINS, "Coins");
		NAMES.put(KEY, "Brimstone key");
		NAMES.put(ItemID.ANCHOVIE_PIZZA, "Anchovy pizza");
		NAMES.put(ItemID.AMULET_OF_GLORY_6, "Amulet of glory(6)");
	}

	/** The nature rune's GE price in these tests. */
	private static final Long NATURE_RUNE = 100L;
	private static final ItemDetails.ItemNames LOOKUP = NAMES::get;

	private static ItemTally tally(long... idQuantity)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQuantity.length; i += 2)
		{
			t.add((int) idQuantity[i], idQuantity[i + 1]);
		}
		return t;
	}

	private static Map<Integer, Long> prices(long... idPrice)
	{
		Map<Integer, Long> m = new TreeMap<>();
		for (int i = 0; i < idPrice.length; i += 2)
		{
			m.put((int) idPrice[i], idPrice[i + 1]);
		}
		return m;
	}

	/** Each row as "name | quantity | value", with " | (alch)" when the hint is shown. */
	private static List<String> texts(List<ItemDetails.Row> rows)
	{
		return rows.stream()
			.map(r -> r.getName() + " | " + r.quantityText() + " | " + r.valueText()
				+ (r.isAlchHint() ? " | " + ItemDetails.ALCH_MARKER : ""))
			.collect(Collectors.toList());
	}

	@Test
	public void suppliesAreSortedByValueWithPotionsInDoses()
	{
		ItemDetails details = ItemDetails.of(new ItemTally(), tally(SHARK, 14, PRAYER_POTION_4, 22),
			Collections.singletonMap(PRAYER_POTION_4, 4), prices(SHARK, 1_000, PRAYER_POTION_4, 8_000),
			prices(SHARK, 50, PRAYER_POTION_4, 100));

		// 22 doses at 8,000 per 4 doses = 44,000; 14 sharks = 14,000.
		assertEquals(Arrays.asList("Prayer potion | 22 doses | 44K", "Shark | x14 | 14K"),
			texts(details.supplyRows(LOOKUP)));
	}

	@Test
	public void rowValuesAddUpToTheTotalsWithDoseRounding()
	{
		ItemTally supplies = tally(SHARK, 3, PRAYER_POTION_4, 7);
		Map<Integer, Integer> doses = Collections.singletonMap(PRAYER_POTION_4, 4);
		Map<Integer, Long> ge = prices(SHARK, 999, PRAYER_POTION_4, 8_003);
		long sum = 0;
		for (ItemDetails.Row row : ItemDetails.of(null, supplies, doses, ge, null).supplyRows(LOOKUP))
		{
			sum += row.getValue();
		}
		assertEquals(ItemValuation.total(supplies, ge, doses), sum);
	}

	@Test
	public void bitesAndChargesHaveTheirOwnWords()
	{
		Map<Integer, Integer> doses = new HashMap<>();
		doses.put(ItemID.ANCHOVIE_PIZZA, 2);
		doses.put(ItemID.AMULET_OF_GLORY_6, 6);
		doses.put(PRAYER_POTION_4, 4);
		ItemDetails details = ItemDetails.of(null,
			tally(ItemID.ANCHOVIE_PIZZA, 3, ItemID.AMULET_OF_GLORY_6, 1, PRAYER_POTION_4, 1), doses,
			prices(ItemID.ANCHOVIE_PIZZA, 400, ItemID.AMULET_OF_GLORY_6, 12_000, PRAYER_POTION_4, 8_000), null);

		assertEquals(Arrays.asList("Amulet of glory | 1 charge | 2,000", "Prayer potion | 1 dose | 2,000",
			"Anchovy pizza | 3 bites | 600"), texts(details.supplyRows(LOOKUP)));
		assertEquals(ItemDetails.Unit.BITES, ItemDetails.doseUnit(ItemID.ANCHOVIE_PIZZA));
		assertEquals(ItemDetails.Unit.CHARGES, ItemDetails.doseUnit(ItemID.AMULET_OF_GLORY_6));
		assertEquals(ItemDetails.Unit.DOSES, ItemDetails.doseUnit(PRAYER_POTION_4));
	}

	@Test
	public void unpricedItemsShowAQuestionMarkAndComeLast()
	{
		ItemDetails details = ItemDetails.of(tally(UNPRICED, 5, SHARK, 1), tally(UNPRICED, 2, SHARK, 1), null,
			prices(SHARK, 1_000), prices(SHARK, 50));

		assertEquals(Arrays.asList("Shark | x1 | 1,000", "Item 99999 | x2 | ?"), texts(details.supplyRows(LOOKUP)));
		assertEquals(Arrays.asList("Shark | x1 | 1,000", "Item 99999 | x5 | ?"),
			texts(details.lootRows(LootPriceMode.GE, LOOKUP)));
		assertTrue(details.supplyRows(LOOKUP).get(1).tooltip().contains("Value (GE): unavailable"));
	}

	@Test
	public void lootFollowsThePriceModeAndUntradeablesCountAtHighAlch()
	{
		ItemDetails details = ItemDetails.of(tally(WHIP, 1, RUNE_PLATEBODY, 2, KEY, 3, COINS, 5_000), null, null,
			prices(WHIP, 1_500_000, RUNE_PLATEBODY, 38_000, KEY, 0, COINS, 1),
			prices(WHIP, 72_000, RUNE_PLATEBODY, 39_000, KEY, 2_000, COINS, 1)).withNatureRunePrice(NATURE_RUNE);

		assertEquals(Arrays.asList("Abyssal whip | x1 | 1.5M", "Rune platebody | x2 | 76K | (alch)",
			"Brimstone key | x3 | 6,000", "Coins | x5,000 | 5,000"), texts(details.lootRows(LootPriceMode.GE, LOOKUP)));
		assertEquals(Arrays.asList("Rune platebody | x2 | 78K | (alch)", "Abyssal whip | x1 | 72K",
			"Brimstone key | x3 | 6,000", "Coins | x5,000 | 5,000"),
			texts(details.lootRows(LootPriceMode.HIGH_ALCH, LOOKUP)));
	}

	@Test
	public void alchHintNeedsHighAlchLessANatureRuneAboveAKnownNonZeroGePrice()
	{
		assertTrue(ItemDetails.alchBeatsGe(38_000L, 39_000L, NATURE_RUNE));
		assertFalse("equal is not better", ItemDetails.alchBeatsGe(38_900L, 39_000L, NATURE_RUNE));
		assertFalse("law rune: high alch beats GE, but not after the nature rune",
			ItemDetails.alchBeatsGe(117L, 144L, NATURE_RUNE));
		assertFalse(ItemDetails.alchBeatsGe(1_500_000L, 72_000L, NATURE_RUNE));
		assertFalse("untradeable: already valued at high alch", ItemDetails.alchBeatsGe(0L, 2_000L, NATURE_RUNE));
		assertFalse("GE unavailable", ItemDetails.alchBeatsGe(null, 2_000L, NATURE_RUNE));
		assertFalse("high alch unavailable", ItemDetails.alchBeatsGe(1_000L, null, NATURE_RUNE));
		assertFalse("nature rune price unknown", ItemDetails.alchBeatsGe(38_000L, 39_000L, null));

		ItemDetails details = ItemDetails.of(tally(RUNE_PLATEBODY, 1), null, null, prices(RUNE_PLATEBODY, 38_000),
			prices(RUNE_PLATEBODY, 39_000));
		assertFalse("no hint until the nature rune price is known", details.lootRows(LootPriceMode.GE, LOOKUP).get(0)
			.isAlchHint());
		assertFalse("an unavailable price (0) is unknown", details.withNatureRunePrice(0L)
			.lootRows(LootPriceMode.GE, LOOKUP).get(0).isAlchHint());
		assertTrue(details.withNatureRunePrice(NATURE_RUNE).lootRows(LootPriceMode.GE, LOOKUP).get(0).isAlchHint());
	}

	@Test
	public void suppliesNeverGetTheAlchHint()
	{
		ItemDetails details = ItemDetails.of(null, tally(RUNE_PLATEBODY, 1), null, prices(RUNE_PLATEBODY, 38_000),
			prices(RUNE_PLATEBODY, 39_000));
		assertFalse(details.supplyRows(LOOKUP).get(0).isAlchHint());
	}

	@Test
	public void alchHintTooltipExplainsIt()
	{
		ItemDetails details = ItemDetails.of(tally(RUNE_PLATEBODY, 2), null, null, prices(RUNE_PLATEBODY, 38_000),
			prices(RUNE_PLATEBODY, 39_000)).withNatureRunePrice(NATURE_RUNE);
		String tooltip = details.lootRows(LootPriceMode.GE, LOOKUP).get(0).tooltip();
		assertTrue(tooltip, tooltip.contains("Rune platebody<br>Quantity: 2<br>Value (GE): 76,000 gp"));
		assertTrue(tooltip, tooltip.contains("GE: 38,000 gp each<br>High alch: 39,000 gp each"));
		assertTrue(tooltip, tooltip.contains("(alch) High alch, less a nature rune, is worth more than<br>the GE price."));
	}

	@Test
	public void namesAreLookedUpAndFallBackToTheId()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(SHARK, "<b>Shark</b>");
		ItemDetails details = ItemDetails.of(tally(SHARK, 1, WHIP, 1), null, null, prices(SHARK, 1, WHIP, 1), null);
		List<ItemDetails.Row> rows = details.lootRows(LootPriceMode.GE, names::get);
		assertEquals("<b>Shark</b>", rows.get(0).getName());
		assertTrue("names are escaped in the tooltip", rows.get(0).tooltip().contains("&lt;b&gt;Shark"));
		assertEquals("Item " + WHIP, rows.get(1).getName());
		assertEquals("Item 7", ItemDetails.displayName(7, null, false));
		assertEquals("Item 7", ItemDetails.displayName(7, id -> " ", false));
		assertEquals("Prayer potion", ItemDetails.displayName(1, id -> "Prayer potion(4)", true));
		assertEquals("Prayer potion(4)", ItemDetails.displayName(1, id -> "Prayer potion(4)", false));
		assertEquals("Amulet of glory", ItemDetails.displayName(1, id -> "Amulet of glory(t6)", true));
		assertEquals("Ring of wealth", ItemDetails.displayName(1, id -> "Ring of wealth (i5)", true));
		assertEquals("Fungicide spray", ItemDetails.displayName(1, id -> "Fungicide spray 10", true));
		assertEquals("not counted per charge", "Black mask (10)", ItemDetails.displayName(1, id -> "Black mask (10)", false));
	}

	@Test
	public void tiesAreSortedByNameThenId()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(1, "b");
		names.put(2, "A");
		names.put(3, "A");
		ItemDetails details = ItemDetails.of(tally(1, 1, 3, 1, 2, 1), null, null, prices(1, 5, 2, 5, 3, 5), null);
		List<Integer> ids = new ArrayList<>();
		for (ItemDetails.Row row : details.lootRows(LootPriceMode.GE, names::get))
		{
			ids.add(row.getItemId());
		}
		assertEquals(Arrays.asList(2, 3, 1), ids);
	}

	@Test
	public void oldRecordsHaveNoItemDetails()
	{
		LedgerRecord old = new LedgerRecord();
		assertNull(ItemDetails.of(old));

		LedgerRecord empty = new LedgerRecord();
		empty.setLootGeValue(0L);
		ItemDetails details = ItemDetails.of(empty);
		assertNotNull("a valued task with nothing in it still has (empty) lists", details);
		assertTrue(details.supplyRows(LOOKUP).isEmpty());
		assertTrue(details.lootRows(LootPriceMode.GE, LOOKUP).isEmpty());
	}

	@Test
	public void savedRecordsUseTheirStoredPrices()
	{
		LedgerRecord record = new LedgerRecord();
		record.setLoot(prices(RUNE_PLATEBODY, 1, KEY, 1));
		record.setSupplies(prices(PRAYER_POTION_4, 6));
		record.setSupplyDoses(Collections.singletonMap(PRAYER_POTION_4, 4));
		record.setUnitGePrices(prices(RUNE_PLATEBODY, 38_000, KEY, 0, PRAYER_POTION_4, 8_000));
		record.setUnitHaPrices(prices(RUNE_PLATEBODY, 39_000, KEY, 2_000, PRAYER_POTION_4, 100));
		record.setLootGeValue(38_000L);

		ItemDetails details = ItemDetails.of(record).withNatureRunePrice(NATURE_RUNE);
		assertEquals(Arrays.asList("Rune platebody | x1 | 38K | (alch)", "Brimstone key | x1 | 2,000"),
			texts(details.lootRows(LootPriceMode.GE, LOOKUP)));
		assertEquals(Collections.singletonList("Prayer potion | 6 doses | 12K"), texts(details.supplyRows(LOOKUP)));
		assertEquals(new java.util.TreeSet<>(Arrays.asList(RUNE_PLATEBODY, KEY, PRAYER_POTION_4)), details.itemIds());

		// Today's GE prices: the GE side changes, high alch stays (as the history totals); a missing price is "?".
		ItemDetails today = details.withGePrices(prices(RUNE_PLATEBODY, 40_000, PRAYER_POTION_4, 10_000));
		assertEquals(Arrays.asList("Rune platebody | x1 | 40K", "Brimstone key | x1 | ?"),
			texts(today.lootRows(LootPriceMode.GE, LOOKUP)));
		assertEquals(Arrays.asList("Rune platebody | x1 | 39K | (alch)", "Brimstone key | x1 | 2,000"),
			texts(details.lootRows(LootPriceMode.HIGH_ALCH, LOOKUP)));
		assertEquals(Collections.singletonList("Prayer potion | 6 doses | 15K"), texts(today.supplyRows(LOOKUP)));
	}

	@Test
	public void rowValuesMatchTheHistoryTotals()
	{
		LedgerRecord record = new LedgerRecord();
		record.setLoot(prices(RUNE_PLATEBODY, 3, KEY, 2, COINS, 777));
		record.setUnitGePrices(prices(RUNE_PLATEBODY, 38_000, KEY, 0, COINS, 1));
		record.setUnitHaPrices(prices(RUNE_PLATEBODY, 39_000, KEY, 2_000, COINS, 1));
		record.setLootGeValue(38_000L * 3 + 777);
		record.setLootHaValue(39_000L * 3 + 4_000 + 777);
		for (LootPriceMode mode : LootPriceMode.values())
		{
			long sum = 0;
			for (ItemDetails.Row row : ItemDetails.of(record).lootRows(mode, LOOKUP))
			{
				sum += row.getValue();
			}
			assertEquals(mode.name(), HistoryPricing.value(record, mode, null).getLootValue().longValue(), sum);
		}
	}

	@Test
	public void longListsShowTheTopRowsUntilAskedForAll()
	{
		List<Integer> rows = new ArrayList<>();
		for (int i = 0; i < 13; i++)
		{
			rows.add(i);
		}
		assertEquals(ItemDetails.MAX_ROWS, ItemDetails.visible(rows, false).size());
		assertEquals(Integer.valueOf(9), ItemDetails.visible(rows, false).get(9));
		assertEquals(13, ItemDetails.visible(rows, true).size());
		assertEquals(3, ItemDetails.hiddenCount(13));
		assertEquals(0, ItemDetails.hiddenCount(10));
		assertEquals(10, ItemDetails.visible(rows.subList(0, 10), false).size());
	}

	@Test
	public void quantitiesAreShortenedLikeStackSizes()
	{
		ItemDetails details = ItemDetails.of(tally(COINS, 123_456), null, null, prices(COINS, 1), prices(COINS, 1));
		ItemDetails.Row row = details.lootRows(LootPriceMode.GE, LOOKUP).get(0);
		assertEquals("x123K", row.quantityText());
		assertEquals("123K", row.valueText());
		assertTrue(row.tooltip(), row.tooltip().contains("Quantity: 123,456"));
	}

	@Test
	public void emptyDetailsHaveNoRows()
	{
		assertTrue(ItemDetails.EMPTY.itemIds().isEmpty());
		assertTrue(ItemDetails.EMPTY.lootRows(null, LOOKUP).isEmpty());
		assertEquals(ItemDetails.EMPTY, ItemDetails.of(new ItemTally(), new ItemTally(), null, null, null));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Container;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;

/**
 * {@link ItemGridView}: supplies and loot as item icons, five to a row, read through
 * {@link PanelProbe.ItemGridProbe} with a fake {@link ItemIcons} (no {@code ItemManager}). Each icon reads as
 * {@code "<name> | <item id> x<quantity>"}, with {@code " | (alch)"} for the alch hint's border. The XP list stays
 * text ({@link ItemListView}). {@link HarnessItemListsTest} covers the grids as wired in the plugin.
 */
public class ItemGridViewTest
{
	/** What each fake icon shows, by its image. */
	private final Map<Image, String> shown = Collections.synchronizedMap(new IdentityHashMap<>());
	/** Every icon asked for, in order. */
	private final List<String> requests = Collections.synchronizedList(new ArrayList<>());
	private final ItemIcons icons = (label, itemId, quantity) ->
	{
		assertTrue("icons are put on labels on the EDT", SwingUtilities.isEventDispatchThread());
		Image image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		shown.put(image, itemId + " x" + quantity);
		requests.add(itemId + " x" + quantity);
		label.setIcon(new ImageIcon(image));
	};

	private String iconText(Icon icon)
	{
		return icon instanceof ImageIcon ? shown.get(((ImageIcon) icon).getImage()) : null;
	}

	private static ItemDetails.Row row(int id, String name, long quantity, Long value, boolean alch)
	{
		return ItemDetails.Row.builder()
			.itemId(id)
			.name(name)
			.quantity(quantity)
			.unit(ItemDetails.Unit.ITEMS)
			.value(value)
			.priceName("GE")
			.unitGe(value == null ? null : value / Math.max(1, quantity))
			.unitHa(null)
			.dosesPerItem(null)
			.alchHint(alch)
			.build();
	}

	private static void onEdt(Runnable action)
	{
		try
		{
			SwingUtilities.invokeAndWait(action);
		}
		catch (InterruptedException | InvocationTargetException e)
		{
			throw new AssertionError(e.getCause() != null ? e.getCause() : e);
		}
	}

	private PanelProbe.ItemGridProbe probe(ItemGridView grid)
	{
		return new PanelProbe.ItemGridProbe(grid, this::iconText);
	}

	@Test
	public void showsEveryRowAsAnIconInOrderWithItsTooltip()
	{
		List<ItemDetails.Row> rows = new ArrayList<>();
		for (int i = 0; i < 7; i++)
		{
			rows.add(row(100 + i, "Item " + i, i + 1, 1_000L - i, false));
		}
		onEdt(() ->
		{
			ItemGridView grid = new ItemGridView("Loot received", false, ColorScheme.DARKER_GRAY_COLOR, icons);
			grid.setRows(rows);
			PanelProbe.ItemGridProbe probe = probe(grid);
			assertEquals("Loot received (7)", probe.getHeaderText());
			assertEquals(Arrays.asList("Item 0 | 100 x1", "Item 1 | 101 x2", "Item 2 | 102 x3", "Item 3 | 103 x4",
				"Item 4 | 104 x5", "Item 5 | 105 x6", "Item 6 | 106 x7"), probe.getCellTexts());
			List<String> tooltips = probe.getCellTooltips();
			for (int i = 0; i < rows.size(); i++)
			{
				assertEquals(rows.get(i).tooltip(), tooltips.get(i));
			}
			// Two rows of five; three empty slots fill the second.
			assertEquals(2 * ItemGridView.COLUMNS, probe.getSlotCount());
		});
	}

	@Test
	public void theAlchHintIsAnOrangeBorder()
	{
		onEdt(() ->
		{
			ItemGridView grid = new ItemGridView("Loot received", false, ColorScheme.DARKER_GRAY_COLOR, icons);
			grid.setRows(Arrays.asList(row(1127, "Rune platebody", 1, 38_000L, true),
				row(526, "Bones", 3, 300L, false)));
			assertEquals(Arrays.asList("Rune platebody | 1127 x1 | (alch)", "Bones | 526 x3"),
				probe(grid).getCellTexts());
		});
	}

	@Test
	public void aCollapsibleGridStartsClosedCountsItsItemsAndSaysNoneWhenEmpty()
	{
		onEdt(() ->
		{
			ItemGridView grid = new ItemGridView("Supplies used", true, ColorScheme.DARKER_GRAY_COLOR, icons);
			PanelProbe.ItemGridProbe probe = probe(grid);
			assertEquals("Supplies used (0) | Show", probe.getHeaderText());
			assertTrue(probe.getCellTexts().isEmpty());

			probe.toggle();
			assertTrue(grid.isExpanded());
			assertEquals("Supplies used (0) | Hide", probe.getHeaderText());
			assertEquals(Collections.singletonList("None"), probe.getCellTexts());
			assertEquals(0, probe.getSlotCount());

			grid.setRows(Arrays.asList(row(385, "Shark", 2, 1_600L, false), row(2434, "Prayer potion", 1, null,
				false)));
			assertEquals("Supplies used (2) | Hide", probe.getHeaderText());
			assertEquals(Arrays.asList("Shark | 385 x2", "Prayer potion | 2434 x1"), probe.getCellTexts());

			probe.toggle();
			assertEquals("Supplies used (2) | Show", probe.getHeaderText());
			assertTrue("closed: no icons", probe.getCellTexts().isEmpty());
		});
	}

	@Test
	public void iconsAreOnlyAskedForWhileOpenAndWhenTheRowsChange()
	{
		List<ItemDetails.Row> rows = Arrays.asList(row(385, "Shark", 2, 1_600L, false));
		onEdt(() ->
		{
			ItemGridView grid = new ItemGridView("Supplies used", true, ColorScheme.DARKER_GRAY_COLOR, icons);
			grid.setRows(rows);
			assertTrue("closed: nothing drawn", requests.isEmpty());
			grid.toggle();
			assertEquals(Collections.singletonList("385 x2"), requests);
			grid.setRows(new ArrayList<>(rows));
			assertEquals("the same rows are not drawn again", 1, requests.size());
		});
	}

	@Test
	public void theGridNeverWidensTheSidebar()
	{
		onEdt(() ->
		{
			ItemGridView grid = new ItemGridView("Loot received", false, ColorScheme.DARKER_GRAY_COLOR, icons);
			List<ItemDetails.Row> rows = new ArrayList<>();
			for (int i = 0; i < 12; i++)
			{
				rows.add(row(100 + i, "Item " + i, 1, 100L, false));
			}
			grid.setRows(rows);
			Container cells = (Container) SwingLookup.find(grid, "itemGrid.grid");
			// Five columns take the list's width; the grid itself asks for less than one 36 px sprite.
			assertTrue(cells.getPreferredSize().toString(), cells.getPreferredSize().width < 36);
			assertEquals(3 * ItemGridView.CELL_HEIGHT + 2, cells.getPreferredSize().height);
		});
	}

	@Test
	public void hiddenLootIsLeftOutAndCountedInTheTitleAndTooltip()
	{
		List<ItemDetails.Row> rows = Arrays.asList(row(1127, "Rune platebody", 1, 38_000L, false),
			row(526, "Bones", 3, 300L, false), row(995, "Coins", 500, 500L, false));
		onEdt(() ->
		{
			ItemGridView grid = new ItemGridView("Loot received", true, ColorScheme.DARKER_GRAY_COLOR, icons);
			PanelProbe.ItemGridProbe probe = probe(grid);
			grid.toggle();
			grid.setRows(rows, HiddenLoot.of(Arrays.asList(526, 995)));
			assertEquals("Loot received (1, 2 hidden) | Hide", probe.getHeaderText());
			assertEquals(Collections.singletonList("Rune platebody | 1127 x1"), probe.getCellTexts());
			String tip = probe.getHeaderTooltip();
			assertTrue(tip, tip.startsWith("<html>Click to show or hide the items.<br>2 items are hidden by your"
				+ " Ground Items<br>hidden list"));
			assertTrue("coins are hidden like any item and counted in the hidden number", tip.endsWith(
				"2 items are hidden by your Ground Items<br>hidden list; hidden items<br>are left out of loot value,"
					+ " except coins.</html>"));

			// Every item hidden: said instead of "None".
			grid.setRows(rows, HiddenLoot.of(Arrays.asList(1127, 526, 995)));
			assertEquals("Loot received (0, 3 hidden) | Hide", probe.getHeaderText());
			assertEquals(Collections.singletonList("All hidden"), probe.getCellTexts());

			// Nothing hidden: as before, with the plain tooltip.
			grid.setRows(rows, HiddenLoot.NONE);
			assertEquals("Loot received (3) | Hide", probe.getHeaderText());
			assertEquals("Click to show or hide the items", probe.getHeaderTooltip());
			grid.setRows(Collections.emptyList(), null);
			assertEquals(Collections.singletonList("None"), probe.getCellTexts());
		});
	}

	@Test
	public void aFixedGridSaysHowManyAreHiddenAndSkipsEqualRows()
	{
		List<ItemDetails.Row> rows = Arrays.asList(row(1127, "Rune platebody", 1, 38_000L, false),
			row(526, "Bones", 1, 100L, false));
		onEdt(() ->
		{
			ItemGridView grid = new ItemGridView("Loot received", false, ColorScheme.DARKER_GRAY_COLOR, icons);
			PanelProbe.ItemGridProbe probe = probe(grid);
			assertNull("no tooltip without hidden items", probe.getHeaderTooltip());
			grid.setRows(rows, HiddenLoot.of(Collections.singleton(526)));
			assertEquals("Loot received (1, 1 hidden)", probe.getHeaderText());
			assertTrue(probe.getHeaderTooltip(), probe.getHeaderTooltip().startsWith("<html>1 item is hidden by"));
			int drawn = requests.size();
			grid.setRows(new ArrayList<>(rows), HiddenLoot.of(Collections.singleton(526)));
			assertEquals("the same rows and hidden count are not drawn again", drawn, requests.size());
			grid.setRows(rows, HiddenLoot.NONE);
			assertEquals("Loot received (2)", probe.getHeaderText());
			assertNull(probe.getHeaderTooltip());

			// The same header format as a collapsible list, without " | Show" or " | Hide".
			grid.setRows(rows, HiddenLoot.of(Arrays.asList(1127, 526)));
			assertEquals("Loot received (0, 2 hidden)", probe.getHeaderText());
			assertEquals(Collections.singletonList("All hidden"), probe.getCellTexts());
			grid.setRows(Collections.emptyList(), null);
			assertEquals("Loot received (0)", probe.getHeaderText());
			assertEquals(Collections.singletonList("None"), probe.getCellTexts());
		});
	}

	@Test
	public void quantitiesAboveAnIntAreCapped()
	{
		assertEquals(Integer.MAX_VALUE, ItemGridView.iconQuantity(Long.MAX_VALUE));
		assertEquals(14, ItemGridView.iconQuantity(14));
		assertEquals(0, ItemGridView.iconQuantity(-1));
	}

	@Test
	public void theXpListStaysText()
	{
		onEdt(() ->
		{
			ItemListView xp = new ItemListView(SkillXp.LIST_TITLE, false, ColorScheme.DARKER_GRAY_COLOR,
				SkillXp.LIST_NOUN, (label, skill) ->
				{
				});
			xp.setRows(SkillXp.rows(Collections.singletonMap("SLAYER", 1_500L), 0));
			assertEquals(Collections.singletonList("Slayer | 1,500"),
				new PanelProbe.ItemListProbe(xp, this::iconText).getLineTexts());
			assertFalse(SwingLookup.isInTree(xp, "itemGrid.grid"));
		});
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;

/**
 * {@link ItemListView} as the XP list: each line has its skill's small icon before the name, from a fake
 * {@link SkillIcons} (no {@code SkillIconManager}), and a line with no skill keeps an empty slot of the same size. The
 * top ten, "+N more" and tooltips are as before. {@link HarnessXpTest} and {@link HarnessItemListsTest} cover the
 * lists as wired in the plugin.
 */
public class ItemListViewTest
{
	/** Skills the fake knows; like the plugin, it leaves the label without an icon for any other key. */
	private static final List<String> KNOWN = Arrays.asList("ATTACK", "STRENGTH", "DEFENCE", "RANGED", "PRAYER",
		"MAGIC", "HITPOINTS", "SLAYER", "AGILITY", "HERBLORE", "THIEVING", "CRAFTING");

	/** What each fake icon shows, by its image. */
	private final Map<Image, String> shown = Collections.synchronizedMap(new IdentityHashMap<>());
	/** Every icon asked for, in order. */
	private final List<String> requests = Collections.synchronizedList(new ArrayList<>());
	private final SkillIcons icons = (label, skill) ->
	{
		assertTrue("icons are put on labels on the EDT", SwingUtilities.isEventDispatchThread());
		requests.add(skill);
		if (KNOWN.contains(skill))
		{
			Image image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
			shown.put(image, "skill " + skill);
			label.setIcon(new ImageIcon(image));
		}
	};

	private String iconText(Icon icon)
	{
		return icon instanceof ImageIcon ? shown.get(((ImageIcon) icon).getImage()) : null;
	}

	private static void onEdt(Runnable action)
	{
		try
		{
			SwingUtilities.invokeAndWait(action);
		}
		catch (InterruptedException | InvocationTargetException e)
		{
			throw new AssertionError(e.getCause() != null ? e.getCause() : e);
		}
	}

	private ItemListView xpList()
	{
		return new ItemListView(SkillXp.LIST_TITLE, false, ColorScheme.DARKER_GRAY_COLOR, SkillXp.LIST_NOUN, icons);
	}

	private PanelProbe.ItemListProbe probe(ItemListView list)
	{
		return new PanelProbe.ItemListProbe(list, this::iconText);
	}

	/** {@code count} skills of {@link #KNOWN}, the first with the most XP. */
	private static Map<String, Long> xp(int count)
	{
		Map<String, Long> xp = new LinkedHashMap<>();
		for (int i = 0; i < count; i++)
		{
			xp.put(KNOWN.get(i), (long) (count - i) * 100);
		}
		return xp;
	}

	@Test
	public void eachLineShowsItsSkillsIconBeforeTheName()
	{
		onEdt(() ->
		{
			ItemListView list = xpList();
			Map<String, Long> xp = new LinkedHashMap<>();
			xp.put("SLAYER", 1_500L);
			xp.put("HITPOINTS", 500L);
			list.setRows(SkillXp.rows(xp, 0));
			assertEquals(Arrays.asList("Slayer | 1,500", "Hitpoints | 500"), probe(list).getLineTexts());
			assertEquals(Arrays.asList("skill SLAYER 18x16", "skill HITPOINTS 18x16"), probe(list).getLineIcons());
			assertEquals(Arrays.asList("SLAYER", "HITPOINTS"), requests);
		});
	}

	@Test
	public void aLineWithNoSkillIconKeepsAnEmptySlotOfTheSameSize()
	{
		onEdt(() ->
		{
			ItemListView list = xpList();
			Map<String, Long> xp = new LinkedHashMap<>();
			xp.put("SLAYER", 200L);
			xp.put("FUTURE_SKILL", 100L);
			list.setRows(SkillXp.rows(xp, 0));
			assertEquals(Arrays.asList("Slayer | 200", "Future skill | 100"), probe(list).getLineTexts());
			assertEquals(Arrays.asList("skill SLAYER 18x16", "- 18x16"), probe(list).getLineIcons());
		});
	}

	@Test
	public void aLineWithNoSkillIsNotAskedForAnIcon()
	{
		onEdt(() ->
		{
			ItemListView list = xpList();
			list.setRows(Collections.singletonList(new ItemListView.Line()
			{
				@Override
				public String getName()
				{
					return "Total";
				}

				@Override
				public String getSkill()
				{
					return null;
				}

				@Override
				public String amountText()
				{
					return "1,000";
				}

				@Override
				public String tooltip()
				{
					return "Total";
				}
			}));
			assertEquals(Collections.singletonList("Total | 1,000"), probe(list).getLineTexts());
			assertEquals(Collections.singletonList("- 18x16"), probe(list).getLineIcons());
			assertEquals(Collections.emptyList(), requests);
		});
	}

	@Test
	public void theTopTenShowUntilMoreIsClickedWithTheirIcons()
	{
		onEdt(() ->
		{
			ItemListView list = xpList();
			List<Boolean> told = new ArrayList<>();
			list.setShowAll(false, told::add);
			list.setRows(SkillXp.rows(xp(12), 0));
			List<String> lines = probe(list).getLineTexts();
			assertEquals(11, lines.size());
			assertEquals("Attack | 1,200", lines.get(0));
			assertEquals("+2 more", lines.get(10));
			assertEquals(10, probe(list).getLineIcons().size());
			assertEquals("skill ATTACK 18x16", probe(list).getLineIcons().get(0));

			probe(list).clickShowAll();
			lines = probe(list).getLineTexts();
			assertEquals(13, lines.size());
			assertEquals("Show less", lines.get(12));
			assertEquals(12, probe(list).getLineIcons().size());
			assertEquals("skill CRAFTING 18x16", probe(list).getLineIcons().get(11));
			assertEquals(Collections.singletonList(true), told);
		});
	}

	@Test
	public void tooltipsAreTheRowsOwn()
	{
		onEdt(() ->
		{
			ItemListView list = xpList();
			List<SkillXp.Row> rows = SkillXp.rows(Collections.singletonMap("SLAYER", 1_500L), 3_600_000);
			list.setRows(rows);
			assertEquals(Collections.singletonList(rows.get(0).tooltip()), probe(list).getLineTooltips());
			assertEquals("<html>Slayer: 1,500 XP<br>1,500 XP per hour</html>", rows.get(0).tooltip());
		});
	}

	@Test
	public void fixedAndCollapsibleListsCountTheirRowsInTheTitleAlike()
	{
		onEdt(() ->
		{
			// The count covers every row, also those behind "+N more".
			ItemListView fixed = xpList();
			assertEquals("XP gained (0)", probe(fixed).getHeaderText());
			fixed.setRows(SkillXp.rows(xp(12), 0));
			assertEquals("XP gained (12)", probe(fixed).getHeaderText());

			ItemListView collapsible = new ItemListView(SkillXp.LIST_TITLE, true, ColorScheme.DARKER_GRAY_COLOR,
				SkillXp.LIST_NOUN, icons);
			collapsible.setRows(SkillXp.rows(xp(3), 0));
			assertEquals("XP gained (3) | Show", probe(collapsible).getHeaderText());
			collapsible.toggle();
			assertEquals("XP gained (3) | Hide", probe(collapsible).getHeaderText());
		});
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class ItemTallyTest
{
	@Test
	public void addAccumulatesAndIgnoresNonPositive()
	{
		ItemTally t = new ItemTally();
		t.add(995, 100);
		t.add(995, 50);
		t.add(526, 1);
		t.add(526, 0);
		t.add(1, -5);
		assertEquals(150, t.get(995));
		assertEquals(1, t.get(526));
		assertEquals(0, t.get(1));
		assertEquals(2, t.size());
		assertEquals(Arrays.asList(526, 995), Arrays.asList(t.itemIds().toArray()));
	}

	@Test
	public void mergeAddsQuantities()
	{
		ItemTally a = new ItemTally();
		a.add(995, 100);
		a.add(526, 2);
		ItemTally b = new ItemTally();
		b.add(995, 25);
		b.add(1215, 1);
		a.merge(b);
		assertEquals(125, a.get(995));
		assertEquals(2, a.get(526));
		assertEquals(1, a.get(1215));
		// the merged-in tally is unchanged
		assertEquals(25, b.get(995));
		assertEquals(2, b.size());

		a.merge(null);
		assertEquals(3, a.size());
	}

	@Test
	public void mergeIntoItselfDoubles()
	{
		ItemTally a = new ItemTally();
		a.add(995, 10);
		a.add(526, 1);
		a.merge(a);
		assertEquals(20, a.get(995));
		assertEquals(2, a.get(526));
	}

	@Test
	public void addSaturatesInsteadOfOverflowing()
	{
		ItemTally t = new ItemTally();
		t.add(995, Long.MAX_VALUE - 1);
		t.add(995, 10);
		assertEquals(Long.MAX_VALUE, t.get(995));
	}

	@Test
	public void copyIsIndependent()
	{
		ItemTally a = new ItemTally();
		a.add(995, 10);
		ItemTally copy = new ItemTally(a);
		a.add(995, 5);
		assertEquals(10, copy.get(995));
		assertEquals(0, new ItemTally(null).size());
	}

	@Test
	public void mapFormRoundTripsThroughJson()
	{
		ItemTally t = new ItemTally();
		t.add(995, 12_345);
		t.add(1216, 3);
		Map<Integer, Long> map = t.toMap();
		Gson gson = new Gson();
		Type type = new TypeToken<Map<Integer, Long>>()
		{
		}.getType();
		String json = gson.toJson(map, type);
		assertEquals("{\"995\":12345,\"1216\":3}", json);
		Map<Integer, Long> back = gson.fromJson(json, type);
		assertEquals(t, ItemTally.fromMap(back));
	}

	@Test
	public void emptyTallyHasNoMapAndNullMapIsEmpty()
	{
		assertNull(new ItemTally().toMap());
		assertTrue(ItemTally.fromMap(null).isEmpty());

		Map<Integer, Long> withJunk = new HashMap<>();
		withJunk.put(995, 5L);
		withJunk.put(526, 0L);
		withJunk.put(1, null);
		withJunk.put(null, 4L);
		ItemTally t = ItemTally.fromMap(withJunk);
		assertEquals(1, t.size());
		assertEquals(5, t.get(995));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class ItemValuationTest
{
	private static final int BONES = 526;
	private static final int RUNE_SCIMITAR = 1333;
	/** Fake noted id for RUNE_SCIMITAR. */
	private static final int RUNE_SCIMITAR_NOTED = 1334;
	/** Untradeable: no GE price, but an alchemy value. */
	private static final int UNTRADEABLE = 20_000;
	private static final int UNKNOWN = 30_000;

	/** Fake price source; records which ids were priced. */
	private static class FakeLookup implements ItemValuation.PriceLookup
	{
		final Map<Integer, Integer> noted = new HashMap<>();
		final Map<Integer, Long> ge = new HashMap<>();
		final Map<Integer, Long> ha = new HashMap<>();

		FakeLookup()
		{
			noted.put(RUNE_SCIMITAR_NOTED, RUNE_SCIMITAR);
			ge.put(BONES, 100L);
			ha.put(BONES, 0L);
			ge.put(RUNE_SCIMITAR, 15_000L);
			ha.put(RUNE_SCIMITAR, 15_360L);
			ha.put(UNTRADEABLE, 500L);
			// Coins' own alchemy value is not face value; the helper must override it.
			ge.put(ItemValuation.COINS, 1L);
			ha.put(ItemValuation.COINS, 0L);
		}

		@Override
		public int canonicalize(int itemId)
		{
			return noted.getOrDefault(itemId, itemId);
		}

		@Override
		public long gePrice(int canonicalId)
		{
			if (noted.containsKey(canonicalId))
			{
				throw new AssertionError("priced a noted id");
			}
			return ge.getOrDefault(canonicalId, 0L);
		}

		@Override
		public long haPrice(int canonicalId)
		{
			if (noted.containsKey(canonicalId))
			{
				throw new AssertionError("priced a noted id");
			}
			return ha.getOrDefault(canonicalId, 0L);
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return canonicalId != UNTRADEABLE;
		}
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	@Test
	public void totalsGeAndHa()
	{
		ItemTally loot = tally(BONES, 10, RUNE_SCIMITAR, 2);
		ItemValuation.UnitPrices prices = ItemValuation.capturePrices(loot, new FakeLookup());
		assertEquals(Long.valueOf(100), prices.getGe().get(BONES));
		assertEquals(Long.valueOf(15_360), prices.getHa().get(RUNE_SCIMITAR));
		assertEquals(10 * 100 + 2 * 15_000, ItemValuation.total(loot, prices.getGe()));
		assertEquals(2 * 15_360, ItemValuation.total(loot, prices.getHa()));
	}

	@Test
	public void coinsAndPlatinumAreFaceValue()
	{
		ItemTally loot = tally(ItemValuation.COINS, 5_000, ItemValuation.PLATINUM, 3);
		ItemValuation.UnitPrices prices = ItemValuation.capturePrices(loot, new FakeLookup());
		assertEquals(5_000 + 3_000, ItemValuation.total(loot, prices.getGe()));
		assertEquals(5_000 + 3_000, ItemValuation.total(loot, prices.getHa()));
	}

	@Test
	public void notedItemsUseUnnotedPricesButKeepTheirId()
	{
		ItemTally loot = tally(RUNE_SCIMITAR_NOTED, 4);
		ItemValuation.UnitPrices prices = ItemValuation.capturePrices(loot, new FakeLookup());
		assertEquals(Long.valueOf(15_000), prices.getGe().get(RUNE_SCIMITAR_NOTED));
		assertEquals(Long.valueOf(15_360), prices.getHa().get(RUNE_SCIMITAR_NOTED));
		assertEquals(60_000, ItemValuation.total(loot, prices.getGe()));
		assertEquals(61_440, ItemValuation.total(loot, prices.getHa()));
	}

	@Test
	public void untradeableIsZeroButTradeableWithoutPriceIsMissing()
	{
		ItemTally loot = tally(UNTRADEABLE, 2, UNKNOWN, 7, BONES, 1);
		ItemValuation.UnitPrices prices = ItemValuation.capturePrices(loot, new FakeLookup());
		// Untradeable: a known GE value of 0, alchemy value still counts.
		assertEquals(Long.valueOf(0), prices.getGe().get(UNTRADEABLE));
		// Tradeable at 0: the price is unavailable (not loaded, or not in the price list), not worthless.
		assertFalse(prices.getGe().containsKey(UNKNOWN));
		assertTrue(prices.getGeMissing().contains(UNKNOWN));
		assertEquals("its alchemy value is still known", Long.valueOf(0), prices.getHa().get(UNKNOWN));
		assertEquals(1, ItemValuation.countUnpriced(loot, prices.getGe()));
		assertEquals(100, ItemValuation.total(loot, prices.getGe()));
		assertEquals(1_000, ItemValuation.total(loot, prices.getHa()));
		// An id absent from the price map, or a null map, is 0.
		assertEquals(0, ItemValuation.total(tally(99, 5), prices.getGe()));
		assertEquals(0, ItemValuation.total(loot, null));
		assertEquals(0, ItemValuation.total(null, prices.getGe()));
	}

	@Test
	public void negativePricesAndFailingLookupsAreZero()
	{
		ItemValuation.PriceLookup broken = new ItemValuation.PriceLookup()
		{
			@Override
			public int canonicalize(int itemId)
			{
				if (itemId == UNKNOWN)
				{
					throw new IllegalStateException("no definition");
				}
				return itemId;
			}

			@Override
			public long gePrice(int canonicalId)
			{
				return -1;
			}

			@Override
			public long haPrice(int canonicalId)
			{
				return 7;
			}

			@Override
			public boolean isTradeable(int canonicalId)
			{
				return true;
			}
		};
		ItemTally loot = tally(UNKNOWN, 1, BONES, 2);
		ItemValuation.UnitPrices prices = ItemValuation.capturePrices(loot, broken);
		// A negative GE price of a tradeable item and a failing definition lookup are both unavailable.
		assertNull(prices.getGe().get(BONES));
		assertNull(prices.getGe().get(UNKNOWN));
		assertNull("a failed lookup has no alchemy value either", prices.getHa().get(UNKNOWN));
		assertEquals(Long.valueOf(7), prices.getHa().get(BONES));
		assertEquals(2, ItemValuation.countUnpriced(loot, prices.getGe()));
		assertEquals(0, ItemValuation.total(loot, prices.getGe()));
		assertEquals(14, ItemValuation.total(loot, prices.getHa()));
	}

	@Test
	public void totalSaturatesOnOverflow()
	{
		ItemTally loot = tally(BONES, Integer.MAX_VALUE);
		Map<Integer, Long> prices = new HashMap<>();
		prices.put(BONES, Long.MAX_VALUE / 2);
		assertEquals(Long.MAX_VALUE, ItemValuation.total(loot, prices));
	}

	/** Prices not loaded yet: ItemManager returns 0 for every item. */
	private static final class UnloadedLookup extends FakeLookup
	{
		@Override
		public long gePrice(int canonicalId)
		{
			return 0;
		}
	}

	@Test
	public void unloadedPricesAreMissingButCoinsAndPlatinumAreKnown()
	{
		ItemTally loot = tally(BONES, 3, RUNE_SCIMITAR, 1, ItemValuation.COINS, 500, ItemValuation.PLATINUM, 2);
		ItemValuation.UnitPrices prices = ItemValuation.capturePrices(loot, new UnloadedLookup());
		assertEquals(2, prices.getGe().size());
		assertEquals(Long.valueOf(1), prices.getGe().get(ItemValuation.COINS));
		assertEquals(Long.valueOf(ItemValuation.PLATINUM_VALUE), prices.getGe().get(ItemValuation.PLATINUM));
		assertTrue(prices.getGeMissing().contains(BONES));
		assertTrue(prices.getGeMissing().contains(RUNE_SCIMITAR));
		assertEquals("totals sum the known prices", 500 + 2_000, ItemValuation.total(loot, prices.getGe()));
		assertEquals(2, ItemValuation.countUnpriced(loot, prices.getGe()));
		// High alchemy comes from the item definition, which is available.
		assertEquals(Long.valueOf(15_360), prices.getHa().get(RUNE_SCIMITAR));
	}

	@Test
	public void recapturingReplacesAMissingPrice()
	{
		ItemTally loot = tally(BONES, 3);
		ItemValuation.UnitPrices prices = ItemValuation.capturePrices(loot, new UnloadedLookup());
		assertTrue(prices.getGeMissing().contains(BONES));
		ItemValuation.capturePrices(loot, new FakeLookup(), prices);
		assertEquals(Long.valueOf(100), prices.getGe().get(BONES));
		assertTrue(prices.getGeMissing().isEmpty());
		// And the other way: a price that becomes unavailable is removed, never left stale.
		ItemValuation.capturePrices(loot, new UnloadedLookup(), prices);
		assertFalse(prices.getGe().containsKey(BONES));
		assertTrue(prices.getGeMissing().contains(BONES));
	}

	@Test
	public void countUnpricedHandlesNulls()
	{
		assertEquals(0, ItemValuation.countUnpriced(null, new HashMap<>()));
		assertEquals(0, ItemValuation.countUnpriced(new ItemTally(), null));
		assertEquals(2, ItemValuation.countUnpriced(tally(BONES, 1, RUNE_SCIMITAR, 1), null));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * {@link KeysAndClues} and {@link ClueScrollIds}: counting keys and clue scrolls in a loot tally, their panel text, and
 * every id checked against the gameval {@link ItemID} constants of the RuneLite API the build resolves.
 */
public class KeysAndCluesTest
{
	/** Constant names of the top-level gameval ItemID ints, by value. */
	private static Map<Integer, String> itemIdNames() throws IllegalAccessException
	{
		Map<Integer, String> names = new HashMap<>();
		for (Field f : ItemID.class.getDeclaredFields())
		{
			int m = f.getModifiers();
			if (Modifier.isStatic(m) && Modifier.isFinal(m) && f.getType() == int.class)
			{
				names.put(f.getInt(null), f.getName());
			}
		}
		return names;
	}

	private static Map<Integer, Long> loot(long... idQuantityPairs)
	{
		Map<Integer, Long> loot = new TreeMap<>();
		for (int i = 0; i < idQuantityPairs.length; i += 2)
		{
			loot.put((int) idQuantityPairs[i], idQuantityPairs[i + 1]);
		}
		return loot;
	}

	@Test
	public void keyIdsAreTheGamevalKeys()
	{
		assertEquals(ItemID.KONAR_KEY, KeysAndClues.BRIMSTONE_KEY_IDS[0]);
		assertEquals(new HashSet<>(java.util.Arrays.asList(ItemID.KONAR_KEY, ItemID.KONAR_KEY_COUNTVIEW1,
			ItemID.KONAR_KEY_COUNTVIEW2, ItemID.KONAR_KEY_COUNTVIEW3, ItemID.KONAR_KEY_COUNTVIEW4,
			ItemID.KONAR_KEY_COUNTVIEW5, ItemID.KONAR_KEY_COUNTVIEW6)), toSet(KeysAndClues.BRIMSTONE_KEY_IDS));
		assertEquals(ItemID.SLAYER_WILDERNESS_KEY, KeysAndClues.LARRANS_KEY_IDS[0]);
		assertEquals(new HashSet<>(java.util.Arrays.asList(ItemID.SLAYER_WILDERNESS_KEY,
			ItemID.SLAYER_WILDERNESS_KEY_2, ItemID.SLAYER_WILDERNESS_KEY_4, ItemID.SLAYER_WILDERNESS_KEY_5)),
			toSet(KeysAndClues.LARRANS_KEY_IDS));
	}

	/**
	 * Every clue id is a gameval clue scroll constant of its tier ({@code TRAIL_..._<TIER>_...}), not a casket, key,
	 * challenge scroll, puzzle box or torn master clue part, and no id is in two tiers. The lists were generated from
	 * the item names in the API source; the constant names are checked here because names aren't in the class file.
	 */
	@Test
	public void clueIdsAreGamevalClueScrollsOfTheirTier() throws IllegalAccessException
	{
		Map<Integer, String> names = itemIdNames();
		Pattern notAClue = Pattern.compile("_(CASKET|KEY\\d*|CHALLENGE|PUZZLEBOX|PART\\d)$");
		Set<Integer> seen = new HashSet<>();
		int total = 0;
		for (KeysAndClues.ClueTier tier : KeysAndClues.ClueTier.values())
		{
			String upper = tier.name();
			Pattern ofTier = Pattern.compile("^TRAIL_(CLUE_)?" + upper + "(_|$)");
			for (int id : idsOf(tier))
			{
				String name = names.get(id);
				assertNotNull(tier + " id " + id + " is not a gameval ItemID", name);
				assertTrue(tier + " id " + id + " is " + name, ofTier.matcher(name).find());
				assertFalse(tier + " id " + id + " is " + name, notAClue.matcher(name).find());
				assertTrue("in one tier only: " + id, seen.add(id));
				total++;
			}
		}
		assertEquals("ids in API 1.13.4", 1 + 166 + 167 + 187 + 138 + 1, total);
		assertEquals(ItemID.TRAIL_CLUE_BEGINNER, ClueScrollIds.BEGINNER[0]);
		assertEquals(ItemID.TRAIL_CLUE_MASTER, ClueScrollIds.MASTER[0]);
		// The base ids core LootTrackerMapping uses are included.
		assertTrue(toSet(ClueScrollIds.EASY).contains(ItemID.TRAIL_CLUE_EASY_SIMPLE001));
		assertTrue(toSet(ClueScrollIds.MEDIUM).contains(ItemID.TRAIL_CLUE_MEDIUM_SEXTANT001));
		assertTrue(toSet(ClueScrollIds.HARD).contains(ItemID.TRAIL_CLUE_HARD_MAP001));
		assertTrue(toSet(ClueScrollIds.ELITE).contains(ItemID.TRAIL_ELITE_EMOTE_EXP1));
	}

	/**
	 * The reverse check: every gameval clue scroll constant of a tier is in that tier's list, so a RuneLite update that
	 * adds clue steps fails here instead of leaving them uncounted. Regenerate {@link ClueScrollIds} when it does.
	 */
	@Test
	public void everyGamevalClueScrollIsListed() throws IllegalAccessException
	{
		Map<Integer, String> names = itemIdNames();
		Pattern notAClue = Pattern.compile("_(CASKET|KEY\\d*|CHALLENGE|PUZZLEBOX|PART\\d)$");
		for (KeysAndClues.ClueTier tier : KeysAndClues.ClueTier.values())
		{
			Pattern ofTier = Pattern.compile("^TRAIL_(CLUE_)?" + tier.name() + "(_|$)");
			Set<Integer> listed = toSet(idsOf(tier));
			for (Map.Entry<Integer, String> e : new TreeMap<>(names).entrySet())
			{
				String name = e.getValue();
				if (ofTier.matcher(name).find() && !notAClue.matcher(name).find())
				{
					assertTrue(tier + " clue " + name + " (" + e.getKey() + ") is not listed", listed.contains(e.getKey()));
				}
			}
		}
	}

	private static int[] idsOf(KeysAndClues.ClueTier tier)
	{
		switch (tier)
		{
			case BEGINNER:
				return ClueScrollIds.BEGINNER;
			case EASY:
				return ClueScrollIds.EASY;
			case MEDIUM:
				return ClueScrollIds.MEDIUM;
			case HARD:
				return ClueScrollIds.HARD;
			case ELITE:
				return ClueScrollIds.ELITE;
			default:
				return ClueScrollIds.MASTER;
		}
	}

	private static Set<Integer> toSet(int[] ids)
	{
		Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return set;
	}

	@Test
	public void countsKeysAndCluesByTier()
	{
		KeysAndClues k = KeysAndClues.of(loot(ItemID.KONAR_KEY, 2, ItemID.SLAYER_WILDERNESS_KEY, 1,
			ItemID.TRAIL_CLUE_HARD_MAP001, 1, ClueScrollIds.HARD[5], 1, ItemID.TRAIL_ELITE_EMOTE_EXP1, 2,
			ItemID.TRAIL_CLUE_BEGINNER, 1, ItemID.COINS, 5000, ItemID.TRAIL_CLUE_HARD_SEXTANT001_CASKET, 1));
		assertEquals(2, k.getBrimstoneKeys());
		assertEquals(1, k.getLarransKeys());
		assertEquals(1, k.getClues(KeysAndClues.ClueTier.BEGINNER));
		assertEquals("a casket is not a clue scroll", 2, k.getClues(KeysAndClues.ClueTier.HARD));
		assertEquals(2, k.getClues(KeysAndClues.ClueTier.ELITE));
		assertEquals(0, k.getClues(KeysAndClues.ClueTier.MASTER));
		assertEquals("Keys: 2 brimstone, 1 Larran's", k.keysText());
		assertEquals("Clues: 1 beginner, 2 hard, 2 elite", k.cluesText());
	}

	@Test
	public void stackSizeVariantsCountAsTheKey()
	{
		KeysAndClues k = KeysAndClues.of(loot(ItemID.KONAR_KEY_COUNTVIEW3, 1, ItemID.SLAYER_WILDERNESS_KEY_5, 1));
		assertEquals(1, k.getBrimstoneKeys());
		assertEquals(1, k.getLarransKeys());
	}

	@Test
	public void nothingToShow()
	{
		assertSame(KeysAndClues.NONE, KeysAndClues.of((Map<Integer, Long>) null));
		assertSame(KeysAndClues.NONE, KeysAndClues.of((ItemTally) null));
		KeysAndClues k = KeysAndClues.of(loot(ItemID.COINS, 100));
		assertFalse(k.hasKeys());
		assertFalse(k.hasClues());
		assertNull(k.keysText());
		assertNull(k.cluesText());
		assertEquals("Keys: 1 Larran's", KeysAndClues.of(loot(ItemID.SLAYER_WILDERNESS_KEY, 1)).keysText());
		assertNull(KeysAndClues.of(loot(ItemID.SLAYER_WILDERNESS_KEY, 1)).cluesText());
	}

	@Test
	public void ignoresBadEntriesAndSaturates()
	{
		Map<Integer, Long> loot = new HashMap<>();
		loot.put(ItemID.KONAR_KEY, Long.MAX_VALUE);
		loot.put(ItemID.KONAR_KEY_COUNTVIEW1, 5L);
		loot.put(ItemID.SLAYER_WILDERNESS_KEY, -3L);
		loot.put(null, 4L);
		loot.put(ItemID.TRAIL_CLUE_MASTER, null);
		KeysAndClues k = KeysAndClues.of(loot);
		assertEquals(Long.MAX_VALUE, k.getBrimstoneKeys());
		assertEquals(0, k.getLarransKeys());
		assertFalse(k.hasClues());
	}

	@Test
	public void fromATally()
	{
		ItemTally tally = new ItemTally();
		tally.add(ItemID.TRAIL_CLUE_MASTER, 1);
		assertEquals("Clues: 1 master", KeysAndClues.of(tally).cluesText());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * {@link KillCountMessage}: the message texts are the ones core's ChatCommandsPluginTest (RuneLite 1.13.4, tag
 * {@code runelite-parent-1.13.4}) feeds core's KILLCOUNT_PATTERN.
 */
public class KillCountMessageTest
{
	private static KillCountMessage.Result parse(String message)
	{
		return KillCountMessage.parse(true, message);
	}

	private static void assertBossKill(String message, String boss, int kc)
	{
		KillCountMessage.Result result = parse(message);
		assertEquals(message, new KillCountMessage.Result(boss, kc, true), result);
	}

	private static void assertOtherCount(String message, String name, int kc)
	{
		KillCountMessage.Result result = parse(message);
		assertEquals(message, new KillCountMessage.Result(name, kc, false), result);
	}

	@Test
	public void bossKillCounts()
	{
		assertBossKill("Your Corporeal Beast kill count is: <col=ff0000>4</col>.", "Corporeal Beast", 4);
		assertBossKill("Your Kree'arra kill count is: <col=ff0000>4</col>.", "Kree'arra", 4);
		assertBossKill("Your TzKal-Zuk kill count is: <col=ff0000>2</col>.", "TzKal-Zuk", 2);
		assertBossKill("Your TzTok-Jad kill count is: <col=ff0000>2</col>.", "TzTok-Jad", 2);
		assertBossKill("Your Grotesque Guardians kill count is: <col=ff0000>179</col>.", "Grotesque Guardians", 179);
		assertBossKill("Your Tempoross kill count is: <col=ff0000>60</col>.", "Tempoross", 60);
	}

	@Test
	public void noFullStopAndThousandsSeparators()
	{
		assertBossKill("Your Nightmare kill count is: <col=ff0000>1130</col>", "Nightmare", 1130);
		assertBossKill("Your Nightmare kill count is: <col=ff0000>1,130</col>", "Nightmare", 1130);
	}

	@Test
	public void colouredBossNamesAndNoSpaceBeforeTheCount()
	{
		assertBossKill("Your <col=a53fff>Corrupted Hunllef (Echo)</col> kill count is: <col=ff3045>31</col>",
			"Corrupted Hunllef (Echo)", 31);
		assertBossKill("Your <col=6800bf>Kalphite Queen (Echo)</col> kill count is:<col=e00a19>1</col>",
			"Kalphite Queen (Echo)", 1);
	}

	@Test
	public void bareCountIsABossKill()
	{
		assertBossKill("Your Barrows chest count is: <col=ff0000>277</col>.", "Barrows chest", 277);
	}

	@Test
	public void otherCountsParseButAreNotBossKills()
	{
		assertOtherCount("Your completed Theatre of Blood count is: <col=ff0000>73</col>.", "Theatre of Blood", 73);
		assertOtherCount("Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>1</col>.",
			"Tombs of Amascut: Expert Mode", 1);
		assertOtherCount("Your completion count for TzHaar-Ket-Rak's First Challenge is: <col=ff0000>1</col>.",
			"TzHaar-Ket-Rak's First Challenge", 1);
		assertOtherCount("Your subdued Wintertodt count is: <col=ff0000>4</col>.", "Wintertodt", 4);
		assertOtherCount("Your herbiboar harvest count is: <col=ff0000>4091</col>.", "herbiboar", 4091);
		assertOtherCount("Your Gauntlet completion count is: <col=ff0000>123</col>.", "Gauntlet", 123);
		assertOtherCount("Your Prifddinas Agility Course lap count is: @mes_hl_red@2</col>.",
			"Prifddinas Agility Course", 2);
		assertOtherCount("Your Agility Arena Total Ticket count is: <col=ff0000>206</col>.", "Agility Arena", 206);
		assertFalse(parse("Your completed Chambers of Xeric count is: <col=ff0000>51</col>.").isBossKill());
	}

	@Test
	public void notKillCounts()
	{
		assertNull("wrong chat type", KillCountMessage.parse(false,
			"Your Kree'arra kill count is: <col=ff0000>4</col>."));
		assertNull(parse(null));
		assertNull("the count must be coloured, as in core", parse("Your Kree'arra kill count is: 4."));
		assertNull("no prefix or count word: core ignores it", parse("Your Kree'arra is: <col=ff0000>4</col>."));
		assertNull("too large", parse("Your Kree'arra kill count is: <col=ff0000>99,999,999,999</col>."));
		assertNull(parse("A superior foe has appeared..."));
		assertNull(parse("Fight duration: <col=ff0000>1:23</col>. Personal best: 1:01"));
	}

	@Test
	public void bossNameHasNoTagsLeft()
	{
		KillCountMessage.Result result = parse("Your <col=ff0000>Vorkath</col> kill count is: <col=ff0000>9</col>.");
		assertEquals("Vorkath", result.getBoss());
		assertTrue(result.isBossKill());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link LedgerHistoryModel} without the panel or the plugin: the history it holds, its version, and the
 * decisions it makes on its own (the new-task chat preview and the overlay's historical time per kill).
 * {@link HarnessHistoryModelTest} covers the wiring.
 */
public class LedgerHistoryModelTest
{
	private static final long ACCOUNT = 1L;
	private static final long OTHER_ACCOUNT = 2L;
	private static final int DEMONS = 42;
	private static final long MINUTE = 60_000L;
	private static final int SHARK = 385;

	private final List<String> posted = new ArrayList<>();
	private final List<OverlayRows.HistoricalPace> published = new ArrayList<>();
	private final List<Set<Integer>> priceRequests = new ArrayList<>();
	private long now = 1_000_000L;
	private SessionTracker tracker;
	private LedgerHistoryModel model;

	@Before
	public void setUp()
	{
		tracker = new SessionTracker(() -> now);
		model = new LedgerHistoryModel(tracker, LootPriceMode.GE, regions ->
		{
		}, priceRequests::add, ids ->
		{
		}, posted::add, published::add,
			Runnable::run, Runnable::run);
	}

	/**
	 * A completed Abyssal demons task ended at {@code endedAt}: 10 kills in 10 minutes, loot 100K GE, 1 bank trip. It
	 * has totals but no per-item prices, so it keeps them, marked {@code ~}.
	 */
	private static LedgerRecord task(String id, long endedAt)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(id);
		record.setCreatureId(DEMONS);
		record.setMonster("Abyssal demons");
		record.setKills(10);
		record.setActiveMillis(10 * MINUTE);
		record.setCompleted(true);
		record.setLootGeValue(100_000L);
		record.setLootHaValue(200_000L);
		record.setSuppliesGeValue(10_000L);
		record.setBankTrips(1);
		record.setEndedAt(endedAt);
		return record;
	}

	private static AssignmentEntry entry(String id, long endedAt)
	{
		AssignmentEntry entry = new AssignmentEntry();
		entry.setId(id);
		entry.setMonster("Abyssal demons");
		entry.setEndedAt(endedAt);
		entry.setOutcome(AssignmentOutcome.SKIPPED);
		return entry;
	}

	/** Today's GE prices of the bones (5,000 gp) and coins (1 gp) of the hidden-loot test. */
	private static Map<Integer, Long> prices(int bones, int coins)
	{
		Map<Integer, Long> prices = new HashMap<>();
		prices.put(bones, 5_000L);
		prices.put(coins, 1L);
		return prices;
	}

	/** The tracker sees an Abyssal demons task with {@code remaining} kills left. */
	private void demons(int remaining)
	{
		tracker.observe("Abyssal demons", DEMONS, remaining, false);
	}

	@Test
	public void theVersionChangesWithEveryHistoryChange()
	{
		long version = model.version();
		assertTrue(model.setRecords(ACCOUNT, Collections.singletonList(task("a", 1))));
		assertTrue(model.version() > version);

		version = model.version();
		assertTrue(model.setAssignments(ACCOUNT, Collections.singletonList(entry("s", 1))));
		assertTrue(model.version() > version);

		version = model.version();
		assertFalse("another account's entries are ignored",
			model.setAssignments(OTHER_ACCOUNT, Collections.singletonList(entry("t", 2))));
		assertEquals(version, model.version());
		assertEquals(1, model.assignments().size());

		model.clearRecords(ACCOUNT, null);
		assertTrue(model.version() > version);
		assertTrue(model.records().isEmpty());
		assertTrue("a message drops the entries too", model.assignments().isEmpty());
		assertFalse(model.isLoaded());
	}

	@Test
	public void theViewsAreUnmodifiableSortedCopies()
	{
		List<LedgerRecord> records = new ArrayList<>(Arrays.asList(task("old", 1), task("new", 2)));
		List<AssignmentEntry> entries = new ArrayList<>(Arrays.asList(entry("old", 1), entry("new", 2)));
		model.setRecords(ACCOUNT, records);
		model.setAssignments(ACCOUNT, entries);
		records.clear();
		entries.clear();

		assertEquals("newest first, and not the caller's list", Arrays.asList("new", "old"),
			Arrays.asList(model.records().get(0).getId(), model.records().get(1).getId()));
		assertEquals(Arrays.asList("new", "old"),
			Arrays.asList(model.assignments().get(0).getId(), model.assignments().get(1).getId()));
		assertTrue(model.isLoaded());
		assertEquals(ACCOUNT, model.account());
		assertUnmodifiable(model.records(), task("x", 3));
		assertUnmodifiable(model.assignments(), entry("x", 3));
	}

	private static <T> void assertUnmodifiable(List<T> list, T element)
	{
		try
		{
			list.add(element);
		}
		catch (UnsupportedOperationException expected)
		{
			return;
		}
		throw new AssertionError("the list can be changed");
	}

	@Test
	public void thePreviewWaitsForTheRecordsThenPostsOnce()
	{
		demons(20);
		model.requestAssignmentPreview(ACCOUNT, DEMONS, "Abyssal demons");
		assertTrue("another account's (none) history is held", posted.isEmpty());
		assertFalse("dropped: the history held is not the account's", model.isAssignmentPreviewPending());

		model.clearRecords(ACCOUNT, null);
		model.requestAssignmentPreview(ACCOUNT, DEMONS, "Abyssal demons");
		model.checkAssignmentPreview();
		assertTrue("waits while the records load", model.isAssignmentPreviewPending());
		assertTrue(posted.isEmpty());

		model.setRecords(ACCOUNT, Arrays.asList(SavedItems.withItems(task("a", 1)), SavedItems.withItems(task("b", 2)),
			SavedItems.withItems(task("c", 3))));
		model.checkAssignmentPreview();
		assertTrue("waits for today's prices", posted.isEmpty());
		model.addCurrentPrices(priceRequests.get(priceRequests.size() - 1), SavedItems.todaysPrices());
		model.checkAssignmentPreview();
		model.refreshLive();
		model.checkAssignmentPreview();
		assertEquals(Collections.singletonList(
			"Abyssal demons (20): ~0:20:00 · +180K (GE) · ~2 bank trips (from 3 tasks)"), posted);
		assertFalse(model.isAssignmentPreviewPending());
	}

	@Test
	public void thePreviewWaitsForTheNamesThatDecideTheHiddenLoot()
	{
		final int bones = 526;
		final int coins = ItemValuation.COINS;
		// Ground Items' built-in list hides both; only the bones leave the value (coins always count).
		model.setGroundItemsHidden(GroundItemsHidden.parse("Coins, Bones", ""));
		List<LedgerRecord> records = new ArrayList<>();
		for (String id : Arrays.asList("a", "b", "c"))
		{
			// 50K of bones and 50K of coins: the 100K GE of task().
			LedgerRecord record = task(id, 1);
			Map<Integer, Long> loot = new HashMap<>();
			loot.put(bones, 10L);
			loot.put(coins, 50_000L);
			Map<Integer, Long> prices = new HashMap<>();
			prices.put(bones, 5_000L);
			prices.put(coins, 1L);
			record.setLoot(loot);
			record.setUnitGePrices(prices);
			record.setUnitHaPrices(prices);
			// Supplies are valued per item at today's prices too: 10K of supplies, as task() saved.
			record.setSupplies(Collections.singletonMap(SHARK, 10L));
			records.add(record);
		}
		model.clearRecords(ACCOUNT, null);
		demons(20);
		model.requestAssignmentPreview(ACCOUNT, DEMONS, "Abyssal demons");

		model.setRecords(ACCOUNT, records);
		model.refreshLive();
		assertTrue("waits for today's prices", posted.isEmpty());
		Map<Integer, Long> today = new HashMap<>(prices(bones, coins));
		today.put(SHARK, 1_000L);
		model.addCurrentPrices(priceRequests.get(priceRequests.size() - 1), today);
		model.refreshLive();
		assertTrue("waits for the loot items' names", posted.isEmpty());
		assertTrue(model.isAssignmentPreviewPending());

		Map<Integer, String> names = new HashMap<>();
		names.put(bones, "Bones");
		names.put(coins, "Coins");
		model.addItemNames(new HashSet<>(Arrays.asList(bones, coins)), names, null);
		assertEquals("posted with the bones left out and the coins counted", Collections.singletonList(
			"Abyssal demons (20): ~0:20:00 · +80K (GE) · ~2 bank trips (from 3 tasks)"), posted);
		assertFalse(model.isAssignmentPreviewPending());
	}

	@Test
	public void thePreviewIsDroppedWhenTheTaskChanges()
	{
		model.setRecords(ACCOUNT, Collections.singletonList(task("a", 1)));
		model.clearRecords(ACCOUNT, null);
		demons(20);
		model.requestAssignmentPreview(ACCOUNT, DEMONS, "Abyssal demons");
		tracker.observe("Gargoyles", 46, 15, false);
		model.checkAssignmentPreview();

		assertFalse(model.isAssignmentPreviewPending());
		model.setRecords(ACCOUNT, Collections.singletonList(task("a", 1)));
		model.checkAssignmentPreview();
		assertTrue(posted.isEmpty());
	}

	@Test
	public void thePreviewWaitsForTodaysPrices()
	{
		LedgerRecord record = task("a", 1);
		record.setLoot(Collections.singletonMap(995, 1L));
		model.setRecords(ACCOUNT, Collections.singletonList(record));
		model.setRecords(ACCOUNT, Collections.singletonList(record));
		assertEquals("asked once", 1, priceRequests.size());
		assertTrue(model.isWaitingForCurrentPrices());

		demons(20);
		model.requestAssignmentPreview(ACCOUNT, DEMONS, "Abyssal demons");
		assertTrue(model.isAssignmentPreviewPending());

		model.addCurrentPrices(priceRequests.get(0), Collections.singletonMap(995, 1L));
		model.endCurrentPricesWait();
		model.checkAssignmentPreview();
		assertEquals(1, posted.size());
	}

	@Test
	public void anExpiredWaitForTodaysPricesEndsInTheModelAndPostsThePreview()
	{
		final int[] redraws = new int[1];
		model.setListener(change ->
		{
			if (change == LedgerHistoryModel.Change.PRICED_VIEWS)
			{
				redraws[0]++;
			}
		});
		LedgerRecord record = task("a", 1);
		record.setLoot(Collections.singletonMap(995, 1L));
		// Another account's records never wait; the same account's again do.
		model.setRecords(ACCOUNT, Collections.singletonList(record));
		model.setRecords(ACCOUNT, Collections.singletonList(record));
		assertTrue(model.isWaitingForCurrentPrices());
		demons(20);
		model.requestAssignmentPreview(ACCOUNT, DEMONS, "Abyssal demons");

		assertFalse("not run out yet", model.endExpiredCurrentPricesWait());
		model.refreshLive();
		assertTrue(posted.isEmpty());
		assertEquals(0, redraws[0]);

		// The answer never comes.
		model.expireCurrentPricesWait();
		model.refreshLive();
		assertFalse(model.isWaitingForCurrentPrices());
		assertEquals(1, posted.size());
		assertEquals("the panel is told to redraw once", 1, redraws[0]);
		assertFalse("nothing more to end", model.endExpiredCurrentPricesWait());
		model.refreshLive();
		assertEquals("posted once", 1, posted.size());
		assertEquals(1, redraws[0]);
	}

	@Test
	public void theOverlayPaceFollowsTheRecordsAndTheSession()
	{
		demons(12);
		assertTrue(tracker.play(ACCOUNT));
		model.setRecords(ACCOUNT, Collections.singletonList(task("a", 1)));
		OverlayRows.HistoricalPace pace = published.get(published.size() - 1);
		assertNotNull("published when the records arrive", pace);
		assertEquals(new OverlayRows.HistoricalPace(tracker.getSessionId(), MINUTE), pace);
		assertEquals(pace, model.historicalPace());

		model.clearRecords(ACCOUNT, null);
		assertNull("no history, no pace", published.get(published.size() - 1));

		model.setRecords(ACCOUNT, Collections.singletonList(task("a", 1)));
		assertNotNull(published.get(published.size() - 1));
		assertTrue(tracker.stop());
		model.refreshLive();
		assertNull("no session, no pace", published.get(published.size() - 1));

		int count = published.size();
		model.shutDown();
		model.refreshLive();
		model.setRecords(ACCOUNT, Collections.emptyList());
		assertEquals("nothing is published after shutDown", count, published.size());
	}

	@Test
	public void todaysPricesArrivingRevalueTheCachedViewsOnce()
	{
		LedgerRecord record = task("a", 1);
		record.setLoot(Collections.singletonMap(995, 1L));
		record.setUnitGePrices(Collections.singletonMap(995, 1L));
		model.setRecords(ACCOUNT, Collections.singletonList(record));
		assertEquals("asked once, without a box to tick", 1, priceRequests.size());
		demons(20);

		model.advice();
		model.overallTotals(OverallTotals.Grouping.ALL);
		model.ranking(TaskRanking.Metric.PROFIT);
		long valuation = model.valuationVersion();
		int adviceBuilds = model.getAdviceBuildCount();
		int totalsBuilds = model.getOverallTotalsBuildCount();
		int rankingBuilds = model.getRankingBuildCount();
		model.advice();
		assertEquals("cached until the prices arrive", adviceBuilds, model.getAdviceBuildCount());

		model.addCurrentPrices(priceRequests.get(0), Collections.singletonMap(995, 1L));
		assertTrue("today's prices revalue the history", model.valuationVersion() > valuation);
		model.advice();
		model.overallTotals(OverallTotals.Grouping.ALL);
		model.ranking(TaskRanking.Metric.PROFIT);
		assertEquals(adviceBuilds + 1, model.getAdviceBuildCount());
		assertEquals(totalsBuilds + 1, model.getOverallTotalsBuildCount());
		assertEquals(rankingBuilds + 1, model.getRankingBuildCount());
		model.advice();
		model.overallTotals(OverallTotals.Grouping.ALL);
		model.ranking(TaskRanking.Metric.PROFIT);
		assertEquals("then cached again", adviceBuilds + 1, model.getAdviceBuildCount());
		assertEquals(totalsBuilds + 1, model.getOverallTotalsBuildCount());
		assertEquals(rankingBuilds + 1, model.getRankingBuildCount());
	}

	/** A record of {@link #task} with one of each of {@code items} in its loot. */
	private static LedgerRecord withLoot(String id, long endedAt, int... items)
	{
		LedgerRecord record = task(id, endedAt);
		Map<Integer, Long> loot = new HashMap<>();
		for (int item : items)
		{
			loot.put(item, 1L);
		}
		record.setLoot(loot);
		return record;
	}

	@Test
	public void anAnswerWithoutANewPriceRedrawsNothingButStillEndsTheWait()
	{
		final int[] changes = new int[2];
		model.setListener(change ->
		{
			if (change == LedgerHistoryModel.Change.CURRENT_PRICES)
			{
				changes[0]++;
			}
			else if (change == LedgerHistoryModel.Change.PRICED_VIEWS)
			{
				changes[1]++;
			}
		});
		LedgerRecord coins = withLoot("a", 1, 995);
		// Another account's records never wait.
		model.setRecords(ACCOUNT, Collections.singletonList(coins));
		model.addCurrentPrices(priceRequests.get(0), Collections.singletonMap(995, 1L));
		assertEquals("a new price redraws", 1, changes[0]);
		long version = model.valuationVersion();

		// The same price again, and an answer that found nothing: nothing new, nothing redrawn.
		model.addCurrentPrices(Collections.singleton(995), Collections.singletonMap(995, 1L));
		model.addCurrentPrices(Collections.singleton(7), Collections.emptyMap());
		assertEquals(version, model.valuationVersion());
		assertEquals(1, changes[0]);

		// A changed price is new.
		model.addCurrentPrices(Collections.singleton(995), Collections.singletonMap(995, 2L));
		assertTrue(model.valuationVersion() > version);
		assertEquals(2, changes[0]);
		version = model.valuationVersion();

		// The last answer a wait asked for ends it even when it adds nothing.
		model.setRecords(ACCOUNT, Arrays.asList(coins, withLoot("b", 2, 7)));
		assertTrue(model.isWaitingForCurrentPrices());
		model.addCurrentPrices(priceRequests.get(priceRequests.size() - 1), Collections.emptyMap(),
			Collections.emptySet());
		assertFalse(model.isWaitingForCurrentPrices());
		assertFalse(model.isCurrentPricesPending());
		assertEquals("the views are redrawn once", 1, changes[1]);
		assertEquals(version, model.valuationVersion());
		assertEquals(2, changes[0]);
	}

	@Test
	public void aWaitHoldsForPricesLookedUpAgainUntilTheyArriveRunOutOrTheHistoryIsCleared()
	{
		final int[] redraws = new int[1];
		model.setListener(change ->
		{
			if (change == LedgerHistoryModel.Change.PRICED_VIEWS)
			{
				redraws[0]++;
			}
		});
		// As at client start, before RuneLite's price list has loaded: the answer has no price for item 7.
		LedgerRecord first = withLoot("a", 1, 995, 7);
		model.setRecords(ACCOUNT, Collections.singletonList(first));
		model.setRecords(ACCOUNT, Collections.singletonList(first));
		assertTrue(model.isWaitingForCurrentPrices());
		model.addCurrentPrices(priceRequests.get(0), Collections.singletonMap(995, 1L), Collections.singleton(7));
		assertFalse("answered", model.isCurrentPricesPending());
		assertTrue("but item 7 is looked up again", model.isWaitingForCurrentPrices());
		assertEquals(0, redraws[0]);

		// The retry finds it: the wait ends with one redraw.
		model.addCurrentPrices(Collections.singleton(7), Collections.singletonMap(7, 100L));
		assertFalse(model.isWaitingForCurrentPrices());
		assertEquals(1, redraws[0]);

		// A price that never turns up: the wait still runs out.
		LedgerRecord second = withLoot("b", 2, 8);
		model.setRecords(ACCOUNT, Arrays.asList(first, second));
		model.addCurrentPrices(priceRequests.get(priceRequests.size() - 1), Collections.emptyMap(),
			Collections.singleton(8));
		assertTrue(model.isWaitingForCurrentPrices());
		assertFalse("not run out yet", model.endExpiredCurrentPricesWait());
		model.expireCurrentPricesWait();
		assertTrue(model.endExpiredCurrentPricesWait());
		assertFalse(model.isWaitingForCurrentPrices());
		assertEquals(2, redraws[0]);

		// And clearing the history ends it too.
		model.setRecords(ACCOUNT, Arrays.asList(first, second, withLoot("c", 3, 9)));
		model.addCurrentPrices(priceRequests.get(priceRequests.size() - 1), Collections.emptyMap(),
			Collections.singleton(9));
		assertTrue(model.isWaitingForCurrentPrices());
		model.clearRecords(ACCOUNT, null);
		assertFalse(model.isWaitingForCurrentPrices());

		// Prices looked up again while nothing waits hold nothing back later.
		model.setRecords(OTHER_ACCOUNT, Collections.singletonList(withLoot("d", 4, 10)));
		assertFalse(model.isWaitingForCurrentPrices());
		model.addCurrentPrices(priceRequests.get(priceRequests.size() - 1), Collections.emptyMap(),
			Collections.singleton(10));
		model.setRecords(OTHER_ACCOUNT, Arrays.asList(withLoot("d", 4, 10), withLoot("e", 5, 11)));
		assertTrue(model.isWaitingForCurrentPrices());
		model.addCurrentPrices(priceRequests.get(priceRequests.size() - 1), Collections.singletonMap(11, 5L),
			Collections.emptySet());
		assertFalse("only the ids of this wait hold it", model.isWaitingForCurrentPrices());
	}
}

package com.shmayvan.slayerledger;

