	// ---- Kept (unsaved) records ----

	private String[] unsavedNames(long account)
	{
		final String prefix = account + ".unsaved-";
		return dir.exists() ? Arrays.stream(dir.list()).filter(n -> n.startsWith(prefix)).sorted().toArray(String[]::new)
			: new String[0];
	}

