package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import javax.swing.JTextField;
import org.junit.Test;

/** {@link LengthLimitFilter}: typing, pasting and replacing never take a field past its limit. */
public class LengthLimitFilterTest
{
	@Test
	public void textPastTheLimitIsCut()
	{
		JTextField field = new JTextField();
		LengthLimitFilter.apply(field, 5);
		field.setText("abcdefgh");
		assertEquals("abcde", field.getText());
		field.replaceSelection("x");
		assertEquals("full, so nothing is added", "abcde", field.getText());
		field.select(1, 3);
		field.replaceSelection("XYZW");
		assertEquals("a replaced selection makes room", "aXYde", field.getText());
		field.setText("");
		assertEquals("", field.getText());
		field.setText("ab");
		field.setCaretPosition(2);
		field.replaceSelection("cdefg");
		assertEquals("abcde", field.getText());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/** The kills per region of a session: adding, the dominant region and its ties, and cleaning a stored tally. */
public class LocationTallyTest
{
	private static final int SMOKE = 12_946;
	private static final int CATACOMBS = 6_557;
	private static final int TOWER = 13_623;

	@Test
	public void addsKillsPerRegionInTheOrderFirstSeen()
	{
		List<LocationKills> tally = LocationTally.add(null, SMOKE, 3);
		tally = LocationTally.add(tally, CATACOMBS, 1);
		List<LocationKills> before = tally;
		tally = LocationTally.add(tally, SMOKE, 2);
		assertEquals(Arrays.asList(new LocationKills(SMOKE, 5), new LocationKills(CATACOMBS, 1)), tally);
		assertEquals("the list passed in is not changed",
			Arrays.asList(new LocationKills(SMOKE, 3), new LocationKills(CATACOMBS, 1)), before);
	}

	@Test
	public void containsOnlyTalliedRegions()
	{
		List<LocationKills> tally = LocationTally.add(null, SMOKE, 2);
		assertTrue(LocationTally.contains(tally, SMOKE));
		assertFalse(LocationTally.contains(tally, CATACOMBS));
		assertFalse(LocationTally.contains(tally, LocationTally.NO_REGION));
		assertFalse(LocationTally.contains(null, SMOKE));
		assertFalse("no kills", LocationTally.contains(Collections.singletonList(new LocationKills(SMOKE, 0)), SMOKE));
	}

	@Test
	public void unknownRegionsAndNoKillsAreNotTallied()
	{
		List<LocationKills> tally = LocationTally.add(null, LocationTally.NO_REGION, 4);
		assertTrue(tally.isEmpty());
		tally = LocationTally.add(tally, SMOKE, 0);
		tally = LocationTally.add(tally, SMOKE, -2);
		assertTrue(tally.isEmpty());
		assertNull(LocationTally.dominantRegion(tally));
		assertNull(LocationTally.dominantRegion(null));
	}

	@Test
	public void theDominantRegionHasTheMostKillsAndTiesGoToTheEarliestSeen()
	{
		List<LocationKills> tally = LocationTally.add(null, SMOKE, 2);
		tally = LocationTally.add(tally, CATACOMBS, 3);
		assertEquals(Integer.valueOf(CATACOMBS), LocationTally.dominantRegion(tally));
		tally = LocationTally.add(tally, SMOKE, 1);
		assertEquals("a tie goes to the region seen first", Integer.valueOf(SMOKE), LocationTally.dominantRegion(tally));
		tally = LocationTally.add(tally, TOWER, 3);
		assertEquals("a later region needs more kills, not as many", Integer.valueOf(SMOKE),
			LocationTally.dominantRegion(tally));
		tally = LocationTally.add(tally, TOWER, 1);
		assertEquals(Integer.valueOf(TOWER), LocationTally.dominantRegion(tally));
	}

	@Test
	public void killsSaturate()
	{
		List<LocationKills> tally = LocationTally.add(null, SMOKE, Integer.MAX_VALUE - 1);
		tally = LocationTally.add(tally, SMOKE, 5);
		assertEquals(Collections.singletonList(new LocationKills(SMOKE, Integer.MAX_VALUE)), tally);
	}

	@Test
	public void atMostMaxRegionsAreTallied()
	{
		List<LocationKills> tally = null;
		for (int region = 0; region < LocationTally.MAX_REGIONS + 3; region++)
		{
			tally = LocationTally.add(tally, region, 1);
		}
		assertEquals(LocationTally.MAX_REGIONS, tally.size());
		tally = LocationTally.add(tally, 0, 1);
		assertEquals("a tallied region still counts", 2, tally.get(0).getKills());
	}

	@Test
	public void sanitizeDropsBadEntriesAndMergesRepeats()
	{
		List<LocationKills> stored = new ArrayList<>(Arrays.asList(new LocationKills(SMOKE, 2), null,
			new LocationKills(-5, 3), new LocationKills(CATACOMBS, 0), new LocationKills(CATACOMBS, 4),
			new LocationKills(SMOKE, 3)));
		assertEquals(Arrays.asList(new LocationKills(SMOKE, 5), new LocationKills(CATACOMBS, 4)),
			LocationTally.sanitize(stored));
		assertTrue(LocationTally.sanitize(null).isEmpty());
		assertEquals("repeats count together once cleaned", Integer.valueOf(SMOKE),
			LocationTally.dominantRegion(LocationTally.sanitize(stored)));
		assertEquals("a bad entry never wins", Integer.valueOf(SMOKE),
			LocationTally.dominantRegion(Arrays.asList(new LocationKills(-5, 9), new LocationKills(CATACOMBS, 0),
				new LocationKills(SMOKE, 1))));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * The combined capture-time loot filter: crushed bones and ashes ({@link CrushedLootFilter}) and the player's ignored
 * items ({@link IgnoredLoot}).
 */
public class LootFilterTest
{
	private static final Map<Integer, String> NAMES = new HashMap<>();

	static
	{
		NAMES.put(ItemID.WYRM_BONES, "Wyrm bones");
		NAMES.put(ItemID.ABYSSAL_ASHES, "Abyssal ashes");
		NAMES.put(ItemID.COINS, "Coins");
		NAMES.put(ItemID.DRAGON_BONES, "Dragon bones");
		NAMES.put(ItemID.RANARR_SEED, "Ranarr seed");
	}

	/** Item facts as the plugin reads them; records every lookup. */
	private static final class FakeNames implements LootFilter.ItemNames
	{
		final List<String> calls = new ArrayList<>();

		@Override
		public int unnoted(int itemId)
		{
			calls.add("unnoted " + itemId);
			return itemId == ItemID.Cert.DRAGON_BONES ? ItemID.DRAGON_BONES : itemId;
		}

		@Override
		public String name(int itemId)
		{
			calls.add("name " + itemId);
			return NAMES.get(itemId);
		}
	}

	private static ItemTally drop()
	{
		ItemTally loot = new ItemTally();
		loot.add(ItemID.WYRM_BONES, 1);
		loot.add(ItemID.ABYSSAL_ASHES, 1);
		loot.add(ItemID.COINS, 300);
		loot.add(ItemID.Cert.DRAGON_BONES, 5);
		loot.add(ItemID.RANARR_SEED, 2);
		return loot;
	}

	private static CrushedLootFilter crusher()
	{
		return CrushedLootFilter.forDrop(BonecrusherMode.AUTO, Collections.singletonList(ItemID.BONECRUSHER));
	}

	@Test
	public void keepsEverythingWithoutCrusherOrIgnoredItemsAndLooksNothingUp()
	{
		FakeNames names = new FakeNames();
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.NONE).apply(drop(), names);
		assertEquals(drop(), kept);
		assertTrue("no item lookups when nothing is ignored", names.calls.isEmpty());
	}

	@Test
	public void combinesTheCrusherAndTheIgnoredItems()
	{
		ItemTally kept = new LootFilter(crusher(), IgnoredLoot.parse("coins, *seed")).apply(drop(), new FakeNames());
		assertEquals(0, kept.get(ItemID.WYRM_BONES));
		assertEquals(0, kept.get(ItemID.COINS));
		assertEquals(0, kept.get(ItemID.RANARR_SEED));
		assertEquals(1, kept.get(ItemID.ABYSSAL_ASHES));
		assertEquals("noted bones are not crushed", 5, kept.get(ItemID.Cert.DRAGON_BONES));
		assertEquals(2, kept.size());
	}

	@Test
	public void notedDropsAreMatchedByTheUnnotedName()
	{
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.parse("Dragon bones"))
			.apply(drop(), new FakeNames());
		assertEquals(0, kept.get(ItemID.Cert.DRAGON_BONES));
		assertEquals(1, kept.get(ItemID.WYRM_BONES));
	}

	@Test
	public void idOnlyListsLookUpNoNames()
	{
		FakeNames names = new FakeNames();
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.parse(Integer.toString(ItemID.DRAGON_BONES)))
			.apply(drop(), names);
		assertEquals(0, kept.get(ItemID.Cert.DRAGON_BONES));
		assertEquals(4, kept.size());
		for (String call : names.calls)
		{
			assertTrue(call, call.startsWith("unnoted "));
		}
	}

	@Test
	public void eachItemIsLookedUpOnce()
	{
		FakeNames names = new FakeNames();
		new LootFilter(crusher(), IgnoredLoot.parse("coins")).apply(drop(), names);
		// The crushed wyrm bones are never looked up; the other four ids once each (unnoted id, then name).
		assertEquals(8, names.calls.size());
	}

	@Test
	public void failedLookupsLeaveOnlyIdMatches()
	{
		LootFilter.ItemNames failing = new LootFilter.ItemNames()
		{
			@Override
			public int unnoted(int itemId)
			{
				throw new IllegalStateException("not loaded");
			}

			@Override
			public String name(int itemId)
			{
				throw new IllegalStateException("not loaded");
			}
		};
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.parse("Coins, " + ItemID.RANARR_SEED))
			.apply(drop(), failing);
		assertEquals("the name could not be read", 300, kept.get(ItemID.COINS));
		assertEquals(0, kept.get(ItemID.RANARR_SEED));
	}

	@Test
	public void nullLootIsEmpty()
	{
		assertTrue(new LootFilter(crusher(), IgnoredLoot.parse("x")).apply(null, new FakeNames()).isEmpty());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Loot valued in a price mode: GE, high alch, a missing GE price, a GE price of 0 (valued at high alch in every
 * mode), and doses.
 */
public class LootPricingTest
{
	private static final int RUNE = 1;
	private static final int UNTRADEABLE = 2;
	private static final int NO_GE = 3;
	private static final int POTION = 4;

	private static Map<Integer, Long> prices(long... idPrice)
	{
		Map<Integer, Long> map = new HashMap<>();
		for (int i = 0; i < idPrice.length; i += 2)
		{
			map.put((int) idPrice[i], idPrice[i + 1]);
		}
		return map;
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	/** GE: 100 each, untradeable 0 (known), no GE price for {@link #NO_GE}. */
	private final Map<Integer, Long> ge = prices(RUNE, 100, UNTRADEABLE, 0);
	private final Map<Integer, Long> ha = prices(RUNE, 60, UNTRADEABLE, 50, NO_GE, 300);
	private final ItemTally loot = tally(RUNE, 2, UNTRADEABLE, 1, NO_GE, 1);

	@Test
	public void geValuesAtGeAndLeavesOutAMissingPrice()
	{
		// Runes at GE, the untradeable item (GE 0) at its high alch value, the item without a GE price left out.
		assertEquals(200 + 50, LootPricing.total(loot, LootPriceMode.GE, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(loot, LootPriceMode.GE, ge, ha));
		assertEquals(200, LootPricing.total(loot, LootPriceMode.GE, ge, null, null));
	}

	@Test
	public void aZeroGePriceCountsAtHighAlchInEveryMode()
	{
		// 7 Brimstone keys (untradeable: GE 0, high alch 48,000) and an item at GE 100 / high alch 60.
		int key = 23083;
		ItemTally keys = tally(key, 7, RUNE, 1);
		Map<Integer, Long> keyGe = prices(key, 0, RUNE, 100);
		Map<Integer, Long> keyHa = prices(key, 48_000, RUNE, 60);
		assertEquals(336_100, LootPricing.total(keys, LootPriceMode.GE, keyGe, keyHa, null));
		assertEquals(336_060, LootPricing.total(keys, LootPriceMode.HIGH_ALCH, keyGe, keyHa, null));
		for (LootPriceMode mode : LootPriceMode.values())
		{
			assertEquals("a GE price of 0 is known, not unpriced (" + mode + ")", 0,
				LootPricing.countUnpriced(keys, mode, keyGe, keyHa));
		}
		assertEquals(Long.valueOf(48_000), LootPricing.geUnitPrices(keyGe, keyHa).get(key));
		assertEquals("the input prices are not changed", Long.valueOf(0), keyGe.get(key));
	}

	@Test
	public void aMissingGePriceIsStillUnpricedInGe()
	{
		ItemTally t = tally(NO_GE, 2, RUNE, 1);
		assertEquals(100, LootPricing.total(t, LootPriceMode.GE, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(t, LootPriceMode.GE, ge, ha));
		assertEquals(null, LootPricing.geUnitPrices(ge, ha).get(NO_GE));
	}

	@Test
	public void coinsStayAtFaceValue()
	{
		// Coins are captured at 1 gp for both prices (ItemValuation), so no mode changes them.
		ItemTally coins = tally(ItemValuation.COINS, 5_000);
		Map<Integer, Long> one = prices(ItemValuation.COINS, 1);
		for (LootPriceMode mode : LootPriceMode.values())
		{
			assertEquals(5_000, LootPricing.total(coins, mode, one, one, null));
		}
	}

	@Test
	public void aZeroGePriceWithoutHighAlchStaysZero()
	{
		ItemTally t = tally(UNTRADEABLE, 3);
		assertEquals(0, LootPricing.total(t, LootPriceMode.GE, ge, prices(), null));
		assertEquals(0, LootPricing.countUnpriced(t, LootPriceMode.GE, ge, prices()));
	}

	@Test
	public void highAlchValuesAtHighAlch()
	{
		assertEquals(120 + 50 + 300, LootPricing.total(loot, LootPriceMode.HIGH_ALCH, ge, ha, null));
		assertEquals(0, LootPricing.countUnpriced(loot, LootPriceMode.HIGH_ALCH, ge, ha));
		assertEquals("no high alch values at all", 3,
			LootPricing.countUnpriced(loot, LootPriceMode.HIGH_ALCH, ge, null));
	}

	@Test
	public void anItemWithNeitherPriceIsLeftOut()
	{
		ItemTally t = tally(RUNE, 1, 99, 5);
		assertEquals(100, LootPricing.total(t, LootPriceMode.GE, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(t, LootPriceMode.GE, ge, ha));
		assertEquals(60, LootPricing.total(t, LootPriceMode.HIGH_ALCH, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(t, LootPriceMode.HIGH_ALCH, ge, ha));
		for (LootPriceMode mode : LootPriceMode.values())
		{
			assertEquals(mode.name(), 0, LootPricing.total(t, mode, null, null, null));
		}
	}

	@Test
	public void dosesAreValuedPerDoseInEveryMode()
	{
		// 3 doses of a 4-dose potion: GE 800, high alch 100 per potion.
		ItemTally doses = tally(POTION, 3);
		Map<Integer, Long> potionGe = prices(POTION, 800);
		Map<Integer, Long> potionHa = prices(POTION, 100);
		Map<Integer, Integer> perItem = Collections.singletonMap(POTION, 4);
		assertEquals(600, LootPricing.total(doses, LootPriceMode.GE, potionGe, potionHa, perItem));
		assertEquals(75, LootPricing.total(doses, LootPriceMode.HIGH_ALCH, potionGe, potionHa, perItem));
		assertEquals(2_400, LootPricing.total(doses, LootPriceMode.GE, potionGe, potionHa, null));
	}

	@Test
	public void nullModeIsGe()
	{
		assertEquals(250, LootPricing.total(loot, null, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(loot, null, ge, ha));
	}

	@Test
	public void displayNames()
	{
		assertEquals("GE", LootPriceMode.GE.toString());
		assertEquals("High alch", LootPriceMode.HIGH_ALCH.toString());
	}

	@Test
	public void onlyGeAndHighAlchRemain()
	{
		// "Higher of the two" was removed (owner decision, 2026-10-25).
		assertArrayEquals(new LootPriceMode[]{LootPriceMode.GE, LootPriceMode.HIGH_ALCH}, LootPriceMode.values());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Loot tally in the session tracker, snapshots and ledger records.
 */
public class LootTrackingTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};
	private static final int BONES = 526;
	private static final int RUNE_SCIMITAR = 1333;

	/** Fixed prices: bones 100 GE / 0 HA, scimitar 15,000 GE / 15,360 HA, coins at face value via the helper. */
	private static final ItemValuation.PriceLookup PRICES = new ItemValuation.PriceLookup()
	{
		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int canonicalId)
		{
			return canonicalId == BONES ? 100 : canonicalId == RUNE_SCIMITAR ? 15_000 : 0;
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return canonicalId == RUNE_SCIMITAR ? 15_360 : 0;
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}
	};

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private long now;
	private SessionTracker tracker;
	private final Gson gson = new Gson();

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	private void startDemonTask()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertTrue(tracker.play(ACCOUNT));
	}

	// ---- Tracker ----

	@Test
	public void lootIsRecordedOnlyWhileRunning()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertFalse("idle", tracker.addLoot(tally(BONES, 1)));
		assertTrue(tracker.play(ACCOUNT));
		assertTrue(tracker.addLoot(tally(BONES, 1, ItemValuation.COINS, 300)));
		tracker.pause();
		assertFalse("paused", tracker.addLoot(tally(BONES, 5)));
		tracker.play(ACCOUNT);
		assertTrue(tracker.addLoot(tally(BONES, 1)));
		tracker.autoPause();
		assertFalse("auto-paused", tracker.addLoot(tally(BONES, 5)));

		ItemTally loot = tracker.getLoot();
		assertEquals(2, loot.get(BONES));
		assertEquals(300, loot.get(ItemValuation.COINS));

		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(loot, summary.getLoot());
		assertFalse("stopped/idle", tracker.addLoot(tally(BONES, 1)));
		assertTrue(tracker.getLoot().isEmpty());
	}

	@Test
	public void lootFromAnyNpcCountsAndEmptyLootIsIgnored()
	{
		startDemonTask();
		// Not filtered by task monster: the tracker has no NPC information at all.
		assertTrue(tracker.addLoot(tally(RUNE_SCIMITAR, 1)));
		assertFalse(tracker.addLoot(new ItemTally()));
		assertFalse(tracker.addLoot(null));
		assertEquals(1, tracker.getLoot().size());
	}

	@Test
	public void newSessionStartsWithEmptyLoot()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 3));
		tracker.stopAndReset();
		assertTrue(tracker.play(ACCOUNT));
		assertTrue(tracker.getLoot().isEmpty());
		assertTrue(tracker.activeSummary().getLoot().isEmpty());
	}

	@Test
	public void summaryLootIsACopy()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 3));
		SessionTracker.Summary summary = tracker.activeSummary();
		tracker.addLoot(tally(BONES, 3));
		summary.getLoot().add(BONES, 100);
		assertEquals(3, summary.getLoot().get(BONES));
		assertEquals(6, tracker.getLoot().get(BONES));
	}

	// ---- Snapshot and restore ----

	private SessionSnapshot snapshotWithLoot()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 4, ItemValuation.COINS, 1_000));
		now += 30_000;
		tracker.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		tracker.autoPause();
		return SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
	}

	@Test
	public void snapshotWithLootRoundTripsThroughJson()
	{
		SessionSnapshot s = snapshotWithLoot();
		assertEquals(Long.valueOf(4), s.getLoot().get(BONES));
		String json = gson.toJson(s);
		assertTrue(json, json.contains("\"loot\":{\"526\":4,\"995\":1000}"));
		SessionSnapshot back = gson.fromJson(json, SessionSnapshot.class);
		assertEquals(s, back);
		assertEquals(s.getLoot(), back.getLoot());
	}

	@Test
	public void snapshotWithoutLootOmitsField()
	{
		startDemonTask();
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertNull(s.getLoot());
		assertFalse(gson.toJson(s).contains("loot"));
	}

	@Test
	public void oldSnapshotWithoutLootRestores()
	{
		String v1 = "{\"schemaVersion\":1,\"sessionId\":\"s1\",\"accountHash\":555,\"monster\":\"Abyssal demons\","
			+ "\"creatureId\":42,\"initialAmount\":50,\"originalAmount\":150,\"kills\":4,\"activeMillis\":30000,"
			+ "\"startedAt\":1000,\"savedAt\":2000,\"remaining\":46,\"completionCounters\":[100,2,0]}";
		SessionSnapshot s = gson.fromJson(v1, SessionSnapshot.class);
		assertNull(s.getLoot());
		assertTrue(s.toSummary().getLoot().isEmpty());

		tracker.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
		assertTrue(tracker.getLoot().isEmpty());
		assertTrue(tracker.play(ACCOUNT));
		tracker.addLoot(tally(BONES, 1));
		assertEquals(1, tracker.getLoot().get(BONES));
	}

	@Test
	public void fileRestoreKeepsLootAndAddsToIt()
	{
		SessionSnapshot s = gson.fromJson(gson.toJson(snapshotWithLoot()), SessionSnapshot.class);
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(s, COUNTERS));
		assertEquals(4, restored.getLoot().get(BONES));
		assertFalse("restored session is paused", restored.addLoot(tally(BONES, 10)));
		assertTrue(restored.play(ACCOUNT));
		restored.addLoot(tally(BONES, 1, RUNE_SCIMITAR, 1));

		LedgerRecord record = LedgerRecord.fromSummary(restored.stopAndReset(), true);
		assertEquals(Long.valueOf(5), record.getLoot().get(BONES));
		assertEquals(Long.valueOf(1_000), record.getLoot().get(ItemValuation.COINS));
		assertEquals(Long.valueOf(1), record.getLoot().get(RUNE_SCIMITAR));
	}

	@Test
	public void restoreClearsLootOfAnyEarlierSession()
	{
		SessionSnapshot s = snapshotWithLoot();
		SessionTracker other = new SessionTracker(() -> now);
		other.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		other.play(ACCOUNT);
		other.addLoot(tally(RUNE_SCIMITAR, 9));
		other.stopAndReset();
		assertEquals(SessionTracker.RestoreResult.RESTORED, other.restore(s, COUNTERS));
		assertEquals(0, other.getLoot().get(RUNE_SCIMITAR));
		assertEquals(4, other.getLoot().get(BONES));
	}

	@Test
	public void mismatchedFileRestoreSavesLootInPartialRecord()
	{
		SessionSnapshot s = gson.fromJson(gson.toJson(snapshotWithLoot()), SessionSnapshot.class);
		SessionTracker later = new SessionTracker(() -> now);
		later.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertEquals(SessionTracker.RestoreResult.MISMATCH, later.restore(s, COUNTERS));
		assertTrue(later.getLoot().isEmpty());

		LedgerRecord record = LedgerRecord.fromSummary(s.toSummary(), true);
		assertTrue(record.isPartial());
		assertEquals(Long.valueOf(4), record.getLoot().get(BONES));
		assertEquals(Long.valueOf(1_000), record.getLoot().get(ItemValuation.COINS));
	}

	@Test
	public void inMemoryReloginKeepsLoot()
	{
		SessionSnapshot logout = snapshotWithLoot();
		// Logout: the session stays in memory, auto-paused; the current task is forgotten.
		tracker.clearCurrentTask();
		tracker.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertTrue(tracker.activeSessionStillMatches(logout, COUNTERS));
		assertEquals(4, tracker.getLoot().get(BONES));
		assertTrue(tracker.play(ACCOUNT));
		tracker.addLoot(tally(BONES, 2));
		assertEquals(6, tracker.getLoot().get(BONES));
	}

	@Test
	public void inMemoryReloginMismatchSavesLootInPartialRecord()
	{
		SessionSnapshot logout = snapshotWithLoot();
		tracker.clearCurrentTask();
		tracker.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertFalse(tracker.activeSessionStillMatches(logout, COUNTERS));
		// The plugin then ends the session as RESTORE_MISMATCH.
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertNotNull(summary);
		LedgerRecord record = LedgerRecord.fromSummary(summary, true);
		assertEquals(Long.valueOf(4), record.getLoot().get(BONES));
	}

	// ---- Records ----

	@Test
	public void recordCarriesLootAndCapturesValues()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 10, RUNE_SCIMITAR, 2, ItemValuation.COINS, 2_500));
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, record.getSchemaVersion());
		assertEquals(3, record.getLoot().size());
