package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class LuckMeterTest
{
	private static final LuckMeter METER = LuckMeter.load(new Gson(), LuckMeter.SNAPSHOT_RESOURCE);

	@Test
	public void bundledSnapshotLoadsWithTheCacheTaskNames()
	{
		assertNotNull(METER);
		List<LedgerRecord> records = Arrays.asList(record("Abyssal demons", 10), record("Dust devils", 10),
			record("Gargoyles", 10), record("Kurask", 10), record("Nechryael", 10));
		// The cache task names (core Task enum: "Kurask", not "Kurasks").
		assertEquals(Arrays.asList("Abyssal demons", "Dust devils", "Gargoyles", "Kurask", "Nechryael"),
			METER.supportedTasks(records));
		assertEquals("2026-10-26", METER.getSnapshotDate());
		assertEquals("CC BY-NC-SA 3.0", METER.getLicense());
	}

	@Test
	public void kuraskRecordsMatchTheirTable()
	{
		LedgerRecord kurask = record("Kurask", 384);
		kurask.setLoot(map(200, 1));
		LuckMeter.Summary summary = METER.summarize(Collections.singletonList(kurask), " kurask ",
			Collections.singletonMap(200, "Leaf-bladed sword"));
		assertEquals("Kurask", summary.getTask());
		assertEquals(1, summary.getTaskCount());
		assertEquals(384L, summary.getKills());
		assertEquals("Leaf-bladed sword", summary.getDrops().get(0).getItem());
		assertEquals(1L, summary.getDrops().get(0).getActual());
		assertEquals(1d, summary.getDrops().get(0).getExpected(), 1e-9);
	}

	@Test
	public void comparesObservedWithExpectedCountsOverSamplesOnly()
	{
		assertTrue(METER.supportedTasks(Collections.emptyList()).isEmpty());

		LedgerRecord completed = record("Abyssal demons", 512);
		completed.setLoot(map(100, 2, 101, 1, 102, 3));
		LedgerRecord partial = record("Abyssal demons", 50_000);
		partial.setPartial(true);
		LedgerRecord incomplete = record("Abyssal demons", 50_000);
		incomplete.setCompleted(false);

		Map<Integer, String> itemNames = new HashMap<>();
		itemNames.put(100, "Abyssal whip");
		itemNames.put(101, "ABYSSAL DAGGER");
		itemNames.put(102, "Untracked item");
		List<LedgerRecord> records = Arrays.asList(completed, partial, incomplete);

		LuckMeter.Summary summary = METER.summarize(records, "abyssal DEMONS", itemNames);
		assertEquals(1, summary.getTaskCount());
		assertEquals(512L, summary.getKills());
		assertEquals(2, summary.getDrops().size());

		LuckMeter.DropEntry whip = summary.getDrops().get(0);
		assertEquals("Abyssal whip", whip.getItem());
		assertEquals(2L, whip.getActual());
		assertEquals(1d, whip.getExpected(), 1e-9);
		assertTrue(whip.hasRatio());
		assertEquals(2d, whip.getRatio(), 1e-9);

		LuckMeter.DropEntry dagger = summary.getDrops().get(1);
		assertEquals("Abyssal dagger", dagger.getItem());
		assertEquals(1L, dagger.getActual());
		assertEquals(512d / 32000d, dagger.getExpected(), 1e-9);
	}

	@Test
	public void recordsWithoutLootDataAreNotSamples()
	{
		// Saved before loot tracking: no loot and no values. Its kills must not inflate expected.
		LedgerRecord old = record("Nechryael", 10_000);
		old.setLootGeValue(null);
		assertNull(old.getLoot());
		// Tracked with no loot at all: the empty tally is stored as null, but the record was valued.
		LedgerRecord tracked = record("Nechryael", 116);
		tracked.setLootGeValue(0L);
		LedgerRecord withLoot = record("Nechryael", 116);
		withLoot.setLoot(map(300, 1));
		assertFalse(LuckMeter.isSample(old));
		assertTrue(LuckMeter.isSample(tracked));
		assertTrue(LuckMeter.isSample(withLoot));

		LuckMeter.Summary summary = METER.summarize(Arrays.asList(old, tracked, withLoot), "Nechryael",
			Collections.singletonMap(300, "Rune boots"));
		assertEquals(2, summary.getTaskCount());
		assertEquals(232L, summary.getKills());
		assertEquals(2d, summary.getDrops().get(0).getExpected(), 1e-9);
		assertEquals(1L, summary.getDrops().get(0).getActual());

		assertTrue(METER.supportedTasks(Collections.singletonList(old)).isEmpty());
	}

	@Test
	public void notedNamesAndQuantitiesCount()
	{
		LedgerRecord record = record("Gargoyles", 512);
		record.setLoot(map(400, 2, 401, 1));
		Map<Integer, String> names = new HashMap<>();
		names.put(400, "Granite maul");
		names.put(401, "Granite maul (noted)");
		LuckMeter.Summary summary = METER.summarize(Collections.singletonList(record), "Gargoyles", names);
		assertEquals(3L, summary.getDrops().get(0).getActual());
		assertEquals(2d, summary.getDrops().get(0).getExpected(), 1e-9);
	}

	@Test
	public void unknownItemNamesAndUnsupportedTasksAreNotGuessed()
	{
		LedgerRecord record = record("Nechryael", 116);
		record.setLoot(map(100, 2));
		LuckMeter.Summary summary = METER.summarize(Collections.singletonList(record), "Nechryael",
			Collections.emptyMap());
		assertEquals(1, summary.getDrops().size());
		assertEquals(0L, summary.getDrops().get(0).getActual());
		assertEquals(1d, summary.getDrops().get(0).getExpected(), 1e-9);

		assertTrue(METER.summarize(Collections.singletonList(record), "Abyssal Sire",
			Collections.emptyMap()).getDrops().isEmpty());
		assertEquals(Collections.singletonList("Nechryael"), METER.supportedTasks(Collections.singletonList(record)));
	}

	@Test
	public void ratioIsHiddenBelowOneExpectedDrop()
	{
		LedgerRecord record = record("Abyssal demons", 256);
		record.setLoot(map(100, 1));
		LuckMeter.DropEntry whip = METER.summarize(Collections.singletonList(record), "Abyssal demons",
			Collections.singletonMap(100, "Abyssal whip")).getDrops().get(0);
		assertEquals(0.5, whip.getExpected(), 1e-9);
		assertFalse(whip.hasRatio());
		assertTrue(Double.isNaN(whip.getRatio()));
		// P(X >= 1) for Poisson(0.5) = 1 - e^-0.5.
		assertEquals(1 - Math.exp(-0.5), whip.getChanceOfAtLeastObserved(), 1e-12);
	}

	@Test
	public void poissonChanceOfAtLeastIsNumericallySafe()
	{
		assertEquals(1d, LuckMeter.chanceOfAtLeast(0, 0.01), 0);
		assertEquals(1d, LuckMeter.chanceOfAtLeast(0, 0), 0);
		assertEquals(0d, LuckMeter.chanceOfAtLeast(1, 0), 0);
		assertEquals(1 - Math.exp(-2) * (1 + 2), LuckMeter.chanceOfAtLeast(2, 2), 1e-12);
		// Upper tail: P(X >= 3) for Poisson(0.5).
		double lower = Math.exp(-0.5) * (1 + 0.5 + 0.125);
		assertEquals(1 - lower, LuckMeter.chanceOfAtLeast(3, 0.5), 1e-12);
		// Large means and counts neither overflow nor underflow to a wrong answer.
		assertEquals(0.5, LuckMeter.chanceOfAtLeast(10_000, 10_000), 0.01);
		double tiny = LuckMeter.chanceOfAtLeast(50, 0.01);
		assertTrue(tiny >= 0 && tiny < 1e-100);
		assertTrue(LuckMeter.chanceOfAtLeast(1, 5_000) > 0.999_999);
	}

	@Test
	public void blankNamesMatchNoTaskOrDrop()
	{
		LedgerRecord blank = record("  ", 10);
		LedgerRecord unnamed = record(null, 10);
		assertTrue(METER.supportedTasks(Arrays.asList(blank, unnamed)).isEmpty());
		assertEquals(0, METER.summarize(Arrays.asList(blank, unnamed), " ", Collections.emptyMap()).getTaskCount());

		LedgerRecord demons = record("Abyssal demons", 512);
		demons.setLoot(map(100, 2, 101, 1));
		Map<Integer, String> itemNames = new HashMap<>();
		itemNames.put(100, "Abyssal whip");
		itemNames.put(101, " ");
		LuckMeter.Summary summary = METER.summarize(Collections.singletonList(demons), "Abyssal demons", itemNames);
		assertEquals(2L, summary.getDrops().get(0).getActual());
		assertEquals(0L, summary.getDrops().get(1).getActual());
	}

	@Test
	public void missingOrBadSnapshotsLoadAsNull()
	{
		Gson gson = new Gson();
		assertNull(LuckMeter.load(gson, "no-such-snapshot.json"));
		assertNull(LuckMeter.load(gson, "luck-snapshot-malformed.json"));
		assertNull(LuckMeter.load(gson, "luck-snapshot-invalid.json"));
	}

	private static LedgerRecord record(String monster, int kills)
	{
		LedgerRecord record = new LedgerRecord();
		record.setMonster(monster);
		record.setKills(kills);
		record.setCompleted(true);
		record.setPartial(false);
		// Tracked loot (valued), unless a test clears it.
		record.setLootGeValue(0L);
		return record;
	}

	private static Map<Integer, Long> map(int... values)
	{
		Map<Integer, Long> result = new HashMap<>();
		for (int i = 0; i < values.length; i += 2)
		{
			result.put(values[i], (long) values[i + 1]);
		}
		return result;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.Icon;
import org.junit.Test;

/**
 * The masters' faces ({@link MasterIcons}) and the task names Trends' icons come from: every master name has a
 * file, a missing image is an empty slot, a bundled one is read once and drawn in the 18 by 16 slot; a Catacombs
 * variant or cannon group in Trends carries its task's name.
 */
public class MasterIconsTest
{
	@Test
	public void everyMasterNameHasAFile()
	{
		Map<String, String> expected = new HashMap<>();
		expected.put("Turael/Aya", "turael_chathead.png");
		expected.put("Mazchna", "mazchna_chathead.png");
		expected.put("Vannaka", "vannaka_chathead.png");
		expected.put("Chaeldar", "chaeldar_chathead.png");
		// A shared name uses the first master's face.
		expected.put("Duradel/Kuradal", "duradel_chathead.png");
		expected.put("Nieve/Steve", "nieve_chathead.png");
		expected.put("Krystilia", "krystilia_chathead.png");
		expected.put("Konar", "konar_quo_maten_chathead.png");
		expected.put("Spria", "spria_chathead.png");
		expected.put("Mortimer", "mortimer_chathead.png");
		for (int master = 1; SlayerMaster.hasName(master); master++)
		{
			String name = SlayerMaster.displayName(master);
			assertEquals(name, expected.get(name), MasterIcons.fileName(name));
		}
		assertEquals(expected.size(), SlayerMaster.MORTIMER);
		assertNull(MasterIcons.fileName(SlayerMaster.displayName(42)));
		assertNull(MasterIcons.fileName(null));
	}

	@Test
	public void aMissingImageIsAnEmptySlot()
	{
		// As if the masters/ folder were deleted: no code change, no exception, an empty slot of the same size.
		MasterIcons icons = new MasterIcons("no-such-folder/");
		for (int master = 1; SlayerMaster.hasName(master); master++)
		{
			Icon icon = icons.icon(SlayerMaster.displayName(master));
			assertSame(SmallItemIcon.EMPTY, icon);
			assertEquals(ItemListView.ICON_WIDTH, icon.getIconWidth());
			assertEquals(ItemListView.ICON_HEIGHT, icon.getIconHeight());
		}
		assertSame(SmallItemIcon.EMPTY, new MasterIcons().icon("Unknown master (42)"));
		assertSame(SmallItemIcon.EMPTY, new MasterIcons().icon(null));
	}

	@Test
	public void anUnreadableImageIsAnEmptySlot()
	{
		// A test resource with Konar's file name that is no PNG: an empty slot, no exception.
		MasterIcons icons = new MasterIcons("masters-unreadable/");
		assertNotNull(MasterIcons.class.getResource("masters-unreadable/" + MasterIcons.fileName("Konar")));
		assertSame(SmallItemIcon.EMPTY, icons.icon("Konar"));
		assertSame(SmallItemIcon.EMPTY, icons.icon("Konar"));
	}

	@Test
	public void bundledImagesAreReadOnceAndFitTheSlot()
	{
		MasterIcons icons = new MasterIcons();
		for (int master = 1; SlayerMaster.hasName(master); master++)
		{
			String name = SlayerMaster.displayName(master);
			Icon icon = icons.icon(name);
			if (MasterIcons.class.getResource(MasterIcons.DIRECTORY + MasterIcons.fileName(name)) == null)
			{
				// Removed for the hub: the empty slot.
				assertSame(name, SmallItemIcon.EMPTY, icon);
				continue;
			}
			assertTrue(name, icon instanceof MasterIcons.MasterIcon);
			assertEquals(MasterIcons.fileName(name), ((MasterIcons.MasterIcon) icon).getFile());
			assertEquals(ItemListView.ICON_WIDTH, icon.getIconWidth());
			assertEquals(ItemListView.ICON_HEIGHT, icon.getIconHeight());
			assertSame("kept, not read again", icon, icons.icon(name));
			// Draws inside its slot without throwing.
			BufferedImage canvas = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = canvas.createGraphics();
			icon.paintIcon(null, g, 5, 5);
			g.dispose();
			assertEquals(0, canvas.getRGB(4, 4) >>> 24);
			assertEquals(0, canvas.getRGB(5 + ItemListView.ICON_WIDTH, 5 + ItemListView.ICON_HEIGHT) >>> 24);
		}
	}

	@Test
	public void scalingKeepsTheAspectRatio()
	{
		BufferedImage tall = MasterIcons.scaled(new BufferedImage(66, 102, BufferedImage.TYPE_INT_ARGB), 36, 32);
		assertEquals(Arrays.asList(21, 32), Arrays.asList(tall.getWidth(), tall.getHeight()));
		BufferedImage wide = MasterIcons.scaled(new BufferedImage(119, 60, BufferedImage.TYPE_INT_ARGB), 36, 32);
		assertEquals(Arrays.asList(36, 18), Arrays.asList(wide.getWidth(), wide.getHeight()));
		// Already small: kept as it is.
		BufferedImage small = new BufferedImage(10, 8, BufferedImage.TYPE_INT_ARGB);
		assertSame(small, MasterIcons.scaled(small, 36, 32));
	}

	@Test
	public void trendsGroupsCarryTheirTasksName()
	{
		LedgerRecord plain = record("Dust devils", 3);
		LedgerRecord deviant = record("Aberrant spectres", 2);
		deviant.setVariant("Deviant spectres");
		LedgerRecord cannon = record("Dust devils", 1);
		cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 100L));
		List<LedgerRecord> records = Arrays.asList(plain, deviant, cannon);

		Map<String, String> tasks = new HashMap<>();
		for (TaskRanking.Entry entry : TaskRanking.rank(records, TaskRanking.Metric.XP, LootPriceMode.GE, null))
		{
			tasks.put(entry.getMonster(), entry.getTask());
		}
		Map<String, String> expected = new HashMap<>();
		expected.put("Dust devils", "Dust devils");
		expected.put("Deviant spectres", "Aberrant spectres");
		expected.put("Dust devils (cannon)", "Dust devils");
		assertEquals(expected, tasks);

		Map<String, String> chart = new HashMap<>();
		for (TaskChart.Monster monster : TaskChart.monsters(records, TaskRanking.Metric.XP, LootPriceMode.GE, null))
		{
			chart.put(monster.getLabel(), monster.getTask());
		}
		assertEquals(expected, chart);
		assertEquals(TaskIcons.itemId("Aberrant spectres"), TaskIcons.itemId(chart.get("Deviant spectres")));
	}

	private static LedgerRecord record(String monster, long endedAt)
	{
		LedgerRecord record = new LedgerRecord();
		record.setMonster(monster);
		record.setEndedAt(endedAt);
		record.setKills(10);
		record.setActiveMillis(30 * 60_000L);
		record.setXpGained(Collections.singletonMap(SkillXp.SLAYER, 1_000L));
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;

/**
 * Food eaten in parts (pizzas, pies and cakes) is tracked in bites, like potion doses, so eating a whole one costs
 * exactly one item.
 */
public class MultiBiteFoodTest
{
	private static final String[] EAT = {"Eat", null, null, null, "Drop"};
	private static final String[] NONE = {null, null, null, null, "Drop"};

	/** Classifies with the production rules; the pie dish and everything unknown have no "Eat" action. */
	private static final SupplyTracker.Classifier CLASSIFIER = id ->
	{
		if (id == ItemID.PIEDISH)
		{
			return SupplyTracker.classify(id, "Pie dish", NONE, false, false, false);
		}
		if (id == ItemID.SHARK || SupplyTracker.MULTI_BITE_FOOD.containsKey(id))
		{
			return SupplyTracker.classify(id, "Food " + id, EAT, false, false, false);
		}
		return SupplyTracker.classify(id, "Other", NONE, false, false, false);
	};

	private SupplyTracker supplies;

	@Before
	public void setUp()
	{
		supplies = new SupplyTracker(CLASSIFIER);
	}

	private SupplyTracker.Usage tick(int... idQty)
	{
		return supplies.update(SupplyTrackerTest.obs(idQty), true, false, Collections.emptySet());
	}

	@Test
	public void itemIdsMatchTheGameValues()
	{
		// Checked against net.runelite.api.gameval.ItemID in RuneLite 1.13.4.
		assertEquals(2289, ItemID.PLAIN_PIZZA);
		assertEquals(2291, ItemID.HALF_PLAIN_PIZZA);
		assertEquals(2293, ItemID.MEAT_PIZZA);
		assertEquals(2295, ItemID.HALF_MEAT_PIZZA);
		assertEquals(2297, ItemID.ANCHOVIE_PIZZA);
		assertEquals(2299, ItemID.HALF_ANCHOVIE_PIZZA);
		assertEquals(2301, ItemID.PINEAPPLE_PIZZA);
		assertEquals(2303, ItemID.HALF_PINEAPPLE_PIZZA);
		assertEquals(2323, ItemID.APPLE_PIE);
		assertEquals(2325, ItemID.REDBERRY_PIE);
		assertEquals(2327, ItemID.MEAT_PIE);
		assertEquals(2331, ItemID.HALF_A_MEAT_PIE);
		assertEquals(2333, ItemID.HALF_A_REDBERRY_PIE);
		assertEquals(2335, ItemID.HALF_AN_APPLE_PIE);
		assertEquals(7178, ItemID.GARDEN_PIE);
		assertEquals(7180, ItemID.HALF_GARDEN_PIE);
		assertEquals(7188, ItemID.FISH_PIE);
		assertEquals(7190, ItemID.HALF_FISH_PIE);
		assertEquals(7198, ItemID.ADMIRAL_PIE);
		assertEquals(7200, ItemID.HALF_ADMIRAL_PIE);
		assertEquals(7208, ItemID.WILD_PIE);
		assertEquals(7210, ItemID.HALF_WILD_PIE);
		assertEquals(7218, ItemID.SUMMER_PIE);
		assertEquals(7220, ItemID.HALF_SUMMER_PIE);
		assertEquals(19662, ItemID.BOTANICAL_PIE);
		assertEquals(19659, ItemID.HALF_BOTANICAL_PIE);
		assertEquals(21690, ItemID.MUSHROOM_PIE);
		assertEquals(21687, ItemID.HALF_MUSHROOM_PIE);
		assertEquals(22795, ItemID.DRAGONFRUIT_PIE);
		assertEquals(22792, ItemID.HALF_DRAGONFRUIT_PIE);
		assertEquals(1891, ItemID.CAKE);
		assertEquals(1893, ItemID.PARTIAL_CAKE);
		assertEquals(1895, ItemID.CAKE_SLICE);
		assertEquals(1897, ItemID.CHOCOLATE_CAKE);
		assertEquals(1899, ItemID.PARTIAL_CHOCOLATE_CAKE);
		assertEquals(1901, ItemID.CHOCOLATE_SLICE);
		assertEquals(2313, ItemID.PIEDISH);
	}

	@Test
	public void tableHoldsEveryStageWithItsBites()
	{
		assertEquals(4 * 2 + 11 * 2 + 2 * 3, SupplyTracker.MULTI_BITE_FOOD.size());
		assertArrayEquals(new int[]{ItemID.PLAIN_PIZZA, 2, 2}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.PLAIN_PIZZA));
		assertArrayEquals(new int[]{ItemID.PLAIN_PIZZA, 1, 2}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.HALF_PLAIN_PIZZA));
		assertArrayEquals(new int[]{ItemID.MEAT_PIE, 1, 2}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.HALF_A_MEAT_PIE));
		assertArrayEquals(new int[]{ItemID.CAKE, 3, 3}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.CAKE));
		assertArrayEquals(new int[]{ItemID.CAKE, 2, 3}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.PARTIAL_CAKE));
		assertArrayEquals(new int[]{ItemID.CAKE, 1, 3}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.CAKE_SLICE));
		assertArrayEquals(new int[]{ItemID.CHOCOLATE_CAKE, 1, 3},
			SupplyTracker.MULTI_BITE_FOOD.get(ItemID.CHOCOLATE_SLICE));
		assertFalse("the pie dish is not food", SupplyTracker.MULTI_BITE_FOOD.containsKey(ItemID.PIEDISH));
		assertFalse("noted food is never a supply", SupplyTracker.MULTI_BITE_FOOD.containsKey(ItemID.Cert.PLAIN_PIZZA));
	}

	@Test
	public void classifiedByIdAsFoodInBites()
	{
		SupplyTracker.ItemInfo half = CLASSIFIER.classify(ItemID.HALF_MEAT_PIZZA);
		assertEquals(SupplyTracker.Category.FOOD, half.getCategory());
		assertEquals(1, half.getDoses());
		assertEquals(ItemID.MEAT_PIZZA, half.getFullItemId());
		assertEquals(2, half.getDosesPerItem());
		assertEquals(CLASSIFIER.classify(ItemID.MEAT_PIZZA).getFamily(), half.getFamily());
		SupplyTracker.ItemInfo shark = CLASSIFIER.classify(ItemID.SHARK);
		assertNull("ordinary food is counted per item", shark.getFamily());
		assertEquals(SupplyTracker.Category.OTHER, CLASSIFIER.classify(ItemID.PIEDISH).getCategory());
	}

	@Test
	public void eatingAWholePizzaCostsExactlyOnePizza()
	{
		tick(ItemID.PLAIN_PIZZA, 1);
		SupplyTracker.Usage first = tick(ItemID.HALF_PLAIN_PIZZA, 1);
		SupplyTracker.Usage second = tick();

		ItemTally used = new ItemTally();
		Map<Integer, Integer> doses = new HashMap<>();
		for (SupplyTracker.Usage usage : new SupplyTracker.Usage[]{first, second})
		{
			used.merge(usage.getUsed());
			doses.putAll(usage.getDoses());
		}
		assertEquals("two bites, recorded under the full pizza", 2, used.get(ItemID.PLAIN_PIZZA));
		assertEquals("the half pizza is not an item of its own", 0, used.get(ItemID.HALF_PLAIN_PIZZA));
		assertEquals(1, used.size());
		assertEquals(Integer.valueOf(2), doses.get(ItemID.PLAIN_PIZZA));

		// Valued at exactly one pizza (not a pizza plus a half pizza, as before).
		Map<Integer, Long> prices = new HashMap<>();
		prices.put(ItemID.PLAIN_PIZZA, 300L);
		prices.put(ItemID.HALF_PLAIN_PIZZA, 150L);
		assertEquals(300L, ItemValuation.total(used, prices, doses));
	}

	@Test
	public void aHalfPizzaHeldAtSessionStartCostsHalf()
	{
		tick(ItemID.HALF_ANCHOVIE_PIZZA, 1, ItemID.SHARK, 2);
		SupplyTracker.Usage usage = tick(ItemID.SHARK, 2);
		assertEquals(1, usage.getUsed().get(ItemID.ANCHOVIE_PIZZA));
		assertEquals(Integer.valueOf(2), usage.getDoses().get(ItemID.ANCHOVIE_PIZZA));
		Map<Integer, Long> prices = Collections.singletonMap(ItemID.ANCHOVIE_PIZZA, 401L);
		assertEquals("half of 401, rounded", 201L, ItemValuation.total(usage.getUsed(), prices, usage.getDoses()));
	}

	@Test
	public void eatingAPieLeavesTheDishUncounted()
	{
		tick(ItemID.MEAT_PIE, 2);
		assertEquals(1, tick(ItemID.MEAT_PIE, 1, ItemID.HALF_A_MEAT_PIE, 1).getUsed().get(ItemID.MEAT_PIE));
		SupplyTracker.Usage last = tick(ItemID.MEAT_PIE, 1, ItemID.PIEDISH, 1);
		assertEquals(1, last.getUsed().get(ItemID.MEAT_PIE));
		assertEquals(1, last.getUsed().size());
		assertTrue("the dish is no return", last.getReturned().isEmpty());
	}

	@Test
	public void aCakeIsThreeBites()
	{
		tick(ItemID.CHOCOLATE_CAKE, 1);
		ItemTally used = new ItemTally();
		Map<Integer, Integer> doses = new HashMap<>();
		for (int[] after : new int[][]{{ItemID.PARTIAL_CHOCOLATE_CAKE, 1}, {ItemID.CHOCOLATE_SLICE, 1}, {}})
		{
			SupplyTracker.Usage usage = tick(after);
			used.merge(usage.getUsed());
			doses.putAll(usage.getDoses());
		}
		assertEquals(3, used.get(ItemID.CHOCOLATE_CAKE));
		assertEquals(Integer.valueOf(3), doses.get(ItemID.CHOCOLATE_CAKE));
		assertEquals(900L, ItemValuation.total(used, Collections.singletonMap(ItemID.CHOCOLATE_CAKE, 900L), doses));
	}

	@Test
	public void differentFoodsAreSeparateAndSlicesAreNotCake()
	{
		tick(ItemID.PLAIN_PIZZA, 1, ItemID.MEAT_PIZZA, 1, ItemID.CAKE_SLICE, 1);
		SupplyTracker.Usage usage = tick(ItemID.HALF_PLAIN_PIZZA, 1, ItemID.MEAT_PIZZA, 1);
		assertEquals(1, usage.getUsed().get(ItemID.PLAIN_PIZZA));
		assertEquals(0, usage.getUsed().get(ItemID.MEAT_PIZZA));
		assertEquals("a slice is one bite of a cake", 1, usage.getUsed().get(ItemID.CAKE));
	}

	@Test
	public void droppingAPartNetsNothing()
	{
		tick(ItemID.PLAIN_PIZZA, 1, ItemID.HALF_PLAIN_PIZZA, 1);
		SupplyTracker.Usage usage = supplies.update(SupplyTrackerTest.obs(ItemID.PLAIN_PIZZA, 1), true, false,
			Collections.singleton(ItemID.HALF_PLAIN_PIZZA));
		assertTrue(usage.isEmpty());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link NotableDrops} and {@link NotableDrop}: which loot stacks are notable at a threshold and price mode, the cap
 * per task, order, text, and how they go through the session, snapshots, records and JSON.
 */
public class NotableDropsTest
{
	private static final int WHIP = 4151;
	private static final int KEY = 23083;
	private static final int BAR = 2363;
	private static final int UNPRICED = 11840;
	private static final long TIME = 1_000L;

	private final Gson gson = new Gson();
	private ItemValuation.UnitPrices prices;

	@Before
	public void setUp()
	{
		prices = new ItemValuation.UnitPrices();
		prices.getGe().put(WHIP, 1_500_000L);
		prices.getHa().put(WHIP, 72_000L);
		// Untradeable: a GE price of 0, valued at its high alch value in GE mode.
		prices.getGe().put(KEY, 0L);
		prices.getHa().put(KEY, 120_000L);
		prices.getGe().put(BAR, 12_000L);
		prices.getHa().put(BAR, 7_500L);
		// GE price unavailable.
		prices.getGeMissing().add(UNPRICED);
		prices.getHa().put(UNPRICED, 300_000L);
	}

	private static ItemTally tally(long... idQuantityPairs)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQuantityPairs.length; i += 2)
		{
			t.add((int) idQuantityPairs[i], idQuantityPairs[i + 1]);
		}
		return t;
	}

	private List<NotableDrop> find(ItemTally drop, LootPriceMode mode, long threshold)
	{
		return NotableDrops.find(drop, prices, mode, threshold, id -> "Item " + id, TIME);
	}

	private static NotableDrop item(int id, long value, long time)
	{
		return NotableDrop.item(id, "Item " + id, 1, value, value, time);
	}

	@Test
	public void stackAtTheThresholdIsNotable()
	{
		assertEquals(1, find(tally(BAR, 25), LootPriceMode.GE, 300_000).size());
		assertTrue("1 gp below", find(tally(BAR, 25), LootPriceMode.GE, 300_001).isEmpty());
		NotableDrop bars = find(tally(BAR, 25), LootPriceMode.GE, 300_000).get(0);
		assertEquals(Integer.valueOf(BAR), bars.getItemId());
		assertEquals("Item " + BAR, bars.getName());
		assertEquals(25, bars.getQuantity());
		assertEquals(Long.valueOf(300_000), bars.getGeValue());
		assertEquals(Long.valueOf(187_500), bars.getHaValue());
		assertEquals(TIME, bars.getTime());
		assertFalse(bars.isPet());
	}

	@Test
	public void valuedInTheLootPriceMode()
	{
		List<NotableDrop> ge = find(tally(WHIP, 1, KEY, 1, BAR, 1, UNPRICED, 1), LootPriceMode.GE, 100_000);
		assertEquals("whip, and the untradeable key at its high alch value; not the unpriced item", 2, ge.size());
		assertEquals(Integer.valueOf(WHIP), ge.get(0).getItemId());
		assertEquals(Integer.valueOf(KEY), ge.get(1).getItemId());
		assertEquals(Long.valueOf(120_000), ge.get(1).getGeValue());

		List<NotableDrop> ha = find(tally(WHIP, 1, KEY, 1, BAR, 1, UNPRICED, 1), LootPriceMode.HIGH_ALCH, 100_000);
		assertEquals(2, ha.size());
		// In item id order.
		assertEquals(Integer.valueOf(UNPRICED), ha.get(0).getItemId());
		assertNull("GE value unknown", ha.get(0).getGeValue());
		assertEquals(Long.valueOf(300_000), ha.get(0).getHaValue());
		assertEquals(Integer.valueOf(KEY), ha.get(1).getItemId());
	}

	@Test
	public void nothingFoundForEmptyInput()
	{
		assertTrue(find(null, LootPriceMode.GE, 1).isEmpty());
		assertTrue(find(new ItemTally(), LootPriceMode.GE, 1).isEmpty());
		assertTrue(NotableDrops.find(tally(WHIP, 1), null, LootPriceMode.GE, 1, null, TIME).isEmpty());
		assertNull("names are optional", NotableDrops.find(tally(WHIP, 1), prices, null, 1, null, TIME).get(0)
			.getName());
	}

	@Test
	public void thresholdIsAtLeastOneGp()
	{
		assertEquals(1, NotableDrops.threshold(0));
		assertEquals(1, NotableDrops.threshold(-5));
		assertEquals(100_000, NotableDrops.threshold(100_000));
		prices.getGe().put(BAR, 0L);
		prices.getHa().put(BAR, 0L);
		assertTrue("a worthless item is never notable", find(tally(BAR, 1), LootPriceMode.GE, 0).isEmpty());
	}

	@Test
	public void stackValueSaturates()
	{
		assertEquals(Long.valueOf(Long.MAX_VALUE), NotableDrops.stackValue(Long.MAX_VALUE / 2, 3));
		assertNull(NotableDrops.stackValue(null, 3));
		assertNull(NotableDrops.stackValue(5L, 0));
		assertEquals(Long.valueOf(0), NotableDrops.stackValue(0L, 3));
	}

	@Test
	public void capKeepsTheMostValuableAndEveryPet()
	{
		List<NotableDrop> drops = new ArrayList<>();
		for (int i = 0; i < NotableDrops.MAX_PER_TASK; i++)
		{
			drops.add(item(1000 + i, 100_000 + i, i));
		}
		NotableDrop pet = NotableDrop.pet(NotableDrop.Pet.RECEIVED, 50);
		List<NotableDrop> withPet = NotableDrops.add(drops, Collections.singletonList(pet));
		assertEquals(NotableDrops.MAX_PER_TASK, withPet.size());
		assertEquals("the cheapest item made way", Integer.valueOf(1001), withPet.get(0).getItemId());
		assertEquals("added last", pet, withPet.get(withPet.size() - 1));

		List<NotableDrop> cheap = NotableDrops.add(withPet, Collections.singletonList(item(9, 1, 60)));
		assertEquals("a drop worth less than all kept ones is left out", withPet, cheap);

		// Among equal values the oldest goes first.
		List<NotableDrop> equal = new ArrayList<>();
		for (int i = 0; i <= NotableDrops.MAX_PER_TASK; i++)
		{
			equal.add(item(2000 + i, 5, i));
		}
		List<NotableDrop> bounded = NotableDrops.sanitize(equal);
		assertEquals(NotableDrops.MAX_PER_TASK, bounded.size());
		assertEquals(Integer.valueOf(2001), bounded.get(0).getItemId());

		// Pets above an item at the largest value.
		assertTrue(NotableDrops.rank(pet) > NotableDrops.rank(item(1, Long.MAX_VALUE, 0)));
	}

	@Test
	public void sanitizeDropsNullsAndNewestFirstOrdersByTime()
	{
		NotableDrop a = item(1, 200_000, 10);
		NotableDrop b = item(2, 300_000, 30);
		NotableDrop c = item(3, 400_000, 30);
		NotableDrop d = item(4, 500_000, 20);
		assertEquals(Arrays.asList(a, b), NotableDrops.sanitize(Arrays.asList(a, null, b)));
		assertTrue(NotableDrops.sanitize(null).isEmpty());
		assertEquals("equal times: the later-added first", Arrays.asList(c, b, d, a),
			NotableDrops.newestFirst(Arrays.asList(a, b, c, d)));
	}

	@Test
	public void petAndValues()
	{
		NotableDrop pet = NotableDrop.pet(null, 5);
		assertTrue(pet.isPet());
		assertEquals(NotableDrop.Pet.RECEIVED, pet.getPet());
		assertNull(pet.getItemId());
		assertNull(pet.value(LootPriceMode.GE));
		NotableDrop whip = NotableDrop.item(WHIP, "Abyssal whip", 1, 1_500_000L, 72_000L, 5);
		assertEquals(Long.valueOf(1_500_000), whip.value(null));
		assertEquals(Long.valueOf(72_000), whip.value(LootPriceMode.HIGH_ALCH));
	}

	@Test
	public void formatting()
	{
		NotableDrop whip = NotableDrop.item(WHIP, "Abyssal whip", 1, 1_500_000L, 72_000L, 5);
		assertEquals("Abyssal whip: 1.5M", LedgerHistory.formatNotableDrop(whip, LootPriceMode.GE, false));
		assertEquals("Abyssal whip: 72,000 gp", LedgerHistory.formatNotableDrop(whip, LootPriceMode.HIGH_ALCH, true));
		NotableDrop bars = NotableDrop.item(BAR, "Rune bar", 1500, 18_000_000L, null, 5);
		assertEquals("Rune bar x 1,500: 18M", LedgerHistory.formatNotableDrop(bars, LootPriceMode.GE, false));
		assertEquals("Rune bar x 1,500: -", LedgerHistory.formatNotableDrop(bars, LootPriceMode.HIGH_ALCH, false));
		assertEquals("Item 7: 5", LedgerHistory.formatNotableDrop(NotableDrop.item(7, null, 1, 5L, 5L, 0),
			LootPriceMode.GE, false));
		assertEquals("Pet", LedgerHistory.formatNotableDrop(NotableDrop.pet(NotableDrop.Pet.RECEIVED, 0), null,
			false));
		assertEquals("Pet (already owned)", LedgerHistory.formatNotableDrop(
			NotableDrop.pet(NotableDrop.Pet.DUPLICATE, 0), null, true));
	}

	@Test
	public void liveLinesAndTooltip()
	{
		ItemTally loot = tally(KEY, 2, ClueScrollIds.HARD[0], 1, ClueScrollIds.ELITE[0], 2);
		List<NotableDrop> drops = Arrays.asList(item(1, 100_000, 1), item(2, 200_000, 2),
			NotableDrop.item(3, "A <b>", 1, 300_000L, 1L, 3), item(4, 400_000, 4));
		assertEquals(Arrays.asList("Keys: 2 brimstone", "Clues: 1 hard, 2 elite", "Notable drops:", "  Item 4: 400K",
			"  A <b>: 300K", "  Item 2: 200K", "  +1 more"),
			LedgerHistory.liveTaskLootLines(KeysAndClues.of(loot), drops, LootPriceMode.GE));
		assertTrue(LedgerHistory.liveTaskLootLines(KeysAndClues.NONE, null, LootPriceMode.GE).isEmpty());
		assertEquals("<br>Notable drops:<br>&nbsp;&nbsp;Item 4: 400,000 gp<br>&nbsp;&nbsp;A &lt;b&gt;: 300,000 gp"
				+ "<br>&nbsp;&nbsp;Item 2: 200,000 gp<br>&nbsp;&nbsp;Item 1: 100,000 gp",
			LedgerHistory.notableDropsTooltip(drops, LootPriceMode.GE));
		assertEquals("", LedgerHistory.notableDropsTooltip(Collections.emptyList(), LootPriceMode.GE));
	}

	@Test
	public void historyTooltipShowsOnlyKnownData()
	{
		LedgerRecord old = new LedgerRecord();
		assertEquals("no loot, no drops: no lines", "", LedgerHistory.taskLootTooltip(old, LootPriceMode.GE));
		old.setLoot(Collections.singletonMap(BAR, 5L));
		assertEquals("", LedgerHistory.taskLootTooltip(old, LootPriceMode.GE));
		old.setLoot(Collections.singletonMap(KEY, 1L));
		old.setNotableDrops(Collections.singletonList(NotableDrop.pet(NotableDrop.Pet.RECEIVED, 1)));
		assertEquals("<br>Keys: 1 brimstone<br>Notable drops:<br>&nbsp;&nbsp;Pet",
			LedgerHistory.taskLootTooltip(old, LootPriceMode.GE));
	}

	@Test
	public void sessionKeepsDropsOnlyWhileRunningAndHandsThemOn()
	{
		long[] now = {1_000_000L};
		SessionTracker tracker = new SessionTracker(() -> now[0]);
		tracker.observe("Kraken", 42, 10, 10, TaskContext.NONE, false);
		NotableDrop whip = item(WHIP, 1_500_000, 1);
		NotableDrop pet = NotableDrop.pet(NotableDrop.Pet.RECEIVED, 2);
		assertFalse("idle", tracker.isRecordingLoot());
		assertFalse(tracker.addLoot(tally(WHIP, 1), Collections.singletonList(whip)));
		assertFalse(tracker.addPet(pet));
		assertTrue(tracker.play(555L));
		assertTrue(tracker.isRecordingLoot());
		assertTrue(tracker.addLoot(tally(WHIP, 1), Collections.singletonList(whip)));
		assertTrue(tracker.addPet(pet));
		assertFalse(tracker.addPet(null));
		assertFalse("no loot, no drops", tracker.addLoot(new ItemTally(), Collections.singletonList(whip)));
		tracker.pause();
		assertFalse(tracker.isRecordingLoot());
		assertFalse(tracker.addLoot(tally(WHIP, 1), Collections.singletonList(whip)));
		assertFalse(tracker.addPet(pet));
		assertEquals(Arrays.asList(whip, pet), tracker.getNotableDrops());

		// Through a snapshot (JSON) and a restore.
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.summary(), null, now[0]);
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(Arrays.asList(whip, pet), read.getNotableDrops());
		assertEquals(Arrays.asList(whip, pet), read.toSummary().getNotableDrops());
		SessionTracker restored = new SessionTracker(() -> now[0]);
		restored.observe("Kraken", 42, 10, 10, TaskContext.NONE, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, null));
		assertEquals(Arrays.asList(whip, pet), restored.getNotableDrops());

		// Into a record and back from JSON.
		LedgerRecord record = LedgerRecord.fromSummary(tracker.summary(), true);
		LedgerRecord readRecord = gson.fromJson(gson.toJson(record), LedgerRecord.class);
		assertEquals(Arrays.asList(whip, pet), readRecord.getNotableDrops());

		// None: stored as null.
		tracker.stop();
		SessionTracker empty = new SessionTracker(() -> now[0]);
		empty.observe("Kraken", 42, 10, 10, TaskContext.NONE, false);
		assertTrue(empty.play(555L));
		assertNull(LedgerRecord.fromSummary(empty.summary(), true).getNotableDrops());
		assertNull(SessionSnapshot.fromSummary(empty.summary(), null, now[0]).getNotableDrops());
	}

	@Test
	public void heldCompletionTakesLateDropsAndAnOldSnapshotHasNone()
	{
		long[] now = {1_000_000L};
		SessionTracker tracker = new SessionTracker(() -> now[0]);
		tracker.observe("Kraken", 42, 1, 10, TaskContext.NONE, false);
		assertTrue(tracker.play(555L));
		tracker.observe("Kraken", 42, 0, 10, TaskContext.NONE, true);
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.isRecordingLoot());
		NotableDrop whip = item(WHIP, 1_500_000, 1);
		NotableDrop pet = NotableDrop.pet(NotableDrop.Pet.RECEIVED, 2);
		assertTrue(tracker.addLoot(tally(WHIP, 1), Collections.singletonList(whip)));
		assertTrue(tracker.addPet(pet));
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(Arrays.asList(whip, pet), held.getNotableDrops());

		SessionSnapshot old = gson.fromJson("{\"schemaVersion\":2,\"sessionId\":\"s\",\"accountHash\":555,"
			+ "\"monster\":\"Kraken\",\"creatureId\":42,\"initialAmount\":10,\"kills\":1,\"remaining\":9}",
			SessionSnapshot.class);
		assertNull(old.getNotableDrops());
		SessionTracker restored = new SessionTracker(() -> now[0]);
		restored.observe("Kraken", 42, 9, 10, TaskContext.NONE, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(old, null));
		assertTrue(restored.getNotableDrops().isEmpty());
	}
}

