	/**
	 * The {@code SkillIconManager} fake. RuneLite's reads only bundled images (no client), but its cache is not
	 * thread-safe, so the panel calls it on the EDT, as the XP tracker does; the harness fails a call from any other
	 * thread. It is not counted as a client read.
	 */
	private Object answerSkillIconManager(InvocationOnMock invocation) throws Throwable
	{
		final Method method = invocation.getMethod();
		if (method.getDeclaringClass() == Object.class)
		{
			return RETURNS_DEFAULTS.answer(invocation);
		}
		if (!SwingUtilities.isEventDispatchThread())
		{
			recordError("thread check", new AssertionError("SkillIconManager." + method.getName()
				+ " called off the EDT, on " + Thread.currentThread().getName()));
		}
		if ("getSkillImage".equals(method.getName()))
		{
			final boolean small = method.getParameterCount() == 2 && invocation.<Boolean>getArgument(1);
			final BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
			itemImages.put(image, "skill " + invocation.<Skill>getArgument(0).name() + (small ? "" : " large"));
			return image;
		}
		return RETURNS_DEFAULTS.answer(invocation);
	}

	private Object answerItemManager(InvocationOnMock invocation) throws Throwable
	{
		final Method method = invocation.getMethod();
		if (method.getDeclaringClass() == Object.class)
		{
			return RETURNS_DEFAULTS.answer(invocation);
		}
		final String name = method.getName();
		if ("getImage".equals(name) && method.getParameterCount() == 3)
		{
			// RuneLite allows getImage on any thread (it queues the sprite to the client thread); the panel calls it on
			// the EDT, as Loot Tracker does. It reads nothing from the client, so it is not counted as a client read.
			if (!SwingUtilities.isEventDispatchThread())
			{
				recordError("thread check", new AssertionError("ItemManager.getImage called off the EDT, on "
					+ Thread.currentThread().getName()));
			}
			itemImageRequests.incrementAndGet();
			final AsyncBufferedImage image = new AsyncBufferedImage(clientThread, Constants.ITEM_SPRITE_WIDTH,
				Constants.ITEM_SPRITE_HEIGHT, BufferedImage.TYPE_INT_ARGB);
			final int quantity = invocation.getArgument(1);
			itemImages.put(image, invocation.<Integer>getArgument(0)
				+ (invocation.<Boolean>getArgument(2) ? " x" + quantity : ""));
			return image;
		}
		checkClientThread("ItemManager." + name);
		switch (name)
		{
			case "canonicalize":
				return notedItems.getOrDefault(invocation.<Integer>getArgument(0), invocation.getArgument(0));
			case "getItemPrice":
				if (intParams(method, 1))
				{
					itemPriceLookups.merge(invocation.<Integer>getArgument(0), 1, Integer::sum);
					return gePrices.getOrDefault(invocation.<Integer>getArgument(0), 0L);
				}
				break;
			case "getItemComposition":
				itemCompositionLookups.merge(invocation.<Integer>getArgument(0), 1, Integer::sum);
				return composition(invocation.getArgument(0));
			case "getItemStats":
				// Only stackable weapons have stats (loaded); other items' stats are never loaded.
				return stackableWeapons.contains(invocation.<Integer>getArgument(0)) ? new ItemStats(true, 0, 0,
					ItemEquipmentStats.builder().slot(EquipmentInventorySlot.WEAPON.getSlotIdx()).build()) : null;
			default:
				break;
		}
		return RETURNS_DEFAULTS.answer(invocation);
	}

	/** Item composition fake; an undefined id is an untradeable item with no actions (never a supply). */
	private ItemComposition composition(int id)
	{
		return compositions.computeIfAbsent(id, k -> mock(ItemComposition.class, withSettings().stubOnly().defaultAnswer(
			invocation ->
			{
				final String name = invocation.getMethod().getName();
				if (invocation.getMethod().getDeclaringClass() != Object.class)
				{
					checkClientThread("ItemComposition." + name);
				}
				final Integer unnoted = notedItems.get(k);
				final ItemDef def = itemDefs.getOrDefault(k, new ItemDef("Item " + k, new String[0], false, 0));
				switch (name)
				{
					case "getId":
						return k;
					case "getName":
						return unnoted != null && itemDefs.containsKey(unnoted) ? itemDefs.get(unnoted).name : def.name;
					case "getNote":
						// Any template id other than -1 marks a noted item.
						return unnoted != null ? 799 : -1;
					case "getLinkedNoteId":
						return unnoted != null ? unnoted : -1;
					case "getPlaceholderTemplateId":
						return -1;
					case "getInventoryActions":
						return def.actions.clone();
					case "isTradeable":
						return def.tradeable;
					case "isStackable":
						return stackableWeapons.contains(k);
					case "getHaPrice":
						return def.haPrice;
					default:
						return RETURNS_DEFAULTS.answer(invocation);
				}
			})));
	}

	/** Looks up a package-private {@link ClientThread} frame method; see {@link HarnessClientThread}. */
	private static Method clientThreadFrameMethod(String name)
	{
		try
		{
			final Method method = ClientThread.class.getDeclaredMethod(name);
			method.setAccessible(true);
			return method;
		}
		catch (NoSuchMethodException e)
		{
			throw new AssertionError("ClientThread." + name
				+ "() not found; has RuneLite changed how Hooks run the client thread's queues?", e);
		}
	}

	/**
	 * The real {@link ClientThread}, with every queued or inline task wrapped so an exception it throws is reported
	 * (the real class only logs it) and so the harness knows how many tasks are queued. Its queues are run through
	 * its package-private {@code invoke()} and {@code invokeTickEnd()}, which the client's Hooks call every frame.
	 * Those are called by reflection: a test-source helper in {@code net.runelite.client.callback} could call them
	 * directly, but the client jar is signed, so the JVM refuses unsigned classes in its packages
	 * ({@code SecurityException: signer information does not match}). The methods are looked up once, when
	 * PluginHarness loads, so a RuneLite update that renames them fails every harness test with a clear message.
	 */
	final class HarnessClientThread extends ClientThread
	{
		/** Tasks in either queue: queued, or run inline and re-queued after returning {@code false}. */
		private final AtomicInteger pending = new AtomicInteger();

		@Override
		public void invoke(BooleanSupplier r)
		{
			// Runs inline on the client thread (a false result queues it, see Captured); otherwise calls invokeLater.
			super.invoke(capture(r));
		}

		@Override
		public void invokeLater(BooleanSupplier r)
		{
			final Captured captured = capture(r);
			captured.queued();
			super.invokeLater(captured);
		}

		@Override
		public void invokeAtTickEnd(Runnable r)
		{
			final Captured captured = capture(() ->
			{
				r.run();
				return true;
			});
			captured.queued();
			super.invokeAtTickEnd(captured::getAsBoolean);
		}

		private Captured capture(BooleanSupplier r)
		{
			if (r instanceof Captured)
			{
				return (Captured) r;
			}
			return new Captured(r);
		}

		int pendingCount()
		{
			return pending.get();
		}

		/** Runs the queued tasks, then the tick-end tasks, as a client frame does. */
		void runQueues()
		{
			runFrameMethod(INVOKE);
			runFrameMethod(INVOKE_TICK_END);
		}

		private void runFrameMethod(Method method)
		{
			try
			{
				method.invoke(this);
			}
			catch (InvocationTargetException e)
			{
				recordError("ClientThread." + method.getName(), e.getCause());
			}
			catch (IllegalAccessException e)
			{
				throw new AssertionError(e);
			}
		}

		/**
		 * A client-thread task that reports its exception before the client thread swallows it, and keeps
		 * {@link #pending} up to date: counted while it is in a queue, until it returns {@code true} or throws (both of
		 * which remove it, inline or queued).
		 */
		private final class Captured implements BooleanSupplier
		{
			private final BooleanSupplier task;
			private boolean inQueue;

			Captured(BooleanSupplier task)
			{
				this.task = task;
			}

			synchronized void queued()
			{
				if (!inQueue)
				{
					inQueue = true;
					pending.incrementAndGet();
				}
			}

			private synchronized void done()
			{
				if (inQueue)
				{
					inQueue = false;
					pending.decrementAndGet();
				}
			}

			@Override
			public boolean getAsBoolean()
			{
				final boolean result;
				try
				{
					result = task.getAsBoolean();
				}
				catch (RuntimeException | Error e)
				{
					done();
					recordError("client thread task", e);
					throw e;
				}
				if (result)
				{
					done();
				}
				else
				{
					// Re-run later: ClientThread keeps it queued, or queues it if it ran inline.
					queued();
				}
				return result;
			}
		}
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.SwingUtilities;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ServerNpcLoot;
import org.junit.Rule;
import org.junit.Test;

/**
 * The threading semantics {@link PluginHarness} promises, so plugin-level tests can rely on them: client-thread
 * invokes behave as in the client, executor and EDT work happens only when drained, errors the client would only
 * log fail the test, and the real LootManager's loot lands where the event bus orders it.
 */
public class PluginHarnessSelfTest
{
	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void invokeRunsAtOnceOnTheClientThreadAndInvokeLaterIsQueued()
	{
		AtomicInteger ran = new AtomicInteger();
		harness.clientThread.invoke(ran::incrementAndGet);
		assertEquals(1, ran.get());

		harness.clientThread.invokeLater(ran::incrementAndGet);
		assertEquals(1, ran.get());
		harness.runClientThread();
		assertEquals(2, ran.get());
	}

	@Test
	public void invokeFromTheEdtIsQueuedForTheClientThread()
	{
		AtomicBoolean onClientThread = new AtomicBoolean();
		harness.onEdt(() -> harness.clientThread.invoke(() -> onClientThread.set(harness.client.isClientThread())));
		assertFalse("queued, not run on the EDT", onClientThread.get());
		harness.drain();
		assertTrue(onClientThread.get());
	}

	@Test
	public void invokeReturningFalseIsRunAgainOnTheNextFrame()
	{
		AtomicInteger calls = new AtomicInteger();
		harness.clientThread.invoke(() -> calls.incrementAndGet() >= 3);
		assertEquals(1, calls.get());
		harness.runClientThread();
		assertEquals(2, calls.get());
		harness.runClientThread();
		assertEquals(3, calls.get());
		harness.runClientThread();
		assertEquals("done after returning true", 3, calls.get());
	}

	@Test
	public void inlineInvokeReturningFalseIsDrainedOnTheNextFrame()
	{
		AtomicInteger calls = new AtomicInteger();
		harness.clientThread.invoke(() -> calls.incrementAndGet() >= 2);
		assertEquals(1, calls.get());
		harness.drain();
		assertEquals(2, calls.get());
	}

	@Test
	public void tickEndWorkRunsAfterTheInvokeQueueAndIsDrained()
	{
		List<String> order = new ArrayList<>();
		harness.clientThread.invokeAtTickEnd(() -> order.add("tick end"));
		harness.clientThread.invokeLater(() -> order.add("invoke"));
		harness.drain();
		assertEquals(Arrays.asList("invoke", "tick end"), order);
	}

	@Test
	public void drainFailsInsteadOfHangingOnAnEndlesslyRetriedTask()
	{
		AtomicBoolean done = new AtomicBoolean();
		harness.clientThread.invokeLater(done::get);
		try
		{
			harness.drain();
			fail("drain should have given up");
		}
		catch (AssertionError expected)
		{
			// Let the task finish so the harness can clean up.
			done.set(true);
		}
	}

	@Test
	public void executorWorkRunsOnlyWhenDrainedAndNotAsTheClientThread() throws Exception
	{
		AtomicBoolean onClientThread = new AtomicBoolean(true);
		Future<?> future = harness.executor.submit(() -> onClientThread.set(harness.client.isClientThread()));
		assertFalse(future.isDone());
		harness.drain();
		assertTrue(future.isDone());
		future.get();
		assertFalse(onClientThread.get());
	}

	@Test
	public void clientCallsOffTheClientThreadAreReported()
	{
		harness.onEdt(() -> harness.client.getGameState());
		harness.executor.execute(() -> harness.itemManager.getItemPrice(1));
		harness.drain();
		List<Throwable> errors = harness.takeErrors();
		assertEquals(2, errors.size());
		assertTrue(errors.get(0).getMessage().contains("Client.getGameState called off the client thread"));
		assertTrue(errors.get(1).getMessage().contains("ItemManager.getItemPrice called off the client thread"));
	}

	@Test
	public void otherClientFakesAreCheckedToo()
	{
		harness.setInventory(PluginHarness.item(ItemID.BONES, 1));
		harness.openInterface(InterfaceID.BANKMAIN);
		ItemContainer inventory = harness.client.getItemContainer(InventoryID.INV);
		Player player = harness.client.getLocalPlayer();
		Widget widget = harness.client.getWidget(InterfaceID.BANKMAIN, 0);
		harness.onEdt(() ->
		{
			inventory.getItems();
			player.getName();
			widget.isHidden();
		});
		String all = harness.takeErrors().toString();
		assertTrue(all, all.contains("ItemContainer.getItems called off the client thread"));
		assertTrue(all, all.contains("Player.getName called off the client thread"));
		assertTrue(all, all.contains("Widget.isHidden called off the client thread"));
	}

	@Test
	public void edtWorkPostedByEdtWorkIsDrainedToo()
	{
		AtomicBoolean ran = new AtomicBoolean();
		SwingUtilities.invokeLater(() -> SwingUtilities.invokeLater(() -> SwingUtilities.invokeLater(() ->
		{
			harness.client.getGameState();
			ran.set(true);
		})));
		harness.drain();
		assertTrue("the innermost runnable ran before drain returned", ran.get());
		List<Throwable> errors = harness.takeErrors();
		assertEquals(errors.toString(), 1, errors.size());
		assertTrue(errors.get(0).getMessage().contains("Client.getGameState called off the client thread"));
	}

	@Test
	public void uncaughtExceptionsOnOtherThreadsAreReported() throws InterruptedException
	{
		Thread thread = new Thread(() ->
		{
			throw new IllegalStateException("thread failed");
		}, "harness-self-test");
		thread.start();
		thread.join();
		String all = harness.takeErrors().toString();
		assertTrue(all, all.contains("uncaught on harness-self-test"));
		assertTrue(all, all.contains("thread failed"));
	}

	/**
	 * The real LootManager posts {@link ServerNpcLoot} from its default-priority {@code onGameTick}. The event bus runs
	 * it after the plugin's own default-priority handler (equal priority: class-name order, and {@code com.shmayvan}
	 * sorts before {@code net.runelite}) and before the plugin's priority -1 grace ticker. So the plugin has already
	 * held the completed task when the completion tick's loot arrives, and the ticker releases it only after the last
	 * grace tick's loot.
	 */
	@Test
	public void lootManagerLootArrivesAfterThePluginsTickHandlerAndBeforeTheGraceTicker()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 1, 3);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertTrue(harness.play());

		List<String> lootSeen = new ArrayList<>();
		EventBus.Subscriber recorder = harness.eventBus.register(ServerNpcLoot.class, loot -> lootSeen.add(
			loot.getComposition().getName() + " held=" + harness.tracker().hasPendingCompletion()), 0);

		harness.completeTask();
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		for (int i = 0; i < SessionTracker.COMPLETION_LOOT_GRACE_TICKS; i++)
		{
			assertTrue("held until the window ends", harness.tracker().hasPendingCompletion());
			harness.lootOnNextTick(ItemID.BONES, 1);
			harness.tick();
		}
		harness.eventBus.unregister(recorder);

		// Each tick's loot came from LootManager (named by the NPC definition it looked up) while the task was held.
		List<String> expected = new ArrayList<>();
		for (int i = 0; i <= SessionTracker.COMPLETION_LOOT_GRACE_TICKS; i++)
		{
			expected.add(PluginHarness.LOOT_NPC_NAME + " held=true");
		}
		assertEquals(expected, lootSeen);
		assertFalse("released after the last grace tick's loot", harness.tracker().hasPendingCompletion());
		LedgerRecord record = harness.onlyRecord(PluginHarness.ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Long.valueOf(1 + SessionTracker.COMPLETION_LOOT_GRACE_TICKS), record.getLoot().get(ItemID.BONES));
	}

	public static final class ThrowingSubscriber
	{
		@Subscribe
		public void onGameTick(GameTick tick)
		{
			throw new IllegalStateException("handler failed");
		}
	}

	@Test
	public void exceptionsTheClientWouldOnlyLogAreReported()
	{
		EventBus bus = harness.eventBus;
		ThrowingSubscriber subscriber = new ThrowingSubscriber();
		bus.register(subscriber);
		harness.tick();
		bus.unregister(subscriber);
		harness.clientThread.invokeLater(() ->
		{
			throw new IllegalStateException("client thread task failed");
		});
		harness.executor.execute(() ->
		{
			throw new IllegalStateException("executor task failed");
		});
		SwingUtilities.invokeLater(() ->
		{
			throw new IllegalStateException("EDT task failed");
		});
		harness.drain();

		String all = harness.takeErrors().toString();
		assertTrue(all, all.contains("handler failed"));
		assertTrue(all, all.contains("client thread task failed"));
		assertTrue(all, all.contains("executor task failed"));
		assertTrue(all, all.contains("EDT task failed"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.Set;
import java.util.TreeSet;
import org.junit.Test;

/** When unavailable today's prices are looked up again: the interval, the cap and what resets them. */
public class PriceRetryTest
{
	private final PriceRetry retry = new PriceRetry();

	/** Ticks until an id is due, at most {@code max} ticks; the ids due, or empty when none was. */
	private Set<Integer> tickUntilDue(int max)
	{
		for (int i = 0; i < max; i++)
		{
			Set<Integer> due = retry.tick();
			if (!due.isEmpty())
			{
				return due;
			}
		}
		return Collections.emptySet();
	}

	@Test
	public void nothingIsDueWithoutMissedIds()
	{
		assertTrue(retry.isEmpty());
		assertEquals(Collections.emptySet(), tickUntilDue(100));
		retry.missed(Collections.emptySet());
		assertEquals(Collections.emptySet(), tickUntilDue(100));
	}

	@Test
	public void missedIdsAreDueEveryIntervalTicks()
	{
		retry.missed(Arrays.asList(1, 2));
		for (int i = 1; i < PriceRetry.INTERVAL_TICKS; i++)
		{
			assertEquals("tick " + i, Collections.emptySet(), retry.tick());
		}
		assertEquals(new TreeSet<>(Arrays.asList(1, 2)), retry.tick());
		for (int i = 1; i < PriceRetry.INTERVAL_TICKS; i++)
		{
			assertEquals(Collections.emptySet(), retry.tick());
		}
		assertEquals(new TreeSet<>(Arrays.asList(1, 2)), retry.tick());
	}

	@Test
	public void foundIdsAreNotTriedAgain()
	{
		retry.missed(Arrays.asList(1, 2));
		assertEquals(2, tickUntilDue(PriceRetry.INTERVAL_TICKS).size());
		retry.found(Collections.singleton(1));
		assertEquals(Collections.singleton(2), tickUntilDue(PriceRetry.INTERVAL_TICKS));
		retry.found(Collections.singleton(2));
		assertTrue(retry.isEmpty());
		assertEquals(Collections.emptySet(), tickUntilDue(100));
	}

	@Test
	public void anIdIsTriedAtMostMaxAttemptsTimes()
	{
		retry.missed(Collections.singleton(7));
		int tries = 0;
		for (int tick = 0; tick < PriceRetry.INTERVAL_TICKS * (PriceRetry.MAX_ATTEMPTS + 5); tick++)
		{
			tries += retry.tick().size();
		}
		assertEquals(PriceRetry.MAX_ATTEMPTS, tries);
		assertTrue("dropped after its last try", retry.isEmpty());
	}

	@Test
	public void aNewMissResetsTheTriesButKeepsTheCountdown()
	{
		retry.missed(Collections.singleton(7));
		for (int i = 0; i < PriceRetry.MAX_ATTEMPTS - 1; i++)
		{
			assertEquals(Collections.singleton(7), tickUntilDue(PriceRetry.INTERVAL_TICKS));
		}
		// Two ticks into the countdown, a new request misses 7 again and also 8.
		retry.tick();
		retry.tick();
		retry.missed(Arrays.asList(7, 8));
		for (int i = 2; i < PriceRetry.INTERVAL_TICKS - 1; i++)
		{
			assertEquals(Collections.emptySet(), retry.tick());
		}
		assertEquals("due when the running countdown ends", new TreeSet<>(Arrays.asList(7, 8)), retry.tick());
		int tries = 1;
		for (int tick = 0; tick < PriceRetry.INTERVAL_TICKS * (PriceRetry.MAX_ATTEMPTS + 5); tick++)
		{
			tries += retry.tick().contains(7) ? 1 : 0;
		}
		assertEquals("7 got a full set of tries again", PriceRetry.MAX_ATTEMPTS, tries);
	}

	@Test
	public void clearForgetsEverything()
	{
		retry.missed(Collections.singleton(7));
		retry.clear();
		assertTrue(retry.isEmpty());
		assertEquals(Collections.emptySet(), tickUntilDue(100));
		retry.missed(Collections.singleton(8));
		assertFalse(retry.isEmpty());
		assertEquals(Collections.singleton(8), tickUntilDue(PriceRetry.INTERVAL_TICKS));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.SaveDecision.Action;
import static com.shmayvan.slayerledger.SaveDecision.EndReason;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class SaveDecisionTest
{
	private static final long ACCOUNT = 42L;

	private static Action decide(boolean hasTask, long account, boolean completed, EndReason reason, boolean confirm)
	{
		return SaveDecision.decide(hasTask, account, completed, reason, confirm);
	}

	@Test
	public void completedIsSavedForEveryReason()
	{
		for (EndReason reason : EndReason.values())
		{
			assertEquals(Action.SAVE_COMPLETED, decide(true, ACCOUNT, true, reason, true));
			assertEquals(Action.SAVE_COMPLETED, decide(true, ACCOUNT, true, reason, false));
		}
	}

	@Test
	public void playerStopIncomplete()
	{
		assertEquals(Action.PROMPT, decide(true, ACCOUNT, false, EndReason.PLAYER_STOP, true));
		assertEquals(Action.SAVE_PARTIAL, decide(true, ACCOUNT, false, EndReason.PLAYER_STOP, false));
	}

	@Test
	public void systemEndedIncompleteIsPartialWithNotice()
	{
		assertEquals(Action.SAVE_PARTIAL_WITH_NOTICE, decide(true, ACCOUNT, false, EndReason.SYSTEM, true));
		assertEquals(Action.SAVE_PARTIAL_WITH_NOTICE, decide(true, ACCOUNT, false, EndReason.SYSTEM, false));
	}

	@Test
	public void restoreMismatchIsPartialWithNotice()
	{
		assertEquals(Action.SAVE_PARTIAL_WITH_NOTICE, decide(true, ACCOUNT, false, EndReason.RESTORE_MISMATCH, true));
		assertEquals(Action.SAVE_PARTIAL_WITH_NOTICE, decide(true, ACCOUNT, false, EndReason.RESTORE_MISMATCH, false));
	}

	@Test
	public void shutdownLogoutAndAccountSwitchPersistInsteadOfSaving()
	{
		for (EndReason reason : new EndReason[]{EndReason.SHUTDOWN, EndReason.LOGOUT, EndReason.ACCOUNT_SWITCH})
		{
			assertEquals(Action.PERSIST_ACTIVE, decide(true, ACCOUNT, false, reason, true));
			assertEquals(Action.PERSIST_ACTIVE, decide(true, ACCOUNT, false, reason, false));
		}
	}

	@Test
	public void unresolvedPromptIsPartialWithoutPrompt()
	{
		assertEquals(Action.SAVE_PARTIAL, decide(true, ACCOUNT, false, EndReason.PROMPT_UNRESOLVED, true));
		assertEquals(Action.SAVE_PARTIAL, decide(true, ACCOUNT, false, EndReason.PROMPT_UNRESOLVED, false));
	}

	@Test
	public void noTaskOrNoAccountIsDiscarded()
	{
		for (EndReason reason : EndReason.values())
		{
			assertEquals(Action.DISCARD, decide(false, ACCOUNT, false, reason, true));
			assertEquals(Action.DISCARD, decide(false, ACCOUNT, true, reason, false));
			assertEquals(Action.DISCARD, decide(true, SessionTracker.NO_ACCOUNT, true, reason, true));
			assertEquals(Action.DISCARD, decide(true, SessionTracker.NO_ACCOUNT, false, reason, false));
		}
	}

	@Test
	public void summaryOverloadUsesSessionAccount()
	{
		SessionTracker tracker = new SessionTracker(() -> 0L);
		tracker.observe("Abyssal demons", 1, 10, false);
		tracker.play(ACCOUNT);
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(Action.PROMPT, SaveDecision.decide(summary, EndReason.PLAYER_STOP, true));
		assertEquals(Action.SAVE_PARTIAL_WITH_NOTICE, SaveDecision.decide(summary, EndReason.SYSTEM, true));
		assertEquals(Action.PERSIST_ACTIVE, SaveDecision.decide(summary, EndReason.SHUTDOWN, true));
	}
}

package com.shmayvan.slayerledger;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/**
 * Saved-record fixtures for tests: gives a record built from totals the items those totals stand for, so it is
 * valued at today's prices like the tasks the plugin saves, and a {@code ~} only ever means a price that is really
 * unavailable. The loot is coins (always 1 gp, in {@link PluginHarness} too, without a definition); the supplies are
 * manta rays at {@link #SUPPLY_PRICE} gp, which a harness test defines with {@link #define}.
 */
final class SavedItems
{
	/** The loot item: coins, worth 1 gp each at GE and high alch. */
	static final int LOOT = ItemValuation.COINS;
	/** The supply item, worth {@link #SUPPLY_PRICE} gp at GE today. */
	static final int SUPPLY = ItemID.MANTARAY;
	static final long SUPPLY_PRICE = 50;

	private SavedItems()
	{
	}

	/** Defines the supply item in {@code harness} at {@link #SUPPLY_PRICE} gp. */
	static void define(PluginHarness harness)
	{
		harness.defineItem(SUPPLY, "Manta ray", SUPPLY_PRICE, 0);
	}

	/** Today's GE prices of the fixture items, for valuations worked out without the plugin. */
	static Map<Integer, Long> todaysPrices()
	{
		Map<Integer, Long> prices = new HashMap<>();
		prices.put(LOOT, 1L);
		prices.put(SUPPLY, SUPPLY_PRICE);
		return prices;
	}

	/**
	 * Gives {@code record} loot and supply items worth its saved loot and supplies GE totals at today's prices, and
	 * saves their unit prices with it; its high alch totals are kept as they are. A supplies total must be a whole
	 * number of {@link #SUPPLY_PRICE}. Returns {@code record}.
	 */
	static LedgerRecord withItems(LedgerRecord record)
	{
		long loot = record.getLootGeValue() == null ? 0 : record.getLootGeValue();
		long supplies = record.getSuppliesGeValue() == null ? 0 : record.getSuppliesGeValue();
		if (supplies % SUPPLY_PRICE != 0)
		{
			throw new IllegalArgumentException("supplies of " + supplies + " gp are not a whole number of items");
		}
		Map<Integer, Long> lootItems = new HashMap<>();
		if (loot > 0)
		{
			lootItems.put(LOOT, loot);
		}
		record.setLoot(lootItems);
		if (supplies > 0)
		{
			Map<Integer, Long> supplyItems = new HashMap<>();
			supplyItems.put(SUPPLY, supplies / SUPPLY_PRICE);
			record.setSupplies(supplyItems);
		}
		record.setUnitGePrices(todaysPrices());
		Map<Integer, Long> ha = new HashMap<>();
		ha.put(LOOT, 1L);
		ha.put(SUPPLY, 0L);
		record.setUnitHaPrices(ha);
		return record;
	}
}

