/**
 * The ledger and active-session JSON, pinned byte for byte. The expected strings below were produced by the
 * build before the session value objects (SessionLoot, SessionCounters, the Summary builder) were introduced, from the
 * same scenario, so a refactor of how a session is modelled can't change what is written to disk. Every field of
 * {@link LedgerRecord} and {@link SessionSnapshot} is set at least once.
 */
public class SessionJsonFormatTest
{
	private static final long ACCOUNT = 123456789L;
	private static final long START = 1_700_000_000_000L;
	private static final int BOSS_TASK = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 5);
	private static final int REGION = 12850;
	private static final int WHIP = 4151;
	private static final int ASHES = 592;
	private static final int COINS = 995;
	/** Tradeable without a GE price, so the record counts it as unpriced. */
	private static final int UNPRICED_LOOT = 11286;
	private static final int PRAYER_POTION = 2434;
	private static final int SHARK = 385;
	private static final int UNPRICED_SUPPLY = 12625;
	/** Task-completion counters when the snapshot was taken. */
	private static final int[] COUNTERS = {3, 0, 1};

	/** A completed record from the scenario, values captured, as {@link LedgerStore} writes it inside the file. */
	private static final String RECORD_JSON =
		"{\"schemaVersion\":2,\"id\":\"session-1\",\"monster\":\"Abyssal Sire\",\"creatureId\":-7,"
		+ "\"initialAmount\":6,\"originalAmount\":6,\"kills\":6,\"activeMillis\":91000,"
		+ "\"startedAt\":1700000000000,\"endedAt\":1700000091000,\"completed\":true,\"partial\":false,"
		+ "\"loot\":{\"592\":3,\"995\":2500,\"4151\":1,\"11286\":1},\"supplies\":{\"385\":5,\"2434\":7,"
		+ "\"12625\":1},\"supplyDoses\":{\"2434\":4},\"unitGePrices\":{\"385\":800,\"592\":120,\"995\":1,"
		+ "\"2434\":9000,\"4151\":1500000},\"unitHaPrices\":{\"385\":150,\"592\":0,\"995\":1,\"2434\":0,"
		+ "\"4151\":72000,\"11286\":0,\"12625\":0},\"lootGeValue\":1502860,\"lootHaValue\":74500,"
		+ "\"suppliesGeValue\":19750,\"suppliesHaValue\":750,\"lootUnpricedItems\":1,"
		+ "\"suppliesUnpricedItems\":1,\"superiorsSpawned\":1,\"bankTrips\":2,\"deaths\":1,"
		+ "\"note\":\"Barrage\",\"slayerMaster\":8,\"slayerArea\":3,\"taskLocation\":\"Catacombs\","
		+ "\"pointsEarned\":15,\"taskStreak\":42,\"notableDrops\":[{\"itemId\":4151,"
		+ "\"name\":\"Abyssal whip\",\"quantity\":1,\"geValue\":1500000,\"haValue\":72000,"
		+ "\"time\":1700000060000},{\"quantity\":1,\"time\":1700000060001,\"pet\":\"RECEIVED\"}],"
		+ "\"bossKillCounts\":[{\"boss\":\"Abyssal Sire\",\"firstKc\":10,\"lastKc\":11,\"kills\":2}],"
		+ "\"xpGained\":{\"HITPOINTS\":700,\"SLAYER\":2500},\"locationRegion\":12850,"
		+ "\"location\":\"Catacombs of Kourend\"}";
	/** The scenario's snapshot taken mid-session, as the active-session file. */
	private static final String SNAPSHOT_JSON =
		"{\"schemaVersion\":2,\"sessionId\":\"session-1\",\"accountHash\":123456789,"
		+ "\"monster\":\"Abyssal Sire\",\"creatureId\":-7,\"initialAmount\":6,\"originalAmount\":6,"
		+ "\"kills\":4,\"activeMillis\":61000,\"startedAt\":1700000000000,\"savedAt\":1700000061005,"
		+ "\"remaining\":2,\"completionCounters\":[3,0,1],\"loot\":{\"592\":3,\"995\":2500,\"4151\":1,"
		+ "\"11286\":1},\"supplies\":{\"385\":5,\"2434\":7,\"12625\":1},\"supplyDoses\":{\"2434\":4},"
		+ "\"superiorsSpawned\":1,\"bankTrips\":2,\"deaths\":1,\"note\":\"Barrage\",\"slayerMaster\":8,"
		+ "\"slayerArea\":3,\"taskLocation\":\"Catacombs\",\"notableDrops\":[{\"itemId\":4151,"
		+ "\"name\":\"Abyssal whip\",\"quantity\":1,\"geValue\":1500000,\"haValue\":72000,"
		+ "\"time\":1700000060000},{\"quantity\":1,\"time\":1700000060001,\"pet\":\"RECEIVED\"}],"
		+ "\"bossKillCounts\":[{\"boss\":\"Abyssal Sire\",\"firstKc\":10,\"lastKc\":11,\"kills\":2}],"
		+ "\"xpGained\":{\"HITPOINTS\":700,\"SLAYER\":2500},\"locationKills\":[{\"region\":12850,"
		+ "\"kills\":2},{\"region\":12851,\"kills\":2}]}";
	/** The snapshot above saved as a partial record (it could not be restored). */
	private static final String PARTIAL_JSON =
		"{\"schemaVersion\":2,\"id\":\"session-1\",\"monster\":\"Abyssal Sire\",\"creatureId\":-7,"
		+ "\"initialAmount\":6,\"originalAmount\":6,\"kills\":4,\"activeMillis\":61000,"
		+ "\"startedAt\":1700000000000,\"endedAt\":1700000061005,\"completed\":false,\"partial\":true,"
		+ "\"loot\":{\"592\":3,\"995\":2500,\"4151\":1,\"11286\":1},\"supplies\":{\"385\":5,\"2434\":7,"
		+ "\"12625\":1},\"supplyDoses\":{\"2434\":4},\"superiorsSpawned\":1,\"bankTrips\":2,\"deaths\":1,"
		+ "\"note\":\"Barrage\",\"slayerMaster\":8,\"slayerArea\":3,\"taskLocation\":\"Catacombs\","
		+ "\"notableDrops\":[{\"itemId\":4151,\"name\":\"Abyssal whip\",\"quantity\":1,\"geValue\":1500000,"
		+ "\"haValue\":72000,\"time\":1700000060000},{\"quantity\":1,\"time\":1700000060001,"
		+ "\"pet\":\"RECEIVED\"}],\"bossKillCounts\":[{\"boss\":\"Abyssal Sire\",\"firstKc\":10,"
		+ "\"lastKc\":11,\"kills\":2}],\"xpGained\":{\"HITPOINTS\":700,\"SLAYER\":2500},"
		+ "\"locationRegion\":12850,\"location\":\"Catacombs\"}";

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private final Gson gson = new Gson();
	private final AtomicLong now = new AtomicLong(START);
	private File dir;
	private LedgerStore store;

	@Before
	public void setUp()
	{
		dir = new File(temp.getRoot(), "slayer-ledger");
		store = new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), gson);
	}

	@Test
	public void completedRecordIsWrittenAsBefore()
	{
		assertEquals(RECORD_JSON, gson.toJson(completedRecord()));
	}

	@Test
	public void snapshotIsWrittenAsBefore()
	{
		assertEquals(SNAPSHOT_JSON, gson.toJson(snapshot()));
	}

	@Test
	public void snapshotSavedAsPartialIsWrittenAsBefore()
	{
		LedgerRecord partial = LedgerRecord.fromSummary(snapshot().toSummary(), true);
		assertEquals(PARTIAL_JSON, gson.toJson(partial));
	}

	@Test
	public void restoredSnapshotIsWrittenBackUnchanged()
	{
		SessionSnapshot saved = gson.fromJson(SNAPSHOT_JSON, SessionSnapshot.class);
		SessionTracker tracker = new SessionTracker(now::get);
		tracker.observe("Abyssal Sire", BOSS_TASK, 2, 6, TaskContext.assignment(8, 3, "Catacombs"), REGION, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(saved, COUNTERS.clone()));

		SessionSnapshot again = SessionSnapshot.fromSummary(tracker.summary(), COUNTERS, saved.getSavedAt());
		// Restoring starts a new active stretch; nothing else of the session changes.
		assertEquals(SNAPSHOT_JSON, gson.toJson(again));
	}

	@Test
	public void ledgerFileIsRewrittenByteForByte() throws IOException
	{
		String fixture = "{\"schemaVersion\":2,\"records\":[" + RECORD_JSON + "," + PARTIAL_JSON + "]}";
		assertEquals(true, dir.mkdirs());
		File file = new File(dir, ACCOUNT + ".json");
		Files.write(file.toPath(), fixture.getBytes(StandardCharsets.UTF_8));

		List<LedgerRecord> records = store.load(ACCOUNT);
		assertEquals(2, records.size());
		store.write(ACCOUNT, records);

		assertEquals(fixture, new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
	}

	@Test
	public void activeFileIsRewrittenByteForByte() throws IOException
	{
		assertEquals(true, dir.mkdirs());
		File file = new File(dir, ACCOUNT + ".active.json");
		Files.write(file.toPath(), SNAPSHOT_JSON.getBytes(StandardCharsets.UTF_8));

		SessionSnapshot read = store.readActive(ACCOUNT);
		assertNotNull(read);
		store.writeActive(ACCOUNT, read);

		assertEquals(SNAPSHOT_JSON, new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
	}

	/** The scenario's snapshot, taken while the session is running, with a fixed id. */
	private SessionSnapshot snapshot()
	{
		SessionTracker tracker = runningSession();
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.summary(), COUNTERS, now.get() + 5);
		s.setSessionId("session-1");
		return s;
	}

	/** The scenario's session completed, with completion rewards and captured values, with a fixed id. */
	private LedgerRecord completedRecord()
	{
		SessionTracker tracker = runningSession();
		now.addAndGet(30_000);
		tracker.observe("Abyssal Sire", BOSS_TASK, 0, 6, TaskContext.assignment(8, 3, "Catacombs"), REGION, true);
		assertEquals(true, tracker.isCompleted());
		tracker.setCompletionRewards(tracker.getSessionId(), 15, 42);
		tracker.stop();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.summary(), false);
		record.setId("session-1");
		record.captureValues(new ItemValuation.PriceLookup()
		{
			@Override
			public int canonicalize(int itemId)
			{
				return itemId;
			}

			@Override
			public long gePrice(int canonicalId)
			{
				switch (canonicalId)
				{
					case WHIP:
						return 1_500_000;
					case ASHES:
						return 120;
					case COINS:
						return 1;
					case PRAYER_POTION:
						return 9_000;
					case SHARK:
						return 800;
					default:
						return 0;
				}
			}

			@Override
			public boolean isTradeable(int canonicalId)
			{
				return true;
			}

			@Override
			public long haPrice(int canonicalId)
			{
				return canonicalId == WHIP ? 72_000 : canonicalId == SHARK ? 150 : 0;
			}
		});
		record.setLocation("Catacombs of Kourend");
		return record;
	}

	/** A running boss task session with every kind of session data: loot, supplies, counters, XP, region, note. */
	private SessionTracker runningSession()
	{
		now.set(START);
		SessionTracker tracker = new SessionTracker(now::get);
		final TaskContext assignment = TaskContext.assignment(8, 3, "Catacombs");
		tracker.observe("Abyssal Sire", BOSS_TASK, 6, 6, assignment, REGION, false);
		tracker.observeXp(xp(1_000, 500));
		assertEquals(true, tracker.play(ACCOUNT));
		now.addAndGet(60_000);
		tracker.observe("Abyssal Sire", BOSS_TASK, 4, 6, assignment, REGION, false);
		tracker.observe("Abyssal Sire", BOSS_TASK, 2, 6, assignment, REGION + 1, false);
		tracker.observeXp(xp(3_500, 1_200));

		ItemTally loot = new ItemTally();
		loot.add(WHIP, 1);
		loot.add(ASHES, 3);
		loot.add(COINS, 2_500);
		loot.add(UNPRICED_LOOT, 1);
		tracker.addLoot(loot, Collections.singletonList(
			NotableDrop.item(WHIP, "Abyssal whip", 1, 1_500_000L, 72_000L, now.get())));
		tracker.addPet(NotableDrop.pet(null, now.get() + 1));
		tracker.addBossKillCount("Abyssal Sire", 10);
		tracker.addBossKillCount("Abyssal Sire", 11);

		ItemTally used = new ItemTally();
		used.add(PRAYER_POTION, 7);
		used.add(SHARK, 5);
		used.add(UNPRICED_SUPPLY, 1);
		tracker.addSupplies(used, null, Collections.singletonMap(PRAYER_POTION, 4));

		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addBankTrip();
		tracker.addDeath();
		tracker.setNote(tracker.getSessionId(), "Barrage");
		now.addAndGet(1_000);
		return tracker;
	}

	private static Map<String, Integer> xp(int slayer, int hitpoints)
	{
		Map<String, Integer> reading = new TreeMap<>();
		reading.put("SLAYER", slayer);
		reading.put("HITPOINTS", hitpoints);
		return reading;
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.SessionTracker.RestoreResult;
import static com.shmayvan.slayerledger.SessionTracker.State;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

/**
 * Snapshot / restore of in-progress sessions (persisted on logout, client exit, plugin shutdown, account switch).
 */
public class SessionRestoreTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	/** A session with 7 kills and 60s of active time, snapshotted while paused at 43 remaining. */
	private SessionSnapshot snapshotOfSession()
	{
		SessionTracker original = new SessionTracker(() -> now);
		original.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		original.play(ACCOUNT);
		now += 60_000;
		original.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		original.autoPause();
		now += 5_000;
		SessionTracker.Summary summary = original.activeSummary();
		assertNotNull(summary);
		return SessionSnapshot.fromSummary(summary, COUNTERS, now);
	}

	@Test
	public void snapshotCapturesSession()
	{
		SessionSnapshot s = snapshotOfSession();
		assertNotNull(s.getSessionId());
		assertEquals(ACCOUNT, s.getAccountHash());
		assertEquals("Abyssal demons", s.getMonster());
		assertEquals(DEMON_ID, s.getCreatureId());
		assertEquals(50, s.getInitialAmount());
		assertEquals(Integer.valueOf(150), s.getOriginalAmount());
		assertEquals(7, s.getKills());
		assertEquals(60_000, s.getActiveMillis());
		assertEquals(1_000_000L, s.getStartedAt());
		assertEquals(43, s.getRemaining());
		assertArrayEquals(COUNTERS, s.getCompletionCounters());
		assertEquals(SessionSnapshot.CURRENT_SCHEMA_VERSION, s.getSchemaVersion());
	}

	@Test
	public void snapshotSurvivesJsonRoundTrip()
	{
		Gson gson = new Gson();
		SessionSnapshot s = snapshotOfSession();
		assertEquals(s, gson.fromJson(gson.toJson(s), SessionSnapshot.class));
	}

	@Test
	public void restoresMatchingTaskAsPausedAndIgnoresUntrackedKills()
	{
		SessionSnapshot s = snapshotOfSession();
		// 3 kills happened while the plugin was not watching
		tracker.observe("Abyssal demons", DEMON_ID, 40, 150, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
		assertEquals(State.PAUSED, tracker.getState());
		assertTrue(tracker.isRestoredPending());
		assertEquals(7, tracker.getKills());
		assertEquals(60_000, tracker.getActiveMillis());
		assertEquals(ACCOUNT, tracker.getSessionAccountHash());

		// resume: baseline is the current remaining count
		assertTrue(tracker.play(ACCOUNT));
		assertFalse(tracker.isRestoredPending());
		now += 10_000;
		tracker.observe("Abyssal demons", DEMON_ID, 38, 150, false);
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(9, summary.getKills());
		assertEquals(70_000, summary.getActiveMillis());
		assertEquals(s.getSessionId(), summary.getSessionId());
		assertEquals(50, summary.getInitialAmount());
		assertEquals(150, summary.getOriginalAmount());
		assertEquals(1_000_000L, summary.getStartedAt());
		assertEquals(s.getSessionId(), LedgerRecord.fromSummary(summary, true).getId());
	}

	@Test
	public void restoreRefusedBeforeObservationOrWithActiveSession()
	{
		SessionSnapshot s = snapshotOfSession();
		assertEquals(RestoreResult.REFUSED, tracker.restore(s, COUNTERS));
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		tracker.play(ACCOUNT);
		assertEquals(RestoreResult.REFUSED, tracker.restore(s, COUNTERS));
		assertEquals(State.RUNNING, tracker.getState());
	}

	@Test
	public void differentCreatureIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
		assertEquals(State.IDLE, tracker.getState());
	}

	@Test
	public void noTaskIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void higherRemainingIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 44, 150, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void changedAssignedSizeIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 120, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void completionInBetweenIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{101, 2, 0}));
		// unknown counters on either side do not block
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, null));
	}

	@Test
	public void unknownSizeOrCountersStillRestore()
	{
		SessionSnapshot s = snapshotOfSession();
		s.setOriginalAmount(null);
		s.setCompletionCounters(null);
		tracker.observe("Abyssal demons", DEMON_ID, 43, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
	}

	@Test
	public void noAccountIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		s.setAccountHash(SessionTracker.NO_ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void mismatchSummaryIsIncompleteWithSnapshotValues()
	{
		SessionSnapshot s = snapshotOfSession();
		SessionTracker.Summary summary = s.toSummary();
		assertTrue(summary.hasTask());
		assertFalse(summary.isCompleted());
		assertEquals(7, summary.getKills());
		assertEquals(s.getSavedAt(), summary.getEndedAt());
		assertEquals(s.getSessionId(), summary.getSessionId());
		assertEquals(SaveDecision.Action.SAVE_PARTIAL_WITH_NOTICE,
			SaveDecision.decide(summary, SaveDecision.EndReason.RESTORE_MISMATCH, true));
		LedgerRecord record = LedgerRecord.fromSummary(summary, true);
		assertEquals(s.getSessionId(), record.getId());
		assertTrue(record.isPartial());
		assertEquals(Integer.valueOf(150), record.getOriginalAmount());
	}

	@Test
	public void activeSummaryIsNullWhenIdleAndKeepsSessionInMemory()
	{
		assertNull(tracker.activeSummary());
		tracker.observe("Abyssal demons", DEMON_ID, 10, false);
		tracker.play(ACCOUNT);
		tracker.autoPause();
		assertNotNull(tracker.activeSummary());
		// taking a snapshot on logout does not end the in-memory session
		assertEquals(State.PAUSED, tracker.getState());
	}

	@Test
	public void snapshotDuringPendingZeroResumesFromCountBeforeTheZero()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, false);
		tracker.play(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 8, false);
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.activeSummary(), null, now);
		assertEquals(8, s.getRemaining());
		assertEquals(2, s.getKills());
	}

	@Test
	public void newSessionsGetDistinctIds()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, false);
		tracker.play(ACCOUNT);
		String first = tracker.stopAndReset().getSessionId();
		tracker.play(ACCOUNT);
		String second = tracker.stopAndReset().getSessionId();
		assertNotNull(first);
		assertFalse(first.equals(second));
	}

	@Test
	public void completionCounterDecreaseIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		// Turael reset / cancellation lowers the streak
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{50, 2, 0}));
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{100, 1, 0}));
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
	}

	@Test
	public void allZeroCountersAreTreatedAsNotYetSynced()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, new int[]{0, 0, 0}));
	}

	/** A session kept in memory across logout: log out at 43 left, then log back in. */
	private SessionSnapshot logOutWithSessionInMemory()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		tracker.play(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		tracker.autoPause();
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		tracker.clearCurrentTask();
		return s;
	}

	@Test
	public void reloginWithSameTaskStillMatches()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		assertTrue(tracker.activeSessionStillMatches(s, COUNTERS));
		assertEquals(State.PAUSED, tracker.getState());
	}

	@Test
	public void reloginAfterFinishingAndGettingSameCreatureIsMismatch()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		// finished the task elsewhere, then got the same creature again with a new size
		tracker.observe("Abyssal demons", DEMON_ID, 180, 180, false);
		assertFalse(tracker.activeSessionStillMatches(s, new int[]{101, 2, 0}));
		// even without size or counter evidence, the higher remaining count gives it away
		assertFalse(tracker.activeSessionStillMatches(s, null));
	}

	@Test
	public void reloginWithStreakDecreaseIsMismatch()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		tracker.observe("Abyssal demons", DEMON_ID, 40, 150, false);
		assertFalse(tracker.activeSessionStillMatches(s, new int[]{60, 2, 0}));
		// a counter reading zero is unknown (possibly unsynced), not a reset
		assertTrue(tracker.activeSessionStillMatches(s, new int[]{0, 2, 0}));
	}

	@Test
	public void perCounterUnknownHandling()
	{
		// zero now, non-zero before: unknown
		assertFalse(SessionTracker.counterChanged(100, 0));
		// unchanged
		assertFalse(SessionTracker.counterChanged(100, 100));
		assertFalse(SessionTracker.counterChanged(0, 0));
		// increases (including from zero) and non-zero decreases are changes
		assertTrue(SessionTracker.counterChanged(100, 101));
		assertTrue(SessionTracker.counterChanged(0, 1));
		assertTrue(SessionTracker.counterChanged(100, 40));
	}

	@Test
	public void oneUnsyncedCounterDoesNotHideAnotherCounterChange()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, new int[]{0, 2, 0}));
		tracker.stopAndReset();
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{0, 3, 0}));
	}

	@Test
	public void restoreCheckDefersWhileCountReadsZeroUpToCap()
	{
		assertTrue(SessionTracker.shouldDeferRestoreCheck(0, 0));
		assertTrue(SessionTracker.shouldDeferRestoreCheck(0, SessionTracker.RESTORE_SYNC_MAX_TICKS - 1));
		assertFalse(SessionTracker.shouldDeferRestoreCheck(0, SessionTracker.RESTORE_SYNC_MAX_TICKS));
		assertFalse(SessionTracker.shouldDeferRestoreCheck(5, 0));
		assertFalse(SessionTracker.shouldDeferRestoreCheck(1, 3));
	}

	@Test
	public void zeroCountAfterCapIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertFalse(SessionTracker.shouldDeferRestoreCheck(0, SessionTracker.RESTORE_SYNC_MAX_TICKS));
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void reloginCheckIgnoresOtherOrNoSession()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		tracker.observe("Black dragons", DRAGON_ID, 20, false);
		SessionSnapshot other = snapshotOfSession();
		assertTrue(tracker.activeSessionStillMatches(other, COUNTERS));
		assertTrue(tracker.activeSessionStillMatches(null, COUNTERS));
		tracker.stopAndReset();
		assertTrue(tracker.activeSessionStillMatches(s, COUNTERS));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

/**
 * Superior spawns, bank trips and deaths on the session: RUNNING-only counting, the completion grace window, reset on session
 * end, and how they travel through snapshots, restores, records and JSON.
 */
public class SessionTrackerCountersTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private final Gson gson = new Gson();
	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
	}

	@Test
	public void countedOnlyWhileRunning()
	{
		assertFalse("idle", tracker.addSuperiorSpawn());
		assertFalse("idle", tracker.addBankTrip());
		assertFalse("idle", tracker.addDeath());
		assertTrue(tracker.play(ACCOUNT));
		assertTrue(tracker.addSuperiorSpawn());
		assertTrue(tracker.addBankTrip());
		assertTrue(tracker.addBankTrip());
		assertTrue(tracker.addDeath());
		tracker.pause();
		assertFalse("paused", tracker.addSuperiorSpawn());
		assertFalse("paused", tracker.addBankTrip());
		assertFalse("paused", tracker.addDeath());
		assertEquals(1, tracker.getSuperiorsSpawned());
		assertEquals(2, tracker.getBankTrips());
		assertEquals(1, tracker.getDeaths());
		SessionTracker.Summary summary = tracker.activeSummary();
		assertEquals(Integer.valueOf(1), summary.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), summary.getBankTrips());
		assertEquals(Integer.valueOf(1), summary.getDeaths());
	}

	@Test
	public void resetWhenTheSessionEnds()
	{
		tracker.play(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addDeath();
		SessionTracker.Summary ended = tracker.stopAndReset();
		assertEquals(Integer.valueOf(1), ended.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), ended.getBankTrips());
		assertEquals(Integer.valueOf(1), ended.getDeaths());
		assertEquals(0, tracker.getSuperiorsSpawned());
		assertEquals(0, tracker.getBankTrips());
		assertEquals(0, tracker.getDeaths());

		tracker.play(ACCOUNT);
		SessionTracker.Summary next = tracker.activeSummary();
		assertEquals("a new session starts at 0, not unknown", Integer.valueOf(0), next.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(0), next.getBankTrips());
		assertEquals(Integer.valueOf(0), next.getDeaths());
	}

	@Test
	public void notAddedToACompletedSessionHeldForLateLoot()
	{
		tracker.play(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		tracker.addDeath();
		assertTrue(tracker.holdCompletion());
		assertFalse(tracker.addSuperiorSpawn());
		assertFalse(tracker.addBankTrip());
		assertFalse(tracker.addDeath());
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(Integer.valueOf(1), held.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), held.getBankTrips());
		assertEquals(Integer.valueOf(1), held.getDeaths());
	}

	@Test
	public void lateLootKeepsTheCounts()
	{
		tracker.play(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		tracker.holdCompletion();
		ItemTally loot = new ItemTally();
		loot.add(526, 1);
		tracker.addLoot(loot);
		assertEquals(Integer.valueOf(1), tracker.takePendingCompletion().getSuperiorsSpawned());
	}

	@Test
	public void recordCarriesTheCounts()
	{
		tracker.play(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addDeath();
		tracker.addDeath();
		tracker.addDeath();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(2), record.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), record.getBankTrips());
		assertEquals(Integer.valueOf(3), record.getDeaths());
		LedgerRecord read = gson.fromJson(gson.toJson(record), LedgerRecord.class);
		assertEquals(record, read);
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, read.getSchemaVersion());
		assertEquals(2, LedgerRecord.CURRENT_SCHEMA_VERSION);
	}

	@Test
	public void zeroCountsAreSavedAsZeroNotUnknown()
	{
		tracker.play(ACCOUNT);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		String json = gson.toJson(record);
		assertTrue(json, json.contains("\"superiorsSpawned\":0"));
		assertTrue(json, json.contains("\"bankTrips\":0"));
		assertTrue(json, json.contains("\"deaths\":0"));
	}

	@Test
	public void olderRecordsReadAsUnknown()
	{
		LedgerRecord old = gson.fromJson("{\"schemaVersion\":2,\"id\":\"x\",\"monster\":\"Abyssal demons\",\"kills\":5}",
			LedgerRecord.class);
		assertNull(old.getSuperiorsSpawned());
		assertNull(old.getBankTrips());
		assertNull(old.getDeaths());
		String json = gson.toJson(old);
		assertFalse("unknown counts are not written", json.contains("superiorsSpawned"));
		assertFalse(json.contains("bankTrips"));
		assertFalse(json.contains("deaths"));
	}

	@Test
	public void snapshotRoundTripAndRestoreCarryTheCounts()
	{
		tracker.play(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addBankTrip();
		tracker.addDeath();
		tracker.autoPause();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(Integer.valueOf(1), snapshot.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), snapshot.getBankTrips());
		assertEquals(Integer.valueOf(1), snapshot.getDeaths());
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertEquals(1, restored.getSuperiorsSpawned());
		assertEquals(2, restored.getBankTrips());
		assertEquals(1, restored.getDeaths());
		assertTrue(restored.play(ACCOUNT));
		restored.addSuperiorSpawn();
		restored.addDeath();
		LedgerRecord record = LedgerRecord.fromSummary(restored.stopAndReset(), true);
		assertEquals(Integer.valueOf(2), record.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), record.getBankTrips());
		assertEquals(Integer.valueOf(2), record.getDeaths());
	}

	@Test
	public void olderSnapshotRestoresFromZeroAndMismatchKeepsUnknown()
	{
		tracker.play(ACCOUNT);
		tracker.autoPause();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		snapshot.setSuperiorsSpawned(null);
		snapshot.setBankTrips(null);
		snapshot.setDeaths(null);
		SessionSnapshot old = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertNull(old.getSuperiorsSpawned());

		// Saved as a partial record when it cannot be restored: the counts stay unknown.
		LedgerRecord partial = LedgerRecord.fromSummary(old.toSummary(), true);
		assertNull(partial.getSuperiorsSpawned());
		assertNull(partial.getBankTrips());
		assertNull(partial.getDeaths());

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(old, COUNTERS));
		assertEquals(0, restored.getSuperiorsSpawned());
		assertEquals(0, restored.getBankTrips());
		assertEquals(0, restored.getDeaths());
		assertNotNull(restored.activeSummary().getBankTrips());
		assertNotNull(restored.activeSummary().getDeaths());
	}

	@Test
	public void snapshotToSummaryKeepsTheCounts()
	{
		tracker.play(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addDeath();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		SessionTracker.Summary summary = snapshot.toSummary();
		assertEquals(Integer.valueOf(1), summary.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), summary.getBankTrips());
		assertEquals(Integer.valueOf(1), summary.getDeaths());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

/**
 * Kills per region in {@link SessionTracker}: tallied exactly when kills are counted, kept by snapshots and
 * restores, and saved as the record's dominant region.
 */
public class SessionTrackerLocationTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};
	private static final int SMOKE = 12_946;
	private static final int CATACOMBS = 6_557;
	private static final TaskContext KONAR = TaskContext.of(SlayerMaster.KONAR, 7, "Kraken Cove", null, null);

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		observe(50, SMOKE);
	}

	private SessionTracker.ObserveResult observe(int remaining, int region)
	{
		return observe(remaining, region, TaskContext.NONE, false);
	}

	private SessionTracker.ObserveResult observe(int remaining, int region, TaskContext context, boolean completed)
	{
		return tracker.observe("Abyssal demons", DEMON_ID, remaining, 150, context, region, completed);
	}

	@Test
	public void killsAreTalliedWhereTheyAreCounted()
	{
		assertTrue(tracker.play(ACCOUNT));
		observe(47, SMOKE);
		observe(45, CATACOMBS);
		observe(44, SMOKE);
		assertEquals(Arrays.asList(new LocationKills(SMOKE, 4), new LocationKills(CATACOMBS, 2)),
			tracker.getLocationKills());
		assertEquals(Integer.valueOf(SMOKE), tracker.getDominantRegion());
		assertEquals(6, tracker.getKills());
		assertEquals(SMOKE, tracker.takeRegionToName());
		assertEquals("taken once", LocationTally.NO_REGION, tracker.takeRegionToName());
	}

	@Test
	public void killsWithoutARegionStillCountUntallied()
	{
		assertTrue(tracker.play(ACCOUNT));
		observe(48, LocationTally.NO_REGION);
		assertEquals(2, tracker.getKills());
		assertTrue(tracker.getLocationKills().isEmpty());
		assertNull(tracker.getDominantRegion());
		assertEquals(LocationTally.NO_REGION, tracker.takeRegionToName());
	}

	@Test
	public void pausedOrIdleKillsAreNotTallied()
	{
		observe(48, SMOKE);
		assertTrue(tracker.play(ACCOUNT));
		observe(47, SMOKE);
		tracker.pause();
		observe(40, CATACOMBS);
		assertEquals(Collections.singletonList(new LocationKills(SMOKE, 1)), tracker.getLocationKills());
		assertEquals(SMOKE, tracker.takeRegionToName());
		assertEquals(LocationTally.NO_REGION, tracker.takeRegionToName());
	}

	@Test
	public void theFinalKillIsTalliedWhereTheCountDropped()
	{
		assertTrue(tracker.play(ACCOUNT));
		observe(2, SMOKE);
		// The count drops to 0 in the Catacombs; the completion is confirmed a tick later, after walking away.
		assertEquals(SessionTracker.ObserveResult.TASK_CLEARED, observe(0, CATACOMBS));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, SMOKE, TaskContext.NONE, true));
		assertEquals(Arrays.asList(new LocationKills(SMOKE, 48), new LocationKills(CATACOMBS, 2)),
			tracker.getLocationKills());

		assertTrue(tracker.holdCompletion());
		assertEquals("the tally is the held session's", Integer.valueOf(SMOKE),
			tracker.takePendingCompletion().getDominantRegion());
		assertTrue(tracker.getLocationKills().isEmpty());
		assertEquals("the region to name outlives the session", CATACOMBS, tracker.takeRegionToName());
	}

	@Test
	public void aCompletionOnTheSameTickIsTallied()
	{
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, CATACOMBS, TaskContext.NONE, true));
		assertEquals(Collections.singletonList(new LocationKills(CATACOMBS, 50)), tracker.getLocationKills());
	}

	@Test
	public void aRegionPastTheLimitIsNotOfferedForNaming()
	{
		tracker = new SessionTracker(() -> now);
		observe(140, SMOKE);
		assertTrue(tracker.play(ACCOUNT));
		for (int i = 0; i < LocationTally.MAX_REGIONS; i++)
		{
			observe(139 - i, 1_000 + i);
			assertEquals(1_000 + i, tracker.takeRegionToName());
		}
		observe(139 - LocationTally.MAX_REGIONS, SMOKE);
		assertEquals("not in the tally, so never asked about", LocationTally.NO_REGION, tracker.takeRegionToName());
		assertEquals(LocationTally.MAX_REGIONS + 1, tracker.getKills());
		assertEquals(LocationTally.MAX_REGIONS, tracker.getLocationKills().size());

		observe(138 - LocationTally.MAX_REGIONS, 1_000);
		assertEquals("a tallied region still is", 1_000, tracker.takeRegionToName());
	}

	@Test
	public void aTaskWithAnAssignedAreaHasNoRegionToName()
	{
		observe(50, SMOKE, KONAR, false);
		assertTrue(tracker.play(ACCOUNT));
		observe(49, SMOKE, KONAR, false);
		assertEquals("still tallied", Integer.valueOf(SMOKE), tracker.getDominantRegion());
		assertEquals("Kraken Cove", tracker.getSessionTaskLocation());
		assertEquals(LocationTally.NO_REGION, tracker.takeRegionToName());

		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(SMOKE), record.getLocationRegion());
		assertEquals("the area is the location", "Kraken Cove", record.getLocation());
	}

	@Test
	public void theRecordKeepsTheDominantRegionWithoutAName()
	{
		assertTrue(tracker.play(ACCOUNT));
		observe(49, CATACOMBS);
		observe(47, SMOKE);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(SMOKE), record.getLocationRegion());
		assertNull("named when saved", record.getLocation());

		tracker.reset();
		assertTrue(tracker.play(ACCOUNT));
		LedgerRecord none = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertNull(none.getLocationRegion());
		assertNull(none.getLocation());
	}

	@Test
	public void snapshotsAndRestoresKeepTheTally()
	{
		assertTrue(tracker.play(ACCOUNT));
		observe(47, CATACOMBS);
		observe(46, SMOKE);
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(Arrays.asList(new LocationKills(CATACOMBS, 3), new LocationKills(SMOKE, 1)),
			snapshot.getLocationKills());
		Gson gson = new Gson();
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);
		assertEquals("a partial from the snapshot keeps it", Integer.valueOf(CATACOMBS),
			LedgerRecord.fromSummary(read.toSummary(), true).getLocationRegion());

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertTrue(restored.play(ACCOUNT));
		restored.observe("Abyssal demons", DEMON_ID, 43, 150, TaskContext.NONE, SMOKE, false);
		assertEquals(Arrays.asList(new LocationKills(CATACOMBS, 3), new LocationKills(SMOKE, 4)),
			restored.getLocationKills());
		assertEquals(Integer.valueOf(SMOKE), restored.getDominantRegion());
	}

	@Test
	public void anOlderSnapshotRestoresWithNoTally()
	{
		assertTrue(tracker.play(ACCOUNT));
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertNull("none yet, so not written", snapshot.getLocationKills());
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(snapshot, COUNTERS));
		assertTrue(restored.getLocationKills().isEmpty());
	}

	@Test
	public void theCurrentRegionIsTheLatestObservedOneUntilTheTaskIsCleared()
	{
		assertEquals("observed while idle too", SMOKE, tracker.getCurrentRegion());
		observe(50, CATACOMBS);
		assertEquals(CATACOMBS, tracker.getCurrentRegion());
		observe(50, LocationTally.NO_REGION);
		assertEquals(LocationTally.NO_REGION, tracker.getCurrentRegion());
		observe(50, SMOKE);
		tracker.clearCurrentTask();
		assertEquals(LocationTally.NO_REGION, tracker.getCurrentRegion());
	}

	@Test
	public void aNewSessionStartsWithNoTally()
	{
		assertTrue(tracker.play(ACCOUNT));
		observe(49, SMOKE);
		tracker.stopAndReset();
		assertTrue(tracker.getLocationKills().isEmpty());
		assertTrue(tracker.play(ACCOUNT));
		assertNull(tracker.getDominantRegion());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

/**
 * The note on a session: when it can be set (running, paused, or held for late loot), and how it travels through
 * snapshots, restores, records and JSON.
 */
public class SessionTrackerNoteTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private final Gson gson = new Gson();
	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
	}

	@Test
	public void setWhileRunningOrPausedAndNormalized()
	{
		assertFalse("no session", tracker.setNote(null, "Barrage"));
		assertTrue(tracker.play(ACCOUNT));
		String id = tracker.getSessionId();
		assertFalse("another session", tracker.setNote("other", "Barrage"));
		assertTrue(tracker.setNote(id, "  Barrage\n "));
		assertEquals("Barrage", tracker.getNote());
		assertEquals("Barrage", tracker.activeSummary().getNote());

		tracker.pause();
		assertTrue(tracker.setNote(id, "Prayer gear"));
		assertEquals("Prayer gear", tracker.getNote());
		assertTrue("cleared", tracker.setNote(id, "   "));
		assertNull(tracker.getNote());
	}

	@Test
	public void clearedWhenTheSessionEndsAndRefusedAfterwards()
	{
		tracker.play(ACCOUNT);
		String id = tracker.getSessionId();
		tracker.setNote(id, "Cannon");
		SessionTracker.Summary ended = tracker.stopAndReset();
		assertEquals("Cannon", ended.getNote());
		assertNull(tracker.getNote());
		assertFalse("the session is gone", tracker.setNote(id, "Barrage"));

		tracker.play(ACCOUNT);
		assertNull("a new session has no note", tracker.activeSummary().getNote());
	}

	@Test
	public void aNoteSetDuringTheGraceWindowReachesTheHeldSession()
	{
		tracker.play(ACCOUNT);
		String id = tracker.getSessionId();
		tracker.setNote(id, "Range pray");
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.setNote(id, "Barrage"));

		// A new session started during the grace window keeps its own note.
		tracker.observe("Abyssal demons", DEMON_ID, 30, 30, false);
		assertTrue(tracker.play(ACCOUNT));
		String next = tracker.getSessionId();
		assertTrue(tracker.setNote(next, "Cannon"));
		assertTrue(tracker.setNote(id, "Barrage, burst"));
		ItemTally loot = new ItemTally();
		loot.add(526, 1);
		tracker.addLoot(loot);

		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals("Barrage, burst", held.getNote());
		assertEquals("late loot keeps the note", 1, held.getLoot().get(526));
		assertEquals("Cannon", tracker.getNote());
		assertFalse("no longer held", tracker.setNote(id, "x"));
	}

	@Test
	public void recordCarriesTheNoteThroughJson()
	{
		tracker.play(ACCOUNT);
		tracker.setNote(tracker.getSessionId(), "Prayer gear");
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertEquals("Prayer gear", record.getNote());
		String json = gson.toJson(record);
		assertTrue(json, json.contains("\"note\":\"Prayer gear\""));
		LedgerRecord read = gson.fromJson(json, LedgerRecord.class);
		assertEquals(record, read);
		assertEquals(2, read.getSchemaVersion());
	}

	@Test
	public void recordWithoutANoteOmitsIt()
	{
		tracker.play(ACCOUNT);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertNull(record.getNote());
		String json = gson.toJson(record);
		assertFalse(json, json.contains("note"));
		assertEquals(record, gson.fromJson(json, LedgerRecord.class));
	}

	@Test
	public void olderRecordsHaveNoNote()
	{
		LedgerRecord old = gson.fromJson("{\"schemaVersion\":2,\"id\":\"x\",\"monster\":\"Abyssal demons\",\"kills\":5}",
			LedgerRecord.class);
		assertNull(old.getNote());
		SessionSnapshot oldSnapshot = gson.fromJson("{\"schemaVersion\":2,\"sessionId\":\"s\",\"accountHash\":555,"
			+ "\"creatureId\":42,\"remaining\":50,\"kills\":3}", SessionSnapshot.class);
		assertNull(oldSnapshot.getNote());
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(oldSnapshot, COUNTERS));
		assertNull(restored.getNote());
		assertTrue("a note can be added after the restore", restored.setNote("s", "Cannon"));
	}

	@Test
	public void snapshotRoundTripAndRestoreCarryTheNote()
	{
		tracker.play(ACCOUNT);
		tracker.setNote(tracker.getSessionId(), "Strength gear");
		tracker.autoPause();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals("Strength gear", snapshot.getNote());
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertEquals("Strength gear", restored.getNote());
		assertEquals("as a partial record when it cannot be restored", "Strength gear",
			LedgerRecord.fromSummary(read.toSummary(), true).getNote());
	}

	@Test
	public void aHandEditedSnapshotNoteIsNormalized()
	{
		tracker.play(ACCOUNT);
		tracker.autoPause();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		snapshot.setNote("  Barrage \n");
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		restored.restore(snapshot, COUNTERS);
		assertEquals("Barrage", restored.getNote());
		assertEquals("Barrage", snapshot.toSummary().getNote());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

/** {@link SessionTracker#takeSessionTaskKeys()}: which tasks a session held since the last call. */
public class SessionTrackerTaskKeysTest
{
	private static final int DEMONS = 42;
	private static final int GARGOYLES = 46;
	private static final long ACCOUNT = 555L;

	private long now = 1_000_000L;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new SessionTracker(() -> now);
		tracker.observe("Abyssal demons", DEMONS, 100, false);
	}

	@Test
	public void noSessionHoldsNoTask()
	{
		assertTrue(tracker.takeSessionTaskKeys().isEmpty());
	}

	@Test
	public void anActiveSessionsTaskIsReportedEveryCall()
	{
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		tracker.pause();
		assertEquals("paused too", Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
	}

	@Test
	public void aSessionThatEndedBeforeTheCallIsStillReportedOnce()
	{
		assertTrue(tracker.play(ACCOUNT));
		tracker.stopAndReset();
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		assertTrue(tracker.takeSessionTaskKeys().isEmpty());
	}

	@Test
	public void aTaskAdoptedLaterIsReported()
	{
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertTrue(tracker.play(ACCOUNT));
		assertTrue("no task yet", tracker.takeSessionTaskKeys().isEmpty());
		tracker.observe("Gargoyles", GARGOYLES, 150, false);
		assertEquals(Collections.singleton(GARGOYLES), tracker.takeSessionTaskKeys());
	}

	@Test
	public void aHeldCompletionIsReported()
	{
		assertTrue(tracker.play(ACCOUNT));
		tracker.takeSessionTaskKeys();
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.holdCompletion());
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		tracker.takePendingCompletion();
		assertTrue(tracker.takeSessionTaskKeys().isEmpty());
	}

	@Test
	public void aRestoredSessionIsReported()
	{
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(startedSummary(), null, now);
		snapshot.setAccountHash(ACCOUNT);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(snapshot, null));
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
	}

	/** A stopped session on the demons task, as saved at a logout. */
	private SessionTracker.Summary startedSummary()
	{
		SessionTracker other = new SessionTracker(() -> now);
		other.observe("Abyssal demons", DEMONS, 100, false);
		other.play(ACCOUNT);
		return other.stopAndReset();
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.SessionTracker.ObserveResult;
import static com.shmayvan.slayerledger.SessionTracker.State;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class SessionTrackerTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final long OTHER_ACCOUNT = 777L;

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		// Simulates the first post-login observation (no task yet) so Play is allowed.
		noTask();
	}

	private ObserveResult noTask()
	{
		return tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
	}

	private ObserveResult demons(int remaining)
	{
		return tracker.observe("Abyssal demons", DEMON_ID, remaining, false);
	}

	@Test
	public void transitions()
	{
		assertEquals(State.IDLE, tracker.getState());
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(State.RUNNING, tracker.getState());
		assertTrue(tracker.pause());
		assertEquals(State.PAUSED, tracker.getState());
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(State.RUNNING, tracker.getState());
		assertTrue(tracker.stop());
		assertEquals(State.STOPPED, tracker.getState());
		assertTrue(tracker.reset());
		assertEquals(State.IDLE, tracker.getState());
	}

	@Test
	public void stopFromPaused()
	{
		tracker.play(ACCOUNT);
		tracker.pause();
		assertTrue(tracker.stop());
		assertEquals(State.STOPPED, tracker.getState());
	}

	@Test
	public void invalidTransitionsAreNoOps()
	{
		assertFalse(tracker.pause());
		assertFalse(tracker.stop());
		assertFalse(tracker.autoPause());
		assertFalse(tracker.reset());
		assertNull(tracker.stopAndReset());
		assertEquals(State.IDLE, tracker.getState());

		tracker.play(ACCOUNT);
		assertFalse(tracker.play(ACCOUNT));
		assertFalse(tracker.reset());
		assertEquals(State.RUNNING, tracker.getState());

		tracker.pause();
		assertFalse(tracker.pause());
		assertFalse(tracker.autoPause());
		assertEquals(State.PAUSED, tracker.getState());

		tracker.stop();
		assertFalse(tracker.play(ACCOUNT));
		assertFalse(tracker.pause());
		assertFalse(tracker.stop());
		assertEquals(State.STOPPED, tracker.getState());
	}

	@Test
	public void elapsedOnlyAccumulatesWhileRunning()
	{
		now += 5_000; // idle time is not counted
		tracker.play(ACCOUNT);
		now += 10_000;
		assertEquals(10_000, tracker.getActiveMillis());
		tracker.pause();
		now += 60_000;
		assertEquals(10_000, tracker.getActiveMillis());
		tracker.play(ACCOUNT);
		now += 2_500;
		assertEquals(12_500, tracker.getActiveMillis());
		tracker.stop();
		now += 30_000;
		assertEquals(12_500, tracker.getActiveMillis());
		assertEquals(12_500, tracker.summary().getActiveMillis());
	}

	@Test
	public void countsDecreasesOnlyWhileRunning()
	{
		demons(100);
		demons(99); // before session start: ignored
		tracker.play(ACCOUNT);
		assertEquals(0, tracker.getKills());
		demons(97);
		assertEquals(2, tracker.getKills());
		tracker.pause();
		demons(90); // paused: ignored, but baseline moves
		assertEquals(2, tracker.getKills());
		tracker.play(ACCOUNT);
		demons(89);
		assertEquals(3, tracker.getKills());
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertNotNull(summary);
		assertEquals(99, summary.getInitialAmount());
		assertEquals(3, summary.getKills());
		assertEquals("Abyssal demons", summary.getMonster());
		assertEquals(DEMON_ID, summary.getCreatureId());
		assertFalse(summary.isCompleted());
		assertEquals(State.IDLE, tracker.getState());
		assertEquals(0, tracker.getKills());
	}

	@Test
	public void increasesAreNotKills()
	{
		tracker.play(ACCOUNT);
		demons(50); // first observation: baseline only
		assertEquals(0, tracker.getKills());
		demons(60); // e.g. extended task
		assertEquals(0, tracker.getKills());
		demons(58);
		assertEquals(2, tracker.getKills());
	}

	@Test
	public void sessionStartedWithoutTaskAdoptsFirstTask()
	{
		tracker.play(ACCOUNT);
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertFalse(tracker.hasSessionTask());
		demons(120);
		assertTrue(tracker.hasSessionTask());
		demons(119);
		assertEquals(1, tracker.getKills());
		assertEquals(120, tracker.summary().getInitialAmount());
	}

	@Test
	public void autoPause()
	{
		demons(10);
		tracker.play(ACCOUNT);
		now += 1_000;
		assertTrue(tracker.autoPause());
		assertEquals(State.PAUSED, tracker.getState());
		now += 5_000;
		assertEquals(1_000, tracker.getActiveMillis());
		// resume is manual: further observations do not resume
		demons(10);
		assertEquals(State.PAUSED, tracker.getState());
	}

	@Test
	public void completionWithSignal()
	{
		demons(3);
		tracker.play(ACCOUNT);
		demons(1);
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.isCompleted());
		assertEquals(3, tracker.getKills());
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertTrue(summary.isCompleted());
		assertEquals(3, summary.getKills());
	}

	@Test
	public void completionSignalOnLaterObservation()
	{
		demons(2);
		tracker.play(ACCOUNT);
		assertEquals(ObserveResult.TASK_CLEARED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		assertFalse(tracker.isCompleted());
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.isCompleted());
		assertEquals(2, tracker.getKills());
	}

	@Test
	public void clearedWithoutCompletionIsNotCompleted()
	{
		demons(80);
		tracker.play(ACCOUNT);
		demons(75);
		// cancelled task: count drops to zero without a completion signal
		assertEquals(ObserveResult.TASK_CLEARED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		assertEquals(5, tracker.getKills());
		assertFalse(tracker.isCompleted());
		// then a new task is assigned
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Black dragons", DRAGON_ID, 20, false));
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertFalse(summary.isCompleted());
		assertEquals(5, summary.getKills());
		assertEquals("Abyssal demons", summary.getMonster());
		// the new task is current for the next session
		assertEquals("Black dragons", tracker.getCurrentMonster());
		assertEquals(20, tracker.getCurrentRemaining());
	}

	@Test
	public void taskChangeDuringSession()
	{
		demons(50);
		tracker.play(ACCOUNT);
		demons(45);
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Black dragons", DRAGON_ID, 30, false));
		// change of task does not count as kills
		assertEquals(5, tracker.getKills());
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals("Abyssal demons", summary.getMonster());
		tracker.play(ACCOUNT);
		assertEquals("Black dragons", tracker.summary().getMonster());
		assertEquals(30, tracker.summary().getInitialAmount());
	}

	@Test
	public void completionWhilePausedDoesNotAddKills()
	{
		demons(1);
		tracker.play(ACCOUNT);
		tracker.pause();
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.isCompleted());
		assertEquals(0, tracker.getKills());
	}

	@Test
	public void partialFlagOnRecord()
	{
		demons(10);
		tracker.play(ACCOUNT);
		now += 3_000;
		demons(8);
		SessionTracker.Summary summary = tracker.stopAndReset();

		LedgerRecord partial = LedgerRecord.fromSummary(summary, true);
		assertTrue(partial.isPartial());
		assertFalse(partial.isCompleted());
		assertEquals(2, partial.getKills());
		assertEquals(10, partial.getInitialAmount());
		assertEquals(3_000, partial.getActiveMillis());
		assertEquals(Integer.valueOf(DEMON_ID), partial.getCreatureId());
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, partial.getSchemaVersion());
		assertNotNull(partial.getId());
		assertEquals(1_000_000L, partial.getStartedAt());
		assertEquals(1_003_000L, partial.getEndedAt());
	}

	@Test
	public void playRefusedUntilTaskObserved()
	{
		SessionTracker fresh = new SessionTracker(() -> now);
		assertFalse(fresh.canPlay(ACCOUNT));
		assertFalse(fresh.play(ACCOUNT));
		assertEquals(State.IDLE, fresh.getState());
		fresh.observe("Abyssal demons", DEMON_ID, 10, false);
		assertTrue(fresh.canPlay(ACCOUNT));
		assertFalse(fresh.canPlay(SessionTracker.NO_ACCOUNT));
		assertFalse(fresh.play(SessionTracker.NO_ACCOUNT));
		assertTrue(fresh.play(ACCOUNT));
	}

	@Test
	public void clearCurrentTaskForgetsStaleTaskAndBlocksPlay()
	{
		demons(50);
		tracker.clearCurrentTask();
		assertNull(tracker.getCurrentMonster());
		assertEquals(0, tracker.getCurrentRemaining());
		assertFalse(tracker.isTaskObserved());
		assertFalse(tracker.canPlay(ACCOUNT));
		assertFalse(tracker.play(ACCOUNT));

		// first observation on the new login enables Play with the fresh task
		tracker.observe("Black dragons", DRAGON_ID, 12, false);
		assertTrue(tracker.play(OTHER_ACCOUNT));
		assertEquals("Black dragons", tracker.summary().getMonster());
		assertEquals(12, tracker.summary().getInitialAmount());
	}

	@Test
	public void clearCurrentTaskBlocksResumeUntilObserved()
	{
		demons(50);
		tracker.play(ACCOUNT);
		tracker.autoPause();
		tracker.clearCurrentTask();
		assertFalse(tracker.play(ACCOUNT));
		demons(50);
		assertTrue(tracker.play(ACCOUNT));
	}

	@Test
	public void sessionAccountIsCapturedAtomically()
	{
		demons(50);
		tracker.play(ACCOUNT);
		assertEquals(ACCOUNT, tracker.getSessionAccountHash());
		tracker.pause();
		// resuming with another account is refused
		assertFalse(tracker.canPlay(OTHER_ACCOUNT));
		assertFalse(tracker.play(OTHER_ACCOUNT));
		assertNull(tracker.stopAndResetIfOtherAccount(ACCOUNT));
		assertEquals(State.PAUSED, tracker.getState());

		SessionTracker.Summary summary = tracker.stopAndResetIfOtherAccount(OTHER_ACCOUNT);
		assertNotNull(summary);
		assertEquals(ACCOUNT, summary.getAccountHash());
		assertEquals(State.IDLE, tracker.getState());
		assertEquals(SessionTracker.NO_ACCOUNT, tracker.getSessionAccountHash());
		assertNull(tracker.stopAndResetIfOtherAccount(OTHER_ACCOUNT));
	}

	@Test
	public void sameTaskReturningAfterTransientZeroResumes()
	{
		demons(10);
		tracker.play(ACCOUNT);
		demons(8);
		assertEquals(ObserveResult.TASK_CLEARED, noTask());
		// the same task comes back: not a change, and the drop is not counted
		assertEquals(ObserveResult.NONE, demons(8));
		assertEquals(2, tracker.getKills());
		demons(7);
		assertEquals(3, tracker.getKills());
		// a completion signal while the task is still active is not a completion
		assertEquals(ObserveResult.NONE, tracker.observe("Abyssal demons", DEMON_ID, 7, true));
		assertFalse(tracker.isCompleted());
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertEquals(10, tracker.getKills());
	}

	@Test
	public void lateCounterSyncWhileClearedIsNotCompletionAfterTaskReturns()
	{
		demons(10);
		tracker.play(ACCOUNT);
		noTask();
		demons(10);
		// even if a signal arrives now, the task is active again so it is not a completion
		assertEquals(ObserveResult.NONE, tracker.observe("Abyssal demons", DEMON_ID, 10, true));
		assertFalse(tracker.isCompleted());
	}

	@Test
	public void originalAmountIsTracked()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 120, 150, false);
		tracker.play(ACCOUNT);
		assertEquals(150, tracker.summary().getOriginalAmount());
		// extension changes the assigned size
		tracker.observe("Abyssal demons", DEMON_ID, 119, 200, false);
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(200, summary.getOriginalAmount());
		assertEquals(Integer.valueOf(200), LedgerRecord.fromSummary(summary, false).getOriginalAmount());
	}

	@Test
	public void unknownOriginalAmountIsNullOnRecord()
	{
		demons(20);
		tracker.play(ACCOUNT);
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(SessionTracker.UNKNOWN_AMOUNT, summary.getOriginalAmount());
		assertNull(LedgerRecord.fromSummary(summary, true).getOriginalAmount());
	}

	@Test
	public void unknownNameDoesNotLookLikeTaskChange()
	{
		tracker.observe(null, DEMON_ID, 30, false);
		tracker.play(ACCOUNT);
		// lookup succeeds later: same creature id, so same task, and the name is filled in
		assertEquals(ObserveResult.NONE, demons(29));
		assertEquals(1, tracker.getKills());
		assertEquals("Abyssal demons", tracker.summary().getMonster());
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe(null, DRAGON_ID, 30, false));
	}

	@Test
	public void unknownNameFallbackOnRecord()
	{
		tracker.observe(null, DEMON_ID, 30, false);
		tracker.play(ACCOUNT);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals("Unknown task (" + DEMON_ID + ")", record.getMonster());
	}

	@Test
	public void shortZeroGapResumesSameTask()
	{
		demons(10);
		tracker.play(ACCOUNT);
		demons(8);
		for (int i = 0; i < SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		// even with a higher count, a short gap is a glitch rather than a reassignment
		assertEquals(ObserveResult.NONE, demons(9));
		assertEquals(2, tracker.getKills());
	}

	@Test
	public void longZeroGapWithSameCreatureIsTaskChange()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, 150, false);
		tracker.play(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 8, 150, false);
		for (int i = 0; i <= SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		// cancelled then reassigned to the same creature with a new size
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Abyssal demons", DEMON_ID, 120, 120, false));
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(2, summary.getKills());
		assertFalse(summary.isCompleted());
	}

	@Test
	public void longZeroGapWithHigherRemainingIsTaskChangeEvenWithSameSize()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, 150, false);
		tracker.play(ACCOUNT);
		for (int i = 0; i <= SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Abyssal demons", DEMON_ID, 150, 150, false));
	}

	@Test
	public void longZeroGapWithUnchangedSizeAndNoIncreaseResumes()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, 150, false);
		tracker.play(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 8, 150, false);
		for (int i = 0; i < 10; i++)
		{
			noTask();
		}
		assertEquals(ObserveResult.NONE, tracker.observe("Abyssal demons", DEMON_ID, 8, 150, false));
		tracker.observe("Abyssal demons", DEMON_ID, 6, 150, false);
		assertEquals(4, tracker.getKills());
	}

	@Test
	public void longZeroGapWithUnknownSizeIsTaskChange()
	{
		demons(10);
		tracker.play(ACCOUNT);
		for (int i = 0; i <= SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		assertEquals(ObserveResult.TASK_CHANGED, demons(5));
	}

	@Test
	public void bossTasksUseDistinctCreatureKeys()
	{
		int zulrah = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 21);
		int vorkath = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 22);
		assertEquals(DEMON_ID, SessionTracker.creatureKey(DEMON_ID, 0));
		assertTrue(zulrah != vorkath);
		assertTrue(zulrah < SessionTracker.NO_CREATURE);
		assertTrue(SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 0) != SessionTracker.NO_CREATURE);

		// boss-to-boss change with failed name lookups is still a task change
		tracker.observe(null, zulrah, 5, false);
		tracker.play(ACCOUNT);
		assertEquals(ObserveResult.NONE, tracker.observe(null, zulrah, 4, false));
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe(null, vorkath, 5, false));

		SessionTracker.Summary summary = tracker.stopAndReset();
		LedgerRecord record = LedgerRecord.fromSummary(summary, true);
		assertEquals(Integer.valueOf(zulrah), record.getCreatureId());
		assertEquals("Unknown boss task (21)", record.getMonster());
	}

	@Test
	public void liveTaskKnowsTheKillsLeftOnlyWhileTheSessionsTaskIsObserved()
	{
		assertNull("idle", tracker.liveTask());
		assertTrue(tracker.play(ACCOUNT));
		assertNull("a session without a task", tracker.liveTask());

		demons(20);
		now += 60_000;
		demons(17);
		SessionTracker.LiveTask live = tracker.liveTask();
		assertEquals(State.RUNNING, live.getState());
		assertEquals(tracker.getSessionId(), live.getSessionId());
		assertEquals("Abyssal demons", live.getMonster());
		assertEquals(DEMON_ID, live.getCreatureId());
		assertEquals(3, live.getKills());
		assertEquals(60_000, live.getActiveMillis());
		assertEquals(17, live.getRemaining());

		// Logout: paused, and the task is not read again until the next observation.
		assertTrue(tracker.autoPause());
		tracker.clearCurrentTask();
		assertEquals(State.PAUSED, tracker.liveTask().getState());
		assertEquals(SessionTracker.LiveTask.UNKNOWN_REMAINING, tracker.liveTask().getRemaining());
		demons(17);
		assertEquals(17, tracker.liveTask().getRemaining());

		// Another task observed while paused is not the session's.
		tracker.observe("Black dragons", DRAGON_ID, 30, false);
		assertEquals(SessionTracker.LiveTask.UNKNOWN_REMAINING, tracker.liveTask().getRemaining());
		demons(17);

		// A cleared count waiting for its completion message.
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(ObserveResult.TASK_CLEARED, demons(0));
		assertEquals(SessionTracker.LiveTask.UNKNOWN_REMAINING, tracker.liveTask().getRemaining());

		assertTrue(tracker.stop());
		assertNull("stopped", tracker.liveTask());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Before;
import org.junit.Test;

/**
 * XP gained per task in {@link SessionTracker#observeXp}: counted only while RUNNING, against the previous
 * reading, never across a reset baseline, and carried through summaries, snapshots and records.
 */
public class SessionTrackerXpTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private long now;
	private SessionTracker tracker;
	/** The player's XP, as the plugin would read it each tick. */
	private final Map<String, Integer> stats = new HashMap<>();

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		stats.put("SLAYER", 1_000_000);
		stats.put("HITPOINTS", 2_000_000);
		stats.put("MAGIC", 3_000_000);
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
	}

	/** One tick's reading of {@link #stats}. */
	private boolean read()
	{
		return tracker.observeXp(new HashMap<>(stats));
	}

	private void gain(String skill, int xp)
	{
		stats.merge(skill, xp, Integer::sum);
	}

	private static Map<String, Long> xp(Object... skillAndXp)
	{
		Map<String, Long> map = new TreeMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], ((Number) skillAndXp[i + 1]).longValue());
		}
		return map;
	}

	// ---- Baseline and diff ----

	@Test
	public void xpAfterPlayIsCountedAgainstTheReadingBeforeIt()
	{
		read();
		gain("SLAYER", 500);
		assertFalse("before Play nothing counts", read());
		assertTrue(tracker.play(ACCOUNT));
		gain("SLAYER", 120);
		gain("HITPOINTS", 40);
		assertTrue(read());
		gain("SLAYER", 80);
		read();
		assertEquals(xp("SLAYER", 200, "HITPOINTS", 40), tracker.getXpGained());
		assertEquals(xp("SLAYER", 200, "HITPOINTS", 40), tracker.activeSummary().getXpGained());
	}

	@Test
	public void theFirstReadingOnlySetsTheBaseline()
	{
		assertTrue(tracker.play(ACCOUNT));
		assertFalse(read());
		gain("SLAYER", 50);
		read();
		assertEquals(xp("SLAYER", 50), tracker.getXpGained());
	}

	@Test
	public void noChangeAddsNothing()
	{
		tracker.play(ACCOUNT);
		read();
		assertFalse(read());
		assertTrue(tracker.getXpGained().isEmpty());
	}

	// ---- Pause and resume ----

	@Test
	public void xpWhilePausedIsNotCountedAndResumeCountsFromTheLatestReading()
	{
		tracker.play(ACCOUNT);
		read();
		gain("SLAYER", 100);
		read();
		tracker.pause();
		gain("SLAYER", 5_000);
		gain("MAGIC", 9_000);
		assertFalse(read());
		read();
		assertTrue(tracker.play(ACCOUNT));
		gain("MAGIC", 30);
		read();
		assertEquals(xp("SLAYER", 100, "MAGIC", 30), tracker.getXpGained());
	}

	@Test
	public void autoPauseStopsCountingToo()
	{
		tracker.play(ACCOUNT);
		read();
		tracker.autoPause();
		gain("SLAYER", 100);
		read();
		assertTrue(tracker.getXpGained().isEmpty());
	}

	// ---- Re-login, hop and account switch ----

	@Test
	public void aResetBaselineNeverCountsTheNextReading()
	{
		tracker.play(ACCOUNT);
		read();
		gain("SLAYER", 10);
		read();
		// Login, hop or lost connection: the stats are re-sent, possibly with XP the session never saw being gained.
		tracker.resetXpBaseline();
		gain("SLAYER", 400_000);
		assertFalse(read());
		gain("SLAYER", 25);
		read();
		assertEquals(xp("SLAYER", 35), tracker.getXpGained());
	}

	@Test
	public void anUnsyncedReadingDropsTheBaseline()
	{
		tracker.play(ACCOUNT);
		read();
		// Hitpoints XP read 0: the caller passes null and the stats then arrive in a burst.
		assertFalse(tracker.observeXp(null));
		gain("SLAYER", 1_000);
		assertFalse("the login burst is only a baseline", read());
		assertTrue(tracker.getXpGained().isEmpty());
	}

	@Test
	public void aDecreaseIsAnotherAccountAndOnlyMovesTheBaseline()
	{
		tracker.play(ACCOUNT);
		read();
		Map<String, Integer> other = new HashMap<>();
		other.put("SLAYER", 13_034_431);
		other.put("HITPOINTS", 1_154);
		other.put("MAGIC", 0);
		assertFalse(tracker.observeXp(other));
		other.put("SLAYER", 13_034_500);
		assertTrue(tracker.observeXp(other));
		assertEquals(xp("SLAYER", 69), tracker.getXpGained());
	}

	// ---- Grace window ----

	@Test
	public void aHeldCompletionGetsNoXpAfterItsCompletionTick()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 1, 150, false);
		tracker.play(ACCOUNT);
		read();
		// The completion tick: the plugin reads XP before observing the task, so the final kill's XP counts.
		gain("SLAYER", 300);
		read();
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true));
		assertTrue(tracker.holdCompletion());

		gain("SLAYER", 999);
		assertFalse(read());
		assertNull(tracker.tickCompletion());
		gain("PRAYER", 5);
		read();
		SessionTracker.Summary saved = tracker.tickCompletion();
		assertNotNull(saved);
		assertEquals(xp("SLAYER", 300), saved.getXpGained());
		assertEquals(xp("SLAYER", 300), LedgerRecord.fromSummary(saved, false).getXpGained());
	}

	@Test
	public void aNewSessionStartsWithNoXpAndCountsItsOwn()
	{
		tracker.play(ACCOUNT);
		read();
		gain("SLAYER", 100);
		read();
		SessionTracker.Summary first = tracker.stopAndReset();
		assertEquals(xp("SLAYER", 100), first.getXpGained());
		assertTrue(tracker.getXpGained().isEmpty());
		gain("SLAYER", 50);
		read();
		tracker.play(ACCOUNT);
		gain("SLAYER", 7);
		read();
		assertEquals(xp("SLAYER", 7), tracker.getXpGained());
	}

	// ---- Snapshot and records ----

	@Test
	public void xpSurvivesASnapshotRoundTripAndTheRestoredSessionKeepsCounting()
	{
		tracker.play(ACCOUNT);
		read();
		gain("SLAYER", 400);
		gain("MAGIC", 1_200);
		read();
		tracker.autoPause();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(xp("SLAYER", 400, "MAGIC", 1_200), snapshot.getXpGained());
		Gson gson = new Gson();
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertEquals(xp("SLAYER", 400, "MAGIC", 1_200), restored.getXpGained());
		// The restored tracker has no baseline: the login's first reading only sets it.
		restored.observeXp(new HashMap<>(stats));
		assertTrue(restored.play(ACCOUNT));
		gain("SLAYER", 100);
		restored.observeXp(new HashMap<>(stats));
		assertEquals(xp("SLAYER", 500, "MAGIC", 1_200), LedgerRecord.fromSummary(restored.stopAndReset(), false)
			.getXpGained());
	}

	@Test
	public void aSnapshotFromBeforeXpWasTrackedRestoresWithNoneAndCountsFromThere()
	{
		tracker.play(ACCOUNT);
		tracker.autoPause();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		snapshot.setXpGained(null);
		Gson gson = new Gson();
		String json = gson.toJson(snapshot);
		assertFalse("an older file has no field", json.contains("xpGained"));
		SessionSnapshot old = gson.fromJson(json, SessionSnapshot.class);

		// Saved as partial (it no longer matches): the XP is unknown, not 0.
		assertNull(old.toSummary().getXpGained());
		assertNull(LedgerRecord.fromSummary(old.toSummary(), true).getXpGained());

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(old, COUNTERS));
		assertEquals(Collections.emptyMap(), restored.getXpGained());
	}

	@Test
	public void aRecordWithNoXpGainedStoresAnEmptyMap()
	{
		tracker.play(ACCOUNT);
		read();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertEquals(Collections.emptyMap(), record.getXpGained());
		assertEquals("XP: 0", LedgerHistory.formatXp(record));
	}

	@Test
	public void anOldRecordShowsADash()
	{
		LedgerRecord old = new Gson().fromJson("{\"schemaVersion\":2,\"id\":\"a\",\"monster\":\"Abyssal demons\","
			+ "\"kills\":5,\"activeMillis\":600000}", LedgerRecord.class);
		assertNull(old.getXpGained());
		assertEquals("XP: -", LedgerHistory.formatXp(old));
		assertEquals("", LedgerHistory.formatXpRate(old));
	}

	@Test
	public void aRecordShowsItsTotalAndRate()
	{
		LedgerRecord record = new Gson().fromJson("{\"schemaVersion\":2,\"id\":\"a\",\"monster\":\"Abyssal demons\","
			+ "\"kills\":5,\"activeMillis\":1800000,\"xpGained\":{\"SLAYER\":15000,\"HITPOINTS\":5000}}",
			LedgerRecord.class);
		assertEquals(xp("SLAYER", 15_000, "HITPOINTS", 5_000), record.getXpGained());
		assertEquals("XP: 20K", LedgerHistory.formatXp(record));
		assertEquals("XP/h: 40K", LedgerHistory.formatXpRate(record));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Live session valuation for the panel: totals, per-dose potions, unit-price caching, retries and resets.
 */
public class SessionValuationTest
{
	private static final int BONES = 526;
	private static final int SHARK = 385;
	private static final int PRAYER_4 = 2434;

	/** Counts GE lookups per id; prices can be changed or made unavailable (0) between calls. */
	private static final class CountingLookup implements ItemValuation.PriceLookup
	{
		final Map<Integer, Long> ge = new HashMap<>();
		final Map<Integer, Integer> lookups = new HashMap<>();

		CountingLookup()
		{
			ge.put(BONES, 100L);
			ge.put(SHARK, 1_000L);
			ge.put(PRAYER_4, 8_000L);
		}

		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int canonicalId)
		{
			lookups.merge(canonicalId, 1, Integer::sum);
			return ge.getOrDefault(canonicalId, 0L);
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return canonicalId == SHARK ? 180 : 0;
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}

		int lookups(int id)
		{
			return lookups.getOrDefault(id, 0);
		}
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	private final SessionValuation valuation = new SessionValuation();
	private final CountingLookup lookup = new CountingLookup();

	@Test
	public void valuesLootSuppliesAndProfitWithPotionsPerDose()
	{
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 10, ItemValuation.COINS, 500),
			tally(SHARK, 3, PRAYER_4, 5), Collections.singletonMap(PRAYER_4, 4), lookup, 0);
		assertEquals(10 * 100 + 500, v.getLootGe());
		assertEquals(500, v.getLootHa());
		// 3 sharks + 5 doses of a 4-dose potion (8,000 * 5 / 4).
		assertEquals(3_000 + 10_000, v.getSuppliesGe());
		assertEquals(540, v.getSuppliesHa());
		assertEquals("a loss", 1_500 - 13_000, v.getProfitGe());
		assertEquals(0, v.getLootUnpriced());
		assertEquals(0, v.getSuppliesUnpriced());
	}

	@Test
	public void emptySessionIsZero()
	{
		SessionValuation.Values v = valuation.update("s1", null, null, null, lookup, 0);
		assertEquals(new SessionValuation.Values("s1", 0, 0, 0, 0, 0, 0), v);
	}

	@Test
	public void unitPricesAreCachedForTheSession()
	{
		valuation.update("s1", tally(BONES, 1), tally(SHARK, 1), null, lookup, 0);
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 5), tally(SHARK, 2, PRAYER_4, 1),
			Collections.singletonMap(PRAYER_4, 4), lookup, 2);
		assertEquals(1, lookup.lookups(BONES));
		assertEquals(1, lookup.lookups(SHARK));
		assertEquals(1, lookup.lookups(PRAYER_4));
		assertEquals(500, v.getLootGe());
		assertEquals(2_000 + 2_000, v.getSuppliesGe());
	}

	@Test
	public void unchangedTalliesReturnTheSameValuesWithoutLookups()
	{
		SessionValuation.Values first = valuation.update("s1", tally(BONES, 1), new ItemTally(), null, lookup, 0);
		lookup.ge.put(BONES, 999L);
		SessionValuation.Values second = valuation.update("s1", tally(BONES, 1), new ItemTally(), null, lookup, 50);
		assertSame(first, second);
		assertEquals(1, lookup.lookups(BONES));
	}

	@Test
	public void newSessionDropsTheCache()
	{
		valuation.update("s1", tally(BONES, 1), null, null, lookup, 0);
		lookup.ge.put(BONES, 200L);
		SessionValuation.Values v = valuation.update("s2", tally(BONES, 1), null, null, lookup, 2);
		assertEquals(200, v.getLootGe());
		assertEquals(2, lookup.lookups(BONES));
	}

	@Test
	public void resetDropsTheCache()
	{
		valuation.update("s1", tally(BONES, 1), null, null, lookup, 0);
		valuation.reset();
		lookup.ge.put(BONES, 300L);
		assertEquals(300, valuation.update("s1", tally(BONES, 1), null, null, lookup, 2).getLootGe());
	}

	@Test
	public void unavailablePricesAreCountedAndRetriedOnACadence()
	{
		lookup.ge.put(SHARK, 0L);
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 1), tally(SHARK, 4), null, lookup, 100);
		assertEquals(100, v.getLootGe());
		assertEquals("known prices still sum", 0, v.getSuppliesGe());
		assertEquals(1, v.getSuppliesUnpriced());
		assertEquals(1, lookup.lookups(SHARK));

		// Prices load meanwhile, but nothing changed and the retry window has not passed.
		lookup.ge.put(SHARK, 1_000L);
		valuation.update("s1", tally(BONES, 1), tally(SHARK, 4), null, lookup, 100 + SessionValuation.RETRY_TICKS - 1);
		assertEquals(1, lookup.lookups(SHARK));

		v = valuation.update("s1", tally(BONES, 1), tally(SHARK, 4), null, lookup, 100 + SessionValuation.RETRY_TICKS);
		assertEquals(2, lookup.lookups(SHARK));
		assertEquals(4_000, v.getSuppliesGe());
		assertEquals(0, v.getSuppliesUnpriced());
		assertEquals("found prices are not looked up again", 1, lookup.lookups(BONES));
	}

	@Test
	public void missingItemsNoLongerInTheTalliesAreNotRetried()
	{
		lookup.ge.put(SHARK, 0L);
		valuation.update("s1", tally(BONES, 1), tally(SHARK, 1), null, lookup, 0);
		// The shark was "returned" (supplies back to zero): it is gone from the tally.
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 1), new ItemTally(), null, lookup,
			SessionValuation.RETRY_TICKS);
		assertEquals(1, lookup.lookups(SHARK));
		assertEquals(0, v.getSuppliesUnpriced());
	}

	@Test
	public void profitSaturates()
	{
		SessionValuation.Values v = new SessionValuation.Values("s1", Long.MAX_VALUE, 0, -1, 0, 0, 0);
		assertEquals(Long.MAX_VALUE, v.getProfitGe());
	}

	// ---- Loot price mode ----

	@Test
	public void lootFollowsThePriceModeAndSuppliesStayAtGe()
	{
		// Shark: GE 100, high alch 180. Bones: GE 100, high alch 0.
		lookup.ge.put(SHARK, 100L);
		ItemTally loot = tally(SHARK, 2, BONES, 1);
		ItemTally supplies = tally(SHARK, 1);

		SessionValuation.Values ge = valuation.update("s1", loot, supplies, null, LootPriceMode.GE, lookup, 0);
		assertEquals(LootPriceMode.GE, ge.getLootPriceMode());
		assertEquals(300, ge.getLootValue());
		assertEquals(200, ge.getProfit());

		SessionValuation.Values ha = valuation.update("s1", loot, supplies, null, LootPriceMode.HIGH_ALCH, lookup, 1);
		assertEquals(LootPriceMode.HIGH_ALCH, ha.getLootPriceMode());
		assertEquals(360, ha.getLootValue());
		assertEquals("supplies stay at GE", 100, ha.getSuppliesGe());
		assertEquals(260, ha.getProfit());
		assertEquals("the GE figures are kept", 300, ha.getLootGe());
		assertEquals(200, ha.getProfitGe());

		SessionValuation.Values back = valuation.update("s1", loot, supplies, null, LootPriceMode.GE, lookup, 2);
		assertEquals(LootPriceMode.GE, back.getLootPriceMode());
		assertEquals(300, back.getLootValue());
		assertEquals("a mode change reuses the cached prices", 1, lookup.lookups(SHARK));
		assertEquals(1, lookup.lookups(BONES));

		assertSame("unchanged mode and tallies", back,
			valuation.update("s1", loot, supplies, null, LootPriceMode.GE, lookup, 3));
	}

	@Test
	public void highAlchCountsOnlyItemsWithoutAHighAlchValueAsUnpriced()
	{
		lookup.ge.put(SHARK, 0L);
		SessionValuation.Values v = valuation.update("s1", tally(SHARK, 1, BONES, 1), null, null,
			LootPriceMode.HIGH_ALCH, lookup, 0);
		assertEquals("the shark at its high alch value", 180, v.getLootValue());
		assertEquals("both items have a high alch value", 0, v.getLootValueUnpriced());
		assertEquals("the shark's GE price is unavailable", 1, v.getLootUnpriced());
		assertEquals("the ~ follows the shown (high alch) figure", "Loot (HA): 180 gp", LiveSessionSection.liveLootText(v));
		String tooltip = LedgerHistory.valuesTooltip(v);
		// The GE figure misses the shark, so it is marked and counted in the note.
		assertTrue(tooltip, tooltip.contains("Loot: ~100 gp GE, 180 gp high alch"));
		assertTrue(tooltip, tooltip.contains("~ Some prices were unavailable (loot at high alch: 0, loot at GE: 1,"
			+ " supplies: 0), so the figures marked ~ may be too low."));

		SessionValuation.Values ge = valuation.update("s1", tally(SHARK, 1, BONES, 1), null, null, LootPriceMode.GE,
			lookup, 1);
		String geTooltip = LedgerHistory.valuesTooltip(ge);
		assertTrue(geTooltip, geTooltip.contains("Loot: ~100 gp GE, 180 gp high alch"));
		assertTrue("GE mode keeps its note", geTooltip.contains("(loot: 1, supplies: 0), so totals may be too low."));
	}

	@Test
	public void highAlchTooltipHasNoGeNoteWhenEveryGePriceIsKnown()
	{
		lookup.ge.put(SHARK, 100L);
		SessionValuation.Values v = valuation.update("s1", tally(SHARK, 1), tally(BONES, 1), null,
			LootPriceMode.HIGH_ALCH, lookup, 0);
		String tooltip = LedgerHistory.valuesTooltip(v);
		assertTrue(tooltip, tooltip.contains("Loot: 100 gp GE, 180 gp high alch"));
		assertFalse(tooltip, tooltip.contains("~"));
	}

	@Test
	public void anUntradeableItemCountsAtHighAlchInEveryMode()
	{
		// 7 Brimstone keys: untradeable (GE 0), high alch 48,000. One more item at GE 100 / high alch 60.
		final int key = 23083;
		final int rune = 1;
		ItemValuation.PriceLookup keys = new ItemValuation.PriceLookup()
		{
			@Override
			public int canonicalize(int itemId)
			{
				return itemId;
			}

			@Override
			public long gePrice(int canonicalId)
			{
				return canonicalId == rune ? 100 : 0;
			}

			@Override
			public boolean isTradeable(int canonicalId)
			{
				return canonicalId != key;
			}

			@Override
			public long haPrice(int canonicalId)
			{
				return canonicalId == key ? 48_000 : 60;
			}
		};
		ItemTally loot = tally(key, 7, rune, 1);
		// An untradeable supply stays at its GE price of 0: supplies are not part of the rule.
		ItemTally supplies = tally(key, 1);

		SessionValuation.Values ge = valuation.update("s1", loot, supplies, null, LootPriceMode.GE, keys, 0);
		assertEquals(336_100, ge.getLootValue());
		assertEquals(336_100, ge.getLootGe());
		assertEquals(0, ge.getLootValueUnpriced());
		assertEquals(0, ge.getLootUnpriced());
		assertEquals(0, ge.getSuppliesGe());
		assertEquals(336_100, ge.getProfit());

		SessionValuation.Values ha = valuation.update("s1", loot, supplies, null, LootPriceMode.HIGH_ALCH, keys, 1);
		assertEquals(336_060, ha.getLootValue());
		assertEquals("no ~", "Loot (HA): 336K gp", LiveSessionSection.liveLootText(ha));
		String tooltip = LedgerHistory.valuesTooltip(ha);
		assertTrue(tooltip, tooltip.contains("Loot: 336,100 gp GE, 336,060 gp high alch"));
		assertTrue(tooltip, tooltip.contains("Loot value (High alch): 336,060 gp"));
	}

	@Test
	public void liveLootAndProfitLinesAreLabelledWithThePriceMode()
	{
		lookup.ge.put(SHARK, 100L);
		ItemTally loot = tally(SHARK, 2);
		SessionValuation.Values ge = valuation.update("s1", loot, null, null, LootPriceMode.GE, lookup, 0);
		assertEquals("Loot (GE): 200 gp", LiveSessionSection.liveLootText(ge));
		assertEquals("Profit (GE): 200 gp", LiveSessionSection.liveProfitText(ge));
		String geTooltip = LedgerHistory.valuesTooltip(ge);
		assertTrue("both prices stay in the tooltip", geTooltip.contains("Loot: 200 gp GE, 360 gp high alch"));
		assertTrue(geTooltip, geTooltip.contains("Profit: 200 gp GE"));

		SessionValuation.Values ha = valuation.update("s1", loot, null, null, LootPriceMode.HIGH_ALCH, lookup, 1);
		assertEquals("Loot (HA): 360 gp", LiveSessionSection.liveLootText(ha));
		assertEquals("Profit (HA): 360 gp", LiveSessionSection.liveProfitText(ha));
		String tooltip = LedgerHistory.valuesTooltip(ha);
		assertTrue(tooltip, tooltip.contains("Loot: 200 gp GE, 360 gp high alch"));
		assertTrue(tooltip, tooltip.contains("Loot value (High alch): 360 gp"));
		assertTrue(tooltip, tooltip.contains("Profit: 360 gp (loot at high alch, supplies at GE)"));
	}

	@Test
	public void liveProfitIsApproximateWhenASupplyIsUnpriced()
	{
		lookup.ge.put(SHARK, 0L);
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 1), tally(SHARK, 1), null, LootPriceMode.GE,
			lookup, 0);
		assertEquals(1, v.getSuppliesUnpriced());
		String profit = LiveSessionSection.liveProfitText(v);
		assertTrue(profit, profit.startsWith("Profit (GE): ~"));
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** {@link SessionCounters}, {@link SessionLoot} and the {@link SessionTracker.Summary} builder. */
public class SessionValueObjectsTest
{
	@Test
	public void emptySummaryBuilderIsANewSession()
	{
		SessionTracker.Summary s = SessionTracker.Summary.builder().build();
		assertNull(s.getSessionId());
		assertEquals(SessionTracker.NO_ACCOUNT, s.getAccountHash());
		assertEquals(SessionTracker.NO_CREATURE, s.getCreatureId());
		assertEquals(SessionTracker.UNKNOWN_AMOUNT, s.getOriginalAmount());
		assertSame(TaskContext.NONE, s.getContext());
		assertEquals(Integer.valueOf(0), s.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(0), s.getBankTrips());
		assertEquals(Integer.valueOf(0), s.getDeaths());
		assertTrue(s.getLoot().isEmpty());
		assertTrue(s.getNotableDrops().isEmpty());
		assertEquals(Collections.emptyMap(), s.getXpGained());
		assertTrue(s.getLocationKills().isEmpty());
	}

	@Test
	public void nullsInTheSummaryBuilderAreEmptyOrUnknown()
	{
		SessionTracker.Summary s = SessionTracker.Summary.builder()
			.sessionLoot(null)
			.counters(null)
			.context(null)
			.xpGained(null)
			.locationKills(null)
			.build();
		assertSame(SessionLoot.EMPTY, s.getSessionLoot());
		assertSame(SessionCounters.ZERO, s.getCounters());
		assertSame(TaskContext.NONE, s.getContext());
		assertNull("unknown XP stays unknown", s.getXpGained());
		assertTrue(s.getLocationKills().isEmpty());
	}

	@Test
	public void copiesChangeOnlyWhatTheyNameAndKeepTheRest()
	{
		ItemTally loot = new ItemTally();
		loot.add(592, 3);
		SessionTracker.Summary s = SessionTracker.Summary.builder()
			.sessionId("s1")
			.kills(4)
			.counters(SessionCounters.builder().deaths(2).build())
			.sessionLoot(SessionLoot.builder().loot(loot).build())
			.note("Barrage")
			.build();

		SessionTracker.Summary noted = s.withNote("Cannon").withBossKillCount("Abyssal Sire", 10);
		assertEquals("Cannon", noted.getNote());
		assertEquals(1, noted.getBossKillCounts().size());
		assertEquals("s1", noted.getSessionId());
		assertEquals(4, noted.getKills());
		assertEquals(Integer.valueOf(2), noted.getDeaths());
		assertEquals(3, noted.getLoot().get(592));
		assertEquals("Barrage", s.getNote());

		ItemTally extra = new ItemTally();
		extra.add(592, 2);
		assertEquals(5, s.withAddedLoot(extra, null).getLoot().get(592));
		assertEquals(3, s.getLoot().get(592));
	}

	@Test
	public void sessionLootCopiesWhatItIsGiven()
	{
		ItemTally loot = new ItemTally();
		loot.add(592, 3);
		Map<Integer, Integer> doses = new HashMap<>();
		doses.put(2434, 4);
		doses.put(385, 0);
		List<BossKillCount> counts = new ArrayList<>(BossKillCounts.add(null, "Abyssal Sire", 10));
		SessionLoot built = SessionLoot.builder().loot(loot).supplyDoses(doses).bossKillCounts(counts).build();

		loot.add(592, 10);
		doses.put(2434, 3);
		counts.clear();
		assertEquals(3, built.getLoot().get(592));
		assertEquals(Collections.singletonMap(2434, 4), built.getSupplyDoses());
		assertEquals(1, built.getBossKillCounts().size());
		built.getLoot().add(592, 1);
		assertEquals("getters hand out copies", 3, built.getLoot().get(592));
	}

	@Test
	public void restoredCountersCountUnknownAndNegativeAsZero()
	{
		SessionCounters stored = SessionCounters.builder().superiorsSpawned(null).bankTrips(-3).deaths(2).build();
		SessionCounters restored = stored.withUnknownAsZero();
		assertEquals(Integer.valueOf(0), restored.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(0), restored.getBankTrips());
		assertEquals(Integer.valueOf(2), restored.getDeaths());
		assertNull("the stored counters are unchanged", stored.getSuperiorsSpawned());
	}

	@Test
	public void countersAreCopiedToBothPersistedShapesAndBack()
	{
		SessionCounters counters = SessionCounters.builder().superiorsSpawned(1).bankTrips(null).deaths(3).build();
		SessionSnapshot snapshot = new SessionSnapshot();
		counters.copyTo(snapshot);
		LedgerRecord record = new LedgerRecord();
		counters.copyTo(record);

		assertEquals(counters, SessionCounters.from(snapshot));
		assertEquals(Integer.valueOf(1), record.getSuperiorsSpawned());
		assertNull(record.getBankTrips());
		assertEquals(Integer.valueOf(3), record.getDeaths());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;

public class SkillXpTest
{
	private static Map<String, Integer> reading(Object... skillAndXp)
	{
		Map<String, Integer> map = new HashMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], (Integer) skillAndXp[i + 1]);
		}
		return map;
	}

	private static Map<String, Long> xp(Object... skillAndXp)
	{
		Map<String, Long> map = new TreeMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], ((Number) skillAndXp[i + 1]).longValue());
		}
		return map;
	}

	@Test
	public void gainsAreTheSkillsThatWentUp()
	{
		Map<String, Long> gains = SkillXp.gains(reading("SLAYER", 1000, "HITPOINTS", 5000, "PRAYER", 300),
			reading("SLAYER", 1250, "HITPOINTS", 5100, "PRAYER", 300));
		assertEquals(xp("SLAYER", 250, "HITPOINTS", 100), gains);
	}

	@Test
	public void noChangeIsNoGain()
	{
		assertEquals(Collections.emptyMap(), SkillXp.gains(reading("SLAYER", 1000), reading("SLAYER", 1000)));
	}

	@Test
	public void anyDecreaseMeansTheReadingsCantBeCompared()
	{
		// Another account, or a reading from before the stats synced: never a gain, even for the skill that went up.
		assertNull(SkillXp.gains(reading("SLAYER", 1000, "HITPOINTS", 5000),
			reading("SLAYER", 900_000, "HITPOINTS", 4000)));
	}

	@Test
	public void aMissingReadingCantBeCompared()
	{
		assertNull(SkillXp.gains(null, reading("SLAYER", 1)));
		assertNull(SkillXp.gains(reading("SLAYER", 1), null));
	}

	@Test
	public void aSkillMissingFromEitherReadingIsLeftOut()
	{
		assertEquals(xp("SLAYER", 5), SkillXp.gains(reading("SLAYER", 10, "PRAYER", 1),
			reading("SLAYER", 15, "MAGIC", 99)));
	}

	@Test
	public void addMergesAndSaturates()
	{
		Map<String, Long> into = xp("SLAYER", 100);
		SkillXp.add(into, xp("SLAYER", 50, "MAGIC", 10));
		SkillXp.add(into, null);
		assertEquals(xp("SLAYER", 150, "MAGIC", 10), into);
		SkillXp.add(into, xp("MAGIC", Long.MAX_VALUE));
		assertEquals(Long.valueOf(Long.MAX_VALUE), into.get("MAGIC"));
	}

	@Test
	public void sanitizeKeepsOnlyPositiveEntries()
	{
		Map<String, Long> raw = new HashMap<>();
		raw.put("SLAYER", 10L);
		raw.put("MAGIC", 0L);
		raw.put("PRAYER", -5L);
		raw.put("RANGED", null);
		raw.put(null, 7L);
		assertEquals(xp("SLAYER", 10), SkillXp.sanitize(raw));
		assertTrue(SkillXp.sanitize(null).isEmpty());
	}

	@Test
	public void totalAddsEverySkill()
	{
		assertEquals(360, SkillXp.total(xp("SLAYER", 250, "HITPOINTS", 100, "PRAYER", 10)));
		assertEquals(0, SkillXp.total(null));
	}

	@Test
	public void perHourNeedsAMinuteOfActiveTime()
	{
		assertNull(SkillXp.perHour(1000, TaskTimeEstimate.MIN_ACTIVE_MILLIS - 1));
		assertEquals(Long.valueOf(60_000), SkillXp.perHour(1000, TaskTimeEstimate.MIN_ACTIVE_MILLIS));
		assertEquals(Long.valueOf(40_000), SkillXp.perHour(20_000, 30 * 60_000));
	}

	@Test
	public void skillNames()
	{
		assertEquals("Hitpoints", SkillXp.skillName("HITPOINTS"));
		assertEquals("Slayer", SkillXp.skillName("SLAYER"));
		assertEquals("Unknown skill", SkillXp.skillName(null));
	}

	@Test
	public void totalTextShowsTheRateOnceThereIsOne()
	{
		Map<String, Long> gained = xp("SLAYER", 15_000, "HITPOINTS", 5_000);
		assertEquals("XP: 20K", SkillXp.totalText(gained, 30_000));
		assertEquals("XP: 20K (40K/h)", SkillXp.totalText(gained, 30 * 60_000));
		assertEquals("XP: 0 (0/h)", SkillXp.totalText(xp(), 30 * 60_000));
	}

	@Test
	public void unrecordedXpShowsADash()
	{
		assertEquals("XP: -", SkillXp.totalText(null, 60_000));
		assertTrue(SkillXp.rows(null, 60_000).isEmpty());
		assertFalse(SkillXp.tooltip(null, 60_000).contains("<html>"));
	}

	@Test
	public void rowsAreHighestFirstThenByName()
	{
		List<SkillXp.Row> rows = SkillXp.rows(xp("PRAYER", 100, "SLAYER", 900, "MAGIC", 100), 60 * 60_000);
		assertEquals(Arrays.asList("Slayer", "Magic", "Prayer"),
			Arrays.asList(rows.get(0).getName(), rows.get(1).getName(), rows.get(2).getName()));
		assertEquals("900", rows.get(0).amountText());
		assertEquals(Long.valueOf(900), rows.get(0).getPerHour());
		assertEquals("<html>Slayer: 900 XP<br>900 XP per hour</html>", rows.get(0).tooltip());
		assertNull("no rate without enough active time", SkillXp.rows(xp("SLAYER", 1), 0).get(0).getPerHour());
	}

	@Test
	public void tooltipListsEverySkill()
	{
		assertEquals("<html>XP gained: 1,500<br>XP per hour: 1,500<br>Slayer: 1,000<br>Hitpoints: 500"
			+ "<br>Counted only while the session runs.</html>",
			SkillXp.tooltip(xp("SLAYER", 1000, "HITPOINTS", 500), 60 * 60_000));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.config.ConfigDescriptor;
import net.runelite.client.config.ConfigItemDescriptor;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigSectionDescriptor;
import org.junit.Test;

/**
 * The "Loot price" setting read through RuneLite's own config proxy handler (the one
 * {@link ConfigManager#getConfig(Class)} uses), so a value saved for the removed "Higher of the two" option is checked
 * against the client's real parsing rather than a stub.
 */
public class SlayerLedgerConfigTest
{
	/** A config proxy whose stored "Loot price" value is {@code saved} ({@code null} for unset). */
	private static SlayerLedgerConfig configWithLootPrice(String saved) throws Exception
	{
		// Only the stored string is stubbed; stringToObject (the enum parsing) is the client's own.
		ConfigManager manager = mock(ConfigManager.class, CALLS_REAL_METHODS);
		doReturn(saved).when(manager).getConfiguration(SlayerLedgerConfig.GROUP, SlayerLedgerConfig.LOOT_PRICE_MODE);

		// The handler class is package-private in the client.
		Constructor<?> ctor = Class.forName("net.runelite.client.config.ConfigInvocationHandler")
			.getDeclaredConstructor(ConfigManager.class);
		ctor.setAccessible(true);
		InvocationHandler handler = (InvocationHandler) ctor.newInstance(manager);
		return (SlayerLedgerConfig) Proxy.newProxyInstance(SlayerLedgerConfig.class.getClassLoader(),
			new Class<?>[]{SlayerLedgerConfig.class}, handler);
	}

	@Test
	public void savedModesAreRead() throws Exception
	{
		assertEquals(LootPriceMode.GE, configWithLootPrice("GE").lootPriceMode());
		assertEquals(LootPriceMode.HIGH_ALCH, configWithLootPrice("HIGH_ALCH").lootPriceMode());
		assertEquals("unset", LootPriceMode.GE, configWithLootPrice(null).lootPriceMode());
	}

	@Test
	public void defaults()
	{
		SlayerLedgerConfig defaults = new SlayerLedgerConfig()
		{
		};
		assertFalse(defaults.taskCompleteNotification());
		// The new-task chat preview is on by default.
		assertTrue(defaults.assignmentPreview());
		assertTrue(defaults.showTaskOverlay());
		assertTrue(defaults.overlayTask());
		assertTrue(defaults.overlayKills());
		assertTrue(defaults.overlayTimeLeft());
		assertTrue(defaults.overlayProfit());
		// Every panel section is shown by default.
		assertTrue(defaults.showWhatToBring());
		assertTrue(defaults.showTrends());
		assertTrue(defaults.showOverallTotals());
		assertTrue(defaults.showLuckMeter());
		assertTrue(defaults.showSkippedBlocked());
		// The task advisor is on, with Profit/h as its goal.
		assertTrue(defaults.taskAdvisor());
		assertEquals(TaskAdvisorGoal.PROFIT, defaults.taskAdvisorGoal());
		// Nothing is waiting to forget the skipped places.
		assertFalse(defaults.resetLocationSkips());
	}

	@Test
	public void taskAdvisorGoalsHaveTheirLabelAndMetric()
	{
		assertEquals("Profit/h", TaskAdvisorGoal.PROFIT.toString());
		assertEquals("Slayer XP/h", TaskAdvisorGoal.SLAYER_XP.toString());
		assertEquals("Points/h", TaskAdvisorGoal.POINTS.toString());
		assertEquals(TaskRanking.Metric.PROFIT, TaskAdvisorGoal.PROFIT.metric());
		assertEquals(TaskRanking.Metric.XP, TaskAdvisorGoal.SLAYER_XP.metric());
		assertEquals(TaskRanking.Metric.POINTS, TaskAdvisorGoal.POINTS.metric());
		// Profit per kill is a Trends metric only: the advisor keeps its three hourly goals.
		assertEquals(3, TaskAdvisorGoal.values().length);
		for (TaskAdvisorGoal goal : TaskAdvisorGoal.values())
		{
			assertFalse(goal.name(), goal.metric().isPerKill());
		}
	}

	@Test
	public void everySettingIsPlacedInASectionInADeliberateOrder() throws Exception
	{
		// The client's own descriptor (sorted by position, then name), as the config panel lays it out.
		ConfigDescriptor descriptor = mock(ConfigManager.class, CALLS_REAL_METHODS)
			.getConfigDescriptor(configWithLootPrice(null));

		// Core settings first, the niche charged-weapon setting last.
		List<String> sections = new ArrayList<>();
		List<String> sectionNames = new ArrayList<>();
		for (ConfigSectionDescriptor section : descriptor.getSections())
		{
			sections.add(section.getKey());
			sectionNames.add(section.getSection().name());
		}
		assertEquals(Arrays.asList(SlayerLedgerConfig.trackingSection, SlayerLedgerConfig.valuesSection,
			SlayerLedgerConfig.chatSection, SlayerLedgerConfig.taskOverlaySection, SlayerLedgerConfig.taskAdvisorSection,
			SlayerLedgerConfig.panelSectionsSection, SlayerLedgerConfig.chargedWeaponsSection), sections);
		assertEquals(Arrays.asList("Tracking", "Values", "Chat", "Task overlay", "Task advisor", "Panel sections",
			"Charged weapons"), sectionNames);

		// Every item has a position (no accidental by-name order) and a section; keys in config panel order.
		Map<String, List<String>> bySection = new LinkedHashMap<>();
		for (ConfigItemDescriptor item : descriptor.getItems())
		{
			String key = item.getItem().keyName();
			// -1 is ConfigItem's default: no position given.
			assertNotEquals("no position: " + key, -1, item.getItem().position());
			assertNotEquals("no section: " + key, "", item.getItem().section());
			bySection.computeIfAbsent(item.getItem().section(), k -> new ArrayList<>()).add(key);
		}
		assertEquals(Arrays.asList("confirmIncomplete", "bonecrusherHandling", SlayerLedgerConfig.IGNORED_LOOT,
			SlayerLedgerConfig.RESET_LOCATION_SKIPS), bySection.get(SlayerLedgerConfig.trackingSection));
		assertEquals(Arrays.asList(SlayerLedgerConfig.LOOT_PRICE_MODE, SlayerLedgerConfig.NOTABLE_DROP_THRESHOLD,
			SlayerLedgerConfig.HIDE_GROUND_ITEMS_HIDDEN), bySection.get(SlayerLedgerConfig.valuesSection));
		assertEquals(Arrays.asList("taskCompleteNotification", "assignmentPreview"),
			bySection.get(SlayerLedgerConfig.chatSection));
		// The master toggle first, then the rows.
		assertEquals(Arrays.asList("showTaskOverlay", "overlayTask", "overlayKills", "overlayTimeLeft", "overlayProfit"),
			bySection.get(SlayerLedgerConfig.taskOverlaySection));
		// The on/off toggle first, then the goal.
		assertEquals(Arrays.asList(SlayerLedgerConfig.TASK_ADVISOR, SlayerLedgerConfig.TASK_ADVISOR_GOAL),
			bySection.get(SlayerLedgerConfig.taskAdvisorSection));
		// In sidebar order.
		assertEquals(Arrays.asList(SlayerLedgerConfig.SHOW_WHAT_TO_BRING, SlayerLedgerConfig.SHOW_TRENDS,
			SlayerLedgerConfig.SHOW_OVERALL_TOTALS, SlayerLedgerConfig.SHOW_LUCK_METER,
			SlayerLedgerConfig.SHOW_SKIPPED_BLOCKED), bySection.get(SlayerLedgerConfig.panelSectionsSection));
		assertEquals(Collections.singletonList(SlayerLedgerConfig.VORKATHS_HEAD_UPGRADE),
			bySection.get(SlayerLedgerConfig.chargedWeaponsSection));
		assertEquals("no other section", 7, bySection.size());
	}

	@Test
	public void panelSectionSettingsAreNamedAsTheSidebarHeadings() throws Exception
	{
		ConfigDescriptor descriptor = mock(ConfigManager.class, CALLS_REAL_METHODS)
			.getConfigDescriptor(configWithLootPrice(null));
		List<String> names = new ArrayList<>();
		for (ConfigItemDescriptor item : descriptor.getItems())
		{
			if (SlayerLedgerConfig.panelSectionsSection.equals(item.getItem().section()))
			{
				names.add(item.getItem().name());
			}
		}
		assertEquals(Arrays.asList("What to bring", "Trends", "Overall totals", "Luck meter", "Skipped / blocked"),
			names);
	}

	@Test
	public void theRemovedHigherOptionReadsAsGe() throws Exception
	{
		// Saved by clients from before "Higher of the two" was removed (owner decision, 2026-10-25).
		assertEquals(LootPriceMode.GE, configWithLootPrice("HIGHER").lootPriceMode());
	}
}

