			new int[]{ItemID.SLAYER_BAG_OF_SALT, 49, ItemID.SLAYER_ICY_WATER, 30},
			new int[]{ItemID.SLAYER_BAG_OF_SALT, 47, ItemID.SLAYER_ICY_WATER, 29});
