package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

/**
 * Which ticks and dropped items the plugin leaves out of supply counting.
 */
public class SupplyExclusionsTest
{
	private static final int SHARK = 385;
	private static final int ARROW = 890;
	private static final int RUNE_POUCH = 12791;
	/** Not an excluded interface. */
	private static final int OTHER_INTERFACE = 149;

	private final SupplyExclusions exclusions = new SupplyExclusions();

	@Test
	public void nothingIsExcludedByDefault()
	{
		exclusions.beginTick(0, false);
		assertFalse(exclusions.isTickExcluded(0));
		assertFalse(exclusions.isTickExcluded(1_000));
		assertTrue(exclusions.droppedItems().isEmpty());
	}

	@Test
	public void excludedInterfacesAreRecognised()
	{
		for (int group : SupplyExclusions.excludedInterfaces())
		{
			assertTrue(SupplyExclusions.isExcludedInterface(group));
		}
		assertTrue(SupplyExclusions.isExcludedInterface(InterfaceID.BANKMAIN));
		assertTrue(SupplyExclusions.isExcludedInterface(InterfaceID.DEATH_COFFER));
		assertFalse(SupplyExclusions.isExcludedInterface(OTHER_INTERFACE));
		assertEquals(11, SupplyExclusions.excludedInterfaces().length);
	}

	@Test
	public void openInterfaceExcludesItsTickAndTwoMore()
	{
		exclusions.beginTick(100, true);
		assertTrue("+0", exclusions.isTickExcluded(100));
		exclusions.beginTick(101, false);
		assertTrue("+1", exclusions.isTickExcluded(101));
		exclusions.beginTick(102, false);
		assertTrue("+2", exclusions.isTickExcluded(102));
		exclusions.beginTick(103, false);
		assertFalse("+3", exclusions.isTickExcluded(103));
	}

	@Test
	public void interfaceStillOpenKeepsExtendingTheWindow()
	{
		for (int tick = 100; tick <= 110; tick++)
		{
			exclusions.beginTick(tick, true);
			assertTrue(exclusions.isTickExcluded(tick));
		}
		exclusions.beginTick(112, false);
		assertTrue("2 ticks after it was last open", exclusions.isTickExcluded(112));
		exclusions.beginTick(113, false);
		assertFalse(exclusions.isTickExcluded(113));
	}

	@Test
	public void widgetLoadedAndClosedMarkTheTick()
	{
		// Opened and closed between two ticks: never seen open by beginTick.
		exclusions.interfaceChanged(InterfaceID.BANKMAIN, 200);
		exclusions.beginTick(200, false);
		assertTrue(exclusions.isTickExcluded(200));
		assertTrue(exclusions.isTickExcluded(202));
		assertFalse(exclusions.isTickExcluded(203));

		exclusions.interfaceChanged(InterfaceID.SHOPMAIN, 300);
		assertTrue(exclusions.isTickExcluded(302));
		assertFalse(exclusions.isTickExcluded(303));
	}

	@Test
	public void otherInterfacesDoNotExclude()
	{
		exclusions.interfaceChanged(OTHER_INTERFACE, 200);
		assertFalse(exclusions.isTickExcluded(200));
	}

	@Test
	public void dropWindowCoversTwoTicksThenIsPruned()
	{
		exclusions.dropClicked(SHARK, false, 50);
		exclusions.beginTick(50, false);
		assertEquals("+0", Collections.singleton(SHARK), exclusions.droppedItems());
		assertFalse("a drop alone does not exclude the tick", exclusions.isTickExcluded(50));
		exclusions.beginTick(52, false);
		assertEquals("+2", Collections.singleton(SHARK), exclusions.droppedItems());
		exclusions.beginTick(53, false);
		assertTrue("+3: pruned", exclusions.droppedItems().isEmpty());
	}

	@Test
	public void dropsArePrunedPerItem()
	{
		exclusions.dropClicked(SHARK, false, 50);
		exclusions.dropClicked(ARROW, false, 52);
		exclusions.beginTick(53, false);
		assertEquals(Collections.singleton(ARROW), exclusions.droppedItems());
		// A repeated drop moves the item's window forward.
		exclusions.dropClicked(ARROW, false, 54);
		exclusions.beginTick(56, false);
		assertEquals(Collections.singleton(ARROW), exclusions.droppedItems());
		exclusions.beginTick(57, false);
		assertTrue(exclusions.droppedItems().isEmpty());
	}

	@Test
	public void dropFromALaterTickIsPruned()
	{
		// The tick count went backwards (it is re-sent after a login or hop).
		exclusions.dropClicked(SHARK, false, 500);
		exclusions.beginTick(10, false);
		assertTrue(exclusions.droppedItems().isEmpty());
	}

	@Test
	public void droppedItemsIsACopy()
	{
		exclusions.dropClicked(SHARK, false, 50);
		exclusions.beginTick(50, false);
		exclusions.droppedItems().clear();
		assertEquals(Collections.singleton(SHARK), exclusions.droppedItems());
	}

	@Test
	public void runePouchDropExcludesTheWholeTick()
	{
		exclusions.dropClicked(RUNE_POUCH, true, 70);
		exclusions.beginTick(70, false);
		assertTrue(exclusions.isTickExcluded(70));
		assertTrue(exclusions.droppedItems().contains(RUNE_POUCH));
		assertTrue("+2", exclusions.isTickExcluded(72));
		assertFalse("+3", exclusions.isTickExcluded(73));
	}

	@Test
	public void deathExcludesTenTicks()
	{
		exclusions.playerDied(1_000);
		assertTrue("+0", exclusions.isTickExcluded(1_000));
		assertTrue("+3", exclusions.isTickExcluded(1_003));
		assertTrue("+10", exclusions.isTickExcluded(1_010));
		assertFalse("+11", exclusions.isTickExcluded(1_011));
	}

	@Test
	public void resetForgetsEverything()
	{
		exclusions.beginTick(10, true);
		exclusions.dropClicked(SHARK, false, 10);
		exclusions.playerDied(10);
		exclusions.reset();
		assertFalse(exclusions.isTickExcluded(10));
		assertTrue(exclusions.droppedItems().isEmpty());
		// After a reset the tick count may restart at a low value; nothing is excluded.
		assertFalse(exclusions.isTickExcluded(0));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link SupplyReader}: how an item definition is classified for supply counting, and which containers are read.
 * The client and item manager are plain Mockito mocks; the counting rules themselves are {@link SupplyTrackerTest}'s.
 */
public class SupplyReaderTest
{
	private static final String[] WIELD = {null, "Wield", null, null, "Drop"};
	private static final String[] NONE = {null, null, null, null, "Drop"};
	private static final int FIRE_RUNE = 554;
	private static final int ODD_POUCH_RUNE = 30000;
	private static final int BOLTS = 9144;
	private static final int DARTS = 811;
	private static final int SWORD = 1277;

	private Client client;
	private ItemManager itemManager;
	private SupplyReader reader;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		itemManager = mock(ItemManager.class);
		reader = new SupplyReader(client, itemManager);
	}

	private ItemComposition item(int id, String name, String[] actions, boolean stackable)
	{
		final ItemComposition comp = mock(ItemComposition.class);
		when(comp.getName()).thenReturn(name);
		when(comp.getNote()).thenReturn(-1);
		when(comp.getPlaceholderTemplateId()).thenReturn(-1);
		when(comp.getInventoryActions()).thenReturn(actions);
		when(comp.isStackable()).thenReturn(stackable);
		when(itemManager.getItemComposition(id)).thenReturn(comp);
		return comp;
	}

	private void stats(int id, EquipmentInventorySlot slot)
	{
		when(itemManager.getItemStats(id)).thenReturn(new ItemStats(true, 0, 0,
			ItemEquipmentStats.builder().slot(slot.getSlotIdx()).build()));
	}

	private EnumComposition runeEnum(int... runeIds)
	{
		final EnumComposition runes = mock(EnumComposition.class);
		when(runes.getIntVals()).thenReturn(runeIds);
		when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(runes);
		return runes;
	}

	private static SupplyTracker.Category category(SupplyTracker.ItemInfo info)
	{
		return info.getCategory();
	}

	@Test
	public void notedItemsAndPlaceholdersAreNeverSupplies()
	{
		when(item(386, "Shark", NONE, false).getNote()).thenReturn(799);
		when(item(14401, "Shark", NONE, false).getPlaceholderTemplateId()).thenReturn(385);

		assertSame(SupplyTracker.ItemInfo.OTHER, reader.classifyItem(386));
		assertSame(SupplyTracker.ItemInfo.OTHER, reader.classifyItem(14401));
	}

	@Test
	public void runesComeFromThePouchEnumOrTheName()
	{
		runeEnum(0, ODD_POUCH_RUNE);
		item(ODD_POUCH_RUNE, "Odd thing", NONE, true);
		item(FIRE_RUNE, "Fire rune", NONE, true);
		item(SWORD, "Bronze sword", NONE, false);

		assertEquals(SupplyTracker.Category.RUNE, category(reader.classifyItem(ODD_POUCH_RUNE)));
		assertEquals(SupplyTracker.Category.RUNE, category(reader.classifyItem(FIRE_RUNE)));
		assertEquals(SupplyTracker.Category.OTHER, category(reader.classifyItem(SWORD)));
	}

	@Test
	public void runePouchIdsAreCachedOnceLoadedAndReloadedAfterReset()
	{
		runeEnum(FIRE_RUNE);
		item(FIRE_RUNE, "Fire rune", NONE, true);

		reader.classifyItem(FIRE_RUNE);
		reader.classifyItem(FIRE_RUNE);
		verify(client, times(1)).getEnum(EnumID.RUNEPOUCH_RUNE);

		reader.reset();
		reader.classifyItem(FIRE_RUNE);
		verify(client, times(2)).getEnum(EnumID.RUNEPOUCH_RUNE);
	}

	@Test
	public void anUnavailablePouchEnumIsRetried()
	{
		item(FIRE_RUNE, "Fire rune", NONE, true);

		reader.classifyItem(FIRE_RUNE);
		reader.classifyItem(FIRE_RUNE);
		verify(client, times(2)).getEnum(EnumID.RUNEPOUCH_RUNE);
	}

	@Test
	public void ammoIsTheAmmoSlotOrAStackableWeapon()
	{
		item(BOLTS, "Steel bolts", WIELD, true);
		stats(BOLTS, EquipmentInventorySlot.AMMO);
		item(DARTS, "Rune dart", WIELD, true);
		stats(DARTS, EquipmentInventorySlot.WEAPON);
		item(SWORD, "Bronze sword", WIELD, false);
		stats(SWORD, EquipmentInventorySlot.WEAPON);

		assertEquals(SupplyTracker.Category.AMMO, category(reader.classifyItem(BOLTS)));
		assertEquals(SupplyTracker.Category.AMMO, category(reader.classifyItem(DARTS)));
		assertEquals(SupplyTracker.Category.OTHER, category(reader.classifyItem(SWORD)));
	}

	@Test
	public void aWieldableItemWithoutStatsYetIsLeftForLater()
	{
		item(DARTS, "Rune dart", WIELD, true);

		assertNull(reader.classifyItem(DARTS));
	}

	@Test
	public void cannonballsAndIdTableItemsNeedNoItemStats()
	{
		item(SupplyTracker.CANNONBALL, "Cannonball", NONE, true);
		item(ItemID.PLAIN_PIZZA, "Plain pizza", new String[]{"Eat", null, null, null, "Drop"}, false);

		assertEquals(SupplyTracker.Category.CANNONBALL, category(reader.classifyItem(SupplyTracker.CANNONBALL)));
		assertEquals(SupplyTracker.Category.FOOD, category(reader.classifyItem(ItemID.PLAIN_PIZZA)));
		verify(itemManager, never()).getItemStats(ItemID.PLAIN_PIZZA);
	}

	@Test
	public void isEquipableLooksForWieldOrWear()
	{
		assertTrue(SupplyReader.isEquipable(WIELD));
		assertTrue(SupplyReader.isEquipable(new String[]{null, "Wear"}));
		assertFalse(SupplyReader.isEquipable(NONE));
		assertFalse(SupplyReader.isEquipable(null));
	}

	@Test
	public void runePouchesAreTheRegularAndDivineOnes()
	{
		assertTrue(SupplyReader.isRunePouch(ItemID.BH_RUNE_POUCH));
		assertTrue(SupplyReader.isRunePouch(ItemID.BH_RUNE_POUCH_TROUVER));
		assertTrue(SupplyReader.isRunePouch(ItemID.DIVINE_RUNE_POUCH));
		assertTrue(SupplyReader.isRunePouch(ItemID.DIVINE_RUNE_POUCH_TROUVER));
		assertFalse(SupplyReader.isRunePouch(FIRE_RUNE));
	}

	@Test
	public void noObservationWhileTheInventoryIsNotLoaded()
	{
		assertNull(reader.readSupplyObservation());
	}

	@Test
	public void theObservationReadsInventoryWornSlotsQuiverRunePouchAndCannon()
	{
		final ItemContainer inventory = mock(ItemContainer.class);
		when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.BH_RUNE_POUCH, 1), new Item(SWORD, 1)});
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		final ItemContainer worn = mock(ItemContainer.class);
		when(worn.getItem(EquipmentInventorySlot.AMMO.getSlotIdx())).thenReturn(new Item(BOLTS, 100));
		// Not a supply slot: never read.
		when(worn.getItem(EquipmentInventorySlot.HEAD.getSlotIdx())).thenReturn(new Item(1155, 1));
		when(client.getItemContainer(InventoryID.WORN)).thenReturn(worn);
		when(client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO)).thenReturn(DARTS);
		when(client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT)).thenReturn(30);
		when(client.getVarpValue(VarPlayerID.ROCKTHROWER)).thenReturn(25);
		final EnumComposition runes = runeEnum(FIRE_RUNE);
		when(runes.getIntValue(3)).thenReturn(FIRE_RUNE);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_2)).thenReturn(3);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_2)).thenReturn(500);

		final SupplyTracker.Observation observation = reader.readSupplyObservation();

		final Map<Integer, Long> expected = new HashMap<>();
		expected.put(ItemID.BH_RUNE_POUCH, 1L);
		expected.put(SWORD, 1L);
		expected.put(BOLTS, 100L);
		expected.put(DARTS, 30L);
		expected.put(FIRE_RUNE, 500L);
		assertEquals(expected, observation.getItems());
		assertEquals(25, observation.getCannonBalls());
	}

	@Test
	public void thePouchIsOnlyReadWhileOneIsCarried()
	{
		final ItemContainer inventory = mock(ItemContainer.class);
		when(inventory.getItems()).thenReturn(new Item[]{new Item(SWORD, 1)});
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		when(client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO)).thenReturn(-1);
		runeEnum(FIRE_RUNE);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1)).thenReturn(3);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1)).thenReturn(500);

		final SupplyTracker.Observation observation = reader.readSupplyObservation();

		assertEquals(1, observation.getItems().size());
		verify(client, never()).getEnum(anyInt());
	}

	@Test
	public void wornItemIdIsNoItemForAnEmptySlotOrNoContainer()
	{
		final ItemContainer worn = mock(ItemContainer.class);
		when(worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx())).thenReturn(new Item(DARTS, 10));

		assertEquals(DARTS, SupplyReader.wornItemId(worn, EquipmentInventorySlot.WEAPON));
		assertEquals(ChargedWeaponUsage.NO_ITEM, SupplyReader.wornItemId(worn, EquipmentInventorySlot.CAPE));
		assertEquals(ChargedWeaponUsage.NO_ITEM, SupplyReader.wornItemId(null, EquipmentInventorySlot.CAPE));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.Map;
import org.junit.Test;

public class SupplyRecommendationTest
{
	@Test
	public void scalesPooledSupplyUseAndBankTripsPerKill()
	{
		LedgerRecord first = record(10);
		first.setSupplies(map(100, 12, 101, 30));
		first.setSupplyDoses(Collections.singletonMap(100, 4));
		first.setBankTrips(1);
		LedgerRecord second = record(20);
		second.setSupplies(map(100, 40, 101, 60));
		second.setSupplyDoses(Collections.singletonMap(100, 4));
		second.setBankTrips(2);

		TaskStatistics stats = statistics(Arrays.asList(first, second));
		SupplyRecommendation.Estimate estimate = SupplyRecommendation.forTask(stats, 10);

		// 52 doses over 30 kills, times 10: 17.3, rounded up.
		assertEquals(Long.valueOf(18), estimate.getSupplies().get(100));
		assertEquals(Long.valueOf(30), estimate.getSupplies().get(101));
		assertEquals(2, estimate.getSupplySampleCount());
		assertEquals(30, estimate.getSupplyKills());
		// 3 trips over 30 kills, times 10.
		assertEquals(Long.valueOf(1), estimate.getBankTrips());
		assertEquals(2, estimate.getBankTripSampleCount());
		assertEquals(30, estimate.getBankTripKills());
		assertEquals(10, estimate.getKills());
	}

	@Test
	public void wholeNumberResultsAreNotRoundedUpByFloatingPointError()
	{
		// 5 / 147 * 147 and 3 / 187 * 187 come out just above a whole number in doubles.
		assertEquals(Long.valueOf(5), single(5, 147, 147));
		assertEquals(Long.valueOf(3), single(3, 187, 187));
		assertEquals(Long.valueOf(15), single(3, 17, 85));
		// 10 over 3 kills, times 2: 6.67, rounded up.
		assertEquals(Long.valueOf(7), single(10, 3, 2));
		assertEquals(Long.valueOf(1), single(1, 1_000, 1));
	}

	@Test
	public void scaleUpIsExactAndSaturates()
	{
		assertEquals(5, SupplyRecommendation.scaleUp(5, 147, 147));
		assertEquals(1, SupplyRecommendation.scaleUp(1, 1, 3));
		assertEquals(0, SupplyRecommendation.scaleUp(0, 10, 3));
		assertEquals(Long.MAX_VALUE, SupplyRecommendation.scaleUp(Long.MAX_VALUE, 2, 1));
		assertEquals(Long.MAX_VALUE / 2 + 1, SupplyRecommendation.scaleUp(Long.MAX_VALUE, 1, 2));
	}

	@Test
	public void bankTripsUseOnlyTheKillsOfRecordsWithACount()
	{
		LedgerRecord counted = record(10);
		counted.setBankTrips(1);
		LedgerRecord unknown = record(30);
		unknown.setBankTrips(null);
		LedgerRecord negative = record(30);
		negative.setBankTrips(-1);
		SupplyRecommendation.Estimate estimate = SupplyRecommendation.forTask(
			statistics(Arrays.asList(counted, unknown, negative)), 25);

		// 1 trip over 10 kills, times 25: 2.5, rounded up.
		assertEquals(Long.valueOf(3), estimate.getBankTrips());
		assertEquals(1, estimate.getBankTripSampleCount());
		assertEquals(10, estimate.getBankTripKills());
	}

	@Test
	public void excludesPartialRecordsAndKeepsUnknownMetricsUnknown()
	{
		LedgerRecord partial = record(10);
		partial.setPartial(true);
		partial.setSupplies(map(100, 1_000));
		partial.setBankTrips(100);

		LedgerRecord legacy = record(10);
		legacy.setSupplies(null);
		legacy.setBankTrips(null);
		TaskStatistics stats = statistics(Arrays.asList(partial, legacy));

		assertEquals(1, stats.getSampleCount());
		assertEquals(0, stats.getSupplySampleCount());
		assertNull(SupplyRecommendation.forTask(stats, 10));
		assertNull(SupplyRecommendation.forTask(statistics(Collections.emptyList()), 10));
	}

	@Test
	public void countsKnownNoUseAsNoSuppliesAndAllowsBankOnlyEstimates()
	{
		LedgerRecord noSupplies = record(10);
		noSupplies.setLootGeValue(0L);
		noSupplies.setSupplies(Collections.emptyMap());
		noSupplies.setBankTrips(0);
		SupplyRecommendation.Estimate none = SupplyRecommendation.forTask(statistics(Collections.singletonList(noSupplies)),
			10);
		assertEquals(1, none.getSupplySampleCount());
		assertTrue(none.getSupplies().isEmpty());
		assertEquals(Long.valueOf(0), none.getBankTrips());

		LedgerRecord bankOnly = record(10);
		bankOnly.setBankTrips(2);
		SupplyRecommendation.Estimate banks = SupplyRecommendation.forTask(statistics(Collections.singletonList(bankOnly)),
			10);
		assertEquals(0, banks.getSupplySampleCount());
		assertTrue(banks.getSupplies().isEmpty());
		assertEquals(Long.valueOf(2), banks.getBankTrips());
	}

	@Test
	public void supplyPricesAreTodaysPrices()
	{
		LedgerRecord older = record(10);
		older.setEndedAt(1_000L);
		older.setSupplies(map(100, 5, 101, 5));
		older.setUnitGePrices(map(100, 10, 101, 20));
		LedgerRecord newer = record(10);
		newer.setEndedAt(2_000L);
		newer.setSupplies(map(100, 5));
		newer.setUnitGePrices(map(100, 30));

		// The prices saved with the tasks are not used.
		TaskStatistics none = statistics(Arrays.asList(newer, older));
		assertTrue(none.getSupplyUnitGePrices().isEmpty());

		TaskStatistics today = TaskStatistics.forTask(Arrays.asList(newer, older), 42, "Abyssal demons",
			LootPriceMode.GE, map(100, 99));
		assertEquals(Long.valueOf(99), today.getSupplyUnitGePrices().get(100));
		assertNull("no price today means none", today.getSupplyUnitGePrices().get(101));
	}

	/** The suggestion for {@code kills} after one task of {@code sampleKills} kills that used {@code used} of an item. */
	private static Long single(int used, int sampleKills, int kills)
	{
		LedgerRecord record = record(sampleKills);
		record.setSupplies(map(100, used));
		return SupplyRecommendation.forTask(statistics(Collections.singletonList(record)), kills).getSupplies().get(100);
	}

	private static TaskStatistics statistics(Iterable<LedgerRecord> records)
	{
		java.util.List<LedgerRecord> list = new java.util.ArrayList<>();
		for (LedgerRecord record : records)
		{
			list.add(record);
		}
		return TaskStatistics.forTask(list, 42, "Abyssal demons", LootPriceMode.GE, Collections.emptyMap());
	}

	private static LedgerRecord record(int kills)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(42);
		record.setMonster("Abyssal demons");
		record.setKills(kills);
		record.setActiveMillis(kills * 1_000L);
		record.setCompleted(true);
		return record;
	}

	private static Map<Integer, Long> map(int... values)
	{
		Map<Integer, Long> result = new java.util.HashMap<>();
		for (int i = 0; i < values.length; i += 2)
		{
			result.put(values[i], (long) values[i + 1]);
		}
		return result;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * The pure per-tick supplies diff: categories, potion doses, container moves netting to zero, and exclusions.
 */
public class SupplyTrackerTest
{
	static final int SHARK = 385;
	static final int JUG_OF_WINE = 1993;
	static final int PRAYER_4 = 2434;
	static final int PRAYER_3 = 139;
	static final int PRAYER_2 = 141;
	static final int PRAYER_1 = 143;
	static final int SUPER_COMBAT_3 = 12697;
	static final int SUPER_COMBAT_2 = 12699;
	static final int VIAL = 229;
	static final int NATURE_RUNE = 561;
	static final int DEATH_RUNE = 560;
	static final int RUNE_POUCH = 12791;
	static final int ADAMANT_ARROW = 890;
	static final int BONES = 526;
	static final int GLORY_4 = 1712;

	private static final String[] EAT = {"Eat", null, null, null, "Drop"};
	private static final String[] DRINK = {"Drink", null, null, "Empty", "Drop"};
	private static final String[] NONE = {null, null, null, null, "Drop"};

	/** Test item definitions, classified with the production rules. */
	static final SupplyTracker.Classifier CLASSIFIER = id ->
	{
		switch (id)
		{
			case SHARK:
				return SupplyTracker.classify("Shark", EAT, false, false, false);
			case JUG_OF_WINE:
				return SupplyTracker.classify("Jug of wine", DRINK, false, false, false);
			case PRAYER_4:
				return SupplyTracker.classify("Prayer potion(4)", DRINK, false, false, false);
			case PRAYER_3:
				return SupplyTracker.classify("Prayer potion(3)", DRINK, false, false, false);
			case PRAYER_2:
				return SupplyTracker.classify("Prayer potion(2)", DRINK, false, false, false);
			case PRAYER_1:
				return SupplyTracker.classify("Prayer potion(1)", DRINK, false, false, false);
			case SUPER_COMBAT_3:
				return SupplyTracker.classify("Super combat potion(3)", DRINK, false, false, false);
			case SUPER_COMBAT_2:
				return SupplyTracker.classify("Super combat potion(2)", DRINK, false, false, false);
			case NATURE_RUNE:
				return SupplyTracker.classify("Nature rune", NONE, true, false, false);
			case DEATH_RUNE:
				return SupplyTracker.classify("Death rune", NONE, true, false, false);
			case ADAMANT_ARROW:
				return SupplyTracker.classify("Adamant arrow", NONE, false, true, false);
			case SupplyTracker.CANNONBALL:
				return SupplyTracker.classify("Cannonball", NONE, false, false, true);
			case SupplyTracker.GRANITE_CANNONBALL:
				return SupplyTracker.classify("Granite cannonball", NONE, false, false, true);
			case GLORY_4:
				return SupplyTracker.classify("Amulet of glory(4)", new String[]{null, null, "Rub", null, "Drop"}, false, false, false);
			default:
				// Vials, bones, the rune pouch and anything else: not a supply.
				return SupplyTracker.classify("Other", NONE, false, false, false);
		}
	};

	private SupplyTracker supplies;

	@Before
	public void setUp()
	{
		supplies = new SupplyTracker(CLASSIFIER);
	}

	static SupplyTracker.Observation obs(int... idQty)
	{
		SupplyTracker.Observation o = new SupplyTracker.Observation();
		for (int i = 0; i < idQty.length; i += 2)
		{
			o.add(idQty[i], idQty[i + 1]);
		}
		return o;
	}

	private SupplyTracker.Usage running(SupplyTracker.Observation o)
	{
		return supplies.update(o, true, false, Collections.emptySet());
	}

	private static Set<Integer> ids(int... ids)
	{
		Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return set;
	}

	// ---- Classification ----

	@Test
	public void classifiesByNameActionsAndFlags()
	{
		SupplyTracker.ItemInfo prayer = CLASSIFIER.classify(PRAYER_3);
		assertEquals(SupplyTracker.Category.POTION, prayer.getCategory());
		assertEquals("Prayer potion", prayer.getFamily());
		assertEquals(3, prayer.getDoses());
		assertEquals(SupplyTracker.Category.FOOD, CLASSIFIER.classify(SHARK).getCategory());
		assertEquals("a drink without doses is food", SupplyTracker.Category.FOOD, CLASSIFIER.classify(JUG_OF_WINE).getCategory());
		assertEquals("charged jewellery is not a potion", SupplyTracker.Category.OTHER, CLASSIFIER.classify(GLORY_4).getCategory());
		assertEquals(SupplyTracker.Category.OTHER, SupplyTracker.classify("Prayer potion(4)", null, false, false, false).getCategory());
		assertEquals(SupplyTracker.Category.RUNE, CLASSIFIER.classify(NATURE_RUNE).getCategory());
		assertEquals(SupplyTracker.Category.AMMO, CLASSIFIER.classify(ADAMANT_ARROW).getCategory());
		assertEquals(SupplyTracker.Category.CANNONBALL, CLASSIFIER.classify(SupplyTracker.CANNONBALL).getCategory());
		assertEquals(SupplyTracker.Category.OTHER, CLASSIFIER.classify(BONES).getCategory());
		assertEquals("flags take precedence", SupplyTracker.Category.CANNONBALL,
			SupplyTracker.classify("Odd(4)", DRINK, true, true, true).getCategory());
	}

