import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class TaskCompleteMessageTest
{
	@Test
	public void formatsSummaryUsingSelectedLootPriceMode()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(172);
		record.setActiveMillis(6_012_000);
		record.setLootGeValue(2_500_000L);
		record.setLootHaValue(1_500_000L);
		record.setSuppliesGeValue(400_000L);
		record.setSuperiorsSpawned(3);

		assertEquals("Slayer task complete: 172 Wyrms · 1:40:12 · +2.1M · 3 superiors",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
		assertEquals("Slayer task complete: 172 Wyrms · 1:40:12 · +1.1M · 3 superiors",
			TaskCompleteMessage.format(record, LootPriceMode.HIGH_ALCH));
	}

	@Test
	public void omitsUnavailableProfitAndSuperiorCount()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(172);
		record.setActiveMillis(6_012_000);

		assertEquals("Slayer task complete: 172 Wyrms · 1:40:12", TaskCompleteMessage.format(record, LootPriceMode.GE));
	}

	@Test
	public void omitsZeroSuperiorsAndShowsApproximateProfit()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(172);
		record.setActiveMillis(6_012_000);
		record.setLootGeValue(100L);
		record.setSuppliesGeValue(0L);
		record.setLootUnpricedItems(1);
		record.setSuperiorsSpawned(0);

		assertEquals("Slayer task complete: 172 Wyrms · 1:40:12 · ~+100",
			TaskCompleteMessage.format(record, LootPriceMode.GE));

		record.setSuperiorsSpawned(1);
		assertEquals("Slayer task complete: 172 Wyrms · 1:40:12 · ~+100 · 1 superior",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
	}

	@Test
	public void putsTheSignAfterTheApproximateMarkForLosses()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(172);
		record.setActiveMillis(6_012_000);
		record.setLootGeValue(100L);
		record.setSuppliesGeValue(600L);
		record.setLootUnpricedItems(1);

		assertEquals("Slayer task complete: 172 Wyrms · 1:40:12 · ~-500",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
	}

	@Test
	public void doesNotFormatPartialRecords()
	{
		assertNull(TaskCompleteMessage.format(record(false), LootPriceMode.GE));
	}

	private static LedgerRecord record(boolean completed)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCompleted(completed);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link TaskContext} (master, area, points earned and streak) on its own and as the session carries it: taken with the
 * task, filled from later readings of the same task, rewards set on completion only, and through snapshots, restores,
 * records, JSON and the history tooltip.
 */
public class TaskContextTest
{
	private static final int TASK = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};
	private static final TaskContext KONAR_AT_COVE = TaskContext.assignment(SlayerMaster.KONAR, 12, "Kraken Cove");

	private final Gson gson = new Gson();
	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	private SessionTracker.ObserveResult observe(int remaining, TaskContext assignment, boolean completion)
	{
		return tracker.observe("Kraken", TASK, remaining, 100, assignment, completion);
	}

	// ---- TaskContext ----

	@Test
	public void assignmentKeepsOnlyRealValues()
	{
		assertSame(TaskContext.NONE, TaskContext.assignment(SlayerMaster.NONE, 0, "Ignored"));
		TaskContext noArea = TaskContext.assignment(6, 0, null);
		assertEquals(Integer.valueOf(6), noArea.getMaster());
		assertNull(noArea.getArea());
		assertNull(noArea.getLocation());
		TaskContext unnamed = TaskContext.assignment(SlayerMaster.KONAR, 12, "");
		assertEquals(Integer.valueOf(12), unnamed.getArea());
		assertNull(unnamed.getLocation());
		assertEquals(TaskType.KONAR, KONAR_AT_COVE.type(TASK));
	}

	@Test
	public void fillAssignmentOnlyAddsWhatIsMissing()
	{
		TaskContext unsynced = TaskContext.assignment(SlayerMaster.NONE, 12, null);
		TaskContext filled = unsynced.fillAssignment(KONAR_AT_COVE);
		assertEquals(KONAR_AT_COVE, filled);
		TaskContext other = TaskContext.assignment(6, 30, "Elsewhere");
		assertEquals("known parts are kept", KONAR_AT_COVE, KONAR_AT_COVE.fillAssignment(other));
		assertEquals("a name for another area is not taken", TaskContext.assignment(SlayerMaster.KONAR, 12, null),
			TaskContext.assignment(SlayerMaster.KONAR, 12, null).fillAssignment(other));
		assertEquals(KONAR_AT_COVE, KONAR_AT_COVE.fillAssignment(null));
	}

	// ---- Session ----

	@Test
	public void sessionTakesTheAssignmentWithTheTask()
	{
		observe(50, KONAR_AT_COVE, false);
		assertEquals(KONAR_AT_COVE, tracker.getCurrentContext());
		assertTrue(tracker.play(ACCOUNT));
		assertEquals(KONAR_AT_COVE, tracker.summary().getContext());
	}

	@Test
	public void laterReadingsOfTheSameTaskFillTheGaps()
	{
		observe(50, TaskContext.assignment(SlayerMaster.NONE, 0, null), false);
		assertTrue(tracker.play(ACCOUNT));
		assertNull(tracker.summary().getContext().getMaster());
		observe(49, KONAR_AT_COVE, false);
		assertEquals(KONAR_AT_COVE, tracker.summary().getContext());
	}

	@Test
	public void noTaskClearsTheCurrentAssignment()
	{
		observe(50, KONAR_AT_COVE, false);
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertSame(TaskContext.NONE, tracker.getCurrentContext());
		observe(50, KONAR_AT_COVE, false);
		tracker.clearCurrentTask();
		assertSame(TaskContext.NONE, tracker.getCurrentContext());
	}

	@Test
	public void rewardsAreSetOnlyOnACompletedSession()
	{
		observe(2, KONAR_AT_COVE, false);
		assertTrue(tracker.play(ACCOUNT));
		String id = tracker.getSessionId();
		assertFalse("not completed yet", tracker.setCompletionRewards(id, 18, 43));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, TaskContext.NONE, true));
		assertFalse("another session", tracker.setCompletionRewards("other", 18, 43));
		assertTrue(tracker.setCompletionRewards(id, 18, 43));
		assertEquals(Integer.valueOf(18), tracker.summary().getContext().getPointsEarned());
		assertEquals(Integer.valueOf(43), tracker.summary().getContext().getTaskStreak());
		assertEquals("the assignment stays", Integer.valueOf(SlayerMaster.KONAR), tracker.summary().getContext().getMaster());
	}

	@Test
	public void heldCompletionTakesCorrectedPoints()
	{
		observe(2, KONAR_AT_COVE, false);
		assertTrue(tracker.play(ACCOUNT));
		String id = tracker.getSessionId();
		observe(0, TaskContext.NONE, true);
		assertTrue(tracker.setCompletionRewards(id, 0, 43));
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.setCompletionRewards(id, 18, 43));
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(Integer.valueOf(18), held.getContext().getPointsEarned());
		assertFalse("saved: nothing left to update", tracker.setCompletionRewards(id, 20, 43));
	}

	@Test
	public void recordHasTheContextAndRewardsOnlyWhenCompleted()
	{
		observe(2, KONAR_AT_COVE, false);
		assertTrue(tracker.play(ACCOUNT));
		String id = tracker.getSessionId();
		observe(0, TaskContext.NONE, true);
		tracker.setCompletionRewards(id, 18, 43);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), record.getSlayerMaster());
		assertEquals(Integer.valueOf(12), record.getSlayerArea());
		assertEquals("Kraken Cove", record.getTaskLocation());
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
		assertEquals(Integer.valueOf(43), record.getTaskStreak());

		LedgerRecord copy = gson.fromJson(gson.toJson(record), LedgerRecord.class);
		assertEquals(record, copy);
	}

	@Test
	public void partialRecordHasNoRewards()
	{
		observe(50, KONAR_AT_COVE, false);
		assertTrue(tracker.play(ACCOUNT));
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), record.getSlayerMaster());
		assertNull(record.getPointsEarned());
		assertNull(record.getTaskStreak());
	}

	@Test
	public void snapshotRestoresTheAssignment()
	{
		observe(50, KONAR_AT_COVE, false);
		assertTrue(tracker.play(ACCOUNT));
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.stopAndReset(), COUNTERS, now);
		SessionSnapshot copy = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), copy.getSlayerMaster());

		SessionTracker restored = new SessionTracker(() -> now);
		// The game's reading lacks the area name this time; the snapshot's is kept.
		restored.observe("Kraken", TASK, 50, 100, TaskContext.assignment(SlayerMaster.KONAR, 12, null), false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(copy, COUNTERS));
		assertEquals(KONAR_AT_COVE, restored.summary().getContext());
		assertEquals(KONAR_AT_COVE, copy.toSummary().getContext());
	}

	@Test
	public void olderSnapshotTakesTheAssignmentFromTheMatchingTask()
	{
		String json = "{\"schemaVersion\":2,\"sessionId\":\"s1\",\"accountHash\":555,\"monster\":\"Kraken\","
			+ "\"creatureId\":42,\"initialAmount\":60,\"originalAmount\":100,\"kills\":10,\"remaining\":50}";
		SessionSnapshot old = gson.fromJson(json, SessionSnapshot.class);
		assertNull(old.getSlayerMaster());
		assertSame(TaskContext.NONE, old.toSummary().getContext());
		observe(50, KONAR_AT_COVE, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(old, null));
		assertEquals(KONAR_AT_COVE, tracker.summary().getContext());
	}

	@Test
	public void olderRecordLoadsWithEverythingUnknown()
	{
		String json = "{\"schemaVersion\":2,\"id\":\"x\",\"monster\":\"Kraken\",\"creatureId\":42,\"kills\":4,"
			+ "\"completed\":true}";
		LedgerRecord old = gson.fromJson(json, LedgerRecord.class);
		assertNull(old.getSlayerMaster());
		assertNull(old.getSlayerArea());
		assertNull(old.getTaskLocation());
		assertNull(old.getPointsEarned());
		assertNull(old.getTaskStreak());
		assertEquals("no task context lines", "", LedgerHistory.taskContextTooltip(old));
	}

	// ---- Display ----

	@Test
	public void formatsTheContext()
	{
		assertEquals("Master: Konar", LedgerHistory.formatMaster(SlayerMaster.KONAR));
		assertEquals("Unknown master (14)", LedgerHistory.formatMaster(14));
		assertEquals("Master: -", LedgerHistory.formatMaster(null));
		assertEquals("Master: -", LedgerHistory.formatMaster(SlayerMaster.NONE));
		assertEquals("Type: Konar (Kraken Cove)", LedgerHistory.formatTaskType(TaskType.KONAR, "Kraken Cove"));
		assertEquals("Type: Boss", LedgerHistory.formatTaskType(TaskType.BOSS, null));
		assertEquals("Type: -", LedgerHistory.formatTaskType(null, null));
		assertEquals("Points earned: 18", LedgerHistory.formatPointsEarned(18));
		assertEquals("Points earned: -", LedgerHistory.formatPointsEarned(null));
		assertEquals("Task streak: 43", LedgerHistory.formatTaskStreak(43));
	}

	@Test
	public void historyTooltipListsTheKnownParts()
	{
		LedgerRecord r = new LedgerRecord();
		r.setCreatureId(TASK);
		r.setSlayerMaster(SlayerMaster.KONAR);
		r.setTaskLocation("Kraken <Cove>");
		r.setPointsEarned(18);
		r.setTaskStreak(43);
		assertEquals("<br>Master: Konar<br>Type: Konar (Kraken &lt;Cove&gt;)<br>Points earned: 18<br>Task streak: 43",
			LedgerHistory.taskContextTooltip(r));
		String tooltip = LedgerHistory.rowTooltip(r, HistoryPricing.value(r, LootPriceMode.GE, Collections.emptyMap()),
			null);
		assertTrue(tooltip, tooltip.endsWith("<br>Deaths: -<br>Master: Konar<br>Type: Konar (Kraken &lt;Cove&gt;)"
			+ "<br>Points earned: 18<br>Task streak: 43</html>"));

		LedgerRecord boss = new LedgerRecord();
		boss.setCreatureId(SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 3));
		assertEquals("a boss task without a known master", "<br>Type: Boss", LedgerHistory.taskContextTooltip(boss));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.lang.reflect.Method;
import java.time.ZoneId;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** The task icons of Overall totals: {@link TaskIcons} and the task a By monster group shows the icon of. */
public class TaskIconsTest
{
	private static final ZoneId UTC = ZoneId.of("UTC");

	@Test
	public void aKnownTaskHasItsSlayerGuideIcon()
	{
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_DUSTDEVIL), TaskIcons.itemId("Dust devils"));
		// Matched as TaskStatistics.normalize matches names: case and outer spaces don't matter.
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_DUSTDEVIL), TaskIcons.itemId("  dust DEVILS "));
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_ABERRANTSPECTER), TaskIcons.itemId("Aberrant spectres"));
		// A task without a Slayer-guide picture has the core plugin's other item, a boss task its pet.
		assertEquals(Integer.valueOf(ItemID.DRAGONMASK_BLACK), TaskIcons.itemId("Black dragons"));
		assertEquals(Integer.valueOf(ItemID.SNAKEPET), TaskIcons.itemId("Zulrah"));
	}

	@Test
	public void anUnknownTaskHasNone()
	{
		assertNull(TaskIcons.itemId("Lava strykewyrms"));
		assertNull(TaskIcons.itemId(LedgerHistory.UNKNOWN_MONSTER));
		assertNull(TaskIcons.itemId("Unknown task (12)"));
		assertNull(TaskIcons.itemId(""));
		assertNull(TaskIcons.itemId("   "));
		assertNull(TaskIcons.itemId(null));
		// Group names are no task names: the group's task (OverallTotals.Entry#getTask) is looked up instead.
		assertNull(TaskIcons.itemId("Deviant spectres"));
		assertNull(TaskIcons.itemId("Dust devils" + CannonTasks.SUFFIX));
	}

	@Test
	public void aCatacombsVariantGroupShowsItsTasksIcon()
	{
		LedgerRecord newest = record("Aberrant spectres", 1);
		newest.setVariant("Deviant spectres");
		LedgerRecord older = record("Aberrant spectres", 2);
		older.setVariant("Deviant spectres");

		OverallTotals.Entry group = byMonster(Arrays.asList(newest, older)).get(0);

		assertEquals("Deviant spectres", group.getLabel());
		assertEquals("Aberrant spectres", group.getTask());
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_ABERRANTSPECTER), TaskIcons.itemId(group.getTask()));
	}

	@Test
	public void aCannonGroupShowsItsTasksIcon()
	{
		LedgerRecord cannon = record("Dust devils", 1);
		cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 200L));
		LedgerRecord granite = record("Fire giants", 2);
		granite.setSupplies(Collections.singletonMap(SupplyTracker.GRANITE_CANNONBALL, 50L));

		List<OverallTotals.Entry> groups = byMonster(Arrays.asList(cannon, granite));

		Map<String, String> tasks = new HashMap<>();
		for (OverallTotals.Entry group : groups)
		{
			tasks.put(group.getLabel(), group.getTask());
		}
		assertEquals("Dust devils", tasks.get("Dust devils (cannon)"));
		assertEquals("Fire giants", tasks.get("Fire giants (cannon)"));
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_DUSTDEVIL), TaskIcons.itemId(tasks.get("Dust devils (cannon)")));
	}

	@Test
	public void aGroupWithoutATaskNameHasNoTaskAndOtherGroupingsHaveNone()
	{
		LedgerRecord unnamed = record(null, 1);
		OverallTotals.Entry group = byMonster(Collections.singletonList(unnamed)).get(0);
		assertNull(group.getTask());
		assertNull(TaskIcons.itemId(group.getTask()));

		LedgerRecord named = record("Dust devils", 1);
		for (OverallTotals.Grouping grouping : Arrays.asList(OverallTotals.Grouping.ALL,
			OverallTotals.Grouping.MASTER, OverallTotals.Grouping.MONTH))
		{
			List<OverallTotals.Entry> entries = OverallTotals.summarize(Collections.singletonList(named), grouping,
				LootPriceMode.GE, Collections.emptyMap(), UTC);
			assertNull(grouping.toString(), entries.get(0).getTask());
		}
	}

	@Test
	public void everyBundledTaskHasAnIcon()
	{
		TaskLocations locations = TaskLocations.load(new Gson(), TaskLocations.SNAPSHOT_RESOURCE);
		assertNotNull(locations);
		for (String task : locations.tasks())
		{
			assertNotNull("No icon: " + task, TaskIcons.itemId(task));
		}
	}

	/**
	 * The table is RuneLite's core Slayer {@code Task} enum: every task with the same item, and no other. The enum is
	 * package-private, so it is read by reflection (test code only; the plugin can't).
	 */
	@Test
	public void theTableMatchesRuneLitesSlayerTasks() throws Exception
	{
		Class<?> taskClass = Class.forName("net.runelite.client.plugins.slayer.Task");
		Method getName = taskClass.getDeclaredMethod("getName");
		Method getItemSpriteId = taskClass.getDeclaredMethod("getItemSpriteId");
		getName.setAccessible(true);
		getItemSpriteId.setAccessible(true);
		Object[] tasks = taskClass.getEnumConstants();
		assertTrue(tasks.length > 100);
		for (Object task : tasks)
		{
			String name = (String) getName.invoke(task);
			assertEquals(name, getItemSpriteId.invoke(task), TaskIcons.itemId(name));
		}
		assertEquals(tasks.length, TaskIcons.size());
	}

	private static List<OverallTotals.Entry> byMonster(List<LedgerRecord> records)
	{
		return OverallTotals.summarize(records, OverallTotals.Grouping.MONSTER, LootPriceMode.GE,
			Collections.emptyMap(), UTC);
	}

	/** A completed Konar task of {@code monster}, newest first by {@code age}. */
	private static LedgerRecord record(String monster, long age)
	{
		LedgerRecord record = new LedgerRecord();
		record.setMonster(monster);
		record.setSlayerMaster(SlayerMaster.KONAR);
		record.setEndedAt(1_000_000L - age);
		record.setKills(10);
		record.setActiveMillis(60_000L);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/** Location names: validation, the name a record is saved with, what the panel shows, and the prompt's state. */
public class TaskLocationTest
{
	private static final int SMOKE = 12_946;
	private static final int TOWER = 13_623;

	@Test
	public void namesAreTrimmedCollapsedAndCut()
	{
		assertEquals("Smoke Dungeon", TaskLocation.normalizeName("  Smoke \t  Dungeon\n"));
		assertNull("empty", TaskLocation.normalizeName(""));
		assertNull("blank", TaskLocation.normalizeName(" \n\t "));
		assertNull(TaskLocation.normalizeName(null));
		String longName = "Catacombs of Kourend, the north-westernmost corner";
		String cut = TaskLocation.normalizeName(longName);
		assertEquals(TaskLocation.MAX_NAME_LENGTH, cut.length());
		assertEquals(longName.substring(0, TaskLocation.MAX_NAME_LENGTH).trim(), cut);
	}

	@Test
	public void aRecordIsSavedWithItsAssignedAreaFirst()
	{
		assertEquals("Kraken Cove", TaskLocation.recordName("Kraken Cove", "My cave"));
		assertEquals("My cave", TaskLocation.recordName(null, " My cave "));
		assertEquals("My cave", TaskLocation.recordName("  ", "My cave"));
		assertNull(TaskLocation.recordName(null, null));
	}

	@Test
	public void historyShowsTheRecordsNameThenItsAreaThenItsRegionsNameThenUnknown()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(SMOKE, "Smoke Dungeon");
		LedgerRecord record = new LedgerRecord();
		assertEquals("an older record", TaskLocation.UNKNOWN, TaskLocation.displayName(record, names::get));

		record.setLocationRegion(TOWER);
		assertEquals("a region nobody named", TaskLocation.UNKNOWN, TaskLocation.displayName(record, names::get));
		record.setLocationRegion(SMOKE);
		assertEquals("named after it was saved", "Smoke Dungeon", TaskLocation.displayName(record, names::get));
		record.setTaskLocation("Kraken Cove");
		assertEquals("an older Konar record", "Kraken Cove", TaskLocation.displayName(record, names::get));
		record.setLocation("Edited");
		assertEquals("Edited", TaskLocation.displayName(record, names::get));
	}

	@Test
	public void aRecordsLocationIsNullWhenUnknownAndFollowsItsRegionOnceNamed()
	{
		Map<Integer, String> names = new HashMap<>();
		LedgerRecord record = new LedgerRecord();
		assertNull(TaskLocation.recordLocation(record, names::get));
		record.setLocationRegion(SMOKE);
		assertNull("saved before the region was named", TaskLocation.recordLocation(record, names::get));
		names.put(SMOKE, " Smoke  Dungeon ");
		assertEquals("named since", "Smoke Dungeon", TaskLocation.recordLocation(record, names::get));
		record.setTaskLocation("Kraken Cove");
		assertEquals("Kraken Cove", TaskLocation.recordLocation(record, names::get));
		record.setLocation("Edited");
		assertEquals("Edited", TaskLocation.recordLocation(record, names::get));
	}

	@Test
	public void theCurrentNameIsTheAreaThenTheSessionsRegionThenWhereThePlayerIs()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(TOWER, "Slayer Tower");
		assertNull(TaskLocation.currentName(null, null, LocationTally.NO_REGION, names::get));
		assertNull("unnamed", TaskLocation.currentName(null, SMOKE, SMOKE, names::get));
		assertEquals("where the player is", "Slayer Tower", TaskLocation.currentName(null, null, TOWER, names::get));
		assertEquals("an unnamed session region falls back too", "Slayer Tower",
			TaskLocation.currentName(null, SMOKE, TOWER, names::get));
		names.put(SMOKE, "Smoke Dungeon");
		assertEquals("the session's region first", "Smoke Dungeon",
			TaskLocation.currentName(null, SMOKE, TOWER, names::get));
		assertEquals("the assigned area first", "Kraken Cove",
			TaskLocation.currentName(" Kraken Cove ", SMOKE, TOWER, names::get));
		assertEquals("Slayer Tower", TaskLocation.currentName(null, null, TOWER, names::get));
	}

	@Test
	public void locationsMatchIgnoringCaseAndSpacing()
	{
		assertTrue(TaskLocation.sameLocation("Smoke Dungeon", "  smoke   DUNGEON "));
		assertFalse(TaskLocation.sameLocation("Smoke Dungeon", "Smoke Devil Dungeon"));
		assertFalse("no name never matches", TaskLocation.sameLocation(null, null));
		assertFalse(TaskLocation.sameLocation(" ", " "));
		assertFalse(TaskLocation.sameLocation("Smoke Dungeon", null));
		assertEquals("smoke dungeon", TaskLocation.matchKey(" Smoke\tDungeon "));
		assertNull(TaskLocation.matchKey(""));
	}

	@Test
	public void suggestionsAreTheWikisThenThePlayersOwnWithoutRepeats()
	{
		assertEquals(Arrays.asList("Smoke Dungeon", "Catacombs of Kourend", "Ancient cavern", "my spot", "Zul spot"),
			TaskLocation.suggestions(Arrays.asList("Smoke Dungeon", " Catacombs  of Kourend", "smoke dungeon"),
				Arrays.asList("Zul spot", "catacombs of kourend", "my spot", null, " ", "Ancient cavern")));
		assertTrue(TaskLocation.suggestions(null, null).isEmpty());
		assertEquals(Collections.singletonList("Mine"),
			TaskLocation.suggestions(Collections.emptyList(), Collections.singletonList("Mine")));
	}

	@Test
	public void theLiveNameIsTheAreaElseTheRegionsName()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(SMOKE, "Smoke Dungeon");
		assertEquals("Kraken Cove", TaskLocation.liveName("Kraken Cove", SMOKE, names::get));
		assertEquals("Smoke Dungeon", TaskLocation.liveName(null, SMOKE, names::get));
		assertNull(TaskLocation.liveName(null, TOWER, names::get));
		assertNull("no kills yet", TaskLocation.liveName(null, null, names::get));
		assertEquals("Location: Smoke Dungeon", TaskLocation.format("Smoke Dungeon"));
		assertEquals("Location: Unknown", TaskLocation.format(null));
	}

	@Test
	public void thePromptAsksAboutOneUnnamedRegionAtATime()
	{
		LocationPrompt prompt = new LocationPrompt();
		assertFalse("a named region", prompt.offer(SMOKE, true, false));
		assertFalse("no region", prompt.offer(LocationTally.NO_REGION, false, false));
		assertTrue(prompt.offer(SMOKE, false, false));
		assertEquals(SMOKE, prompt.getShown());
		assertFalse("already shown", prompt.offer(SMOKE, false, false));
		assertFalse("one at a time", prompt.offer(TOWER, false, false));

		prompt.named(TOWER);
		assertEquals("another region's name doesn't close it", SMOKE, prompt.getShown());
		prompt.named(SMOKE);
		assertEquals(LocationTally.NO_REGION, prompt.getShown());
		assertTrue(prompt.offer(TOWER, false, false));
	}

	@Test
	public void aSkippedRegionIsNotAskedAboutAgainUntilReset()
	{
		LocationPrompt prompt = new LocationPrompt();
		assertTrue(prompt.offer(SMOKE, false, false));
		prompt.skip(SMOKE);
		assertEquals(LocationTally.NO_REGION, prompt.getShown());
		assertFalse(prompt.offer(SMOKE, false, false));
		assertTrue(prompt.offer(TOWER, false, false));
		prompt.hide();
		assertTrue("hidden is not skipped", prompt.offer(TOWER, false, false));

		prompt.reset();
		assertEquals(LocationTally.NO_REGION, prompt.getShown());
		assertTrue("a new run asks again", prompt.offer(SMOKE, false, false));
	}

	@Test
	public void aSkipKeptInTheProfileIsNotAskedAboutAndForgetSkipsKeepsTheShownPrompt()
	{
		LocationPrompt prompt = new LocationPrompt();
		assertFalse("skipped in an earlier run", prompt.offer(SMOKE, false, true));
		assertTrue(prompt.offer(TOWER, false, false));
		prompt.skip(TOWER);
		assertTrue(prompt.offer(SMOKE, false, false));
		prompt.forgetSkips();
		assertEquals("still shown", SMOKE, prompt.getShown());
		prompt.hide();
		assertTrue("asked again", prompt.offer(TOWER, false, false));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import com.google.gson.Gson;
import java.io.StringReader;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Pattern;
import org.junit.Test;

public class TaskLocationsTest
{
	private static final Gson GSON = new Gson();
	private static final TaskLocations LOCATIONS = TaskLocations.load(GSON, TaskLocations.SNAPSHOT_RESOURCE);

	@Test
	public void bundledSnapshotLoadsWithItsMetadata()
	{
		assertNotNull(LOCATIONS);
		assertEquals("2026-10-27", LOCATIONS.getRetrieved());
		assertEquals("Old School RuneScape Wiki", LOCATIONS.getSource());
		assertEquals("CC BY-NC-SA 3.0", LOCATIONS.getLicense());
		assertTrue(LOCATIONS.getAttribution().contains("Old School RuneScape Wiki contributors"));
		assertTrue(LOCATIONS.tasks().size() > 100);
	}

	@Test
	public void knownTasksListTheWikiLocationsInOrder()
	{
		// Slayer task/Dust devils, revision 15382347 ("Location comparison").
		assertEquals(Arrays.asList("Catacombs of Kourend", "Wilderness Slayer Cave", "Smoke Dungeon"),
			LOCATIONS.locationsFor("Dust devils"));
		// Slayer task/Kurask, revision 15373542.
		assertEquals(Arrays.asList("Fremennik Slayer Dungeon", "Iorwerth Dungeon", "Kurask Lair"),
			LOCATIONS.locationsFor("Kurask"));
		// Floor qualifiers are dropped: Slayer Tower (top floor), (basement) and (roof) are one location.
		assertEquals(Arrays.asList("Slayer Tower"), LOCATIONS.locationsFor("Gargoyles"));
		// From the monster article when there is no task page: Frost dragon, revision 15357143.
		assertEquals(Arrays.asList("Grimstone Dungeon"), LOCATIONS.locationsFor("Frost dragons"));
	}

	@Test
	public void lookupNormalisesTheTaskName()
	{
		List<String> expected = LOCATIONS.locationsFor("Dust devils");
		assertEquals(expected, LOCATIONS.locationsFor("  dust DEVILS "));
		assertEquals(expected, LOCATIONS.locationsFor("DUST DEVILS"));
	}

	@Test
	public void unknownOrMissingTasksHaveNoLocations()
	{
		assertTrue(LOCATIONS.locationsFor("Not a task").isEmpty());
		assertTrue(LOCATIONS.locationsFor("").isEmpty());
		assertTrue(LOCATIONS.locationsFor(null).isEmpty());
		// Boss tasks are not in the snapshot.
		assertTrue(LOCATIONS.locationsFor("Zulrah").isEmpty());
	}

	@Test
	public void locationListsAreUnmodifiable()
	{
		assertUnmodifiable(LOCATIONS.locationsFor("Dust devils"));
		assertUnmodifiable(LOCATIONS.locationsFor("Not a task"));
		assertUnmodifiable(LOCATIONS.tasks());
	}

	@Test
	public void everyTaskNameIsACoreSlayerTaskName() throws Exception
	{
		Set<String> coreNames = coreTaskNames();
		for (String task : LOCATIONS.tasks())
		{
			assertTrue("Not a core Task name: " + task, coreNames.contains(task));
		}
	}

	@Test
	public void everyTaskHasUniqueNonBlankLocations()
	{
		for (String task : LOCATIONS.tasks())
		{
			List<String> locations = LOCATIONS.locationsFor(task);
			assertTrue(task, !locations.isEmpty());
			Set<String> seen = new HashSet<>();
			for (String location : locations)
			{
				assertTrue(task, location != null && !location.trim().isEmpty());
				assertEquals(task, location.trim(), location);
				assertTrue(task + ": " + location, seen.add(location.toLowerCase(Locale.ROOT)));
			}
		}
	}

	/** A ", " followed by a lowercase word: a trailing description ("Lizardman Canyon, west side"). */
	private static final Pattern COMMA_DESCRIPTION = Pattern.compile(", \\p{Ll}");
	/** Directions, positions, levels, parts and rooms, matched case-insensitively. */
	private static final Pattern DESCRIPTIVE_WORDS = Pattern.compile(
		"(?i)\\bnear |\\b(north|south|east|west)(-(east|west))? of\\b|\\blevel |\\bpart |\\brooms?\\b"
			+ "|\\b(outside|inside|around|along|between|beneath|underneath|entrance|side|floor"
			+ "|northern|southern|eastern|western)\\b");
	/** The only disambiguators allowed after a place name. */
	private static final Pattern ALLOWED_SUFFIX = Pattern.compile(" \\((Wilderness|task-only|Cave|west)\\)$");
	/** Stronghold of Security floors are written "Stronghold of Security: Floor"; only the floor counts toward the length. */
	private static final String STRONGHOLD_PREFIX = "Stronghold of Security: ";
	/** The longest place name, "Miscellania and Etceteria Dungeon", is 33 characters. */
	private static final int MAX_NAME_LENGTH = 33;
	/** Small words that stay lowercase in a title-case place name ("Ruins of Tapoyauik", "Burgh de Rott"). */
	private static final Set<String> LOWERCASE_WORDS = new HashSet<>(Arrays.asList("of", "the", "and", "de"));

	@Test
	public void locationsAreShortPlaceNames()
	{
		for (String task : LOCATIONS.tasks())
		{
			for (String location : LOCATIONS.locationsFor(task))
			{
				String where = task + ": " + location;
				assertFalse(where, COMMA_DESCRIPTION.matcher(location).find());
				assertFalse(where, DESCRIPTIVE_WORDS.matcher(location).find());
				String name = location.startsWith(STRONGHOLD_PREFIX)
					? location.substring(STRONGHOLD_PREFIX.length()) : location;
				assertTrue(where, name.length() <= MAX_NAME_LENGTH);
				String base = ALLOWED_SUFFIX.matcher(name).replaceAll("");
				// Only a known disambiguator may follow the name, and no ", " outside the Stronghold prefix.
				assertFalse(where, base.contains("(") || base.contains(", "));
				// Title case, ignoring the allowed disambiguator.
				for (String word : base.split(" "))
				{
					assertTrue(where, LOWERCASE_WORDS.contains(word) || !Character.isLowerCase(word.charAt(0)));
				}
			}
		}
	}

	@Test
	public void locationsUseOneSpellingPerPlace()
	{
		// Aliases replaced by the Wiki's article titles.
		Set<String> banned = new HashSet<>(Arrays.asList(
			"Stronghold Slayer Dungeon", "Fremennik Slayer Cave", "Taverley dungeon", "Killerwatt plane",
			"The Underground Pass", "Edgeville Dungeon (Wilderness)"));
		for (String task : LOCATIONS.tasks())
		{
			for (String location : LOCATIONS.locationsFor(task))
			{
				// Exact match: "Taverley dungeon" is banned, "Taverley Dungeon" is the article title.
				assertFalse(task + ": " + location, banned.contains(location));
			}
		}
	}

	@Test
	public void snapshotCoversEveryRegularCoreTask() throws Exception
	{
		// Boss tasks and Revenants are left out on purpose; a new or dropped task must update this set.
		Set<String> expectedMissing = new HashSet<>(Arrays.asList(EXPECTED_MISSING));
		Set<String> missing = new TreeSet<>(coreTaskNames());
		missing.removeAll(LOCATIONS.tasks());
		assertEquals(new TreeSet<>(expectedMissing), missing);
	}

	private static final String[] EXPECTED_MISSING = {
		// Boss tasks.
		"Araxxor", "Barrows Brothers", "Callisto", "Cerberus", "Commander Zilyana", "Crazy Archaeologists",
		"Dagannoth Kings", "Deranged Archaeologist", "Duke Sucellus", "General Graardor", "K'ril Tsutsaroth",
		"Kree'arra", "Sarachnis", "Scorpia", "The Abyssal Sire", "The Alchemical Hydra", "The Cave Kraken Boss",
		"The Chaos Elemental", "The Chaos Fanatic", "The Giant Mole", "The Grotesque Guardians",
		"The Kalphite Queen", "The King Black Dragon", "The Leviathan", "The Maggot King", "The Phantom Muspah",
		"The Shellbane Gryphon", "The Thermonuclear Smoke Devil", "The Whisperer", "TzKal-Zuk", "TzTok-Jad",
		"Vardorvis", "Venenatis", "Vet'ion", "Vorkath", "Zulrah",
		// Also left out of the snapshot.
		"Revenants",
	};

	@Test
	public void missingMalformedOrInvalidResourcesLoadAsNull()
	{
		assertNull(TaskLocations.load(GSON, "no-such-task-locations.json"));
		assertNull(TaskLocations.load(GSON, "task-locations-malformed.json"));
		// Valid JSON, but the same task twice (after normalising).
		assertNull(TaskLocations.load(GSON, "task-locations-invalid.json"));
	}

	@Test
	public void validationRejectsBadSnapshots()
	{
		assertNotNull(TaskLocations.parse(GSON, new StringReader(snapshot(1, "\"Smoke Dungeon\""))));
		assertRejected("null");
		assertRejected(snapshot(2, "\"Smoke Dungeon\""));
		assertRejected(snapshot(1, ""));
		assertRejected(snapshot(1, "\" \""));
		assertRejected(snapshot(1, "null"));
		assertRejected(snapshot(1, "\"Smoke Dungeon\", \" smoke dungeon \""));
		assertRejected(snapshot(1, "\"Smoke Dungeon\"").replace("\"attribution\": \"Test\"", "\"attribution\": \" \""));
		assertRejected(snapshot(1, "\"Smoke Dungeon\"").replace("\"revision\": 1", "\"revision\": 0"));
		assertRejected(snapshot(1, "\"Smoke Dungeon\"").replace("\"task\": \"Dust devils\"", "\"task\": \"\""));
		assertRejected(snapshot(1, "\"Smoke Dungeon\"").replace(", \"locations\": [\"Smoke Dungeon\"]", ""));
		assertRejected("{ \"version\": 1, \"source\": \"s\", \"license\": \"l\", \"licenseUrl\": \"u\", "
			+ "\"contributors\": \"c\", \"retrieved\": \"r\", \"attribution\": \"a\", \"tasks\": [] }");
		assertRejected("{ \"version\": 1, \"source\": \"s\", \"license\": \"l\", \"licenseUrl\": \"u\", "
			+ "\"contributors\": \"c\", \"retrieved\": \"r\", \"attribution\": \"a\", \"tasks\": [ null ] }");
	}

	private static String snapshot(int version, String locations)
	{
		return "{ \"version\": " + version + ", \"source\": \"Old School RuneScape Wiki\", "
			+ "\"license\": \"CC BY-NC-SA 3.0\", \"licenseUrl\": \"https://creativecommons.org/licenses/by-nc-sa/3.0/\", "
			+ "\"contributors\": \"Old School RuneScape Wiki contributors\", \"retrieved\": \"2026-10-27\", "
			+ "\"attribution\": \"Test\", \"tasks\": [ { \"task\": \"Dust devils\", "
			+ "\"article\": \"Slayer task/Dust devils\", "
			+ "\"page\": \"https://oldschool.runescape.wiki/w/Slayer_task/Dust_devils\", \"revision\": 1"
			+ ", \"locations\": [" + locations + "] } ] }";
	}

	private static void assertRejected(String json)
	{
		try
		{
			TaskLocations.parse(GSON, new StringReader(json));
			fail("Expected the snapshot to be rejected: " + json);
		}
		catch (RuntimeException expected)
		{
			// Rejected, as load() would turn into null.
		}
	}

	private static void assertUnmodifiable(List<String> list)
	{
		try
		{
			list.add("Somewhere");
			fail("Expected an unmodifiable list");
		}
		catch (UnsupportedOperationException expected)
		{
			// Unmodifiable.
		}
	}

	/** The names in RuneLite's core Slayer {@code Task} enum (package-private, so read by reflection). */
	private static Set<String> coreTaskNames() throws Exception
	{
		Class<?> taskClass = Class.forName("net.runelite.client.plugins.slayer.Task");
		Method getName = taskClass.getDeclaredMethod("getName");
		getName.setAccessible(true);
		Set<String> names = new HashSet<>();
		for (Object task : taskClass.getEnumConstants())
		{
			names.add((String) getName.invoke(task));
		}
		assertTrue(names.size() > 100);
		return names;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/** Note normalization and the recent-notes list. */
public class TaskNoteTest
{
	@Test
	public void trimsAndCollapsesWhitespace()
	{
		assertEquals("Prayer gear", TaskNote.normalize("  Prayer   gear  "));
		assertEquals("Prayer gear", TaskNote.normalize("Prayer\t gear"));
		assertEquals("Barrage", TaskNote.normalize("Barrage"));
	}

	@Test
	public void emptyIsNull()
	{
		assertNull(TaskNote.normalize(null));
		assertNull(TaskNote.normalize(""));
		assertNull(TaskNote.normalize("   \t\n "));
		assertNull(TaskNote.normalize("\u0000\u0007"));
	}

	@Test
	public void controlCharactersAreStripped()
	{
		assertEquals("Range pray", TaskNote.normalize("Range\npray"));
		assertEquals("Range pray", TaskNote.normalize("Range\r\n\u0000pray\u001b"));
		assertEquals("Cannon", TaskNote.normalize("Can​non"));
	}

	@Test
	public void longNotesAreCut()
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < 10; i++)
		{
			sb.append("abcdefghi ");
		}
		String note = TaskNote.normalize(sb.toString());
		assertEquals(TaskNote.MAX_LENGTH, 60);
		// Six 9-letter words and five spaces make 59; a seventh word does not fit, and no trailing space is kept.
		assertEquals("abcdefghi abcdefghi abcdefghi abcdefghi abcdefghi abcdefghi", note);

		String exact = repeat('x', 60);
		assertEquals(exact, TaskNote.normalize(exact));
		assertEquals(exact, TaskNote.normalize(exact + "yz"));
		assertEquals(exact, TaskNote.normalize("   " + exact + "   "));
	}

	@Test
	public void neverSplitsASurrogatePair()
	{
		String emoji = "💀";
		String note = TaskNote.normalize(repeat('x', 59) + emoji);
		assertEquals(repeat('x', 59), note);
		assertEquals(repeat('x', 58) + emoji, TaskNote.normalize(repeat('x', 58) + emoji));
	}

	@Test
	public void recentNotesStartWithTheDefaults()
	{
		assertEquals(TaskNote.DEFAULTS, TaskNote.recentNotes(Collections.<String>emptyList()));
		assertEquals(Arrays.asList("Prayer gear", "Strength gear", "Barrage", "Range pray", "Cannon"),
			TaskNote.DEFAULTS);
	}

	@Test
	public void recentNotesAreNewestFirstDistinctAndKeepTheLatestCasing()
	{
		List<String> notes = Arrays.asList("Burst  ", null, "", "burst", "BARRAGE", "Bursting cannon", "Burst");
		assertEquals(Arrays.asList("Burst", "BARRAGE", "Bursting cannon", "Prayer gear", "Strength gear", "Range pray",
			"Cannon"), TaskNote.recentNotes(notes));
	}

	@Test
	public void recentNotesAreCapped()
	{
		List<String> notes = new ArrayList<>();
		for (int i = 0; i < 12; i++)
		{
			notes.add("Note " + i);
		}
		List<String> recent = TaskNote.recentNotes(notes);
		assertEquals(TaskNote.MAX_RECENT, recent.size());
		assertEquals("Note 0", recent.get(0));
		assertEquals("Note 7", recent.get(7));
	}

	@Test
	public void recentNotesFromRecordsUseTheEndTime()
	{
		LedgerRecord older = record("a", 1_000, "Cannon");
		LedgerRecord newer = record("b", 2_000, "Barrage");
		LedgerRecord none = record("c", 3_000, null);
		LedgerRecord oldest = record("d", 500, "barrage");
		List<String> recent = TaskNote.recentNotes(Arrays.asList(older, none, oldest, newer));
		assertEquals(Arrays.asList("Barrage", "Cannon", "Prayer gear", "Strength gear", "Range pray"), recent);
	}

	private static LedgerRecord record(String id, long endedAt, String note)
	{
		LedgerRecord r = new LedgerRecord();
		r.setId(id);
		r.setEndedAt(endedAt);
		r.setNote(note);
		return r;
	}

	private static String repeat(char c, int n)
	{
		char[] chars = new char[n];
		Arrays.fill(chars, c);
		return new String(chars);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;

public class TaskRankingTest
{
	private static final long MINUTE = 60_000L;

	@Test
	public void ranksPooledRatesWithMetricSpecificSampleCounts()
	{
		LedgerRecord first = record(42, "Abyssal demons", 10 * MINUTE);
		first.setLootGeValue(100_000L);
		first.setSuppliesGeValue(10_000L);
		first.setXpGained(Collections.singletonMap("SLAYER", 10_000L));
		first.setPointsEarned(20);

		LedgerRecord second = record(42, "Abyssal demons", 20 * MINUTE);
		second.setLootGeValue(500_000L);
		second.setSuppliesGeValue(100_000L);

		LedgerRecord other = record(43, "Kurask", 30 * MINUTE);
		other.setLootGeValue(0L);
		other.setSuppliesGeValue(0L);
		other.setXpGained(Collections.emptyMap());
		other.setPointsEarned(0);

		LedgerRecord partial = record(42, "Abyssal demons", MINUTE);
		partial.setPartial(true);
		partial.setLootGeValue(100_000_000L);
		LedgerRecord untracked = record(44, "Gargoyles", MINUTE);
		untracked.setCompleted(false);
		untracked.setLootGeValue(100_000_000L);

		List<LedgerRecord> records = Arrays.asList(first, second, other, partial, untracked);
		List<TaskRanking.Entry> gp = rank(records, TaskRanking.Metric.PROFIT, LootPriceMode.GE);
		assertEquals(2, gp.size());
		assertEquals("Abyssal demons", gp.get(0).getMonster());
		assertEquals(Long.valueOf(980_000L), gp.get(0).getRatePerHour());
		assertEquals(2, gp.get(0).getSampleCount());
		assertEquals("Kurask", gp.get(1).getMonster());
		assertEquals(Long.valueOf(0L), gp.get(1).getRatePerHour());

		List<TaskRanking.Entry> xp = rank(records, TaskRanking.Metric.XP, LootPriceMode.GE);
		assertEquals(2, xp.size());
		assertEquals("Abyssal demons", xp.get(0).getMonster());
		assertEquals(Long.valueOf(60_000L), xp.get(0).getRatePerHour());
		assertEquals(1, xp.get(0).getSampleCount());
		assertEquals(Long.valueOf(0L), xp.get(1).getRatePerHour());
		assertEquals(1, xp.get(1).getSampleCount());

		List<TaskRanking.Entry> points = rank(records, TaskRanking.Metric.POINTS, LootPriceMode.GE);
		assertEquals(2, points.size());
		assertEquals("Abyssal demons", points.get(0).getMonster());
		assertEquals(Long.valueOf(120L), points.get(0).getRatePerHour());
		assertEquals(1, points.get(0).getSampleCount());
	}

	@Test
	public void includesUntrimmedOutliersAndMatchesLegacyNamesToCreatureKeys()
	{
		LedgerRecord ordinary = record(42, "Abyssal demons", 60 * MINUTE);
		ordinary.setLootGeValue(0L);
		ordinary.setSuppliesGeValue(0L);
		LedgerRecord outlier = record(null, " ABYSSAL DEMONS ", MINUTE);
		outlier.setLootGeValue(100_000L);
		outlier.setSuppliesGeValue(0L);

		TaskRanking.Entry entry = rank(Arrays.asList(ordinary, outlier), TaskRanking.Metric.PROFIT,
			LootPriceMode.GE).get(0);
		assertEquals(2, entry.getSampleCount());
		assertEquals(Long.valueOf(Math.round(100_000 * 3_600_000d / (61 * MINUTE))), entry.getRatePerHour());
		assertEquals("Abyssal demons", entry.getMonster());
	}

	@Test
	public void selectedLootModeSetsProfitAndUnavailableDataIsNotInvented()
	{
		LedgerRecord valued = record(42, "Abyssal demons", MINUTE);
		valued.setLootGeValue(200L);
		valued.setLootHaValue(400L);
		valued.setSuppliesGeValue(100L);
		assertEquals(Long.valueOf(18_000L), rank(Collections.singletonList(valued), TaskRanking.Metric.PROFIT,
			LootPriceMode.HIGH_ALCH).get(0).getRatePerHour());

		LedgerRecord legacy = record(42, "Abyssal demons", MINUTE);
		assertTrue(rank(Collections.singletonList(legacy), TaskRanking.Metric.PROFIT, LootPriceMode.GE).isEmpty());
		assertTrue(rank(Collections.singletonList(legacy), TaskRanking.Metric.XP, LootPriceMode.GE).isEmpty());
		assertTrue(rank(Collections.singletonList(legacy), TaskRanking.Metric.POINTS, LootPriceMode.GE).isEmpty());
	}

	@Test
	public void valuedRecordWithoutStoredSuppliesCountsThemAsZeroAsTaskStatisticsDoes()
	{
		LedgerRecord valued = record(42, "Abyssal demons", 60 * MINUTE);
		valued.setLootGeValue(5_000L);

		List<TaskRanking.Entry> gp = rank(Collections.singletonList(valued), TaskRanking.Metric.PROFIT,
			LootPriceMode.GE);
		assertEquals(1, gp.size());
		assertEquals(Long.valueOf(5_000L), gp.get(0).getRatePerHour());
	}

	@Test
	public void marksRatesApproximateWhenPricesAreMissingAndUsesCurrentGePrices()
	{
