	private static List<String> names(List<TaskRanking.Entry> entries)
	{
		List<String> names = new ArrayList<>();
		for (TaskRanking.Entry entry : entries)
		{
			names.add(entry.getMonster());
		}
		return names;
	}

	private static List<TaskRanking.Entry> rank(List<LedgerRecord> records, TaskRanking.Metric metric,
		LootPriceMode mode)
	{
		return TaskRanking.rank(records, metric, mode, null);
	}

	/** A completed record that tracked the whole assignment of 10. */
	private static LedgerRecord record(Integer creatureId, String monster, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setKills(10);
		record.setInitialAmount(10);
		record.setOriginalAmount(10);
		record.setActiveMillis(activeMillis);
		record.setCompleted(true);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** {@link TaskRewards}: points earned and streak of a completion, and {@link CompletionSignal#incrementedCounter()}. */
public class TaskRewardsTest
{
	private static final int[] COUNTERS = {43, 7, 2};

	@Test
	public void pointsEarnedIsTheIncrease()
	{
		assertEquals(Integer.valueOf(15), TaskRewards.pointsEarned(100, 115));
		assertEquals("Turael's tasks and early streaks give none", Integer.valueOf(0), TaskRewards.pointsEarned(100, 100));
	}

	@Test
	public void pointsEarnedIsNeverNegativeOrGuessed()
	{
		assertNull(TaskRewards.pointsEarned(100, 40));
		assertNull(TaskRewards.pointsEarned(null, 40));
		assertNull(TaskRewards.pointsEarned(40, null));
	}

	@Test
	public void completionUsesTheReadingBeforeTheCompletionTick()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(115);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertTrue(rewards.isFollowing());
		assertEquals("s1", rewards.getSessionId());
		assertEquals(Integer.valueOf(15), rewards.earned());
		assertEquals(Integer.valueOf(43), rewards.streak());
	}

	@Test
	public void pointsSpentEarlierInTheTaskDontMatter()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(500);
		// Spent 400 points at a master mid-task.
		rewards.update(100);
		rewards.update(100);
		rewards.update(118);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertEquals(Integer.valueOf(18), rewards.earned());
	}

	@Test
	public void pointsArrivingAfterTheCompletionTickAreFollowed()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(100);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertEquals(Integer.valueOf(0), rewards.earned());
		rewards.update(115);
		assertEquals(Integer.valueOf(15), rewards.earned());
		assertEquals("the streak is fixed at the completion", Integer.valueOf(43), rewards.streak());
	}

	@Test
	public void spendingRightAfterTheCompletionIsNotTrusted()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(115);
		rewards.startCompletion("s1", COUNTERS, 0);
		rewards.update(10);
		assertNull(rewards.earned());
	}

	@Test
	public void firstReadingAfterResetIsOnlyABaseline()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.reset();
		// Login resync: the first reading has nothing before it.
		rewards.update(900);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertNull(rewards.earned());
		rewards.reset();
		assertFalse("reset also stops following", rewards.isFollowing());
	}

	@Test
	public void stoppedFollowingReportsNothing()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(115);
		rewards.startCompletion("s1", COUNTERS, 1);
		rewards.stopFollowing();
		assertFalse(rewards.isFollowing());
		assertNull(rewards.getSessionId());
		assertNull(rewards.earned());
		assertNull(rewards.streak());
	}

	@Test
	public void streakIsTheCounterThatWentUp()
	{
		assertEquals(Integer.valueOf(43), TaskRewards.streakAfter(COUNTERS, 0));
		assertEquals(Integer.valueOf(7), TaskRewards.streakAfter(COUNTERS, 1));
		assertEquals(Integer.valueOf(2), TaskRewards.streakAfter(COUNTERS, 2));
		assertNull(TaskRewards.streakAfter(COUNTERS, CompletionSignal.NO_COUNTER));
		assertNull(TaskRewards.streakAfter(COUNTERS, 3));
		assertNull(TaskRewards.streakAfter(null, 0));
	}

	@Test
	public void completionSignalNamesTheIncrementedCounter()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(42, 6, 2);
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		assertTrue(signal.update(42, 7, 2));
		assertEquals("Wilderness", 1, signal.incrementedCounter());
		assertFalse(signal.update(42, 7, 2));
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		assertTrue(signal.update(42, 7, 3));
		assertEquals("Mortimer", 2, signal.incrementedCounter());
		assertTrue(signal.update(43, 7, 3));
		assertEquals("regular", 0, signal.incrementedCounter());
	}

	@Test
	public void completionSignalHasNoCounterWhenTwoWentUp()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(42, 6, 2);
		assertTrue(signal.update(43, 7, 2));
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		assertFalse("a resync", signal.update(50, 7, 2));
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		signal.reset();
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.Locale;
import org.junit.Test;

public class TaskStatisticsTest
{
	private static final int CREATURE = 42;
	private static final String MONSTER = "Abyssal demons";
	private static final long MINUTE = 60_000L;

	@Test
	public void averagesCompletedRecordsAndKeepsOutliers()
	{
		LedgerRecord usual = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		usual.setLoot(Collections.singletonMap(SavedItems.LOOT, 100_000L));
		usual.setLootGeValue(100_000L);
		usual.setLootHaValue(200_000L);
		usual.setSuppliesGeValue(10_000L);
		usual.setSupplies(Collections.singletonMap(100, 10L));
		usual.setSupplyDoses(Collections.singletonMap(100, 4));
		usual.setXpGained(Collections.singletonMap("SLAYER", 10_000L));

		LedgerRecord outlier = record(CREATURE, MONSTER, 20, 60 * MINUTE);
		outlier.setLoot(Collections.singletonMap(SavedItems.LOOT, 400_000L));
		outlier.setLootGeValue(400_000L);
		outlier.setLootHaValue(800_000L);
		outlier.setSuppliesGeValue(60_000L);
		outlier.setSupplies(Collections.singletonMap(100, 60L));
		outlier.setSupplyDoses(Collections.singletonMap(100, 4));
		outlier.setXpGained(Collections.singletonMap("SLAYER", 30_000L));

		LedgerRecord partial = record(CREATURE, MONSTER, 100, 100 * MINUTE);
		partial.setPartial(true);
		LedgerRecord otherCreature = record(43, MONSTER, 100, 100 * MINUTE);
		// A 4-dose item at 4,000 gp today: 1,000 gp a dose.
		java.util.Map<Integer, Long> today = SavedItems.todaysPrices();
		today.put(100, 4_000L);
		TaskStatistics stats = TaskStatistics.forTask(Arrays.asList(usual, outlier, partial, otherCreature), CREATURE,
			MONSTER, LootPriceMode.GE, today);

		assertEquals(2, stats.getSampleCount());
		assertEquals(35 * MINUTE, stats.getAverageTaskDurationMillis());
		assertEquals(Long.valueOf(140_000), stats.getMillisPerKill());
		assertEquals(Long.valueOf(16_667), stats.getLootPerKill());
		assertEquals("70 doses at 1,000 gp over 30 kills", Long.valueOf(2_333), stats.getSuppliesValuePerKill());
		assertFalse(stats.isProfitApproximate());
		assertEquals(70d / 30d, stats.getSuppliesPerKill().get(100), 1e-9);
		assertEquals(4, (int) stats.getSupplyDoses().get(100));
		assertEquals(40_000d / 30d, stats.getXpPerKill().get("SLAYER"), 1e-9);
		assertEquals(Long.valueOf(34_286), stats.getXpPerHour());
	}

	@Test
	public void includesOneSampleAndReturnsNoEstimateForNoSamples()
	{
		assertEquals(0, stats(Collections.emptyList()).getSampleCount());
		assertNull(stats(Collections.emptyList()).estimate(10));

		LedgerRecord one = record(CREATURE, MONSTER, 2, 2 * MINUTE);
		one.setLootGeValue(1_000L);
		one.setSuppliesGeValue(100L);
		TaskStatistics stats = stats(Collections.singletonList(one));
		TaskStatistics.Estimate estimate = stats.estimate(5);

		assertEquals(1, estimate.getSampleCount());
		assertEquals(Long.valueOf(5 * MINUTE), estimate.getActiveMillis());
		assertEquals(Long.valueOf(2_500), estimate.getLootValue());
		assertEquals(Long.valueOf(250), estimate.getSuppliesValue());
	}

