	@Test
	public void namesNormalizeTheSameUnderATurkishDefaultLocale()
	{
		Locale original = Locale.getDefault();
		try
		{
			// In Turkish, "I".toLowerCase() is a dotless i and "i".toUpperCase() a dotted capital I.
			Locale.setDefault(new Locale("tr", "TR"));
			assertEquals("iron dragons", TaskStatistics.normalize("IRON DRAGONS"));
			assertEquals("Hitpoints", SkillXp.skillName("HITPOINTS"));
			assertEquals("Mining", SkillXp.skillName("mINING"));
			LedgerRecord iron = record(null, "Iron dragons", 10, 10 * MINUTE);
			assertEquals(1, TaskStatistics.forTask(Collections.singletonList(iron), SessionTracker.NO_CREATURE,
				"IRON DRAGONS", LootPriceMode.GE, Collections.emptyMap()).getSampleCount());
		}
		finally
		{
			Locale.setDefault(original);
		}
	}

	private static TaskStatistics stats(Iterable<LedgerRecord> records)
	{
		java.util.List<LedgerRecord> list = new java.util.ArrayList<>();
		for (LedgerRecord record : records)
		{
			list.add(record);
		}
		return TaskStatistics.forTask(list, CREATURE, MONSTER, LootPriceMode.GE, SavedItems.todaysPrices());
	}

	private static LedgerRecord record(Integer creatureId, String monster, int kills, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setKills(kills);
		record.setActiveMillis(activeMillis);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.OptionalLong;
import org.junit.Test;

/**
 * The live "time left" estimate ({@link TaskTimeEstimate}) and how the panel words it.
 */
public class TaskTimeEstimateTest
{
	private static final long MINUTE = 60_000;

	@Test
	public void noKillsGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, 0, 100).isPresent());
		assertFalse(TaskTimeEstimate.killsPerHour(10 * MINUTE, 0).isPresent());
		assertFalse(TaskTimeEstimate.averageKillMillis(10 * MINUTE, 0).isPresent());
	}

	@Test
	public void belowKillThresholdGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, TaskTimeEstimate.MIN_KILLS - 1, 100).isPresent());
		assertTrue(TaskTimeEstimate.remainingMillis(10 * MINUTE, TaskTimeEstimate.MIN_KILLS, 100).isPresent());
	}

	@Test
	public void belowTimeThresholdGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(TaskTimeEstimate.MIN_ACTIVE_MILLIS - 1, 10, 100).isPresent());
		assertTrue(TaskTimeEstimate.remainingMillis(TaskTimeEstimate.MIN_ACTIVE_MILLIS, 10, 100).isPresent());
	}

	@Test
	public void normalCaseIsAverageKillTimesKillsLeft()
	{
		// 10 kills in 5 minutes: 30 s a kill, 120 kills/hour; 40 left is 20 minutes.
		assertEquals(OptionalLong.of(20 * MINUTE), TaskTimeEstimate.remainingMillis(5 * MINUTE, 10, 40));
		assertEquals(120d, TaskTimeEstimate.killsPerHour(5 * MINUTE, 10).getAsDouble(), 1e-9);
		assertEquals(OptionalLong.of(30_000), TaskTimeEstimate.averageKillMillis(5 * MINUTE, 10));
	}

	@Test
	public void resultIsRounded()
	{
		// 100,000 ms / 3 kills * 1 = 33,333.33 ms.
		assertEquals(OptionalLong.of(33_333), TaskTimeEstimate.remainingMillis(100_000, 3, 1));
		// 100,000 ms / 3 kills * 2 = 66,666.67 ms.
		assertEquals(OptionalLong.of(66_667), TaskTimeEstimate.remainingMillis(100_000, 3, 2));
	}

	@Test
	public void nothingRemainingGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, 10, 0).isPresent());
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, 10, -1).isPresent());
	}

	@Test
	public void hugeValuesSaturate()
	{
		assertEquals(OptionalLong.of(Long.MAX_VALUE),
			TaskTimeEstimate.remainingMillis(Long.MAX_VALUE, TaskTimeEstimate.MIN_KILLS, Integer.MAX_VALUE));
		// Large but representable: one kill an hour over 1,000 kills, Integer.MAX_VALUE left.
		long hour = 60 * MINUTE;
		assertEquals(OptionalLong.of(hour * Integer.MAX_VALUE),
			TaskTimeEstimate.remainingMillis(1_000 * hour, 1_000, Integer.MAX_VALUE));
		assertTrue(TaskTimeEstimate.averageKillMillis(Long.MAX_VALUE, TaskTimeEstimate.MIN_KILLS).getAsLong() > 0);
		// The panel still formats a saturated estimate.
		assertTrue(LiveSessionSection.timeLeftText(Long.MAX_VALUE, TaskTimeEstimate.MIN_KILLS, Integer.MAX_VALUE)
			.startsWith("Time left: ~"));
	}

	@Test
	public void restoredSessionUsesItsRestoredKillsAndTime()
	{
		// A session restored after a logout: 60 kills in 45 minutes of active time, 90 left. Only the inputs differ.
		assertEquals(OptionalLong.of(67 * MINUTE + 30_000), TaskTimeEstimate.remainingMillis(45 * MINUTE, 60, 90));
	}

	@Test
	public void taskExtensionRaisesTheEstimate()
	{
		// 20 kills in 10 minutes; the task count goes from 30 left to 130 left after an extension.
		OptionalLong before = TaskTimeEstimate.remainingMillis(10 * MINUTE, 20, 30);
		OptionalLong after = TaskTimeEstimate.remainingMillis(10 * MINUTE, 20, 130);
		assertEquals(OptionalLong.of(15 * MINUTE), before);
		assertEquals(OptionalLong.of(65 * MINUTE), after);
	}

	@Test
	public void panelTextEstimatesThenCountsDown()
	{
		assertEquals(LiveSessionSection.TIME_LEFT_ESTIMATING, LiveSessionSection.timeLeftText(MINUTE, 2, 50));
		assertEquals(LiveSessionSection.TIME_LEFT_ESTIMATING, LiveSessionSection.timeLeftText(30_000, 5, 50));
		assertEquals("Time left: ~20m", LiveSessionSection.timeLeftText(5 * MINUTE, 10, 40));
		assertEquals("Time left: ~1h 08m", LiveSessionSection.timeLeftText(45 * MINUTE, 60, 90));
	}

	@Test
	public void panelTextAfterCompletionOrWithoutTask()
	{
		assertEquals(LiveSessionSection.TIME_LEFT_NONE, LiveSessionSection.timeLeftText(10 * MINUTE, 40, 0));
		assertEquals("no task: nothing to estimate even with no kills", LiveSessionSection.TIME_LEFT_NONE,
			LiveSessionSection.timeLeftText(0, 0, 0));
	}

	@Test
	public void panelTooltipShowsPace()
	{
		String tooltip = LiveSessionSection.timeLeftTooltip(5 * MINUTE, 10);
		assertTrue(tooltip, tooltip.contains("Kills per hour: 120"));
		assertTrue(tooltip, tooltip.contains("Average kill: 30s"));
		assertEquals("Estimated after 3 kills and 1 minute of active time.",
			LiveSessionSection.timeLeftTooltip(30_000, 10));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class TrackingNudgeTest
{
	private static final long ACCOUNT = 1L;
	private static final SessionTracker.State IDLE = SessionTracker.State.IDLE;
	private static final SessionTracker.State RUNNING = SessionTracker.State.RUNNING;
	private static final SessionTracker.State PAUSED = SessionTracker.State.PAUSED;

	private TrackingNudge nudge;

	@Before
	public void setUp()
	{
		nudge = new TrackingNudge();
	}

	private TrackingNudge.Line read(int remaining, SessionTracker.State state)
	{
		return read("Wyrms", 42, remaining, 100, state);
	}

	private TrackingNudge.Line read(String monster, int creatureId, int remaining, int amount,
		SessionTracker.State state)
	{
		return nudge.update(ACCOUNT, monster, creatureId, remaining, amount, state, false);
	}

	@Test
	public void firstReadingIsABaseline()
	{
		assertEquals(TrackingNudge.Line.NONE, read(50, IDLE));
		assertFalse(nudge.isRowShown());
	}

	@Test
	public void killWhileIdleNudgesOncePerAssignment()
	{
		read(50, IDLE);
		assertEquals(TrackingNudge.Line.IDLE, read(49, IDLE));
		assertTrue(nudge.isRowShown());
		assertEquals(TrackingNudge.Line.NONE, read(48, IDLE));
		assertEquals("no kill", TrackingNudge.Line.NONE, read(48, IDLE));
		assertTrue(nudge.isRowShown());
	}

	@Test
	public void killWhileRunningNeverNudges()
	{
		read(50, RUNNING);
		assertEquals(TrackingNudge.Line.NONE, read(49, RUNNING));
		assertFalse(nudge.isRowShown());
		// The assignment wasn't nudged yet, so a later idle kill still does.
		assertEquals(TrackingNudge.Line.IDLE, read(48, IDLE));
	}

	@Test
	public void killWhilePausedPostsThePausedLineButNoRow()
	{
		read(50, PAUSED);
		assertEquals(TrackingNudge.Line.PAUSED, read(49, PAUSED));
		assertFalse(nudge.isRowShown());
		assertEquals(TrackingNudge.Line.NONE, read(48, PAUSED));
	}

	@Test
	public void oneLinePerAssignmentWhateverTheState()
	{
		read(50, IDLE);
		assertEquals(TrackingNudge.Line.IDLE, read(49, IDLE));
		read(45, RUNNING);
		assertFalse("a session clears the row", nudge.isRowShown());
		assertEquals(TrackingNudge.Line.NONE, read(44, PAUSED));
		// After a stop, another untracked kill shows the row again, without a line.
		assertEquals(TrackingNudge.Line.NONE, read(43, IDLE));
		assertTrue(nudge.isRowShown());
	}

	@Test
	public void completingKillNeverNudges()
	{
		read(1, IDLE);
		assertEquals(TrackingNudge.Line.NONE, read(0, IDLE));
		assertFalse(nudge.isRowShown());
	}

	@Test
	public void zeroCountHidesTheRow()
	{
		read(50, IDLE);
		read(49, IDLE);
		assertEquals(TrackingNudge.Line.NONE, read(0, IDLE));
		assertFalse(nudge.isRowShown());
		// The same assignment back (a transient zero) with a kill: the row, no second line.
		assertEquals(TrackingNudge.Line.NONE, read(48, IDLE));
		assertTrue(nudge.isRowShown());
	}

	@Test
	public void newAssignmentOrResetSetsTheBaselineAndCanNudgeAgain()
	{
		read(50, IDLE);
		assertEquals(TrackingNudge.Line.IDLE, read(49, IDLE));
		read(0, IDLE);
		// Another task with fewer kills than the old one had left: a new assignment, not a kill.
		assertEquals(TrackingNudge.Line.NONE, read("Black demons", 43, 30, 30, IDLE));
		assertFalse(nudge.isRowShown());
		assertEquals(TrackingNudge.Line.IDLE, read("Black demons", 43, 29, 30, IDLE));
	}

	@Test
	public void countGoingUpIsANewAssignment()
	{
		read(10, IDLE);
		assertEquals(TrackingNudge.Line.IDLE, read(9, IDLE));
		// Same monster and size reassigned: the count went up.
		assertEquals(TrackingNudge.Line.NONE, read(100, IDLE));
		assertFalse(nudge.isRowShown());
		assertEquals(TrackingNudge.Line.IDLE, read(99, IDLE));
	}

	@Test
	public void otherSizeIsANewAssignment()
	{
		read(50, IDLE);
		assertEquals(TrackingNudge.Line.IDLE, read(49, IDLE));
		assertEquals(TrackingNudge.Line.NONE, read("Wyrms", 42, 40, 120, IDLE));
		assertEquals(TrackingNudge.Line.IDLE, read("Wyrms", 42, 39, 120, IDLE));
	}

	@Test
	public void resetMakesTheNextReadingABaselineButKeepsTheAssignment()
	{
		read(50, IDLE);
		assertEquals(TrackingNudge.Line.IDLE, read(49, IDLE));
		nudge.reset();
		nudge.hideRow();
		assertFalse(nudge.isRowShown());
		assertEquals("baseline", TrackingNudge.Line.NONE, read(47, IDLE));
		assertFalse(nudge.isRowShown());
		assertEquals("same assignment: no second line", TrackingNudge.Line.NONE, read(46, IDLE));
		assertTrue(nudge.isRowShown());
	}

	@Test
	public void anotherAccountIsAnotherAssignment()
	{
		read(50, IDLE);
		assertEquals(TrackingNudge.Line.IDLE, read(49, IDLE));
		nudge.reset();
		assertEquals(TrackingNudge.Line.NONE, nudge.update(2L, "Wyrms", 42, 49, 100, IDLE, false));
		assertEquals(TrackingNudge.Line.IDLE, nudge.update(2L, "Wyrms", 42, 48, 100, IDLE, false));
	}

	@Test
	public void suppressedKillMovesTheBaselineWithoutNudging()
	{
		read(50, IDLE);
		assertEquals(TrackingNudge.Line.NONE, nudge.update(ACCOUNT, "Wyrms", 42, 49, 100, IDLE, true));
		assertFalse(nudge.isRowShown());
		assertEquals(TrackingNudge.Line.NONE, read(49, IDLE));
		assertEquals(TrackingNudge.Line.IDLE, read(48, IDLE));
	}

	@Test
	public void messages()
	{
		assertEquals("Kill not counted: Slayer Ledger isn't tracking. Press Play in the sidebar.",
			TrackingNudge.message(TrackingNudge.Line.IDLE));
		assertEquals("Kill not counted: Slayer Ledger is paused. Press Resume in the sidebar.",
			TrackingNudge.message(TrackingNudge.Line.PAUSED));
		assertEquals(null, TrackingNudge.message(TrackingNudge.Line.NONE));
	}
}
